import java.io.*;
import java.math.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static class Currency {
        String code;
        int minorUnits;

        Currency(String code, int minorUnits) {
            this.code = code;
            this.minorUnits = minorUnits;
        }
    }

    static class Account {
        String name;
        Currency currency;
        BigDecimal balance;
        BigDecimal limit;

        Account(String name, Currency currency, BigDecimal limit) {
            this.name = name;
            this.currency = currency;
            this.balance = BigDecimal.ZERO.setScale(currency.minorUnits, RoundingMode.HALF_EVEN);
            this.limit = limit;
        }
    }

    public static void main(String[] args) {
        if (args.length < 1) return;
        String directory = args[0];
        Path ledgerPath = Paths.get(directory, "ledger.txt");

        Map<String, Currency> currencies = new HashMap<>();
        Map<String, Account> accounts = new LinkedHashMap<>();
        List<String> rejections = new ArrayList<>();

        try {
            List<String> lines = Files.readAllLines(ledgerPath);
            for (int i = 0; i < lines.size(); i++) {
                String line = lines.get(i).trim();
                if (line.isEmpty() || line.startsWith("#")) continue;

                String[] parts = line.split("\\s+");
                String command = parts[0];

                try {
                    if (command.equals("currency")) {
                        String code = parts[1];
                        int minorUnits = Integer.parseInt(parts[2]);
                        currencies.put(code, new Currency(code, minorUnits));
                    } else if (command.equals("open")) {
                        String name = parts[1];
                        String code = parts[2];
                        if (accounts.containsKey(name)) {
                            rejections.add("line " + (i + 1) + ": REJECT account exists " + name);
                            continue;
                        }
                        Currency curr = currencies.get(code);
                        BigDecimal limit = (parts.length > 3) 
                            ? new BigDecimal(parts[3]).setScale(curr.minorUnits, RoundingMode.HALF_EVEN) 
                            : BigDecimal.ZERO.setScale(curr.minorUnits, RoundingMode.HALF_EVEN);
                        accounts.put(name, new Account(name, curr, limit));
                    } else if (command.equals("deposit")) {
                        String name = parts[1];
                        BigDecimal amount = new BigDecimal(parts[2]);
                        if (!accounts.containsKey(name)) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + name);
                            continue;
                        }
                        Account acc = accounts.get(name);
                        BigDecimal roundedAmount = amount.setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
                        if (roundedAmount.signum() <= 0) {
                            rejections.add("line " + (i + 1) + ": REJECT non-positive amount");
                            continue;
                        }
                        acc.balance = acc.balance.add(roundedAmount);
                    } else if (command.equals("withdraw")) {
                        String name = parts[1];
                        BigDecimal amount = new BigDecimal(parts[2]);
                        if (!accounts.containsKey(name)) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + name);
                            continue;
                        }
                        Account acc = accounts.get(name);
                        BigDecimal roundedAmount = amount.setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
                        if (roundedAmount.signum() <= 0) {
                            rejections.add("line " + (i + 1) + ": REJECT non-positive amount");
                            continue;
                        }
                        if (acc.balance.subtract(roundedAmount).compareTo(acc.limit.negate()) < 0) {
                            rejections.add("line " + (i + 1) + ": REJECT insufficient funds " + name);
                            continue;
                        }
                        acc.balance = acc.balance.subtract(roundedAmount);
                    } else if (command.equals("transfer")) {
                        String fromName = parts[1];
                        String toName = parts[2];
                        BigDecimal amount = new BigDecimal(parts[3]);

                        Account from = accounts.get(fromName);
                        Account to = accounts.get(toName);

                        if (from == null) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + fromName);
                            continue;
                        }
                        if (to == null) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + toName);
                            continue;
                        }
                        if (!from.currency.code.equals(to.currency.code)) {
                            rejections.add("line " + (i + 1) + ": REJECT currency mismatch");
                            continue;
                        }
                        BigDecimal roundedAmount = amount.setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
                        if (roundedAmount.signum() <= 0) {
                            rejections.add("line " + (i + 1) + ": REJECT non-positive amount");
                            continue;
                        }
                        if (from.balance.subtract(roundedAmount).compareTo(from.limit.negate()) < 0) {
                            rejections.add("line " + (i + 1) + ": REJECT insufficient funds " + fromName);
                            continue;
                        }
                        from.balance = from.balance.subtract(roundedAmount);
                        to.balance = to.balance.add(roundedAmount);
                    } else if (command.equals("convert")) {
                        String fromName = parts[1];
                        String toName = parts[2];
                        BigDecimal amount = new BigDecimal(parts[3]);
                        BigDecimal rate = new BigDecimal(parts[4]);

                        Account from = accounts.get(fromName);
                        Account to = accounts.get(toName);

                        if (from == null) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + fromName);
                            continue;
                        }
                        if (to == null) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + toName);
                            continue;
                        }
                        BigDecimal roundedFromAmount = amount.setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
                        if (roundedFromAmount.signum() <= 0) {
                            rejections.add("line " + (i + 1) + ": REJECT non-positive amount");
                            continue;
                        }
                        if (from.balance.subtract(roundedFromAmount).compareTo(from.limit.negate()) < 0) {
                            rejections.add("line " + (i + 1) + ": REJECT insufficient funds " + fromName);
                            continue;
                        }
                        BigDecimal roundedToAmount = roundedFromAmount.multiply(rate).setScale(to.currency.minorUnits, RoundingMode.HALF_EVEN);
                        from.balance = from.balance.subtract(roundedFromAmount);
                        to.balance = to.balance.add(roundedToAmount);
                    } else if (command.equals("interest")) {
                        String name = parts[1];
                        BigDecimal rate = new BigDecimal(parts[2]);
                        if (!accounts.containsKey(name)) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + name);
                            continue;
                        }
                        Account acc = accounts.get(name);
                        BigDecimal interest = acc.balance.multiply(rate).setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
                        acc.balance = acc.balance.add(interest);
                    } else if (command.equals("split")) {
                        String fromName = parts[1];
                        BigDecimal amount = new BigDecimal(parts[2]);
                        List<String> targetNames = new ArrayList<>();
                        List<Integer> weights = new ArrayList<>();
                        for (int j = 3; j < parts.length; j++) {
                            String[] pair = parts[j].split(":");
                            targetNames.add(pair[0]);
                            weights.add(Integer.parseInt(pair[1]));
                        }

                        Account from = accounts.get(fromName);
                        if (from == null) {
                            rejections.add("line " + (i + 1) + ": REJECT unknown account " + fromName);
                            continue;
                        }

                        boolean unknownFound = false;
                        for (String tn : targetNames) {
                            if (!accounts.containsKey(tn)) {
                                rejections.add("line " + (i + 1) + ": REJECT unknown account " + tn);
                                unknownFound = true;
                                break;
                            }
                        }
                        if (unknownFound) continue;

                        boolean mismatchFound = false;
                        for (String tn : targetNames) {
                            if (!accounts.get(tn).currency.code.equals(from.currency.code)) {
                                rejections.add("line " + (i + 1) + ": REJECT currency mismatch");
                                mismatchFound = true;
                                break;
                            }
                        }
                        if (mismatchFound) continue;

                        BigDecimal roundedFromAmount = amount.setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
                        if (roundedFromAmount.signum() <= 0) {
                            rejections.add("line " + (i + 1) + ": REJECT non-positive amount");
                            continue;
                        }
                        if (from.balance.subtract(roundedFromAmount).compareTo(from.limit.negate()) < 0) {
                            rejections.add("line " + (i + 1) + ": REJECT insufficient funds " + fromName);
                            continue;
                        }

                        BigInteger aMinor = roundedFromAmount.multiply(BigDecimal.TEN.pow(from.currency.minorUnits)).setScale(0, RoundingMode.HALF_EVEN).toBigInteger();
                        BigInteger wSum = BigInteger.ZERO;
                        for (int w : weights) wSum = wSum.add(BigInteger.valueOf(w));

                        BigInteger[] initialAmounts = new BigInteger[targetNames.size()];
                        BigInteger[] remainders = new BigInteger[targetNames.size()];
                        BigInteger totalDistributed = BigInteger.ZERO;

                        for (int j = 0; j < targetNames.size(); j++) {
                            BigInteger weight = BigInteger.valueOf(weights.get(j));
                            BigInteger product = aMinor.multiply(weight);
                            initialAmounts[j] = product.divide(wSum);
                            remainders[j] = product.remainder(wSum);
                            totalDistributed = totalDistributed.add(initialAmounts[j]);
                        }

                        BigInteger leftover = aMinor.subtract(totalDistributed);

                        List<Integer> sortedIndices = new ArrayList<>();
                        for (int j = 0; j < targetNames.size(); j++) sortedIndices.add(j);
                        sortedIndices.sort((a, b) -> {
                            int cmp = remainders[b].compareTo(remainders[a]);
                            return (cmp != 0) ? cmp : Integer.compare(a, b);
                        });

                        for (int j = 0; j < leftover.intValue(); j++) {
                            int idx = sortedIndices.get(j);
                            initialAmounts[idx] = initialAmounts[idx].add(BigInteger.ONE);
                        }

                        from.balance = from.balance.subtract(roundedFromAmount);
                        for (int j = 0; j < targetNames.size(); j++) {
                            BigDecimal share = new BigDecimal(initialAmounts[j]).divide(BigDecimal.TEN.pow(from.currency.minorUnits), from.currency.minorUnits, RoundingMode.UNNECESSARY);
                            accounts.get(targetNames.get(j)).balance = accounts.get(targetNames.get(j)).balance.add(share);
                        }
                    }
                } catch (Exception e) {
                    // Command execution error, ignore or handle
                }
            }

            for (String rej : rejections) System.out.println(rej);
            System.out.println();

            List<Account> sortedAccounts = new ArrayList<>(accounts.values());
            sortedAccounts.sort(Comparator.comparing(a -> a.name));
            for (Account acc : sortedAccounts) {
                System.out.println(acc.name + " " + acc.currency.code + " " + formatMoney(acc.balance, acc.currency.minorUnits));
            }
            System.out.println();

            Set<String> activeCurrencies = new TreeSet<>();
            for (Account acc : accounts.values()) activeCurrencies.add(acc.currency.code);
            for (String code : activeCurrencies) {
                Currency curr = currencies.get(code);
                BigDecimal total = BigDecimal.ZERO.setScale(curr.minorUnits, RoundingMode.HALF_EVEN);
                int count = 0;
                for (Account acc : accounts.values()) {
                    if (acc.currency.code.equals(code)) {
                        total = total.add(acc.balance);
                        count++;
                    }
                }
                System.out.println("total " + code + " " + formatMoney(total, curr.minorUnits) + " (" + count + " accounts)");
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static String formatMoney(BigDecimal amount, int minorUnits) {
        amount = amount.setScale(minorUnits, RoundingMode.HALF_EVEN);
        boolean negative = amount.signum() < 0;
        if (negative) amount = amount.negate();

        String s = amount.toPlainString();
        int dotIndex = s.indexOf('.');
        String integerPart = (dotIndex == -1) ? s : s.substring(0, dotIndex);
        String decimalPart = (dotIndex == -1) ? "" : s.substring(dotIndex + 1);

        if (minorUnits > 0) {
            if (decimalPart.length() > minorUnits) {
                decimalPart = decimalPart.substring(0, minorUnits);
            } else {
                while (decimalPart.length() < minorUnits) {
                    decimalPart += "0";
                }
            }
        } else {
            decimalPart = "";
        }

        StringBuilder sb = new StringBuilder();
        if (negative && amount.signum() != 0) sb.append('-');
        else if (negative && amount.signum() == 0) {
            // Zero is never negative
        } else if (negative) {
            // Handled by signum
        }

        // Corrected negative sign logic: Zero is never negative.
        // Re-evaluating negative:
        sb = new StringBuilder();
        boolean isNegative = amount.signum() < 0; // This is wrong because we negated it.
        // Let's use the original amount's signum.
        return formatMoneyFixed(amount, minorUnits, negative);
    }

    private static String formatMoneyFixed(BigDecimal amount, int minorUnits, boolean negative) {
        // amount is already absolute and set to scale
        String s = amount.toPlainString();
        int dotIndex = s.indexOf('.');
        String integerPart = (dotIndex == -1) ? s : s.substring(0, dotIndex);
        String decimalPart = (dotIndex == -1) ? "" : s.substring(dotIndex + 1);

        if (minorUnits > 0) {
            if (decimalPart.length() > minorUnits) {
                decimalPart = decimalPart.substring(0, minorUnits);
            } else {
                while (decimalPart.length() < minorUnits) {
                    decimalPart += "0";
                }
            }
        } else {
            decimalPart = "";
        }

        StringBuilder sb = new StringBuilder();
        if (negative && amount.signum() != 0) sb.append('-');

        int len = integerPart.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) sb.append(',');
            sb.append(integerPart.charAt(i));
        }
        if (minorUnits > 0) {
            sb.append('.').append(decimalPart);
        }
        return sb.toString();
    }
