import Foundation

// Helper to read little-endian integers from Data
func readUInt16(data: Data, offset: Int) -> UInt16 {
    return data.withUnsafeBytes { $0.load(fromByteOffset: offset, as: UInt16.self).littleEndian }
}

func readUInt32(data: Data, offset: Int) -> UInt32 {
    return data.withUnsafeBytes { $0.load(fromByteOffset: offset, as: UInt32.self).littleEndian }
}

func readInt32(data: Data, offset: Int) -> Int32 {
    return Int32(bitPattern: readUInt32(data: data, offset: offset))
}

func solve() {
    let args = CommandLine.arguments
    guard args.count > 1 else { return }
    let directory = args[1]

    let fileManager = FileManager.default
    guard let files = try? fileManager.contentsOfDirectory(atPath: directory) else { return }
    let bmpFiles = files.filter { $0.hasSuffix(".bmp") }.sorted()

    for fileName in bmpFiles {
        let filePath = (directory as NSString).appendingPathComponent(fileName)
        guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)) else { continue }

        print("== \(fileName)")
        if data.count < 14 { continue }

        let bfOffBits = Int(readUInt32(data: data, offset: 10))
        if data.count < 14 + 4 { continue }

        let dibHeaderSize = Int(readUInt32(data: data, offset: 14))
        if dibHeaderSize < 40 { continue }

        let width = Int(readInt32(data: data, offset: 18))
        let heightSigned = readInt32(data: data, offset: 22)
        let height = Int(abs(heightSigned))
        let bpp = Int(readUInt16(data: data, offset: 26))
        let compression = readUInt32(data: data, offset: 28)
        let coloursUsed = readUInt32(data: data, offset: 36)

        if compression != 0 && compression != 3 {
            print("error: unsupported compression \(compression)")
            continue
        }

        let isBottomUp = heightSigned > 0
        let rowSize = (width * bpp + 31) / 32 * 4

        var inkPixels = [Bool](repeating: false, count: width * height)

        // Handle BPP and Color Table
        if bpp == 1 || bpp == 4 || bpp == 8 {
            let numColours = coloursUsed == 0 ? (1 << bpp) : Int(coloursUsed)
            let paletteOffset = 14 + dibHeaderSize
            var palette = [(r: UInt8, g: UInt8, b: UInt8)]()
            for i in 0..<numColours {
                let off = paletteOffset + i * 4
                if off + 3 >= data.count { break }
                palette.append((r: data[off+2], g: data[off+1], b: data[off]))
            }

            for y in 0..<height {
                let storedY = isBottomUp ? (height - 1 - y) : y
                let rowStart = bfOffBits + storedY * rowSize

                for x in 0..<width {
                    var pixelIndex = 0
                    if bpp == 1 {
                        let byteOffset = rowStart + (x / 8)
                        if byteOffset >= data.count { break }
                        let byte = data[byteOffset]
                        pixelIndex = Int((byte >> (7 - (x % 8))) & 1)
                    } else if bpp == 4 {
                        let byteOffset = rowStart + (x / 2)
                        if byteOffset >= data.count { break }
                        let byte = data[byteOffset]
                        pixelIndex = (x % 2 == 0) ? Int((byte >> 4) & 0x0F) : Int(byte & 0x0F)
                    } else if bpp == 8 {
                        let byteOffset = rowStart + x
                        if byteOffset >= data.count { break }
                        pixelIndex = Int(data[byteOffset])
                    }

                    if pixelIndex < palette.count {
                        let color = palette[pixelIndex]
                        let intensity = (299 * Int(color.r) + 587 * Int(color.g) + 114 * Int(color.b)) / 1000
                        if intensity < 128 {
                            inkPixels[y * width + x] = true
                        }
                    }
                }
            }
        } else if bpp == 24 {
            for y in 0..<height {
                let storedY = isBottomUp ? (height - 1 - y) : y
                let rowStart = bfOffBits + storedY * rowSize
                for x in 0..<width {
                    let off = rowStart + x * 3
                    if off + 2 >= data.count { break }
                    let b = data[off], g = data[off+1], r = data[off+2]
                    let intensity = (299 * Int(r) + 587 * Int(g) + 114 * Int(b)) / 1000
                    if intensity < 128 {
                        inkPixels[y * width + x] = true
                    }
                }
            }
        } else if bpp == 32 {
            var rMask: UInt32 = 0, gMask: UInt32 = 0, bMask: UInt32 = 0
            if compression == 3 {
                let maskOffset = (dibHeaderSize == 40) ? (14 + 40) : (14 + 40)
                rMask = readUInt32(data: data, offset: maskOffset)
                gMask = readUInt32(data: data, offset: maskOffset + 4)
                bMask = readUInt32(data: data, offset: maskOffset + 8)
            }

            func getChannelValue(pixel: UInt32, mask: UInt32) -> Int {
                if mask == 0 { return 0 }
                let s = mask.trailingZeroBitCount
                let n = mask.nonzeroBitCount
                let m = (1 << n) - 1
                let v = (pixel & mask) >> s
                return Int((v * 255 + UInt32(m / 2)) / UInt32(m))
            }

            for y in 0..<height {
                let storedY = isBottomUp ? (height - 1 - y) : y
                let rowStart = bfOffBits + storedY * rowSize
                for x in 0..<width {
                    let off = rowStart + x * 4
                    if off + 3 >= data.count { break }
                    let pixel = readUInt32(data: data, offset: off)
                    let r, g, b: Int
                    if compression == 0 {
                        r = Int(data[off+2])
                        g = Int(data[off+1])
                        b = Int(data[off])
                    } else {
                        r = getChannelValue(pixel: pixel, mask: rMask)
                        g = getChannelValue(pixel: pixel, mask: gMask)
                        b = getChannelValue(pixel: pixel, mask: bMask)
                    }
                    let intensity = (299 * r + 587 * g + 114 * b) / 1000
                    if intensity < 128 {
                        inkPixels[y * width + x] = true
                    }
                }
            }
        }

        let inkCount = inkPixels.filter { $0 }.count
        print("size \(width)x\(height) bpp \(bpp) header \(dibHeaderSize) \(isBottomUp ? "bottom-up" : "top-down") ink \(inkCount)")

        var visited = [Bool](repeating: false, count: width * height)
        var components = [[(Int, Int)]]()
        for y in 0..<height {
            for x in 0..<width {
                if inkPixels[y * width + x] && !visited[y * width + x] {
                    var component = [(Int, Int)]()
                    var queue = [(x, y)]
                    visited[y * width + x] = true
                    var head = 0
                    while head < queue.count {
                        let (cx, cy) = queue[head]
                        head += 1
                        component.append((cx, cy))
                        for dx in -1...1 {
                            for dy in -1...1 {
                                if dx == 0 && dy == 0 { continue }
                                let nx = cx + dx
                                let ny = cy + dy
                                if nx >= 0 && nx < width && ny >= 0 && ny < height {
                                    if inkPixels[ny * width + nx] && !visited[ny * width + nx] {
                                        visited[ny * width + nx] = true
                                        queue.append((nx, ny))
                                    }
                                }
                            }
                        }
                    }
                    components.append(component)
                }
            }
        }

        struct ComponentInfo {
            let firstPixel: (Int, Int)
            let bbox: (minX: Int, minY: Int, maxX: Int, maxY: Int)
            let size: Int
        }

        var componentDetails = [ComponentInfo]()
        for comp in components {
            var minX = Int.max, minY = Int.max, maxX = Int.min, maxY = Int.min
            var firstPixel = (Int.max, Int.max)
            for p in comp {
                minX = min(minX, p.0)
                minY = min(minY, p.1)
                maxX = max(maxX, p.0)
                maxY = max(maxY, p.1)
                if p.1 < firstPixel.1 || (p.1 == firstPixel.1 && p.0 < firstPixel.0) {
                    firstPixel = p
                }
            }
            componentDetails.append(ComponentInfo(firstPixel: firstPixel, bbox: (minX, minY, maxX, maxY), size: comp.count))
        }

        componentDetails.sort { 
            if $0.firstPixel.1 != $1.firstPixel.1 { return $0.firstPixel.1 < $1.firstPixel.1 }
            return $0.firstPixel.0 < $1.firstPixel.0
        }

        print("components \(componentDetails.count)")
        for det in componentDetails {
            print("\(det.firstPixel.0),\(det.firstPixel.1) bbox \(det.bbox.minX),\(det.bbox.minY)-\(det.bbox.maxX),\(det.bbox.maxY) pixels \(det.size)")
        }
    }
}

