/**
 * Helper to read little-endian values from a buffer.
 */
class BufferReader {
    constructor(private buffer: Buffer) {}

    getU16(offset: number): number {
        return this.buffer.readUInt16LE(offset);
    }

    getU32(offset: number): number {
        return this.buffer.readUInt32LE(offset);
    }

    getI32(offset: number): number {
        return this.buffer.readInt32LE(offset);
    }

    getU8(offset: number): number {
        return this.buffer[offset];
    }
}

function getChannelValue(pixel: number, mask: number): number {
    if (mask === 0) return 0;
    let s = 0;
    let tempMask = mask;
    while ((tempMask & 1) === 0) {
        tempMask >>>= 1;
        s++;
    }
    let n = 0;
    tempMask = mask >>> s;
    while ((tempMask & 1) === 1) {
        tempMask >>>= 1;
        n++;
    }
    const m = (1 << n) - 1;
    const v = (pixel & mask) >>> s;
    return Math.floor((v * 255 + Math.floor(m / 2)) / m);
}

function processBmp(filename: string, buffer: Buffer) {
    const reader = new BufferReader(buffer);

    // File Header (14 bytes)
    if (buffer.toString('utf8', 0, 2) !== 'BM') return;
    const bfOffBits = reader.getU32(10);

    // DIB Header
    const headerSize = reader.getU32(14);
    const width = reader.getI32(18);
    const height = reader.getI32(22);
    const bpp = reader.getU16(26);
    const compression = reader.getU32(30);
    const coloursUsed = reader.getU32(42);

    if (compression !== 0 && compression !== 3) {
        process.stdout.write(`== ${filename}\nerror: unsupported compression ${compression}\n`);
        return;
    }

    const absHeight = Math.abs(height);
    const isBottomUp = height > 0;

    // Palette for 1, 4, 8 bpp
    let palette: Uint8Array | null = null;
    if (bpp === 1 || bpp === 4 || bpp === 8) {
        const numColours = coloursUsed === 0 ? (1 << bpp) : coloursUsed;
        palette = new Uint8Array(numColours * 4);
        for (let i = 0; i < numColours * 4; i++) {
            palette[i] = reader.getU8(14 + headerSize + i);
        }
    }

    // Masks for BPP 32 Compression 3
    let redMask = 0, greenMask = 0, blueMask = 0;
    if (bpp === 32 && compression === 3) {
        if (headerSize === 40) {
            redMask = reader.getU32(54);
            greenMask = reader.getU32(58);
            blueMask = reader.getU32(62);
        } else {
            redMask = reader.getU32(54);
            greenMask = reader.getU32(58);
            blueMask = reader.getU32(62);
        }
    }

    // Calculate row size and padding
    let rowSize: number;
    if (bpp === 1) rowSize = Math.ceil(width / 8);
    else if (bpp === 4) rowSize = Math.ceil(width / 4);
    else if (bpp === 8) rowSize = width;
    else if (bpp === 24) rowSize = width * 3;
    else if (bpp === 32) rowSize = width * 4;
    else rowSize = 0;

    const paddedRowSize = (rowSize + 3) & ~3;

    const inkMap = new Uint8Array(width * absHeight);
    let inkCount = 0;

    for (let storedRow = 0; storedRow < absHeight; storedRow++) {
        const y = isBottomUp ? absHeight - 1 - storedRow : storedRow;
        const rowOffset = bfOffBits + storedRow * paddedRowSize;

        for (let x = 0; x < width; x++) {
            let r = 0, g = 0, b = 0;

            if (bpp === 1 || bpp === 4 || bpp === 8) {
                let colorIdx = 0;
                if (bpp === 1) {
                    const byte = reader.getU8(rowOffset + Math.floor(x / 8));
                    colorIdx = (byte >> (7 - (x % 8))) & 1;
                } else if (bpp === 4) {
                    const byte = reader.getU8(rowOffset + Math.floor(x / 4));
                    colorIdx = (byte >> (6 - 2 * (x % 4))) & 3;
                } else {
                    colorIdx = reader.getU8(rowOffset + x);
                }
                const pOff = colorIdx * 4;
                b = palette![pOff];
                g = palette![pOff + 1];
                r = palette![pOff + 2];
            } else if (bpp === 24) {
                const offset = rowOffset + x * 3;
                b = reader.getU8(offset);
                g = reader.getU8(offset + 1);
                r = reader.getU8(offset + 2);
            } else if (bpp === 32) {
                const offset = rowOffset + x * 4;
                if (compression === 0) {
                    b = reader.getU8(offset);
                    g = reader.getU8(offset + 1);
                    r = reader.getU8(offset + 2);
                } else {
                    const pixel = reader.getU32(offset);
                    r = getChannelValue(pixel, redMask);
                    g = getChannelValue(pixel, greenMask);
                    b = getChannelValue(pixel, blueMask);
                }
            }

            const luminance = Math.floor((299 * r + 587 * g + 114 * b) / 1000);
            if (luminance < 128) {
                inkMap[y * width + x] = 1;
                inkCount++;
            }
        }
    }

    // Connected Components (8-connectivity)
    const visited = new Uint8Array(width * absHeight);
    const components: { firstPixel: [number, number], bbox: [number, number, number, number], pixels: number }[] = [];

    for (let y = 0; y < absHeight; y++) {
        for (let x = 0; x < width; x++) {
            if (inkMap[y * width + x] === 1 && visited[y * width + x] === 0) {
                let count = 0;
                let minX = x, maxX = x, minY = y, maxY = y;
                let firstX = x, firstY = y;

                const queue: [number, number][] = [[x, y]];
                visited[y * width + x] = 1;

                let head = 0;
                while (head < queue.length) {
                    const [cx, cy] = queue[head++];
                    count++;

                    if (cy < firstY || (cy === firstY && cx < firstX)) {
                        firstX = cx;
                        firstY = cy;
                    }
                    minX = Math.min(minX, cx);
                    maxX = Math.max(maxX, cx);
                    minY = Math.min(minY, cy);
                    maxY = Math.max(maxY, cy);

                    for (let dy = -1; dy <= 1; dy++) {
                        for (let dx = -1; dx <= 1; dx++) {
                            if (dx === 0 && dy === 0) continue;
                            const nx = cx + dx;
                            const ny = cy + dy;
                            if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight) {
                                if (inkMap[ny * width + nx] === 1 && visited[ny * width + nx] === 0) {
                                    visited[ny * width + nx] = 1;
                                    queue.push([nx, ny]);
                                }
                            }
                        }
                    }
                }
                components.push({ firstPixel: [firstX, firstY], bbox: [minX, minY, maxX, maxY], pixels: count });
            }
        }
    }

    components.sort((a, b) => a.firstPixel[1] - b.firstPixel[1] || a.firstPixel[0] - b.firstPixel[0]);

    process.stdout.write(`== ${filename}\n`);
    process.stdout.write(`size ${width}x${absHeight} bpp ${bpp} header ${headerSize} ${isBottomUp ? 'bottom-up' : 'top-down'} ink ${inkCount}\n`);
    process.stdout.write(`components ${components.length}\n`);
    for (const comp of components) {
        process.stdout.write(`${comp.firstPixel[0]},${comp.firstPixel[1]} bbox ${comp.bbox[0]},${comp.bbox[1]}-${comp.bbox[2]},${comp.bbox[3]} pixels ${comp.pixels}\n`);
    }
}

function main() {
    const dir = process.argv[2];
    if (!dir) return;

    const files = fs.readdirSync(dir).filter(f => f.endsWith('.bmp'));
    files.sort((a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)));

    for (const file of files) {
        const buffer = fs.readFileSync(path.join(dir, file));
        processBmp(file, buffer);
    }
}

