import * as fs from 'fs';
import * as path from 'path';
import * as dgram from 'dgram';
import * as net from 'net';

const TYPE_MAP: Record<string, number> = { 'A': 1, 'CNAME': 5, 'MX': 15, 'TXT': 16, 'AAAA': 28 };
const TYPE_REV_MAP: Record<number, string> = { 1: 'A', 5: 'CNAME', 15: 'MX', 16: 'TXT', 28: 'AAAA' };
const RCODE_MAP: Record<number, string> = { 0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED' };

function encodeName(name: string): Buffer {
    const labels = name.split('.');
    if (labels[labels.length - 1] === '') labels.pop();
    let buf = Buffer.alloc(0);
    for (const label of labels) {
        const labelBuf = Buffer.from(label);
        const lenBuf = Buffer.alloc(1);
        lenBuf[0] = labelBuf.length;
        buf = Buffer.concat([buf, lenBuf, labelBuf]);
    }
    return Buffer.concat([buf, Buffer.from([0])]);
}

function readName(buf: Buffer, pos: number): { name: string, nextPos: number } {
    let labels = [];
    let currentPos = pos;
    let jumped = false;
    let nextPosAfterJump = -1;
    let visited = new Set<number>();

    while (true) {
        if (visited.has(currentPos)) throw new Error("Pointer loop");
        visited.add(currentPos);
        const len = buf[currentPos];
        if (len === 0) {
            if (!jumped) nextPosAfterJump = currentPos + 1;
            break;
        }
        if ((len & 0xC0) === 0xC0) {
            const offset = ((len & 0x3F) << 8) | buf[currentPos + 1];
            if (!jumped) nextPosAfterJump = currentPos + 2;
            jumped = true;
            currentPos = offset;
        } else {
            labels.push(buf.slice(currentPos + 1, currentPos + 1 + len).toString());
            currentPos += 1 + len;
        }
    }
    const name = labels.join('.').toLowerCase();
    return { name: name === '' ? '.' : name, nextPos: jumped ? nextPosAfterJump : currentPos };
}

function formatIPv6(buf: Buffer): string {
    const groups = [];
    for (let i = 0; i < 16; i += 2) groups.push(buf.readUInt16BE(i));
    let maxLen = 0, maxStart = -1;
    for (let i = 0; i < 8; i++) {
        if (groups[i] === 0) {
            let j = i;
            while (j < 8 && groups[j] === 0) j++;
            if (j - i > maxLen) { maxLen = j - i; maxStart = i; }
            i = j - 1;
        }
    }
    if (maxLen >= 2) {
        const head = groups.slice(0, maxStart).map(g => g.toString(16)).join(':');
        const tail = groups.slice(maxStart + maxLen).map(g => g.toString(16)).join(':');
        return `${head}::${tail}`;
    }
    return groups.map(g => g.toString(16)).join(':');
}

function formatTXT(buf: Buffer, pos: number, len: number): string {
    const parts = [];
    let offset = 0;
    while (offset < len) {
        const strLen = buf[pos + offset];
        let str = "";
        for (let i = 1; i <= strLen; i++) {
            const b = buf[pos + offset + i];
            if (b === 34) str += '\\"';
            else if (b === 92) str += '\\\\';
            else if (b >= 32 && b <= 126) str += String.fromCharCode(b);
            else str += `\\${b.toString().padStart(3, '0')}`;
        }
        parts.push(`"${str}"`);
        offset += strLen + 1;
    }
    return parts.join(' ');
}

async function queryUDP(queryPacket: Buffer, port: number): Promise<Buffer> {
    return new Promise((resolve) => {
        const socket = dgram.createSocket('udp4');
        socket.on('message', (msg) => {
            const id = queryPacket.readUInt16BE(0);
            const respId = msg.readUInt16BE(0);
            const flags = msg.readUInt16BE(2);
            if (id === respId && (flags & 0x8000)) {
                socket.close();
                resolve(msg);
            }
        });
        socket.send(queryPacket, port, '127.0.0.1');
    });
}

async function queryTCP(queryPacket: Buffer, port: number): Promise<Buffer> {
    return new Promise((resolve) => {
        const client = net.createConnection(port, '127.0.0.1', () => {
            const lenBuf = Buffer.alloc(2);
            lenBuf.writeUInt16BE(queryPacket.length);
            client.write(Buffer.concat([lenBuf, queryPacket]));
        });
        let responseData = Buffer.alloc(0);
        client.on('data', (data) => {
            responseData = Buffer.concat([responseData, data]);
            if (responseData.length >= 2) {
                const len = responseData.readUInt16BE(0);
                if (responseData.length >= len + 2) {
                    resolve(responseData.slice(2, len + 2));
                    client.destroy();
                }
            }
        });
    });
}

