use std::collections::VecDeque;
use std::fs;
use std::io::Read;
use std::path::Path;

struct Component {
    first_pixel: (i32, i32),
    bbox: (i32, i32, i32, i32),
    pixel_count: usize,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        return;
    }

    let dir_path = &args[1];
    let mut entries: Vec<_> = fs::read_dir(dir_path).unwrap().collect();
    entries.sort_by(|a, b| {
        let na = a.as_ref().unwrap().file_name();
        let nb = b.as_ref().unwrap().file_name();
        na.as_bytes().cmp(nb.as_bytes())
    });

    for entry in entries {
        let path = entry.unwrap().path();
        if path.extension().and_then(|s| s.to_str()) == Some("bmp") {
            process_bmp(&path);
        }
    }
}

fn process_bmp(path: &Path) {
    let file_name = path.file_name().unwrap().to_string_lossy();
    println!("== {}", file_name);

    let mut file = fs::File::open(path).unwrap();
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes).unwrap();

    if bytes.len() < 14 {
        return;
    }

    let bf_off_bits = u32::from_le_bytes(bytes[10..14].try_into().unwrap()) as usize;
    let dib_header_size = u32::from_le_bytes(bytes[14..18].try_into().unwrap());
    let width = i32::from_le_bytes(bytes[18..22].try_into().unwrap());
    let height_raw = i32::from_le_bytes(bytes[22..26].try_into().unwrap());
    let bpp = u16::from_le_bytes(bytes[26..28].try_into().unwrap());
    let compression = u32::from_le_bytes(bytes[28..32].try_into().unwrap());

    if compression != 0 && compression != 3 {
        println!("error: unsupported compression {}", compression);
        return;
    }

    let height = height_raw.abs();
    let is_bottom_up = height_raw > 0;

    let mut ink_map = vec![false; (width as usize * height as usize)];
    let mut total_ink_pixels = 0;

    let row_size_bytes = match bpp {
        1 => (width as usize + 7) / 8,
        4 => (width as usize + 1) / 2,
        8 => width as usize,
        24 => width as usize * 3,
        32 => width as usize * 4,
        _ => 0,
    };
    let padded_row_size = (row_size_bytes + 3) & !3;

    let color_table_start = 14 + dib_header_size as usize;
    let num_colors = if bpp <= 8 {
        let colors_used = u32::from_le_bytes(bytes[42..46].try_into().unwrap());
        if colors_used == 0 { 1 << bpp } else { colors_used }
    } else { 0 };

    let masks = if compression == 3 {
        let mask_start = 14 + 40;
        let r = u32::from_le_bytes(bytes[mask_start..mask_start + 4].try_into().unwrap());
        let g = u32::from_le_bytes(bytes[mask_start + 4..mask_start + 8].try_into().unwrap());
        let b = u32::from_le_bytes(bytes[mask_start + 8..mask_start + 12].try_into().unwrap());
        Some((r, g, b))
    } else {
        None
    };

    for i in 0..height {
        let y = if is_bottom_up { height - 1 - i } else { i };
        let row_start = bf_off_bits + i as usize * padded_row_size;

        for x in 0..width {
            let (r, g, b) = match bpp {
                1 | 4 | 8 => {
                    let pixel_idx = match bpp {
                        1 => {
                            let byte_idx = x as usize / 8;
                            let bit_idx = 7 - (x as usize % 8);
                            (bytes[row_start + byte_idx] >> bit_idx) & 1
                        }
                        4 => {
                            let byte_idx = x as usize / 2;
                            let bit_idx = 4 * (1 - (x as usize % 2));
                            (bytes[row_start + byte_idx] >> bit_idx) & 0x0F
                        }
                        _ => bytes[row_start + x as usize] as usize,
                    };
                    let table_idx = pixel_idx * 4;
                    let b_val = bytes[color_table_start + table_idx] as u8;
                    let g_val = bytes[color_table_start + table_idx + 1] as u8;
                    let r_val = bytes[color_table_start + table_idx + 2] as u8;
                    (r_val, g_val, b_val)
                }
                24 => {
                    let pixel_start = row_start + x as usize * 3;
                    let b_val = bytes[pixel_start] as u8;
                    let g_val = bytes[pixel_start + 1] as u8;
                    let r_val = bytes[pixel_start + 2] as u8;
                    (r_val, g_val, b_val)
                }
                32 => {
                    let pixel_start = row_start + x as usize * 4;
                    let pixel_u32 = u32::from_le_bytes(bytes[pixel_start..pixel_start + 4].try_into().unwrap());
                    if let Some((rm, gm, bm)) = masks {
                        let extract = |p: u32, m: u32| {
                            let s = m.trailing_zeros();
                            let n = m.count_ones();
                            let mask_val = (1u64 << n) - 1;
                            let v = ((p & m) as u64) >> s;
                            ((v * 255 + mask_val / 2) / mask_val) as u8
                        };
                        (extract(pixel_u32, rm), extract(pixel_u32, gm), extract(pixel_u32, bm))
                    } else {
                        let b_val = bytes[pixel_start] as u8;
                        let g_val = bytes[pixel_start + 1] as u8;
                        let r_val = bytes[pixel_start + 2] as u8;
                        (r_val, g_val, b_val)
                    }
                }
                _ => (0, 0, 0),
            };

            if (299 * r as i32 + 587 * g as i32 + 114 * b as i32) / 1000 < 128 {
                ink_map[y as usize * width as usize + x as usize] = true;
                total_ink_pixels += 1;
            }
        }
    }

    println!(
        "size {}x{} bpp {} header {} {} ink {}",
        width, height, bpp, dib_header_size, if is_bottom_up { "bottom-up" } else { "top-down" }, total_ink_pixels
    );

    let mut visited = vec![false; ink_map.len()];
    let mut components = Vec::new();

    for y in 0..height {
        for x in 0..width {
            let idx = y as usize * width as usize + x as usize;
            if ink_map[idx] && !visited[idx] {
                let mut component_pixels = Vec::new();
                let mut queue = VecDeque::new();
                queue.push_back((x, y));
                visited[idx] = true;

                while let Some((cx, cy)) = queue.pop_front() {
                    component_pixels.push((cx, cy));
                    for dx in -1..=1 {
                        for dy in -1..=1 {
                            if dx == 0 && dy == 0 { continue; }
                            let nx = cx + dx;
                            let ny = cy + dy;
                            if nx >= 0 && nx < width && ny >= 0 && ny < height {
                                let nidx = ny as usize * width as usize + nx as usize;
                                if ink_map[nidx] && !visited[nidx] {
                                    visited[nidx] = true;
                                    queue.push_back((nx, ny));
                                }
                            }
                        }
                    }
                }

                let mut min_x = i32::MAX;
                let mut max_x = i32::MIN;
                let mut min_y = i32::MAX;
                let mut max_y = i32::MIN;
                let mut first_pixel = (i32::MAX, i32::MAX);

                for &(px, py) in &component_pixels {
                    if px < min_x { min_x = px; }
                    if px > max_x { max_x = px; }
                    if py < min_y { min_y = py; }
                    if py > max_y { max_y = py; }
                    if py < first_pixel.1 || (py == first_pixel.1 && px < first_pixel.0) {
                        first_pixel = (px, py);
                    }
                }

                components.push(Component {
                    first_pixel,
                    bbox: (min_x, min_y, max_x, max_y),
                    pixel_count: component_pixels.len(),
                });
            }
        }
    }

    components.sort_by(|a, b| a.first_pixel.cmp(&b.first_pixel));
    println!("components {}", components.len());
    for comp in components {
        println!(
            "{},{} bbox {},{}-{},{} pixels {}",
            comp.first_pixel.0, comp.first_pixel.1, comp.bbox.0, comp.bbox.1, comp.bbox.2, comp.bbox.3, comp.pixel_count
        );
    }
}

