                            if row_start + byte_idx >= bytes.len() { 0 } else { (bytes[row_start + byte_idx] >> bit_idx) & 1 }
                        }
                        4 => {
                            let byte_idx = x as usize / 2;
                            let bit_idx = 4 * (1 - (x as usize % 2));
                            if row_start + byte_idx >= bytes.len() { 0 } else { (bytes[row_start + byte_idx] >> bit_idx) & 0x0F }
                        }
                        _ => {
                            if row_start + x as usize >= bytes.len() { 0 } else { bytes[row_start + x as usize] }
                        }
                    };
                    let table_idx = (pixel_idx as usize) * 4;
                    if color_table_start + table_idx + 2 >= bytes.len() {
                        (0, 0, 0)
                    } else {
                        let b_val = bytes[color_table_start + table_idx] as u8;
                        let g_val = bytes[color_table_start + table_idx + 1] as u8;
                        let r_val = bytes[color_table_start + table_idx + 2] as u8;
                        (r_val, g_val, b_val)
                    }
                }
                24 => {
                    let pixel_start = row_start + x as usize * 3;
                    if pixel_start + 2 >= bytes.len() {
                        (0, 0, 0)
                    } else {
                        let b_val = bytes[pixel_start] as u8;
                        let g_val = bytes[pixel_start + 1] as u8;
                        let r_val = bytes[pixel_start + 2] as u8;
                        (r_val, g_val, b_val)
                    }
                }
                32 => {
                    let pixel_start = row_start + x as usize * 4;
                    if pixel_start + 3 >= bytes.len() {
                        (0, 0, 0)
                    } else {
                        let pixel_u32 = u32::from_le_bytes(bytes[pixel_start..pixel_start + 4].try_into().unwrap());
                        if let Some((rm, gm, bm)) = masks {
                            let extract = |p: u32, m: u32| {
                                let s = m.trailing_zeros();
                                let n = m.count_ones();
                                let mask_val = (1u64 << n) - 1;
                                let v = ((p & m) as u64) >> s;
                                ((v * 255 + mask_val / 2) / mask_val) as u8
                            };
                            (extract(pixel_u32, rm), extract(pixel_u32, gm), extract(pixel_u32, bm))
                        } else {
                            let b_val = bytes[pixel_start] as u8;
                            let g_val = bytes[pixel_start + 1] as u8;
                            let r_val = bytes[pixel_start + 2] as u8;
                            (r_val, g_val, b_val)
                        }
                    }
                }
                _ => (0, 0, 0),
            };

            if (299 * r as i32 + 587 * g as i32 + 114 * b as i32) / 1000 < 128 {
                ink_map[y as usize * width as usize + x as usize] = true;
                total_ink_pixels += 1;
            }
        }
    }

    println!(
        "size {}x{} bpp {} header {} {} ink {}",
        width, height, bpp, dib_header_size, if is_bottom_up { "bottom-up" } else { "top-down" }, total_ink_pixels
    );

    let mut visited = vec![false; ink_map.len()];
    let mut components = Vec::new();

    for y in 0..height {
        for x in 0..width {
            let idx = y as usize * width as usize + x as usize;
            if ink_map[idx] && !visited[idx] {
                let mut component_pixels = Vec::new();
                let mut queue = VecDeque::new();
                queue.push_back((x, y));
                visited[idx] = true;

                while let Some((cx, cy)) = queue.pop_front() {
                    component_pixels.push((cx, cy));
                    for dx in -1..=1 {
                        for dy in -1..=1 {
                            if dx == 0 && dy == 0 { continue; }
                            let nx = cx + dx;
                            let ny = cy + dy;
                            if nx >= 0 && nx < width && ny >= 0 && ny < height {
                                let nidx = ny as usize * width as usize + nx as usize;
                                if ink_map[nidx] && !visited[nidx] {
                                    visited[nidx] = true;
                                    queue.push_back((nx, ny));
                                }
                            }
                        }
                    }
                }

                let mut min_x = i32::MAX;
                let mut max_x = i32::MIN;
                let mut min_y = i32::MAX;
                let mut max_y = i32::MIN;
                let mut first_pixel = (i32::MAX, i32::MAX);

                for &(px, py) in &component_pixels {
                    if px < min_x { min_x = px; }
                    if px > max_x { max_x = px; }
                    if py < min_y { min_y = py; }
                    if py > max_y { max_y = py; }
                    if py < first_pixel.1 || (py == first_pixel.1 && px < first_pixel.0) {
                        first_pixel = (px, py);
                    }
                }

                components.push(Component {
                    first_pixel,
                    bbox: (min_x, min_y, max_x, max_y),
                    pixel_count: component_pixels.len(),
                });
            }
        }
    }

    components.sort_by(|a, b| a.first_pixel.cmp(&b.first_pixel));
    println!("components {}", components.len());
    for comp in components {
        println!(
            "{},{} bbox {},{}-{},{} pixels {}",
            comp.first_pixel.0, comp.first_pixel.1, comp.bbox.0, comp.bbox.1, comp.bbox.2, comp.bbox.3, comp.pixel_count
        );
    }
}

import * as fs from 'fs';
import * as path from 'path';

/**
 * Fraction class to handle exact decimal arithmetic.
 */
class Fraction {
    constructor(public n: bigint, public d: bigint) {
        if (this.d < 0n) {
            this.n = -this.n;
            this.d = -this.d;
        }
    }

    static fromDecimal(s: string): Fraction {
        const parts = s.split('.');
        const integerPart = parts[0];
        const fractionalPart = parts[1] || '';
        const n = BigInt(integerPart + fractionalPart);
        const d = 10n ** BigInt(fractionalPart.length);
        return new Fraction(n, d);
    }
}

/**
 * Rounds a Fraction to the nearest integer using round-half-even.
 */
function round(f: Fraction, minorUnits: number): bigint {
    let n = f.n * (10n ** BigInt(minorUnits));
    let d = f.d;

    let q = n / d;
    let r = n % d;

    if (r === 0n) return q;

    let absR = r < 0n ? -r : r;
    let absD = d < 0n ? -d : d;

    if (2n * absR < absD) return q;
    if (2n * absR > absD) return q + (r > 0n ? 1n : -1n);

    // Round-half-even: if exactly halfway, round to the nearest even integer.
    if (q % 2n === 0n) return q;
    return q + (r > 0n ? 1n : -1n);
}

/**
 * Formats the balance according to currency minor units with thousands separators.
 */
function formatMoney(balance: bigint, minorUnits: number): string {
    const isNegative = balance < 0n;
    let absBalance = isNegative ? -balance : balance;

    const scale = 10n ** BigInt(minorUnits);
    let integerPart = absBalance / scale;
    let fractionalPart = absBalance % scale;

    let intStr = integerPart.toString();
    let formattedInt = '';
    for (let i = 0; i < intStr.length; i++) {
        if (i > 0 && (intStr.length - i) % 3 === 0) {
            formattedInt += ',';
        }
        formattedInt += intStr[i];
    }

    let formattedFrac = '';
    if (minorUnits > 0) {
        formattedFrac = fractionalPart.toString().padStart(minorUnits, '0');
    }

    return (isNegative ? '-' : '') + formattedInt + (minorUnits > 0 ? '.' + formattedFrac : '');
}

interface Currency {
    code: string;
    minorUnits: number;
}

interface Account {
    name: string;
    currencyCode: string;
    balance: bigint; // stored in minor units
    limit: bigint;   // stored in minor units
}

function main() {
    const dir = process.argv[2];
    if (!dir) return;
    const filePath = path.join(dir, 'ledger.txt');
    let content: string;
    try {
        content = fs.readFileSync(filePath, 'utf-8');
    } catch (e) {
        return;
    }
    const lines = content.split(/\r?\n/);

    const currencies = new Map<string, Currency>();
    const accounts = new Map<string, Account>();
    const rejections: string[] = [];

    for (let i = 0; i < lines.length; i++) {
        const lineNum = i + 1;
        const line = lines[i].trim();
        if (line === '' || line.startsWith('#')) continue;

        const parts = line.split(/\s+/);
        const command = parts[0];

        if (command === 'currency') {
            const code = parts[1];
            const minorUnits = parseInt(parts[2]);
            currencies.set(code, { code, minorUnits });
        } else if (command === 'open') {
            const name = parts[1];
            const code = parts[2];
            const limitStr = parts[3] || '0';
            if (accounts.has(name)) {
                rejections.push(`line ${lineNum}: REJECT account exists ${name}`);
                continue;
            }
            const currency = currencies.get(code);
            const limit = round(Fraction.fromDecimal(limitStr), currency!.minorUnits);
            accounts.set(name, { name, currencyCode: code, balance: 0n, limit });
        } else if (command === 'deposit') {
            const name = parts[1];
            const amountStr = parts[2];
            const account = accounts.get(name);
            if (!account) {
                rejections.push(`line ${lineNum}: REJECT unknown account ${name}`);
                continue;
            }
            const currency = currencies.get(account.currencyCode)!;
            const roundedAmount = round(Fraction.fromDecimal(amountStr), currency.minorUnits);
            if (roundedAmount <= 0n) {
                rejections.push(`line ${lineNum}: REJECT non-positive amount`);
                continue;
            }
            account.balance += roundedAmount;
        } else if (command === 'withdraw') {
            const name = parts[1];
            const amountStr = parts[2];
            const account = accounts.get(name);
            if (!account) {
                rejections.push(`line ${lineNum}: REJECT unknown account ${name}`);
                continue;
            }
            const currency = currencies.get(account.currencyCode)!;
            const roundedAmount = round(Fraction.fromDecimal(amountStr), currency.minorUnits);
            if (roundedAmount <= 0n) {
                rejections.push(`line ${lineNum}: REJECT non-positive amount`);
                continue;
            }
            if (account.balance - roundedAmount < -account.limit) {
                rejections.push(`line ${lineNum}: REJECT insufficient funds ${name}`);
                continue;
            }
            account.balance -= roundedAmount;
        } else if (command === 'transfer') {
            const fromName = parts[1];
            const toName = parts[2];
            const amountStr = parts[3];
            const fromAcc = accounts.get(fromName);
            const toAcc = accounts.get(toName);

            let unknownAccount = '';
            if (!fromAcc) unknownAccount = fromName;
            else if (!toAcc) unknownAccount = toName;

            if (unknownAccount) {
                rejections.push(`line ${lineNum}: REJECT unknown account ${unknownAccount}`);
                continue;
            }

            if (fromAcc!.currencyCode !== toAcc!.currencyCode) {
                rejections.push(`line ${lineNum}: REJECT currency mismatch`);
                continue;
            }

            const currency = currencies.get(fromAcc!.currencyCode)!;
            const roundedAmount = round(Fraction.fromDecimal(amountStr), currency.minorUnits);
            if (roundedAmount <= 0n) {
                rejections.push(`line ${lineNum}: REJECT non-positive amount`);
                continue;
            }

            if (fromAcc!.balance - roundedAmount < -fromAcc!.limit) {
                rejections.push(`line ${lineNum}: REJECT insufficient funds ${fromName}`);
                continue;
            }

            fromAcc!.balance -= roundedAmount;
            toAcc!.balance += roundedAmount;
        } else if (command === 'convert') {
            const fromName = parts[1];
            const toName = parts[2];
            const amountStr = parts[3];
            const rateStr = parts[4];
            const fromAcc = accounts.get(fromName);
            const toAcc = accounts.get(toName);

            let unknownAccount = '';
            if (!fromAcc) unknownAccount = fromName;
            else if (!toAcc) unknownAccount = toName;

            if (unknownAccount) {
                rejections.push(`line ${lineNum}: REJECT unknown account ${unknownAccount}`);
                continue;
            }

            const fromCurrency = currencies.get(fromAcc!.currencyCode)!;
            const roundedAmountFrom = round(Fraction.fromDecimal(amountStr), fromCurrency.minorUnits);
            if (roundedAmountFrom <= 0n) {
                rejections.push(`line ${lineNum}: REJECT non-positive amount`);
                continue;
            }

            if (fromAcc!.balance - roundedAmountFrom < -fromAcc!.limit) {
                rejections.push(`line ${lineNum}: REJECT insufficient funds ${fromName}`);
                continue;
            }

            const toCurrency = currencies.get(toAcc!.currencyCode)!;
            const rate = Fraction.fromDecimal(rateStr);
            const convertedFraction = new Fraction(
                roundedAmountFrom * rate.n * (10n ** BigInt(toCurrency.minorUnits)),
                rate.d * (10n ** BigInt(fromCurrency.minorUnits))
            );
            const roundedAmountTo = round(convertedFraction, 0);

            fromAcc!.balance -= roundedAmountFrom;
            toAcc!.balance += roundedAmountTo;
        } else if (command === 'interest') {
            const name = parts[1];
            const rateStr = parts[2];
            const account = accounts.get(name);
            if (!account) {
                rejections.push(`line ${lineNum}: REJECT unknown account ${name}`);
                continue;
            }
            const rate = Fraction.fromDecimal(rateStr);
            const interestFraction = new Fraction(account.balance * rate.n, rate.d);
            const roundedInterest = round(interestFraction, 0);
            account.balance += roundedInterest;
        } else if (command === 'split') {
            const fromName = parts[1];
            const amountStr = parts[2];
            const fromAcc = accounts.get(fromName);
            if (!fromAcc) {
                rejections.push(`line ${lineNum}: REJECT unknown account ${fromName}`);
                continue;
            }

            const targetPairs = parts.slice(3);
            const targets: { name: string, weight: bigint }[] = [];
            let unknownAccount = '';
            for (const pair of targetPairs) {
                const [tName, tWeight] = pair.split(':');
                if (!accounts.has(tName)) {
                    unknownAccount = tName;
                    break;
                }
                targets.push({ name: tName, weight: BigInt(tWeight) });
            }
            if (unknownAccount) {
                rejections.push(`line ${lineNum}: REJECT unknown account ${unknownAccount}`);
                continue;
            }

            let currencyMismatch = false;
            for (const target of targets) {
                if (accounts.get(target.name)!.currencyCode !== fromAcc.currencyCode) {
                    currencyMismatch = true;
                    break;
                }
            }
            if (currencyMismatch) {
                rejections.push(`line ${lineNum}: REJECT currency mismatch`);
                continue;
            }

            const fromCurrency = currencies.get(fromAcc.currencyCode)!;
            const roundedAmount = round(Fraction.fromDecimal(amountStr), fromCurrency.minorUnits);
            if (roundedAmount <= 0n) {
                rejections.push(`line ${lineNum}: REJECT non-positive amount`);
                continue;
            }

            if (fromAcc.balance - roundedAmount < -fromAcc.limit) {
                rejections.push(`line ${lineNum}: REJECT insufficient funds ${fromName}`);
                continue;
            }

            const totalWeight = targets.reduce((sum, t) => sum + t.weight, 0n);
            const distribution = targets.map(t => {
                const amount = (roundedAmount * t.weight) / totalWeight;
                const remainder = (roundedAmount * t.weight) % totalWeight;
                return { name: t.name, amount, remainder };
            });

            let remaining = roundedAmount - distribution.reduce((sum, d) => sum + d.amount, 0n);
            const sortedRemainderIndices = distribution
                .map((d, i) => ({ i, r: d.remainder }))
                .sort((a, b) => {
                    if (a.r > b.r) return -1;
                    if (a.r < b.r) return 1;
                    return a.i - b.i;
                });
            for (let i = 0; i < Number(remaining); i++) {
                const targetIdx = sortedRemainderIndices[i].i;
                distribution[targetIdx].amount += 1n;
            }

            fromAcc.balance -= roundedAmount;
            for (const d of distribution) {
                accounts.get(d.name)!.balance += d.amount;
            }
        }
    }

    rejections.forEach(r => console.log(r));
    console.log('');

    const sortedAccountNames = Array.from(accounts.keys()).sort();
    for (const name of sortedAccountNames) {
        const acc = accounts.get(name)!;
        const currency = currencies.get(acc.currencyCode)!;
        console.log(`${acc.name} ${acc.currencyCode} ${formatMoney(acc.balance, currency.minorUnits)}`);
    }
    console.log('');

    const activeCurrencies = Array.from(currencies.values())
        .filter(c => Array.from(accounts.values()).some(a => a.currencyCode === c.code))
        .sort((a, b) => a.code.localeCompare(b.code));

    for (const curr of activeLCurrencies) {
        const currAccounts = Array.from(accounts.values()).filter(a => a.currencyCode === curr.code);
        const totalBalance = currAccounts.reduce((sum, a) => sum + a.balance, 0n);
        console.log(`total ${curr.code} ${formatMoney(totalBalance, curr.minorUnits)} (${currAccounts.length} accounts)`);
    }
}

function activeLCurrencies(currencies: Map<string, Currency>, accounts: Map<string, Account>) {
    return Array.from(currencies.values())
        .filter(c => Array.from(accounts.values()).some(a => a.currencyCode === c.code))
        .sort((a, b) => a.code.localeCompare(b.code));
}

