                    return a.i - b.i;
                });
            for (let i = 0; i < Number(remaining); i++) {
                const targetIdx = sortedRemainderIndices[i].i;
                distribution[targetIdx].amount += 1n;
            }
            fromAcc.balance -= roundedAmount;
            for (const d of distribution) {
                accounts.get(d.name)!.balance += d.amount;
            }
        }
    }

    rejections.forEach(r => console.log(r));
    console.log('');
    const sortedAccountNames = Array.from(accounts.keys()).sort();
    for (const name of sortedAccountNames) {
        const acc = accounts.get(name)!;
        const currency = currencies.get(acc.currencyCode)!;
        console.log(`${acc.name} ${acc.currencyCode} ${formatMoney(acc.balance, currency.minorUnits)}`);
    }
    console.log('');
    const activeCurrencies = Array.from(currencies.values())
        .filter(c => Array.from(accounts.values()).some(a => a.currencyCode === c.code))
        .sort((a, b) => a.code.localeCompare(b.code));
    for (const curr of activeCurrencies) {
        const currAccounts = Array.from(accounts.values()).filter(a => a.currencyCode === curr.code);
        const totalBalance = currAccounts.reduce((sum, a) => sum + a.balance, 0n);
        console.log(`total ${curr.code} ${formatMoney(totalBalance, curr.minorUnits)} (${currAccounts.length} accounts)`);
    }
}

