import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.toLowerCase().endsWith(".bmp"));
        if (files == null) return;
        Arrays.sort(files, Comparator.comparing(File::getName));

        for (File file : files) {
            processFile(file);
        }
    }

    static void processFile(File file) {
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            ByteBuffer bb = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);

            if (data.length < 14) return;
            if (bb.get() != 'B' || bb.get() != 'M') return;

            long fileSize = bb.getInt() & 0xFFFFFFFFL;
            bb.getShort(); // reserved
            bb.getShort(); // reserved
            long bfOffBits = bb.getInt() & 0xFFFFFFFFL;

            int dibHeaderSize = bb.getInt();
            int width = bb.getInt();
            int height = bb.getInt();
            int planes = bb.getShort() & 0xFFFF;
            int bpp = bb.getShort() & 0xFFFF;
            long compression = bb.getInt() & 0xFFFFFFFFL;
            long imageSize = bb.getInt() & 0xFFFFFFFFL;
            int xppm = bb.getInt();
            int yppm = bb.getInt();
            long coloursUsed = bb.getInt() & 0xFFFFFFFFL;
            long importantColours = bb.getInt() & 0xFFFFFFFFL;

            System.out.println("== " + file.getName());

            if (compression != 0 && compression != 3) {
                System.out.println("error: unsupported compression " + compression);
                return;
            }

            int[] redMasks = new int[3]; // R, G, B
            if (compression == 3) {
                if (dibHeaderSize == 40) {
                    bb.position(14 + 40);
                    redMasks[0] = bb.getInt();
                    redMasks[1] = bb.getInt();
                    redMasks[2] = bb.getInt();
                } else {
                    bb.position(14 + 40 + 12); // Skip to masks in 108/124 header
                    redMasks[0] = bb.getInt();
                    redMasks[1] = bb.getInt();
                    redMasks[2] = bb.getInt();
                }
            }

            int absHeight = Math.abs(height);
            boolean bottomUp = height > 0;
            int rowSize = (width * bpp + 7) / 8;
            rowSize = (rowSize + 3) & ~3;

            int[][] pixels = new int[absHeight][width * 3]; // Store as R, G, B for each pixel
            int[] colorTable = new int[0];
            if (bpp == 1 || bpp == 4 || bpp == 8) {
                int numColors = (coloursUsed == 0) ? (1 << bpp) : (int) coloursUsed;
                colorTable = new int[numColors * 3];
                bb.position(14 + dibHeaderSize);
                for (int i = 0; i < numColors; i++) {
                    int b = bb.get() & 0xFF;
                    int g = bb.get() & 0xFF;
                    int r = bb.get() & 0xFF;
                    bb.get(); // unused
                    colorTable[i * 3] = r;
                    colorTable[i * 3 + 1] = g;
                    colorTable[i * 3 + 2] = b;
                }
            }

            byte[] pixelData = new byte[data.length - (int) bfOffBits];
            System.arraycopy(data, (int) bfOffBits, pixelData, 0, pixelData.length);

            for (int r = 0; r < absHeight; r++) {
                int taskY = bottomUp ? absHeight - 1 - r : r;
                int offset = r * rowSize;
                for (int x = 0; x < width; x++) {
                    int red, green, blue;
                    if (bpp == 1 || bpp == 4 || bpp == 8) {
                        int colorIdx;
                        if (bpp == 1) {
                            int byteIdx = offset + (x / 8);
                            int bitIdx = 7 - (x % 8);
                            colorIdx = (pixelData[byteIdx] >> bitIdx) & 1;
                        } else if (bpp == 4) {
                            int byteIdx = offset + (x / 2);
                            int bitIdx = 4 * (1 - (x % 2));
                            colorIdx = (pixelData[byteIdx] >> bitIdx) & 0x0F;
                        } else {
                            int byteIdx = offset + x;
                            colorIdx = pixelData[byteIdx] & 0xFF;
                        }
                        red = colorTable[colorIdx * 3];
                        green = colorTable[colorIdx * 3 + 1];
                        blue = colorTable[colorIdx * 3 + 2];
                    } else if (bpp == 24) {
                        int byteIdx = offset + x * 3;
                        blue = pixelData[byteIdx] & 0xFF;
                        green = pixelData[byteIdx + 1] & 0xFF;
                        red = pixelData[byteIdx + 2] & 0xFF;
                    } else if (bpp == 32) {
                        int byteIdx = offset + x * 4;
                        int pixel = (pixelData[byteIdx] & 0xFF) | ((pixelData[byteIdx + 1] & 0xFF) << 8) |
                                   ((pixelData[byteIdx + 2] & 0xFF) << 16) | ((pixelData[byteIdx + 3] & 0xFF) << 24);
                        if (compression == 0) {
                            blue = pixelData[byteIdx] & 0xFF;
                            green = pixelData[byteIdx + 1] & 0xFF;
                            red = pixelData[byteIdx + 2] & 0xFF;
                        } else {
                            red = extractChannel(pixel, redMasks[0]);
                            green = extractChannel(pixel, redMasks[1]);
                            blue = extractChannel(pixel, redMasks[2]);
                        }
                    } else {
                        red = green = blue = 0;
                    }
                    pixels[taskY][x * 3] = red;
                    pixels[taskY][x * 3 + 1] = green;
                    pixels[taskY][x * 3 + 2] = blue;
                }
            }

            boolean[][] isInk = new boolean[absHeight][width];
            int inkCount = 0;
            for (int y = 0; y < absHeight; y++) {
                for (int x = 0; x < width; x++) {
                    int r = pixels[y][x * 3];
                    int g = pixels[y][x * 3 + 1];
                    int b = pixels[y][x * 3 + 2];
                    if ((299 * r + 587 * g + 114 * b) / 1000 < 128) {
                        isInk[y][x] = true;
                        inkCount++;
                    }
                }
            }

            System.out.println("size " + width + "x" + absHeight + " bpp " + bpp + " header " + dibHeaderSize + " " + (bottomUp ? "bottom-up" : "top-down") + " ink " + inkCount);

            List<Component> components = new ArrayList<>();
            boolean[][] visited = new boolean[absHeight][width];
            for (int y = 0; y < absHeight; y++) {
                for (int x = 0; x < width; x++) {
                    if (isInk[y][x] && !visited[y][x]) {
                        Component comp = new Component();
                        Queue<int[]> queue = new LinkedList<>();
                        queue.add(new int[]{x, y});
                        visited[y][x] = true;
                        while (!queue.isEmpty()) {
                            int[] curr = queue.poll();
                            int cx = curr[0], cy = curr[1];
                            comp.addPixel(cx, cy);
                            for (int dy = -1; dy <= 1; dy++) {
                                for (int dx = -1; dx <= 1; dx++) {
                                    if (dx == 0 && dy == 0) continue;
                                    int nx = cx + dx, ny = cy + dy;
                                    if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight && isInk[ny][nx] && !visited[ny][nx]) {
                                        visited[ny][nx] = true;
                                        queue.add(new int[]{nx, ny});
                                    }
                                }
                            }
                        }
                        components.add(comp);
                    }
                }
            }

            Collections.sort(components, Comparator.comparing(c -> c.firstPixel));
            System.out.println("components " + components.size());
            for (Component c : components) {
                System.out.println(c.firstPixel[0] + "," + c.firstPixel[1] + " bbox " + c.minX + "," + c.minY + "-" + c.maxX + "," + c.maxY + " pixels " + c.pixelCount);
            }

        } catch (IOException e) {
            // Silence IO errors
        }
    }

    static int extractChannel(int pixel, int mask) {
        int s = Integer.numberOfTrailingZeros(mask);
        int n = Integer.bitCount(mask);
        int m = (1 << n) - 1;
        int v = (pixel & mask) >>> s;
        return (v * 255 + m / 2) / m;
    }

    static class Component {
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        int pixelCount = 0;
        int[] firstPixel = new int[]{Integer.MAX_VALUE, Integer.MAX_VALUE};

        void addPixel(int x, int y) {
            minX = Math.min(minX, x);
            minY = Math.min(minY, y);
            maxX = Math.max(maxX, x);
            maxY = Math.max(maxY, y);
            pixelCount++;
            if (y < firstPixel[1] || (y == firstPixel[1] && x < firstPixel[0])) {
                firstPixel[0] = x;
                firstPixel[1] = y;
            }
        }
    }
}

