#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <dirent.h>

typedef struct {
    uint8_t b, g, r, unused;
} PaletteEntry;

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point first;
    int minx, miny, maxx, maxy;
    int pixels;
} Component;

uint32_t read_u32(FILE *fp) {
    uint32_t val;
    if (fread(&val, 4, 1, fp) != 1) return 0;
    return val;
}

uint16_t read_u16(FILE *fp) {
    uint16_t val;
    if (fread(&val, 2, 1, fp) != 1) return 0;
    return val;
}

int32_t read_i32(FILE *fp) {
    int32_t val;
    if (fread(&val, 4, 1, fp) != 1) return 0;
    return val;
}

int calculate_channel(uint32_t pixel, uint32_t mask) {
    int s = 0;
    uint32_t temp_mask = mask;
    while (temp_mask && !(temp_mask & 1)) {
        temp_mask >>= 1;
        s++;
    }
    int n = 0;
    temp_mask = mask;
    while (temp_mask) {
        if (temp_mask & 1) n++;
        temp_mask >>= 1;
    }
    uint32_t v = (pixel & mask) >> s;
    uint32_t m = (1U << n) - 1;
    return (int)((v * 255 + m / 2) / m);
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

void process_bmp(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return;

    char magic[2];
    fread(magic, 1, 2, fp);
    uint32_t file_size = read_u32(fp);
    uint16_t res1 = read_u16(fp);
    uint16_t res2 = read_u16(fp);
    uint32_t bfOffBits = read_u32(fp);
    uint32_t dib_size = read_u32(fp);
    int32_t width = read_i32(fp);
    int32_t height = read_i32(fp);
    uint16_t planes = read_u16(fp);
    uint16_t bpp = read_u16(fp);
    uint32_t compression = read_u32(fp);
    uint32_t image_size = read_u32(fp);
    int32_t x_ppm = read_i32(fp);
    int32_t y_ppm = read_i32(fp);
    uint32_t colours_used = read_u32(fp);
    uint32_t important_colours = read_u32(fp);

    uint32_t maskR = 0, maskG = 0, maskB = 0;
    if (dib_size == 108 || dib_size == 124) {
        maskR = read_u32(fp); maskG = read_u32(fp); maskB = read_u32(fp);
        read_u32(fp); // alpha
        if (dib_size == 124) {
            uint8_t dummy[16]; fread(dummy, 1, 16, fp);
        }
    }

    printf("== %s\n", filename);
    if (compression != 0 && compression != 3) {
        printf("error: unsupported compression %u\n", compression);
        fclose(fp);
        return;
    }

    int actual_height = abs(height);
    uint32_t padded_row_size = ((width * bpp + 31) / 32) * 4;
    PaletteEntry *palette = NULL;
    if (bpp == 1 || bpp == 4 || bpp == 8) {
        uint32_t num_colours = (colours_used == 0) ? (1U << bpp) : colours_used;
        palette = malloc(num_colours * sizeof(PaletteEntry));
        fseek(fp, 14 + dib_size, SEEK_SET);
        fread(palette, 4, num_colours, fp);
    }

    if (compression == 3 && dib_size == 40) {
        fseek(fp, 14 + 40, SEEK_SET);
        maskR = read_u32(fp); maskG = read_u32(fp); maskB = read_u32(fp);
    }

    fseek(fp, bfOffBits, SEEK_SET);
    uint8_t *data = malloc(padded_row_size * actual_height);
    fread(data, padded_row_size * actual_height, 1, fp);
    fclose(fp);

    bool *ink_map = malloc(width * actual_height * sizeof(bool));
    int ink_count = 0;
    for (int y = 0; y < actual_height; y++) {
        int stored_row = (height > 0) ? (actual_height - 1 - y) : y;
        uint8_t *row_ptr = data + (stored_row * padded_row_size);
        for (int x = 0; x < width; x++) {
            int r, g, b;
            if (bpp == 1 || bpp == 4 || bpp == 8) {
                int idx;
                if (bpp == 1) idx = (row_ptr[x / 8] >> (7 - (x % 8))) & 1;
                else if (bpp == 4) idx = (x % 2 == 0) ? (row_ptr[x / 2] >> 4) & 0xF : row_ptr[x / 2] & 0xF;
                else idx = row_ptr[x];
                b = palette[idx].b; g = palette[idx].g; r = palette[idx].r;
            } else if (bpp == 24) {
                b = row_ptr[x * 3]; g = row_ptr[x * 3 + 1]; r = row_ptr[x * 3 + 2];
            } else {
                uint32_t pixel; memcpy(&pixel, &row_ptr[x * 4], 4);
                if (compression == 0) {
                    b = (pixel & 0xFF); g = (pixel >> 8) & 0xFF; r = (pixel >> 16) & 0xFF;
                } else {
                    r = calculate_channel(pixel, maskR); g = calculate_channel(pixel, maskG); b = calculate_channel(pixel, maskB);
                }
            }
            if ((299 * r + 587 * g + 114 * b) / 1000 < 128) {
                ink_map[y * width + x] = true;
                ink_count++;
            } else ink_map[y * width + x] = false;
        }
    }
    printf("size %dx%d bpp %d header %u %s ink %d\n", width, actual_height, bpp, dib_size, (height > 0 ? "bottom-up" : "top-down"), ink_count);

    bool *visited = calloc(width * actual_height, sizeof(bool));
    int dx[] = {-1, 0, 1, -1, 1, -1, 0, 1}, dy[] = {-1, -1, -1, 0, 0, 1, 1, 1};
    Point *q = malloc(width * actual_height * sizeof(Point));
    Component *comps = malloc(width * actual_height * sizeof(Component));
    int comps_count = 0;

    for (int y = 0; y < actual_height; y++) {
        for (int x = 0; x < width; x++) {
            if (ink_map[y * width + x] && !visited[y * width + x]) {
                int head = 0, tail = 0;
                q[tail++] = (Point){x, y};
                visited[y * width + x] = true;
                int minx = x, maxx = x, miny = y, maxy = y, count = 0;
                while (head < tail) {
                    Point p = q[head++];
                    count++;
                    if (p.x < minx) minx = p.x; if (p.x > maxx) maxx = p.x;
                    if (p.y < miny) miny = p.y; if (p.y > maxy) maxy = p.y;
                    for (int i = 0; i < 8; i++) {
                        int nx = p.x + dx[i], ny = p.y + dy[i];
                        if (nx >= 0 && nx < width && ny >= 0 && ny < actual_height && ink_map[ny * width + nx] && !visited[ny * width + nx]) {
                            visited[ny * width + nx] = true;
                            q[tail++] = (Point){nx, ny};
                        }
                    }
                }
                comps[comps_count++] = (Component){{x, y}, minx, miny, maxx, maxy, count};
            }
        }
    }
    printf("components %d\n", comps_count);
    for (int i = 0; i < comps_count; i++) {
        printf("%d,%d bbox %d,%d-%d,%d pixels %d\n", comps[i].first.x, comps[i].first.y, comps[i].minx, comps[i].miny, comps[i].maxx, comps[i].maxy, comps[i].pixels);
    }

    free(palette); free(data); free(ink_map); free(visited); free(q); free(comps);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    DIR *dp = opendir(argv[1]);
