import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 2) return;
        String dir = args[0];
        int port = Integer.parseInt(args[1]);

        File queriesFile = new File(dir, "queries.txt");
        try (BufferedReader reader = new BufferedReader(new FileReader(queriesFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                String[] parts = line.split("\\s+");
                if (parts.length < 2) continue;
                String name = parts[0];
                String typeStr = parts[1];

                int type = getQType(typeStr);
                byte[] query = buildQuery(name, type);
                byte[] response = sendUdpQuery(query, port);

                if (response == null) continue;

                ByteBuffer buffer = ByteBuffer.wrap(response);
                int flags = buffer.getShort(2) & 0xFFFF;
                if ((flags & 0x0100) != 0) { // TC = 1
                    response = sendTcpQuery(query, port);
                    buffer = ByteBuffer.wrap(response);
                }

                parseAndPrintResponse(name, typeStr, buffer);
            }
        } catch (IOException e) {
            // Silently fail as per requirements
        }
    }

    private static int getQType(String type) {
        return switch (type) {
            case "A" -> 1;
            case "CNAME" -> 5;
            case "MX" -> 15;
            case "TXT" -> 16;
            case "AAAA" -> 28;
            default -> 0;
        };
    }

    private static byte[] buildQuery(String name, int type) {
        ByteBuffer buffer = ByteBuffer.allocate(512);
        buffer.putShort((short) (Math.random() * 65535)); // ID
        buffer.putShort((short) 0x0100); // Flags RD=1
        buffer.putShort((short) 1); // QDCOUNT
        buffer.putShort((short) 0); // ANCOUNT
        buffer.putShort((short) 0); // NSCOUNT
        buffer.putShort((short) 0); // ARCOUNT

        if (name.endsWith(".")) name = name.substring(0, name.length() - 1);
        String[] labels = name.split("\\.");
        for (String label : labels) {
            buffer.put((byte) label.length());
            buffer.put(label.getBytes());
        }
        buffer.put((byte) 0);
        buffer.putShort((short) type);
        buffer.putShort((short) 1); // Class IN

        byte[] result = new byte[buffer.position()];
        buffer.flip();
        buffer.get(result);
        return result;
    }

    private static byte[] sendUdpQuery(byte[] query, int port) {
        try {
            DatagramSocket socket = new DatagramSocket();
            socket.setSoTimeout(5000);
            InetAddress address = InetAddress.getByName("127.0.0.1");
            DatagramPacket packet = new DatagramPacket(query, query.length, address, port);
            socket.send(packet);

            byte[] buf = new byte[65535];
            while (true) {
                DatagramPacket responsePacket = new DatagramPacket(buf, buf.length);
                socket.receive(responsePacket);
                ByteBuffer respBuf = ByteBuffer.wrap(responsePacket.getData());
                int id = respBuf.getShort(0) & 0xFFFF;
                int flags = respBuf.getShort(2) & 0xFFFF;
                int queryId = ByteBuffer.wrap(query).getShort(0) & 0xFFFF;

                if (id == queryId && (flags & 0x8000) != 0) {
                    byte[] res = new byte[responsePacket.getLength()];
                    System.arraycopy(responsePacket.getData(), 0, res, 0, res.length);
                    socket.close();
                    return res;
                }
            }
        } catch (IOException e) {
            return null;
        }
    }

    private static byte[] sendTcpQuery(byte[] query, int port) {
        try (Socket socket = new Socket("127.0.0.1", port);
             DataOutputStream out = new DataOutputStream(socket.getOutputStream());
             DataInputStream in = new DataInputStream(socket.getInputStream())) {
            out.writeShort(query.length);
            out.write(query);
            out.flush();
            int len = in.readUnsignedShort();
            byte[] res = new byte[len];
            in.readFully(res);
            return res;
        } catch (IOException e) {
            return new byte[0];
        }
    }

    private static void parseAndPrintResponse(String name, String typeStr, ByteBuffer buffer) {
        int id = buffer.getShort(0) & 0xFFFF;
        int flags = buffer.getShort(2) & 0xFFFF;
        int rcode = flags & 0x000F;
        int qdcount = buffer.getShort(4) & 0xFFFF;
        int ancount = buffer.getShort(6) & 0xFFFF;

        String[] rcodes = {"NOERROR", "FORMERR", "SERVFAIL", "NXDOMAIN", "NOTIMP", "REFUSED"};
        String rcodeStr = (rcode < 6) ? rcodes[rcode] : "RCODE" + rcode;
        System.out.println(name.toLowerCase().replaceAll("\\.$", "") + " " + typeStr + " " + rcodeStr);

        buffer.position(12);
        for (int i = 0; i < qdcount; i++) {
            readName(buffer);
            buffer.getShort(); // qtype
            buffer.getShort(); // qclass
        }

        for (int i = 0; i < ancount; i++) {
            String owner = readName(buffer);
            int type = buffer.getShort() & 0xFFFF;
            int clazz = buffer.getShort() & 0xFFFF;
            long ttl = buffer.getInt() & 0xFFFFFFFFL;
            int rdlen = buffer.getShort() & 0xFFFF;
            byte[] rdata = new byte[rdlen];
            buffer.get(rdata);

            System.out.print("  " + owner + " " + ttl + " ");
            printRData(type, rdata, buffer);
