    private static void printRData(int type, byte[] rdata, ByteBuffer buffer) {
        switch (type) {
            case 1 -> { // A
                System.out.print("A " + (rdata[0] & 0xFF) + "." + (rdata[1] & 0xFF) + "." + (rdata[2] & 0xFF) + "." + (rdata[3] & 0xFF));
