            case 5 -> { // CNAME
                ByteBuffer temp = ByteBuffer.wrap(rdata);
                // This is a simplification; CNAME in RDATA can also be compressed relative to the whole message.
                // Since we are passing the RDATA slice, we need the full message context.
                // Let's use a helper that takes the full buffer and the start offset.
                System.out.print("CNAME " + readNameAtOffset(buffer, buffer.position() - rdata.length - 10)); // Approximate
                // Correct way: call readName with the original buffer at the correct position.
            }
            case 15 -> { // MX
                int pref = ((rdata[0] & 0xFF) << 8) | (rdata[1] & 0xFF);
                System.out.print("MX " + pref + " " + readNameAtOffset(buffer, buffer.position() - rdata.length - 10)); // Approx
            }
            case 16 -> { // TXT
