    private static String readName(ByteBuffer buffer) {
        StringBuilder sb = new StringBuilder();
        int pos = buffer.position();
        int consumed = 0;
        boolean jumped = false;
        int jumps = 0;
        while (true) {
            if (jumps > 20) break;
            int b = buffer.get(pos) & 0xFF;
            if (b == 0) {
                if (!jumped) consumed++;
                break;
            }
            if ((b & 0xC0) == 0xC0) {
                int pointer = ((b & 0x3F) << 8) | (buffer.get(pos + 1) & 0xFF);
                if (!jumped) consumed += 2;
                pos = pointer;
                jumped = true;
                jumps++;
            } else {
                int len = b;
                for (int i = 0; i < len; i++) sb.append(Character.toLowerCase((char) buffer.get(pos + 1 + i)));
                if (sb.length() > 0) sb.append('.');
                pos += 1 + len;
                if (!jumped) consumed += 1 + len;
            }
        }
        buffer.position(buffer.position() + consumed);
        String res = sb.toString();
        if (res.endsWith(".")) res = res.substring(0, res.length() - 1);
        return res.isEmpty() ? "." : res;
    }

    private static String formatAAAA(byte[] data) {
        String[] groups = new String[8];
        for (int i = 0; i < 8; i++) {
            int val = ((data[i * 2] & 0xFF) << 8) | (data[i * 2 + 1] & 0xFF);
            groups[i] = Integer.toHexString(val);
        }
        int maxRun = 0, startRun = -1;
        for (int i = 0; i < 8; i++) {
            if (groups[i].equals("0")) {
                int j = i;
                while (j < 8 && groups[j].equals("0")) j++;
                if (j - i > maxRun) {
                    maxRun = j - i;
                    startRun = i;
                }
                i = j - 1;
            }
        }
        if (maxRun < 2) return String.join(":", groups);
        String left = String.join(":", Arrays.copyOfRange(groups, 0, startRun));
        String right = String.join(":", Arrays.copyOfRange(groups, startRun + maxRun, 8));
        return left + "::" + right;
    }

    private static String formatTXT(byte[] data) {
        StringBuilder res = new StringBuilder();
        int pos = 0;
        while (pos < data.length) {
            int len = data[pos++] & 0xFF;
            StringBuilder quoted = new StringBuilder("\"");
            for (int i = 0; i < len; i++) {
                byte b = data[pos++];
                if (b == '"') quoted.append("\\\"");
                else if (b == '\\') quoted.append("\\\\");
                else if (b >= 0x20 && b <= 0x7E) quoted.append((char) b);
                else quoted.append(String.format("\\%03d", b & 0xFF));
            }
            quoted.append("\"");
            res.append(quoted).append(" ");
        }
        return res.toString().trim();
    }

    // Re-implementing the main loop to use the fixed parser
    static {
        // Since I can't modify the main method's call easily, I'll just rewrite the logic inside it.
    }
}

import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 2) return;
        String dir = args[0];
        int port = Integer.parseInt(args[1]);

        File queriesFile = new File(dir, "queries.txt");
        try (BufferedReader reader = new BufferedReader(new FileReader(queriesFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                String[] parts = line.split("\\s+");
                if (parts.length < 2) continue;
                String name = parts[0];
                String typeStr = parts[1];

                int type = getQType(typeStr);
                byte[] query = buildQuery(name, type);
                byte[] response = sendUdpQuery(query, port);

                if (response == null) continue;

                ByteBuffer buffer = ByteBuffer.wrap(response);
                int flags = buffer.getShort(2) & 0xFFFF;
                if ((flags & 0x0200) != 0) { // TC = 1 (Truncated)
                    response = sendTcpQuery(query, port);
                    buffer = ByteBuffer.wrap(response);
                }

                parseAndPrintResponse(name, typeStr, buffer);
            }
        } catch (IOException e) {
            // Silently fail as per requirements
        }
    }

    private static int getQType(String type) {
        return switch (type) {
            case "A" -> 1;
            case "CNAME" -> 5;
            case "MX" -> 15;
            case "TXT" -> 16;
            case "AAAA" -> 28;
            default -> 0;
        };
    }

    private static byte[] buildQuery(String name, int type) {
        ByteBuffer buffer = ByteBuffer.allocate(512);
        buffer.putShort((short) (Math.random() * 65535)); // ID
        buffer.putShort((short) 0x0100); // Flags RD=1
        buffer.putShort((short) 1); // QDCOUNT
        buffer.putShort((short) 0); // ANCOUNT
        buffer.putShort((short) 0); // NSCOUNT
        buffer.putShort((short) 0); // ARCOUNT

        String cleanName = name.endsWith(".") ? name.substring(0, name.length() - 1) : name;
        if (!cleanName.isEmpty()) {
            String[] labels = cleanName.split("\\.");
            for (String label : labels) {
                buffer.put((byte) label.length());
                buffer.put(label.getBytes());
            }
        }
        buffer.put((byte) 0);
        buffer.putShort((short) type);
        buffer.putShort((short) 1); // Class IN

        byte[] result = new byte[buffer.position()];
        buffer.flip();
        buffer.get(result);
        return result;
    }

    private static byte[] sendUdpQuery(byte[] query, int port) {
        try {
            DatagramSocket socket = new DatagramSocket();
            socket.setSoTimeout(5000);
            InetAddress address = InetAddress.getByName("127.0.0.1");
            DatagramPacket packet = new DatagramPacket(query, query.length, address, port);
            socket.send(packet);

            int queryId = ByteBuffer.wrap(query).getShort(0) & 0xFFFF;
            byte[] buf = new byte[65535];
            while (true) {
                DatagramPacket responsePacket = new DatagramPacket(buf, buf.length);
                socket.receive(responsePacket);
                ByteBuffer respBuf = ByteBuffer.wrap(responsePacket.getData(), 0, responsePacket.getLength());
                int id = respBuf.getShort(0) & 0xFFFF;
                int flags = respBuf.getShort(2) & 0xFFFF;
                if (id == queryId && (flags & 0x8000) != 0) {
                    byte[] res = new byte[responsePacket.getLength()];
                    System.arraycopy(responsePacket.getData(), 0, res, 0, res.length);
                    socket.close();
                    return res;
                }
            }
        } catch (IOException e) {
            return null;
        }
    }

    private static byte[] sendTcpQuery(byte[] query, int port) {
        try (Socket socket = new Socket("127.0.0.1", port);
             DataOutputStream out = new DataOutputStream(socket.getOutputStream());
             DataInputStream in = new DataInputStream(socket.getInputStream())) {
            out.writeShort(query.length);
            out.write(query);
            out.flush();
            int len = in.readUnsignedShort();
            byte[] res = new byte[len];
            in.readFully(res);
            return res;
        } catch (IOException e) {
            return new byte[0];
        }
    }

    private static void parseAndPrintResponse(String name, String typeStr, ByteBuffer buffer) {
        int flags = buffer.getShort(2) & 0xFFFF;
        int rcode = flags & 0x000F;
        int qdcount = buffer.getShort(4) & 0xFFFF;
        int ancount = buffer.getShort(6) & 0xFFFF;

        String[] rcodeNames = {"NOERROR", "FORMERR", "SERVFAIL", "NXDOMAIN", "NOTIMP", "REFUSED"};
        String rcodeStr = (rcode < 6) ? rcodeNames[rcode] : "RCODE" + rcode;
        System.out.println(name.toLowerCase().replaceAll("\\.$", "") + " " + typeStr + " " + rcodeStr);

        buffer.position(12);
        for (int i = 0; i < qdcount; i++) {
            readName(buffer);
            buffer.getShort(); // qtype
            buffer.getShort(); // qclass
        }

        for (int i = 0; i < ancount; i++) {
            String owner = readName(buffer);
            int type = buffer.getShort() & 0xFFFF;
            buffer.getShort(); // class
            long ttl = buffer.getInt() & 0xFFFFFFFFL;
            int rdlen = buffer.getShort() & 0xFFFF;
            int rdataStart = buffer.position();
            byte[] rdata = new byte[rdlen];
            buffer.get(rdata);

            System.out.print("  " + owner + " " + ttl + " ");
            if (type == 1) {
                System.out.print("A " + (rdata[0] & 0xFF) + "." + (rdata[1] & 0xFF) + "." + (rdata[2] & 0xFF) + "." + (rdata[3] & 0xFF));
            } else if (type == 28) {
                System.out.print("AAAA " + formatAAAA(rdata));
            } else if (type == 5) {
                buffer.position(rdataStart);
                System.out.print("CNAME " + readName(buffer));
            } else if (type == 15) {
                int pref = ((rdata[0] & 0xFF) << 8) | (rdata[1] & 0xFF);
                buffer.position(rdataStart + 2);
                System.out.print("MX " + pref + " " + readName(buffer));
            } else if (type == 16) {
                System.out.print("TXT " + formatTXT(rdata));
            } else {
                System.out.print("TYPE" + type + " # " + rdlen);
                if (rdlen > 0) {
                    System.out.print(" ");
                    for (byte b : rdata) System.out.printf("%02x", b);
                }
            }
            System.out.println();
            buffer.position(rdataStart + rdlen);
        }
    }

    private static String readName(ByteBuffer buffer) {
        StringBuilder sb = new StringBuilder();
        int pos = buffer.position();
        int nextPos = -1;
        boolean jumped = false;
        while (true) {
            int b = buffer.get(pos) & 0xFF;
            if (b == 0) {
                pos++;
                if (!jumped) nextPos = pos;
                break;
            } else if ((b & 0xC0) == 0xC0) {
                int offset = ((b & 0x3F) << 8) | (buffer.get(pos + 1) & 0xFF);
                if (!jumped) nextPos = pos + 2;
                jumped = true;
                pos = offset;
            } else {
                int len = b;
                pos++;
                for (int i = 0; i < len; i++) {
                    sb.append((char) buffer.get(pos++));
                }
                sb.append('.');
                if (!jumped) nextPos = pos;
            }
        }
        if (nextPos != -1) buffer.position(nextPos);
        String res = sb.toString().toLowerCase();
        if (res.endsWith(".")) res = res.substring(0, res.length() - 1);
        return res.isEmpty() ? "." : res;
    }

    private static String formatAAAA(byte[] data) {
        int[] words = new int[8];
        for (int i = 0; i < 8; i++) {
            words[i] = ((data[i * 2] & 0xFF) << 8) | (data[i * 2 + 1] & 0xFF);
        }
        int maxRun = 0, startRun = -1;
        for (int i = 0; i < 8; i++) {
            if (words[i] == 0) {
                int j = i;
                while (j < 8 && words[j] == 0) j++;
                if (j - i > maxRun) {
                    maxRun = j - i;
                    startRun = i;
                }
                i = j - 1;
            }
        }
        if (maxRun < 2) startRun = -1;

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 8; i++) {
            if (i == startRun) {
                sb.append("::");
                i += maxRun - 1;
            } else {
                sb.append(Integer.toHexString(words[i]));
                if (i < 7 && (i + 1 != startRun)) {
                    sb.append(":");
                }
            }
        }
        return sb.toString();
    }

    private static String formatTXT(byte[] data) {
        StringBuilder sb = new StringBuilder();
        int pos = 0;
        while (pos < data.length) {
            int len = data[pos++] & 0xFF;
            sb.append('"');
            for (int i = 0; i < len; i++) {
                byte b = data[pos++];
                if (b == '"') sb.append("\\\"");
                else if (b == '\\') sb.append("\\\\");
                else if (b >= 0x20 && b <= 0x7E) sb.append((char) b);
                else sb.append(String.format("\\%03d", b & 0xFF));
            }
            sb.append('"');
            if (pos < data.length) sb.append(' ');
        }
        return sb.toString();
    }
}

#include <stdio.h>
