typedef struct {
    uint16_t id;
    uint16_t flags;
    uint16_t qdcount;
    uint16_t ancount;
    uint16_t nscount;
    uint16_t arcount;
} DNSHeader;

uint16_t get_type_val(const char *type) {
    if (strcmp(type, "A") == 0) return 1;
    if (strcmp(type, "CNAME") == 0) return 5;
    if (strcmp(type, "MX") == 0) return 15;
    if (strcmp(type, "TXT") == 0) return 16;
    if (strcmp(type, "AAAA") == 0) return 28;
    return 0;
}

const char *get_type_name(uint16_t type) {
    if (type == 1) return "A";
    if (type == 5) return "CNAME";
    if (type == 15) return "MX";
    if (type == 16) return "TXT";
    if (type == 28) return "AAAA";
    return NULL;
}

const char *get_rcode_name(uint8_t rcode) {
    if (rcode == 0) return "NOERROR";
    if (rcode == 1) return "FORMERR";
    if (rcode == 2) return "SERVFAIL";
    if (rcode == 3) return "NXDOMAIN";
    if (rcode == 4) return "NOTIMP";
    if (rcode == 5) return "REFUSED";
    return NULL;
}

void dns_name_to_wire(const char *name, uint8_t *buf, int *pos) {
    char temp[256];
    strncpy(temp, name, 255);
    temp[255] = '\0';
    char *token = strtok(temp, ".");
    while (token) {
        int len = strlen(token);
        buf[(*pos)++] = (uint8_t)len;
        memcpy(&buf[*pos], token, len);
        *pos += len;
        token = strtok(NULL, ".");
    }
    buf[(*pos)++] = 0;
}

void parse_name(uint8_t *buf, int pos, char *out, int *next_pos) {
    int curr = pos;
    int jumped = 0;
    int offset = 0;
    int len = 0;
    bool done = false;

    while (!done) {
        uint8_t b = buf[curr];
        if ((b & 0xC0) == 0xC0) {
            uint16_t ptr = ((b & 0x3F) << 8) | buf[curr + 1];
            if (!jumped) *next_pos = curr + 2;
            jumped = 1;
            curr = ptr;
        } else {
            if (b == 0) {
                done = true;
                if (!jumped) *next_pos = curr + 1;
            } else {
                int label_len = b;
                for (int i = 0; i < label_len; i++) {
                    if (len > 0) out[len++] = '.';
                    out[len++] = tolower(buf[curr + 1 + i]);
                }
                curr += label_len + 1;
            }
        }
    }
    out[len] = '\0';
    if (len == 0) strcpy(out, ".");
}

void print_txt(uint8_t *buf, int pos, int len) {
    int curr = 0;
    while (curr < len) {
        uint8_t s_len = buf[pos + curr];
        printf("\"");
        for (int i = 0; i < s_len; i++) {
            uint8_t c = buf[pos + curr + 1 + i];
            if (c == '"') printf("\\\"");
            else if (c == '\\') printf("\\\\");
            else if (c >= 0x20 && c <= 0x7E) printf("%c", c);
            else printf("\\%03d", c);
        }
        printf("\"");
        curr += s_len + 1;
        if (curr < len) printf(" ");
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) return 1;
    char path[512];
    snprintf(path, sizeof(path), "%s/queries.txt", argv[1]);
    int port = atoi(argv[2]);

    FILE *fp = fopen(path, "r");
    if (!fp) return 1;

    srand(time(NULL));
    char line[512];
    while (fgets(line, sizeof(line), fp)) {
        char qname[256], qtype_str[64];
        if (sscanf(line, "%s %s", qname, qtype_str) != 2) continue;

        uint16_t qtype = get_type_val(qtype_str);
        uint16_t id = (uint16_t)rand();
        uint8_t query[512];
        int pos = 0;

        DNSHeader *header = (DNSHeader *)query;
        header->id = htons(id);
        header->flags = htons(0x0100);
        header->qdcount = htons(1);
        header->ancount = htons(0);
        header->nscount = htons(0);
        header->arcount = htons(0);
        pos = 12;

        char name_clean[256];
        strcpy(name_clean, qname);
        int len_name = strlen(name_clean);
        if (len_name > 0 && name_clean[len_name - 1] == '.') name_clean[len_name - 1] = '\0';
        dns_name_to_wire(name_clean, query, &pos);

        uint16_t type_net = htons(qtype);
        uint16_t class_net = htons(1);
        memcpy(&query[pos], &type_net, 2);
        memcpy(&query[pos + 2], &class_net, 2);
        pos += 4;

        struct sockaddr_in server;
        memset(&server, 0, sizeof(server));
        server.sin_family = AF_INET;
        server.sin_port = htons(port);
        inet_pton(AF_INET, "127.0.0.1", &server.sin_addr);

        int udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
        sendto(udp_sock, query, pos, 0, (struct sockaddr *)&server, sizeof(server));

        uint8_t res_buf[4096];
        int res_len = 0;
        bool truncated = false;

        while (1) {
            int rec = recvfrom(udp_sock, res_buf, sizeof(res_buf), 0, NULL, NULL);
            if (rec < 12) continue;
            DNSHeader *res_h = (DNSHeader *)res_buf;
            if (ntohs(res_h->id) != id || !(ntohs(res_h->flags) & 0x8000)) continue;
            res_len = rec;
            if (ntohs(res_h->flags) & 0x0200) truncated = true;
            break;
        }
        close(udp_sock);

        if (truncated) {
            int tcp_sock = socket(AF_INET, SOCK_STREAM, 0);
            connect(tcp_sock, (struct sockaddr *)&server, sizeof(server));
            uint16_t q_len = htons(pos);
            send(tcp_sock, &q_len, 2, 0);
            send(tcp_sock, query, pos, 0);
            uint16_t r_len_net;
            recv(tcp_sock, &r_len_net, 2, MSG_WAITALL);
            int r_len = ntohs(r_len_net);
            int total_rec = 0;
            while (total_rec < r_len) {
                int n = recv(tcp_sock, res_buf + total_rec, r_len - total_rec, 0);
                if (n <= 0) break;
                total_rec += n;
            }
            res_len = total_rec;
            close(tcp_sock);
        }

        DNSHeader *rh = (DNSHeader *)res_buf;
        uint8_t rcode = ntohs(rh->flags) & 0x000F;
        char lower_qname[256];
        int dummy;
        parse_name(res_buf, 12, lower_qname, &dummy);

        const char *rcode_name = get_rcode_name(rcode);
        if (rcode_name) printf("%s %s %s\n", lower_qname, qtype_str, rcode_name);
        else printf("%s %s RCODE%d\n", lower_qname, qtype_str, rcode);

        int curr_pos = 12;
        int qdcount = ntohs(rh->qdcount);
        for (int i = 0; i < qdcount; i++) {
            int next;
            parse_name(res_buf, curr_pos, lower_qname, &next);
            curr_pos = next + 4;
        }

        int ancount = ntohs(rh->ancount);
        for (int i = 0; i < ancount; i++) {
            char owner[256];
            int next_pos;
            parse_name(res_buf, curr_pos, owner, &next_pos);
            curr_pos = next_pos;

            uint16_t type = (res_buf[curr_pos] << 8) | res_buf[curr_pos + 1];
            uint32_t ttl = (res_buf[curr_pos + 4] << 24) | (res_buf[curr_pos + 5] << 16) | (res_buf[curr_pos + 6] << 8) | res_buf[curr_pos + 7];
            uint16_t rdlen = (res_buf[curr_pos + 8] << 8) | res_buf[curr_pos + 9];
            curr_pos += 10;

            const char *tname = get_type_name(type);
            printf("  %s %u %s ", owner, ttl, tname ? tname : "TYPE");
            if (!tname) printf("%d ", type);

            if (type == 1) {
                printf("%d.%d.%d.%d\n", res_buf[curr_pos], res_buf[curr_pos + 1], res_buf[curr_pos + 2], res_buf[curr_pos + 3]);
            } else if (type == 28) {
                char ip6[INET6_ADDRSTRLEN];
                inet_ntop(AF_INET6, &res_buf[curr_pos], ip6, INET6_ADDRSTRLEN);
                printf("%s\n", ip6);
            } else if (type == 5) {
                char target[256];
                parse_name(res_buf, curr_pos, target, &dummy);
                printf("%s\n", target);
            } else if (type == 15) {
                uint16_t pref = (res_buf[curr_pos] << 8) | res_buf[curr_pos + 1];
                char exchange[256];
                parse_name(res_buf, curr_pos + 2, exchange, &dummy);
                printf("%u %s\n", pref, exchange);
            } else if (type == 16) {
                print_txt(res_buf, curr_pos, rdlen);
                printf("\n");
            } else {
                printf("# %d ", rdlen);
                for (int j = 0; j < rdlen; j++) printf("%02x", res_buf[curr_pos + j]);
                printf("\n");
            }
            curr_pos += rdlen;
        }
    }
    fclose(fp);
    return 0;
}

