typedef struct {
    uint16_t id;
    uint16_t flags;
    uint16_t qdcount;
    uint16_t ancount;
    uint16_t nscount;
    uint16_t arcount;
} DNSHeader;

uint16_t get_type_val(const char *type) {
    if (strcmp(type, "A") == 0) return 1;
    if (strcmp(type, "CNAME") == 0) return 5;
    if (strcmp(type, "MX") == 0) return 15;
    if (strcmp(type, "TXT") == 0) return 16;
    if (strcmp(type, "AAAA") == 0) return 28;
    return 0;
}

const char *get_type_name(uint16_t type) {
    if (type == 1) return "A";
    if (type == 5) return "CNAME";
    if (type == 15) return "MX";
    if (type == 16) return "TXT";
    if (type == 28) return "AAAA";
    return NULL;
}

const char *get_rcode_name(uint8_t rcode) {
    if (rcode == 0) return "NOERROR";
    if (rcode == 1) return "FORMERR";
    if (rcode == 2) return "SERVFAIL";
    if (rcode == 3) return "NXDOMAIN";
    if (rcode == 4) return "NOTIMP";
    if (rcode == 5) return "REFUSED";
    return NULL;
}

void dns_name_to_wire(const char *name, uint8_t *buf, int *pos) {
    int len = strlen(name);
    int end = len;
    if (end > 0 && name[end - 1] == '.') end--;
    int start = 0;
    while (start < end) {
        int dot = -1;
        for (int i = start; i < end; i++) {
            if (name[i] == '.') {
                dot = i;
                break;
            }
        }
        int label_len = (dot == -1) ? (end - start) : (dot - start);
        buf[(*pos)++] = (uint8_t)label_len;
        memcpy(&buf[*pos], &name[start], label_len);
        *pos += label_len;
        if (dot == -1) break;
        start = dot + 1;
    }
    buf[(*pos)++] = 0;
}

void parse_name(uint8_t *buf, int pos, char *out, int *next_pos) {
    int curr = pos;
    int written = 0;
    int jumped = 0;
    int jump_pos = 0;

    while (1) {
        uint8_t len = buf[curr];
        if ((len & 0xC0) == 0xC0) {
            if (!jumped) jump_pos = curr + 2;
            jumped = 1;
            curr = ((len & 0x3F) << 8) | buf[curr + 1];
        } else if (len == 0) {
            curr++;
            if (!jumped) jump_pos = curr;
            break;
        } else {
            curr++;
            if (written > 0) out[written++] = '.';
            for (int i = 0; i < len; i++) {
                out[written++] = (char)tolower(buf[curr++]);
            }
        }
    }
    out[written] = '\0';
    if (written == 0) {
        out[0] = '.';
        out[1] = '\0';
    }
    if (jumped) *next_pos = jump_pos;
    else *next_pos = curr;
}

void print_txt(uint8_t *buf, int pos, int len) {
    int curr = 0;
    while (curr < len) {
        uint8_t s_len = buf[pos + curr];
        curr++;
        printf("\"");
        for (int i = 0; i < s_len; i++) {
            uint8_t c = buf[pos + curr + i];
            if (c == '"') printf("\\\"");
            else if (c == '\\') printf("\\\\");
            else if (c >= 0x20 && c <= 0x7E) printf("%c", c);
            else printf("\\%03d", c);
        }
        printf("\"");
        curr += s_len;
        if (curr < len) printf(" ");
    }
}

