        uint16_t qtype = get_type_val(qtype_str);
        uint16_t id = (uint16_t)rand();
        uint8_t query[512];
        int pos = 0;

        DNSHeader *header = (DNSHeader *)query;
        header->id = htons(id);
        header->flags = htons(0x0100);
        header->qdcount = htons(1);
        header->ancount = htons(0);
        header->nscount = htons(0);
        header->arcount = htons(0);
        pos = 12;

        dns_name_to_wire(qname, query, &pos);
        uint16_t type_net = htons(qtype);
        uint16_t class_net = htons(1);
        memcpy(&query[pos], &type_net, 2);
        memcpy(&query[pos + 2], &class_net, 2);
        pos += 4;

        struct sockaddr_in server;
        memset(&server, 0, sizeof(server));
        server.sin_family = AF_INET;
        server.sin_port = htons(port);
        inet_pton(AF_INET, "127.0.0.1", &server.sin_addr);

        int udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
        sendto(udp_sock, query, pos, 0, (struct sockaddr *)&server, sizeof(server));

        uint8_t res_buf[8192];
        int res_len = 0;
        bool truncated = false;

        while (1) {
            int rec = recvfrom(udp_sock, res_buf, sizeof(res_buf), 0, NULL, NULL);
            if (rec < 12) continue;
            DNSHeader *res_h = (DNSHeader *)res_buf;
            if (ntohs(res_h->id) != id) continue;
            if (!(ntohs(res_h->flags) & 0x8000)) continue;
            res_len = rec;
            if (ntohs(res_h->flags) & 0x0200) truncated = true;
            break;
        }
        close(udp_sock);

        if (truncated) {
            int tcp_sock = socket(AF_INET, SOCK_STREAM, 0);
            connect(tcp_sock, (struct sockaddr *)&server, sizeof(server));
            uint16_t q_len = htons(pos);
            send(tcp_sock, &q_len, 2, 0);
            send(tcp_sock, query, pos, 0);
            uint16_t r_len_net;
            recv(tcp_sock, &r_len_net, 2, MSG_WAITALL);
            int r_len = ntohs(r_len_net);
            int total_rec = 0;
            while (total_rec < r_len) {
                int n = recv(tcp_sock, res_buf + total_rec, r_len - total_rec, 0);
                if (n <= 0) break;
                total_rec += n;
            }
            res_len = total_rec;
            close(tcp_sock);
        }

        DNSHeader *rh = (DNSHeader *)res_buf;
        uint8_t rcode = ntohs(rh->flags) & 0x000F;
        char qname_lower[256];
        int qlen = strlen(qname);
        if (qlen > 0 && qname[qlen - 1] == '.') qlen--;
        for (int i = 0; i < qlen; i++) qname_lower[i] = (char)tolower(qname[i]);
        qname_lower[qlen] = '\0';
        if (qlen == 0) { qname_lower[0] = '.'; qname_lower[1] = '\0'; }

        const char *rcode_name = get_rcode_name(rcode);
        if (rcode_name) printf("%s %s %s\n", qname_lower, qtype_str, rcode_name);
        else printf("%s %s RCODE%d\n", qname_lower, qtype_str, rcode);

        int curr_pos = 12;
        int qdcount = ntohs(rh->qdcount);
        for (int i = 0; i < qdcount; i++) {
            int next;
            char dummy[256];
            parse_name(res_buf, curr_pos, dummy, &next);
            curr_pos = next + 4;
        }

        int ancount = ntohs(rh->ancount);
        for (int i = 0; i < ancount; i++) {
            char owner[256];
            int next_pos;
            parse_name(res_buf, curr_pos, owner, &next_pos);
            curr_pos = next_pos;

            uint16_t type = (res_buf[curr_pos] << 8) | res_buf[curr_pos + 1];
            uint32_t ttl = (res_buf[curr_pos + 4] << 24) | (res_buf[curr_pos + 5] << 16) | (res_buf[curr_pos + 6] << 8) | res_buf[curr_pos + 7];
            uint16_t rdlen = (res_buf[curr_pos + 8] << 8) | res_buf[curr_pos + 9];
            curr_pos += 10;

            const char *tname = get_type_name(type);
            printf("  %s %u ", owner, ttl);
            if (tname) printf("%s ", tname);
            else printf("TYPE%d ", type);

            if (type == 1) {
                printf("%d.%d.%d.%d\n", res_buf[curr_pos], res_buf[curr_pos + 1], res_buf[curr_pos + 2], res_buf[curr_pos + 3]);
            } else if (type == 28) {
                char ip6[INET6_ADDRSTRLEN];
                inet_ntop(AF_INET6, &res_buf[curr_pos], ip6, INET6_ADDRSTRLEN);
                printf("%s\n", ip6);
            } else if (type == 5) {
                char target[256];
                int dummy;
                parse_name(res_buf, curr_pos, target, &dummy);
                printf("%s\n", target);
            } else if (type == 15) {
                uint16_t pref = (res_buf[curr_pos] << 8) | res_buf[curr_pos + 1];
                char exchange[256];
                int dummy;
                parse_name(res_buf, curr_pos + 2, exchange, &dummy);
                printf("%u %s\n", pref, exchange);
            } else if (type == 16) {
                print_txt(res_buf, curr_pos, rdlen);
                printf("\n");
            } else {
                printf("# %d ", rdlen);
                for (int j = 0; j < rdlen; j++) printf("%02x", res_buf[curr_pos + j]);
                printf("\n");
            }
            curr_pos += rdlen;
        }
    }
    fclose(fp);
    return 0;
}

use std::collections::{BTreeMap, HashMap};
use std::env;
use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct BigInt {
    negative: bool,
    digits: Vec<u64>, // Base 10^9
}

const BASE: u64 = 1_000_000_000;

impl BigInt {
    fn zero() -> Self {
        BigInt { negative: false, digits: vec![0] }
    }

    fn from_u64(mut n: u64) -> Self {
        if n == 0 { return Self::zero(); }
        let mut digits = Vec::new();
        while n > 0 {
            digits.push(n % BASE);
            n /= BASE;
        }
        BigInt { negative: false, digits }
    }

    fn from_str(s: &str) -> Self {
        let s = s.trim();
        if s.is_empty() { return Self::zero(); }
        let (negative, s) = if s.starts_with('-') {
            (true, &s[1..])
        } else {
            (false, s)
        };
        let mut digits = Vec::new();
        let mut i = s.len();
        while i > 0 {
            let start = if i >= 9 { i - 9 } else { 0 };
            digits.push(s[start..i].parse::<u64>().unwrap());
            i = start;
        }
        let mut res = BigInt { negative, digits };
        res.trim();
        res
    }

    fn trim(&mut self) {
        while self.digits.len() > 1 && self.digits.last() == Some(&0) {
            self.digits.pop();
        }
        if self.digits.is_empty() {
            self.digits.push(0);
        }
        if self.digits == [0] {
            self.negative = false;
        }
    }

    fn abs_compare(&self, other: &Self) -> std::cmp::Ordering {
        if self.digits.len() != other.digits.len() {
            return self.digits.len().cmp(&other.digits.len());
        }
        for i in (0..self.digits.len()).rev() {
            if self.digits[i] != other.digits[i] {
                return self.digits[i].cmp(&other.digits[i]);
            }
        }
        std::cmp::Ordering::Equal
    }

    fn add_abs(&self, other: &Self) -> Self {
        let mut res = Vec::new();
        let mut carry = 0;
        let mut i = 0;
        while i < self.digits.len() || i < other.digits.len() || carry > 0 {
            let mut sum = carry;
            if i < self.digits.len() { sum += self.digits[i]; }
            if i < other.digits.len() { sum += other.digits[i]; }
            res.push(sum % BASE);
            carry = sum / BASE;
            i += 1;
        }
        BigInt { negative: false, digits: res }
    }

    fn sub_abs(&self, other: &Self) -> Self {
        // Assumes self >= other
        let mut res = Vec::new();
        let mut borrow = 0;
        for i in 0..self.digits.len() {
            let mut diff = self.digits[i] as i64 - borrow as i64;
            if i < other.digits.len() { diff -= other.digits[i] as i64; }
            if diff < 0 {
                diff += BASE as i64;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.push(diff as u64);
        }
        let mut res_bi = BigInt { negative: false, digits: res };
        res_bi.trim();
        res_bi
    }

    fn add(&self, other: &Self) -> Self {
        if self.negative == other.negative {
            let mut res = self.add_abs(other);
            res.negative = self.negative;
            res.trim();
            res
        } else {
            match self.abs_compare(other) {
                std::cmp::Ordering::Equal => Self::zero(),
                std::cmp::Ordering::Greater => {
                    let mut res = self.sub_abs(other);
                    res.negative = self.negative;
                    res.trim();
                    res
                }
                std::cmp::Ordering::Less => {
                    let mut res = other.sub_abs(self);
                    res.negative = other.negative;
                    res.trim();
                    res
                }
            }
        }
    }

    fn sub(&self, other: &Self) -> Self {
        let mut other_neg = other.clone();
        other_neg.negative = !other.negative;
        self.add(&other_neg)
    }

    fn mul(&self, other: &Self) -> Self {
        let mut res_digits = vec![0u64; self.digits.len() + other.digits.len()];
        for i in 0..self.digits.len() {
            let mut carry = 0u128;
            for j in 0..other.digits.len() {
                let prod = res_digits[i + j] as u128 + (self.digits[i] as u128 * other.digits[j] as u128) + carry;
                res_digits[i + j] = (prod % BASE as u128) as u64;
                carry = prod / BASE as u128;
            }
            if carry > 0 {
                res_digits[i + other.digits.len()] += carry as u64;
            }
        }
        let mut res = BigInt { negative: self.negative ^ other.negative, digits: res_digits };
        res.trim();
        res
    }

    fn div_rem(&self, other: &Self) -> (Self, Self) {
        if other.digits == [0] { panic!("Division by zero"); }
        let mut q = Vec::new();
        let mut r = BigInt::zero();
        for i in (0..self.digits.len()).rev() {
            r = r.mul(&BigInt::from_u64(BASE)) ;
            r = r.add(&BigInt::from_u64(self.digits[i]));

            let mut low = 0u64;
            let mut high = BASE - 1;
            let mut best_q = 0u64;
            while low <= high {
                let mid = low + (high - low) / 2;
                let mid_bi = BigInt::from_u64(mid);
                let prod = mid_bi.mul(other);
                if prod.abs_compare(&r) != std::cmp::Ordering::Greater {
                    best_q = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            q.push(best_q);
            let best_q_bi = BigInt::from_u64(best_q);
            let prod = best_q_bi.mul(other);
            let mut prod_abs = prod.clone();
            prod_abs.negative = false;
            let mut r_abs = r.clone();
            r_abs.negative = false;
            r = r_abs.sub_abs(&prod_abs);
            r.negative = self.negative ^ other.negative;
            r.trim();
        }
        q.reverse();
        let mut q_bi = BigInt { negative: self.negative ^ other.negative, digits: q };
        q_bi.trim();
        (q_bi, r)
    }

    fn is_even(&self) -> bool {
        if self.digits.is_empty() { return true; }
        self.digits[0] % 2 == 0
    }

    fn to_string_formatted(&self, precision: u32) -> String {
        let mut s = String::new();
        if self.negative && !(self.digits == [0]) { s.push('-'); }

        let mut abs_val = self.clone();
        abs_val.negative = false;

        // To handle precision, we need to multiply by 10^precision
        let mut scaled = abs_val;
        for _ in 0..precision {
            scaled = scaled.mul(&BigInt::from_u64(10));
        }

        let (integer_part, fractional_part) = scaled.div_rem(&BigInt::from_u64(10).pow(precision));

        // Format integer part with commas
        let mut int_s = String::new();
        let mut temp_int = integer_part.clone();
        if temp_int.digits == [0] {
            int_s.push('0');
        } else {
            while !(temp_int.digits == [0]) {
                let (q, r) = temp_int.div_rem(&BigInt::from_u64(10));
                int_s.push(std::char::from_digit(r.digits[0] as u32, 10).unwrap());
                temp_int = q;
            }
        }

        let mut formatted_int = String::new();
        let bytes = int_s.as_bytes();
        for i in 0..bytes.len() {
            formatted_int.push(bytes[bytes.len() - 1 - i] as char);
            if i > 0 && i % 3 == 0 && i < bytes.len() {
                formatted_int.insert(formatted_int.len() - (i % 3), ','); // This is wrong
            }
        }
        // Correct comma logic:
        let mut final_int = String::new();
        let mut count = 0;
        for i in (0..int_s.len()).rev() {
            if count > 0 && count % 3 == 0 { final_int.push(','); }
            final_int.push(int_s.as_bytes()[i] as char);
            count += 1;
        }
        s.push_str(&final_int);

        if precision > 0 {
            s.push('.');
            let mut frac_s = String::new();
            let mut f = fractional_part;
            for _ in 0..precision {
                let (q, r) = f.div_rem(&BigInt::from_u64(10));
                frac_s.push(std::char::from_digit(r.digits[0] as u32, 10).unwrap());
                f = q;
            }
            frac_s.chars().rev().for_each(|c| s.push(c));
        }
        s
    }

    fn pow(&self, exp: u32) -> Self {
        let mut res = BigInt::from_u64(1);
        let mut base = self.clone();
        let mut e = exp;
        while e > 0 {
            if e % 2 == 1 { res = res.mul(&base); }
            base = base.mul(&base);
            e /= 2;
        }
        res
    }
}

impl std::fmt::Display for BigInt {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.negative && !(self.digits == [0]) { f.write_str("-")?; }
        let mut res = String::new();
        let mut temp = self.clone();
        temp.negative = false;
        if temp.digits == [0] {
            res.push('0');
        } else {
            while !(temp.digits == [0]) {
                let (q, r) = temp.div_rem(&BigInt::from_u64(10));
                res.push(std::char::from_digit(r.digits[0] as u32, 10).unwrap());
                temp = q;
            }
        }
        let mut final_res = String::new();
        let mut count = 0;
        for i in (0..res.len()).rev() {
            if count > 0 && count % 3 == 0 { final_res.push(','); }
            final_res.push(res.as_bytes()[i] as char);
            count += 1;
        }
        f.write_str(&final_res)
    }
}

struct Fraction {
    num: BigInt,
    den: BigInt,
}

impl Fraction {
    fn from_str(s: &str) -> Self {
        let s = s.trim();
        if let Some(pos) = s.find('.') {
            let integer_part = &s[..pos];
            let fractional_part = &s[pos + 1..];
            let mut num = BigInt::from_str(integer_part);
            let den = BigInt::from_u64(10).pow(fractional_part.len() as u32);

            // num = num * den + fractional_part
            let mut num_scaled = num.mul(&den);
            let mut frac_val = BigInt::from_str(fractional_part);
            if num_scaled.negative {
                num_scaled = num_scaled.sub(&frac_val);
            } else {
                num_scaled = num_scaled.add(&frac_val);
            }
            Fraction { num: num_scaled, den }
        } else {
            Fraction { num: BigInt::from_str(s), den: BigInt::from_u64(1) }
        }
    }

    fn round_half_even(&self, precision: u32) -> BigInt {
        let mut n_prime = self.num.clone();
        n_prime = n_prime.mul(&BigInt::from_u64(10).pow(precision));
        let (q, r) = n_prime.div_rem(&self.den);

        if r.digits == [0] { return q; }

        let mut r_abs = r.clone(); r_abs.negative = false;
        let mut d_abs = self.den.clone(); d_abs.negative = false;

        let two_r_abs = r_abs.mul(&BigInt::from_u64(2));
        match two_r_abs.abs_compare(&d_abs) {
            std::cmp::Ordering::Less => q,
            std::cmp::Ordering::Greater => {
                let mut res = q.clone();
                if r.negative { res = res.sub(&BigInt::from_u64(1)); }
                else { res = res.add(&BigInt::from_u64(1)); }
                res
            }
            std::cmp::Ordering::Equal => {
                if q.is_even() { q } else {
                    let mut res = q.clone();
                    if r.negative { res = res.sub(&BigInt::from_u64(1)); }
                    else { res = res.add(&BigInt::from_u64(1)); }
                    res
                }
            }
        }
    }
}

struct Account {
    name: String,
    currency: String,
    balance: BigInt,
    limit: BigInt,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = Path::new(dir).join("ledger.txt");
    let file = File::open(path).expect("Could not open ledger.txt");
    let reader = io::BufReader::new(file);

    let mut currencies: HashMap<String, u32> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections = Vec::new();

    for (line_idx, line_res) in reader.lines().enumerate() {
        let line = line_res.unwrap();
        let line_num = line_idx + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }

        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.is_empty() { continue; }

        match parts[0] {
            "currency" => {
                let code = parts[1].to_string();
                let minor_units = parts[2].parse::<u32>().unwrap();
                currencies.insert(code, minor_units);
            }
            "open" => {
                let acc_name = parts[1].to_string();
                let code = parts[2].to_string();
                let minor_units = *currencies.get(&code).unwrap();
                let limit_val = if parts.len() > 3 {
                    Fraction::from_str(parts[3]).round_half_even(minor_units)
                } else {
                    BigInt::zero()
                };
                if accounts.contains_key(&acc_name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, acc_name));
                } else {
                    accounts.insert(acc_name.clone(), Account { name: acc_name, currency: code, balance: BigInt::zero(), limit: limit_val });
                }
            }
            "deposit" | "withdraw" | "transfer" | "convert" | "split" => {
                let mut rounded_amount = BigInt::zero();
                let mut rejected = false;
                let mut rejection_msg = String::new();

                // 1. Unknown account
                let mut acc_names_in_cmd = Vec::new();
                if parts[0] == "deposit" || parts[0] == "withdraw" {
                    acc_names_in_cmd.push(parts[1]);
                } else if parts[0] == "transfer" {
                    acc_names_in_cmd.push(parts[1]);
                    acc_names_in_cmd.push(parts[2]);
                } else if parts[0] == "convert" {
                    acc_names_in_cmd.push(parts[1]);
                    acc_names_in_cmd.push(parts[2]);
                } else if parts[0] == "split" {
                    acc_names_in_cmd.push(parts[1]);
                    for p in &parts[3..] {
                        if let Some(pos) = p.find(':') {
                            acc_names_in_cmd.push(&p[..pos]);
                        }
                    }
                }
                for name in &acc_names_in_cmd {
                    if !accounts.contains_key(*name) {
                        rejection_msg = format!("unknown account {}", name);
                        rejected = true;
                        break;
                    }
                }

                if !rejected {
                    let from_acc_name = match parts[0] {
                        "deposit" | "withdraw" => parts[1],
                        "transfer" | "convert" | "split" => parts[1],
                        _ => unreachable!(),
                    };
                    let from_curr = accounts.get(from_acc_name).unwrap().currency.clone();
                    let minor_units = *currencies.get(&from_curr).unwrap();

                    let amount_str = match parts[0] {
                        "deposit" | "withdraw" => parts[2],
                        "transfer" | "convert" | "split" => parts[3],
                        _ => unreachable!(),
                    };
                    rounded_amount = Fraction::from_str(amount_str).round_half_even(minor_units);

                    // 2. Currency mismatch
                    if parts[0] == "transfer" {
                        let to_curr = accounts.get(parts[3]).unwrap().currency.clone();
                        if from_curr != to_curr {
                            rejection_msg = "currency mismatch".to_string();
                            rejected = true;
                        }
                    } else if parts[0] == "split" {
                        for p in &parts[3..] {
                            if let Some(pos) = p.find(':') {
                                let to_name = &p[..pos];
                                let to_curr = accounts.get(to_name).unwrap().currency.clone();
                                if from_curr != to_curr {
                                    rejection_msg = "currency mismatch".to_string();
                                    rejected = true;
                                    break;
                                }
                            }
                        }
                    }

                    // 3. Non-positive amount
                    if !rejected && (rounded_amount.negative || rounded_amount.digits == [0]) {
                        rejection_msg = "non-positive amount".to_string();
                        rejected = true;
                    }

                    // 4. Insufficient funds
                    if !rejected {
                        let is_withdrawal = match parts[0] {
                            "deposit" => false,
                            "withdraw" | "transfer" | "convert" | "split" => true,
                            _ => false,
                        };
                        if is_withdrawal {
                            let acc = accounts.get(from_acc_name).unwrap();
                            let mut balance_scaled = acc.balance.clone();
                            let mut limit_scaled = acc.limit.clone();
                            limit_scaled.negative = false;

                            // balance - rounded_amount < -limit => balance + limit < rounded_amount
                            let mut combined = balance_scaled.clone();
                            combined = combined.add(&limit_scaled);
                            if combined.abs_compare(&rounded_amount) == std::cmp::Ordering::Less && !combined.negative {
                                rejection_msg = format!("insufficient funds {}", from_acc_name);
                                rejected = true;
                            } else if combined.negative && combined.abs_compare(&rounded_amount) != std::cmp::Ordering::Greater {
                                // If balance+limit is negative, and rounded_amount is positive, it's always insufficient
                                rejection_msg = format!("insufficient funds {}", from_acc_name);
                                rejected = true;
                            }
                        }
                    }
                }

                if rejected {
                    rejections.push(format!("line {}: REJECT {}", line_num, rejection_msg));
                } else {
                    // Execute command
                    match parts[0] {
                        "deposit" => {
                            let acc = accounts.get_mut(parts[1]).unwrap();
                            acc.balance = acc.balance.add(&rounded_amount);
                        }
                        "withdraw" => {
                            let acc = accounts.get_mut(parts[1]).unwrap();
                            let mut neg_amount = rounded_amount.clone();
                            neg_amount.negative = true;
                            acc.balance = acc.balance.add(&neg_amount);
                        }
                        "transfer" => {
                            let from_name = parts[1].to_string();
                            let to_name = parts[2].to_string();
                            let mut neg_amount = rounded_amount.clone();
                            neg_amount.negative = true;
                            accounts.get_mut(&from_name).unwrap().balance = accounts.get(&from_name).unwrap().balance.clone().add(&neg_amount);
                            accounts.get_mut(&to_name).unwrap().balance = accounts.get(&to_name).unwrap().balance.clone().add(&rounded_amount);
                        }
                        "convert" => {
                            let from_name = parts[2].to_string();
                            let to_name = parts[3].to_string();
                            let amount_str = parts[4];
                            let rate_str = parts[5];

                            let from_curr = accounts.get(&from_name).unwrap().currency.clone();
                            let to_curr = accounts.get(&to_name).unwrap().currency.clone();
                            let from_minor = *currencies.get(&from_curr).unwrap();
                            let to_minor = *currencies.get(&to_curr).unwrap();

                            let rounded_from = Fraction::from_str(amount_str).round_half_even(from_minor);
                            let mut neg_rounded_from = rounded_from.clone();
                            neg_rounded_from.negative = true;
                            accounts.get_mut(&from_name).unwrap().balance = accounts.get(&from_name).unwrap().balance.clone().add(&neg_rounded_from);

                            let rate = Fraction::from_str(rate_str);
                            let mut num = rounded_from.mul(&rate.num);
                            num = num.mul(&BigInt::from_u64(10).pow(to_minor));
                            let mut den = rate.den.clone();
                            den = den.mul(&BigInt::from_u64(10).pow(from_minor));

                            let rounded_to = Fraction { num, den }.round_half_even(0);
                            accounts.get_mut(&to_name).unwrap().balance = accounts.get(&to_name).unwrap().balance.clone().add(&rounded_to);
                        }
                        "split" => {
                            let from_name = parts[1].to_string();
                            let amount_str = parts[2];
                            let from_curr = accounts.get(&from_name).unwrap().currency.clone();
                            let from_minor = *currencies.get(&from_curr).unwrap();
                            let a = Fraction::from_str(amount_str).round_half_even(from_minor);

                            let mut neg_a = a.clone();
                            neg_a.negative = true;
                            accounts.get_mut(&from_name).unwrap().balance = accounts.get(&from_name).unwrap().balance.clone().add(&neg_a);

                            let mut weights = Vec::new();
                            let mut total_w = BigInt::zero();
                            for p in &parts[3..] {
                                if let Some(pos) = p.find(':') {
                                    let w = BigInt::from_str(&p[pos+1..]);
                                    weights.push((p[..pos].to_string(), w.clone()));
                                    total_w = total_w.add(&w);
                                }
                            }

                            let mut target_shares = Vec::new();
                            let mut sum_q = BigInt::zero();
                            for (name, w) in &weights {
                                let prod = a.mul(w);
                                let (q, r) = prod.div_rem(&total_w);
                                target_shares.push((name.clone(), q, r));
                                sum_q = sum_q.add(&target_shares.last().unwrap().1);
                            }

                            let mut rem = a.sub(&sum_q);
                            let mut rem_count = 0;
                            if !rem.negative && !(rem.digits == [0]) {
                                let mut rem_val = rem.clone();
                                while !rem_val.digits.is_empty() {
                                    let (q, r) = rem_val.div_rem(&BigInt::from_u64(10));
                                    rem_val = q;
                                    // This is slow but okay for small rem
                                }
                            }
                            // Correct way to get rem_count:
                            let mut rem_count_bi = rem.clone();
                            let mut rem_count_u64 = 0u64;
                            let mut temp_rem = rem_count_bi.clone();
                            while !(temp_rem.digits == [0]) {
                                let (q, r) = temp_rem.div_rem(&BigInt::from_u64(10));
                                rem_count_u64 = rem_count_u64 * 10 + r.digits[0];
                                temp_rem = q;
                            }

                            let mut sorted_targets: Vec<usize> = (0..target_shares.len()).collect();
                            sorted_targets.sort_by(|&i, &j| {
                                target_shares[j].2.abs_compare(&target_shares[i].2)
                            });

                            for i in 0..rem_count_u64 as usize {
                                let target_idx = sorted_targets[i];
                                let name = &target_shares[target_idx].0;
                                accounts.get_mut(name).unwrap().balance = accounts.get(name).unwrap().balance.clone().add(&BigInt::from_u64(1));
                            }

                            for (name, q, _) in target_shares {
                                accounts.get_mut(&name).unwrap().balance = accounts.get(&name).unwrap().balance.clone().add(&q);
                            }
                        }
                        _ => unreachable!(),
                    }
                }
            }
            "interest" => {
                let acc_name = parts[1].to_string();
                let rate_str = parts[2];
                let rate = Fraction::from_str(rate_str);

                let acc = accounts.get(&acc_name).unwrap();
                let balance = acc.balance.clone();
                let mut num = balance.mul(&rate.num);
                let den = rate.den.clone();
                let interest = Fraction { num, den }.round_half_even(0);

                // Check insufficient funds if interest is negative
                if interest.negative {
                    let mut combined = acc.balance.clone();
                    let mut limit_scaled = accounts.get(&acc_name).unwrap().limit.clone();
                    limit_scaled.negative = false;
                    combined = combined.add(&limit_scaled);

                    let mut abs_interest = interest.clone();
                    abs_interest.negative = false;
                    if combined.abs_compare(&abs_interest) == std::cmp::Ordering::Less && !combined.negative {
                        rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, acc_name));
                        continue;
                    } else if combined.negative && combined.abs_compare(&abs_interest) != std::cmp::Ordering::Greater {
                        rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, acc_name));
                        continue;
                    }
                }

                accounts.get_mut(&acc_name).unwrap().balance = accounts.get(&acc_name).unwrap().balance.clone().add(&interest);
            }
            _ => {}
        }
    }

    for rej in rejections { println!("{}", rej); }
    println!();

    let mut sorted_accs: Vec<_> = accounts.keys().collect();
    sorted_accs.sort();
    for name in sorted_accs {
        let acc = &accounts[name];
        let minor_units = *currencies.get(&acc.currency).unwrap();
        println!("{} {} {}", acc.name, acc.currency, acc.balance.to_string_formatted(minor_units));
    }
    println!();

    let mut curr_totals: BTreeMap<String, (BigInt, usize)> = BTreeMap::new();
    for acc in accounts.values() {
        let entry = curr_totals.entry(acc.currency.clone()).or_insert((BigInt::zero(), 0));
        entry.0 = entry.0.add(&acc.balance);
        entry.1 += 1;
    }
    for (code, (total, count)) in curr_totals {
        let minor_units = *currencies.get(&code).unwrap();
        println!("total {} {} ({} accounts)", code, total.to_string_formatted(minor_units), count);
    }
}

use std::collections::{BTreeMap, HashMap};
use std::env;
use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct BigInt {
    negative: bool,
    digits: Vec<u64>,
}

const BASE: u64 = 1_000_000_000;

impl BigInt {
    fn zero() -> Self {
        BigInt { negative: false, digits: vec![0] }
    }

    fn from_u64(mut n: u64) -> Self {
        if n == 0 { return Self::zero(); }
        let mut digits = Vec::new();
        while n > 0 {
            digits.push(n % BASE);
            n /= BASE;
        }
        BigInt { negative: false, digits }
    }

    fn from_str(s: &str) -> Self {
        let s = s.trim();
        if s.is_empty() { return Self::zero(); }
        let (negative, s) = if s.starts_with('-') {
            (true, &s[1..])
        } else {
            (false, s)
        };
        let mut digits = Vec::new();
        let mut i = s.len();
        while i > 0 {
            let start = if i >= 9 { i - 9 } else { 0 };
            digits.push(s[start..i].parse::<u64>().unwrap());
            i = start;
        }
        let mut res = BigInt { negative, digits };
        res.trim();
        res
    }

    fn trim(&mut self) {
        while self.digits.len() > 1 && self.digits.last() == Some(&0) {
            self.digits.pop();
        }
        if self.digits.is_empty() {
            self.digits.push(0);
        }
        if self.digits == [0] {
            self.negative = false;
        }
    }

    fn abs_compare(&self, other: &Self) -> std::cmp::Ordering {
        if self.digits.len() != other.digits.len() {
            return self.digits.len().cmp(&other.digits.len());
        }
        for i in (0..self.digits.len()).rev() {
            if self.digits[i] != other.digits[i] {
                return self.digits[i].cmp(&other.digits[i]);
            }
        }
        std::cmp::Ordering::Equal
    }

    fn add_abs(&self, other: &Self) -> Self {
        let mut res = Vec::new();
        let mut carry = 0;
        let mut i = 0;
        while i < self.digits.len() || i < other.digits.len() || carry > 0 {
            let mut sum = carry;
            if i < self.digits.len() { sum += self.digits[i]; }
            if i < other.digits.len() { sum += other.digits[i]; }
            res.push(sum % BASE);
            carry = sum / BASE;
            i += 1;
        }
        BigInt { negative: false, digits: res }
    }

    fn sub_abs(&self, other: &Self) -> Self {
        let mut res = Vec::new();
        let mut borrow = 0;
        for i in 0..self.digits.len() {
            let mut diff = self.digits[i] as i64 - borrow as i64;
            if i < other.digits.len() { diff -= other.digits[i] as i64; }
            if diff < 0 {
                diff += BASE as i64;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.push(diff as u64);
        }
        let mut res_bi = BigInt { negative: false, digits: res };
        res_bi.trim();
        res_bi
    }

    fn add(&self, other: &Self) -> Self {
        if self.negative == other.negative {
            let mut res = self.add_abs(other);
            res.negative = self.negative;
            res.trim();
            res
        } else {
            match self.abs_compare(other) {
                std::cmp::Ordering::Equal => Self::zero(),
                std::cmp::Ordering::Greater => {
                    let mut res = self.sub_abs(other);
                    res.negative = self.negative;
                    res.trim();
                    res
                }
                std::cmp::Ordering::Less => {
                    let mut res = other.sub_abs(self);
                    res.negative = other.negative;
                    res.trim();
                    res
                }
            }
        }
    }

    fn sub(&self, other: &Self) -> Self {
        let mut other_neg = other.clone();
        other_neg.negative = !other.negative;
        self.add(&other_neg)
    }

    fn mul(&self, other: &Self) -> Self {
        let mut res_digits = vec![0u64; self.digits.len() + other.digits.len()];
        for i in 0..self.digits.len() {
            let mut carry = 0u128;
            for j in 0..other.digits.len() {
                let prod = res_digits[i + j] as u128 + (self.digits[i] as u128 * other.digits[j] as u128) + carry;
                res_digits[i + j] = (prod % BASE as u128) as u64;
                carry = prod / BASE as u128;
            }
            if carry > 0 {
                res_digits[i + other.digits.len()] += carry as u64;
            }
        }
        let mut res = BigInt { negative: self.negative ^ other.negative, digits: res_digits };
        res.trim();
        res
    }

    fn div_rem(&self, other: &Self) -> (Self, Self) {
        if other.digits == [0] { panic!("Division by zero"); }
        let mut q = Vec::new();
        let mut r = BigInt::zero();
        for i in (0..self.digits.len()).rev() {
            r = r.mul(&BigInt::from_u64(BASE));
            r = r.add(&BigInt::from_u64(self.digits[i]));
            let mut low = 0u64;
            let mut high = BASE - 1;
            let mut best_q = 0u64;
            while low <= high {
                let mid = low + (high - low) / 2;
                let mid_bi = BigInt::from_u64(mid);
                let prod = mid_bi.mul(other);
                if prod.abs_compare(&r) != std::cmp::Ordering::Greater {
                    best_q = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            q.push(best_q);
            let best_q_bi = BigInt::from_u64(best_q);
            let prod = best_q_bi.mul(other);
            let mut prod_abs = prod.clone();
            prod_abs.negative = false;
            let mut r_abs = r.clone();
            r_abs.negative = false;
            r = r_abs.sub_abs(&prod_abs);
            r.negative = self.negative ^ other.negative;
            r.trim();
        }
        q.reverse();
        let mut q_bi = BigInt { negative: self.negative ^ other.negative, digits: q };
        q_bi.trim();
        (q_bi, r)
    }

    fn is_even(&self) -> bool {
        if self.digits.is_empty() { return true; }
        self.digits[0] % 2 == 0
    }

    fn pow(&self, exp: u32) -> Self {
        let mut res = BigInt::from_u64(1);
        let mut base = self.clone();
        let mut e = exp;
        while e > 0 {
            if e % 2 == 1 { res = res.mul(&base); }
            base = base.mul(&base);
            e /= 2;
        }
        res
    }

    fn to_string_formatted(&self, precision: u32) -> String {
        let mut s = String::new();
        if self.negative && !(self.digits == [0]) { s.push('-'); }
        let mut abs_val = self.clone();
        abs_val.negative = false;
        let mut scaled = abs_val;
        for _ in 0..precision { scaled = scaled.mul(&BigInt::from_u64(10)); }
        let (integer_part, fractional_part) = scaled.div_rem(&BigInt::from_u64(10).pow(precision));
        let mut int_s = String::new();
        let mut temp_int = integer_part.clone();
        temp_int.negative = false;
        if temp_int.digits == [0] {
            int_s.push('0');
        } else {
            while !(temp_int.digits == [0]) {
                let (q, r) = temp_int.div_rem(&BigInt::from_u64(10));
                int_s.push(std::char::from_digit(r.digits[0] as u32, 10).unwrap());
                temp_int = q;
            }
        }
        let mut formatted_int = String::new();
        let mut count = 0;
        for i in (0..int_s.len()).rev() {
            if count > 0 && count % 3 == 0 { formatted_int.push(','); }
            formatted_int.push(int_s.as_bytes()[i] as char);
            count += 1;
        }
        s.push_str(&formatted_int);
        if precision > 0 {
            s.push('.');
            let mut frac_s = String::new();
            let mut f = fractional_part;
            f.negative = false;
            for _ in 0..precision {
                let (q, r) = f.div_rem(&BigInt::from_u64(10));
                frac_s.push(std::char::from_digit(r.digits[0] as u32, 10).unwrap());
                f = q;
            }
            frac_s.chars().rev().for_each(|c| s.push(c));
        }
        s
    }
}

struct Fraction {
    num: BigInt,
    den: BigInt,
}

impl Fraction {
    fn from_str(s: &str) -> Self {
        let s = s.trim();
        if let Some(pos) = s.find('.') {
            let integer_part = &s[..pos];
            let fractional_part = &s[pos + 1..];
            let mut num = BigInt::from_str(integer_part);
            let den = BigInt::from_u64(10).pow(fractional_part.len() as u32);
            let mut num_scaled = num.mul(&den);
            let mut frac_val = BigInt::from_str(fractional_part);
            if num_scaled.negative {
                num_scaled = num_scaled.sub(&frac_val);
            } else {
                num_scaled = num_scaled.add(&frac_val);
            }
            Fraction { num: num_scaled, den }
        } else {
            Fraction { num: BigInt::from_str(s), den: BigInt::from_u64(1) }
        }
    }

    fn round_half_even(&self, precision: u32) -> BigInt {
        let mut n_prime = self.num.clone();
        n_prime = n_prime.mul(&BigInt::from_u64(10).pow(precision));
        let (q, r) = n_prime.div_rem(&self.den);
        if r.digits == [0] { return q; }
        let mut r_abs = r.clone(); r_abs.negative = false;
        let mut d_abs = self.den.clone(); d_abs.negative = false;
        let two_r_abs = r_abs.mul(&BigInt::from_u64(2));
        match two_r_abs.abs_compare(&d_abs) {
            std::cmp::Ordering::Less => q,
            std::cmp::Ordering::Greater => {
                let mut res = q.clone();
                if r.negative { res = res.sub(&BigInt::from_u64(1)); }
                else { res = res.add(&BigInt::from_u64(1)); }
                res
            }
            std::cmp::Ordering::Equal => {
                if q.is_even() { q } else {
                    let mut res = q.clone();
                    if r.negative { res = res.sub(&BigInt::from_u64(1)); }
                    else { res = res.add(&BigInt::from_u64(1)); }
                    res
                }
            }
        }
    }
}

struct Account {
    name: String,
    currency: String,
    balance: BigInt,
    limit: BigInt,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = Path::new(dir).join("ledger.txt");
    let file = File::open(path).expect("Could not open ledger.txt");
    let reader = io::BufReader::new(file);

    let mut currencies: HashMap<String, u32> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections = Vec::new();

    for (line_idx, line_res) in reader.lines().enumerate() {
        let line = line_res.unwrap();
        let line_num = line_idx + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.is_empty() { continue; }

        match parts[0] {
            "currency" => {
                let code = parts[1].to_string();
                let minor_units = parts[2].parse::<u32>().unwrap();
                currencies.insert(code, minor_units);
            }
            "open" => {
                let acc_name = parts[1].to_string();
                let code = parts[2].to_string();
                let minor_units = *currencies.get(&code).unwrap();
                let limit_val = if parts.len() > 3 {
                    Fraction::from_str(parts[3]).round_half_even(minor_units)
                } else {
                    BigInt::zero()
                };
                if accounts.contains_key(&acc_name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, acc_name));
                } else {
                    accounts.insert(acc_name.clone(), Account { name: acc_name, currency: code, balance: BigInt::zero(), limit: limit_val });
                }
            }
            "deposit" | "withdraw" | "transfer" | "convert" | "split" => {
                let mut rounded_amount = BigInt::zero();
                let mut rejected = false;
                let mut rejection_msg = String::new();
                let mut acc_names_in_cmd = Vec::new();
                if parts[0] == "deposit" || parts[0] == "withdraw" {
                    acc_names_in_cmd.push(parts[1]);
                } else if parts[0] == "transfer" {
                    acc_names_in_cmd.push(parts[1]);
                    acc_names_in_cmd.push(parts[2]);
                } else if parts[0] == "convert" {
                    acc_names_in_cmd.push(parts[1]);
                    acc_names_in_cmd.push(parts[2]);
                } else if parts[0] == "split" {
                    acc_names_in_cmd.push(parts[1]);
                    for p in &parts[3..] {
                        if let Some(pos) = p.find(':') { acc_names_in_cmd.push(&p[..pos]); }
                    }
                }
                for name in &acc_names_in_cmd {
                    if !accounts.contains_key(*name) {
                        rejection_msg = format!("unknown account {}", name);
                        rejected = true;
                        break;
                    }
                }
                if !rejected {
                    let from_acc_name = match parts[0] {
                        "deposit" | "withdraw" | "transfer" | "convert" | "split" => parts[1],
                        _ => unreachable!(),
                    };
                    let from_curr = accounts.get(from_acc_name).unwrap().currency.clone();
                    let minor_units = *currencies.get(&from_curr).unwrap();
                    let amount_str = match parts[0] {
                        "deposit" | "withdraw" => parts[2],
                        "transfer" | "convert" | "split" => parts[3],
                        _ => unreachable!(),
                    };
                    rounded_amount = Fraction::from_str(amount_str).round_half_even(minor_units);
                    if parts[0] == "transfer" {
                        let to_curr = accounts.get(parts[3]).unwrap().currency.clone();
                        if from_curr != to_curr {
                            rejection_msg = "currency mismatch".to_string();
                            rejected = true;
                        }
                    } else if parts[0] == "split" {
                        for p in &parts[3..] {
                            if let Some(pos) = p.find(':') {
                                let to_curr = accounts.get(&p[..pos]).unwrap().currency.clone();
                                if from_curr != to_curr {
                                    rejection_msg = "currency mismatch".to_string();
                                    rejected = true;
                                    break;
                                }
                            }
                        }
                    }
                    if !rejected && (rounded_amount.negative || rounded_amount.digits == [0]) {
                        rejection_msg = "non-positive amount".to_string();
                        rejected = true;
                    }
                    if !rejected {
                        let is_withdrawal = match parts[0] {
                            "deposit" => false,
                            "withdraw" | "transfer" | "convert" | "split" => true,
                            _ => false,
                        };
                        if is_withdrawal {
                            let acc = accounts.get(from_acc_name).unwrap();
                            let mut limit_scaled = acc.limit.clone();
                            limit_scaled.negative = false;
                            let mut combined = acc.balance.clone();
                            combined = combined.add(&limit_scaled);
                            if combined.negative || combined.abs_compare(&rounded_amount) == std::cmp::Ordering::Less {
                                rejection_msg = format!("insufficient funds {}", from_acc_name);
                                rejected = true;
                            }
                        }
                    }
                }
                if rejected {
                    rejections.push(format!("line {}: REJECT {}", line_num, rejection_msg));
                } else {
                    match parts[0] {
                        "deposit" => {
                            let acc = accounts.get_mut(parts[1]).unwrap();
                            acc.balance = acc.balance.add(&rounded_amount);
                        }
                        "withdraw" => {
                            let acc = accounts.get_mut(parts[1]).unwrap();
                            let mut neg_amount = rounded_amount.clone();
                            neg_amount.negative = true;
                            acc.balance = acc.balance.add(&neg_amount);
                        }
                        "transfer" => {
                            let from_name = parts[1].to_string();
                            let to_name = parts[2].to_string();
                            let mut neg_amount = rounded_amount.clone();
                            neg_amount.negative = true;
                            let from_bal = accounts.get(&from_name).unwrap().balance.clone();
                            accounts.get_mut(&from_name).unwrap().balance = from_bal.add(&neg_amount);
                            let to_bal = accounts.get(&to_name).unwrap().balance.clone();
                            accounts.get_mut(&to_name).unwrap().balance = to_bal.add(&rounded_amount);
                        }
                        "convert" => {
                            let from_name = parts[1].to_string();
                            let to_name = parts[2].to_string();
                            let amount_str = parts[3];
                            let rate_str = parts[4];
                            let from_curr = accounts.get(&from_name).unwrap().currency.clone();
                            let to_curr = accounts.get(&to_name).unwrap().currency.clone();
                            let from_minor = *currencies.get(&from_curr).unwrap();
                            let to_minor = *currencies.get(&to_curr).unwrap();
                            let rounded_from = Fraction::from_str(amount_str).round_half_even(from_minor);
                            let mut neg_rounded_from = rounded_from.clone();
                            neg_rounded_from.negative = true;
                            let from_bal = accounts.get(&from_name).unwrap().balance.clone();
                            accounts.get_mut(&from_name).unwrap().balance = from_bal.add(&neg_rounded_from);
