} BigInt;

BigInt bi_zero() { return (BigInt){.len = 1, .d = {0}, .sign = 0}; }
BigInt bi_one() { return (BigInt){.len = 1, .d = {1}, .sign = 1}; }

int bi_cmp(BigInt a, BigInt b) {
    if (a.sign != b.sign) return a.sign - b.sign;
    if (a.sign == 0) return 0;
    int res = 0;
    if (a.len > b.len) res = a.sign;
    else if (a.len < b.len) res = -a.sign;
    else {
        for (int i = a.len - 1; i >= 0; i--) {
            if (a.d[i] > b.d[i]) { res = a.sign; break; }
            if (a.d[i] < b.d[i]) { res = -a.sign; break; }
        }
    }
    return res;
}

BigInt bi_add_abs(BigInt a, BigInt b) {
    BigInt res = {0};
    int64_t carry = 0;
    int max_len = a.len > b.len ? a.len : b.len;
    for (int i = 0; i < max_len || carry; i++) {
        int64_t sum = carry + (i < a.len ? a.d[i] : 0) + (i < b.len ? b.d[i] : 0);
        res.d[res.len++] = sum % 1000000000LL;
        carry = sum / 1000000000LL;
    }
    return res;
}

BigInt bi_sub_abs(BigInt a, BigInt b) {
    BigInt res = {0};
    int64_t borrow = 0;
    for (int i = 0; i < a.len; i++) {
        int64_t diff = a.d[i] - borrow - (i < b.len ? b.d[i] : 0);
        if (diff < 0) { diff += 1000000000LL; borrow = 1; }
        else borrow = 0;
        res.d[res.len++] = diff;
    }
    while (res.len > 0 && res.d[res.len - 1] == 0) res.len--;
    return res;
}

BigInt bi_add(BigInt a, BigInt b) {
    if (a.sign == 0) { BigInt res = b; res.sign = b.sign; return res; }
    if (b.sign == 0) { BigInt res = a; res.sign = a.sign; return res; }
    if (a.sign == b.sign) {
        BigInt res = bi_add_abs(a, b);
        res.sign = a.sign;
        return res;
    }
    if (bi_cmp(a, a) == 0) return bi_zero(); // Not possible here
    int cmp = 0;
    BigInt abs_a = a; abs_a.sign = 1;
    BigInt abs_b = b; abs_b.sign = 1;
    if (abs_a.len > abs_b.len) cmp = 1;
    else if (abs_a.len < abs_b.len) cmp = -1;
    else {
        for (int i = a.len - 1; i >= 0; i--) {
            if (a.d[i] > b.d[i]) { cmp = 1; break; }
            if (a.d[i] < b.d[i]) { cmp = -1; break; }
        }
    }
    if (cmp == 0) return bi_zero();
    if (cmp > 0) {
        BigInt res = bi_sub_abs(abs_a, abs_b);
        res.sign = a.sign;
        return res;
    } else {
        BigInt res = bi_sub_abs(abs_b, abs_a);
        res.sign = b.sign;
        return res;
    }
}

BigInt bi_sub(BigInt a, BigInt b) {
    BigInt nb = b; nb.sign = -b.sign;
    return bi_add(a, nb);
}

BigInt bi_mul(BigInt a, BigInt b) {
    if (a.sign == 0 || b.sign == 0) return bi_zero();
    BigInt res = {0};
    int64_t sign = (int64_t)a.sign * b.sign;
    for (int i = 0; i < a.len; i++) {
        int64_t carry = 0;
        for (int j = 0; j < b.len || carry; j++) {
            int64_t cur = res.d[i + j] + a.d[i] * (j < b.len ? b.d[j] : 0) + carry;
