    }
    // Correct len update
    int max_len = a.len + b.len + 2;
    int actual_len = max_len;
    while (actual_len > 0 && res.d[actual_len - 1] == 0) actual_len--;
    res.len = actual_len;
    res.sign = sign;
    if (res.len == 0) res.sign = 0;
    return res;
}

// Proper BigInt multiplication
BigInt bi_mul_fixed(BigInt a, BigInt b) {
    if (a.sign == 0 || b.sign == 0) return bi_zero();
    int64_t res_d[60] = {0};
    for (int i = 0; i < a.len; i++) {
        for (int j = 0; j < b.len; j++) {
            res_d[i + j] += a.d[i] * b.d[j];
            res_d[i + j + 1] += res_d[i + j] / 1000000000LL;
            res_d[i + j] %= 1000000000LL;
        }
    }
    BigInt res = {0};
    int carry = 0;
    for (int i = 0; i < 60 || carry; i++) {
        int64_t cur = (i < 60 ? res_d[i] : 0) + carry;
        res.d[res.len++] = cur % 1000000000LL;
        carry = cur / 1000000000LL;
    }
    while (res.len > 0 && res.d[res.len - 1] == 0) res.len--;
    res.sign = (int64_t)a.sign * b.sign;
    if (res.len == 0) res.sign = 0;
    return res;
}

