}

// A simpler division for the specific needs of this problem
BigInt bi_div_small(BigInt a, int64_t b, BigInt *r) {
    BigInt q = {0};
    int64_t rem = 0;
    for (int i = a.len - 1; i >= 0; i--) {
        int64_t cur = a.d[i] + rem * 1000000000LL;
        int64_t quotient = cur / b;
        rem = cur % b;
        q.d[q.len++] = quotient; // This is reverse order
    }
    // Reverse q.d and fix len
    int real_len = q.len;
    int64_t temp[60];
    for (int i = 0; i < real_len; i++) temp[i] = q.d[real_len - 1 - i];
    q.len = 0;
    for (int i = 0; i < real_len; i++) q.d[q.len++] = temp[i];
    while (q.len > 0 && q.d[q.len - 1] == 0) q.len--;
    if (r) {
        *r = bi_zero();
        (*r).len = 1; (*r).d[0] = rem; (*r).sign = 1;
        if (rem == 0) (*r).sign = 0;
    }
    return q;
}

// We need a more robust BigInt. Let's use a simpler base for division.
// Since the max value is ~70 digits, base 10 is feasible but slow.
// Base 10^9 is better. Let's implement a basic BigInt class-like structure.

typedef struct {
    int64_t v[100];
    int len;
    int sign;
} BigNum;

BigNum bn_zero() { return (BigNum){.len = 1, .v = {0}, .sign = 0}; }
BigNum bn_one() { return (BigNum){.len = 1, .v = {1}, .sign = 1}; }

int bn_cmp(BigNum a, BigNum b) {
    if (a.sign != b.sign) return a.sign - b.sign;
    if (a.sign == 0) return 0;
    if (a.len > b.len) return a.sign;
    if (a.len < b.len) return -a.sign;
    for (int i = a.len - 1; i >= 0; i--) {
        if (a.v[i] > b.v[i]) return a.sign;
        if (a.v[i] < b.v[i]) return -a.sign;
    }
    return 0;
}

BigNum bn_add_abs(BigNum a, BigNum b) {
    BigNum res = {0};
    int64_t carry = 0;
    int max_len = a.len > b.len ? a.len : b.len;
    for (int i = 0; i < max_len || carry; i++) {
        int64_t sum = carry + (i < a.len ? a.v[i] : 0) + (i < b.len ? b.v[i] : 0);
        res.v[res.len++] = sum % 10;
        carry = sum / 10;
    }
    return res;
}

BigNum bn_sub_abs(BigNum a, BigNum b) {
    BigNum res = {0};
    int64_t borrow = 0;
    for (int i = 0; i < a.len; i++) {
        int64_t diff = a.v[i] - borrow - (i < b.len ? b.v[i] : 0);
        if (diff < 0) { diff += 10; borrow = 1; }
        else borrow = 0;
        res.v[res.len++] = diff;
    }
    while (res.len > 0 && res.v[res.len - 1] == 0) res.len--;
    return res;
}

BigNum bn_add(BigNum a, BigNum b) {
    if (a.sign == 0) { BigNum r = b; r.sign = b.sign; return r; }
    if (b.sign == 0) { BigNum r = a; r.sign = a.sign; return r; }
    if (a.sign == b.sign) {
        BigNum r = bn_add_abs(a, b);
        r.sign = a.sign; return r;
    }
    BigNum abs_a = a; abs_a.sign = 1;
    BigNum abs_b = b; abs_b.sign = 1;
    int cmp = 0;
    if (abs_a.len > abs_b.len) cmp = 1;
    else if (abs_a.len < abs_b.len) cmp = -1;
    else {
        for (int i = a.len - 1; i >= 0; i--) {
            if (a.v[i] > b.v[i]) { cmp = 1; break; }
            if (a.v[i] < b.v[i]) { cmp = -1; break; }
        }
    }
    if (cmp == 0) return bn_zero();
    if (cmp > 0) {
        BigNum r = bn_sub_abs(abs_a, abs_b);
        r.sign = a.sign; return r;
    } else {
        BigNum r = bn_sub_abs(abs_b, abs_a);
        r.sign = b.sign; return r;
    }
}

BigNum bn_sub(BigNum a, BigNum b) {
    BigNum nb = b; nb.sign = -b.sign;
    return bn_add(a, nb);
}

BigNum bn_mul(BigNum a, BigNum b) {
    if (a.sign == 0 || b.sign == 0) return bn_zero();
    BigNum res = {0};
    int64_t v[200] = {0};
    for (int i = 0; i < a.len; i++) {
        for (int j = 0; j < b.len; j++) {
            v[i + j] += a.v[i] * b.v[j];
            v[i + j + 1] += v[i + j] / 10;
            v[i + j] %= 10;
        }
    }
    int carry = 0;
    for (int i = 0; i < 200 || carry; i++) {
        int64_t cur = (i < 200 ? v[i] : 0) + carry;
        res.v[res.len++] = cur % 10;
        carry = cur / 10;
    }
    while (res.len > 0 && res.v[res.len - 1] == 0) res.len--;
    res.sign = a.sign * b.sign;
    if (res.len == 0) res.sign = 0;
    return res;
}

void bn_div_mod(BigNum a, BigNum b, BigNum *q, BigNum *r) {
    BigNum abs_a = a; abs_a.sign = 1;
    BigNum abs_b = b; abs_b.sign = 1;
    BigNum cur_q = {0}, cur_r = {0};
    cur_q.len = 0; cur_r.len = 0;
    for (int i = a.len - 1; i >= 0; i--) {
        BigNum next_r = {0};
        int64_t carry = a.v[i];
        for (int j = 0; j < cur_r.len || carry; j++) {
            int64_t val = carry + (j < cur_r.len ? cur_r.v[j] * 10 : 0);
            next_r.v[next_r.len++] = val % 10;
            carry = val / 10;
        }
        while (next_r.len > 0 && next_r.v[next_r.len - 1] == 0) next_r.len--;
        cur_r = next_r;
        int best_q = 0;
        for (int d = 1; d <= 9; d++) {
            BigNum d_bi = {0}; d_bi.len = 1; d_bi.v[0] = d; d_bi.sign = 1;
            BigNum prod = bn_mul(abs_b, d_bi);
            prod.sign = 1;
            if (bn_cmp(prod, cur_r) <= 0) best_q = d;
            else break;
        }
        cur_q.v[cur_q.len++] = best_q;
        BigNum b_q = {0}; b_q.len = 1; b_q.v[0] = best_q; b_q.sign = 1;
        BigNum prod = bn_mul(abs_b, b_q);
        prod.sign = 1;
        cur_r = bn_sub_abs(cur_r, prod);
        while (cur_r.len > 0 && cur_r.v[cur_r.len - 1] == 0) cur_r.len--;
    }
    BigNum final_q = {0};
    for (int i = 0; i < cur_q.len; i++) final_q.v[i] = cur_q.v[cur_q.len - 1 - i];
    final_q.len = cur_q.len;
    while (final_q.len > 0 && final_q.v[final_q.len - 1] == 0) final_q.len--;
    final_q.sign = a.sign * b.sign;
    if (final_q.len == 0) final_q.sign = 0;
    *q = final_q;
    *r = cur_r;
    (*r).sign = a.sign;
    if ((*r).len == 0) (*r).sign = 0;
}

BigNum bn_from_string(const char *s) {
    BigNum res = {0};
    int sign = 1;
    if (*s == '-') { sign = -1; s++; }
    int len = 0;
    while (*s && ((*s >= '0' && *s <= '9') || *s == '.')) {
        if (*s == '.') {
            while (*s == '.') s++;
            continue;
        }
        // This is a very simple string to BigNum, doesn't handle decimals
        // We will handle decimals in Decimal_from_string
        s++;
    }
    return res;
}

BigNum bn_from_int(int64_t n) {
    BigNum res = {0};
    if (n == 0) return bn_zero();
    res.sign = (n > 0) ? 1 : -1;
    if (n < 0) n = -n;
    while (n > 0) {
        res.v[res.len++] = n % 10;
        n /= 10;
    }
    return res;
}

BigNum bn_pow10(int p) {
    BigNum res = bn_one();
    for (int i = 0; i < p; i++) {
        BigNum ten = bn_from_int(10);
        res = bn_mul(res, ten);
    }
    return res;
}

BigNum bn_round_half_even(BigNum P, BigNum Q) {
    BigNum q, r;
    bn_div_mod(P, Q, &q, &r);
    BigNum r2 = bn_mul(r, bn_from_int(2));
    int cmp = bn_cmp(r2, Q);
    if (cmp < 0) return q;
    if (cmp > 0) {
        BigNum one = bn_one();
        return bn_add(q, one);
    }
    if (q.len == 0 || q.v[0] % 2 == 0) return q;
    BigNum one = bn_one();
    return bn_add(q, one);
}

typedef struct {
    BigNum val;
    int scale;
} Decimal;

Decimal dec_from_string(const char *s) {
    int sign = 1;
    if (*s == '-') { sign = -1; s++; }
    char buf[128];
    int b_idx = 0;
    bool has_dot = false;
    int scale = 0;
    while (*s) {
        if (*s == '.') {
            has_dot = true;
        } else {
            buf[b_idx++] = *s;
            if (has_dot) scale++;
        }
        s++;
    }
    buf[b_idx] = '\0';
    BigNum n = {0};
    for (int i = b_idx - 1; i >= 0; i--) {
        n.v[n.len++] = buf[i] - '0';
    }
    while (n.len > 0 && n.v[n.len - 1] == 0) n.len--;
    n.sign = sign;
    if (n.len == 0) n.sign = 0;
    return (Decimal){n, scale};
}

BigNum dec_to_minor(Decimal dec, int precision) {
    BigNum abs_n = dec.val; abs_n.sign = 1;
    BigNum p10 = bn_pow10(precision);
    BigNum P = bn_mul(abs_n, p10);
    BigNum Q = bn_pow10(dec.scale);
    BigNum rounded = bn_round_half_even(P, Q);
    rounded.sign = dec.val.sign;
    if (rounded.len == 0) rounded.sign = 0;
    return rounded;
}

