#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>
#include <stdint.h>

#define BASE 1000000000LL
#define MAX_DIGITS 100

typedef struct {
    int64_t d[MAX_DIGITS];
    int len;
    int sign; // 1 for positive, -1 for negative, 0 for zero
} BigInt;

BigInt bi_zero() { return (BigInt){.len = 1, .d = {0}, .sign = 0}; }
BigInt bi_one() { return (BigInt){.len = 1, .d = {1}, .sign = 1}; }

int bi_cmp_abs(BigInt a, BigInt b) {
    if (a.len > b.len) return 1;
    if (a.len < b.len) return -1;
    for (int i = a.len - 1; i >= 0; i--) {
        if (a.d[i] > b.d[i]) return 1;
        if (a.d[i] < b.d[i]) return -1;
    }
    return 0;
}

int bi_cmp(BigInt a, BigInt b) {
    if (a.sign != b.sign) return a.sign - b.sign;
    if (a.sign == 0) return 0;
    int res = bi_cmp_abs(a, b);
    return (a.sign == 1) ? res : -res;
}

BigInt bi_add_abs(BigInt a, BigInt b) {
    BigInt res = {0};
    int64_t carry = 0;
    int max_len = a.len > b.len ? a.len : b.len;
    for (int i = 0; i < max_len || carry; i++) {
        int64_t sum = carry + (i < a.len ? a.d[i] : 0) + (i < b.len ? b.d[i] : 0);
        res.d[res.len++] = sum % BASE;
        carry = sum / BASE;
    }
    return res;
}

BigInt bi_sub_abs(BigInt a, BigInt b) { // Assumes a >= b
    BigInt res = {0};
    int64_t borrow = 0;
    for (int i = 0; i < a.len; i++) {
        int64_t diff = a.d[i] - borrow - (i < b.len ? b.d[i] : 0);
        if (diff < 0) { diff += BASE; borrow = 1; }
        else borrow = 0;
        res.d[res.len++] = diff;
    }
    while (res.len > 0 && res.d[res.len - 1] == 0) res.len--;
    if (res.len == 0) res.sign = 0;
    return res;
}

BigInt bi_add(BigInt a, BigInt b) {
    if (a.sign == 0) return b;
    if (b.sign == 0) return a;
    if (a.sign == b.sign) {
        BigInt res = bi_add_abs(a, b);
        res.sign = a.sign;
        return res;
    }
    int cmp = bi_cmp_abs(a, b);
    if (cmp == 0) return bi_zero();
    if (cmp > 0) {
        BigInt res = bi_sub_abs(a, b);
        res.sign = a.sign;
        return res;
    } else {
        BigInt res = bi_sub_abs(b, a);
        res.sign = b.sign;
        return res;
    }
}

BigInt bi_sub(BigInt a, BigInt b) {
    BigInt nb = b; nb.sign = -b.sign;
    return bi_add(a, nb);
}

BigInt bi_mul(BigInt a, BigInt b) {
    if (a.sign == 0 || b.sign == 0) return bi_zero();
    int64_t res_d[MAX_DIGITS * 2] = {0};
    for (int i = 0; i < a.len; i++) {
        int64_t carry = 0;
        for (int j = 0; j < b.len || carry; j++) {
            int64_t prod = res_d[i + j] + a.d[i] * (j < b.len ? b.d[j] : 0) + carry;
            res_d[i + j] = prod % BASE;
            carry = prod / BASE;
        }
    }
    BigInt res = {0};
    int total_len = a.len + b.len + 2;
    for (int i = 0; i < total_len; i++) res.d[res.len++] = res_d[i];
    while (res.len > 0 && res.d[res.len - 1] == 0) res.len--;
    res.sign = a.sign * b.sign;
    if (res.len == 0) res.sign = 0;
    return res;
}

void bi_div_mod(BigInt a, BigInt b, BigInt *q, BigInt *r) {
    BigInt abs_a = a; abs_a.sign = 1; if (a.sign == 0) abs_a.sign = 0;
    BigInt abs_b = b; abs_b.sign = 1; if (b.sign == 0) abs_b.sign = 0;
    BigInt cur_q = {0}, cur_r = {0};
    for (int i = a.len - 1; i >= 0; i--) {
        BigInt next_r = {0};
        int64_t carry = a.d[i];
        for (int j = 0; j < cur_r.len || carry; j++) {
            int64_t val = carry + (j < cur_r.len ? cur_r.d[j] * BASE : 0);
            next_r.d[next_r.len++] = val % BASE;
            carry = val / BASE;
        }
        while (next_r.len > 0 && next_r.d[next_r.len - 1] == 0) next_r.len--;
        cur_r = next_r;
        int64_t low = 0, high = BASE - 1, best_q = 0;
        while (low <= high) {
            int64_t mid = low + (high - low) / 2;
            BigInt m_bi = {0}; m_bi.len = 1; m_bi.d[0] = mid; m_bi.sign = 1;
            BigInt prod = bi_mul(abs_b, m_bi);
            if (bi_cmp_abs(prod, cur_r) <= 0) { best_q = mid; low = mid + 1; }
            else high = mid - 1;
        }
        cur_q.d[cur_q.len++] = best_q;
        BigInt b_q = {0}; b_q.len = 1; b_q.d[0] = best_q; b_q.sign = 1;
        BigInt prod = bi_mul(abs_b, b_q);
        cur_r = bi_sub_abs(cur_r, prod);
        while (cur_r.len > 0 && cur_r.d[cur_r.len - 1] == 0) cur_r.len--;
    }
    BigInt final_q = {0};
    for (int i = 0; i < cur_q.len; i++) final_q.d[final_q.len++] = cur_q.d[cur_q.len - 1 - i];
    while (final_q.len > 0 && final_q.d[final_q.len - 1] == 0) final_q.len--;
    final_q.sign = a.sign * b.sign;
    if (final_q.len == 0) final_q.sign = 0;
    *q = final_q;
    *r = cur_r;
    (*r).sign = a.sign;
    if ((*r).len == 0) (*r).sign = 0;
}

BigInt bi_from_string(const char *s) {
    BigInt res = {0};
    int sign = 1;
    if (*s == '-') { sign = -1; s++; }
    char buf[128];
    int b_idx = 0;
    while (*s && *s != '.') buf[b_idx++] = *s++;
    buf[b_idx] = '\0';
    for (int i = b_idx - 1; i >= 0; i--) {
        BigInt digit = {0}; digit.len = 1; digit.d[0] = buf[i] - '0'; digit.sign = 1;
        BigInt ten = {0}; ten.len = 1; ten.d[0] = 10; ten.sign = 1;
        res = bi_add(bi_mul(res, ten), digit);
    }
    res.sign = sign;
    if (res.len == 0 || (res.len == 1 && res.d[0] == 0)) res.sign = 0;
    return res;
}

BigInt bi_pow10(int p) {
    BigInt res = bi_one();
    BigInt ten = {0}; ten.len = 1; ten.d[0] = 10; ten.sign = 1;
    for (int i = 0; i < p; i++) res = bi_mul(res, ten);
    return res;
}

typedef struct {
    BigInt val;
    int scale;
} Decimal;

Decimal dec_from_string(const char *s) {
    int sign = 1;
    if (*s == '-') { sign = -1; s++; }
    char buf[128];
    int b_idx = 0, scale = 0;
    bool dot = false;
    while (*s) {
        if (*s == '.') dot = true;
        else {
            buf[b_idx++] = *s;
            if (dot) scale++;
        }
        s++;
    }
    buf[b_idx] = '\0';
    BigInt v = {0};
    for (int i = b_idx - 1; i >= 0; i--) {
        BigInt digit = {0}; digit.len = 1; digit.d[0] = buf[i] - '0'; digit.sign = 1;
        BigInt ten = {0}; ten.len = 1; ten.d[0] = 10; ten.sign = 1;
        v = bi_add(bi_mul(v, ten), digit);
    }
    v.sign = sign;
    if (v.len == 0 || (v.len == 1 && v.d[0] == 0)) v.sign = 0;
    return (Decimal){v, scale};
}

BigInt round_half_even(BigInt num, BigInt den) {
    BigInt abs_num = num; abs_num.sign = 1; if (num.sign == 0) abs_num.sign = 0;
    BigInt abs_den = den; abs_den.sign = 1; if (den.sign == 0) abs_den.sign = 0;
    BigInt q, r;
    bi_div_mod(abs_num, abs_den, &q, &r);
    BigInt r2 = bi_mul(r, bi_one()); r2.d[0] = r.d[0] * 2; // Simplified for small r
    // Correct bi_mul for r*2
    BigInt two = {0}; two.len = 1; two.d[0] = 2; two.sign = 1;
    r2 = bi_mul(r, two);

    int cmp = bi_cmp(r2, abs_den);
    if (cmp < 0) {
        q.sign = num.sign; if (q.len == 0 || (q.len == 1 && q.d[0] == 0)) q.sign = 0;
        return q;
    } else if (cmp > 0) {
        BigInt res = bi_add(q, bi_one());
        res.sign = num.sign; if (res.len == 0 || (res.len == 1 && res.d[0] == 0)) res.sign = 0;
        return res;
    } else {
        bool odd = false;
        if (q.len == 0) odd = false;
        else {
            int64_t last = q.d[0];
            odd = (last % 2 != 0);
        }
        if (odd) {
            BigInt res = bi_add(q, bi_one());
            res.sign = num.sign; if (res.len == 0 || (res.len == 1 && res.d[0] == 0)) res.sign = 0;
            return res;
        } else {
            q.sign = num.sign; if (q.len == 0 || (q.len == 1 && q.d[0] == 0)) q.sign = 0;
            return q;
        }
    }
}

BigInt dec_to_minor(Decimal dec, int precision) {
    BigInt p10 = bi_pow10(precision);
    BigInt num = bi_mul(dec.val, p10);
    BigInt den = bi_pow10(dec.scale);
    return round_half_even(num, den);
}

