def base64url_decode(s):
    """Decodes a base64url-encoded string (RFC 4648 §5, no padding)."""
    # Add padding if necessary to make the length a multiple of 4
    padding = len(s) % 4
    if padding == 2:
        s += '=='
    elif padding == 3:
        s += '='
    elif padding == 1:
        # A base64 string cannot have a length that is 1 mod 4
        raise ValueError("Invalid base64url length")
    return base64.urlsafe_b64decode(s)

def verify_token(token, config, now, leeway, issuer, audience, keys):
    """Verifies a single JWT based on the provided configuration and rules."""
    # 1. MALFORMED
    segments = token.split('.')
    if len(segments) != 3:
        return "MALFORMED", None

    for seg in segments:
        if not seg:
            return "MALFORMED", None
        # Valid base64url characters: A-Z, a-z, 0-9, -, _
        if not all(c in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_" for c in seg):
            return "MALFORMED", None
        # Length must not be 1 mod 4
        if len(seg) % 4 == 1:
            return "MALFORMED", None

    try:
        # Decoded segments must be valid UTF-8 and JSON objects
        header_bytes = base64url_decode(segments[0])
        header = json.loads(header_bytes.decode('utf-8'))
        if not isinstance(header, dict):
            return "MALFORMED", None

        payload_bytes = base64url_decode(segments[1])
        payload = json.loads(payload_bytes.decode('utf-8'))
        if not isinstance(payload, dict):
            return "MALFORMED", None
    except Exception:
        return "MALFORMED", None

    # 2. UNSUPPORTED_ALG
    alg = header.get('alg')
    if not isinstance(alg, str) or alg not in ["HS256", "HS384", "HS512"]:
        return "UNSUPPORTED_ALG", None

    # 3. UNKNOWN_KEY
    kid = header.get('kid')
    if not isinstance(kid, str):
        return "UNKNOWN_KEY", None

    key_config = next((k for k in keys if k.get('kid') == kid), None)
    if not key_config:
        return "UNKNOWN_KEY", None

    # 4. ALG_MISMATCH
    if key_config.get('alg') != alg:
        return "ALG_MISMATCH", None

    # 5. BAD_SIGNATURE
    # Decode the HMAC secret from the config
    try:
        secret = base64url_decode(key_config['k'])
    except Exception:
        return "BAD_SIGNATURE", None

    # The signing input is exactly <header segment>.<payload segment>
    signing_input = (segments[0] + '.' + segments[1]).encode('ascii')

    hash_alg_map = {
        "HS256": hashlib.sha256,
        "HS384": hashlib.sha384,
        "HS512": hashlib.sha512
    }
    digest_mod = hash_alg_map[alg]

    expected_sig = hmac.new(secret, signing_input, digest_mod).digest()
    try:
        actual_sig = base64url_decode(segments[2])
    except Exception:
        return "BAD_SIGNATURE", None

    if actual_sig != expected_sig:
        return "BAD_SIGNATURE", None

    # 6. EXPIRED
    exp = payload.get('exp')
    if exp is not None:
        # exp and nbf are numbers and may have fractional parts
        if now >= exp + leeway:
            return "EXPIRED", None

    # 7. NOT_YET_VALID
    nbf = payload.get('nbf')
    if nbf is not None:
        if now + leeway < nbf:
            return "NOT_YET_VALID", None

    # 8. BAD_ISSUER
    iss = payload.get('iss')
    if not isinstance(iss, str) or iss != issuer:
        return "BAD_ISSUER", None

    # 9. BAD_AUDIENCE
    aud = payload.get('aud')
    if isinstance(aud, str):
        if aud != audience:
            return "BAD_AUDIENCE", None
    elif isinstance(aud, list):
        if audience not in aud:
            return "BAD_AUDIENCE", None
    else:
        # Covers missing aud, or any other JSON type
        return "BAD_AUDIENCE", None

    return "VALID", payload

def main():
    if len(sys.argv) < 2:
        return

    root_dir = sys.argv[1]
    config_path = os.path.join(root_dir, 'config.json')
    tokens_path = os.path.join(root_dir, 'tokens.txt')

    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except Exception:
        return

    now = config.get('now', 0)
    leeway = config.get('leeway', 0)
    issuer = config.get('issuer', '')
    audience = config.get('audience', '')
    keys = config.get('keys', [])

    valid_count = 0
    invalid_count = 0

    try:
        with open(tokens_path, 'r', encoding='utf-8') as f:
            token_num = 0
            for line in f:
                token = line.strip()
                if not token:
                    continue

                token_num += 1
                res, payload = verify_token(token, config, now, leeway, issuer, audience, keys)

                if res == "VALID":
                    valid_count += 1
                    # Extract sub (guaranteed to exist as string if VALID)
                    sub = payload.get('sub', '')
                    # Extract and process scope
                    scope_val = payload.get('scope', '')
                    if not isinstance(scope_val, str):
                        scope_val = ''
                    # split on spaces, ignore empty pieces, de-duplicate, sort by Unicode, join with commas
                    scopes_list = scope_val.split()
                    unique_scopes = sorted(list(set(scopes_list)))
                    scopes_joined = ','.join(unique_scopes)
                    print(f"{token_num}: VALID sub={sub} scope={scopes_joined}")
                else:
                    invalid_count += 1
                    print(f"{token_num}: {res}")
    except Exception:
        pass

    print()
    print(f"valid={valid_count} invalid={invalid_count}")

if __name__ == "__main__":
    main()

import json
import sys
import os

def get_json_type(v):
    """Returns the JSON type of the value v."""
    if v is None: return 'null'
    if isinstance(v, bool): return 'boolean'
    if isinstance(v, (int, float)): return 'number'
    if isinstance(v, str): return 'string'
    if isinstance(v, list): return 'array'
    if isinstance(v, dict): return 'object'
    return None

def deep_equal(v1, v2):
    """Checks for deep equality between two JSON values."""
    t1, t2 = get_json_type(v1), get_json_type(v2)
    if t1 != t2: return False
    if t1 == 'number': return v1 == v2
    if t1 == 'string': return v1 == v2
    if t1 == 'boolean' or t1 == 'null': return v1 == v2
    if t1 == 'array':
        if len(v1) != len(v2): return False
        return all(deep_equal(x, y) for x, y in zip(v1, v2))
    if t1 == 'object':
        if len(v1) != len(v2): return False
        return all(k in v2 and deep_equal(v1[k], v2[k]) for k in v1)
    return False

def pointer_to_str(ptr):
    """Converts a JSON pointer (list of tokens) to its string representation."""
    if not ptr: return "#"
    res = "#"
    for token in ptr:
        res += "/" + token.replace("~", "~0").replace("/", "~1")
    return res

def resolve_ref(ref, root_schema):
    """Resolves a $ref string to its corresponding schema and its location."""
    if ref == "#":
        return root_schema, []
    if ref.startswith("#/$defs/"):
        token = ref[len("#/$defs/"):]
        name = token.replace("~0", "~").replace("~1", "/")
        return root_schema["$defs"][name], ["$defs", name]
    return None, None

def matches_type(val, t):
    """Checks if a JSON value matches a specific type string."""
    vt = get_json_type(val)
    if t == 'number': return vt == 'number'
    if t == 'integer': return vt == 'number' and float(val).is_integer()
    return vt == t

def validate(instance, schema, instance_ptr, schema_ptr, root_schema, errors):
    """Validates an instance against a schema and collects errors."""
    if schema is True:
        return
    if schema is False:
        errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr)))
        return

    # Schema is an object
    # Any instance type keywords
    if 'type' in schema:
        type_val = schema['type']
        allowed_types = [type_val] if isinstance(type_val, str) else type_val
        if not any(matches_type(instance, t) for t in allowed_types):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['type'])))

    if 'enum' in schema:
        if not any(deep_equal(instance, x) for x in schema['enum']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['enum'])))

    if 'const' in schema:
        if not deep_equal(instance, schema['const']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['const'])))

    # Number keywords
    if get_json_type(instance) == 'number':
        if 'minimum' in schema and not (instance >= schema['minimum']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['minimum'])))
        if 'maximum' in schema and not (instance <= schema['maximum']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['maximum'])))
        if 'exclusiveMinimum' in schema and not (instance > schema['exclusiveMinimum']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['exclusiveMinimum'])))
        if 'exclusiveMaximum' in schema and not (instance < schema['exclusiveMaximum']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['exclusiveMaximum'])))

    # String keywords
    if get_json_type(instance) == 'string':
        if 'minLength' in schema and not (len(instance) >= schema['minLength']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['minLength'])))
        if 'maxLength' in schema and not (len(instance) <= schema['maxLength']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['maxLength'])))

    # Array keywords
    if get_json_type(instance) == 'array':
        if 'minItems' in schema and not (len(instance) >= schema['minItems']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['minItems'])))
        if 'maxItems' in schema and not (len(instance) <= schema['maxItems']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['maxItems'])))
        if 'uniqueItems' in schema and schema['uniqueItems'] is True:
            unique = True
            for i in range(len(instance)):
                for j in range(i + 1, len(instance)):
                    if deep_equal(instance[i], instance[j]):
                        unique = False
                        break
                if not unique: break
            if not unique:
                errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['uniqueItems'])))
        if 'prefixItems' in schema:
            for i in range(min(len(instance), len(schema['prefixItems']))):
                sub_errors = set()
                validate(instance[i], schema['prefixItems'][i], instance_ptr + [str(i)], schema_ptr + ['prefixItems', str(i)], root_schema, sub_errors)
                errors.update(sub_errors)
        if 'items' in schema:
            start_idx = len(schema.get('prefixItems', []))
            for i in range(start_idx, len(instance)):
                sub_errors = set()
                validate(instance[i], schema['items'], instance_ptr + [str(i)], schema_ptr + ['items'], root_schema, sub_errors)
                errors.update(sub_errors)

    # Object keywords
    if get_json_type(instance) == 'object':
        if 'minProperties' in schema and not (len(instance) >= schema['minProperties']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['minProperties'])))
        if 'maxProperties' in schema and not (len(instance) <= schema['maxProperties']):
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['maxProperties'])))
        if 'required' in schema:
            for j in range(len(schema['required'])):
                req_name = schema['required'][j]
                if req_name not in instance:
                    errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['required', str(j)])))
        if 'properties' in schema:
            for prop_name, prop_schema in schema['properties'].items():
                if prop_name in instance:
                    sub_errors = set()
                    validate(instance[prop_name], prop_schema, instance_ptr + [prop_name], schema_ptr + ['properties', prop_name], root_schema, sub_errors)
                    errors.update(sub_errors)
        if 'additionalProperties' in schema:
            properties = schema.get('properties', {})
            for prop_name, prop_val in instance.items():
                if prop_name not in properties:
                    sub_errors = set()
                    validate(prop_val, schema['additionalProperties'], instance_ptr + [prop_name], schema_ptr + ['additionalProperties'], root_schema, sub_errors)
                    errors.update(sub_errors)

    # Applicators
    if 'allOf' in schema:
        for i in range(len(schema['allOf'])):
            sub_errors = set()
            validate(instance, schema['allOf'][i], instance_ptr, schema_ptr + ['allOf', str(i)], root_schema, sub_errors)
            errors.update(sub_errors)
    if 'anyOf' in schema:
        any_accepted = False
        for i in range(len(schema['anyOf'])):
            sub_errors = set()
            validate(instance, schema['anyOf'][i], instance_ptr, schema_ptr + ['anyOf', str(i)], root_schema, sub_errors)
            if not sub_errors:
                any_accepted = True
                break
        if not any_accepted:
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['anyOf'])))
    if 'oneOf' in schema:
        accepted_count = 0
        for i in range(len(schema['oneOf'])):
            sub_errors = set()
            validate(instance, schema['oneOf'][i], instance_ptr, schema_ptr + ['oneOf', str(i)], root_schema, sub_errors)
            if not sub_errors:
                accepted_count += 1
        if accepted_count != 1:
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['oneOf'])))
    if 'not' in schema:
        sub_errors = set()
        validate(instance, schema['not'], instance_ptr, schema_ptr + ['not'], root_schema, sub_errors)
        if not sub_errors:
            errors.add((pointer_to_str(instance_ptr), pointer_to_str(schema_ptr + ['not'])))
    if 'if' in schema:
        sub_errors = set()
        validate(instance, schema['if'], instance_ptr, schema_ptr + ['if'], root_schema, sub_errors)
        if not sub_errors:
            if 'then' in schema:
                then_errors = set()
                validate(instance, schema['then'], instance_ptr, schema_ptr + ['then'], root_schema, then_errors)
                errors.update(then_errors)
        else:
            if 'else' in schema:
                else_errors = set()
                validate(instance, schema['else'], instance_ptr, schema_ptr + ['else'], root_schema, else_errors)
                errors.update(else_errors)
    if '$ref' in schema:
        ref = schema['$ref']
        ref_schema, ref_ptr = resolve_ref(ref, root_schema)
        sub_errors = set()
        validate(instance, ref_schema, instance_ptr, ref_ptr, root_schema, sub_errors)
        errors.update(sub_errors)

def main():
    if len(sys.argv) < 2:
        return
    directory = sys.argv[1]

    with open(os.path.join(directory, 'schema.json'), 'r', encoding='utf-8') as f:
        schema = json.load(f)
    with open(os.path.join(directory, 'instances.json'), 'r', encoding='utf-8') as f:
        instances = json.load(f)

    valid_count = 0
    invalid_count = 0

    for i, instance in enumerate(instances):
        errors = set()
        validate(instance, schema, [], [], schema, errors)

        if not errors:
            print(f"{i}: valid")
            valid_count += 1
        else:
            print(f"{i}: invalid ({len(errors)})")
            sorted_errors = sorted(list(errors), key=lambda x: (x[0], x[1]))
            for inst_ptr, sch_ptr in sorted_errors:
                print(f"  {inst_ptr} {sch_ptr}")
            invalid_count += 1

    print(f"valid={valid_count} invalid={invalid_count}")

if __name__ == "__main__":
    main()

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

interface Config {
    now: number;
    leeway: number;
    issuer: string;
    audience: string;
    keys: Array<{
        kid: string;
        kty: string;
        alg: string;
        k: string;
    }>;
}

interface VerificationResult {
    status: string;
    sub?: string;
    scope?: string;
}

function isObject(val: any): boolean {
    return typeof val === 'object' && val !== null && !Array.isArray(val);
}

function verifyToken(token: string, config: Config): VerificationResult {
    // 1. MALFORMED
    const segments = token.split('.');
    if (segments.length !== 3) return { status: 'MALFORMED' };

    for (const seg of segments) {
        if (seg.length === 0) return { status: 'MALFORMED' };
        if (seg.length % 4 === 1) return { status: 'MALFORMED' };
        if (!/^[A-Za-z0-9_-]*$/.test(seg)) return { status: 'MALFORMED' };
    }

    let header: any;
    let payload: any;
    try {
        header = JSON.parse(Buffer.from(segments[0], 'base64url').toString('utf8'));
        payload = JSON.parse(Buffer.from(segments[1], 'base64url').toString('utf8'));
        if (!isObject(header) || !isObject(payload)) return { status: 'MALFORMED' };
    } catch (e) {
        return { status: 'MALFORMED' };
    }

    // 2. UNSUPPORTED_ALG
    const supportedAlgs = ['HS256', 'HS384', 'HS512'];
    if (typeof header.alg !== 'string' || !supportedAlgs.includes(header.alg)) {
        return { status: 'UNSUPPORTED_ALG' };
    }

    // 3. UNKNOWN_KEY
    if (typeof header.kid !== 'string') return { status: 'UNKNOWN_KEY' };
    const key = config.keys.find(k => k.kid === header.kid);
    if (!key) return { status: 'UNKNOWN_KEY' };

    // 4. ALG_MISMATCH
    if (key.alg !== header.alg) return { status: 'ALG_MISMATCH' };

    // 5. BAD_SIGNATURE
    const algMap: Record<string, string> = { 'HS256': 'sha256', 'HS384': 'sha384', 'HS512': 'sha512' };
    const signingInput = segments[0] + '.' + segments[1];
    const signature = Buffer.from(segments[2], 'base64url');
    const hmac = crypto.createHmac(algMap[header.alg], Buffer.from(key.k, 'base64url'))
        .update(signingInput)
        .digest();

    if (!hmac.equals(signature)) return { status: 'BAD_SIGNATURE' };

    // 6. EXPIRED
    if (payload.exp !== undefined) {
        if (config.now >= payload.exp + config.leeway) return { status: 'EXPIRED' };
    }

    // 7. NOT_YET_VALID
    if (payload.nbf !== undefined) {
        if (config.now + config.leeway < payload.nbf) return { status: 'NOT_YET_VALID' };
    }

    // 8. BAD_ISSUER
    if (payload.iss !== config.issuer) return { status: 'BAD_ISSUER' };

    // 9. BAD_AUDIENCE
    if (payload.aud === undefined) return { status: 'BAD_AUDIENCE' };
    if (typeof payload.aud === 'string') {
        if (payload.aud !== config.audience) return { status: 'BAD_AUDIENCE' };
    } else if (Array.isArray(payload.aud)) {
        if (!payload.aud.includes(config.audience)) return { status: 'BAD_AUDIENCE' };
    } else {
        return { status: 'BAD_AUDIENCE' };
    }

    // VALID
    let scopes = "";
    if (typeof payload.scope === 'string') {
        const scopeParts = payload.scope.split(' ').filter(s => s !== '');
        const uniqueScopes = Array.from(new Set(scopeParts)).sort();
        scopes = uniqueScopes.join(',');
    }

    return { status: 'VALID', sub: payload.sub, scope: scopes };
}

function main() {
    const dir = process.argv[2];
    if (!dir) return;

    const configContent = fs.readFileSync(path.join(dir, 'config.json'), 'utf8');
    const config: Config = JSON.parse(configContent);
    const tokensContent = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf8');
    const lines = tokensContent.split('\n');

    let validCount = 0;
    let invalidCount = 0;
    let tokenIndex = 0;

    for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed === '') continue;
        tokenIndex++;

        const result = verifyToken(trimmed, config);
        if (result.status === 'VALID') {
            validCount++;
            process.stdout.write(`${tokenIndex}: VALID sub=${result.sub} scope=${result.scope}\n`);
        } else {
            invalidCount++;
            process.stdout.write(`${tokenIndex}: ${result.status}\n`);
        }
    }

    process.stdout.write(`\nvalid=${validCount} invalid=${invalidCount}\n`);
}

main();

import Foundation

struct BigInt: Comparable, CustomStringConvertible, Equatable {
    var digits: [Int64]
    var isNegative: Bool
    static let base: Int64 = 1_000_000_000

    init() {
        self.digits = [0]
        self.isNegative = false
    }

    init(integerLiteral value: Int) {
        self.isNegative = value < 0
        var v = Int64(abs(value))
        self.digits = []
        if v == 0 { self.digits = [0] }
        while v > 0 {
            self.digits.append(v % BigInt.base)
            v /= BigInt.base
        }
        if self.digits.isEmpty { self.digits = [0] }
    }

    init(string: String) {
        var s = string.trimmingCharacters(in: .whitespaces)
        if s.isEmpty {
            self.init(integerLiteral: 0)
            return
        }
        if s.hasPrefix("-") {
            self.isNegative = true
            s.removeFirst()
        } else {
            self.isNegative = false
        }
        self.digits = []
        var i = s.endIndex
        while i > s.startIndex {
            let start = s.index(i, offsetBy: -min(9, s.distance(from: s.startIndex, to: i)))
            if let part = Int64(s[start..<i]) {
                self.digits.append(part)
            }
            i = start
        }
        self.trim()
    }

    mutating func trim() {
        while digits.count > 1 && digits.last == 0 {
            digits.removeLast()
        }
        if digits == [0] {
            isNegative = false
        }
    }

    static func < (lhs: BigInt, rhs: BigInt) -> Bool {
        if lhs.isNegative != rhs.isNegative {
            return lhs.isNegative
        }
        if lhs.isNegative {
            return compareAbs(lhs, rhs) > 0
        } else {
            return compareAbs(lhs, rhs) < 0
        }
    }

    static func == (lhs: BigInt, rhs: BigInt) -> Bool {
        return lhs.isNegative == rhs.isNegative && compareAbs(lhs, rhs) == 0
    }

    static func compareAbs(_ lhs: BigInt, _ rhs: BigInt) -> Int {
        if lhs.digits.count != rhs.digits.count {
            return lhs.digits.count > rhs.digits.count ? 1 : -1
        }
        for i in (0..<lhs.digits.count).reversed() {
            if lhs.digits[i] != rhs.digits[i] {
                return lhs.digits[i] > rhs.digits[i] ? 1 : -1
            }
        }
        return 0
    }

    static func + (lhs: BigInt, rhs: BigInt) -> BigInt {
        if lhs.isNegative == rhs.isNegative {
            var res = BigInt()
            res.isNegative = lhs.isNegative
            res.digits = addAbs(lhs.digits, rhs.digits)
            res.trim()
            return res
        } else {
            return lhs - (-rhs)
        }
    }

    static func - (lhs: BigInt, rhs: BigInt) -> BigInt {
        if lhs.isNegative != rhs.isNegative {
            return lhs + (-rhs)
        }
        let cmp = compareAbs(lhs, rhs)
        if cmp == 0 {
            return BigInt(integerLiteral: 0)
        } else if cmp > 0 {
            var res = BigInt()
            res.isNegative = lhs.isNegative
            res.digits = subAbs(lhs.digits, rhs.digits)
            res.trim()
            return res
        } else {
            var res = BigInt()
            res.isNegative = !lhs.isNegative
            res.digits = subAbs(rhs.digits, lhs.digits)
            res.trim()
            return res
        }
    }

    static prefix func - (lhs: BigInt) -> BigInt {
        if lhs == BigInt(integerLiteral: 0) { return lhs }
        var res = lhs
        res.isNegative = !lhs.isNegative
        return res
    }

    static func addAbs(_ a: [Int64], _ b: [Int64]) -> [Int64] {
        var res = [Int64]()
        var carry: Int64 = 0
        let n = max(a.count, b.count)
        for i in 0..<n {
            let sum = (i < a.count ? a[i] : 0) + (i < b.count ? b[i] : 0) + carry
            res.append(sum % BigInt.base)
            carry = sum / BigInt.base
        }
        if carry > 0 { res.append(carry) }
        return res
    }

    static func subAbs(_ a: [Int64], _ b: [Int64]) -> [Int64] {
        var res = [Int64]()
        var borrow: Int64 = 0
        for i in 0..<a.count {
            var diff = a[i] - (i < b.count ? b[i] : 0) - borrow
            if diff < 0 {
                diff += BigInt.base
                borrow = 1
            } else {
                borrow = 0
            }
            res.append(diff)
        }
        return res
    }

    static func * (lhs: BigInt, rhs: BigInt) -> BigInt {
        var res = BigInt()
        res.isNegative = lhs.isNegative != rhs.isNegative
        var resDigits = [Int64](repeating: 0, count: lhs.digits.count + rhs.digits.count)
        for i in 0..<lhs.digits.count {
            var carry: Int64 = 0
            for j in 0..<rhs.digits.count {
                let prod = lhs.digits[i] * rhs.digits[j] + resDigits[i + j] + carry
                resDigits[i + j] = prod % BigInt.base
                carry = prod / BigInt.base
            }
            if carry > 0 {
                resDigits[i + rhs.digits.count] += carry
            }
        }
        res.digits = resDigits
        res.trim()
        return res
    }

