        let bAbs = rhs.absVal()
        if BigInt.compareAbs(aAbs, bAbs) < 0 {
            return (BigInt(integerLiteral: 0), self)
        }
        var qDigits = [Int64]()
        var r = BigInt(integerLiteral: 0)
        for i in (0..<aAbs.digits.count).reversed() {
            r = BigInt.multiplyByBaseAndAdd(r, aAbs.digits[i])
            var low: Int64 = 0
            var high: Int64 = BigInt.base - 1
            var qDigit: Int64 = 0
            while low <= high {
                let mid = (low + high) / 2
                if BigInt.compareAbs(bAbs * mid, r) <= 0 {
                    qDigit = mid
                    low = mid + 1
                } else {
                    high = mid - 1
                }
            }
            qDigits.append(qDigit)
            r = r - (bAbs * qDigit)
        }
        var q = BigInt()
        q.isNegative = self.isNegative != rhs.isNegative
        q.digits = qDigits.reversed()
        q.trim()
        var rem = r
        rem.isNegative = self.isNegative
        rem.trim()
        return (q, rem)
    }

    static func multiplyByBaseAndAdd(_ a: BigInt, _ digit: Int64) -> BigInt {
        var res = BigInt()
        res.isNegative = a.isNegative
        var resDigits = [Int64]()
        var carry: Int64 = 0
        for i in 0..<a.digits.count {
            let prod = a.digits[i] * BigInt.base + carry
            resDigits.append(prod % BigInt.base)
            carry = prod / BigInt.base
        }
        if carry > 0 { resDigits.append(carry) }
        var addCarry: Int64 = digit
        for i in 0..<resDigits.count {
            let sum = resDigits[i] + addCarry
            resDigits[i] = sum % BigInt.base
            addCarry = sum / BigInt.base
            if addCarry == 0 { break }
        }
        if addCarry > 0 { resDigits.append(addCarry) }
        res.digits = resDigits
        res.trim()
        return res
    }

    func absVal() -> BigInt {
        var res = self
        res.isNegative = false
        return res
    }

    var description: String {
        if digits == [0] { return "0" }
        var res = isNegative ? "-" : ""
        res += String(digits.last!)
        for i in (0..<digits.count - 1).reversed() {
            let s = String(digits[i])
            res += String(repeating: "0", count: 9 - s.count) + s
        }
        return res
    }
}

struct DecimalValue {
    var value: BigInt
    var scale: Int
    init(string: String) {
        var s = string.trimmingCharacters(in: .whitespaces)
        if let dotIndex = s.firstIndex(of: ".") {
            let integerPart = String(s[..<dotIndex])
            let fractionalPart = String(s[s.index(after: dotIndex)...])
            self.scale = fractionalPart.count
            self.value = BigInt(string: integerPart + fractionalPart)
        } else {
            self.scale = 0
            self.value = BigInt(string: s)
        }
    }
    init(value: BigInt, scale: Int) {
        self.value = value
        self.scale = scale
    }
    func rounded(toMinorUnits m: Int) -> BigInt {
        var v = self.value
        var s = self.scale
        if s <= m {
            var res = v
            for _ in 0..<(m - s) { res = res * 10 }
            return res
        } else {
            let diff = s - m
            var divisor = BigInt(integerLiteral: 1)
            for _ in 0..<diff { divisor = divisor * 10 }
            let (q, r) = v.divmod(divisor)
            let rAbs = r.absVal()
            let qAbs = q.absVal()
            var qRounded = qAbs
            let half = divisor.divmod(BigInt(integerLiteral: 2)).quotient
            let rS = BigInt.compareAbs(rAbs, half)
            if rS > 0 {
                qRounded = qRounded + 1
            } else if rS == 0 {
                if BigInt.compareAbs(qAbs.divmod(BigInt(integerLiteral: 2)).remainder, BigInt(integerLiteral: 1)) == 0 {
                    qRounded = qRounded + 1
                }
            }
            return v.isNegative ? -qRounded : qRounded
        }
    }
}

struct Account {
    let currencyCode: String
    var balance: BigInt
    var limit: BigInt
}

func format(balance: BigInt, minorUnits: Int) -> String {
    var b = balance.absVal()
    var s = b.description
    if s.count <= minorUnits {
        s = String(repeating: "0", count: minorUnits + 1 - s.count) + s
    }
    let splitIdx = s.index(s.endIndex, offsetBy: -minorUnits)
    let integerPart = String(s[..<splitIdx])
    let fractionalPart = String(s[splitIdx...])
    var formattedInteger = ""
    let chars = Array(integerPart)
    for i in 0..<chars.count {
        if i > 0 && (chars.count - i) % 3 == 0 { formattedInteger += "," }
        formattedInteger += String(chars[i])
    }
    let sign = (balance.isNegative && balance != BigInt(integerLiteral: 0)) ? "-" : ""
    if minorUnits > 0 {
        return "\(sign)\(formattedInteger).\(fractionalPart)"
    } else {
        return "\(sign)\(formattedInteger)"
    }
}

func solve() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let directory = args[1]
    let filePath = (directory as NSString).appendingPathComponent("ledger.txt")
    guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else { return }

    let lines = content.components(separatedBy: .newlines)
    var currencies = [String: Int]()
    var accounts = [String: Account]()
    var rejected = [String]()

    for (lineNum, line) in lines.enumerated() {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }

        let parts = trimmed.components(separatedBy: .whitespaces).filter { !$0.isEmpty }
        if parts.isEmpty { continue }
        let command = parts[0]

        switch command {
        case "currency":
            let code = parts[1]
            let units = Int(parts[2]) ?? 0
            currencies[code] = units
        case "open":
            let name = parts[1]
            let code = parts[2]
            let limitDec = parts.count > 3 ? DecimalValue(string: parts[3]) : DecimalValue(string: "0")
            if let units = currencies[code] {
                if accounts[name] != nil {
                    rejected.append("line \(lineNum + 1): REJECT account exists \(name)")
                } else {
                    accounts[name] = Account(currencyCode: code, balance: BigInt(integerLiteral: 0), limit: limitDec.rounded(toMinorUnits: units))
                }
            }
        case "deposit":
            let name = parts[1]
            let amountDec = DecimalValue(string: parts[2])
            if let acc = accounts[name] {
                let rounded = amountDec.rounded(toMinorUnits: currencies[acc.currencyCode]!)
                if rounded <= BigInt(integerLiteral: 0) {
                    rejected.append("line \(lineNum + 1): REJECT non-positive amount")
                } else {
                    accounts[name]!.balance = acc.balance + rounded
                }
            } else {
                rejected.append("line \(lineNum + 1): REJECT unknown account \(name)")
            }
        case "withdraw":
            let name = parts[1]
            let amountDec = DecimalValue(string: parts[2])
            if let acc = accounts[name] {
                let rounded = amountDec.rounded(toMinorUnits: currencies[acc.currencyCode]!)
                if rounded <= BigInt(integerLiteral: 0) {
                    rejected.append("line \(lineNum + 1): REJECT non-positive amount")
                } else if acc.balance - rounded < -acc.limit {
                    rejected.append("line \(lineNum + 1): REJECT insufficient funds \(name)")
                } else {
                    accounts[name]!.balance = acc.balance - rounded
                }
            } else {
                rejected.append("line \(lineNum + 1): REJECT unknown account \(name)")
            }
        case "transfer":
            let from = parts[1]
            let to = parts[2]
            let amountDec = DecimalValue(string: parts[3])
            if let accFrom = accounts[from], let accTo = accounts[to] {
                if accFrom.currencyCode != accTo.currencyCode {
                    rejected.append("line \(lineNum + 1): REJECT currency mismatch")
                } else {
                    let rounded = amountDec.rounded(toMinorUnits: currencies[accFrom.currencyCode]!)
                    if rounded <= BigInt(integerLiteral: 0) {
                        rejected.append("line \(lineNum + 1): REJECT non-positive amount")
                    } else if accFrom.balance - rounded < -accFrom.limit {
                        rejected.append("line \(lineNum + 1): REJECT insufficient funds \(from)")
                    } else {
                        accounts[from]!.balance = accFrom.balance - rounded
                        accounts[to]!.balance = accTo.balance + rounded
                    }
                }
            } else {
                let unknown = accounts[from] == nil ? from : to
                rejected.append("line \(lineNum + 1): REJECT unknown account \(unknown)")
            }
        case "convert":
            let from = parts[1]
            let to = parts[2]
            let amountDec = DecimalValue(string: parts[3])
            let rateDec = DecimalValue(string: parts[4])
            if let accFrom = accounts[from], let accTo = accounts[to] {
                let roundedFrom = amountDec.rounded(toMinorUnits: currencies[accFrom.currencyCode]!)
                if roundedFrom <= BigInt(integerLiteral: 0) {
                    rejected.append("line \(lineNum + 1): REJECT non-positive amount")
                } else if accFrom.balance - roundedFrom < -accFrom.limit {
                    rejected.append("line \(lineNum + 1): REJECT insufficient funds \(from)")
                } else {
                    let toUnits = currencies[accTo.currencyCode]!
                    let resDec = DecimalValue(value: roundedFrom * rateDec.value, scale: rateDec.scale + currencies[accFrom.currencyCode]!)
                    let toRounded = resDec.rounded(toMinorUnits: toUnits)
                    accounts[from]!.balance = accFrom.balance - roundedFrom
                    accounts[to]!.balance = accTo.balance + toRounded
                }
            } else {
                let unknown = accounts[from] == nil ? from : to
                rejected.append("line \(lineNum + 1): REJECT unknown account \(unknown)")
            }
        case "interest":
            let name = parts[1]
            let rateDec = DecimalValue(string: parts[2])
            if let acc = accounts[name] {
                let resDec = DecimalValue(value: acc.balance * rateDec.value, scale: rateDec.scale + currencies[acc.currencyCode]!)
                let roundedInterest = resDec.rounded(toMinorUnits: currencies[acc.currencyCode]!)
                accounts[name]!.balance = acc.balance + roundedInterest
            } else {
                rejected.append("line \(lineNum + 1): REJECT unknown account \(name)")
            }
        case "split":
            let from = parts[1]
            let amountDec = DecimalValue(string: parts[2])
            var targets = [(name: String, weight: Int)]()
            for i in 3..<parts.count {
                let targetParts = parts[i].components(separatedBy: ":")
                targets.append((targetParts[0], Int(targetParts[1]) ?? 0))
            }
            if let accFrom = accounts[from] {
                let roundedAmount = amountDec.rounded(toMinorUnits: currencies[accFrom.currencyCode]!)
                if roundedAmount <= BigInt(integerLiteral: 0) {
                    rejected.append("line \(lineNum + 1): REJECT non-positive amount")
                } else {
                    var possible = true
                    for target in targets {
                        if let accTo = accounts[target.name] {
                            if accTo.currencyCode != accFrom.currencyCode {
                                possible = false; break
                            }
                        } else {
                            rejected.append("line \(lineNum + 1): REJECT unknown account \(target.name)")
                            possible = false; break
                        }
                    }
                    if possible {
                        let W = targets.reduce(0) { $0 + $1.weight }
                        var q = [BigInt]()
                        var r = [BigInt]()
                        var totalQ = BigInt(integerLiteral: 0)
                        for t in targets {
                            let (quot, rem) = (roundedAmount * BigInt(integerLiteral: t.weight)).divmod(BigInt(integerLiteral: W))
                            q.append(quot)
                            r.append(rem)
                            totalQ = totalQ + quot
                        }
                        var diff = roundedAmount - totalQ
                        var indices = Array(0..<targets.count)
                        indices.sort { i, j in
                            let cmp = BigInt.compareAbs(r[i], r[j])
                            if cmp != 0 { return cmp > 0 }
                            return i < j
                        }
                        var idx = 0
                        while diff > BigInt(integerLiteral: 0) {
                            q[indices[idx % targets.count]] = q[indices[idx % targets.count]] + BigInt(integerLiteral: 1)
                            diff = diff - BigInt(integerLiteral: 1)
                            idx += 1
                        }
                        accounts[from]!.balance = accFrom.balance - roundedAmount
                        for i in 0..<targets.count {
                            accounts[targets[i].name]!.balance = accounts[targets[i].name]!.balance + q[i]
                        }
                    }
                }
            } else {
                rejected.append("line \(lineNum + 1): REJECT unknown account \(from)")
            }
        default: break
        }
    }

    for r in rejected { print(r) }
    print("")
    let sortedAccNames = accounts.keys.sorted()
    for name in sortedAccNames {
        let acc = accounts[name]!
        print("\(name) \(acc.currencyCode) \(format(balance: acc.balance, minorUnits: currencies[acc.currencyCode]!))")
    }
    print("")
    let sortedCodes = currencies.keys.sorted()
    for code in sortedCodes {
        let accsWithCode = accounts.values.filter { $0.currencyCode == code }
        if accsWithCode.isEmpty { continue }
        var totalBalance = BigInt(integerLiteral: 0)
        for acc in accsWithCode {
            totalBalance = totalBalance + acc.balance
        }
        print("total \(code) \(format(balance: totalBalance, minorUnits: currencies[code]!)) (\(accsWithCode.count) accounts)")
    }
}

solve()

use std::env;
use std::fs::File;
use std::io::{self, BufRead, Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::time::SystemTime;

struct Rng(u64);
impl Rng {
    fn next_u16(&mut self) -> u16 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 & 0xFFFF) as u16
    }
}

fn read_name(data: &[u8], start_offset: usize) -> (String, usize) {
    let mut labels = Vec::new();
    let mut curr = start_offset;
    let mut jumped = false;
    let mut next_offset = 0;

    loop {
        if curr >= data.len() {
            break;
        }
        let len = data[curr];
        if len == 0 {
            curr += 1;
            if !jumped {
                next_offset = curr;
            }
            break;
        } else if (len & 0xC0) == 0xC0 {
            if curr + 1 >= data.len() {
                break;
            }
            let ptr = (((len & 0x3F) as usize) << 8) | (data[curr + 1] as usize);
            if !jumped {
                next_offset = curr + 2;
            }
            curr = ptr;
            jumped = true;
        } else {
            curr += 1;
            if curr + (len as usize) > data.len() {
                break;
            }
            let label = &data[curr..curr + (len as usize)];
            let s: String = label.iter().map(|&b| b as char).collect();
            labels.push(s.to_lowercase());
            curr += len as usize;
        }
    }
    let res = labels.join(".");
    (res, if jumped { next_offset } else { curr })
}

fn format_ipv6(addr: [u8; 16]) -> String {
    let mut words = [0u16; 8];
    for i in 0..8 {
        words[i] = u16::from_be_bytes([addr[2 * i], addr[2 * i + 1]]);
    }
    let (best_start, best_len) = {
        let mut bs = 0;
        let mut bl = 0;
        let mut cs = 0;
        let mut cl = 0;
        for i in 0..8 {
            if words[i] == 0 {
                if cl == 0 {
                    cs = i;
                }
                cl += 1;
            } else {
                if cl > bl {
                    bl = cl;
                    bs = cs;
                }
                cs = i + 1;
                cl = 0;
            }
        }
        if cl > bl {
            bl = cl;
            bs = cs;
        }
        (bs, bl)
    };

    let mut res = String::new();
    let mut i = 0;
    while i < 8 {
        if i == best_start && best_len >= 2 {
            res.push_str("::");
            i += best_len;
        } else {
            res.push_str(&format!("{:x}", words[i]));
            i += 1;
            if i < 8 && (i != best_start || best_len < 2) {
                res.push(':');
            }
        }
    }
    if res.ends_with(':') && !res.ends_with("::") {
        res.pop();
    }
    res
}

fn format_txt(data: &[u8]) -> String {
    let mut res = String::new();
    let mut curr = 0;
    let mut first = true;
    while curr < data.len() {
        if !first {
            res.push(' ');
        }
        first = false;
        let len = data[curr] as usize;
        curr += 1;
        res.push('"');
        for i in 0..len {
            if i >= data.len() - curr {
                break;
            }
            let b = data[curr + i];
            if b == b'"' {
                res.push_str("\\\"");
            } else if b == b'\\' {
                res.push_str("\\\\");
            } else if (0x20..=0x7E).contains(&b) {
                res.push(b as char);
            } else {
                res.push_str(&format!("\\{:03}", b));
            }
        }
        res.push('"');
        curr += len;
    }
    res
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        return;
    }
    let dir = &args[1];
    let port = &args[2];

    let queries_path = format!("{}/queries.txt", dir);
    let file = match File::open(queries_path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = io::BufReader::new(file);

    let mut rng = Rng(SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64);

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() < 2 {
            continue;
        }
        let qname_raw = parts[0];
        let qtype_str = parts[1];

        let qtype = match qtype_str {
            "A" => 1,
            "CNAME" => 5,
            "MX" => 15,
            "TXT" => 16,
            "AAAA" => 28,
            _ => 0,
        };

        let mut packet = Vec::new();
        let id = rng.next_u16();
        packet.extend_from_slice(&id.to_be_bytes());
        packet.extend_from_slice(&0x0100u16.to_be_bytes());
        packet.extend_from_slice(&1u16.to_be_bytes()); // QDCOUNT
        packet.extend_from_slice(&0u16.to_be_bytes()); // ANCOUNT
        packet.extend_from_slice(&0u16.to_be_bytes()); // NSCOUNT
        packet.extend_from_slice(&0u16.to_be_bytes()); // ARCOUNT

        let labels: Vec<&str> = qname_raw.split('.').filter(|s| !s.is_empty()).collect();
        for label in labels {
            packet.push(label.len() as u8);
            packet.extend_from_slice(label.as_bytes());
        }
        packet.push(0);
        packet.extend_from_slice(&qtype.to_be_bytes());
        packet.extend_from_slice(&1u16.to_be_bytes()); // CLASS IN

        let server_addr = format!("127.0.0.1:{}", port);
        let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
        socket.send_to(&packet, &server_addr).unwrap();

        let mut buf = [0u8; 4096];
        loop {
            let (amt, _) = socket.recv_from(&mut buf).unwrap();
            let resp = &buf[..amt];
            if resp.len() < 12 {
                continue;
            }
            let resp_id = u16::from_be_bytes([resp[0], resp[1]]);
            let flags = u16::from_be_bytes([resp[2], resp[3]]);
            if resp_id != id || (flags & 0x8000) == 0 {
                continue;
            }

            let tc = (flags & 0x0200) != 0;
            if tc {
                let mut stream = TcpStream::connect(&server_addr).unwrap();
                let mut tcp_send = Vec::new();
                tcp_send.extend_from_slice(&(packet.len() as u16).to_be_bytes());
                tcp_send.extend_from_slice(&packet);
                stream.write_all(&tcp_send).unwrap();

                let mut len_buf = [0u8; 2];
                stream.read_exact(&mut len_buf).unwrap();
                let len = u16::from_be_bytes(len_buf) as usize;
                let mut resp_data = vec![0u8; len];
                stream.read_exact(&mut resp_data).unwrap();
                process_response(qname_raw, qtype_str, &resp_data);
                break;
            } else {
                process_response(qname_raw, qtype_str, resp);
                break;
            }
        }
    }
}

fn process_response(qname: &str, qtype_str: &str, data: &[u8]) {
    if data.len() < 12 {
        return;
    }
    let flags = u16::from_be_bytes([data[2], data[3]]);
    let qdcount = u16::from_be_bytes([data[4], data[5]]) as usize;
    let ancount = u16::from_be_bytes([data[6], data[7]]) as usize;
    let rcode = flags & 0x000F;

    let rcode_str = match rcode {
        0 => "NOERROR",
        1 => "FORMERR",
        2 => "SERVFAIL",
        3 => "NXDOMAIN",
        4 => "NOTIMP",
        5 => "REFUSED",
        n => {
            let mut s = String::new();
            s.push_str("RCODE");
            s.push_str(&n.to_string());
            s
        }
    };

    let mut qname_clean = qname.to_lowercase();
    if qname_clean.ends_with('.') {
        qname_clean.pop();
    }

    println!("{} {} {}", qname_clean, qtype_str, rcode_str);

    let mut offset = 12;
    for _ in 0..qdcount {
        let (_, next_offset) = read_name(data, offset);
        offset = next_offset + 4;
    }

    for _ in 0..ancount {
        let (owner, next_offset) = read_name(data, offset);
        offset = next_offset;
        let type_raw = u16::from_be_bytes([data[offset], data[offset + 1]]);
        let _class = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
        let ttl = u32::from_be_bytes([data[offset + 4], data[offset + 5], data[offset + 6], data[offset + 7]]);
        let rdlen = u16::from_be_bytes([data[offset + 8], data[offset + 9]]) as usize;
        offset += 10;

        let rdata = &data[offset..offset + rdlen];
        offset += rdlen;

        let owner_fmt = if owner.is_empty() { ".".to_string() } else { owner };
        let type_fmt = match type_raw {
            1 => "A",
            5 => "CNAME",
            15 => "MX",
            16 => "TXT",
            28 => "AAAA",
            n => {
                let mut s = String::new();
                s.push_str("TYPE");
                s.push_str(&n.to_string());
                s
            }
        };

        let data_fmt = match type_raw {
            1 => {
                let bytes = rdata;
                format!("{}.{}.{}.{}", bytes[0], bytes[1], bytes[2], bytes[3])
            }
            5 => {
                let (name, _) = read_name(data, offset - rdlen);
                let name_fmt = if name.is_empty() { ".".to_string() } else { name };
                name_fmt
            }
            15 => {
                let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
                let (name, _) = read_name(data, offset - rdlen + 2);
                let name_fmt = if name.is_empty() { ".".to_string() } else { name };
                format!("{} {}", pref, name_fmt)
            }
            16 => format_txt(rdata),
            28 => {
                let mut bytes = [0u8; 16];
                bytes.copy_from_slice(rdata);
                format_ipv6(bytes)
            }
            n => {
                let mut hex = String::new();
                for &b in rdata {
                    hex.push_str(&format!("{:02x}", b));
                }
                format!("# {} {}", n, rdlen, hex)
            }
        };
        // Special case for "Other" type data formatting (removing extra space if rdlen is 0)
        let data_fmt_final = if type_raw != 1 && type_raw != 5 && type_raw != 15 && type_raw != 16 && type_raw != 28 {
            if rdlen == 0 {
                let mut s = String::new();
                s.push_str("# 0");
                s
            } else {
                data_fmt
            }
        } else {
            data_fmt
        };

        println!("  {} {} {} {}", owner_fmt, ttl, type_fmt, data_fmt_final);
    }
}

use std::env;
use std::fs::File;
use std::io::{self, BufRead, Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::time::SystemTime;

struct Rng(u64);
impl Rng {
    fn next_u16(&mut self) -> u16 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 & 0xFFFF) as u16
    }
}

fn read_name(data: &[u8], start_offset: usize) -> (String, usize) {
    let mut labels = Vec::new();
    let mut curr = start_offset;
    let mut jumped = false;
    let mut next_offset = 0;

    loop {
        if curr >= data.len() {
            break;
        }
        let len = data[curr];
        if len == 0 {
            curr += 1;
            if !jumped {
                next_offset = curr;
            }
            break;
        } else if (len & 0xC0) == 0xC0 {
            if curr + 1 >= data.len() {
                break;
            }
            let ptr = (((len & 0x3F) as usize) << 8) | (data[curr + 1] as usize);
            if !jumped {
                next_offset = curr + 2;
            }
            curr = ptr;
            jumped = true;
            if curr >= data.len() {
                break;
            }
        } else {
            curr += 1;
            if curr + (len as usize) > data.len() {
                break;
            }
            let label = &data[curr..curr + (len as usize)];
            let s: String = label.iter().map(|&b| b as char).collect();
            labels.push(s.to_lowercase());
            curr += len as usize;
        }
    }
    let res = labels.join(".");
    (res, if jumped { next_offset } else { curr })
}

fn format_ipv6(addr: [u8; 16]) -> String {
    let mut words = [0u16; 8];
    for i in 0..8 {
        words[i] = u16::from_be_bytes([addr[2 * i], addr[2 * i + 1]]);
    }
    let (best_start, best_len) = {
        let mut bs = 0;
        let mut bl = 0;
        let mut cs = 0;
        let mut cl = 0;
        for i in 0..8 {
            if words[i] == 0 {
                if cl == 0 {
                    cs = i;
                }
                cl += 1;
            } else {
                if cl > bl {
                    bl = cl;
                    bs = cs;
                }
                cs = i + 1;
                cl = 0;
            }
        }
        if cl > bl {
            bl = cl;
            bs = cs;
        }
        (bs, bl)
    };

    let mut res = String::new();
    let mut i = 0;
    while i < 8 {
        if i == best_start && best_len >= 2 {
            res.push_str("::");
            i += best_len;
        } else {
            res.push_str(&format!("{:x}", words[i]));
            i += 1;
            if i < 8 && (i != best_start || best_len < 2) {
                res.push(':');
            }
        }
    }
    if res.ends_with(':') && !res.ends_with("::") {
        res.pop();
    }
    res
}

fn format_txt(data: &[u8]) -> String {
    let mut res = String::new();
    let mut curr = 0;
    let mut first = true;
    while curr < data.len() {
        if !first {
            res.push(' ');
        }
        first = false;
        let len = data[curr] as usize;
        curr += 1;
        res.push('"');
        for i in 0..len {
            if curr + i >= data.len() {
                break;
            }
            let b = data[curr + i];
            if b == b'"' {
                res.push_str("\\\"");
            } else if b == b'\\' {
                res.push_str("\\\\");
            } else if (0x20..=0x7E).contains(&b) {
                res.push(b as char);
            } else {
                res.push_str(&format!("\\{:03}", b));
            }
        }
        res.push('"');
        curr += len;
    }
    res
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        return;
    }
    let dir = &args[1];
    let port = &args[2];

    let queries_path = format!("{}/queries.txt", dir);
    let file = match File::open(queries_path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = io::BufReader::new(file);

    let mut rng = Rng(SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64);

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() < 2 {
            continue;
        }
        let qname_raw = parts[0];
        let qtype_str = parts[1];

        let qtype: u16 = match qtype_str {
            "A" => 1,
            "CNAME" => 5,
            "MX" => 15,
            "TXT" => 16,
            "AAAA" => 28,
            _ => 0,
        };

        let mut packet = Vec::new();
        let id = rng.next_u16();
        packet.extend_from_slice(&id.to_be_bytes());
        packet.extend_from_slice(&0x0100u16.to_be_bytes());
        packet.extend_from_slice(&1u16.to_be_bytes()); // QDCOUNT
        packet.extend_from_slice(&0u16.to_be_bytes()); // ANCOUNT
        packet.extend_from_slice(&0u16.to_be_bytes()); // NSCOUNT
        packet.extend_from_slice(&0u16.to_be_bytes()); // ARCOUNT

        let labels: Vec<&str> = qname_raw.split('.').filter(|s| !s.is_empty()).collect();
        for label in labels {
            packet.push(label.len() as u8);
            packet.extend_from_slice(label.as_bytes());
        }
        packet.push(0);
        packet.extend_from_slice(&qtype.to_be_bytes());
        packet.extend_from_slice(&1u16.to_be_bytes()); // CLASS IN

        let server_addr = format!("127.0.0.1:{}", port);
        let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
        socket.send_to(&packet, &server_addr).unwrap();

        let mut buf = [0u8; 8192];
        loop {
            let (amt, _) = socket.recv_from(&mut buf).unwrap();
            let resp = &buf[..amt];
            if resp.len() < 12 {
                continue;
            }
            let resp_id = u16::from_be_bytes([resp[0], resp[1]]);
            let flags = u16::from_be_bytes([resp[2], resp[3]]);
            if resp_id != id || (flags & 0x8000) == 0 {
                continue;
            }

            let tc = (flags & 0x0200) != 0;
            if tc {
                let mut stream = TcpStream::connect(&server_addr).unwrap();
                let mut tcp_send = Vec::new();
                tcp_send.extend_from_slice(&(packet.len() as u16).to_be_bytes());
                tcp_send.extend_from_slice(&packet);
                stream.write_all(&tcp_send).unwrap();

                let mut len_buf = [0u8; 2];
                stream.read_exact(&mut len_buf).unwrap();
                let len = u16::from_be_bytes(len_buf) as usize;
                let mut resp_data = vec![0u8; len];
                stream.read_exact(&mut resp_data).unwrap();
                process_response(qname_raw, qtype_str, &resp_data);
                break;
            } else {
                process_response(qname_raw, qtype_str, resp);
                break;
            }
        }
    }
}

fn process_response(qname: &str, qtype_str: &str, data: &[u8]) {
    if data.len() < 12 {
        return;
    }
    let flags = u16::from_be_bytes([data[2], data[3]]);
    let qdcount = u16::from_be_bytes([data[4], data[5]]) as usize;
    let ancount = u16::from_be_bytes([data[6], data[7]]) as usize;
    let rcode = flags & 0x000F;

    let rcode_str = match rcode {
        0 => "NOERROR".to_string(),
        1 => "FORMERR".to_string(),
        2 => "SERVFAIL".to_string(),
        3 => "NXDOMAIN".to_string(),
        4 => "NOTIMP".to_string(),
        5 => "REFUSED".to_string(),
        n => format!("RCODE{}", n),
    };

    let mut qname_clean = qname.to_lowercase();
    if qname_clean.ends_with('.') {
        qname_clean.pop();
    }

    println!("{} {} {}", qname_clean, qtype_str, rcode_str);

    let mut offset = 12;
    for _ in 0..qdcount {
        let (_, next_offset) = read_name(data, offset);
        offset = next_offset + 4;
    }

    for _ in 0..ancount {
        if offset + 10 > data.len() { break; }
        let (owner, next_offset) = read_name(data, offset);
        offset = next_offset;
        if offset + 10 > data.len() { break; }
        let type_raw = u16::from_be_bytes([data[offset], data[offset + 1]]);
        let _class = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
        let ttl = u32::from_be_bytes([data[offset + 4], data[offset + 5], data[offset + 6], data[offset + 7]]);
        let rdlen = u16::from_be_bytes([data[offset + 8], data[offset + 9]]) as usize;
        offset += 10;

        if offset + rdlen > data.len() { break; }
        let rdata = &data[offset..offset + rdlen];
        offset += rdlen;

        let owner_fmt = if owner.is_empty() { ".".to_string() } else { owner };
        let type_fmt = match type_raw {
            1 => "A".to_string(),
            5 => "CNAME".to_string(),
            15 => "MX".to_string(),
            16 => "TXT".to_string(),
            28 => "AAAA".to_string(),
            n => format!("TYPE{}", n),
        };

        let data_fmt = match type_raw {
            1 => {
                if rdata.len() < 4 { ".".to_string() } else {
                    format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3])
                }
            }
            5 => {
                let (name, _) = read_name(data, offset - rdlen);
                if name.is_empty() { ".".to_string() } else { name }
            }
            15 => {
                if rdata.len() < 2 { "0 .".to_string() } else {
                    let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
                    let (name, _) = read_name(data, offset - rdlen + 2);
                    let name_fmt = if name.is_empty() { ".".to_string() } else { name };
                    format!("{} {}", pref, name_fmt)
                }
            }
            16 => format_txt(rdata),
            28 => {
                if rdata.len() < 16 { "::".to_string() } else {
                    let mut bytes = [0u8; 16];
                    bytes.copy_from_slice(&rdata[..16]);
                    format_ipv6(bytes)
                }
            }
            _ => {
                let mut hex = String::new();
                for &b in rdata {
                    hex.push_str(&format!("{:02x}", b));
                }
                if rdlen == 0 {
                    format!("# 0")
                } else {
                    format!("# {} {}", rdlen, hex)
                }
            }
        };

        println!("  {} {} {} {}", owner_fmt, ttl, type_fmt, data_fmt);
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class Main {

    public static void main(String[] args) {
        if (args.length < 1) return;
        Path dir = Path.of(args[0]);
        try {
            String configContent = Files.readString(dir.resolve("config.json"));
            JsonValue config = JsonParser.parse(configContent);
            if (!(config instanceof JsonObject)) return;
            JsonObject configObj = (JsonObject) config;

            double now = configObj.getDouble("now");
            double leeway = configObj.getDouble("leeway");
            String issuer = configObj.getString("issuer");
            String audience = configObj.getString("audience");
            JsonArray keys = configObj.getArray("keys");

            List<String> tokenLines = Files.readAllLines(dir.resolve("tokens.txt"), StandardCharsets.UTF_8);
            int validCount = 0;
            int invalidCount = 0;
            int lineNum = 1;

            for (String line : tokenLines) {
                String trimmed = line.trim();
                if (trimmed.isEmpty()) continue;

                String result = verifyToken(trimmed, now, leeway, issuer, audience, keys);
                if (result.startsWith("VALID")) {
                    validCount++;
                } else {
                    invalidCount++;
                }
                System.out.println(lineNum + ": " + result);
                lineNum++;
            }

            System.out.println();
            System.out.println("valid=" + validCount + " invalid=" + invalidCount);

        } catch (Exception e) {
            // Silent fail as per problem constraints
        }
    }

    private static String verifyToken(String token, double now, double leeway, String issuer, String audience, JsonArray keys) {
        String[] parts = token.split("\\.", -1);
        if (parts.length != 3) return "MALFORMED";

        byte[][] decoded = new byte[3][];
        for (int i = 0; i < 3; i++) {
            String part = parts[i];
            if (part.isEmpty() || !part.matches("^[A-Za-z0-9-_]*$") || part.length() % 4 == 1) {
                return "MALFORMED";
            }
            try {
                decoded[i] = Base64.getUrlDecoder().decode(part);
            } catch (IllegalArgumentException e) {
                return "MALFORMED";
            }
        }

        JsonValue headerVal, payloadVal;
        try {
            headerVal = JsonParser.parse(new String(decoded[0], StandardCharsets.UTF_8));
            payloadVal = JsonParser.parse(new String(decoded[1], StandardCharsets.UTF_8));
        } catch (Exception e) {
            return "MALFORMED";
        }

        if (!(headerVal instanceof JsonObject) || !(payloadVal instanceof JsonObject)) {
            return "MALFORMED";
        }

        JsonObject header = (JsonObject) headerVal;
        JsonObject payload = (JsonObject) payloadVal;

        // 2. UNSUPPORTED_ALG
        JsonValue algVal = header.get("alg");
        if (!(algVal instanceof JsonString)) return "UNSUPPORTED_ALG";
        String alg = ((JsonString) algVal).value;
        if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512")) {
            return "UNSUPPORTED_ALG";
        }

        // 3. UNKNOWN_KEY
        JsonValue kidVal = header.get("kid");
        if (!(kidVal instanceof JsonString)) return "UNKNOWN_KEY";
        String kid = ((JsonString) kidVal).value;
        JsonObject key = null;
        for (JsonValue kv : keys) {
            JsonObject kObj = (JsonObject) kv;
            if (kid.equals(kObj.getString("kid"))) {
                key = kObj;
                break;
            }
        }
        if (key == null) return "UNKNOWN_KEY";

        // 4. ALG_MISMATCH
        if (!key.getString("alg").equals(alg)) return "ALG_MISMATCH";

        // 5. BAD_SIGNATURE
        try {
            String hmacAlg = alg.replace("HS", "HmacSHA");
            Mac mac = Mac.getInstance(hmacAlg);
            byte[] secret = Base64.getUrlDecoder().decode(key.getString("k"));
            mac.init(new SecretKeySpec(secret, hmacAlg));
            String signingInput = parts[0] + "." + parts[1];
            byte[] signature = mac.doFinal(signingInput.getBytes(StandardCharsets.US_ASCII));
            if (!MessageDigest.isEqual(signature, decoded[2])) return "BAD_SIGNATURE";
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        // 6. EXPIRED
        JsonValue expVal = payload.get("exp");
        if (expVal instanceof JsonNumber) {
            if (now >= ((JsonNumber) expVal).value + leeway) return "EXPIRED";
        }

        // 7. NOT_YET_VALID
        JsonValue nbfVal = payload.get("nbf");
        if (nbfVal instanceof JsonNumber) {
            if (now + leeway < ((JsonNumber) nbfVal).value) return "NOT_YET_VALID";
        }

        // 8. BAD_ISSUER
        JsonValue issVal = payload.get("iss");
        if (!(issVal instanceof JsonString) || !((JsonString) issVal).value.equals(issuer)) {
            return "BAD_ISSUER";
        }

        // 9. BAD_AUDIENCE
        JsonValue audVal = payload.get("aud");
        if (audVal instanceof JsonString) {
            if (!((JsonString) audVal).value.equals(audience)) return "BAD_AUDIENCE";
        } else if (audVal instanceof JsonArray) {
            boolean found = false;
            for (JsonValue av : (JsonArray) audVal) {
                if (av instanceof JsonString && ((JsonString) av).value.equals(audience)) {
                    found = true;
                    break;
                }
            }
            if (!found) return "BAD_AUDIENCE";
        } else {
            return "BAD_AUDIENCE";
        }

        // VALID
        String sub = payload.getString("sub");
        JsonValue scopeVal = payload.get("scope");
        String scopes = "";
        if (scopeVal instanceof JsonString) {
            String scopeStr = ((JsonString) scopeVal).value;
            String[] partsS = scopeStr.split(" ");
            Set<String> distinctScopes = new TreeSet<>();
            for (String s : partsS) {
                if (!s.isEmpty()) distinctScopes.add(s);
            }
            scopes = String.join(",", distinctScopes);
        }

        return "VALID sub=" + sub + " scope=" + scopes;
    }

    // Simple JSON Parser implementation
    static class JsonParser {
        static JsonValue parse(String input) {
            return new Parser(input).parseValue();
        }

        static class Parser {
            int pos = 0;
            String s;
            Parser(String s) { this.s = s; }
            char peek() { return pos < s.length() ? s.charAt(pos) : '\0'; }
            char next() { return s.charAt(pos++); }
            void skipWhitespace() { while (pos < s.length() && Character.isWhitespace(peek())) pos++; }

            JsonValue parseValue() {
                skipWhitespace();
                char c = peek();
                if (c == '{') return parseObject();
                if (c == '[') return parseArray();
                if (c == '"') return parseString();
                if (c == '-' || Character.isDigit(c)) return parseNumber();
                if (s.startsWith("true", pos)) { pos += 4; return new JsonBoolean(true); }
                if (s.startsWith("false", pos)) { pos += 5; return new JsonBoolean(false); }
                if (s.startsWith("null", pos)) { pos += 4; return new JsonNull(); }
                throw new RuntimeException("Unexpected char: " + c);
            }

            JsonObject parseObject() {
                next(); // {
                Map<String, JsonValue> map = new LinkedHashMap<>();
                skipWhitespace();
                if (peek() == '}') { next(); return new JsonObject(map); }
                while (true) {
                    skipWhitespace();
                    String key = parseString().value;
                    skipWhitespace();
                    next(); // :
                    map.put(key, parseValue());
                    skipWhitespace();
                    if (peek() == '}') { next(); break; }
                    next(); // ,
                }
                return new JsonObject(map);
            }

            JsonArray parseArray() {
                next(); // [
                List<JsonValue> list = new ArrayList<>();
                skipWhitespace();
                if (peek() == ']') { next(); return new JsonArray(list); }
                while (true) {
                    list.add(parseValue());
                    skipWhitespace();
                    if (peek() == ']') { next(); break; }
                    next(); // ,
                }
                return new JsonArray(list);
            }

            JsonString parseString() {
                next(); // "
                StringBuilder sb = new StringBuilder();
                while (peek() != '"') {
                    char c = next();
                    if (c == '\\') {
                        char esc = next();
                        switch (esc) {
                            case '"' -> sb.append('"');
                            case '\\' -> sb.append('\\');
                            case '/' -> sb.append('/');
                            case 'b' -> sb.append('\b');
                            case 'f' -> sb.append('\f');
                            case 'n' -> sb.append('\n');
                            case 'r' -> sb.append('\r');
                            case 't' -> sb.append('\t');
                            case 'u' -> {
                                String hex = s.substring(pos, pos + 4);
                                sb.append((char) Integer.parseInt(hex, 16));
                                pos += 4;
                            }
                        }
                    } else sb.append(c);
                }
                next(); // "
                return new JsonString(sb.toString());
            }

            JsonNumber parseNumber() {
                StringBuilder sb = new StringBuilder();
                if (peek() == '-') sb.append(next());
                while (Character.isDigit(peek()) || peek() == '.') sb.append(next());
                return new JsonNumber(Double.parseDouble(sb.toString()));
            }
        }
    }

    interface JsonValue {}
    static class JsonObject implements JsonValue {
        Map<String, JsonValue> members;
        JsonObject(Map<String, JsonValue> m) { members = m; }
        JsonValue get(String key) { return members.get(key); }
        String getString(String key) {
            JsonValue v = get(key);
            return (v instanceof JsonString) ? ((JsonString) v).value : null;
        }
        double getDouble(String key) {
            JsonValue v = get(key);
            return (v instanceof JsonNumber) ? ((JsonNumber) v).value : 0;
        }
        JsonArray getArray(String key) {
            JsonValue v = get(key);
            return (v instanceof JsonArray) ? (JsonArray) v : null;
        }
    }
    static class JsonArray implements JsonValue {
        List<JsonValue> elements;
        JsonArray(List<JsonValue> e) { elements = e; }
        Iterable<JsonValue> iterator() { return elements; }
        public java.util.Iterator<JsonValue> iterator() { return elements.iterator(); }
    }
    static class JsonString implements JsonValue {
        String value;
        JsonString(String v) { value = v; }
    }
    static class JsonNumber implements JsonValue {
        double value;
        JsonNumber(double v) { value = v; }
    }
    static class JsonBoolean implements JsonValue {
        boolean value;
        JsonBoolean(boolean v) { value = v; }
    }
    static class JsonNull implements JsonValue {}
}

// Helper for MessageDigest.isEqual
class MessageDigest {
    public static boolean isEqual(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) result |= (a[i] ^ b[i]);
        return result == 0;
    }
}

