/**
 * Decodes a JSON Pointer token.
 * ~1 is decoded to / and ~0 is decoded to ~.
 */
function decodePointer(token: string): string {
    let result = "";
    for (let i = 0; i < token.length; i++) {
        if (token[i] === '~' && i + 1 < token.length) {
            if (token[i + 1] === '0') {
                result += '~';
                i++;
            } else if (token[i + 1] === '1') {
                result += '/';
                i++;
            } else {
                result += token[i];
            }
        } else {
            result += token[i];
        }
    }
    return result;
}

/**
 * Encodes a JSON Pointer path into a string.
 */
function encodePointer(tokens: string[]): string {
    if (tokens.length === 0) return "#";
    return "#" + tokens.map(t => t.replace(/~/g, "~0").replace(/\//g, "~1")).join("/");
}

