    // Array keywords
    if (type === 'array') {
        if ('minItems' in schema && instance.length < schema.minItems) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'minItems'])}`);
        }
        if ('maxItems' in schema && instance.length > schema.maxItems) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'maxItems'])}`);
        }
        if ('uniqueItems' in schema && schema.uniqueItems === true) {
            let unique = true;
            for (let i = 0; i < instance.length; i++) {
                for (let j = i + 1; j < instance.length; j++) {
                    if (deepEqual(instance[i], instance[j])) {
                        unique = false;
                        break;
                    }
                }
                if (!unique) break;
            }
            if (!unique) {
                errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'uniqueItems'])}`);
            }
        }
        if ('prefixItems' in schema) {
            const prefixItems = schema.prefixItems;
            for (let i = 0; i < prefixItems.length && i < instance.length; i++) {
                validate(instance[i], prefixItems[i], [...instanceLoc, i.toString()], [...schemaLoc, 'prefixItems', i.toString()], rootSchema, errors);
            }
        }
        if ('items' in schema) {
            const itemsSchema = schema.items;
            const start = 'prefixItems' in schema ? schema.prefixItems.length : 0;
            for (let i = start; i < instance.length; i++) {
                validate(instance[i], itemsSchema, [...instanceLoc, i.toString()], [...schemaLoc, 'items'], rootSchema, errors);
            }
        }
    }

    // Object keywords
    if (type === 'object') {
        if ('minProperties' in schema && Object.keys(instance).length < schema.minProperties) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'minProperties'])}`);
        }
        if ('maxProperties' in schema && Object.keys(instance).length > schema.maxProperties) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'maxProperties'])}`);
        }
        if ('required' in schema) {
            for (const req of schema.required) {
                if (!(req in instance)) {
                    errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'required', req])}`);
                }
            }
        }
        if ('properties' in schema) {
            for (const key in schema.properties) {
                if (key in instance) {
                    validate(instance[key], schema.properties[key], [...instanceLoc, key], [...schemaLoc, 'properties', key], rootSchema, errors);
                }
            }
        }
        if ('additionalProperties' in schema) {
            const addPropSchema = schema.additionalProperties;
            for (const key in instance) {
                const isProperty = 'properties' in schema && key in schema.properties;
                if (!isProperty) {
                    validate(instance[key], addPropSchema, [...instanceLoc, key], [...schemaLoc, 'additionalProperties'], rootSchema, errors);
                }
            }
        }
    }

    // Applicators
    if ('allOf' in schema) {
        for (let i = 0; i < schema.allOf.length; i++) {
            validate(instance, schema.allOf[i], instanceLoc, [...schemaLoc, 'allOf', i.toString()], rootSchema, errors);
        }
    }
    if ('anyOf' in schema) {
        let anyAccepts = false;
        for (const subSchema of schema.anyOf) {
            const subErrors = new Set<string>();
            validate(instance, subSchema, instanceLoc, [], rootSchema, subErrors);
            if (subErrors.size === 0) {
                anyAccepts = true;
                break;
            }
        }
        if (!anyAccepts) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'anyOf'])}`);
        }
    }
    if ('oneOf' in schema) {
        let count = 0;
        for (const subSchema of schema.oneOf) {
            const subErrors = new Set<string>();
            validate(instance, subSchema, instanceLoc, [], rootSchema, subErrors);
            if (subErrors.size === 0) {
                count++;
            }
        }
        if (count !== 1) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'oneOf'])}`);
        }
    }
    if ('not' in schema) {
        const subErrors = new Set<string>();
        validate(instance, schema.not, instanceLoc, [], rootSchema, subErrors);
        if (subErrors.size === 0) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'not'])}`);
        }
    }
    if ('if' in schema) {
        const ifErrors = new Set<string>();
        validate(instance, schema.if, instanceLoc, [], rootSchema, ifErrors);
        if (ifErrors.size === 0) {
            if ('then' in schema) {
                validate(instance, schema.then, instanceLoc, [...schemaLoc, 'then'], rootSchema, errors);
            }
        } else {
            if ('else' in schema) {
                validate(instance, schema.else, instanceLoc, [...schemaLoc, 'else'], rootSchema, errors);
            }
        }
    }
    if ('$ref' in schema) {
        const { schema: refSchema, loc: refLoc } = resolveRef(schema.$ref, rootSchema);
        validate(instance, refSchema, instanceLoc, refLoc, rootSchema, errors);
    }
}

function main() {
    const dir = process.argv[2];
    if (!dir) return;
    const schema = JSON.parse(fs.readFileSync(path.join(dir, 'schema.json'), 'utf-8'));
    const instances = JSON.parse(fs.readFileSync(path.join(dir, 'instances.json'), 'utf-8'));

    let validCount = 0;
    let invalidCount = 0;

    instances.forEach((instance, index) => {
        const errors = new Set<string>();
        validate(instance, schema, [], [], schema, errors);
        if (errors.size === 0) {
            process.stdout.write(`${index}: valid\n`);
            validCount++;
        } else {
            process.stdout.write(`${index}: invalid (${errors.size})\n`);
            const sortedErrors = Array.from(errors).sort();
            sortedErrors.forEach(err => {
                process.stdout.write(`  ${err}\n`);
            });
            invalidCount++;
        }
    });

    process.stdout.write(`valid=${validCount} invalid=${invalidCount}\n`);
}

main();

import * as fs from 'fs';
import * as path from 'path';

/**
 * Decodes a JSON Pointer token.
 * ~1 is decoded to / and ~0 is decoded to ~.
 */
function decodePointer(token: string): string {
    let result = "";
    for (let i = 0; i < token.length; i++) {
        if (token[i] === '~' && i + 1 < token.length) {
            if (token[i + 1] === '0') {
                result += '~';
                i++;
            } else if (token[i + 1] === '1') {
                result += '/';
                i++;
            } else {
                result += token[i];
            }
        } else {
            result += token[i];
        }
    }
    return result;
}

/**
 * Encodes a JSON Pointer path into a string.
 * Root is "#", others start with "#/".
 */
function encodePointer(tokens: string[]): string {
    if (tokens.length === 0) return "#";
    return "#/" + tokens.map(t => t.replace(/~/g, "~0").replace(/\//g, "~1")).join("/");
}

/**
 * Checks for deep equality between two JSON values.
 */
function deepEqual(a: any, b: any): boolean {
    if (typeof a !== typeof b) return false;
    if (a === null || b === null) return a === b;
    if (typeof a === 'number' || typeof a === 'string' || typeof a === 'boolean') return a === b;
    if (Array.isArray(a)) {
        if (!Array.isArray(b) || a.length !== b.length) return false;
        for (let i = 0; i < a.length; i++) {
            if (!deepEqual(a[i], b[i])) return false;
        }
        return true;
    }
    if (typeof a === 'object') {
        if (Array.isArray(b)) return false;
        const keysA = Object.keys(a);
        const keysB = Object.keys(b);
        if (keysA.length !== keysB.length) return false;
        for (const key of keysA) {
            if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) return false;
        }
        return true;
    }
    return false;
}

/**
 * Returns the JSON type of a value.
 */
function getType(val: any): string {
    if (val === null) return 'null';
    if (Array.isArray(val)) return 'array';
    if (typeof val === 'number') return 'number';
    if (typeof val === 'string') return 'string';
    if (typeof val === 'boolean') return 'boolean';
    if (typeof val === 'object') return 'object';
    return '';
}

/**
 * Checks if a value is an integer.
 */
function isInteger(val: any): boolean {
    return typeof val === 'number' && Number.isInteger(val);
}

/**
 * Returns the number of Unicode code points in a string.
 */
function getCodePointLength(s: string): number {
    return [...s].length;
}

/**
 * Resolves a JSON reference to its schema and location.
 */
function resolveRef(ref: string, rootSchema: any): { schema: any, loc: string[] } {
    if (ref === "#") {
        return { schema: rootSchema, loc: [] };
    }
    if (ref.startsWith("#/$defs/")) {
        const pointer = ref.substring(8);
        const name = decodePointer(pointer);
        return { schema: rootSchema['$defs'][name], loc: ['$defs', name] };
    }
    throw new Error("Invalid ref");
}

/**
 * Validates an instance against a schema.
 */
function validate(instance: any, schema: any, instanceLoc: string[], schemaLoc: string[], rootSchema: any): Set<string> {
    const errors = new Set<string>();
    if (schema === true) return errors;
    if (schema === false) {
        errors.add(`${encodePointer(instanceLoc)} ${encodePointer(schemaLoc)}`);
        return errors;
    }

    const type = getType(instance);

    // type keyword
    if ('type' in schema) {
        const allowedTypes = Array.isArray(schema.type) ? schema.type : [schema.type];
        let match = false;
        for (const t of allowedTypes) {
            if (t === 'number' && type === 'number') match = true;
            else if (t === 'integer' && isInteger(instance)) match = true;
            else if (t === type) match = true;
        }
        if (!match) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'type'])}`);
        }
    }

    // enum keyword
    if ('enum' in schema) {
        const enumVals = schema.enum;
        let match = false;
        for (const val of enumVals) {
            if (deepEqual(instance, val)) {
                match = true;
                break;
            }
        }
        if (!match) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'enum'])}`);
        }
    }

    // const keyword
    if ('const' in schema) {
        if (!deepEqual(instance, schema.const)) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'const'])}`);
        }
    }

    // Number keywords
    if (type === 'number') {
        if ('minimum' in schema && instance < schema.minimum) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'minimum'])}`);
        }
        if ('maximum' in schema && instance > schema.maximum) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'maximum'])}`);
        }
        if ('exclusiveMinimum' in schema && instance <= schema.exclusiveMinimum) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'exclusiveMinimum'])}`);
        }
        if ('exclusiveMaximum' in schema && instance >= schema.exclusiveMaximum) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'exclusiveMaximum'])}`);
        }
    }

    // String keywords
    if (type === 'string') {
        const len = getCodePointLength(instance);
        if ('minLength' in schema && len < schema.minLength) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'minLength'])}`);
        }
        if ('maxLength' in schema && len > schema.maxLength) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'maxLength'])}`);
        }
    }

    // Array keywords
    if (type === 'array') {
        if ('minItems' in schema && instance.length < schema.minItems) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'minItems'])}`);
        }
        if ('maxItems' in schema && instance.length > schema.maxItems) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'maxItems'])}`);
        }
        if ('uniqueItems' in schema && schema.uniqueItems === true) {
            let unique = true;
            for (let i = 0; i < instance.length; i++) {
                for (let j = i + 1; j < instance.length; j++) {
                    if (deepEqual(instance[i], instance[j])) {
                        unique = false;
                        break;
                    }
                }
                if (!unique) break;
            }
            if (!unique) {
                errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'uniqueItems'])}`);
            }
        }
        if ('prefixItems' in schema) {
            const prefixItems = schema.prefixItems;
            for (let i = 0; i < prefixItems.length && i < instance.length; i++) {
                const subErrors = validate(instance[i], prefixItems[i], [...instanceLoc, i.toString()], [...schemaLoc, 'prefixItems', i.toString()], rootSchema);
                subErrors.forEach(e => errors.add(e));
            }
        }
        if ('items' in schema) {
            const itemsSchema = schema.items;
            const start = 'prefixItems' in schema ? schema.prefixItems.length : 0;
            for (let i = start; i < instance.length; i++) {
                const subErrors = validate(instance[i], itemsSchema, [...instanceLoc, i.toString()], [...schemaLoc, 'items'], rootSchema);
                subErrors.forEach(e => errors.add(e));
            }
        }
    }

    // Object keywords
    if (type === 'object') {
        if ('minProperties' in schema && Object.keys(instance).length < schema.minProperties) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'minProperties'])}`);
        }
        if ('maxProperties' in schema && Object.keys(instance).length > schema.maxProperties) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'maxProperties'])}`);
        }
        if ('required' in schema) {
            for (let j = 0; j < schema.required.length; j++) {
                const req = schema.required[j];
                if (!(req in instance)) {
                    errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'required', j.toString()])}`);
                }
            }
        }
        if ('properties' in schema) {
            for (const key in schema.properties) {
                if (key in instance) {
                    const propErrors = validate(instance[key], schema.properties[key], [...instanceLoc, key], [...schemaLoc, 'properties', key], rootSchema);
                    propErrors.forEach(e => errors.add(e));
                }
            }
        }
        if ('additionalProperties' in schema) {
            const addPropSchema = schema.additionalProperties;
            for (const key in instance) {
                const isProperty = 'properties' in schema && key in schema.properties;
                if (!isProperty) {
                    const addPropErrors = validate(instance[key], addPropSchema, [...instanceLoc, key], [...schemaLoc, 'additionalProperties'], rootSchema);
                    addPropErrors.forEach(e => errors.add(e));
                }
            }
        }
    }

    // Applicators
    if ('allOf' in schema) {
        for (let i = 0; i < schema.allOf.length; i++) {
            const subErrors = validate(instance, schema.allOf[i], instanceLoc, [...schemaLoc, 'allOf', i.toString()], rootSchema);
            subErrors.forEach(e => errors.add(e));
        }
    }
    if ('anyOf' in schema) {
        let anyAccepts = false;
        for (let i = 0; i < schema.anyOf.length; i++) {
            if (validate(instance, schema.anyOf[i], [], [], rootSchema).size === 0) {
                anyAccepts = true;
                break;
            }
        }
        if (!anyAccepts) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'anyOf'])}`);
        }
    }
    if ('oneOf' in schema) {
        let count = 0;
        for (let i = 0; i < schema.oneOf.length; i++) {
            if (validate(instance, schema.oneOf[i], [], [], rootSchema).size === 0) {
                count++;
            }
        }
        if (count !== 1) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'oneOf'])}`);
        }
    }
    if ('not' in schema) {
        if (validate(instance, schema.not, [], [], rootSchema).size === 0) {
            errors.add(`${encodePointer(instanceLoc)} ${encodePointer([...schemaLoc, 'not'])}`);
        }
    }
    if ('if' in schema) {
        if (validate(instance, schema.if, [], [], rootSchema).size === 0) {
            if ('then' in schema) {
                const thenErrors = validate(instance, schema.then, instanceLoc, [...schemaLoc, 'then'], rootSchema);
                thenErrors.forEach(e => errors.add(e));
            }
        } else {
            if ('else' in schema) {
                const elseErrors = validate(instance, schema.else, instanceLoc, [...schemaLoc, 'else'], rootSchema);
                elseErrors.forEach(e => errors.add(e));
            }
        }
    }
    if ('$ref' in schema) {
        const { schema: refSchema, loc: refLoc } = resolveRef(schema.$ref, rootSchema);
        const refErrors = validate(instance, refSchema, instanceLoc, refLoc, rootSchema);
        refErrors.forEach(e => errors.add(e));
    }

    return errors;
}

function main() {
    const dir = process.argv[2];
    if (!dir) return;
    const schema = JSON.parse(fs.readFileSync(path.join(dir, 'schema.json'), 'utf-8'));
    const instances = JSON.parse(fs.readFileSync(path.join(dir, 'instances.json'), 'utf-8'));

    let validCount = 0;
