import sys
import json
import re

def main():
    kv_store = {}
    initialized = False

    # Tool definitions
    tools_def = [
        {
            "name": "kv_set",
            "title": "Set a value",
            "description": "Store a string value under a key, replacing any previous value.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "key": {"type": "string", "minLength": 1},
                    "value": {"type": "string"}
                },
                "required": ["key", "value"],
                "additionalProperties": False
            }
        },
        {
            "name": "kv_get",
            "title": "Get a value",
            "description": "Return the value stored under a key.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "key": {"type": "string", "minLength": 1}
                },
                "required": ["key"],
                "additionalProperties": False
            }
        },
        {
            "name": "kv_list",
            "title": "List keys",
            "description": "List the stored keys that start with a prefix, sorted by Unicode code point.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "prefix": {"type": "string"}
                },
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "keys": {"type": "array", "items": {"type": "string"}},
                    "count": {"type": "integer"}
                },
                "required": ["keys", "count"]
            }
        },
        {
            "name": "sum",
            "title": "Sum integers",
            "description": "Add up a non-empty list of integers.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "numbers": {
                        "type": "array",
                        "items": {"type": "integer"},
                        "minItems": 1
                    }
                },
                "required": ["numbers"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "sum": {"type": "integer"},
                    "count": {"type": "integer"}
                },
                "required": ["sum", "count"]
            },
            "annotations": {"readOnlyHint": True, "idempotentHint": True}
        },
        {
            "name": "text_stats",
            "title": "Text statistics",
            "description": "Count the words, Unicode code points and UTF-8 bytes of a text.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "text": {"type": "string"}
                },
                "required": ["text"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "words": {"type": "integer"},
                    "codepoints": {"type": "integer"},
                    "utf8_bytes": {"type": "integer"}
                },
                "required": ["words", "codepoints", "utf8_bytes"]
            },
            "annotations": {"readOnlyHint": True}
        }
    ]

    def is_valid_id(id_val):
        if isinstance(id_val, str):
            return True
        if isinstance(id_val, int) and not isinstance(id_val, bool):
            return True
        return False

    for line in sys.stdin:
        line = line.strip('\r\n')
        if not line or line.isspace():
            continue

        try:
            msg = json.loads(line)
        except json.JSONDecodeError:
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error"}}) + '\n')
            continue

        if not isinstance(msg, dict):
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Invalid Request"}}) + '\n')
            continue

        if 'method' not in msg and ('result' in msg or 'error' in msg):
            continue

        # Invalid Request Check
        valid_id = None
        if 'id' in msg:
            if is_valid_id(msg['id']):
                valid_id = msg['id']

        is_invalid = False
        if msg.get('jsonrpc') != "2.0":
            is_invalid = True
        elif 'method' not in msg or not isinstance(msg['method'], str):
            is_invalid = True
        elif 'id' in msg and not is_valid_id(msg['id']):
            is_invalid = True

        if is_invalid:
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": valid_id, "error": {"code": -32600, "message": "Invalid Request"}}) + '\n')
            continue

        # Notification Check
        if 'id' not in msg:
            continue

        # Request
        req_id = msg['id']
        method = msg['method']
        params = msg.get('params')

        if method not in ['initialize', 'ping', 'tools/list', 'tools/call']:
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32601, "message": "Method not found"}}) + '\n')
            continue

        if 'params' in msg and not isinstance(params, dict):
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Invalid params"}}) + '\n')
            continue

        if not initialized and method not in ['initialize', 'ping']:
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32002, "message": "Server not initialized"}}) + '\n')
            continue

        # Method Dispatch
        if method == 'initialize':
            if initialized:
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32600, "message": "Already initialized"}}) + '\n')
                continue

            if params is None or 'protocolVersion' not in params or not isinstance(params['protocolVersion'], str):
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Invalid params"}}) + '\n')
                continue

            pv = params['protocolVersion']
            version = pv if pv in ["2025-06-18", "2025-03-26", "2024-11-05"] else "2025-06-18"
            initialized = True
            sys.stdout.write(json.dumps({
                "jsonrpc": "2.0", "id": req_id, "result": {
                    "protocolVersion": version,
                    "capabilities": {"tools": {"listChanged": False}},
                    "serverInfo": {"name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"}
                }
            }) + '\n')

        elif method == 'ping':
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": {}}) + '\n')

        elif method == 'tools/list':
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": {"tools": tools_def}}) + '\n')

        elif method == 'tools/call':
            if params is None or 'name' not in params or not isinstance(params['name'], str):
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": "Invalid params"}}) + '\n')
                continue

            tool_name = params['name']
            tool = next((t for t in tools_def if t['name'] == tool_name), None)
            if not tool:
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "error": {"code": -32602, "message": f"Unknown tool: {tool_name}"}}) + '\n')
                continue

            args = params.get('arguments', {})
            if 'arguments' in params and not isinstance(args, dict):
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": "arguments must be an object"}], "isError": True}}) + '\n')
                continue

            # Argument validation
            fail_msg = None
            # 1. Unknown arguments
            unknown_args = [k for k in args if k not in tool['inputSchema']['properties']]
            if unknown_args:
                fail_msg = f"unknown argument: {min(unknown_args)}"

            if not fail_msg:
                # 2. Required and Type checks in order of schema
                for prop_name, prop_schema in tool['inputSchema']['properties'].items():
                    if prop_name not in args:
                        if prop_name in tool['inputSchema'].get('required', []):
                            fail_msg = f"missing required argument: {prop_name}"
                            break
                        continue

                    val = args[prop_name]
                    # Type checks
                    if prop_schema['type'] == 'string':
                        if not isinstance(val, str):
                            fail_msg = f"argument {prop_name} must be a string"
                            break
                        if 'minLength' in prop_schema and len(val) < prop_schema['minLength']:
                            fail_msg = f"argument {prop_name} must not be empty"
                            break
                    elif prop_schema['type'] == 'array':
                        if not isinstance(val, list) or not all(isinstance(x, int) and not isinstance(x, bool) for x in val):
                            fail_msg = f"argument {prop_name} must be an array of integers"
                            break
                        if 'minItems' in prop_schema and len(val) < prop_schema['minItems']:
                            fail_msg = f"argument {prop_name} must not be empty"
                            break

            if fail_msg:
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": fail_msg}], "isError": True}}) + '\n')
                continue

            # Tool Execution
            try:
                if tool_name == 'kv_set':
                    k, v = args['key'], args['value']
                    res_text = f"updated {k}" if k in kv_store else f"created {k}"
                    kv_store[k] = v
                    res = {"content": [{"type": "text", "text": res_text}], "isError": False}
                elif tool_name == 'kv_get':
                    k = args['key']
                    if k not in kv_store:
                        res = {"content": [{"type": "text", "text": f"key not found: {k}"}], "isError": True}
                    else:
                        res = {"content": [{"type": "text", "text": kv_store[k]}], "isError": False}
                elif tool_name == 'kv_list':
                    prefix = args.get('prefix', "")
                    matches = sorted([k for k in kv_store if k.startswith(prefix)])
                    S = {"keys": matches, "count": len(matches)}
                    res = {"content": [{"type": "text", "text": json.dumps(S)}], "structuredContent": S, "isError": False}
                elif tool_name == 'sum':
                    nums = args['numbers']
                    S = {"sum": sum(nums), "count": len(nums)}
                    res = {"content": [{"type": "text", "text": json.dumps(S)}], "structuredContent": S, "isError": False}
                elif tool_name == 'text_stats':
                    text = args['text']
                    words = re.split(r'[ \t\n\r]+', text)
                    w = len([word for word in words if word])
                    S = {"words": w, "codepoints": len(text), "utf8_bytes": len(text.encode('utf-8'))}
                    res = {"content": [{"type": "text", "text": json.dumps(S)}], "structuredContent": S, "isError": False}

                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": res}) + '\n')
            except Exception as e:
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "result": {"content": [{"type": "text", "text": str(e)}], "isError": True}}) + '\n')

