        public int size() { return elements.size(); }
        public JsonValue get(int i) { return elements.get(i); }
        public String toString() { return "array"; }
    }
    static class JsonObject extends JsonValue {
        final Map<String, JsonValue> members = new LinkedHashMap<>();
        public JsonValue get(String key) { return members.get(key); }
        public void put(String key, JsonValue val) { members.put(key, val); }
        public Set<String> keySet() { return members.keySet(); }
        public String toString() { return "object"; }
    }

    static class JsonParser {
        private final String input;
        private int pos = 0;
        JsonParser(String s) { input = s; }
        JsonValue parse() {
            skipWhitespace();
            return parseValue();
        }
        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
        }
        private JsonValue parseValue() {
            skipWhitespace();
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBoolean();
            if (c == 'n') return parseNull();
            return parseNumber();
        }
        private JsonObject parseObject() {
            JsonObject obj = new JsonObject();
            pos++; // skip {
            while (true) {
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == '}') { pos++; break; }
                String key = parseString().stringValue();
                skipWhitespace();
                pos++; // skip :
                obj.put(key, parseValue());
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') pos++;
            }
            return obj;
        }
        private JsonArray parseArray() {
            JsonArray arr = new JsonArray();
            pos++; // skip [
            while (true) {
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ']') { pos++; break; }
                arr.elements.add(parseValue());
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') pos++;
            }
            return arr;
        }
        private JsonString parseString() {
            StringBuilder sb = new StringBuilder();
            pos++; // skip "
            while (pos < input.length()) {
                char c = input.charAt(pos++);
                if (c == '"') break;
                if (c == '\\') {
                    char next = input.charAt(pos++);
                    switch (next) {
                        case '"' -> sb.append('"');
                        case '\\' -> sb.append('\\');
                        case '/' -> sb.append('/');
                        case 'b' -> sb.append('\b');
                        case 'f' -> sb.append('\f');
                        case 'n' -> sb.append('\n');
                        case 'r' -> sb.append('\r');
                        case 't' -> sb.append('\t');
                        case 'u' -> {
                            StringBuilder hex = new StringBuilder();
                            for (int i = 0; i < 4; i++) hex.append(input.charAt(pos++));
                            sb.append((char) Integer.parseInt(hex.toString(), 16));
                        }
                    }
                } else sb.append(c);
            }
            return new JsonString(sb.toString());
        }
        private JsonBoolean parseBoolean() {
            if (input.startsWith("true", pos)) { pos += 4; return new JsonBoolean(true); }
            pos += 5; return new JsonBoolean(false);
        }
        private JsonNull parseNull() { pos += 4; return new JsonNull(); }
        private JsonNumber parseNumber() {
            int start = pos;
            while (pos < input.length() && "0123456789.eE-+".indexOf(input.charAt(pos)) != -1) pos++;
            return new JsonNumber(Double.parseDouble(input.substring(start, pos)));
        }
    }

    static class Error implements Comparable<Error> {
        final String instLoc, schLoc;
        Error(String i, String s) { instLoc = i; schLoc = s; }
        public String toString() { return instLoc + " " + schLoc; }
        public int compareTo(Error other) {
            int cmp = instLoc.compareTo(other.instLoc);
            return cmp != 0 ? cmp : schLoc.compareTo(other.schLoc);
        }
        public boolean equals(Object o) {
            if (!(o instanceof Error)) return false;
            Error e = (Error) o;
            return instLoc.equals(e.instLoc) && schLoc.equals(e.schLoc);
        }
        public int hashCode() { return Objects.hash(instLoc, schLoc); }
    }

    static class Validator {
        final JsonValue rootSchema;
        Validator(JsonValue root) { rootSchema = root; }

        String encode(List<String> loc) {
            StringBuilder sb = new StringBuilder("#");
            for (String s : loc) sb.append("/").append(s.replace("~", "~0").replace("/", "~1"));
            return sb.toString();
        }

        boolean accepts(JsonValue inst, JsonValue sch, List<String> iLoc, List<String> sLoc) {
            return validate(inst, sch, iLoc, sLoc).isEmpty();
        }

        Set<Error> validate(JsonValue inst, JsonValue sch, List<String> iLoc, List<String> sLoc) {
            Set<Error> errors = new HashSet<>();
            if (sch instanceof JsonBoolean) {
                if (!((JsonBoolean) sch).booleanValue()) errors.add(new Error(encode(iLoc), encode(sLoc)));
                return errors;
            }
            if (!(sch instanceof JsonObject)) return errors;
            JsonObject sObj = (JsonObject) sch;

            // type
            JsonValue typeK = sObj.get("type");
            if (typeK != null) {
                boolean ok = false;
                if (typeK instanceof JsonString) {
                    ok = checkType(inst, ((JsonString) typeK).stringValue());
                } else if (typeK instanceof JsonArray) {
                    for (JsonValue t : ((JsonArray) typeK).elements) {
                        if (t instanceof JsonString && checkType(inst, ((JsonString) t).stringValue())) {
                            ok = true; break;
                        }
                    }
                }
                if (!ok) errors.add(new Error(encode(iLoc), encode(append(sLoc, "type"))));
            }

            // enum
            JsonValue enumK = sObj.get("enum");
            if (enumK instanceof JsonArray) {
                boolean ok = false;
                for (JsonValue e : ((JsonArray) enumK).elements) {
                    if (deepEqual(inst, e)) { ok = true; break; }
                }
                if (!ok) errors.add(new Error(encode(iLoc), encode(append(sLoc, "enum"))));
            }

            // const
            JsonValue constK = sObj.get("const");
            if (constK != null && !deepEqual(inst, constK)) {
                errors.add(new Error(encode(iLoc), encode(append(sLoc, "const"))));
            }

            // Number keywords
            if (inst instanceof JsonNumber) {
                double val = ((JsonNumber) inst).doubleValue();
                if (sObj.get("minimum") instanceof JsonNumber) {
                    if (val < ((JsonNumber) sObj.get("minimum")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "minimum"))));
                }
                if (sObj.get("maximum") instanceof JsonNumber) {
                    if (val > ((JsonNumber) sObj.get("maximum")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "maximum"))));
                }
                if (sObj.get("exclusiveMinimum") instanceof JsonNumber) {
                    if (val <= ((JsonNumber) sObj.get("exclusiveMinimum")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "exclusiveMinimum"))));
                }
                if (sObj.get("exclusiveMaximum") instanceof JsonNumber) {
                    if (val >= ((JsonNumber) sObj.get("exclusiveMaximum")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "exclusiveMaximum"))));
                }
            }

            // String keywords
            if (inst instanceof JsonString) {
                String s = ((JsonString) inst).stringValue();
                int len = s.codePointCount(0, s.length());
                if (sObj.get("minLength") instanceof JsonNumber) {
                    if (len < ((JsonNumber) sObj.get("minLength")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "minLength"))));
                }
                if (sObj.get("maxLength") instanceof JsonNumber) {
                    if (len > ((JsonNumber) sObj.get("maxLength")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "maxLength"))));
                }
            }

            // Array keywords
            if (inst instanceof JsonArray) {
                JsonArray a = (JsonArray) inst;
                if (sObj.get("minItems") instanceof JsonNumber) {
                    if (a.size() < ((JsonNumber) sObj.get("minItems")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "minItems"))));
                }
                if (sObj.get("maxItems") instanceof JsonNumber) {
                    if (a.size() > ((JsonNumber) sObj.get("maxItems")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "maxItems"))));
                }
                if (sObj.get("uniqueItems") instanceof JsonBoolean && ((JsonBoolean) sObj.get("uniqueItems")).booleanValue()) {
                    boolean dup = false;
                    for (int i = 0; i < a.size(); i++) {
                        for (int j = i + 1; j < a.size(); j++) {
                            if (deepEqual(a.get(i), a.get(j))) { dup = true; break; }
                        }
                        if (dup) break;
                    }
                    if (dup) errors.add(new Error(encode(iLoc), encode(append(sLoc, "uniqueItems"))));
                }
                JsonValue prefixItemsK = sObj.get("prefixItems");
                JsonValue itemsK = sObj.get("items");
                if (prefixItemsK instanceof JsonArray) {
                    JsonArray pi = (JsonArray) prefixItemsK;
                    for (int i = 0; i < Math.min(a.size(), pi.size()); i++) {
                        errors.addAll(validate(a.get(i), pi.get(i), append(iLoc, String.valueOf(i)), append(append(sLoc, "prefixItems"), String.valueOf(i))));
                    }
                    if (itemsK != null) {
                        for (int i = pi.size(); i < a.size(); i++) {
                            errors.addAll(validate(a.get(i), itemsK, append(iLoc, String.valueOf(i)), append(sLoc, "items")));
                        }
                    }
                } else if (itemsK != null) {
                    for (int i = 0; i < a.size(); i++) {
                        errors.addAll(validate(a.get(i), itemsK, append(iLoc, String.valueOf(i)), append(sLoc, "items")));
                    }
                }
            }

            // Object keywords
            if (inst instanceof JsonObject) {
                JsonObject o = (JsonObject) inst;
                JsonValue propsK = sObj.get("properties");
                if (propsK instanceof JsonObject) {
                    JsonObject props = (JsonObject) propsK;
                    for (String key : props.keySet()) {
                        if (o.members.containsKey(key)) {
                            errors.addAll(validate(o.get(key), props.get(key), append(iLoc, key), append(append(sLoc, "properties"), key)));
                        }
                    }
                }
                JsonValue reqK = sObj.get("required");
                if (reqK instanceof JsonArray) {
                    JsonArray req = (JsonArray) reqK;
                    for (int i = 0; i < req.size(); i++) {
                        String r = ((JsonString) req.get(i)).stringValue();
                        if (!o.members.containsKey(r)) {
                            errors.add(new Error(encode(iLoc), encode(append(append(sLoc, "required"), String.valueOf(i)))));
                        }
                    }
                }
                JsonValue addPropK = sObj.get("additionalProperties");
                if (addPropK != null) {
                    Set<String> propKeys = (propsK instanceof JsonObject) ? ((JsonObject) propsK).keySet() : Collections.emptySet();
                    for (String key : o.members.keySet()) {
                        if (!propKeys.contains(key)) {
                            errors.addAll(validate(o.get(key), addPropK, append(iLoc, key), append(sLoc, "additionalProperties")));
                        }
                    }
                }
                if (sObj.get("minProperties") instanceof JsonNumber) {
                    if (o.members.size() < ((JsonNumber) sObj.get("minProperties")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "minProperties"))));
                }
                if (sObj.get("maxProperties") instanceof JsonNumber) {
                    if (o.members.size() > ((JsonNumber) sObj.get("maxProperties")).doubleValue())
                        errors.add(new Error(encode(iLoc), encode(append(sLoc, "maxProperties"))));
                }
            }

            // Applicators
            JsonValue allOfK = sObj.get("allOf");
            if (allOfK instanceof JsonArray) {
                for (int i = 0; i < ((JsonArray) allOfK).size(); i++) {
                    errors.addAll(validate(inst, ((JsonArray) allOfK).get(i), iLoc, append(append(sLoc, "allOf"), String.valueOf(i))));
                }
            }
            JsonValue anyOfK = sObj.get("anyOf");
            if (anyOfK instanceof JsonArray) {
                boolean any = false;
                for (JsonValue s : ((JsonArray) anyOfK).elements) {
                    if (accepts(inst, s, iLoc, sLoc)) { any = true; break; }
                }
                if (!any) errors.add(new Error(encode(iLoc), encode(append(sLoc, "anyOf"))));
            }
            JsonValue oneOfK = sObj.get("oneOf");
            if (oneOfK instanceof JsonArray) {
                int count = 0;
                for (JsonValue s : ((JsonArray) oneOfK).elements) {
                    if (accepts(inst, s, iLoc, sLoc)) count++;
                }
                if (count != 1) errors.add(new Error(encode(iLoc), encode(append(sLoc, "oneOf"))));
            }
            JsonValue notK = sObj.get("not");
            if (notK != null && accepts(inst, notK, iLoc, sLoc)) {
                errors.add(new Error(encode(iLoc), encode(append(sLoc, "not"))));
            }
            JsonValue ifK = sObj.get("if");
            if (ifK != null) {
                if (accepts(inst, ifK, iLoc, sLoc)) {
                    JsonValue thenK = sObj.get("then");
                    if (thenK != null) errors.addAll(validate(inst, thenK, iLoc, append(sLoc, "then")));
                } else {
                    JsonValue elseK = sObj.get("else");
                    if (elseK != null) errors.addAll(validate(inst, elseK, iLoc, append(sLoc, "else")));
                }
            }
            JsonValue refK = sObj.get("$ref");
            if (refK instanceof JsonString) {
                String ref = ((JsonString) refK).stringValue();
                JsonValue target = resolve(ref);
                List<String> targetLoc = resolveLoc(ref);
                errors.addAll(validate(inst, target, iLoc, targetLoc));
            }

            return errors;
        }

        private JsonValue resolve(String ref) {
            if (ref.equals("#")) return rootSchema;
            if (ref.startsWith("#/$defs/")) {
                String name = ref.substring(8);
                String decodedName = decode(name);
                JsonObject defs = (JsonObject) ((JsonObject) rootSchema).get("$defs");
                return defs.get(decodedName);
            }
            return null;
        }

        private List<String> resolveLoc(String ref) {
            if (ref.equals("#")) return new ArrayList<>();
            if (ref.startsWith("#/$defs/")) {
                List<String> loc = new ArrayList<>();
                loc.add("$defs");
                loc.add(decode(ref.substring(8)));
                return loc;
            }
            return new ArrayList<>();
        }

        private String decode(String s) {
            return s.replace("~1", "/").replace("~0", "~");
        }

        private List<String> append(List<String> loc, String token) {
            List<String> next = new ArrayList<>(loc);
            next.add(token);
            return next;
        }

        private boolean checkType(JsonValue inst, String type) {
            return switch (type) {
                case "null" -> inst instanceof JsonNull;
                case "boolean" -> inst instanceof JsonBoolean;
                case "object" -> inst instanceof JsonObject;
                case "array" -> inst instanceof JsonArray;
                case "number" -> inst instanceof JsonNumber;
                case "string" -> inst instanceof JsonString;
                case "integer" -> (inst instanceof JsonNumber && ((JsonNumber) inst).isInteger());
                default -> false;
            };
        }

        private boolean deepEqual(JsonValue v1, JsonValue v2) {
            if (v1 instanceof JsonNull || v2 instanceof JsonNull) return (v1 instanceof JsonNull && v2 instanceof JsonNull);
            if (v1 instanceof JsonNumber && v2 instanceof JsonNumber) return ((JsonNumber) v1).doubleValue() == ((JsonNumber) v2).doubleValue();
            if (v1 instanceof JsonString && v2 instanceof JsonString) return ((JsonString) v1).stringValue().equals(((JsonString) v2).stringValue());
            if (v1 instanceof JsonBoolean && v2 instanceof JsonBoolean) return ((JsonBoolean) v1).booleanValue() == ((JsonBoolean) v2).booleanValue();
            if (v1 instanceof JsonArray && v2 instanceof JsonArray) {
                JsonArray a1 = (JsonArray) v1, a2 = (JsonArray) v2;
                if (a1.size() != a2.size()) return false;
                for (int i = 0; i < a1.size(); i++) if (!deepEqual(a1.get(i), a2.get(i))) return false;
                return true;
            }
            if (v1 instanceof JsonObject && v2 instanceof JsonObject) {
                JsonObject o1 = (JsonObject) v1, o2 = (JsonObject) v2;
                if (o1.members.size() != o2.members.size()) return false;
                for (String k : o1.keySet()) {
                    if (!o2.members.containsKey(k) || !deepEqual(o1.get(k), o2.get(k))) return false;
                }
                return true;
            }
            return false;
        }
    }
}

import Foundation

enum JSONValue: Equatable, Hashable {
    case null
    case boolean(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])
}

struct JSONPointer: Hashable, Comparable {
    let tokens: [String]

    init() { self.tokens = [] }
    init(tokens: [String]) { self.tokens = tokens }

    init(string: String) {
        if string == "#" {
            self.tokens = []
        } else if string.hasPrefix("#/") {
            let path = String(string.dropFirst(2))
            var parts: [String] = []
            var currentPart = ""
            for char in path {
                if char == "/" {
                    parts.append(currentPart)
                    currentPart = ""
                } else {
                    currentPart.append(char)
                }
            }
            parts.append(currentPart)
            self.tokens = parts.map { token in
                token.replacingOccurrences(of: "~1", with: "/").replacingOccurrences(of: "~0", with: "~")
            }
        } else {
            self.tokens = []
        }
    }

    func appending(_ token: String) -> JSONPointer {
        return JSONPointer(tokens: tokens + [token])
    }

    func toString() -> String {
        if tokens.isEmpty { return "#" }
        return "#" + tokens.map { token in
            token.replacingOccurrences(of: "~", with: "~0").replacingOccurrences(of: "/", with: "~1")
        }.joined(separator: "/")
    }

    static func < (lhs: JSONPointer, rhs: JSONPointer) -> Bool {
        return lhs.toString() < rhs.toString()
    }

    func resolve(root: JSONValue) -> JSONValue? {
        var current = root
        for token in tokens {
            if case .object(let dict) = current {
                if let next = dict[token] {
                    current = next
                } else {
                    return nil
                }
            } else if case .array(let array) = current {
                if let index = Int(token), index >= 0 && index < array.count {
                    current = array[index]
                } else {
                    return nil
                }
            } else {
                return nil
            }
        }
        return current
    }
}

struct ValidationError: Hashable, Comparable {
    let instanceLoc: JSONPointer
    let schemaLoc: JSONPointer

    static func < (lhs: ValidationError, rhs: ValidationError) -> Bool {
        let lInst = lhs.instanceLoc.toString()
        let rInst = rhs.instanceLoc.toString()
        if lInst != rInst {
            return lInst < rInst
        }
        return lhs.schemaLoc.toString() < rhs.schemaLoc.toString()
    }
}

func convertToJSONValue(_ any: Any) -> JSONValue {
    if any is NSNull { return .null }
    if let b = any as? Bool { return .boolean(b) }
    if let s = any as? String { return .string(s) }
    if let n = any as? NSNumber {
        return .number(n.doubleValue)
    }
    if let a = any as? [Any] {
        return .array(a.map { convertToJSONValue($0) })
    }
    if let o = any as? [String: Any] {
        return .object(o.mapValues { convertToJSONValue($0) })
    }
    return .null
}

func matchesType(instance: JSONValue, typeVal: JSONValue) -> Bool {
    if case .string(let t) = typeVal {
        switch instance {
        case .null: return t == "null"
        case .boolean: return t == "boolean"
        case .object: return t == "object"
        case .array: return t == "array"
        case .string: return t == "string"
        case .number(let n):
            if t == "number" { return true }
            if t == "integer" { return n == floor(n) }
            return false
        }
    } else if case .array(let types) = typeVal {
        return types.contains { type in
            if case .string(let t) = type {
                return matchesType(instance: instance, typeVal: .string(t))
            }
            return false
        }
    }
    return false
}

func hasDuplicates(_ array: [JSONValue]) -> Bool {
    var seen = Set<JSONValue>()
    for item in array {
        if seen.contains(item) { return true }
        seen.insert(item)
    }
    return false
}

func validate(instance: JSONValue, schema: JSONValue, instanceLoc: JSONPointer, schemaLoc: JSONPointer, rootSchema: JSONValue) -> Set<ValidationError> {
    var errors = Set<ValidationError>()

    if case .boolean(let val) = schema {
        if !val {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc))
        }
        return errors
    }

    guard case .object(let schemaObj) = schema else { return errors }

    if let refVal = schemaObj["$ref"], case .string(let refString) = refVal {
        let refPointer = JSONPointer(string: refString)
        if let resolvedSchema = refPointer.resolve(root: rootSchema) {
            errors.formUnion(validate(instance: instance, schema: resolvedSchema, instanceLoc: instanceLoc, schemaLoc: refPointer, rootSchema: rootSchema))
        }
    }

    if let typeVal = schemaObj["type"] {
        if !matchesType(instance: instance, typeVal: typeVal) {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("type")))
        }
    }

    if let enumVal = schemaObj["enum"], case .array(let enumArray) = enumVal {
        if !enumArray.contains(instance) {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("enum")))
        }
    }

    if let constVal = schemaObj["const"] {
        if instance != constVal {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("const")))
        }
    }

    if case .number(let instNum) = instance {
        if let minVal = schemaObj["minimum"], case .number(let minNum) = minVal, instNum < minNum {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("minimum")))
        }
        if let maxVal = schemaObj["maximum"], case .number(let maxNum) = maxVal, instNum > maxNum {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("maximum")))
        }
        if let exMinVal = schemaObj["exclusiveMinimum"], case .number(let exMinNum) = exMinVal, instNum <= exMinNum {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("exclusiveMinimum")))
        }
        if let exMaxVal = schemaObj["exclusiveMaximum"], case .number(let exMaxNum) = exMaxVal, instNum >= exMaxNum {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("exclusiveMaximum")))
        }
    }

    if case .string(let instStr) = instance {
        let len = instStr.unicodeScalars.count
        if let minLen = schemaObj["minLength"], case .number(let minL) = minLen, len < Int(minL) {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("minLength")))
        }
        if let maxLen = schemaObj["maxLength"], case .number(let maxL) = maxLen, len > Int(maxL) {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("maxLength")))
        }
    }

    if case .array(let instArr) = instance {
        if let minItems = schemaObj["minItems"], case .number(let minI) = minItems, instArr.count < Int(minI) {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("minItems")))
        }
        if let maxItems = schemaObj["maxItems"], case .number(let maxI) = maxItems, instArr.count > Int(maxI) {
            errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("maxItems")))
        }
        if let uniqueItems = schemaObj["uniqueItems"], case .boolean(let unique) = uniqueItems, unique {
            if hasDuplicates(instArr) {
                errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc.appending("uniqueItems")))
            }
        }

        let prefixItemsCount: Int
        if let pi = schemaObj["prefixItems"], case .array(let piArr) = pi {
            prefixItemsCount = piArr.count
            for i in 0..<min(instArr.count, prefixItemsCount) {
                let subSchema = piArr[i]
                errors.formUnion(validate(instance: instArr[i], schema: subSchema, instanceLoc: instanceLoc.appending(String(i)), schemaLoc: schemaLoc.appending("prefixItems").appending(String(i)), rootSchema: rootSchema))
            }
        } else {
            prefixItemsCount = 0
        }

        if let itemsSchema = schemaObj["items"] {
            for i in prefixItemsCount..<instArr.count {
                errors.formUnion(validate(instance: instArr[i], schema: itemsSchema, instanceLoc: instanceLoc.appending(String(i)), schemaLoc: schemaLoc.appending("items"), rootSchema: rootSchema))
            }
        }
    }

    if case .object(let instObj) = instance {
        let propKeys: Set<String>
        if let properties = schemaObj["properties"], case .object(let propSchemas) = properties {
            propKeys = Set(propSchemas.keys)
            for (key, subSchema) in propSchemas {
                if let instVal = instObj[key] {
                    errors.formUnion(validate(instance: instVal, schema: subSchema, instanceLoc: instanceLoc.appending(key), schemaLoc: schemaLoc.appending("properties").appending(key), rootSchema: rootSchema))
                }
            }
        } else {
