import Foundation

enum JSONValue: Equatable, Hashable {
    case null
    case boolean(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])
}

struct JSONPointer: Hashable, Comparable {
    let tokens: [String]

    init() { self.tokens = [] }
    init(tokens: [String]) { self.tokens = tokens }

    init(string: String) {
        if string == "#" {
            self.tokens = []
        } else if string.hasPrefix("#/") {
            let path = String(string.dropFirst(2))
            var parts: [String] = []
            var currentPart = ""
            for char in path {
                if char == "/" {
                    parts.append(currentPart)
                    currentPart = ""
                } else {
                    currentPart.append(char)
                }
            }
            parts.append(currentPart)
            self.tokens = parts.map { token in
                token.replacingOccurrences(of: "~1", with: "/").replacingOccurrences(of: "~0", with: "~")
            }
        } else {
            self.tokens = []
        }
    }

    func appending(_ token: String) -> JSONPointer {
        return JSONPointer(tokens: tokens + [token])
    }

    func toString() -> String {
        if tokens.isEmpty { return "#" }
        return "#" + tokens.map { token in
            token.replacingOccurrences(of: "~", with: "~0").replacingOccurrences(of: "/", with: "~1")
        }.joined(separator: "/")
    }

    static func < (lhs: JSONPointer, rhs: JSONPointer) -> Bool {
        return lhs.toString() < rhs.toString()
    }

    func resolve(root: JSONValue) -> JSONValue? {
        var current = root
        for token in tokens {
            if case .object(let dict) = current {
                if let next = dict[token] {
                    current = next
                } else {
                    return nil
                }
            } else if case .array(let array) = current {
                if let index = Int(token), index >= 0 && index < array.count {
                    current = array[index]
                } else {
                    return nil
                }
            } else {
                return nil
            }
        }
        return current
    }
}

