import Foundation
import Darwin

// DNS Type mapping
func typeName(_ type: Int) -> String {
    switch type {
    case 1: return "A"
    case 5: return "CNAME"
    case 15: return "MX"
    case 16: return "TXT"
    case 28: return "AAAA"
    default: return "TYPE\(type)"
    }
}

func rcodeName(_ rcode: Int) -> String {
    switch rcode {
    case 0: return "NOERROR"
    case 1: return "FORMERR"
    case 2: return "SERVFAIL"
    case 3: return "NXDOMAIN"
    case 4: return "NOTIMP"
    case 5: return "REFUSED"
    default: return "RCODE\(rcode)"
    }
}

func formatIPv4(_ bytes: [UInt8]) -> String {
    return bytes.map { String($0) }.joined(separator: ".")
}

func formatIPv6(_ bytes: [UInt8]) -> String {
    var groups = [Int]()
    for i in stride(from: 0, to: 16, by: 2) {
        groups.append(Int(bytes[i]) << 8 | Int(bytes[i+1]))
    }

    var bestStart = -1
    var bestLen = 0
    var currentStart = -1
    var currentLen = 0
    for i in 0..<8 {
        if groups[i] == 0 {
            if currentStart == -1 { currentStart = i }
            currentLen += 1
        } else {
            if currentLen > bestLen {
                bestLen = currentLen
                bestStart = currentStart
            }
            currentStart = -1
            currentLen = 0
        }
    }
    if currentLen > bestLen {
        bestLen = currentLen
        bestStart = currentStart
    }

    var parts = [String]()
    var i = 0
    while i < 8 {
        if i == bestStart && bestLen >= 2 {
            parts.append("")
            i += bestLen
        } else {
            parts.append(String(groups[i], radix: 16))
            i += 1
        }
    }

    var result = parts.joined(separator: ":")
    if result.hasPrefix(":") && !result.hasPrefix("::") { result = ":" + result }
    if result.hasSuffix(":") && !result.hasSuffix("::") { result = result + ":" }
    if result == "" { result = "::" }
    return result
}

func formatTXT(_ data: [UInt8]) -> String {
    var result = [String]()
    var i = 0
    while i < data.count {
        let len = Int(data[i])
        i += 1
        let segment = data[i..<i+len]
        i += len

        var escaped = "\""
        for b in segment {
            if b == 0x22 { escaped += "\\\"" }
            else if b == 0x5c { escaped += "\\\\" }
            else if b >= 0x20 && b <= 0x7E { escaped.append(Character(UnicodeScalar(b))) }
            else { escaped += String(format: "\\%03d", b) }
        }
        escaped += "\""
        result.append(escaped)
    }
    return result.joined(separator: " ")
}

func readName(data: [UInt8], offset: inout Int) -> String {
    var labels = [String]()
    var currentOffset = offset
    var jumped = false
    var nextOffset = 0

    while currentOffset < data.count && data[currentOffset] != 0 {
        let length = data[currentOffset]
        if (length & 0xC0) == 0xC0 {
            if currentOffset + 1 >= data.count { break }
            let pointer = Int(UInt16(length & 0x3F) << 8 | UInt16(data[currentOffset + 1]))
            if !jumped { nextOffset = currentOffset + 2 }
            currentOffset = pointer
            jumped = true
        } else {
            let start = currentOffset + 1
            let end = start + Int(length)
            if end > data.count { break }
            labels.append(String(decoding: data[start..<end], as: UTF8.self))
            currentOffset += Int(length) + 1
        }
    }

    if !jumped { nextOffset = currentOffset + 1 }
    offset = nextOffset
    let result = labels.joined(separator: ".").lowercased()
    return result.isEmpty ? "." : result
}

