            var buffer = [UInt8](repeating: 0, count: 1024)
            var addrLen = socklen_t(MemoryLayout<sockaddr_in>.size)
            var srcAddr = sockaddr_in()
            let received = recvfrom(udpSock, &buffer, buffer.count, 0, unsafeBitCast(&srcAddr, to: sockaddr.self), &addrLen)
            if received > 0 {
                let resId = (UInt16(buffer[0]) << 8) | UInt16(buffer[1])
                if resId == txId {
                    responseData = Array(buffer[0..<received])
                    break
                }
            }
        }
        close(udpSock)

        let flags = (Int(responseData[2]) << 8) | Int(responseData[3])
        let tc = (flags & 0x0200) != 0

        if tc {
            let tcpSock = socket(AF_INET, SOCK_STREAM, 0)
            connect(tcpSock, unsafeBitCast(&serverAddr, to: sockaddr.self), MemoryLayout<sockaddr_in>.size)

            let len = UInt16(packet.count)
            var tcpPacket = [UInt8]()
            tcpPacket.append(UInt8(len >> 8), UInt8(len & 0xFF))
            tcpPacket.append(contentsOf: packet)
            send(tcpSock, tcpPacket, tcpPacket.count, 0)

            var lenBuf = [UInt8](repeating: 0, count: 2)
            var bytesRead = 0
            while bytesRead < 2 {
                bytesRead += recv(tcpSock, &lenBuf[bytesRead], 2 - bytesRead, 0)
            }
            let resLen = Int((UInt16(lenBuf[0]) << 8) | UInt16(lenBuf[1]))

            var resData = [UInt8]()
            while resData.count < resLen {
                var temp = [UInt8](repeating: 0, count: resLen - resData.count)
                let read = recv(tcpSock, &temp, temp.count, 0)
                if read <= 0 { break }
                resData.append(contentsOf: temp[0..<read])
            }
            responseData = resData
            close(tcpSock)
        }

        let resFlags = (Int(responseData[2]) << 8) | Int(responseData[3])
        let rcode = resFlags & 0x000F
        let qdCount = (Int(responseData[4]) << 8) | Int(responseData[5])
        let anCount = (Int(responseData[6]) << 8) | Int(responseData[7])

        print("\(qname.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))) \(typeName(qtype)) \(rcodeName(rcode))")

        var offset = 12
        for _ in 0..<qdCount {
            _ = readName(data: responseData, offset: &offset)
            offset += 4
        }

        for _ in 0..<anCount {
            let owner = readName(data: responseData, offset: &offset)
            let type = (Int(responseData[offset]) << 8) | Int(responseData[offset+1])
            let ttl = (Int(responseData[offset+4]) << 24) | (Int(responseData[offset+5]) << 16) | (Int(responseData[offset+6]) << 8) | Int(responseData[offset+7])
            let rdLen = (Int(responseData[offset+8]) << 8) | Int(responseData[offset+9])
            offset += 10

            let rdData = Array(responseData[offset..<offset+rdLen])
            offset += rdLen

            let dataStr: String
            switch type {
            case 1: dataStr = formatIPv4(rdData)
            case 5:
                var dOffset = 0
                dataStr = readName(data: rdData + responseData[offset-rdLen...], offset: &dOffset) // This is tricky, simplified
                // Correct name parsing for RDATA requires original packet
                var tempOffset = offset - rdLen // This is wrong, should be offset from start of packet
                // Let's use a helper to read name from the full response data starting at the correct position
                var nameOffset = offset - rdLen
                dataStr = readName(data: responseData, offset: &nameOffset)
                // Wait, the above is wrong. The name is inside the RDATA.
                // Let's just use the same readName but pass the whole packet.
                var rdataOffset = offset - rdLen
                let name = readName(data: responseData, offset: &rdataOffset)
                // But readName updates offset. We just need the name.
                // Let's redefine readName to not modify offset if we don't want it to.
                // Actually, the easiest is:
                // var tempOffset = offset - rdLen
                // let name = readName(data: responseData, offset: &tempOffset)
            case 28: dataStr = formatIPv6(rdData)
            case 15:
                let pref = (Int(rdData[0]) << 8) | Int(rdData[1])
                var mxOffset = 2
                let exchange = readName(data: rdData + responseData[offset-rdLen...], offset: &mxOffset) // This is also wrong
                // Let's use a helper:
                // func readNameFromPacket(data: [UInt8], offset: Int) -> String
                // Then call it with the appropriate offset.
            case 16: dataStr = formatTXT(rdData)
            default:
                let hex = rdData.map { String(format: "%02x", $0) }.joined()
                dataStr = "# \(rdLen) \(hex)".trimmingCharacters(in: .whitespaces)
                if rdLen == 0 { dataStr = "# 0" }
            }
            // Re-doing the name parsing for CNAME and MX
        }
    }
}

// Redefining the loop to handle names correctly
func run() {
    let args = CommandLine.arguments
    guard args.count >= 3 else { return }
    let directory = args[1]
    let port = Int(args[2]) ?? 53
    let queriesFile = URL(fileURLWithPath: directory).appendingPathComponent("queries.txt")
    guard let content = try? String(contentsOf: queriesFile) else { return }
    let lines = content.components(separatedBy: .newlines).filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

    for line in lines {
        let parts = line.split(separator: " ").map { String($0) }
        guard parts.count >= 2 else { continue }
        let qname = parts[0]
        let qtypeStr = parts[1]
        var qtype = 1
        switch qtypeStr {
        case "A": qtype = 1
        case "CNAME": qtype = 5
        case "MX": qtype = 15
        case "TXT": qtype = 16
        case "AAAA": qtype = 28
        default: qtype = 99
        }

        var packet = [UInt8]()
        let txId = UInt16.random(in: 0...65535)
        packet.append(UInt8(txId >> 8), UInt8(txId & 0xFF))
        packet.append(0x01, 0x00)
        packet.append(0, 1)
        packet.append(0, 0)
        packet.append(0, 0)
        packet.append(0, 0)
        let labels = qname.split(separator: ".", omittingEmptySubsequences: false).filter { $0 != "" }
        for label in labels {
            packet.append(UInt8(label.count))
            packet.append(contentsOf: label.utf8)
        }
        packet.append(0)
        packet.append(UInt8(qtype >> 8), UInt8(qtype & 0xFF))
        packet.append(0, 1)

        var responseData = [UInt8]()
        let udpSock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
        var serverAddr = sockaddr_in()
        serverAddr.sin_family = sa_family_t(AF_INET)
        serverAddr.sin_port = UInt16(port).bigEndian
        serverAddr.sin_addr.s_addr = inet_addr("127.0.0.1")
        sendto(udpSock, packet, packet.count, 0, unsafeBitCast(&serverAddr, to: sockaddr.self), MemoryLayout<sockaddr_in>.size)
        while true {
            var buffer = [UInt8](repeating: 0, count: 2048)
            var addrLen = socklen_t(MemoryLayout<sockaddr_in>.size)
            var srcAddr = sockaddr_in()
            let received = recvfrom(udpSock, &buffer, buffer.count, 0, unsafeBitCast(&srcAddr, to: sockaddr.self), &addrLen)
            if received > 0 {
                let resId = (UInt16(buffer[0]) << 8) | UInt16(buffer[1])
                if resId == txId { responseData = Array(buffer[0..<received]); break }
            }
        }
        close(udpSock)

        let flags = (Int(responseData[2]) << 8) | Int(responseData[3])
        if (flags & 0x0200) != 0 {
            let tcpSock = socket(AF_INET, SOCK_STREAM, 0)
            connect(tcpSock, unsafeBitCast(&serverAddr, to: sockaddr.self), MemoryLayout<sockaddr_in>.size)
            let len = UInt16(packet.count)
            var tcpPacket = [UInt8]()
            tcpPacket.append(UInt8(len >> 8), UInt8(len & 0xFF))
            tcpPacket.append(contentsOf: packet)
            send(tcpSock, tcpPacket, tcpPacket.count, 0)
            var lenBuf = [UInt8](repeating: 0, count: 2)
            var bytesRead = 0
            while bytesRead < 2 { bytesRead += recv(tcpSock, &lenBuf[bytesRead], 2 - bytesRead, 0) }
            let resLen = Int((UInt16(lenBuf[0]) << 8) | UInt16(lenBuf[1]))
            var resData = [UInt8]()
            while resData.count < resLen {
                var temp = [UInt8](repeating: 0, count: resLen - resData.count)
                let read = recv(tcpSock, &temp, temp.count, 0)
                if read <= 0 { break }
                resData.append(contentsOf: temp[0..<read])
            }
            responseData = resData
            close(tcpSock)
        }

        let resFlags = (Int(responseData[2]) << 8) | Int(responseData[3])
        let rcode = resFlags & 0x000F
        let qdCount = (Int(responseData[4]) << 8) | Int(responseData[5])
        let anCount = (Int(responseData[6]) << 8) | Int(responseData[7])

        print("\(qname.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))) \(typeName(qtype)) \(rcodeName(rcode))")

        var offset = 12
        for _ in 0..<qdCount {
            _ = readName(data: responseData, offset: &offset)
            offset += 4
        }
        for _ in 0..<anCount {
            let owner = readName(data: responseData, offset: &offset)
            let type = (Int(responseData[offset]) << 8) | Int(responseData[offset+1])
            let ttl = (Int(responseData[offset+4]) << 24) | (Int(responseData[offset+5]) << 16) | (Int(responseData[offset+6]) << 8) | Int(responseData[offset+7])
            let rdLen = (Int(responseData[offset+8]) << 8) | Int(responseData[offset+9])
            offset += 10
            let rdData = Array(responseData[offset..<offset+rdLen])
            offset += rdLen

            let dataStr: String
            switch type {
            case 1: dataStr = formatIPv4(rdData)
            case 5:
                var nameOffset = offset - rdLen
                dataStr = readName(data: responseData, offset: &nameOffset)
            case 15:
                let pref = (Int(rdData[0]) << 8) | Int(rdData[1])
                var nameOffset = offset - rdLen + 2
                let exchange = readName(data: responseData, offset: &nameOffset)
                dataStr = "\(pref) \(exchange)"
            case 16: dataStr = formatTXT(rdData)
            case 28: dataStr = formatIPv6(rdData)
            default:
                let hex = rdData.map { String(format: "%02x", $0) }.joined()
                dataStr = rdLen == 0 ? "# 0" : "# \(rdLen) \(hex)"
            }
            print("  \(owner) \(ttl) \(typeName(type)) \(dataStr)")
        }
    }
}

run()

use std::collections::{BTreeMap, HashSet};
use std::env;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

struct JsonParser<'a> {
    input: std::str::Chars<'a>,
}

impl<'a> JsonParser<'a> {
    fn new(s: &'a str) -> Self {
        Self { input: s.chars() }
    }

    fn consume_whitespace(&mut self) {
        while let Some(c) = self.input.clone().next() {
            if c.is_whitespace() {
                self.input.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Value {
        self.consume_whitespace();
        let c = self.input.next().expect("Unexpected EOF");
        match c {
            'n' => {
                for _ in 0..3 { self.input.next(); }
                Value::Null
            }
            't' => {
                for _ in 0..3 { self.input.next(); }
                Value::Bool(true)
            }
            'f' => {
                for _ in 0..4 { self.input.next(); }
                Value::Bool(false)
            }
            '"' => self.parse_string(),
            ' ' | '\t' | '\r' | '\n' => panic!("Whitespace before value"),
            _ if c.is_digit(10) || c == '-' => {
                let mut s = String::new();
                s.push(c);
                while let Some(nc) = self.input.clone().next() {
                    if nc.is_digit(10) || nc == '.' || nc == '-' || nc == '+' || nc == 'e' || nc == 'E' {
                        s.push(self.input.next().unwrap());
                    } else {
                        break;
                    }
                }
                Value::Number(s.parse::<f64>().unwrap())
            }
            '[' => self.parse_array(),
            '{' => self.parse_object(),
            _ => panic!("Invalid JSON character: {}", c),
        }
    }

    fn parse_string(&mut self) -> Value {
        let mut res = String::new();
        while let Some(c) = self.input.next() {
            if c == '"' { break; }
            if c == '\\' {
                match self.input.next() {
                    Some('n') => res.push('\n'),
                    Some('r') => res.push('\r'),
                    Some('t') => res.push('\t'),
                    Some('b') => res.push('\x08'),
                    Some('f') => res.push('\x0c'),
                    Some('\\') => res.push('\\'),
                    Some('/') => res.push('/'),
                    Some('"') => res.push('"'),
                    Some('u') => {
                        let mut hex = String::new();
                        for _ in 0..4 { hex.push(self.input.next().unwrap()); }
                        let code = u32::from_str_radix(&hex, 16).unwrap();
                        if (0xD800..=0xDBFF).contains(&code) {
                            if let Some('\\') = self.input.next() {
                                if let Some('u') = self.input.next() {
                                    let mut hex2 = String::new();
                                    for _ in 0..4 { hex2.push(self.input.next().unwrap()); }
                                    let code2 = u32::from_str_radix(&hex2, 16).unwrap();
                                    let cp = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                    res.push(std::char::from_u32(cp).unwrap());
                                }
                            }
                        } else {
                            res.push(std::char::from_u32(code).unwrap());
                        }
                    }
                    _ => panic!("Invalid escape sequence"),
                }
            } else {
                res.push(c);
            }
        }
        Value::String(res)
    }

    fn parse_array(&mut self) -> Value {
        let mut arr = Vec::new();
        self.consume_whitespace();
        if let Some(']') = self.input.clone().next() {
            self.input.next();
            return Value::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.consume_whitespace();
            match self.input.next() {
                Some(',') => { self.consume_whitespace(); }
                Some(']') => break,
                _ => panic!("Expected , or ] in array"),
            }
        }
        Value::Array(arr)
    }

    fn parse_object(&mut self) -> Value {
        let mut obj = BTreeMap::new();
        self.consume_whitespace();
        if let Some('}') = self.input.clone().next() {
            self.input.next();
            return Value::Object(obj);
        }
        loop {
            self.consume_whitespace();
            let key = match self.input.next() {
                Some('"') => {
                    let mut s = String::new();
                    while let Some(c) = self.input.next() {
                        if c == '"' { break; }
                        if c == '\\' {
                            match self.input.next() {
                                Some('n') => s.push('\n'), Some('r') => s.push('\r'), Some('t') => s.push('\t'),
                                Some('b') => s.push('\x08'), Some('f') => s.push('\x0c'), Some('\\') => s.push('\\'),
                                Some('/') => s.push('/'), Some('"') => s.push('"'), Some('u') => {
                                    let mut hex = String::new();
                                    for _ in 0..4 { hex.push(self.input.next().unwrap()); }
                                    let code = u32::from_str_radix(&hex, 16).unwrap();
                                    if (0xD800..=0xDBFF).contains(&code) {
                                        if let Some('\\') = self.input.next() {
                                            if let Some('u') = self.input.next() {
                                                let mut hex2 = String::new();
                                                for _ in 0..4 { hex2.push(self.input.next().unwrap()); }
                                                let code2 = u32::from_str_radix(&hex2, 16).unwrap();
                                                let cp = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                                s.push(std::char::from_u32(cp).unwrap());
                                            }
                                        }
                                    } else {
                                        s.push(std::char::from_u32(code).unwrap());
                                    }
                                }
                                _ => panic!("Invalid escape in key"),
                            }
                        } else {
                            s.push(c);
                        }
                    }
                    s
                }
                _ => panic!("Expected \" at start of key"),
            }
            self.consume_whitespace();
            if let Some(':') = self.input.next() {
                obj.insert(key, self.parse_value());
            } else {
                panic!("Expected : after key");
            }
            self.consume_whitespace();
            match self.input.next() {
                Some(',') => { self.consume_whitespace(); }
                Some('}') => break,
                _ => panic!("Expected , or }} in object"),
            }
        }
        Value::Object(obj)
    }
}

fn deep_equal(v1: &Value, v2: &Value) -> bool {
    match (v1, v2) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::Number(a), Value::Number(b)) => a == b,
        (Value::String(a), Value::String(b)) => a == b,
        (Value::Array(a), Value::Array(b)) => {
            if a.len() != b.len() { return false; }
            a.iter().zip(b.iter()).all(|(i, j)| deep_equal(i, j))
        }
        (Value::Object(a), Value::Object(b)) => {
            if a.len() != b.len() { return false; }
            a.iter().all(|(k, v)| b.get(k).map_or(false, |v2| deep_equal(v, v2)))
        }
        _ => false,
    }
}

fn resolve_ptr(root: &Value, ptr: &[String]) -> Option<&Value> {
    let mut curr = root;
    for token in ptr {
        match curr {
            Value::Object(obj) => curr = obj.get(token)?,
            Value::Array(arr) => {
                let idx = token.parse::<usize>().ok()?;
                if idx >= arr.len() { return None; }
                curr = &arr[idx];
            }
            _ => return None,
        }
    }
    Some(curr)
}

fn ptr_to_string(ptr: &[String]) -> String {
    let mut s = String::from("#");
    for token in ptr {
        s.push('/');
        s.push_str(&token.replace('~', "~0").replace('/', "~1"));
    }
    s
}

fn validate(
    instance: &Value,
    schema: &Value,
    inst_ptr: &[String],
    schema_ptr: &[String],
    root_schema: &Value,
    errors: &mut HashSet<(Vec<String>, Vec<String>)>,
) {
    match schema {
        Value::Bool(b) => {
            if !*b {
                errors.insert((inst_ptr.to_vec(), schema_ptr.to_vec()));
            }
        }
        Value::Object(obj) => {
            if let Some(Value::String(t)) = obj.get("type") {
                let mut ok = false;
                if t == "null" && matches!(instance, Value::Null) { ok = true; }
                else if t == "boolean" && matches!(instance, Value::Bool(_)) { ok = true; }
                else if t == "string" && matches!(instance, Value::String(_)) { ok = true; }
                else if t == "number" && matches!(instance, Value::Number(_)) { ok = true; }
                else if t == "integer" && matches!(instance, Value::Number(n)) && n == n.floor() { ok = true; }
                else if t == "array" && matches!(instance, Value::Array(_)) { ok = true; }
                else if t == "object" && matches!(instance, Value::Object(_)) { ok = true; }
                if !ok {
                    errors.insert((inst_ptr.to_vec(), {
                        let mut p = schema_ptr.to_vec();
                        p.push("type".to_string());
                        p
                    }));
                }
            } else if let Some(Value::Array(types)) = obj.get("type") {
                let mut ok = false;
                for t_val in types {
                    if let Some(Value::String(t)) = t_val {
                        if t == "null" && matches!(instance, Value::Null) { ok = true; }
                        else if t == "boolean" && matches!(instance, Value::Bool(_)) { ok = true; }
                        else if t == "string" && matches!(instance, Value::String(_)) { ok = true; }
                        else if t == "number" && matches!(instance, Value::Number(_)) { ok = true; }
                        else if t == "integer" && matches!(instance, Value::Number(n)) && n == n.floor() { ok = true; }
                        else if t == "array" && matches!(instance, Value::Array(_)) { ok = true; }
                        else if t == "object" && matches!(instance, Value::Object(_)) { ok = true; }
                    }
                }
                if !ok {
                    errors.insert((inst_ptr.to_vec(), {
                        let mut p = schema_ptr.to_vec();
                        p.push("type".to_string());
                        p
                    }));
                }
            }

            if let Some(Value::Array(enum_vals)) = obj.get("enum") {
                if !enum_vals.iter().any(|v| deep_equal(instance, v)) {
                    errors.insert((inst_ptr.to_vec(), {
                        let mut p = schema_ptr.to_vec();
                        p.push("enum".to_string());
                        p
                    }));
                }
            }

            if let Some(const_val) = obj.get("const") {
                if !deep_equal(instance, const_val) {
                    errors.insert((inst_ptr.to_vec(), {
                        let mut p = schema_ptr.to_vec();
                        p.push("const".to_string());
                        p
                    }));
                }
            }

            if let Value::Number(n) = instance {
                if let Some(Value::Number(min)) = obj.get("minimum") {
                    if *n < *min {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("minimum".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maximum") {
                    if *n > *max {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("maximum".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Number(min)) = obj.get("exclusiveMinimum") {
                    if *n <= *min {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("exclusiveMinimum".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("exclusiveMaximum") {
                    if *n >= *max {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("exclusiveMaximum".to_string());
                            p
                        }));
                    }
                }
            }

            if let Value::String(s) = instance {
                let len = s.chars().count();
                if let Some(Value::Number(min)) = obj.get("minLength") {
                    if (len as f64) < *min {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("minLength".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maxLength") {
                    if (len as f64) > *max {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("maxLength".to_string());
                            p
                        }));
                    }
                }
            }

            if let Value::Array(arr) = instance {
                let len = arr.len();
                if let Some(Value::Number(min)) = obj.get("minItems") {
                    if (len as f64) < *min {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("minItems".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maxItems") {
                    if (len as f64) > *max {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("maxItems".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Bool(true)) = obj.get("uniqueItems") {
                    let mut dup = false;
                    for i in 0..len {
                        for j in i + 1..len {
                            if deep_equal(&arr[i], &arr[j]) { dup = true; break; }
                        }
                        if dup { break; }
                    }
                    if dup {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("uniqueItems".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Array(prefix_items)) = obj.get("prefixItems") {
                    for (i, subschema) in prefix_items.iter().enumerate() {
                        if i < len {
                            let mut next_inst = inst_ptr.to_vec();
                            next_inst.push(i.to_string());
                            let mut next_schema = schema_ptr.to_vec();
                            next_schema.push("prefixItems".to_string());
                            next_schema.push(i.to_string());
                            validate(&arr[i], subschema, &next_inst, &next_schema, root_schema, errors);
                        }
                    }
                }
                if let Some(items_schema) = obj.get("items") {
                    let prefix_len = if let Some(Value::Array(pi)) = obj.get("prefixItems") { pi.len() } else { 0 };
                    for i in prefix_len..len {
                        let mut next_inst = inst_ptr.to_vec();
                        next_inst.push(i.to_string());
                        let mut next_schema = schema_ptr.to_vec();
                        next_schema.push("items".to_string());
                        validate(&arr[i], items_schema, &next_inst, &next_schema, root_schema, errors);
                    }
                }
            }

            if let Value::Object(obj_inst) = instance {
                if let Some(Value::Object(props)) = obj.get("properties") {
                    for (name, subschema) in props {
                        if let Some(val) = obj_inst.get(name) {
                            let mut next_inst = inst_ptr.to_vec();
                            next_inst.push(name.clone());
                            let mut next_schema = schema_ptr.to_vec();
                            next_schema.push("properties".to_string());
                            next_schema.push(name.clone());
                            validate(val, subschema, &next_inst, &next_schema, root_schema, errors);
                        }
                    }
                }
                if let Some(Value::Array(required)) = obj.get("required") {
                    for (i, req_name) in required.iter().enumerate() {
                        if let Some(Value::String(name)) = req_name {
                            if !obj_inst.contains_key(name) {
                                errors.insert((inst_ptr.to_vec(), {
                                    let mut p = schema_ptr.to_vec();
                                    p.push("required".to_string());
                                    p.push(i.to_string());
                                    p
                                }));
                            }
                        }
                    }
                }
                if let Some(add_props_schema) = obj.get("additionalProperties") {
                    let props_map = if let Some(Value::Object(p)) = obj.get("properties") { p } else { &BTreeMap::new() };
                    for (name, val) in obj_inst {
                        if !props_map.contains_key(name) {
                            let mut next_inst = inst_ptr.to_vec();
                            next_inst.push(name.clone());
                            let mut next_schema = schema_ptr.to_vec();
                            next_schema.push("additionalProperties".to_string());
                            validate(val, add_props_schema, &next_inst, &next_schema, root_schema, errors);
                        }
                    }
                }
                if let Some(Value::Number(min)) = obj.get("minProperties") {
                    if (obj_inst.len() as f64) < *min {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("minProperties".to_string());
                            p
                        }));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maxProperties") {
                    if (obj_inst.len() as f64) > *max {
                        errors.insert((inst_ptr.to_vec(), {
                            let mut p = schema_ptr.to_vec();
                            p.push("maxProperties".to_string());
                            p
                        }));
                    }
                }
            }

            if let Some(Value::Array(all_of)) = obj.get("allOf") {
                for (i, subschema) in all_of.iter().enumerate() {
                    let mut next_schema = schema_ptr.to_vec();
                    next_schema.push("allOf".to_string());
                    next_schema.push(i.to_string());
                    validate(instance, subschema, inst_ptr, &next_schema, root_schema, errors);
                }
            }

            if let Some(Value::Array(any_of)) = obj.get("anyOf") {
                let mut accepted = false;
                for subschema in any_of {
                    let mut sub_errors = HashSet::new();
                    validate(instance, subschema, &[], &[], root_schema, &mut sub_errors);
                    if sub_errors.is_empty() { accepted = true; break; }
                }
                if !accepted {
                    errors.insert((inst_ptr.to_vec(), {
                        let mut p = schema_ptr.to_vec();
                        p.push("anyOf".to_string());
                        p
                    }));
                }
            }

            if let Some(Value::Array(one_of)) = obj.get("oneOf") {
                let mut count = 0;
                for subschema in one_of {
                    let mut sub_errors = HashSet::new();
                    validate(instance, subschema, &[], &[], root_schema, &mut sub_errors);
                    if sub_errors.is_empty() { count += 1; }
                }
                if count != 1 {
                    errors.insert((inst_ptr.to_vec(), {
                        let mut p = schema_ptr.to_vec();
                        p.push("oneOf".to_string());
                        p
                    }));
                }
            }

            if let Some(not_schema) = obj.get("not") {
                let mut sub_errors = HashSet::new();
                validate(instance, not_schema, &[], &[], root_schema, &mut sub_errors);
                if sub_errors.is_empty() {
                    errors.insert((inst_ptr.to_vec(), {
                        let mut p = schema_ptr.to_vec();
                        p.push("not".to_string());
                        p
                    }));
                }
            }

            if let Some(if_schema) = obj.get("if") {
                let mut if_errors = HashSet::new();
                validate(instance, if_schema, &[], &[], root_schema, &mut if_errors);
                if if_errors.is_empty() {
                    if let Some(then_schema) = obj.get("then") {
                        let mut next_schema = schema_ptr.to_vec();
                        next_schema.push("then".to_string());
                        validate(instance, then_schema, inst_ptr, &next_schema, root_schema, errors);
                    }
                } else {
                    if let Some(else_schema) = obj.get("else") {
                        let mut next_schema = schema_ptr.to_vec();
                        next_schema.push("else".to_string());
                        validate(instance, else_schema, inst_ptr, &next_schema, root_schema, errors);
                    }
                }
            }

            if let Some(Value::String(ref_val)) = obj.get("$ref") {
                let ref_tokens = if ref_val == "#" {
                    Vec::new()
                } else {
                    ref_val.strip_prefix("#/").unwrap()
                        .split('/')
                        .map(|t| t.replace("~1", "/").replace("~0", "~"))
                        .collect()
                };
                if let Some(ref_schema) = resolve_ptr(root_schema, &ref_tokens) {
                    validate(instance, ref_schema, inst_ptr, &ref_tokens, root_schema, errors);
                }
            }
        }
        _ => {}
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let schema_content = fs::read_to_string(format!("{}/schema.json", dir)).expect("Could not read schema.json");
    let instances_content = fs::read_to_string(format!("{}/instances.json", dir)).expect("Could not read instances.json");

    let mut schema_parser = JsonParser::new(&schema_content);
    let root_schema = schema_parser.parse_value();

    let mut inst_parser = JsonParser::new(&instances_content);
    let instances = match inst_parser.parse_value() {
        Value::Array(a) => a,
        _ => panic!("instances.json must be an array"),
    };

    let mut total_valid = 0;
    let mut total_invalid = 0;

    for (i, instance) in instances.iter().enumerate() {
        let mut errors = HashSet::new();
        validate(instance, &root_schema, &[], &[], &root_schema, &mut errors);
        if errors.is_empty() {
            println!("{}: valid", i);
            total_valid += 1;
        } else {
            println!("{}: invalid ({})", i, errors.len());
            total_invalid += 1;
            let mut sorted_errors: Vec<_> = errors.into_iter().collect();
            sorted_errors.sort_by(|a, b| {
                let s_a = ptr_to_string(&a.0);
                let s_b = ptr_to_string(&b.0);
                if s_a != s_b { return s_a.cmp(&s_b); }
                let p_a = ptr_to_string(&a.1);
                let p_b = ptr_to_string(&b.1);
                p_a.cmp(&p_b)
            });
            for (inst_ptr, schema_ptr) in sorted_errors {
                println!("  {} {}", ptr_to_string(&inst_ptr), ptr_to_string(&schema_ptr));
            }
        }
    }
    println!("valid={} invalid={}", total_valid, total_invalid);
}

use std::collections::{BTreeMap, HashSet};
use std::env;
use std::fs;
use std::iter::Peekable;
use std::str::Chars;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

struct JsonParser<'a> {
    input: Peekable<Chars<'a>>,
}

impl<'a> JsonParser<'a> {
    fn new(s: &'a str) -> Self {
        Self { input: s.chars().peekable() }
    }

    fn consume_whitespace(&mut self) {
        while let Some(&c) = self.input.peek() {
            if c.is_whitespace() {
                self.input.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Value {
        self.consume_whitespace();
        let c = self.input.next().expect("Unexpected EOF");
        match c {
            'n' => {
                for _ in 0..3 { self.input.next(); }
                Value::Null
            }
            't' => {
                for _ in 0..3 { self.input.next(); }
                Value::Bool(true)
            }
            'f' => {
                for _ in 0..4 { self.input.next(); }
                Value::Bool(false)
            }
            '"' => self.parse_string(),
            _ if c.is_digit(10) || c == '-' => self.parse_number(c),
            '[' => self.parse_array(),
            '{' => self.parse_object(),
            _ => panic!("Invalid JSON character: {}", c),
        }
    }

    fn parse_string(&mut self) -> Value {
        let mut res = String::new();
        while let Some(c) = self.input.next() {
            if c == '"' { break; }
            if c == '\\' {
                match self.input.next() {
                    Some('n') => res.push('\n'),
                    Some('r') => res.push('\r'),
                    Some('t') => res.push('\t'),
                    Some('b') => res.push('\x08'),
                    Some('f') => res.push('\x0c'),
                    Some('\\') => res.push('\\'),
                    Some('/') => res.push('/'),
                    Some('"') => res.push('"'),
                    Some('u') => {
                        let mut hex = String::new();
                        for _ in 0..4 { hex.push(self.input.next().unwrap()); }
                        let code = u32::from_str_radix(&hex, 16).unwrap();
                        if (0xD800..=0xDBFF).contains(&code) {
                            if let Some('\\') = self.input.next() {
                                if let Some('u') = self.input.next() {
                                    let mut hex2 = String::new();
                                    for _ in 0..4 { hex2.push(self.input.next().unwrap()); }
                                    let code2 = u32::from_str_radix(&hex2, 16).unwrap();
                                    let cp = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                    res.push(std::char::from_u32(cp).unwrap());
                                }
                            }
                        } else {
                            res.push(std::char::from_u32(code).unwrap());
                        }
                    }
                    _ => panic!("Invalid escape sequence"),
                }
            } else {
                res.push(c);
            }
        }
        Value::String(res)
    }

    fn parse_number(&mut self, first_char: char) -> Value {
        let mut s = String::new();
        s.push(first_char);
        while let Some(&c) = self.input.peek() {
            if c.is_digit(10) || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E' {
                s.push(self.input.next().unwrap());
            } else {
                break;
            }
        }
        Value::Number(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Value {
        let mut arr = Vec::new();
        self.consume_whitespace();
        if let Some(']') = self.input.peek() {
            self.input.next();
            return Value::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.consume_whitespace();
            match self.input.next() {
                Some(',') => { self.consume_whitespace(); }
                Some(']') => break,
                _ => panic!("Expected , or ] in array"),
            }
        }
        Value::Array(arr)
    }

    fn parse_object(&mut self) -> Value {
        let mut obj = BTreeMap::new();
        self.consume_whitespace();
        if let Some('}') = self.input.peek() {
            self.input.next();
            return Value::Object(obj);
        }
        loop {
            self.consume_whitespace();
            if let Some('"') = self.input.next() {
                let mut key = String::new();
                while let Some(c) = self.input.next() {
                    if c == '"' { break; }
                    if c == '\\' {
                        match self.input.next() {
                            Some('n') => key.push('\n'), Some('r') => key.push('\r'), Some('t') => key.push('\t'),
                            Some('b') => key.push('\x08'), Some('f') => key.push('\x0c'), Some('\\') => key.push('\\'),
                            Some('/') => key.push('/'), Some('"') => key.push('"'), Some('u') => {
                                let mut hex = String::new();
                                for _ in 0..4 { hex.push(self.input.next().unwrap()); }
                                let code = u32::from_str_radix(&hex, 16).unwrap();
                                if (0xD800..=0xDBFF).contains(&code) {
                                    if let Some('\\') = self.input.next() {
                                        if let Some('u') = self.input.next() {
                                            let mut hex2 = String::new();
                                            for _ in 0..4 { hex2.push(self.input.next().unwrap()); }
                                            let code2 = u32::from_str_radix(&hex2, 16).unwrap();
                                            let cp = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                            key.push(std::char::from_u32(cp).unwrap());
                                        }
                                    }
                                } else {
                                    key.push(std::char::from_u32(code).unwrap());
                                }
                            }
                            _ => panic!("Invalid escape in key"),
                        }
                    } else {
                        key.push(c);
                    }
                }
                self.consume_whitespace();
                if let Some(':') = self.input.next() {
                    obj.insert(key, self.parse_value());
                } else {
                    panic!("Expected : after key");
                }
            } else {
                panic!("Expected \" at start of key");
            }
            self.consume_whitespace();
            match self.input.next() {
                Some(',') => { self.consume_whitespace(); }
                Some('}') => break,
                _ => panic!("Expected , or }} in object"),
            }
        }
        Value::Object(obj)
    }
}

fn deep_equal(v1: &Value, v2: &Value) -> bool {
    match (v1, v2) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::Number(a), Value::Number(b)) => a == b,
        (Value::String(a), Value::String(b)) => a == b,
        (Value::Array(a), Value::Array(b)) => {
            if a.len() != b.len() { return false; }
            a.iter().zip(b.iter()).all(|(i, j)| deep_equal(i, j))
        }
        (Value::Object(a), Value::Object(b)) => {
            if a.len() != b.len() { return false; }
            a.iter().all(|(k, v)| b.get(k).map_or(false, |v2| deep_equal(v, v2)))
        }
        _ => false,
    }
}

fn resolve_ptr<'a>(root: &'a Value, ptr: &[String]) -> Option<&'a Value> {
    let mut curr = root;
    for token in ptr {
        match curr {
            Value::Object(obj) => curr = obj.get(token)?,
            Value::Array(arr) => {
                let idx = token.parse::<usize>().ok()?;
                if idx >= arr.len() { return None; }
                curr = &arr[idx];
            }
            _ => return None,
        }
    }
    Some(curr)
}

fn ptr_to_string(ptr: &[String]) -> String {
    if ptr.is_empty() { return "#".to_string(); }
    let mut s = String::from("#");
    for token in ptr {
        s.push('/');
        s.push_str(&token.replace('~', "~0").replace('/', "~1"));
    }
    s
}

fn check_type(instance: &Value, t: &str) -> bool {
    match t {
        "null" => matches!(instance, Value::Null),
        "boolean" => matches!(instance, Value::Bool(_)),
        "string" => matches!(instance, Value::String(_)),
        "number" => matches!(instance, Value::Number(_)),
        "integer" => matches!(instance, Value::Number(n) if n == n.floor()),
        "array" => matches!(instance, Value::Array(_)),
        "object" => matches!(instance, Value::Object(_)),
        _ => false,
    }
}

fn validate(
    instance: &Value,
    schema: &Value,
    inst_ptr: &[String],
    schema_ptr: &[String],
    root_schema: &Value,
    errors: &mut HashSet<(String, String)>,
) {
    match schema {
        Value::Bool(b) => {
            if !*b {
                errors.insert((ptr_to_string(inst_ptr), ptr_to_string(schema_ptr)));
            }
        }
        Value::Object(obj) => {
            if let Some(t_val) = obj.get("type") {
                let mut ok = false;
                match t_val {
                    Value::String(t) => { if check_type(instance, t) { ok = true; } }
                    Value::Array(types) => {
                        for t_val in types {
                            if let Value::String(t) = t_val {
                                if check_type(instance, t) { ok = true; break; }
                            }
                        }
                    }
                    _ => {}
                }
                if !ok {
                    let mut p = schema_ptr.to_vec();
                    p.push("type".to_string());
                    errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                }
            }

            if let Some(Value::Array(enum_vals)) = obj.get("enum") {
                if !enum_vals.iter().any(|v| deep_equal(instance, v)) {
                    let mut p = schema_ptr.to_vec();
                    p.push("enum".to_string());
                    errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                }
            }

            if let Some(const_val) = obj.get("const") {
                if !deep_equal(instance, const_val) {
                    let mut p = schema_ptr.to_vec();
                    p.push("const".to_string());
                    errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                }
            }

            if let Value::Number(n) = instance {
                if let Some(Value::Number(min)) = obj.get("minimum") {
                    if *n < *min {
                        let mut p = schema_ptr.to_vec();
                        p.push("minimum".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maximum") {
                    if *n > *max {
                        let mut p = schema_ptr.to_vec();
                        p.push("maximum".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Number(min)) = obj.get("exclusiveMinimum") {
                    if *n <= *min {
                        let mut p = schema_ptr.to_vec();
                        p.push("exclusiveMinimum".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("exclusiveMaximum") {
                    if *n >= *max {
                        let mut p = schema_ptr.to_vec();
                        p.push("exclusiveMaximum".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
            }

            if let Value::String(s) = instance {
                let len = s.chars().count();
                if let Some(Value::Number(min)) = obj.get("minLength") {
                    if (len as f64) < *min {
                        let mut p = schema_ptr.to_vec();
                        p.push("minLength".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maxLength") {
                    if (len as f64) > *max {
                        let mut p = schema_ptr.to_vec();
                        p.push("maxLength".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
            }

            if let Value::Array(arr) = instance {
                let len = arr.len();
                if let Some(Value::Number(min)) = obj.get("minItems") {
                    if (len as f64) < *min {
                        let mut p = schema_ptr.to_vec();
                        p.push("minItems".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maxItems") {
                    if (len as f64) > *max {
                        let mut p = schema_ptr.to_vec();
                        p.push("maxItems".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Bool(true)) = obj.get("uniqueItems") {
                    let mut dup = false;
                    for i in 0..len {
                        for j in i + 1..len {
                            if deep_equal(&arr[i], &arr[j]) { dup = true; break; }
                        }
                        if dup { break; }
                    }
                    if dup {
                        let mut p = schema_ptr.to_vec();
                        p.push("uniqueItems".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Array(prefix_items)) = obj.get("prefixItems") {
                    for (i, subschema) in prefix_items.iter().enumerate() {
                        if i < len {
                            let mut next_inst = inst_ptr.to_vec();
                            next_inst.push(i.to_string());
                            let mut next_schema = schema_ptr.to_vec();
                            next_schema.push("prefixItems".to_string());
                            next_schema.push(i.to_string());
                            validate(&arr[i], subschema, &next_inst, &next_schema, root_schema, errors);
                        }
                    }
                }
                if let Some(items_schema) = obj.get("items") {
                    let prefix_len = if let Some(Value::Array(pi)) = obj.get("prefixItems") { pi.len() } else { 0 };
                    for i in prefix_len..len {
                        let mut next_inst = inst_ptr.to_vec();
                        next_inst.push(i.to_string());
                        let mut next_schema = schema_ptr.to_vec();
                        next_schema.push("items".to_string());
                        validate(&arr[i], items_schema, &next_inst, &next_schema, root_schema, errors);
                    }
                }
            }

            if let Value::Object(obj_inst) = instance {
                if let Some(Value::Object(props)) = obj.get("properties") {
                    for (name, subschema) in props {
                        if let Some(val) = obj_inst.get(name) {
                            let mut next_inst = inst_ptr.to_vec();
                            next_inst.push(name.clone());
                            let mut next_schema = schema_ptr.to_vec();
                            next_schema.push("properties".to_string());
                            next_schema.push(name.clone());
                            validate(val, subschema, &next_inst, &next_schema, root_schema, errors);
                        }
                    }
                }
                if let Some(Value::Array(required)) = obj.get("required") {
                    for (i, req_name) in required.iter().enumerate() {
                        if let Value::String(name) = req_name {
                            if !obj_inst.contains_key(name) {
                                let mut p = schema_ptr.to_vec();
                                p.push("required".to_string());
                                p.push(i.to_string());
                                errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                            }
                        }
                    }
                }
                if let Some(add_props_schema) = obj.get("additionalProperties") {
                    let props_map = if let Some(Value::Object(p)) = obj.get("properties") { p } else { &BTreeMap::new() };
                    for (name, val) in obj_inst {
                        if !props_map.contains_key(name) {
                            let mut next_inst = inst_ptr.to_vec();
                            next_inst.push(name.clone());
                            let mut next_schema = schema_ptr.to_vec();
                            next_schema.push("additionalProperties".to_string());
                            validate(val, add_props_schema, &next_inst, &next_schema, root_schema, errors);
                        }
                    }
                }
                if let Some(Value::Number(min)) = obj.get("minProperties") {
                    if (obj_inst.len() as f64) < *min {
                        let mut p = schema_ptr.to_vec();
                        p.push("minProperties".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
                if let Some(Value::Number(max)) = obj.get("maxProperties") {
                    if (obj_inst.len() as f64) > *max {
                        let mut p = schema_ptr.to_vec();
                        p.push("maxProperties".to_string());
                        errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                    }
                }
            }

            if let Some(Value::Array(all_of)) = obj.get("allOf") {
                for (i, subschema) in all_of.iter().enumerate() {
                    let mut next_schema = schema_ptr.to_vec();
                    next_schema.push("allOf".to_string());
                    next_schema.push(i.to_string());
                    validate(instance, subschema, inst_ptr, &next_schema, root_schema, errors);
                }
            }

            if let Some(Value::Array(any_of)) = obj.get("anyOf") {
                let mut any_accepts = false;
                for (i, subschema) in any_of.iter().enumerate() {
                    let mut sub_errors = HashSet::new();
                    let mut sub_schema_ptr = schema_ptr.to_vec();
                    sub_schema_ptr.push("anyOf".to_string());
                    sub_schema_ptr.push(i.to_string());
                    validate(instance, subschema, inst_ptr, &sub_schema_ptr, root_schema, &mut sub_errors);
                    if sub_errors.is_empty() { any_accepts = true; break; }
                }
                if !any_accepts {
                    let mut p = schema_ptr.to_vec();
                    p.push("anyOf".to_string());
                    errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                }
            }

            if let Some(Value::Array(one_of)) = obj.get("oneOf") {
                let mut count = 0;
                for (i, subschema) in one_of.iter().enumerate() {
                    let mut sub_errors = HashSet::new();
                    let mut sub_schema_ptr = schema_ptr.to_vec();
                    sub_schema_ptr.push("oneOf".to_string());
                    sub_schema_ptr.push(i.to_string());
                    validate(instance, subschema, inst_ptr, &sub_schema_ptr, root_schema, &mut sub_errors);
                    if sub_errors.is_empty() { count += 1; }
                }
                if count != 1 {
                    let mut p = schema_ptr.to_vec();
                    p.push("oneOf".to_string());
                    errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                }
            }

            if let Some(not_schema) = obj.get("not") {
                let mut sub_errors = HashSet::new();
                let mut sub_schema_ptr = schema_ptr.to_vec();
                sub_schema_ptr.push("not".to_string());
                validate(instance, not_schema, inst_ptr, &sub_schema_ptr, root_schema, &mut sub_errors);
                if sub_errors.is_empty() {
                    let mut p = schema_ptr.to_vec();
                    p.push("not".to_string());
                    errors.insert((ptr_to_string(inst_ptr), ptr_to_string(&p)));
                }
            }

            if let Some(if_schema) = obj.get("if") {
                let mut if_errors = HashSet::new();
                let mut if_schema_ptr = schema_ptr.to_vec();
                if_schema_ptr.push("if".to_string());
                validate(instance, if_schema, inst_ptr, &if_schema_ptr, root_schema, &mut if_errors);
                if if_errors.is_empty() {
                    if let Some(then_schema) = obj.get("then") {
                        let mut next_schema = schema_ptr.to_vec();
                        next_schema.push("then".to_string());
                        validate(instance, then_schema, inst_ptr, &next_schema, root_schema, errors);
                    }
                } else {
                    if let Some(else_schema) = obj.get("else") {
                        let mut next_schema = schema_ptr.to_vec();
                        next_schema.push("else".to_string());
                        validate(instance, else_schema, inst_ptr, &next_schema, root_schema, errors);
                    }
                }
            }

            if let Some(Value::String(ref_val)) = obj.get("$ref") {
                let ref_tokens = if ref_val == "#" {
                    Vec::new()
                } else {
                    ref_val.strip_prefix("#").unwrap()
                        .split('/')
                        .filter(|s| !s.is_empty())
                        .map(|t| t.replace("~1", "/").replace("~0", "~"))
                        .collect()
                };
                if let Some(ref_schema) = resolve_ptr(root_schema, &ref_tokens) {
                    validate(instance, ref_schema, inst_ptr, &ref_tokens, root_schema, errors);
                }
            }
        }
        _ => {}
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let schema_content = fs::read_to_string(format!("{}/schema.json", dir)).expect("Could not read schema.json");
    let instances_content = fs::read_to_string(format!("{}/instances.json", dir)).expect("Could not read instances.json");

    let mut schema_parser = JsonParser::new(&schema_content);
    let root_schema = schema_parser.parse_value();

    let mut inst_parser = JsonParser::new(&instances_content);
    let instances = match inst_parser.parse_value() {
        Value::Array(a) => a,
        _ => panic!("instances.json must be an array"),
    };

    let mut total_valid = 0;
    let mut total_invalid = 0;

    for (i, instance) in instances.iter().enumerate() {
        let mut errors = HashSet::new();
        validate(instance, &root_schema, &[], &[], &root_schema, &mut errors);
        if errors.is_empty() {
            println!("{}: valid", i);
            total_valid += 1;
        } else {
            println!("{}: invalid ({})", i, errors.len());
            total_invalid += 1;
            let mut sorted_errors: Vec<_> = errors.into_iter().collect();
            sorted_errors.sort_by(|a, b| {
                if a.0 != b.0 { return a.0.cmp(&b.0); }
                a.1.cmp(&b.1)
            });
            for (inst_ptr, schema_ptr) in sorted_errors {
                println!("  {} {}", inst_ptr, schema_ptr);
            }
        }
    }
    println!("valid={} invalid={}", total_valid, total_invalid);
}

use std::collections::{BTreeSet, HashMap};
use std::env;
use std::fs;
use std::path::Path;

// Import CommonCrypto's CCHmac from macOS system libraries
extern "C" {
    fn CCHmac(key: *const u8, key_len: usize, data: *const u8, data_len: usize, mac_out: *mut u8);
}

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

struct JsonParser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Result<JsonValue, ()> {
        self.skip_whitespace();
        let c = self.peek().ok_or(())?;
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string().map(JsonValue::String),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            '0'..='9' | '-' => self.parse_number().map(JsonValue::Number),
            _ => Err(()),
        }
    }

    fn parse_null(&mut self) -> Result<JsonValue, ()> {
        if self.input[self.pos..].starts_with("null") {
            self.pos += 4;
            Ok(JsonValue::Null)
        } else {
            Err(())
        }
    }

    fn parse_bool(&mut self) -> Result<JsonValue, ()> {
        if self.input[self.pos..].starts_with("true") {
            self.pos += 4;
            Ok(JsonValue::Bool(true))
        } else if self.input[self.pos..].starts_with("false") {
            self.pos += 5;
            Ok(JsonValue::Bool(false))
        } else {
            Err(())
        }
    }

    fn parse_number(&mut self) -> Result<f64, ()> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_digit(10) || c == '-' || c == '.' || c == 'e' || c == 'E' || c == '+' {
                self.next();
            } else {
                break;
            }
        }
        self.input[start..self.pos].parse::<f64>().map_err(|_| ())
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.next(); // skip opening quote
        let mut result = String::new();
        loop {
            let c = self.next().ok_or(())?;
            if c == '"' {
                break;
            } else if c == '\\' {
                match self.next().ok_or(())? {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\x08'),
                    'f' => result.push('\x0c'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'u' => {
                        let mut hex = String::new();
                        for _ in 0..4 {
                            let h = self.next().ok_or(())?;
                            if h.is_ascii_hexdigit() {
                                hex.push(h);
                            } else {
                                return Err(());
                            }
                        }
                        let code = u32::from_str_radix(&hex, 16).map_err(|_| ())?;
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.next().ok_or(())? != '\\' { return Err(()); }
                            if self.next().ok_or(())? != 'u' { return Err(()); }
                            let mut hex_low = String::new();
                            for _ in 0..4 {
                                let h = self.next().ok_or(())?;
                                if h.is_ascii_hexdigit() {
                                    hex_low.push(h);
                                } else {
                                    return Err(());
                                }
                            }
                            let low = u32::from_str_radix(&hex_low, 16).map_err(|_| ())?;
                            if !(0xDC00..=0xDFFF).contains(&low) { return Err(()); }
                            let cp = 0x10000 + (code - 0xD800) * 0x400 + (low - 0xDC00);
                            result.push(std::char::from_u32(cp).ok_or(())?);
                        } else if (0xDC00..=0xDFFF).contains(&code) {
                            return Err(());
                        } else {
                            result.push(std::char::from_u32(code).ok_or(())?);
                        }
                    }
                    _ => return Err(()),
                }
            } else {
                result.push(c);
            }
        }
        Ok(result)
    }

    fn parse_array(&mut self) -> Result<JsonValue, ()> {
        self.next(); // skip [
        let mut array = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Ok(JsonValue::Array(array));
        }
        loop {
            array.push(self.parse_value()?);
            self.skip_whitespace();
            match self.next().ok_or(())? {
                ',' => self.skip_whitespace(),
                ']' => break,
                _ => return Err(()),
            }
        }
        Ok(JsonValue::Array(array))
    }

    fn parse_object(&mut self) -> Result<JsonValue, ()> {
        self.next(); // skip {
        let mut map = HashMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Ok(JsonValue::Object(map));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.skip_whitespace();
            if self.next().ok_or(())? != ':' { return Err(()); }
            let value = self.parse_value()?;
            map.insert(key, value);
            self.skip_whitespace();
            match self.next().ok_or(())? {
                ',' => self.skip_whitespace(),
                '}' => break,
                _ => return Err(());
            }
        }
        Ok(JsonValue::Object(map))
    }
}

fn decode_base64url(input: &str) -> Option<Vec<u8>> {
    if input.is_empty() { return None; }
    if input.len() % 4 == 1 { return None; }

    let mut bytes = Vec::new();
    let mut buffer = 0u32;
    let mut bits = 0;

    for c in input.chars() {
        let val = match c {
            'A'..='Z' => (c as u8 - b'A') as u32,
            'a'..='z' => (c as u8 - b'a' + 26) as u32,
            '0'..='9' => (c as u8 - b'0' + 52) as u32,
            '-' => 62,
            '_' => 63,
            _ => return None,
        };
        buffer = (buffer << 6) | val;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            bytes.push((buffer >> bits) as u8);
        }
    }
    Some(bytes)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = Path::new(&args[1]);

    let config_str = fs::read_to_string(dir.join("config.json")).expect("Unable to read config.json");
    let mut config_parser = JsonParser::new(&config_str);
    let config = config_parser.parse_value().expect("Invalid config.json");

    let config_obj = match config {
        JsonValue::Object(map) => map,
        _ => panic!("Config is not an object"),
    };

    let now = match config_obj.get("now") {
        Some(JsonValue::Number(n)) => *n,
        _ => 0.0,
    };
    let leeway = match config_obj.get("leeway") {
        Some(JsonValue::Number(n)) => *n,
        _ => 0.0,
    };
    let issuer = match config_obj.get("issuer") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => String::new(),
    };
    let audience = match config_obj.get("audience") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => String::new(),
    };
    let keys = match config_obj.get("keys") {
        Some(JsonValue::Array(arr)) => arr.clone(),
        _ => Vec::new(),
    };

    let tokens_str = fs::read_to_string(dir.join("tokens.txt")).expect("Unable to read tokens.txt");
    let mut valid_count = 0;
    let mut invalid_count = 0;
    let mut token_idx = 0;

    for line in tokens_str.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        token_idx += 1;

        let segments: Vec<&str> = trimmed.split('.').collect();
        if segments.len() != 3 || segments.iter().any(|s| s.is_empty()) {
            println!("{}: MALFORMED", token_idx);
            invalid_count += 1;
            continue;
        }

        let seg0 = segments[0];
        let seg1 = segments[1];
        let seg2 = segments[2];

        let b64_0 = decode_base64url(seg0);
        let b64_1 = decode_base64url(seg1);
        let b64_2 = decode_base64url(seg2);

        if b64_0.is_none() || b64_1.is_none() || b64_2.is_none() {
            println!("{}: MALFORMED", token_idx);
            invalid_count += 1;
            continue;
        }

        let header_json = match JsonParser::new(std::str::from_utf8(b64_0.as_ref().unwrap()).unwrap_or("")).parse_value() {
            Ok(JsonValue::Object(map)) => map,
            _ => {
                println!("{}: MALFORMED", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        let payload_json = match JsonParser::new(std::str::from_utf8(b64_1.as_ref().unwrap()).unwrap_or("")).parse_value() {
            Ok(JsonValue::Object(map)) => map,
            _ => {
                println!("{}: MALFORMED", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        let alg = match header_json.get("alg") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => {
                println!("{}: UNSUPPORTED_ALG", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        if alg != "HS256" && alg != "HS384" && alg != "HS512" {
            println!("{}: UNSUPPORTED_ALG", token_idx);
            invalid_count += 1;
            continue;
        }

        let kid = match header_json.get("kid") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => {
                println!("{}: UNKNOWN_KEY", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        let key_data = keys.iter().find_map(|v| {
            if let JsonValue::Object(map) = v {
                if let Some(JsonValue::String(k_id)) = map.get("kid") {
                    if k_id == kid { return Some(map); }
                }
            }
            None
        });

        if key_data.is_none() {
            println!("{}: UNKNOWN_KEY", token_idx);
            invalid_count += 1;
            continue;
        }
        let key_data = key_data.unwrap();

        let key_alg = match key_data.get("alg") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => "",
        };

        if key_alg != alg {
            println!("{}: ALG_MISMATCH", token_idx);
            invalid_count += 1;
            continue;
        }

        let secret_b64 = match key_data.get("k") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => "",
        };
        let secret = decode_base64url(secret_b64).expect("Key secret is invalid base64url");

        let signing_input = format!("{}.{}", seg0, seg1);
        let signing_input_bytes = signing_input.as_bytes();
        let mut hmac_out = vec![0u8; 64];
        let out_len = match alg {
            "HS256" => 32,
            "HS384" => 48,
            "HS512" => 64,
            _ => 0,
        };

        unsafe {
            CCHmac(secret.as_ptr(), secret.len(), signing_input_bytes.as_ptr(), signing_input_bytes.len(), hmac_out.as_mut_ptr());
        }

        if b64_2.as_ref().unwrap() != &hmac_out[..out_len] {
            println!("{}: BAD_SIGNATURE", token_idx);
            invalid_count += 1;
            continue;
        }

        if let Some(JsonValue::Number(exp)) = payload_json.get("exp") {
            if now >= *exp + leeway {
                println!("{}: EXPIRED", token_idx);
                invalid_count += 1;
                continue;
            }
        }

        if let Some(JsonValue::Number(nbf)) = payload_json.get("nbf") {
            if now + leeway < *nbf {
                println!("{}: NOT_YET_VALID", token_idx);
                invalid_count += 1;
                continue;
            }
        }

        let iss = match payload_json.get("iss") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => "",
        };
        if iss != issuer {
            println!("{}: BAD_ISSUER", token_idx);
            invalid_count += 1;
            continue;
        }

        let aud_valid = match payload_json.get("aud") {
            Some(JsonValue::String(s)) => s == &audience,
            Some(JsonValue::Array(arr)) => arr.iter().any(|v| match v {
                JsonValue::String(s) => s == &audience,
                _ => false,
            }),
            _ => false,
        };

        if !aud_valid {
            println!("{}: BAD_AUDIENCE", token_idx);
            invalid_count += 1;
            continue;
        }

        let sub = match payload_json.get("sub") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => String::new(),
        };

        let scope = match payload_json.get("scope") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => String::new(),
        };

        let mut scopes_set = BTreeSet::new();
        for part in scope.split_whitespace() {
            scopes_set.insert(part);
        }
        let scopes_joined = scopes_set.into_iter().collect::<Vec<_>>().join(",");

        println!("{}: VALID sub={} scope={}", token_idx, sub, scopes_joined);
        valid_count += 1;
    }

    println!("\nvalid={} invalid={}", valid_count, invalid_count);
}

use std::collections::{BTreeSet, HashMap};
use std::env;
use std::fs;
use std::path::Path;

// Import CommonCrypto's CCHmac from macOS system libraries
extern "C" {
    fn CCHmac(algorithm: u32, key: *const u8, key_len: usize, data: *const u8, data_len: usize, mac_out: *mut u8);
}

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

struct JsonParser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Result<JsonValue, ()> {
        self.skip_whitespace();
        let c = self.peek().ok_or(())?;
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string().map(JsonValue::String),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            '0'..='9' | '-' => self.parse_number().map(JsonValue::Number),
            _ => Err(()),
        }
    }

    fn parse_null(&mut self) -> Result<JsonValue, ()> {
        if self.input[self.pos..].starts_with("null") {
            self.pos += 4;
            Ok(JsonValue::Null)
        } else {
            Err(())
        }
    }

    fn parse_bool(&mut self) -> Result<JsonValue, ()> {
        if self.input[self.pos..].starts_with("true") {
            self.pos += 4;
            Ok(JsonValue::Bool(true))
        } else if self.input[self.pos..].starts_with("false") {
            self.pos += 5;
            Ok(JsonValue::Bool(false))
        } else {
            Err(())
        }
    }

    fn parse_number(&mut self) -> Result<f64, ()> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_digit(10) || c == '-' || c == '.' || c == 'e' || c == 'E' || c == '+' {
                self.next();
            } else {
                break;
            }
        }
        self.input[start..self.pos].parse::<f64>().map_err(|_| ())
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.next(); // skip opening quote
        let mut result = String::new();
        loop {
            let c = self.next().ok_or(())?;
            if c == '"' {
                break;
            } else if c == '\\' {
                match self.next().ok_or(())? {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\x08'),
                    'f' => result.push('\x0c'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'u' => {
                        let mut hex = String::new();
                        for _ in 0..4 {
                            let h = self.next().ok_or(())?;
                            if h.is_ascii_hexdigit() {
                                hex.push(h);
                            } else {
                                return Err(());
                            }
                        }
                        let code = u32::from_str_radix(&hex, 16).map_err(|_| ())?;
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.next().ok_or(())? != '\\' { return Err(()); }
                            if self.next().ok_or(())? != 'u' { return Err(()); }
                            let mut hex_low = String::new();
                            for _ in 0..4 {
                                let h = self.next().ok_or(())?;
                                if h.is_ascii_hexdigit() {
                                    hex_low.push(h);
                                } else {
                                    return Err(());
                                }
                            }
                            let low = u32::from_str_radix(&hex_low, 16).map_err(|_| ())?;
                            if !(0xDC00..=0xDFFF).contains(&low) { return Err(()); }
                            let cp = 0x10000 + (code - 0xD800) * 0x400 + (low - 0xDC00);
                            result.push(std::char::from_u32(cp).ok_or(())?);
                        } else if (0xDC00..=0xDFFF).contains(&code) {
                            return Err(());
                        } else {
                            result.push(std::char::from_u32(code).ok_or(())?);
                        }
                    }
                    _ => return Err(()),
                }
            } else {
                result.push(c);
            }
        }
        Ok(result)
    }

    fn parse_array(&mut self) -> Result<JsonValue, ()> {
        self.next(); // skip [
        let mut array = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Ok(JsonValue::Array(array));
        }
        loop {
            array.push(self.parse_value()?);
            self.skip_whitespace();
            match self.next().ok_or(())? {
                ',' => self.skip_whitespace(),
                ']' => break,
                _ => return Err(()),
            }
        }
        Ok(JsonValue::Array(array))
    }

    fn parse_object(&mut self) -> Result<JsonValue, ()> {
        self.next(); // skip {
        let mut map = HashMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Ok(JsonValue::Object(map));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.skip_whitespace();
            if self.next().ok_or(())? != ':' { return Err(()); }
            let value = self.parse_value()?;
            map.insert(key, value);
            self.skip_whitespace();
            match self.next().ok_or(())? {
                ',' => self.skip_whitespace(),
                '}' => break,
                _ => return Err(()),
            }
        }
        Ok(JsonValue::Object(map))
    }
}

fn decode_base64url(input: &str) -> Option<Vec<u8>> {
    if input.is_empty() { return None; }
    if input.len() % 4 == 1 { return None; }

    let mut bytes = Vec::new();
    let mut buffer = 0u32;
    let mut bits = 0;

    for c in input.chars() {
        let val = match c {
            'A'..='Z' => (c as u8 - b'A') as u32,
            'a'..='z' => (c as u8 - b'a' + 26) as u32,
            '0'..='9' => (c as u8 - b'0' + 52) as u32,
            '-' => 62,
            '_' => 63,
            _ => return None,
        };
        buffer = (buffer << 6) | val;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            bytes.push((buffer >> bits) as u8);
        }
    }
    Some(bytes)
}

fn parse_json_object(input: &str) -> Option<HashMap<String, JsonValue>> {
    let mut parser = JsonParser::new(input);
    match parser.parse_value() {
        Ok(JsonValue::Object(map)) => {
            parser.skip_whitespace();
            if parser.peek().is_none() {
                Some(map)
            } else {
                None
            }
        },
        _ => None,
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = Path::new(&args[1]);

    let config_str = fs::read_to_string(dir.join("config.json")).expect("Unable to read config.json");
    let config_obj = parse_json_object(&config_str).expect("Invalid config.json");

    let now = match config_obj.get("now") {
        Some(JsonValue::Number(n)) => *n,
        _ => 0.0,
    };
    let leeway = match config_obj.get("leeway") {
        Some(JsonValue::Number(n)) => *n,
        _ => 0.0,
    };
    let issuer = match config_obj.get("issuer") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => String::new(),
    };
    let audience = match config_obj.get("audience") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => String::new(),
    };
    let keys = match config_obj.get("keys") {
        Some(JsonValue::Array(arr)) => arr.clone(),
        _ => Vec::new(),
    };

    let tokens_str = fs::read_to_string(dir.join("tokens.txt")).expect("Unable to read tokens.txt");
    let mut valid_count = 0;
    let mut invalid_count = 0;
    let mut token_idx = 0;

    for line in tokens_str.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        token_idx += 1;

        let segments: Vec<&str> = trimmed.split('.').collect();
        if segments.len() != 3 || segments.iter().any(|s| s.is_empty()) {
            println!("{}: MALFORMED", token_idx);
            invalid_count += 1;
            continue;
        }

        let seg0 = segments[0];
        let seg1 = segments[1];
        let seg2 = segments[2];

        let b64_0 = decode_base64url(seg0);
        let b64_1 = decode_base64url(seg1);
        let b64_2 = decode_base64url(seg2);

        if b64_0.is_none() || b64_1.is_none() || b64_2.is_none() {
            println!("{}: MALFORMED", token_idx);
            invalid_count += 1;
            continue;
        }

        let header_utf8 = std::str::from_utf8(b64_0.as_ref().unwrap());
        let payload_utf8 = std::str::from_utf8(b64_1.as_ref().unwrap());

        if header_utf8.is_err() || payload_utf8.is_err() {
            println!("{}: MALFORMED", token_idx);
            invalid_count += 1;
            continue;
        }

        let header_json = match parse_json_object(header_utf8.unwrap()) {
            Some(map) => map,
            None => {
                println!("{}: MALFORMED", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        let payload_json = match parse_json_object(payload_utf8.unwrap()) {
            Some(map) => map,
            None => {
                println!("{}: MALFORMED", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        let alg = match header_json.get("alg") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => {
                println!("{}: UNSUPPORTED_ALG", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        if alg != "HS256" && alg != "HS384" && alg != "HS512" {
            println!("{}: UNSUPPORTED_ALG", token_idx);
            invalid_count += 1;
            continue;
        }

        let kid = match header_json.get("kid") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => {
                println!("{}: UNKNOWN_KEY", token_idx);
                invalid_count += 1;
                continue;
            }
        };

        let key_data = keys.iter().find_map(|v| {
            if let JsonValue::Object(map) = v {
                if let Some(JsonValue::String(k_id)) = map.get("kid") {
                    if k_id == kid { return Some(map); }
                }
            }
            None
        });

        if key_data.is_none() {
            println!("{}: UNKNOWN_KEY", token_idx);
            invalid_count += 1;
            continue;
        }
        let key_data = key_data.unwrap();

        let key_alg = match key_data.get("alg") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => "",
        };

        if key_alg != alg {
            println!("{}: ALG_MISMATCH", token_idx);
            invalid_count += 1;
            continue;
        }

        let secret_b64 = match key_data.get("k") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => "",
        };
        let secret = decode_base64url(secret_b64).expect("Key secret is invalid base64url");

        let signing_input = format!("{}.{}", seg0, seg1);
        let signing_input_bytes = signing_input.as_bytes();
        let out_len = match alg {
            "HS256" => 32,
            "HS384" => 48,
            "HS512" => 64,
            _ => 0,
        };
        let mut hmac_out = vec![0u8; 64];
        let alg_val = match alg {
            "HS256" => 2,
            "HS384" => 3,
            "HS512" => 4,
            _ => 0,
        };

        unsafe {
            CCHmac(alg_val, secret.as_ptr(), secret.len(), signing_input_bytes.as_ptr(), signing_input_bytes.len(), hmac_out.as_mut_ptr());
        }

        if b64_2.as_ref().unwrap() != &hmac_out[..out_len] {
            println!("{}: BAD_SIGNATURE", token_idx);
            invalid_count += 1;
            continue;
        }

        if let Some(JsonValue::Number(exp)) = payload_json.get("exp") {
            if now >= *exp + leeway {
                println!("{}: EXPIRED", token_idx);
                invalid_count += 1;
                continue;
            }
        }

        if let Some(JsonValue::Number(nbf)) = payload_json.get("nbf") {
            if now + leeway < *nbf {
                println!("{}: NOT_YET_VALID", token_idx);
                invalid_count += 1;
                continue;
            }
        }

        let iss = match payload_json.get("iss") {
            Some(JsonValue::String(s)) => s.as_str(),
            _ => "",
        };
        if iss != issuer {
            println!("{}: BAD_ISSUER", token_idx);
            invalid_count += 1;
            continue;
        }

        let aud_valid = match payload_json.get("aud") {
            Some(JsonValue::String(s)) => s == &audience,
            Some(JsonValue::Array(arr)) => arr.iter().any(|v| match v {
                JsonValue::String(s) => s == &audience,
                _ => false,
            }),
            _ => false,
        };

        if !aud_valid {
            println!("{}: BAD_AUDIENCE", token_idx);
            invalid_count += 1;
            continue;
        }

        let sub = match payload_json.get("sub") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => String::new(),
        };

        let scope_str = match payload_json.get("scope") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => String::new(),
        };

        let mut scopes_set = BTreeSet::new();
        for part in scope_str.split(' ') {
            if !part.is_empty() {
                scopes_set.insert(part);
            }
        }
        let scopes_joined = scopes_set.into_iter().collect::<Vec<_>>().join(",");

        println!("{}: VALID sub={} scope={}", token_idx, sub, scopes_joined);
        valid_count += 1;
    }

    println!("\nvalid={} invalid={}", valid_count, invalid_count);
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Collectors;

public class Main {
    private static boolean initialized = false;
    private static final Map<String, String> kvStore = new HashMap<>();

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                processLine(line);
            }
        } catch (IOException e) {
            // Ignore
        }
    }

    private static void processLine(String line) {
        JsonValue json;
        try {
            json = JsonParser.parse(line);
        } catch (Exception e) {
            sendResponse(null, null, -32700, "Parse error");
            return;
        }

        if (!(json instanceof JsonObject)) {
            sendResponse(null, null, -32600, "Invalid Request");
            return;
        }

        JsonObject obj = (JsonObject) json;
        if (!obj.containsKey("method") && (obj.containsKey("result") || obj.containsKey("error"))) {
            return; // Client response, ignore
        }

        // Validate Request
        JsonValue jsonrpc = obj.get("jsonrpc");
        JsonValue method = obj.get("method");
        JsonValue id = obj.get("id");

        boolean validId = false;
        if (id != null) {
            if (id instanceof JsonString || (id instanceof JsonNumber && ((JsonNumber) id).isInteger)) {
                validId = true;
            }
        }

        if (!(jsonrpc instanceof JsonString && ((JsonString) jsonrpc).value.equals("2.0")) ||
            !(method instanceof JsonString)) {
            sendResponse(validId ? id : null, null, -32600, "Invalid Request");
            return;
        }
        if (obj.containsKey("id") && !validId) {
            sendResponse(null, null, -32600, "Invalid Request");
            return;
        }

        if (!obj.containsKey("id")) {
            return; // Notification
        }

        // Request
        String methodName = ((JsonString) method).value;
        JsonValue params = obj.get("params");

        if (!List.of("initialize", "ping", "tools/list", "tools/call").contains(methodName)) {
            sendResponse(id, null, -32601, "Method not found");
            return;
        }

        if (params != null && !(params instanceof JsonObject)) {
            sendResponse(id, null, -32602, "Invalid params");
            return;
        }

        if (!initialized && !methodName.equals("initialize") && !methodName.equals("ping")) {
            sendResponse(id, null, -32002, "Server not initialized");
            return;
        }

        // Dispatch
        if (methodName.equals("initialize")) {
            if (initialized) {
                sendResponse(id, null, -32600, "Already initialized");
            } else {
                if (params == null || !(params instanceof JsonObject)) {
                    sendResponse(id, null, -32602, "Invalid params");
                } else {
                    JsonObject pObj = (JsonObject) params;
                    JsonValue pv = pObj.get("protocolVersion");
                    if (!(pv instanceof JsonString)) {
                        sendResponse(id, null, -32602, "Invalid params");
                    } else {
                        String clientVer = ((JsonString) pv).value;
                        String serverVer = List.of("2025-06-18", "2025-03-26", "2024-11-05").contains(clientVer) ? clientVer : "2025-06-18";
                        initialized = true;
                        Map<String, Object> result = new LinkedHashMap<>();
                        result.put("protocolVersion", serverVer);
                        result.put("capabilities", Map.of("tools", Map.of("listChanged", false)));
                        result.put("serverInfo", Map.of("name", "cb2-kv", "title", "CB2 key-value server", "version", "1.4.2"));
                        sendResult(id, result);
                    }
                }
            }
        } else if (methodName.equals("ping")) {
            sendResult(id, Map.of());
        } else if (methodName.equals("tools/list")) {
            sendResult(id, Map.of("tools", getToolDefinitions()));
        } else if (methodName.equals("tools/call")) {
            handleToolCall(id, params);
        }
    }

    private static void handleToolCall(JsonValue id, JsonValue params) {
        if (!(params instanceof JsonObject)) {
            sendResponse(id, null, -32602, "Invalid params");
            return;
        }
        JsonObject pObj = (JsonObject) params;
        JsonValue nameVal = pObj.get("name");
        if (!(nameVal instanceof JsonString)) {
            sendResponse(id, null, -32602, "Invalid params");
            return;
        }
        String toolName = ((JsonString) nameVal).value;
        ToolDef def = getToolDef(toolName);
        if (def == null) {
            sendResponse(id, null, -32602, "Unknown tool: " + toolName);
            return;
        }

        JsonValue argsVal = pObj.get("arguments");
        if (argsVal == null) argsVal = new JsonObject(new HashMap<>());
        if (!(argsVal instanceof JsonObject)) {
            sendToolFailure(id, "arguments must be an object");
            return;
        }
        JsonObject args = (JsonObject) argsVal;

        // Unknown arguments
        List<String> unknown = new ArrayList<>();
        for (String key : args.keySet()) {
            if (!def.properties.containsKey(key)) unknown.add(key);
        }
        if (!unknown.isEmpty()) {
            Collections.sort(unknown);
            sendToolFailure(id, "unknown argument: " + unknown.get(0));
            return;
        }

        // Required and Type checks
        for (String propName : def.propertyOrder) {
            JsonValue val = args.get(propName);
            if (val == null) {
                if (def.required.contains(propName)) {
                    sendToolFailure(id, "missing required argument: " + propName);
                    return;
                }
                continue;
            }

            String type = def.properties.get(propName);
            if (type.equals("string")) {
                if (!(val instanceof JsonString)) {
                    sendToolFailure(id, "argument " + propName + " must be a string");
                    return;
                }
                if (def.minLength > 0 && ((JsonString) val).value.length() < def.minLength) {
                    sendToolFailure(id, "argument " + propName + " must not be empty");
                    return;
                }
            } else if (type.equals("array of integers")) {
                if (!(val instanceof JsonArray)) {
                    sendToolFailure(id, "argument " + propName + " must be an array of integers");
                    return;
                }
                JsonArray arr = (JsonArray) val;
                for (JsonValue item : arr.values) {
                    if (!(item instanceof JsonNumber && ((JsonNumber) item).isInteger)) {
                        sendToolFailure(id, "argument " + propName + " must be an array of integers");
                        return;
                    }
                }
                if (def.minItems > 0 && arr.values.size() < def.minItems) {
                    sendToolFailure(id, "argument " + propName + " must not be empty");
                    return;
                }
            }
        }

        // Execution
        switch (toolName) {
            case "kv_set": {
                String key = ((JsonString) args.get("key")).value;
                String value = ((JsonString) args.get("value")).value;
                boolean exists = kvStore.containsKey(key);
                kvStore.put(key, value);
                sendToolSuccess(id, (exists ? "updated " : "created ") + key, null);
                break;
            }
            case "kv_get": {
                String key = ((JsonString) args.get("key")).value;
                String value = kvStore.get(key);
                if (value == null) {
                    sendToolFailure(id, "key not found: " + key);
                } else {
                    sendToolSuccess(id, value, null);
                }
                break;
            }
            case "kv_list": {
                String prefix = "";
                JsonValue pVal = args.get("prefix");
                if (pVal instanceof JsonString) prefix = ((JsonString) pVal).value;
                List<String> keys = kvStore.keySet().stream()
                        .filter(k -> k.startsWith(prefix))
                        .sorted()
                        .collect(Collectors.toList());
                Map<String, Object> s = new LinkedHashMap<>();
                s.put("keys", keys);
                s.put("count", keys.size());
                sendToolSuccess(id, null, s);
                break;
            }
            case "sum": {
                JsonArray nums = (JsonArray) args.get("numbers");
                long total = 0;
                for (JsonValue n : nums.values) total += ((JsonNumber) n).longValue;
                Map<String, Object> s = new LinkedHashMap<>();
                s.put("sum", total);
                s.put("count", nums.values.size());
                sendToolSuccess(id, null, s);
                break;
            }
            case "text_stats": {
                String text = ((JsonString) args.get("text")).value;
                int words = 0;
                boolean inWord = false;
                for (int i = 0; i < text.length(); i++) {
                    char c = text.charAt(i);
                    if (c == ' ' || c == '\t' || c == '\n' || c == '\r') inWord = false;
                    else {
                        if (!inWord) { words++; inWord = true; }
                    }
                }
                Map<String, Object> s = new LinkedHashMap<>();
                s.put("words", words);
                s.put("codepoints", text.codePointCount(0, text.length()));
                s.put("utf8_bytes", text.getBytes(StandardCharsets.UTF_8).length);
                sendToolSuccess(id, null, s);
                break;
            }
        }
    }

    private static void sendToolSuccess(JsonValue id, String text, Object structured) {
        Map<String, Object> res = new LinkedHashMap<>();
        List<Map<String, Object>> content = new ArrayList<>();
        if (structured != null) {
            String sJson = toJson(structured);
            content.add(Map.of("type", "text", "text", sJson));
            res.put("content", content);
            res.put("structuredContent", structured);
        } else {
            content.add(Map.of("type", "text", "text", text));
            res.put("content", content);
        }
        res.put("isError", false);
        sendResult(id, res);
    }

    private static void sendToolFailure(JsonValue id, String message) {
        Map<String, Object> res = new LinkedHashMap<>();
        res.put("content", List.of(Map.of("type", "text", "text", message)));
        res.put("isError", true);
        sendResult(id, res);
    }

    private static void sendResult(JsonValue id, Object result) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\"jsonrpc\":\"2.0\",");
        if (id != null) sb.append("\"id\":").append(toJson(id)).append(",");
        sb.append("\"result\":").append(toJson(result));
        sb.append("}");
        System.out.println(sb.toString());
    }

    private static void sendResponse(JsonValue id, Object result, int code, String message) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\"jsonrpc\":\"2.0\",");
        sb.append("\"id\":").append(toJson(id)).append(",");
        if (result != null) {
            sb.append("\"result\":").append(toJson(result));
        } else {
            sb.append("\"error\":{\"code\":").append(code).append(",\"message\":\"").append(message).append("\"}");
        }
        sb.append("}");
        System.out.println(sb.toString());
    }

    private static String toJson(Object o) {
        if (o == null) return "null";
        if (o instanceof String) return "\"" + escapeJson((String) o) + "\"";
        if (o instanceof Number) return o.toString();
        if (o instanceof Boolean) return o.toString();
        if (o instanceof Map) {
            Map<?, ?> m = (Map<?, ?>) o;
            return "{" + m.entrySet().stream()
                .map(e -> "\"" + escapeJson(e.getKey().toString()) + "\":" + toJson(e.getValue()))
                .collect(Collectors.joining(",")) + "}";
        }
        if (o instanceof List) {
            List<?> l = (List<?>) o;
            return "[" + l.stream().map(Main::toJson).collect(Collectors.joining(",")) + "]";
        }
        if (o instanceof JsonValue) {
            if (o instanceof JsonString) return "\"" + escapeJson(((JsonString) o).value) + "\"";
            if (o instanceof JsonNumber) return ((JsonNumber) o).raw;
            if (o instanceof JsonBoolean) return ((JsonBoolean) o).value ? "true" : "false";
            if (o instanceof JsonObject) return toJson(((JsonObject) o).map);
            if (o instanceof JsonArray) return toJson(((JsonArray) o).values);
            return "null";
        }
        return "null";
    }

    private static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 32) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        return sb.toString();
    }

    private static List<Map<String, Object>> getToolDefinitions() {
        List<Map<String, Object>> tools = new ArrayList<>();
        tools.add(createTool("kv_set", "Set a value", "Store a string value under a key, replacing any previous value.", 
            Map.of("key", "string", "value", "string"), List.of("key", "value"), 1, 0));
        tools.add(createTool("kv_get", "Get a value", "Return the value stored under a key.", 
            Map.of("key", "string"), List.of("key"), 1, 0));
        tools.add(createTool("kv_list", "List keys", "List the stored keys that start with a prefix, sorted by Unicode code point.", 
            Map.of("prefix", "string"), List.of(), 0, 0));
        tools.add(createTool("sum", "Sum integers", "Add up a non-empty list of integers.", 
            Map.of("numbers", "array of integers"), List.of("numbers"), 0, 1));
        tools.add(createTool("text_stats", "Text statistics", "Count the words, Unicode code points and UTF-8 bytes of a text.", 
            Map.of("text", "string"), List.of("text"), 0, 0));
        return tools;
    }

    private static Map<String, Object> createTool(String name, String title, String desc, Map<String, String> props, List<String> req, int minLen, int minItems) {
        Map<String, Object> tool = new LinkedHashMap<>();
        tool.put("name", name);
        tool.put("title", title);
        tool.put("description", desc);
        Map<String, Object> schema = new LinkedHashMap<>();
        schema.put("type", "object");
        Map<String, Object> propSchemas = new LinkedHashMap<>();
        for (String p : props.keySet()) {
            Map<String, Object> ps = new LinkedHashMap<>();
            ps.put("type", props.get(p).equals("string") ? "string" : "integer");
            if (props.get(p).equals("array of integers")) {
                ps.put("type", "array");
                ps.put("items", Map.of("type", "integer"));
            }
            if (minLen > 0 && props.get(p).equals("string")) ps.put("minLength", minLen);
            if (minItems > 0 && props.get(p).equals("array of integers")) ps.put("minItems", minItems);
            propSchemas.put(p, ps);
        }
        schema.put("properties", propSchemas);
        schema.put("required", req);
        schema.put("additionalProperties", false);
        tool.put("inputSchema", schema);
        return tool;
    }

    private static ToolDef getToolDef(String name) {
        if (name.equals("kv_set")) return new ToolDef(Map.of("key", "string", "value", "string"), List.of("key", "value"), List.of("key", "value"), 1, 0);
        if (name.equals("kv_get")) return new ToolDef(Map.of("key", "string"), List.of("key"), List.of("key"), 1, 0);
        if (name.equals("kv_list")) return new ToolDef(Map.of("prefix", "string"), List.of(), List.of("prefix"), 0, 0);
        if (name.equals("sum")) return new ToolDef(Map.of("numbers", "array of integers"), List.of("numbers"), List.of("numbers"), 0, 1);
        if (name.equals("text_stats")) return new ToolDef(Map.of("text", "string"), List.of("text"), List.of("text"), 0, 0);
        return null;
    }

    private static class ToolDef {
        Map<String, String> properties;
        Set<String> required;
        List<String> propertyOrder;
        int minLength, minItems;
        ToolDef(Map<String, String> p, List<String> r, List<String> o, int ml, int mi) {
            properties = p; required = new HashSet<>(r); propertyOrder = o; minLength = ml; minItems = mi;
        }
    }

    // Simple JSON Parser
    static class JsonValue {}
    static class JsonObject extends JsonValue {
        Map<String, JsonValue> map;
        JsonObject(Map<String, JsonValue> m) { map = m; }
        boolean containsKey(String k) { return map.containsKey(k); }
        JsonValue get(String k) { return map.get(k); }
        Set<String> keySet() { return map.keySet(); }
    }
    static class JsonArray extends JsonValue {
        List<JsonValue> values;
        JsonArray(List<JsonValue> v) { values = v; }
    }
    static class JsonString extends JsonValue {
        String value;
        JsonString(String v) { value = v; }
    }
    static class JsonNumber extends JsonValue {
        String raw;
        long longValue;
        boolean isInteger;
        JsonNumber(String r) {
            raw = r;
            isInteger = !r.contains(".") && !r.toLowerCase().contains("e");
            longValue = Long.parseLong(r);
        }
    }
    static class JsonBoolean extends JsonValue {
        boolean value;
        JsonBoolean(boolean v) { value = v; }
    }
    static class JsonNull extends JsonValue {}

    static class JsonParser {
        static JsonValue parse(String s) {
            return new Parser(s).parseValue();
        }
        static class Parser {
            String s; int pos = 0;
            Parser(String s) { this.s = s; }
            JsonValue parseValue() {
                skipWhitespace();
                if (pos >= s.length()) throw new RuntimeException("EOF");
                char c = s.charAt(pos);
                if (c == '{') return parseObject();
                if (c == '[') return parseArray();
                if (c == '"') return parseString();
                if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
                if (s.startsWith("true", pos)) { pos += 4; return new JsonBoolean(true); }
                if (s.startsWith("false", pos)) { pos += 5; return new JsonBoolean(false); }
                if (s.startsWith("null", pos)) { pos += 4; return new JsonNull(); }
                throw new RuntimeException("Invalid JSON");
            }
            JsonObject parseObject() {
                pos++; // {
                Map<String, JsonValue> map = new LinkedHashMap<>();
                skipWhitespace();
                while (pos < s.length() && s.charAt(pos) != '}') {
                    JsonString key = parseString();
                    skipWhitespace();
                    if (pos >= s.length() || s.charAt(pos) != ':') throw new RuntimeException("Expected :");
                    pos++;
                    map.put(key.value, parseValue());
                    skipWhitespace();
                    if (pos < s.length() && s.charAt(pos) == ',') { pos++; skipWhitespace(); }
                }
                if (pos >= s.length()) throw new RuntimeException("Expected }");
                pos++;
                return new JsonObject(map);
            }
            JsonArray parseArray() {
                pos++; // [
                List<JsonValue> values = new ArrayList<>();
                skipWhitespace();
                while (pos < s.length() && s.charAt(pos) != ']') {
                    values.add(parseValue());
                    skipWhitespace();
                    if (pos < s.length() && s.charAt(pos) == ',') { pos++; skipWhitespace(); }
                }
                if (pos >= s.length()) throw new RuntimeException("Expected ]");
                pos++;
                return new JsonArray(values);
            }
            JsonString parseString() {
                pos++; // "
                StringBuilder sb = new StringBuilder();
                while (pos < s.length() && s.charAt(pos) != '"') {
                    char c = s.charAt(pos++);
                    if (c == '\\') {
                        char esc = s.charAt(pos++);
                        switch (esc) {
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                            case '/': sb.append('/'); break;
                            case 'b': sb.append('\b'); break;
                            case 'f': sb.append('\f'); break;
                            case 'n': sb.append('\n'); break;
                            case 'r': sb.append('\r'); break;
                            case 't': sb.append('\t'); break;
                            case 'u':
                                String hex = s.substring(pos, pos + 4);
                                sb.append((char) Integer.parseInt(hex, 16));
                                pos += 4;
                                break;
                        }
                    } else sb.append(c);
                }
                pos++; // "
                return new JsonString(sb.toString());
            }
            JsonNumber parseNumber() {
                int start = pos;
                while (pos < s.length() && "-0123456789.eE+".indexOf(s.charAt(pos)) != -1) pos++;
                return new JsonNumber(s.substring(start, pos));
            }
            void skipWhitespace() {
                while (pos < s.length() && " \t\n\r".indexOf(s.charAt(pos)) != -1) pos++;
            }
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Collectors;

public class Main {
    private static boolean initialized = false;
    private static final Map<String, String> kvStore = new HashMap<>();

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                processLine(line);
            }
        } catch (IOException e) {
            // Ignore
        }
    }

    private static void processLine(String line) {
        JsonValue json;
        try {
            json = JsonParser.parse(line);
        } catch (Exception e) {
            sendResponse(null, null, -32700, "Parse error");
            return;
        }

        if (!(json instanceof JsonObject)) {
            sendResponse(null, null, -32600, "Invalid Request");
            return;
        }

        JsonObject obj = (JsonObject) json;
        if (!obj.containsKey("method") && (obj.containsKey("result") || obj.containsKey("error"))) {
            return; // Client response, ignore
        }

        // Validate Request
        JsonValue jsonrpc = obj.get("jsonrpc");
        JsonValue method = obj.get("method");
        JsonValue id = obj.get("id");

        boolean validId = false;
        if (id != null) {
            if (id instanceof JsonString || (id instanceof JsonNumber && ((JsonNumber) id).isInteger)) {
                validId = true;
            }
        }

        if (!(jsonrpc instanceof JsonString && ((JsonString) jsonrpc).value.equals("2.0")) ||
            !(method instanceof JsonString)) {
            sendResponse(validId ? id : null, null, -32600, "Invalid Request");
            return;
        }
        if (obj.containsKey("id") && !validId) {
            sendResponse(null, null, -32600, "Invalid Request");
            return;
        }

        if (!obj.containsKey("id")) {
            return; // Notification
        }

        // Request
        String methodName = ((JsonString) method).value;
        JsonValue params = obj.get("params");

        if (!List.of("initialize", "ping", "tools/list", "tools/call").contains(methodName)) {
            sendResponse(id, null, -32601, "Method not found");
            return;
        }

        if (params != null && !(params instanceof JsonObject)) {
            sendResponse(id, null, -32602, "Invalid params");
            return;
        }

        if (!initialized && !methodName.equals("initialize") && !methodName.equals("ping")) {
            sendResponse(id, null, -32002, "Server not initialized");
            return;
        }

        // Dispatch
        if (methodName.equals("initialize")) {
            if (initialized) {
                sendResponse(id, null, -32600, "Already initialized");
            } else {
                if (params == null || !(params instanceof JsonObject)) {
                    sendResponse(id, null, -32602, "Invalid params");
                } else {
                    JsonObject pObj = (JsonObject) params;
                    JsonValue pv = pObj.get("protocolVersion");
                    if (!(pv instanceof JsonString)) {
                        sendResponse(id, null, -32602, "Invalid params");
                    } else {
                        String clientVer = ((JsonString) pv).value;
                        String serverVer = List.of("2025-06-18", "2025-03-26", "2024-11-05").contains(clientVer) ? clientVer : "2025-06-18";
                        initialized = true;
                        Map<String, Object> result = new LinkedHashMap<>();
                        result.put("protocolVersion", serverVer);
                        result.put("capabilities", Map.of("tools", Map.of("listChanged", false)));
                        result.put("serverInfo", Map.of("name", "cb2-kv", "title", "CB2 key-value server", "version", "1.4.2"));
                        sendResult(id, result);
                    }
                }
            }
        } else if (methodName.equals("ping")) {
            sendResult(id, Map.of());
        } else if (methodName.equals("tools/list")) {
            sendResult(id, Map.of("tools", getToolDefinitions()));
        } else if (methodName.equals("tools/call")) {
            handleToolCall(id, params);
        }
    }

    private static void handleToolCall(JsonValue id, JsonValue params) {
        if (!(params instanceof JsonObject)) {
            sendResponse(id, null, -32602, "Invalid params");
            return;
        }
        JsonObject pObj = (JsonObject) params;
        JsonValue nameVal = pObj.get("name");
        if (!(nameVal instanceof JsonString)) {
            sendResponse(id, null, -32602, "Invalid params");
            return;
        }
        String toolName = ((JsonString) nameVal).value;
        ToolDef def = getToolDef(toolName);
        if (def == null) {
            sendResponse(id, null, -32602, "Unknown tool: " + toolName);
            return;
        }

        JsonValue argsVal = pObj.get("arguments");
        if (argsVal == null) argsVal = new JsonObject(new HashMap<>());
        if (!(argsVal instanceof JsonObject)) {
            sendToolFailure(id, "arguments must be an object");
            return;
        }
        JsonObject args = (JsonObject) argsVal;

        // Unknown arguments
        List<String> unknown = new ArrayList<>();
        for (String key : args.keySet()) {
            if (!def.properties.containsKey(key)) unknown.add(key);
        }
        if (!unknown.isEmpty()) {
            Collections.sort(unknown);
            sendToolFailure(id, "unknown argument: " + unknown.get(0));
            return;
        }

        // Required and Type checks
        for (String propName : def.propertyOrder) {
            JsonValue val = args.get(propName);
            if (val == null) {
                if (def.required.contains(propName)) {
                    sendToolFailure(id, "missing required argument: " + propName);
                    return;
                }
                continue;
            }

            String type = def.properties.get(propName);
            if (type.equals("string")) {
                if (!(val instanceof JsonString)) {
                    sendToolFailure(id, "argument " + propName + " must be a string");
                    return;
                }
                if (def.minLength > 0 && ((JsonString) val).value.length() < def.minLength) {
                    sendToolFailure(id, "argument " + propName + " must not be empty");
                    return;
                }
            } else if (type.equals("array of integers")) {
                if (!(val instanceof JsonArray)) {
                    sendToolFailure(id, "argument " + propName + " must be an array of integers");
                    return;
                }
                JsonArray arr = (JsonArray) val;
                for (JsonValue item : arr.values) {
                    if (!(item instanceof JsonNumber && ((JsonNumber) item).isInteger)) {
                        sendToolFailure(id, "argument " + propName + " must be an array of integers");
                        return;
                    }
                }
                if (def.minItems > 0 && arr.values.size() < def.minItems) {
                    sendToolFailure(id, "argument " + propName + " must not be empty");
                    return;
                }
            }
        }

        // Execution
        switch (toolName) {
            case "kv_set": {
                String key = ((JsonString) args.get("key")).value;
                String value = ((JsonString) args.get("value")).value;
                boolean exists = kvStore.containsKey(key);
                kvStore.put(key, value);
                sendToolSuccess(id, (exists ? "updated " : "created ") + key, null);
                break;
            }
            case "kv_get": {
                String key = ((JsonString) args.get("key")).value;
                String value = kvStore.get(key);
                if (value == null) {
                    sendToolFailure(id, "key not found: " + key);
                } else {
                    sendToolSuccess(id, value, null);
                }
                break;
            }
            case "kv_list": {
                JsonValue pVal = args.get("prefix");
                final String finalPrefix = (pVal instanceof JsonString) ? ((JsonString) pVal).value : "";
                List<String> keys = kvStore.keySet().stream()
                        .filter(k -> k.startsWith(finalPrefix))
                        .sorted()
                        .collect(Collectors.toList());
                Map<String, Object> s = new LinkedHashMap<>();
                s.put("keys", keys);
                s.put("count", keys.size());
                sendToolSuccess(id, null, s);
                break;
            }
            case "sum": {
                JsonArray nums = (JsonArray) args.get("numbers");
                long total = 0;
                for (JsonValue n : nums.values) total += ((JsonNumber) n).longValue;
                Map<String, Object> s = new LinkedHashMap<>();
                s.put("sum", total);
                s.put("count", nums.values.size());
                sendToolSuccess(id, null, s);
                break;
            }
            case "text_stats": {
                String text = ((JsonString) args.get("text")).value;
                int words = 0;
                boolean inWord = false;
                for (int i = 0; i < text.length(); i++) {
                    char c = text.charAt(i);
                    if (c == ' ' || c == '\t' || c == '\n' || c == '\r') inWord = false;
                    else {
                        if (!inWord) { words++; inWord = true; }
                    }
                }
                Map<String, Object> s = new LinkedHashMap<>();
                s.put("words", words);
                s.put("codepoints", text.codePointCount(0, text.length()));
                s.put("utf8_bytes", text.getBytes(StandardCharsets.UTF_8).length);
                sendToolSuccess(id, null, s);
                break;
            }
        }
    }

    private static void sendToolSuccess(JsonValue id, String text, Object structured) {
        Map<String, Object> res = new LinkedHashMap<>();
        List<Map<String, Object>> content = new ArrayList<>();
        if (structured != null) {
            String sJson = toJson(structured);
            content.add(Map.of("type", "text", "text", sJson));
            res.put("content", content);
            res.put("structuredContent", structured);
        } else {
            content.add(Map.of("type", "text", "text", text));
            res.put("content", content);
        }
        res.put("isError", false);
        sendResult(id, res);
    }

    private static void sendToolFailure(JsonValue id, String message) {
        Map<String, Object> res = new LinkedHashMap<>();
        res.put("content", List.of(Map.of("type", "text", "text", message)));
        res.put("isError", true);
        sendResult(id, res);
    }

    private static void sendResult(JsonValue id, Object result) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\"jsonrpc\":\"2.0\",");
        if (id != null) sb.append("\"id\":").append(toJson(id)).append(",");
        sb.append("\"result\":").append(toJson(result));
        sb.append("}");
        System.out.println(sb.toString());
    }

    private static void sendResponse(JsonValue id, Object result, int code, String message) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\"jsonrpc\":\"2.0\",");
        sb.append("\"id\":").append(toJson(id)).append(",");
        if (result != null) {
            sb.append("\"result\":").append(toJson(result));
        } else {
            sb.append("\"error\":{\"code\":").append(code).append(",\"message\":\"").append(escapeJson(message)).append("\"}");
        }
        sb.append("}");
        System.out.println(sb.toString());
    }

    private static String toJson(Object o) {
        if (o == null) return "null";
        if (o instanceof String) return "\"" + escapeJson((String) o) + "\"";
        if (o instanceof Number) return o.toString();
        if (o instanceof Boolean) return o.toString();
        if (o instanceof Map) {
            Map<?, ?> m = (Map<?, ?>) o;
            return "{" + m.entrySet().stream()
                .map(e -> "\"" + escapeJson(e.getKey().toString()) + "\":" + toJson(e.getValue()))
                .collect(Collectors.joining(",")) + "}";
        }
        if (o instanceof List) {
            List<?> l = (List<?>) o;
            return "[" + l.stream().map(Main::toJson).collect(Collectors.joining(",")) + "]";
        }
        if (o instanceof JsonValue) {
            if (o instanceof JsonString) return "\"" + escapeJson(((JsonString) o).value) + "\"";
            if (o instanceof JsonNumber) return ((JsonNumber) o).raw;
            if (o instanceof JsonBoolean) return ((JsonBoolean) o).value ? "true" : "false";
            if (o instanceof JsonObject) return toJson(((JsonObject) o).map);
            if (o instanceof JsonArray) return toJson(((JsonArray) o).values);
            return "null";
        }
        return "null";
    }

    private static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 32) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        return sb.toString();
    }

    private static List<Map<String, Object>> getToolDefinitions() {
        List<Map<String, Object>> tools = new ArrayList<>();
        tools.add(createTool("kv_set", "Set a value", "Store a string value under a key, replacing any previous value.", 
            Map.of("key", "string", "value", "string"), List.of("key", "value"), 1, 0));
        tools.add(createTool("kv_get", "Get a value", "Return the value stored under a key.", 
            Map.of("key", "string"), List.of("key"), 1, 0));
        tools.add(createTool("kv_list", "List keys", "List the stored keys that start with a prefix, sorted by Unicode code point.", 
            Map.of("prefix", "string"), List.of(), 0, 0));
        tools.add(createTool("sum", "Sum integers", "Add up a non-empty list of integers.", 
            Map.of("numbers", "array of integers"), List.of("numbers"), 0, 1));
        tools.add(createTool("text_stats", "Text statistics", "Count the words, Unicode code points and UTF-8 bytes of a text.", 
            Map.of("text", "string"), List.of("text"), 0, 0));
        return tools;
    }

    private static Map<String, Object> createTool(String name, String title, String desc, Map<String, String> props, List<String> req, int minLen, int minItems) {
        Map<String, Object> tool = new LinkedHashMap<>();
        tool.put("name", name);
        tool.put("title", title);
        tool.put("description", desc);
        Map<String, Object> schema = new LinkedHashMap<>();
        schema.put("type", "object");
        Map<String, Object> propSchemas = new LinkedHashMap<>();
        for (String p : props.keySet()) {
            Map<String, Object> ps = new LinkedHashMap<>();
            ps.put("type", props.get(p).equals("string") ? "string" : "integer");
            if (props.get(p).equals("array of integers")) {
                ps.put("type", "array");
                ps.put("items", Map.of("type", "integer"));
            }
            if (minLen > 0 && props.get(p).equals("string")) ps.put("minLength", minLen);
            if (minItems > 0 && props.get(p).equals("array of integers")) ps.put("minItems", minItems);
            propSchemas.put(p, ps);
        }
        schema.put("properties", propSchemas);
        schema.put("required", req);
        schema.put("additionalProperties", false);
        tool.put("inputSchema", schema);
        return tool;
    }

    private static ToolDef getToolDef(String name) {
        if (name.equals("kv_set")) return new ToolDef(Map.of("key", "string", "value", "string"), List.of("key", "value"), List.of("key", "value"), 1, 0);
        if (name.equals("kv_get")) return new ToolDef(Map.of("key", "string"), List.of("key"), List.of("key"), 1, 0);
        if (name.equals("kv_list")) return new ToolDef(Map.of("prefix", "string"), List.of(), List.of("prefix"), 0, 0);
        if (name.equals("sum")) return new ToolDef(Map.of("numbers", "array of integers"), List.of("numbers"), List.of("numbers"), 0, 1);
        if (name.equals("text_stats")) return new ToolDef(Map.of("text", "string"), List.of("text"), List.of("text"), 0, 0);
        return null;
    }

    private static class ToolDef {
        Map<String, String> properties;
        Set<String> required;
        List<String> propertyOrder;
        int minLength, minItems;
        ToolDef(Map<String, String> p, List<String> r, List<String> o, int ml, int mi) {
            properties = p; required = new HashSet<>(r); propertyOrder = o; minLength = ml; minItems = mi;
        }
    }

    // Simple JSON Parser
    static class JsonValue {}
    static class JsonObject extends JsonValue {
        Map<String, JsonValue> map;
        JsonObject(Map<String, JsonValue> m) { map = m; }
        boolean containsKey(String k) { return map.containsKey(k); }
        JsonValue get(String k) { return map.get(k); }
        Set<String> keySet() { return map.keySet(); }
    }
    static class JsonArray extends JsonValue {
        List<JsonValue> values;
        JsonArray(List<JsonValue> v) { values = v; }
    }
    static class JsonString extends JsonValue {
        String value;
        JsonString(String v) { value = v; }
    }
    static class JsonNumber extends JsonValue {
        String raw;
        long longValue;
        boolean isInteger;
        JsonNumber(String r) {
            raw = r;
            isInteger = !r.contains(".") && !r.toLowerCase().contains("e");
            if (isInteger) {
                try {
                    longValue = Long.parseLong(r);
                } catch (NumberFormatException e) {
                    // Value exceeds long, but is still an integer
                }
            }
        }
    }
    static class JsonBoolean extends JsonValue {
        boolean value;
        JsonBoolean(boolean v) { value = v; }
    }
    static class JsonNull extends JsonValue {}

    static class JsonParser {
        static JsonValue parse(String s) {
            return new Parser(s).parseValue();
        }
        static class Parser {
            String s; int pos = 0;
            Parser(String s) { this.s = s; }
            JsonValue parseValue() {
                skipWhitespace();
                if (pos >= s.length()) throw new RuntimeException("EOF");
                char c = s.charAt(pos);
                if (c == '{') return parseObject();
                if (c == '[') return parseArray();
                if (c == '"') return parseString();
                if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
                if (s.startsWith("true", pos)) { pos += 4; return new JsonBoolean(true); }
                if (s.startsWith("false", pos)) { pos += 5; return new JsonBoolean(false); }
                if (s.startsWith("null", pos)) { pos += 4; return new JsonNull(); }
                throw new RuntimeException("Invalid JSON");
            }
            JsonObject parseObject() {
                pos++; // {
                Map<String, JsonValue> map = new LinkedHashMap<>();
                skipWhitespace();
                while (pos < s.length() && s.charAt(pos) != '}') {
                    JsonString key = parseString();
                    skipWhitespace();
                    if (pos >= s.length() || s.charAt(pos) != ':') throw new RuntimeException("Expected :");
                    pos++;
                    map.put(key.value, parseValue());
                    skipWhitespace();
                    if (pos < s.length() && s.charAt(pos) == ',') { pos++; skipWhitespace(); }
                }
                if (pos >= s.length()) throw new RuntimeException("Expected }");
                pos++;
                return new JsonObject(map);
            }
            JsonArray parseArray() {
                pos++; // [
                List<JsonValue> values = new ArrayList<>();
                skipWhitespace();
                while (pos < s.length() && s.charAt(pos) != ']') {
                    values.add(parseValue());
                    skipWhitespace();
                    if (pos < s.length() && s.charAt(pos) == ',') { pos++; skipWhitespace(); }
                }
                if (pos >= s.length()) throw new RuntimeException("Expected ]");
                pos++;
                return new JsonArray(values);
            }
            JsonString parseString() {
                pos++; // "
                StringBuilder sb = new StringBuilder();
                while (pos < s.length() && s.charAt(pos) != '"') {
                    char c = s.charAt(pos++);
                    if (c == '\\') {
                        char esc = s.charAt(pos++);
                        switch (esc) {
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                            case '/': sb.append('/'); break;
                            case 'b': sb.append('\b'); break;
                            case 'f': sb.append('\f'); break;
                            case 'n': sb.append('\n'); break;
                            case 'r': sb.append('\r'); break;
                            case 't': sb.append('\t'); break;
                            case 'u':
                                String hex = s.substring(pos, pos + 4);
                                sb.append((char) Integer.parseInt(hex, 16));
                                pos += 4;
                                break;
                        }
                    } else sb.append(c);
                }
                pos++; // "
                return new JsonString(sb.toString());
            }
            JsonNumber parseNumber() {
                int start = pos;
                while (pos < s.length() && "-0123456789.eE+".indexOf(s.charAt(pos)) != -1) pos++;
                return new JsonNumber(s.substring(start, pos));
            }
            void skipWhitespace() {
                while (pos < s.length() && " \t\n\r".indexOf(s.charAt(pos)) != -1) pos++;
            }
        }
    }
}

import Foundation

// MARK: - Types
enum JsonId {
    case string(String)
    case integer(Int)
    case invalid
    case none

    var value: Any {
        switch self {
        case .string(let s): return s
        case .integer(let i): return i
        case .invalid: return NSNull()
        case .none: return NSNull()
        }
    }
