struct Tool {
    let name: String
    let title: String
    let description: String
    let inputSchema: [String: Any]
    let outputSchema: [String: Any]?
    let annotations: [String: Any]?
}

// MARK: - Server State
class MCPServer {
    var isInitialized = false
    var kvStore: [String: String] = [:]

    let tools: [Tool] = [
        Tool(name: "kv_set", title: "Set a value", description: "Store a string value under a key, replacing any previous value.",
             inputSchema: ["type": "object", "properties": ["key": ["type": "string", "minLength": 1], "value": ["type": "string"]], "required": ["key", "value"], "additionalProperties": false],
             outputSchema: nil, annotations: nil),
        Tool(name: "kv_get", title: "Get a value", description: "Return the value stored under a key.",
             inputSchema: ["type": "object", "properties": ["key": ["type": "string", "minLength": 1]], "required": ["key"], "additionalProperties": false],
             outputSchema: nil, annotations: nil),
        Tool(name: "kv_list", title: "List keys", description: "List the stored keys that start with a prefix, sorted by Unicode code point.",
             inputSchema: ["type": "object", "properties": ["prefix": ["type": "string"]], "required": [], "additionalProperties": false],
             outputSchema: ["type": "object", "properties": ["keys": ["type": "array", "items": ["type": "string"]], "count": ["type": "integer"]], "required": ["keys", "count"]],
             annotations: nil),
        Tool(name: "sum", title: "Sum integers", description: "Add up a non-empty list of integers.",
             inputSchema: ["type": "object", "properties": ["numbers": ["type": "array", "items": ["type": "integer"], "minItems": 1]], "required": ["numbers"], "additionalProperties": false],
             outputSchema: ["type": "object", "properties": ["sum": ["type": "integer"], "count": ["type": "integer"]], "required": ["sum", "count"]],
             annotations: ["readOnlyHint": true, "idempotentHint": true]),
        Tool(name: "text_stats", title: "Text statistics", description: "Count the words, Unicode code points and UTF-8 bytes of a text.",
             inputSchema: ["type": "object", "properties": ["text": ["type": "string"]], "required": ["text"], "additionalProperties": false],
             outputSchema: ["type": "object", "properties": ["words": ["type": "integer"], "codepoints": ["type": "integer"], "utf8_bytes": ["type": "integer"]], "required": ["words", "codepoints", "utf8_bytes"]],
             annotations: ["readOnlyHint": true])
    ]

    func processLine(_ line: String) {
        let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty { return }

        guard let data = trimmed.data(using: .utf8) else { return }

        do {
            guard let json = try JSONSerialization.jsonObject(with: data, options: []) as? [String: Any] else {
                sendResponse(id: .invalid, error: -32600, message: "Invalid Request")
                return
            }

            // Rule 3: Client response
            if json["method"] == nil && (json["result"] != nil || json["error"] != nil) {
                return
            }

            // Rule 4: Invalid Request
            let jsonrpc = json["jsonrpc"] as? String
            let method = json["method"] as? String
            let idAny = json["id"]

            var idValue: JsonId = .none
            if let idAny = idAny {
                if let s = idAny as? String {
                    idValue = .string(s)
                } else if let i = idAny as? Int {
                    idValue = .integer(i)
                } else {
                    idValue = .invalid
                }
            }

            if jsonrpc != "2.0" || method == nil || idValue == .invalid {
                sendResponse(id: idValue == .invalid ? .invalid : (idValue == .none ? .invalid : idValue), error: -32600, message: "Invalid Request")
                return
            }

            // Rule 5: Notification
            if idValue == .none {
                return
            }

            // Rule 6: Request
            let reqId = idValue
            let reqMethod = method!
            let params = json["params"] as? [String: Any]

            // Check if params is present but not an object
            if json["params"] != nil && params == nil {
                sendResponse(id: reqId, error: -32602, message: "Invalid params")
                return
            }

            // a. Method not found
            let validMethods = ["initialize", "ping", "tools/list", "tools/call"]
            if !validMethods.contains(reqMethod) {
                sendResponse(id: reqId, error: -32601, message: "Method not found")
                return
            }

            // c. Server not initialized
            if !isInitialized && reqMethod != "initialize" && reqMethod != "ping" {
                sendResponse(id: reqId, error: -32002, message: "Server not initialized")
                return
            }

            // Dispatch
            switch reqMethod {
            case "initialize":
                handleInitialize(id: reqId, params: params)
            case "ping":
                sendResult(id: reqId, result: [:])
            case "tools/list":
                handleToolsList(id: reqId)
            case "tools/call":
                handleToolsCall(id: reqId, params: params)
            default:
                break
            }
        } catch {
            sendResponse(id: .invalid, error: -32700, message: "Parse error")
        }
    }

    func handleInitialize(id: JsonId, params: [String: Any]?) {
        if isInitialized {
            sendResponse(id: id, error: -32600, message: "Already initialized")
            return
        }

        guard let params = params, let protocolVersion = params["protocolVersion"] as? String else {
            sendResponse(id: id, error: -32602, message: "Invalid params")
            return
        }

        let supported = ["2025-06-18", "2025-03-26", "2024-11-05"]
        let version = supported.contains(protocolVersion) ? protocolVersion : "2025-06-18"

        isInitialized = true
        let result: [String: Any] = [
            "protocolVersion": version,
            "capabilities": ["tools": ["listChanged": false]],
            "serverInfo": ["name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"]
        ]
        sendResult(id: id, result: result)
    }

    func handleToolsList(id: JsonId) {
        let toolList = tools.map { tool in
            var dict: [String: Any] = [
                "name": tool.name,
                "title": tool.title,
                "description": tool.description,
                "inputSchema": tool.inputSchema
            ]
            if let os = tool.outputSchema { dict["outputSchema"] = os }
            if let ann = tool.annotations { dict["annotations"] = ann }
            return dict
        }
        sendResult(id: id, result: ["tools": toolList])
    }

    func handleToolsCall(id: JsonId, params: [String: Any]?) {
        guard let params = params else {
            sendResponse(id: id, error: -32602, message: "Invalid params")
            return
        }

        guard let toolName = params["name"] as? String else {
            sendResponse(id: id, error: -32602, message: "Invalid params")
            return
        }

        guard let tool = tools.first(where: { $0.name == toolName }) else {
            sendResponse(id: id, error: -32602, message: "Unknown tool: \(toolName)")
            return
        }

        let arguments = params["arguments"] as? [String: Any] ?? [:]
        if params["arguments"] != nil && (params["arguments"] as? [String: Any]) == nil {
            sendToolFailure(id: id, message: "arguments must be an object")
            return
        }

        // Argument Validation
        let schemaProps = tool.inputSchema["properties"] as? [String: Any] ?? [:]
        let argKeys = arguments.keys
        let unknownKeys = argKeys.filter { schemaProps[$0] == nil }.sorted()
        if let firstUnknown = unknownKeys.first {
            sendToolFailure(id: id, message: "unknown argument: \(firstUnknown)")
            return
        }

        let required = tool.inputSchema["required"] as? [String] ?? []
        for req in required {
            if arguments[req] == nil {
                sendToolFailure(id: id, message: "missing required argument: \(req)")
                return
            }
        }

        // Type and Order Check
        let propOrder: [String] = {
            switch tool.name {
            case "kv_set": return ["key", "value"]
            case "kv_get": return ["key"]
            case "kv_list": return ["prefix"]
            case "sum": return ["numbers"]
            case "text_stats": return ["text"]
            default: return []
            }
        }()

        for prop in propOrder {
            guard let val = arguments[prop] else { continue }
            let propSchema = schemaProps[prop] as? [String: Any] ?? [:]
            let type = propSchema["type"] as? String

            if type == "string" {
                guard let s = val as? String else {
                    sendToolFailure(id: id, message: "argument \(prop) must be a string")
                    return
                }
                if let minLen = propSchema["minLength"] as? Int, s.count < minLen {
                    sendToolFailure(id: id, message: "argument \(prop) must not be empty")
                    return
                }
            } else if type == "array" {
                guard let arr = val as? [Any] else {
                    sendToolFailure(id: id, message: "argument \(prop) must be an array of integers")
                    return
                }
                for item in arr {
                    if !(item is Int) {
                        sendToolFailure(id: id, message: "argument \(prop) must be an array of integers")
                        return
                    }
                }
                if let minItems = propSchema["minItems"] as? Int, arr.count < minItems {
                    sendToolFailure(id: id, message: "argument \(prop) must not be empty")
                    return
                }
            }
        }

        // Tool Execution
        switch tool.name {
        case "kv_set":
            let key = arguments["key"] as! String
            let value = arguments["value"] as! String
            let existed = kvStore[key] != nil
            kvStore[key] = value
            sendToolSuccess(id: id, text: (existed ? "updated " : "created ") + key, structured: nil)
        case "kv_get":
            let key = arguments["key"] as! String
            if let val = kvStore[key] {
                sendToolSuccess(id: id, text: val, structured: nil)
            } else {
                sendToolFailure(id: id, message: "key not found: \(key)")
            }
        case "kv_list":
            let prefix = arguments["prefix"] as? String ?? ""
            let keys = kvStore.keys.filter { $0.hasPrefix(prefix) }.sorted()
            let result: [String: Any] = ["keys": keys, "count": keys.count]
            sendToolSuccess(id: id, text: nil, structured: result)
        case "sum":
            let numbers = arguments["numbers"] as! [Int]
            let total = numbers.reduce(0, +)
            let result: [String: Any] = ["sum": total, "count": numbers.count]
            sendToolSuccess(id: id, text: nil, structured: result)
        case "text_stats":
            let text = arguments["text"] as! String
            let separators = CharacterSet(charactersIn: " \t\n\r")
            let words = text.components(separatedBy: separators).filter { !$0.isEmpty }
            let result: [String: Any] = [
                "words": words.count,
                "codepoints": text.unicodeScalars.count,
                "utf8_bytes": text.utf8.count
            ]
            sendToolSuccess(id: id, text: nil, structured: result)
        default:
            break
        }
    }

    func sendToolSuccess(id: JsonId, text: String?, structured: [String: Any]?) {
        var result: [String: Any] = ["isError": false]
        if let s = structured {
            let jsonData = try! JSONSerialization.data(withJSONObject: s, options: [])
            let jsonString = String(data: jsonData, encoding: .utf8)!
            result["content"] = [["type": "text", "text": jsonString]]
            result["structuredContent"] = s
        } else {
            result["content"] = [["type": "text", "text": text ?? ""]]
        }
        sendResult(id: id, result: result)
    }

    func sendToolFailure(id: JsonId, message: String) {
        let result: [String: Any] = [
            "content": [["type": "text", "text": message]],
            "isError": true
        ]
        sendResult(id: id, result: result)
    }

    func sendResult(id: JsonId, result: Any) {
        let response: [String: Any] = [
            "jsonrpc": "2.0",
            "id": id.value,
            "result": result
        ]
        printJson(response)
    }

    func sendResponse(id: JsonId, error: Int, message: String) {
        let response: [String: Any] = [
            "jsonrpc": "2.0",
            "id": id.value,
            "error": ["code": error, "message": message]
        ]
        printJson(response)
    }

    func printJson(_ dict: [String: Any]) {
        if let data = try? JSONSerialization.data(withJSONObject: dict, options: []),
           let str = String(data: data, encoding: .utf8) {
            print(str)
        }
    }
}

