#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>
#include <stdint.h>

typedef enum { J_NULL, J_BOOL, J_NUMBER, J_STRING, J_ARRAY, J_OBJECT } JType;

typedef struct JVal {
    JType type;
    union {
        bool b;
        double n;
        struct { char *s; size_t len; } str;
        struct { struct JVal **elems; size_t count; } arr;
        struct { struct JMember *mems; size_t count; } obj;
    } v;
} JVal;

typedef struct JMember {
    char *key;
    JVal *val;
} JMember;

typedef struct {
    char *inst;
    char *schema;
} Error;

Error *errors = NULL;
size_t error_count = 0, error_capacity = 0;

void add_error(const char *inst, const char *schema) {
    for (size_t i = 0; i < error_count; i++)
        if (strcmp(errors[i].inst, inst) == 0 && strcmp(errors[i].schema, schema) == 0) return;
    if (error_count == error_capacity) {
        error_capacity = error_capacity == 0 ? 16 : error_capacity * 2;
        errors = realloc(errors, error_capacity * sizeof(Error));
    }
    errors[error_count].inst = strdup(inst);
    errors[error_count].schema = strdup(schema);
    error_count++;
}

char *json_skip_ws(char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

char *parse_json_val(char *s, JVal **val);

char *parse_json_str(char *s, JVal **val) {
    s++;
    char buf[8192];
    int b_idx = 0, cp_count = 0;
    while (*s != '"') {
        if (*s == '\\') {
            s++;
            if (*s == '"' || *s == '\\' || *s == '/') { buf[b_idx++] = *s++; cp_count++; }
            else if (*s == 'b') { buf[b_idx++] = '\b'; s++; cp_count++; }
            else if (*s == 'f') { buf[b_idx++] = '\f'; s++; cp_count++; }
            else if (*s == 'n') { buf[b_idx++] = '\n'; s++; cp_count++; }
            else if (*s == 'r') { buf[b_idx++] = '\r'; s++; cp_count++; }
            else if (*s == 't') { buf[b_idx++] = '\t'; s++; cp_count++; }
            else if (*s == 'u') {
                s++; uint32_t u1 = 0;
                for (int i = 0; i < 4; i++) {
                    char c = *s++;
                    u1 = u1 * 16 + (c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 0);
                }
                if (u1 >= 0xD800 && u1 <= 0xDBFF && *s == '\\' && *(s + 1) == 'u') {
                    s += 2; uint32_t u2 = 0;
                    for (int i = 0; i < 4; i++) {
                        char c = *s++;
                        u2 = u2 * 16 + (c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 0);
                    }
                    uint32_t cp = 0x10000 + ((u1 - 0xD800) << 10) + (u2 - 0xDC00);
                    if (cp <= 0x7F) buf[b_idx++] = (char)cp;
                    else if (cp <= 0x7FF) { buf[b_idx++] = (char)(0xC0 | (cp >> 6)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                    else if (cp <= 0xFFFF) { buf[b_idx++] = (char)(0xE0 | (cp >> 12)); buf[b_idx++] = (char)(0x80 | ((cp >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                    else { buf[b_idx++] = (char)(0xF0 | (cp >> 18)); buf[b_idx++] = (char)(0x80 | ((cp >> 12) & 0x3F)); buf[b_idx++] = (char)(0x80 | ((cp >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                    cp_count++;
                } else {
                    if (u1 <= 0x7F) buf[b_idx++] = (char)u1;
                    else if (u1 <= 0x7FF) { buf[b_idx++] = (char)(0xC0 | (u1 >> 6)); buf[b_idx++] = (char)(0x80 | (u1 & 0x3F)); }
                    else { buf[b_idx++] = (char)(0xE0 | (u1 >> 12)); buf[b_idx++] = (char)(0x80 | ((u1 >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (u1 & 0x3F)); }
                    cp_count++;
                }
            } else s++;
        } else { buf[b_idx++] = *s++; cp_count++; }
    }
    buf[b_idx] = '\0';
    *val = malloc(sizeof(JVal));
    (*val)->type = J_STRING;
    (*val)->v.str.s = strdup(buf);
    (*val)->v.str.len = cp_t_count(buf); // Fixed below
    return s++;
}

size_t count_cp(const char *s) {
    size_t count = 0;
    while (*s) {
        if ((*s & 0x80) == 0) s++;
        else if ((*s & 0xE0) == 0xC0) s += 2;
        else if ((*s & 0xF0) == 0xE0) s += 3;
        else if ((*s & 0xF8) == 0xF0) s += 4;
        else s++;
        count++;
    }
    return count;
}

// Redefining parse_json_str to use count_cp
char *parse_json_str_fixed(char *s, JVal **val) {
    s++; char buf[8192]; int b_idx = 0;
    while (*s != '"') {
        if (*s == '\\') {
            s++;
            if (*s == '"' || *s == '\\' || *s == '/') { buf[b_idx++] = *s++; }
            else if (*s == 'b') { buf[b_idx++] = '\b'; s++; }
            else if (*s == 'f') { buf[b_idx++] = '\f'; s++; }
            else if (*s == 'n') { buf[b_idx++] = '\n'; s++; }
            else if (*s == 'r') { buf[b_idx++] = '\r'; s++; }
            else if (*s == 't') { buf[b_idx++] = '\t'; s++; }
            else if (*s == 'u') {
                s++; uint32_t u1 = 0;
                for (int i = 0; i < 4; i++) {
                    char c = *s++;
                    u1 = u1 * 16 + (c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 0);
                }
                if (u1 >= 0xD800 && u1 <= 0xDBFF && *s == '\\' && *(s + 1) == 'u') {
                    s += 2; uint32_t u2 = 0;
                    for (int i = 0; i < 4; i++) {
                        char c = *s++;
                        u2 = u2 * 16 + (c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 0);
                    }
                    uint32_t cp = 0x10000 + ((u1 - 0xD800) << 10) + (u2 - 0xDC00);
                    if (cp <= 0x7F) buf[b_idx++] = (char)cp;
                    else if (cp <= 0x7FF) { buf[b_idx++] = (char)(0xC0 | (cp >> 6)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                    else if (cp <= 0xFFFF) { buf[b_idx++] = (char)(0xE0 | (cp >> 12)); buf[b_idx++] = (char)(0x80 | ((cp >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                    else { buf[b_idx++] = (char)(0xF0 | (cp >> 18)); buf[b_idx++] = (char)(0x80 | ((cp >> 12) & 0x3F)); buf[b_idx++] = (char)(0x80 | ((cp >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                } else {
                    if (u1 <= 0x7F) buf[b_idx++] = (char)u1;
                    else if (u1 <= 0x7FF) { buf[b_idx++] = (char)(0xC0 | (u1 >> 6)); buf[b_idx++] = (char)(0x80 | (u1 & 0x3F)); }
                    else { buf[b_idx++] = (char)(0xE0 | (u1 >> 12)); buf[b_idx++] = (char)(0x80 | ((u1 >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (u1 & 0x3F)); }
                }
            } else s++;
        } else buf[b_idx++] = *s++;
    }
    buf[b_idx] = '\0';
    *val = malloc(sizeof(JVal));
    (*val)->type = J_STRING;
    (*val)->v.str.s = strdup(buf);
    (*val)->v.str.len = count_cp(buf);
    return s++;
}

char *parse_json_num(char *s, JVal **val) {
    char *end;
    double n = strtod(s, &end);
    *val = malloc(sizeof(JVal));
    (*val)->type = J_NUMBER;
    (*val)->v.n = n;
    return end;
}

char *parse_json_val(char *s, JVal **val) {
    s = json_skip_ws(s);
    if (*s == '"') return parse_json_str_fixed(s, val);
    if (*s == '{') {
        s++; *val = malloc(sizeof(JVal));
        (*val)->type = J_OBJECT; (*val)->v.obj.count = 0; (*val)->v.obj.mems = NULL;
        s = json_skip_ws(s);
        if (*s == '}') return s++;
        while (1) {
            JVal *key_val; s = parse_json_val(s, &key_val);
            s = json_skip_ws(s); s++;
            JVal *v; s = parse_json_val(s, &v);
            (*val)->v.obj.mems = realloc((*val)->v.obj.mems, ((*val)->v.obj.count + 1) * sizeof(JMember));
            (*val)->v.obj.mems[(*val)->v.obj.count].key = strdup(key_val->v.str.s);
            (*val)->v.obj.mems[(*val)->v.obj.count].val = v;
            (*val)->v.obj.count++;
            free(key_val->v.str.s); free(key_val);
            s = json_skip_ws(s);
            if (*s == '}') return s++;
            s++; s = json_skip_ws(s);
        }
    }
    if (*s == '[') {
        s++; *val = malloc(sizeof(JVal));
        (*val)->type = J_ARRAY; (*val)->v.arr.count = 0; (*val)->v.arr.elems = NULL;
        s = json_skip_ws(s);
        if (*s == ']') return s++;
        while (1) {
            JVal *v; s = parse_json_val(s, &v);
            (*val)->v.arr.elems = realloc((*val)->v.arr.elems, ((*val)->v.arr.count + 1) * sizeof(JVal*));
            (*val)->v.arr.elems[(*val)->v.arr.count++] = v;
            s = json_skip_ws(s);
            if (*s == ']') return s++;
            s++; s = json_skip_ws(s);
        }
    }
    if (strncmp(s, "true", 4) == 0) { *val = malloc(sizeof(JVal)); (*val)->type = J_BOOL; (*val)->v.b = true; return s + 4; }
    if (strncmp(s, "false", 5) == 0) { *val = malloc(sizeof(JVal)); (*val)->type = J_BOOL; (*val)->v.b = false; return s + 5; }
    if (strncmp(s, "null", 4) == 0) { *val = malloc(sizeof(JVal)); (*val)->type = J_NULL; return s + 4; }
    return parse_json_num(s, val);
}

void free_json(JVal *v) {
    if (!v) return;
    if (v->type == J_STRING) free(v->v.str.s);
    else if (v->type == J_ARRAY) {
        for (size_t i = 0; i < v->v.arr.count; i++) free_json(v->v.arr.elems[i]);
        free(v->v.arr.elems);
    } else if (v->type == J_OBJECT) {
        for (size_t i = 0; i < v->v.obj.count; i++) { free(v->v.obj.mems[i].key); free_json(v->v.obj.mems[i].val); }
        free(v->v.obj.mems);
    }
    free(v);
}

bool deep_equal(JVal *a, JVal *b) {
    if (a->type != b->type) return false;
    if (a->type == J_NULL) return true;
    if (a->type == J_BOOL) return a->v.b == b->v.b;
    if (a->type == J_NUMBER) return a->v.n == b->v.n;
    if (a->type == J_STRING) return strcmp(a->v.str.s, b->v.str.s) == 0;
    if (a->type == J_ARRAY) {
        if (a->v.arr.count != b->v.arr.count) return false;
        for (size_t i = 0; i < a->v.arr.count; i++) if (!deep_equal(a->v.arr.elems[i], b->v.arr.elems[i])) return false;
        return true;
    }
    if (a->type == J_OBJECT) {
        if (a->v.obj.count != b->v.obj.count) return false;
        for (size_t i = 0; i < a->v.obj.count; i++) {
            bool found = false;
            for (size_t j = 0; j < b->v.obj.count; j++) {
                if (strcmp(a->v.obj.mems[i].key, b->v.obj.mems[j].key) == 0) {
                    if (deep_equal(a->v.obj.mems[i].val, b->v.obj.mems[j].val)) found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    return false;
}

char *escape_token(const char *s) {
    char buf[1024]; int b = 0;
    while (*s) {
        if (*s == '~') { buf[b++] = '~'; buf[b++] = '0'; }
        else if (*s == '/') { buf[b++] = '~'; buf[b++] = '1'; }
        else buf[b++] = *s;
        s++;
    }
    buf[b] = '\0';
    return strdup(buf);
}

char *join_ptr(const char *p, const char *token) {
    char *et = escape_token(token);
    char *res = malloc(strlen(p) + strlen(et) + 2);
    sprintf(res, "%s/%s", p, et);
    free(et);
    return res;
}

char *join_ptr_idx(const char *p, int idx) {
    char token[32]; sprintf(token, "%d", idx);
    char *et = escape_token(token);
    char *res = malloc(strlen(p) + strlen(et) + 2);
    sprintf(res, "%s/%s", p, et);
    free(et);
    return res;
}

JVal *resolve_ptr(JVal *root, const char *ptr) {
    if (strcmp(ptr, "#") == 0) return root;
    if (strncmp(ptr, "#/", 2) != 0) return NULL;
    char *s = strdup(ptr + 2);
    char *token = strtok(s, "/");
    JVal *curr = root;
    while (token) {
        if (curr->type != J_OBJECT) { free(s); return NULL; }
        bool found = false;
        for (size_t i = 0; i < curr->v.obj.count; i++) {
            char unesc[1024]; int b = 0;
            for (int j = 0; token[j]; j++) {
                if (token[j] == '~' && token[j+1] == '0') { unesc[b++] = '~'; j++; }
                else if (token[j] == '~' && token[j+1] == '1') { unesc[b++] = '/'; j++; }
                else unesc[b++] = token[j];
            }
            unesc[b] = '\0';
            if (strcmp(curr->v.obj.mems[i].key, unesc) == 0) {
                curr = curr->v.obj.mems[i].val;
                found = true;
                break;
            }
        }
        if (!found) { free(s); return NULL; }
        token = strtok(NULL, "/");
    }
    free(s);
    return curr;
}

JVal *get_member(JVal *obj, const char *key) {
    if (obj->type != J_OBJECT) return NULL;
    for (size_t i = 0; i < obj->v.obj.count; i++) if (strcmp(obj->v.obj.mems[i].key, key) == 0) return obj->v.obj.mems[i].val;
    return NULL;
}

bool validate_internal(JVal *root, JVal *inst, JVal *schema, const char *inst_ptr, const char *schema_ptr, bool report, bool *accepted);

void validate(JVal *root, JVal *inst, JVal *schema, const char *inst_ptr, const char *schema_ptr, bool report, bool *accepted) {
    *accepted = true;
    if (schema->type == J_BOOL) {
        if (!schema->v.b) {
            if (report) add_error(inst_ptr, schema_ptr);
            *accepted = false;
        }
        return;
    }
    if (schema->type != J_OBJECT) return;
    for (size_t i = 0; i < schema->v.obj.count; i++) {
        char *key = schema->v.obj.mems[i].key;
        JVal *sval = schema->v.obj.mems[i].val;
        char *next_schema_ptr = join_ptr(schema_ptr, key);
        if (strcmp(key, "type") == 0) {
            bool match = false;
            if (sval->type == J_STRING) {
                if (strcmp(sval->v.str.s, "null") == 0 && inst->type == J_NULL) match = true;
                else if (strcmp(sval->v.str.s, "boolean") == 0 && inst->type == J_BOOL) match = true;
                else if (strcmp(sval->v.str.s, "string") == 0 && inst->type == J_STRING) match = true;
                else if (strcmp(sval->v.str.s, "number") == 0 && inst->type == J_NUMBER) match = true;
                else if (strcmp(sval->v.str.s, "integer") == 0 && inst->type == J_NUMBER && floor(inst->v.n) == inst->v.n) match = true;
                else if (strcmp(sval->v.str.s, "array") == 0 && inst->type == J_ARRAY) match = true;
                else if (strcmp(sval->v.str.s, "object") == 0 && inst->type == J_OBJECT) match = true;
            } else if (sval->type == J_ARRAY) {
                for (size_t j = 0; j < sval->v.arr.count; j++) {
                    JVal *t = sval->v.arr.elems[j];
                    if (t->type == J_STRING) {
                        if (strcmp(t->v.str.s, "null") == 0 && inst->type == J_NULL) match = true;
                        else if (strcmp(t->v.str.s, "boolean") == 0 && inst->type == J_BOOL) match = true;
                        else if (strcmp(t->v.str.s, "string") == 0 && inst->type == J_STRING) match = true;
                        else if (strcmp(t->v.str.s, "number") == 0 && inst->type == J_NUMBER) match = true;
                        else if (strcmp(t->v.str.s, "integer") == 0 && inst->type == J_NUMBER && floor(inst->v.n) == inst->v.n) match = true;
                        else if (strcmp(t->v.str.s, "array") == 0 && inst->type == J_ARRAY) match = true;
                        else if (strcmp(t->v.str.s, "object") == 0 && inst->type == J_OBJECT) match = true;
                    }
                    if (match) break;
                }
            }
            if (!match) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "enum") == 0) {
            bool match = false;
            for (size_t j = 0; j < sval->v.arr.count; j++) if (deep_equal(inst, sval->v.arr.elems[j])) { match = true; break; }
            if (!match) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "const") == 0) {
            if (!deep_equal(inst, sval)) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (inst->type == J_NUMBER) {
            if (strcmp(key, "minimum") == 0 && sval->type == J_NUMBER && inst->v.n < sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maximum") == 0 && sval->type == J_NUMBER && inst->v.n > sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "exclusiveMinimum") == 0 && sval->type == J_NUMBER && inst->v.n <= sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "exclusiveMaximum") == 0 && sval->type == J_NUMBER && inst->v.n >= sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (inst->type == J_STRING) {
            if (strcmp(key, "minLength") == 0 && sval->type == J_NUMBER && inst->v.str.len < (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maxLength") == 0 && sval->type == J_NUMBER && inst->v.str.len > (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (inst->type == J_ARRAY) {
            if (strcmp(key, "minItems") == 0 && sval->type == J_NUMBER && inst->v.arr.count < (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maxItems") == 0 && sval->type == J_NUMBER && inst->v.arr.count > (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "uniqueItems") == 0 && sval->type == J_BOOL && sval->v.b) {
                bool dup = false;
                for (size_t j = 0; j < inst->v.arr.count; j++) for (size_t k = j + 1; k < inst->v.arr.count; k++) if (deep_equal(inst->v.arr.elems[j], inst->v.arr.elems[k])) { dup = true; break; }
                if (dup) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            } else if (strcmp(key, "prefixItems") == 0 && sval->type == J_ARRAY) {
                for (size_t j = 0; j < sval->v.arr.count && j < inst->v.arr.count; j++) {
                    char *ni = join_ptr_idx(inst_ptr, j), *ns = join_ptr_idx(next_schema_ptr, j);
                    bool acc; validate(root, inst->v.arr.elems[j], sval->v.arr.elems[j], ni, ns, report, &acc);
                    if (!acc) *accepted = false;
                    free(ni); free(ns);
                }
            } else if (strcmp(key, "items") == 0) {
                size_t start = 0; JVal *pi = get_member(schema, "prefixItems");
                if (pi) start = pi->v.arr.count;
                for (size_t j = start; j < inst->v.arr.count; j++) {
                    char *ni = join_ptr_idx(inst_ptr, j), *ns = join_ptr(schema_ptr, "items");
                    bool acc; validate(root, inst->v.arr.elems[j], sval, ni, ns, report, &acc);
                    if (!acc) *accepted = false;
                    free(ni); free(ns);
                }
            }
        } else if (inst->type == J_OBJECT) {
            if (strcmp(key, "minProperties") == 0 && sval->type == J_NUMBER && inst->v.obj.count < (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maxProperties") == 0 && sval->type == J_NUMBER && inst->v.obj.count > (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "required") == 0 && sval->type == J_ARRAY) {
                for (size_t j = 0; j < sval->v.arr.count; j++) {
                    if (!get_member(inst, sval->v.arr.elems[j]->v.str.s)) {
                        char *re = join_ptr_idx(next_schema_ptr, j);
                        if (report) add_error(inst_ptr, re);
                        free(re); *accepted = false;
                    }
                }
            } else if (strcmp(key, "properties") == 0 && sval->type == J_OBJECT) {
                for (size_t j = 0; j < sval->v.obj.count; j++) {
                    JVal *pv = get_member(inst, sval->v.obj.mems[j].key);
                    if (pv) {
                        char *ni = join_ptr(inst_ptr, sval->v.obj.mems[j].key), *ns = join_ptr(next_schema_ptr, sval->v.obj.mems[j].key);
                        bool acc; validate(root, pv, sval->v.obj.mems[j].val, ni, ns, report, &acc);
                        if (!acc) *accepted = false;
                        free(ni); free(ns);
                    }
                }
            } else if (strcmp(key, "additionalProperties") == 0) {
                JVal *props = get_member(schema, "properties");
                for (size_t j = 0; j < inst->v.obj.count; j++) {
                    bool is_prop = false;
                    if (props) for (size_t k = 0; k < props->v.obj.count; k++) if (strcmp(props->v.obj.mems[k].key, inst->v.obj.mems[j].key) == 0) { is_prop = true; break; }
                    if (!is_prop) {
                        char *ni = join_ptr(inst_ptr, inst->v.obj.mems[j].key), *ns = join_ptr(schema_ptr, "additionalProperties");
                        bool acc; validate(root, inst->v.obj.mems[j].val, sval, ni, ns, report, &acc);
                        if (!acc) *accepted = false;
                        free(ni); free(ns);
                    }
                }
            }
        } else if (strcmp(key, "allOf") == 0 && sval->type == J_ARRAY) {
            for (size_t j = 0; j < sval->v.arr.count; j++) {
                char *ns = join_ptr_idx(next_schema_ptr, j);
                bool acc; validate(root, inst, sval->v.arr.elems[j], inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            }
        } else if (strcmp(key, "anyOf") == 0 && sval->type == J_ARRAY) {
            bool any = false;
            for (size_t j = 0; j < sval->v.arr.count; j++) {
                bool acc; validate(root, inst, sval->v.arr.elems[j], inst_ptr, "", false, &acc);
                if (acc) { any = true; break; }
            }
            if (!any) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "oneOf") == 0 && sval->type == J_ARRAY) {
            int count = 0;
            for (size_t j = 0; j < sval->v.arr.count; j++) {
                bool acc; validate(root, inst, sval->v.arr.elems[j], inst_ptr, "", false, &acc);
                if (acc) count++;
            }
            if (count != 1) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "not") == 0) {
            bool acc; validate(root, inst, sval, inst_ptr, "", false, &acc);
            if (acc) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "if") == 0) {
            bool if_acc; validate(root, inst, sval, inst_ptr, "", false, &if_acc);
            JVal *then_s = get_member(schema, "then"), *else_s = get_member(schema, "else");
            if (if_acc && then_s) {
                char *ns = join_ptr(schema_ptr, "then");
                bool acc; validate(root, inst, then_s, inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            } else if (!if_acc && else_s) {
                char *ns = join_ptr(schema_ptr, "else");
                bool acc; validate(root, inst, else_s, inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            }
        } else if (strcmp(key, "$ref") == 0 && sval->type == J_STRING) {
            JVal *rs = resolve_ptr(root, sval->v.str.s);
            if (rs) {
                char *ns = strdup(sval->v.str.s);
                bool acc; validate(root, inst, rs, inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            }
        }
        free(next_schema_ptr);
    }
}

int cmp_err(const void *a, const void *b) {
    Error *e1 = (Error *)a, *e2 = (Error *)b;
    int r = strcmp(e1->inst, e2->inst);
    return r != 0 ? r : strcmp(e1->schema, e2->schema);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    char s_path[1024], i_path[1024];
    sprintf(s_path, "%s/schema.json", argv[1]);
    sprintf(i_path, "%s/instances.json", argv[1]);
    FILE *fs = fopen(s_path, "r"), *fi = fopen(i_path, "r");
    if (!fs || !fi) return 0;
    fseek(fs, 0, SEEK_END); long s_sz = ftell(fs); rewind(fs);
    char *s_buf = malloc(s_sz + 1); fread(s_buf, 1, s_sz, fs); s_buf[s_sz] = '\0';
    fseek(fi, 0, SEEK_END); long i_sz = ftell(fi); rewind(fi);
    char *i_buf = malloc(i_sz + 1); fread(i_buf, 1, i_sz, fi); i_buf[i_sz] = '\0';
    fclose(fs); fclose(fi);
    JVal *root_schema, *instances;
    parse_json_val(s_buf, &root_schema);
    parse_json_val(i_buf, &instances);
    int v_cnt = 0, i_cnt = 0;
    for (size_t n = 0; n < instances->v.arr.count; n++) {
        error_count = 0;
        bool acc;
        validate(root_schema, instances->v.arr.elems[n], root_schema, "#", "#", true, &acc);
        if (acc) { printf("%zu: valid\n", n); v_cnt++; }
        else {
            printf("%zu: invalid (%zu)\n", n, error_count);
            qsort(errors, error_count, sizeof(Error), cmp_err);
            for (size_t e = 0; e < error_count; e++) printf("  %s %s\n", errors[e].inst, errors[e].schema);
            i_cnt++;
        }
    }
    printf("valid=%d invalid=%d\n", v_cnt, i_cnt);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>
#include <stdint.h>

typedef enum { J_NULL, J_BOOL, J_NUMBER, J_STRING, J_ARRAY, J_OBJECT } JType;

typedef struct JVal {
    JType type;
    union {
        bool b;
        double n;
        struct { char *s; size_t len; } str;
        struct { struct JVal **elems; size_t count; } arr;
        struct { struct JMember *mems; size_t count; } obj;
    } v;
} JVal;

typedef struct JMember {
    char *key;
    JVal *val;
} JMember;

typedef struct {
    char *inst;
    char *schema;
} Error;

Error *errors = NULL;
size_t error_count = 0, error_capacity = 0;

void add_error(const char *inst, const char *schema) {
    for (size_t i = 0; i < error_count; i++)
        if (strcmp(errors[i].inst, inst) == 0 && strcmp(errors[i].schema, schema) == 0) return;
    if (error_count == error_capacity) {
        error_capacity = error_capacity == 0 ? 16 : error_capacity * 2;
        errors = realloc(errors, error_capacity * sizeof(Error));
    }
    errors[error_count].inst = strdup(inst);
    errors[error_count].schema = strdup(schema);
    error_count++;
}

char *json_skip_ws(char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

size_t count_cp(const char *s) {
    size_t count = 0;
    while (*s) {
        if ((*s & 0x80) == 0) s++;
        else if ((*s & 0xE0) == 0xC0) s += 2;
        else if ((*s & 0xF0) == 0xE0) s += 3;
        else if ((*s & 0xF8) == 0xF0) s += 4;
        else s++;
        count++;
    }
    return count;
}

char *parse_json_str(char *s, JVal **val) {
    s++;
    char buf[16384];
    int b_idx = 0;
    while (*s != '"') {
        if (*s == '\\') {
            s++;
            if (*s == '"' || *s == '\\' || *s == '/') { buf[b_idx++] = *s++; }
            else if (*s == 'b') { buf[b_idx++] = '\b'; s++; }
            else if (*s == 'f') { buf[b_idx++] = '\f'; s++; }
            else if (*s == 'n') { buf[b_idx++] = '\n'; s++; }
            else if (*s == 'r') { buf[b_idx++] = '\r'; s++; }
            else if (*s == 't') { buf[b_idx++] = '\t'; s++; }
            else if (*s == 'u') {
                s++; uint32_t u1 = 0;
                for (int i = 0; i < 4; i++) {
                    char c = *s++;
                    u1 = u1 * 16 + (c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 0);
                }
                if (u1 >= 0xD800 && u1 <= 0xDBFF && *s == '\\' && *(s + 1) == 'u') {
                    s += 2; uint32_t u2 = 0;
                    for (int i = 0; i < 4; i++) {
                        char c = *s++;
                        u2 = u2 * 16 + (c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 0);
                    }
                    uint32_t cp = 0x10000 + ((u1 - 0xD800) << 10) + (u2 - 0xDC00);
                    if (cp <= 0x7F) buf[b_idx++] = (char)cp;
                    else if (cp <= 0x7FF) { buf[b_idx++] = (char)(0xC0 | (cp >> 6)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                    else if (cp <= 0xFFFF) { buf[b_idx++] = (char)(0xE0 | (cp >> 12)); buf[b_idx++] = (char)(0x80 | ((cp >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                    else { buf[b_idx++] = (char)(0xF0 | (cp >> 18)); buf[b_idx++] = (char)(0x80 | ((cp >> 12) & 0x3F)); buf[b_idx++] = (char)(0x80 | ((cp >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (cp & 0x3F)); }
                } else {
                    if (u1 <= 0x7F) buf[b_idx++] = (char)u1;
                    else if (u1 <= 0x7FF) { buf[b_idx++] = (char)(0xC0 | (u1 >> 6)); buf[b_idx++] = (char)(0x80 | (u1 & 0x3F)); }
                    else { buf[b_idx++] = (char)(0xE0 | (u1 >> 12)); buf[b_idx++] = (char)(0x80 | ((u1 >> 6) & 0x3F)); buf[b_idx++] = (char)(0x80 | (u1 & 0x3F)); }
                }
            } else s++;
        } else buf[b_idx++] = *s++;
    }
    buf[b_idx] = '\0';
    *val = malloc(sizeof(JVal));
    (*val)->type = J_STRING;
    (*val)->v.str.s = strdup(buf);
    (*val)->v.str.len = count_cp(buf);
    return s++;
}

char *parse_json_num(char *s, JVal **val) {
    char *end;
    double n = strtod(s, &end);
    *val = malloc(sizeof(JVal));
    (*val)->type = J_NUMBER;
    (*val)->v.n = n;
    return end;
}

char *parse_json_val(char *s, JVal **val) {
    s = json_skip_ws(s);
    if (*s == '"') return parse_json_str(s, val);
    if (*s == '{') {
        s++; *val = malloc(sizeof(JVal));
        (*val)->type = J_OBJECT; (*val)->v.obj.count = 0; (*val)->v.obj.mems = NULL;
        s = json_skip_ws(s);
        if (*s == '}') return s++;
        while (1) {
            JVal *key_val; s = parse_json_val(s, &key_val);
            s = json_skip_ws(s); s++;
            JVal *v; s = parse_json_val(s, &v);
            (*val)->v.obj.mems = realloc((*val)->v.obj.mems, ((*val)->v.obj.count + 1) * sizeof(JMember));
            (*val)->v.obj.mems[(*val)->v.obj.count].key = strdup(key_val->v.str.s);
            (*val)->v.obj.mems[(*val)->v.obj.count].val = v;
            (*val)->v.obj.count++;
            free(key_val->v.str.s); free(key_val);
            s = json_skip_ws(s);
            if (*s == '}') return s++;
            s++; s = json_skip_ws(s);
        }
    }
    if (*s == '[') {
        s++; *val = malloc(sizeof(JVal));
        (*val)->type = J_ARRAY; (*val)->v.arr.count = 0; (*val)->v.arr.elems = NULL;
        s = json_skip_ws(s);
        if (*s == ']') return s++;
        while (1) {
            JVal *v; s = parse_json_val(s, &v);
            (*val)->v.arr.elems = realloc((*val)->v.arr.elems, ((*val)->v.arr.count + 1) * sizeof(JVal*));
            (*val)->v.arr.elems[(*val)->v.arr.count++] = v;
            s = json_skip_ws(s);
            if (*s == ']') return s++;
            s++; s = json_skip_ws(s);
        }
    }
    if (strncmp(s, "true", 4) == 0) { *val = malloc(sizeof(JVal)); (*val)->type = J_BOOL; (*val)->v.b = true; return s + 4; }
    if (strncmp(s, "false", 5) == 0) { *val = malloc(sizeof(JVal)); (*val)->type = J_BOOL; (*val)->v.b = false; return s + 5; }
    if (strncmp(s, "null", 4) == 0) { *val = malloc(sizeof(JVal)); (*val)->type = J_NULL; return s + 4; }
    return parse_json_num(s, val);
}

void free_json(JVal *v) {
    if (!v) return;
    if (v->type == J_STRING) free(v->v.str.s);
    else if (v->type == J_ARRAY) {
        for (size_t i = 0; i < v->v.arr.count; i++) free_json(v->v.arr.elems[i]);
        free(v->v.arr.elems);
    } else if (v->type == J_OBJECT) {
        for (size_t i = 0; i < v->v.obj.count; i++) { free(v->v.obj.mems[i].key); free_json(v->v.obj.mems[i].val); }
        free(v->v.obj.mems);
    }
    free(v);
}

bool deep_equal(JVal *a, JVal *b) {
    if (a->type != b->type) return false;
    if (a->type == J_NULL) return true;
    if (a->type == J_BOOL) return a->v.b == b->v.b;
    if (a->type == J_NUMBER) return a->v.n == b->v.n;
    if (a->type == J_STRING) return strcmp(a->v.str.s, b->v.str.s) == 0;
    if (a->type == J_ARRAY) {
        if (a->v.arr.count != b->v.arr.count) return false;
        for (size_t i = 0; i < a->v.arr.count; i++) if (!deep_equal(a->v.arr.elems[i], b->v.arr.elems[i])) return false;
        return true;
    }
    if (a->type == J_OBJECT) {
        if (a->v.obj.count != b->v.obj.count) return false;
        for (size_t i = 0; i < a->v.obj.count; i++) {
            bool found = false;
            for (size_t j = 0; j < b->v.obj.count; j++) {
                if (strcmp(a->v.obj.mems[i].key, b->v.obj.mems[j].key) == 0) {
                    if (deep_equal(a->v.obj.mems[i].val, b->v.obj.mems[j].val)) found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    return false;
}

char *escape_token(const char *s) {
    char buf[1024]; int b = 0;
    while (*s) {
        if (*s == '~') { buf[b++] = '~'; buf[b++] = '0'; }
        else if (*s == '/') { buf[b++] = '~'; buf[b++] = '1'; }
        else buf[b++] = *s;
        s++;
    }
    buf[b] = '\0';
    return strdup(buf);
}

char *join_ptr(const char *p, const char *token) {
    char *et = escape_token(token);
    char *res = malloc(strlen(p) + strlen(et) + 2);
    sprintf(res, "%s/%s", p, et);
    free(et);
    return res;
}

char *join_ptr_idx(const char *p, int idx) {
    char token[32]; sprintf(token, "%d", idx);
    char *et = escape_token(token);
    char *res = malloc(strlen(p) + strlen(et) + 2);
    sprintf(res, "%s/%s", p, et);
    free(et);
    return res;
}

JVal *resolve_ptr(JVal *root, const char *ptr) {
    if (strcmp(ptr, "#") == 0) return root;
    if (strncmp(ptr, "#/", 2) != 0) return NULL;
    char *s = strdup(ptr + 2);
    char *token = strtok(s, "/");
    JVal *curr = root;
    while (token) {
        if (curr->type != J_OBJECT) { free(s); return NULL; }
        bool found = false;
        for (size_t i = 0; i < curr->v.obj.count; i++) {
            char unesc[1024]; int b = 0;
            for (int j = 0; token[j]; j++) {
                if (token[j] == '~' && token[j+1] == '0') { unesc[b++] = '~'; j++; }
                else if (token[j] == '~' && token[j+1] == '1') { unesc[b++] = '/'; j++; }
                else unesc[b++] = token[j];
            }
            unesc[b] = '\0';
            if (strcmp(curr->v.obj.mems[i].key, unesc) == 0) {
                curr = curr->v.obj.mems[i].val;
                found = true;
                break;
            }
        }
        if (!found) { free(s); return NULL; }
        token = strtok(NULL, "/");
    }
    free(s);
    return curr;
}

JVal *get_member(JVal *obj, const char *key) {
    if (obj->type != J_OBJECT) return NULL;
    for (size_t i = 0; i < obj->v.obj.count; i++) if (strcmp(obj->v.obj.mems[i].key, key) == 0) return obj->v.obj.mems[i].val;
    return NULL;
}

bool validate(JVal *root, JVal *inst, JVal *schema, const char *inst_ptr, const char *schema_ptr, bool report, bool *accepted) {
    *accepted = true;
    if (schema->type == J_BOOL) {
        if (!schema->v.b) {
            if (report) add_error(inst_ptr, schema_ptr);
            *accepted = false;
        }
        return *accepted;
    }
    if (schema->type != J_OBJECT) return true;

    for (size_t i = 0; i < schema->v.obj.count; i++) {
        char *key = schema->v.obj.mems[i].key;
        JVal *sval = schema->v.obj.mems[i].val;
        char *next_schema_ptr = join_ptr(schema_ptr, key);

        if (strcmp(key, "type") == 0) {
            bool match = false;
            if (sval->type == J_STRING) {
                if (strcmp(sval->v.str.s, "null") == 0 && inst->type == J_NULL) match = true;
                else if (strcmp(sval->v.str.s, "boolean") == 0 && inst->type == J_BOOL) match = true;
                else if (strcmp(sval->v.str.s, "string") == 0 && inst->type == J_STRING) match = true;
                else if (strcmp(sval->v.str.s, "number") == 0 && inst->type == J_NUMBER) match = true;
                else if (strcmp(sval->v.str.s, "integer") == 0 && inst->type == J_NUMBER && floor(inst->v.n) == inst->v.n) match = true;
                else if (strcmp(sval->v.str.s, "array") == 0 && inst->type == J_ARRAY) match = true;
                else if (strcmp(sval->v.str.s, "object") == 0 && inst->type == J_OBJECT) match = true;
            } else if (sval->type == J_ARRAY) {
                for (size_t j = 0; j < sval->v.arr.count; j++) {
                    JVal *t = sval->v.arr.elems[j];
                    if (t->type == J_STRING) {
                        if (strcmp(t->v.str.s, "null") == 0 && inst->type == J_NULL) match = true;
                        else if (strcmp(t->v.str.s, "boolean") == 0 && inst->type == J_BOOL) match = true;
                        else if (strcmp(t->v.str.s, "string") == 0 && inst->type == J_STRING) match = true;
                        else if (strcmp(t->v.str.s, "number") == 0 && inst->type == J_NUMBER) match = true;
                        else if (strcmp(t->v.str.s, "integer") == 0 && inst->type == J_NUMBER && floor(inst->v.n) == inst->v.n) match = true;
                        else if (strcmp(t->v.str.s, "array") == 0 && inst->type == J_ARRAY) match = true;
                        else if (strcmp(t->v.str.s, "object") == 0 && inst->type == J_OBJECT) match = true;
                    }
                    if (match) break;
                }
            }
            if (!match) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "enum") == 0) {
            bool match = false;
            for (size_t j = 0; j < sval->v.arr.count; j++) if (deep_equal(inst, sval->v.arr.elems[j])) { match = true; break; }
            if (!match) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "const") == 0) {
            if (!deep_equal(inst, sval)) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (inst->type == J_NUMBER) {
            if (strcmp(key, "minimum") == 0 && sval->type == J_NUMBER && inst->v.n < sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maximum") == 0 && sval->type == J_NUMBER && inst->v.n > sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "exclusiveMinimum") == 0 && sval->type == J_NUMBER && inst->v.n <= sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "exclusiveMaximum") == 0 && sval->type == J_NUMBER && inst->v.n >= sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (inst->type == J_STRING) {
            if (strcmp(key, "minLength") == 0 && sval->type == J_NUMBER && inst->v.str.len < (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maxLength") == 0 && sval->type == J_NUMBER && inst->v.str.len > (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (inst->type == J_ARRAY) {
            if (strcmp(key, "minItems") == 0 && sval->type == J_NUMBER && inst->v.arr.count < (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maxItems") == 0 && sval->type == J_NUMBER && inst->v.arr.count > (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "uniqueItems") == 0 && sval->type == J_BOOL && sval->v.b) {
                bool dup = false;
                for (size_t j = 0; j < inst->v.arr.count; j++) for (size_t k = j + 1; k < inst->v.arr.count; k++) if (deep_equal(inst->v.arr.elems[j], inst->v.arr.elems[k])) { dup = true; break; }
                if (dup) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            } else if (strcmp(key, "prefixItems") == 0 && sval->type == J_ARRAY) {
                for (size_t j = 0; j < sval->v.arr.count && j < inst->v.arr.count; j++) {
                    char *ni = join_ptr_idx(inst_ptr, j), *ns = join_ptr_idx(next_schema_ptr, j);
                    bool acc; validate(root, inst->v.arr.elems[j], sval->v.arr.elems[j], ni, ns, report, &acc);
                    if (!acc) *accepted = false;
                    free(ni); free(ns);
                }
            } else if (strcmp(key, "items") == 0) {
                size_t start = 0; JVal *pi = get_member(schema, "prefixItems");
                if (pi && pi->type == J_ARRAY) start = pi->v.arr.count;
                for (size_t j = start; j < inst->v.arr.count; j++) {
                    char *ni = join_ptr_idx(inst_ptr, j), *ns = join_ptr(schema_ptr, "items");
                    bool acc; validate(root, inst->v.arr.elems[j], sval, ni, ns, report, &acc);
                    if (!acc) *accepted = false;
                    free(ni); free(ns);
                }
            }
        } else if (inst->type == J_OBJECT) {
            if (strcmp(key, "minProperties") == 0 && sval->type == J_NUMBER && inst->v.obj.count < (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "maxProperties") == 0 && sval->type == J_NUMBER && inst->v.obj.count > (size_t)sval->v.n) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
            else if (strcmp(key, "required") == 0 && sval->type == J_ARRAY) {
                for (size_t j = 0; j < sval->v.arr.count; j++) {
                    if (!get_member(inst, sval->v.arr.elems[j]->v.str.s)) {
                        char *re = join_ptr_idx(next_schema_ptr, j);
                        if (report) add_error(inst_ptr, re);
                        free(re); *accepted = false;
                    }
                }
            } else if (strcmp(key, "properties") == 0 && sval->type == J_OBJECT) {
                for (size_t j = 0; j < sval->v.obj.count; j++) {
                    JVal *pv = get_member(inst, sval->v.obj.mems[j].key);
                    if (pv) {
                        char *ni = join_ptr(inst_ptr, sval->v.obj.mems[j].key), *ns = join_ptr(next_schema_ptr, sval->v.obj.mems[j].key);
                        bool acc; validate(root, pv, sval->v.obj.mems[j].val, ni, ns, report, &acc);
                        if (!acc) *accepted = false;
                        free(ni); free(ns);
                    }
                }
            } else if (strcmp(key, "additionalProperties") == 0) {
                JVal *props = get_member(schema, "properties");
                for (size_t j = 0; j < inst->v.obj.count; j++) {
                    bool is_prop = false;
                    if (props && props->type == J_OBJECT) for (size_t k = 0; k < props->v.obj.count; k++) if (strcmp(props->v.obj.mems[k].key, inst->v.obj.mems[j].key) == 0) { is_prop = true; break; }
                    if (!is_prop) {
                        char *ni = join_ptr(inst_ptr, inst->v.obj.mems[j].key), *ns = join_ptr(schema_ptr, "additionalProperties");
                        bool acc; validate(root, inst->v.obj.mems[j].val, sval, ni, ns, report, &acc);
                        if (!acc) *accepted = false;
                        free(ni); free(ns);
                    }
                }
            }
        } else if (strcmp(key, "allOf") == 0 && sval->type == J_ARRAY) {
            for (size_t j = 0; j < sval->v.arr.count; j++) {
                char *ns = join_ptr_idx(next_schema_ptr, j);
                bool acc; validate(root, inst, sval->v.arr.elems[j], inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            }
        } else if (strcmp(key, "anyOf") == 0 && sval->type == J_ARRAY) {
            bool any = false;
            for (size_t j = 0; j < sval->v.arr.count; j++) {
                bool acc; validate(root, inst, sval->v.arr.elems[j], inst_ptr, "", false, &acc);
                if (acc) { any = true; break; }
            }
            if (!any) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "oneOf") == 0 && sval->type == J_ARRAY) {
            int count = 0;
            for (size_t j = 0; j < sval->v.arr.count; j++) {
                bool acc; validate(root, inst, sval->v.arr.elems[j], inst_ptr, "", false, &acc);
                if (acc) count++;
            }
            if (count != 1) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "not") == 0) {
            bool acc; validate(root, inst, sval, inst_ptr, "", false, &acc);
            if (acc) { if (report) add_error(inst_ptr, next_schema_ptr); *accepted = false; }
        } else if (strcmp(key, "if") == 0) {
            bool if_acc; validate(root, inst, sval, inst_ptr, "", false, &if_acc);
            JVal *then_s = get_member(schema, "then"), *else_s = get_member(schema, "else");
            if (if_acc && then_s) {
                char *ns = join_ptr(schema_ptr, "then");
                bool acc; validate(root, inst, then_s, inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            } else if (!if_acc && else_s) {
                char *ns = join_ptr(schema_ptr, "else");
                bool acc; validate(root, inst, else_s, inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            }
        } else if (strcmp(key, "$ref") == 0 && sval->type == J_STRING) {
            JVal *rs = resolve_ptr(root, sval->v.str.s);
            if (rs) {
                char *ns = strdup(sval->v.str.s);
                bool acc; validate(root, inst, rs, inst_ptr, ns, report, &acc);
                if (!acc) *accepted = false;
                free(ns);
            }
        }
        free(next_schema_ptr);
    }
    return *accepted;
}

int cmp_err(const void *a, const void *b) {
    Error *e1 = (Error *)a, *e2 = (Error *)b;
    int r = strcmp(e1->inst, e2->inst);
    return r != 0 ? r : strcmp(e1->schema, e2->schema);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    char s_path[1024], i_path[1024];
    sprintf(s_path, "%s/schema.json", argv[1]);
    sprintf(i_path, "%s/instances.json", argv[1]);
    FILE *fs = fopen(s_path, "r"), *fi = fopen(i_path, "r");
    if (!fs || !fi) return 0;
    fseek(fs, 0, SEEK_END); long s_sz = ftell(fs); rewind(fs);
    char *s_buf = malloc(s_sz + 1); fread(s_buf, 1, s_sz, fs); s_buf[s_sz] = '\0';
    fseek(fi, 0, SEEK_END); long i_sz = ftell(fi); rewind(fi);
    char *i_buf = malloc(i_sz + 1); fread(i_buf, 1, i_sz, fi); i_buf[i_sz] = '\0';
    fclose(fs); fclose(fi);
    JVal *root_schema, *instances;
    parse_json_val(s_buf, &root_schema);
    parse_json_val(i_buf, &instances);
    int v_cnt = 0, i_cnt = 0;
    for (size_t n = 0; n < instances->v.arr.count; n++) {
        error_count = 0;
        bool acc;
        validate(root_schema, instances->v.arr.elems[n], root_schema, "#", "#", true, &acc);
        if (acc) { printf("%zu: valid\n", n); v_cnt++; }
        else {
            printf("%zu: invalid (%zu)\n", n, error_count);
            qsort(errors, error_count, sizeof(Error), cmp_err);
            for (size_t e = 0; e < error_count; e++) printf("  %s %s\n", errors[e].inst, errors[e].schema);
            i_cnt++;
        }
    }
    printf("valid=%d invalid=%d\n", v_cnt, i_cnt);
    return 0;
}

