let isInitialized = false;
const kvStore = new Map<string, string>();

function isValidId(id: any): boolean {
  if (typeof id === 'string') return true;
  if (typeof id === 'number' && Number.isInteger(id)) return true;
  return false;
}

function processLine(line: string) {
  const trimmed = line.trim();
  if (!trimmed) return;

  let parsed: any;
  try {
    parsed = JSON.parse(trimmed);
  } catch (e) {
    console.log(JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } }));
    return;
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    console.log(JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid Request" } }));
    return;
  }

  if (parsed.method === undefined && (parsed.result !== undefined || parsed.error !== undefined)) {
    return;
  }

  const id = parsed.id;
  const method = parsed.method;

  if (parsed.jsonrpc !== "2.0" || typeof method !== 'string' || (id !== undefined && !isValidId(id))) {
    console.log(JSON.stringify({ jsonrpc: "2.0", id: isValidId(id) ? id : null, error: { code: -32600, message: "Invalid Request" } }));
    return;
  }

  if (id === undefined) return;

  const params = parsed.params;
  if (params !== undefined && (typeof params !== 'object' || params === null || Array.isArray(params))) {
    console.log(JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } }));
    return;
  }

  if (method === 'initialize') {
    if (isInitialized) {
      console.log(JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32600, message: "Already initialized" } }));
      return;
    }
    if (!params || typeof params.protocolVersion !== 'string') {
      console.log(JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } }));
      return;
    }
    const validVersions = ["2025-06-18", "2025-03-26", "2024-11-05"];
    const version = validVersions.includes(params.protocolVersion) ? params.protocolVersion : "2025-06-18";
    isInitialized = true;
    console.log(JSON.stringify({
      jsonrpc: "2.0",
      id,
      result: {
        protocolVersion: version,
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
      }
    }));
    return;
  }

  if (method === 'ping') {
    console.log(JSON.stringify({ jsonrpc: "2.0", id, result: {} }));
    return;
  }

  if (!isInitialized) {
    console.log(JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32002, message: "Server not initialized" } }));
    return;
  }

  if (method === 'tools/list') {
    console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { tools: TOOLS } }));
    return;
  }

  if (method === 'tools/call') {
    if (!params || typeof params.name !== 'string') {
      console.log(JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } }));
      return;
    }
    const tool = TOOLS.find(t => t.name === params.name);
    if (!tool) {
      console.log(JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: `Unknown tool: ${params.name}` } }));
      return;
    }

    const args = params.arguments;
    if (args !== undefined && (typeof args !== 'object' || args === null || Array.isArray(args))) {
      console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: "arguments must be an object" }], isError: true } }));
      return;
    }

    const activeArgs = args || {};
    const unknownArgs = Object.keys(activeArgs).filter(k => !(k in tool.inputSchema.properties));
    if (unknownArgs.length > 0) {
      unknownArgs.sort();
      console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `unknown argument: ${unknownArgs[0]}` }], isError: true } }));
      return;
    }

    for (const propName of Object.keys(tool.inputSchema.properties)) {
      const prop = tool.inputSchema.properties[propName];
      const val = activeArgs[propName];
      const isRequired = tool.inputSchema.required?.includes(propName);

      if (val === undefined) {
        if (isRequired) {
          console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `missing required argument: ${propName}` }], isError: true } }));
          return;
        }
        continue;
      }

      if (prop.type === 'string') {
        if (typeof val !== 'string') {
          console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `argument ${propName} must be a string` }], isError: true } }));
          return;
        }
        if (prop.minLength === 1 && val.length === 0) {
          console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `argument ${propName} must not be empty` }], isError: true } }));
          return;
        }
      } else if (prop.type === 'array') {
        if (!Array.isArray(val)) {
          console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `argument ${propName} must be an array of integers` }], isError: true } }));
          return;
        }
        if (!val.every(v => typeof v === 'number' && Number.isInteger(v))) {
          console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `argument ${propName} must be an array of integers` }], isError: true } }));
          return;
        }
        if (prop.minItems === 1 && val.length === 0) {
          console.log(JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `argument ${propName} must not be empty` }], isError: true } }));
          return;
        }
      }
    }

    let result: any;
    if (tool.name === 'kv_set') {
      const { key, value } = activeArgs;
      const exists = kvStore.has(key);
      kvStore.set(key, value);
      result = { content: [{ type: "text", text: `${exists ? 'updated' : 'created'} ${key}` }], isError: false };
    } else if (tool.name === 'kv_get') {
      const { key } = activeArgs;
      if (!kvStore.has(key)) {
        result = { content: [{ type: "text", text: `key not found: ${key}` }], isError: true };
      } else {
        result = { content: [{ type: "text", text: kvStore.get(key) }], isError: false };
      }
    } else if (tool.name === 'kv_list') {
      const prefix = activeArgs.prefix || "";
      const keys = Array.from(kvStore.keys()).filter(k => k.startsWith(prefix)).sort();
      const S = { keys, count: keys.length };
      result = { content: [{ type: "text", text: JSON.stringify(S) }], structuredContent: S, isError: false };
    } else if (tool.name === 'sum') {
      const numbers = activeArgs.numbers;
      const sum = numbers.reduce((a: number, b: number) => a + b, 0);
      const S = { sum, count: numbers.length };
      result = { content: [{ type: "text", text: JSON.stringify(S) }], structuredContent: S, isError: false };
    } else if (tool.name === 'text_stats') {
      const text = activeArgs.text || "";
      const words = text.split(/[ \t\n\r]+/).filter((s: string) => s.length > 0).length;
      const codepoints = [...text].length;
      const utf8_bytes = Buffer.byteLength(text, 'utf8');
      const S = { words, codepoints, utf8_bytes };
      result = { content: [{ type: "text", text: JSON.stringify(S) }], structuredContent: S, isError: false };
    }

    console.log(JSON.stringify({ jsonrpc: "2.0", id, result }));
    return;
  }

  console.log(JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found" } }));
}

const rl = readline.createInterface({
  input: process.stdin,
  terminal: false
});

rl.on('line', (line) => {
  processLine(line);
});

