                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"key not found: %s\"}],\"isError\":true}}\n", key_v->s);
            } else {
                printf("{\"jsonrpc\":\"2.0\",");
                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"%s\"}],\"isError\":false}}\n", kv_store[found].v);
            }
            return;
        } else if (strcmp(name, "kv_list") == 0) {
            JsonValue *pref_v = get_obj_member(args, "prefix");
            const char *prefix = (pref_v && pref_v->type == JSON_STRING) ? pref_v->s : "";
            int match_count = 0;
            for (int i = 0; i < kv_count; i++) if (strncmp(kv_store[i].k, prefix, strlen(prefix)) == 0) match_count++;
            KVEntry *matches = malloc(sizeof(KVEntry) * match_count);
            int m_idx = 0;
            for (int i = 0; i < kv_count; i++) if (strncmp(kv_store[i].k, prefix, strlen(prefix)) == 0) matches[m_idx++] = kv_store[i];
            qsort(matches, match_count, sizeof(KVEntry), compare_kv);
            printf("{\"jsonrpc\":\"2.0\",");
            if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
            printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"{\"keys\":[");
            for (int i = 0; i < match_count; i++) {
                print_json_string(matches[i].k);
                if (i < match_count - 1) printf(",");
            }
            printf("],\"count\":%d}\"}],\"structuredContent\":{\"keys\":[", match_count);
            for (int i = 0; i < match_count; i++) {
                print_json_string(matches[i].k);
                if (i < match_count - 1) printf(",");
            }
            printf("],\"count\":%d},\"isError\":false}}\n", match_count);
            free(matches);
            return;
        } else if (strcmp(name, "sum") == 0) {
            JsonValue *num_v = get_obj_member(args, "numbers");
            if (!num_v || num_v->type != JSON_ARRAY) {
                printf("{\"jsonrpc\":\"2.0\",");
                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"argument numbers must be an array of integers\"}],\"isError\":true}}\n");
                return;
            }
            if (num_v->array.count == 0) {
                printf("{\"jsonrpc\":\"2.0\",");
                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"argument numbers must not be empty\"}],\"isError\":true}}\n");
                return;
            }
            long long total = 0;
            for (int i = 0; i < num_v->array.count; i++) {
                JsonValue *el = num_v->array.elements[i];
                if (el->type != JSON_NUMBER || el->has_decimal || el->has_exponent) {
                    printf("{\"jsonrpc\":\"2.0\",");
                    if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                    printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"argument numbers must be an array of integers\"}],\"isError\":true}}\n");
                    return;
                }
                total += (long long)el->n;
            }
            printf("{\"jsonrpc\":\"2.0\",");
            if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
            printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"{\"sum\":%lld,\"count\":%d}\"}],\"structuredContent\":{\"sum\":%lld,\"count\":%d},\"isError\":false}}\n", total, num_v->array.count, total, num_v->array.count);
            return;
        } else if (strcmp(name, "text_stats") == 0) {
            JsonValue *text_v = get_obj_member(args, "text");
            if (!text_v || text_v->type != JSON_STRING) {
                printf("{\"jsonrpc\":\"2.0\",");
                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"argument text must be a string\"}],\"isError\":true}}\n");
                return;
            }
            int w = count_words(text_v->s), c = count_codepoints(text_v->s), b = strlen(text_v->s);
            printf("{\"jsonrpc\":\"2.0\",");
            if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
            printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"{\"words\":%d,\"codepoints\":%d,\"utf8_bytes\":%d}\"}],\"structuredContent\":{\"words\":%d,\"codepoints\":%d,\"utf8_bytes\":%d},\"isError\":false}}\n", w, c, b, w, c, b);
            return;
        } else {
            printf("{\"jsonrpc\":\"2.0\",");
            if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
            printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"Unknown tool: %s\"}],\"isError\":true}}\n", name);
            return;
        }
    } else {
        print_error(id, -32601, "Method not found");
    }
}

int main() {
    char line[65536];
    while (fgets(line, sizeof(line), stdin)) {
        char *trimmed = line;
        while (*trimmed && isspace(*trimmed)) trimmed++;
        if (!*trimmed) continue;
        const char *p = trimmed;
        JsonValue *json = json_parse_value(&p);
        skip_whitespace(&p);
        if (!json || *p != '\0') {
            print_error(NULL, -32700, "Parse error");
            json_free(json);
        } else if (json->type != JSON_OBJECT) {
            print_error(NULL, -32600, "Invalid Request");
            json_free(json);
        } else {
            JsonValue *jsonrpc = get_obj_member(json, "jsonrpc");
            JsonValue *method = get_obj_member(json, "method");
            JsonValue *id = get_obj_member(json, "id");
            bool id_valid = (id && (id->type == JSON_STRING || (id->type == JSON_NUMBER && !id->has_decimal && !id->has_exponent)));
            if (get_obj_member(json, "result") || get_obj_member(json, "error")) {
                json_free(json);
            } else if (!jsonrpc || jsonrpc->type != JSON_STRING || strcmp(jsonrpc->s, "2.0") != 0 || !method || method->type != JSON_STRING || (!id_valid && id)) {
                print_error(id_valid ? id : NULL, -32600, "Invalid Request");
                json_free(json);
            } else if (!id) {
                json_free(json);
            } else {
                handle_request(json);
                json_free(json);
            }
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

typedef enum { JSON_STRING, JSON_NUMBER, JSON_BOOLEAN, JSON_NULL, JSON_ARRAY, JSON_OBJECT } JsonType;

typedef struct JsonValue {
    JsonType type;
    union {
        char *s;
        double n;
        bool b;
        struct {
            struct JsonValue **elements;
            int count;
        } array;
        struct {
            char **keys;
            struct JsonValue **values;
            int count;
        } object;
    };
    bool has_decimal;
    bool has_exponent;
} JsonValue;

JsonValue *json_parse_value(const char **json);
JsonValue *json_parse_object(const char **json);
JsonValue *json_parse_array(const char **json);
JsonValue *json_parse_string(const char **json);
JsonValue *json_parse_number(const char **json);

void json_free(JsonValue *v) {
    if (!v) return;
    if (v->type == JSON_STRING) free(v->s);
    else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->array.count; i++) json_free(v->array.elements[i]);
        free(v->array.elements);
    } else if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->object.count; i++) {
            free(v->object.keys[i]);
            json_free(v->object.values[i]);
        }
        free(v->object.keys);
        free(v->object.values);
    }
    free(v);
}

void skip_whitespace(const char **json) {
    while (**json && (**json == ' ' || **json == '\t' || **json == '\n' || **json == '\r')) (*json)++;
}

JsonValue *json_parse_string(const char **json) {
    if (**json != '"') return NULL;
    (*json)++;
    int len = 0;
    char buf[8192];
    while (**json && **json != '"') {
        if (**json == '\\') {
            (*json)++;
            if (**json == 'n') buf[len++] = '\n';
            else if (**json == 'r') buf[len++] = '\r';
            else if (**json == 't') buf[len++] = '\t';
            else if (**json == 'b') buf[len++] = '\b';
            else if (**json == 'f') buf[len++] = '\f';
            else if (**json == '"') buf[len++] = '"';
            else if (**json == '\\') buf[len++] = '\\';
            else if (**json == '/') buf[len++] = '/';
            else if (**json == 'u') {
                (*json)++;
                char hex[5] = {0};
                for (int i = 0; i < 4; i++) hex[i] = *(*json)++;
                int code = (int)strtol(hex, NULL, 16);
                if (code < 0x80) buf[len++] = (char)code;
                else if (code < 0x800) {
                    buf[len++] = (char)(0xC0 | (code >> 6));
                    buf[len++] = (char)(0x80 | (code & 0x3F));
                } else {
                    buf[len++] = (char)(0xE0 | (code >> 12));
                    buf[len++] = (char)(0x80 | ((code >> 6) & 0x3F));
                    buf[len++] = (char)(0x80 | (code & 0x3F));
                }
            }
        } else {
            buf[len++] = *(*json)++;
        }
        if (len >= 8191) break;
    }
    if (**json != '"') return NULL;
    (*json)++;
    JsonValue *v = calloc(1, sizeof(JsonValue));
    v->type = JSON_STRING;
    v->s = strndup(buf, len);
    return v;
}

JsonValue *json_parse_number(const char **json) {
    char buf[64];
    int len = 0;
    bool decimal = false, exponent = false;
    if (**json == '-') buf[len++] = *(*json)++;
    while (**json && (isdigit(**json) || **json == '.' || **json == 'e' || **json == 'E')) {
        if (**json == '.') decimal = true;
        if (**json == 'e' || **json == 'E') exponent = true;
        buf[len++] = *(*json)++;
    }
    buf[len] = 0;
    JsonValue *v = calloc(1, sizeof(JsonValue));
    v->type = JSON_NUMBER;
    v->n = strtod(buf, NULL);
    v->has_decimal = decimal;
    v->has_exponent = exponent;
    return v;
}

JsonValue *json_parse_value(const char **json) {
    skip_whitespace(json);
    if (**json == '"') return json_parse_string(json);
    if (**json == '{') return json_parse_object(json);
    if (**json == '[') return json_parse_array(json);
    if (**json == 't') {
        if (strncmp(*json, "true", 4) == 0) {
            *json += 4;
            JsonValue *v = calloc(1, sizeof(JsonValue));
            v->type = JSON_BOOLEAN; v->b = true; return v;
        }
        return NULL;
    }
    if (**json == 'f') {
        if (strncmp(*json, "false", 5) == 0) {
            *json += 5;
            JsonValue *v = calloc(1, sizeof(JsonValue));
            v->type = JSON_BOOLEAN; v->b = false; return v;
        }
        return NULL;
    }
    if (**json == 'n') {
        if (strncmp(*json, "null", 4) == 0) {
            *json += 4;
            JsonValue *v = calloc(1, sizeof(JsonValue));
            v->type = JSON_NULL; return v;
        }
        return NULL;
    }
    if (isdigit(**json) || **json == '-') return json_parse_number(json);
    return NULL;
}

JsonValue *json_parse_array(const char **json) {
    (*json)++;
    JsonValue *v = calloc(1, sizeof(JsonValue));
    v->type = JSON_ARRAY;
    skip_whitespace(json);
    if (**json == ']') { (*json)++; return v; }
    while (1) {
        JsonValue *el = json_parse_value(json);
        if (!el) return NULL;
        v->array.elements = realloc(v->array.elements, sizeof(JsonValue *) * (v->array.count + 1));
        v->array.elements[v->array.count++] = el;
        skip_whitespace(json);
        if (**json == ']') { (*json)++; break; }
        if (**json != ',') return NULL;
        (*json)++;
        skip_whitespace(json);
    }
    return v;
}

JsonValue *json_parse_object(const char **json) {
    (*json)++;
    JsonValue *v = calloc(1, sizeof(JsonValue));
    v->type = JSON_OBJECT;
    skip_whitespace(json);
    if (**json == '}') { (*json)++; return v; }
    while (1) {
        JsonValue *key_v = json_parse_string(json);
        if (!key_v) return NULL;
        skip_whitespace(json);
        if (**json != ':') { json_free(key_v); return NULL; }
        (*json)++;
        JsonValue *val_v = json_parse_value(json);
        if (!val_v) { json_free(key_v); return NULL; }
        v->object.keys = realloc(v->object.keys, sizeof(char *) * (v->object.count + 1));
        v->object.values = realloc(v->object.values, sizeof(JsonValue *) * (v->object.count + 1));
        v->object.keys[v->object.count] = key_v->s;
        v->object.values[v->object.count] = val_v;
        free(key_v);
        v->object.count++;
        skip_whitespace(json);
        if (**json == '}') { (*json)++; break; }
        if (**json != ',') return NULL;
        (*json)++;
        skip_whitespace(json);
    }
    return v;
}

void print_json_string(const char *s) {
    printf("\"");
    for (const char *p = s; *p; p++) {
        if (*p == '"') printf("\\\"");
        else if (*p == '\\') printf("\\\\");
        else if (*p == '\n') printf("\\n");
        else if (*p == '\r') printf("\\r");
        else if (*p == '\t') printf("\\t");
        else printf("%c", *p);
    }
    printf("\"");
}

void print_json_value(JsonValue *v) {
    if (!v) { printf("null"); return; }
    if (v->type == JSON_STRING) print_json_string(v->s);
    else if (v->type == JSON_NUMBER) {
        if (v->has_decimal || v->has_exponent) printf("%g", v->n);
        else printf("%.0f", v->n);
    } else if (v->type == JSON_BOOLEAN) printf("%s", v->b ? "true" : "false");
    else if (v->type == JSON_NULL) printf("null");
    else if (v->type == JSON_ARRAY) {
        printf("[");
        for (int i = 0; i < v->array.count; i++) {
            print_json_value(v->array.elements[i]);
            if (i < v->array.count - 1) printf(",");
        }
        printf("]");
    } else if (v->type == JSON_OBJECT) {
        printf("{");
        for (int i = 0; i < v->object.count; i++) {
            print_json_string(v->object.keys[i]);
            printf(":");
            print_json_value(v->object.values[i]);
            if (i < v->object.count - 1) printf(",");
        }
        printf("}");
    }
}

JsonValue *get_obj_member(JsonValue *obj, const char *key) {
    if (!obj || obj->type != JSON_OBJECT) return NULL;
    for (int i = 0; i < obj->object.count; i++) {
        if (strcmp(obj->object.keys[i], key) == 0) return obj->object.values[i];
    }
    return NULL;
}

typedef struct {
    char *k;
    char *v;
} KVEntry;

KVEntry *kv_store = NULL;
int kv_count = 0;
int initialized = 0;

void print_error(JsonValue *id, int code, const char *msg) {
    printf("{\"jsonrpc\":\"2.0\",");
    if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
    printf(",\"error\":{\"code\":%d,\"message\":\"%s\"}}\n", code, msg);
}

int compare_kv(const void *a, const void *b) {
    return strcmp(((KVEntry *)a)->k, ((KVEntry *)b)->k);
}

int count_words(const char *s) {
    int words = 0, in_word = 0;
    while (*s) {
        if (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') in_word = 0;
        else {
            if (!in_word) words++;
            in_word = 1;
        }
        s++;
    }
    return words;
}

int count_codepoints(const char *s) {
    int count = 0;
    while (*s) {
        if ((*s & 0xC0) != 0x80) count++;
        s++;
    }
    return count;
}

void handle_request(JsonValue *req) {
    JsonValue *id = get_obj_member(req, "id");
    JsonValue *method_v = get_obj_member(req, "method");
    if (!method_v || method_v->type != JSON_STRING) {
        print_error(id, -32600, "Invalid Request");
        return;
    }
    const char *method = method_v->s;
    JsonValue *params = get_obj_member(req, "params");
    if (params && params->type != JSON_OBJECT) {
        print_error(id, -32602, "Invalid params");
        return;
    }

    if (strcmp(method, "initialize") == 0) {
        if (initialized) { print_error(id, -32600, "Already initialized"); return; }
        if (!params || !get_obj_member(params, "protocolVersion")) {
            print_error(id, -32602, "Invalid params");
            return;
        }
        JsonValue *pv = get_obj_member(params, "protocolVersion");
        if (pv->type != JSON_STRING) { print_error(id, -32602, "Invalid params"); return; }
        initialized = 1;
        const char *version = pv->s;
        if (strcmp(version, "2025-06-18") != 0 && strcmp(version, "2025-03-26") != 0 && strcmp(version, "2024-11-05") != 0) {
            version = "2025-06-18";
        }
        printf("{\"jsonrpc\":\"2.0\",");
        if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
        printf(",\"result\":{\"protocolVersion\":\"%s\",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}\n", version);
        return;
    } else if (strcmp(method, "ping") == 0) {
        printf("{\"jsonrpc\":\"2.0\",");
        if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
        printf(",\"result\":{}}\n");
        return;
