            "{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}}",
            "{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}}",
            "{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}}",
            "{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}}",
            "{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}"
        };
        for (int i = 0; i < 5; i++) {
            printf("%s%s", tools[i], i < 4 ? "," : "");
        }
        printf("]}}\n");
        return;
    } else if (strcmp(method, "tools/call") == 0) {
        if (!initialized) { print_error(id, -32002, "Server not initialized"); return; }
        if (!params) { print_error(id, -32602, "Invalid params"); return; }
        JsonValue *name_v = get_obj_member(params, "name");
        if (!name_v || name_v->type != JSON_STRING) { print_error(id, -32602, "Invalid params"); return; }
        const char *name = name_v->s;
        JsonValue *args = get_obj_member(params, "arguments");
        if (args && args->type != JSON_OBJECT) {
            printf("{\"jsonrpc\":\"2.0\",");
            if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
            printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"arguments must be an object\"}],\"isError\":true}}\n");
            return;
        }
        if (!args) args = (JsonValue *){.type = JSON_OBJECT, .object = {NULL, NULL, 0}};

        if (strcmp(name, "kv_set") == 0) {
            for (int i = 0; i < args->object.count; i++) {
