                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"argument key must be a string\"}],\"isError\":true}}\n");
                return;
            }
            if (strlen(key_v->s) < 1) {
                printf("{\"jsonrpc\":\"2.0\",");
                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"argument key must not be empty\"}],\"isError\":true}}\n");
                return;
            }
            JsonValue *val_v = get_obj_member(args, "value");
