                printf("{\"jsonrpc\":\"2.0\",");
                if (id) { printf("\"id\":"); print_json_value(id); } else printf("\"id\":null");
                printf(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"missing required argument: value\"}],\"isError\":true}}\n");
                return;
            }
            if (val_v->type != JSON_STRING) {
