def quote_string(text):
    res = ['"']
    for char in text:
        if char == '\\': res.append('\\\\')
        elif char == '"': res.append('\\"')
        elif char == '\n': res.append('\\n')
        elif char == '\t': res.append('\\t')
        elif ord(char) < 0x20 or 0x7F <= ord(char) <= 0x9F:
            res.append(f'\\u{ord(char):04x}')
        else:
            res.append(char)
    res.append('"')
    return "".join(res)

def decode_windows_1252(data):
    mapping = {
        0x80: '\u20AC', 0x81: '\u0081', 0x82: '\u201A', 0x83: '\u0192',
        0x84: '\u201E', 0x85: '\u2026', 0x86: '\u2020', 0x87: '\u2021',
        0x88: '\u02C6', 0x89: '\u2030', 0x8A: '\u0160', 0x8B: '\u2039',
        0x8C: '\u0152', 0x8D: '\u008D', 0x8E: '\u017D', 0x8F: '\u008F',
        0x90: '\u0090', 0x91: '\u2018', 0x92: '\u2019', 0x93: '\u201C',
        0x94: '\u201D', 0x95: '\u2022', 0x96: '\u2013', 0x97: '\u2014',
        0x98: '\u02DC', 0x99: '\u2122', 0x9A: '\u0161', 0x9B: '\u203A',
        0x9C: '\u0153', 0x9D: '\u009D', 0x9E: '\u017E', 0x9F: '\u0178',
    }
    return "".join(mapping.get(b, chr(b)) for b in data)

def decode_charset(data, charset):
    charset = charset.lower()
    if charset == 'us-ascii': return data.decode('ascii', errors='replace')
    if charset == 'utf-8': return data.decode('utf-8', errors='replace')
    if charset == 'iso-8859-1': return data.decode('iso-8859-1', errors='replace')
    if charset == 'windows-1252': return decode_windows_1252(data)
    return data.decode('ascii', errors='replace')

def decode_rfc2047(text):
    pattern = re.compile(r'=\?([^? ]+)\?([BqQ])\?([^? ]+)?=')
    res = []
    i = 0
    while i < len(text):
        match = pattern.search(text, i)
        if not match:
            res.append(text[i:])
            break
        res.append(text[i:match.start()])

        charset_full = match.group(1)
        charset = charset_full.split('*')[0]
        encoding = match.group(2).upper()
        encoded_text = match.group(3) or ""

        def get_bytes(t, enc):
            if enc == 'B':
                try: return base64.b64decode(t)
                except: return b''
            elif enc == 'Q':
                out = bytearray()
                j = 0
                while j < len(t):
                    if t[j] == '_': out.append(0x20); j += 1
                    elif t[j] == '=' and j+2 < len(t) and all(c in '0123456789abcdefABCDEF' for c in t[j+1:j+3]):
                        out.append(int(t[j+1:j+3], 16)); j += 3
                    else: out.append(ord(t[j])); j += 1
                return bytes(out)
            return b''

        word_bytes = get_bytes(encoded_text, encoding)
        word_charset = charset

        # Check for adjacent words with same charset
        j = match.end()
        run_bytes = word_bytes
        while True:
            # Only spaces and tabs allowed between
            ws_match = re.match(r'^[ \t]*', text[j:])
            if not ws_match: break
            j += ws_match.end()
            next_match = pattern.match(text, j)
            if not next_match: break

            next_charset_full = next_match.group(1)
            next_charset = next_charset_full.split('*')[0]
            if next_charset.lower() != word_charset.lower(): break

            next_encoding = next_match.group(2).upper()
            next_encoded_text = next_match.group(3) or ""
            run_bytes += get_bytes(next_encoded_text, next_encoding)
            j = next_match.end()

        res.append(decode_charset(run_bytes, word_charset))
        i = j
    return "".join(res)

def parse_params(param_str):
    params = {}
    if not param_str: return params
    # Split by ; but ignore ; inside quoted strings
    parts = []
    current = []
    in_quote = False
    for char in param_str:
        if char == '"': in_quote = not in_quote
        if char == ';' and not in_quote:
            parts.append("".join(current).strip())
            current = []
        else:
            current.append(char)
    parts.append("".join(current).strip())

    for p in parts:
        if '=' not in p: continue
        name, val = p.split('=', 1)
        name = name.strip().lower()
        val = val.strip()
        if val.startswith('"') and val.endswith('"'):
            val = val[1:-1]
            # Handle \x in quoted strings
            res = []
            k = 0
            while k < len(val):
                if val[k] == '\\' and k+1 < len(val):
                    res.append(val[k+1])
                    k += 2
                else:
                    res.append(val[k])
                    k += 1
            val = "".join(res)
        params[name] = val
    return params

def decode_rfc2231(params, attr_name):
    # RFC 2231 form: a*=... or a*0, a*1...
    # Check for a*=
    start_key = attr_name + '*='
    if start_key in params:
        val = params[start_key]
        # charset'lang'value
        parts = val.split("'", 2)
        if len(parts) >= 2:
            charset = parts[0]
            rest = parts[1]
            if "'" in rest:
                _, value = rest.split("'", 1)
            else:
                value = rest
        else:
            charset, value = 'us-ascii', val

        # Collect segments a*0, a*1...
        segments = {}
        for k, v in params.items():
            if k.startswith(attr_name + '*') and k != start_key:
                num_part = k[len(attr_name)+1:]
                if num_part.isdigit():
                    segments[int(num_part)] = v

        # Check if any segment is percent-encoded (ends with *)
        is_percent = False
        for k, v in params.items():
            if k.startswith(attr_name + '*') and k != start_key and k.endswith('*'):
                is_percent = True; break

        # a* is always percent-encoded
        is_percent = True 

        all_bytes = bytearray()
        # The first segment (a*=) is processed first
        # Then a*0, a*1... in numeric order

        def decode_segment(s):
            res = bytearray()
            k = 0
            while k < len(s):
                if s[k] == '%' and k+2 < len(s) and all(c in '0123456789abcdefABCDEF' for c in s[k+1:k+3]):
                    res.append(int(s[k+1:k+3], 16)); k += 3
                else: res.append(ord(s[k])); k += 1
            return res

        # The a*= segment is the a*0
        # Wait, if a*= exists, it is the first segment.
        # If a*0, a*1 exist, they are segments.
        # The prompt says "RFC 2231 form... is either one parameter a*=... or continuation segments a*0, a*1..."
        # This means they are mutually exclusive for a single attribute.

        # Re-evaluating: a*= is the only segment. a*0, a*1... are segments.
        # Let's just handle the a*= case:
        all_bytes = decode_segment(value)
        return decode_charset(all_bytes, charset)

    # Check for a*0, a*1...
    segments = {}
    for k, v in params.items():
        if k.startswith(attr_name + '*') and k != start_key:
            num_part = k[len(attr_name)+1:]
            if num_part.isdigit():
                segments[int(num_part)] = v

    if segments:
        # Find charset from segment 0
        s0 = segments.get(0, "")
        # If any segment ends with *, it's percent-encoded
        is_percent = any(k.endswith('*') for k in params if k.startswith(attr_name + '*') and k != start_key)

        if is_percent:
            # s0 starts with charset'lang'
            parts = s0.split("'", 2)
            if len(parts) >= 2:
                charset = parts[0]
                rest = parts[1]
                if "'" in rest: _, value = rest.split("'", 1)
                else: value = rest
            else:
                charset, value = 'us-ascii', s0

            def decode_segment(s):
                res = bytearray()
                k = 0
                while k < len(s):
                    if s[k] == '%' and k+2 < len(s) and all(c in '0123456789abcdefABCDEF' for c in s[k+1:k+3]):
                        res.append(int(s[k+1:k+3], 16)); k += 3
                    else: res.append(ord(s[k])); k += 1
                return res

            all_bytes = decode_segment(value)
            for i in range(1, len(segments) + 1):
                if i in segments: all_bytes += decode_segment(segments[i])
            return decode_charset(all_bytes, charset)
        else:
            # Literal segments
            all_text = "".join(segments[i] for i in sorted(segments.keys()))
            return all_text

    return None

