                content = line[:-1]
                i += 1
                while i < len(lines) and lines[i].rstrip(b' \t').endswith(b'='):
                    content += lines[i].rstrip(b' \t')[:-1]
                    i += 1
                if i < len(lines):
                    content += lines[i].rstrip(b' \t')

                # Decode =XY in content
                j = 0
                while j < len(content):
                    if content[j] == ord('=') and j+2 < len(content) and \
                       all(c in b'0123456789abcdefABCDEF' or c in b'abcdef' for c in content[j+1:j+3]):
                        try: res.append(int(content[j+1:j+3], 16))
                        except: res.append(ord('='))
                        j += 3
                    else:
                        res.append(content[j])
                        j += 1
                # Add the line break that was after the final line of the soft-break sequence
                if i < len(lines): res.append(ord('\n'))
            else:
                # Decode =XY in line
                j = 0
                while j < len(line):
                    if line[j] == ord('=') and j+2 < len(line) and \
                       all(c in b'0123456789abcdefABCDEF' or c in b'abcdef' for c in line[j+1:j+3]):
                        try: res.append(int(line[j+1:j+3], 16))
                        except: res.append(ord('='))
                        j += 3
                    else:
                        res.append(line[j])
                        j += 1
                if i < len(lines) - 1: res.append(ord('\n'))
            i += 1
        return bytes(res)
    return data

def parse_entity(data):
    # data is bytes
    # Find line breaks
    lines = []
    curr = bytearray()
    i = 0
    while i < len(data):
        if i+1 < len(data) and data[i:i+2] == b'\r\n':
            lines.append(bytes(curr)); curr = bytearray(); i += 2
        elif data[i] == ord('\n'):
            lines.append(bytes(curr)); curr = bytearray(); i += 1
        else:
            curr.append(data[i]); i += 1
    lines.append(bytes(curr))

    # Headers
    headers = {}
    idx = 0
    while idx < len(lines) and lines[idx] != b'':
        line = lines[idx]
        # Unfold
        while idx + 1 < len(lines) and (lines[idx+1].startswith(b' ') or lines[idx+1].startswith(b'\t')):
            line += b'\n' + lines[idx+1]
            idx += 1

        if b':' in line:
            name, val = line.split(b':', 1)
            name = name.decode('ascii').strip().lower()
            val = val.decode('ascii').strip()
            headers[name] = val
        idx += 1

    # Body starts after the empty line
    # The empty line is at lines[idx]
    body_start = 0
    if idx < len(lines):
        # The body starts after the empty line. The line break of the empty line is part of the delimiter.
        # We need to find the original byte offset.
        # Let's just join the remaining lines.
        body = b'\n'.join(lines[idx+1:])
        # But the prompt says "the line break that ends the last content line before a delimiter belongs to the delimiter"
        # This is for multipart. For a single entity, the body runs to the end.
    else:
        body = b''

    # Re-calculate body from original data to be precise
    # Find the first b'\r\n\r\n' or b'\n\n'
    first_empty = data.find(b'\r\n\r\n')
    if first_empty != -1:
        body = data[first_empty+4:]
    else:
        first_empty = data.find(b'\n\n')
        if first_empty != -1:
            body = data[first_empty+2:]
        else:
            body = b''

    return headers, body

def parse_multipart(headers, body):
    ct_val = headers.get('content-type', 'text/plain')
    params = parse_params(ct_val[ct_val.find('/')+1:]) # This is wrong
    # Correct param parsing
    ct_main = ct_val.split(';', 1)[0].strip().lower()
    ct_params = parse_params(ct_val[len(ct_main)+1:])

    boundary = ct_params.get('boundary')
    if not boundary: return None

    B = boundary.encode('ascii')
    delim = b'--' + B
    close_delim = delim + b'--'

    # Split body by delimiters
    parts = []
    # Find first delimiter
    start = body.find(delim)
    if start == -1: return None

    # Remove the line break before the delimiter
    if start > 0 and body[start-1] == ord('\n'):
        start -= 1
    elif start > 1 and body[start-2:start] == b'\r\n':
        start -= 2

    curr = start + len(delim)
    # The delimiter may be followed by spaces/tabs
    while curr < len(body) and (body[curr] == ord(' ') or body[curr] == ord('\t')):
        curr += 1
    if curr < len(body) and body[curr] == ord('\n'):
        curr += 1
    elif curr < len(body) and curr+1 < len(body) and body[curr:curr+2] == b'\r\n':
        curr += 2

    while True:
        # Find next delimiter
        next_delim = body.find(delim, curr)
        if next_delim == -1: break

        # Check if it's a close delimiter
        if body[next_delim+len(delim):next_delim+len(delim)+2] == b'--':
            # It's a close delimiter
            part_body = body[curr:next_delim]
            # Remove the line break before the delimiter
            if part_body.endswith(b'\n'):
                if part_body.endswith(b'\r\n'): part_body = part_body[:-2]
                else: part_body = part_body[:-1]
            parts.append(part_body)
            break
        else:
            # It's a regular delimiter
            part_body = body[curr:next_delim]
            if part_body.endswith(b'\n'):
                if part_body.endswith(b'\r\n'): part_body = part_body[:-2]
                else: part_body = part_body[:-1]
            parts.append(part_body)

            # Move curr to after this delimiter
            curr = next_delim + len(delim)
            while curr < len(body) and (body[curr] == ord(' ') or body[curr] == ord('\t')):
                curr += 1
            if curr < len(body) and body[curr] == ord('\n'):
                curr += 1
            elif curr < len(body) and curr+1 < len(body) and body[curr:curr+2] == b'\r\n':
                curr += 2

    return parts

def process_entity(headers, body, depth=0):
    ct_main = headers.get('content-type', 'text/plain').split(';', 1)[0].strip().lower()
    ct_params = parse_params(headers.get('content-type', 'text/plain').split(';', 1)[1] if ';' in headers.get('content-type', 'text/plain') else "")

    cte = headers.get('content-transfer-encoding', '7bit').lower()
    disp_val = headers.get('content-disposition', '')
    disp_main = disp_val.split(';', 1)[0].strip().lower() if disp_val else ''
    disp_params = parse_params(disp_val.split(';', 1)[1] if ';' in disp_val else "")

    if ct_main.startswith('multipart/'):
        subtype = ct_main.split('/', 1)[1]
        parts_data = parse_multipart(headers, body)
        print(f'{"  " * depth}multipart/{subtype} parts={len(parts_data) if parts_data else 0}')
        if parts_data:
            for p_body in parts_data:
                p_headers, p_body_content = parse_entity(p_body)
                process_entity(p_headers, p_body_content, depth + 1)
    elif ct_main.startswith('text/') and disp_main != 'attachment':
        subtype = ct_main.split('/', 1)[1]
        charset = ct_params.get('charset', 'us-ascii').lower()
        decoded_bytes = decode_cte_fixed(body, cte)
        text = decode_charset(decoded_bytes, charset).replace('\r\n', '\n').replace('\r', '\n')
        print(f'{"  " * depth}text/{subtype} charset={charset} cte={cte} chars={len(text)}')
        print(f'{"  " * (depth+1)}{quote_string(text)}')
    else:
        subtype = ct_main.split('/', 1)[1] if '/' in ct_main else 'plain'
        # Filename logic
        name = decode_rfc2231(disp_params, 'filename')
        if not name: name = decode_rfc2047(disp_params.get('filename', '')) if 'filename' in disp_params else None
        if not name: name = decode_rfc2231(ct_params, 'name')
        if not name: name = decode_rfc2047(ct_params.get('name', '')) if 'name' in ct_params else None

        decoded_bytes = decode_cte_fixed(body, cte)
        crc = zlib.crc32(decoded_bytes) & 0xFFFFFFFF
        disp = disp_main if disp_main in ['inline', 'attachment'] else '-'
        name_str = quote_string(name) if name else '-'
        print(f'{"  " * depth}{ct_main} cte={cte} disposition={disp} name={name_str} size={len(decoded_bytes)} crc32={crc:08x}')

def main():
    if len(sys.argv) < 2: return
    directory = sys.argv[1]
    files = sorted([f for f in os.listdir(directory) if f.endswith('.eml')])

    for filename in files:
        with open(os.path.join(directory, filename), 'rb') as f:
            data = f.read()

        headers, body = parse_entity(data)
        print(f'== {filename}')
        print(f'From: {quote_string(decode_rfc2047(headers.get("from", "-")) if "from" in headers else "-")}')
        print(f'Subject: {quote_string(decode_rfc2047(headers.get("subject", "-")) if "subject" in headers else "-")}')
        process_entity(headers, body)
        print()

if __name__ == '__main__':
    main()

import os
import sys
import re
import base64
import zlib

def quote_string(text):
    res = ['"']
    for char in text:
        if char == '\\': res.append('\\\\')
        elif char == '"': res.append('\\"')
        elif char == '\n': res.append('\\n')
        elif char == '\t': res.append('\\t')
        elif ord(char) < 0x20 or 0x7F <= ord(char) <= 0x9F:
            res.append(f'\\u{ord(char):04x}')
        else:
            res.append(char)
    res.append('"')
    return "".join(res)

def decode_windows_1252(data):
    mapping = {
        0x80: '\u20AC', 0x81: '\u0081', 0x82: '\u201A', 0x83: '\u0192',
        0x84: '\u201E', 0x85: '\u2026', 0x86: '\u2020', 0x87: '\u2021',
        0x88: '\u02C6', 0x89: '\u2030', 0x8A: '\u0160', 0x8B: '\u2039',
        0x8C: '\u0152', 0x8D: '\u008D', 0x8E: '\u017D', 0x8F: '\u008F',
        0x90: '\u0090', 0x91: '\u2018', 0x92: '\u2019', 0x93: '\u201C',
        0x94: '\u201D', 0x95: '\u2022', 0x96: '\u2013', 0x97: '\u2014',
        0x98: '\u02DC', 0x99: '\u2122', 0x9A: '\u0161', 0x9B: '\u203A',
        0x9C: '\u0153', 0x9D: '\u009D', 0x9E: '\u017E', 0x9F: '\u0178',
    }
    return "".join(mapping.get(b, chr(b)) for b in data)

def decode_charset(data, charset):
    charset = charset.lower()
    if charset == 'us-ascii': return data.decode('ascii', errors='replace')
    if charset == 'utf-8': return data.decode('utf-8', errors='replace')
    if charset == 'iso-8859-1': return data.decode('iso-8859-1', errors='replace')
    if charset == 'windows-1252': return decode_windows_1252(data)
    return data.decode('ascii', errors='replace')

def decode_rfc2047_word(encoded_text, encoding):
    if encoding.upper() == 'B':
        try: return base64.b64decode(encoded_text)
        except: return b''
    elif encoding.upper() == 'Q':
        out = bytearray()
        j = 0
        while j < len(encoded_text):
            if encoded_text[j] == '_': out.append(0x20); j += 1
            elif encoded_text[j] == '=' and j+2 < len(encoded_text) and all(c in '0123456789abcdefABCDEF' for c in encoded_text[j+1:j+3]):
                out.append(int(encoded_text[j+1:j+3], 16)); j += 3
            else: out.append(ord(encoded_text[j])); j += 1
        return bytes(out)
    return b''

def decode_rfc2047(text):
    if not text: return ""
    pattern = re.compile(r'=\?([^? ]+)\?([BqQ])\?([^? ]*)\?=')
    res = []
    i = 0
    while i < len(text):
        match = pattern.search(text, i)
        if not match:
            res.append(text[i:])
            break
        res.append(text[i:match.start()])

        charset_full = match.group(1)
        charset = charset_full.split('*')[0]
        encoding = match.group(2)
        encoded_text = match.group(3)

        word_bytes = decode_rfc2047_word(encoded_text, encoding)

        j = match.end()
        run_bytes = word_bytes
        while True:
            ws_match = re.match(r'^[ \t]*', text[j:])
            if not ws_match: break
            j += ws_match.end()
            next_match = pattern.match(text, j)
            if not next_match: break

            next_charset_full = next_match.group(1)
            next_charset = next_charset_full.split('*')[0]
            if next_charset.lower() != charset.lower(): break

            next_encoding = next_match.group(2)
            next_encoded_text = next_match.group(3)
            run_bytes += decode_rfc2047_word(next_encoded_text, next_encoding)
            j = next_match.end()

        res.append(decode_charset(run_bytes, charset))
        i = j
    return "".join(res)

def parse_params(param_str):
    params = {}
    if not param_str: return params
    i = 0
    while i < len(param_str):
        while i < len(param_str) and param_str[i] in ' \t': i += 1
        if i >= len(param_str): break
        eq_idx = param_str.find('=', i)
        if eq_idx == -1: break
        name = param_str[i:eq_idx].strip().lower()
        i = eq_idx + 1
        while i < len(param_str) and param_str[i] in ' \t': i += 1
        if i < len(param_str) and param_str[i] == '"':
            val = []
            i += 1
            while i < len(param_str):
                if param_str[i] == '\\' and i+1 < len(param_str):
                    val.append(param_str[i+1]); i += 2
                elif param_str[i] == '"':
                    i += 1; break
                else:
                    val.append(param_str[i]); i += 1
            params[name] = "".join(val)
            while i < len(param_str) and param_str[i] not in '; \t': i += 1
        else:
            start = i
            while i < len(param_str) and param_str[i] not in '; \t': i += 1
            params[name] = param_str[start:i]
        if i < len(param_str) and param_str[i] == ';': i += 1
    return params

def decode_rfc2231(params, attr_name):
    # RFC 2231 logic
    segments = []
    if attr_name + '*=' in params:
        segments = [(attr_name + '*', params[attr_name + '='])]
    elif attr_name + '*0' in params:
        idx = 0
        while True:
            key = f"{attr_name}*{idx}"
            if key not in params: break
            segments.append((key, params[key]))
            idx += 1

    if not segments: return None

    is_percent = any(k.endswith('*') for k, v in segments) or (segments[0][0] == attr_name + '*')
    if is_percent:
        first_val = segments[0][1]
        parts = first_val.split("'", 2)
        charset = parts[0]
        if len(parts) >= 2:
            rest = parts[1]
            if "'" in rest: _, value = rest.split("'", 1)
            else: value = rest
        else: value = ""

        all_bytes = bytearray()
        def decode_perc(s):
            res = bytearray()
            k = 0
            while k < len(s):
                if s[k] == '%' and k+2 < len(s) and all(c in '0123456789abcdefABCDEF' for c in s[k+1:k+3]):
                    res.append(int(s[k+1:k+3], 16)); k += 3
                else: res.append(ord(s[k])); k += 1
            return res

        all_bytes += decode_perc(value)
        for i in range(1, len(segments)):
            all_bytes += decode_perc(segments[i][1])
        return decode_charset(all_bytes, charset)
    else:
        # Literal
        res = ""
        for k, v in segments:
            if v.startswith('"') and v.endswith('"'): res += v[1:-1]
            else: res += v
        return res

def decode_cte(data, encoding):
    encoding = encoding.lower()
    if encoding == 'base64':
        b64_data = bytearray()
        for b in data:
            if b in b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/':
                b64_data.append(b)
            elif b == ord('='): break
        try: return base64.b64decode(b64_data)
        except: return b''
    elif encoding == 'quoted-printable':
        lines = []
        curr = bytearray()
        i = 0
        while i < len(data):
            if i+1 < len(data) and data[i:i+2] == b'\r\n':
                lines.append(bytes(curr)); curr = bytearray(); i += 2
            elif data[i] == ord('\n'):
                lines.append(bytes(curr)); curr = bytearray(); i += 1
            else:
                curr.append(data[i]); i += 1
        lines.append(bytes(curr))

        res = bytearray()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip(b' \t')
            if line.endswith(b'='):
                content = line[:-1]
                i += 1
                while i < len(lines) and lines[i].rstrip(b' \t').endswith(b'='):
                    content += lines[i].rstrip(b' \t')[:-1]
                    i += 1
                if i < len(lines):
                    content += lines[i].rstrip(b' \t')

                j = 0
                while j < len(content):
                    if content[j] == ord('=') and j+2 < len(content) and \
                       all(c in b'0123456789abcdefABCDEF' for c in content[j+1:j+3]):
                        res.append(int(content[j+1:j+3], 16)); j += 3
                    else: res.append(content[j]); j += 1
                if i < len(lines): res.append(ord('\n'))
            else:
                j = 0
                while j < len(line):
                    if line[j] == ord('=') and j+2 < len(line) and \
                       all(c in b'0123456789abcdefABCDEF' for c in line[j+1:j+3]):
                        res.append(int(line[j+1:j+3], 16)); j += 3
                    else: res.append(line[j]); j += 1
                if i < len(lines) - 1: res.append(ord('\n'))
            i += 1
        return bytes(res)
    return data

def parse_entity(data):
    # Determine line break
    if b'\r\n' in data: lb = b'\r\n'
    elif b'\n' in data: lb = b'\n'
    else: lb = b'\n'

    lines = data.split(lb)
    headers = {}
    idx = 0
    while idx < len(lines) and lines[idx] != b'':
        line = lines[idx]
        while idx + 1 < len(lines) and (lines[idx+1].startswith(b' ') or lines[idx+1].startswith(b'\t')):
            line += lines[idx+1] # Remove line break, keep space/tab
            idx += 1
        if b':' in line:
            name, val = line.split(b':', 1)
            headers[name.decode('ascii').strip().lower()] = val.decode('ascii').strip()
        idx += 1

    # Body is everything after the first empty line
    # Find the offset of the empty line in original data
    offset = 0
    for i in range(idx + 1):
        if i < len(lines):
            offset += len(lines[i]) + len(lb)

    # The body starts after the empty line's line break
    # But we need to be careful about the very first empty line
    # Let's use a simpler way: find the first lb + lb
    first_empty = data.find(lb + lb)
    if first_empty != -1:
        body = data[first_empty + len(lb)*2:]
    else:
        # Only one line break?
        first_empty = data.find(lb)
        if first_empty != -1:
            body = data[first_empty + len(lb):]
        else:
            body = b''

    # Correct body extraction:
    # The headers end at the first empty line.
    # Let's re-calculate the body offset.
    current_pos = 0
    for i in range(len(lines)):
        if i > 0: current_pos += len(lb)
        if i == idx:
            body = data[current_pos + len(lb):]
            break
        current_pos += len(lines[i])

    return headers, body

def process_entity(headers, body, depth=0):
    ct_val = headers.get('content-type', 'text/plain')
    ct_main = ct_val.split(';', 1)[0].strip().lower()
    ct_params = parse_params(ct_val.split(';', 1)[1] if ';' in ct_val else "")

    cte = headers.get('content-transfer-encoding', '7bit').lower()
    disp_val = headers.get('content-disposition', '')
    disp_main = disp_val.split(';', 1)[0].strip().lower() if disp_val else ''
    disp_params = parse_params(disp_val.split(';', 1)[1] if ';' in disp_val else "")

    if ct_main.startswith('multipart/'):
        subtype = ct_main.split('/', 1)[1]
        boundary = ct_params.get('boundary', '')
        if not boundary: return
        B = boundary.encode('ascii')
        delim = b'--' + B
        close_delim = delim + b'--'

        # Split body by delimiters
        parts_data = []
        start = body.find(delim)
        if start == -1: return

        # Find the end of the first delimiter line
        line_end = body.find(b'\n', start)
        if line_end == -1: line_end = len(body)
        else:
            # Delimiter line may have spaces/tabs
            curr = start + len(delim)
            while curr < len(body) and (body[curr] == ord(' ') or body[curr] == ord('\t')): curr += 1
            if curr < len(body) and body[curr] == ord('\n'): line_end = curr
            elif curr < len(body) and body[curr:curr+2] == b'\r\n': line_end = curr
            else: line_end = len(body) # Not a valid delimiter

        curr_pos = line_end + 1 if line_end < len(body) else line_end

        while True:
            next_delim = body.find(delim, curr_pos)
            if next_delim == -1: break

            # Check if it's a close delimiter
            if body[next_delim+len(delim):next_delim+len(delim)+2] == b'--':
                part_body = body[curr_pos:next_delim]
                if part_body.endswith(b'\n'):
                    if part_body.endswith(b'\r\n'): part_body = part_body[:-2]
                    else: part_body = part_body[:-1]
                parts_data.append(part_body)
                break
            else:
                part_body = body[curr_pos:next_delim]
                if part_body.endswith(b'\n'):
                    if part_body.endswith(b'\r\n'): part_body = part_body[:-2]
                    else: part_body = part_body[:-1]
                parts_data.append(part_body)

                # Move curr_pos to after this delimiter line
                line_end_next = body.find(b'\n', next_delim)
                if line_end_next == -1: line_end_next = len(body)
                curr_pos = line_end_next + 1

        print(f'{"  " * depth}multipart/{subtype} parts={len(parts_data)}')
        for p_body in parts_data:
            p_headers, p_body_content = parse_entity(p_body)
            process_entity(p_headers, p_body_content, depth + 1)

    elif ct_main.startswith('text/') and disp_main != 'attachment':
        subtype = ct_main.split('/', 1)[1]
        charset = ct_params.get('charset', 'us-ascii').lower()
        decoded_bytes = decode_cte(body, cte)
        text = decode_charset(decoded_bytes, charset).replace('\r\n', '\n').replace('\r', '\n')
        print(f'{"  " * depth}text/{subtype} charset={charset} cte={cte} chars={len(text)}')
        print(f'{"  " * (depth+1)}{quote_string(text)}')
    else:
        subtype = ct_main.split('/', 1)[1] if '/' in ct_main else 'plain'
        name = decode_rfc2231(disp_params, 'filename')
        if not name: name = decode_rfc2047(disp_params.get('filename', '')) if 'filename' in disp_params else None
        if not name: name = decode_rfc2231(ct_params, 'name')
        if not name: name = decode_rfc2047(ct_params.get('name', '')) if 'name' in ct_params else None

        decoded_bytes = decode_cte(body, cte)
        crc = zlib.crc32(decoded_bytes) & 0xFFFFFFFF
        disp = disp_main if disp_main in ['inline', 'attachment'] else '-'
        name_str = quote_string(name) if name else '-'
        print(f'{"  " * depth}{ct_main} cte={cte} disposition={disp} name={name_str} size={len(decoded_bytes)} crc32={crc:08x}')

def main():
    if len(sys.argv) < 2: return
    directory = sys.argv[1]
