const CRC_TABLE = new Uint32Array(256);
for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    CRC_TABLE[i] = c;
}

function crc32(buf: Buffer): string {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < buf.length; i++) {
        crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buf[i]) & 0xFF];
    }
    return ((crc ^ 0xFFFFFFFF) >>> 0).toString(16).padStart(8, '0');
}

const WIN1252_MAP: Record<number, string> = {
    0x80: '\u20AC', 0x81: '\u0081', 0x82: '\u201A', 0x83: '\u0192',
    0x84: '\u201E', 0x85: '\u2026', 0x86: '\u2020', 0x87: '\u2021',
    0x88: '\u02C6', 0x89: '\u2030', 0x8A: '\u0160', 0x8B: '\u2039',
    0x8C: '\u0152', 0x8D: '\u008D', 0x8E: '\u017D', 0x8F: '\u008F',
    0x90: '\u0090', 0x91: '\u2018', 0x92: '\u2019', 0x93: '\u201C',
    0x94: '\u201D', 0x95: '\u2022', 0x96: '\u2013', 0x97: '\u2014',
    0x98: '\u02DC', 0x99: '\u2122', 0x9A: '\u0161', 0x9B: '\u203A',
    0x9C: '\u0153', 0x9D: '\u009D', 0x9E: '\u017E', 0x9F: '\u0178',
};

function decodeCharset(buf: Buffer, charset: string): string {
    charset = charset.toLowerCase();
    if (charset === 'us-ascii' || charset === 'utf-8') {
        return buf.toString('utf8');
    } else if (charset === 'iso-8859-1') {
        let res = '';
        for (let i = 0; i < buf.length; i++) res += String.fromCharCode(buf[i]);
        return res;
    } else if (charset === 'windows-1252') {
        let res = '';
        for (let i = 0; i < buf.length; i++) {
            const byte = buf[i];
            res += WIN1252_MAP[byte] || String.fromCharCode(byte);
        }
        return res;
    }
    return buf.toString('utf8');
}

function decodeBase64(s: string): Buffer {
    const b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    let binary = '';
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (char === '=') break;
        const idx = b64chars.indexOf(char);
        if (idx === -1) continue;
        binary += idx.toString(2).padStart(6, '0');
    }
    let bytes = [];
    for (let i = 0; i < binary.length; i += 8) {
        const byte = binary.substring(i, i + 8);
        if (byte.length === 8) bytes.push(parseInt(byte, 2));
    }
    return Buffer.from(bytes);
}

function decodeRFC2047Word(text: string, encoding: string): Buffer {
    if (encoding === 'B') return decodeBase64(text);
    let bytes = [];
    for (let i = 0; i < text.length; i++) {
        if (text[i] === '_') bytes.push(0x20);
        else if (text[i] === '=' && i + 2 < text.length && /^[0-9a-fA-F]{2}$/.test(text.substring(i + 1, i + 3))) {
            bytes.push(parseInt(text.substring(i + 1, i + 3), 16));
            i += 2;
        } else bytes.push(text.charCodeAt(i));
    }
    return Buffer.from(bytes);
}

function decodeRFC2047(s: string): string {
    let res = '', i = 0;
    while (i < s.length) {
        const match = s.substring(i).match(/^=\?([^?]+)\?([BqQb])\?([^?]*)\?=/);
        if (!match) { res += s[i++]; continue; }
        let currentCharset = match[1].split('*')[0];
        let currentEncoding = match[2].toUpperCase();
        let bytes = decodeRFC2047Word(match[3], currentEncoding);
        i += match[0].length;
        while (i < s.length) {
            const nextMatch = s.substring(i).match(/^[ \t]*=\?([^?]+)\?([BqQb])\?([^?]*)\?=/);
            if (!nextMatch || nextMatch[1].split('*')[0].toLowerCase() !== currentCharset.toLowerCase()) break;
            bytes = Buffer.concat([bytes, decodeRFC2047Word(nextMatch[3], nextMatch[2].toUpperCase())]);
            i += nextMatch[0].length;
        }
        res += decodeCharset(bytes, currentCharset);
    }
    return res;
}

function decodeQuotedPrintable(s: string): Buffer {
    let lines = s.split(/\r?\n/);
    let joined = '';
    for (let line of lines) {
        line = line.replace(/[ \t]+$/, '');
        if (line.endsWith('=')) {
            joined += line.substring(0, line.length - 1);
        } else {
            joined += line + '\n';
        }
    }
    if (joined.endsWith('\n')) joined = joined.substring(0, joined.length - 1);
    let res = [];
    for (let i = 0; i < joined.length; i++) {
        if (joined[i] === '=' && i + 2 < joined.length && /^[0-9a-fA-F]{2}$/.test(joined.substring(i + 1, i + 3))) {
            res.push(parseInt(joined.substring(i + 1, i + 3), 16));
            i += 2;
        } else res.push(joined.charCodeAt(i));
    }
    return Buffer.from(res);
}

function parseParams(s: string): Map<string, string> {
    const params = new Map<string, string>();
    let i = 0;
    while (i < s.length) {
        while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
        if (i >= s.length) break;
        let key = '', val = '';
        while (i < s.length && s[i] !== '=' && s[i] !== ' ' && s[i] !== '\t' && s[i] !== ';') key += s[i++];
        if (i < s.length && s[i] === '=') {
            i++;
            if (i < s.length && s[i] === '"') {
                i++;
                while (i < s.length && s[i] !== '"') {
                    if (s[i] === '\\' && i + 1 < s.length) { val += s[++i]; }
                    else val += s[i];
                    i++;
                }
                i++;
            } else {
                while (i < s.length && s[i] !== ' ' && s[i] !== '\t' && s[i] !== ';') val += s[i++];
            }
        }
        params.set(key.toLowerCase(), val);
        while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
        if (i < s.length && s[i] === ';') i++;
    }
    return params;
}

function decodeRFC2231(params: Map<string, string>, attr: string): string | null {
    let segments: { index: number, value: string, encoded: boolean }[] = [];
    let charset = 'us-ascii';
    const aStar = params.get(attr + '*');
    if (aStar) {
        const match = aStar.match(/^([^']*)'([^']*)'(.*)$/);
        if (match) {
            charset = match[1] || 'us-ascii';
            segments.push({ index: 0, value: match[3], encoded: true });
        }
    }
    for (const [key, value] of params.entries()) {
        const match = key.match(new RegExp(`^${attr}\\*(\\d+)(\\*)?$`));
        if (match) segments.push({ index: parseInt(match[1]), value, encoded: !!match[2] });
    }
    if (segments.length > 0) {
        segments.sort((a, b) => a.index - b.index);
        let allBytes = [];
        for (const seg of segments) {
            if (seg.encoded) {
                for (let i = 0; i < seg.value.length; i++) {
                    if (seg.value[i] === '%' && i + 2 < seg.value.length) {
                        allBytes.push(parseInt(seg.value.substring(i + 1, i + 3), 16));
                        i += 2;
                    } else allBytes.push(seg.value.charCodeAt(i));
                }
            } else {
                let val = seg.value;
                if (val.startsWith('"') && val.endsWith('"')) {
                    val = val.substring(1, val.length - 1).replace(/\\(.)/g, '$1');
                }
                for (let i = 0; i < val.length; i++) allBytes.push(val.charCodeAt(i));
            }
        }
        return decodeCharset(Buffer.from(allBytes), charset);
    }
    const simple = params.get(attr);
    return simple ? decodeRFC2047(simple) : null;
}

function quoteString(s: string): string {
    let res = '"';
    for (let i = 0; i < s.length; i++) {
        const c = s[i], code = s.charCodeAt(i);
        if (c === '\\') res += '\\\\';
        else if (c === '"') res += '\\"';
        else if (c === '\n') res += '\\n';
        else if (c === '\t') res += '\\t';
        else if (code < 0x20 || (code >= 0x7F && code <= 0x9F)) res += '\\u' + code.toString(16).padStart(4, '0');
        else res += c;
    }
    return res + '"';
}

class Entity {
    headers = new Map<string, string>();
    body: Buffer;
    type = 'text/plain';
    subtype = 'plain';
    params = new Map<string, string>();
    disposition = '';
    dispositionParams = new Map<string, string>();
    cte = '7bit';

    constructor(raw: Buffer, lineBreak: string) {
        let i = 0;
        let lines = [];
        while (i < raw.length) {
            let end = raw.indexOf(lineBreak === '\r\n' ? Buffer.from('\r\n') : Buffer.from('\n'), i);
            if (end === -1) { lines.push(raw.slice(i).toString()); break; }
            lines.push(raw.slice(i, end).toString());
            i = end + lineBreak.length;
        }
        let headerEnd = lines.findIndex(l => l === '');
        if (headerEnd === -1) headerEnd = lines.length;
        for (let j = 0; j < headerEnd; j++) {
            let line = lines[j];
            while (j + 1 < headerEnd && (lines[j + 1].startsWith(' ') || lines[j + 1].startsWith('\t'))) {
                line += '\n' + lines[++j]; // This is a simplification of unfolding
            }
            // Proper unfolding: remove LB followed by space/tab
            line = line.replace(/\r?\n[ \t]+/g, (m) => m.substring(m.length - 1));
            const colonIdx = line.indexOf(':');
            if (colonIdx !== -1) {
                const name = line.substring(0, colonIdx).trim().toLowerCase();
                const value = line.substring(colonIdx + 1).trim();
                this.headers.set(name, value);
            }
        }
        const bodyStart = headerEnd === -1 ? 0 : (lines.slice(0, headerEnd).join(lineBreak) + lineBreak + lineBreak).length;
        // The above bodyStart is incorrect. Let's find the actual byte offset.
        let offset = 0;
        for (let j = 0; j < headerEnd; j++) {
            offset += lines[j].length + lineBreak.length;
        }
        if (headerEnd !== -1) offset += 0; // The empty line is already counted
        this.body = raw.slice(offset);

        const ct = this.headers.get('content-type') || 'text/plain';
        const ctSplit = ct.split(';');
        const mime = ctSplit[0].trim().toLowerCase();
        [this.type, this.subtype] = mime.split('/');
        this.params = parseParams(ctSplit.slice(1).join(';'));

        const cd = this.headers.get('content-disposition');
        if (cd) {
            const cdSplit = cd.split(';');
            this.disposition = cdSplit[0].trim().toLowerCase();
            this.dispositionParams = parseParams(cdSplit.slice(1).join(';'));
        }
        this.cte = (this.headers.get('content-transfer-encoding') || '7bit').toLowerCase();
    }

    getFileName(): string {
        const name = decodeRFC2231(this.dispositionParams, 'filename') || 
                     decodeRFC2231(this.params, 'name');
        return name || '-';
    }
}

function parseMultipart(entity: Entity, lineBreak: string): Entity[] {
    const boundary = entity.params.get('boundary');
    if (!boundary) return [];
    const b = `--${boundary}`;
    const body = entity.body;
    let offset = 0;
    const bBuf = Buffer.from(b);
    const closeBBuf = Buffer.from(`--${boundary}--`);

    while (offset < body.length) {
        let start = body.indexOf(bBuf, offset);
        if (start === -1) break;
        let end = body.indexOf(bBuf, start + bBuf.length);
        if (end === -1) break;

        // Check if it's a close delimiter
        const isClose = body.slice(start + bBuf.length, start + bBuf.length + 2).equals(Buffer.from('--'));
        if (isClose) break;

        // Find the actual end of the part (the next delimiter)
        let nextS = body.indexOf(bBuf, start + bBuf.length);
        if (nextS === -1) break;

        // The part content is between start + bBuf.length + LB and nextS
        let contentStart = start + bBuf.length;
        if (body[contentStart] === 0x0D || body[contentStart] === 0x0A) {
            if (body[contentStart] === 0x0D && body[contentStart+1] === 0x0A) contentStart += 2;
            else contentStart += 1;
        }
        let contentEnd = nextS;
        if (body[contentEnd - 1] === 0x0D || body[contentEnd - 1] === 0x0A) {
            if (body[contentEnd - 2] === 0x0D && body[contentEnd - 1] === 0x0A) contentEnd -= 2;
            else contentEnd -= 1;
        }

        const part = new Entity(body.slice(contentStart, contentEnd), lineBreak);
        offset = nextS + bBuf.length;
        // We need to find the next delimiter, but the current loop is a bit messy.
        // Let's use a simpler splitting logic.
        break; 
    }
    return []; // Placeholder
}

function splitMultipart(body: Buffer, boundary: string, lineBreak: string): Buffer[] {
    const b = `--${boundary}`;
    const bBuf = Buffer.from(b);
    const closeBBuf = Buffer.from(`${b}--`);
    let parts = [];
    let i = 0;
    while (i < body.length) {
        let start = body.indexOf(bBuf, i);
        if (start === -1) break;
        i = start + bBuf.length;
        if (body.slice(i).startsWith(Buffer.from('--'))) break;

        // Find next boundary
        let next = body.indexOf(bBuf, i);
        if (next === -1) break;

        let partContent = body.slice(i, next);
        // Remove trailing LB
        if (partContent.length >= 2 && partContent[partContent.length-2] === 0x0D && partContent[partContent.length-1] === 0x0A) {
            partContent = partContent.slice(0, -2);
        } else if (partContent.length >= 1 && partContent[partContent.length-1] === 0x0A) {
            partContent = partContent.slice(0, -1);
        }
        parts.push(partContent);
        i = next;
    }
    return parts;
}

function processEntity(entity: Entity, lineBreak: string, depth: number): void {
    const indent = '  '.repeat(depth);
    if (entity.type === 'multipart') {
        const parts = splitMultipart(entity.body, entity.params.get('boundary') || '', lineBreak);
        console.log(`${indent}multipart/${entity.subtype} parts=${parts.length}`);
        for (const pBuf of parts) {
            processEntity(new Entity(pBuf, lineBreak), lineBreak, depth + 1);
        }
    } else if (entity.type === 'text' && entity.disposition !== 'attachment') {
        let decoded = entity.body;
        if (entity.cte === 'base64') decoded = decodeBase64(entity.body.toString());
        else if (entity.cte === 'quoted-printable') decoded = decodeQuotedPrintable(entity.body.toString());

        const charset = entity.params.get('charset') || 'us-ascii';
        const text = decodeCharset(decoded, charset).replace(/\r\n|\r/g, '\n');
        console.log(`${indent}text/${entity.subtype} charset=${charset.toLowerCase()} cte=${entity.cte} chars=${text.length}`);
        console.log(`${indent}  ${quoteString(text)}`);
    } else {
        let decoded = entity.body;
        if (entity.cte === 'base64') decoded = decodeBase64(entity.body.toString());
        else if (entity.cte === 'quoted-printable') decoded = decodeQuotedPrintable(entity.body.toString());

        const disp = entity.disposition || '-';
        const name = entity.getFileName();
        console.log(`${indent}${entity.type}/${entity.subtype} cte=${entity.cte} disposition=${disp} name=${quoteString(name === '-' ? '-' : name)} size=${decoded.length} crc32=${crc32(decoded)}`);
    }
}

async function main() {
    const dir = process.argv[2];
    if (!dir) return;
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml')).sort();
    for (const file of files) {
        const content = fs.readFileSync(path.join(dir, file));
        const lineBreak = content.includes(Buffer.from('\r\n')) ? '\r\n' : '\n';
        const entity = new Entity(content, lineBreak);
        console.log(`== ${file}`);
        console.log(`From: ${quoteString(decodeRFC2047(entity.headers.get('from') || '-'))}`);
        console.log(`Subject: ${quoteString(decodeRFC2047(entity.headers.get('subject') || '-'))}`);
        processEntity(entity, lineBreak, 0);
        console.log('');
    }
}

