function decodeBase64Strict(s: string): Buffer {
    const b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    let filtered = '';
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (char === '=') break;
        if (b64chars.indexOf(char) !== -1) filtered += char;
    }
    let binary = '';
    for (let i = 0; i < filtered.length; i++) {
        binary += b64chars.indexOf(filtered[i]).toString(2).padStart(6, '0');
    }
    const bytes = [];
    for (let i = 0; i + 8 <= binary.length; i += 8) {
        bytes.push(parseInt(binary.substring(i, i + 8), 2));
    }
    return Buffer.from(bytes);
