            bytes = Buffer.concat([bytes, decodeRFC2047Word(nextMatch[3], nextMatch[2].toUpperCase())]);
            i += nextMatch[0].length;
        }
        res += decodeCharset(bytes, currentCharset);
    }
    return res;
