function splitMultipart(body: Buffer, boundary: string, lineBreak: string): Buffer[] {
    const b = `--${boundary}`;
    const bBuf = Buffer.from(b);
    const lbBuf = Buffer.from(lineBreak);
    const lines: Buffer[] = [];
    let offset = 0;
    while (offset < body.length) {
        let end = body.indexOf(lbBuf, offset);
        if (end === -1) { lines.push(body.slice(offset)); break; }
        lines.push(body.slice(offset, end));
        offset = end + lbBuf.length;
    }

    const isDelimiter = (line: Buffer) => {
        if (!line.startsWith(bBuf)) return false;
        let i = bBuf.length;
        while (i < line.length && (line[i] === 0x20 || line[i] === 0x09)) i++;
        return i === line.length;
    };
    const isCloseDelimiter = (line: Buffer) => {
        const closeBBuf = Buffer.from(b + '--');
        if (!line.startsWith(closeBBuf)) return false;
        let i = closeBBuf.length;
        while (i < line.length && (line[i] === 0x20 || line[i] === 0x09)) i++;
        return i === line.length;
    };

    let firstDelim = -1;
    for (let i = 0; i < lines.length; i++) {
        if (isDelimiter(lines[i])) { firstDelim = i; break; }
    }
    if (firstDelim === -1) return [];

    let lastDelim = -1;
    for (let i = firstDelim + 1; i < lines.length; i++) {
        if (isCloseDelimiter(lines[i])) { lastDelim = i; break; }
    }
    if (lastDelim === -1) return [];

    const parts: Buffer[] = [];
    let currentPart: Buffer[] = [];
    for (let i = firstDelim + 1; i < lastDelim; i++) {
        if (isDelimiter(lines[i])) {
            parts.push(Buffer.concat(currentPart));
            currentPart = [];
        } else {
            currentPart.push(lines[i]);
            if (i + 1 < lastDelim) currentPart.push(lbBuf);
        }
    }
    if (currentPart.length > 0) parts.push(Buffer.concat(currentPart));

    // Remove trailing line break from each part
    return parts.map(p => {
        if (p.length >= lbBuf.length && p.slice(p.length - lbBuf.length).equals(lbBuf)) {
            return p.slice(0, p.length - lbBuf.length);
        }
        return p;
    });
