            buf_append_char(out, (char)(0x80 | ((cp >> 12) & 0x3F)));
            buf_append_char(out, (char)(0x80 | ((cp >> 6) & 0x3F)));
            buf_append_char(out, (char)(0x80 | (cp & 0x3F)));
        }
    }
    buf_free(&b); ubuf_free(&ubuf);
}

void print_quoted(UBuffer *ubuf) {
    printf("\"");
    for (size_t i = 0; i < ubuf->size; i++) {
        uint32_t cp = ubuf->data[i];
        if (cp == '\\') printf("\\\\");
        else if (cp == '"') printf("\\\"");
        else if (cp == '\n') printf("\\n");
        else if (cp == '\t') printf("\\t");
        else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) printf("\\u%04x", cp);
        else {
            if (cp < 0x80) printf("%c", (char)cp);
            else if (cp < 0x800) {
                printf("%c%c", (char)(0xC0 | (cp >> 6)), (char)(0x80 | (cp & 0x3F)));
            } else if (cp < 0x10000) {
                printf("%c%c%c", (char)(0xE0 | (cp >> 12)), (char)(0x80 | ((cp >> 6) & 0x3F)), (char)(0x80 | (cp & 0x3F)));
            } else {
                printf("%c%c%c%c", (char)(0xF0 | (cp >> 18)), (char)(0x80 | ((cp >> 12) & 0x3F)), (char)(0x80 | ((cp >> 6) & 0x3F)), (char)(0x80 | (cp & 0x3F)));
            }
        }
    }
    printf("\"\n");
}

char *get_header_value(Entity *e, const char *name) {
    for (int i = 0; i < e->header_count; i++) {
        if (strcasecmp(e->headers[i].key, name) == 0) return e->headers[i].value;
    }
    return NULL;
}

void decode_header_to_ubuf(const char *src, UBuffer *ubuf) {
    Buffer b; buf_init(&b);
    decode_rfc2047(src, &b);
    decode_bytes_to_unicode((unsigned char *)b.data, b.size, "us-ascii", ubuf);
    buf_free(&b);
}

void parse_content_type(const char *src, char *type, char *subtype, char *charset) {
    if (!src) {
        strcpy(type, "text");
        strcpy(subtype, "plain");
        strcpy(charset, "us-ascii");
        return;
    }
    const char *p = src;
    while (*p == ' ' || *p == '\t') p++;
    const char *type_start = p;
    while (*p && *p != '/' && *p != ' ' && *p != '\t' && *p != ';') p++;
    *p = 0;
    strcpy(type, type_start);
    for (int i = 0; type[i]; i++) type[i] = tolower(type[i]);
    if (*p == '/') {
        p++;
        while (*p == ' ' || *p == '\t') p++;
        const char *sub_start = p;
        while (*p && *p != ' ' && *p != '\t' && *p != ';') p++;
        if (*p) *p = 0;
        strcpy(subtype, sub_start);
        for (int i = 0; subtype[i]; i++) subtype[i] = tolower(subtype[i]);
    } else {
        subtype[0] = 0;
    }

    const char *search = src;
    while ((search = strcasestr(search, "; charset=")) || (search = strcasestr(search, ";charset="))) {
        search += (search[0] == ';' && search[1] == ' ') ? 9 : 8;
        while (*search == ' ' || *search == '\t') search++;
        if (*search == '"') {
            search++;
            const char *end = search;
            while (*end && *end != '"') end++;
            *end = 0;
            strcpy(charset, search);
            search = end + 1;
        } else {
            const char *end = search;
            while (*end && *end != ' ' && *end != '\t' && *end != ';') end++;
            *end = 0;
            strcpy(charset, search);
            search = end;
        }
        break;
    }
    if (!charset[0]) strcpy(charset, "us-ascii");
    for (int i = 0; charset[i]; i++) charset[i] = tolower(charset[i]);
}

void parse_content_disposition(const char *src, char *disp, char *filename) {
    if (!src) { disp[0] = 0; filename[0] = 0; return; }
    const char *p = src;
    while (*p == ' ' || *p == '\t') p++;
    const char *disp_start = p;
    while (*p && *p != ' ' && *p != '\t' && *p != ';') p++;
    if (*p) *p = 0;
    strcpy(disp, disp_start);
    for (int i = 0; disp[i]; i++) disp[i] = tolower(disp[i]);

    const char *search = src;
    while ((search = strcasestr(search, "; filename=")) || (search = strcasestr(search, ";filename="))) {
        search += (search[0] == ';' && search[1] == ' ') ? 10 : 9;
        while (*search == ' ' || *search == '\t') search++;
        if (*search == '"') {
            search++;
            const char *end = search;
            while (*end && *end != '"') end++;
            *end = 0;
            strcpy(filename, search);
            search = end + 1;
        } else {
            const char *end = search;
            while (*end && *end != ' ' && *end != '\t' && *end != ';') end++;
            *end = 0;
            strcpy(filename, search);
            search = end;
        }
        break;
    }
    filename[0] = 0;
}

void get_filename(Entity *e) {
    char type[64] = {0}, subtype[64] = {0}, charset[64] = {0}, disp[64] = {0}, filename[256] = {0};
    const char *ct = get_header_value(e, "Content-Type");
    const char *cd = get_header_value(e, "Content-Disposition");
    parse_content_type(ct, type, subtype, charset);
    parse_content_disposition(cd, disp, filename);

    if (filename[0]) {
        Buffer b; buf_init(&b);
        decode_rfc2047(filename, &b);
        filename[0] = 0;
        for (size_t i = 0; i < b.size; i++) filename[i] = b.data[i];
        filename[b.size] = 0;
        buf_free(&b);
    }
}

void print_entity(Entity *e, int depth) {
    for (int i = 0; i < depth; i++) printf("  ");
    char type[64] = {0}, subtype[64] = {0}, charset[64] = {0}, disp[64] = {0}, filename[256] = {0};
    const char *ct = get_header_value(e, "Content-Type");
    const char *cd = get_header_value(e, "Content-Disposition");
    const char *cte = get_header_value(e, "Content-Transfer-Encoding");
    if (!cte) cte = "7bit";

    parse_content_type(ct, type, subtype, charset);
    parse_content_disposition(cd, disp, filename);
    get_filename(e); // This is a simplification; a real one would handle RFC 2231

    if (strcasecmp(type, "multipart") == 0) {
        printf("multipart/%s parts=%d\n", subtype, e->parts_count);
        for (int i = 0; i < e->parts_count; i++) print_entity(e->parts[i], depth + 1);
    } else if (strcasecmp(type, "text") == 0 && strcasecmp(disp, "attachment") != 0) {
        printf("text/%s charset=%s cte=%s chars=%d\n", subtype, charset, cte, 0);
        UBuffer ubuf; ubuf_init(&ubuf);
        Buffer b; buf_init(&b);
        decode_cte(e->body, e->body_size, cte, &b);
        decode_bytes_to_unicode(e->body, e->body_size, charset, &ubuf);
        print_quoted(&ubuf);
        ubuf_free(&ubuf); buf_free(&b);
    } else {
        printf("%s/%s cte=%s disposition=%s name=%s size=%zu crc32=%08x\n", 
               type, subtype, cte, disp[0] ? disp : "-", filename[0] ? filename : "-", 
               e->body_size, crc32(e->body, e->body_size));
    }
}

char *unfold_header(char *line) {
    char *p = line;
    while (*p) {
        if ((*p == '\r' && *p[1] == '\n') || *p == '\n') {
            char next = p[(*p == '\r' && *p[1] == '\n') ? 2 : 1];
            if (next == ' ' || next == '\t') {
                int len = (*p == '\r' && *p[1] == '\n') ? 2 : 1;
                memmove(p, p + len, strlen(p + len) + 1);
            } else break;
        } else p++;
    }
    return line;
}

Entity *parse_entity(unsigned char *data, size_t len, size_t *consumed) {
    Entity *e = calloc(1, sizeof(Entity));
    size_t i = 0;
    while (i < len) {
        size_t line_start = i;
        while (i < len && data[i] != '\n') i++;
        if (i < len) i++;
        if (data[line_start] == '\r' && data[line_start+1] == '\n' && data[line_start+2] == '\n') {
            i = line_start + 1; break;
        }
        if (data[line_start] == '\n' || (data[line_start] == '\r' && data[line_start+1] == '\n')) {
            i = line_start; break;
        }

        char line[1024] = {0};
        size_t line_len = i - line_start;
        memcpy(line, data + line_start, line_len < 1023 ? line_len : 1023);
        if (line[line_len-1] == '\n') line[line_len-1] = 0;
        if (line[line_len-2] == '\r') line[line_len-2] = 0;

        char *unfolded = unfold_header(line);
        char *colon = strchr(unfolded, ':');
        if (colon) {
            *colon = 0;
            char *val = colon + 1;
            while (*val == ' ' || *val == '\t') val++;
            char *end = val + strlen(val) - 1;
            while (end > val && (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n')) end--;
            if (end > val) *(end + 1) = 0; else *val = 0;

            e->headers = realloc(e->headers, sizeof(Header) * (e->header_count + 1));
            e->headers[e->header_count].key = strdup(unfolded);
            e->headers[e->header_count].value = strdup(val);
            e->header_count++;
        }
    }

    size_t body_start = i;
    char type[64] = {0}, subtype[64] = {0}, charset[64] = {0};
    const char *ct = get_header_value(e, "Content-Type");
    parse_content_type(ct, type, subtype, charset);

    if (strcasecmp(type, "multipart") == 0) {
        char boundary[256] = {0};
        const char *b_search = strcasestr(ct, "boundary=");
        if (b_search) {
            b_search += 9;
            if (*b_search == '"') {
                b_search++;
                const char *end = b_search;
                while (*end && *end != '"') end++;
                memcpy(boundary, b_search, end - b_search);
            } else {
                const char *end = b_search;
                while (*end && *end != ' ' && *end != '\t' && *end != ';') end++;
                memcpy(boundary, b_search, end - b_search);
            }
        }

        size_t p = body_start;
        while (p < len) {
            char delim[512] = {0};
            sprintf(delim, "--%s", boundary);
            size_t d_len = strlen(delim);
            bool found = false;
            while (p + d_len <= len) {
                if (memcmp(data + p, delim, d_len) == 0) {
                    size_t check = p + d_len;
                    while (check < len && (data[check] == ' ' || data[check] == '\t')) check++;
                    if (check < len && (data[check] == '\n' || (data[check] == '\r' && data[check+1] == '\n'))) {
                        size_t final_len = (data[check] == '\r' && data[check+1] == '\n') ? 2 : 1;
                        if (check + final_len < len && data[check] == '-' && data[check+1] == '-') {
                            p = check + 2;
                            found = true; break;
                        }
                        p = check;
                        found = true; break;
                    }
                }
                p++;
            }
            if (!found) break;
            // Part logic...
            break;
        }
    } else {
        e->body = malloc(len - body_start);
        memcpy(e->body, data + body_start, len - body_start);
        e->body_size = len - body_start;
    }
    *consumed = i;
    return e;
}

int compare_filenames(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    DIR *dir = opendir(argv[1]);
    if (!dir) return 0;
    char *files[1024];
    int f_count = 0;
    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (strstr(entry->d_name, ".eml")) files[f_count++] = strdup(entry->d_name);
    }
    closedir(dir);
    qsort(files, f_count, sizeof(char *), compare_filenames);
    for (int i = 0; i < f_count; i++) {
        char path[1024];
        sprintf(path, "%s/%s", argv[1], files[i]);
        FILE *f = fopen(path, "rb");
        if (!f) continue;
        fseek(f, 0, SEEK_END);
        size_t size = ftell(f);
        fseek(f, 0, SEEK_SET);
        unsigned char *data = malloc(size);
        fread(data, 1, size, f);
        fclose(f);

        printf("== %s\n", files[i]);
        Entity *e = parse_entity(data, size, &size);
        UBuffer ubuf; ubuf_init(&ubuf);
        decode_header_to_ubuf(get_header_value(e, "From") ? get_header_value(e, "From") : "-", &ubuf);
        print_quoted(&ubuf); ubuf_free(&ubuf);
        ubuf_init(&ubuf);
        decode_header_to_ubuf(get_header_value(e, "Subject") ? get_header_value(e, "Subject") : "-", &ubuf);
        print_quoted(&ubuf); ubuf_free(&ubuf);
        print_entity(e, 0);
        printf("\n");
        free(data);
    }
    return 0;
}

import os
import zlib
import re
import sys

def split_into_lines(data):
    """Splits bytes into lines at \n only, keeping the line endings."""
    if not data:
        return []
    lines = []
    start = 0
    while start < len(data):
        end = data.find(b'\n', start)
        if end == -1:
            lines.append(data[start:])
            break
        lines.append(data[start:end+1])
        start = end + 1
    return lines

def solve():
    if len(sys.argv) < 2:
        return
    base_dir = sys.argv[1]
    diff_path = os.path.join(base_dir, 'changes.diff')
    tree_dir = os.path.join(base_dir, 'tree')

    try:
        with open(diff_path, 'rb') as f:
            diff_data = f.read()
    except FileNotFoundError:
        return

    diff_lines = split_into_lines(diff_data)

    # Parse the diff into sections
    sections = []
    current_section = None

    i = 0
    while i < len(diff_lines):
        line = diff_lines[i]
        if line.startswith(b'diff --git '):
            # Extract path from "diff --git a/path b/path"
            parts = line.split(b' ')
            if len(parts) >= 3:
                path = parts[2][2:]  # Remove 'a/'
                current_section = {'path': path, 'kind': 'modify', 'hunks': []}
                sections.append(current_section)
            i += 1
        elif current_section is not None:
            if line.startswith(b'new file mode '):
                current_section['kind'] = 'create'
                i += 1
            elif line.startswith(b'deleted file mode '):
                current_section['kind'] = 'delete'
                i += 1
            elif line.startswith(b'index '):
                i += 1
            elif line.startswith(b'@@ '):
                # Parse hunk header: @@ -a,b +c,d @@
                match = re.match(b'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
                if match:
                    a = int(match.group(1))
                    b = int(match.group(2)) if match.group(2) else 1
                    c = int(match.group(3))
                    d = int(match.group(4)) if match.group(4) else 1

                    hunk = {'header': (a, b, c, d), 'body': []}
                    i += 1
                    # Collect body lines until the next hunk or section
                    while i < len(diff_lines) and not (diff_lines[i].startswith(b'@@ ') or diff_lines[i].startswith(b'diff --git ')):
                        hunk['body'].append(diff_lines[i])
                        i += 1
                    current_section['hunks'].append(hunk)
                else:
                    i += 1
            else:
                i += 1
        else:
            i += 1

    # Sort sections by path (bytewise)
    sections.sort(key=lambda x: x['path'])

    for section in sections:
        path_bytes = section['path']
        path = path_bytes.decode('utf-8', 'replace')
        kind = section['kind']

        # Load initial content
        if kind == 'create':
            full_path = os.path.join(tree_dir, path)
            if os.path.exists(full_path):
                print(f"{path}: create")
                print("  error: already exists")
                continue
            content_lines = []
        elif kind == 'delete' or kind == 'modify':
            full_path = os.path.join(tree_dir, path)
            if not os.path.exists(full_path):
                print(f"{path}: {kind}")
                print("  error: not found")
                continue
            with open(full_path, 'rb') as f:
                content_lines = split_into_lines(f.read())

        delta = 0
        hunk_results = []
        all_hunks_applied = True

        for idx, hunk in enumerate(section['hunks'], 1):
            a, b, c, d = hunk['header']
            body = hunk['body']

            # Parse hunk body into old_lines and new_lines
            old_lines = []
            new_lines = []
            last_marker = None
            for line in body:
                marker = line[0:1]
                content = line[1:]
                if marker == b' ':
                    old_lines.append(content)
                    new_lines.append(content)
                    last_marker = b' '
                elif marker == b'-':
                    old_lines.append(content)
                    last_marker = b'-'
                elif marker == b'+':
                    new_lines.append(content)
                    last_marker = b'+'
                elif marker == b'\\':
                    if line.startswith(b'\\ No newline at end of file'):
                        if last_marker == b' ':
                            if old_lines: old_lines[-1] = old_lines[-1][:-1] if old_lines[-1].endswith(b'\n') else old_lines[-1]
                            if new_lines: new_lines[-1] = new_lines[-1][:-1] if new_lines[-1].endswith(b'\n') else new_lines[-1]
                        elif last_marker == b'-':
                            if old_lines: old_lines[-1] = old_lines[-1][:-1] if old_lines[-1].endswith(b'\n') else old_lines[-1]
                        elif last_marker == b'+':
                            if new_lines: new_lines[-1] = new_lines[-1][:-1] if new_lines[-1].endswith(b'\n') else new_lines[-1]

            # Validate hunk size
            if len(old_lines) != b or len(new_lines) != d:
                hunk_results.append(f"  hunk {idx}: malformed")
                continue

            # Apply hunk
            P = a + delta
            if b == 0:
                # Hunk inserts new lines after line P
                if 0 <= P <= len(content_lines):
                    content_lines[P:P] = new_lines
                    hunk_results.append(f"  hunk {idx}: applied at {P} (offset 0)")
                    delta += (d - b)
                else:
                    hunk_results.append(f"  hunk {idx}: rejected")
                    all_hunks_applied = False
            else:
                # Search for a match for the old lines near P
                match_p = None
                dist = 0
                while True:
                    # Try P-dist, then P+dist
                    candidates = [P] if dist == 0 else [P - dist, P + dist]
                    for p in candidates:
                        if p < 1 or p + b - 1 > len(content_lines):
                            continue
                        if content_lines[p-1 : p-1+b] == old_lines:
                            match_p = p
                            break
                    if match_p is not None:
                        break
                    dist += 1
                    # Stop when search range is completely outside content bounds
                    if P - dist < 1 and P + dist + b - 1 > len(content_lines):
                        break

                if match_p is not None:
                    content_lines[match_p-1 : match_p-1+b] = new_lines
                    offset = match_p - P
                    offset_str = f"+{offset}" if offset > 0 else str(offset)
                    hunk_results.append(f"  hunk {idx}: applied at {match_p} (offset {offset_str})")
                    delta += (d - b)
                else:
                    hunk_results.append(f"  hunk {idx}: rejected")
                    all_hunks_applied = False

        # Output report for the file
        print(f"{path}: {kind}")
        for res in hunk_results:
            print(res)

        # Determine final result (deleted or line count/CRC)
        if kind == 'delete' and all_hunks_applied and len(content_lines) == 0:
            print("  result: deleted")
        else:
            final_content = b''.join(content_lines)
            crc = zlib.crc32(final_content) & 0xFFFFFFFF
            print(f"  result: {len(content_lines)} lines, crc32 {crc:08x}")

if __name__ == '__main__':
    solve()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>
#include <math.h>
#include <CommonCrypto/CommonHMAC.h>
#include <CommonCrypto/CommonDigest.h>

typedef enum { JSON_STRING, JSON_NUMBER, JSON_OBJECT, JSON_ARRAY, JSON_BOOL, JSON_NULL } JsonType;

typedef struct JsonValue {
    JsonType type;
    union {
        char *s;
        double n;
        struct { struct JsonEntry *entries; size_t count; } obj;
        struct { struct JsonValue *values; size_t count; } arr;
        bool b;
    } val;
} JsonValue;

typedef struct JsonEntry {
    char *key;
    JsonValue value;
} JsonEntry;

void json_free(JsonValue v) {
    if (v.type == JSON_STRING) free(v.val.s);
    else if (v.type == JSON_OBJECT) {
        for (size_t i = 0; i < v.val.obj.count; i++) {
            free(v.val.obj.entries[i].key);
            json_free(v.val.obj.entries[i].value);
        }
        free(v.val.obj.entries);
    } else if (v.type == JSON_ARRAY) {
        for (size_t i = 0; i < v.val.arr.count; i++) json_free(v.val.arr.values[i]);
        free(v.val.arr.values);
    }
}

char *json_parse_string(const char **json) {
    if (**json != '"') return NULL;
    (*json)++;
    char *res = malloc(1024);
    size_t len = 0;
    while (**json && **json != '"') {
        if (**json == '\\') {
            (*json)++;
            if (**json == 'u') {
                char hex[5] = {0};
                memcpy(hex, (*json) + 1, 4);
                (*json) += 5;
                unsigned int cp = (unsigned int)strtol(hex, NULL, 16);
                if (cp <= 0x7F) res[len++] = (char)cp;
                else if (cp <= 0x7FF) {
                    res[len++] = (char)(0xC0 | (cp >> 6));
                    res[len++] = (char)(0x80 | (cp & 0x3F));
                } else {
                    res[len++] = (char)(0xE0 | (cp >> 12));
                    res[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                    res[len++] = (char)(0x80 | (cp & 0x3F));
                }
            } else {
                char esc = **json;
                (*json)++;
                switch (esc) {
                    case 'n': res[len++] = '\n'; break;
                    case 'r': res[len++] = '\r'; break;
                    case 't': res[len++] = '\t'; break;
                    case '\"': res[len++] = '\"'; break;
                    case '\\': res[len++] = '\\'; break;
                    default: res[len++] = esc; break;
                }
            }
        } else {
            res[len++] = *(*json)++;
        }
        if (len >= 1023) {
            res = realloc(res, len + 1024);
        }
    }
    if (**json == '"') (*json)++;
    res[len] = 0;
    return res;
}

JsonValue json_parse_value(const char **json);

JsonValue json_parse_object(const char **json) {
    JsonValue v; v.type = JSON_OBJECT; v.val.obj.entries = NULL; v.val.obj.count = 0;
    if (**json == '{') (*json)++;
    while (**json && **json != '}') {
        while (**json && isspace(**json)) (*json)++;
        char *key = json_parse_string(json);
        while (**json && isspace(**json)) (*json)++;
        if (**json != ':') return v;
        (*json)++;
        while (**json && isspace(**json)) (*json)++;
        JsonValue val = json_parse_value(json);
        v.val.obj.entries = realloc(v.val.obj.entries, sizeof(JsonEntry) * (v.val.obj.count + 1));
        v.val.obj.entries[v.val.obj.count].key = key;
