#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>
#include <math.h>
#include <CommonCrypto/CommonHMAC.h>
#include <CommonCrypto/CommonDigest.h>

typedef enum { J_STRING, J_NUMBER, J_OBJECT, J_ARRAY, J_BOOL, J_NULL } JType;

typedef struct JValue {
    JType type;
    union {
        char *s;
        double n;
        struct { struct JEntry *e; size_t count; } obj;
        struct { struct JValue *v; size_t count; } arr;
        bool b;
    } val;
} JValue;

typedef struct JEntry {
    char *key;
    JValue value;
} JEntry;

void json_free(JValue v) {
    if (v.type == J_STRING) free(v.val.s);
    else if (v.type == J_OBJECT) {
        for (size_t i = 0; i < v.val.obj.count; i++) {
            free(v.val.obj.e[i].key);
            json_free(v.val.obj.e[i].value);
        }
        free(v.val.obj.e);
    } else if (v.type == J_ARRAY) {
        for (size_t i = 0; i < v.val.arr.count; i++) json_free(v.val.arr.v[i]);
        free(v.val.arr.v);
    }
}

char *json_parse_string(const char **json) {
    if (**json != '"') return NULL;
    (*json)++;
    size_t len = 0;
    char *res = malloc(64);
    while (**json && **json != '"') {
        if (**json == '\\') {
            (*json)++;
            if (!**json) break;
            if (**json == 'u') {
                (*json)++;
                char hex[5] = {0};
                for (int i = 0; i < 4 && **json; i++) hex[i] = *(*json)++;
                unsigned int cp = (unsigned int)strtol(hex, NULL, 16);
                int bytes = (cp <= 0x7F) ? 1 : (cp <= 0x7FF) ? 2 : (cp <= 0xFFFF) ? 3 : 4;
                res = realloc(res, len + bytes + 1);
                if (cp <= 0x7F) res[len++] = (char)cp;
                else if (cp <= 0x7FF) {
                    res[len++] = (char)(0xC0 | (cp >> 6));
                    res[len++] = (char)(0x80 | (cp & 0x3F));
                } else if (cp <= 0xFFFF) {
                    res[len++] = (char)(0xE0 | (cp >> 12));
                    res[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                    res[len++] = (char)(0x80 | (cp & 0x3F));
                }
            } else {
                char esc = *(*json)++;
                char rep = 0;
                if (esc == 'n') rep = '\n'; else if (esc == 'r') rep = '\r';
                else if (esc == 't') rep = '\t'; else if (esc == '\"') rep = '\"';
                else if (esc == '\\') rep = '\\'; else rep = esc;
                res = realloc(res, len + 1);
                res[len++] = rep;
            }
        } else {
            res = realloc(res, len + 1);
            res[len++] = *(*json)++;
        }
    }
    if (**json == '"') (*json)++;
    res = realloc(res, len + 1);
    res[len] = 0;
    return res;
}

JValue json_parse_value(const char **json);

JValue json_parse_object(const char **json) {
    JValue v; v.type = J_OBJECT; v.val.obj.e = NULL; v.val.obj.count = 0;
    if (**json == '{') (*json)++;
    while (**json && **json != '}') {
        while (**json && isspace(**json)) (*json)++;
        char *key = json_parse_string(json);
        while (**json && isspace(**json)) (*json)++;
        if (**json == ':') (*json)++;
        while (**json && isspace(**json)) (*json)++;
        JValue val = json_parse_value(json);
        v.val.obj.e = realloc(v.val.obj.e, sizeof(JEntry) * (v.val.obj.count + 1));
        v.val.obj.e[v.val.obj.count].key = key;
        v.val.obj.e[v.val.obj.count].value = val;
        v.val.obj.count++;
        while (**json && isspace(**json)) (*json)++;
        if (**json == ',') (*json)++;
        while (**json && isspace(**json)) (*json)++;
    }
    if (**json == '}') (*json)++;
    return v;
}

JValue json_parse_array(const char **json) {
    JValue v; v.type = J_ARRAY; v.val.arr.v = NULL; v.val.arr.count = 0;
    if (**json == '[') (*json)++;
    while (**json && **json != ']') {
        while (**json && isspace(**json)) (*json)++;
        JValue val = json_parse_value(json);
        v.val.arr.v = realloc(v.val.arr.v, sizeof(JValue) * (v.val.arr.count + 1));
        v.val.arr.v[v.val.arr.count++] = val;
        while (**json && isspace(**json)) (*json)++;
        if (**json == ',') (*json)++;
        while (**json && isspace(**json)) (*json)++;
    }
    if (**json == ']') (*json)++;
    return v;
}

JValue json_parse_value(const char **json) {
    while (**json && isspace(**json)) (*json)++;
    if (**json == '{') return json_parse_object(json);
    if (**json == '[') return json_parse_array(json);
    if (**json == '"') {
        JValue v; v.type = J_STRING; v.val.s = json_parse_string(json);
        return v;
    }
    if (isdigit(**json) || **json == '-') {
        char buf[64] = {0}; int len = 0;
        while (**json && (isdigit(**json) || **json == '.' || **json == '-' || **json == 'e' || **json == 'E' || **json == '+' || **json == '-')) {
            buf[len++] = *(*json)++;
        }
        JValue v; v.type = J_NUMBER; v.val.n = strtod(buf, NULL);
        return v;
    }
    if (strncmp(*json, "true", 4) == 0) { (*json) += 4; JValue v; v.type = J_BOOL; v.val.b = true; return v; }
    if (strncmp(*json, "false", 5) == 0) { (*json) += 5; JValue v; v.type = J_BOOL; v.val.b = false; return v; }
    if (strncmp(*json, "null", 4) == 0) { (*json) += 4; JValue v; v.type = J_NULL; return v; }
    return (JValue){J_NULL};
}

unsigned char *b64url_decode(const char *in, size_t *out_len) {
    size_t len = strlen(in);
    if (len % 4 == 1) return NULL;
    unsigned char *out = malloc((len * 3) / 4 + 1);
    unsigned int buffer = 0;
    int bits = 0;
    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        int val = -1;
        if (in[i] >= 'A' && in[i] <= 'Z') val = in[i] - 'A';
        else if (in[i] >= 'a' && in[i] <= 'z') val = in[i] - 'a' + 26;
        else if (in[i] >= '0' && in[i] <= '9') val = in[i] - '0' + 52;
        else if (in[i] == '-') val = 62;
        else if (in[i] == '_') val = 63;
        if (val == -1) { free(out); return NULL; }
        buffer = (buffer << 6) | val;
        bits += 6;
        if (bits >= 8) {
            out[j++] = (buffer >> (bits - 8)) & 0xFF;
            bits -= 8;
        }
    }
    *out_len = j;
    out[j] = 0;
    return out;
}

JValue *json_get_obj_val(JValue *obj, const char *key) {
    if (obj->type != J_OBJECT) return NULL;
    for (size_t i = 0; i < obj->val.obj.count; i++) {
        if (strcmp(obj->val.obj.e[i].key, key) == 0) return &obj->val.obj.e[i].value;
    }
    return NULL;
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    char config_path[256], tokens_path[256];
    sprintf(config_path, "%s/config.json", argv[1]);
    sprintf(tokens_path, "%s/tokens.txt", argv[1]);

    FILE *cf = fopen(config_path, "r");
    if (!cf) return 0;
    fseek(cf, 0, SEEK_END);
    long c_size = ftell(cf);
    fseek(cf, 0, SEEK_SET);
    char *c_buf = malloc(c_size + 1);
    fread(c_buf, 1, c_size, cf);
    c_buf[c_size] = 0;
    fclose(cf);

    const char *cp = c_buf;
    JValue config = json_parse_value(&cp);
    double now = 0;
    double leeway = 0;
    char *conf_iss = NULL, *conf_aud = NULL;
    JValue *conf_keys = NULL;

    JValue *v_now = json_get_obj_val(&config, "now");
    if (v_now) now = v_now->val.n;
    JValue *v_lee = json_get_obj_val(&config, "leeway");
    if (v_lee) leeway = v_lee->val.n;
    JValue *v_iss = json_get_obj_val(&config, "issuer");
    if (v_iss) conf_iss = v_iss->val.s;
    JValue *v_aud = json_get_obj_val(&config, "audience");
    if (v_aud) conf_aud = v_aud->val.s;
    JValue *v_keys = json_get_obj_val(&config, "keys");
    if (v_keys) conf_keys = v_keys;

    FILE *tf = fopen(tokens_path, "r");
    if (!tf) return 0;
    char line[4096];
    int line_num = 0, valid_cnt = 0, invalid_cnt = 0;
    while (fgets(line, sizeof(line), tf)) {
        char *start = line;
        while (*start && isspace(*start)) start++;
        char *end = line + strlen(line) - 1;
        while (*end && isspace(*end)) end--;
        if (*start == '\0' || start > end) continue;
        * (end + 1) = '\0';
        line_num++;

        char token[4096];
        int len = 0;
        for (int i = 0; start[i]; i++) token[len++] = start[i];
        token[len] = 0;

        int dots = 0;
        for (int i = 0; token[i]; i++) if (token[i] == '.') dots++;
        bool malformed = (dots != 2);
        if (!malformed) {
            char *segs[3];
            char *p = token;
            for (int i = 0; i < 3; i++) {
                char *dot = strchr(p, '.');
                if (i < 2) *dot = '\0';
                segs[i] = p;
                p = dot ? dot + 1 : "";
            }
            for (int i = 0; i < 3; i++) {
                if (strlen(segs[i]) == 0) { malformed = true; break; }
                size_t dlen;
                unsigned char *d = b64url_decode(segs[i], &dlen);
                if (!d) { malformed = true; break; }
                if (i < 2) {
                    const char *js = (char *)d;
                    JValue jv = json_parse_value(&js);
                    if (jv.type != J_OBJECT) malformed = true;
                    json_free(jv);
                }
                free(d);
            }
        }

        if (malformed) { printf("%d: MALFORMED\n", line_num); invalid_cnt++; continue; }

        char token_copy[4096];
        strcpy(token_copy, token);
        char *segs[3];
        char *p = token_copy;
        for (int i = 0; i < 3; i++) {
            char *dot = strchr(p, '.');
            if (i < 2) *dot = '\0';
            segs[i] = p;
            p = dot ? dot + 1 : "";
        }

        size_t hlen, plen, slen;
        unsigned char *h_dec = b64url_decode(segs[0], &hlen);
        unsigned char *p_dec = b64url_decode(segs[1], &plen);
        unsigned char *s_dec = b64url_decode(segs[2], &slen);

        const char *h_ptr = (char *)h_dec;
        JValue header = json_parse_value(&h_ptr);
        const char *p_ptr = (char *)p_dec;
        JValue payload = json_parse_value(&p_ptr);

        JValue *alg_v = json_get_obj_val(&header, "alg");
        if (!alg_v || alg_v->type != J_STRING || (strcmp(alg_v->val.s, "HS256") != 0 && strcmp(alg_v->val.s, "HS384") != 0 && strcmp(alg_v->val.s, "HS512") != 0)) {
            printf("%d: UNSUPPORTED_ALG\n", line_num);
            invalid_cnt++;
        } else {
            JValue *kid_v = json_get_obj_val(&header, "kid");
            bool key_found = false;
            JValue *key_obj = NULL;
            if (kid_v && kid_v->type == J_STRING) {
                for (size_t i = 0; i < conf_keys->val.arr.count; i++) {
                    JValue *k = &conf_keys->val.arr.v[i];
                    JValue *k_kid = json_get_obj_val(k, "kid");
                    if (k_kid && k_kid->type == J_STRING && strcmp(k_kid->val.s, kid_v->val.s) == 0) {
                        key_found = true;
                        key_obj = k;
                        break;
                    }
                }
            }
            if (!key_found) {
                printf("%d: UNKNOWN_KEY\n", line_num);
                invalid_cnt++;
            } else {
                JValue *k_alg = json_get_obj_val(key_obj, "alg");
                if (!k_alg || k_alg->type != J_STRING || strcmp(k_alg->val.s, alg_v->val.s) != 0) {
                    printf("%d: ALG_MISMATCH\n", line_num);
                    invalid_cnt++;
                } else {
                    JValue *k_val = json_get_obj_val(key_obj, "k");
                    size_t k_len;
                    unsigned char *k_dec = b64url_decode(k_val->val.s, &k_len);
                    unsigned char hmac_res[64];
                    CCHMACAlgorithm h_alg = (strcmp(alg_v->val.s, "HS256") == 0) ? kCCHMACAlgorithmSHA256 : (strcmp(alg_v->val.s, "HS384") == 0) ? kCCHMACAlgorithmSHA384 : kCCHMACAlgorithmSHA512;
                    size_t h_out_len = (h_alg == kCCHMACAlgorithmSHA256) ? 32 : (h_alg == kCCHMACAlgorithmSHA384) ? 48 : 64;
                    char signing_input[4096];
                    sprintf(signing_input, "%s.%s", segs[0], segs[1]);
                    CCHMAC(h_alg, k_dec, k_len, (unsigned char *)signing_input, strlen(signing_input), hmac_res);
                    if (slen != h_out_len || memcmp(hmac_res, s_dec, h_out_len) != 0) {
                        printf("%d: BAD_SIGNATURE\n", line_num);
                        invalid_cnt++;
                    } else {
                        JValue *exp_v = json_get_obj_val(&payload, "exp");
                        if (exp_v && exp_v->type == J_NUMBER && now >= exp_v->val.n + leeway) {
                            printf("%d: EXPIRED\n", line_num);
                            invalid_cnt++;
                        } else {
                            JValue *nbf_v = json_get_obj_val(&payload, "nbf");
                            if (nbf_v && nbf_v->type == J_NUMBER && now + leeway < nbf_v->val.n) {
                                printf("%d: NOT_YET_VALID\n", line_num);
                                invalid_cnt++;
                            } else {
                                JValue *iss_v = json_get_obj_val(&payload, "iss");
                                if (!iss_v || iss_v->type != J_STRING || strcmp(iss_v->val.s, conf_iss) != 0) {
                                    printf("%d: BAD_ISSUER\n", line_num);
                                    invalid_cnt++;
                                } else {
                                    JValue *aud_v = json_get_obj_val(&payload, "aud");
                                    bool aud_ok = false;
                                    if (aud_v && aud_v->type == J_STRING && strcmp(aud_v->val.s, conf_aud) == 0) aud_ok = true;
                                    else if (aud_v && aud_v->type == J_ARRAY) {
                                        for (size_t i = 0; i < aud_v->val.arr.count; i++) {
                                            if (aud_v->val.arr.v[i].type == J_STRING && strcmp(aud_v->val.arr.v[i].val.s, conf_aud) == 0) { aud_ok = true; break; }
                                        }
                                    }
                                    if (!aud_ok) {
                                        printf("%d: BAD_AUDIENCE\n", line_num);
                                        invalid_cnt++;
                                    } else {
                                        JValue *sub_v = json_get_obj_val(&payload, "sub");
                                        JValue *scope_v = json_get_obj_val(&payload, "scope");
                                        char scopes_out[4096] = {0};
                                        if (scope_v && scope_v->type == J_STRING) {
                                            char *s_copy = strdup(scope_v->val.s);
                                            char *parts[128];
                                            int p_cnt = 0;
                                            char *tok = strtok(s_copy, " ");
                                            while (tok) {
                                                bool dup = false;
                                                for (int i = 0; i < p_cnt; i++) if (strcmp(parts[i], tok) == 0) dup = true;
                                                if (!dup) parts[p_cnt++] = tok;
                                                tok = strtok(NULL, " ");
                                            }
                                            qsort(parts, p_cnt, sizeof(char *), compare_strings);
                                            for (int i = 0; i < p_cnt; i++) {
                                                strcat(scopes_out, parts[i]);
                                                if (i < p_cnt - 1) strcat(scopes_out, ",");
                                            }
                                            free(s_copy);
                                        }
                                        printf("%d: VALID sub=%s scope=%s\n", line_num, sub_v->val.s, scopes_out);
                                        valid_cnt++;
                                    }
                                }
                            }
                        }
                    }
                    free(k_dec);
                }
            }
        }
        json_free(header); json_free(payload);
        free(h_dec); free(p_dec); free(s_dec);
    }
    fclose(tf);
    printf("\nvalid=%d invalid=%d\n", valid_cnt, invalid_cnt);
    json_free(config);
    free(c_buf);
    return 0;
}

import java.io.*;
import java.nio.charset.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {

    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".eml"));
        if (files == null) return;
        Arrays.sort(files, Comparator.comparing(File::getName));

        for (File file : files) {
            try {
                processFile(file);
                System.out.println();
            } catch (IOException e) {
                // Ignore errors in individual files
            }
        }
    }

    private static void processFile(File file) throws IOException {
        byte[] data = java.nio.file.Files.readAllBytes(file.toPath());
        String lineBreak = detectLineBreak(data);
        List<String> lines = splitLines(data, lineBreak);

        int i = 0;
        List<String> unfoldedHeaders = new ArrayList<>();
        while (i < lines.size() && !lines.get(i).isEmpty()) {
            String line = lines.get(i);
            i++;
            while (i < lines.size() && (lines.get(i).startsWith(" ") || lines.get(i).startsWith("\t"))) {
                line += lines.get(i);
                i++;
            }
            unfoldedHeaders.add(line);
        }

        Map<String, String> headers = parseHeaders(unfoldedHeaders);

        // The body starts after the first empty line
        List<String> bodyLines = new ArrayList<>();
        if (i < lines.size()) {
            i++; // skip the empty line
            while (i < lines.size()) {
                bodyLines.add(lines.get(i++));
            }
        }

        Entity entity = new Entity(headers, bodyLines, lineBreak);
        System.out.println("== " + file.getName());
        System.out.println("From: " + quoteString(decodeRFC2047(headers.getOrDefault("From", "-"))));
        System.out.println("Subject: " + quoteString(decodeRFC2047(headers.getOrDefault("Subject", "-"))));
        printEntity(entity, 0);
    }

    private static String detectLineBreak(byte[] data) {
        for (int i = 0; i < data.length - 1; i++) {
            if (data[i] == (byte) '\r' && data[i + 1] == (byte) '\n') return "\r\n";
            if (data[i] == (byte) '\n') return "\n";
        }
        return "\n";
    }

    private static List<String> splitLines(byte[] data, String lineBreak) {
        List<String> lines = new ArrayList<>();
        int lbLen = lineBreak.length();
        int start = 0;
        for (int i = 0; i <= data.length - lbLen; i++) {
            boolean match = true;
            for (int j = 0; j < lbLen; j++) {
                if (data[i + j] != lineBreak.charAt(j)) {
                    match = false;
                    break;
                }
            }
            if (match) {
                lines.add(new String(data, start, i - start, StandardCharsets.US_ASCII));
                start = i + lbLen;
                i += lbLen - 1;
            }
        }
        if (start < data.length) {
            lines.add(new String(data, start, data.length - start, StandardCharsets.US_ASCII));
        }
        return lines;
    }

    private static Map<String, String> parseHeaders(List<String> lines) {
        Map<String, String> headers = new LinkedHashMap<>();
        for (String line : lines) {
            int colon = line.indexOf(':');
            if (colon != -1) {
                String name = line.substring(0, colon).trim();
                String value = line.substring(colon + 1).trim();
                headers.put(name.toLowerCase(), value);
            }
        }
        return headers;
    }

    private static void printEntity(Entity entity, int indent) {
        String indentStr = "  ".repeat(indent);
        ContentType ct = entity.getContentType();
        String cte = entity.getContentTransferEncoding();

        if (ct.type.equalsIgnoreCase("multipart")) {
            System.out.println(indentStr + "multipart/" + ct.subtype + " parts=" + entity.getParts().size());
            for (Entity part : entity.getParts()) {
                printEntity(part, indent + 1);
            }
        } else if (ct.type.equalsIgnoreCase("text") && !entity.getDisposition().equalsIgnoreCase("attachment")) {
            System.out.println(indentStr + "text/" + ct.subtype + " charset=" + ct.charset + " cte=" + cte + " chars=" + entity.getDecodedText().length());
            System.out.println(indentStr + "  " + quoteString(entity.getDecodedText()));
        } else {
            String disp = entity.getDisposition();
            String name = entity.getFileName();
            byte[] decoded = entity.getDecodedBytes();
            CRC32 crc = new CRC32();
            crc.update(decoded);
            System.out.printf("%s%s/%s cte=%s disposition=%s name=%s size=%d crc32=%08x\n",
                    indentStr, ct.type, ct.subtype, cte, disp, quoteString(name), decoded.length, crc.getValue());
        }
    }

    static class Entity {
        Map<String, String> headers;
        List<String> bodyLines;
        String lineBreak;

        Entity(Map<String, String> headers, List<String> bodyLines, String lineBreak) {
            this.headers = headers;
            this.bodyLines = bodyLines;
            this.lineBreak = lineBreak;
        }

        ContentType getContentType() {
            String val = headers.get("content-type");
            if (val == null) return new ContentType("text", "plain", "us-ascii", Collections.emptyMap());
            return ContentType.parse(val);
        }

        String getContentTransferEncoding() {
            String val = headers.get("content-transfer-encoding");
            return (val == null) ? "7bit" : val.toLowerCase().trim();
        }

        String getDisposition() {
            String val = headers.get("content-disposition");
            if (val == null) return "-";
            ContentDisposition cd = ContentDisposition.parse(val);
            return cd.disposition;
        }

        String getFileName() {
            ContentType ct = getContentType();
            ContentDisposition cd = ContentDisposition.parse(headers.getOrDefault("content-disposition", ""));

            // RFC 2231 filename
            String name = decodeRFC2231(cd.params, "filename");
            if (name == null) name = decodeRFC2231(ct.params, "filename");
            if (name == null) name = decodeRFC2231(cd.params, "name");
            if (name == null) name = decodeRFC2231(ct.params, "name");
            if (name == null) {
                // Fallback to RFC 2047
                String fn = cd.params.get("filename");
                if (fn == null) fn = ct.params.get("name");
                if (fn != null) return decodeRFC2047(fn);
            }
            return name == null ? "-" : name;
        }

        byte[] getDecodedBytes() {
            StringBuilder sb = new StringBuilder();
            for (String line : bodyLines) sb.append(line).append(lineBreak);
            byte[] data = sb.toString().getBytes(StandardCharsets.US_ASCII);
            return decodeTransferEncoding(data, getContentTransferEncoding());
        }

        String getDecodedText() {
            byte[] decoded = getDecodedBytes();
            String charset = getContentType().charset;
            String text = decodeCharset(decoded, charset);
            return text.replace("\r\n", "\n").replace("\r", "\n");
        }

        List<Entity> getParts() {
            ContentType ct = getContentType();
            if (!ct.type.equalsIgnoreCase("multipart")) return Collections.emptyList();
            String boundary = ct.params.get("boundary");
            if (boundary == null) return Collections.emptyList();

            List<Entity> parts = new ArrayList<>();
            StringBuilder body = new StringBuilder();
            for (String line : bodyLines) body.append(line).append(lineBreak);
            String fullBody = body.toString();

            String startDelim = "--" + boundary;
            String endDelim = "--" + boundary + "--";

            int firstDelimIdx = fullBody.indexOf(startDelim);
            if (firstDelimIdx == -1) return parts;

            int currentPos = firstDelimIdx;
            while (currentPos < fullBody.length()) {
                int nextDelimIdx = -1;
                int searchPos = currentPos + startDelim.length();

                while (searchPos < fullBody.length()) {
                    if (fullBody.startsWith(startDelim, searchPos)) {
                        // Check if it's exactly the delimiter followed by whitespace
                        int checkPos = searchPos + startDelim.length();
                        while (checkPos < fullBody.length() && (fullBody.charAt(checkPos) == ' ' || fullBody.charAt(checkPos) == '\t')) {
                            checkPos++;
                        }
                        if (checkPos < fullBody.length() && fullBody.charAt(checkPos) == '\n') {
                            // Potential delimiter, check if it's a close delimiter
                            if (fullBody.startsWith("--", searchPos + startDelim.length())) {
                                // It's --B--
                                int closeCheckPos = searchPos + endDelim.length();
                                while (closeCheckPos < fullBody.length() && (fullBody.charAt(closeCheckPos) == ' ' || fullBody.charAt(closeCheckPos) == '\t')) {
                                    closeCheckPos++;
                                }
                                if (closeCheckPos < fullBody.length() && fullBody.charAt(closeCheckPos) == '\n') {
                                    nextDelimIdx = searchPos;
                                    break;
                                }
                            }
                            nextDelimIdx = searchPos;
                            break;
                        }
                        searchPos++;
                    } else {
                        searchPos++;
                    }
                }

                if (nextDelimIdx == -1) break;

                String partContent = fullBody.substring(currentPos + (currentPos == firstDelimIdx ? 0 : 0), nextDelimIdx);
                // The delimiter itself is part of the break. The content is between.
                // But we need to remove the leading delimiter of the first part.
                if (currentPos == firstDelimIdx) {
                    // First delimiter is not part of the content
                    int firstSemicolon = fullBody.indexOf(lineBreak, firstDelimIdx);
                    partContent = fullBody.substring(firstSemicolon + lineBreak.length(), nextDelimIdx);
                } else {
                    // Previous delimiter already handled the line break
                    int prevSemicolon = fullBody.indexOf(lineBreak, currentPos - 1);
                    // This is tricky. Let's use a better approach.
                }
                currentPos = nextDelimIdx;
                break; // Simplified for brevity, real multipart is complex.
            }

            // Corrected multipart parsing:
            return parseMultipart(fullBody, boundary, lineBreak);
        }

        private List<Entity> parseMultipart(String fullBody, String boundary, String lineBreak) {
            List<Entity> parts = new ArrayList<>();
            String startDelim = "--" + boundary;
            String endDelim = "--" + boundary + "--";

            int searchPos = 0;
            while (searchPos < fullBody.length()) {
                int delimIdx = fullBody.indexOf(startDelim, searchPos);
                if (delimIdx == -1) break;

                // Verify delimiter
                int checkPos = delimIdx + startDelim.length();
                while (checkPos < fullBody.length() && (fullBody.charAt(checkPos) == ' ' || fullBody.charAt(checkPos) == '\t')) checkPos++;
                if (checkPos >= fullBody.length() || fullBody.charAt(checkPos) != '\n') {
                    searchPos = delimIdx + 1;
                    continue;
                }

                // Check if it's a close delimiter
                boolean isClose = false;
                if (fullBody.startsWith("--", delimIdx + startDelim.length())) {
                    int closeCheckPos = delimIdx + endDelim.length();
                    while (closeCheckPos < fullBody.length() && (fullBody.charAt(closeCheckPos) == ' ' || fullBody.charAt(closeCheckPos) == '\t')) closeCheckPos++;
                    if (closeCheckPos < fullBody.length() && fullBody.charAt(closeCheckPos) == '\n') {
                        isClose = true;
                    }
                }

                if (isClose) {
                    searchPos = checkPos + 1;
                    break;
                }

                // Find next delimiter
                int nextDelimIdx = -1;
                int nextSearchPos = checkPos + 1;
                while (nextSearchPos < fullBody.length()) {
                    int nextIdx = fullBody.indexOf(startDelim, nextSearchPos);
                    if (nextIdx == -1) break;
                    int nextCheckPos = nextIdx + startDelim.length();
                    while (nextCheckPos < fullBody.length() && (fullBody.charAt(nextCheckPos) == ' ' || fullBody.charAt(nextCheckPos) == '\t')) nextCheckPos++;
                    if (nextCheckPos < fullBody.length() && fullBody.charAt(nextCheckPos) == '\n') {
                        nextDelimIdx = nextIdx;
                        break;
                    }
                    nextSearchPos = nextIdx + 1;
                }

                if (nextDelimIdx == -1) break;

                String partContent = fullBody.substring(checkPos, nextDelimIdx);
                // Trim trailing line break of the content
                if (partContent.endsWith(lineBreak)) {
                    partContent = partContent.substring(0, partContent.length() - lineBreak.length());
                }

                parts.add(parseEntityFromContent(partContent, lineBreak));
                searchPos = nextDelimIdx;
            }
            return parts;
        }

        private Entity parseEntityFromContent(String content, String lineBreak) {
            List<String> lines = new ArrayList<>();
            int start = 0;
            for (int i = 0; i <= content.length() - lineBreak.length(); i++) {
                if (content.startsWith(lineBreak, i)) {
                    lines.add(content.substring(start, i));
                    start = i + lineBreak.length();
                    i += lineBreak.length() - 1;
                }
            }
            lines.add(content.substring(start));

            int i = 0;
            List<String> unfoldedHeaders = new ArrayList<>();
            while (i < lines.size() && !lines.get(i).isEmpty()) {
                String line = lines.get(i);
                i++;
                while (i < lines.size() && (lines.get(i).startsWith(" ") || lines.get(i).startsWith("\t"))) {
                    line += lines.get(i);
                    i++;
                }
                unfoldedHeaders.add(line);
            }

            Map<String, String> headers = parseHeaders(unfoldedHeaders);
            List<String> bodyLines = new ArrayList<>();
            if (i < lines.size()) {
                i++; // skip empty line
                while (i < lines.size()) bodyLines.add(lines.get(i++));
            }
            return new Entity(headers, bodyLines, lineBreak);
        }
    }

    static class ContentType {
        String type, subtype, charset;
        Map<String, String> params;

        ContentType(String type, String subtype, String charset, Map<String, String> params) {
            this.type = type.toLowerCase();
            this.subtype = subtype.toLowerCase();
            this.charset = charset.toLowerCase();
            this.params = params;
        }

        static ContentType parse(String val) {
            int slash = val.indexOf('/');
            if (slash == -1) return new ContentType("text", "plain", "us-ascii", Collections.emptyMap());
            String type = val.substring(0, slash).trim().toLowerCase();
            int semi = val.indexOf(';', slash);
            String subtype;
            Map<String, String> params = new HashMap<>();
            if (semi == -1) {
                subtype = val.substring(slash + 1).trim().toLowerCase();
            } else {
                subtype = val.substring(slash + 1, semi).trim().toLowerCase();
                String paramStr = val.substring(semi + 1);
                parseParams(paramStr, params);
            }
            String charset = params.getOrDefault("charset", "us-ascii").toLowerCase();
            return new ContentType(type, subtype, charset, params);
        }

        static void parseParams(String s, Map<String, String> params) {
            int i = 0;
            while (i < s.length()) {
                int semi = s.indexOf(';', i);
                String pair = (semi == -1) ? s.substring(i) : s.substring(i, semi);
                int eq = pair.indexOf('=');
                if (eq != -1) {
                    String name = pair.substring(0, eq).trim().toLowerCase();
                    String value = pair.substring(eq + 1).trim();
                    if (value.startsWith("\"") && value.endsWith("\"")) {
                        value = value.substring(1, value.length() - 1);
                        value = decodeQuotedString(value);
                    }
                    params.put(name, value);
                }
                i = (semi == -1) ? s.length() : semi + 1;
            }
        }

        static String decodeQuotedString(String s) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == '\\' && i + 1 < s.length()) {
                    sb.append(s.charAt(++i));
                } else {
                    sb.append(s.charAt(i));
                }
            }
            return sb.toString();
        }
    }

    static class ContentDisposition {
        String disposition;
        Map<String, String> params;

        ContentDisposition(String disposition, Map<String, String> params) {
            this.disposition = disposition.toLowerCase();
            this.params = params;
        }

        static ContentDisposition parse(String val) {
            if (val.isEmpty()) return new ContentDisposition("-", Collections.emptyMap());
            int semi = val.indexOf(';');
            String disp = (semi == -1) ? val.trim() : val.substring(0, semi).trim();
            Map<String, String> params = new HashMap<>();
            if (semi != -1) {
                ContentType.parseParams(val.substring(semi + 1), params);
            }
            return new ContentDisposition(disp, params);
        }
    }

    private static byte[] decodeTransferEncoding(byte[] data, String encoding) {
        if (encoding.equalsIgnoreCase("base64")) {
            StringBuilder sb = new StringBuilder();
            for (byte b : data) {
                char c = (char) b;
                if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/') {
                    sb.append(c);
                } else if (c == '=') {
                    sb.append(c);
                    break;
                }
            }
            return Base64.getDecoder().decode(sb.toString());
        } else if (encoding.equalsIgnoreCase("quoted-printable")) {
            String s = new String(data, StandardCharsets.US_ASCII);
            String[] lines = s.split("\\r?\\n");
            StringBuilder decoded = new StringBuilder();
            for (int i = 0; i < lines.length; i++) {
                String line = lines[i].stripTrailing();
                if (line.endsWith("=") && i + 1 < lines.length) {
                    decoded.append(line, 0, line.length() - 1);
                    i++;
                    String nextLine = lines[i].stripTrailing();
                    decoded.append(nextLine);
                } else {
                    decoded.append(line).append("\n");
                }
            }

            String result = decoded.toString();
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            for (int i = 0; i < result.length(); i++) {
                if (result.charAt(i) == '=' && i + 2 < result.length()) {
                    try {
                        int b = Integer.parseInt(result.substring(i + 1, i + 3), 16);
                        baos.write(b);
                        i += 2;
                    } catch (NumberFormatException e) {
                        baos.write('=');
                    }
                } else {
                    baos.write(result.charAt(i));
                }
            }
            return baos.toByteArray();
        }
        return data;
    }

    private static String decodeCharset(byte[] data, String charset) {
        if (charset.equalsIgnoreCase("utf-8")) return new String(data, StandardCharsets.UTF_8);
        if (charset.equalsIgnoreCase("us-ascii")) return new String(data, StandardCharsets.US_ASCII);
        if (charset.equalsIgnoreCase("iso-8859-1")) return new String(data, StandardCharsets.ISO_8859_1);
        if (charset.equalsIgnoreCase("windows-1252")) {
            char[] map = new char[128];
            String mapping = " \u20AC\u0081\u201A\u0192\u201E\u2026\u2020\u2021\u02C6\u2030\u0160\u2039\u0152\u008D\u017D\u008F\u0090\u2018\u2019\u201C\u201D\u2022\u2013\u2014\u02DC\u2122\u0161\u203A\u0153\u009D\u017E\u0178";
            // This is a simplification. The actual map provided in the prompt:
            char[] winMap = {
                '\u20AC', '\u0081', '\u201A', '\u0192', '\u201E', '\u2026', '\u2020', '\u2021',
                '\u02C6', '\u2030', '\u0160', '\u2039', '\u0152', '\u008D', '\u017D', '\u008F',
                '\u0090', '\u2018', '\u2019', '\u201C', '\u201D', '\u2022', '\u2013', '\u2014',
                '\u02DC', '\u2122', '\u0161', '\u203A', '\u0153', '\u009D', '\u017E', '\u0178'
            };
            StringBuilder sb = new StringBuilder();
            for (byte b : data) {
                int ub = b & 0xFF;
                if (ub >= 0x80 && ub <= 0x9F) sb.append(winMap[ub - 0x80]);
                else sb.append((char) ub);
            }
            return sb.toString();
        }
        return new String(data, StandardCharsets.UTF_8);
    }

    private static String decodeRFC2047(String text) {
        if (text == null || text.isEmpty()) return text;
        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < text.length()) {
            if (text.startsWith("=?", i)) {
                int end = text.indexOf("?=", i + 2);
                if (end == -1) {
                    result.append(text.charAt(i++));
                    continue;
                }
                int charEnd = text.indexOf('?', i + 2);
                if (charEnd == -1 || charEnd >= end) {
                    result.append(text.charAt(i++));
                    continue;
                }
                String charset = text.substring(i + 2, charEnd);
                int langIdx = charset.indexOf('*');
                if (langIdx != -1) charset = charset.substring(0, langIdx);

                int encEnd = text.indexOf('?', charEnd + 1);
                if (encEnd == -1 || encEnd >= end) {
                    result.append(text.charAt(i++));
                    continue;
                }
                String encoding = text.substring(charEnd + 1, encEnd);
                if (!encoding.matches("[BbQq]")) {
                    result.append(text.charAt(i++));
                    continue;
                }

                int textEnd = text.indexOf("?=", encEnd + 1);
                if (textEnd == -1) {
                    result.append(text.charAt(i++));
                    continue;
                }
                String encodedText = text.substring(encEnd + 1, textEnd);

                // Handle adjacent encoded-words
                List<byte[]> wordBytes = new ArrayList<>();
                wordBytes.add(decodeRFC2047Word(encodedText, encoding));

                int nextI = textEnd + 2;
                while (nextI < text.length()) {
                    if (nextI < text.length() && (text.charAt(nextI) == ' ' || text.charAt(nextI) == '\t')) {
                        nextI++;
                        continue;
                    }
                    if (text.startsWith("=?", nextI)) {
                        int nextEnd = text.indexOf("?=", nextI + 2);
                        if (nextEnd == -1) break;
                        int nextCharEnd = text.indexOf('?', nextI + 2);
                        if (nextCharEnd == -1 || nextCharEnd >= nextEnd) break;
                        String nextCharset = text.substring(nextI + 2, nextCharEnd);
                        int nextLangIdx = nextCharset.indexOf('*');
                        if (nextLangIdx != -1) nextCharset = nextCharset.substring(0, nextLangIdx);
                        if (!nextCharset.equalsIgnoreCase(charset)) break;

                        int nextEncEnd = text.indexOf('?', nextCharEnd + 1);
                        if (nextEncEnd == -1 || nextEncEnd >= nextEnd) break;
                        String nextEnc = text.substring(nextCharEnd + 1, nextEncEnd);
                        if (!nextEnc.matches("[BbQq]")) break;

                        int nextTextEnd = text.indexOf("?=", nextEncEnd + 1);
                        if (nextTextEnd == -1) break;
                        wordBytes.add(decodeRFC2047Word(text.substring(nextEncEnd + 1, nextTextEnd), nextEnc));
                        nextI = nextTextEnd + 2;
                    } else {
                        break;
                    }
                }

                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                for (byte[] b : wordBytes) baos.write(b, 0, b.length);
                result.append(decodeCharset(baos.toByteArray(), charset));
                i = nextI;
            } else {
                result.append(text.charAt(i++));
            }
        }
        return result.toString();
    }

    private static byte[] decodeRFC2047Word(String text, String encoding) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        if (encoding.equalsIgnoreCase("B")) {
            try {
                baos.write(Base64.getDecoder().decode(text));
            } catch (Exception e) { }
        } else if (encoding.equalsIgnoreCase("Q")) {
            for (int i = 0; i < text.length(); i++) {
                if (text.charAt(i) == '_') baos.write(0x20);
                else if (text.charAt(i) == '=' && i + 2 < text.length()) {
                    try {
                        baos.write(Integer.parseInt(text.substring(i + 1, i + 3), 16));
                        i += 2;
                    } catch (NumberFormatException e) {
                        baos.write('=');
                    }
                } else {
                    baos.write(text.charAt(i));
                }
            }
        }
        return baos.toByteArray();
    }

    private static String decodeRFC2231(Map<String, String> params, String attr) {
        boolean hasStarSemicolon = params.containsKey(attr + "*");
        boolean hasStarZero = params.containsKey(attr + "*0");
        if (!hasStarSemicolon && !hasStarZero) return null;

        List<String> segments = new ArrayList<>();
        if (hasStarSemicolon) {
            segments.add(params.get(attr + "*"));
        } else {
            int i = 0;
            while (params.containsKey(attr + "*" + i)) {
                segments.add(params.get(attr + "*" + i));
                i++;
            }
        }

        String firstSegment = segments.get(0);
        boolean isPercentEncoded = hasStarSemicolon || (firstSegment.startsWith("\"") == false && !params.containsKey(attr + "*0*"));
        // Actually, the prompt says: "A segment whose name ends with an extra * (a* or a*0*, a*1*, ...) is percent-encoded"
        // Let's re-evaluate based on the prompt.
        boolean isPE = false;
        if (hasStarSemicolon) isPE = true;
        else {
            // Check if any segment was a*n*
            for (int i = 0; i < 100; i++) {
                if (params.containsKey(attr + "*" + i + "*")) {
                    isPE = true;
                    break;
                }
            }
        }

        String charset = "us-ascii";
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        for (int i = 0; i < segments.size(); i++) {
            String val = segments.get(i);
            if (isPE) {
                if (i == 0) {
                    int quote = val.indexOf('\'');
                    if (quote != -1) {
                        charset = val.substring(0, quote);
                        val = val.substring(quote + 1);
                    }
                }
                for (int j = 0; j < val.length(); j++) {
                    if (val.charAt(j) == '%' && j + 2 < val.length()) {
                        try {
                            baos.write(Integer.parseInt(val.substring(j + 1, j + 3), 16));
                            j += 2;
                        } catch (NumberFormatException e) {
                            baos.write('%');
                        }
                    } else {
                        baos.write(val.charAt(j));
                    }
                }
            } else {
                if (val.startsWith("\"") && val.endsWith("\"")) {
                    val = ContentType.decodeQuotedString(val.substring(1, val.length() - 1));
                }
                baos.writeBytes(val);
            }
        }
        return decodeCharset(baos.toByteArray(), charset);
    }

    private static String quoteString(String text) {
        if (text == null) return "\"-\"";
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c == '"') sb.append("\\\"");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\t') sb.append("\\t");
            else if (c < 0x20 || (c >= 0x7F && c <= 0x9F)) {
                sb.append(String.format("\\u%04x", (int) c));
            } else {
                sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }
