]

func decodeBytes(_ bytes: [UInt8], charset: String) -> String {
    let cs = charset.lowercased()
    if cs == "us-ascii" || cs == "utf-8" {
        return String(bytes: bytes, encoding: .utf8) ?? ""
    } else if cs == "iso-8859-1" {
        return bytes.map { String(UnicodeScalar($0)!) }.joined()
    } else if cs == "windows-1252" {
        return bytes.map { byte in
            if let scalar = win1252Map[byte] { return String(scalar) }
            return String(UnicodeScalar($0)!)
        }.joined()
    }
    return ""
}

func decodeB64(_ input: String) -> [UInt8] {
    let b64Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    var filtered = ""
    for char in input {
        if b64Alphabet.contains(char) { filtered.append(char) }
        else if char == "=" { break }
    }
    return Data(base64Encoded: filtered).map { $0 } ?? []
}

func decodeQP(_ input: String) -> [UInt8] {
    var lines = [String]()
    let rawLines = input.components(separatedBy: "\n").map { $0.hasSuffix("\r") ? String($0.dropLast()) : $0 }
    for line in rawLines {
        var trimmed = line
        while trimmed.hasSuffix(" ") || trimmed.hasSuffix("\t") { trimmed.removeLast() }
        lines.append(trimmed)
    }
    var joined = [String]()
    var i = 0
    while i < lines.count {
        var current = lines[i]
        while i < lines.count - 1 && current.hasSuffix("=") {
            i += 1
            current += lines[i]
        }
        joined.append(current)
        i += 1
    }
    var bytes = [UInt8]()
    for line in joined {
        var j = line.startIndex
        while j < line.endIndex {
            if line[j] == "=" && j + 2 < line.endIndex {
                let hex = line[line.index(after: j)...line.index(j, offsetBy: 2)]
                if let val = UInt8(hex, radix: 16) {
                    bytes.append(val)
                    j = line.index(j, offsetBy: 3)
                    continue
                }
            }
            bytes.append(line[j].asciiValue!)
            j = line.index(after: j)
        }
        bytes.append(10)
    }
    return bytes
}

func decodeRFC2047Word(_ word: String) -> (charset: String, bytes: [UInt8]) {
    let parts = word.dropFirst(2).dropLast().split(separator: "?", omittingEmptySubsequences: false)
    if parts.count < 3 { return ("", []) }
    var charset = String(parts[0])
    if let langIdx = charset.firstIndex(of: "*") { charset = String(charset[..<langIdx]) }
    let encoding = parts[1]
    let text = String(parts[2])
    var bytes = [UInt8]()
    if encoding.lowercased() == "b" {
        bytes = decodeB64(text)
    } else if encoding.lowercased() == "q" {
        var j = text.startIndex
        while j < text.endIndex {
            if text[j] == "_" { bytes.append(0x20); j = text.index(after: j) }
            else if text[j] == "=" && j + 2 < text.endIndex {
                let hex = text[text.index(after: j)...text.index(j, offsetBy: 2)]
                if let val = UInt8(hex, radix: 16) { bytes.append(val); j = text.index(j, offsetBy: 3); continue }
                bytes.append(text[j].asciiValue!); j = text.index(after: j)
            } else {
                bytes.append(text[j].asciiValue!); j = text.index(after: j)
            }
        }
    }
    return (charset, bytes)
}

func scanRFC2047(_ input: String) -> String {
    var result = ""
    var i = input.startIndex
    while i < input.endIndex {
        if input[i] == "=" && i + 1 < input.endIndex && input[i+1] == "?" {
            var j = i + 2
            while j < input.endIndex && input[j] != "?" { j = input.index(after: j) }
            if j < input.endIndex {
                let charset = String(input[i+2..<j])
                j = input.index(after: j)
                var k = j
                while k < input.endIndex && input[k] != "?" { k = input.index(after: k) }
                if k < input.endIndex {
                    let encoding = String(input[j..<k])
                    k = input.index(after: k)
                    var l = k
                    while l < input.endIndex && input[l] != "?" { l = input.index(after: l) }
                    if l < input.endIndex && l + 1 < input.endIndex && input[l+1] == "=" {
                        let text = String(input[k..<l])
                        let wordS = "=?\(charset)?\(encoding)?\(text)?="
                        let decodedWord = decodeRFC2047Word(wordS)
                        var currentCharset = decodedWord.charset
                        var allBytes = decodedWord.bytes
                        var nextI = input.index(after: input.index(after: l))
                        while nextI < input.endIndex {
                            while nextI < input.endIndex && (input[nextI] == " " || input[nextI] == "\t") { nextI = input.index(after: nextI) }
                            if nextI >= input.endIndex { break }
                            if input[nextI] == "=" && nextI + 1 < input.endIndex && input[nextI+1] == "?" {
                                var j2 = nextI + 2
                                while j2 < input.endIndex && input[j2] != "?" { j2 = input.index(after: j2) }
                                if j2 < input.endIndex {
                                    var charset2 = String(input[nextI+2..<j2])
                                    if let langIdx = charset2.firstIndex(of: "*") { charset2 = String(charset2[..<langIdx]) }
                                    if charset2.lowercased() == currentCharset.lowercased() {
                                        j2 = input.index(after: j2)
                                        var k2 = j2
                                        while k2 < input.endIndex && input[k2] != "?" { k2 = input.index(after: k2) }
                                        if k2 < input.endIndex {
                                            k2 = input.index(after: k2)
                                            var l2 = k2
                                            while l2 < input.endIndex && input[l2] != "?" { l2 = input.index(after: l2) }
                                            if l2 < input.endIndex && l2 + 1 < input.endIndex && input[l2+1] == "=" {
                                                let text2 = String(input[k2..<l2])
                                                var j3 = nextI
                                                var k3 = j3
                                                while k3 < input.endIndex && input[k3] != "?" { k3 = input.index(after: k3) }
                                                k3 = input.index(after: k3)
                                                var l3 = k3
                                                while l3 < input.endIndex && input[l3] != "?" { l3 = input.index(after: l3) }
                                                l3 = input.index(after: l3)
                                                var m3 = l3
                                                while m3 < input.endIndex && input[m3] != "?" { m3 = input.index(after: m3) }
                                                m3 = input.index(after: m3)
                                                let wordS2 = String(input[nextI...m3])
                                                let decodedS2 = decodeRFC2047Word(wordS2)
                                                allBytes += decodedS2.bytes
                                                nextI = input.index(after: m3)
                                                continue
                                            }
                                        }
                                    }
                                }
                            }
                            break
                        }
                        result += decodeBytes(allBytes, charset: currentCharset)
                        i = nextI
                        continue
                    }
                }
            }
        }
        result.append(input[i])
        i = input.index(after: i)
    }
    return result
}

func parseParameters(_ input: String) -> [String: String] {
    var params = [String: String]()
    var i = input.startIndex
    while i < input.endIndex {
        while i < input.endIndex && (input[i] == " " || input[i] == "\t") { i = input.index(after: i) }
        if i >= input.endIndex { break }
        if i < input.endIndex && input[i] == ";" { i = input.index(after: i) }
