                var j = i + bStart.count
                while j < entity.body.count && (entity.body[j] == 32 || entity.body[j] == 9) { j += 1 }
                if j + lineBreak.count <= entity.body.count && Array(entity.body[j..<j+lineBreak.count]) == lineBreak {
                    firstBoundaryPos = i
                    break
                }
            }
            i += 1
        }

        if firstBoundaryPos != -1 {
            var lastPos = firstBoundaryPos + bStart.count
            // Skip the line break after boundary
            var j = lastPos
            while j < entity.body.count && (entity.body[j] == 32 || entity.body[j] == 9) { j += 1 }
            if j + lineBreak.count <= entity.body.count && Array(entity.body[j..<j+lineBreak.count]) == lineBreak {
                lastPos = j + lineBreak.count
            }

            while true {
                var nextBoundaryPos = -1
                var k = lastPos
                while k <= entity.body.count - bStart.count {
                    if Array(entity.body[k..<k+bStart.count]) == Array(bStart.utf8) {
                        var l = k + bStart.count
                        while l < entity.body.count && (entity.body[l] == 32 || entity.body[l] == 9) { l += 1 }
                        if l + lineBreak.count <= entity.body.count && Array(entity.body[l..<l+lineBreak.count]) == lineBreak {
                            nextBoundaryPos = k
                            break
                        }
                    }
                    k += 1
                }

                if nextBoundaryPos == -1 { break }

