                    while j < entity.body.count && (entity.body[j] == 32 || entity.body[j] == 9) { j += 1 }
                    if j + lineBreak.count <= entity.body.count && Array(entity.body[j..<j+lineBreak.count]) == lineBreak {
                        lastPos = j + lineBreak.count
                    } else {
                        lastPos = nextBoundaryPos + bStart.count // This case should not happen per spec
                    }
