        if cte == "base64" {
            body = decodeB64(String(bytes: body, encoding: .ascii) ?? "")
        } else if cte == "quoted-printable" {
            body = decodeQP(String(bytes: body, encoding: .ascii) ?? "")
        }

        let charset = ctParams["charset"] ?? "us-ascii"
        let name = getFilename(contentTypeParams: ctParams, contentDispParams: cdParams) ?? "-"

        return .single(type: type, subtype: subtype, charset: charset, cte: cte, disposition: dispType, name: name, body: body)
    }
}

func printTree(_ part: MimePart, indent: String) {
    switch part {
    case .multipart(let subtype, let parts):
        print("\(indent)multipart/\(subtype) parts=\(parts.count)")
        for p in parts { printTree(p, indent: indent + "  ") }
    case .single(let type, let subtype, let charset, let cte, let disposition, let name, let body):
        if type == "text" && disposition != "attachment" {
            let decoded = decodeBytes(body, charset: charset).replacingOccurrences(of: "\r\n", with: "\n").replacingOccurrences(of: "\r", with: "\n")
            print("\(indent)text/\(subtype) charset=\(charset.lowercased()) cte=\(cte.lowercased()) chars=\(decoded.count)")
            print("\(indent)  \(quoteString(decoded))")
        } else {
            print("\(indent)\(type)/\(subtype) cte=\(cte.lowercased()) disposition=\(disposition) name=\(quoteString(name)) size=\(body.count) crc32=\(String(format: "%08x", crc32(data: body)))")
        }
    }
}

func main() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let dir = args[1]
    let fm = FileManager.default
    guard let files = try? fm.contentsOfDirectory(atPath: dir) else { return }

    for file in files.sorted() where file.hasSuffix(".eml") {
        let path = (dir as NSString).appendingPathComponent(file)
        guard let data = fm.contents(atPath: path) else { continue }
        let bytes = Array(data)
        let lineBreak = bytes.contains(13) && bytes.contains(10) ? [13, 10] : [10]

        // Unfold headers
        var unfoldedBytes = [UInt8]()
        var i = 0
        while i < bytes.count {
            var j = i
            while j < bytes.count && (j + lineBreak.count <= bytes.count ? Array(bytes[j..<j+lineBreak.count]) != lineBreak : true) {
                j += 1
            }
            if j >= bytes.count {
                unfoldedBytes += bytes[i...]
                break
            }
            let line = Array(bytes[i..<j])
            unfoldedBytes += line
            if j + lineBreak.count <= bytes.count {
                let nextStart = j + lineBreak.count
                if nextStart < bytes.count && (bytes[nextStart] == 32 || bytes[nextStart] == 9) {
                    // Unfold: remove line break
                } else {
                    unfoldedBytes += lineBreak
                }
            }
            i = j + lineBreak.count
        }

        let entity = parseEntity(data: unfoldedBytes, lineBreak: lineBreak)
        let from = scanRFC2047(entity.headers["from"] ?? "-")
        let subject = scanRFC2047(entity.headers["subject"] ?? "-")

        print("== \(file)")
        print("From: \(quoteString(from))")
        print("Subject: \(quoteString(subject))")
        let root = parseMime(entity: entity, lineBreak: lineBreak)
        printTree(root, indent: "")
        print("")
    }
}

