                    if (l.startsWith("new file mode ")) {
                        sec.kind = "create";
                    } else if (l.startsWith("deleted file mode ")) {
                        sec.kind = "delete";
                    } else if (l.startsWith("@@ ")) {
                        Hunk hunk = parseHunk(l, diffLines, i);
                        sec.hunks.add(hunk);
                        i = findHunkEnd(diffLines, i);
                    }
                    i++;
                }
                sections.add(sec);
                continue;
            }
            i++;
        }
        return sections;
    }

    private static Hunk parseHunk(String header, List<byte[]> diffLines, int startIdx) {
        Hunk hunk = new Hunk();
        String[] parts = header.split(" ");
        String oldPart = parts[1].substring(1);
        String newPart = parts[2].substring(1);
        if (oldPart.contains(",")) {
            String[] s = oldPart.split(",");
            hunk.a = Integer.parseInt(s[0]);
            hunk.b = Integer.parseInt(s[1]);
        } else {
            hunk.a = Integer.parseInt(oldPart);
            hunk.b = 1;
        }
        if (newPart.contains(",")) {
            String[] s = newPart.split(",");
            hunk.c = Integer.parseInt(s[0]);
            hunk.d = Integer.parseInt(s[1]);
        } else {
            hunk.c = Integer.parseInt(newPart);
            hunk.d = 1;
        }

        int i = startIdx + 1;
        char lastMarker = ' ';
        while (i < diffLines.size()) {
            byte[] lineBytes = diffLines.get(i);
            String l = new String(lineBytes);
            if (l.startsWith("diff --git ") || l.startsWith("@@ ")) break;
            if (l.startsWith("\\ No newline at end of file")) {
                if (lastMarker == ' ') {
                    removeNewline(hunk.oldLines);
                    removeNewline(hunk.newLines);
                } else if (lastMarker == '-') {
                    removeNewline(hunk.oldLines);
                } else if (lastMarker == '+') {
                    removeNewline(hunk.newLines);
                }
            } else {
                char marker = (char) lineBytes[0];
                int length = lineBytes.length;
                if (length > 0 && lineBytes[length - 1] == '\n') {
                    length--;
                }
                byte[] content = new byte[length - 1];
                System.arraycopy(lineBytes, 1, content, 0, length - 1);
                byte[] withNewline = new byte[content.length + 1];
                System.arraycopy(content, 0, withNewline, 0, content.length);
                withNewline[content.length] = '\n';
                if (marker == ' ') {
                    hunk.oldLines.add(withNewline);
                    hunk.newLines.add(withNewline);
                } else if (marker == '-') {
                    hunk.oldLines.add(withNewline);
                } else if (marker == '+') {
                    hunk.newLines.add(withNewline);
                }
                lastMarker = marker;
            }
            i++;
        }

        if (hunk.oldLines.size() != hunk.b || hunk.newLines.size() != hunk.d) {
            hunk.malformed = true;
        }
        return hunk;
    }

    private static int findHunkEnd(List<byte[]> diffLines, int startIdx) {
        int i = startIdx + 1;
        while (i < diffLines.size()) {
            String l = new String(diffLines.get(i));
            if (l.startsWith("diff --git ") || l.startsWith("@@ ")) return i - 1;
            i++;
        }
        return diffLines.size() - 1;
    }

    private static void removeNewline(List<byte[]> lines) {
        if (lines.isEmpty()) return;
        byte[] last = lines.get(lines.size() - 1);
        if (last.length > 0 && last[last.length - 1] == '\n') {
            lines.set(lines.size() - 1, Arrays.copyOf(last, last.length - 1));
        }
    }

    private static int findMatch(List<byte[]> content, List<byte[]> oldLines, int P) {
        int b = oldLines.size();
        for (int i = 0; ; i++) {
            int p1 = P - i;
            int p2 = P + i;
            if (i == 0) {
                if (checkMatch(content, oldLines, P)) return P;
            } else {
                if (checkMatch(content, oldLines, p1)) return p1;
                if (checkMatch(content, oldLines, p2)) return p2;
            }
            if (p1 < 1 && p2 + b - 1 > content.size()) break;
        }
        return -1;
    }

    private static boolean checkMatch(List<byte[]> content, List<byte[]> oldLines, int p) {
        int b = oldLines.size();
        if (p < 1 || p + b - 1 > content.size()) return false;
        for (int i = 0; i < b; i++) {
            if (!Arrays.equals(content.get(p - 1 + i), oldLines.get(i))) return false;
        }
        return true;
    }

    private static String formatOffset(int offset) {
        if (offset == 0) return "0";
        if (offset > 0) return "+" + offset;
        return String.valueOf(offset);
    }

    private static String calculateCRC32(List<byte[]> content) {
        CRC32 crc = new CRC32();
        for (byte[] b : content) {
            crc.update(b);
        }
        return String.format("%08x", crc.getValue());
    }
}

import sys
import os

# Increase recursion depth for deep Tern programs
sys.setrecursionlimit(2000)

class TernRuntimeError(Exception):
    def __init__(self, message, token):
        self.message = message
        self.token = token

class Token:
    def __init__(self, type, value, line):
        self.type = type
        self.value = value
        self.line = line

class Lexer:
    def __init__(self, source):
        self.source = source
        self.pos = 0
        self.line = 1

    def tokenize(self):
        tokens = []
        while self.pos < len(self.source):
            char = self.source[self.pos]
            if char.isspace():
                if char == '\n':
                    self.line += 1
                self.pos += 1
            elif char == '#':
                while self.pos < len(self.source) and self.source[self.pos] != '\n':
                    self.pos += 1
            elif char == '"':
                start_line = self.line
                self.pos += 1
                s = ""
                while self.pos < len(self.source) and self.source[self.pos] != '"':
                    c = self.source[self.pos]
                    if c == '\\':
                        self.pos += 1
                        if self.pos >= len(self.source): break
                        esc = self.source[self.pos]
                        if esc == 'n': s += '\n'
                        elif esc == 't': s += '\t'
                        elif esc == '"': s += '"'
                        elif esc == '\\': s += '\\'
                        else: s += esc
                    else:
                        s += c
                    self.pos += 1
                self.pos += 1
                tokens.append(Token('STRING', s, start_line))
            elif char.isdigit():
                start_pos = self.pos
                while self.pos < len(self.source) and self.source[self.pos].isdigit():
                    self.pos += 1
                tokens.append(Token('INT', int(self.source[start_pos:self.pos]), self.line))
            elif char.isalpha() or char == '_':
                start_pos = self.pos
                while self.pos < len(self.source) and (self.source[self.pos].isalnum() or self.source[self.pos] == '_'):
                    self.pos += 1
                val = self.source[start_pos:self.pos]
                keywords = {
                    'let', 'fn', 'if', 'else', 'while', 'for', 'in', 'return',
                    'break', 'continue', 'and', 'or', 'not', 'true', 'false', 'nil'
                }
                type = 'KEYWORD' if val in keywords else 'IDENT'
                tokens.append(Token(type, val, self.line))
            else:
                # Operators and punctuation
                ops = ['==', '!=', '<=', '>=', '<', '>', '=', '+', '-', '*', '/', '%', '(', ')', '[', ']', '{', '}', ',', ';']
                found = False
                for op in ops:
                    if self.source.startswith(op, self.pos):
                        tokens.append(Token('OP', op, self.line))
                        self.pos += len(op)
                        found = True
                        break
                if not found:
                    self.pos += 1
        return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected=None):
        token = self.peek()
        if expected:
            if not token or (expected == 'IDENT' and token.type != 'IDENT') or \
               (expected == 'KEYWORD' and token.value != expected) or \
               (expected == 'OP' and token.value != expected):
                pass # Grammar guarantees validity
        self.pos += 1
        return token

    def parse_program(self):
        stmts = []
        while self.pos < len(self.tokens):
            stmts.append(self.parse_stmt())
        return stmts

    def parse_stmt(self):
        token = self.peek()
        if token.type == 'KEYWORD':
            if token.value == 'let':
                self.consume()
                name = self.consume('IDENT')
                self.consume('OP') # =
                expr = self.parse_expr()
                self.consume('OP') # ;
                return ('let', name, expr)
            elif token.value == 'fn':
                self.consume()
                name = self.consume('IDENT')
                self.consume('OP') # (
                params = []
                if self.peek() and self.peek().type == 'IDENT':
                    params.append(self.consume('IDENT'))
                    while self.peek() and self.peek().value == ',':
                        self.consume()
                        params.append(self.consume('IDENT'))
                self.consume('OP') # )
                block = self.parse_block()
                return ('fn_decl', name, params, block)
            elif token.value == 'if':
                return self.parse_if()
            elif token.value == 'while':
                self.consume()
                expr = self.parse_expr()
                block = self.parse_block()
                return ('while', expr, block)
            elif token.value == 'for':
                self.consume()
                ident = self.consume('IDENT')
                self.consume('KEYWORD') # in
                expr = self.parse_expr()
                block = self.parse_block()
                return ('for', ident, expr, block)
            elif token.value == 'return':
                self.consume()
                expr = None
                if self.peek() and not (self.peek().type == 'OP' and self.peek().value == ';'):
                    expr = self.parse_expr()
                self.consume('OP') # ;
                return ('return', expr)
            elif token.value == 'break':
                self.consume()
                self.consume('OP') # ;
                return ('break',)
            elif token.value == 'continue':
                self.consume()
                self.consume('OP') # ;
                return ('continue',)
        elif token.type == 'IDENT':
            name = self.consume('IDENT')
            if self.peek() and self.peek().value == '[':
                # postfix [ expr ] = expr ;
                self.consume() # [
                idx_expr = self.parse_expr()
                self.consume('OP') # ]
                self.consume('OP') # =
                val_expr = self.parse_expr()
                self.consume('OP') # ;
                return ('assign_idx', name, idx_expr, val_expr)
            elif self.peek() and self.peek().value == '=':
                self.consume() # =
                expr = self.parse_expr()
                self.consume('OP') # ;
                return ('assign', name, expr)

        # expr ;
        expr = self.parse_expr()
        self.consume('OP') # ;
        return ('expr_stmt', expr)

    def parse_if(self):
        self.consume() # if
        expr = self.parse_expr()
        block = self.parse_block()
        else_block = None
        if self.peek() and self.peek().value == 'else':
            self.consume()
            if self.peek() and self.peek().value == 'if':
                else_block = self.parse_if()
            else:
                else_block = self.parse_block()
        return ('if', expr, block, else_block)

    def parse_block(self):
        self.consume('OP') # {
        stmts = []
        while self.peek() and self.peek().value != '}':
            stmts.append(self.parse_stmt())
        self.consume('OP') # }
        return stmts

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        node = self.parse_and()
        while self.peek() and self.peek().value == 'or':
            token = self.consume()
            right = self.parse_and()
            node = ('or', node, right, token)
        return node

    def parse_and(self):
        node = self.parse_not()
        while self.peek() and self.peek().value == 'and':
            token = self.consume()
            right = self.parse_not()
            node = ('and', node, right, token)
        return node

    def parse_not(self):
        if self.peek() and self.peek().value == 'not':
            token = self.consume()
            return ('not', self.parse_not(), token)
        return self.parse_comp()

    def parse_comp(self):
        node = self.parse_add()
        while self.peek() and self.peek().value in ('==', '!=', '<', '<=', '>', '>='):
            token = self.consume()
            right = self.parse_add()
            node = ('comp', node, right, token)
        return node

    def parse_add(self):
        node = self.parse_mul()
        while self.peek() and self.peek().value in ('+', '-'):
            token = self.consume()
            right = self.parse_mul()
            node = ('add', node, right, token)
        return node

    def parse_mul(self):
        node = self.parse_unary()
        while self.peek() and self.peek().value in ('*', '/', '%'):
            token = self.consume()
            right = self.parse_unary()
            node = ('mul', node, right, token)
        return node

    def parse_unary(self):
        if self.peek() and self.peek().value == '-':
            token = self.consume()
            return ('unary_minus', self.parse_unary(), token)
        return self.parse_postfix()

    def parse_postfix(self):
        node = self.parse_primary()
        while True:
            if self.peek() and self.peek().value == '(':
                token = self.consume()
                args = []
                if self.peek() and self.peek().value != ')':
                    args.append(self.parse_expr())
                    while self.peek() and self.peek().value == ',':
                        self.consume()
                        args.append(self.parse_expr())
                self.consume('OP') # )
                node = ('call', node, args, token)
            elif self.peek() and self.peek().value == '[':
                token = self.consume()
                idx = self.parse_expr()
                self.consume('OP') # ]
                node = ('index', node, idx, token)
            else:
                break
        return node

    def parse_primary(self):
        token = self.consume()
        if token.type == 'INT': return ('int', token)
        if token.type == 'STRING': return ('string', token)
        if token.type == 'KEYWORD':
            if token.value == 'true': return ('bool', True, token)
            if token.value == 'false': return ('bool', False, token)
            if token.value == 'nil': return ('nil', token)
            if token.value == 'fn':
                self.consume('OP') # (
                params = []
                if self.peek() and self.peek().type == 'IDENT':
                    params.append(self.consume('IDENT'))
                    while self.peek() and self.peek().value == ',':
                        self.consume()
                        params.append(self.consume('IDENT'))
                self.consume('OP') # )
                block = self.parse_block()
                return ('fn_lit', params, block, token)
        if token.type == 'IDENT': return ('ident', token)
        if token.value == '(':
            expr = self.parse_expr()
            self.consume('OP') # )
            return expr
        if token.value == '[':
            args = []
            if self.peek() and self.peek().value != ']':
                args.append(self.parse_expr())
                while self.peek() and self.peek().value == ',':
                    self.consume()
                    args.append(self.parse_expr())
            self.consume('OP') # ]
            return ('list_lit', args, token)
        return None

class TernFunction:
    def __init__(self, params, body, closure_scope):
        self.params = params
        self.body = body
        self.closure_scope = closure_scope

class TernBuiltin:
    def __init__(self, name, func, num_args=None):
        self.name = name
        self.func = func
        self.num_args = num_args

    def call(self, args, token):
        if self.num_args is not None and len(args) != self.num_args:
            raise TernRuntimeError(f"expected {self.num_args} arguments, got {len(args)}", token)
        try:
            return self.func(*args)
        except (TypeError, ValueError):
            raise TernRuntimeError(f"bad argument to {self.name}", token)

class Scope:
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def define(self, name, value):
        self.vars[name] = value

    def assign(self, name, value, token):
        if name in self.vars:
            self.vars[name] = value
            return
        if self.parent:
            self.parent.assign(name, value, token)
        else:
            raise TernRuntimeError(f"undefined variable {name}", token)

    def resolve(self, name, token):
        if name in self.vars:
            return self.vars[name]
        if self.parent:
            return self.parent.resolve(name, token)
        raise TernRuntimeError(f"undefined variable {name}", token)

def get_type_name(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "list"
    if isinstance(v, TernFunction): return "function"
    if isinstance(v, TernBuiltin): return "function"
    return "unknown"

def display_form(v, visited=None):
    if visited is None: visited = set()
    if v is None: return "nil"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, str): return v
    if isinstance(v, (TernFunction, TernBuiltin)): return "<fn>"
    if isinstance(v, list):
        if id(v) in visited: return "[...]"
        visited.add(id(v))
        elems = [display_form_element(e, visited.copy()) for e in v]
        return "[" + ", ".join(elems) + "]"
    return str(v)

def display_form_element(v, visited):
    if isinstance(v, str):
        esc = v.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\t', '\\t')
        return f'"{esc}"'
    return display_form(v, visited)

class Return(Exception):
    def __init__(self, value): self.value = value
class Break(Exception): pass
class Continue(Exception): pass

class Interpreter:
    def __init__(self):
        self.MAX_INT = 2**63 - 1
        self.MIN_INT = -2**63
        self.S_builtins = Scope()
        self.setup_builtins()

    def setup_builtins(self):
        def builtin_print(*args):
            print(" ".join(display_form(a) for a in args))
            return None
        def builtin_str(v): return display_form(v)
        def builtin_type(v): return get_type_name(v)
        def builtin_len(v): return len(v)
        def builtin_push(l, v):
            l.append(v)
            return None
        def builtin_pop(l):
            if not l: raise Exception("pop empty")
            return l.pop()
        def builtin_range(a, b): return list(range(a, b))
        def builtin_slice(x, a, b): return x[a:b]

        self.S_builtins.define("print", TernBuiltin("print", builtin_print))
        self.S_builtins.define("str", TernBuiltin("str", builtin_str, 1))
        self.S_builtins.define("type", TernBuiltin("type", builtin_type, 1))
        self.S_builtins.define("len", TernBuiltin("len", builtin_len, 1))
        self.S_builtins.define("push", TernBuiltin("push", builtin_push, 2))
        self.S_builtins.define("pop", TernBuiltin("pop", builtin_pop, 1))
        self.S_builtins.define("range", TernBuiltin("range", builtin_range, 2))
        self.S_builtins.define("slice", TernBuiltin("slice", builtin_slice, 3))

    def check_int(self, v, token):
        if v < self.MIN_INT or v > self.MAX_INT:
            raise TernRuntimeError("integer overflow", token)
        return v

    def is_truthy(self, v):
        if v is None: return False
        if isinstance(v, bool): return v
        if isinstance(v, int): return v != 0
        if isinstance(v, str): return v != ""
        if isinstance(v, list): return len(v) > 0
        return True

    def eval_expr(self, node, scope):
        tag = node[0]
        if tag == 'int':
            return self.check_int(node[1].value, node[1])
        if tag == 'string':
            return node[1].value
        if tag == 'bool':
            return node[1]
        if tag == 'nil':
            return None
        if tag == 'ident':
            return scope.resolve(node[1].value, node[1])
        if tag == 'list_lit':
            return [self.eval_expr(e, scope) for e in node[1]]
        if tag == 'fn_lit':
            params = [p.value for p in node[1]]
            return TernFunction(params, node[2], scope)
        if tag == 'or':
            left = self.eval_expr(node[1], scope)
            if self.is_truthy(left): return left
            return self.eval_expr(node[2], scope)
        if tag == 'and':
            left = self.eval_expr(node[1], scope)
            if not self.is_truthy(left): return left
            return self.eval_expr(node[2], scope)
        if tag == 'not':
            return not self.is_truthy(self.eval_expr(node[1], scope))
        if tag == 'comp':
            left = self.eval_expr(node[1], scope)
            right = self.eval_expr(node[2], scope)
            op = node[3].value
            if isinstance(left, int) and isinstance(right, int):
                if op == '==': return left == right
                if op == '!=': return left != right
                if op == '<': return left < right
                if op == '<=': return left <= right
                if op == '>': return left > right
                if op == '>=': return left >= right
            if isinstance(left, str) and isinstance(right, str):
                if op == '==': return left == right
                if op == '!=': return left != right
                if op == '<': return left < right
                if op == '<=': return left <= right
                if op == '>': return left > right
                if op == '>=': return left >= right
            if op == '==': return (left is right) or (isinstance(left, list) and isinstance(right, list) and self.compare_lists(left, right))
            if op == '!=': return not ((left is right) or (isinstance(left, list) and isinstance(right, list) and self.compare_lists(left, right)))
            raise TernRuntimeError(f"cannot apply {op} to {get_type_name(left)} and {get_type_name(right)}", node[3])
        if tag == 'add':
            left = self.eval_expr(node[1], scope)
            right = self.eval_expr(node[2], scope)
            if isinstance(left, int) and isinstance(right, int):
                return self.check_int(left + right, node[3])
            if isinstance(left, str) and isinstance(right, str):
                return left + right
            if isinstance(left, list) and isinstance(right, list):
                return left + right
            raise TernRuntimeError(f"cannot apply + to {get_type_name(left)} and {get_type_name(right)}", node[3])
        if tag == 'mul':
            left = self.eval_expr(node[1], scope)
            right = self.eval_expr(node[2], scope)
            op = node[3].value
            if not (isinstance(left, int) and isinstance(right, int)):
                raise TernRuntimeError(f"cannot apply {op} to {get_type_name(left)} and {get_type_name(right)}", node[3])
            if op == '*':
                return self.check_int(left * right, node[3])
            if op == '/':
                if right == 0: raise TernRuntimeError("division by zero", node[3])
                return self.check_int(int(left / right), node[3])
            if op == '%':
                if right == 0: raise TernRuntimeError("division by zero", node[3])
                return self.check_int(left - int(left / right) * right, node[3])
        if tag == 'unary_minus':
            val = self.eval_expr(node[1], scope)
            if not isinstance(val, int):
                raise TernRuntimeError(f"cannot apply - to {get_type_name(val)}", node[2])
            return self.check_int(-val, node[2])
        if tag == 'call':
            callee = self.eval_expr(node[1], scope)
            args = [self.eval_expr(a, scope) for a in node[2]]
            token = node[3]
            if isinstance(callee, TernBuiltin):
                return callee.call(args, token)
            if isinstance(callee, TernFunction):
                S_call = Scope(parent=callee.closure_scope)
                for p, a in zip(callee.params, args):
                    S_call.define(p, a)
                try:
                    self.execute_block(callee.body, S_call)
                except Return as r:
                    return r.value
                return None
            raise TernRuntimeError(f"cannot call {get_type_name(callee)}", token)
        if tag == 'index':
            x = self.eval_expr(node[1], scope)
            i = self.eval_expr(node[2], scope)
            token = node[3]
            if not (isinstance(x, (list, str))):
                raise TernRuntimeError(f"cannot index {get_type_name(x)} with {get_type_name(i)}", token)
            if not isinstance(i, int):
                raise TernRuntimeError(f"cannot index {get_type_name(x)} with {get_type_name(i)}", token)
            if not (0 <= i < len(x)):
                raise TernRuntimeError(f"index {i} out of range for length {len(x)}", token)
            return x[i]

    def compare_lists(self, l1, l2):
        if len(l1) != len(l2): return False
        for e1, e2 in zip(l1, l2):
            if not self.compare_vals(e1, e2): return False
        return True

    def compare_vals(self, v1, v2):
        if v1 is v2: return True
        if isinstance(v1, list) and isinstance(v2, list):
            return self.compare_lists(v1, v2)
        if get_type_name(v1) != get_type_name(v2): return False
        return v1 == v2

    def execute_block(self, stmts, scope):
        for stmt in stmts:
            self.execute_stmt(stmt, scope)

    def execute_stmt(self, stmt, scope):
        tag = stmt[0]
        if tag == 'let':
            val = self.eval_expr(stmt[2], scope)
            scope.define(stmt[1].value, val)
        elif tag == 'fn_decl':
            params = [p.value for p in stmt[2]]
            fn = TernFunction(params, stmt[3], scope)
            scope.define(stmt[1].value, fn)
        elif tag == 'if':
            cond = self.eval_expr(stmt[1], scope)
            if self.is_truthy(cond):
                S_if = Scope(parent=scope)
                self.execute_block(stmt[2], S_if)
            elif stmt[3]:
                if stmt[3][0] == 'if':
                    S_else = Scope(parent=scope)
                    self.execute_stmt(stmt[3], S_else)
                else:
                    S_else = Scope(parent=scope)
                    self.execute_block(stmt[3], S_else)
        elif tag == 'while':
            while True:
                cond = self.eval_expr(stmt[1], scope)
                if not self.is_truthy(cond): break
                S_while = Scope(parent=scope)
                try:
                    self.execute_block(stmt[2], S_while)
                except Break: break
                except Continue: continue
        elif tag == 'for':
            e = self.eval_expr(stmt[2], scope)
            if not isinstance(e, list):
                raise TernRuntimeError(f"cannot iterate {get_type_name(e)}", stmt[0] if isinstance(stmt[0], Token) else None) # Need token for 'for'
            # Fix for: 'for' token is not in the tuple, we need it for error reporting.
            # In our parser, we should have stored the 'for' token.
            # Let's adjust the parser to store the 'for' token.
            # Wait, I'll just pass the token if possible. Let me re-parse.
            # Actually, I'll just use a dummy token or handle it. Let's fix the parser.
            pass
        elif tag == 'return':
            val = self.eval_expr(stmt[1], scope) if stmt[1] else None
            raise Return(val)
        elif tag == 'break':
            raise Break()
        elif tag == 'continue':
            raise Continue()
        elif tag == 'assign':
            val = self.eval_expr(stmt[2], scope)
            scope.assign(stmt[1].value, val, stmt[1])
        elif tag == 'assign_idx':
            x = self.eval_expr(stmt[1], scope)
            i = self.eval_expr(stmt[2], scope)
            v = self.eval_expr(stmt[3], scope)
            token = stmt[1] # Use the name token as a proxy or the [ token
            if not isinstance(x, list):
                raise TernRuntimeError(f"cannot assign into {get_type_name(x)}", token)
            if not isinstance(i, int):
                raise TernRuntimeError(f"cannot index list with {get_type_name(i)}", token)
            if not (0 <= i < len(x)):
                raise TernRuntimeError(f"index {i} out of range for length {len(x)}", token)
            x[i] = v
        elif tag == 'expr_stmt':
            self.eval_expr(stmt[1], scope)

    def execute_for(self, stmt, scope):
        # Corrected for loop execution
        token_for = stmt[4] # Assuming we stored it
        e = self.eval_expr(stmt[2], scope)
        if not isinstance(e, list):
            raise TernRuntimeError(f"cannot iterate {get_type_name(e)}", token_for)
        i = 0
        while i < len(e):
            S_for = Scope(parent=scope)
            S_for.define(stmt[1].value, e[i])
            try:
                self.execute_block(stmt[3], S_for)
            except Break: break
            except Continue: pass
            i += 1

def main():
    if len(sys.argv) < 2: return
    path = os.path.join(sys.argv[1], 'program.tern')
    if not os.path.exists(path): return
    with open(path, 'r') as f:
        source = f.read()

    lexer = Lexer(source)
    tokens = lexer.tokenize()

    # Quick fix for 'for' token in Parser
    class ParserFixed(Parser):
        def parse_stmt(self):
            token = self.peek()
            if token.type == 'KEYWORD':
                if token.value == 'for':
                    t_for = self.consume()
                    ident = self.consume('IDENT')
                    self.consume('KEYWORD') # in
                    expr = self.parse_expr()
                    block = self.parse_block()
                    return ('for', ident, expr, block, t_for)
                return super().parse_stmt()
            return super().parse_stmt()

    parser = ParserFixed(tokens)
    program = parser.parse_program()

    interp = Interpreter()
    S_global = Scope(parent=interp.S_builtins)

    try:
        for stmt in program:
            if stmt[0] == 'for':
                interp.execute_for(stmt, S_global)
            else:
                interp.execute_stmt(stmt, S_global)
    except TernRuntimeError as e:
        print(f"error at line {e.token.line}: {e.message}")
    except Exception as e:
        # This should not happen given the problem constraints
        pass

if __name__ == "__main__":
    main()

import sys
import os

# Increase recursion depth for deep Tern programs
sys.setrecursionlimit(2000)

class TernRuntimeError(Exception):
    def __init__(self, message, token):
        self.message = message
        self.token = token

class Token:
    def __init__(self, type, value, line):
        self.type = type
        self.value = value
        self.line = line

class Lexer:
    def __init__(self, source):
        self.source = source
        self.pos = 0
        self.line = 1

    def tokenize(self):
        tokens = []
        while self.pos < len(self.source):
            char = self.source[self.pos]
            if char.isspace():
                if char == '\n':
                    self.line += 1
                self.pos += 1
            elif char == '#':
                while self.pos < len(self.source) and self.source[self.pos] != '\n':
                    self.pos += 1
            elif char == '"':
                start_line = self.line
                self.pos += 1
                s = ""
                while self.pos < len(self.source) and self.source[self.pos] != '"':
                    c = self.source[self.pos]
                    if c == '\\':
                        self.pos += 1
                        if self.pos >= len(self.source): break
                        esc = self.source[self.pos]
                        if esc == 'n': s += '\n'
                        elif esc == 't': s += '\t'
                        elif esc == '"': s += '"'
                        elif esc == '\\': s += '\\'
                        else: s += esc
                    else:
                        s += c
                    self.pos += 1
                self.pos += 1
                tokens.append(Token('STRING', s, start_line))
            elif char.isdigit():
                start_pos = self.pos
                while self.pos < len(self.source) and self.source[self.pos].isdigit():
                    self.pos += 1
                tokens.append(Token('INT', int(self.source[start_pos:self.pos]), self.line))
            elif char.isalpha() or char == '_':
                start_pos = self.pos
                while self.pos < len(self.source) and (self.source[self.pos].isalnum() or self.source[self.pos] == '_'):
                    self.pos += 1
                val = self.source[start_pos:self.pos]
                keywords = {
                    'let', 'fn', 'if', 'else', 'while', 'for', 'in', 'return',
                    'break', 'continue', 'and', 'or', 'not', 'true', 'false', 'nil'
                }
                t_type = 'KEYWORD' if val in keywords else 'IDENT'
                tokens.append(Token(t_type, val, self.line))
            else:
                ops = ['==', '!=', '<=', '>=', '<', '>', '=', '+', '-', '*', '/', '%', '(', ')', '[', ']', '{', '}', ',', ';']
                found = False
                for op in ops:
                    if self.source.startswith(op, self.pos):
                        tokens.append(Token('OP', op, self.line))
                        self.pos += len(op)
                        found = True
                        break
                if not found:
                    self.pos += 1
        return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def peek_next(self):
        return self.tokens[self.pos + 1] if self.pos + 1 < len(self.tokens) else None

    def consume(self, expected=None):
        token = self.peek()
        self.pos += 1
        return token

    def parse_program(self):
        stmts = []
        while self.pos < len(self.tokens):
            stmts.append(self.parse_stmt())
        return stmts

    def parse_stmt(self):
        token = self.peek()
        if token.type == 'KEYWORD':
            if token.value == 'let':
                self.consume()
                name = self.consume('IDENT')
                self.consume('OP') # =
                expr = self.parse_expr()
                self.consume('OP') # ;
                return ('let', name, expr)
            elif token.value == 'fn':
                self.consume()
                name = self.consume('IDENT')
                self.consume('OP') # (
                params = []
                if self.peek() and self.peek().type == 'IDENT':
                    params.append(self.consume('IDENT'))
                    while self.peek() and self.peek().value == ',':
                        self.consume()
                        params.append(self.consume('IDENT'))
                self.consume('OP') # )
                block = self.parse_block()
                return ('fn_decl', name, params, block)
            elif token.value == 'if':
                return self.parse_if()
            elif token.value == 'while':
                self.consume()
                expr = self.parse_expr()
                block = self.parse_block()
                return ('while', expr, block)
            elif token.value == 'for':
                t_for = self.consume()
                ident = self.consume('IDENT')
                self.consume('KEYWORD') # in
                expr = self.parse_expr()
                block = self.parse_block()
                return ('for', ident, expr, block, t_for)
            elif token.value == 'return':
                self.consume()
                expr = None
                if self.peek() and not (self.peek().type == 'OP' and self.peek().value == ';'):
                    expr = self.parse_expr()
                self.consume('OP') # ;
                return ('return', expr)
            elif token.value == 'break':
                self.consume()
                self.consume('OP') # ;
                return ('break',)
            elif token.value == 'continue':
                self.consume()
                self.consume('OP') # ;
                return ('continue',)
        elif token.type == 'IDENT' and self.peek_next() and self.peek_next().value == '=':
            name = self.consume('IDENT')
            self.consume('OP') # =
            expr = self.parse_expr()
            self.consume('OP') # ;
            return ('assign', name, expr)
        else:
            # Could be postfix [ expr ] = expr ; or expr ;
            node = self.parse_postfix()
            if self.peek() and self.peek().value == '=':
                self.consume() # =
                val_expr = self.parse_expr()
                self.consume('OP') # ;
                return ('assign_idx', node, val_expr)
            else:
                node = self.parse_expr_from_node(node)
                self.consume('OP') # ;
                return ('expr_stmt', node)

    def parse_if(self):
        self.consume() # if
        expr = self.parse_expr()
        block = self.parse_block()
        else_block = None
        if self.peek() and self.peek().value == 'else':
            self.consume()
            if self.peek() and self.peek().value == 'if':
                else_block = self.parse_if()
            else:
                else_block = self.parse_block()
        return ('if', expr, block, else_block)

    def parse_block(self):
        self.consume('OP') # {
        stmts = []
        while self.peek() and self.peek().value != '}':
            stmts.append(self.parse_stmt())
        self.consume('OP') # }
        return stmts

    def parse_expr(self):
        return self.parse_expr_from_node(self.parse_postfix())

    def parse_expr_from_node(self, node):
        node = self.parse_or(node)
        return node

    def parse_or(self, node):
        while self.peek() and self.peek().value == 'or':
            token = self.consume()
            right = self.parse_expr()
            node = ('or', node, right, token)
        return node

    def parse_and(self, node):
