        # The actual logic should be: parse_or calls parse_and, etc.
        # Since we are starting from a postfix, we must follow the hierarchy.
        pass # See updated logic below

    # Corrected precedence hierarchy
    def parse_expr_full(self, node=None):
        if node is None: node = self.parse_postfix()
        node = self.parse_or_level(node)
        return node

    def parse_or_level(self, node):
        while self.peek() and self.peek().value == 'or':
            token = self.consume()
            right = self.parse_expr_full()
            node = ('or', node, right, token)
        return node

    def parse_expr_from_node(self, node):
        # The hierarchy is: or -> and -> not -> comp -> add -> mul -> unary -> postfix
        # Since node is already a postfix, we go up.
        # Wait, the correct way is to treat the node as the result of the level below.
        node = self.parse_and_level(node)
        node = self.parse_or_level(node)
        return node

    def parse_and_level(self, node):
        while self.peek() and self.peek().value == 'and':
            token = self.consume()
            right = self.parse_unary_level()
