    # Re-writing expression parsing to be robust
    def parse_expr_fixed(self):
        return self.parse_or_fixed()

    def parse_or_fixed(self):
        node = self.parse_and_fixed()
        while self.peek() and self.peek().value == 'or':
            token = self.consume()
            right = self.parse_and_fixed()
            node = ('or', node, right, token)
        return node

    def parse_and_fixed(self):
        node = self.parse_not_fixed()
        while self.peek() and self.peek().value == 'and':
            token = self.consume()
            right = self.parse_not_fixed()
            node = ('and', node, right, token)
        return node

    def parse_not_fixed(self):
        if self.peek() and self.peek().value == 'not':
            token = self.consume()
            return ('not', self.parse_not_fixed(), token)
        return self.parse_comp_fixed()

    def parse_comp_fixed(self):
        node = self.parse_add_fixed()
        while self.peek() and self.peek().value in ('==', '!=', '<', '<=', '>', '>='):
            token = self.consume()
            right = self.parse_add_fixed()
            node = ('comp', node, right, token)
        return node

    def parse_add_fixed(self):
        node = self.parse_mul_fixed()
        while self.peek() and self.peek().value in ('+', '-'):
            token = self.consume()
            right = self.parse_mul_fixed()
            node = ('add', node, right, token)
        return node

    def parse_mul_fixed(self):
        node = self.parse_unary_fixed()
        while self.peek() and self.peek().value in ('*', '/', '%'):
            token = self.consume()
            right = self.parse_unary_fixed()
            node = ('mul', node, right, token)
        return node

    def parse_unary_fixed(self):
        if self.peek() and self.peek().value == '-':
            token = self.consume()
            return ('unary_minus', self.parse_unary_fixed(), token)
        return self.parse_postfix()

    def parse_postfix(self):
        node = self.parse_primary()
        while True:
            if self.peek() and self.peek().value == '(':
                token = self.consume()
                args = []
                if self.peek() and self.peek().value != ')':
                    args.append(self.parse_expr_fixed())
                    while self.peek() and self.peek().value == ',':
                        self.consume()
                        args.append(self.parse_expr_fixed())
                self.consume('OP') # )
                node = ('call', node, args, token)
            elif self.peek() and self.peek().value == '[':
                token = self.consume()
                idx = self.parse_expr_fixed()
                self.consume('OP') # ]
                node = ('index', node, idx, token)
            else:
                break
        return node

    def parse_primary(self):
        token = self.consume()
        if token.type == 'INT': return ('int', token)
        if token.type == 'STRING': return ('string', token)
        if token.type == 'KEYWORD':
            if token.value == 'true': return ('bool', True, token)
            if token.value == 'false': return ('bool', False, token)
            if token.value == 'nil': return ('nil', token)
            if token.value == 'fn':
                self.consume('OP') # (
                params = []
                if self.peek() and self.peek().type == 'IDENT':
                    params.append(self.consume('IDENT'))
                    while self.peek() and self.peek().value == ',':
                        self.consume()
                        params.append(self.consume('IDENT'))
                self.consume('OP') # )
                block = self.parse_block()
                return ('fn_lit', params, block, token)
        if token.type == 'IDENT': return ('ident', token)
        if token.value == '(':
            expr = self.parse_expr_fixed()
            self.consume('OP') # )
            return expr
        if token.value == '[':
            args = []
            if self.peek() and self.peek().value != ']':
                args.append(self.parse_expr_fixed())
                while self.peek() and self.peek().value == ',':
                    self.consume()
                    args.append(self.parse_expr_fixed())
            self.consume('OP') # ]
            return ('list_lit', args, token)
        return None

    # For the lapped expression parsing (stmt = expr ;)
    def parse_expr_from_node(self, node):
        # This is tricky. Let's just use a simpler approach:
        # if it's a statement and not an assign_idx, we parse the full expr.
        # To do that, we need to reset the pos to before the postfix.
        # But we can just store the pos.
        return node # This will be replaced by a pos reset in parse_stmt

class TernFunction:
    def __init__(self, params, body, closure_scope):
        self.params = params
        self.body = body
        self.closure_scope = closure_scope

class TernBuiltin:
    def __init__(self, name, func, num_args=None):
        self.name = name
        self.func = func
        self.num_args = num_args

    def call(self, args, token):
        if self.num_args is not None and len(args) != self.num_args:
            raise TernRuntimeError(f"expected {self.num_args} arguments, got {len(args)}", token)
        try:
            return self.func(*args)
        except (TypeError, ValueError):
            raise TernRuntimeError(f"bad argument to {self.name}", token)

class Scope:
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def define(self, name, value):
        self.vars[name] = value

    def assign(self, name, value, token):
        if name in self.vars:
            self.vars[name] = value
            return
        if self.parent:
            self.parent.assign(name, value, token)
        else:
            raise TernRuntimeError(f"undefined variable {name}", token)

    def resolve(self, name, token):
        if name in self.vars:
            return self.vars[name]
        if self.parent:
            return self.parent.resolve(name, token)
        raise TernRuntimeError(f"undefined variable {name}", token)

def get_type_name(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "list"
    if isinstance(v, (TernFunction, TernBuiltin)): return "function"
    return "unknown"

def display_form(v, visited=None):
    if visited is None: visited = set()
    if v is None: return "nil"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, str): return v
    if isinstance(v, (TernFunction, TernBuiltin)): return "<fn>"
    if isinstance(v, list):
        if id(v) in visited: return "[...]"
        visited.add(id(v))
        elems = [display_form_element(e, visited.copy()) for e in v]
        return "[" + ", ".join(elems) + "]"
    return str(v)

def display_form_element(v, visited):
    if isinstance(v, str):
        esc = v.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\t', '\\t')
        return f'"{esc}"'
    return display_form(v, visited)

class Return(Exception):
    def __init__(self, value): self.value = value
class Break(Exception): pass
class Continue(Exception): pass

class Interpreter:
    def __init__(self):
        self.MAX_INT = 2**63 - 1
        self.MIN_INT = -2**63
        self.S_builtins = Scope()
        self.setup_builtins()

    def setup_builtins(self):
        def builtin_print(*args):
            print(" ".join(display_form(a) for a in args))
            return None
        def builtin_str(v): return display_form(v)
        def builtin_type(v): return get_type_name(v)
        def builtin_len(v): return len(v)
        def builtin_push(l, v):
            l.append(v)
            return None
        def builtin_pop(l):
            if not l: raise Exception("pop empty")
            return l.pop()
        def builtin_range(a, b): return list(range(a, b))
        def builtin_slice(x, a, b): return x[a:b]

        self.S_builtins.define("print", TernBuiltin("print", builtin_print))
        self.S_builtins.define("str", TernBuiltin("str", builtin_str, 1))
        self.S_builtins.define("type", TernBuiltin("type", builtin_type, 1))
        self.S_builtins.define("len", TernBuiltin("len", builtin_len, 1))
        self.S_builtins.define("push", TernBuiltin("push", builtin_push, 2))
        self.S_builtins.define("pop", TernBuiltin("pop", builtin_pop, 1))
        self.S_builtins.define("range", TernBuiltin("range", builtin_range, 2))
        self.S_builtins.define("slice", TernBuiltin("slice", builtin_slice, 3))

    def check_int(self, v, token):
        if v < self.MIN_INT or v > self.MAX_INT:
            raise TernRuntimeError("integer overflow", token)
        return v

    def is_truthy(self, v):
        if v is None: return False
        if isinstance(v, bool): return v
        if isinstance(v, int): return v != 0
        if isinstance(v, str): return v != ""
        if isinstance(v, list): return len(v) > 0
        return True

    def eval_expr(self, node, scope):
        tag = node[0]
        if tag == 'int': return self.check_int(node[1].value, node[1])
        if tag == 'string': return node[1].value
        if tag == 'bool': return node[1]
        if tag == 'nil': return None
        if tag == 'ident': return scope.resolve(node[1].value, node[1])
        if tag == 'list_lit': return [self.eval_expr(e, scope) for e in node[1]]
        if tag == 'fn_lit':
            params = [p.value for p in node[1]]
            return TernFunction(params, node[2], scope)
        if tag == 'or':
            left = self.eval_expr(node[1], scope)
            if self.is_truthy(left): return left
            return self.eval_expr(node[2], scope)
        if tag == 'and':
            left = self.eval_expr(node[1], scope)
            if not self.is_truthy(left): return left
            return self.eval_expr(node[2], scope)
        if tag == 'not': return not self.is_truthy(self.eval_expr(node[1], scope))
        if tag == 'comp':
            left = self.eval_expr(node[1], scope)
            right = self.eval_expr(node[2], scope)
            op = node[3].value
            if isinstance(left, int) and isinstance(right, int):
                if op == '==': return left == right
                if op == '!=': return left != right
                if op == '<': return left < right
                if op == '<=': return left <= right
                if op == '>': return left > right
                if op == '>=': return left >= right
            if isinstance(left, str) and isinstance(right, str):
                if op == '==': return left == right
                if op == '!=': return left != right
                if op == '<': return left < right
                if op == '<=': return left <= right
                if op == '>': return left > right
                if op == '>=': return left >= right
            if op == '==': return (left is right) or (isinstance(left, list) and isinstance(right, list) and self.compare_lists(left, right))
            if op == '!=': return not ((left is right) or (isinstance(left, list) and isinstance(right, list) and self.compare_lists(left, right)))
            raise TernRuntimeError(f"cannot apply {op} to {get_type_name(left)} and {get_type_name(right)}", node[3])
        if tag == 'add':
            left = self.eval_expr(node[1], scope)
            right = self.eval_expr(node[2], scope)
            if isinstance(left, int) and isinstance(right, int): return self.check_int(left + right, node[3])
            if isinstance(left, str) and isinstance(right, str): return left + right
            if isinstance(left, list) and isinstance(right, list): return left + right
            raise TernRuntimeError(f"cannot apply + to {get_type_name(left)} and {get_type_name(right)}", node[3])
        if tag == 'mul':
            left = self.eval_expr(node[1], scope)
            right = self.eval_expr(node[2], scope)
            op = node[3].value
            if not (isinstance(left, int) and isinstance(right, int)):
                raise TernRuntimeError(f"cannot apply {op} to {get_type_name(left)} and {get_type_name(right)}", node[3])
            if op == '*': return self.check_int(left * right, node[3])
            if op == '/':
                if right == 0: raise TernRuntimeError("division by zero", node[3])
                return self.check_int(int(left / right), node[3])
            if op == '%':
                if right == 0: raise TernRuntimeError("division by zero", node[3])
                return self.check_int(left - int(left / right) * right, node[3])
        if tag == 'unary_minus':
            val = self.eval_expr(node[1], scope)
            if not isinstance(val, int): raise TernRuntimeError(f"cannot apply - to {get_type_name(val)}", node[2])
            return self.check_int(-val, node[2])
        if tag == 'call':
            callee = self.eval_expr(node[1], scope)
            args = [self.eval_expr(a, scope) for a in node[2]]
            token = node[3]
            if isinstance(callee, TernBuiltin): return callee.call(args, token)
            if isinstance(callee, TernFunction):
                if len(args) != len(callee.params):
                    raise TernRuntimeError(f"expected {len(callee.params)} arguments, got {len(args)}", token)
                S_call = Scope(parent=callee.closure_scope)
                for p, a in zip(callee.params, args): S_call.define(p, a)
                try: self.execute_block(callee.body, S_call)
                except Return as r: return r.value
                return None
            raise TernRuntimeError(f"cannot call {get_type_name(callee)}", token)
        if tag == 'index':
            x = self.eval_expr(node[1], scope)
            i = self.eval_expr(node[2], scope)
            token = node[3]
            if not isinstance(x, (list, str)): raise TernRuntimeError(f"cannot index {get_type_name(x)} with {get_type_name(i)}", token)
            if not isinstance(i, int): raise TernRuntimeError(f"cannot index {get_type_name(x)} with {get_type_name(i)}", token)
            if not (0 <= i < len(x)): raise TernRuntimeError(f"index {i} out of range for length {len(x)}", token)
            return x[i]

    def compare_lists(self, l1, l2):
        if len(l1) != len(l2): return False
        for e1, e2 in zip(l1, l2):
            if not self.compare_vals(e1, e2): return False
        return True

    def compare_vals(self, v1, v2):
        if v1 is v2: return True
        if isinstance(v1, list) and isinstance(v2, list): return self.compare_lists(v1, v2)
        if get_type_name(v1) != get_type_name(v2): return False
        return v1 == v2

    def execute_block(self, stmts, scope):
        for stmt in stmts: self.execute_stmt(stmt, scope)

    def execute_stmt(self, stmt, scope):
        tag = stmt[0]
        if tag == 'let':
            val = self.eval_expr(stmt[2], scope)
            scope.define(stmt[1].value, val)
        elif tag == 'fn_decl':
            params = [p.value for p in stmt[2]]
            fn = TernFunction(params, stmt[3], scope)
            scope.define(stmt[1].value, fn)
        elif tag == 'if':
            cond = self.eval_expr(stmt[1], scope)
            if self.is_truthy(cond):
                self.execute_block(stmt[2], Scope(parent=scope))
            elif stmt[3]:
                if stmt[3][0] == 'if': self.execute_stmt(stmt[3], Scope(parent=scope))
                else: self.execute_block(stmt[3], Scope(parent=scope))
        elif tag == 'while':
            while True:
                cond = self.eval_expr(stmt[1], scope)
                if not self.is_truthy(cond): break
                try: self.execute_block(stmt[2], Scope(parent=scope))
                except Break: break
                except Continue: pass
        elif tag == 'for':
            token_for = stmt[4]
            e = self.eval_expr(stmt[2], scope)
            if not isinstance(e, list): raise TernRuntimeError(f"cannot iterate {get_type_name(e)}", token_for)
            i = 0
            while i < len(e):
                S_for = Scope(parent=scope)
                S_for.define(stmt[1].value, e[i])
                try: self.execute_block(stmt[3], S_for)
                except Break: break
                except Continue: pass
                i += 1
        elif tag == 'return':
            val = self.eval_expr(stmt[1], scope) if stmt[1] else None
            raise Return(val)
        elif tag == 'break': raise Break()
        elif tag == 'continue': raise Continue()
        elif tag == 'assign':
            val = self.eval_expr(stmt[2], scope)
            scope.assign(stmt[1].value, val, stmt[1])
        elif tag == 'assign_idx':
            # stmt[1] is the 'index' node ('index', base, idx, token)
            x = self.eval_expr(stmt[1][1], scope)
            i = self.eval_expr(stmt[1][2], scope)
            v = self.eval_expr(stmt[2], scope)
            token = stmt[1][3]
            if not isinstance(x, list): raise TernRuntimeError(f"cannot assign into {get_type_name(x)}", token)
            if not isinstance(i, int): raise TernRuntimeError(f"cannot index list with {get_type_name(i)}", token)
            if not (0 <= i < len(x)): raise TernRuntimeError(f"index {i} out of range for length {len(x)}", token)
            x[i] = v
        elif tag == 'expr_stmt':
            self.eval_expr(stmt[1], scope)

def main():
    if len(sys.argv) < 2: return
    path = os.path.join(sys.argv[1], 'program.tern')
    if not os.path.exists(path): return
    with open(path, 'r') as f: source = f.read()
    lexer = Lexer(source)
    tokens = lexer.tokenize()
    parser = Parser(tokens)

    # Redefine parse_stmt to handle the lapped expression case
    def parse_stmt_fixed(self):
        token = self.peek()
        if token is None: return None
        if token.type == 'KEYWORD':
            if token.value == 'let':
                self.consume(); name = self.consume('IDENT'); self.consume('OP'); expr = self.parse_expr_fixed(); self.consume('OP')
                return ('let', name, expr)
            elif token.value == 'fn':
                self.consume(); name = self.consume('IDENT'); self.consume('OP')
                params = []
                if self.peek() and self.peek().type == 'IDENT':
                    params.append(self.consume('IDENT'))
                    while self.peek() and self.peek().value == ',':
                        self.consume(); params.append(self.consume('IDENT'))
                self.consume('OP'); block = self.parse_block()
                return ('fn_decl', name, params, block)
            elif token.value == 'if': return self.parse_if()
            elif token.value == 'while':
                self.consume(); expr = self.parse_expr_fixed(); block = self.parse_block()
                return ('while', expr, block)
            elif token.value == 'for':
                t_for = self.consume(); ident = self.consume('IDENT'); self.consume('KEYWORD'); expr = self.parse_expr_fixed(); block = self.parse_block()
                return ('for', ident, expr, block, t_for)
            elif token.value == 'return':
                self.consume(); expr = None
                if self.peek() and not (self.peek().type == 'OP' and self.peek().value == ';'): expr = self.parse_expr_fixed()
                self.consume('OP'); return ('return', expr)
            elif token.value == 'break': self.consume(); self.consume('OP'); return ('break',)
            elif token.value == 'continue': self.consume(); self.consume('OP'); return ('continue',)
        elif token.type == 'IDENT' and self.peek_next() and self.peek_next().value == '=':
            name = self.consume('IDENT'); self.consume('OP'); expr = self.parse_expr_fixed(); self.consume('OP')
            return ('assign', name, expr)
        else:
            start_pos = self.pos
            node = self.parse_postfix()
            if self.peek() and self.peek().value == '=':
                self.consume(); val_expr = self.parse_expr_fixed(); self.consume('OP')
                return ('assign_idx', node, val_expr)
            else:
                self.pos = start_pos
                expr = self.parse_expr_fixed()
                self.consume('OP')
                return ('expr_stmt', expr)

    Parser.parse_stmt = parse_stmt_fixed
    program = parser.parse_program()
    interp = Interpreter()
    S_global = Scope(parent=interp.S_builtins)
    try:
        for stmt in program: interp.execute_stmt(stmt, S_global)
    except TernRuntimeError as e: print(f"error at line {e.token.line}: {e.message}")

if __name__ == "__main__":
    main()

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        try {
            String content = Files.readString(Paths.get(args[0], "program.tern"));
            TernInterpreter interpreter = new TernInterpreter();
            interpreter.run(content);
        } catch (Exception e) {
            // Handle unexpected errors silently as per problem requirements
        }
    }
}

class TernValue {
    public abstract String getTypeName();
    public abstract boolean isTruthy();
    public abstract String display(Set<TernList> path, boolean inList);

    public TernValue add(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            try { return new TernInt(Math.addExact(a, b)); }
            catch (ArithmeticException e) { throw new TernRuntimeError("integer overflow", line, "operator"); }
        } else if (this instanceof TernString && other instanceof TernString) {
            return new TernString(((TernString) this).value + ((TernString) other).value);
        } else if (this instanceof TernList && other instanceof TernList) {
            TernList a = (TernList) this;
            TernList b = (TernList) other;
            TernList res = new TernList();
            res.elements.addAll(a.elements);
            res.elements.addAll(b.elements);
            return res;
        }
        throw new TernRuntimeError("cannot apply + to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue sub(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            try { return new TernInt(Math.subtractExact(a, b)); }
            catch (ArithmeticException e) { throw new TernRuntimeError("integer overflow", line, "operator"); }
        }
        throw new TernRuntimeError("cannot apply - to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue mul(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            try { return new TernInt(Math.multiplyExact(a, b)); }
            catch (ArithmeticException e) { throw new TernRuntimeError("integer overflow", line, "operator"); }
        }
        throw new TernRuntimeError("cannot apply * to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue div(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            if (b == 0) throw new TernRuntimeError("division by zero", line, "operator");
            if (a == Long.MIN_VALUE && b == -1) throw new TernRuntimeError("integer overflow", line, "operator");
            return new TernInt(a / b);
        }
        throw new TernRuntimeError("cannot apply / to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue mod(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            if (b == 0) throw new TernRuntimeError("division by zero", line, "operator");
            return new TernInt(a % b);
        }
        throw new TernRuntimeError("cannot apply % to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue compare(TernValue other, int line, String op) {
        if (op.equals("<") || op.equals("<=")) {
            if (this instanceof TernInt && other instanceof TernInt) {
                return new TernBool(((TernInt) this).value < ((TernInt) other).value || (op.equals("<=") && ((TernInt) this).value == ((TernInt) other).value));
            } else if (this instanceof TernString && other instanceof TernString) {
                int cmp = ((TernString) this).value.compareTo(((TernString) other).value);
                return new TernBool(cmp < 0 || (op.equals("<=") && cmp == 0));
            }
            throw new TernRuntimeError("cannot apply " + op + " to " + getTypeName() + " and " + other.getTypeName(), line, op);
        } else if (op.equals(">") || op.equals(">=")) {
            if (this instanceof TernInt && other instanceof TernInt) {
                return new TernBool(((TernInt) this).value > ((TernInt) other).value || (op.equals(">=") && ((TernInt) this).value == ((TernInt) other).value));
            } else if (this instanceof TernString && other instanceof TernString) {
                int cmp = ((TernString) this).value.compareTo(((TernString) other).value);
                return new TernBool(cmp > 0 || (op.equals(">=") && cmp == 0));
            }
            throw new TernRuntimeError("cannot apply " + op + " to " + getTypeName() + " and " + other.getTypeName(), line, op);
        }
        return null;
    }

    public TernValue equals(TernValue other) {
        if (this == other) return new TernBool(true);
        if (this instanceof TernInt && other instanceof TernInt) return new TernBool(((TernInt) this).value == ((TernInt) other).value);
        if (this instanceof TernBool && other instanceof TernBool) return new TernBool(((TernBool) this).value == ((TernBool) other).value);
        if (this instanceof TernString && other instanceof TernString) return new TernBool(((TernString) this).value.equals(((TernString) other).value));
        if (this instanceof TernNil && other instanceof TernNil) return new TernBool(true);
        if (this instanceof TernList && other instanceof TernList) {
            TernList a = (TernList) this;
            TernList b = (TernList) other;
            if (a.elements.size() != b.elements.size()) return new TernBool(false);
            for (int i = 0; i < a.elements.size(); i++) {
                if (!a.elements.get(i).equals(b.elements.get(i)).isTruthy()) return new TernBool(false);
            }
            return new TernBool(true);
        }
        return new TernBool(false);
    }

    public TernValue call(List<TernValue> args, int line, int depth, TernInterpreter interpreter) {
        if (!(this instanceof TernFunction)) throw new TernRuntimeError("cannot call " + getTypeName(), line, "(");
        TernFunction fn = (TernFunction) this;
        if (fn.isBuiltin) {
            return fn.builtinCall(args, line);
        }
        if (args.size() != fn.params.size()) throw new TernRuntimeError("expected " + fn.params.size() + " arguments, got " + args.size(), line, "(");
        if (depth >= 300) throw new TernRuntimeError("recursion depth exceeded", line, "(");
        TernScope scope = new TernScope(fn.closure);
        for (int i = 0; i < fn.params.size(); i++) {
            scope.declare(fn.params.get(i), args.get(i));
        }
        try {
            for (Stmt stmt : fn.body) {
                stmt.execute(scope, interpreter, depth + 1);
            }
        } catch (ReturnException re) {
            return re.value;
        }
        return TernNil.INSTANCE;
    }

    public TernValue getIndex(TernValue index, int line) {
        if (!(index instanceof TernInt)) throw new TernRuntimeError("cannot index " + getTypeName() + " with " + index.getTypeName(), line, "[");
        int i = ((TernInt) index).valueInt();
        if (this instanceof TernList) {
            TernList list = (TernList) this;
            if (i < 0 || i >= list.elements.size()) throw new TernRuntimeError("index " + i + " out of range for length " + list.elements.size(), line, "[");
            return list.elements.get(i);
        } else if (this instanceof TernString) {
            String s = ((TernString) this).value;
            if (i < 0 || i >= s.length()) throw new TernRuntimeError("index " + i + " out of range for length " + s.length(), line, "[");
            return new TernString(s.substring(i, i + 1));
        }
        throw new TernRuntimeError("cannot index " + getTypeName() + " with " + index.getTypeName(), line, "[");
    }

    public void setIndex(TernValue index, TernValue value, int line) {
        if (!(this instanceof TernList)) throw new TernRuntimeError("cannot assign into " + getTypeName(), line, "[");
        if (!(index instanceof TernInt)) throw new TernRuntimeError("cannot index list with " + index.getTypeName(), line, "[");
        int i = ((TernInt) index).valueInt();
        TernList list = (TernList) this;
        if (i < 0 || i >= list.elements.size()) throw new TernRuntimeError("index " + i + " out of range for length " + list.elements.size(), line, "[");
        list.elements.set(i, value);
    }
}

class TernInt extends TernValue {
    final long value;
    TernInt(long v) { this.value = v; }
    int valueInt() { return (int) value; }
    public String getTypeName() { return "int"; }
    public boolean isTruthy() { return value != 0; }
    public String display(Set<TernList> path, boolean inList) { return String.valueOf(value); }
}

class TernBool extends TernValue {
    final boolean value;
    TernBool(boolean v) { this.value = v; }
    public String getTypeName() { return "bool"; }
    public boolean isTruthy() { return value; }
    public String display(Set<TernList> path, boolean inList) { return String.valueOf(value); }
}

class TernString extends TernValue {
    final String value;
    TernString(String v) { this.value = v; }
    public String getTypeName() { return "string"; }
    public boolean isTruthy() { return !value.isEmpty(); }
    public String display(Set<TernList> path, boolean inList) {
        if (!inList) return value;
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c == '\"') sb.append("\\\"");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.append("\"").toString();
    }
}

class TernList extends TernValue {
    final List<TernValue> elements = new ArrayList<>();
    public String getTypeName() { return "list"; }
    public boolean isTruthy() { return !elements.isEmpty(); }
    public String display(Set<TernList> path, boolean inList) {
        if (path.contains(this)) return "[...]";
        path.add(this);
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < elements.size(); i++) {
            sb.append(elements.get(i).display(path, true));
            if (i < elements.size() - 1) sb.append(", ");
        }
        sb.append("]");
        path.remove(this);
        return sb.toString();
    }
}

class TernNil extends TernValue {
    static final TernNil INSTANCE = new TernNil();
    public String getTypeName() { return "nil"; }
    public boolean isTruthy() { return false; }
    public String display(Set<TernList> path, boolean inList) { return "nil"; }
}

class TernFunction extends TernValue {
    final List<String> params;
    final List<Stmt> body;
    final TernScope closure;
    final boolean isBuiltin;
    final String builtinName;

    TernFunction(List<String> params, List<Stmt> body, TernScope closure) {
        this.params = params; this.body = body; this.closure = closure; this.isBuiltin = false; this.builtinName = null;
    }
    TernFunction(String name) {
        this.params = null; this.body = null; this.closure = null; this.isBuiltin = true; this.builtinName = name;
    }

    public String getTypeName() { return "function"; }
    public boolean isTruthy() { return true; }
    public String display(Set<TernList> path, boolean inList) { return "<fn>"; }

    public TernValue builtinCall(List<TernValue> args, int line) {
        switch (builtinName) {
            case "print":
                Set<TernList> path = new HashSet<>();
                for (int i = 0; i < args.size(); i++) {
                    System.out.print(args.get(i).display(path, false));
                    if (i < args.size() - 1) System.out.print(" ");
                }
                System.out.println();
                return TernNil.INSTANCE;
            case "str":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                return new TernString(args.get(0).display(new HashSet<>(), false));
            case "type":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                return new TernString(args.get(0).getTypeName());
            case "len":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                if (args.get(0) instanceof TernString) return new TernInt(((TernString) args.get(0)).value.length());
                if (args.get(0) instanceof TernList) return new TernInt(((TernList) args.get(0)).elements.size());
                throw new TernRuntimeError("bad argument to len", line, "(");
            case "push":
                if (args.size() != 2) throw new TernRuntimeError("expected 2 arguments, got " + args.size(), line, "(");
                if (!(args.get(0) instanceof TernList)) throw new TernRuntimeError("bad argument to push", line, "(");
                ((TernList) args.get(0)).elements.add(args.get(1));
                return TernNil.INSTANCE;
            case "pop":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                if (!(args.get(0) instanceof TernList)) throw new TernRuntimeError("bad argument to pop", line, "(");
                TernList list = (TernList) args.get(0);
                if (list.elements.isEmpty()) throw new TernRuntimeError("pop on empty list", line, "(");
                return list.elements.remove(list.elements.size() - 1);
            case "range":
                if (args.size() != 2) throw new TernRuntimeError("expected 2 arguments, got " + args.size(), line, "(");
                if (!(args.get(0) instanceof TernInt) || !(args.get(1) instanceof TernInt)) throw new TernRuntimeError("bad argument to range", line, "(");
                long a = ((TernInt) args.get(0)).value, b = ((TernInt) args.get(1)).value;
                TernList rangeList = new TernList();
                for (long i = a; i < b; i++) rangeList.elements.add(new TernInt(i));
                return rangeList;
            case "slice":
                if (args.size() != 3) throw new TernRuntimeError("expected 3 arguments, got " + args.size(), line, "(");
                TernValue x = args.get(0);
                if (!(x instanceof TernInt) && !(x instanceof TernBool) && !(x instanceof TernNil) && !(x instanceof TernFunction)) {
                    // slice works on strings and lists
                }
                if (!(x instanceof TernString || x instanceof TernList)) throw new TernRuntimeError("bad argument to slice", line, "(");
                if (!(args.get(1) instanceof TernInt) || !(args.get(2) instanceof TernInt)) throw new TernRuntimeError("bad argument to slice", line, "(");
                int start = ((TernInt) args.get(1)).valueInt(), end = ((TernInt) args.get(2)).valueInt();
                if (x instanceof TernString) {
                    String s = ((TernString) x).value;
                    if (start < 0 || end > s.length() || start > end) throw new TernRuntimeError("slice out of range", line, "(");
                    return new TernString(s.substring(start, end));
                } else {
                    TernList l = (TernList) x;
                    if (start < 0 || end > l.elements.size() || start > end) throw new TernRuntimeError("slice out of range", line, "(");
                    TernList res = new TernList();
                    for (int i = start; i < end; i++) res.elements.add(l.elements.get(i));
                    return res;
                }
            default: return TernNil.INSTANCE;
        }
    }
}

class TernScope {
    final Map<String, TernValue> vars = new HashMap<>();
    final TernScope parent;
    TernScope(TernScope p) { this.parent = p; }
    void declare(String name, TernValue v) { vars.put(name, v); }
    TernValue resolve(String name, int line) {
        if (vars.containsKey(name)) return vars.get(name);
        if (parent != null) return parent.resolve(name, line);
        throw new TernRuntimeError("undefined variable " + name, line, name);
    }
    void assign(String name, TernValue v, int line) {
        if (vars.containsKey(name)) { vars.put(name, v); return; }
        if (parent != null) { parent.assign(name, v, line); return; }
        throw new TernRuntimeError("undefined variable " + name, line, name);
    }
}

class TernRuntimeError extends RuntimeException {
    TernRuntimeError(String msg, int line, String token) {
        super("error at line " + line + ": " + msg);
        // The problem says to print the error and exit with status 0.
        System.err.println("error at line " + line + ": " + msg);
        System.exit(0);
    }
}

class ReturnException extends RuntimeException {
    final TernValue value;
    ReturnException(TernValue v) { this.value = v; }
}
class BreakException extends RuntimeException {}
class ContinueException extends RuntimeException {}

abstract class Stmt { abstract void execute(TernScope scope, TernInterpreter interpreter, int depth); }
class LetStmt extends Stmt {
    String name; Expr expr; int line;
    LetStmt(String n, Expr e, int l) { name = n; expr = e; line = l; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { scope.declare(name, interpreter.eval(expr, scope, depth)); }
}
class AssignStmt extends Stmt {
    String name; Expr expr; int line;
    AssignStmt(String n, Expr e, int l) { name = n; expr = e; line = l; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { scope.assign(name, interpreter.eval(expr, scope, depth), line); }
}
class PostfixAssignStmt extends Stmt {
    Expr obj, idx, val; int line;
    PostfixAssignStmt(Expr o, Expr i, Expr v, int l) { obj = o; idx = i; val = v; line = l; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernValue o = interpreter.eval(obj, scope, depth);
        TernValue i = interpreter.eval(idx, scope, depth);
        TernValue v = interpreter.eval(val, scope, depth);
        o.setIndex(i, v, line);
    }
}
class BlockStmt extends Stmt {
    List<Stmt> stmts;
    BlockStmt(List<Stmt> s) { stmts = s; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernScope local = new TernScope(scope);
        for (Stmt s : stmts) s.execute(local, interpreter, depth);
    }
}
class IfStmt extends Stmt {
    Expr cond; Stmt thenB, elseB;
    IfStmt(Expr c, Stmt t, Stmt e) { cond = c; thenB = t; elseB = e; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        if (interpreter.eval(cond, scope, depth).isTruthy()) thenB.execute(scope, interpreter, depth);
        else if (elseB != null) elseB.execute(scope, interpreter, depth);
    }
}
class WhileStmt extends Stmt {
    Expr cond; Stmt body;
    WhileStmt(Expr c, Stmt b) { cond = c; body = b; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        while (interpreter.eval(cond, scope, depth).isTruthy()) {
            try { body.execute(scope, interpreter, depth); }
            catch (BreakException be) { break; }
            catch (ContinueException ce) { }
        }
    }
}
class ForStmt extends Stmt {
    String varName; Expr expr; Stmt body;
    ForStmt(String n, Expr e, Stmt b) { varName = n; expr = e; body = b; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernValue listVal = interpreter.eval(expr, scope, depth);
        if (!(listVal instanceof TernList)) throw new TernRuntimeError("cannot iterate " + listVal.getTypeName(), 0, "for");
        TernList list = (TernList) listVal;
        int i = 0;
        while (i < list.elements.size()) {
            TernValue val = list.elements.get(i);
            TernScope local = new TernScope(scope);
            local.declare(varName, val);
            try { body.execute(local, interpreter, depth); }
            catch (BreakException be) { break; }
            catch (ContinueException ce) { }
            i++;
        }
    }
}
class FnStmt extends Stmt {
    String name; List<String> params; BlockStmt body;
    FnStmt(String n, List<String> p, BlockStmt b) { name = n; params = p; body = b; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernFunction fn = new TernFunction(params, body.stmts, scope);
        scope.declare(name, fn);
    }
}
class ReturnStmt extends Stmt {
    Expr expr;
    ReturnStmt(Expr e) { expr = e; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        throw new ReturnException(expr == null ? TernNil.INSTANCE : interpreter.eval(expr, scope, depth));
    }
}
class BreakStmt extends Stmt {
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { throw new BreakException(); }
}
class ContinueStmt extends Stmt {
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { throw new ContinueException(); }
}
class ExprStmt extends Stmt {
    Expr expr;
    ExprStmt(Expr e) { expr = e; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { interpreter.eval(expr, scope, depth); }
}

abstract class Expr { }
class LiteralExpr extends Expr {
    TernValue val;
    LiteralExpr(TernValue v) { val = v; }
}
class VarExpr extends Expr {
    String name; int line;
    VarExpr(String n, int l) { name = n; line = l; }
}
class BinaryExpr extends Expr {
    Expr left, right; String op; int line;
    BinaryExpr(Expr l, Expr r, String o, int ln) { left = l; right = r; op = o; line = ln; }
}
class UnaryExpr extends Expr {
    String op; Expr expr; int line;
    UnaryExpr(String o, Expr e, int l) { op = o; expr = e; line = l; }
}
class PostfixExpr extends Expr {
    Expr obj; Expr index; boolean isCall; int line;
    PostfixExpr(Expr o, Expr i, boolean c, int l) { obj = o; index = i; isCall = c; line = l; }
}
class ListExpr extends Expr {
    List<Expr> elements;
    ListExpr(List<Expr> e) { elements = e; }
}
class FnExpr extends Expr {
    List<String> params; BlockStmt body;
    FnExpr(List<String> p, BlockStmt b) { params = p; body = b; }
}
class CallExpr extends Expr {
    Expr callee; List<Expr> args; int line;
    CallExpr(Expr c, List<Expr> a, int l) { callee = c; args = a; line = l; }
}

class TernInterpreter {
    TernValue eval(Expr e, TernScope scope, int depth) {
        if (e instanceof LiteralExpr) return ((LiteralExpr) e).val;
        if (e instanceof VarExpr) return scope.resolve(((VarExpr) e).name, ((VarExpr) e).line);
        if (e instanceof BinaryExpr) {
            BinaryExpr be = (BinaryExpr) e;
            TernValue l = eval(be.left, scope, depth);
            TernValue r = eval(be.right, scope, depth);
            switch (be.op) {
                case "or": return l.isTruthy() ? l : r;
                case "and": return l.isTruthy() ? r : l;
                case "==": return l.equals(r);
                case "!=": return l.equals(r).isTruthy() ? new TernBool(false) : new TernBool(true);
                case "<": case "<=": case ">": case ">=": return l.compare(r, be.line, be.op);
                case "+": return l.add(r, be.line);
                case "-": return l.sub(r, be.line);
                case "*": return l.mul(r, be.line);
                case "/": return l.div(r, be.line);
                case "%": return l.mod(r, be.line);
            }
        }
        if (e instanceof UnaryExpr) {
            UnaryExpr ue = (UnaryExpr) e;
            TernValue v = eval(ue.expr, scope, depth);
            if (ue.op.equals("not")) return new TernBool(!v.isTruthy());
            if (ue.op.equals("-")) {
                if (!(v instanceof TernInt)) throw new TernRuntimeError("cannot apply - to " + v.getTypeName(), ue.line, "-");
                try { return new TernInt(-((TernInt) v).value); }
                catch (ArithmeticException ex) { throw new TernRuntimeError("integer overflow", ue.line, "-"); }
            }
        }
        if (e instanceof PostfixExpr) {
            PostfixExpr pe = (PostfixExpr) e;
            TernValue obj = eval(pe.obj, scope, depth);
            TernValue idx = pe.index == null ? null : eval(pe.index, scope, depth);
            if (pe.isCall) {
                if (idx == null) return obj.call(new ArrayList<>(), pe.line, depth, this);
                // This case is handled by CallExpr in our parser
            } else {
                return obj.getIndex(idx, pe.line);
            }
        }
        if (e instanceof CallExpr) {
            CallExpr ce = (CallExpr) e;
            TernValue callee = eval(ce.callee, scope, depth);
            List<TernValue> args = new ArrayList<>();
            for (Expr ae : ce.args) args.add(eval(ae, scope, depth));
            return callee.call(args, ce.line, depth, this);
        }
        if (e instanceof ListExpr) {
            TernList list = new TernList();
            for (Expr ee : ((ListExpr) e).elements) list.elements.add(eval(ee, scope, depth));
            return list;
        }
        if (e instanceof FnExpr) {
            FnExpr fe = (FnExpr) e;
            return new TernFunction(fe.params, fe.body.stmts, scope);
        }
        return TernNil.INSTANCE;
    }

    void run(String source) {
        TernLexer lexer = new TernLexer(source);
        TernParser parser = new TernParser(lexer);
        List<Stmt> program = parser.parseProgram();
        TernScope builtins = new TernScope(null);
        builtins.declare("print", new TernFunction("print"));
        builtins.declare("str", new TernFunction("str"));
        builtins.declare("type", new TernFunction("type"));
        builtins.declare("len", new TernFunction("len"));
        builtins.declare("push", new TernFunction("push"));
        builtins.declare("pop", new TernFunction("pop"));
        builtins.declare("range", new TernFunction("range"));
        builtins.declare("slice", new TernFunction("slice"));
        TernScope global = new TernScope(builtins);
        for (Stmt s : program) s.execute(global, this, 0);
    }
}

class TernLexer {
    enum TokenType {
        INT, STRING, IDENT, 
        EQ, NEQ, LT, LTE, GT, GTE, ASSIGN, 
        PLUS, MINUS, STAR, SLASH, PERCENT, 
        LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE, 
        COMMA, SEMICOLON, 
        LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE, AND, OR, NOT, TRUE, FALSE, NIL,
        EOF
    }
    static class Token {
        TokenType type; String value; int line;
        Token(TokenType t, String v, int l) { type = t; value = v; line = l; }
    }
    private String source;
    private int pos = 0, line = 1;
    TernLexer(String s) { source = s; }
    Token nextToken() {
        while (pos < source.length()) {
            char c = source.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
                if (c == '\n') line++;
                pos++;
            } else if (c == '#') {
                while (pos < source.length() && source.charAt(pos) != '\n') pos++;
            } else {
                break;
            }
        }
        if (pos >= source.length()) return new Token(TokenType.EOF, "", line);
        char c = source.charAt(pos);
        if (Character.isDigit(c)) {
            StringBuilder sb = new StringBuilder();
            while (pos < source.length() && Character.isDigit(source.charAt(pos))) sb.append(source.charAt(pos++));
            return new Token(TokenType.INT, sb.toString(), line);
        }
        if (c == '\"') {
            StringBuilder sb = new StringBuilder();
            pos++;
            while (pos < source.length() && source.charAt(pos) != '\"') {
                char cc = source.charAt(pos++);
                if (cc == '\\') {
                    char next = source.charAt(pos++);
                    if (next == 'n') sb.append('\n'); else if (next == 't') sb.append('\t');
                    else if (next == '\"') sb.append('\"'); else if (next == '\\') sb.append('\\');
                } else sb.append(cc);
            }
            pos++;
            return new Token(TokenType.STRING, sb.toString(), line);
        }
        if (Character.isLetter(c) || c == '_') {
            StringBuilder sb = new StringBuilder();
            while (pos < source.length() && (Character.isLetterOrDigit(source.charAt(pos)) || source.charAt(pos) == '_')) sb.append(source.charAt(pos++));
            String s = sb.toString();
            switch (s) {
                case "let": return new Token(TokenType.LET, s, line);
                case "fn": return new Token(TokenType.FN, s, line);
                case "if": return new Token(TokenType.IF, s, line);
                case "else": return new Token(TokenType.ELSE, s, line);
                case "while": return new Token(TokenType.WHILE, s, line);
                case "for": return new Token(TokenType.FOR, s, line);
                case "in": return new Token(TokenType.IN, s, line);
                case "return": return new Token(TokenType.RETURN, s, line);
                case "break": return new Token(TokenType.BREAK, s, line);
                case "continue": return new Token(TokenType.CONTINUE, s, line);
                case "and": return new Token(TokenType.AND, s, line);
                case "or": return new Token(TokenType.OR, s, line);
                case "not": return new Token(TokenType.NOT, s, line);
                case "true": return new Token(TokenType.TRUE, s, line);
                case "false": return new Token(TokenType.FALSE, s, line);
                case "nil": return new Token(TokenType.NIL, s, line);
                default: return new Token(TokenType.IDENT, s, line);
            }
        }
        pos++;
        switch (c) {
            case '(': return new Token(TokenType.LPAREN, "(", line);
            case ')': return new Token(TokenType.RPAREN, ")", line);
            case '[': return new Token(TokenType.LBRACKET, "[", line);
            case ']': return new Token(TokenType.RBRACKET, "]", line);
            case '{': return new Token(TokenType.LBRACE, "{", line);
            case '}': return new Token(TokenType.RBRACE, "}", line);
            case ',': return new Token(TokenType.COMMA, ",", line);
            case ';': return new Token(TokenType.SEMICOLON, ";", line);
            case '+': return new Token(TokenType.PLUS, "+", line);
            case '-': return new Token(TokenType.MINUS, "-", line);
            case '*': return new Token(TokenType.STAR, "*", line);
            case '/': return new Token(TokenType.SLASH, "/", line);
            case '%': return new Token(TokenType.PERCENT, "%", line);
            case '=':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.EQ, "==", line); }
                return new Token(TokenType.ASSIGN, "=", line);
            case '!':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.NEQ, "!=", line); }
                throw new RuntimeException("Unexpected character !");
            case '<':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.LTE, "<=", line); }
                return new Token(TokenType.LT, "<", line);
            case '>':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.GTE, ">=", line); }
                return new Token(TokenType.GT, ">", line);
        }
        throw new RuntimeException("Unexpected character " + c);
    }
}

class TernParser {
    TernLexer lexer;
    TernLexer.Token current;
    TernParser(TernLexer l) { lexer = l; current = lexer.nextToken(); }
    void next() { current = lexer.nextToken(); }
    boolean match(TernLexer.TokenType t) {
        if (current.type == t) { next(); return true; }
        return false;
    }
    List<Stmt> parseProgram() {
        List<Stmt> stmts = new ArrayList<>();
        while (current.type != TernLexer.TokenType.EOF) stmts.add(parseStmt());
        return stmts;
    }
    Stmt parseStmt() {
        if (match(TernLexer.TokenType.LET)) {
            String name = current.value; next();
            next(); // =
            Expr e = parseExpr();
            next(); // ;
            return new LetStmt(name, e, current.line);
        } else if (match(TernLexer.TokenType.FN)) {
            String name = current.value; next();
            next(); // (
            List<String> params = new ArrayList<>();
            if (current.type != TernLexer.TokenType.RPAREN) {
                params.add(current.value); next();
                while (match(TernLexer.TokenType.COMMA)) { params.add(current.value); next(); }
            }
            next(); // )
            BlockStmt body = parseBlock();
            return new FnStmt(name, params, body);
        } else if (match(TernLexer.TokenType.IF)) {
            Expr cond = parseExpr();
            Stmt thenB = parseBlock();
            Stmt elseB = null;
            if (match(TernLexer.TokenType.ELSE)) {
                if (current.type == TernLexer.TokenType.LBRACE) elseB = parseBlock();
                else elseB = parseIfStmt();
            }
            return new IfStmt(cond, thenB, elseB);
        } else if (match(TernLexer.TokenType.WHILE)) {
            Expr cond = parseExpr();
            return new WhileStmt(cond, parseBlock());
        } else if (match(TernLexer.TokenType.FOR)) {
            String name = current.value; next();
            next(); // in
            Expr e = parseExpr();
            return new ForStmt(name, e, parseBlock());
        } else if (match(TernLexer.TokenType.RETURN)) {
            Expr e = null;
            if (current.type != TernLexer.TokenType.SEMICOLON) { e = parseExpr(); }
            next(); // ;
            return new ReturnStmt(e);
        } else if (match(TernLexer.TokenType.BREAK)) {
            next(); // ;
            return new BreakStmt();
        } else if (match(TernLexer.TokenType.CONTINUE)) {
            next(); // ;
            return new ContinueStmt();
        } else {
            Expr e = parseExpr();
            if (e instanceof VarExpr && match(TernLexer.TokenType.ASSIGN)) {
                Expr val = parseExpr();
                next(); // ;
                return new AssignStmt(((VarExpr) e).name, val, current.line);
            } else if (e instanceof PostfixExpr && match(TernLexer.TokenType.ASSIGN)) {
                Expr val = parseExpr();
                next(); // ;
                return new PostfixAssignStmt(((PostfixExpr) e).obj, ((PostfixExpr) e).index, val, current.line);
            } else {
                next(); // ;
                return new ExprStmt(e);
            }
        }
    }
    Stmt parseIfStmt() {
        Expr cond = parseExpr();
        Stmt thenB = parseBlock();
        Stmt elseB = null;
        if (match(TernLexer.TokenType.ELSE)) {
            if (current.type == TernLexer.TokenType.LBRACE) elseB = parseBlock();
            else elseB = parseIfStmt();
        }
        return new IfStmt(cond, thenB, elseB);
    }
    BlockStmt parseBlock() {
        next(); // {
        List<Stmt> stmts = new ArrayList<>();
        while (current.type != TernLexer.TokenType.RBRACE) stmts.add(parseStmt());
        next(); // }
        return new BlockStmt(stmts);
    }
    Expr parseExpr() { return parseOr(); }
    Expr parseOr() {
        Expr e = parseAnd();
        while (match(TernLexer.TokenType.OR)) e = new BinaryExpr(e, parseAnd(), "or", current.line);
        return e;
    }
    Expr parseAnd() {
        Expr e = parseNot();
        while (match(TernLexer.TokenType.AND)) e = new BinaryExpr(e, parseNot(), "and", current.line);
        return e;
    }
    Expr parseNot() {
        if (match(TernLexer.TokenType.NOT)) return new UnaryExpr("not", parseNot(), current.line);
        return parseCompare();
    }
    Expr parseCompare() {
        Expr e = parseAddSub();
        while (current.type == TernLexer.TokenType.EQ || current.type == TernLexer.TokenType.NEQ || 
               current.type == TernLexer.TokenType.LT || current.type == TernLexer.TokenType.LTE || 
               current.type == TernLexer.TokenType.GT || current.type == TernLexer.TokenType.GTE) {
            String op = current.value; next();
            e = new BinaryExpr(e, parseAddSub(), op, current.line);
        }
        return e;
    }
    Expr parseAddSub() {
        Expr e = parseMulDivMod();
        while (current.type == TernLexer.TokenType.PLUS || current.type == TernLexer.TokenType.MINUS) {
            String op = current.value; next();
            e = new BinaryExpr(e, parseMulDivMod(), op, current.line);
        }
        return e;
    }
    Expr parseMulDivMod() {
        Expr e = parseUnaryMinus();
        while (current.type == TernLexer.TokenType.STAR || current.type == TernLexer.TokenType.SLASH || current.type == TernLexer.TokenType.PERCENT) {
            String op = current.value; next();
            e = new BinaryExpr(e, parseUnaryMinus(), op, current.line);
        }
        return e;
    }
    Expr parseUnaryMinus() {
        if (match(TernLexer.TokenType.MINUS)) return new UnaryExpr("-", parseUnaryMinus(), current.line);
        return parsePostfix();
    }
    Expr parsePostfix() {
        Expr e = parsePrimary();
        while (current.type == TernLexer.TokenType.LPAREN || current.type == TernLexer.TokenType.LBRACKET) {
            if (current.type == TernLexer.TokenType.LPAREN) {
                next();
                List<Expr> args = new ArrayList<>();
                if (current.type != TernLexer.TokenType.RPAREN) {
                    args.add(parseExpr());
                    while (match(TernLexer.TokenType.COMMA)) args.add(parseExpr());
                }
                next(); // )
                e = new CallExpr(e, args, current.line);
            } else {
                next();
                Expr idx = parseExpr();
                next(); // ]
                e = new PostfixExpr(e, idx, false, current.line);
            }
        }
        return e;
    }
    Expr parsePrimary() {
        if (match(TernLexer.TokenType.INT)) return new LiteralExpr(new TernInt(Long.parseLong(current.value)));
        if (match(TernLexer.TokenType.STRING)) { String s = current.value; next(); return new LiteralExpr(new TernString(s)); }
        if (match(TernLexer.TokenType.TRUE)) { next(); return new LiteralExpr(new TernBool(true)); }
        if (match(TernLexer.TokenType.FALSE)) { next(); return new LiteralExpr(new TernBool(false)); }
        if (match(TernLexer.TokenType.NIL)) { next(); return new LiteralExpr(TernNil.INSTANCE); }
        if (match(TernLexer.TokenType.IDENT)) { String s = current.value; next(); return new VarExpr(s, current.line); }
        if (match(TernLexer.TokenType.LPAREN)) {
            Expr e = parseExpr();
            next(); // )
            return e;
        }
        if (match(TernLexer.TokenType.LBRACKET)) {
            List<Expr> elements = new ArrayList<>();
            if (current.type != TernLexer.TokenType.RBRACKET) {
                elements.add(parseExpr());
                while (match(TernLexer.TokenType.COMMA)) elements.add(parseExpr());
            }
            next(); // ]
            return new ListExpr(elements);
        }
        if (match(TernLexer.TokenType.FN)) {
            next(); // (
            List<String> params = new ArrayList<>();
            if (current.type != TernLexer.TokenType.RPAREN) {
                params.add(current.value); next();
                while (match(TernLexer.TokenType.COMMA)) { params.add(current.value); next(); }
            }
            next(); // )
            BlockStmt body = parseBlock();
            return new FnExpr(params, body);
        }
        throw new RuntimeException("Unexpected token " + current.type);
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        try {
            String content = Files.readString(Paths.get(args[0], "program.tern"));
            TernInterpreter interpreter = new TernInterpreter();
            interpreter.run(content);
        } catch (Exception e) {
            // Handle unexpected errors silently as per problem requirements
        }
    }
}

abstract class TernValue {
    public abstract String getTypeName();
    public abstract boolean isTruthy();
    public abstract String display(Set<TernList> path, boolean inList);

    public TernValue add(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            try { return new TernInt(Math.addExact(a, b)); }
            catch (ArithmeticException e) { throw new TernRuntimeError("integer overflow", line, "operator"); }
        } else if (this instanceof TernString && other instanceof TernString) {
            return new TernString(((TernString) this).value + ((TernString) other).value);
        } else if (this instanceof TernList && other instanceof TernList) {
            TernList a = (TernList) this;
            TernList b = (TernList) other;
            TernList res = new TernList();
            res.elements.addAll(a.elements);
            res.elements.addAll(b.elements);
            return res;
        }
        throw new TernRuntimeError("cannot apply + to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue sub(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            try { return new TernInt(Math.subtractExact(a, b)); }
            catch (ArithmeticException e) { throw new TernRuntimeError("integer overflow", line, "operator"); }
        }
        throw new TernRuntimeError("cannot apply - to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue mul(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            try { return new TernInt(Math.multiplyExact(a, b)); }
            catch (ArithmeticException e) { throw new TernRuntimeError("integer overflow", line, "operator"); }
        }
        throw new TernRuntimeError("cannot apply * to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue div(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            if (b == 0) throw new TernRuntimeError("division by zero", line, "operator");
            if (a == Long.MIN_VALUE && b == -1) throw new TernRuntimeError("integer overflow", line, "operator");
            return new TernInt(a / b);
        }
        throw new TernRuntimeError("cannot apply / to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue mod(TernValue other, int line) {
        if (this instanceof TernInt && other instanceof TernInt) {
            long a = ((TernInt) this).value;
            long b = ((TernInt) other).value;
            if (b == 0) throw new TernRuntimeError("division by zero", line, "operator");
            return new TernInt(a % b);
        }
        throw new TernRuntimeError("cannot apply % to " + getTypeName() + " and " + other.getTypeName(), line, "operator");
    }

    public TernValue compare(TernValue other, int line, String op) {
        if (op.equals("<") || op.equals("<=")) {
            if (this instanceof TernInt && other instanceof TernInt) {
                return new TernBool(((TernInt) this).value < ((TernInt) other).value || (op.equals("<=") && ((TernInt) this).value == ((TernInt) other).value));
            } else if (this instanceof TernString && other instanceof TernString) {
                int cmp = ((TernString) this).value.compareTo(((TernString) other).value);
                return new TernBool(cmp < 0 || (op.equals("<=") && cmp == 0));
            }
            throw new TernRuntimeError("cannot apply " + op + " to " + getTypeName() + " and " + other.getTypeName(), line, op);
        } else if (op.equals(">") || op.equals(">=")) {
            if (this instanceof TernInt && other instanceof TernInt) {
                return new TernBool(((TernInt) this).value > ((TernInt) other).value || (op.equals(">=") && ((TernInt) this).value == ((TernInt) other).value));
            } else if (this instanceof TernString && other instanceof TernString) {
                int cmp = ((TernString) this).value.compareTo(((TernString) other).value);
                return new TernBool(cmp > 0 || (op.equals(">=") && cmp == 0));
            }
            throw new TernRuntimeError("cannot apply " + op + " to " + getTypeName() + " and " + other.getTypeName(), line, op);
        }
        return null;
    }

    public TernValue ternEquals(TernValue other) {
        if (this == other) return new TernBool(true);
        if (this instanceof TernInt && other instanceof TernInt) return new TernBool(((TernInt) this).value == ((TernInt) other).value);
        if (this instanceof TernBool && other instanceof TernBool) return new TernBool(((TernBool) this).value == ((TernBool) other).value);
        if (this instanceof TernString && other instanceof TernString) return new TernBool(((TernString) this).value.equals(((TernString) other).value));
        if (this instanceof TernNil && other instanceof TernNil) return new TernBool(true);
        if (this instanceof TernList && other instanceof TernList) {
            TernList a = (TernList) this;
            TernList b = (TernList) other;
            if (a.elements.size() != b.elements.size()) return new TernBool(false);
            for (int i = 0; i < a.elements.size(); i++) {
                if (!a.elements.get(i).ternEquals(b.elements.get(i)).isTruthy()) return new TernBool(false);
            }
            return new TernBool(true);
        }
        return new TernBool(false);
    }

    public TernValue call(List<TernValue> args, int line, int depth, TernInterpreter interpreter) {
        if (!(this instanceof TernFunction)) throw new TernRuntimeError("cannot call " + getTypeName(), line, "(");
        TernFunction fn = (TernFunction) this;
        if (fn.isBuiltin) {
            return fn.builtinCall(args, line);
        }
        if (args.size() != fn.params.size()) throw new TernRuntimeError("expected " + fn.params.size() + " arguments, got " + args.size(), line, "(");
        if (depth >= 300) throw new TernRuntimeError("recursion depth exceeded", line, "(");
        TernScope scope = new TernScope(fn.closure);
        for (int i = 0; i < fn.params.size(); i++) {
            scope.declare(fn.params.get(i), args.get(i));
        }
        try {
            for (Stmt stmt : fn.body) {
                stmt.execute(scope, interpreter, depth + 1);
            }
        } catch (ReturnException re) {
            return re.value;
        }
        return TernNil.INSTANCE;
    }

    public TernValue getIndex(TernValue index, int line) {
        if (!(index instanceof TernInt)) throw new TernRuntimeError("cannot index " + getTypeName() + " with " + index.getTypeName(), line, "[");
        long i = ((TernInt) index).value;
        if (this instanceof TernList) {
            TernList list = (TernList) this;
            if (i < 0 || i >= list.elements.size()) throw new TernRuntimeError("index " + i + " out of range for length " + list.elements.size(), line, "[");
            return list.elements.get((int) i);
        } else if (this instanceof TernString) {
            String s = ((TernString) this).value;
            if (i < 0 || i >= s.length()) throw new TernRuntimeError("index " + i + " out of range for length " + s.length(), line, "[");
            return new TernString(s.substring((int) i, (int) i + 1));
        }
        throw new TernRuntimeError("cannot index " + getTypeName() + " with " + index.getTypeName(), line, "[");
    }

    public void setIndex(TernValue index, TernValue value, int line) {
        if (!(this instanceof TernList)) throw new TernRuntimeError("cannot assign into " + getTypeName(), line, "[");
        if (!(index instanceof TernInt)) throw new TernRuntimeError("cannot index list with " + index.getTypeName(), line, "[");
        long i = ((TernInt) index).value;
        TernList list = (TernList) this;
        if (i < 0 || i >= list.elements.size()) throw new TernRuntimeError("index " + i + " out of range for length " + list.elements.size(), line, "[");
        list.elements.set((int) i, value);
    }
}

class TernInt extends TernValue {
    final long value;
    TernInt(long v) { this.value = v; }
    public String getTypeName() { return "int"; }
    public boolean isTruthy() { return value != 0; }
    public String display(Set<TernList> path, boolean inList) { return String.valueOf(value); }
}

class TernBool extends TernValue {
    final boolean value;
    TernBool(boolean v) { this.value = v; }
    public String getTypeName() { return "bool"; }
    public boolean isTruthy() { return value; }
    public String display(Set<TernList> path, boolean inList) { return String.valueOf(value); }
}

class TernString extends TernValue {
    final String value;
    TernString(String v) { this.value = v; }
    public String getTypeName() { return "string"; }
    public boolean isTruthy() { return !value.isEmpty(); }
    public String display(Set<TernList> path, boolean inList) {
        if (!inList) return value;
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c == '\"') sb.append("\\\"");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.append("\"").toString();
    }
}

class TernList extends TernValue {
    final List<TernValue> elements = new ArrayList<>();
    public String getTypeName() { return "list"; }
    public boolean isTruthy() { return !elements.isEmpty(); }
    public String display(Set<TernList> path, boolean inList) {
        if (path.contains(this)) return "[...]";
        path.add(this);
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < elements.size(); i++) {
            sb.append(elements.get(i).display(path, true));
            if (i < elements.size() - 1) sb.append(", ");
        }
        sb.append("]");
        path.remove(this);
        return sb.toString();
    }
}

class TernNil extends TernValue {
    static final TernNil INSTANCE = new TernNil();
    public String getTypeName() { return "nil"; }
    public boolean isTruthy() { return false; }
    public String display(Set<TernList> path, boolean inList) { return "nil"; }
}

class TernFunction extends TernValue {
    final List<String> params;
    final List<Stmt> body;
    final TernScope closure;
    final boolean isBuiltin;
    final String builtinName;

    TernFunction(List<String> params, List<Stmt> body, TernScope closure) {
        this.params = params; this.body = body; this.closure = closure; this.isBuiltin = false; this.builtinName = null;
    }
    TernFunction(String name) {
        this.params = null; this.body = null; this.closure = null; this.isBuiltin = true; this.builtinName = name;
    }

    public String getTypeName() { return "function"; }
    public boolean isTruthy() { return true; }
    public String display(Set<TernList> path, boolean inList) { return "<fn>"; }

    public TernValue builtinCall(List<TernValue> args, int line) {
        switch (builtinName) {
            case "print":
                Set<TernList> path = new HashSet<>();
                for (int i = 0; i < args.size(); i++) {
                    System.out.print(args.get(i).display(path, false));
                    if (i < args.size() - 1) System.out.print(" ");
                }
                System.out.println();
                return TernNil.INSTANCE;
            case "str":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                return new TernString(args.get(0).display(new HashSet<>(), false));
            case "type":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                return new TernString(args.get(0).getTypeName());
            case "len":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                if (args.get(0) instanceof TernString) return new TernInt(((TernString) args.get(0)).value.length());
                if (args.get(0) instanceof TernList) return new TernInt(((TernList) args.get(0)).elements.size());
                throw new TernRuntimeError("bad argument to len", line, "(");
            case "push":
                if (args.size() != 2) throw new TernRuntimeError("expected 2 arguments, got " + args.size(), line, "(");
                if (!(args.get(0) instanceof TernList)) throw new TernRuntimeError("bad argument to push", line, "(");
                ((TernList) args.get(0)).elements.add(args.get(1));
                return TernNil.INSTANCE;
            case "pop":
                if (args.size() != 1) throw new TernRuntimeError("expected 1 arguments, got " + args.size(), line, "(");
                if (!(args.get(0) instanceof TernList)) throw new TernRuntimeError("bad argument to pop", line, "(");
                TernList list = (TernList) args.get(0);
                if (list.elements.isEmpty()) throw new TernRuntimeError("pop on empty list", line, "(");
                return list.elements.remove(list.elements.size() - 1);
            case "range":
                if (args.size() != 2) throw new TernRuntimeError("expected 2 arguments, got " + args.size(), line, "(");
                if (!(args.get(0) instanceof TernInt) || !(args.get(1) instanceof TernInt)) throw new TernRuntimeError("bad argument to range", line, "(");
                long a = ((TernInt) args.get(0)).value, b = ((TernInt) args.get(1)).value;
                TernList rangeList = new TernList();
                for (long i = a; i < b; i++) rangeList.elements.add(new TernInt(i));
                return rangeList;
            case "slice":
                if (args.size() != 3) throw new TernRuntimeError("expected 3 arguments, got " + args.size(), line, "(");
                TernValue x = args.get(0);
                if (!(x instanceof TernString || x instanceof TernList)) throw new TernRuntimeError("bad argument to slice", line, "(");
                if (!(args.get(1) instanceof TernInt) || !(args.get(2) instanceof TernInt)) throw new TernRuntimeError("bad argument to slice", line, "(");
                long start = ((TernInt) args.get(1)).value, end = ((TernInt) args.get(2)).value;
                if (x instanceof TernString) {
                    String s = ((TernString) x).value;
                    if (start < 0 || end > s.length() || start > end) throw new TernRuntimeError("slice out of range", line, "(");
                    return new TernString(s.substring((int) start, (int) end));
                } else {
                    TernList l = (TernList) x;
                    if (start < 0 || end > l.elements.size() || start > end) throw new TernRuntimeError("slice out of range", line, "(");
                    TernList res = new TernList();
                    for (int i = (int) start; i < (int) end; i++) res.elements.add(l.elements.get(i));
                    return res;
                }
            default: return TernNil.INSTANCE;
        }
    }
}

class TernScope {
    final Map<String, TernValue> vars = new HashMap<>();
    final TernScope parent;
    TernScope(TernScope p) { this.parent = p; }
    void declare(String name, TernValue v) { vars.put(name, v); }
    TernValue resolve(String name, int line) {
        if (vars.containsKey(name)) return vars.get(name);
        if (parent != null) return parent.resolve(name, line);
        throw new TernRuntimeError("undefined variable " + name, line, name);
    }
    void assign(String name, TernValue v, int line) {
        if (vars.containsKey(name)) { vars.put(name, v); return; }
        if (parent != null) { parent.assign(name, v, line); return; }
        throw new TernRuntimeError("undefined variable " + name, line, name);
    }
}

class TernRuntimeError extends RuntimeException {
    TernRuntimeError(String msg, int line, String token) {
        super("error at line " + line + ": " + msg);
        System.out.println("error at line " + line + ": " + msg);
        System.exit(0);
    }
}

class ReturnException extends RuntimeException {
    final TernValue value;
    ReturnException(TernValue v) { this.value = v; }
}
class BreakException extends RuntimeException {}
class ContinueException extends RuntimeException {}

abstract class Stmt { abstract void execute(TernScope scope, TernInterpreter interpreter, int depth); }
class LetStmt extends Stmt {
    String name; Expr expr; int line;
    LetStmt(String n, Expr e, int l) { name = n; expr = e; line = l; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { scope.declare(name, interpreter.eval(expr, scope, depth)); }
}
class AssignStmt extends Stmt {
    String name; Expr expr; int line;
    AssignStmt(String n, Expr e, int l) { name = n; expr = e; line = l; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { scope.assign(name, interpreter.eval(expr, scope, depth), line); }
}
class PostfixAssignStmt extends Stmt {
    Expr obj, idx, val; int line;
    PostfixAssignStmt(Expr o, Expr i, Expr v, int l) { obj = o; idx = i; val = v; line = l; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernValue o = interpreter.eval(obj, scope, depth);
        TernValue i = interpreter.eval(idx, scope, depth);
        TernValue v = interpreter.eval(val, scope, depth);
        o.setIndex(i, v, line);
    }
}
class BlockStmt extends Stmt {
    List<Stmt> stmts;
    BlockStmt(List<Stmt> s) { stmts = s; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernScope local = new TernScope(scope);
        for (Stmt s : stmts) s.execute(local, interpreter, depth);
    }
}
class IfStmt extends Stmt {
    Expr cond; Stmt thenB, elseB;
    IfStmt(Expr c, Stmt t, Stmt e) { cond = c; thenB = t; elseB = e; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        if (interpreter.eval(cond, scope, depth).isTruthy()) thenB.execute(scope, interpreter, depth);
        else if (elseB != null) elseB.execute(scope, interpreter, depth);
    }
}
class WhileStmt extends Stmt {
    Expr cond; Stmt body;
    WhileStmt(Expr c, Stmt b) { cond = c; body = b; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        while (interpreter.eval(cond, scope, depth).isTruthy()) {
            try { body.execute(scope, interpreter, depth); }
            catch (BreakException be) { break; }
            catch (ContinueException ce) { }
        }
    }
}
class ForStmt extends Stmt {
    String varName; Expr expr; Stmt body;
    ForStmt(String n, Expr e, Stmt b) { varName = n; expr = e; body = b; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernValue listVal = interpreter.eval(expr, scope, depth);
        if (!(listVal instanceof TernList)) throw new TernRuntimeError("cannot iterate " + listVal.getTypeName(), 0, "for");
        TernList list = (TernList) listVal;
        int i = 0;
        while (i < list.elements.size()) {
            TernValue val = list.elements.get(i);
            TernScope local = new TernScope(scope);
            local.declare(varName, val);
            try { body.execute(local, interpreter, depth); }
            catch (BreakException be) { break; }
            catch (ContinueException ce) { }
            i++;
        }
    }
}
class FnStmt extends Stmt {
    String name; List<String> params; BlockStmt body;
    FnStmt(String n, List<String> p, BlockStmt b) { name = n; params = p; body = b; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        TernFunction fn = new TernFunction(params, body.stmts, scope);
        scope.declare(name, fn);
    }
}
class ReturnStmt extends Stmt {
    Expr expr;
    ReturnStmt(Expr e) { expr = e; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) {
        throw new ReturnException(expr == null ? TernNil.INSTANCE : interpreter.eval(expr, scope, depth));
    }
}
class BreakStmt extends Stmt {
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { throw new BreakException(); }
}
class ContinueStmt extends Stmt {
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { throw new ContinueException(); }
}
class ExprStmt extends Stmt {
    Expr expr;
    ExprStmt(Expr e) { expr = e; }
    void execute(TernScope scope, TernInterpreter interpreter, int depth) { interpreter.eval(expr, scope, depth); }
}

abstract class Expr { }
class LiteralExpr extends Expr {
    TernValue val;
    LiteralExpr(TernValue v) { val = v; }
}
class VarExpr extends Expr {
    String name; int line;
    VarExpr(String n, int l) { name = n; line = l; }
}
class BinaryExpr extends Expr {
    Expr left, right; String op; int line;
    BinaryExpr(Expr l, Expr r, String o, int ln) { left = l; right = r; op = o; line = ln; }
}
class UnaryExpr extends Expr {
    String op; Expr expr; int line;
    UnaryExpr(String o, Expr e, int l) { op = o; expr = e; line = l; }
}
class PostfixExpr extends Expr {
    Expr obj; Expr index; boolean isCall; int line;
    PostfixExpr(Expr o, Expr i, boolean c, int l) { obj = o; index = i; isCall = c; line = l; }
}
class ListExpr extends Expr {
    List<Expr> elements;
    ListExpr(List<Expr> e) { elements = e; }
}
class FnExpr extends Expr {
    List<String> params; BlockStmt body;
    FnExpr(List<String> p, BlockStmt b) { params = p; body = b; }
}
class CallExpr extends Expr {
    Expr callee; List<Expr> args; int line;
    CallExpr(Expr c, List<Expr> a, int l) { callee = c; args = a; line = l; }
}

class TernInterpreter {
    TernValue eval(Expr e, TernScope scope, int depth) {
        if (e instanceof LiteralExpr) return ((LiteralExpr) e).val;
        if (e instanceof VarExpr) return scope.resolve(((VarExpr) e).name, ((VarExpr) e).line);
        if (e instanceof BinaryExpr) {
            BinaryExpr be = (BinaryExpr) e;
            TernValue l = eval(be.left, scope, depth);
            TernValue r = eval(be.right, scope, depth);
            switch (be.op) {
                case "or": return l.isTruthy() ? l : r;
                case "and": return l.isTruthy() ? r : l;
                case "==": return l.ternEquals(r);
                case "!=": return l.ternEquals(r).isTruthy() ? new TernBool(false) : new TernBool(true);
                case "<": case "<=": case ">": case ">=": return l.compare(r, be.line, be.op);
                case "+": return l.add(r, be.line);
                case "-": return l.sub(r, be.line);
                case "*": return l.mul(r, be.line);
                case "/": return l.div(r, be.line);
                case "%": return l.mod(r, be.line);
                default: return null;
            }
        }
        if (e instanceof UnaryExpr) {
            UnaryExpr ue = (UnaryExpr) e;
            TernValue v = eval(ue.expr, scope, depth);
            if (ue.op.equals("not")) return new TernBool(!v.isTruthy());
            if (ue.op.equals("-")) {
                if (!(v instanceof TernInt)) throw new TernRuntimeError("cannot apply - to " + v.getTypeName(), ue.line, "-");
                try { return new TernInt(-((TernInt) v).value); }
                catch (ArithmeticException ex) { throw new TernRuntimeError("integer overflow", ue.line, "-"); }
            }
        }
        if (e instanceof PostfixExpr) {
            PostfixExpr pe = (PostfixExpr) e;
            TernValue obj = eval(pe.obj, scope, depth);
            TernValue idx = pe.index == null ? null : eval(pe.index, scope, depth);
            return obj.getIndex(idx, pe.line);
        }
        if (e instanceof CallExpr) {
            CallExpr ce = (CallExpr) e;
            TernValue callee = eval(ce.callee, scope, depth);
            List<TernValue> args = new ArrayList<>();
            for (Expr ae : ce.args) args.add(eval(ae, scope, depth));
            return callee.call(args, ce.line, depth, this);
        }
        if (e instanceof ListExpr) {
            TernList list = new TernList();
            for (Expr ee : ((ListExpr) e).elements) list.elements.add(eval(ee, scope, depth));
            return list;
        }
        if (e instanceof FnExpr) {
            FnExpr fe = (FnExpr) e;
            return new TernFunction(fe.params, fe.body.stmts, scope);
        }
        return TernNil.INSTANCE;
    }

    void run(String source) {
        TernLexer lexer = new TernLexer(source);
        TernParser parser = new TernParser(lexer);
        List<Stmt> program = parser.parseProgram();
        TernScope builtins = new TernScope(null);
        builtins.declare("print", new TernFunction("print"));
        builtins.declare("str", new TernFunction("str"));
        builtins.declare("type", new TernFunction("type"));
        builtins.declare("len", new TernFunction("len"));
        builtins.declare("push", new TernFunction("push"));
        builtins.declare("pop", new TernFunction("pop"));
        builtins.declare("range", new TernFunction("range"));
        builtins.declare("slice", new TernFunction("slice"));
        TernScope global = new TernScope(builtins);
        for (Stmt s : program) s.execute(global, this, 0);
    }
}

class TernLexer {
    enum TokenType {
        INT, STRING, IDENT, EQ, NEQ, LT, LTE, GT, GTE, ASSIGN, PLUS, MINUS, STAR, SLASH, PERCENT, 
        LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE, COMMA, SEMICOLON, 
        LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE, AND, OR, NOT, TRUE, FALSE, NIL, EOF
    }
    static class Token {
        TokenType type; String value; int line;
        Token(TokenType t, String v, int l) { type = t; value = v; line = l; }
    }
    private String source;
    private int pos = 0, line = 1;
    TernLexer(String s) { source = s; }
    Token nextToken() {
        while (pos < source.length()) {
            char c = source.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
                if (c == '\n') line++;
                pos++;
            } else if (c == '#') {
                while (pos < source.length() && source.charAt(pos) != '\n') pos++;
            } else break;
        }
        if (pos >= source.length()) return new Token(TokenType.EOF, "", line);
        char c = source.charAt(pos);
        if (Character.isDigit(c)) {
            StringBuilder sb = new StringBuilder();
            while (pos < source.length() && Character.isDigit(source.charAt(pos))) sb.append(source.charAt(pos++));
            return new Token(TokenType.INT, sb.toString(), line);
        }
        if (c == '\"') {
            StringBuilder sb = new StringBuilder();
            pos++;
            while (pos < source.length() && source.charAt(pos) != '\"') {
                char cc = source.charAt(pos++);
                if (cc == '\\') {
                    char next = source.charAt(pos++);
                    if (next == 'n') sb.append('\n'); else if (next == 't') sb.append('\t');
                    else if (next == '\"') sb.append('\"'); else if (next == '\\') sb.append('\\');
                } else sb.append(cc);
            }
            pos++;
            return new Token(TokenType.STRING, sb.toString(), line);
        }
        if (Character.isLetter(c) || c == '_') {
            StringBuilder sb = new StringBuilder();
            while (pos < source.length() && (Character.isLetterOrDigit(source.charAt(pos)) || source.charAt(pos) == '_')) sb.append(source.charAt(pos++));
            String s = sb.toString();
            switch (s) {
                case "let": return new Token(TokenType.LET, s, line);
                case "fn": return new Token(TokenType.FN, s, line);
                case "if": return new Token(TokenType.IF, s, line);
                case "else": return new Token(TokenType.ELSE, s, line);
                case "while": return new Token(TokenType.WHILE, s, line);
                case "for": return new Token(TokenType.FOR, s, line);
                case "in": return new Token(TokenType.IN, s, line);
                case "return": return new Token(TokenType.RETURN, s, line);
                case "break": return new Token(TokenType.BREAK, s, line);
                case "continue": return new Token(TokenType.CONTINUE, s, line);
                case "and": return new Token(TokenType.AND, s, line);
                case "or": return new Token(TokenType.OR, s, line);
                case "not": return new Token(TokenType.NOT, s, line);
                case "true": return new Token(TokenType.TRUE, s, line);
                case "false": return new Token(TokenType.FALSE, s, line);
                case "nil": return new Token(TokenType.NIL, s, line);
                default: return new Token(TokenType.IDENT, s, line);
            }
        }
        pos++;
        switch (c) {
            case '(': return new Token(TokenType.LPAREN, "(", line);
            case ')': return new Token(TokenType.RPAREN, ")", line);
            case '[': return new Token(TokenType.LBRACKET, "[", line);
            case ']': return new Token(TokenType.RBRACKET, "]", line);
            case '{': return new Token(TokenType.LBRACE, "{", line);
            case '}': return new Token(TokenType.RBRACE, "}", line);
            case ',': return new Token(TokenType.COMMA, ",", line);
            case ';': return new Token(TokenType.SEMICOLON, ";", line);
            case '+': return new Token(TokenType.PLUS, "+", line);
            case '-': return new Token(TokenType.MINUS, "-", line);
            case '*': return new Token(TokenType.STAR, "*", line);
            case '/': return new Token(TokenType.SLASH, "/", line);
            case '%': return new Token(TokenType.PERCENT, "%", line);
            case '=':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.EQ, "==", line); }
                return new Token(TokenType.ASSIGN, "=", line);
            case '!':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.NEQ, "!=", line); }
                throw new RuntimeException("Unexpected character !");
            case '<':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.LTE, "<=", line); }
                return new Token(TokenType.LT, "<", line);
            case '>':
                if (pos < source.length() && source.charAt(pos) == '=') { pos++; return new Token(TokenType.GTE, ">=", line); }
                return new Token(TokenType.GT, ">", line);
        }
        throw new RuntimeException("Unexpected character " + c);
    }
}

class TernParser {
    TernLexer lexer;
    TernLexer.Token current;
    TernParser(TernLexer l) { lexer = l; current = lexer.nextToken(); }
    void next() { current = lexer.nextToken(); }
    boolean match(TernLexer.TokenType t) {
        if (current.type == t) { next(); return true; }
        return false;
    }
    List<Stmt> parseProgram() {
        List<Stmt> stmts = new ArrayList<>();
        while (current.type != TernLexer.TokenType.EOF) stmts.add(parseStmt());
        return stmts;
    }
    Stmt parseStmt() {
        if (match(TernLexer.TokenType.LET)) {
            String name = current.value; next();
            next(); // =
            Expr e = parseExpr();
            next(); // ;
            return new LetStmt(name, e, current.line);
        } else if (match(TernLexer.TokenType.FN)) {
            String name = current.value; next();
            next(); // (
            List<String> params = new ArrayList<>();
            if (current.type != TernLexer.TokenType.RPAREN) {
                while (true) {
                    params.add(current.value); next();
                    if (!match(TernLexer.TokenType.COMMA)) break;
                }
            }
            next(); // )
            BlockStmt body = parseBlock();
            return new FnStmt(name, params, body);
        } else if (match(TernLexer.TokenType.IF)) {
            Expr cond = parseExpr();
            Stmt thenB = parseBlock();
            Stmt elseB = null;
            if (match(TernLexer.TokenType.ELSE)) {
                if (current.type == TernLexer.TokenType.LBRACE) elseB = parseBlock();
                else elseB = parseIfStmt();
            }
            return new IfStmt(cond, thenB, elseB);
        } else if (match(TernLexer.TokenType.WHILE)) {
            Expr cond = parseExpr();
            return new WhileStmt(cond, parseBlock());
        } else if (match(TernLexer.TokenType.FOR)) {
            String name = current.value; next();
            next(); // in
            Expr e = parseExpr();
            return new ForStmt(name, e, parseBlock());
        } else if (match(TernLexer.TokenType.RETURN)) {
            Expr e = null;
            if (current.type != TernLexer.TokenType.SEMICOLON) { e = parseExpr(); }
            next(); // ;
            return new ReturnStmt(e);
        } else if (match(TernLexer.TokenType.BREAK)) {
            next(); // ;
            return new BreakStmt();
        } else if (match(TernLexer.TokenType.CONTINUE)) {
            next(); // ;
            return new ContinueStmt();
        } else {
            Expr e = parseExpr();
            if (e instanceof VarExpr && match(TernLexer.TokenType.ASSIGN)) {
                Expr val = parseExpr();
                next(); // ;
                return new AssignStmt(((VarExpr) e).name, val, current.line);
            } else if (e instanceof PostfixExpr && match(TernLexer.TokenType.ASSIGN)) {
                Expr val = parseExpr();
                next(); // ;
                return new PostfixAssignStmt(((PostfixExpr) e).obj, ((PostfixExpr) e).index, val, current.line);
            } else {
                next(); // ;
                return new ExprStmt(e);
            }
        }
    }
    Stmt parseIfStmt() {
        Expr cond = parseExpr();
        Stmt thenB = parseBlock();
        Stmt elseB = null;
        if (match(TernLexer.TokenType.ELSE)) {
            if (current.type == TernLexer.TokenType.LBRACE) elseB = parseBlock();
            else elseB = parseIfStmt();
        }
        return new IfStmt(cond, thenB, elseB);
    }
    BlockStmt parseBlock() {
        next(); // {
        List<Stmt> stmts = new ArrayList<>();
        while (current.type != TernLexer.TokenType.RBRACE) stmts.add(parseStmt());
        next(); // }
        return new BlockStmt(stmts);
    }
    Expr parseExpr() { return parseOr(); }
    Expr parseOr() {
        Expr e = parseAnd();
        while (match(TernLexer.TokenType.OR)) e = new BinaryExpr(e, parseAnd(), "or", current.line);
        return e;
    }
    Expr parseAnd() {
        Expr e = parseNot();
        while (match(TernLexer.TokenType.AND)) e = new BinaryExpr(e, parseNot(), "and", current.line);
        return e;
    }
    Expr parseNot() {
        if (match(TernLexer.TokenType.NOT)) return new UnaryExpr("not", parseNot(), current.line);
        return parseCompare();
    }
    Expr parseCompare() {
        Expr e = parseAddSub();
        while (current.type == TernLexer.TokenType.EQ || current.type == TernLexer.TokenType.NEQ || 
               current.type == TernLexer.TokenType.LT || current.type == TernLexer.TokenType.LTE || 
               current.type == TernLexer.TokenType.GT || current.type == TernLexer.TokenType.GTE) {
            String op = current.value; next();
            e = new BinaryExpr(e, parseAddSub(), op, current.line);
        }
        return e;
    }
    Expr parseAddSub() {
        Expr e = parseMulDivMod();
        while (current.type == TernLexer.TokenType.PLUS || current.type == TernLexer.TokenType.MINUS) {
            String op = current.value; next();
            e = new BinaryExpr(e, parseMulDivMod(), op, current.line);
        }
        return e;
    }
    Expr parseMulDivMod() {
        Expr e = parseUnaryMinus();
        while (current.type == TernLexer.TokenType.STAR || current.type == TernLexer.TokenType.SLASH || current.type == TernLexer.TokenType.PERCENT) {
            String op = current.value; next();
            e = new BinaryExpr(e, parseUnaryMinus(), op, current.line);
        }
        return e;
    }
    Expr parseUnaryMinus() {
        if (match(TernLexer.TokenType.MINUS)) return new UnaryExpr("-", parseUnaryMinus(), current.line);
        return parsePostfix();
    }
    Expr parsePostfix() {
        Expr e = parsePrimary();
        while (current.type == TernLexer.TokenType.LPAREN || current.type == TernLexer.TokenType.LBRACKET) {
            if (current.type == TernLexer.TokenType.LPAREN) {
                next();
                List<Expr> args = new ArrayList<>();
                if (current.type != TernLexer.TokenType.RPAREN) {
                    args.add(parseExpr());
                    while (match(TernLexer.TokenType.COMMA)) args.add(parseExpr());
                }
                next(); // )
                e = new CallExpr(e, args, current.line);
            } else {
                next();
                Expr idx = parseExpr();
                next(); // ]
                e = new PostfixExpr(e, idx, false, current.line);
            }
        }
        return e;
    }
    Expr parsePrimary() {
        if (match(TernLexer.TokenType.INT)) { String val = current.value; next(); return new LiteralExpr(new TernInt(Long.parseLong(val))); }
        if (match(TernLexer.TokenType.STRING)) { String val = current.value; next(); return new LiteralExpr(new TernString(val)); }
        if (match(TernLexer.TokenType.TRUE)) { next(); return new LiteralExpr(new TernBool(true)); }
        if (match(TernLexer.TokenType.FALSE)) { next(); return new LiteralExpr(new TernBool(false)); }
        if (match(TernLexer.TokenType.NIL)) { next(); return new LiteralExpr(TernNil.INSTANCE); }
        if (match(TernLexer.TokenType.IDENT)) { String val = current.value; next(); return new VarExpr(val, current.line); }
        if (match(TernLexer.TokenType.LPAREN)) {
            Expr e = parseExpr();
            next(); // )
            return e;
        }
        if (match(TernLexer.TokenType.LBRACKET)) {
            List<Expr> elements = new ArrayList<>();
            if (current.type != TernLexer.TokenType.RBRACKET) {
                elements.add(parseExpr());
                while (match(TernLexer.TokenType.COMMA)) elements.add(parseExpr());
            }
            next(); // ]
            return new ListExpr(elements);
        }
        if (match(TernLexer.TokenType.FN)) {
            next(); // (
            List<String> params = new ArrayList<>();
            if (current.type != TernLexer.TokenType.RPAREN) {
                while (true) {
                    params.add(current.value); next();
                    if (!match(TernLexer.TokenType.COMMA)) break;
                }
            }
            next(); // )
            BlockStmt body = parseBlock();
            return new FnExpr(params, body);
        }
        throw new RuntimeException("Unexpected token " + current.type);
    }
}

import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import javax.imageio.ImageIO;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        String sceneDir = args[0];
        File sceneFile = new File(sceneDir, "scene.json");
        try {
            String jsonContent = Files.readString(sceneFile.toPath());
            JsonParser parser = new JsonParser(jsonContent);
            Map<String, Object> scene = (Map<String, Object>) parser.parse();

            int width = ((Number) scene.get("width")).intValue();
            int height = ((Number) scene.get("height")).intValue();
            List<Integer> bgList = (List<Integer>) scene.get("background");
            int bgR = bgList.get(0);
            int bgG = bgList.get(1);
            int bgB = bgList.get(2);

            int[][] rChan = new int[width][height];
            int[][] gChan = new int[width][height];
            int[][] bChan = new int[width][height];

            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    rChan[x][y] = bgR;
                    gChan[x][y] = bgG;
                    bChan[x][y] = bgB;
                }
            }

            List<Map<String, Object>> shapes = (List<Map<String, Object>>) scene.get("shapes");
            for (int i = 0; i < shapes.size(); i++) {
                Map<String, Object> shape = shapes.get(i);
                String type = (String) shape.get("type");
                List<Integer> colorList = (List<Integer>) shape.get("color");
                int sR = colorList.get(0);
                int sG = colorList.get(1);
                int sB = colorList.get(2);
                int sA = colorList.get(3);

                long coveredCount = 0;
                for (int x = 0; x < width; x++) {
                    for (int y = 0; y < height; y++) {
                        if (isCovered(x, y, shape)) {
                            coveredCount++;
                            rChan[x][y] = blend(sR, sA, rChan[x][y]);
                            gChan[x][y] = blend(sG, sA, gChan[x][y]);
                            bChan[x][y] = blend(sB, sA, bChan[x][y]);
                        }
                    }
                }
                System.out.println((i + 1) + " " + type + " " + coveredCount);
            }

            BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
            Set<Integer> distinctColors = new HashSet<>();
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    int rgb = (rChan[x][y] << 16) | (gChan[x][y] << 8) | bChan[x][y];
                    image.setRGB(x, y, rgb);
                    distinctColors.add(rgb);
                }
            }
            ImageIO.write(image, "png", new File("out.png"));
            System.out.println("colors " + distinctColors.size());

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static int blend(int s, int a, int d) {
        return (s * a + d * (255 - a) + 127) / 255;
    }

    private static boolean isCovered(int x, int y, Map<String, Object> shape) {
        String type = (String) shape.get("type");
        if ("rect".equals(type)) {
            int rx = ((Number) shape.get("x")).intValue();
            int ry = ((Number) shape.get("y")).intValue();
            int w = ((Number) shape.get("w")).intValue();
            int h = ((Number) shape.get("h")).intValue();
            return x >= rx && x < rx + w && y >= ry && y < ry + h;
        } else if ("circle".equals(type)) {
            long cx = ((Number) shape.get("cx")).longValue();
            long cy = ((Number) shape.get("cy")).longValue();
            long r = ((Number) shape.get("r")).longValue();
            long dx = x - cx;
            long dy = y - cy;
            return dx * dx + dy * dy <= r * r;
        } else if ("triangle".equals(type)) {
            List<List<Integer>> points = (List<List<Integer>>) shape.get("points");
            long x0 = points.get(0).get(0), y0 = points.get(0).get(1);
            long x1 = points.get(1).get(0), y1 = points.get(1).get(1);
            long x2 = points.get(2).get(0), y2 = points.get(2).get(1);
            long e0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0);
            long e1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);
            long e2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2);
            return (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0);
        } else if ("line".equals(type)) {
            long x1 = ((Number) shape.get("x1")).longValue();
            long y1 = ((Number) shape.get("y1")).longValue();
            long x2 = ((Number) shape.get("x2")).longValue();
            long y2 = ((Number) shape.get("y2")).longValue();
            long r = ((Number) shape.get("r")).longValue();
            long dx = x2 - x1;
            long dy = y2 - y1;
            long L = dx * dx + dy * dy;
            long t = (x - x1) * dx + (y - y1) * dy;
            if (t <= 0) {
                return (x - x1) * (x - x1) + (y - y1) * (y - y1) <= r * r;
            } else if (t >= L) {
                return (x - x2) * (x - x2) + (y - y2) * (y - y2) <= r * r;
            } else {
                long c = (x - x1) * dy - (y - y1) * dx;
                return c * c <= r * r * L;
            }
        }
        return false;
    }

    static class JsonParser {
        private final String input;
        private int pos = 0;

        public JsonParser(String input) {
            this.input = input;
        }

        public Object parse() {
            skipWhitespace();
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            return parseNumber();
        }

        private Map<String, Object> parseObject() {
            Map<String, Object> map = new HashMap<>();
            pos++; // skip {
            while (true) {
                skipWhitespace();
                if (input.charAt(pos) == '}') {
                    pos++;
                    break;
                }
                String key = parseString();
                skipWhitespace();
                pos++; // skip :
                map.put(key, parse());
                skipWhitespace();
                if (input.charAt(pos) == ',') pos++;
            }
            return map;
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // skip [
            while (true) {
                skipWhitespace();
                if (input.charAt(pos) == ']') {
                    pos++;
                    break;
                }
                list.add(parse());
                skipWhitespace();
                if (input.charAt(pos) == ',') pos++;
            }
            return list;
        }

        private String parseString() {
            pos++; // skip "
            int start = pos;
            while (input.charAt(pos) != '"') pos++;
            String s = input.substring(start, pos);
            pos++; // skip "
            return s;
        }

        private Number parseNumber() {
            int start = pos;
            if (input.charAt(pos) == '-') pos++;
            while (pos < input.length() && (Character.isDigit(input.charAt(pos)) || input.charAt(pos) == '.')) {
                pos++;
            }
            String s = input.substring(start, pos);
            if (s.contains(".")) return Double.parseDouble(s);
            return Integer.parseInt(s);
        }

        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
        }
    }
}

import Foundation

// --- CRC-32 Implementation ---
func crc32(data: Data) -> UInt32 {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 {
                c = (c >> 1) ^ 0xEDB88320
            } else {
                c >>= 1
            }
        }
        table[i] = c
    }

    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc = table[Int((crc ^ UInt32(byte)) & 0xFF)] ^ (crc >> 8)
    }
    return crc ^ 0xFFFFFFFF
}

// --- Helper for splitting data into lines keeping the \n ---
func splitIntoLines(data: Data) -> [Data] {
    var lines = [Data]()
    var start = 0
    for i in 0..<data.count {
        if data[i] == 10 { // \n
            lines.append(data[start...i])
            start = i + 1
        }
    }
    if start < data.count {
        lines.append(data[start..<data.count])
    }
    return lines
}

// --- Diff Section and Hunk structures ---
enum SectionKind {
    case create, delete, modify
}

struct Hunk {
    let a: Int
    let b: Int
    let c: Int
    let d: Int
    let oldLines: [Data]
    let newLines: [Data]
    let isMalformed: Bool
}

struct Section {
    let path: String
    let kind: SectionKind
    let hunks: [Hunk]
}

// --- Main Program ---
func main() {
    let args = CommandLine.arguments
    guard args.count >= 3 else { return }

    let diffFilePath = args[1] + "/changes.diff"
    let treeDir = args[1] + "/tree"

    guard let diffData = try? Data(contentsOf: URL(fileURLWithPath: diffFilePath)) else { return }
    let diffLines = splitIntoLines(data: diffData)

    var sections = [Section]()
    var currentSectionLines = [Data]()

    // Parse diff into sections
    for line in diffLines {
        if line.starts(with: "diff --git ".data(using: .utf8)!) {
            if !currentSectionLines.isEmpty {
                if let section = parseSection(lines: currentSectionLines) {
                    sections.append(section)
                }
            }
            currentSectionLines = [line]
        } else {
            currentSectionLines.append(line)
        }
    }
    if !currentSectionLines.isEmpty {
        if let section = parseSection(lines: currentSectionLines) {
            sections.append(section)
        }
    }

    // Process sections
    var finalReports = [String: String]()

    for section in sections {
        let path = section.path
        let fullPath = treeDir + "/" + path

        var currentContent = [Data]()
        var error: String? = nil

        switch section.kind {
        case .create:
            if FileManager.default.fileExists(atPath: fullPath) {
                error = "already exists"
            }
        case .modify, .delete:
            if !FileManager.default.fileExists(atPath: fullPath) {
                error = "not found"
            } else {
                if let data = try? Data(contentsOf: URL(fileURLWithPath: fullPath)) {
                    currentContent = splitIntoLines(data: data)
                }
            }
        }

        var report = "\(path): \(sectionKindString(section.kind))\n"

        if let err = error {
            report += "  error: \(err)\n"
            finalReports[path] = report.trimmingCharacters(in: .whitespacesAndNewlines) + "\n"
            continue
        }

        var delta = 0
        var allHunksApplied = true

        for (i, hunk) in section.hunks.enumerated() {
            if hunk.isMalformed {
                report += "  hunk \(i+1): malformed\n"
                allHunksApplied = false
                continue
            }

            let P = hunk.a + delta
            let currentLineCount = currentContent.count

            if hunk.b == 0 {
                if P >= 0 && P <= currentLineCount {
                    currentContent.insert(contentsOf: hunk.newLines, at: P)
                    report += "  hunk \(i+1): applied at \(P) (offset 0)\n"
                    delta += (hunk.d - hunk.b)
                } else {
                    report += "  hunk \(i+1): rejected\n"
                    allHunksApplied = false
                }
            } else {
                var matchedP: Int? = nil
                var distance = 0
                while true {
                    let pMinus = P - distance
                    let pPlus = P + distance

                    if distance == 0 {
                        if pMinus >= 1 && pMinus + hunk.b - 1 <= currentLineCount {
                            if match(p: pMinus, current: currentContent, old: hunk.oldLines) {
                                matchedP = pMinus
                                break
                            }
                        }
                    } else {
                        if pMinus >= 1 && pMinus + hunk.b - 1 <= currentLineCount {
                            if match(p: pMinus, current: currentContent, old: hunk.oldLines) {
                                matchedP = pMinus
                                break
                            }
                        }
                        if pPlus >= 1 && pPlus + hunk.b - 1 <= currentLineCount {
                            if match(p: pPlus, current: currentContent, old: hunk.oldLines) {
                                matchedP = pPlus
                                break
                            }
                        }
                    }

                    if pMinus < 1 && pPlus + hunk.b - 1 > currentLineCount {
                        break
                    }
                    distance += 1
                    if distance > currentLineCount + 100 { break }
                }

                if let p = matchedP {
                    let offset = p - P
                    let offsetStr = offset == 0 ? "0" : (offset > 0 ? "+\(offset)" : "\(offset)")
                    report += "  hunk \(i+1): applied at \(p) (offset \(offsetStr))\n"

                    currentContent.removeSubrange((p-1)..<(p-1 + hunk.b))
                    currentContent.insert(contentsOf: hunk.newLines, at: p-1)
                    delta += (hunk.d - hunk.b)
                } else {
                    report += "  hunk \(i+1): rejected\n"
                    allHunksApplied = false
                }
            }
        }

        var finalResult = ""
        if section.kind == .delete && allHunksApplied && currentContent.isEmpty {
            finalResult = "  result: deleted"
        } else {
            let finalData = currentContent.reduce(Data()) { $0 + $1 }
            let crcValue = crc32(data: finalData)
            finalResult = "  result: \(currentContent.count) lines, crc32 \(String(format: "%08x", crcValue))"
        }
        report += finalResult + "\n"
        finalReports[path] = report.trimmingCharacters(in: .whitespacesAndNewlines) + "\n"
    }

    let sortedPaths = finalReports.keys.sorted()
    for path in sortedPaths {
        print(finalReports[path]!, terminator: "")
    }
}

func sectionKindString(_ kind: SectionKind) -> String {
    switch kind {
    case .create: return "create"
    case .delete: return "delete"
    case .modify: return "modify"
    }
}

func match(p: Int, current: [Data], old: [Data]) -> Bool {
    for i in 0..<old.count {
        if current[p - 1 + i] != old[i] {
            return false
        }
    }
    return true
}

func parseSection(lines: [Data]) -> Section? {
    guard let firstLine = lines.first,
          let firstLineStr = String(data: firstLine, encoding: .utf8),
          firstLineStr.starts(with: "diff --git ") else { return nil }

    let parts = firstLineStr.split(separator: " ")
    guard parts.count >= 3 else { return nil }
    let path = String(parts[2])

    var kind: SectionKind = .modify
    for line in lines {
        let s = String(data: line, encoding: .utf8) ?? ""
        if s.starts(with: "new file mode ") {
            kind = .create
            break
        } else if s.starts(with: "deleted file mode ") {
            kind = .delete
            break
        }
    }

    var hunks = [Hunk]()
    var i = 0
    while i < lines.count {
        let line = lines[i]
        let s = String(data: line, encoding: .utf8) ?? ""
        if s.starts(with: "@@ ") {
            let header = s.prefix(while: { $0 != "\n" })
            let rangePart = header.dropFirst(2) // remove "@@ "
            let parts = rangePart.split(separator: " ")
            if parts.count >= 2 {
                let oldRange = parts[0].dropFirst() // remove '-'
                let newRange = parts[1].dropFirst() // remove '+'

                let oldParts = oldRange.split(separator: ",")
                let a = Int(oldParts[0]) ?? 0
                let b = oldParts.count > 1 ? (Int(oldParts[1]) ?? 0) : 1

                let newParts = newRange.split(separator: ",")
                let c = Int(newParts[0]) ?? 0
                let d = newParts.count > 1 ? (Int(newParts[1]) ?? 0) : 1

                i += 1
                var bodyLines = [Data]()
                while i < lines.count {
                    let bodyLine = lines[i]
                    let bodyLineStr = String(data: bodyLine, encoding: .utf8) ?? ""
                    if bodyLineStr.starts(with: "@@ ") || bodyLineStr.starts(with: "diff --git ") {
                        break
                    }
                    bodyLines.append(bodyLine)
                    i += 1
                }

                var oldL = [Data]()
                var newL = [Data]()
                var lastMarker: UInt8 = 0

                for bl in bodyLines {
                    if bl.starts(with: "\\ No newline at end of file".data(using: .utf8)!) {
                        if lastMarker == 32 { // ' '
                            if !oldL.isEmpty { oldL[oldL.count-1].removeLast() }
                            if !newL.isEmpty { newL[newL.count-1].removeLast() }
                        } else if lastMarker == 45 { // '-'
                            if !oldL.isEmpty { oldL[oldL.count-1].removeLast() }
                        } else if lastMarker == 43 { // '+'
                            if !newL.isEmpty { newL[newL.count-1].removeLast() }
                        }
                    } else {
                        let marker = bl[0]
                        let content = bl.dropFirst()
                        if marker == 32 {
                            oldL.append(content)
                            newL.append(content)
                        } else if marker == 45 {
                            oldL.append(content)
                        } else if marker == 43 {
                            newL.append(content)
                        }
                        lastMarker = marker
                    }
                }

                let isMalformed = (oldL.count != b || newL.count != d)
                hunks.append(Hunk(a: a, b: b, c: c, d: d, oldLines: oldL, newLines: newL, isMalformed: isMalformed))
            } else {
                i += 1
            }
        } else {
            i += 1
        }
    }

    return Section(path: path, kind: kind, hunks: hunks)
}

main()

import Foundation

// --- CRC-32 Implementation ---
func crc32(data: Data) -> UInt32 {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 {
                c = (c >> 1) ^ 0xEDB88320
            } else {
                c >>= 1
            }
        }
        table[i] = c
    }

    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc = table[Int((crc ^ UInt32(byte)) & 0xFF)] ^ (crc >> 8)
    }
    return crc ^ 0xFFFFFFFF
}

// --- Helper for splitting data into lines keeping the \n ---
func splitIntoLines(data: Data) -> [Data] {
    var lines = [Data]()
    var start = 0
    while start < data.count {
        if let end = data[start...].firstIndex(of: 10) {
            lines.append(data[start...end])
            start = end + 1
        } else {
            lines.append(data[start...])
            start = data.count
        }
    }
    return lines
}

func removeTrailingNewline(_ line: inout Data) {
    if line.last == 10 {
        line.removeLast()
    }
}

// --- Diff Section and Hunk structures ---
enum SectionKind {
    case create, delete, modify
}

struct Hunk {
    let a: Int
    let b: Int
    let c: Int
    let d: Int
    let oldLines: [Data]
    let newLines: [Data]
    let isMalformed: Bool
}

struct Section {
    let path: String
    let kind: SectionKind
    let hunks: [Hunk]
}

func parseSection(lines: [Data]) -> Section? {
    guard let firstLine = lines.first,
          let firstLineStr = String(data: firstLine, encoding: .utf8) else { return nil }

    if !firstLineStr.starts(with: "diff --git ") { return nil }

    let parts = firstLineStr.split(separator: " ")
    guard parts.count >= 3 else { return nil }
    let aPath = String(parts[2])
    let path = String(aPath.dropFirst(aPath.firstIndex(of: "/")! + 1))

    var kind: SectionKind = .modify
    for line in lines {
        let s = String(data: line, encoding: .utf8) ?? ""
        if s.starts(with: "new file mode ") {
            kind = .create
            break
        } else if s.starts(with: "deleted file mode ") {
            kind = .delete
            break
        }
    }

    var hunks = [Hunk]()
    var i = 0
    while i < lines.count {
        let line = lines[i]
        let s = String(data: line, encoding: .utf8) ?? ""
        if s.starts(with: "@@ ") {
            let header = s.trimmingCharacters(in: .whitespacesAndNewlines)
            let rangePart = header.dropFirst(2) // remove "@@ "
            let parts = rangePart.split(separator: " ")
            if parts.count >= 2 {
                let oldRange = parts[0].dropFirst() // remove '-'
                let newRange = parts[1].dropFirst() // remove '+'

                let oldParts = oldRange.split(separator: ",")
                let a = Int(oldParts[0]) ?? 0
                let b = oldParts.count > 1 ? (Int(oldParts[1]) ?? 0) : 1

                let newParts = newRange.split(separator: ",")
                let c = Int(newParts[0]) ?? 0
                let d = newParts.count > 1 ? (Int(newParts[1]) ?? 0) : 1

                i += 1
                var bodyLines = [Data]()
                while i < lines.count {
                    let bl = lines[i]
                    let bls = String(data: bl, encoding: .utf8) ?? ""
                    if bls.starts(with: "@@ ") || bls.starts(with: "diff --git ") {
                        break
                    }
                    bodyLines.append(bl)
                    i += 1
                }

                var oldL = [Data]()
                var newL = [Data]()
                var lastMarker: Character? = nil

                for bl in bodyLines {
                    let bls = String(data: bl, encoding: .utf8) ?? ""
                    if bls.starts(with: "\\ No newline at end of file") {
                        if lastMarker == " " {
                            if !oldL.isEmpty { removeTrailingNewline(&oldL[oldL.count-1]) }
                            if !newL.isEmpty { removeTrailingNewline(&newL[newL.count-1]) }
                        } else if lastMarker == "-" {
                            if !oldL.isEmpty { removeTrailingNewline(&oldL[oldL.count-1]) }
                        } else if lastMarker == "+" {
                            if !newL.isEmpty { removeTrailingNewline(&newL[newL.count-1]) }
                        }
                    } else {
                        let marker = bls.first!
                        let content = bl.dropFirst()
                        if marker == " " {
                            oldL.append(content)
                            newL.append(content)
                        } else if marker == "-" {
                            oldL.append(content)
                        } else if marker == "+" {
                            newL.append(content)
                        }
                        lastMarker = marker
                    }
                }

                let isMalformed = (oldL.count != b || newL.count != d)
                hunks.append(Hunk(a: a, b: b, c: c, d: d, oldLines: oldL, newLines: newL, isMalformed: isMalformed))
            } else {
                i += 1
            }
        } else {
            i += 1
        }
    }

    return Section(path: path, kind: kind, hunks: hunks)
}

func match(p: Int, current: [Data], old: [Data]) -> Bool {
    for i in 0..<old.count {
        if current[p - 1 + i] != old[i] {
            return false
        }
    }
    return true
}

func main() {
    let args = CommandLine.arguments
    guard args.count >= 3 else { return }

    let diffFilePath = args[1] + "/changes.diff"
    let treeDir = args[1] + "/tree"

    guard let diffData = try? Data(contentsOf: URL(fileURLWithPath: diffFilePath)) else { return }
    let diffLines = splitIntoLines(data: diffData)

    var sections = [Section]()
    var currentSectionLines = [Data]()

    for line in diffLines {
        if let s = String(data: line, encoding: .utf8), s.starts(with: "diff --git ") {
            if !currentSectionLines.isEmpty {
                if let section = parseSection(lines: currentSectionLines) {
                    sections.append(section)
                }
            }
            currentSectionLines = [line]
        } else {
            currentSectionLines.append(line)
        }
    }
    if !currentSectionLines.isEmpty {
        if let section = parseSection(lines: currentSectionLines) {
            sections.append(section)
        }
    }

    var finalReports = [String: String]()

    for section in sections {
        let path = section.path
        let fullPath = treeDir + "/" + path

        var currentContent = [Data]()
        var error: String? = nil

        switch section.kind {
        case .create:
            if FileManager.default.fileExists(atPath: fullPath) {
                error = "already exists"
            }
        case .modify, .delete:
            if !FileManager.default.fileExists(atPath: fullPath) {
                error = "not found"
            } else {
                if let data = try? Data(contentsOf: URL(fileURLWithPath: fullPath)) {
                    currentContent = splitIntoLines(data: data)
                }
            }
        }

        var report = "\(path): \(sectionKindString(section.kind))\n"
        if let err = error {
            report += "  error: \(err)\n"
            finalReports[path] = report
            continue
        }

        var delta = 0
        var allHunksApplied = true

        for (i, hunk) in section.hunks.enumerated() {
            if hunk.isMalformed {
                report += "  hunk \(i+1): malformed\n"
                allHunksApplied = false
                continue
            }

            let P = hunk.a + delta
            let currentLineCount = currentContent.count

            if hunk.b == 0 {
                if P >= 0 && P <= currentLineCount {
                    currentContent.insert(contentsOf: hunk.newLines, at: P)
                    report += "  hunk \(i+1): applied at \(P) (offset 0)\n"
                    delta += (hunk.d - hunk.b)
                } else {
                    report += "  hunk \(i+1): rejected\n"
                    allHunksApplied = false
                }
            } else {
                var matchedP: Int? = nil
                var distance = 0
                while true {
                    let pMinus = P - distance
                    let pPlus = P + distance

                    if distance == 0 {
                        if pMinus >= 1 && pMinus + hunk.b - 1 <= currentLineCount {
                            if match(p: pMinus, current: currentContent, old: hunk.oldLines) {
                                matchedP = pMinus
                                break
                            }
                        }
                    } else {
                        if pMinus >= 1 && pMinus + hunk.b - 1 <= currentLineCount {
                            if match(p: pMinus, current: currentContent, old: hunk.oldLines) {
                                matchedP = pMinus
                                break
                            }
                        }
                        if pPlus >= 1 && pPlus + hunk.b - 1 <= currentLineCount {
                            if match(p: pPlus, current: currentContent, old: hunk.oldLines) {
                                matchedP = pPlus
                                break
                            }
                        }
                    }
                    if pMinus < 1 && pPlus + hunk.b - 1 > currentLineCount {
                        break
                    }
                    distance += 1
                    if distance > currentLineCount + 100 { break }
                }

                if let p = matchedP {
                    let offset = p - P
                    let offsetStr = offset == 0 ? "0" : (offset > 0 ? "+\(offset)" : "\(offset)")
                    report += "  hunk \(i+1): applied at \(p) (offset \(offsetStr))\n"
                    currentContent.removeSubrange((p-1)..<(p-1 + hunk.b))
                    currentContent.insert(contentsOf: hunk.newLines, at: p-1)
                    delta += (hunk.d - hunk.b)
                } else {
                    report += "  hunk \(i+1): rejected\n"
                    allHunksApplied = false
                }
            }
        }

        if section.kind == .delete && allHunksApplied && currentContent.isEmpty {
            report += "  result: deleted\n"
        } else {
            let finalData = currentContent.reduce(Data()) { $0 + $1 }
            let crcValue = crc32(data: finalData)
            report += "  result: \(currentContent.count) lines, crc32 \(String(format: "%08x", crcValue))\n"
        }
        finalReports[path] = report
    }

    let sortedPaths = finalReports.keys.sorted()
    for path in sortedPaths {
        print(finalReports[path]!, terminator: "")
    }
}

func sectionKindString(_ kind: SectionKind) -> String {
    switch kind {
    case .create: return "create"
    case .delete: return "delete"
    case .modify: return "modify"
    }
}

