import * as fs from 'fs';
import * as path from 'path';

function splitLines(buf: Buffer): Buffer[] {
    const lines: Buffer[] = [];
    let start = 0;
    for (let i = 0; i < buf.length; i++) {
        if (buf[i] === 10) { // \n
            lines.push(buf.slice(start, i + 1));
            start = i + 1;
        }
    }
    if (start < buf.length) {
        lines.push(buf.slice(start));
    }
    return lines;
}

function stripNewline(line: Buffer): Buffer {
    if (line.length > 0 && line[line.length - 1] === 10) {
        return line.slice(0, line.length - 1);
    }
    return line;
}

function crc32(data: Buffer): string {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        let byte = data[i];
        crc ^= byte;
        for (let j = 0; j < 8; j++) {
            crc = (crc >>> 1) ^ (crc & 1 ? 0xEDB88320 : 0);
        }
    }
    return ((crc ^ 0xFFFFFFFF) >>> 0).toString(16).padStart(8, '0');
}

interface Hunk {
    a: number;
    b: number;
    c: number;
    d: number;
    oldLines: Buffer[];
    newLines: Buffer[];
}

interface Section {
    path: string;
    kind: 'create' | 'delete' | 'modify';
    hunks: Hunk[];
}

function main() {
    const root = process.argv[2];
    if (!root) return;

    const diffPath = path.join(root, 'changes.diff');
    const treePath = path.join(root, 'tree');

    const diffContent = fs.readFileSync(diffPath);
    const diffLines = splitLines(diffContent);

    const sections: Section[] = [];
    let currentSection: Section | null = null;

    for (let i = 0; i < diffLines.length; i++) {
        const line = stripNewline(diffLines[i]);
        const lineStr = line.toString();

        if (lineStr.startsWith('diff --git ')) {
            const parts = lineStr.split(' ');
            const filePath = parts[2].slice(2);
            currentSection = { path: filePath, kind: 'modify', hunks: [] };
            sections.push(currentSection);
        } else if (currentSection && lineStr.startsWith('new file mode ')) {
            currentSection.kind = 'create';
        } else if (currentSection && lineStr.startsWith('deleted file mode ')) {
            currentSection.kind = 'delete';
        } else if (currentSection && lineStr.startsWith('@@ ')) {
            const match = lineStr.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
            if (match) {
                const a = parseInt(match[1]);
                const b = match[2] ? parseInt(match[2]) : 1;
                const c = parseInt(match[3]);
                const d = match[4] ? parseInt(match[4]) : 1;

                const hunkBody: Buffer[] = [];
                while (i + 1 < diffLines.length) {
                    const nextLine = stripNewline(diffLines[i + 1]);
                    const nextStr = nextLine.toString();
                    if (nextStr.startsWith('diff --git ') || nextStr.startsWith('@@ ')) {
                        break;
                    }
                    hunkBody.push(nextLine);
                    i++;
                }

                const oldHunkLines: Buffer[] = [];
                const newHunkLines: Buffer[] = [];
                for (let j = 0; j < hunkBody.length; j++) {
                    const bodyLine = hunkBody[j];
                    const marker = bodyLine[0];
                    const content = bodyLine.slice(1);
                    if (marker === 32) { // ' '
                        const lineBuf = Buffer.concat([content, Buffer.from([10])]);
                        oldHunkLines.push(lineBuf);
                        newHunkLines.push(lineBuf);
                    } else if (marker === 45) { // '-'
                        const lineBuf = Buffer.concat([content, Buffer.from([10])]);
                        oldHunkLines.push(lineBuf);
                    } else if (marker === 43) { // '+'
                        const lineBuf = Buffer.concat([content, Buffer.from([10])]);
                        newHunkLines.push(lineBuf);
                    } else if (marker === 92 && bodyLine.slice(1, 15).toString() === ' No newline at end of file') {
                        const prevLine = hunkBody[j - 1];
                        const prevMarker = prevLine[0];
                        if (prevMarker === 32) {
                            oldHunkLines[oldHunkLines.length - 1] = oldHunkLines[oldHunkLines.length - 1].slice(0, -1);
                            newHunkLines[newHunkLines.length - 1] = newHunkLines[newHunkLines.length - 1].slice(0, -1);
                        } else if (prevMarker === 45) {
                            oldHunkLines[oldHunkLines.length - 1] = oldHunkLines[oldHunkLines.length - 1].slice(0, -1);
                        } else if (prevMarker === 43) {
                            newHunkLines[newHunkLines.length - 1] = newHunkLines[newHunkLines.length - 1].slice(0, -1);
                        }
                    }
                }
                currentSection.hunks.push({ a, b, c, d, oldLines: oldHunkLines, newLines: newHunkLines });
            }
        }
    }

    const results: { path: string, output: string }[] = [];
    for (const section of sections) {
        const fullPath = path.join(treePath, section.path);
        let contentLines: Buffer[] = [];
        let error: string | null = null;

        if (section.kind === 'create') {
            if (fs.existsSync(fullPath)) {
                error = 'already exists';
            } else {
                contentLines = [];
            }
        } else {
            if (!fs.existsSync(fullPath)) {
                error = 'not found';
            } else {
                contentLines = splitLines(fs.readFileSync(fullPath));
            }
        }

        let output = `${section.path}: ${section.kind}`;
        if (error) {
            output += `\n  error: ${error}`;
        } else {
            let delta = 0;
            let allHunksApplied = true;
            for (let i = 0; i < section.hunks.length; i++) {
                const hunk = section.hunks[i];
                if (hunk.oldLines.length !== hunk.b || hunk.newLines.length !== hunk.d) {
                    output += `\n  hunk ${i + 1}: malformed`;
                    continue;
                }

                const P = hunk.a + delta;
                let pFound = -1;
                let offset = 0;

                if (hunk.b === 0) {
                    if (P >= 0 && P <= contentLines.length) {
                        pFound = P;
                        offset = 0;
                    }
                } else {
                    for (let j = 0; ; j++) {
                        const pMinus = P - j;
                        const pPlus = P + j;
                        if (pMinus >= 1 && pMinus <= contentLines.length - hunk.b + 1) {
                            let match = true;
                            for (let k = 0; k < hunk.b; k++) {
                                if (Buffer.compare(contentLines[pMinus - 1 + k], hunk.oldLines[k]) !== 0) {
                                    match = false;
                                    break;
                                }
                            }
                            if (match) {
                                pFound = pMinus;
                                offset = pMinus - P;
                                break;
                            }
                        }
                        if (j === 0) continue;
                        if (pPlus >= 1 && pPlus <= contentLines.length - hunk.b + 1) {
                            let match = true;
                            for (let k = 0; k < hunk.b; k++) {
                                if (Buffer.compare(contentLines[pPlus - 1 + k], hunk.oldLines[k]) !== 0) {
                                    match = false;
                                    break;
                                }
                            }
                            if (match) {
                                pFound = pPlus;
                                offset = pPlus - P;
                                break;
                            }
                        }
                        if (pMinus < 1 && pPlus > contentLines.length - hunk.b + 1) break;
                    }
                }

                if (pFound !== -1) {
                    const p = pFound;
                    const oldB = hunk.b;
                    const newD = hunk.d;
                    if (oldB === 0) {
                        contentLines.splice(p, 0, ...hunk.newLines);
                    } else {
                        contentLines.splice(p - 1, oldB, ...hunk.newLines);
                    }
                    output += `\n  hunk ${i + 1}: applied at ${p} (offset ${offset > 0 ? '+' + offset : offset})`;
                    delta += newD - oldB;
                } else {
                    output += `\n  hunk ${i + 1}: rejected`;
                    allHunksApplied = false;
                }
            }

            if (section.kind === 'delete' && allHunksApplied && contentLines.length === 0) {
                output += `\n  result: deleted`;
            } else {
                const finalContent = Buffer.concat(contentLines);
                output += `\n  result: ${contentLines.length} lines, crc32 ${crc32(finalContent)}`;
            }
        }
        results.push({ path: section.path, output });
    }

    results.sort((a, b) => Buffer.compare(Buffer.from(a.path), Buffer.from(b.path)));
    for (const res of results) {
        process.stdout.write(res.output + '\n');
    }
}

main();

import * as fs from 'fs';
import * as path from 'path';

/**
 * Splits a buffer into lines, keeping the \n at the end of each line.
 * An empty file has zero lines.
 */
function splitLines(buf: Buffer): Buffer[] {
    const lines: Buffer[] = [];
    let start = 0;
    for (let i = 0; i < buf.length; i++) {
        if (buf[i] === 10) { // \n
            lines.push(buf.slice(start, i + 1));
            start = i + 1;
        }
    }
    if (start < buf.length) {
        lines.push(buf.slice(start));
    }
    return lines;
}

/**
 * Removes the trailing \n from a line, if present.
 */
function stripNewline(line: Buffer): Buffer {
    if (line.length > 0 && line[line.length - 1] === 10) {
        return line.slice(0, line.length - 1);
    }
    return line;
}

/**
 * Computes the CRC-32 (zlib/PNG) checksum of the given data.
 */
function crc32(data: Buffer): string {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            crc = (crc >>> 1) ^ (crc & 1 ? 0xEDB88320 : 0);
        }
    }
    return ((crc ^ 0xFFFFFFFF) >>> 0).toString(16).padStart(8, '0');
}

interface Hunk {
    a: number;
    b: number;
    c: number;
    d: number;
    oldLines: Buffer[];
    newLines: Buffer[];
}

interface Section {
    path: string;
    kind: 'create' | 'delete' | 'modify';
    hunks: Hunk[];
}

function main() {
    const root = process.argv[2];
    if (!root) return;

    const diffPath = path.join(root, 'changes.diff');
    const treePath = path.join(root, 'tree');

    const diffContent = fs.readFileSync(diffPath);
    const diffLines = splitLines(diffContent);

    const sections: Section[] = [];
    let currentSection: Section | null = null;

    for (let i = 0; i < diffLines.length; i++) {
        const line = stripNewline(diffLines[i]);
        const lineStr = line.toString();

        if (lineStr.startsWith('diff --git ')) {
            const parts = lineStr.split(' ');
            const filePath = parts[2].slice(2);
            currentSection = { path: filePath, kind: 'modify', hunks: [] };
            sections.push(currentSection);
        } else if (currentSection && lineStr.startsWith('new file mode ')) {
            currentSection.kind = 'create';
        } else if (currentSection && lineStr.startsWith('deleted file mode ')) {
            currentSection.kind = 'delete';
        } else if (currentSection && lineStr.startsWith('@@ ')) {
            const match = lineStr.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
            if (match) {
                const a = parseInt(match[1]);
                const b = match[2] ? parseInt(match[2]) : 1;
                const c = parseInt(match[3]);
                const d = match[4] ? parseInt(match[4]) : 1;

                const hunkBody: Buffer[] = [];
                while (i + 1 < diffLines.length) {
                    const nextLine = stripNewline(diffLines[i + 1]);
                    const nextStr = nextLine.toString();
                    if (nextStr.startsWith('diff --git ') || nextStr.startsWith('@@ ')) {
                        break;
                    }
                    hunkBody.push(nextLine);
                    i++;
                }

                const oldHunkLines: Buffer[] = [];
                const newHunkLines: Buffer[] = [];
                for (let j = 0; j < hunkBody.length; j++) {
                    const bodyLine = hunkBody[j];
                    if (bodyLine.length === 0) continue;
                    const marker = bodyLine[0];
                    const content = bodyLine.slice(1);
                    if (marker === 32) { // ' '
                        const lineBuf = Buffer.concat([content, Buffer.from([10])]);
                        oldHunkLines.push(lineBuf);
                        newHunkLines.push(lineBuf);
                    } else if (marker === 45) { // '-'
                        const lineBuf = Buffer.concat([content, Buffer.from([10])]);
                        oldHunkLines.push(lineBuf);
                    } else if (marker === 43) { // '+'
                        const lineBuf = Buffer.concat([content, Buffer.from([10])]);
                        newHunkLines.push(lineBuf);
                    } else if (marker === 92 && content.toString() === ' No newline at end of file') {
                        if (j > 0) {
                            const prevMarker = hunkBody[j - 1][0];
                            if (prevMarker === 32) {
                                if (oldHunkLines.length > 0) oldHunkLines[oldHunkLines.length - 1] = oldHunkLines[oldHunkLines.length - 1].slice(0, -1);
                                if (newHunkLines.length > 0) newHunkLines[newHunkLines.length - 1] = newHunkLines[newHunkLines.length - 1].slice(0, -1);
                            } else if (prevMarker === 45) {
                                if (oldHunkLines.length > 0) oldHunkLines[oldHunkLines.length - 1] = oldHunkLines[oldHunkLines.length - 1].slice(0, -1);
                            } else if (prevMarker === 43) {
                                if (newHunkLines.length > 0) newHunkLines[newHunkLines.length - 1] = newHunkLines[newHunkLines.length - 1].slice(0, -1);
                            }
                        }
                    }
                }
                currentSection.hunks.push({ a, b, c, d, oldLines: oldHunkLines, newLines: newHunkLines });
            }
        }
    }

    const results: { path: string, output: string }[] = [];
    for (const section of sections) {
        const fullPath = path.join(treePath, section.path);
        let contentLines: Buffer[] = [];
        let error: string | null = null;

        if (section.kind === 'create') {
            if (fs.existsSync(fullPath)) {
                error = 'already exists';
            } else {
                contentLines = [];
            }
        } else {
            if (!fs.existsSync(fullPath)) {
                error = 'not found';
            } else {
                contentLines = splitLines(fs.readFileSync(fullPath));
            }
        }

        let output = `${section.path}: ${section.kind}`;
        if (error) {
            output += `\n  error: ${error}`;
        } else {
            let delta = 0;
            let allHunksApplied = true;
            for (let i = 0; i < section.hunks.length; i++) {
                const hunk = section.hunks[i];
                if (hunk.oldLines.length !== hunk.b || hunk.newLines.length !== hunk.d) {
                    output += `\n  hunk ${i + 1}: malformed`;
                    allHunksApplied = false;
                    continue;
                }

                const P = hunk.a + delta;
                let pFound = -1;
                let offset = 0;

                if (hunk.b === 0) {
                    if (P >= 0 && P <= contentLines.length) {
                        pFound = P;
                        offset = 0;
                    }
                } else {
                    for (let j = 0; ; j++) {
                        const pMinus = P - j;
                        const pPlus = P + j;
                        if (pMinus >= 1 && pMinus <= contentLines.length - hunk.b + 1) {
                            let match = true;
                            for (let k = 0; k < hunk.b; k++) {
                                if (Buffer.compare(contentLines[pMinus - 1 + k], hunk.oldLines[k]) !== 0) {
                                    match = false;
                                    break;
                                }
                            }
                            if (match) {
                                pFound = pMinus;
                                offset = pMinus - P;
                                break;
                            }
                        }
                        if (j === 0) continue;
                        if (pPlus >= 1 && pPlus <= contentLines.length - hunk.b + 1) {
                            let match = true;
                            for (let k = 0; k < hunk.b; k++) {
                                if (Buffer.compare(contentLines[pPlus - 1 + k], hunk.oldLines[k]) !== 0) {
                                    match = false;
                                    break;
                                }
                            }
                            if (match) {
                                pFound = pPlus;
                                offset = pPlus - P;
                                break;
                            }
                        }
                        if (pMinus < 1 && pPlus > contentLines.length - hunk.b + 1) break;
                    }
                }

                if (pFound !== -1) {
                    const p = pFound;
                    const oldB = hunk.b;
                    const newD = hunk.d;
                    if (oldB === 0) {
                        contentLines.splice(p, 0, ...hunk.newLines);
                    } else {
                        contentLines.splice(p - 1, oldB, ...hunk.newLines);
                    }
                    output += `\n  hunk ${i + 1}: applied at ${p} (offset ${offset > 0 ? '+' + offset : offset})`;
                    delta += newD - oldB;
                } else {
                    output += `\n  hunk ${i + 1}: rejected`;
                    allHunksApplied = false;
                }
            }

            if (section.kind === 'delete' && allHunksApplied && contentLines.length === 0) {
                output += `\n  result: deleted`;
            } else {
                const finalContent = Buffer.concat(contentLines);
                output += `\n  result: ${contentLines.length} lines, crc32 ${crc32(finalContent)}`;
            }
        }
        results.push({ path: section.path, output });
    }

    results.sort((a, b) => Buffer.compare(Buffer.from(a.path), Buffer.from(b.path)));
    for (const res of results) {
        process.stdout.write(res.output + '\n');
    }
}

main();

