void process_png(const char *filename) {
    FILE *f = fopen(filename, "rb");
    if (!f) return;
    uint8_t sig[8];
    fread(sig, 1, 8, f);
    if (memcmp(sig, "\x89PNG\r\n\x1a\n", 8) != 0) { fclose(f); return; }

