    Chunk chunks[1024];
    int chunk_count = 0;
    bool error_crc = false;

    while (1) {
        uint8_t len_buf[4];
        if (fread(len_buf, 1, 4, f) != 4) break;
        uint32_t len = read_u32_be(len_buf);
        char type[5];
        fread(type, 1, 4, f);
        type[4] = '\0';
        uint8_t *data = malloc(len);
        fread(data, 1, len, f);
        uint8_t crc_buf[4];
        fread(crc_buf, 1, 4, f);
