    return strcmp(*(const char **)a, *(const char **)b);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    init_crc32_table();
    const char *dir_path = argv[1];
    DIR *d = opendir(dir_path);
    if (!d) return 0;
    struct dirent *dir;
    char **files = malloc(1024 * sizeof(char *));
    int file_count = 0;
    while ((dir = readdir(d)) != NULL) {
        if (strstr(dir->d_name, ".png")) {
            files[file_count++] = strdup(dir->d_name);
        }
    }
    closedir(d);
    qsort(files, file_count, sizeof(char *), compare_files);

    for (int i = 0; i < file_count; i++) {
        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, files[i]);
        process_png(full_path);
        free(files[i]);
    }
    free(files);
    return 0;
}

