use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

struct Hunk {
    a: usize,
    b: usize,
    c: usize,
    d: usize,
    old_lines: Vec<Vec<u8>>,
    new_lines: Vec<Vec<u8>>,
    malformed: bool,
}

struct Section {
    path: String,
    kind: String,
    hunks: Vec<Hunk>,
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut c = i as u32;
        for _ in 0..8 {
            if c & 1 != 0 { c = (c >> 1) ^ 0xEDB88320; } else { c >>= 1; }
        }
        table[i] = c;
    }
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc = (crc >> 8) ^ table[((crc ^ (b as u32)) & 0xFF) as usize];
    }
    !crc
}

fn split_lines(data: &[u8]) -> Vec<Vec<u8>> {
    let mut lines = Vec::new();
    let mut start = 0;
    while start < data.len() {
        if let Some(pos) = data[start..].iter().position(|&b| b == b'\n') {
            lines.push(data[start..start + pos + 1].to_vec());
            start += pos + 1;
        } else {
            lines.push(data[start..].to_vec());
            start = data.len();
        }
    }
    lines
}

fn parse_range(s: &str) -> (usize, usize) {
    let s = s.trim_start_matches(|c| c == '-' || c == '+');
    if let Some(pos) = s.find(',') {
        let a = s[..pos].parse().unwrap_or(0);
        let b = s[pos + 1..].parse().unwrap_or(0);
        (a, b)
    } else {
        let a = s.parse().unwrap_or(0);
        (a, 1)
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 { return; }
    let diff_dir = &args[1];
    let tree_dir = &args[2];

    let diff_path = Path::new(diff_dir).join("changes.diff");
    let diff_data = fs::read(diff_path).unwrap_or_default();
    let diff_lines = split_lines(&diff_data);

    let mut sections = Vec::new();
    let mut i = 0;
    while i < diff_lines.len() {
        if diff_lines[i].starts_with(b"diff --git ") {
            let line_str = String::from_utf8_lossy(&diff_lines[i]);
            let parts: Vec<&str> = line_str.split_whitespace().collect();
            let path = if parts.len() >= 3 { parts[2].to_string() } else { String::new() };
            let mut kind = "modify".to_string();
            let mut j = i + 1;
            while j < diff_lines.len() && !diff_lines[j].starts_with(b"diff --git ") {
                let line_j = String::from_utf8_lossy(&diff_lines[j]);
                if line_j.starts_with("new file mode ") { kind = "create".to_string(); }
                else if line_j.starts_with("deleted file mode ") { kind = "delete".to_string(); }
                j += 1;
            }
            let mut hunks = Vec::new();
            let mut k = i + 1;
            while k < j {
                if diff_lines[k].starts_with(b"@@ ") {
                    let header = String::from_utf8_lossy(&diff_lines[k]);
                    let parts: Vec<&str> = header.split_whitespace().collect();
                    if parts.len() >= 4 {
                        let (a, b) = parse_range(parts[1]);
                        let (c, d) = parse_range(parts[2]);
                        let mut body_lines = Vec::new();
                        let mut m = k + 1;
                        while m < j && !diff_lines[m].starts_with(b"@@ ") {
                            body_lines.push(diff_lines[m].clone());
                            m += 1;
                        }
                        let mut old_lines = Vec::new();
                        let mut new_lines = Vec::new();
                        let mut last_marker = ' ';
                        for bl in &body_lines {
                            if bl.is_empty() { continue; }
                            let marker = bl[0] as char;
                            let content = &bl[1..];
                            if marker == ' ' {
                                old_lines.push(content.to_vec());
                                new_lines.push(content.to_vec());
                                last_marker = ' ';
                            } else if marker == '-' {
                                old_lines.push(content.to_vec());
                                last_marker = '-';
                            } else if marker == '+' {
                                new_lines.push(content.to_vec());
                                last_marker = '+';
                            } else if marker == '\\' && content.starts_with(b" No newline at end of file") {
                                match last_marker {
                                    ' ' => {
                                        if let Some(l) = old_lines.last_mut() { if l.last() == Some(&b'\n') { l.pop(); } }
                                        if let Some(l) = new_lines.last_mut() { if l.last() == Some(&b'\n') { l.pop(); } }
                                    }
                                    '-' => { if let Some(l) = old_lines.last_mut() { if l.last() == Some(&b'\n') { l.pop(); } } }
                                    '+' => { if let Some(l) = new_lines.last_mut() { if l.last() == Some(&b'\n') { l.pop(); } } }
                                    _ => {}
                                }
                            }
                        }
                        if old_lines.len() == b && new_lines.len() == d {
                            hunks.push(Hunk { a, b, c, d, old_lines, new_lines, malformed: false });
                        } else {
                            hunks.push(Hunk { a, b, c, d, old_lines: Vec::new(), new_lines: Vec::new(), malformed: true });
                        }
                        k = m;
                    } else { k += 1; }
                } else { k += 1; }
            }
            sections.push(Section { path, kind, hunks });
            i = j;
        } else { i += 1; }
    }

    let mut results = BTreeMap::new();
    for section in sections {
        let file_path = Path::new(tree_dir).join(&section.path);
        let mut current_lines = Vec::new();
        let mut error = None;
        if section.kind == "create" {
            if file_path.exists() { error = Some("already exists"); }
        } else {
            if !file_path.exists() { error = Some("not found"); }
            else {
                let data = fs::read(file_path).unwrap_or_default();
                current_lines = split_lines(&data);
            }
        }
        let mut output = Vec::new();
        if let Some(err) = error {
            output.push(format!("  error: {}", err));
        } else {
            let mut delta = 0;
            let mut all_applied = true;
            for (idx, hunk) in section.hunks.iter().enumerate() {
                if hunk.malformed {
                    output.push(format!("  hunk {}: malformed", idx + 1));
                    continue;
                }
                let p_expected = (hunk.a as isize) + delta;
                let mut applied = false;
                let mut p_actual = 0;
                let mut offset = 0;
                if hunk.b == 0 {
                    if p_expected >= 0 && (p_expected as usize) <= current_lines.len() {
                        let pos = p_expected as usize;
                        for (i, nl) in hunk.new_lines.iter().enumerate() {
                            current_lines.insert(pos + i, nl.clone());
                        }
                        p_actual = p_expected as usize;
                        offset = 0;
                        applied = true;
                    }
                } else {
                    let mut dist = 0;
                    loop {
                        let p_low = p_expected - dist;
                        let p_high = p_expected + dist;
                        if dist == 0 {
                            if p_low >= 1 && (p_low as usize) <= current_lines.len().saturating_sub(hunk.b - 1) + 1 {
                                if current_lines[(p_low - 1) as usize..(p_low as usize - 1 + hunk.b)] == hunk.old_lines {
                                    p_actual = p_low as usize;
                                    offset = p_low - p_expected;
                                    applied = true;
                                }
                            }
                        } else {
                            if p_low >= 1 && (p_low as usize) <= current_lines.len().saturating_sub(hunk.b - 1) + 1 {
                                if current_lines[(p_low - 1) as usize..(p_low as usize - 1 + hunk.b)] == hunk.old_lines {
                                    p_actual = p_low as usize;
                                    offset = p_low - p_expected;
                                    applied = true;
                                }
                            }
                            if !applied && p_high >= 1 && (p_high as usize) <= current_lines.len().saturating_sub(hunk.b - 1) + 1 {
                                if current_lines[(p_high - 1) as usize..(p_high as usize - 1 + hunk.b)] == hunk.old_lines {
                                    p_actual = p_high as usize;
                                    offset = p_high - p_expected;
                                    applied = true;
                                }
                            }
                        }
                        if applied || dist > (current_lines.len() as isize + 1).max(p_expected.abs()) { break; }
                        dist += 1;
                    }
                    if applied {
                        let pos = p_actual - 1;
                        current_lines.splice(pos..pos + hunk.b, hunk.new_lines.iter().cloned());
                    }
                }
                if applied {
                    let off_str = if offset > 0 { format!("+{}", offset) } else if offset < 0 { format!("{}", offset) } else { "0".to_string() };
                    output.push(format!("  hunk {}: applied at {} (offset {})", idx + 1, p_actual, off_str));
                    delta += (hunk.d as isize) - (hunk.b as isize);
                } else {
                    output.push(format!("  hunk {}: rejected", idx + 1));
                    all_applied = false;
                }
            }
            if section.kind == "delete" && all_applied && current_lines.is_empty() {
                output.push("  result: deleted".to_string());
            } else {
                let mut final_data = Vec::new();
                for l in &current_lines { final_data.extend_from_slice(l); }
                output.push(format!("  result: {} lines, crc32 {:08x}", current_lines.len(), crc32(&final_data)));
            }
        }
        results.insert(section.path, (section.kind, output));
    }

    for (path, (kind, output)) in results {
        println!("{}: {}", path, kind);
        for line in output { println!("{}", line); }
    }
}

