// Precompute CRC table for PNG chunk checksums
const CRC_TABLE = new Uint32Array(256);
for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    CRC_TABLE[i] = c >>> 0;
}

function fastCrc32(data: Uint8Array): number {
    let crc = 0xffffffff;
    for (let i = 0; i < data.length; i++) {
        crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ data[i]) & 0xff];
    }
    return (crc ^ 0xffffffff) >>> 0;
}

function createChunk(type: string, data: Buffer) {
    const typeBuf = Buffer.from(type);
    const lengthBuf = Buffer.alloc(4);
    lengthBuf.writeUInt32BE(data.length, 0);
    const chunkData = Buffer.concat([typeBuf, data]);
    const crc = fastCrc32(chunkData);
    const crcBuf = Buffer.alloc(4);
    crcBuf.writeUInt32BE(crc, 0);
    return Buffer.concat([lengthBuf, chunkData, crcBuf]);
}

function createPNG(width: number, height: number, data: Uint8ClampedArray) {
    const pngSignature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

    const ihdrData = Buffer.alloc(13);
    ihdrData.writeUInt32BE(width, 0);
    ihdrData.writeUInt32BE(height, 4);
    ihdrData[8] = 8; // bit depth
    ihdrData[9] = 2; // color type: RGB
    ihdrData[10] = 0; // compression
    ihdrData[11] = 0; // filter
    ihdrData[12] = 0; // interlace
    const ihdrChunk = createChunk('IHDR', ihdrData);

    const rawData = Buffer.alloc((width * 3 + 1) * height);
    let offset = 0;
    for (let y = 0; y < height; y++) {
        rawData[offset++] = 0; // Filter type 0 (None)
        for (let x = 0; x < width; x++) {
            rawData[offset++] = data[(y * width + x) * 3];
            rawData[offset++] = data[(y * width + x) * 3 + 1];
            rawData[offset++] = data[(y * width + x) * 3 + 2];
        }
    }
    const idatData = zlib.deflateSync(rawData);
    const idatChunk = createChunk('IDAT', idatData);
    const iendChunk = createChunk('IEND', Buffer.alloc(0));

    return Buffer.concat([pngSignature, ihdrChunk, idatChunk, iendChunk]);
}

function main() {
    const dir = process.argv[2];
    if (!dir) return;

    const sceneData = JSON.parse(fs.readFileSync(path.join(dir, 'scene.json'), 'utf8'));
    const scene: Scene = sceneData;

    const { width, height, background, shapes } = scene;
    const canvas = new Uint8ClampedArray(width * height * 3);

    // Initialize canvas with background color
    for (let i = 0; i < width * height * 3; i += 3) {
        canvas[i] = background[0];
        canvas[i + 1] = background[1];
        canvas[i + 2] = background[2];
    }

    for (let sIdx = 0; sIdx < shapes.length; sIdx++) {
        const shape = shapes[sIdx];
        const [sR, sG, sB, sA] = shape.color;
        let coveredCount = 0;

        // Optimization: calculate bounding box for each shape to reduce pixel checks
        let xMin = 0, xMax = width - 1;
        let yMin = 0, yMax = height - 1;

        if (shape.type === 'rect') {
            xMin = Math.max(0, shape.x!);
            xMax = Math.min(width - 1, shape.x! + shape.w! - 1);
            yMin = Math.max(0, shape.y!);
            yMax = Math.min(height - 1, shape.y! + shape.h! - 1);
        } else if (shape.type === 'circle') {
            xMin = Math.max(0, shape.cx! - shape.r!);
            xMax = Math.min(width - 1, shape.cx! + shape.r!);
            yMin = Math.max(0, shape.cy! - shape.r!);
            yMax = Math.min(height - 1, shape.cy! + shape.r!);
        } else if (shape.type === 'triangle') {
            const pts = shape.points!;
            xMin = Math.max(0, Math.min(pts[0][0], pts[1][0], pts[2][0]));
            xMax = Math.min(width - 1, Math.max(pts[0][0], pts[1][0], pts[2][0]));
            yMin = Math.max(0, Math.min(pts[0][1], pts[1][1], pts[2][1]));
            yMax = Math.min(height - 1, Math.max(pts[0][1], pts[1][1], pts[2][1]));
        } else if (shape.type === 'line') {
            xMin = Math.max(0, Math.min(shape.x1!, shape.x2!) - shape.r!);
            xMax = Math.min(width - 1, Math.max(shape.x1!, shape.x2!) + shape.r!);
            yMin = Math.max(0, Math.min(shape.y1!, shape.y2!) - shape.r!);
            yMax = Math.min(height - 1, Math.max(shape.y1!, shape.y2!) + shape.r!);
        }

        for (let y = yMin; y <= yMax; y++) {
            for (let x = xMin; x <= xMax; x++) {
                let covered = false;
                if (shape.type === 'rect') {
                    covered = (x >= shape.x! && x < shape.x! + shape.w! && y >= shape.y! && y < shape.y! + shape.h!);
                } else if (shape.type === 'circle') {
                    covered = ((x - shape.cx!) ** 2 + (y - shape.cy!) ** 2 <= shape.r! ** 2);
                } else if (shape.type === 'triangle') {
                    const pts = shape.points!;
                    const e0 = (pts[1][0] - pts[0][0]) * (y - pts[0][1]) - (pts[1][1] - pts[0][1]) * (x - pts[0][0]);
                    const e1 = (pts[2][0] - pts[1][0]) * (y - pts[1][1]) - (pts[2][1] - pts[1][1]) * (x - pts[1][0]);
                    const e2 = (pts[0][0] - pts[2][0]) * (y - pts[2][1]) - (pts[0][1] - pts[2][1]) * (x - pts[2][0]);
                    covered = (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0);
                } else if (shape.type === 'line') {
                    const dx = shape.x2! - shape.x1!;
                    const dy = shape.y2! - shape.y1!;
                    const L = dx * dx + dy * dy;
                    const t = (x - shape.x1!) * dx + (y - shape.y1!) * dy;
                    if (t <= 0) {
                        covered = ((x - shape.x1!) ** 2 + (y - shape.y1!) ** 2 <= shape.r! ** 2);
                    } else if (t >= L) {
                        covered = ((x - shape.x2!) ** 2 + (y - shape.y2!) ** 2 <= shape.r! ** 2);
                    } else {
                        const c = (x - shape.x1!) * dy - (y - shape.y1!) * dx;
                        covered = (c * c <= shape.r! * shape.r! * L);
                    }
                }

                if (covered) {
                    coveredCount++;
                    const idx = (y * width + x) * 3;
                    canvas[idx] = (sR * sA + canvas[idx] * (255 - sA) + 127) / 255 | 0;
                    canvas[idx + 1] = (sG * sA + canvas[idx + 1] * (255 - sA) + 127) / 255 | 0;
                    canvas[idx + 2] = (sB * sA + canvas[idx + 2] * (255 - sA) + 127) / 255 | 0;
                }
            }
        }
        process.stdout.write(`${sIdx + 1} ${shape.type} ${coveredCount}\n`);
    }

    const distinctColors = new Set<number>();
    for (let i = 0; i < canvas.length; i += 3) {
        const color = (canvas[i] << 16) | (canvas[i + 1] << 8) | canvas[i + 2];
        distinctColors.add(color);
    }
    process.stdout.write(`colors ${distinctColors.size}\n`);

    const pngBuffer = createPNG(width, height, canvas);
    fs.writeFileSync('out.png', pngBuffer);
}

main();

import Foundation

// MARK: - PNG Writing Helpers

extension UInt32 {
    var littleEndianBytes: [UInt8] {
        [UInt8(self & 0xFF), UInt8((self >> 8) & 0xFF), UInt8((self >> 16) & 0xFF), UInt8((self >> 24) & 0xFF)]
    }
    var bigEndianBytes: [UInt8] {
        [UInt8((self >> 24) & 0xFF), UInt8((self >> 16) & 0xFF), UInt8((self >> 8) & 0xFF), UInt8(self & 0xFF)]
    }
}

extension UInt16 {
    var littleEndianBytes: [UInt8] {
        [UInt8(self & 0xFF), UInt8((self >> 8) & 0xFF)]
    }
}

func computeCRC32(_ data: Data) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if (crc & 1) != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return ~crc
}

func computeCRC16(_ data: Data) -> UInt16 {
    var crc: UInt16 = 0
    for byte in data {
        crc ^= UInt16(byte)
        for _ in 0..<8 {
            if (crc & 1) != 0 {
                crc = (crc >> 1) ^ 0xA001
            } else {
                crc >>= 1
            }
        }
    }
    return crc
}

func computeAdler32(_ data: Data) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for byte in data {
        a = (a + UInt32(byte)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

func writeChunk(type: String, data: Data) -> Data {
    var chunk = Data()
    let typeData = type.data(using: .utf8)!
    let length = UInt32(data.count)
    chunk.append(contentsOf: length.littleEndianBytes)
    chunk.append(typeData)
    chunk.append(data)

    var crcData = typeData
    crcData.append(data)
    let crc = computeCRC32(crcData)
    chunk.append(contentsOf: crc.littleEndianBytes)

    return chunk
}

func savePNG(width: Int, height: Int, pixels: [UInt8]) {
    var output = Data()

    // PNG Signature
    output.append(contentsOf: [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])

    // IHDR Chunk
    var ihdrData = Data()
    ihdrData.append(contentsOf: UInt32(width).littleEndianBytes)
    ihdrData.append(contentsOf: UInt32(height).littleEndianBytes)
    ihdrData.append(8) // Bit depth
    ihdrData.append(2) // Color type (RGB)
    ihdrData.append(0) // Compression
    ihdrData.append(0) // Filter
    ihdrData.append(0) // Interlace
    output.append(writeChunk(type: "IHDR", data: ihdrData))

    // IDAT Chunk
    var idatRaw = Data()
    for y in 0..<height {
        idatRaw.append(0) // Filter byte (None)
        let start = y * width * 3
        idatRaw.append(contentsOf: pixels[start..<(start + width * 3)])
    }

    var zlibData = Data()
    zlibData.append(0x78)
    zlibData.append(0x01) // Zlib header: CM=8, CINFO=7, FCHECK=1

    var offset = 0
    while offset < idatRaw.count {
        let len = min(65535, idatRaw.count - offset)
        let bfinal: UInt8 = (offset + len == idatRaw.count) ? 1 : 0
        zlibData.append(bfinal | 0x02) // BFINAL | (BTYPE 01 << 1)

        let lenUInt16 = UInt16(len)
        zlibData.append(contentsOf: lenUInt16.littleEndianBytes)
        zlibData.append(contentsOf: (~lenUInt16).littleEndianBytes)

        let blockData = idatRaw[offset..<(offset + len)]
        zlibData.append(blockData)

        let crc16 = computeCRC16(blockData)
        zlibData.append(contentsOf: crc16.littleEndianBytes)

        offset += len
    }

    let adler = computeAdler32(idatRaw)
    zlibData.append(contentsOf: adler.bigEndianBytes)
    output.append(writeChunk(type: "IDAT", data: zlibData))

    // IEND Chunk
    output.append(writeChunk(type: "IEND", data: Data()))

    try? output.write(to: URL(fileURLWithPath: "out.png"))
}

// MARK: - Rendering Logic

struct Shape {
    let type: String
    let color: [Int]
    let params: [String: Any]
}

func isCovered(x: Int, y: Int, shape: Shape) -> Bool {
    switch shape.type {
    case "rect":
        let rx = shape.params["x"] as! Int
        let ry = shape.params["y"] as! Int
        let w = shape.params["w"] as! Int
        let h = shape.params["h"] as! Int
        return x >= rx && x < rx + w && y >= ry && y < ry + h
    case "circle":
        let cx = shape.params["cx"] as! Int
        let cy = shape.params["cy"] as! Int
        let r = shape.params["r"] as! Int
        let dx = Int64(x - cx)
        let dy = Int64(y - cy)
        return dx * dx + dy * dy <= Int64(r) * Int64(r)
    case "triangle":
        let points = shape.params["points"] as! [[Int]]
        let p0 = points[0], p1 = points[1], p2 = points[2]
        func crossProduct(pi: [Int], pj: [Int], px: Int, py: Int) -> Int64 {
            let dx = Int64(pj[0] - pi[0])
            let dy = Int64(pj[1] - pi[1])
            let dpx = Int64(px - pi[0])
            let dpy = Int64(py - pi[1])
            return dx * dpy - dy * dpx
        }
        let e0 = crossProduct(pi: p0, pj: p1, px: x, py: y)
        let e1 = crossProduct(pi: p1, pj: p2, px: x, py: y)
        let e2 = crossProduct(pi: p2, pj: p0, px: x, py: y)
        return (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
    case "line":
        let x1 = shape.params["x1"] as! Int
        let y1 = shape.params["y1"] as! Int
        let x2 = shape.params["x2"] as! Int
        let y2 = shape.params["y2"] as! Int
        let r = shape.params["r"] as! Int
        let dx = Int64(x2 - x1)
        let dy = Int64(y2 - y1)
        let l = dx * dx + dy * dy
        let t = Int64(x - x1) * dx + Int64(y - y1) * dy
        if t <= 0 {
            let dpx = Int64(x - x1)
            let dpy = Int64(y - y1)
            return dpx * dpx + dpy * dpy <= Int64(r) * Int64(r)
        } else if t >= l {
            let dpx = Int64(x - x2)
            let dpy = Int64(y - y2)
            return dpx * dpx + dpy * dpy <= Int64(r) * Int64(r)
        } else {
            let c = Int64(x - x1) * dy - Int64(y - y1) * dx
            return c * c <= Int64(r) * Int64(r) * l
        }
    default:
        return false
    }
}

