        let ry = shape.params["y"] as! Int
        let w = shape.params["w"] as! Int
        let h = shape.params["h"] as! Int
        return x >= rx && x < rx + w && y >= ry && y < ry + h
    case "circle":
        let cx = shape.params["cx"] as! Int
        let cy = shape.params["cy"] as! Int
        let r = shape.params["r"] as! Int
        let dx = Int64(x - cx)
        let dy = Int64(y - cy)
