            let dpy = Int64(py - pi[1])
            return dx * dpy - dy * dpx
        }
        let e0 = crossProduct(pi: p0, pj: p1, px: x, py: y)
        let e1 = crossProduct(pi: p1, pj: p2, px: x, py: y)
        let e2 = crossProduct(pi: p2, pj: p0, px: x, py: y)
