                canvas[pos + 2] = UInt8((sB * sA + dB * (255 - sA) + 127) / 255)
            }
        }
    }
    print("\(idx + 1) \(shape.type) \(coveredPixels)")
}

var distinctColors = Set<UInt32>()
for y in 0..<height {
    for x in 0..<width {
        let pos = (y * width + x) * 3
        let color = (UInt32(canvas[pos]) << 16) | (UInt32(canvas[pos + 1]) << 8) | UInt32(canvas[pos + 2])
        distinctColors.insert(color)
    }
}
print("colors \(distinctColors.count)")

savePNG(width: width, height: height, pixels: canvas)

use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::path::Path;
use std::rc::Rc;

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Let, Fn, If, Else, While, For, In, Return, Break, Continue, And, Or, Not, True, False, Nil,
    Ident(String), Int(i64), String(String),
    EqEq, NotEq, Leq, Geq, Lt, Gt, Eq, Plus, Minus, Star, Slash, Percent,
    LParen, RParen, LBracket, RBracket, LBrace, RBrace, Comma, Semicolon,
}

struct Lexer {
    input: Vec<char>,
    pos: usize,
    line: usize,
}

impl Lexer {
    fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
            line: 1,
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += 1;
        if c == '\n' {
            self.line += 1;
        }
        Some(c)
    }

    fn next_token(&mut self) -> Option<(Token, usize)> {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.next();
            } else if c == '#' {
                while let Some(nc) = self.peek() {
                    if nc == '\n' { break; }
                    self.next();
                }
            } else {
                break;
            }
        }

        let line = self.line;
        let c = self.next()?;
        match c {
            '(' => Some((Token::LParen, line)),
            ')' => Some((Token::RParen, line)),
            '[' => Some((Token::LBracket, line)),
            ']' => Some((Token::RBracket, line)),
            '{' => Some((Token::LBrace, line)),
            '}' => Some((Token::RBrace, line)),
            ',' => Some((Token::Comma, line)),
            ';' => Some((Token::Semicolon, line)),
            '=' => if self.peek() == Some('=') { self.next(); Some((Token::EqEq, line)) } else { Some((Token::Eq, line)) },
            '!' => if self.peek() == Some('=') { self.next(); Some((Token::NotEq, line)) } else { panic!("Unexpected !") },
            '<' => if self.peek() == Some('=') { self.next(); Some((Token::Leq, line)) } else { Some((Token::Lt, line)) },
            '>' => if self.peek() == Some('=') { self.next(); Some((Token::Geq, line)) } else { Some((Token::Gt, line)) },
            '+' => Some((Token::Plus, line)),
            '-' => Some((Token::Minus, line)),
            '*' => Some((Token::Star, line)),
            '/' => Some((Token::Slash, line)),
            '%' => Some((Token::Percent, line)),
            '"' => {
                let mut s = String::new();
                while let Some(nc) = self.next() {
                    if nc == '"' { break; }
                    match nc {
                        '\\' => match self.next() {
                            Some('n') => s.push('\n'),
                            Some('t') => s.push('\t'),
                            Some('"') => s.push('"'),
                            Some('\\') => s.push('\\'),
                            _ => {},
                        },
                        _ => s.push(nc),
                    }
                }
                Some((Token::String(s), line))
            }
            c if c.is_ascii_digit() => {
                let mut s = String::new();
                s.push(c);
                while let Some(nc) = self.peek() {
                    if nc.is_ascii_digit() { s.push(nc); self.next(); } else { break; }
                }
                Some((Token::Int(s.parse().unwrap()), line))
            }
            c if c.is_alphabetic() || c == '_' => {
                let mut s = String::new();
                s.push(c);
                while let Some(nc) = self.peek() {
                    if nc.is_alphanumeric() || nc == '_' { s.push(nc); self.next(); } else { break; }
                }
                let token = match s.as_str() {
                    "let" => Token::Let, "fn" => Token::Fn, "if" => Token::If, "else" => Token::Else,
                    "while" => Token::While, "for" => Token::For, "in" => Token::In, "return" => Token::Return,
                    "break" => Token::Break, "continue" => Token::Continue, "and" => Token::And, "or" => Token::Or,
                    "not" => Token::Not, "true" => Token::True, "false" => Token::False, "nil" => Token::Nil,
                    _ => Token::Ident(s),
                };
                Some((token, line))
            }
            _ => None,
        }
    }
}

#[derive(Clone)]
enum Expr {
    Binary(Box<Expr>, Token, Box<Expr>),
    Unary(Token, Box<Expr>),
    Call(Box<Expr>, Vec<Expr>),
    Index(Box<Expr>, Box<Expr>),
    Int(i64), String(String), Bool(bool), Nil,
    Ident(String),
    List(Vec<Expr>),
    Closure(Vec<String>, Vec<Stmt>),
}

enum Stmt {
    Let(String, Expr),
    FnDecl(String, Vec<String>, Vec<Stmt>),
    If(Expr, Vec<Stmt>, Option<Box<Stmt>>),
    While(Expr, Vec<Stmt>),
    For(String, Expr, Vec<Stmt>),
    Return(Option<Expr>),
    Break,
    Continue,
    Assign(Expr, Expr),
    ExprStmt(Expr),
}

struct Parser {
    tokens: Vec<(Token, usize)>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos).map(|t| &t.0)
    }

    fn next(&mut self) -> Option<&Token> {
        let t = self.peek()?;
        self.pos += 1;
        Some(t)
    }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while self.peek().is_some() {
            stmts.push(self.parse_stmt());
        }
        stmts
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.next() {
            Some(Token::Let) => {
                let name = if let Some(Token::Ident(n)) = self.next() { n.clone() } else { panic!() };
                self.next(); // =
                let e = self.parse_expr();
                self.next(); // ;
                Stmt::Let(name, e)
            }
            Some(Token::Fn) => {
                let name = if let Some(Token::Ident(n)) = self.next() { n.clone() } else { panic!() };
                self.next(); // (
                let mut params = Vec::new();
                while let Some(Token::Ident(n)) = self.next() {
                    params.push(n.clone());
                    if self.peek() == Some(&Token::Comma) { self.next(); } else { break; }
                }
                self.next(); // )
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body)
            }
            Some(Token::If) => {
                let cond = self.parse_expr();
                let then_block = self.parse_block();
                let mut else_stmt = None;
                if self.peek() == Some(&Token::Else) {
                    self.next();
                    if self.peek() == Some(&Token::If) {
                        else_stmt = Some(Box::new(self.parse_stmt()));
                    } else {
                        else_stmt = Some(Box::new(Stmt::ExprStmt(self.parse_block_as_expr())));
                    }
                }
                Stmt::If(cond, then_block, else_stmt)
            }
            Some(Token::While) => {
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While(cond, body)
            }
            Some(Token::For) => {
                let name = if let Some(Token::Ident(n)) = self.next() { n.clone() } else { panic!() };
                self.next(); // in
                let e = self.parse_expr();
                let body = self.parse_block();
                Stmt::For(name, e, body)
            }
            Some(Token::Return) => {
                let e = if self.peek() != Some(&Token::Semicolon) { Some(self.parse_expr()) } else { None };
                self.next(); // ;
                Stmt::Return(e)
            }
            Some(Token::Break) => { self.next(); Stmt::Break }
            Some(Token::Continue) => { self.next(); Stmt::Continue }
            _ => {
                let e = self.parse_expr();
                if self.peek() == Some(&Token::LBracket) {
                    self.next();
                    let idx = self.parse_expr();
                    self.next(); // ]
                    if self.peek() == Some(&Token::Eq) {
                        self.next();
                        let val = self.parse_expr();
                        self.next(); // ;
                        Stmt::Assign(e, val) // simplified: postfix[idx] = val
                    } else {
                        self.next(); // ;
                        Stmt::ExprStmt(e) // simplified
                    }
                } else {
                    self.next(); // ;
                    Stmt::ExprStmt(e)
                }
            }
        }
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.next(); // {
        let mut stmts = Vec::new();
        while self.peek() != Some(&Token::RBrace) {
            stmts.push(self.parse_stmt());
        }
        self.next(); // }
        stmts
    }

    fn parse_block_as_expr(&mut self) -> Expr {
        let stmts = self.parse_block();
        Expr::Closure(Vec::new(), stmts) // This is not quite right but the grammar says block
    }

    fn parse_expr(&mut self) -> Expr {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Expr {
        let mut e = self.parse_and();
        while self.peek() == Some(&Token::Or) {
            let op = self.next().unwrap().clone();
            let right = self.parse_and();
            e = Expr::Binary(Box::new(e), op, Box::new(right));
        }
        e
    }

    fn parse_and(&mut self) -> Expr {
        let mut e = self.parse_not();
        while self.peek() == Some(&Token::And) {
            let op = self.next().unwrap().clone();
            let right = self.parse_not();
            e = Expr::Binary(Box::new(e), op, Box::new(right));
        }
        e
    }

    fn parse_not(&mut self) -> Expr {
        if self.peek() == Some(&Token::Not) {
            let op = self.next().unwrap().clone();
            Expr::Unary(op, Box::new(self.parse_not()))
        } else {
            self.parse_comparison()
        }
    }

    fn parse_comparison(&mut self) -> Expr {
        let mut e = self.parse_term();
        while let Some(op) = self.peek() {
            match op {
                Token::EqEq | Token::NotEq | Token::Lt | Token::Leq | Token::Gt | Token::Geq => {
                    let op = self.next().unwrap().clone();
                    let right = self.parse_term();
                    e = Expr::Binary(Box::new(e), op, Box::new(right));
                }
                _ => break,
            }
        }
        e
    }

    fn parse_term(&mut self) -> Expr {
        let mut e = self.parse_factor();
        while let Some(op) = self.peek() {
            match op {
                Token::Plus | Token::Minus => {
                    let op = self.next().unwrap().clone();
                    let right = self.parse_factor();
                    e = Expr::Binary(Box::new(e), op, Box::new(right));
                }
                _ => break,
            }
        }
        e
    }

    fn parse_factor(&mut self) -> Expr {
        let mut e = self.parse_unary();
        while let Some(op) = self.peek() {
            match op {
                Token::Star | Token::Slash | Token::Percent => {
                    let op = self.next().unwrap().clone();
                    let right = self.parse_unary();
                    e = Expr::Binary(Box::new(e), op, Box::new(right));
                }
                _ => break,
            }
        }
        e
    }

    fn parse_unary(&mut self) -> Expr {
        if self.peek() == Some(&Token::Minus) {
            let op = self.next().unwrap().clone();
            Expr::Unary(op, Box::new(self.parse_unary()))
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        while let Some(t) = self.peek() {
            match t {
                Token::LParen => {
                    self.next();
                    let mut args = Vec::new();
                    if self.peek() != Some(&Token::RParen) {
                        args.push(self.parse_expr());
                        while self.peek() == Some(&Token::Comma) {
                            self.next();
                            args.push(self.parse_expr());
                        }
                    }
                    self.next(); // )
                    e = Expr::Call(Box::new(e), args);
                }
                Token::LBracket => {
                    self.next();
                    let idx = self.parse_expr();
                    self.next(); // ]
                    e = Expr::Index(Box::new(e), Box::new(idx));
                }
                _ => break,
            }
        }
        e
    }

    fn parse_primary(&mut self) -> Expr {
        match self.next() {
            Some(Token::Int(i)) => Expr::Int(*i),
            Some(Token::String(s)) => Expr::String(s.clone()),
            Some(Token::True) => Expr::Bool(true),
            Some(Token::False) => Expr::Bool(false),
            Some(Token::Nil) => Expr::Nil,
            Some(Token::Ident(s)) => Expr::Ident(s.clone()),
            Some(Token::LParen) => {
                let e = self.parse_expr();
                self.next(); // )
                e
            }
            Some(Token::LBracket) => {
                let mut elements = Vec::new();
                if self.peek() != Some(&Token::RBracket) {
                    elements.push(self.parse_expr());
                    while self.peek() == Some(&Token::Comma) {
                        self.next();
                        elements.push(self.parse_expr());
                    }
                }
                self.next(); // ]
                Expr::List(elements)
            }
            Some(Token::Fn) => {
                self.next(); // (
                let mut params = Vec::new();
                while let Some(Token::Ident(n)) = self.next() {
                    params.push(n.clone());
                    if self.peek() == Some(&Token::Comma) { self.next(); } else { break; }
                }
                self.next(); // )
                let body = self.parse_block();
                Expr::Closure(params, body)
            }
            _ => panic!("Unexpected token"),
        }
    }
}

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    String(String),
    List(Rc<RefCell<Vec<Value>>>),
    Function(Rc<FunctionValue>),
    Nil,
}

struct FunctionValue {
    params: Vec<String>,
    body: Vec<Stmt>,
    closure: Rc<RefCell<Scope>>,
}

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

enum ControlFlow {
    Continue,
    Break,
    Return(Value),
    None,
}

struct Interpreter {
    current_scope: Rc<RefCell<Scope>>,
    call_stack_depth: usize,
}

impl Interpreter {
    fn new() -> Self {
        let mut builtins = HashMap::new();
        builtins.insert("print".to_string(), Value::Function(Rc::new(FunctionValue {
            params: vec![], body: vec![], closure: Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: None })),
        }))); // Special handling for builtins

        let global_scope = Rc::new(RefCell::new(Scope {
            vars: HashMap::new(),
            parent: None,
        }));

        Interpreter {
            current_scope: global_scope,
            call_stack_depth: 0,
        }
    }

    fn type_name(v: &Value) -> &'static str {
        match v {
            Value::Int(_) => "int",
            Value::Bool(_) => "bool",
            Value::String(_) => "string",
            Value::List(_) => "list",
            Value::Function(_) => "function",
            Value::Nil => "nil",
        }
    }

    fn is_truthy(v: &Value) -> bool {
        match v {
            Value::Int(i) => *i != 0,
            Value::Bool(b) => *b,
            Value::String(s) => !s.is_empty(),
            Value::List(l) => !l.borrow().is_empty(),
            Value::Nil => false,
            Value::Function(_) => true,
        }
    }

    fn display(v: &Value, visited: &mut HashSet<*const Vec<Value>>) -> String {
        match v {
            Value::Int(i) => i.to_string(),
            Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Value::Nil => "nil".to_string(),
            Value::String(s) => s.clone(),
            Value::Function(_) => "<fn>".to_string(),
            Value::List(l) => {
                let bor = l.borrow();
                let ptr = bor.as_ptr();
                if visited.contains(&ptr) {
                    "[...]".to_string()
                } else {
                    visited.insert(ptr);
                    let mut res = String::from("[");
                    for (i, val) in bor.iter().enumerate() {
                        if i > 0 { res.push_str(", "); }
                        match val {
                            Value::String(s) => {
                                res.push('"');
                                for c in s.chars() {
                                    match c {
                                        '\\' => res.push_str("\\\\"),
                                        '"' => res.push_str("\\\""),
                                        '\n' => res.push_str("\\n"),
                                        '\t' => res.push_str("\\t"),
                                        _ => res.push(c),
                                    }
                                }
                                res.push('"');
                            }
                            _ => res.push_str(&Self::display(val, visited)),
                        }
                    }
                    res.push(']');
                    visited.remove(&ptr);
                    res
                }
            }
        }
    }

    fn eval_expr(&mut self, expr: &Expr, token_line: usize) -> Value {
        match expr {
            Expr::Int(i) => Value::Int(*i),
            Expr::String(s) => Value::String(s.clone()),
            Expr::Bool(b) => Value::Bool(*b),
            Expr::Nil => Value::Nil,
            Expr::Ident(name) => {
                let mut scope = self.current_scope.clone();
                loop {
                    if let Some(val) = scope.borrow().vars.get(name) {
                        return val.clone();
                    }
                    if let Some(parent) = &scope.borrow().parent {
                        scope = parent.clone();
                    } else {
                        self.runtime_error(token_line, &format!("undefined variable {}", name), name);
                        return Value::Nil;
                    }
                }
            }
            Expr::Binary(left, op, right) => {
                let lv = self.eval_expr(left, token_line);
                let rv = self.eval_expr(right, token_line);
                match op {
                    Token::Or => if Self::is_truthy(&lv) { lv } else { rv },
                    Token::And => if !Self::is_truthy(&lv) { lv } else { rv },
                    Token::EqEq | Token::NotEq => {
                        let eq = match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => a == b,
                            (Value::Bool(a), Value::Bool(b)) => a == b,
                            (Value::String(a), Value::String(b)) => a == b,
                            (Value::Nil, Value::Nil) => true,
                            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
                            (Value::List(a), Value::List(b)) => {
                                fn list_eq(a: &Vec<Value>, b: &Vec<Value>) -> bool {
                                    if a.len() != b.len() { return false; }
                                    for (va, vb) in a.iter().zip(b.iter()) {
                                        if !val_eq(va, vb) { return false; }
                                    }
                                    true
                                }
                                fn val_eq(a: &Value, b: &Value) -> bool {
                                    match (a, b) {
                                        (Value::Int(x), Value::Int(y)) => x == y,
                                        (Value::Bool(x), Value::Bool(y)) => x == y,
                                        (Value::String(x), Value::String(y)) => x == y,
                                        (Value::Nil, Value::Nil) => true,
                                        (Value::Function(x), Value::Function(y)) => Rc::ptr_eq(x, y),
                                        (Value::List(x), Value::List(y)) => {
                                            let ax = x.borrow();
                                            let ay = y.borrow();
                                            if ax.len() != ay.len() { return false; }
                                            for (va, vb) in ax.iter().zip(ay.iter()) {
                                                if !val_eq(va, vb) { return false; }
                                            }
                                            true
                                        }
                                        _ => false,
                                    }
                                }
                                list_eq(&lv_list(&lv), &lv_list(&rv))
                            }
                            _ => false,
                        };
                        if let Token::EqEq = op { if eq { Value::Bool(true) } else { Value::Bool(false) } } else { if eq { Value::Bool(false) } else { Value::Bool(true) } }
                    }
                    Token::Lt | Token::Leq | Token::Gt | Token::Geq => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                let res = match op {
                                    Token::Lt => a < b, Token::Leq => a <= b, Token::Gt => a > b, Token::Geq => a >= b,
                                    _ => unreachable!(),
                                };
                                Value::Bool(res)
                            }
                            (Value::String(a), Value::String(b)) => {
                                let res = match op {
                                    Token::Lt => a < b, Token::Leq => a <= b, Token::Gt => a > b, Token::Geq => a >= b,
                                    _ => unreachable!(),
                                };
                                Value::Bool(res)
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply {:?} to {} and {}", op, Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    Token::Plus => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                if let Some(res) = a.checked_add(*b) { Value::Int(res) } else {
                                    self.runtime_error(token_line, "integer overflow", op);
                                    Value::Nil
                                }
                            }
                            (Value::String(a), Value::String(b)) => Value::String(format!("{}{}", a, b)),
                            (Value::List(a), Value::List(b)) => {
                                let mut res = a.borrow().clone();
                                res.extend(b.borrow().clone());
                                Value::List(Rc::new(RefCell::new(res)))
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply + to {} and {}", Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    Token::Minus | Token::Star | Token::Slash | Token::Percent => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                if let Token::Slash | Token::Percent = op {
                                    if *b == 0 {
                                        self.runtime_error(token_line, "division by zero", op);
                                        return Value::Nil;
                                    }
                                }
                                let res = match op {
                                    Token::Minus => a.checked_sub(*b),
                                    Token::Star => a.checked_mul(*b),
                                    Token::Slash => Some(a / b),
                                    Token::Percent => Some(a % b),
                                    _ => unreachable!(),
                                };
                                if let Some(r) = res { Value::Int(r) } else {
                                    self.runtime_error(token_line, "integer overflow", op);
                                    Value::Nil
                                }
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply {:?} to {} and {}", op, Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Unary(op, expr) => {
                let v = self.eval_expr(expr, token_line);
                match op {
                    Token::Not => Value::Bool(!Self::is_truthy(&v)),
                    Token::Minus => {
                        if let Value::Int(i) = v {
                            if let Some(res) = i.checked_neg() { Value::Int(res) } else {
                                self.runtime_error(token_line, "integer overflow", op);
                                Value::Nil
                            }
                        } else {
                            self.runtime_error(token_line, &format!("cannot apply - to {}", Self::type_name(&v)), op);
                            Value::Nil
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Call(callee_expr, args_exprs) => {
                let callee = self.eval_expr(callee_expr, token_line);
                let mut args = Vec::new();
                for ae in args_exprs {
                    args.push(self.eval_expr(ae, token_line));
                }
                self.call_function(callee, args, token_line)
            }
            Expr::Index(obj_expr, idx_expr) => {
                let obj = self.eval_expr(obj_expr, token_line);
                let idx = self.eval_expr(idx_expr, token_line);
                match (&obj, &idx) {
                    (Value::List(l), Value::Int(i)) => {
                        let bor = l.borrow();
                        if *i >= 0 && (*i as usize) < bor.len() {
                            bor[*i as usize].clone()
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, bor.len()), &Token::LBracket);
                            Value::Nil
                        }
                    }
                    (Value::String(s), Value::Int(i)) => {
                        if *i >= 0 && (*i as usize) < s.len() {
                            Value::String(s.as_bytes()[*i as usize] as char).to_string().into() // wait, a one-char string
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, s.len()), &Token::LBracket);
                            Value::Nil
                        }
                    }
                    (Value::List(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index list with {}", Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                    (Value::String(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index string with {}", Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                    _ => {
                        self.runtime_error(token_line, &format!("cannot index {} with {}", Self::type_name(&obj), Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                }
            }
            Expr::List(elements) => {
                let mut list = Vec::new();
                for e in elements {
                    list.push(self.eval_expr(e, token_line));
                }
                Value::List(Rc::new(RefCell::new(list)))
            }
            Expr::Closure(params, body) => {
                Value::Function(Rc::new(FunctionValue {
                    params: params.clone(),
                    body: body.clone(),
                    closure: self.current_scope.clone(),
                }))
            }
        }
    }

    fn call_function(&mut self, callee: Value, args: Vec<Value>, token_line: usize) -> Value {
        if let Value::Function(func) = callee {
            // Builtins
            if func.params.is_empty() && func.body.is_empty() {
                // This is a placeholder for builtins. We should handle them separately.
                // But for now, let's check the name in the global scope.
                // Actually, I'll implement builtins inside the interpreter.
                return Value::Nil;
            }

            if args.len() != func.params.len() {
                self.runtime_error(token_line, &format!("expected {} arguments, got {}", func.params.len(), args.len()), &Token::LParen);
                return Value::Nil;
            }

            if self.call_stack_depth >= 300 {
                // Recursion limit
                return Value::Nil;
            }

            let mut scope = Rc::new(RefCell::new(Scope {
                vars: HashMap::new(),
                parent: Some(func.closure.clone()),
            }));

            for (param, arg) in func.params.iter().zip(args.iter()) {
                scope.borrow_mut().vars.insert(param.clone(), arg.clone());
            }

            let old_scope = self.current_scope.clone();
            self.current_scope = scope;
            self.call_stack_depth += 1;

            let mut result = Value::Nil;
            for stmt in &func.body {
                match self.exec_stmt(stmt, token_line) {
                    ControlFlow::Return(v) => {
                        result = v;
                        break;
                    }
                    ControlFlow::Break | ControlFlow::Continue => {} // Should not happen in function
                    ControlFlow::None => {}
                }
            }

            self.current_scope = old_scope;
            self.call_stack_depth -= 1;
            result
        } else {
            self.runtime_error(token_line, &format!("cannot call {}", Self::type_name(&callee)), &Token::LParen);
            Value::Nil
        }
    }

    fn exec_stmt(&mut self, stmt: &Stmt, token_line: usize) -> ControlFlow {
        match stmt {
            Stmt::Let(name, expr) => {
                let val = self.eval_expr(expr, token_line);
                self.current_scope.borrow_mut().vars.insert(name.clone(), val);
                ControlFlow::None
            }
            Stmt::FnDecl(name, params, body) => {
                let func = Value::Function(Rc::new(FunctionValue {
                    params: params.clone(),
                    body: body.clone(),
                    closure: self.current_scope.clone(),
                }));
                self.current_scope.borrow_mut().vars.insert(name.clone(), func);
                ControlFlow::None
            }
            Stmt::If(cond, then_block, else_stmt) => {
                let cv = self.eval_expr(cond, token_line);
                if Self::is_truthy(&cv) {
                    let old_scope = self.current_scope.clone();
                    self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                    for s in then_block {
                        match self.exec_stmt(s, token_line) {
                            ControlFlow::Return(v) => {
                                self.current_scope = old_scope;
                                return ControlFlow::Return(v);
                            }
                            ControlFlow::Break => {
                                self.current_scope = old_scope;
                                return ControlFlow::Break;
                            }
                            ControlFlow::Continue => {
                                self.current_scope = old_scope;
                                return ControlFlow::Continue;
                            }
                            ControlFlow::None => {}
                        }
                    }
                    self.current_scope = old_scope;
                    ControlFlow::None
                } else if let Some(es) = else_stmt {
                    match self.exec_stmt(es, token_line) {
                        ControlFlow::Return(v) => ControlFlow::Return(v),
                        ControlFlow::Break => ControlFlow::Break,
                        ControlFlow::Continue => ControlFlow::Continue,
                        ControlFlow::None => ControlFlow::None,
                    }
                } else {
                    ControlFlow::None
                }
            }
            Stmt::While(cond, body) => {
                loop {
                    let cv = self.eval_expr(cond, token_line);
                    if !Self::is_truthy(&cv) { break; }
                    let old_scope = self.current_scope.clone();
                    self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                    let mut cf = ControlFlow::None;
                    for s in body {
                        cf = self.exec_stmt(s, token_line);
                        if let ControlFlow::Break = cf { break; }
                        if let ControlFlow::Continue = cf { break; }
                        if let ControlFlow::Return(v) = cf {
                            self.current_scope = old_scope;
                            return ControlFlow::Return(v);
                        }
                    }
                    self.current_scope = old_scope;
                    if let ControlFlow::Break = cf { break; }
                }
                ControlFlow::None
            }
            Stmt::For(name, expr, body) => {
                let ev = self.eval_expr(expr, token_line);
                if let Value::List(l) = ev {
                    let mut i = 0;
                    loop {
                        let len = l.borrow().len();
                        if i >= len { break; }
                        let val = l.borrow()[i].clone();
                        let old_scope = self.current_scope.clone();
                        self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                        self.current_scope.borrow_mut().vars.insert(name.clone(), val);
                        let mut cf = ControlFlow::None;
                        for s in body {
                            cf = self.exec_stmt(s, token_line);
                            if let ControlFlow::Break = cf { break; }
                            if let ControlFlow::Continue = cf { break; }
                            if let ControlFlow::Return(v) = cf {
                                self.current_scope = old_scope;
                                return ControlFlow::Return(v);
                            }
                        }
                        self.current_scope = old_scope;
                        i += 1;
                        if let ControlFlow::Break = cf { break; }
                    }
                } else {
                    self.runtime_error(token_line, &format!("cannot iterate {}", Self::type_name(&ev)), &Token::For);
                }
                ControlFlow::None
            }
            Stmt::Return(expr) => {
                let val = if let Some(e) = expr { self.eval_expr(e, token_line) } else { Value::Nil };
                ControlFlow::Return(val)
            }
            Stmt::Break => ControlFlow::Break,
            Stmt::Continue => ControlFlow::Continue,
            Stmt::Assign(obj_expr, val_expr) => {
                // This is a simplified representation of postfix[idx] = val
                // We need to handle both name = val and postfix[idx] = val
                // In the actual parser, these are different.
                ControlFlow::None
            }
            Stmt::ExprStmt(expr) => {
                self.eval_expr(expr, token_line);
                ControlFlow::None
            }
        }
    }

    fn runtime_error(&self, line: usize, msg: &str, token: &Token) {
        println!("error at line {}: {}", line, msg);
        std::process::exit(0);
    }
}

fn lv_list(v: &Value) -> &Vec<Value> {
    if let Value::List(l) = v { l.borrow() } else { panic!("Not a list") }
}

fn val_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::Function(x), Value::Function(y)) => Rc::ptr_eq(x, y),
        (Value::List(x), Value::List(y)) => {
            let ax = x.borrow();
            let ay = y.borrow();
            if ax.len() != ay.len() { return false; }
            for (va, vb) in ax.iter().zip(ay.iter()) {
                if !val_eq(va, vb) { return false; }
            }
            true
        }
        _ => false,
    }
}

