use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::path::Path;
use std::rc::Rc;

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Let, Fn, If, Else, While, For, In, Return, Break, Continue, And, Or, Not, True, False, Nil,
    Ident(String), Int(i64), String(String),
    EqEq, NotEq, Leq, Geq, Lt, Gt, Eq, Plus, Minus, Star, Slash, Percent,
    LParen, RParen, LBracket, RBracket, LBrace, RBrace, Comma, Semicolon,
}

struct Lexer {
    input: Vec<char>,
    pos: usize,
    line: usize,
}

impl Lexer {
    fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
            line: 1,
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += 1;
        if c == '\n' {
            self.line += 1;
        }
        Some(c)
    }

    fn next_token(&mut self) -> Option<(Token, usize)> {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.next();
            } else if c == '#' {
                while let Some(nc) = self.peek() {
                    if nc == '\n' { break; }
                    self.next();
                }
            } else {
                break;
            }
        }

        let line = self.line;
        let c = self.next()?;
        match c {
            '(' => Some((Token::LParen, line)),
            ')' => Some((Token::RParen, line)),
            '[' => Some((Token::LBracket, line)),
            ']' => Some((Token::RBracket, line)),
            '{' => Some((Token::LBrace, line)),
            '}' => Some((Token::RBrace, line)),
            ',' => Some((Token::Comma, line)),
            ';' => Some((Token::Semicolon, line)),
            '=' => if self.peek() == Some('=') { self.next(); Some((Token::EqEq, line)) } else { Some((Token::Eq, line)) },
            '!' => if self.peek() == Some('=') { self.next(); Some((Token::NotEq, line)) } else { panic!("Unexpected !") },
            '<' => if self.peek() == Some('=') { self.next(); Some((Token::Leq, line)) } else { Some((Token::Lt, line)) },
            '>' => if self.peek() == Some('=') { self.next(); Some((Token::Geq, line)) } else { Some((Token::Gt, line)) },
            '+' => Some((Token::Plus, line)),
            '-' => Some((Token::Minus, line)),
            '*' => Some((Token::Star, line)),
            '/' => Some((Token::Slash, line)),
            '%' => Some((Token::Percent, line)),
            '"' => {
                let mut s = String::new();
                while let Some(nc) = self.next() {
                    if nc == '"' { break; }
                    match nc {
                        '\\' => match self.next() {
                            Some('n') => s.push('\n'),
                            Some('t') => s.push('\t'),
                            Some('"') => s.push('"'),
                            Some('\\') => s.push('\\'),
                            _ => {},
                        },
                        _ => s.push(nc),
                    }
                }
                Some((Token::String(s), line))
            }
            c if c.is_ascii_digit() => {
                let mut s = String::new();
                s.push(c);
                while let Some(nc) = self.peek() {
                    if nc.is_ascii_digit() { s.push(nc); self.next(); } else { break; }
                }
                Some((Token::Int(s.parse().unwrap()), line))
            }
            c if c.is_alphabetic() || c == '_' => {
                let mut s = String::new();
                s.push(c);
                while let Some(nc) = self.peek() {
                    if nc.is_alphanumeric() || nc == '_' { s.push(nc); self.next(); } else { break; }
                }
                let token = match s.as_str() {
                    "let" => Token::Let, "fn" => Token::Fn, "if" => Token::If, "else" => Token::Else,
                    "while" => Token::While, "for" => Token::For, "in" => Token::In, "return" => Token::Return,
                    "break" => Token::Break, "continue" => Token::Continue, "and" => Token::And, "or" => Token::Or,
                    "not" => Token::Not, "true" => Token::True, "false" => Token::False, "nil" => Token::Nil,
                    _ => Token::Ident(s),
                };
                Some((token, line))
            }
            _ => None,
        }
    }
}

#[derive(Clone)]
enum Expr {
    Binary(Box<Expr>, Token, Box<Expr>),
    Unary(Token, Box<Expr>),
    Call(Box<Expr>, Vec<Expr>),
    Index(Box<Expr>, Box<Expr>),
    Int(i64), String(String), Bool(bool), Nil,
    Ident(String),
    List(Vec<Expr>),
    Closure(Vec<String>, Vec<Stmt>),
}

#[derive(Clone)]
enum Stmt {
    Let(String, Expr),
    FnDecl(String, Vec<String>, Vec<Stmt>),
    If(Expr, Vec<Stmt>, Option<Box<Stmt>>),
    While(Expr, Vec<Stmt>),
    For(String, Expr, Vec<Stmt>),
    Return(Option<Expr>),
    Break,
    Continue,
    AssignIdent(String, Expr),
    AssignPostfix(Expr, Expr, Expr),
    ExprStmt(Expr),
}

struct Parser {
    tokens: Vec<(Token, usize)>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos).map(|t| &t.0)
    }

    fn next(&mut self) -> Option<Token> {
        if self.pos >= self.tokens.len() {
            None
        } else {
            let t = self.tokens[self.pos].0.clone();
            self.pos += 1;
            Some(t)
        }
    }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while self.peek().is_some() {
            stmts.push(self.parse_stmt());
        }
        stmts
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.next() {
            Some(Token::Let) => {
                let name = if let Some(Token::Ident(n)) = self.next() { n.clone() } else { panic!() };
                self.next(); // =
                let e = self.parse_expr();
                self.next(); // ;
                Stmt::Let(name, e)
            }
            Some(Token::Fn) => {
                let name = if let Some(Token::Ident(n)) = self.next() { n.clone() } else { panic!() };
                self.next(); // (
                let mut params = Vec::new();
                while let Some(Token::Ident(n)) = self.next() {
                    params.push(n.clone());
                    if self.peek() == Some(&Token::Comma) { self.next(); } else { break; }
                }
                self.next(); // )
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body)
            }
            Some(Token::If) => {
                let cond = self.parse_expr();
                let then_block = self.parse_block();
                let mut else_stmt = None;
                if self.peek() == Some(&Token::Else) {
                    self.next();
                    if self.peek() == Some(&Token::If) {
                        else_stmt = Some(Box::new(self.parse_stmt()));
                    } else {
                        else_stmt = Some(Box::new(Stmt::ExprStmt(self.parse_block_as_expr())));
                    }
                }
                Stmt::If(cond, then_block, else_stmt)
            }
            Some(Token::While) => {
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While(cond, body)
            }
            Some(Token::For) => {
                let name = if let Some(Token::Ident(n)) = self.next() { n.clone() } else { panic!() };
                self.next(); // in
                let e = self.parse_expr();
                let body = self.parse_block();
                Stmt::For(name, e, body)
            }
            Some(Token::Return) => {
                let e = if self.peek() != Some(&Token::Semicolon) { Some(self.parse_expr()) } else { None };
                self.next(); // ;
                Stmt::Return(e)
            }
            Some(Token::Break) => { self.next(); Stmt::Break }
            Some(Token::Continue) => { self.next(); Stmt::Continue }
            _ => {
                let (e, ended_in_index) = self.parse_postfix_with_info();
                if self.peek() == Some(&Token::Eq) {
                    self.next(); // =
                    let val = self.parse_expr();
                    self.next(); // ;
                    if let Expr::Ident(name) = e {
                        Stmt::AssignIdent(name, val)
                    } else if ended_in_index {
                        if let Expr::Index(obj, idx) = e {
                            Stmt::AssignPostfix(obj.clone(), idx.clone(), val)
                        } else {
                            panic!("Invalid assignment")
                        }
                    } else {
                        panic!("Invalid assignment")
                    }
                } else {
                    self.next(); // ;
                    Stmt::ExprStmt(e)
                }
            }
        }
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.next(); // {
        let mut stmts = Vec::new();
        while self.peek() != Some(&Token::RBrace) {
            stmts.push(self.parse_stmt());
        }
        self.next(); // }
        stmts
    }

    fn parse_block_as_expr(&mut self) -> Expr {
        let stmts = self.parse_block();
        Expr::Closure(Vec::new(), stmts)
    }

    fn parse_expr(&mut self) -> Expr {
        self.parse_or().0
    }

    fn parse_or(&mut self) -> (Expr, bool) {
        let mut e = self.parse_and();
        while self.peek() == Some(&Token::Or) {
            let op = self.next().unwrap().clone();
            let right = self.parse_and();
            e = (Expr::Binary(Box::new(e.0), op, Box::new(right.0)), false);
        }
        e
    }

    fn parse_and(&mut self) -> (Expr, bool) {
        let mut e = self.parse_not();
        while self.peek() == Some(&Token::And) {
            let op = self.next().unwrap().clone();
            let right = self.parse_not();
            e = (Expr::Binary(Box::new(e.0), op, Box::new(right.0)), false);
        }
        e
    }

    fn parse_not(&mut self) -> (Expr, bool) {
        if self.peek() == Some(&Token::Not) {
            let op = self.next().unwrap().clone();
            let e = self.parse_not();
            (Expr::Unary(op, Box::new(e.0)), false)
        } else {
            self.parse_comparison()
        }
    }

    fn parse_comparison(&mut self) -> (Expr, bool) {
        let mut e = self.parse_term();
        while let Some(op) = self.peek() {
            match op {
                Token::EqEq | Token::NotEq | Token::Lt | Token::Leq | Token::Gt | Token::Geq => {
                    let op = self.next().unwrap().clone();
                    let right = self.parse_term();
                    e = (Expr::Binary(Box::new(e.0), op, Box::new(right.0)), false);
                }
                _ => break,
            }
        }
        e
    }

    fn parse_term(&mut self) -> (Expr, bool) {
        let mut e = self.parse_factor();
        while let Some(op) = self.peek() {
            match op {
                Token::Plus | Token::Minus => {
                    let op = self.next().unwrap().clone();
                    let right = self.parse_factor();
                    e = (Expr::Binary(Box::new(e.0), op, Box::new(right.0)), false);
                }
                _ => break,
            }
        }
        e
    }

    fn parse_factor(&mut self) -> (Expr, bool) {
        let mut e = self.parse_unary();
        while let Some(op) = self.peek() {
            match op {
                Token::Star | Token::Slash | Token::Percent => {
                    let op = self.next().unwrap().clone();
                    let right = self.parse_unary();
                    e = (Expr::Binary(Box::new(e.0), op, Box::new(right.0)), false);
                }
                _ => break,
            }
        }
        e
    }

    fn parse_unary(&mut self) -> (Expr, bool) {
        if self.peek() == Some(&Token::Minus) {
            let op = self.next().unwrap().clone();
            let e = self.parse_unary();
            (Expr::Unary(op, Box::new(e.0)), false)
        } else {
            self.parse_postfix_with_info()
        }
    }

    fn parse_postfix_with_info(&mut self) -> (Expr, bool) {
        let mut e = self.parse_primary();
        let mut ended_in_index = false;
        while let Some(t) = self.peek() {
            match t {
                Token::LParen => {
                    self.next();
                    let mut args = Vec::new();
                    if self.peek() != Some(&Token::RParen) {
                        args.push(self.parse_expr());
                        while self.peek() == Some(&Token::Comma) {
                            self.next();
                            args.push(self.parse_expr());
                        }
                    }
                    self.next(); // )
                    e = Expr::Call(Box::new(e), args);
                    ended_in_index = false;
                }
                Token::LBracket => {
                    self.next();
                    let idx = self.parse_expr();
                    self.next(); // ]
                    e = Expr::Index(Box::new(e), Box::new(idx));
                    ended_in_index = true;
                }
                _ => break,
            }
        }
        (e, ended_in_index)
    }

    fn parse_primary(&mut self) -> Expr {
        match self.next() {
            Some(Token::Int(i)) => Expr::Int(*i),
            Some(Token::String(s)) => Expr::String(s.clone()),
            Some(Token::True) => Expr::Bool(true),
            Some(Token::False) => Expr::Bool(false),
            Some(Token::Nil) => Expr::Nil,
            Some(Token::Ident(s)) => Expr::Ident(s.clone()),
            Some(Token::LParen) => {
                let e = self.parse_expr();
                self.next(); // )
                e
            }
            Some(Token::LBracket) => {
                let mut elements = Vec::new();
                if self.peek() != Some(&Token::RBracket) {
                    elements.push(self.parse_expr());
                    while self.peek() == Some(&Token::Comma) {
                        self.next();
                        elements.push(self.parse_expr());
                    }
                }
                self.next(); // ]
                Expr::List(elements)
            }
            Some(Token::Fn) => {
                self.next(); // (
                let mut params = Vec::new();
                while let Some(Token::Ident(n)) = self.next() {
                    params.push(n.clone());
                    if self.peek() == Some(&Token::Comma) { self.next(); } else { break; }
                }
                self.next(); // )
                let body = self.parse_block();
                Expr::Closure(params, body)
            }
            _ => panic!("Unexpected token"),
        }
    }
}

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    String(String),
    List(Rc<RefCell<Vec<Value>>>),
    Function(Rc<FunctionValue>),
    Nil,
}

struct FunctionValue {
    params: Vec<String>,
    body: Vec<Stmt>,
    closure: Rc<RefCell<Scope>>,
}

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

enum ControlFlow {
    Continue,
    Break,
    Return(Value),
    None,
}

struct Interpreter {
    current_scope: Rc<RefCell<Scope>>,
    call_stack_depth: usize,
}

impl Interpreter {
    fn new() -> Self {
        let global_scope = Rc::new(RefCell::new(Scope {
            vars: HashMap::new(),
            parent: None,
        }));
        Interpreter {
            current_scope: global_scope,
            call_stack_depth: 0,
        }
    }

    fn type_name(v: &Value) -> &'static str {
        match v {
            Value::Int(_) => "int",
            Value::Bool(_) => "bool",
            Value::String(_) => "string",
            Value::List(_) => "list",
            Value::Function(_) => "function",
            Value::Nil => "nil",
        }
    }

    fn is_truthy(v: &Value) -> bool {
        match v {
            Value::Int(i) => *i != 0,
            Value::Bool(b) => *b,
            Value::String(s) => !s.is_empty(),
            Value::List(l) => !l.borrow().is_empty(),
            Value::Nil => false,
            Value::Function(_) => true,
        }
    }

    fn display(v: &Value, visited: &mut HashSet<*const Vec<Value>>) -> String {
        match v {
            Value::Int(i) => i.to_string(),
            Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Value::Nil => "nil".to_string(),
            Value::String(s) => s.clone(),
            Value::Function(_) => "<fn>".to_string(),
            Value::List(l) => {
                let bor = l.borrow();
                let ptr = bor.as_ptr();
                if visited.contains(&ptr) {
                    "[...]".to_string()
                } else {
                    visited.insert(ptr);
                    let mut res = String::from("[");
                    for (i, val) in bor.iter().enumerate() {
                        if i > 0 { res.push_str(", "); }
                        match val {
                            Value::String(s) => {
                                res.push('"');
                                for c in s.chars() {
                                    match c {
                                        '\\' => res.push_str("\\\\"),
                                        '"' => res.push_str("\\\""),
                                        '\n' => res.push_str("\\n"),
                                        '\t' => res.push_str("\\t"),
                                        _ => res.push(c),
                                    }
                                }
                                res.push('"');
                            }
                            _ => res.push_str(&Self::display(val, visited)),
                        }
                    }
                    res.push(']');
                    visited.remove(&ptr);
                    res
                }
            }
        }
    }

    fn eval_expr(&mut self, expr: &Expr, token_line: usize) -> Value {
        match expr {
            Expr::Int(i) => Value::Int(*i),
            Expr::String(s) => Value::String(s.clone()),
            Expr::Bool(b) => Value::Bool(*b),
            Expr::Nil => Value::Nil,
            Expr::Ident(name) => {
                let mut scope = self.current_scope.clone();
                loop {
                    if let Some(val) = scope.borrow().vars.get(name) {
                        return val.clone();
                    }
                    if let Some(parent) = &scope.borrow().parent {
                        scope = parent.clone();
                    } else {
                        self.runtime_error(token_line, &format!("undefined variable {}", name), &Token::Ident(name.clone()));
                        return Value::Nil;
                    }
                }
            }
            Expr::Binary(left, op, right) => {
                let lv = self.eval_expr(left, token_line);
                let rv = self.eval_expr(right, token_line);
                match op {
                    Token::Or => if Self::is_truthy(&lv) { lv } else { rv },
                    Token::And => if !Self::is_truthy(&lv) { lv } else { rv },
                    Token::EqEq | Token::NotEq => {
                        let eq = match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => a == b,
                            (Value::Bool(a), Value::Bool(b)) => a == b,
                            (Value::String(a), Value::String(b)) => a == b,
                            (Value::Nil, Value::Nil) => true,
                            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
                            (Value::List(a), Value::List(b)) => {
                                fn list_eq(a: &Vec<Value>, b: &Vec<Value>) -> bool {
                                    if a.len() != b.len() { return false; }
                                    for (va, vb) in a.iter().zip(b.iter()) {
                                        if !val_eq(va, vb) { return false; }
                                    }
                                    true
                                }
                                list_eq(&a.borrow(), &b.borrow())
                            }
                            _ => false,
                        };
                        if let Token::EqEq = op { if eq { Value::Bool(true) } else { Value::Bool(false) } } else { if eq { Value::Bool(false) } else { Value::Bool(true) } }
                    }
                    Token::Lt | Token::Leq | Token::Gt | Token::Geq => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                let res = match op {
                                    Token::Lt => a < b, Token::Leq => a <= b, Token::Gt => a > b, Token::Geq => a >= b,
                                    _ => unreachable!(),
                                };
                                Value::Bool(res)
                            }
                            (Value::String(a), Value::String(b)) => {
                                let res = match op {
                                    Token::Lt => a < b, Token::Leq => a <= b, Token::Gt => a > b, Token::Geq => a >= b,
                                    _ => unreachable!(),
                                };
                                Value::Bool(res)
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply {:?} to {} and {}", op, Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    Token::Plus => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                if let Some(res) = a.checked_add(*b) { Value::Int(res) } else {
                                    self.runtime_error(token_line, "integer overflow", op);
                                    Value::Nil
                                }
                            }
                            (Value::String(a), Value::String(b)) => Value::String(format!("{}{}", a, b)),
                            (Value::List(a), Value::List(b)) => {
                                let mut res = a.borrow().clone();
                                res.extend(b.borrow().clone());
                                Value::List(Rc::new(RefCell::new(res)))
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply + to {} and {}", Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    Token::Minus | Token::Star | Token::Slash | Token::Percent => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                if let Token::Slash | Token::Percent = op {
                                    if *b == 0 {
                                        self.runtime_error(token_line, "division by zero", op);
                                        return Value::Nil;
                                    }
                                }
                                let res = match op {
                                    Token::Minus => a.checked_sub(*b),
                                    Token::Star => a.checked_mul(*b),
                                    Token::Slash => Some(a / b),
                                    Token::Percent => Some(a % b),
                                    _ => unreachable!(),
                                };
                                if let Some(r) = res { Value::Int(r) } else {
                                    self.runtime_error(token_line, "integer overflow", op);
                                    Value::Nil
                                }
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply {:?} to {} and {}", op, Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Unary(op, expr) => {
                let v = self.eval_expr(expr, token_line);
                match op {
                    Token::Not => Value::Bool(!Self::is_truthy(&v)),
                    Token::Minus => {
                        if let Value::Int(i) = v {
                            if let Some(res) = i.checked_neg() { Value::Int(res) } else {
                                self.runtime_error(token_line, "integer overflow", op);
                                Value::Nil
                            }
                        } else {
                            self.runtime_error(token_line, &format!("cannot apply - to {}", Self::type_name(&v)), op);
                            Value::Nil
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Call(callee_expr, args_exprs) => {
                let callee = self.eval_expr(callee_expr, token_line);
                let mut args = Vec::new();
                for ae in args_exprs {
                    args.push(self.eval_expr(ae, token_line));
                }
                self.call_function(callee, args, token_line)
            }
            Expr::Index(obj_expr, idx_expr) => {
                let obj = self.eval_expr(obj_expr, token_line);
                let idx = self.eval_expr(idx_expr, token_line);
                match (&obj, &idx) {
                    (Value::List(l), Value::Int(i)) => {
                        let bor = l.borrow();
                        if *i >= 0 && (*i as usize) < bor.len() {
                            bor[*i as usize].clone()
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, bor.len()), &Token::LBracket);
                            Value::Nil
                        }
                    }
                    (Value::String(s), Value::Int(i)) => {
                        if *i >= 0 && (*i as usize) < s.len() {
                            let mut res = String::new();
                            res.push(s.as_bytes()[*i as usize] as char);
                            Value::String(res)
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, s.len()), &Token::LBracket);
                            Value::Nil
                        }
                    }
                    (Value::List(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index list with {}", Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                    (Value::String(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index string with {}", Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                    _ => {
                        self.runtime_error(token_line, &format!("cannot index {} with {}", Self::type_name(&obj), Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                }
            }
            Expr::List(elements) => {
                let mut list = Vec::new();
                for e in elements {
                    list.push(self.eval_expr(e, token_line));
                }
                Value::List(Rc::new(RefCell::new(list)))
            }
            Expr::Closure(params, body) => {
                Value::Function(Rc::new(FunctionValue {
                    params: params.clone(),
                    body: body.clone(),
                    closure: self.current_scope.clone(),
                }))
            }
        }
    }

    fn call_function(&mut self, callee: Value, args: Vec<Value>, token_line: usize) -> Value {
        match &callee {
            Value::Function(func) => {
                if func.params.is_empty() && func.body.is_empty() {
                    // Built-in handled in call_function
                    return Value::Nil;
                }
                if args.len() != func.params.len() {
                    self.runtime_error(token_line, &format!("expected {} arguments, got {}", func.params.len(), args.len()), &Token::LParen);
                    return Value::Nil;
                }
                if self.call_stack_depth >= 300 {
                    return Value::Nil;
                }
                let mut scope = Rc::new(RefCell::new(Scope {
                    vars: HashMap::new(),
                    parent: Some(func.closure.clone()),
                }));
                for (param, arg) in func.params.iter().zip(args.iter()) {
                    scope.borrow_mut().vars.insert(param.clone(), arg.clone());
                }
                let old_scope = self.current_scope.clone();
                self.current_scope = scope;
                self.call_stack_depth += 1;
                let mut result = Value::Nil;
                for stmt in &func.body {
                    match self.exec_stmt(stmt, token_line) {
                        ControlFlow::Return(v) => {
                            result = v;
                            break;
                        }
                        ControlFlow::Break | ControlFlow::Continue => {}
                        ControlFlow::None => {}
                    }
                }
                self.current_scope = old_scope;
                self.call_stack_depth -= 1;
                result
            }
            _ => {
                self.runtime_error(token_line, &format!("cannot call {}", Self::type_name(&callee)), &Token::LParen);
                Value::Nil
            }
        }
    }

    fn exec_stmt(&mut self, stmt: &Stmt, token_line: usize) -> ControlFlow {
        match stmt {
            Stmt::Let(name, expr) => {
                let val = self.eval_expr(expr, token_line);
                self.current_scope.borrow_mut().vars.insert(name.clone(), val);
                ControlFlow::None
            }
            Stmt::FnDecl(name, params, body) => {
                let func = Value::Function(Rc::new(FunctionValue {
                    params: params.clone(),
                    body: body.clone(),
                    closure: self.current_scope.clone(),
                }));
                self.current_scope.borrow_mut().vars.insert(name.clone(), func);
                ControlFlow::None
            }
            Stmt::If(cond, then_block, else_stmt) => {
                let cv = self.eval_expr(cond, token_line);
                if Self::is_truthy(&cv) {
                    let old_scope = self.current_scope.clone();
                    self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                    let mut cf = ControlFlow::None;
                    for s in then_block {
                        cf = self.exec_stmt(s, token_line);
                        if let ControlFlow::Return(v) = cf {
                            self.current_scope = old_scope;
                            return ControlFlow::Return(v);
                        }
                        if let ControlFlow::Break = cf { break; }
                        if let ControlFlow::Continue = cf { break; }
                    }
                    self.current_scope = old_scope;
                    cf
                } else if let Some(es) = else_stmt {
                    self.exec_stmt(es, token_line)
                } else {
                    ControlFlow::None
                }
            }
            Stmt::While(cond, body) => {
                loop {
                    let cv = self.eval_expr(cond, token_line);
                    if !Self::is_truthy(&cv) { break; }
                    let old_scope = self.current_scope.clone();
                    self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                    let mut cf = ControlFlow::None;
                    for s in body {
                        cf = self.exec_stmt(s, token_line);
                        if let ControlFlow::Return(v) = cf {
                            self.current_scope = old_scope;
                            return ControlFlow::Return(v);
                        }
                        if let ControlFlow::Break = cf { break; }
                        if let ControlFlow::Continue = cf { break; }
                    }
                    self.current_scope = old_scope;
                    if let ControlFlow::Break = cf { break; }
                }
                ControlFlow::None
            }
            Stmt::For(name, expr, body) => {
                let ev = self.eval_expr(expr, token_line);
                if let Value::List(l) = ev {
                    let mut i = 0;
                    loop {
                        let len = l.borrow().len();
                        if i >= len { break; }
                        let val = l.borrow()[i].clone();
                        let old_scope = self.current_scope.clone();
                        self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                        self.current_scope.borrow_mut().vars.insert(name.clone(), val);
                        let mut cf = ControlFlow::None;
                        for s in body {
                            cf = self.exec_stmt(s, token_line);
                            if let ControlFlow::Return(v) = cf {
                                self.current_scope = old_scope;
                                return ControlFlow::Return(v);
                            }
                            if let ControlFlow::Break = cf { break; }
                            if let ControlFlow::Continue = cf { break; }
                        }
                        self.current_scope = old_scope;
                        i += 1;
                        if let ControlFlow::Break = cf { break; }
                    }
                } else {
                    self.runtime_error(token_line, &format!("cannot iterate {}", Self::type_name(&ev)), &Token::For);
                }
                ControlFlow::None
            }
            Stmt::Return(expr) => {
                let val = if let Some(e) = expr { self.eval_expr(e, token_line) } else { Value::Nil };
                ControlFlow::Return(val)
            }
            Stmt::Break => ControlFlow::Break,
            Stmt::Continue => ControlFlow::Continue,
            Stmt::AssignIdent(name, expr) => {
                let val = self.eval_expr(expr, token_line);
                let mut scope = self.current_scope.clone();
                loop {
                    if let Some(v) = scope.borrow_mut().vars.get_mut(name) {
                        *v = val;
                        break;
                    }
                    if let Some(parent) = &scope.borrow().parent {
                        scope = parent.clone();
                    } else {
                        self.runtime_error(token_line, &format!("undefined variable {}", name), &Token::Ident(name.clone()));
                        break;
                    }
                }
                ControlFlow::None
            }
            Stmt::AssignPostfix(obj_expr, idx_expr, val_expr) => {
                let obj = self.eval_expr(obj_expr, token_line);
                let idx = self.eval_expr(idx_expr, token_line);
                let val = self.eval_expr(val_expr, token_line);
                match (&obj, &idx) {
                    (Value::List(l), Value::Int(i)) => {
                        let mut bor = l.borrow_mut();
                        if *i >= 0 && (*i as usize) < bor.len() {
                            bor[*i as usize] = val;
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, bor.len()), &Token::LBracket);
                        }
                    }
                    (Value::List(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index list with {}", Self::type_name(&idx)), &Token::LBracket);
                    }
                    (obj, _) => {
                        self.runtime_error(token_line, &format!("cannot assign into {}", Self::type_name(obj)), &Token::LBracket);
                    }
                }
                ControlFlow::None
            }
            Stmt::ExprStmt(expr) => {
                self.eval_expr(expr, token_line);
                ControlFlow::None
            }
        }
    }

    fn runtime_error(&self, line: usize, msg: &str, token: &Token) {
        println!("error at line {}: {}", line, msg);
        std::process::exit(0);
    }
}

fn val_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::Function(x), Value::Function(y)) => Rc::ptr_eq(x, y),
        (Value::List(x), Value::List(y)) => {
            let ax = x.borrow();
            let ay = y.borrow();
            if ax.len() != ay.len() { return false; }
            for (va, vb) in ax.iter().zip(ay.iter()) {
                if !val_eq(va, vb) { return false; }
            }
            true
        }
        _ => false,
    }
}

fn builtin_call(name: &str, args: Vec<Value>, interp: &mut Interpreter, token_line: usize) -> Value {
    match name {
        "print" => {
            let mut first = true;
            for v in args {
                if !first { print!(" "); }
                print!("{}", Interpreter::display(&v, &mut HashSet::new()));
                first = false;
            }
            println!();
            Value::Nil
        }
        "str" => {
            if args.len() != 1 {
                interp.runtime_error(token_line, &format!("expected 1 arguments, got {}", args.len()), &Token::LParen);
            }
            Value::String(Interpreter::display(&args[0], &mut HashSet::new()))
        }
        "type" => {
            if args.len() != 1 {
                interp.runtime_error(token_line, &format!("expected 1 arguments, got {}", args.len()), &Token::LParen);
            }
            Value::String(Interpreter::type_name(&args[0]).to_string())
        }
        "len" => {
            if args.len() != 1 {
                interp.runtime_error(token_line, &format!("expected 1 arguments, got {}", args.len()), &Token::LParen);
            }
            match &args[0] {
                Value::String(s) => Value::Int(s.len() as i64),
                Value::List(l) => Value::Int(l.borrow().len() as i64),
                _ => {
                    interp.runtime_error(token_line, "bad argument to len", &Token::LParen);
                    Value::Nil
                }
            }
        }
        "push" => {
            if args.len() != 2 {
                interp.runtime_error(token_line, &format!("expected 2 arguments, got {}", args.len()), &Token::LParen);
            }
            match args[0] {
                Value::List(l) => {
                    l.borrow_mut().push(args[1].clone());
                    Value::Nil
                }
                _ => {
                    interp.runtime_error(token_line, "bad argument to push", &Token::LParen);
                    Value::Nil
                }
            }
        }
        "pop" => {
            if args.len() != 1 {
                interp.runtime_error(token_line, &format!("expected 1 arguments, got {}", args.len()), &Token::LParen);
            }
            match args[0] {
                Value::List(l) => {
                    let mut bor = l.borrow_mut();
                    if bor.is_empty() {
                        interp.runtime_error(token_line, "pop from empty list", &Token::LParen);
                    }
                    bor.pop().unwrap_or(Value::Nil)
                }
                _ => {
                    interp.runtime_error(token_line, "bad argument to pop", &Token::LParen);
                    Value::Nil
                }
            }
        }
        "range" => {
            if args.len() != 2 {
                interp.runtime_error(token_line, &format!("expected 2 arguments, got {}", args.len()), &Token::LParen);
            }
            if let (Value::Int(a), Value::Int(b)) = (&args[0], &args[1]) {
                let mut res = Vec::new();
                let mut curr = *a;
                while curr < *b {
                    res.push(Value::Int(curr));
                    curr += 1;
                }
                Value::List(Rc::new(RefCell::new(res)))
            } else {
                interp.runtime_error(token_line, "bad argument to range", &Token::LParen);
                Value::Nil
            }
        }
        "slice" => {
            if args.len() != 3 {
                interp.runtime_error(token_line, &format!("expected 3 arguments, got {}", args.len()), &Token::LParen);
            }
            match (&args[0], &args[1], &args[2]) {
                (Value::String(s), Value::Int(a), Value::Int(b)) => {
                    if *a < 0 || *b < 0 || *a > *b || *b > s.len() as i64 {
                        interp.runtime_error(token_line, "slice index out of range", &Token::LParen);
                    }
                    let slice_str = &s[*a as usize..*b as usize];
                    Value::String(slice_str.to_string())
                }
                (Value::List(l), Value::Int(a), Value::Int(b)) => {
                    if *a < 0 || *b < 0 || *a > *b || *b > l.borrow().len() as i64 {
                        interp.runtime_error(token_line, "slice index out of range", &Token::LParen);
                    }
                    let slice_list = l.borrow()[*a as usize..*b as usize].to_vec();
                    Value::List(Rc::new(RefCell::new(slice_list)))
                }
                _ => {
                    interp.runtime_error(token_line, "bad argument to slice", &Token::LParen);
                    Value::Nil
                }
            }
        }
        _ => Value::Nil,
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = Path::new(dir).join("program.tern");
    let source = fs::read_to_string(path).expect("Could not read file");
    let mut lexer = Lexer::new(&source);
    let mut tokens = Vec::new();
    while let Some(t) = lexer.next_token() {
        tokens.push(t);
    }
    let mut parser = Parser { tokens, pos: 0 };
    let program = parser.parse_program();
    let mut interp = Interpreter::new();

    let mut builtins = HashMap::new();
    builtins.insert("print".to_string(), "print");
    builtins.insert("str".to_string(), "str");
    builtins.insert("type".to_string(), "type");
    builtins.insert("len".to_string(), "len");
    builtins.insert("push".to_string(), "push");
    builtins.insert("pop".to_string(), "pop");
    builtins.insert("range".to_string(), "range");
    builtins.insert("slice".to_string(), "slice");

    let mut builtin_scope = Scope { vars: HashMap::new(), parent: None };
    for (name, func_name) in builtins {
        builtin_scope.vars.insert(name, Value::Function(Rc::new(FunctionValue {
            params: vec![], body: vec![], closure: Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: None })),
        }))); // Placeholder, handled by name lookup
    }

    // We need a way to map the placeholder function to the actual builtin_call.
    // The easiest way is to wrap the interpreter's call_function.

    let global_scope = Rc::new(RefCell::new(Scope {
        vars: HashMap::new(),
        parent: Some(Rc::new(RefCell::new(builtin_scope))),
    }));
    interp.current_scope = global_scope;

    // Modified call_function to support builtins
    fn call_with_builtins(interp: &mut Interpreter, callee: Value, args: Vec<Value>, token_line: usize, builtins: &HashMap<String, &str>) -> Value {
        if let Value::Function(func) = &callee {
            if func.params.is_empty() && func.body.is_empty() {
                // This is a builtin. We need to find its name.
                // Since the builtin's name is not stored in the function object,
                // we'll have to find which builtin it is by searching the builtins map.
                // However, we can just store the builtin's name in the closure's vars or something.
                // A better way is to have a separate Value variant for Builtins.
                // For now, let's just check the lapped scope.
                return Value::Nil;
            }
            interp.call_function(callee.clone(), args, token_line)
        } else {
            interp.runtime_error(token_line, &format!("cannot call {}", Interpreter::type_name(&callee)), &Token::LParen);
            Value::Nil
        }
    }

    // Since we can't easily change the Value enum without modifying everything,
    // let's just intercept the call in a custom loop.

    // Actually, let's just modify the interpreter's call_function to check for builtins.
    // But since the `Semicolon` logic is already handled, let's just implement the main loop.

    // To make builtins work, we'll modify the interpreter logic to check if the function is a builtin.
    // The simplest way is to store the name of the builtin in the function's `params`.

    let mut interp_with_builtins = Interpreter::new();
    let mut builtin_vars = HashMap::new();
    let builtin_names = vec!["print", "str", "type", "len", "push", "pop", "range", "slice"];
    for name in builtin_names {
        builtin_vars.insert(name.to_string(), Value::Function(Rc::new(FunctionValue {
            params: vec![name.to_string()], // Store the name here
            body: vec![],
            closure: Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: None })),
        })));
    }

    let global_scope = Rc::new(RefCell::new(Scope {
        vars: HashMap::new(),
        parent: Some(Rc::new(RefCell::new(Scope { vars: builtin_vars, parent: None }))),
    }));
    interp_with_builtins.current_scope = global_scope;

    // Now we need to override the call_function.
    // We can't easily override a method, so we'll just call a helper.

    fn execute_program(interp: &mut Interpreter, program: Vec<Stmt>, token_line: usize) {
        for stmt in program {
            match interp.exec_stmt_with_builtins(&stmt, token_line) {
                ControlFlow::Return(v) => { break; }
                ControlFlow::Break | ControlFlow::Continue => {}
                ControlFlow::None => {}
            }
        }
    }

    execute_program(&mut interp_with_builtins, program, 0);
}

impl Interpreter {
    fn exec_stmt_with_builtins(&mut self, stmt: &Stmt, token_line: usize) -> ControlFlow {
        match stmt {
            Stmt::Let(name, expr) => {
                let val = self.eval_expr_with_builtins(expr, token_line);
                self.current_scope.borrow_mut().vars.insert(name.clone(), val);
                ControlFlow::None
            }
            Stmt::FnDecl(name, params, body) => {
                let func = Value::Function(Rc::new(FunctionValue {
                    params: params.clone(),
                    body: body.clone(),
                    closure: self.current_scope.clone(),
                }));
                self.current_scope.borrow_mut().vars.insert(name.clone(), func);
                ControlFlow::None
            }
            Stmt::If(cond, then_block, else_stmt) => {
                let cv = self.eval_expr_with_builtins(cond, token_line);
                if Self::is_truthy(&cv) {
                    let old_scope = self.current_scope.clone();
                    self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                    let mut cf = ControlFlow::None;
                    for s in then_block {
                        cf = self.exec_stmt_with_builtins(s, token_line);
                        if let ControlFlow::Return(v) = cf {
                            self.current_scope = old_scope;
                            return ControlFlow::Return(v);
                        }
                        if let ControlFlow::Break = cf { break; }
                        if let ControlFlow::Continue = cf { break; }
                    }
                    self.current_scope = old_scope;
                    cf
                } else if let Some(es) = else_stmt {
                    self.exec_stmt_with_builtins(es, token_line)
                } else {
                    ControlFlow::None
                }
            }
            Stmt::While(cond, body) => {
                loop {
                    let cv = self.eval_expr_with_builtins(cond, token_line);
                    if !Self::is_truthy(&cv) { break; }
                    let old_scope = self.current_scope.clone();
                    self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                    let mut cf = ControlFlow::None;
                    for s in body {
                        cf = self.exec_stmt_with_builtins(s, token_line);
                        if let ControlFlow::Return(v) = cf {
                            self.current_scope = old_scope;
                            return ControlFlow::Return(v);
                        }
                        if let ControlFlow::Break = cf { break; }
                        if let ControlFlow::Continue = cf { break; }
                    }
                    self.current_scope = old_scope;
                    if let ControlFlow::Break = cf { break; }
                }
                ControlFlow::None
            }
            Stmt::For(name, expr, body) => {
                let ev = self.eval_expr_with_builtins(expr, token_line);
                if let Value::List(l) = ev {
                    let mut i = 0;
                    loop {
                        let len = l.borrow().len();
                        if i >= len { break; }
                        let val = l.borrow()[i].clone();
                        let old_scope = self.current_scope.clone();
                        self.current_scope = Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent: Some(old_scope.clone()) }));
                        self.current_scope.borrow_mut().vars.insert(name.clone(), val);
                        let mut cf = ControlFlow::None;
                        for s in body {
                            cf = self.exec_stmt_with_builtins(s, token_line);
                            if let ControlFlow::Return(v) = cf {
                                self.current_scope = old_scope;
                                return ControlFlow::Return(v);
                            }
                            if let ControlFlow::Break = cf { break; }
                            if let ControlFlow::Continue = cf { break; }
                        }
                        self.current_scope = old_scope;
                        i += 1;
                        if let ControlFlow::Break = cf { break; }
                    }
                } else {
                    self.runtime_error(token_line, &format!("cannot iterate {}", Self::type_name(&ev)), &Token::For);
                }
                ControlFlow::None
            }
            Stmt::Return(expr) => {
                let val = if let Some(e) = expr { self.eval_expr_with_builtins(e, token_line) } else { Value::Nil };
                ControlFlow::Return(val)
            }
            Stmt::Break => ControlFlow::Break,
            Stmt::Continue => ControlFlow::Continue,
            Stmt::AssignIdent(name, expr) => {
                let val = self.eval_expr_with_builtins(expr, token_line);
                let mut scope = self.current_scope.clone();
                loop {
                    if let Some(v) = scope.borrow_mut().vars.get_mut(name) {
                        *v = val;
                        break;
                    }
                    if let Some(parent) = &scope.borrow().parent {
                        scope = parent.clone();
                    } else {
                        self.runtime_error(token_line, &format!("undefined variable {}", name), &Token::Ident(name.clone()));
                        break;
                    }
                }
                ControlFlow::None
            }
            Stmt::AssignPostfix(obj_expr, idx_expr, val_expr) => {
                let obj = self.eval_expr_with_builtins(obj_expr, token_line);
                let idx = self.eval_expr_with_builtins(idx_expr, token_line);
                let val = self.eval_expr_with_builtins(val_expr, token_line);
                match (&obj, &idx) {
                    (Value::List(l), Value::Int(i)) => {
                        let mut bor = l.borrow_mut();
                        if *i >= 0 && (*i as usize) < bor.len() {
                            bor[*i as usize] = val;
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, bor.len()), &Token::LBracket);
                        }
                    }
                    (Value::List(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index list with {}", Self::type_name(&idx)), &Token::LBracket);
                    }
                    (obj, _) => {
                        self.runtime_error(token_line, &format!("cannot assign into {}", Self::type_name(obj)), &Token::LBracket);
                    }
                }
                ControlFlow::None
            }
            Stmt::ExprStmt(expr) => {
                self.eval_expr_with_builtins(expr, token_line);
                ControlFlow::None
            }
        }
    }

    fn eval_expr_with_builtins(&mut self, expr: &Expr, token_line: usize) -> Value {
        match expr {
            Expr::Int(i) => Value::Int(*i),
            Expr::String(s) => Value::String(s.clone()),
            Expr::Bool(b) => Value::Bool(*b),
            Expr::Nil => Value::Nil,
            Expr::Ident(name) => {
                let mut scope = self.current_scope.clone();
                loop {
                    if let Some(val) = scope.borrow().vars.get(name) {
                        return val.clone();
                    }
                    if let Some(parent) = &scope.borrow().parent {
                        scope = parent.clone();
                    } else {
                        self.runtime_error(token_line, &format!("undefined variable {}", name), &Token::Ident(name.clone()));
                        return Value::Nil;
                    }
                }
            }
            Expr::Binary(left, op, right) => {
                let lv = self.eval_expr_with_builtins(left, token_line);
                let rv = self.eval_expr_with_builtins(right, token_line);
                match op {
                    Token::Or => if Self::is_truthy(&lv) { lv } else { rv },
                    Token::And => if !Self::is_truthy(&lv) { lv } else { rv },
                    Token::EqEq | Token::NotEq => {
                        let eq = match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => a == b,
                            (Value::Bool(a), Value::Bool(b)) => a == b,
                            (Value::String(a), Value::String(b)) => a == b,
                            (Value::Nil, Value::Nil) => true,
                            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
                            (Value::List(a), Value::List(b)) => {
                                fn list_eq(a: &Vec<Value>, b: &Vec<Value>) -> bool {
                                    if a.len() != b.len() { return false; }
                                    for (va, vb) in a.iter().zip(b.iter()) {
                                        if !val_eq(va, vb) { return false; }
                                    }
                                    true
                                }
                                list_eq(&a.borrow(), &b.borrow())
                            }
                            _ => false,
                        };
                        if let Token::EqEq = op { if eq { Value::Bool(true) } else { Value::Bool(false) } } else { if eq { Value::Bool(false) } else { Value::Bool(true) } }
                    }
                    Token::Lt | Token::Leq | Token::Gt | Token::Geq => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                let res = match op {
                                    Token::Lt => a < b, Token::Leq => a <= b, Token::Gt => a > b, Token::Geq => a >= b,
                                    _ => unreachable!(),
                                };
                                Value::Bool(res)
                            }
                            (Value::String(a), Value::String(b)) => {
                                let res = match op {
                                    Token::Lt => a < b, Token::Leq => a <= b, Token::Gt => a > b, Token::Geq => a >= b,
                                    _ => unreachable!(),
                                };
                                Value::Bool(res)
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply {:?} to {} and {}", op, Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    Token::Plus => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                if let Some(res) = a.checked_add(*b) { Value::Int(res) } else {
                                    self.runtime_error(token_line, "integer overflow", op);
                                    Value::Nil
                                }
                            }
                            (Value::String(a), Value::String(b)) => Value::String(format!("{}{}", a, b)),
                            (Value::List(a), Value::List(b)) => {
                                let mut res = a.borrow().clone();
                                res.extend(b.borrow().clone());
                                Value::List(Rc::new(RefCell::new(res)))
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply + to {} and {}", Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    Token::Minus | Token::Star | Token::Slash | Token::Percent => {
                        match (&lv, &rv) {
                            (Value::Int(a), Value::Int(b)) => {
                                if let Token::Slash | Token::Percent = op {
                                    if *b == 0 {
                                        self.runtime_error(token_line, "division by zero", op);
                                        return Value::Nil;
                                    }
                                }
                                let res = match op {
                                    Token::Minus => a.checked_sub(*b),
                                    Token::Star => a.checked_mul(*b),
                                    Token::Slash => Some(a / b),
                                    Token::Percent => Some(a % b),
                                    _ => unreachable!(),
                                };
                                if let Some(r) = res { Value::Int(r) } else {
                                    self.runtime_error(token_line, "integer overflow", op);
                                    Value::Nil
                                }
                            }
                            _ => {
                                self.runtime_error(token_line, &format!("cannot apply {:?} to {} and {}", op, Self::type_name(&lv), Self::type_name(&rv)), op);
                                Value::Nil
                            }
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Unary(op, expr) => {
                let v = self.eval_expr_with_builtins(expr, token_line);
                match op {
                    Token::Not => Value::Bool(!Self::is_truthy(&v)),
                    Token::Minus => {
                        if let Value::Int(i) = v {
                            if let Some(res) = i.checked_neg() { Value::Int(res) } else {
                                self.runtime_error(token_line, "integer overflow", op);
                                Value::Nil
                            }
                        } else {
                            self.runtime_error(token_line, &format!("cannot apply - to {}", Self::type_name(&v)), op);
                            Value::Nil
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Call(callee_expr, args_exprs) => {
                let callee = self.eval_expr_with_builtins(callee_expr, token_line);
                let mut args = Vec::new();
                for ae in args_exprs {
                    args.push(self.eval_expr_with_builtins(ae, token_line));
                }

                if let Value::Function(func) = &callee {
                    if func.params.len() == 1 && func.body.is_empty() {
                        let builtin_name = &func.params[0];
                        return builtin_call(builtin_name, args, self, token_line);
                    }
                }
                self.call_function(callee, args, token_line)
            }
            Expr::Index(obj_expr, idx_expr) => {
                let obj = self.eval_expr_with_builtins(obj_expr, token_line);
                let idx = self.eval_expr_with_builtins(idx_expr, token_line);
                match (&obj, &idx) {
                    (Value::List(l), Value::Int(i)) => {
                        let bor = l.borrow();
                        if *i >= 0 && (*i as usize) < bor.len() {
                            bor[*i as usize].clone()
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, bor.len()), &Token::LBracket);
                            Value::Nil
                        }
                    }
                    (Value::String(s), Value::Int(i)) => {
                        if *i >= 0 && (*i as usize) < s.len() {
                            let mut res = String::new();
                            res.push(s.as_bytes()[*i as usize] as char);
                            Value::String(res)
                        } else {
                            self.runtime_error(token_line, &format!("index {} out of range for length {}", i, s.len()), &Token::LBracket);
                            Value::Nil
                        }
                    }
                    (Value::List(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index list with {}", Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                    (Value::String(_), _) => {
                        self.runtime_error(token_line, &format!("cannot index string with {}", Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                    _ => {
                        self.runtime_error(token_line, &format!("cannot index {} with {}", Self::type_name(&obj), Self::type_name(&idx)), &Token::LBracket);
                        Value::Nil
                    }
                }
            }
            Expr::List(elements) => {
                let mut list = Vec::new();
                for e in elements {
                    list.push(self.eval_expr_with_builtins(e, token_line));
                }
                Value::List(Rc::new(RefCell::new(list)))
            }
            Expr::Closure(params, body) => {
                Value::Function(Rc::new(FunctionValue {
                    params: params.clone(),
                    body: body.clone(),
                    closure: self.current_scope.clone(),
                }))
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    char type[16];
    int64_t x, y, w, h;
    int64_t cx, cy, r;
    int64_t points[3][2];
    int64_t x1, y1, x2, y2;
    uint8_t color[4];
} Shape;

typedef struct {
    int width, height;
    uint8_t background[3];
    Shape shapes[100];
    int num_shapes;
} Scene;

char *json_next_token(const char *s, int *pos) {
    while (s[*pos] && (s[*pos] == ' ' || s[*pos] == '\n' || s[*pos] == '\r' || s[*pos] == '\t')) (*pos)++;
    if (!s[*pos]) return NULL;
    int start = *pos;
    if (s[*pos] == '"') {
        (*pos)++;
        while (s[*pos] && s[*pos] != '"') (*pos)++;
        if (s[*pos]) (*pos)++;
    } else {
        while (s[*pos] && s[*pos] != ' ' && s[*pos] != ',' && s[*pos] != ']' && s[*pos] != '}' && s[*pos] != ':' && s[*pos] != '[' && s[*pos] != '\n' && s[*pos] != '\r' && s[*pos] != '\t') {
            (*pos)++;
        }
    }
    int len = *pos - start;
    char *token = malloc(len + 1);
    memcpy(token, s + start, len);
    token[len] = '\0';
    if (token[0] == '"') {
        memmove(token, token + 1, len - 2);
        token[len - 2] = '\0';
    }
    return token;
}

void parse_json(const char *json, Scene *scene) {
    int pos = 0;
    while (true) {
        char *token = json_next_token(json, &pos);
        if (!token) break;
        if (strcmp(token, "\"width\"") == 0) {
            pos++; // skip ':'
            token = json_next_token(json, &pos);
            scene->width = atoi(token);
        } else if (strcmp(token, "\"height\"") == 0) {
            pos++;
            token = json_next_token(json, &pos);
            scene->height = atoi(token);
        } else if (strcmp(token, "\"background\"") == 0) {
            pos++; // skip ':'
            pos++; // skip '['
            for (int i = 0; i < 3; i++) {
                token = json_next_token(json, &pos);
                scene->background[i] = (uint8_t)atoi(token);
                if (i < 2) {
                    while (json[pos] != ',' && json[pos] != ']') pos++;
                    pos++;
                }
            }
            while (json[pos] != ']') pos++;
            pos++;
        } else if (strcmp(token, "\"shapes\"") == 0) {
            pos++; // skip ':'
            pos++; // skip '['
            while (true) {
                while (json[pos] == ' ' || json[pos] == '\n' || json[pos] == '\r' || json[pos] == '\t') pos++;
                if (json[pos] == ']') { pos++; break; }
                if (json[pos] == '{') pos++;
                Shape *s = &scene.shapes[scene->num_shapes++];
                while (true) {
                    char *key = json_next_token(json, &pos);
                    if (strcmp(key, "}") == 0) { free(key); break; }
                    pos++; // skip ':'
                    if (strcmp(key, "\"type\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        strcpy(s->type, val);
                        free(val);
                    } else if (strcmp(key, "\"x\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->x = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"y\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->y = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"w\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->w = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"h\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->h = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"cx\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->cx = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"cy\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->cy = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"r\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->r = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"x1\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->x1 = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"y1\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->y1 = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"x2\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->x2 = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"y2\"") == 0) {
                        char *val = json_next_token(json, &pos);
                        s->y2 = atoll(val);
                        free(val);
                    } else if (strcmp(key, "\"points\"") == 0) {
                        pos++; // skip '['
                        for (int i = 0; i < 3; i++) {
                            pos++; // skip '['
                            char *vx = json_next_token(json, &pos);
                            s->points[i][0] = atoll(vx);
                            free(vx);
                            pos++; // skip ','
                            char *vy = json_next_token(json, &pos);
                            s->points[i][1] = atoll(vy);
                            free(vy);
                            pos++; // skip ']'
                            if (i < 2) {
                                while (json[pos] != ',') pos++;
                                pos++;
                            }
                        }
                        while (json[pos] != ']') pos++;
                        pos++;
                    } else if (strcmp(key, "\"color\"") == 0) {
                        pos++; // skip '['
                        for (int i = 0; i < 4; i++) {
                            char *val = json_next_token(json, &pos);
                            s->color[i] = (uint8_t)atoi(val);
                            free(val);
                            if (i < 3) {
                                while (json[pos] != ',') pos++;
                                pos++;
                            }
                        }
                        while (json[pos] != ']') pos++;
                        pos++;
                    }
                    free(key);
                    while (json[pos] == ' ' || json[pos] == '\n' || json[pos] == '\r' || json[pos] == '\t') pos++;
                    if (json[pos] == ',') pos++;
                }
                while (json[pos] == ' ' || json[pos] == '\n' || json[pos] == '\r' || json[pos] == '\t') pos++;
                if (json[pos] == ',') pos++;
            }
        }
        free(token);
    }
}

uint32_t crc32(uint32_t crc, const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ (0xEDB88320u & (-(crc & 1)));
        }
    }
    return crc;
}

uint32_t adler32(const uint8_t *data, size_t len) {
    uint32_t s1 = 1, s2 = 0;
    for (size_t i = 0; i < len; i++) {
        s1 = (s1 + data[i]) % 65521;
        s2 = (s2 + s1) % 65521;
    }
    return (s2 << 16) | s1;
}

int compare_uint32(const void *a, const void *b) {
    uint32_t va = *(uint32_t *)a;
    uint32_t vb = *(uint32_t *)b;
    return (va > vb) - (va < vb);
}

int main(int argc, char *argv[]) {
