        canvas[i + 1] = scene.background[1];
        canvas[i + 2] = scene.background[2];
    }

    for (int s_idx = 0; s_idx < scene.num_shapes; s_idx++) {
        Shape *s = &scene.shapes[s_idx];
        int64_t covered = 0;
        for (int y = 0; y < scene.height; y++) {
            for (int x = 0; x < scene.width; x++) {
                bool is_covered = false;
                if (strcmp(s->type, "rect") == 0) {
                    if (x >= s->x && x < s->x + s->w && y >= s->y && y < s->y + s->h) is_covered = true;
                } else if (strcmp(s->type, "circle") == 0) {
                    int64_t dx = x - s->cx, dy = y - s->cy;
                    if (dx * dx + dy * dy <= s->r * s->r) is_covered = true;
                } else if (strcmp(s->type, "triangle") == 0) {
                    int64_t e0 = (s->points[1][0] - s->points[0][0]) * (y - s->points[0][1]) - (s->points[1][1] - s->points[0][1]) * (x - s->points[0][0]);
                    int64_t e1 = (s->points[2][0] - s->points[1][0]) * (y - s->points[1][1]) - (s->points[2][1] - s->points[1][1]) * (x - s->points[1][0]);
                    int64_t e2 = (s->points[0][0] - s->points[2][0]) * (y - s->points[2][1]) - (s->points[0][1] - s->points[2][1]) * (x - s->points[2][0]);
                    if ((e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)) is_covered = true;
                } else if (strcmp(s->type, "line") == 0) {
                    int64_t dx = s->x2 - s->x1, dy = s->y2 - s->y1;
                    int64_t L = dx * dx + dy * dy;
                    int64_t t = (x - s->x1) * dx + (y - s->y1) * dy;
                    if (t <= 0) {
                        int64_t d2 = (x - s->x1) * (x - s->x1) + (y - s->y1) * (y - s->y1);
                        if (d2 <= s->r * s->r) is_covered = true;
                    } else if (t >= L) {
                        int64_t d2 = (x - s->x2) * (x - s->x2) + (y - s->y2) * (y - s->y2);
                        if (d2 <= s->r * s->r) is_covered = true;
                    } else {
                        int64_t c = (x - s->x1) * dy - (y - s->y1) * dx;
                        if (c * c <= s->r * s->r * L) is_covered = true;
                    }
                }
                if (is_covered) {
                    covered++;
                    int p_idx = (y * scene.width + x) * 3;
                    uint8_t alpha = s->color[3];
                    for (int c = 0; c < 3; c++) {
                        int64_t sR = s->color[c], dR = canvas[p_idx + c];
                        canvas[p_idx + c] = (uint8_t)((sR * alpha + dR * (255 - alpha) + 127) / 255);
                    }
                }
            }
        }
        printf("%d %s %lld\n", s_idx + 1, s->type, covered);
    }

    uint32_t *all_colors = malloc(scene.width * scene.height * sizeof(uint32_t));
    for (int i = 0; i < scene.width * scene.height; i++) {
        all_colors[i] = (canvas[i * 3] << 16) | (canvas[i * 3 + 1] << 8) | canvas[i * 3 + 2];
    }
    qsort(all_colors, scene.width * scene.height, sizeof(uint32_t), compare_uint32);
    int unique_colors = 0;
    for (int i = 0; i < scene.width * scene.height; i++) {
        if (i == 0 || all_colors[i] != all_colors[i - 1]) unique_colors++;
    }
    printf("colors %d\n", unique_colors);

    FILE *out = fopen("out.png", "wb");
    uint8_t sig[] = {0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A};
    fwrite(sig, 1, 8, out);

    uint8_t ihdr[] = {0,0,0,0, 'I', 'H', 'D', 'R', 0,0,0,13, 0,0,0,0, 0,0,0,0, 8, 2, 0, 0, 0};
    uint32_t w32 = scene.width, h32 = scene.height;
    ihdr[4] = (w32 >> 24) & 0xFF; ihdr[5] = (w32 >> 16) & 0xFF; ihdr[6] = (w32 >> 8) & 0xFF; ihdr[7] = w32 & 0xFF; // This is wrong, IHDR is 13 bytes
    // Correction for IHDR
    uint8_t ihdr_data[13];
    ihdr_data[0] = (w32 >> 24) & 0xFF; ihdr_data[1] = (w32 >> 16) & 0xFF; ihdr_data[2] = (w32 >> 8) & 0xFF; ihdr_data[3] = w32 & 0xFF;
    ihdr_data[4] = (h32 >> 24) & 0xFF; ihdr_data[5] = (h32 >> 16) & 0xFF; ihdr_data[6] = (h32 >> 8) & 0xFF; ihdr_data[7] = h32 & 0xFF;
    ihdr_data[8] = 8; ihdr_data[9] = 2; ihdr_data[10] = 0; ihdr_data[11] = 0; ihdr_data[12] = 0;
    uint32_t len = 13;
    fwrite(&len, 1, 0, out); // Dummy call, use manual write for big-endian
    uint8_t len_be[] = {0,0,0,13}; fwrite(len_be, 1, 4, out);
    fwrite("IHDR", 1, 4, out);
    fwrite(ihdr_data, 1, 13, out);
    uint32_t crc = crc32(0, "IHDR", 4);
    crc = crc32(crc, ihdr_data, 13);
    uint8_t crc_be[] = {(crc >> 24) & 0xFF, (crc >> 16) & 0xFF, (crc >> 8) & 0xFF, crc & 0xFF};
    fwrite(crc_be, 1, 4, out);

    size_t img_size = (scene.width * 3 + 1) * scene.height;
    uint8_t *img_data = malloc(img_size);
    size_t offset = 0;
    for (int y = 0; y < scene.height; y++) {
        img_data[offset++] = 0;
        memcpy(img_data + offset, canvas + y * scene.width * 3, scene.width * 3);
        offset += scene.width * 3;
    }

    uint8_t zlib_header[] = {0x78, 0x9C};
    fwrite(zlib_header, 1, 2, out);
    size_t z_off = 0;
    while (z_off < img_size) {
        size_t block_size = (img_size - z_off > 65535) ? 65535 : img_size - z_off;
        uint8_t bfinal = (z_off + block_size == img_size) ? 1 : 0;
        uint8_t head = bfinal | (1 << 1);
        fwrite(&head, 1, 1, out);
        uint16_t plen = block_size;
        uint16_t plenx = ~plen;
        fwrite(&plen, 2, 1, out);
        fwrite(&plenx, 2, 1, out);
        fwrite(img_data + z_off, 1, block_size, out);
        z_off += block_size;
    }
    uint32_t adler = adler32(img_data, img_size);
    uint8_t adler_be[] = {(adler >> 24) & 0xFF, (adler >> 16) & 0xFF, (adler >> 8) & 0xFF, adler & 0xFF};
    fwrite(adler_be, 1, 4, out);

    // The IDAT chunk needs to wrap the zlib stream.
    // Re-writing IDAT properly:
    fseek(out, 0, SEEK_SET);
    fwrite(sig, 1, 8, out);
    fwrite(len_be, 1, 4, out);
    fwrite("IHDR", 1, 4, out);
    fwrite(ihdr_data, 1, 13, out);
    fwrite(crc_be, 1, 4, out);

    // IDAT
    size_t zlib_size = 2 + ( (img_size + 65534) / 65535 ) * 5 + img_size + 4;
    uint32_t idat_len = zlib_size;
    uint8_t idat_len_be[] = {(idat_len >> 24) & 0xFF, (idat_len >> 16) & 0xFF, (idat_len >> 8) & 0xFF, idat_len & 0xFF};
    fwrite(idat_len_be, 1, 4, out);
    fwrite("IDAT", 1, 4, out);
    fwrite(zlib_header, 1, 2, out);
    z_off = 0;
    while (z_off < img_size) {
        size_t block_size = (img_size - z_off > 65535) ? 65535 : img_size - z_off;
        uint8_t bfinal = (z_off + block_size == img_size) ? 1 : 0;
        uint8_t head = bfinal | (1 << 1);
        fwrite(&head, 1, 1, out);
        uint16_t plen = block_size;
        uint16_t plenx = ~plen;
        fwrite(&plen, 2, 1, out);
        fwrite(&plenx, 2, 1, out);
        fwrite(img_data + z_off, 1, block_size, out);
        z_off += block_size;
    }
    fwrite(adler_be, 1, 4, out);

    // CRC for IDAT
    uint8_t *idat_content = malloc(zlib_size);
    memcpy(idat_content, zlib_header, 2);
    z_off = 2;
    z_off = 0; // Reset for logic
    uint8_t *ptr = idat_content + 2;
    z_off = 0;
    while (z_off < img_size) {
        size_t block_size = (img_size - z_off > 65535) ? 65535 : img_size - z_off;
        uint8_t bfinal = (z_off + block_size == img_size) ? 1 : 0;
        *ptr++ = bfinal | (1 << 1);
        uint16_t plen = block_size;
        memcpy(ptr, &plen, 2); ptr += 2;
        uint16_t plenx = ~plen;
        memcpy(ptr, &plenx, 2); ptr += 2;
        memcpy(ptr, img_data + z_off, block_size); ptr += block_size;
        z_off += block_size;
    }
    memcpy(ptr, adler_be, 4);
    uint32_t idat_crc = crc32(0, "IDAT", 4);
    idat_crc = crc32(idat_crc, idat_content, zlib_size);
    uint8_t idat_crc_be[] = {(idat_crc >> 24) & 0xFF, (idat_crc >> 16) & 0xFF, (idat_crc >> 8) & 0xFF, idat_crc & 0xFF};
    fwrite(idat_crc_be, 1, 4, out);
    free(idat_content);

    uint8_t iend_len[] = {0,0,0,0};
    fwrite(iend_len, 1, 4, out);
    fwrite("IEND", 1, 4, out);
    uint32_t iend_crc = crc32(0, "IEND", 4);
    uint8_t iend_crc_be[] = {(iend_crc >> 24) & 0xFF, (iend_crc >> 16) & 0xFF, (iend_crc >> 8) & 0xFF, iend_crc & 0xFF};
    fwrite(iend_crc_be, 1, 4, out);

    fclose(out);
    free(canvas);
    free(all_colors);
    free(img_data);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    char type[16];
    int64_t x, y, w, h;
    int64_t cx, cy, r;
    int64_t points[3][2];
    int64_t x1, y1, x2, y2;
    uint8_t color[4];
} Shape;

typedef struct {
    int width, height;
    uint8_t background[3];
    Shape shapes[100];
    int num_shapes;
} Scene;

void skip_ws(const char **s) {
    while (**s && (**s == ' ' || **s == '\n' || **s == '\r' || **s == '\t')) (*s)++;
}

void parse_string(const char **s, char *buf) {
    skip_ws(s);
    if (**s == '"') (*s)++;
    int i = 0;
    while (**s && **s != '"') buf[i++] = *(*s)++;
    if (**s == '"') (*s)++;
    buf[i] = '\0';
}

int64_t parse_num(const char **s) {
    skip_ws(s);
    int64_t res = 0, sign = 1;
    if (**s == '-') { sign = -1; (*s)++; }
    while (**s && (**s >= '0' && **s <= '9')) {
        res = res * 10 + (**s - '0');
        (*s)++;
    }
    return res * sign;
}

void parse_json(const char *json, Scene *scene) {
    const char *s = json;
    while (*s) {
        skip_ws(&s);
        if (*s == '{') s++;
        else if (*s == '}') { s++; break; }
        else if (*s == '[') s++;
        else if (*s == ']') s++;
        else if (*s == ',') s++;
        else if (*s == ':') s++;
        else {
            char key[32];
            parse_string(&s, key);
            skip_ws(&s);
            if (*s == ':') s++;
            if (strcmp(key, "width") == 0) scene->width = (int)parse_num(&s);
            else if (strcmp(key, "height") == 0) scene->height = (int)parse_num(&s);
            else if (strcmp(key, "background") == 0) {
                skip_ws(&s); s++; // [
                for (int i = 0; i < 3; i++) {
                    scene->background[i] = (uint8_t)parse_num(&s);
                    skip_ws(&s); if (*s == ',') s++;
                }
                skip_ws(&s); s++; // ]
            } else if (strcmp(key, "shapes") == 0) {
                skip_ws(&s); s++; // [
                while (true) {
                    skip_ws(&s);
                    if (*s == ']') { s++; break; }
                    if (*s == '{') s++;
                    Shape *sh = &scene->shapes[scene->num_shapes++];
                    while (true) {
                        skip_ws(&s);
                        if (*s == '}') { s++; break; }
                        char skey[32];
                        parse_string(&s, skey);
                        skip_ws(&s); if (*s == ':') s++;
                        if (strcmp(skey, "type") == 0) {
                            char val[16]; parse_string(&s, val); strcpy(sh->type, val);
                        } else if (strcmp(skey, "x") == 0) sh->x = parse_num(&s);
                        else if (strcmp(skey, "y") == 0) sh->y = parse_num(&s);
                        else if (strcmp(skey, "w") == 0) sh->w = parse_num(&s);
                        else if (strcmp(skey, "h") == 0) sh->h = parse_num(&s);
                        else if (strcmp(skey, "cx") == 0) sh->cx = parse_num(&s);
                        else if (strcmp(skey, "cy") == 0) sh->cy = parse_num(&s);
                        else if (strcmp(skey, "r") == 0) sh->r = parse_num(&s);
                        else if (strcmp(skey, "x1") == 0) sh->x1 = parse_num(&s);
                        else if (strcmp(skey, "y1") == 0) sh->y1 = parse_num(&s);
                        else if (strcmp(skey, "x2") == 0) sh->x2 = parse_num(&s);
                        else if (strcmp(skey, "y2") == 0) sh->y2 = parse_num(&s);
                        else if (strcmp(skey, "points") == 0) {
                            skip_ws(&s); s++; // [
                            for (int i = 0; i < 3; i++) {
                                skip_ws(&s); s++; // [
                                sh->points[i][0] = parse_num(&s);
                                skip_ws(&s); s++; // ,
                                sh->points[i][1] = parse_num(&s);
                                skip_ws(&s); s++; // ]
                                skip_ws(&s); if (*s == ',') s++;
                            }
                            skip_ws(&s); s++; // ]
                        } else if (strcmp(skey, "color") == 0) {
                            skip_ws(&s); s++; // [
                            for (int i = 0; i < 4; i++) {
                                sh->color[i] = (uint8_t)parse_num(&s);
                                skip_ws(&s); if (*s == ',') s++;
                            }
                            skip_ws(&s); s++; // ]
                        }
                        skip_ws(&s); if (*s == ',') s++;
                    }
                    skip_ws(&s); if (*s == ',') s++;
                }
            }
        }
    }
}

uint32_t crc32(uint32_t crc, const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ (0xEDB88320u & (-(crc & 1)));
        }
    }
    return crc;
}

uint32_t adler32(const uint8_t *data, size_t len) {
    uint32_t s1 = 1, s2 = 0;
    for (size_t i = 0; i < len; i++) {
        s1 = (s1 + data[i]) % 65521;
        s2 = (s2 + s1) % 65521;
    }
    return (s2 << 16) | s1;
}

void write_u32_be(FILE *f, uint32_t v) {
    uint8_t b[4] = {(v >> 24) & 0xFF, (v >> 16) & 0xFF, (v >> 8) & 0xFF, v & 0xFF};
    fwrite(b, 1, 4, f);
}

void write_u32_le(FILE *f, uint32_t v) {
    uint8_t b[4] = {v & 0xFF, (v >> 8) & 0xFF, (v >> 16) & 0xFF, (v >> 24) & 0xFF};
    fwrite(b, 1, 4, f);
}

int compare_u32(const void *a, const void *b) {
    uint32_t va = *(uint32_t *)a, vb = *(uint32_t *)b;
    return (va > vb) - (va < vb);
}

