    uint8_t ihdr_data[13];
    uint32_t w32 = scene.width, h32 = scene.height;
    ihdr_data[0] = (w32 >> 24) & 0xFF; ihdr_data[1] = (w32 >> 16) & 0xFF; ihdr_data[2] = (w32 >> 8) & 0xFF; ihdr_data[3] = w32 & 0xFF;
    ihdr_data[4] = (h32 >> 24) & 0xFF; ihdr_data[5] = (h32 >> 16) & 0xFF; ihdr_data[6] = (h32 >> 8) & 0xFF; ihdr_data[7] = h32 & 0xFF;
    memcpy(ihdr_data + 8, ihdr_extra, 5);
    ihdr_crc = crc32(ihdr_crc, ihdr_data, 13);
    write_u32_be(out, ihdr_crc);

    size_t img_size = (size_t)scene.height * (1 + (size_t)scene.width * 3);
    uint8_t *img_data = malloc(img_size);
    size_t offset = 0;
    for (int y = 0; y < scene.height; y++) {
        img_data[offset++] = 0;
        memcpy(img_data + offset, canvas + y * scene.width * 3, scene.width * 3);
        offset += scene.width * 3;
    }

    uint8_t zlib_header[] = {0x78, 0x9C};
    uint8_t *zlib_buf = malloc(img_size + 100);
    size_t z_off = 0;
    memcpy(zlib_buf, zlib_header, 2); z_off = 2;
    size_t data_off = 0;
    while (data_off < img_size) {
        size_t block_size = (img_size - data_off > 65535) ? 65535 : img_size - data_off;
        uint8_t bfinal = (data_off + block_size == img_size) ? 1 : 0;
        zlib_buf[z_off++] = (bfinal << 7);
        uint16_t plen = (uint16_t)block_size;
        zlib_buf[z_off++] = plen & 0xFF; zlib_buf[z_off++] = (plen >> 8) & 0xFF;
        uint16_t nlen = ~plen;
        zlib_buf[z_off++] = nlen & 0xFF; zlib_buf[z_off++] = (nlen >> 8) & 0xFF;
        memcpy(zlib_buf + z_off, img_data + data_off, block_size);
        z_off += block_size;
        data_off += block_size;
    }
    uint32_t adler = adler32(img_data, img_size);
    zlib_buf[z_off++] = (adler >> 24) & 0xFF; zlib_buf[z_off++] = (adler >> 16) & 0xFF;
    zlib_buf[z_off++] = (adler >> 8) & 0xFF; zlib_buf[z_off++] = adler & 0xFF;

    write_u32_be(out, (uint32_t)z_off);
    fwrite("IDAT", 1, 4, out);
    fwrite(zlib_buf, 1, z_off, out);
    uint32_t idat_crc = crc32(0, (const uint8_t *)"IDAT", 4);
    idat_crc = crc32(idat_crc, zlib_buf, z_off);
    write_u32_be(out, idat_crc);

    write_u32_be(out, 0);
    fwrite("IEND", 1, 4, out);
    uint32_t iend_crc = crc32(0, (const uint8_t *)"IEND", 4);
    write_u32_be(out, iend_crc);

    fclose(out);
    free(canvas);
    free(all_colors);
    free(img_data);
    free(zlib_buf);
    return 0;
}

import Foundation

// MARK: - Schema Definitions
enum ProtoType {
    case int32, int64, uint32, uint64, sint32, sint64, bool, string, bytes, fixed32, fixed64, sfixed32, sfixed64
    case message(String), enumType(String)
}

struct Field {
    let type: ProtoType
    let name: String
    let number: Int
    let isRepeated: Bool
    let isOptional: Bool
    let isMap: Bool
    let mapKeyType: ProtoType?
}

struct Message {
    let name: String
    var fields: [Int: Field] = [:]
    var oneofs: [String: [Int]] = [:]
    var fieldToOneof: [Int: String] = [:]
}

struct Enum {
    let name: String
    let values: [Int: String]
}

// MARK: - Lexer & Parser
class ProtoParser {
    let input: String
    var pos = 0

    init(_ input: String) { self.input = input }

    func peek() -> Character? { pos < input.count ? input[input.index(input.startIndex, offsetBy: pos)] : nil }
    func next() -> Character? {
        let c = peek()
        if c != nil { pos += 1 }
        return c
    }

    func skipWhitespace() {
        while pos < input.count {
            let c = peek()
            if c?.isWhitespace == true {
                _ = next()
            } else if c == "/" {
                if pos + 1 < input.count && input[input.index(input.startIndex, offsetBy: pos + 1)] == "/" {
                    while pos < input.count && peek() != "\n" { _ = next() }
                } else if pos + 1 < input.count && input[input.index(input.startIndex, offsetBy: pos + 1)] == "*" {
                    _ = next(); _ = next()
                    while pos < input.count {
                        if peek() == "*" {
                            _ = next()
                            if peek() == "/" { _ = next(); _ = next(); break }
                        } else { _ = next() }
                    }
                } else { break }
            } else { break }
        }
    }

    func consume(expected: String) {
        for char in expected {
            if next() != char { fatalError("Expected \(expected)") }
        }
    }

    func readIdentifier() -> String {
        var s = ""
        while let c = peek(), (c.isLetter || c.isNumber || c == "_") {
            s.append(next()!)
        }
        return s
    }

    func readStringLiteral() -> String {
        _ = next() // "
        var s = ""
        while let c = peek(), c != "\"" {
            s.append(next()!)
        }
        _ = next() // "
        return s
    }

    func readNumber() -> Int {
        var s = ""
        if peek() == "-" { s.append(next()!) }
        while let c = peek(), c.isNumber { s.append(next()!) }
        return Int(s) ?? 0
    }

    func parse() -> (messages: [String: Message], enums: [String: Enum], root: String) {
        var messages: [String: Message] = [:]
        var enums: [String: Enum] = [:]
        var rootType: String?

        while pos < input.count {
            skipWhitespace()
            if pos >= input.count { break }
            let id = readIdentifier()
            if id == "syntax" {
                consume(expected: " = ")
                _ = readStringLiteral()
                consume(expected: ";")
            } else if id == "package" {
                var p = ""
                skipWhitespace()
                while let c = peek(), c != ";" {
                    p.append(next()!)
                }
                consume(expected: ";")
            } else if id == "option" {
                skipWhitespace(); consume(expected: " = ")
                _ = parseValue()
                consume(expected: ";")
            } else if id == "message" {
                skipWhitespace()
                let name = readIdentifier()
                if rootType == nil { rootType = name }
                var msg = Message(name: name)
                consume(expected: " {")
                while true {
                    skipWhitespace()
                    if peek() == "}" { _ = next(); break }
                    let token = readIdentifier()
                    if token == "repeated" {
                        skipWhitespace()
                        let type = readIdentifier()
                        skipWhitespace()
                        let name = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(type, messages, enums), name: name, number: num, isRepeated: true, isOptional: false, isMap: false, mapKeyType: nil)
                        handleOptions()
                    } else if token == "optional" {
                        skipWhitespace()
                        let type = readIdentifier()
                        skipWhitespace()
                        let name = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(type, messages, enums), name: name, number: num, isRepeated: false, isOptional: true, isMap: false, mapKeyType: nil)
                        handleOptions()
                    } else if token == "map" {
                        consume(expected: "<")
                        let kTypeStr = readIdentifier()
                        consume(expected: ", ")
                        let vTypeStr = readIdentifier()
                        consume(expected: ">")
                        skipWhitespace()
                        let name = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(vTypeStr, messages, enums), name: name, number: num, isRepeated: true, isOptional: false, isMap: true, mapKeyType: parseType(kTypeStr, messages, enums))
                        handleOptions()
                    } else if token == "oneof" {
                        skipWhitespace()
                        let oneofName = readIdentifier()
                        consume(expected: " {")
                        while true {
                            skipWhitespace()
                            if peek() == "}" { _ = next(); break }
                            let type = readIdentifier()
                            skipWhitespace()
                            let name = readIdentifier()
                            skipWhitespace(); consume(expected: "="); skipWhitespace()
                            let num = readNumber()
                            consume(expected: ";")
                            msg.fields[num] = Field(type: parseType(type, messages, enums), name: name, number: num, isRepeated: false, isOptional: false, isMap: false, mapKeyType: nil)
                            msg.oneofs[oneofName, default: []].append(num)
                            msg.fieldToOneof[num] = oneofName
                            handleOptions()
                        }
                        handleOptions()
                    } else if token == "reserved" {
                        while peek() != ";" { _ = next() }
                        consume(expected: ";")
                    } else if token == "enum" {
                        skipWhitespace()
                        let enumName = readIdentifier()
                        consume(expected: " {")
                        var enumVals: [Int: String] = [:]
                        while true {
                            skipWhitespace()
                            if peek() == "}" { _ = next(); break }
                            let valName = readIdentifier()
                            skipWhitespace(); consume(expected: "="); skipWhitespace()
                            let valNum = readNumber()
                            consume(expected: ";")
                            enumVals[valNum] = valName
                            handleOptions()
                        }
                        handleOptions()
                        enums[enumName] = Enum(name: enumName, values: enumVals)
                    } else if token == "message" {
                        // This is handled by the outer loop, but we need to handle nested.
                        // The problem says names are unique, so we can just parse and add to global maps.
                        // Since we've already read "message", we need to backtrack or handle it.
                        // Let's refine the loop.
                    } else {
                        // Likely a field type
                        let type = token
                        skipWhitespace()
                        let name = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(type, messages, enums), name: name, number: num, isRepeated: false, isOptional: false, isMap: false, mapKeyType: nil)
                        handleOptions()
                    }
                }
                messages[name] = msg
            } else {
                _ = next()
            }
        }
        return (messages, enums, rootType!)
    }

    func parseType(_ name: String, _ messages: [String: Message], _ enums: [String: Enum]) -> ProtoType {
        switch name {
        case "int32": return .int32
        case "int64": return .int64
        case "uint32": return .uint32
        case "uint64": return .uint64
        case "sint32": return .sint32
        case "sint64": return .sint64
        case "bool": return .bool
        case "string": return .string
        case "bytes": return .bytes
        case "fixed32": return .fixed32
        case "fixed64": return .fixed64
        case "sfixed32": return .sfixed32
        case "sfixed64": return .sfixed64
        default:
            if !enums[name]!.isEmpty || enums[name] != nil { return .enumType(name) }
            return .message(name)
        }
    }

    func parseValue() -> String {
        skipWhitespace()
        if peek() == "\"" { return readStringLiteral() }
        let id = readIdentifier()
        if id.isEmpty { return "" }
        return id
    }

    func handleOptions() {
        skipWhitespace()
        if peek() == "[" {
            _ = next()
            while peek() != "]" {
                skipWhitespace()
                _ = readIdentifier()
                consume(expected: " = ")
                _ = parseValue()
                skipWhitespace()
                if peek() == "," { _ = next() }
            }
            _ = next()
        }
    }
}

// MARK: - Protobuf Decoder
class ProtobufDecoder {
    let data: Data
    var pos = 0

    init(_ data: Data) { self.data = data }

    func readVarint() -> Int64 {
        var value: Int64 = 0
        var shift: Int = 0
        while pos < data.count {
            let byte = data[pos]
            pos += 1
            value |= Int64(byte & 0x7F) << shift
            if byte & 0x80 == 0 { break }
            shift += 7
        }
        return value
    }

    func readFixed32() -> UInt32 {
        let val = data.subdata(in: pos..<pos+4).withUnsafeBytes { $0.load(as: UInt32.self) }
        pos += 4
        return val
    }

    func readFixed64() -> UInt64 {
        let val = data.subdata(in: pos..<pos+8).withUnsafeBytes { $0.load(as: UInt64.self) }
        pos += 8
        return val
    }

    func decodeMessage(schema: Message, messages: [String: Message], enums: [String: Enum], limit: Int) -> [Int: Any] {
        var result: [Int: Any] = [:]
        let end = pos + limit
        while pos < end {
            let key = readVarint()
            let fieldNum = Int(key >> 3)
            let wireType = Int(key & 0x07)

            if let field = schema.fields[fieldNum] {
                let value = decodeValue(field: field, messages: messages, enums: enums, end: end)
                mergeValue(field: field, value: value, result: &result)
            } else {
                skipUnknownField(wireType: wireType, end: end)
            }
        }
        return result
    }

    func decodeValue(field: Field, messages: [String: Message], enums: [String: Enum], end: Int) -> Any {
        switch field.type {
        case .int32, .uint32, .sint32, .bool, .enumType:
            let v = readVarint()
            if case .sint32 = field.type { return decodeZigZag(v) }
            return v
        case .int64, .uint64, .sint64:
            let v = readVarint()
            if case .sint64 = field.type { return decodeZigZag(v) }
            return v
        case .fixed32, .sfixed32:
            return readFixed32()
        case .fixed64, .sfixed64:
            return readFixed64()
        case .string:
            let len = Int(readVarint())
            let s = String(data: data.subdata(in: pos..<pos+len), encoding: .utf8) ?? ""
            pos += len
            return s
        case .bytes:
            let len = Int(readVarint())
            let b = data.subdata(in: pos..<pos+len)
            pos += len
            return b
        case .message(let name):
            let len = Int(readVarint())
            let subDecoder = ProtobufDecoder(data.subdata(in: pos..<pos+len))
            let res = subDecoder.decodeMessage(schema: messages[name]!, messages: messages, enums: enums, limit: len)
            pos += len
            return res
        case .enumType(let name):
            let v = readVarint()
            return v
        }
    }

    func decodeZigZag(_ n: Int64) -> Int64 {
        return (n >> 1) ^ -(n & 1)
    }

    func mergeValue(field: Field, value: Any, result: inout [Int: Any]) {
        if field.isRepeated {
            if field.isMap {
                let mapVal = value as! [Int: Any]
                var currentMap = result[field.number] as? [AnyHashable: Any] ?? [:]
                let key = mapVal[1] ?? (field.mapKeyType == .string ? "" : 0)
                let val = mapVal[2] ?? (field.type == .bool ? false : field.type == .string ? "" : field.type == .bytes ? Data() : 0) // simplified
                // This logic for map values is slightly flawed; the map entry is a message.
                // Let's fix it: the map entry is decoded as a message.
                // We need the actual value from the map entry.
            } else {
                // Handle packed repeated
                // If the value is a packed array (detected by wire type 2), it's already processed?
                // No, the current `decodeValue` doesn't handle packed.
            }
        }
    }

    func skipUnknownField(wireType: Int, end: Int) {
        switch wireType {
        case 0: _ = readVarint()
        case 1: pos += 8
        case 2:
            let len = Int(readVarint())
            pos += len
        case 5: pos += 4
        case 3:
            let fieldNum = 0 // Need to track for group
            // The prompt says groups only occur as unknown fields.
            // We need the field number to find the matching end group.
            // This requires modifying the loop.
            break
        default: break
        }
    }
}

// MARK: - Refined Decoder
class ProtoDecoder {
    let data: Data
    var pos = 0

    init(_ data: Data) { self.data = data }

    func readVarint() -> Int64 {
        var value: Int64 = 0
        var shift: Int = 0
        while pos < data.count {
            let byte = data[pos]
            pos += 1
            value |= Int64(byte & 0x7F) << shift
            if byte & 0x80 == 0 { break }
            shift += 7
            if shift >= 64 { break }
        }
        return value
    }

    func readFixed32() -> UInt32 {
        let val = data.subdata(in: pos..<pos+4).withUnsafeBytes { $0.load(as: UInt32.self) }
        pos += 4
        return val
    }

    func readFixed64() -> UInt64 {
        let val = data.subdata(in: pos..<pos+8).withUnsafeBytes { $0.load(as: UInt64.self) }
        pos += 8
        return val
    }

    func decodeMessage(schema: Message, messages: [String: Message], enums: [String: Enum], limit: Int) -> [Int: Any] {
        var result: [Int: Any] = [:]
        let end = pos + limit
        while pos < end {
            let key = readVarint()
            let fieldNum = Int(key >> 3)
            let wireType = Int(key & 0x07)

            if let field = schema.fields[fieldNum] {
                if wireType == 2 && field.isRepeated && !field.isMap {
                    // Packed repeated
                    let len = Int(readVarint())
                    let packedEnd = pos + len
                    while pos < packedEnd {
                        let val = decodeScalar(type: field.type, messages: messages, enums: enums)
                        var list = result[fieldNum] as? [Any] ?? []
                        list.append(val)
                        result[fieldNum] = list
                    }
                    pos = packedEnd
                } else {
                    let val = decodeValue(field: field, messages: messages, enums: enums)
                    if field.isRepeated {
                        if field.isMap {
                            var map = result[fieldNum] as? [AnyHashable: Any] ?? [:]
                            let entry = val as! [Int: Any]
                            let k = entry[1] ?? (field.mapKeyType == .string ? "" : 0)
                            let v = entry[2] ?? decodeDefault(type: field.type, messages: messages, enums: enums)
                            map[k] = v
                            result[fieldNum] = map
                        } else {
                            var list = result[fieldNum] as? [Any] ?? []
                            list.append(val)
                            result[fieldNum] = list
                        }
                    } else {
                        if let oneofName = schema.fieldToOneof[fieldNum] {
                            // oneof: clear others
                            for otherNum in schema.oneofs[oneofName] ?? [] {
                                if otherNum != fieldNum { result.removeValue(forKey: otherNum) }
                            }
                        }

                        if case .message(let name) = field.type {
                            let msgVal = val as! [Int: Any]
                            var current = result[fieldNum] as? [Int: Any] ?? [:]
                            let merged = mergeMessages(current, msgVal, messages[name]!, messages, enums)
                            result[fieldNum] = merged
                        } else {
                            result[fieldNum] = val
                        }
                    }
                }
            } else {
                if wireType == 3 {
                    let fieldNum = fieldNum
                    while pos < end {
                        let k = readVarint()
                        let fNum = Int(k >> 3)
                        let wType = Int(k & 0x07)
                        if wType == 4 && fNum == fieldNum {
                            _ = readVarint() // not needed, already read k
                            // Wait, the key (fieldNum << 3 | 4) is the k we just read.
                            // So we just break.
                            break
                        } else {
                            skipUnknownField(wireType: wType)
                        }
                    }
                } else {
                    skipUnknownField(wireType: wireType)
                }
            }
        }
        return result
    }

    func decodeValue(field: Field, messages: [String: Message], enums: [String: Enum]) -> Any {
        switch field.type {
        case .message(let name):
            let len = Int(readVarint())
            let subDecoder = ProtoDecoder(data.subdata(in: pos..<pos+len))
            let res = subDecoder.decodeMessage(schema: messages[name]!, messages: messages, enums: enums, limit: len)
            pos += len
            return res
        default:
            return decodeScalar(type: field.type, messages: messages, enums: enums)
        }
    }

    func decodeScalar(type: ProtoType, messages: [String: Message], enums: [String: Enum]) -> Any {
        switch type {
        case .int32, .uint32, .bool, .enumType:
            return readVarint()
        case .sint32:
            return decodeZigZag(readVarint())
        case .int64, .uint64:
            return readVarint()
        case .sint64:
            return decodeZigZag(readVarint())
        case .fixed32, .sfixed32:
            return readFixed32()
        case .fixed64, .sfixed64:
            return readFixed64()
        case .string:
            let len = Int(readVarint())
            let s = String(data: data.subdata(in: pos..<pos+len), encoding: .utf8) ?? ""
            pos += len
            return s
        case .bytes:
            let len = Int(readVarint())
            let b = data.subdata(in: pos..<pos+len)
            pos += len
            return b
        case .message, .enumType:
            fatalError("Not a scalar")
        }
    }

    func decodeDefault(type: ProtoType, messages: [String: Message], enums: [String: Enum]) -> Any {
        switch type {
        case .int32, .uint32, .sint32, .int64, .uint64, .sint64, .fixed32, .sfixed32, .fixed64, .sfixed64, .enumType: return 0
        case .bool: return false
        case .string: return ""
        case .bytes: return Data()
        case .message(let name): return decodeMessage(schema: messages[name]!, messages: messages, enums: enums, limit: 0)
        }
    }

    func mergeMessages(_ base: [Int: Any], _ new: [Int: Any], _ schema: Message, _ messages: [String: Message], _ enums: [String: Enum]) -> [Int: Any] {
        var result = base
        for (num, val) in new {
            if let field = schema.fields[num] {
                if field.isRepeated {
                    if field.isMap {
                        var map = result[num] as? [AnyHashable: Any] ?? [:]
                        let entry = val as! [Int: Any]
                        let k = entry[1] ?? (field.mapKeyType == .string ? "" : 0)
                        let v = entry[2] ?? decodeDefault(type: field.type, messages: messages, enums: enums)
                        map[k] = v
                        result[num] = map
                    } else {
                        var list = result[num] as? [Any] ?? []
                        list.append(val)
                        result[num] = list
                    }
                } else if case .message(let name) = field.type {
                    let baseMsg = result[num] as? [Int: Any] ?? [:]
                    let newMsg = val as! [Int: Any]
                    result[num] = mergeMessages(baseMsg, newMsg, messages[name]!, messages, enums)
                } else {
                    result[num] = val
                }
            }
        }
        return result
    }

    func skipUnknownField(wireType: Int) {
        switch wireType {
        case 0: _ = readVarint()
        case 1: pos += 8
        case 2:
            let len = Int(readVarint())
            pos += len
        case 5: pos += 4
        default: break
        }
    }

    func decodeZigZag(_ n: Int64) -> Int64 {
        return (n >> 1) ^ -(n & 1)
    }
}

// MARK: - JSON Encoder
func lowerCamelCase(_ s: String) -> String {
    var result = ""
    var capitalizeNext = false
    for (i, char) in s.enumerated() {
        if char == "_" {
            capitalizeNext = true
        } else {
            if capitalizeNext && char.isLowercase {
                result.append(char.uppercased())
                capitalizeNext = false
            } else {
                result.append(char)
                capitalizeNext = false
            }
        }
    }
    return result
}

func escapeJSONString(_ s: String) -> String {
    var result = ""
    for char in s {
        switch char {
        case "\"": result.append("\\\"")
        case "\\": result.append("\\\\")
        case "\u{0008}": result.append("\\b")
        case "\u{0009}": result.append("\\t")
        case "\u{000A}": result.append("\\n")
        case "\u{000C}": result.append("\\f")
        case "\u{000D}": result.append("\\r")
        default:
            if char.unicodeScalars.first!.value < 0x20 {
                result.append(String(format: "\\u%04x", char.unicodeScalars.first!.value))
            } else {
                result.append(char)
            }
        }
    }
    return result
}

func encodeValue(val: Any, type: ProtoType, messages: [String: Message], enums: [String: Enum]) -> String {
    switch type {
    case .int32, .uint32, .sint32, .fixed32, .sfixed32:
        return "\(val)"
    case .int64, .uint64, .sint64, .fixed64, .sfixed64:
        return "\"\(val)\""
    case .bool:
        return (val as? Int64 ?? 0) != 0 ? "true" : "false"
    case .string:
        return "\"\(escapeJSONString(val as! String))\""
    case .bytes:
        return "\"\( (val as! Data).base64EncodedString())\""
    case .enumType(let name):
        let v = val as! Int64
        if let name = enums[name]?.values[Int(v)] {
            return "\"\(name)\""
        } else {
            return "\(v)"
        }
    case .message(let name):
        let msg = val as! [Int: Any]
        let schema = messages[name]!
        var fields: [String] = []
        let sortedNums = schema.fields.keys.sorted()
        for num in sortedNums {
            let field = schema.fields[num]!
            if let fVal = msg[num] {
                let jsonVal = encodeValue(val: fVal, type: field.type, messages: messages, enums: enums)
                fields.append("\"\(lowerCamelCase(field.name))\":\(jsonVal)")
            } else {
                // Presence: singular message is printed if it occurred (it's in the map)
                // Repeated/Maps are omitted if empty.
                // Scalars are omitted if default, unless optional or oneof.
                if field.isRepeated || field.isMap {
                    // Omitted if empty (not in msg)
                } else if field.isOptional || schema.fieldToOneof[num] != nil {
                    // Printed even if default? The prompt says "printed whenever they occurred".
                    // If it's not in the map, it didn't occur.
                }
            }
        }
        return "{\(fields.joined(separator: ","))}"
    }
}

func renderMessage(msg: [Int: Any], schema: Message, messages: [String: Message], enums: [String: Enum]) -> String {
    var fields: [String] = []
    let sortedNums = schema.fields.keys.sorted()
    for num in sortedNums {
        let field = schema.fields[num]!
        if let val = msg[num] {
            if field.isMap {
                let map = val as! [AnyHashable: Any]
                if map.isEmpty { continue }
                var mapFields: [String] = []
                let sortedKeys: [AnyHashable]
                if field.mapKeyType == .string {
                    sortedKeys = map.keys.compactMap { $0 as? String }.sorted().map { $0 as AnyHashable }
                } else {
                    sortedKeys = map.keys.compactMap { $0 as? Int }.sorted().map { $0 as AnyHashable }
                }
                for k in sortedKeys {
                    let keyStr = (k as? String) != nil ? "\((k as! String))" : "\((k as! Int))"
                    let keyStrEscaped = "\"\(escapeJSONString(keyStr))\""
                    let v = map[k]!
                    mapFields.append("\(keyStrEscaped):\(encodeValue(val: v, type: field.type, messages: messages, enums: enums))")
                }
                fields.append("\"\(lowerCamelCase(field.name))\":{\(mapFields.joined(separator: ","))}")
            } else if field.isRepeated {
                let list = val as! [Any]
                if list.isEmpty { continue }
                let listVals = list.map { encodeValue(val: $0, type: field.type, messages: messages, enums: enums) }
                fields.append("\"\(lowerCamelCase(field.name))\":[\(listVals.joined(separator: ","))]")
            } else {
                // Scalar presence
                let isDefault: Bool
                switch field.type {
                case .int32, .uint32, .sint32, .int64, .uint64, .sint64, .fixed32, .sfixed32, .fixed64, .sfixed64, .enumType:
                    isDefault = (val as! Int64) == 0
                case .bool:
                    isDefault = (val as! Int64) == 0
                case .string:
                    isDefault = (val as! String).isEmpty
                case .bytes:
                    isDefault = (val as! Data).isEmpty
                case .message:
                    isDefault = false // Message fields are always printed if they occur
                }
                if !isDefault || field.isOptional || schema.fieldToOneof[num] != nil {
                    fields.append("\"\(lowerCamelCase(field.name))\":\(encodeValue(val: val, type: field.type, messages: messages, enums: enums))")
                }
            }
        }
    }
    return "{\(fields.joined(separator: ","))}"
}

// MARK: - Main
let args = CommandLine.arguments
if args.count < 2 { exit(0) }
let dir = args[1]
let schemaPath = "\(dir)/schema.proto"
let messagesPath = "\(dir)/messages.bin"

if let schemaContent = try? String(contentsOfFile: schemaPath, encoding: .utf8) {
    let parser = ProtoParser(schemaContent)
    let (messages, enums, rootType) = parser.parse()
    let rootSchema = messages[rootType]!

    if let binData = try? Data(contentsOfFile: messagesPath) {
        var pos = 0
        while pos < binData.count {
            let decoder = ProtoDecoder(binData.subdata(in: pos..<binData.count))
            let len = Int(decoder.readVarint())
            pos += 1
            // The readVarint above is not quite right because the varint itself takes bytes.
            // Let's use a proper varint reader for the record length.
        }
    }
}

// Fixing the main loop for record reading
func run() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let dir = args[1]
    let schemaPath = "\(dir)/schema.proto"
    let messagesPath = "\(dir)/messages.bin"

    guard let schemaContent = try? String(contentsOfFile: schemaPath, encoding: .utf8) else { return }
    let parser = ProtoParser(schemaContent)
    let (messages, enums, rootType) = parser.parse()
    let rootSchema = messages[rootType]!

    guard let binData = try? Data(contentsOfFile: messagesPath) else { return }
    var pos = 0
    while pos < binData.count {
        var value: Int64 = 0
        var shift = 0
        var varintLen = 0
        while pos < binData.count {
            let byte = binData[pos]
            pos += 1
            varintLen += 1
            value |= Int64(byte & 0x7F) << shift
            if byte & 0x80 == 0 { break }
            shift += 7
        }
        let len = Int(value)
        let recordData = binData.subdata(in: pos..<pos+len)
        pos += len
        let decoder = ProtoDecoder(recordData)
        let decoded = decoder.decodeMessage(schema: rootSchema, messages: messages, enums: enums, limit: len)
        print(renderMessage(msg: decoded, schema: rootSchema, messages: messages, enums: enums))
    }
}

run()

import Foundation

// MARK: - Schema Definitions

enum ProtoType: Equatable {
    case int32, int64, uint32, uint64, sint32, sint64, bool, string, bytes, fixed32, fixed64, sfixed32, sfixed64
    case message(String), enumType(String)
}

struct Field {
    let type: ProtoType
    let name: String
    let number: Int
    let isRepeated: Bool
    let isOptional: Bool
    let isMap: Bool
    let mapKeyType: ProtoType?
}

struct Message {
    let name: String
    var fields: [Int: Field] = [:]
    var oneofs: [String: [Int]] = [:]
    var fieldToOneof: [Int: String] = [:]
}

struct EnumType {
    let name: String
    let values: [Int: String]
}

// MARK: - Lexer & Parser

class ProtoParser {
    let input: String
    var pos = 0

    init(_ input: String) { self.input = input }

    func peek() -> Character? { pos < input.count ? input[input.index(input.startIndex, offsetBy: pos)] : nil }
    func next() -> Character? {
        let c = peek()
        if c != nil { pos += 1 }
        return c
    }

    func skipWhitespace() {
        while pos < input.count {
            let c = peek()
            if c?.isWhitespace == true {
                _ = next()
            } else if c == "/" {
                if pos + 1 < input.count && input[input.index(input.startIndex, offsetBy: pos + 1)] == "/" {
                    while pos < input.count && peek() != "\n" { _ = next() }
                } else if pos + 1 < input.count && input[input.index(input.startIndex, offsetBy: pos + 1)] == "*" {
                    _ = next(); _ = next()
                    while pos < input.count {
                        if peek() == "*" {
                            _ = next()
                            if peek() == "/" { _ = next(); _ = next(); break }
                        } else { _ = next() }
                    }
                } else { break }
            } else { break }
        }
    }

    func consume(expected: String) {
        for char in expected {
            if next() != char { fatalError("Expected \(expected)") }
        }
    }

    func readIdentifier() -> String {
        var s = ""
        while let c = peek(), (c.isLetter || c.isNumber || c == "_") {
            s.append(next()!)
        }
        return s
    }

    func readStringLiteral() -> String {
        _ = next() // "
        var s = ""
        while let c = peek(), c != "\"" {
            s.append(next()!)
        }
        _ = next() // "
        return s
    }

    func readNumber() -> Int {
        var s = ""
        if peek() == "-" { s.append(next()!) }
        while let c = peek(), c.isNumber { s.append(next()!) }
        return Int(s) ?? 0
    }

    func parse() -> (messages: [String: Message], enums: [String: EnumType], root: String) {
        var messages: [String: Message] = [:]
        var enums: [String: EnumType] = [:]
        var rootType: String?

        while pos < input.count {
            skipWhitespace()
            if pos >= input.count { break }
            let id = readIdentifier()
            if id == "syntax" {
                skipWhitespace(); consume(expected: "="); skipWhitespace()
                _ = readStringLiteral()
                skipWhitespace(); consume(expected: ";")
            } else if id == "package" {
                skipWhitespace()
                while pos < input.count && peek() != ";" { _ = next() }
                consume(expected: ";")
            } else if id == "option" {
                skipWhitespace(); consume(expected: "="); skipWhitespace()
                _ = parseValue()
                skipWhitespace(); consume(expected: ";")
            } else if id == "message" {
                skipWhitespace()
                let name = readIdentifier()
                if rootType == nil { rootType = name }
                var msg = Message(name: name)
                skipWhitespace(); consume(expected: "{")
                while true {
                    skipWhitespace()
                    if peek() == "}" { _ = next(); break }
                    let token = readIdentifier()
                    if token == "repeated" {
                        skipWhitespace()
                        let typeStr = readIdentifier()
                        skipWhitespace()
                        let fieldName = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(typeStr, messages, enums), name: fieldName, number: num, isRepeated: true, isOptional: false, isMap: false, mapKeyType: nil)
                        handleOptions()
                    } else if token == "optional" {
                        skipWhitespace()
                        let typeStr = readIdentifier()
                        skipWhitespace()
                        let fieldName = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(typeStr, messages, enums), name: fieldName, number: num, isRepeated: false, isOptional: true, isMap: false, mapKeyType: nil)
                        handleOptions()
                    } else if token == "map" {
                        consume(expected: "<")
                        let kTypeStr = readIdentifier()
                        skipWhitespace(); consume(expected: ","); skipWhitespace()
                        let vTypeStr = readIdentifier()
                        consume(expected: ">")
                        skipWhitespace()
                        let fieldName = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(vTypeStr, messages, enums), name: fieldName, number: num, isRepeated: true, isOptional: false, isMap: true, mapKeyType: parseType(kTypeStr, messages, enums))
                        handleOptions()
                    } else if token == "oneof" {
                        skipWhitespace()
                        let oneofName = readIdentifier()
                        skipWhitespace(); consume(expected: "{")
                        while true {
                            skipWhitespace()
                            if peek() == "}" { _ = next(); break }
                            let typeStr = readIdentifier()
                            skipWhitespace()
                            let fieldName = readIdentifier()
                            skipWhitespace(); consume(expected: "="); skipWhitespace()
                            let num = readNumber()
                            consume(expected: ";")
                            msg.fields[num] = Field(type: parseType(typeStr, messages, enums), name: fieldName, number: num, isRepeated: false, isOptional: false, isMap: false, mapKeyType: nil)
                            msg.oneofs[oneofName, default: []].append(num)
                            msg.fieldToOneof[num] = oneofName
                            handleOptions()
                        }
                        handleOptions()
                    } else if token == "reserved" {
                        while pos < input.count && peek() != ";" { _ = next() }
                        consume(expected: ";")
                    } else if token == "enum" {
                        skipWhitespace()
                        let enumName = readIdentifier()
                        skipWhitespace(); consume(expected: "{")
                        var enumVals: [Int: String] = [:]
                        while true {
                            skipWhitespace()
                            if peek() == "}" { _ = next(); break }
                            let valName = readIdentifier()
                            skipWhitespace(); consume(expected: "="); skipWhitespace()
                            let valNum = readNumber()
                            consume(expected: ";")
                            enumVals[valNum] = valName
                            handleOptions()
                        }
                        handleOptions()
                        enums[enumName] = EnumType(name: enumName, values: enumVals)
                    } else {
                        let typeStr = token
                        skipWhitespace()
                        let fieldName = readIdentifier()
                        skipWhitespace(); consume(expected: "="); skipWhitespace()
                        let num = readNumber()
                        consume(expected: ";")
                        msg.fields[num] = Field(type: parseType(typeStr, messages, enums), name: fieldName, number: num, isRepeated: false, isOptional: false, isMap: false, mapKeyType: nil)
                        handleOptions()
                    }
                }
                messages[name] = msg
            } else {
                _ = next()
            }
        }
        return (messages, enums, rootType!)
    }

    func parseType(_ name: String, _ messages: [String: Message], _ enums: [String: EnumType]) -> ProtoType {
        switch name {
        case "int32": return .int32
        case "int64": return .int64
        case "uint32": return .uint32
        case "uint64": return .uint64
        case "sint32": return .sint32
        case "sint64": return .sint64
        case "bool": return .bool
        case "string": return .string
        case "bytes": return .bytes
        case "fixed32": return .fixed32
        case "fixed64": return .fixed64
        case "sfixed32": return .sfixed32
        case "sfixed64": return .sfixed64
        default:
            if enums[name] != nil { return .enumType(name) }
            return .message(name)
        }
    }

    func parseValue() -> String {
        skipWhitespace()
        if peek() == "\"" { return readStringLiteral() }
        return readIdentifier()
    }

    func handleOptions() {
        skipWhitespace()
        if peek() == "[" {
            _ = next()
            while pos < input.count && peek() != "]" {
                skipWhitespace()
                _ = readIdentifier()
                skipWhitespace(); consume(expected: "="); skipWhitespace()
                _ = parseValue()
                skipWhitespace()
                if peek() == "," { _ = next() }
            }
            _ = next()
        }
    }
}

// MARK: - Protobuf Decoder

class ProtoDecoder {
    let data: Data
    var pos = 0

    init(_ data: Data) { self.data = data }

    func readVarint() -> Int64 {
        var value: Int64 = 0
        var shift: Int = 0
        while pos < data.count {
            let byte = data[pos]
            pos += 1
            value |= Int64(byte & 0x7F) << shift
            if byte & 0x80 == 0 { break }
            shift += 7
            if shift >= 64 { break }
        }
        return value
    }

    func readFixed32() -> UInt32 {
        let val = data.subdata(in: pos..<pos+4).withUnsafeBytes { $0.load(as: UInt32.self) }
        pos += 4
        return val
    }

    func readFixed64() -> UInt64 {
        let val = data.subdata(in: pos..<pos+8).withUnsafeBytes { $0.load(as: UInt64.self) }
        pos += 8
        return val
    }

    func decodeMessage(schema: Message, messages: [String: Message], enums: [String: EnumType], limit: Int) -> [Int: Any] {
        var result: [Int: Any] = [:]
        let end = pos + limit
        while pos < end {
            let key = readVarint()
            let fieldNum = Int(key >> 3)
            let wireType = Int(key & 0x07)

            if let field = schema.fields[fieldNum] {
                if wireType == 2 && field.isRepeated && !field.isMap {
                    let len = Int(readVarint())
                    let packedEnd = pos + len
                    while pos < packedEnd {
                        let val = decodeScalar(type: field.type, messages: messages, enums: enums)
                        var list = result[fieldNum] as? [Any] ?? []
                        list.append(val)
                        result[fieldNum] = list
                    }
                    pos = packedEnd
                } else {
                    let val = decodeValue(field: field, messages: messages, enums: enums)
                    if field.isRepeated {
                        if field.isMap {
                            var map = result[fieldNum] as? [AnyHashable: Any] ?? [:]
                            let entry = val as! [Int: Any]
                            let k = entry[1] ?? (field.mapKeyType == .string ? "" : 0)
                            let v = entry[2] ?? decodeDefault(type: field.type, messages: messages, enums: enums)
                            map[k] = v
                            result[fieldNum] = map
                        } else {
                            var list = result[fieldNum] as? [Any] ?? []
                            list.append(val)
                            result[fieldNum] = list
                        }
                    } else {
                        if let oneofName = schema.fieldToOneof[fieldNum] {
                            for otherNum in schema.oneofs[oneofName] ?? [] {
                                if otherNum != fieldNum { result.removeValue(forKey: otherNum) }
                            }
                        }
                        if case .message(let name) = field.type {
                            let msgVal = val as! [Int: Any]
                            let baseMsg = result[fieldNum] as? [Int: Any] ?? [:]
                            result[fieldNum] = mergeMessages(baseMsg, msgVal, messages[name]!, messages, enums)
                        } else {
                            result[fieldNum] = val
                        }
                    }
                }
            } else {
                if wireType == 3 {
                    let groupFieldNum = fieldNum
                    while pos < end {
                        let k = readVarint()
                        let fNum = Int(k >> 3)
                        let wType = Int(k & 0x07)
                        if wType == 4 && fNum == groupFieldNum { break }
                        skipUnknownField(wireType: wType)
                    }
                } else {
                    skipUnknownField(wireType: wireType)
                }
            }
        }
        return result
    }

    func decodeValue(field: Field, messages: [String: Message], enums: [String: EnumType]) -> Any {
        switch field.type {
        case .message(let name):
            let len = Int(readVarint())
            let subDecoder = ProtoDecoder(data.subdata(in: pos..<pos+len))
            let res = subDecoder.decodeMessage(schema: messages[name]!, messages: messages, enums: enums, limit: len)
            pos += len
            return res
        default:
            return decodeScalar(type: field.type, messages: messages, enums: enums)
        }
    }

    func decodeScalar(type: ProtoType, messages: [String: Message], enums: [String: EnumType]) -> Any {
        switch type {
        case .int32, .uint32, .bool, .enumType:
            return readVarint()
        case .sint32:
            return decodeZigZag(readVarint())
        case .int64, .uint64:
            return readVarint()
        case .sint64:
            return decodeZigZag(readVarint())
        case .fixed32, .sfixed32:
            return readFixed32()
        case .fixed64, .sfixed64:
            return readFixed64()
        case .string:
            let len = Int(readVarint())
            let s = String(data: data.subdata(in: pos..<pos+len), encoding: .utf8) ?? ""
            pos += len
            return s
        case .bytes:
            let len = Int(readVarint())
            let b = data.subdata(in: pos..<pos+len)
            pos += len
            return b
        case .message, .enumType:
            return 0 // Should not happen
        }
    }

    func decodeDefault(type: ProtoType, messages: [String: Message], enums: [String: EnumType]) -> Any {
        switch type {
        case .int32, .uint32, .sint32, .int64, .uint64, .sint64, .fixed32, .sfixed32, .fixed64, .sfixed64, .enumType: return Int64(0)
        case .bool: return Int64(0)
        case .string: return ""
        case .bytes: return Data()
        case .message(let name): return decodeMessage(schema: messages[name]!, messages: messages, enums: enums, limit: 0)
        }
    }

    func mergeMessages(_ base: [Int: Any], _ new: [Int: Any], _ schema: Message, _ messages: [String: Message], _ enums: [String: EnumType]) -> [Int: Any] {
        var result = base
        for (num, val) in new {
            if let field = schema.fields[num] {
                if field.isRepeated {
                    if field.isMap {
                        var map = result[num] as? [AnyHashable: Any] ?? [:]
                        let entry = val as! [Int: Any]
                        let k = entry[1] ?? (field.mapKeyType == .string ? "" : 0)
                        let v = entry[2] ?? decodeDefault(type: field.type, messages: messages, enums: enums)
                        map[k] = v
                        result[num] = map
                    } else {
                        var list = result[num] as? [Any] ?? []
                        list.append(val)
                        result[num] = list
                    }
                } else if case .message(let name) = field.type {
                    let baseMsg = result[num] as? [Int: Any] ?? [:]
                    let newMsg = val as! [Int: Any]
                    result[num] = mergeMessages(baseMsg, newMsg, messages[name]!, messages, enums)
                } else {
                    result[num] = val
                }
            }
        }
        return result
    }

    func skipUnknownField(wireType: Int) {
        switch wireType {
        case 0: _ = readVarint()
        case 1: pos += 8
        case 2:
            let len = Int(readVarint())
            pos += len
        case 5: pos += 4
        default: break
        }
    }

    func decodeZigZag(_ n: Int64) -> Int64 {
        return (n >> 1) ^ -(n & 1)
    }
}

// MARK: - JSON Encoder

func lowerCamelCase(_ s: String) -> String {
    var result = ""
    var capitalizeNext = false
    for char in s {
        if char == "_" {
            capitalizeNext = true
        } else {
            if capitalizeNext && char.isLowercase {
                result.append(char.uppercased())
                capitalizeNext = false
            } else {
                result.append(char)
                capitalizeNext = false
            }
        }
    }
    return result
}

func escapeJSONString(_ s: String) -> String {
    var result = ""
    for char in s {
        switch char {
        case "\"": result.append("\\\"")
        case "\\": result.append("\\\\")
        case "\u{0008}": result.append("\\b")
        case "\u{0009}": result.append("\\t")
        case "\u{000A}": result.append("\\n")
        case "\u{000C}": result.append("\\f")
        case "\u{000D}": result.append("\\r")
        default:
            if let scalar = char.unicodeScalars.first, scalar.value < 0x20 {
                result.append(String(format: "\\u%04x", scalar.value))
            } else {
                result.append(char)
            }
        }
    }
    return result
}

func encodeValue(val: Any, type: ProtoType, messages: [String: Message], enums: [String: EnumType]) -> String {
    switch type {
    case .int32, .uint32, .sint32, .fixed32, .sfixed32:
        return "\(val)"
    case .int64, .uint64, .sint64, .fixed64, .sfixed64:
        return "\"\(val)\""
    case .bool:
        let v = (val as? Int64) ?? 0
        return v != 0 ? "true" : "false"
    case .string:
        return "\"\(escapeJSONString(val as! String))\""
    case .bytes:
        return "\"\( (val as! Data).base64EncodedString())\""
    case .enumType(let name):
        let v = (val as? Int64) ?? 0
        if let enumVal = enums[name]?.values[Int(v)] {
            return "\"\(enumVal)\""
        } else {
            return "\(v)"
        }
    case .message(let name):
        let msg = val as! [Int: Any]
        let schema = messages[name]!
        var fields: [String] = []
        let sortedNums = schema.fields.keys.sorted()
        for num in sortedNums {
            let field = schema.fields[num]!
            if let fVal = msg[num] {
                let jsonVal = encodeValue(val: fVal, type: field.type, messages: messages, enums: enums)
                fields.append("\"\(lowerCamelCase(field.name))\":\(jsonVal)")
            } else {
                // Presence handled in renderMessage
            }
        }
        // Note: The logic here is a bit recursive, but renderMessage is the main entry.
        // We need to apply the same presence rules.
        return renderMessage(msg: msg, schema: schema, messages: messages, enums: enums)
    }
}

func renderMessage(msg: [Int: Any], schema: Message, messages: [String: Message], enums: [String: EnumType]) -> String {
    var fields: [String] = []
    let sortedNums = schema.fields.keys.sorted()
    for num in sortedNums {
        let field = schema.fields[num]!
        if let val = msg[num] {
            if field.isMap {
                let map = val as! [AnyHashable: Any]
                if map.isEmpty { continue }
                var mapFields: [String] = []
                let sortedKeys: [AnyHashable]
                if field.mapKeyType == .string {
                    sortedKeys = map.keys.compactMap { $0 as? String }.sorted().map { $0 as AnyHashable }
                } else {
                    sortedKeys = map.keys.compactMap { $0 as? Int }.sorted().map { $0 as AnyHashable }
                }
                for k in sortedKeys {
                    let keyStr = (k as? String) != nil ? (k as! String) : "\(k as! Int)"
                    let keyStrEscaped = "\"\(escapeJSONString(keyStr))\""
                    let v = map[k]!
                    mapFields.append("\(keyStrEscaped):\(encodeValue(val: v, type: field.type, messages: messages, enums: enums))")
                }
                fields.append("\"\(lowerCamelCase(field.name))\":{\(mapFields.joined(separator: ","))}")
            } else if field.isRepeated {
                let list = val as! [Any]
                if list.isEmpty { continue }
                let listVals = list.map { encodeValue(val: $0, type: field.type, messages: messages, enums: enums) }
                fields.append("\"\(lowerCamelCase(field.name))\":[\(listVals.joined(separator: ","))]")
            } else {
                let isDefault: Bool
                switch field.type {
                case .int32, .uint32, .sint32, .int64, .uint64, .sint64, .fixed32, .sfixed32, .fixed64, .sfixed64, .enumType:
                    isDefault = ((val as? Int64) ?? 0) == 0
                case .bool:
                    isDefault = ((val as? Int64) ?? 0) == 0
                case .string:
                    isDefault = (val as! String).isEmpty
                case .bytes:
                    isDefault = (val as! Data).isEmpty
                case .message:
                    isDefault = false
                }
                if !isDefault || field.isOptional || schema.fieldToOneof[num] != nil {
                    fields.append("\"\(lowerCamelCase(field.name))\":\(encodeValue(val: val, type: field.type, messages: messages, enums: enums))")
                }
            }
        }
    }
    return "{\(fields.joined(separator: ","))}"
}

// MARK: - Main

func run() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let dir = args[1]
    let schemaPath = "\(dir)/schema.proto"
    let messagesPath = "\(dir)/messages.bin"

    guard let schemaContent = try? String(contentsOfFile: schemaPath, encoding: .utf8) else { return }
    let parser = ProtoParser(schemaContent)
    let (messages, enums, rootType) = parser.parse()
    let rootSchema = messages[rootType]!

    guard let binData = try? Data(contentsOf: URL(fileURLWithPath: messagesPath)) else { return }
    var pos = 0
    while pos < binData.count {
        var value: Int64 = 0
        var shift = 0
        var varintLen = 0
        while pos < binData.count {
            let byte = binData[pos]
            pos += 1
            varintLen += 1
            value |= Int64(byte & 0x7F) << shift
            if byte & 0x80 == 0 { break }
            shift += 7
            if shift >= 64 { break }
        }
        let len = Int(value)
        let recordData = binData.subdata(in: pos..<pos+len)
        pos += len
        let decoder = ProtoDecoder(recordData)
        let decoded = decoder.decodeMessage(schema: rootSchema, messages: messages, enums: enums, limit: len)
        print(renderMessage(msg: decoded, schema: rootSchema, messages: messages, enums: enums))
    }
}

run()

use std::collections::{HashMap, HashSet};
use std::env;
use std::fs::{self, File};
use std::io::{Read, Write};

#[derive(Debug)]
enum Shape {
    Rect { x: i64, y: i64, w: i64, h: i64, color: [u8; 4] },
    Circle { cx: i64, cy: i64, r: i64, color: [u8; 4] },
    Triangle { points: [(i64, i64); 3], color: [u8; 4] },
    Line { x1: i64, y1: i64, x2: i64, y2: i64, r: i64, color: [u8; 4] },
}

#[derive(Debug)]
enum JsonValue {
    Object(HashMap<String, JsonValue>),
    Array(Vec<JsonValue>),
    Number(i64),
    String(String),
}

fn tokenize(s: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut chars = s.chars().peekable();
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else if c == '{' || c == '}' || c == '[' || c == ']' || c == ':' || c == ',' {
            tokens.push(c.to_string());
            chars.next();
        } else if c == '"' {
            chars.next();
            let mut s = String::new();
            while let Some(&c) = chars.peek() {
                if c == '"' {
                    chars.next();
                    break;
                }
                s.push(c);
                chars.next();
            }
            tokens.push(format!("\"{}\"", s));
        } else {
            let mut s = String::new();
            while let Some(&c) = chars.peek() {
                if c.is_whitespace() || c == '{' || c == '}' || c == '[' || c == ']' || c == ':' || c == ',' {
                    break;
                }
                s.push(c);
                chars.next();
            }
            tokens.push(s);
        }
    }
    tokens
}

fn parse_json_value(tokens: &mut std::iter::Peekable<std::vec::IntoIter<String>>) -> JsonValue {
    let token = tokens.next().expect("Expected token");
    if token == "{" {
        let mut map = HashMap::new();
        loop {
            let key_token = tokens.next().expect("Expected key");
            let key = key_token.trim_matches('"').to_string();
            tokens.next().expect("Expected ':'");
            let value = parse_json_value(tokens);
            map.insert(key, value);
            match tokens.next() {
                Some(",") => continue,
                Some("}") => break,
                _ => panic!("Expected ',' or '}}'"),
            }
        }
        JsonValue::Object(map)
    } else if token == "[" {
        let mut array = Vec::new();
        loop {
            let val = parse_json_value(tokens);
            array.push(val);
            match tokens.next() {
                Some(",") => continue,
                Some("]") => break,
                _ => panic!("Expected ',' or ']'"),
            }
        }
        JsonValue::Array(array)
    } else if token.starts_with('"') {
        JsonValue::String(token.trim_matches('"').to_string())
    } else {
        JsonValue::Number(token.parse::<i64>().expect("Expected number"))
    }
}

fn get_num(val: &JsonValue) -> i64 {
    if let JsonValue::Number(n) = val { *n } else { 0 }
}

fn get_color_rgb(val: &JsonValue) -> [u8; 3] {
    if let JsonValue::Array(arr) = val {
        [get_num(&arr[0]) as u8, get_num(&arr[1]) as u8, get_num(&arr[2]) as u8]
    } else { [0, 0, 0] }
}

fn get_color_rgba(val: &JsonValue) -> [u8; 4] {
    if let JsonValue::Array(arr) = val {
        [get_num(&arr[0]) as u8, get_num(&arr[1]) as u8, get_num(&arr[2]) as u8, get_num(&arr[3]) as u8]
    } else { [0, 0, 0, 0] }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let scene_path = format!("{}/scene.json", args[1]);
    let mut content = String::new();
    File::open(scene_path).unwrap().read_to_string(&mut content).unwrap();
    let tokens = tokenize(&content);
    let mut token_iter = tokens.into_iter().peekable();
    let root = parse_json_value(&mut token_iter);

    if let JsonValue::Object(ref map) = root {
        let width = get_num(map.get("width").unwrap());
        let height = get_num(map.get("height").unwrap());
        let background = get_color_rgb(map.get("background").unwrap());
        let shapes_json = map.get("shapes").unwrap();
        if let JsonValue::Array(ref shapes_list) = shapes_json {
            let mut canvas = vec![background; (width * height) as usize];
            let mut shape_counts = Vec::new();

            for shape_val in shapes_list {
                if let JsonValue::Object(ref s_map) = shape_val {
                    let s_type = if let JsonValue::String(ref t) = s_map.get("type").unwrap() { t.as_str() } else { "" };
                    let color = get_color_rgba(s_map.get("color").unwrap());
                    let mut covered = 0;

                    let shape = match s_type {
                        "rect" => Shape::Rect {
                            x: get_num(s_map.get("x").unwrap()),
                            y: get_num(s_map.get("y").unwrap()),
                            w: get_num(s_map.get("w").unwrap()),
                            h: get_num(s_map.get("h").unwrap()),
                            color,
                        },
                        "circle" => Shape::Circle {
                            cx: get_num(s_map.get("cx").unwrap()),
                            cy: get_num(s_map.get("cy").unwrap()),
                            r: get_num(s_map.get("r").unwrap()),
                            color,
                        },
                        "triangle" => {
                            let pts_json = s_map.get("points").unwrap();
                            if let JsonValue::Array(ref pts_arr) = pts_json {
                                let mut points = [(0, 0); 3];
                                for i in 0..3 {
                                    if let JsonValue::Array(ref pt) = pts_arr[i] {
                                        points[i] = (get_num(&pt[0]), get_num(&pt[1]));
                                    }
                                }
                                Shape::Triangle { points, color }
                            } else { unreachable!() }
                        },
                        "line" => Shape::Line {
                            x1: get_num(s_map.get("x1").unwrap()),
                            y1: get_num(s_map.get("y1").unwrap()),
                            x2: get_num(s_map.get("x2").unwrap()),
                            y2: get_num(s_map.get("y2").unwrap()),
                            r: get_num(s_map.get("r").unwrap()),
                            color,
                        },
                        _ => panic!("Unknown shape"),
                    };

                    for y in 0..height {
                        for x in 0..width {
                            let is_covered = match &shape {
                                Shape::Rect { x: rx, y: ry, w, h, .. } => {
                                    x >= *rx && x < *rx + *w && y >= *ry && y < *ry + *h
                                }
                                Shape::Circle { cx, cy, r, .. } => {
                                    (x - *cx).pow(2) + (y - *cy).pow(2) <= (*r).pow(2)
                                }
                                Shape::Triangle { points, .. } => {
                                    let mut signs = [0i64; 3];
                                    for i in 0..3 {
                                        let p1 = points[i];
                                        let p2 = points[(i + 1) % 3];
                                        signs[i] = (p2.0 - p1.0) * (y - p1.1) - (p2.1 - p1.1) * (x - p1.0);
                                    }
                                    (signs[0] >= 0 && signs[1] >= 0 && signs[2] >= 0) || (signs[0] <= 0 && signs[1] <= 0 && signs[2] <= 0)
                                }
                                Shape::Line { x1, y1, x2, y2, r, .. } => {
                                    let dx = *x2 - *x1;
                                    let dy = *y2 - *y1;
                                    let l_sq = dx * dx + dy * dy;
                                    let t = (x - *x1) * dx + (y - *y1) * dy;
                                    if t <= 0 {
                                        (x - *x1).pow(2) + (y - *y1).pow(2) <= (*r).pow(2)
                                    } else if t >= l_sq {
                                        (x - *x2).pow(2) + (y - *y2).pow(2) <= (*r).pow(2)
                                    } else {
                                        let c = (x - *x1) * dy - (y - *y1) * dx;
                                        c * c <= (*r).pow(2) * l_sq
                                    }
                                }
                            };

                            if is_covered {
                                covered += 1;
                                let idx = (y * width + x) as usize;
                                let d = canvas[idx];
                                let s = color;
                                let a = s[3] as i64;
                                canvas[idx] = [
                                    ((s[0] as i64 * a + d[0] as i64 * (255 - a) + 127) / 255) as u8,
                                    ((s[1] as i64 * a + d[1] as i64 * (255 - a) + 127) / 255) as u8,
                                    ((s[2] as i64 * a + d[2] as i64 * (255 - a) + 127) / 255) as u8,
                                ];
                                // Wait, canvas only needs 3 components.
                                // Corrected: the canvas is [u8; 3].
                            }
                        }
                    }
                    shape_counts.push((s_type.to_string(), covered));

                    // Update canvas colors
                    for y in 0..height {
                        for x in 0..width {
                            let is_covered = match &shape {
                                Shape::Rect { x: rx, y: ry, w, h, .. } => x >= *rx && x < *rx + *w && y >= *ry && y < *ry + *h,
                                Shape::Circle { cx, cy, r, .. } => (x - *cx).pow(2) + (y - *cy).pow(2) <= (*r).pow(2),
                                Shape::Triangle { points, .. } => {
                                    let mut signs = [0i64; 3];
                                    for i in 0..3 {
                                        let p1 = points[i];
                                        let p2 = points[(i + 1) % 3];
                                        signs[i] = (p2.0 - p1.0) * (y - p1.1) - (p2.1 - p1.1) * (x - p1.0);
                                    }
                                    (signs[0] >= 0 && signs[1] >= 0 && signs[2] >= 0) || (signs[0] <= 0 && signs[1] <= 0 && signs[2] <= 0)
                                },
                                Shape::Line { x1, y1, x2, y2, r, .. } => {
                                    let dx = *x2 - *x1;
                                    let dy = *y2 - *y1;
                                    let l_sq = dx * dx + dy * dy;
                                    let t = (x - *x1) * dx + (y - *y1) * dy;
                                    if t <= 0 { (x - *x1).pow(2) + (y - *y1).pow(2) <= (*r).pow(2) }
                                    else if t >= l_sq { (x - *x2).pow(2) + (y - *y2).pow(2) <= (*r).pow(2) }
                                    else { let c = (x - *x1) * dy - (y - *y1) * dx; c * c <= (*r).pow(2) * l_sq }
                                }
                            };
                            if is_covered {
                                let idx = (y * width + x) as usize;
                                let d = canvas[idx];
                                let s = color;
                                let a = s[3] as i64;
                                canvas[idx] = [
                                    ((s[0] as i64 * a + d[0] as i64 * (255 - a) + 127) / 255) as u8,
                                    ((s[1] as i64 * a + d[1] as i64 * (255 - a) + 127) / 255) as u8,
                                    ((s[2] as i64 * a + d[2] as i64 * (255 - a) + 127) / 255) as u8,
                                ];
                            }
                        }
                    }
                }
            }

            let mut unique_colors = HashSet::new();
            for &c in &canvas { unique_colors.insert(c); }

            for (i, (stype, count)) in shape_counts.iter().enumerate() {
                println!("{} {} {}", i + 1, stype, count);
            }
            println!("colors {}", unique_colors.len());

            // PNG Output
            let mut png_data = Vec::new();
            png_data.extend_from_slice(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

            fn write_chunk(data: &mut Vec<u8>, chunk_type: &[u8; 4], chunk_data: &[u8]) {
                let len = (chunk_data.len() as u32).to_be_bytes();
                data.extend_from_slice(&len);
                data.extend_from_slice(chunk_type);
                data.extend_from_slice(chunk_data);
                let mut crc = 0xFFFFFFFFu32;
                for &b in chunk_type.iter().chain(chunk_data.iter()) {
                    crc ^= b as u32;
                    for _ in 0..8 {
                        if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320; }
                        else { crc >>= 1; }
                    }
                }
                data.extend_from_slice(&(crc ^ 0xFFFFFFFF).to_be_bytes());
            }

            let mut ihdr = Vec::new();
            ihdr.extend_from_slice(&(width as u32).to_be_bytes());
            ihdr.extend_from_slice(&(height as u32).to_be_bytes());
            ihdr.push(8); ihdr.push(2); ihdr.push(0); ihdr.push(0); ihdr.push(0);
            write_chunk(&mut png_data, &[b'I', b'H', b'D', b'R'], &ihdr);

            let mut idat_raw = Vec::new();
            for y in 0..height {
                idat_raw.push(0); // filter 0
                for x in 0..width {
                    let c = canvas[(y * width + x) as usize];
                    idat_raw.extend_from_slice(&c);
                }
            }

            let mut zlib_data = Vec::new();
            zlib_data.extend_from_slice(&[0x78, 0x01]);

            let mut data_ptr = 0;
            while data_ptr < idat_raw.len() {
                let len = std::cmp::min(65535, idat_raw.len() - data_ptr);
                let is_final = data_ptr + len == idat_raw.len();

                let mut bw = BitWriter { out: Vec::new(), curr: 0, bits: 0 };
                bw.write_bit(is_final);
                bw.write_bit(false); // BTYPE 0
                bw.write_bit(false); // BTYPE 0
                bw.write_u16_le(len as u16);
                bw.write_u16_le(!(len as u16));
                for i in 0..len {
                    let b = idat_raw[data_ptr + i];
                    for j in 0..8 { bw.write_bit((b >> j) & 1 == 1); }
                }
                bw.flush();
                zlib_data.extend(bw.out);
                data_ptr += len;
            }

            let mut s1 = 1u32;
            let mut s2 = 0u32;
            for &b in &idat_raw {
                s1 = (s1 + b as u32) % 65521;
                s2 = (s2 + s1) % 65521;
            }
            let adler = (s2 << 16) | s1;
            zlib_data.extend_from_slice(&adler.to_be_bytes());
            write_chunk(&mut png_data, &[b'I', b'D', b'A', b'T'], &zlib_data);
            write_chunk(&mut png_data, &[b'I', b'E', b'N', b'D'], &[]);

            let mut out_file = File::create("out.png").unwrap();
            out_file.write_all(&png_data).unwrap();
        }
    }
}

struct BitWriter {
    out: Vec<u8>,
    curr: u8,
    bits: u8,
}

impl BitWriter {
    fn write_bit(&mut self, bit: bool) {
        if bit { self.curr |= 1 << (7 - self.bits); }
        self.bits += 1;
        if self.bits == 8 {
            self.out.push(self.curr);
            self.curr = 0;
            self.bits = 0;
        }
    }
    fn write_u16_le(&mut self, val: u16) {
        for i in 0..16 { self.write_bit((val >> i) & 1 == 1); }
    }
    fn flush(&mut self) {
        if self.bits > 0 { self.out.push(self.curr); }
    }
}

