}

struct BitWriter {
    out: Vec<u8>,
    curr: u8,
    bits: u8,
}

impl BitWriter {
    fn new() -> Self {
        BitWriter { out: Vec::new(), curr: 0, bits: 0 }
    }
    fn write_bit(&mut self, bit: bool) {
        if bit { self.curr |= 1 << self.bits; }
        self.bits += 1;
        if self.bits == 8 {
            self.out.push(self.curr);
            self.curr = 0;
            self.bits = 0;
        }
    }
    fn write_u16_le(&mut self, val: u16) {
        for i in 0..16 { self.write_bit((val >> i) & 1 == 1); }
    }
    fn write_byte(&mut self, byte: u8) {
        for i in 0..8 { self.write_bit((byte >> i) & 1 == 1); }
    }
    fn flush(&mut self) {
        if self.bits > 0 { self.out.push(self.curr); }
    }
}

