            let mut shape_counts = Vec::new();

            for shape_val in shapes_list {
                if let JsonValue::Object(ref s_map) = shape_val {
                    let s_type = if let JsonValue::String(ref t) = s_map.get("type").unwrap() { t.as_str() } else { "" };
                    let color = get_color_rgba(s_map.get("color").unwrap());

                    let shape = match s_type {
                        "rect" => Shape::Rect {
                            x: get_num(s_map.get("x").unwrap()),
                            y: get_num(s_map.get("y").unwrap()),
                            w: get_num(s_map.get("w").unwrap()),
                            h: get_num(s_map.get("h").unwrap()),
                            color,
                        },
                        "circle" => Shape::Circle {
                            cx: get_num(s_map.get("cx").unwrap()),
                            cy: get_num(s_map.get("cy").unwrap()),
                            r: get_num(s_map.get("r").unwrap()),
                            color,
                        },
                        "triangle" => {
                            let pts_json = s_map.get("points").unwrap();
                            if let JsonValue::Array(ref pts_arr) = pts_json {
                                let mut points = [(0, 0); 3];
                                for i in 0..3 {
                                    if let JsonValue::Array(ref pt) = pts_arr[i] {
                                        points[i] = (get_num(&pt[0]), get_num(&pt[1]));
                                    }
                                }
                                Shape::Triangle { points, color }
                            } else { unreachable!() }
                        },
                        "line" => Shape::Line {
                            x1: get_num(s_map.get("x1").unwrap()),
                            y1: get_num(s_map.get("y1").unwrap()),
                            x2: get_num(s_map.get("x2").unwrap()),
                            y2: get_num(s_map.get("y2").unwrap()),
                            r: get_num(s_map.get("r").unwrap()),
                            color,
                        },
                        _ => panic!("Unknown shape"),
                    };

                    let mut covered = 0;
                    for y in 0..height {
                        for x in 0..width {
                            let is_covered = match &shape {
                                Shape::Rect { x: rx, y: ry, w, h, .. } => {
                                    x >= *rx && x < *rx + *w && y >= *ry && y < *ry + *h
                                }
                                Shape::Circle { cx, cy, r, .. } => {
                                    (x - *cx).pow(2) + (y - *cy).pow(2) <= (*r).pow(2)
                                }
                                Shape::Triangle { points, .. } => {
                                    let mut signs = [0i64; 3];
                                    for i in 0..3 {
                                        let p1 = points[i];
                                        let p2 = points[(i + 1) % 3];
                                        signs[i] = (p2.0 - p1.0) * (y - p1.1) - (p2.1 - p1.1) * (x - p1.0);
                                    }
                                    (signs[0] >= 0 && signs[1] >= 0 && signs[2] >= 0) || (signs[0] <= 0 && signs[1] <= 0 && signs[2] <= 0)
                                }
                                Shape::Line { x1, y1, x2, y2, r, .. } => {
                                    let dx = *x2 - *x1;
                                    let dy = *y2 - *y1;
                                    let l_sq = dx * dx + dy * dy;
                                    let t = (x - *x1) * dx + (y - *y1) * dy;
                                    if t <= 0 {
                                        (x - *x1).pow(2) + (y - *y1).pow(2) <= (*r).pow(2)
                                    } else if t >= l_sq {
                                        (x - *x2).pow(2) + (y - *y2).pow(2) <= (*r).pow(2)
                                    } else {
                                        let c = (x - *x1) * dy - (y - *y1) * dx;
                                        c * c <= (*r).pow(2) * l_sq
                                    }
                                }
                            };

                            if is_covered {
                                covered += 1;
                                let idx = (y * width + x) as usize;
                                let d = canvas[idx];
                                let s = color;
                                let a = s[3] as i64;
                                canvas[idx] = [
                                    ((s[0] as i64 * a + d[0] as i64 * (255 - a) + 127) / 255) as u8,
                                    ((s[1] as i64 * a + d[1] as i64 * (255 - a) + 127) / 255) as u8,
                                    ((s[2] as i64 * a + d[2] as i64 * (255 - a) + 127) / 255) as u8,
                                ];
                            }
                        }
                    }
                    shape_counts.push((s_type.to_string(), covered));
                }
            }

            let mut unique_colors = HashSet::new();
            for &c in &canvas { unique_colors.insert(c); }

            for (i, (stype, count)) in shape_counts.iter().enumerate() {
                println!("{} {} {}", i + 1, stype, count);
            }
            println!("colors {}", unique_colors.len());

            let mut png_data = Vec::new();
            png_data.extend_from_slice(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

            fn write_chunk(data: &mut Vec<u8>, chunk_type: &[u8; 4], chunk_data: &[u8]) {
                let len = (chunk_data.len() as u32).to_be_bytes();
                data.extend_from_slice(&len);
                data.extend_from_slice(chunk_type);
                data.extend_from_slice(chunk_data);
                let mut crc = 0xFFFFFFFFu32;
                for &b in chunk_type.iter().chain(chunk_data.iter()) {
                    crc ^= b as u32;
                    for _ in 0..8 {
                        if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320; }
                        else { crc >>= 1; }
                    }
                }
                data.extend_from_slice(&(crc ^ 0xFFFFFFFF).to_be_bytes());
            }

            let mut ihdr = Vec::new();
            ihdr.extend_from_slice(&(width as u32).to_be_bytes());
            ihdr.extend_from_slice(&(height as u32).to_be_bytes());
            ihdr.push(8); ihdr.push(2); ihdr.push(0); ihdr.push(0); ihdr.push(0);
            write_chunk(&mut png_data, &[b'I', b'H', b'D', b'R'], &ihdr);

            let mut idat_raw = Vec::new();
            for y in 0..height {
                idat_raw.push(0);
                for x in 0..width {
                    let c = canvas[(y * width + x) as usize];
                    idat_raw.extend_from_slice(&c);
                }
            }

            let mut zlib_data = Vec::new();
            zlib_data.extend_from_slice(&[0x78, 0x01]);

            let mut data_ptr = 0;
            let mut bw = BitWriter::new();
            while data_ptr < idat_raw.len() {
                let len = std::cmp::min(65535, idat_raw.len() - data_ptr);
                let is_final = data_ptr + len == idat_raw.len();
                bw.write_bit(is_final);
                bw.write_bit(false);
                bw.write_bit(false);
                bw.write_u16_le(len as u16);
                bw.write_u16_le(!(len as u16));
                for i in 0..len {
                    bw.write_byte(idat_raw[data_ptr + i]);
                }
                data_ptr += len;
            }
            bw.flush();
            zlib_data.extend(bw.out);

            let mut s1 = 1u32;
            let mut s2 = 0u32;
            for &b in &idat_raw {
                s1 = (s1 + b as u32) % 65521;
                s2 = (s2 + s1) % 65521;
            }
            let adler = (s2 << 16) | s1;
            zlib_data.extend_from_slice(&adler.to_be_bytes());
            write_chunk(&mut png_data, &[b'I', b'D', b'A', b'T'], &zlib_data);
            write_chunk(&mut png_data, &[b'I', b'E', b'N', b'D'], &[]);

            let mut out_file = File::create("out.png").unwrap();
            out_file.write_all(&png_data).unwrap();
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

type FieldType = 'int32' | 'int64' | 'uint32' | 'uint64' | 'sint32' | 'sint64' | 'bool' | 'string' | 'bytes' | 'fixed32' | 'fixed64' | 'sfixed32' | 'sfixed64' | string;

interface Field {
    type: FieldType;
    name: string;
    number: number;
    label: 'singular' | 'repeated' | 'optional';
    oneofName?: string;
    isMap?: boolean;
    mapKeyType?: 'string' | 'int32';
}

interface Enum {
    name: string;
    values: { [name: string]: number; [number: number]: string };
}

interface Message {
    name: string;
    fields: { [number: number]: Field };
    oneofs: { [name: string]: number[] };
}

class ProtoParser {
    private tokens: string[] = [];
    private pos = 0;

    constructor(input: string) {
        this.tokens = this.tokenize(input);
    }

    private tokenize(input: string): string[] {
        const tokens: string[] = [];
        let i = 0;
        while (i < input.length) {
            if (input[i] === '/' && input[i + 1] === '/') {
                while (i < input.length && input[i] !== '\n') i++;
            } else if (input[i] === '/' && input[i + 1] === '*') {
                i += 2;
                while (i < input.length && !(input[i] === '*' && input[i + 1] === '/')) i++;
                i += 2;
            } else if (/\s/.test(input[i])) {
                i++;
            } else if (input[i] === '"') {
                let str = '"';
                i++;
                while (i < input.length && input[i] !== '"') str += input[i++];
                str += '"';
                i++;
                tokens.push(str);
            } else if (/[a-zA-Z_]/.test(input[i])) {
                let id = '';
                while (i < input.length && /[a-zA-Z0-9_]/.test(input[i])) id += input[i++];
                tokens.push(id);
            } else if (/[0-9-]/.test(input[i])) {
                let num = '';
                while (i < input.length && /[0-9.\- ]/.test(input[i])) {
                    if (input[i] === ' ') break;
                    num += input[i++];
                }
                tokens.push(num);
            } else {
                tokens.push(input[i++]);
            }
        }
        return tokens;
    }

    private peek() { return this.tokens[this.pos]; }
    private next() { return this.tokens[this.pos++]; }

    parse(): { messages: Map<string, Message>; enums: Map<string, Enum>; rootType: string } {
        const messages = new Map<string, Message>();
        const enums = new Map<string, Enum>();
        let rootType = '';

        while (this.pos < this.tokens.length) {
            const token = this.next();
            if (token === 'syntax' || token === 'package' || token === 'option') {
                while (this.next() !== ';') { if (this.peek() === ';') break; }
            } else if (token === 'message') {
                const name = this.next();
                if (rootType === '') rootType = name;
                const msg = this.parseMessage(name, messages, enums);
                messages.set(name, msg);
            } else if (token === 'enum') {
                const name = this.next();
                const en = this.parseEnum(name);
                enums.set(name, en);
            }
        }
        return { messages, enums, rootType };
    }

    private parseMessage(name: string, messages: Map<string, Message>, enums: Map<string, Enum>): Message {
        const msg: Message = { name, fields: {}, oneofs: {} };
        this.next(); // {
        while (this.peek() !== '}') {
            const token = this.next();
            if (token === 'message') {
                const nestedName = this.next();
                const nestedMsg = this.parseMessage(nestedName, messages, enums);
                messages.set(nestedName, nestedMsg);
            } else if (token === 'enum') {
                const nestedName = this.next();
                const nestedEnum = this.parseEnum(nestedName);
                enums.set(nestedName, nestedEnum);
            } else if (token === 'oneof') {
                const oneofName = this.next();
                this.next(); // {
                while (this.peek() !== '}') {
                    const field = this.parseField(oneofName);
                    msg.fields[field.number] = field;
                    if (!msg.oneofs[oneofName]) msg.oneofs[oneofName] = [];
                    msg.oneofs[oneofName].push(field.number);
                }
                this.next(); // }
            } else if (token === 'reserved') {
                while (this.peek() !== ';') this.next();
                this.next(); // ;
            } else if (token === 'option') {
                while (this.peek() !== ';') this.next();
                this.next(); // ;
            } else {
                // field
                let label: 'singular' | 'repeated' | 'optional' = 'singular';
                let currentToken = token;
                if (currentToken === 'repeated') {
                    label = 'repeated';
                    currentToken = this.next();
                } else if (currentToken === 'optional') {
                    label = 'optional';
                    currentToken = this.next();
                }

                let field: Field;
                if (currentToken === 'map') {
                    this.next(); // <
                    const keyType = this.next() as 'string' | 'int32';
                    this.next(); // ,
                    const valType = this.next();
                    this.next(); // >
                    const fieldName = this.next();
                    this.next(); // =
                    const fieldNum = parseInt(this.next());
                    field = { type: valType, name: fieldName, number: fieldNum, label: 'repeated', isMap: true, mapKeyType: keyType };
                } else {
                    const type = currentToken;
                    const fieldName = this.next();
                    this.next(); // =
                    const fieldNum = parseInt(this.next());
                    field = { type, name: fieldName, number: fieldNum, label };
                }

                if (this.peek() === '[') {
                    this.next(); // [
                    while (this.peek() !== ']') this.next();
                    this.next(); // ]
                }
                if (this.peek() === ';') this.next();
                msg.fields[field.number] = field;
            }
        }
        this.next(); // }
        return msg;
    }

    private parseField(oneofName: string): Field {
        const type = this.next();
        const name = this.next();
        this.next(); // =
        const number = parseInt(this.next());
        if (this.peek() === '[') {
            this.next(); // [
            while (this.peek() !== ']') this.next();
            this.next(); // ]
        }
        if (this.peek() === ';') this.next();
        return { type, name, number, label: 'singular', oneofName };
    }

    private parseEnum(name: string): Enum {
        const en: Enum = { name, values: {} };
        this.next(); // {
        while (this.peek() !== '}') {
            const valName = this.next();
            this.next(); // =
            const valNum = parseInt(this.next());
            if (this.peek() === ';') this.next();
            en.values[valName] = valNum;
            en.values[valNum] = valName;
        }
        this.next(); // }
        return en;
    }
}

class ProtoDecoder {
    private buffer: Buffer;
    private pos = 0;

    constructor(buffer: Buffer) {
        this.buffer = buffer;
    }

    private readVarint(): bigint {
        let result = 0n;
        let shift = 0n;
        while (true) {
            const byte = this.buffer[this.pos++];
            result |= BigInt(byte & 0x7f) << shift;
            if (!(byte & 0x80)) break;
            shift += 7n;
        }
        return result;
    }

    private readFixed32(): number {
        const val = this.buffer.readUInt32LE(this.pos);
        this.pos += 4;
        return val;
    }

    private readFixed64(): bigint {
        const val = this.buffer.readBigUInt64LE(this.pos);
        this.pos += 8;
        return val;
    }

    decodeMessage(schema: Map<string, Message>, msgType: string, limit: number): any {
        const msgSchema = schema.get(msgType)!;
        const result: any = {};
        const seenFields = new Set<number>();

        while (this.pos < limit) {
            const key = Number(this.readVarint());
            const wireType = key & 0x07;
            const fieldNum = key >> 3;
            const field = msgSchema.fields[fieldNum];

            if (!field) {
                if (wireType === 3) {
                    const groupNum = fieldNum;
                    while (true) {
                        const gKey = Number(this.readVarint());
                        if ((gKey & 0x07) === 4 && (gKey >> 3) === groupNum) break;
                        // We can't actually decode unknown groups properly without knowing their schema,
                        // but the prompt says we can skip them. We must process them to find the end group.
                        // Since we don't know the types, we just skip based on wire type.
                        this.skipField(gKey & 0x07, gKey >> 3, schema);
                    }
                } else {
                    this.skipField(wireType, fieldNum, schema);
                }
                continue;
            }

            const value = this.decodeValue(field, schema);
            if (field.label === 'repeated') {
                if (!result[fieldNum]) result[fieldNum] = [];
                if (field.isMap) {
                    const mapValue = value;
                    if (!result[fieldNum]) result[fieldNum] = {};
                    const map = result[fieldNum];
                    const key = mapValue[1] ?? (field.mapKeyType === 'string' ? '' : 0);
                    const val = mapValue[2] ?? this.getDefaultValue(field.type, schema);
                    map[key] = val;
                } else {
                    (result[fieldNum] as any[]).push(value);
                }
            } else {
                if (field.oneofName) {
                    const oneofFields = msgSchema.oneofs[field.oneofName];
                    oneofFields.forEach(fNum => delete result[fNum]);
                }
                if (field.type.startsWith('message') || schema.has(field.type)) {
                    if (result[fieldNum]) {
                        result[fieldNum] = this.mergeMessages(result[fieldNum], value, schema, field.type);
                    } else {
                        result[fieldNum] = value;
                    }
                } else {
                    result[fieldNum] = value;
                }
            }
            seenFields.add(fieldNum);
        }
        return result;
    }

    private skipField(wireType: number, fieldNum: number, schema: Map<string, Message>) {
        if (wireType === 0) this.readVarint();
        else if (wireType === 1) this.pos += 8;
        else if (wireType === 2) {
            const len = Number(this.readVarint());
            this.pos += len;
        } else if (wireType === 5) this.pos += 4;
    }

    private decodeValue(field: Field, schema: Map<string, Message>): any {
        const wireType = (this.buffer[this.pos] & 0x07) >> 0; // This is not correct, key was already read.
        // The key was already read in decodeMessage. We need to pass the wireType.
        // Let's refactor decodeMessage to pass wireType to decodeValue.
        return null; // Placeholder
    }

    private mergeMessages(oldMsg: any, newMsg: any, schema: Map<string, Message>, type: string): any {
        const msgSchema = schema.get(type)!;
        const merged = { ...oldMsg };
        for (const fieldNum in newMsg) {
            const fNum = parseInt(fieldNum);
            const field = msgSchema.fields[fNum];
            if (!field) continue;
            if (field.label === 'repeated') {
                if (field.isMap) {
                    merged[fNum] = { ...merged[fNum], ...newMsg[fNum] };
                } else {
                    merged[fNum] = [...(merged[fNum] || []), ...newMsg[fNum]];
                }
            } else if (field.type.startsWith('message') || schema.has(field.type)) {
                merged[fNum] = this.mergeMessages(merged[fNum] || {}, newMsg[fNum], schema, field.type);
            } else {
                merged[fNum] = newMsg[fNum];
            }
        }
        return merged;
    }

    private getDefaultValue(type: string, schema: Map<string, Message>): any {
        if (type === 'string') return '';
        if (type === 'bytes') return Buffer.alloc(0);
        if (type === 'bool') return false;
        if (type === 'int32' || type === 'uint32' || type === 'sint32' || type === 'fixed32' || type === 'sfixed32') return 0;
        if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return 0n;
        if (schema.has(type)) return {};
        return 0;
    }
}

// The above ProtoDecoder was a bit fragmented. Let's rewrite the decoding logic more cleanly.

function decodeVarint(buf: Buffer, pos: { val: number }): bigint {
    let result = 0n;
    let shift = 0n;
    while (true) {
        const byte = buf[pos.val++];
        result |= BigInt(byte & 0x7f) << shift;
        if (!(byte & 0x80)) break;
        shift += 7n;
    }
    return result;
}

function zigzagDecode(n: bigint): bigint {
    return (n >> 1n) ^ (n & 1n ? -1n : 0n);
}

function decodeMessage(buf: Buffer, pos: { val: number }, schema: Map<string, Message>, msgType: string): any {
    const msgSchema = schema.get(msgType)!;
    const result: any = {};
    const limit = pos.val; // This is not quite right, the length is passed from the record.
    // Let's assume the caller handles the limit.
    return result;
}

function decodeValue(buf: Buffer, pos: { val: number }, wireType: number, field: Field, schema: Map<string, Message>, limit: number): any {
    if (wireType === 0) {
        const val = decodeVarint(buf, pos);
        if (field.type === 'bool') return !!val;
        if (field.type === 'sint32') return Number(zigzagDecode(val));
        if (field.type === 'sint64') return zigzagDecode(val);
        if (field.type === 'int32') return Number(BigInt.asIntN(32, val));
        if (field.type === 'uint32') return Number(BigInt.asUintN(32, val));
        if (field.type === 'int64' || field.type === 'uint64') return val;
        // Enum
        return val;
    } else if (wireType === 1) {
        const val = buf.readBigInt64LE(pos.val);
        pos.val += 8;
        return val;
    } else if (wireType === 2) {
        const len = Number(decodeVarint(buf, pos));
        const data = buf.slice(pos.val, pos.val + len);
        pos.val += len;
        if (field.type === 'string') return data.toString('utf8');
        if (field.type === 'bytes') return data;
        if (schema.has(field.type)) {
            return decodeMessageInternal(data, schema, field.type);
        }
        // Packed repeated
        return data;
    } else if (wireType === 5) {
        const val = buf.readInt32LE(pos.val);
        pos.val += 4;
        return val;
    }
    return null;
}

function decodeMessageInternal(buf: Buffer, schema: Map<string, Message>, msgType: string): any {
    const msgSchema = schema.get(msgType)!;
    const result: any = {};
    const pos = { val: 0 };
    while (pos.val < buf.length) {
        const key = Number(decodeVarint(buf, pos));
        const wireType = key & 0x07;
        const fieldNum = key >> 3;
        const field = msgSchema.fields[fieldNum];

        if (!field) {
            if (wireType === 3) {
                while (true) {
                    const gKey = Number(decodeVarint(buf, pos));
                    if ((gKey & 0x07) === 4 && (gKey >> 3) === fieldNum) break;
                    // Skip unknown field inside group
                    const gWire = gKey & 0x07;
                    if (gWire === 0) decodeVarint(buf, pos);
                    else if (gWire === 1) pos.val += 8;
                    else if (gWire === 2) {
                        const len = Number(decodeVarint(buf, pos));
                        pos.val += len;
                    } else if (gWire === 5) pos.val += 4;
                }
            } else {
                if (wireType === 0) decodeVarint(buf, pos);
                else if (wireType === 1) pos.val += 8;
                else if (wireType === 2) {
                    const len = Number(decodeVarint(buf, pos));
                    pos.val += len;
                } else if (wireType === 5) pos.val += 4;
            }
            continue;
        }

        let val: any;
        if (wireType === 0) {
            const v = decodeVarint(buf, pos);
            if (field.type === 'bool') val = !!v;
            else if (field.type === 'sint32') val = Number(zigzagDecode(v));
            else if (field.type === 'sint64') val = zigzagDecode(v);
            else if (field.type === 'int32') val = Number(BigInt.asIntN(32, v));
            else if (field.type === 'uint32') val = Number(BigInt.asUintN(32, v));
            else val = v;
        } else if (wireType === 1) {
            val = buf.readBigInt64LE(pos.val);
            pos.val += 8;
        } else if (wireType === 2) {
            const len = Number(decodeVarint(buf, pos));
            const data = buf.slice(pos.val, pos.val + len);
            pos.val += len;
            if (field.type === 'string') val = data.toString('utf8');
            else if (field.type === 'bytes') val = data;
            else if (schema.has(field.type)) val = decodeMessageInternal(data, schema, field.type);
            else {
                // Packed repeated
                const packedVals: any[] = [];
                const pPos = { val: 0 };
                const pBuf = data;
                while (pPos.val < pBuf.length) {
                    const pv = decodeVarint(pBuf, pPos);
                    if (field.type === 'bool') packedVals.push(!!pv);
                    else if (field.type === 'sint32') packedVals.push(Number(zigzagDecode(pv)));
                    else if (field.type === 'sint64') packedVals.push(zigzagDecode(pv));
                    else if (field.type === 'int32') packedVals.push(Number(BigInt.asIntN(32, pv)));
                    else if (field.type === 'uint32') packedVals.push(Number(BigInt.asUintN(32, pv)));
                    else packedVals.push(pv);
                }
                val = packedVals;
            }
        } else if (wireType === 5) {
            val = buf.readInt32LE(pos.val);
            pos.val += 4;
        }

        if (field.label === 'repeated') {
            if (field.isMap) {
                if (!result[fieldNum]) result[fieldNum] = {};
                const map = result[fieldNum];
                const entry = decodeMessageInternal(val as Buffer, schema, 'MapEntry_' + field.name); // Special map entry
                // Map entries are just messages with field 1 and 2.
                // But we don't have a MapEntry schema. Let's manually decode.
                const entryPos = { val: 0 };
                const entryBuf = val as Buffer;
                let eKey: any, eVal: any;
                while (entryPos.val < entryBuf.length) {
                    const ek = Number(decodeVarint(entryBuf, entryPos));
                    const ew = ek & 0x07;
                    const ef = ek >> 3;
                    if (ef === 1) {
                        eKey = decodeValueManual(entryBuf, entryPos, ew, field.mapKeyType!, schema);
                    } else if (ef === 2) {
                        eVal = decodeValueManual(entryBuf, entryPos, ew, field.type, schema);
                    } else {
                        // skip
                        if (ew === 0) decodeVarint(entryBuf, entryPos);
                        else if (ew === 1) entryPos.val += 8;
                        else if (ew === 2) { const l = Number(decodeVarint(entryBuf, entryPos)); entryPos.val += l; }
                        else if (ew === 5) entryPos.val += 4;
                    }
                }
                const finalKey = eKey ?? (field.mapKeyType === 'string' ? '' : 0);
                const finalVal = eVal ?? getDefaultValueManual(field.type, schema);
                map[finalKey] = finalVal;
            } else {
                if (!result[fieldNum]) result[fieldNum] = [];
                if (Array.isArray(val)) result[fieldNum].push(...val);
                else result[fieldNum].push(val);
            }
        } else {
            if (field.oneofName) {
                const oneofFields = msgSchema.oneofs[field.oneofName];
                oneofFields.forEach(fNum => delete result[fNum]);
            }
            if (schema.has(field.type)) {
                if (result[fieldNum]) {
                    result[fieldNum] = mergeMessagesInternal(result[fieldNum], val, schema, field.type);
                } else {
                    result[fieldNum] = val;
                }
            } else {
                result[fieldNum] = val;
            }
        }
    }
    return result;
}

function decodeValueManual(buf: Buffer, pos: { val: number }, wireType: number, type: string, schema: Map<string, Message>): any {
    if (wireType === 0) {
        const v = decodeVarint(buf, pos);
        if (type === 'bool') return !!v;
        if (type === 'sint32') return Number(zigzagDecode(v));
        if (type === 'sint64') return zigzagDecode(v);
        if (type === 'int32') return Number(BigInt.asIntN(32, v));
        if (type === 'uint32') return Number(BigInt.asUintN(32, v));
        return v;
    } else if (wireType === 1) {
        const v = buf.readBigInt64LE(pos.val);
        pos.val += 8;
        return v;
    } else if (wireType === 2) {
        const len = Number(decodeVarint(buf, pos));
        const data = buf.slice(pos.val, pos.val + len);
        pos.val += len;
        if (type === 'string') return data.toString('utf8');
        if (type === 'bytes') return data;
        if (schema.has(type)) return decodeMessageInternal(data, schema, type);
        return data;
    } else if (wireType === 5) {
        const v = buf.readInt32LE(pos.val);
        pos.val += 4;
        return v;
    }
    return null;
}

function getDefaultValueManual(type: string, schema: Map<string, Message>): any {
    if (type === 'string') return '';
    if (type === 'bytes') return Buffer.alloc(0);
    if (type === 'bool') return false;
    if (type === 'int32' || type === 'uint32' || type === 'sint32' || type === 'fixed32' || type === 'sfixed32') return 0;
    if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return 0n;
    if (schema.has(type)) return {};
    return 0;
}

function mergeMessagesInternal(oldMsg: any, newMsg: any, schema: Map<string, Message>, type: string): any {
    const msgSchema = schema.get(type)!;
    const merged = { ...oldMsg };
    for (const fieldNum in newMsg) {
        const fNum = parseInt(fieldNum);
        const field = msgSchema.fields[fNum];
        if (!field) continue;
        if (field.label === 'repeated') {
            if (field.isMap) {
                merged[fNum] = { ...merged[fNum], ...newMsg[fNum] };
            } else {
                merged[fNum] = [...(merged[fNum] || []), ...newMsg[fNum]];
            }
        } else if (schema.has(field.type)) {
            merged[fNum] = mergeMessagesInternal(merged[fNum] || {}, newMsg[fNum], schema, field.type);
        } else {
            merged[fNum] = newMsg[fNum];
        }
    }
    return merged;
}

function camelCase(s: string): string {
    return s.replace(/_([a-z])/g, (_, char) => char.toUpperCase());
}

function escapeString(s: string): string {
    let res = '';
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (c === '"') res += '\\"';
        else if (c === '\\') res += '\\\\';
        else if (c === '\b') res += '\\b';
        else if (c === '\t') res += '\\t';
        else if (c === '\n') res += '\\n';
        else if (c === '\f') res += '\\f';
        else if (c === '\r') res += '\\r';
        else if (c.charCodeAt(0) < 0x20) {
            res += '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0').toLowerCase();
        } else {
            res += c;
        }
    }
    return res;
}

function formatValue(val: any, field: Field, schema: Map<string, Message>, enums: Map<string, Enum>): any {
    if (field.type === 'int64' || field.type === 'uint64' || field.type === 'sint64' || field.type === 'fixed64' || field.type === 'sfixed64') {
        return `"${val.toString()}"`;
    }
    if (field.type === 'bool') return val ? 'true' : 'false';
    if (field.type === 'string') return `"${escapeString(val)}"`;
    if (field.type === 'bytes') return `"${val.toString('base64')}"`;
    if (enums.has(field.type)) {
        const en = enums.get(field.type)!;
        const name = en.values[Number(val)];
        return name ? `"${name}"` : Number(val);
    }
    if (schema.has(field.type)) {
        const msgSchema = schema.get(field.type)!;
        const fields = Object.keys(val).map(Number).sort((a, b) => a - b);
        const parts = fields.map(fNum => {
            const f = msgSchema.fields[fNum];
            if (!f) return null;
            const fVal = formatValue(val[fNum], f, schema, enums);
            return `"${camelCase(f.name)}":${fVal}`;
        }).filter(p => p !== null);
        return `{${parts.join(',')}}`;
    }
    return val;
}

function formatMessage(val: any, msgSchema: Message, schema: Map<string, Message>, enums: Map<string, Enum>): string {
    const fieldNums = Object.keys(val).map(Number).sort((a, b) => a - b);
    const parts: string[] = [];
    for (const fNum of fieldNums) {
        const field = msgSchema.fields[fNum];
        if (!field) continue;

        const fVal = val[fNum];
        if (field.label === 'repeated') {
            if (field.isMap) {
                const mapKeys = Object.keys(fVal).sort((a, b) => {
                    if (field.mapKeyType === 'int32') return parseInt(a) - parseInt(b);
                    return a < b ? -1 : (a > b ? 1 : 0);
                });
                if (mapKeys.length === 0) continue;
                const mapParts = mapKeys.map(k => {
                    const v = fVal[k];
                    const vField: Field = { type: field.type, name: '', number: 0, label: 'singular' };
                    return `"${escapeString(k)}":${formatValue(v, vField, schema, enums)}`;
                });
                parts.push(`"${camelCase(field.name)}":{${mapParts.join(',')}}`);
            } else {
                if (fVal.length === 0) continue;
                const arrayParts = fVal.map(v => {
                    const vField: Field = { ...field, label: 'singular' };
                    return formatValue(v, vField, schema, enums);
                });
                parts.push(`"${camelCase(field.name)}":[${arrayParts.join(',')}]`);
            }
        } else {
            const defVal = getDefaultValueManual(field.type, schema);
            const isDefault = (val[fNum] === defVal);
            if (isDefault && field.label !== 'optional' && !field.oneofName) continue;

            const fValFormatted = formatValue(val[fNum], field, schema, enums);
            parts.push(`"${camelCase(field.name)}":${fValFormatted}`);
        }
    }
    return `{${parts.join(',')}}`;
}

async function main() {
    const dir = process.argv[2];
    if (!dir) return;
    const protoContent = fs.readFileSync(path.join(dir, 'schema.proto'), 'utf8');
    const binContent = fs.readFileSync(path.join(dir, 'messages.bin'));

    const parser = new ProtoParser(protoContent);
    const { messages, enums, rootType } = parser.parse();

    const pos = { val: 0 };
    while (pos.val < binContent.length) {
        const len = Number(decodeVarint(binContent, pos));
        const recordBuf = binContent.slice(pos.val, pos.val + len);
        pos.val += len;
        const decoded = decodeMessageInternal(recordBuf, messages, rootType);
        process.stdout.write(formatMessage(decoded, messages.get(rootType)!, messages, enums) + '\n');
    }
}

main();

import * as fs from 'fs';
import * as path from 'path';

type FieldType = 'int32' | 'int64' | 'uint32' | 'uint64' | 'sint32' | 'sint64' | 'bool' | 'string' | 'bytes' | 'fixed32' | 'fixed64' | 'sfixed32' | 'sfixed64' | string;

interface Field {
    type: FieldType;
    name: string;
    number: number;
    label: 'singular' | 'repeated' | 'optional';
    oneofName?: string;
    isMap?: boolean;
    mapKeyType?: 'string' | 'int32';
}

interface Enum {
    name: string;
    values: Map<number, string>;
}

interface Message {
    name: string;
    fields: Map<number, Field>;
    oneofs: Map<string, number[]>;
}

class ProtoParser {
    private tokens: string[] = [];
    private pos = 0;

    constructor(input: string) {
        this.tokens = this.tokenize(input);
    }

    private tokenize(input: string): string[] {
        const tokens: string[] = [];
        let i = 0;
        while (i < input.length) {
            if (input[i] === '/' && input[i + 1] === '/') {
                while (i < input.length && input[i] !== '\n') i++;
            } else if (input[i] === '/' && input[i + 1] === '*') {
                i += 2;
                while (i < input.length && !(input[i] === '*' && input[i + 1] === '/')) i++;
                i += 2;
            } else if (/\s/.test(input[i])) {
                i++;
            } else if (input[i] === '"') {
                let str = '"';
                i++;
                while (i < input.length && input[i] !== '"') str += input[i++];
                str += '"';
                i++;
                tokens.push(str);
            } else if (/[a-zA-Z_]/.test(input[i])) {
                let id = '';
                while (i < input.length && /[a-zA-Z0-9_]/.test(input[i])) id += input[i++];
                tokens.push(id);
            } else if (/[0-9-]/.test(input[i])) {
                let num = '';
                while (i < input.length && /[0-9.\- ]/.test(input[i])) {
                    if (input[i] === ' ') break;
                    num += input[i++];
                }
                tokens.push(num);
            } else {
                tokens.push(input[i++]);
            }
        }
        return tokens;
    }

    private peek() { return this.tokens[this.pos]; }
    private next() { return this.tokens[this.pos++]; }

    parse(): { messages: Map<string, Message>; enums: Map<string, Enum>; rootType: string } {
        const messages = new Map<string, Message>();
        const enums = new Map<string, Enum>();
        let rootType = '';

        while (this.pos < this.tokens.length) {
            const token = this.next();
            if (token === 'syntax' || token === 'package' || token === 'option') {
                while (this.peek() !== ';' && this.pos < this.tokens.length) this.next();
                this.next(); // ;
            } else if (token === 'message') {
                const name = this.next();
                if (rootType === '') rootType = name;
                const msg = this.parseMessage(name, messages, enums);
                messages.set(name, msg);
            } else if (token === 'enum') {
                const name = this.next();
                const en = this.parseEnum(name);
                enums.set(name, en);
            }
        }
        return { messages, enums, rootType };
    }

    private parseMessage(name: string, messages: Map<string, Message>, enums: Map<string, Enum>): Message {
        const msg: Message = { name, fields: new Map(), oneofs: new Map() };
        this.next(); // {
        while (this.peek() !== '}' && this.pos < this.tokens.length) {
            const token = this.next();
            if (token === 'message') {
                const nestedName = this.next();
                const nestedMsg = this.parseMessage(nestedName, messages, enums);
                messages.set(nestedName, nestedMsg);
            } else if (token === 'enum') {
                const nestedName = this.next();
                const nestedEnum = this.parseEnum(nestedName);
                enums.set(nestedName, nestedEnum);
            } else if (token === 'oneof') {
                const oneofName = this.next();
                this.next(); // {
                while (this.peek() !== '}') {
                    const field = this.parseField(oneofName);
                    msg.fields.set(field.number, field);
                    if (!msg.oneofs.has(oneofName)) msg.oneofs.set(oneofName, []);
                    msg.oneofs.get(oneofName)!.push(field.number);
                }
                this.next(); // }
            } else if (token === 'reserved') {
                while (this.peek() !== ';') this.next();
                this.next(); // ;
            } else if (token === 'option') {
                while (this.peek() !== ';') this.next();
                this.next(); // ;
            } else {
                let label: 'singular' | 'repeated' | 'optional' = 'singular';
                let currentToken = token;
                if (currentToken === 'repeated') {
                    label = 'repeated';
                    currentToken = this.next();
                } else if (currentToken === 'optional') {
                    label = 'optional';
                    currentToken = this.next();
                }

                let field: Field;
                if (currentToken === 'map') {
                    this.next(); // <
                    const keyType = this.next() as 'string' | 'int32';
                    this.next(); // ,
                    const valType = this.next();
                    this.next(); // >
                    const fieldName = this.next();
                    this.next(); // =
                    const fieldNum = parseInt(this.next());
                    field = { type: valType, name: fieldName, number: fieldNum, label: 'repeated', isMap: true, mapKeyType: keyType };
                } else {
                    const type = currentToken;
                    const fieldName = this.next();
                    this.next(); // =
                    const fieldNum = parseInt(this.next());
                    field = { type, name: fieldName, number: fieldNum, label };
                }
                if (this.peek() === '[') {
                    this.next(); // [
                    while (this.peek() !== ']') this.next();
                    this.next(); // ]
                }
                if (this.peek() === ';') this.next();
                msg.fields.set(field.number, field);
            }
        }
        this.next(); // }
        return msg;
    }

    private parseField(oneofName: string): Field {
        const type = this.next();
        const name = this.next();
        this.next(); // =
        const number = parseInt(this.next());
        if (this.peek() === '[') {
            this.next(); // [
            while (this.peek() !== ']') this.next();
            this.next(); // ]
        }
        if (this.peek() === ';') this.next();
        return { type, name, number, label: 'singular', oneofName };
    }

    private parseEnum(name: string): Enum {
        const en: Enum = { name, values: new Map() };
        this.next(); // {
        while (this.peek() !== '}' && this.pos < this.tokens.length) {
            const valName = this.next();
            this.next(); // =
            const valNum = parseInt(this.next());
            if (this.peek() === ';') this.next();
            en.values.set(valNum, valName);
        }
        this.next(); // }
        return en;
    }
}

function readVarint(buf: Buffer, pos: { val: number }): bigint {
    let result = 0n;
    let shift = 0n;
    while (true) {
        const byte = buf[pos.val++];
        result |= BigInt(byte & 0x7f) << shift;
        if (!(byte & 0x80)) break;
        shift += 7n;
    }
    return result;
}

function zigzagDecode(n: bigint): bigint {
    return (n >> 1n) ^ (n & 1n ? -1n : 0n);
}

function decodeValue(buf: Buffer, pos: { val: number }, wireType: number, field: Field, schema: Map<string, Message>): any {
    if (wireType === 0) {
        const v = readVarint(buf, pos);
        if (field.type === 'bool') return !!v;
        if (field.type === 'sint32') return Number(zigzagDecode(v));
        if (field.type === 'sint64') return zigzagDecode(v);
        if (field.type === 'int32') return Number(BigInt.asIntN(32, v));
        if (field.type === 'uint32') return Number(BigInt.asUintN(32, v));
        if (field.type === 'int64') return BigInt.asIntN(64, v);
        if (field.type === 'uint64') return BigInt.asUintN(64, v);
        return v;
    } else if (wireType === 1) {
        const v = buf.readBigInt64LE(pos.val);
        pos.val += 8;
        if (field.type === 'sfixed64') return BigInt.asIntN(64, v);
        if (field.type === 'fixed64') return BigInt.asUintN(64, v);
        return v;
    } else if (wireType === 2) {
        const len = Number(readVarint(buf, pos));
        const data = buf.slice(pos.val, pos.val + len);
        pos.val += len;
        if (field.type === 'string') return data.toString('utf8');
        if (field.type === 'bytes') return data;
        if (schema.has(field.type)) return decodeMessageInternal(data, schema, field.type);
        return data;
    } else if (wireType === 5) {
        const v = buf.readInt32LE(pos.val);
        pos.val += 4;
        if (field.type === 'sfixed32') return Number(v);
        if (field.type === 'fixed32') return Number(buf.readUInt32LE(pos.val - 4));
        return Number(v);
    }
    return null;
}

function decodeMessageInternal(buf: Buffer, schema: Map<string, Message>, msgType: string): any {
    const msgSchema = schema.get(msgType)!;
    const result: any = {};
    const presence = new Set<number>();
    const pos = { val: 0 };

    while (pos.val < buf.length) {
        const key = Number(readVarint(buf, pos));
        const wireType = key & 0x07;
        const fieldNum = key >> 3;
        const field = msgSchema.fields.get(fieldNum);

        if (!field) {
            if (wireType === 3) {
                while (true) {
                    const gKey = Number(readVarint(buf, pos));
                    if ((gKey & 0x07) === 4 && (gKey >> 3) === fieldNum) break;
                    const gWire = gKey & 0x07;
                    if (gWire === 0) readVarint(buf, pos);
                    else if (gWire === 1) pos.val += 8;
                    else if (gWire === 2) { const l = Number(readVarint(buf, pos)); pos.val += l; }
                    else if (gWire === 5) pos.val += 4;
                }
            } else {
                if (wireType === 0) readVarint(buf, pos);
                else if (wireType === 1) pos.val += 8;
                else if (wireType === 2) { const l = Number(readVarint(buf, pos)); pos.val += l; }
                else if (wireType === 5) pos.val += 4;
            }
            continue;
        }

        let val: any;
        if (wireType === 0) {
            const v = readVarint(buf, pos);
            if (field.type === 'bool') val = !!v;
            else if (field.type === 'sint32') val = Number(zigzagDecode(v));
            else if (field.type === 'sint64') val = zigzagDecode(v);
            else if (field.type === 'int32') val = Number(BigInt.asIntN(32, v));
            else if (field.type === 'uint32') val = Number(BigInt.asUintN(32, v));
            else if (field.type === 'int64') val = BigInt.asIntN(64, v);
            else if (field.type === 'uint64') val = BigInt.asUintN(64, v);
            else val = v;
        } else if (wireType === 1) {
            val = buf.readBigInt64LE(pos.val);
            pos.val += 8;
            if (field.type === 'sfixed64') val = BigInt.asIntN(64, val);
            else if (field.type === 'fixed64') val = BigInt.asUintN(64, val);
        } else if (wireType === 2) {
            const len = Number(readVarint(buf, pos));
            const data = buf.slice(pos.val, pos.val + len);
            pos.val += len;
            if (field.type === 'string') val = data.toString('utf8');
            else if (field.type === 'bytes') val = data;
            else if (schema.has(field.type)) val = decodeMessageInternal(data, schema, field.type);
            else {
                const packedVals: any[] = [];
                const pPos = { val: 0 };
                while (pPos.val < data.length) {
                    const pv = readVarint(data, pPos);
                    if (field.type === 'bool') packedVals.push(!!pv);
                    else if (field.type === 'sint32') packedVals.push(Number(zigzagDecode(pv)));
                    else if (field.type === 'sint64') packedVals.push(zigzagDecode(pv));
                    else if (field.type === 'int32') packedVals.push(Number(BigInt.asIntN(32, pv)));
                    else if (field.type === 'uint32') packedVals.push(Number(BigInt.asUintN(32, pv)));
                    else if (field.type === 'int64') packedVals.push(BigInt.asIntN(64, pv));
                    else if (field.type === 'uint64') packedVals.push(BigInt.asUintN(64, pv));
                    else packedVals.push(pv);
                }
                val = packedVals;
            }
        } else if (wireType === 5) {
            val = buf.readInt32LE(pos.val);
            pos.val += 4;
            if (field.type === 'fixed32') val = buf.readUInt32LE(pos.val - 4);
            else val = Number(val);
        }

        if (field.label === 'repeated') {
            if (field.isMap) {
                if (!result[fieldNum]) result[fieldNum] = {};
                const map = result[fieldNum];
                const entryPos = { val: 0 };
                const entryBuf = val as Buffer;
                let eKey: any, eVal: any;
                while (entryPos.val < entryBuf.length) {
                    const ek = Number(readVarint(entryBuf, entryPos));
                    const ew = ek & 0x07;
                    const ef = ek >> 3;
                    if (ef === 1) eKey = decodeValue(entryBuf, entryPos, ew, { type: field.mapKeyType!, name: '', number: 0, label: 'singular' }, schema);
                    else if (ef === 2) eVal = decodeValue(entryBuf, entryPos, ew, { type: field.type, name: '', number: 0, label: 'singular' }, schema);
                    else {
                        if (ew === 0) readVarint(entryBuf, entryPos);
                        else if (ew === 1) entryPos.val += 8;
                        else if (ew === 2) { const l = Number(readVarint(entryBuf, entryPos)); entryPos.val += l; }
                        else if (ew === 5) entryPos.val += 4;
                    }
                }
                const finalKey = eKey ?? (field.mapKeyType === 'string' ? '' : 0);
                const finalVal = eVal ?? getDefaultValue(field.type, schema);
                map[finalKey] = finalVal;
            } else {
                if (!result[fieldNum]) result[fieldNum] = [];
                if (Array.isArray(val)) result[fieldNum].push(...val);
                else result[fieldNum].push(val);
            }
        } else {
            if (field.oneofName) {
                const oneofFields = msgSchema.oneofs.get(field.oneofName)!;
                oneofFields.forEach(fNum => {
                    delete result[fNum];
                    presence.delete(fNum);
                });
            }
            if (schema.has(field.type)) {
                if (result[fieldNum]) result[fieldNum] = mergeMessagesInternal(result[fieldNum], val, schema, field.type);
                else result[fieldNum] = val;
            } else {
                result[fieldNum] = val;
            }
        }
        presence.add(fieldNum);
    }
    return { values: result, presence };
}

function mergeMessagesInternal(oldMsg: any, newMsg: any, schema: Map<string, Message>, type: string): any {
    const msgSchema = schema.get(type)!;
    const oldVals = oldMsg.values;
    const newVals = newMsg.values;
    const mergedVals = { ...oldVals };
    const mergedPresence = new Set(oldMsg.presence);

    for (const fieldNumStr in newVals) {
        const fNum = parseInt(fieldNumStr);
        const field = msgSchema.fields.get(fNum);
        if (!field) continue;
        if (field.label === 'repeated') {
            if (field.isMap) {
                mergedVals[fNum] = { ...mergedVals[fNum], ...newVals[fNum] };
            } else {
                mergedVals[fNum] = [...(mergedVals[fNum] || []), ...newVals[fNum]];
            }
        } else if (schema.has(field.type)) {
            mergedVals[fNum] = mergeMessagesInternal(mergedVals[fNum] || { values: {}, presence: new Set() }, newMsg[fNum], schema, field.type);
        } else {
            mergedVals[fNum] = newVals[fNum];
        }
        mergedPresence.add(fNum);
    }
    return { values: mergedVals, presence: mergedPresence };
}

function getDefaultValue(type: string, schema: Map<string, Message>): any {
    if (type === 'string') return '';
    if (type === 'bytes') return Buffer.alloc(0);
    if (type === 'bool') return false;
    if (['int32', 'uint32', 'sint32', 'fixed32', 'sfixed32'].includes(type)) return 0;
    if (['int64', 'uint64', 'sint64', 'fixed64', 'sfixed64'].includes(type)) return 0n;
    if (schema.has(type)) return { values: {}, presence: new Set() };
    return 0;
}

function camelCase(s: string): string {
    return s.replace(/_([a-z])/g, (_, char) => char.toUpperCase());
}

function escapeString(s: string): string {
    let res = '';
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (c === '"') res += '\\"';
        else if (c === '\\') res += '\\\\';
        else if (c === '\b') res += '\\b';
        else if (c === '\t') res += '\\t';
        else if (c === '\n') res += '\\n';
        else if (c === '\f') res += '\\f';
        else if (c === '\r') res += '\\r';
        else if (c.charCodeAt(0) < 0x20) {
            res += '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0').toLowerCase();
        } else res += c;
    }
    return res;
}

function formatValue(val: any, field: Field, schema: Map<string, Message>, enums: Map<string, Enum>): string {
    if (['int64', 'uint64', 'sint64', 'fixed64', 'sfixed64'].includes(field.type)) return `"${val.toString()}"`;
    if (field.type === 'bool') return val ? 'true' : 'false';
    if (field.type === 'string') return `"${escapeString(val)}"`;
    if (field.type === 'bytes') return `"${val.toString('base64')}"`;
    if (enums.has(field.type)) {
        const en = enums.get(field.type)!;
        const name = en.values.get(Number(val));
        return name ? `"${name}"` : Number(val);
    }
    if (schema.has(field.type)) {
        const msgSchema = schema.get(field.type)!;
        const fNums = Object.keys(val.values).map(Number).sort((a, b) => a - b);
        const parts = fNums.map(fNum => {
            const f = msgSchema.fields.get(fNum);
            if (!f) return null;
            return `"${camelCase(f.name)}":${formatValue(val.values[fNum], f, schema, enums)}`;
        }).filter(p => p !== null);
        return `{${parts.join(',')}}`;
    }
    return Number(val);
}

function formatMessage(val: any, msgSchema: Message, schema: Map<string, Message>, enums: Map<string, Enum>): string {
    const fNums = Object.keys(val.values).map(Number).sort((a, b) => a - b);
    const parts: string[] = [];
    for (const fNum of fNums) {
        const field = msgSchema.fields.get(fNum);
        if (!field) continue;
        const fVal = val.values[fNum];
        if (field.label === 'repeated') {
            if (field.isMap) {
                const mapKeys = Object.keys(fVal).sort((a, b) => {
                    if (field.mapKeyType === 'int32') return parseInt(a) - parseInt(b);
                    return a < b ? -1 : (a > b ? 1 : 0);
                });
                if (mapKeys.length === 0) continue;
                const mapParts = mapKeys.map(k => {
                    const v = fVal[k];
                    const vField: Field = { type: field.type, name: '', number: 0, label: 'singular' };
                    return `"${escapeString(k)}":${formatValue(v, vField, schema, enums)}`;
                });
                parts.push(`"${camelCase(field.name)}":{${mapParts.join(',')}}`);
            } else {
                if (fVal.length === 0) continue;
                const arrayParts = fVal.map(v => {
                    const vField: Field = { ...field, label: 'singular' };
                    return formatValue(v, vField, schema, enums);
                });
                parts.push(`"${camelCase(field.name)}":[${arrayParts.join(',')}]`);
            }
        } else {
            const defVal = getDefaultValue(field.type, schema);
            const isDefault = (field.type === 'string' || field.type === 'bytes') ? fVal === defVal : (typeof fVal === 'bigint' ? fVal === defVal : fVal === defVal);
            if (isDefault && field.label !== 'optional' && !field.oneofName) continue;
            parts.push(`"${camelCase(field.name)}":${formatValue(fVal, field, schema, enums)}`);
        }
    }
    return `{${parts.join(',')}}`;
}

async function main() {
    const dir = process.argv[2];
    if (!dir) return;
    const protoContent = fs.readFileSync(path.join(dir, 'schema.proto'), 'utf8');
    const binContent = fs.readFileSync(path.join(dir, 'messages.bin'));
    const parser = new ProtoParser(protoContent);
    const { messages, enums, rootType } = parser.parse();
    const pos = { val: 0 };
    while (pos.val < binContent.length) {
        const len = Number(readVarint(binContent, pos));
        const recordBuf = binContent.slice(pos.val, pos.val + len);
        pos.val += len;
        const decoded = decodeMessageInternal(recordBuf, messages, rootType);
        process.stdout.write(formatMessage(decoded, messages.get(rootType)!, messages, enums) + '\n');
    }
}

main();

import sys
