# --- Proto Parser ---

class ProtoParser:
    def __init__(self, content):
        # Remove comments
        content = re.sub(r'/\*.*?\*/', '', content, flags=re.DOTALL)
        content = re.sub(r'//.*', '', content)

        # Tokenizer
        self.tokens = []
        token_pattern = re.compile(r'("[^"]*"|[a-zA-Z_][a-zA-Z0-9_]*|[0-9]+|[0-9]+ to [0-9]+|[=;{},\[\]])')
        for match in token_pattern.finditer(content):
            self.tokens.append(match.group())
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self):
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, token):
        t = self.consume()
        if t != token:
            raise ValueError(f"Expected {token}, got {t}")

    def parse(self):
        messages = []
        enums = []
        while self.pos < len(self.tokens):
            token = self.peek()
            if token == 'syntax':
                self.consume()
                self.expect('=')
                self.consume() # "proto3"
                self.expect(';')
            elif token == 'package':
                self.consume()
                while self.peek() != ';':
                    self.consume()
                self.expect(';')
            elif token == 'option':
                self.consume()
                while self.peek() != ';':
                    self.consume()
                self.expect(';')
            elif token == 'message':
                messages.append(self.parse_message())
            elif token == 'enum':
                enums.append(self.parse_enum())
            else:
                self.pos += 1
        return messages, enums

    def parse_message(self):
        self.consume() # message
        name = self.consume()
        self.expect('{')
        fields = {}
        oneofs = {}

        while self.peek() != '}':
            token = self.peek()
            if token == 'message':
                self.parse_message() # Nested, but we only care about unique names
            elif token == 'enum':
                self.parse_enum()
            elif token == 'oneof':
                self.consume()
                oneof_name = self.consume()
                self.expect('{')
                oneof_fields = []
                while self.peek() != '}':
                    f = self.parse_field()
                    oneof_fields.append(f)
                self.expect('}')
                self.expect(';')
                for f in oneof_fields:
                    oneofs[f['number']] = oneof_name
                # The fields are still added to the message fields
                for f in oneof_fields:
                    fields[f['number']] = f
            elif token == 'reserved':
                self.consume()
                while self.peek() != ';':
                    self.consume()
                self.expect(';')
            elif token == 'option':
                self.consume()
                while self.peek() != ';':
                    self.consume()
                self.expect(';')
            else:
                # Field
                f = self.parse_field()
                fields[f['number']] = f
                if self.peek() == '[':
                    while self.peek() != ']':
                        self.consume()
                    self.expect(']')
                self.expect(';')
        self.expect('}')
        return {'name': name, 'fields': fields, 'oneofs': oneofs}

    def parse_enum(self):
        self.consume() # enum
        name = self.consume()
        self.expect('{')
        values = {}
        while self.peek() != '}':
            val_name = self.consume()
            self.expect('=')
            val_num = int(self.consume())
            self.expect(';')
            values[val_num] = val_name
        self.expect('}')
        return {'name': name, 'values': values}

    def parse_field(self):
        label = None
        if self.peek() == 'repeated':
            label = 'repeated'
            self.consume()
        elif self.peek() == 'optional':
            label = 'optional'
            self.consume()

        if self.peek() == 'map':
            self.consume()
            self.expect('<')
            key_type = self.consume()
            self.expect(',')
            val_type = self.consume()
            self.expect('>')
            name = self.consume()
            self.expect('=')
            num = int(self.consume())
            return {'name': name, 'number': num, 'type': 'map', 'key_type': key_type, 'val_type': val_type, 'label': 'repeated'}
        else:
            ftype = self.consume()
            name = self.consume()
            self.expect('=')
            num = int(self.consume())
            return {'name': name, 'number': num, 'type': ftype, 'label': label}

