def read_varint(stream):
    res = 0
    shift = 0
    for _ in range(10):
        b = stream.read(1)
        if not b: return None
        b = b[0]
        res |= (b & 0x7F) << shift
        if not (b & 0x80):
            return res
        shift += 7
    return res

