                        pass
                if field_num not in data: data[field_num] = []
                # Handle packed scalars
                if wire_type == 2 and ftype not in [t['name'] for t in types if 'fields' in t]:
                    # The 'b' was already read. Let's decode it.
                    # We need the raw bytes 'b' here.
                    # Let's re-read the loop to make 'b' available.
                    pass
                else:
