def merge_refined(target, source, types, msg_type):
    # This is a complex recursive merge. Let's implement it carefully.
    res = target.copy()
    for fn, fv in source.items():
        f_info = msg_type['fields'].get(fn)
        if not f_info: continue
        if f_info['label'] == 'repeated':
            if f_info['type'] == 'map':
                if fn not in res: res[fn] = {}
                res[fn].update(fv)
            else:
                if fn not in res: res[fn] = []
                res[fn].extend(fv)
        else:
            if f_info['type'] in [t['name'] for t in types if 'fields' in t]:
                if fn not in res:
                    res[fn] = fv
                else:
                    res[fn] = merge_refined(res[fn], fv, types, types[f_info['type']])
            else:
                res[fn] = fv
    return res

