def decode_varint_from_bytes(data, pos):
    res = 0
    shift = 0
    while True:
        b = data[pos]
        res |= (b & 0x7F) << shift
        pos += 1
        if not (b & 0x80): break
        shift += 7
    return res, pos

def decode_message_final(stream, msg_type, types, length=None):
    # Stream is now a BytesStream
    data = {}
    oneof_set = {}
    pos = 0

    # We need the raw bytes to handle packed fields
    raw_bytes = stream.read(length) if length is not None else stream.read()

    while pos < len(raw_bytes):
        key = 0
        # Read varint
        shift = 0
        while True:
            b = raw_bytes[pos]
            key |= (b & 0x7F) << shift
            pos += 1
            if not (b & 0x80): break
            shift += 7

        wire_type = key & 0x07
        field_num = key >> 3
        field_info = msg_type['fields'].get(field_num)

        if not field_info:
            if wire_type == 0:
                _, pos = decode_varint_from_bytes(raw_bytes, pos)
            elif wire_type == 1: pos += 8
            elif wire_type == 2:
                l, pos = decode_varint_from_bytes(raw_bytes, pos)
                pos += l
            elif wire_type == 3:
                depth = 1
                while depth > 0 and pos < len(raw_bytes):
                    k = 0
                    s = 0
                    while True:
                        b = raw_bytes[pos]
                        k |= (b & 0x7F) << s
                        pos += 1
                        if not (b & 0x80): break
                        s += 7
                    wt = k & 0x07
                    fn = k >> 3
                    if fn == field_num:
                        if wt == 3: depth += 1
                        elif wt == 4: depth -= 1
                    elif wt == 0: _, pos = decode_varint_from_bytes(raw_bytes, pos)
                    elif wt == 1: pos += 8
                    elif wt == 2:
                        l, pos = decode_varint_from_bytes(raw_bytes, pos)
                        pos += l
                    elif wt == 5: pos += 4
            elif wire_type == 5: pos += 4
            continue

        ftype = field_info['type']
        val = None
        if wire_type == 0:
            v, pos = decode_varint_from_bytes(raw_bytes, pos)
            if ftype == 'bool': val = (v != 0)
            elif ftype == 'int32':
                val = v & 0xFFFFFFFF
                if val >= 0x80000000: val -= 0x100000000
            elif ftype == 'int64':
                val = v & 0xFFFFFFFFFFFFFFFF
                if val >= 0x8000000000000000: val -= 0x10000000000000000
            elif ftype == 'uint32': val = v & 0xFFFFFFFF
            elif ftype == 'uint64': val = v & 0xFFFFFFFFFFFFFFFF
            elif ftype == 'sint32':
                val = decode_zigzag(v & 0xFFFFFFFF)
                if val >= 0x80000000: val -= 0x100000000 # This is actually not needed if we use the zigzag properly
                # Correct sint32:
                v_raw = v & 0xFFFFFFFF
                val = (v_raw >> 1) ^ -(v_raw & 1)
                if val >= 0x80000000: val -= 0x100000000 # No, it should be a 32-bit signed int
                # Let's just use:
                val = (v_raw >> 1) ^ -(v_raw & 1)
                if val > 0x7FFFFFFF: val -= 0x100000000
            elif ftype == 'sint64': val = decode_zigzag(v)
            elif ftype in [t['name'] for t in types if 'values' in t]:
                val = v & 0xFFFFFFFF
                if val >= 0x80000000: val -= 0x100000000
        elif wire_type == 1:
            b = raw_bytes[pos:pos+8]
            pos += 8
            val = struct.unpack('<q', b)[0] if ftype == 'sfixed64' else struct.unpack('<Q', b)[0]
        elif wire_type == 2:
            l, pos = decode_varint_from_bytes(raw_bytes, pos)
            b = raw_bytes[pos:pos+l]
            pos += l
            if ftype == 'string': val = b.decode('utf-8')
            elif ftype == 'bytes': val = b
            elif ftype == 'map':
                val = decode_message_final(BytesStream(b), 
                                         {'fields': {1: {'type': field_info['key_type'], 'number': 1}, 
                                                     2: {'type': field_info['val_type'], 'number': 2}}}, 
                                         types)
            elif ftype in [t['name'] for t in types if 'fields' in t]:
                val = decode_message_final(BytesStream(b), types[ftype], types)
        elif wire_type == 5:
            b = raw_bytes[pos:pos+4]
            pos += 4
            val = struct.unpack('<i', b)[0] if ftype == 'sfixed32' else struct.unpack('<I', b)[0]

        # Oneof
        oneof_name = msg_type['oneofs'].get(field_num)
        if oneof_name:
            oneof_set[oneof_name] = field_num
            for fn in list(data.keys()):
                if msg_type['oneofs'].get(fn) == oneof_name and fn != field_num:
                    del data[fn]

        # Merge
        if field_info['label'] == 'repeated':
            if ftype == 'map':
                if field_num not in data: data[field_num] = {}
                k = val.get(1, None)
                v = val.get(2, None)
                if k is None: k = "" if field_info['key_type'] == 'string' else 0
                if v is None:
                    v_type = field_info['val_type']
                    if v_type == 'string': v = ""
                    elif v_type == 'bytes': v = b""
                    elif v_type in ['int32', 'uint32', 'sint32', 'fixed32', 'sfixed32', 'bool']: v = 0
                    elif v_type in ['int64', 'uint64', 'sint64', 'fixed64', 'sfixed64']: v = 0
                    elif v_type in [t['name'] for t in types if 'values' in t]: v = 0
                    elif v_type in [t['name'] for t in types if 'fields' in t]: v = {}
                data[field_num][k] = v
            else:
                # Packed scalar
                if wire_type == 2 and ftype not in [t['name'] for t in types if 'fields' in t]:
                    # The 'b' was already read. Decode it.
                    # We need to go back to the bytes 'b'
                    b = raw_bytes[pos-l:pos] # This is wrong, 'pos' was already incremented
                    # Let's just use the 'b' from the `elif wire_type == 2` block.
                    # Since we are in the same loop, we can just use it.
                    pass
                # Let's just handle the packed scalars by decoding them one by one.
                if wire_type == 2 and ftype not in [t['name'] for t in types if 'fields' in t]:
                    # This is the laziest but most correct way:
                    # Re-decode the bytes 'b' as a sequence of the same type.
                    # We need the type to know how to decode.
                    packed_vals = []
                    p_pos = 0
                    while p_pos < len(b):
                        pv, p_pos = decode_varint_from_bytes(b, p_pos)
                        if ftype == 'bool': packed_vals.append(pv != 0)
                        elif ftype == 'int32':
                            v = pv & 0xFFFFFFFF
                            packed_vals.append(v if v < 0x80000000 else v - 0x100000000)
                        elif ftype == 'int64':
                            v = pv & 0xFFFFFFFFFFFFFFFF
                            packed_vals.append(v if v < 0x8000000000000000 else v - 0x10000000000000000)
                        elif ftype == 'uint32': packed_vals.append(pv & 0xFFFFFFFF)
                        elif ftype == 'uint64': packed_vals.append(pv & 0xFFFFFFFFFFFFFFFF)
                        elif ftype == 'sint32':
                            v_raw = pv & 0xFFFFFFFF
                            v = (v_raw >> 1) ^ -(v_raw & 1)
                            packed_vals.append(v if v < 0x80000000 else v - 0x100000000)
                        elif ftype == 'sint64': packed_vals.append(decode_zigzag(pv))
                        elif ftype in [t['name'] for t in types if 'values' in t]:
                            v = pv & 0xFFFFFFFF
                            packed_vals.append(v if v < 0x80000000 else v - 0x100000000)
                    if field_num not in data: data[field_num] = []
                    data[field_num].extend(packed_vals)
                else:
                    if field_num not in data: data[field_num] = []
                    data[field_num].append(val)
        else:
            if ftype in [t['name'] for t in types if 'fields' in t]:
                if field_num not in data: data[field_num] = val
                else: data[field_num] = merge_refined(data[field_num], val, types, types[ftype])
            else:
                data[field_num] = val
    return data

class BytesStream:
    def __init__(self, data): self.data = data; self.pos = 0
    def read(self, n=None):
        if n is None:
            res = self.data[self.pos:]
            self.pos = len(self.data)
            return res
        res = self.data[self.pos:self.pos+n]
        self.pos += len(res)
        return res

def to_camel_case(s):
    res = []
    i = 0
    while i < len(s):
        if s[i] == '_':
            i += 1
            if i < len(s) and 'a' <= s[i] <= 'z':
                res.append(s[i].upper())
                i += 1
            continue
        res.append(s[i])
        i += 1
    return "".join(res)

def json_escape(s):
    res = []
    for char in s:
        if char == '"': res.append('\\"')
        elif char == '\\': res.append('\\\\')
        elif char == '\b': res.append('\\b')
        elif char == '\t': res.append('\\t')
        elif char == '\n': res.append('\\n')
        elif char == '\f': res.append('\\f')
        elif char == '\r': res.append('\\r')
        elif ord(char) < 32: res.append(f'\\u{ord(char):04x}')
        else: res.append(char)
    return "".join(res)

def print_message(msg_type, data, types):
    res = []
    # Fields in ascending field-number order
    sorted_fields = sorted(msg_type['fields'].keys())
    for fn in sorted_fields:
        f_info = msg_type['fields'][fn]
        if fn not in data: continue

        val = data[fn]
        ftype = f_info['type']

        # Presence
        if f_info['label'] != 'repeated' and f_info['type'] != 'map':
            # Singular scalar
            if ftype not in [t['name'] for t in types if 'fields' in t]:
                # Check if default
                is_default = False
                if ftype == 'bool': is_default = (val == False)
                elif ftype in ['int32', 'uint32', 'sint32', 'fixed32', 'sfixed32', 'int64', 'uint64', 'sint64', 'fixed64', 'sfixed64']:
                    is_default = (val == 0)
                elif ftype == 'string': is_default = (val == "")
                elif ftype == 'bytes': is_default = (val == b"")
                elif ftype in [t['name'] for t in types if 'values' in t]:
                    is_default = (val == 0)

                if is_default and f_info['label'] != 'optional' and msg_type['oneofs'].get(fn) is None:
                    continue
        elif f_info['label'] == 'repeated' or f_info['type'] == 'map':
            if not val: continue

        # JSON Name
        name = to_camel_case(f_info['name'])

        # Value
        val_json = ""
        if f_info['type'] == 'map':
            # Sort map keys: string by UTF-8, int32 numerically
            sorted_keys = sorted(val.keys(), key=lambda k: (0 if isinstance(k, int) else 1, k))
            # Wait, the rule is "string keys by Unicode code point, int32 keys numerically".
            # This means we just sort them.
            if len(sorted_keys) > 0:
                if isinstance(sorted_keys[0], int):
                    sorted_keys = sorted(val.keys())
                else:
                    sorted_keys = sorted(val.keys())

            map_res = []
            for k in sorted_keys:
                k_json = json_escape(str(k))
                v_type = f_info['val_type']
                v_val = val[k]
                # To print v_val, we need its type. Let's use a helper.
                map_res.append(f'"{k_json}":{print_value(v_val, v_type, types)}')
            val_json = "{" + ",".join(map_res) + "}"
        elif f_info['label'] == 'repeated':
            # Array
            arr_res = []
            for item in val:
                item_type = ftype
                if ftype in [t['name'] for t in types if 'fields' in t]:
                    item_type = ftype
                arr_res.append(print_value(item, item_type, types))
            val_json = "[" + ",".join(arr_res) + "]"
        else:
            val_json = print_value(val, ftype, types)

        res.append(f'"{name}":{val_json}')

    return "{" + ",".join(res) + "}"

def print_value(val, ftype, types):
    if ftype == 'bool': return "true" if val else "false"
    if ftype in ['int32', 'uint32', 'sint32', 'fixed32', 'sfixed32']: return str(val)
    if ftype in ['int64', 'uint64', 'sint64', 'fixed64', 'sfixed64']: return f'"{val}"'
    if ftype == 'string': return f'"{json_escape(val)}"'
    if ftype == 'bytes': return f'"{base64.b64encode(val).decode()}"'
    if ftype in [t['name'] for t in types if 'values' in t]:
        enum_type = next(t for t in types if t['name'] == ftype)
        if val in enum_type['values']: return f'"{enum_type["values"][val]}"'
        return str(val)
    if ftype in [t['name'] for t in types if 'fields' in t]:
        return print_message(types[ftype], val, types)
    return "null"

