import sys
import os
import re
import struct
import base64

# --- Proto Parser ---

class ProtoParser:
    def __init__(self, content):
        # Remove comments
        content = re.sub(r'/\*.*?\*/', '', content, flags=re.DOTALL)
        content = re.sub(r'//.*', '', content)

        # Tokenizer
        self.tokens = []
        token_pattern = re.compile(r'("[^"]*"|[a-zA-Z_][a-zA-Z0-9_]*|[0-9]+|[0-9]+ to [0-9]+|[=;{},\[\]<>])')
        for match in token_pattern.finditer(content):
            self.tokens.append(match.group())
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self):
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, token):
        t = self.consume()
        if t != token:
            raise ValueError(f"Expected {token}, got {t}")

    def parse(self, all_types):
        top_level_messages = []
        while self.pos < len(self.tokens):
            token = self.peek()
            if token == 'syntax':
                self.consume(); self.expect('='); self.consume(); self.expect(';')
            elif token == 'package':
                self.consume()
                while self.peek() != ';': self.consume()
                self.expect(';')
            elif token == 'option':
                self.consume()
                while self.peek() != ';': self.consume()
                self.expect(';')
            elif token == 'message':
                m = self.parse_message(all_types)
                all_types[m['name']] = m
                top_level_messages.append(m)
            elif token == 'enum':
                e = self.parse_enum(all_types)
                all_types[e['name']] = e
            else:
                self.pos += 1
        return top_level_messages

    def parse_message(self, all_types):
        self.consume() # message
        name = self.consume()
        self.expect('{')
        fields = {}
        oneofs = {}
        while self.peek() != '}':
            token = self.peek()
            if token == 'message':
                m = self.parse_message(all_types)
                all_types[m['name']] = m
            elif token == 'enum':
                e = self.parse_enum(all_types)
                all_types[e['name']] = e
            elif token == 'oneof':
                self.consume() # oneof
                oneof_name = self.consume()
                self.expect('{')
                while self.peek() != '}':
                    f = self.parse_field()
                    fields[f['number']] = f
                    oneofs[f['number']] = oneof_name
                self.expect('}')
                self.expect(';')
            elif token == 'reserved':
                self.consume()
                while self.peek() != ';': self.consume()
                self.expect(';')
            elif token == 'option':
                self.consume()
                while self.peek() != ';': self.consume()
                self.expect(';')
            else:
                f = self.parse_field()
                fields[f['number']] = f
                if self.peek() == '[':
                    self.consume() # [
                    while self.peek() != ']': self.consume()
                    self.expect(']')
                self.expect(';')
        self.expect('}')
        return {'name': name, 'fields': fields, 'oneofs': oneofs}

    def parse_enum(self, all_types):
        self.consume() # enum
        name = self.consume()
        self.expect('{')
        values = {}
        while self.peek() != '}':
            val_name = self.consume()
            self.expect('=')
            val_num = int(self.consume())
            self.expect(';')
            values[val_num] = val_name
        self.expect('}')
        return {'name': name, 'values': values}

    def parse_field(self):
        label = None
        if self.peek() == 'repeated':
            label = 'repeated'
            self.consume()
        elif self.peek() == 'optional':
            label = 'optional'
            self.consume()

        if self.peek() == 'map':
            self.consume() # map
            self.expect('<')
            key_type = self.consume()
            self.expect(',')
            val_type = self.consume()
            self.expect('>')
            name = self.consume()
            self.expect('=')
            num = int(self.consume())
            return {'name': name, 'number': num, 'type': 'map', 'key_type': key_type, 'val_type': val_type, 'label': 'repeated'}
        else:
            ftype = self.consume()
            name = self.consume()
            self.expect('=')
            num = int(self.consume())
            return {'name': name, 'number': num, 'type': ftype, 'label': label}

# --- Protobuf Decoder ---

def read_varint(stream):
    res = 0
    shift = 0
    for _ in range(10):
        b = stream.read(1)
        if not b: return None
        b = b[0]
        res |= (b & 0x7F) << shift
        if not (b & 0x80): return res
        shift += 7
    return res

def decode_zigzag(n):
    return (n >> 1) ^ -(n & 1)

def merge_messages(target, source, msg_type, all_types):
    for fn, fv in source.items():
        f_info = msg_type['fields'].get(fn)
        if not f_info: continue
        if f_info['label'] == 'repeated':
            if f_info['type'] == 'map':
                if fn not in target: target[fn] = {}
                target[fn].update(fv)
            else:
                if fn not in target: target[fn] = []
                target[fn].extend(fv)
        else:
            if f_info['type'] in all_types and 'fields' in all_types[f_info['type']]:
                if fn not in target:
                    target[fn] = fv
                else:
                    target[fn] = merge_messages(target[fn], fv, all_types[f_info['type']], all_types)
            else:
                target[fn] = fv
    return target

def decode_message(stream, msg_type, all_types, length=None):
    if length is not None:
        class LimitedStream:
            def __init__(self, s, l): self.s = s; self.l = l
            def read(self, n):
                if self.l <= 0: return b''
                res = self.s.read(min(n, self.l))
                self.l -= len(res)
                return res
        stream = LimitedStream(stream, length)

    data = {}
    while True:
        key = read_varint(stream)
        if key is None: break
        if hasattr(stream, 'l') and stream.l == 0: break # Check if length exhausted

        wire_type = key & 0x07
        field_num = key >> 3
        field_info = msg_type['fields'].get(field_num)

        if not field_info:
            if wire_type == 0: read_varint(stream)
            elif wire_type == 1: stream.read(8)
            elif wire_type == 2:
                l = read_varint(stream)
                stream.read(l)
            elif wire_type == 3:
                depth = 1
                while depth > 0:
                    k = read_varint(stream)
                    if k is None: break
                    wt = k & 0x07
                    fn = k >> 3
                    if fn == field_num:
                        if wt == 3: depth += 1
                        elif wt == 4: depth -= 1
                    elif wt == 0: read_varint(stream)
                    elif wt == 1: stream.read(8)
                    elif wt == 2:
                        l = read_varint(stream)
                        stream.read(l)
                    elif wt == 5: stream.read(4)
            elif wire_type == 5: stream.read(4)
            continue

        ftype = field_info['type']
        val = None
        if wire_type == 0:
            v = read_varint(stream)
            if ftype == 'bool': val = (v != 0)
            elif ftype == 'int32':
                val = v & 0xFFFFFFFF
                if val >= 0x80000000: val -= 0x100000000
            elif ftype == 'int64':
                val = v & 0xFFFFFFFFFFFFFFFF
                if val >= 0x8000000000000000: val -= 0x10000000000000000
            elif ftype == 'uint32': val = v & 0xFFFFFFFF
            elif ftype == 'uint64': val = v & 0xFFFFFFFFFFFFFFFF
            elif ftype == 'sint32':
                v_raw = v & 0xFFFFFFFF
                val = decode_zigzag(v_raw)
                if val >= 0x80000000: val -= 0x100000000
            elif ftype == 'sint64': val = decode_zigzag(v)
            elif ftype in all_types and 'values' in all_types[ftype]:
                val = v & 0xFFFFFFFF
                if val >= 0x80000000: val -= 0x100000000
        elif wire_type == 1:
            b = stream.read(8)
            val = struct.unpack('<q', b)[0] if ftype == 'sfixed64' else struct.unpack('<Q', b)[0]
        elif wire_type == 2:
            l = read_varint(stream)
            b = stream.read(l)
            if ftype == 'string': val = b.decode('utf-8')
            elif ftype == 'bytes': val = b
            elif ftype == 'map':
                class BytesStream:
                    def __init__(self, data): self.data = data; self.pos = 0
                    def read(self, n):
                        res = self.data[self.pos:self.pos+n]
                        self.pos += len(res)
                        return res
                val = decode_message(BytesStream(b), {'fields': {1: {'type': field_info['key_type'], 'number': 1}, 2: {'type': field_info['val_type'], 'number': 2}}, 'oneofs': {}}, all_types)
            elif ftype in all_types and 'fields' in all_types[ftype]:
                class BytesStream:
                    def __init__(self, data): self.data = data; self.pos = 0
                    def read(self, n):
                        res = self.data[self.pos:self.pos+n]
                        self.pos += len(res)
                        return res
                val = decode_message(BytesStream(b), all_types[ftype], all_types)
        elif wire_type == 5:
            b = stream.read(4)
            val = struct.unpack('<i', b)[0] if ftype == 'sfixed32' else struct.unpack('<I', b)[0]

        oneof_name = msg_type['oneofs'].get(field_num)
        if oneof_name:
            for fn in list(data.keys()):
                if msg_type['oneofs'].get(fn) == oneof_name and fn != field_num:
                    del data[fn]

        if field_info['label'] == 'repeated':
            if ftype == 'map':
                if field_num not in data: data[field_num] = {}
                k = val.get(1, None)
                v = val.get(2, None)
                if k is None: k = "" if field_info['key_type'] == 'string' else 0
                if v is None:
                    v_type = field_info['val_type']
                    if v_type == 'string': v = ""
                    elif v_type == 'bytes': v = b""
                    elif v_type in ['int32', 'uint32', 'sint32', 'fixed32', 'sfixed32', 'bool'] or (v_type in all_types and 'values' in all_types[v_type]): v = 0
                    elif v_type in ['int64', 'uint64', 'sint64', 'fixed64', 'sfixed64']: v = 0
                    elif v_type in all_types and 'fields' in all_types[v_type]: v = {}
                data[field_num][k] = v
            else:
                if field_num not in data: data[field_num] = []
                if wire_type == 2 and ftype not in all_types: # Packed
                    class BytesStream:
                        def __init__(self, data): self.data = data; self.pos = 0
                        def read(self, n):
                            res = self.data[self.pos:self.pos+n]
                            self.pos += len(res)
                            return res
                    bs = BytesStream(b)
                    while True:
                        pv = read_varint(bs)
                        if pv is None: break
                        if ftype == 'bool': data[field_num].append(pv != 0)
                        elif ftype == 'int32':
                            v = pv & 0xFFFFFFFF
                            data[field_num].append(v if v < 0x80000000 else v - 0x100000000)
                        elif ftype == 'int64':
                            v = pv & 0xFFFFFFFFFFFFFFFF
                            data[field_num].append(v if v < 0x8000000000000000 else v - 0x10000000000000000)
                        elif ftype == 'uint32': data[field_num].append(pv & 0xFFFFFFFF)
                        elif ftype == 'uint64': data[field_num].append(pv & 0xFFFFFFFFFFFFFFFF)
                        elif ftype == 'sint32':
                            v_raw = pv & 0xFFFFFFFF
                            val_z = decode_zigzag(v_raw)
                            data[field_num].append(val_z if val_z < 0x80000000 else val_z - 0x100000000)
                        elif ftype == 'sint64': data[field_num].append(decode_zigzag(pv))
                        elif ftype in all_types and 'values' in all_types[ftype]:
                            v = pv & 0xFFFFFFFF
                            data[field_num].append(v if v < 0x80000000 else v - 0x100000000)
                else:
                    data[field_num].append(val)
        else:
            if ftype in all_types and 'fields' in all_types[ftype]:
                if field_num not in data:
                    data[field_num] = val
                else:
                    data[field_num] = merge_messages(data[field_num], val, all_types[ftype], all_types)
            else:
                data[field_num] = val
    return data

def to_camel_case(s):
    res = []
    i = 0
    while i < len(s):
        if s[i] == '_':
            i += 1
            if i < len(s) and 'a' <= s[i] <= 'z':
                res.append(s[i].upper())
                i += 1
            continue
        res.append(s[i])
        i += 1
    return "".join(res)

def json_escape(s):
    res = []
    for char in s:
        if char == '"': res.append('\\"')
        elif char == '\\': res.append('\\\\')
        elif char == '\b': res.append('\\b')
        elif char == '\t': res.append('\\t')
        elif char == '\n': res.append('\\n')
        elif char == '\f': res.append('\\f')
        elif char == '\r': res.append('\\r')
        elif ord(char) < 32: res.append(f'\\u{ord(char):04x}')
        else: res.append(char)
    return "".join(res)

def print_value(val, ftype, all_types):
    if ftype == 'bool': return "true" if val else "false"
    if ftype in ['int32', 'uint32', 'sint32', 'fixed32', 'sfixed32']: return str(val)
    if ftype in ['int64', 'uint64', 'sint64', 'fixed64', 'sfixed64']: return f'"{val}"'
    if ftype == 'string': return f'"{json_escape(val)}"'
    if ftype == 'bytes': return f'"{base64.b64encode(val).decode()}"'
    if ftype in all_types and 'values' in all_types[ftype]:
        enum_type = all_types[ftype]
        if val in enum_type['values']: return f'"{enum_type["values"][val]}"'
        return str(val)
    if ftype in all_types and 'fields' in all_types[ftype]:
        return print_message(all_types[ftype], val, all_types)
    return "null"

def print_message(msg_type, data, all_types):
    res = []
    sorted_fields = sorted(msg_type['fields'].keys())
    for fn in sorted_fields:
        f_info = msg_type['fields'][fn]
        if fn not in data: continue
        val = data[fn]
        ftype = f_info['type']
        if f_info['label'] != 'repeated' and ftype != 'map':
            if ftype not in all_types or 'fields' not in all_types[ftype]:
                is_default = False
                if ftype == 'bool': is_default = (val == False)
                elif ftype in ['int32', 'uint32', 'sint32', 'fixed32', 'sfixed32', 'int64', 'uint64', 'sint64', 'fixed64', 'sfixed64']: is_default = (val == 0)
                elif ftype == 'string': is_default = (val == "")
                elif ftype == 'bytes': is_default = (val == b"")
                elif ftype in all_types and 'values' in all_types[ftype]: is_default = (val == 0)
                if is_default and f_info['label'] != 'optional' and msg_type['oneofs'].get(fn) is None:
                    continue
        elif f_info['label'] == 'repeated' or ftype == 'map':
            if not val: continue

        name = to_camel_case(f_info['name'])
        if ftype == 'map':
            sorted_keys = sorted(val.keys(), key=lambda k: (0 if isinstance(k, int) else 1, k if isinstance(k, int) else k))
            map_res = []
            for k in sorted_keys:
                k_json = json_escape(str(k))
                v_type = f_info['val_type']
                v_val = val[k]
                map_res.append(f'"{k_json}":{print_value(v_val, v_type, all_types)}')
            val_json = "{" + ",".join(map_res) + "}"
        elif f_info['label'] == 'repeated':
            arr_res = [print_value(item, ftype, all_types) for item in val]
            val_json = "[" + ",".join(arr_res) + "]"
        else:
            val_json = print_value(val, ftype, all_types)
        res.append(f'"{name}":{val_json}')
    return "{" + ",".join(res) + "}"

def main():
    if len(sys.argv) < 2: return
    dir_path = sys.argv[1]
    with open(os.path.join(dir_path, 'schema.proto'), 'r') as f:
        content = f.read()
    all_types = {}
    parser = ProtoParser(content)
    top_messages = parser.parse(all_types)
    root_type = top_messages[0]
    with open(os.path.join(dir_path, 'messages.bin'), 'rb') as f:
        while True:
            length = read_varint(f)
            if length is None: break
            class LimitedStream:
                def __init__(self, s, l): self.s = s; self.l = l
                def read(self, n):
                    if self.l <= 0: return b''
                    res = self.s.read(min(n, self.l))
                    self.l -= len(res)
                    return res
            decoded = decode_message(LimitedStream(f, length), root_type, all_types, length)
            print(print_message(root_type, decoded, all_types))

if __name__ == "__main__":
    main()

import sys
import os

# Instruction classes for the VM
class Char:
    def __init__(self, c): self.c = c
class Any: pass
class Class:
    def __init__(self, items, negated):
        self.items = items
        self.negated = negated
class Split:
    def __init__(self, l1, l2):
        self.l1 = l1
        self.l2 = l2
class Jump:
    def __init__(self, l): self.l = l
class Save:
    def __init__(self, slot): self.slot = slot
class AnchorStart: pass
class AnchorEnd: pass
class Match: pass

class RegexParser:
    def __init__(self, pattern):
        self.pattern = pattern
        self.pos = 0
        self.group_count = 0

    def peek(self):
        return self.pattern[self.pos] if self.pos < len(self.pattern) else None

    def eat(self, char=None):
        if char is not None and self.peek() != char:
            raise Exception("Unexpected character")
        self.pos += 1

    def eat_char(self):
        c = self.peek()
        self.pos += 1
        return c

    def parse_regex(self):
        branches = [self.parse_branch()]
        while self.peek() == '|':
            self.eat('|')
            branches.append(self.parse_branch())
        return branches

    def parse_branch(self):
        pieces = []
        while self.pos < len(self.pattern) and self.peek() not in '|)':
            pieces.append(self.parse_piece())
        return pieces

    def parse_piece(self):
        atom = self.parse_atom()
        quantifier = None
        if self.peek() in '*+?{':
            q_char = self.peek()
            self.eat()
            if q_char == '*': quantifier = (0, float('inf'), False)
            elif q_char == '+': quantifier = (1, float('inf'), False)
            elif q_char == '?': quantifier = (0, 1, False)
            elif q_char == '{':
                m_str = ""
                while self.peek() != ',' and self.peek() != '}':
                    m_str += self.eat_char()
                if self.peek() == ',':
                    self.eat(',')
                    n_str = ""
                    while self.peek() != '}':
                        n_str += self.eat_char()
                    self.eat('}')
                    m = int(m_str)
                    n = int(n_str) if n_str else float('inf')
                else:
                    self.eat('}')
                    m = n = int(m_str)
                quantifier = (m, n, False)
            if self.peek() == '?':
                self.eat('?')
                m, n, _ = quantifier
                quantifier = (m, n, True)
        return (atom, quantifier)

    def parse_atom(self):
        c = self.peek()
        if c == '(':
            self.eat('(')
            if self.peek() == '?' and self.pos + 1 < len(self.pattern) and self.pattern[self.pos+1] == ':':
                self.eat('?')
                self.eat(':')
                regex = self.parse_regex()
                self.eat(')')
                return ('group', regex, False, None)
            else:
                self.group_count += 1
                g_num = self.group_count
                regex = self.parse_regex()
                self.eat(')')
                return ('group', regex, True, g_num)
        elif c == '.':
            self.eat('.')
            return ('any',)
        elif c == '^':
            self.eat('^')
            return ('anchor_start',)
        elif c == '$':
            self.eat('$')
            return ('anchor_end',)
        elif c == '[':
            return self.parse_class()
        elif c == '\\':
            self.eat('\\')
            esc = self.eat_char()
            if esc == 'd': return ('class_esc', 'digit')
            elif esc == 'w': return ('class_esc', 'word')
            elif esc == 's': return ('class_esc', 'space')
            elif esc == 'D': return ('class_esc', 'not_digit')
            elif esc == 'W': return ('class_esc', 'not_word')
            elif esc == 'S': return ('class_esc', 'not_space')
            else: return ('char', esc)
        else:
            char = self.eat_char()
            if char in '.[](){)*+?|^$':
                return ('char', char) # Handle as literal if it's escaped, but here we're in atom
            return ('char', char)

    def parse_class(self):
        self.eat('[')
        negated = False
        if self.peek() == '^':
            negated = True
            self.eat('^')
        items = []
        while self.peek() != ']':
            if self.peek() == '\\':
                self.eat('\\')
                esc = self.eat_char()
                if esc == 'd': items.append(('digit',))
                elif esc == 'w': items.append(('word',))
                elif esc == 's': items.append(('space',))
                elif esc == 'D': items.append(('not_digit',))
                elif esc == 'W': items.append(('not_word',))
                elif esc == 'S': items.append(('not_space',))
                else: items.append(('char', esc))
            elif self.peek() == '-' and len(items) > 0:
                if items[-1][0] == 'char' and self.peek() != ']':
                    start_char = items[-1][1]
                    self.eat('-')
                    if self.peek() == '\\':
                        self.eat('\\')
                        end_char = self.eat_char()
                    else:
                        end_char = self.eat_char()
                    items[-1] = ('range', start_char, end_char)
                else:
                    self.eat('-')
                    items.append(('char', '-'))
            else:
                char = self.eat_char()
                items.append(('char', char))
        self.eat(']')
        return ('class', items, negated)

def compile_regex_internal(vm, branches):
    if len(branches) == 1:
        return compile_branch_internal(vm, branches[0])
    split_pc = vm.add_instr(None)
    branch1_start = len(vm.instructions)
    num_instr1 = compile_branch_internal(vm, branches[0])
    jump_pc = vm.add_instr(Jump(0))
    num_instr_rest = compile_regex_internal(vm, branches[1:])
    vm.update_instr(split_pc, Split(branch1_start, len(vm.instructions)))
    vm.update_instr(jump_pc, Jump(len(vm.instructions)))
    return 1 + num_instr1 + 1 + num_instr_rest

def compile_branch_internal(vm, pieces):
    total_instr = 0
    for atom, quantifier in pieces:
        total_instr += compile_atom_with_quantifier(vm, atom, quantifier)
    return total_instr

def compile_atom(vm, atom):
    if atom[0] == 'group':
        is_capturing, g_num = atom[2], atom[3]
        if is_capturing: vm.add_instr(Save(g_num * 2))
        num_instr = compile_regex_internal(vm, atom[1])
        if is_capturing: vm.add_instr(Save(g_num * 2 + 1))
        return (1 if is_capturing else 0) + num_instr + (1 if is_capturing else 0)
    elif atom[0] == 'any':
        vm.add_instr(Any())
        return 1
    elif atom[0] == 'anchor_start':
        vm.add_instr(AnchorStart())
        return 1
    elif atom[0] == 'anchor_end':
        vm.add_instr(AnchorEnd())
        return 1
    elif atom[0] == 'class':
        vm.add_instr(Class(atom[1], atom[2]))
        return 1
    elif atom[0] == 'char':
        vm.add_instr(Char(atom[1]))
        return 1
    elif atom[0] == 'class_esc':
        # Convert class_esc to a Class with one item
        esc = atom[1]
        items = []
        if esc == 'digit': items.append(('digit',))
        elif esc == 'word': items.append(('word',))
        elif esc == 'space': items.append(('space',))
        elif esc == 'not_digit': items.append(('not_digit',))
        elif esc == 'not_word': items.append(('not_word',))
        elif esc == 'not_space': items.append(('not_space',))
        vm.add_instr(Class(items, False))
        return 1

def compile_atom_with_quantifier(vm, atom, quantifier):
    if quantifier is None: return compile_atom(vm, atom)
    m, n, lazy = quantifier
    total_instr = 0
    for _ in range(m): total_instr += compile_atom(vm, atom)
    if n == float('inf'):
        split_pc = vm.add_instr(None)
        atom_start = len(vm.instructions)
        atom_instr_count = compile_atom(vm, atom)
        jump_pc = vm.add_instr(Jump(0))
        if lazy: vm.update_instr(split_pc, Split(len(vm.instructions), atom_start))
        else: vm.update_instr(split_pc, Split(atom_start, len(vm.instructions)))
        vm.update_instr(jump_pc, Jump(split_pc))
        total_instr += 1 + atom_instr_count + 1
        return total_instr
    else:
        for _ in range(n - m):
            split_pc = vm.add_instr(None)
            atom_start = len(vm.instructions)
            atom_instr_count = compile_atom(vm, atom)
            if lazy: vm.update_instr(split_pc, Split(len(vm.instructions), atom_start))
            else: vm.update_instr(split_pc, Split(atom_start, len(vm.instructions)))
            total_instr += 1 + atom_instr_count
        return total_instr

class VMCompiler:
    def __init__(self): self.instructions = []
    def add_instr(self, instr):
        self.instructions.append(instr)
        return len(self.instructions) - 1
    def update_instr(self, pc, instr):
        self.instructions[pc] = instr

def is_match(char, item):
    if item[0] == 'char': return char == item[1]
    if item[0] == 'range': return item[1] <= char <= item[2]
    if item[0] == 'digit': return '0' <= char <= '9'
