import sys
import os

# Instruction classes for the VM
class Char:
    def __init__(self, c): self.c = c
class Any: pass
class Class:
    def __init__(self, items, negated):
        self.items = items
        self.negated = negated
class Split:
    def __init__(self, l1, l2):
        self.l1 = l1
        self.l2 = l2
class Jump:
    def __init__(self, l): self.l = l
class Save:
    def __init__(self, slot): self.slot = slot
class AnchorStart: pass
class AnchorEnd: pass
class Match: pass

class RegexParser:
    def __init__(self, pattern):
        self.pattern = pattern
        self.pos = 0
        self.group_count = 0

    def peek(self):
        return self.pattern[self.pos] if self.pos < len(self.pattern) else None

    def eat(self, char=None):
        if char is not None and self.peek() != char:
            raise Exception("Unexpected character")
        self.pos += 1

    def eat_char(self):
        c = self.peek()
        self.pos += 1
        return c

    def parse_regex(self):
        branches = [self.parse_branch()]
        while self.peek() == '|':
            self.eat('|')
            branches.append(self.parse_branch())
        return branches

    def parse_branch(self):
        pieces = []
        while self.pos < len(self.pattern) and self.peek() not in '|)':
            pieces.append(self.parse_piece())
        return pieces

    def parse_piece(self):
        atom = self.parse_atom()
        quantifier = None
        if self.peek() in '*+?{':
            q_char = self.peek()
            self.eat()
            if q_char == '*': quantifier = (0, float('inf'), False)
            elif q_char == '+': quantifier = (1, float('inf'), False)
            elif q_char == '?': quantifier = (0, 1, False)
            elif q_char == '{':
                m_str = ""
                while self.peek() != ',' and self.peek() != '}':
                    m_str += self.eat_char()
                if self.peek() == ',':
                    self.eat(',')
                    n_str = ""
                    while self.peek() != '}':
                        n_str += self.eat_char()
                    self.eat('}')
                    m = int(m_str)
                    n = int(n_str) if n_str else float('inf')
                else:
                    self.eat('}')
                    m = n = int(m_str)
                quantifier = (m, n, False)
            if self.peek() == '?':
                self.eat('?')
                m, n, _ = quantifier
                quantifier = (m, n, True)
        return (atom, quantifier)

    def parse_atom(self):
        c = self.peek()
        if c == '(':
            self.eat('(')
            if self.peek() == '?' and self.pos + 1 < len(self.pattern) and self.pattern[self.pos+1] == ':':
                self.eat('?')
                self.eat(':')
                regex = self.parse_regex()
                self.eat(')')
                return ('group', regex, False, None)
            else:
                self.group_count += 1
                g_num = self.group_count
                regex = self.parse_regex()
                self.eat(')')
                return ('group', regex, True, g_num)
        elif c == '.':
            self.eat('.')
            return ('any',)
        elif c == '^':
            self.eat('^')
            return ('anchor_start',)
        elif c == '$':
            self.eat('$')
            return ('anchor_end',)
        elif c == '[':
            return self.parse_class()
        elif c == '\\':
            self.eat('\\')
            esc = self.eat_char()
            if esc == 'd': return ('class_esc', 'digit')
            elif esc == 'w': return ('class_esc', 'word')
            elif esc == 's': return ('class_esc', 'space')
            elif esc == 'D': return ('class_esc', 'not_digit')
            elif esc == 'W': return ('class_esc', 'not_word')
            elif esc == 'S': return ('class_esc', 'not_space')
            else: return ('char', esc)
        else:
            char = self.eat_char()
            return ('char', char)

    def parse_class(self):
        self.eat('[')
        negated = False
        if self.peek() == '^':
            negated = True
            self.eat('^')
        items = []
        while self.pos < len(self.pattern) and self.peek() != ']':
            if self.peek() == '\\':
                self.eat('\\')
                esc = self.eat_char()
                if esc == 'd': items.append(('digit',))
                elif esc == 'w': items.append(('word',))
                elif esc == 's': items.append(('space',))
                elif esc == 'D': items.append(('not_digit',))
                elif esc == 'W': items.append(('not_word',))
                elif esc == 'S': items.append(('not_space',))
                else: items.append(('char', esc))
            elif self.peek() == '-' and len(items) > 0:
                start_char = items[-1][1] if items[-1][0] == 'char' else None
                if start_char is not None:
                    # Check if next char is ']'
                    if self.peek() == ']':
                        items.append(('char', '-'))
                        self.eat('-')
                    else:
                        # Possible range
                        self.eat('-')
                        if self.peek() == '\\':
                            self.eat('\\')
                            end_char = self.eat_char()
                        else:
                            end_char = self.eat_char()
                        items[-1] = ('range', start_char, end_char)
                else:
                    items.append(('char', '-'))
                    self.eat('-')
            else:
                char = self.eat_char()
                items.append(('char', char))
        self.eat(']')
        return ('class', items, negated)

def compile_regex_internal(vm, branches):
    if len(branches) == 1:
        return compile_branch_internal(vm, branches[0])
    split_pc = vm.add_instr(None)
    branch1_start = len(vm.instructions)
    num_instr1 = compile_branch_internal(vm, branches[0])
    jump_pc = vm.add_instr(Jump(0))
    num_instr_rest = compile_regex_internal(vm, branches[1:])
    vm.update_instr(split_pc, Split(branch1_start, len(vm.instructions)))
    vm.update_instr(jump_pc, Jump(len(vm.instructions)))
    return 1 + num_instr1 + 1 + num_instr_rest

def compile_branch_internal(vm, pieces):
    total_instr = 0
    for atom, quantifier in pieces:
        total_instr += compile_atom_with_quantifier(vm, atom, quantifier)
    return total_instr

def compile_atom(vm, atom):
    if atom[0] == 'group':
        is_capturing, g_num = atom[2], atom[3]
        if is_capturing: vm.add_instr(Save(g_num * 2))
        num_instr = compile_regex_internal(vm, atom[1])
        if is_capturing: vm.add_instr(Save(g_num * 2 + 1))
        return (1 if is_capturing else 0) + num_instr + (1 if is_capturing else 0)
    elif atom[0] == 'any':
        vm.add_instr(Any())
        return 1
    elif atom[0] == 'anchor_start':
        vm.add_instr(AnchorStart())
        return 1
    elif atom[0] == 'anchor_end':
        vm.add_instr(AnchorEnd())
        return 1
    elif atom[0] == 'class':
        vm.add_instr(Class(atom[1], atom[2]))
        return 1
    elif atom[0] == 'char':
        vm.add_instr(Char(atom[1]))
        return 1
    elif atom[0] == 'class_esc':
        esc = atom[1]
        items = []
        if esc == 'digit': items.append(('digit',))
        elif esc == 'word': items.append(('word',))
        elif esc == 'space': items.append(('space',))
        elif esc == 'not_digit': items.append(('not_digit',))
        elif esc == 'not_word': items.append(('not_word',))
        elif esc == 'not_space': items.append(('not_space',))
        vm.add_instr(Class(items, False))
        return 1

def compile_atom_with_quantifier(vm, atom, quantifier):
    if quantifier is None: return compile_atom(vm, atom)
    m, n, lazy = quantifier
    total_instr = 0
    for _ in range(m): total_instr += compile_atom(vm, atom)
    if n == float('inf'):
        split_pc = vm.add_instr(None)
        atom_start = len(vm.instructions)
        atom_instr_count = compile_atom(vm, atom)
        jump_pc = vm.add_instr(Jump(0))
        if lazy: vm.update_instr(split_pc, Split(len(vm.instructions), atom_start))
        else: vm.update_instr(split_pc, Split(atom_start, len(vm.instructions)))
        vm.update_instr(jump_pc, Jump(split_pc))
        total_instr += 1 + atom_instr_count + 1
        return total_instr
    else:
        for _ in range(n - m):
            split_pc = vm.add_instr(None)
            atom_start = len(vm.instructions)
            atom_instr_count = compile_atom(vm, atom)
            if lazy: vm.update_instr(split_pc, Split(len(vm.instructions), atom_start))
            else: vm.update_instr(split_pc, Split(atom_start, len(vm.instructions)))
            total_instr += 1 + atom_instr_count
        return total_instr

class VMCompiler:
    def __init__(self): self.instructions = []
    def add_instr(self, instr):
        self.instructions.append(instr)
        return len(self.instructions) - 1
    def update_instr(self, pc, instr):
        self.instructions[pc] = instr

def is_match(char, item):
    if item[0] == 'char': return char == item[1]
    if item[0] == 'range': return item[1] <= char <= item[2]
    if item[0] == 'digit': return '0' <= char <= '9'
