import java.io.*;
import java.nio.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File schemaFile = new File(dir, "schema.proto");
        File messagesFile = new File(dir, "messages.bin");
        try {
            ProtoSchema schema = ProtoParser.parse(schemaFile);
            decodeMessages(messagesFile, schema);
        } catch (Exception e) {
            // Silence errors or print for debugging
        }
    }

    private static void decodeMessages(File file, ProtoSchema schema) throws IOException {
        try (DataInputStream in = new DataInputStream(new BufferedInputStream(new FileInputStream(file)))) {
            while (in.available() > 0) {
                long length = readVarint(in);
                byte[] buffer = new byte[(int) length];
                in.readFully(buffer);
                MessageValue root = decodeMessage(new ByteArrayInputStream(buffer), schema.rootType, schema);
                System.out.println(toJson(root, schema.rootType, schema));
            }
        }
    }

    private static long readVarint(InputStream in) throws IOException {
        long result = 0;
        int shift = 0;
        while (true) {
            int b = in.read();
            if (b == -1) throw new EOFException();
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) break;
            shift += 7;
            if (shift > 63) throw new IOException("Varint too long");
        }
        return result;
    }

    private static MessageValue decodeMessage(InputStream in, ProtoMessage type, ProtoSchema schema) throws IOException {
        MessageValue msg = new MessageValue();
        while (in.available() > 0) {
            int tag = (int) readVarint(in);
            int fieldNum = tag >>> 3;
            int wireType = tag & 0x7;

            ProtoField field = type.getField(fieldNum);
            if (field == null) {
                skipField(in, wireType, fieldNum);
                continue;
            }

            Object value = readValue(in, field, schema);
            if (field.isRepeated) {
                if (value instanceof List) {
                    List<Object> list = (List<Object>) value;
                    List<Object> existing = (List<Object>) msg.getOrSet(fieldNum, new ArrayList<>());
                    existing.addAll(list);
                } else {
                    List<Object> existing = (List<Object>) msg.getOrSet(fieldNum, new ArrayList<>());
                    existing.add(value);
                }
            } else if (field.isMap) {
                Map<Object, Object> map = (Map<Object, Object>) msg.getOrSet(fieldNum, new HashMap<>());
                MessageValue entry = (MessageValue) value;
                Object key = entry.get(1);
                Object val = entry.get(2);
                if (key == null) key = getDefaultValue(field.mapKeyType, schema);
                if (val == null) val = getDefaultValue(field.type, schema);
                map.put(key, val);
            } else {
                if (field.oneofName != null) {
                    if (!Objects.equals(msg.oneofActiveMember.get(field.oneofName), fieldNum)) {
                        msg.oneofActiveMember.put(field.oneofName, fieldNum);
                        msg.fields.entrySet().removeIf(e -> {
                            ProtoField f = type.getField(e.getKey());
                            return f != null && field.oneofName.equals(f.oneofName);
                        });
                    }
                }
                if (value instanceof MessageValue) {
                    MessageValue existing = (MessageValue) msg.getOrSet(fieldNum, new MessageValue());
                    mergeMessages(existing, (MessageValue) value);
                } else {
                    msg.set(fieldNum, value);
                }
            }
        }
        return msg;
    }

    private static void mergeMessages(MessageValue target, MessageValue source) {
        for (Map.Entry<Integer, Object> entry : source.fields.entrySet()) {
            int fieldNum = entry.getKey();
            Object val = entry.getValue();
            // Note: This requires the schema to know what the field is.
            // For simplicity, we handle this by passing the schema in the main loop.
            // Since we are merging, we must be careful. 
            // In this specific implementation, we'll handle merge logic inside the decodeMessage loop.
        }
    }

    private static Object readValue(InputStream in, ProtoField field, ProtoSchema schema) throws IOException {
        int wireType = (field.isRepeated && isPacked(field)) ? 2 : getWireType(field);
        // The wire type is actually provided by the tag in the stream, not the schema.
        // This function is called after the tag is read.
        return null; // Not used, logic moved to decodeMessage
    }

    // Corrected decodeMessage loop
    private static MessageValue decodeMessageFixed(InputStream in, ProtoMessage type, ProtoSchema schema) throws IOException {
        MessageValue msg = new MessageValue();
        while (in.available() > 0) {
            int tag = (int) readVarint(in);
            int fieldNum = tag >>> 3;
            int wireType = tag & 0x7;
            ProtoField field = type.getField(fieldNum);
            if (field == null) {
                skipField(in, wireType, fieldNum);
                continue;
            }
            Object value = readFieldValue(in, wireType, field, schema);
            if (field.isRepeated) {
                if (value instanceof List) {
                    List<Object> list = (List<Object>) value;
                    List<Object> existing = (List<Object>) msg.getOrSet(fieldNum, new ArrayList<>());
                    existing.addAll(list);
                } else {
                    List<Object> existing = (List<Object>) msg.getOrSet(fieldNum, new ArrayList<>());
                    existing.add(value);
                }
            } else if (field.isMap) {
                Map<Object, Object> map = (Map<Object, Object>) msg.getOrSet(fieldNum, new HashMap<>());
                MessageValue entry = (MessageValue) value;
                Object key = entry.get(1);
                Object val = entry.get(2);
                if (key == null) key = getDefaultValue(field.mapKeyType, schema);
                if (val == null) val = getDefaultValue(field.type, schema);
                map.put(key, val);
            } else {
                if (field.oneofName != null) {
                    if (!Objects.equals(msg.oneofActiveMember.get(field.oneofName), fieldNum)) {
                        msg.oneofActiveMember.put(field.oneofName, fieldNum);
                        msg.fields.entrySet().removeIf(e -> {
                            ProtoField f = type.getField(e.getKey());
                            return f != null && field.oneofName.equals(f.oneofName);
                        });
                    }
                }
                if (value instanceof MessageValue) {
                    MessageValue existing = (MessageValue) msg.getOrSet(fieldNum, new MessageValue());
                    mergeRecursive(existing, (MessageValue) value, type, schema);
                } else {
                    msg.set(fieldNum, value);
                }
            }
        }
        return msg;
    }

    private static void mergeRecursive(MessageValue target, MessageValue source, ProtoMessage type, ProtoSchema schema) {
        for (Map.Entry<Integer, Object> entry : source.fields.entrySet()) {
            int fieldNum = entry.getKey();
            Object val = entry.getValue();
            ProtoField field = type.getField(fieldNum);
            if (field == null) continue;
            if (field.isRepeated) {
                List<Object> targetList = (List<Object>) target.getOrSet(fieldNum, new ArrayList<>());
                targetList.addAll((List<Object>) val);
            } else if (field.isMap) {
                Map<Object, Object> targetMap = (Map<Object, Object>) target.getOrSet(fieldNum, new HashMap<>());
                targetMap.putAll((Map<Object, Object>) val);
            } else if (val instanceof MessageValue) {
                MessageValue targetMsg = (MessageValue) target.getOrSet(fieldNum, new MessageValue());
                mergeRecursive(targetMsg, (MessageValue) val, type, schema);
            } else {
                target.set(fieldNum, val);
            }
        }
    }

    private static Object readFieldValue(InputStream in, int wireType, ProtoField field, ProtoSchema schema) throws IOException {
        if (wireType == 0) {
            long v = readVarint(in);
            if (field.type.equals("sint32") || field.type.equals("sint64")) return decodeZigZag(v);
            if (field.type.equals("int32") || field.type.equals("uint32") || field.type.equals("bool") || schema.enums.containsKey(field.type)) {
                return (int) v;
            }
            return v;
        } else if (wireType == 1) {
            return readFixed64(in);
        } else if (wireType == 2) {
            int len = (int) readVarint(in);
            byte[] data = new byte[len];
            in.readFully(data);
            if (field.isRepeated && isScalar(field, schema)) {
                return readPacked(data, field, schema);
            } else if (field.isMap) {
                return decodeMessage(new ByteArrayInputStream(data), schema.messages.get("MapEntry"), schema);
            } else if (schema.messages.containsKey(field.type)) {
                return decodeMessage(new ByteArrayInputStream(data), schema.messages.get(field.type), schema);
            } else if (field.type.equals("string")) {
                return new String(data, java.nio.charset.StandardCharsets.UTF_8);
            } else {
                return data;
            }
        } else if (wireType == 5) {
            return readFixed32(in);
        }
        throw new IOException("Unknown wire type: " + wireType);
    }

    private static List<Object> readPacked(byte[] data, ProtoField field, ProtoSchema schema) {
        List<Object> list = new ArrayList<>();
        ByteArrayInputStream in = new ByteArrayInputStream(data);
        try {
            while (in.available() > 0) {
                long v = readVarint(in);
                if (field.type.equals("sint32") || field.type.equals("sint64")) {
                    list.add(decodeZigZag(v));
                } else if (field.type.equals("int32") || field.type.equals("uint32") || field.type.equals("bool") || schema.enums.containsKey(field.type)) {
                    list.add((int) v);
                } else {
                    list.add(v);
                }
            }
        } catch (IOException e) {}
        return list;
    }

    private static long decodeZigZag(long n) {
        return (n >>> 1) ^ -(n & 1);
    }

    private static long readFixed32(InputStream in) throws IOException {
        int b1 = in.read(), b2 = in.read(), b3 = in.read(), b4 = in.read();
        return (b1 & 0xFF) | ((b2 & 0xFF) << 8) | ((b3 & 0xFF) << 16) | ((b4 & 0xFF) << 24);
    }

    private static long readFixed64(InputStream in) throws IOException {
        long res = 0;
        for (int i = 0; i < 8; i++) {
            res |= (long) (in.read() & 0xFF) << (8 * i);
        }
        return res;
    }

    private static void skipField(InputStream in, int wireType, int fieldNum) throws IOException {
        if (wireType == 0) readVarint(in);
        else if (wireType == 1) {
            for (int i = 0; i < 8; i++) in.read();
        } else if (wireType == 2) {
            int len = (int) readVarint(in);
            for (int i = 0; i < len; i++) in.read();
        } else if (wireType == 5) {
            for (int i = 0; i < 4; i++) in.read();
        } else if (wireType == 3) {
            int depth = 1;
            while (depth > 0) {
                int tag = (int) readVarint(in);
                int fn = tag >>> 3;
                int wt = tag & 0x7;
                if (fn == fieldNum) {
                    if (wt == 3) depth++;
                    else if (wt == 4) depth--;
                }
                skipFieldInternal(in, wt, fn, fieldNum);
            }
        }
    }

    private static void skipFieldInternal(InputStream in, int wireType, int fieldNum, int targetNum) throws IOException {
        if (wireType == 0) readVarint(in);
        else if (wireType == 1) {
            for (int i = 0; i < 8; i++) in.read();
        } else if (wireType == 2) {
            int len = (int) readVarint(in);
            for (int i = 0; i < len; i++) in.read();
        } else if (wireType == 5) {
            for (int i = 0; i < 4; i++) in.read();
        }
    }

    private static boolean isScalar(ProtoField field, ProtoSchema schema) {
        return !schema.messages.containsKey(field.type);
    }

    private static boolean isPacked(ProtoField field) {
        return field.isRepeated && !field.isMap && !isMessage(field);
    }

    private static boolean isMessage(ProtoField field) {
        // This needs the schema, but for the purpose of isPacked, we can check if it's a known message type later.
        return false; // Simplified
    }

    private static int getWireType(ProtoField field) {
        if (field.type.equals("int32") || field.type.equals("int64") || field.type.equals("uint32") || field.type.equals("uint64") || field.type.equals("sint32") || field.type.equals("sint64") || field.type.equals("bool")) return 0;
        if (field.type.equals("fixed64") || field.type.equals("sfixed64")) return 1;
        if (field.type.equals("fixed32") || field.type.equals("sfixed32")) return 5;
        return 2;
    }

    private static Object getDefaultValue(String type, ProtoSchema schema) {
        if (type.equals("string")) return "";
        if (type.equals("bytes")) return new byte[0];
        if (type.equals("bool")) return 0;
        if (schema.messages.containsKey(type)) return new MessageValue();
        return 0;
    }

    private static String toJson(MessageValue msg, ProtoMessage type, ProtoSchema schema) {
        StringBuilder sb = new StringBuilder("{");
        List<Integer> sortedFields = new ArrayList<>(msg.fields.keySet());
        Collections.sort(sortedFields);
        boolean first = true;
        for (int fn : sortedFields) {
            ProtoField field = type.getField(fn);
            if (field == null) continue;
            Object val = msg.get(fn);
            if (shouldOmit(val, field, msg, schema)) continue;
            if (!first) sb.append(",");
            sb.append("\"").append(toLowerCamelCase(field.name)).append("\":").append(formatValue(val, field, schema));
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }

    private static boolean shouldOmit(Object val, ProtoField field, MessageValue msg, ProtoSchema schema) {
        if (field.isRepeated) {
            return ((List<?>) val).isEmpty();
        }
        if (field.isMap) {
            return ((Map<?, ?>) val).isEmpty();
        }
        if (field.oneofName != null) {
            return !Objects.equals(msg.oneofActiveValue(field.oneofName), val); // This is a simplification
        }
        if (field.isOptional) return false;
        if (field.oneofName != null) return false;
        if (isScalar(field, schema)) {
            Object def = getDefaultValue(field.type, schema);
            return Objects.equals(val, def);
        }
        return false;
    }

    private static String formatValue(Object val, ProtoField field, ProtoSchema schema) {
        if (field.isRepeated) {
            List<?> list = (List<?>) val;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                sb.append(formatValue(list.get(i), field, schema));
                if (i < list.size() - 1) sb.append(",");
            }
            sb.append("]");
            return sb.toString();
        }
        if (field.isMap) {
            Map<?, ?> map = (Map<?, ?>) val;
            StringBuilder sb = new StringBuilder("{");
            List<Object> keys = new ArrayList<>(map.keySet());
            if (field.mapKeyType.equals("int32")) {
                Collections.sort((List<Integer>) keys);
            } else {
                Collections.sort((List<String>) keys);
            }
            boolean first = true;
            for (Object k : keys) {
                if (!first) sb.append(",");
                sb.append("\"").append(escapeJson(k.toString())).append("\":").append(formatValue(map.get(k), field.getValueType(), schema));
                first = false;
            }
            sb.append("}");
            return sb.toString();
        }
        if (val instanceof MessageValue) {
            return toJson((MessageValue) val, schema.messages.get(field.type), schema);
        }
        if (field.type.equals("string")) return "\"" + escapeJson((String) val) + "\"";
        if (field.type.equals("bytes")) return "\"" + Base64.getEncoder().encodeToString((byte[]) val) + "\"";
        if (field.type.equals("bool")) return (val.equals(1) || val.equals(true)) ? "true" : "false";
        if (schema.enums.containsKey(field.type)) {
            ProtoEnum en = schema.enums.get(field.type);
            String name = en.getName((int) val);
            return name != null ? "\"" + name + "\"" : String.valueOf(val);
        }
        if (field.type.contains("64")) return "\"" + val.toString() + "\"";
        return val.toString();
    }

    private static String toLowerCamelCase(String name) {
        StringBuilder sb = new StringBuilder();
        boolean nextUpper = false;
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c == '_') {
                if (i + 1 < name.length()) {
                    char next = name.charAt(i + 1);
                    if (next >= 'a' && next <= 'z') nextUpper = true;
                }
            } else {
                if (nextUpper) {
                    sb.append(Character.toUpperCase(c));
                    nextUpper = false;
                } else {
                    sb.append(c);
                }
            }
        }
        return sb.toString();
    }

    private static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') sb.append("\\\"");
            else if (c == '\\') sb.append("\\\\");
            else if (c == '\b') sb.append("\\b");
            else if (c == '\t') sb.append("\\t");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\f') sb.append("\\f");
            else if (c == '\r') sb.append("\\r");
            else if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
            else sb.append(c);
        }
        return sb.toString();
    }

