    static class MessageValue {
        Map<Integer, Object> fields = new TreeMap<>();
        Map<String, Integer> oneofActiveMember = new HashMap<>();
        void set(int fn, Object v) { fields.put(fn, v); }
        Object get(int fn) { return fields.get(fn); }
        Object getOrSet(int fn, Object def) {
            if (!fields.containsKey(fn)) fields.put(fn, def);
            return fields.get(fn);
        }
        Object oneofActiveValue(String name) {
            Integer fn = oneofActiveMember.get(name);
            return fn == null ? null : fields.get(fn);
        }
    }

    static class ProtoSchema {
        Map<String, ProtoMessage> messages = new HashMap<>();
        Map<String, ProtoEnum> enums = new HashMap<>();
        ProtoMessage rootType;
    }

    static class ProtoMessage {
        Map<Integer, ProtoField> fields = new HashMap<>();
        ProtoField getField(int fn) { return fields.get(fn); }
    }

    static class ProtoField {
        int number;
        String name;
        String type;
        boolean isRepeated, isOptional, isMap;
        String mapKeyType;
        String oneofName;
        String getValueType() { return isMap ? type : type; } // Simplified
    }

    static class ProtoEnum {
        Map<Integer, String> values = new HashMap<>();
        String getName(int v) { return values.get(v); }
    }

    static class ProtoParser {
        static ProtoSchema parse(File file) throws IOException {
            String content = new String(java.nio.file.Files.readAllBytes(file.toPath()));
            content = content.replaceAll("//.*", "").replaceAll("/\*([^*]|\*+[^*/])*\*+/", "");
            Scanner sc = new Scanner(content);
            ProtoSchema schema = new ProtoSchema();
            boolean firstMessage = true;
            while (sc.hasNext()) {
                String token = sc.next();
                if (token.equals("syntax") || token.equals("package") || token.equals("option")) {
                    skipToSemicolon(sc);
                } else if (token.equals("message")) {
                    String name = sc.next();
                    ProtoMessage msg = new ProtoMessage();
                    schema.messages.put(name, msg);
                    if (firstMessage) { schema.rootType = msg; firstMessage = false; }
                    sc.next(); // {
                    parseMessageBody(sc, msg, schema);
                    sc.next(); // }
                } else if (token.equals("enum")) {
                    String name = sc.next();
                    ProtoEnum en = new ProtoEnum();
                    schema.enums.put(name, en);
                    sc.next(); // {
                    parseEnumBody(sc, en);
                    sc.next(); // }
                } else {
                    sc.next();
                }
            }
            // Add a dummy MapEntry message for map decoding
            ProtoMessage mapEntry = new ProtoMessage();
            ProtoField f1 = new ProtoField(); f1.number = 1; mapEntry.fields.put(1, f1);
            ProtoField f2 = new ProtoField(); f2.number = 2; mapEntry.fields.put(2, f2);
            schema.messages.put("MapEntry", mapEntry);
            return schema;
        }
        private static void skipToSemicolon(Scanner sc) {
            while (sc.hasNext() && !sc.next().equals(";"));
        }
        private static void parseMessageBody(Scanner sc, ProtoMessage msg, ProtoSchema schema) {
            while (sc.hasNext()) {
                String token = sc.next();
                if (token.equals("}")) break;
                if (token.equals("message")) {
                    String name = sc.next();
                    ProtoMessage nested = new ProtoMessage();
                    schema.messages.put(name, nested);
                    sc.next(); parseMessageBody(sc, nested, schema); sc.next();
                } else if (token.equals("enum")) {
                    String name = sc.next();
                    ProtoEnum en = new ProtoEnum();
                    schema.enums.put(name, en);
                    sc.next(); parseEnumBody(sc, en); sc.next();
                } else if (token.equals("oneof")) {
                    String oneofName = sc.next();
                    sc.next(); // {
                    while (true) {
                        String t = sc.next();
                        if (t.equals("}")) break;
                        ProtoField f = parseField(sc, true);
                        f.oneofName = oneofName;
                        msg.fields.put(f.number, f);
                        if (sc.next().equals(";")) continue;
                    }
                    sc.next(); // ;
                } else if (token.equals("reserved")) {
                    while (!sc.next().equals(";"));
                } else if (token.equals("option")) {
                    while (!sc.next().equals(";"));
                } else {
                    // It's a field
                    String label = "";
                    if (token.equals("repeated") || token.equals("optional")) {
                        label = token;
                        token = sc.next();
                    }
                    ProtoField f = new ProtoField();
                    if (token.equals("map")) {
                        f.isMap = true;
                        sc.next(); // <
                        f.mapKeyType = sc.next().replace(",", "");
                        sc.next(); // ,
                        f.type = sc.next().replace(">", "");
                        sc.next(); // >
                    } else {
                        f.type = token;
                    }
                    f.name = sc.next();
                    sc.next(); // =
                    f.number = Integer.parseInt(sc.next().replace(";", ""));
                    if (label.equals("repeated")) f.isRepeated = true;
                    if (label.equals("optional")) f.isOptional = true;
                    // Skip options
                    while (sc.hasNext() && !sc.next().equals(";"));
                    msg.fields.put(f.number, f);
                }
            }
        }
        private static ProtoField parseField(Scanner sc, boolean inOneof) {
            String token = sc.next();
            ProtoField f = new ProtoField();
            if (token.equals("map")) {
                f.isMap = true;
                sc.next(); f.mapKeyType = sc.next().replace(",", "");
                sc.next(); f.type = sc.next().replace(">", "");
                sc.next();
            } else {
                f.type = token;
            }
            f.name = sc.next();
            sc.next(); f.number = Integer.parseInt(sc.next().replace(";", ""));
            return f;
        }
        private static void parseEnumBody(Scanner sc, ProtoEnum en) {
            while (sc.hasNext()) {
                String token = sc.next();
                if (token.equals("}")) break;
                String name = token;
                sc.next(); // =
                int val = Integer.parseInt(sc.next().replace(";", ""));
                en.values.put(val, name);
                if (token.equals("}")) break;
            }
        }
    }
}

import java.io.*;
import java.nio.*;
import java.util.*;
import java.util.Base64;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File schemaFile = new File(dir, "schema.proto");
        File messagesFile = new File(dir, "messages.bin");
        try {
            ProtoSchema schema = ProtoParser.parse(schemaFile);
            decodeMessages(messagesFile, schema);
        } catch (Exception e) {
            // Silence errors
        }
    }

    private static void decodeMessages(File file, ProtoSchema schema) throws IOException {
        try (DataInputStream in = new DataInputStream(new BufferedInputStream(new FileInputStream(file)))) {
            while (in.available() > 0) {
                long length = readVarint(in);
                byte[] buffer = new byte[(int) length];
                in.readFully(buffer);
                MessageValue root = decodeMessage(new ByteArrayInputStream(buffer), schema.rootType, schema);
                System.out.println(toJson(root, schema.rootType, schema));
            }
        }
    }

    private static long readVarint(InputStream in) throws IOException {
        long result = 0;
        int shift = 0;
        while (true) {
            int b = in.read();
            if (b == -1) throw new EOFException();
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) break;
            shift += 7;
            if (shift > 63) throw new IOException("Varint too long");
        }
        return result;
    }

    private static MessageValue decodeMessage(InputStream in, ProtoMessage type, ProtoSchema schema) throws IOException {
        MessageValue msg = new MessageValue();
        while (in.available() > 0) {
            int tag = (int) readVarint(in);
            int fieldNum = tag >>> 3;
            int wireType = tag & 0x7;

            ProtoField field = type.getField(fieldNum);
            if (field == null) {
                skipField(in, wireType, fieldNum);
                continue;
            }

            Object value = readFieldValue(in, wireType, field, schema);
            processField(msg, field, value, type, schema);
        }
        return msg;
    }

    private static void processField(MessageValue msg, ProtoField field, Object value, ProtoMessage type, ProtoSchema schema) {
        if (field.isRepeated) {
            List<Object> list = (List<Object>) msg.getOrSet(field.number, new ArrayList<>());
            if (value instanceof List) {
                list.addAll((List<Object>) value);
            } else {
                list.add(value);
            }
        } else if (field.isMap) {
            Map<Object, Object> map = (Map<Object, Object>) msg.getOrSet(field.number, new HashMap<>());
            MessageValue entry = (MessageValue) value;
            Object key = entry.get(1);
            Object val = entry.get(2);
            if (key == null) key = getDefaultValue(field.mapKeyType, schema);
            if (val == null) val = getDefaultValue(field.type, schema);
            map.put(key, val);
        } else {
            if (field.oneofName != null) {
                if (!Objects.equals(msg.oneofActiveMember.get(field.oneofName), field.number)) {
                    msg.oneofActiveMember.put(field.oneofName, field.number);
                    msg.fields.entrySet().removeIf(e -> {
                        ProtoField f = type.getField(e.getKey());
                        return f != null && Objects.equals(f.oneofName, field.oneofName);
                    });
                }
            }
            if (value instanceof MessageValue) {
                MessageValue existing = (MessageValue) msg.getOrSet(field.number, new MessageValue());
                mergeMessages(existing, (MessageValue) value, type, schema);
            } else {
                msg.set(field.number, value);
            }
        }
    }

    private static void mergeMessages(MessageValue target, MessageValue source, ProtoMessage type, ProtoSchema schema) {
        for (Map.Entry<Integer, Object> entry : source.fields.entrySet()) {
            int fieldNum = entry.getKey();
            Object value = entry.getValue();
            ProtoField field = type.getField(fieldNum);
            if (field == null) continue;
            processField(target, field, value, type, schema);
        }
    }

    private static Object readFieldValue(InputStream in, int wireType, ProtoField field, ProtoSchema schema) throws IOException {
        if (wireType == 0) {
            long v = readVarint(in);
            if (field.type.equals("sint32") || field.type.equals("sint64")) return decodeZigZag(v);
            return v;
        } else if (wireType == 1) {
            return readFixed64(in);
        } else if (wireType == 2) {
            int len = (int) readVarint(in);
            byte[] data = new byte[len];
            in.readFully(data);
            if (field.isRepeated && isScalar(field, schema)) {
                return readPacked(data, field, schema);
            } else if (field.isMap) {
                return decodeMessage(new ByteArrayInputStream(data), schema.mapEntryType, schema);
            } else if (schema.messages.containsKey(field.type)) {
                return decodeMessage(new ByteArrayInputStream(data), schema.messages.get(field.type), schema);
            } else if (field.type.equals("string")) {
                return new String(data, java.nio.charset.StandardCharsets.UTF_8);
            } else {
                return data;
            }
        } else if (wireType == 5) {
            return readFixed32(in);
        }
        throw new IOException("Unknown wire type: " + wireType);
    }

    private static List<Object> readPacked(byte[] data, ProtoField field, ProtoSchema schema) {
        List<Object> list = new ArrayList<>();
        ByteArrayInputStream in = new ByteArrayInputStream(data);
        try {
            while (in.available() > 0) {
                long v = readVarint(in);
                if (field.type.equals("sint32") || field.type.equals("sint64")) {
                    list.add(decodeZigZag(v));
                } else {
                    list.add(v);
                }
            }
        } catch (IOException e) {}
        return list;
    }

    private static long decodeZigZag(long n) {
        return (n >>> 1) ^ -(n & 1);
    }

    private static long readFixed32(InputStream in) throws IOException {
        int b1 = in.read(), b2 = in.read(), b3 = in.read(), b4 = in.read();
        return (b1 & 0xFF) | ((b2 & 0xFF) << 8) | ((b3 & 0xFF) << 16) | ((b4 & 0xFF) << 24);
    }

    private static long readFixed64(InputStream in) throws IOException {
        long res = 0;
        for (int i = 0; i < 8; i++) {
            res |= (long) (in.read() & 0xFF) << (8 * i);
        }
        return res;
    }

    private static void skipField(InputStream in, int wireType, int fieldNum) throws IOException {
        if (wireType == 0) readVarint(in);
        else if (wireType == 1) {
            for (int i = 0; i < 8; i++) in.read();
        } else if (wireType == 2) {
            int len = (int) readVarint(in);
            for (int i = 0; i < len; i++) in.read();
        } else if (wireType == 5) {
            for (int i = 0; i < 4; i++) in.read();
        } else if (wireType == 3) {
            while (true) {
                int tag = (int) readVarint(in);
                int fn = tag >>> 3;
                int wt = tag & 0x7;
                if (fn == fieldNum && wt == 4) break;
                skipField(in, wt, fn);
            }
        }
    }

    private static boolean isScalar(ProtoField field, ProtoSchema schema) {
        return !schema.messages.containsKey(field.type);
    }

    private static Object getDefaultValue(String type, ProtoSchema schema) {
        if (type.equals("string")) return "";
        if (type.equals("bytes")) return new byte[0];
        if (type.equals("bool")) return 0L;
        if (schema.messages.containsKey(type)) return new MessageValue();
        return 0L;
    }

    private static String toJson(MessageValue msg, ProtoMessage type, ProtoSchema schema) {
        StringBuilder sb = new StringBuilder("{");
        List<Integer> sortedFields = new ArrayList<>(msg.fields.keySet());
        Collections.sort(sortedFields);
        boolean first = true;
        for (int fn : sortedFields) {
            ProtoField field = type.getField(fn);
            if (field == null) continue;
            Object val = msg.get(fn);
            if (shouldOmit(val, field, msg, schema)) continue;
            if (!first) sb.append(",");
            sb.append("\"").append(toLowerCamelCase(field.name)).append("\":").append(formatValue(val, field, schema));
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }

    private static boolean shouldOmit(Object val, ProtoField field, MessageValue msg, ProtoSchema schema) {
        if (field.isRepeated) return ((List<?>) val).isEmpty();
        if (field.isMap) return ((Map<?, ?>) val).isEmpty();
        if (field.oneofName != null) return false;
        if (field.isOptional) return false;
        if (isScalar(field, schema)) {
            Object def = getDefaultValue(field.type, schema);
            return Objects.equals(val, def);
        }
        return false;
    }

    private static String formatValue(Object val, ProtoField field, ProtoSchema schema) {
        if (field.isRepeated) {
            List<?> list = (List<?>) val;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                sb.append(formatValue(list.get(i), field, schema));
                if (i < list.size() - 1) sb.append(",");
            }
            sb.append("]");
            return sb.toString();
        }
        if (field.isMap) {
            Map<?, ?> map = (Map<?, ?>) val;
            StringBuilder sb = new StringBuilder("{");
            List<Object> keys = new ArrayList<>(map.keySet());
            if (field.mapKeyType.equals("int32")) {
                Collections.sort((List<Integer>) keys);
            } else {
                Collections.sort((List<String>) keys);
            }
            boolean first = true;
            for (Object k : keys) {
                if (!first) sb.append(",");
                sb.append("\"").append(escapeJson(k.toString())).append("\":").append(formatValue(map.get(k), field.getValueType(), schema));
                first = false;
            }
            sb.append("}");
            return sb.toString();
        }
        if (val instanceof MessageValue) {
            return toJson((MessageValue) val, schema.messages.get(field.type), schema);
        }
        if (field.type.equals("string")) return "\"" + escapeJson((String) val) + "\"";
        if (field.type.equals("bytes")) return "\"" + Base64.getEncoder().encodeToString((byte[]) val) + "\"";
        if (field.type.equals("bool")) return (val != null && (long)val != 0) ? "true" : "false";
        if (schema.enums.containsKey(field.type)) {
            ProtoEnum en = schema.enums.get(field.type);
            String name = en.getName((int) (long) val);
            return name != null ? "\"" + name + "\"" : String.valueOf((long) val);
        }
        if (field.type.contains("64")) return "\"" + (long) val + "\"";
        return String.valueOf((long) val);
    }

    private static String toLowerCamelCase(String name) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c == '_') {
                if (i + 1 < name.length()) {
                    char next = name.charAt(i + 1);
                    if (next >= 'a' && next <= 'z') {
                        sb.append(Character.toUpperCase(next));
                        i++;
                    }
                }
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') sb.append("\\\"");
            else if (c == '\\') sb.append("\\\\");
            else if (c == '\b') sb.append("\\b");
            else if (c == '\t') sb.append("\\t");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\f') sb.append("\\f");
            else if (c == '\r') sb.append("\\r");
            else if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
            else sb.append(c);
        }
        return sb.toString();
    }

    static class MessageValue {
        Map<Integer, Object> fields = new TreeMap<>();
        Map<String, Integer> oneofActiveMember = new HashMap<>();
        void set(int fn, Object v) { fields.put(fn, v); }
        Object get(int fn) { return fields.get(fn); }
        Object getOrSet(int fn, Object def) {
            if (!fields.containsKey(fn)) fields.put(fn, def);
            return fields.get(fn);
        }
    }

    static class ProtoSchema {
        Map<String, ProtoMessage> messages = new HashMap<>();
        Map<String, ProtoEnum> enums = new HashMap<>();
        ProtoMessage rootType;
        ProtoMessage mapEntryType;
    }

    static class ProtoMessage {
        Map<Integer, ProtoField> fields = new HashMap<>();
        ProtoField getField(int fn) { return fields.get(fn); }
    }

    static class ProtoField {
        int number;
        String name;
        String type;
        boolean isRepeated, isOptional, isMap;
        String mapKeyType;
        String oneofName;
        String getValueType() { return isMap ? type : type; }
    }

    static class ProtoEnum {
        Map<Integer, String> values = new HashMap<>();
        String getName(int v) { return values.get(v); }
    }

    static class ProtoParser {
        static ProtoSchema parse(File file) throws IOException {
            String content = new String(java.nio.file.Files.readAllBytes(file.toPath()));
            content = content.replaceAll("//.*", "").replaceAll("/\\*([^*]|\\*+[^*/])*\\*+/", "");
            Lexer lexer = new Lexer(content);
            ProtoSchema schema = new ProtoSchema();
            boolean firstMessage = true;
            while (lexer.hasNext()) {
                String token = lexer.nextToken();
                if (token.equals("syntax") || token.equals("package") || token.equals("option")) {
                    while (!lexer.nextToken().equals(";"));
                } else if (token.equals("message")) {
                    String name = lexer.nextToken();
                    ProtoMessage msg = new ProtoMessage();
                    schema.messages.put(name, msg);
                    if (firstMessage) { schema.rootType = msg; firstMessage = false; }
                    lexer.nextToken(); // {
                    parseMessageBody(lexer, msg, schema);
                    lexer.nextToken(); // }
                } else if (token.equals("enum")) {
                    String name = lexer.nextToken();
                    ProtoEnum en = new ProtoEnum();
                    schema.enums.put(name, en);
                    lexer.nextToken(); // {
                    parseEnumBody(lexer, en);
                    lexer.nextToken(); // }
                }
            }
            ProtoMessage mapEntry = new ProtoMessage();
            ProtoField f1 = new ProtoField(); f1.number = 1; mapEntry.fields.put(1, f1);
            ProtoField f2 = new ProtoField(); f2.number = 2; mapEntry.fields.put(2, f2);
            schema.mapEntryType = mapEntry;
            return schema;
        }

        private static void parseMessageBody(Lexer lexer, ProtoMessage msg, ProtoSchema schema) {
            while (lexer.hasNext()) {
                String token = lexer.peek();
                if (token.equals("}")) { lexer.nextToken(); break; }
                if (token.equals("message")) {
                    lexer.nextToken();
                    String name = lexer.nextToken();
                    ProtoMessage nested = new ProtoMessage();
                    schema.messages.put(name, nested);
                    lexer.nextToken(); parseMessageBody(lexer, nested, schema);
                } else if (token.equals("enum")) {
                    lexer.nextToken();
                    String name = lexer.nextToken();
                    ProtoEnum en = new ProtoEnum();
                    schema.enums.put(name, en);
                    lexer.nextToken(); parseEnumBody(lexer, en);
                } else if (token.equals("oneof")) {
                    lexer.nextToken();
                    String oneofName = lexer.nextToken();
                    lexer.nextToken(); // {
                    while (true) {
                        if (lexer.peek().equals("}")) { lexer.nextToken(); break; }
                        ProtoField f = parseField(lexer, true);
                        f.oneofName = oneofName;
                        msg.fields.put(f.number, f);
                        lexer.nextToken(); // ;
                    }
                    lexer.nextToken(); // ;
                } else if (token.equals("reserved")) {
                    lexer.nextToken();
                    while (!lexer.nextToken().equals(";"));
                } else if (token.equals("option")) {
                    lexer.nextToken();
                    while (!lexer.nextToken().equals(";"));
                } else {
                    String label = "";
                    if (token.equals("repeated") || token.equals("optional")) {
                        label = token;
                        lexer.nextToken();
                        token = lexer.nextToken();
                    } else {
                        lexer.nextToken();
                    }
                    ProtoField f = new ProtoField();
                    if (token.equals("map")) {
                        f.isMap = true;
                        lexer.nextToken(); // <
                        f.mapKeyType = lexer.nextToken().replace(",", "");
                        lexer.nextToken(); // ,
                        f.type = lexer.nextToken().replace(">", "");
                        lexer.nextToken(); // >
                    } else {
                        f.type = token;
                    }
                    f.name = lexer.nextToken();
                    lexer.nextToken(); // =
                    f.number = Integer.parseInt(lexer.nextToken().replace(";", ""));
                    if (label.equals("repeated")) f.isRepeated = true;
                    if (label.equals("optional")) f.isOptional = true;
                    while (lexer.hasNext() && !lexer.peek().equals(";")) {
                        if (lexer.peek().equals("[")) {
                            lexer.nextToken();
                            while (!lexer.nextToken().equals("]"));
                        } else {
                            lexer.nextToken();
                        }
                    }
                    if (lexer.hasNext()) lexer.nextToken(); // ;
                    msg.fields.put(f.number, f);
                }
            }
        }

        private static ProtoField parseField(Lexer lexer, boolean inOneof) {
            String token = lexer.nextToken();
            ProtoField f = new ProtoField();
            if (token.equals("map")) {
                f.isMap = true;
                lexer.nextToken(); f.mapKeyType = lexer.nextToken().replace(",", "");
                lexer.nextToken(); f.type = lexer.nextToken().replace(">", "");
                lexer.nextToken();
            } else {
                f.type = token;
            }
            f.name = lexer.nextToken();
            lexer.nextToken(); f.number = Integer.parseInt(lexer.nextToken().replace(";", ""));
            return f;
        }

        private static void parseEnumBody(Lexer lexer, ProtoEnum en) {
            while (lexer.hasNext()) {
                if (lexer.peek().equals("}")) break;
                String name = lexer.nextToken();
                lexer.nextToken(); // =
                int val = Integer.parseInt(lexer.nextToken().replace(";", ""));
                en.values.put(val, name);
                if (lexer.peek().equals(";")) lexer.nextToken();
            }
        }
    }

    static class Lexer {
        String input;
        int pos = 0;
        Lexer(String input) { this.input = input; }
        boolean hasNext() { return pos < input.length(); }
        String peek() {
            int start = pos;
            while (start < input.length() && Character.isWhitespace(input.charAt(start))) start++;
            if (start >= input.length()) return "";
            int end = start;
            if (input.charAt(end) == '"') {
                end++;
                while (end < input.length() && input.charAt(end) != '"') end++;
                end++;
            } else {
                while (end < input.length() && !Character.isWhitespace(input.charAt(end)) && "(){};,[]<>".indexOf(input.charAt(end)) == -1) end++;
            }
            return input.substring(start, end);
        }
        String nextToken() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
            if (pos >= input.length()) return "";
            int start = pos;
            if (input.charAt(pos) == '"') {
                pos++;
                while (pos < input.length() && input.charAt(pos) != '"') pos++;
                pos++;
                return input.substring(start, pos);
            } else if ("(){};,[]<>".indexOf(input.charAt(pos)) != -1) {
                pos++;
                return input.substring(start, pos);
            } else {
                while (pos < input.length() && !Character.isWhitespace(input.charAt(pos)) && "(){};,[]<>".indexOf(input.charAt(pos)) == -1) pos++;
                return input.substring(start, pos);
            }
        }
    }
}

import Foundation

// Utility to form-urlencode strings as per the requirements
func urlEncode(_ s: String) -> String {
    let allowed = CharacterSet(charactersIn: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._*")
    var result = ""
    for char in s {
        if let scalar = char.unicodeScalars.first, allowed.contains(scalar) {
            result.append(char)
        } else if char == " " {
            result.append("+")
        } else {
            for byte in String(char).utf8 {
                result.append(String(format: "%%%02X", byte))
            }
        }
    }
    return result
}

// Utility to percent-encode the cursor as per the requirements
func encodeCursor(_ cursor: String) -> String {
    let allowed = CharacterSet(charactersIn: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._*")
    var result = ""
    for char in cursor {
        if let scalar = char.unicodeScalars.first, allowed.contains(scalar) {
            result.append(char)
        } else {
            for byte in String(char).utf8 {
                result.append(String(format: "%%%02X", byte))
            }
        }
    }
    return result
}

// Utility to parse the amount decimal string to cents (Int64)
func parseAmount(_ s: String) -> Int64 {
    var currentS = s
    var sign: Int64 = 1
    if currentS.hasPrefix("-") {
        sign = -1
        currentS.removeFirst()
    }
    let parts = currentS.split(separator: ".", omittingEmptySubsequences: false)
    let integerPart = Int64(parts[0]) ?? 0
    var fractionalPart: Int64 = 0
    if parts.count > 1 {
        let fracS = String(parts[1])
        if fracS.count == 1 {
            fractionalPart = (Int64(fracS) ?? 0) * 10
        } else if fracS.count >= 2 {
            let fracS2 = String(fracS.prefix(2))
            fractionalPart = Int64(fracS2) ?? 0
        }
    }
    return sign * (integerPart * 100 + fractionalPart)
}

// Utility to format cents (Int64) back to a decimal string
func formatAmount(_ cents: Int64) -> String {
    let absCents = abs(cents)
    let integerPart = absCents / 100
    let fractionalPart = absCents % 100
    let sign = cents < 0 ? "-" : ""
    return String(format: "%@%d.%02d", sign, integerPart, fractionalPart)
}

// Main program logic
func main() {
    let args = CommandLine.arguments
    guard args.count >= 3 else { return }
    let dataDir = args[1]
    let baseUrl = args[2]

    let clientJsonPath = "\(dataDir)/client.json"
    guard let clientData = try? Data(contentsOf: URL(fileURLWithPath: clientJsonPath)),
          let clientSettings = try? JSONSerialization.jsonObject(with: clientData) as? [String: Any] else {
        return
    }

    let clientId = clientSettings["client_id"] as? String ?? ""
    let clientSecret = clientSettings["client_secret"] as? String ?? ""
    let scope = clientSettings["scope"] as? String ?? ""
    let pageSize = clientSettings["page_size"] as? Int ?? 0

    let session = URLSession.shared

    func getToken() -> String? {
        let tokenUrl = URL(string: "\(baseUrl)/oauth/token")!
        var request = URLRequest(url: tokenUrl)
        request.httpMethod = "POST"
        request.setValue("application/x-www-form-urlencoded", forHTTPHeaderField: "Content-Type")

        let encodedId = urlEncode(clientId)
        let encodedSecret = urlEncode(clientSecret)
        let authString = "\(encodedId):\(encodedSecret)"
        let authB64 = Data(authString.utf8).base64EncodedString()
        request.setValue("Basic \(authB64)", forHTTPHeaderField: "Authorization")

        let body = "grant_type=client_credentials&scope=\(urlEncode(scope))"
        request.httpBody = Data(body.utf8)

        var responseData: Data?
        var responseStatus: Int = 0

        let semaphore = DispatchSemaphore(value: 0)
        let task = session.dataTask(with: request) { data, response, error in
            responseData = data
            responseStatus = (response as? HTTPURLResponse)?.statusCode ?? 0
            semaphore.signal()
        }
        task.resume()
        semaphore.wait()

        if responseStatus == 200, let data = responseData,
           let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let accessToken = json["access_token"] as? String {
            return accessToken
        } else {
            let body = responseData != nil ? String(data: responseData!, encoding: .utf8)! : ""
            print("ERROR \(responseStatus) \(body)")
            exit(0)
        }
    }

    var token = getToken()!
    var isNewToken = true
    var cursor: String? = nil

    var totalOrdersCount = 0
    var totalPagesCount = 0
    var totalRetriesCount = 0
    var totalReauthCount = 0

    var customerTotals: [String: [String: Int64]] = [:] // name -> [currency: totalCents]
    var statusCounts: [String: Int] = [:]

    while true {
        var urlString = "\(baseUrl)/orders?limit=\(pageSize)"
        if let c = cursor {
            urlString += "&cursor=\(encodeCursor(c))"
        }

        let requestUrl = URL(string: urlString)!
        var request = URLRequest(url: requestUrl)
        request.httpMethod = "GET"
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")

        var responseData: Data?
        var responseStatus: Int = 0
        var responseHeaders: [AnyHashable: Any] = [:]

        let semaphore = DispatchSemaphore(value: 0)
        let task = session.dataTask(with: request) { data, response, error in
            responseData = data
            let httpResponse = response as? HTTPURLResponse
            responseStatus = httpResponse?.statusCode ?? 0
            responseHeaders = httpResponse?.allHeaderFields ?? [:]
            semaphore.signal()
        }
        task.resume()
        semaphore.wait()

        if responseStatus == 200 {
            totalPagesCount += 1
            isNewToken = false
            guard let data = responseData,
                  let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
                // Should not happen based on prompt
                continue
            }

            let orders = json["data"] as? [[String: Any]] ?? []
            for order in orders {
                totalOrdersCount += 1
                let status = order["status"] as? String ?? ""
                statusCounts[status, default: 0] += 1

                if status != "cancelled" {
                    let customer = order["customer"] as? [String: Any]
                    let name = customer?["name"] as? String ?? ""
                    let currency = order["currency"] as? String ?? ""
                    let amountStr = order["amount"] as? String ?? "0"
                    let cents = parseAmount(amountStr)

                    var currencies = customerTotals[name, default: [:]]
                    currencies[currency, default: 0] += cents
                    customerTotals[name] = currencies
                }
            }

            let nextCursor = json["next_cursor"] as? String
            cursor = nextCursor
            if nextCursor == nil {
                break
            }
        } else if responseStatus == 429 {
            totalRetriesCount += 1
            if let retryAfterStr = responseHeaders["Retry-After"] as? String,
               let retryAfter = Int(retryAfterStr) {
                Thread.sleep(forTimeInterval: TimeInterval(retryAfter))
            }
            continue
        } else if responseStatus == 503 {
            totalRetriesCount += 1
            Thread.sleep(forTimeInterval: 1.0)
            continue
        } else if responseStatus == 401 {
            if isNewToken {
                let body = responseData != nil ? String(data: responseData!, encoding: .utf8)! : ""
                print("ERROR \(responseStatus) \(body)")
                exit(0)
            }
            token = getToken()!
            totalReauthCount += 1
            isNewToken = true
            continue
        } else {
            let body = responseData != nil ? String(data: responseData!, encoding: .utf8)! : ""
            print("ERROR \(responseStatus) \(body)")
            exit(0)
        }
    }

    // Sorting and printing results
    let sortedNames = customerTotals.keys.sorted { a, b in
        let aBytes = Array(a.utf8)
        let bBytes = Array(b.utf8)
        for (ba, bb) in zip(aBytes, bBytes) {
            if ba < bb { return true }
            if ba > bb { return false }
        }
        return aBytes.count < bBytes.count
    }

    for name in sortedNames {
        let currencies = customerTotals[name]!
        let sortedCurrencies = currencies.keys.sorted()
        for curr in sortedCurrencies {
            let totalCents = currencies[curr]!
            print("total \(curr) \(formatAmount(totalCents)) \(name)")
        }
    }

    let sortedStatuses = statusCounts.keys.sorted()
    for status in sortedStatuses {
        print("status \(status) \(statusCounts[status]!)")
    }

    print("orders \(totalOrdersCount) pages \(totalPagesCount) retries \(totalRetriesCount) reauth \(totalReauthCount)")
}

