import * as fs from 'fs';
import * as http from 'http';
import * as url from 'url';

interface ClientConfig {
  client_id: string;
  client_secret: string;
  scope: string;
  page_size: number;
}

function rfc6749Encode(str: string): string {
  const buf = Buffer.from(str, 'utf8');
  let result = '';
  for (const byte of buf) {
    const char = String.fromCharCode(byte);
    if (/[a-zA-Z0-9\-._*]/.test(char)) {
      result += char;
    } else if (char === ' ') {
      result += '+';
    } else {
      result += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function parseAmountToCents(amountStr: string): bigint {
  const isNegative = amountStr.startsWith('-');
  const absStr = isNegative ? amountStr.slice(1) : amountStr;
  const [intPart, fracPart = ''] = absStr.split('.');
  let cents = BigInt(intPart) * 100n;
  if (fracPart.length === 1) {
    cents += BigInt(fracPart) * 10n;
  } else if (fracPart.length === 2) {
    cents += BigInt(fracPart);
  }
  return isNegative ? -cents : cents;
}

function formatCentsToDecimal(cents: bigint): string {
  const isNegative = cents < 0n;
  const absCents = isNegative ? -cents : cents;
  const intPart = absCents / 100n;
  const fracPart = absCents % 100n;
  return `${isNegative ? '-' : ''}${intPart}.${fracPart.toString().padStart(2, '0')}`;
}

function compareUtf8(a: string, b: string): number {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  const len = Math.min(bufA.length, bufB.length);
  for (let i = 0; i < len; i++) {
    if (bufA[i] !== bufB[i]) return bufA[i] - bufB[i];
  }
  return bufA.length - bufB.length;
}

async function makeRequest(options: http.RequestOptions, body?: string): Promise<{ status: number, headers: http.IncomingHttpHeaders, body: string }> {
  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        resolve({ status: res.statusCode, headers: res.headers, body: data });
      });
    });
    req.on('error', (e) => reject(e));
    if (body) req.write(body);
    req.end();
  });
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 2) return;
  const dataDir = args[0];
  const baseUrl = args[1];

  const clientConfig: ClientConfig = JSON.parse(fs.readFileSync(`${dataDir}/client.json`, 'utf8'));
  const parsedUrl = new URL(baseUrl);
  const host = parsedUrl.hostname;
  const port = parsedUrl.port || (parsedUrl.protocol === 'https:' ? '443' : '80');
  const basePath = parsedUrl.pathname;
  const hostHeader = `${host}:${port === '80' || port === '443' ? '' : port}`;

  async function getAccessToken() {
    const body = `grant_type=client_credentials&scope=${rfc6749Encode(clientConfig.scope)}`;
    const authStr = rfc6749Encode(clientConfig.client_id) + ':' + rfc6749Encode(clientConfig.client_secret);
    const authB64 = Buffer.from(authStr, 'utf8').toString('base64');

    const res = await makeRequest({
      hostname: host,
      port: parseInt(port),
      path: `${basePath}/oauth/token`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': `Basic ${authB64}`,
        'Host': hostHeader,
      },
    }, body);

    if (res.status !== 200) {
      process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
      process.exit(0);
    }
    return JSON.parse(res.body).access_token;
  }

  let accessToken = await getAccessToken();
  let tokenWasJustObtained = true;
  let reauthCount = 0;
  let retriesCount = 0;
  let pagesCount = 0;
  let ordersCount = 0;
  let cursor: string | null = null;

  const totalAmountMap = new Map<string, Map<string, bigint>>();
  const statusCounts = new Map<string, number>();

  while (true) {
    let urlPath = `${basePath}/orders?limit=${clientConfig.page_size}`;
    if (cursor) {
      urlPath += `&cursor=${encodeURIComponent(cursor)}`;
    }

    const res = await makeRequest({
      hostname: host,
      port: parseInt(port),
      path: urlPath,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Host': hostHeader,
      },
    });

    if (res.status === 429) {
      retriesCount++;
      const retryAfter = parseInt(res.headers['retry-after'] as string) || 0;
      await new Promise(r => setTimeout(r, retryAfter * 1000));
      continue;
    } else if (res.status === 503) {
      retriesCount++;
      await new Promise(r => setTimeout(r, 1000));
      continue;
    } else if (res.status === 401) {
      if (tokenWasJustObtained) {
        process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
        process.exit(0);
      }
      accessToken = await getAccessToken();
      reauthCount++;
      tokenWasJustObtained = true;
      continue;
    } else if (res.status === 200) {
      tokenWasJustObtained = false;
      pagesCount++;
      const json = JSON.parse(res.body);
      const data = json.data || [];
      for (const order of data) {
        ordersCount++;
        const status = order.status;
        statusCounts.set(status, (statusCounts.get(status) || 0) + 1);
        if (status !== 'cancelled') {
          const name = order.customer?.name;
          const currency = order.currency;
          if (name && currency) {
            if (!totalAmountMap.has(name)) totalAmountMap.set(name, new Map());
            const currencyMap = totalAmountMap.get(name)!;
            const cents = parseAmountToCents(order.amount);
            currencyMap.set(currency, (currencyMap.get(currency) || 0n) + cents);
          }
        }
      }
      cursor = json.next_cursor;
      if (cursor === null) break;
    } else {
      process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
      process.exit(0);
    }
  }

  const sortedNames = Array.from(totalAmountMap.keys()).sort(compareUtf8);
  for (const name of sortedNames) {
    const currencyMap = totalAmountMap.get(name)!;
    const sortedCurrencies = Array.from(currencyMap.keys()).sort();
    for (const currency of sortedCurrencies) {
      const amountCents = currencyMap.get(currency)!;
      process.stdout.write(`total ${currency} ${formatCentsToDecimal(amountCents)} ${name}\n`);
    }
  }

  const sortedStatuses = Array.from(statusCounts.keys()).sort();
  for (const status of sortedStatuses) {
    process.stdout.write(`status ${status} ${statusCounts.get(status)}\n`);
  }

  process.stdout.write(`orders ${ordersCount} pages ${pagesCount} retries ${retriesCount} reauth ${reauthCount}\n`);
}

