typedef struct {
    char *s;
    int pos;
} Lexer;

char *lexer_next_token(Lexer *l) {
    while (l->s[l->pos] && (isspace(l->s[l->pos]))) l->pos++;
    if (!l->s[l->pos]) return NULL;
    if (l->s[l->pos] == '/' && l->s[l->pos + 1] == '/') {
        while (l->s[l->pos] && l->s[l->pos] != '\n') l->pos++;
        return lexer_next_token(l);
    }
    if (l->s[l->pos] == '/' && l->s[l->pos + 1] == '*') {
        l->pos += 2;
        while (l->s[l->pos] && !(l->s[l->pos] == '*' && l->s[l->pos + 1] == '/')) l->pos++;
        l->pos += 2;
        return lexer_next_token(l);
    }
    int start = l->pos;
    if (l->s[l->pos] == '"') {
        l->pos++;
        while (l->s[l->pos] && l->s[l->pos] != '"') l->pos++;
        l->pos++;
        char *res = strndup(&l->s[start + 1], l->pos - start - 2);
        return res;
    }
    while (l->s[l->pos] && (isalnum(l->s[l->pos]) || l->s[l->pos] == '_')) l->pos++;
    if (l->pos == start) {
        char *res = strndup(&l->s[l->pos], 1);
        l->pos++;
        return res;
    }
    return strndup(&l->s[start], l->pos - start);
}

typedef struct {
    Lexer *lexer;
    char *curr;
} Parser;

char *parser_next(Parser *p) {
    if (p->curr) free(p->curr);
    p->curr = lexer_next_token(p->lexer);
    return p->curr;
}

bool parser_match(Parser *p, const char *s) {
    if (!p->curr || strcmp(p->curr, s) != 0) return false;
    parser_next(p);
    return true;
}

