    if (strcmp(s, "uint64") == 0) return T_UINT64;
    if (strcmp(s, "sint32") == 0) return T_SINT32;
    if (strcmp(s, "sint64") == 0) return T_SINT64;
    if (strcmp(s, "bool") == 0) return T_BOOL;
    if (strcmp(s, "string") == 0) return T_STRING;
    if (strcmp(s, "bytes") == 0) return T_BYTES;
    if (strcmp(s, "fixed32") == 0) return T_FIXED32;
    if (strcmp(s, "fixed64") == 0) return T_FIXED64;
    if (strcmp(s, "sfixed32") == 0) return T_SFIXED32;
