void parse_proto(Parser *p) {
    while (p->curr) {
        if (parser_match(p, "syntax")) {
            parser_next(p); parser_next(p); parser_next(p); parser_next(p);
        } else if (parser_match(p, "package")) {
            while (!parser_match(p, ";")) parser_next(p);
        } else if (parser_match(p, "option")) {
            while (!parser_match(p, ";")) parser_next(p);
        } else if (parser_match(p, "message")) {
            // We need to launder the "message" token back.
            // Since we already consumed it, let's just call a modified parse_message.
            // Or just call parse_message and handle the "message" token.
            // Let's just launder it:
            p->curr = "message";
            parse_message(p);
        } else if (parser_match(p, "enum")) {
            p->curr = "enum";
            parse_enum(p);
        } else {
            parser_next(p);
        }
    }
}

