uint64_t read_varint(const uint8_t **data, const uint8_t *end) {
    uint64_t val = 0;
    int shift = 0;
    while (*data < end) {
        uint8_t b = **data;
        (*data)++;
        val |= (uint64_t)(b & 0x7F) << shift;
        if (!(b & 0x80)) break;
        shift += 7;
    }
    return val;
}

int64_t decode_zigzag(uint64_t n) {
    return (n >> 1) ^ -(int64_t)(n & 1);
}

