// --- Lexer & Parser ---

typedef struct {
    const char *s;
    int pos;
} Lexer;

char *lexer_next_token(Lexer *l) {
    while (l->s[l->pos] && (isspace(l->s[l->pos]))) l->pos++;
    if (!l->s[l->pos]) return NULL;
    if (l->s[l->pos] == '/' && l->s[l->pos + 1] == '/') {
        while (l->s[l->pos] && l->s[l->pos] != '\n') l->pos++;
        return lexer_next_token(l);
    }
    if (l->s[l->pos] == '/' && l->s[l->pos + 1] == '*') {
        l->pos += 2;
        while (l->s[l->pos] && !(l->s[l->pos] == '*' && l->s[l->pos + 1] == '/')) l->pos++;
        l->pos += 2;
        return lexer_next_token(l);
    }
    int start = l->pos;
    if (l->s[l->pos] == '"') {
        l->pos++;
        while (l->s[l->pos] && l->s[l->pos] != '"') l->pos++;
        if (l->s[l->pos]) l->pos++;
        int len = l->pos - start - 2;
        if (len < 0) len = 0;
        char *res = malloc(len + 1);
        memcpy(res, &l->s[start + 1], len);
        res[len] = '\0';
        return res;
    }
    if (strchr("(){}[],;=<>", l->s[l->pos])) {
        char *res = malloc(2);
        res[0] = l->s[l->pos++];
        res[1] = '\0';
        return res;
    }
    while (l->s[l->pos] && (isalnum(l->s[l->pos]) || l->s[l->pos] == '_')) l->pos++;
    int len = l->pos - start;
    char *res = malloc(len + 1);
    memcpy(res, &l->s[start], len);
    res[len] = '\0';
    return res;
}

typedef struct {
    Lexer *lexer;
    char *curr;
} Parser;

char *parser_next(Parser *p) {
    if (p->curr) free(p->curr);
    p->curr = lexer_next_token(p->lexer);
    return p->curr;
}

bool parser_match(Parser *p, const char *s) {
    if (!p->curr || strcmp(p->curr, s) != 0) return false;
    parser_next(p);
    return true;
}

TypeKind get_type_kind(const char *s) {
    if (strcmp(s, "int32") == 0) return T_INT32;
    if (strcmp(s, "int64") == 0) return T_INT64;
    if (strcmp(s, "uint32") == 0) return T_UINT32;
    if (strcmp(s, "uint64") == 0) return T_UINT64;
    if (strcmp(s, "sint32") == 0) return T_SINT32;
    if (strcmp(s, "sint64") == 0) return T_SINT64;
    if (strcmp(s, "bool") == 0) return T_BOOL;
    if (strcmp(s, "string") == 0) return T_STRING;
    if (strcmp(s, "bytes") == 0) return T_BYTES;
    if (strcmp(s, "fixed32") == 0) return T_FIXED32;
    if (strcmp(s, "fixed64") == 0) return T_FIXED64;
    if (strcmp(s, "sfixed32") == 0) return T_SFIXED32;
    if (strcmp(s, "sfixed64") == 0) return T_SFIXED64;
    return (TypeKind)0;
}

Message *find_msg(const char *name) {
    for (int i = 0; i < schema.num_messages; i++) if (strcmp(schema.messages[i]->name, name) == 0) return schema.messages[i];
    return NULL;
}

Enum *find_enum(const char *name) {
    for (int i = 0; i < schema.num_enums; i++) if (strcmp(schema.enums[i]->name, name) == 0) return schema.enums[i];
    return NULL;
}

void resolve_field_type(Field *f, const char *type_name) {
    TypeKind tk = get_type_kind(type_name);
    if (tk != (TypeKind)0) {
        f->kind = tk;
    } else {
        Enum *en = find_enum(type_name);
        if (en) { f->kind = T_ENUM; f->enum_type = en; }
        else { f->kind = T_MESSAGE; f->msg_type = find_msg(type_name); }
    }
}

void parse_proto(Parser *p) {
    while (p->curr) {
        if (parser_match(p, "syntax")) {
            while (!parser_match(p, ";")) parser_next(p);
        } else if (parser_match(p, "package")) {
            while (!parser_match(p, ";")) parser_next(p);
        } else if (parser_match(p, "option")) {
            while (!parser_match(p, ";")) parser_next(p);
        } else if (parser_match(p, "enum")) {
            char *name = parser_next(p);
            Enum *e = calloc(1, sizeof(Enum));
            e->name = name;
            parser_next(p); // {
            while (!parser_match(p, "}")) {
                char *vn = parser_next(p);
                parser_next(p); // =
                char *vs = parser_next(p);
                int v = atoi(vs);
                free(vs);
                e->num_values++;
                e->values = realloc(e->values, sizeof(int) * e->num_values);
                e->value_names = realloc(e->value_names, sizeof(char *) * e->num_values);
                e->values[e->num_values - 1] = v;
                e->value_names[e->num_values - 1] = vn;
                parser_next(p); // ;
                if (parser_match(p, "[")) while (!parser_match(p, "]")) parser_next(p);
                if (p->curr && strcmp(p->curr, ";") == 0) parser_next(p);
            }
            schema.num_enums++;
            schema.enums = realloc(schema.enums, sizeof(Enum *) * schema.num_enums);
            schema.enums[schema.num_enums - 1] = e;
            if (p->curr && strcmp(p->curr, ";") == 0) parser_next(p);
        } else if (parser_match(p, "message")) {
            char *name = parser_next(p);
            Message *m = calloc(1, sizeof(Message));
            m->name = name;
            parser_next(p); // {
            while (!parser_match(p, "}")) {
                if (parser_match(p, "repeated")) {
                    char *t_name = parser_next(p);
                    char *f_name = parser_next(p);
                    parser_next(p); // =
                    int num = atoi(parser_next(p));
                    m->num_fields++;
                    m->fields = realloc(m->fields, sizeof(Field) * m->num_fields);
                    Field *f = &m->fields[m->num_fields - 1];
                    f->number = num; f->name = f_name; f->repeated = true; f->optional = false; f->is_map = false; f->oneof_id = -1;
                    resolve_field_type(f, t_name);
                    parser_next(p); // ;
                    if (parser_match(p, "[")) while (!parser_match(p, "]")) parser_next(p);
                    if (p->curr && strcmp(p->curr, ";") == 0) parser_next(p);
                } else if (parser_match(p, "optional")) {
                    char *t_name = parser_next(p);
                    char *f_name = parser_next(p);
                    parser_next(p); // =
                    int num = atoi(parser_next(p));
                    m->num_fields++;
                    m->fields = realloc(m->fields, sizeof(Field) * m->num_fields);
                    Field *f = &m->fields[m->num_fields - 1];
                    f->number = num; f->name = f_name; f->repeated = false; f->optional = true; f->is_map = false; f->oneof_id = -1;
                    resolve_field_type(f, t_name);
                    parser_next(p); // ;
                    if (parser_match(p, "[")) while (!parser_match(p, "]")) parser_next(p);
                    if (p->curr && strcmp(p->curr, ";") == 0) parser_next(p);
                } else if (parser_match(p, "map")) {
                    parser_next(p); // <
                    char *kt_name = parser_next(p);
                    parser_next(p); // ,
                    char *vt_name = parser_next(p);
                    parser_next(p); // >
                    char *f_name = parser_next(p);
                    parser_next(p); // =
                    int num = atoi(parser_next(p));
                    m->num_fields++;
                    m->fields = realloc(m->fields, sizeof(Field) * m->num_fields);
                    Field *f = &m->fields[m->num_fields - 1];
                    f->number = num; f->name = f_name; f->repeated = false; f->optional = false; f->is_map = true; f->oneof_id = -1;
                    f->map_key_kind = get_type_kind(kt_name);
                    f->map_val_kind = get_type_kind(vt_name);
                    if (f->map_val_kind == (TypeKind)0) {
                        f->map_val_kind = T_MESSAGE;
                        f->map_val_msg = find_msg(vt_name);
                        Enum *en = find_enum(vt_name);
                        if (en) { f->map_val_kind = T_ENUM; f->map_val_enum = en; }
                    }
                    parser_next(p); // ;
                    if (parser_match(p, "[")) while (!parser_match(p, "]")) parser_next(p);
                    if (p->curr && strcmp(p->curr, ";") == 0) parser_next(p);
                } else if (parser_match(p, "oneof")) {
                    char *oname = parser_next(p);
                    m->num_oneofs++;
                    parser_next(p); // {
                    while (!parser_match(p, "}")) {
                        char *t_name = parser_next(p);
                        char *f_name = parser_next(p);
                        parser_next(p); // =
                        int num = atoi(parser_next(p));
                        m->num_fields++;
                        m->fields = realloc(m->fields, sizeof(Field) * m->num_fields);
                        Field *f = &m->fields[m->num_fields - 1];
                        f->number = num; f->name = f_name; f->repeated = false; f->optional = false; f->is_map = false; f->oneof_id = m->num_oneofs;
                        resolve_field_type(f, t_name);
                        parser_next(p); // ;
                    }
                    if (p->curr && strcmp(p->curr, ";") == 0) parser_next(p);
                } else if (parser_match(p, "reserved")) {
                    while (!parser_match(p, ";")) parser_next(p);
                } else if (parser_match(p, "message")) {
                    // Handled by the main loop
                } else if (parser_match(p, "enum")) {
                    // Handled by the main loop
                } else {
                    parser_next(p);
                }
            }
            if (p->curr && strcmp(p->curr, ";") == 0) parser_next(p);
            schema.num_messages++;
            schema.messages = realloc(schema.messages, sizeof(Message *) * schema.num_messages);
            schema.messages[schema.num_messages - 1] = m;
            if (!root_type) root_type = m;
        } else {
            parser_next(p);
        }
    }
}

// --- Protobuf Decoder ---

uint64_t read_varint(const uint8_t **data, const uint8_t *end) {
    uint64_t res = 0;
    int shift = 0;
    while (*data < end) {
        uint8_t b = **data;
        (*data)++;
        res |= (uint64_t)(b & 0x7f) << shift;
        if (!(b & 0x80)) break;
        shift += 7;
        if (shift >= 64) break;
    }
    return res;
}

int64_t decode_zigzag(uint64_t n) {
    return (n >> 1) ^ -(int64_t)(n & 1);
}

uint32_t read_u32(const uint8_t **data) {
    uint32_t res = 0;
    for (int i = 0; i < 4; i++) res |= (uint32_t)(*(*data)++) << (8 * i);
    return res;
}

uint64_t read_u64(const uint8_t **data) {
    uint64_t res = 0;
    for (int i = 0; i < 8; i++) res |= (uint64_t)(*(*data)++) << (8 * i);
    return res;
}

