// Simplified Value handling for this specific task.
void decode_message(Message *m, const uint8_t **data, const uint8_t *end, Value *v) {
    while (*data < end) {
        uint64_t key = read_varint(data, end);
        int field_num = key >> 3;
        int wire_type = key & 0x7;
        Field *f = NULL;
        for (int i = 0; i < m->num_fields; i++) if (m->fields[i].number == field_num) { f = &m->fields[i]; break; }
        if (!f) {
            if (wire_type == 0) read_varint(data, end);
            else if (wire_type == 1) *data += 8;
            else if (wire_type == 2) {
                uint64_t len = read_varint(data, end);
                *data += len;
            } else if (wire_type == 5) *data += 4;
            else if (wire_type == 3) {
                uint64_t fn = (key >> 3);
                while (*data < end) {
                    uint64_t k2 = read_varint(data, end);
                    if ((k2 >> 3) == fn && (k2 & 0x7) == 4) { (*data)++; break; }
                    // This is a simplification; groups can be nested.
                }
            }
            continue;
        }
        // Handle field
        if (f->kind == T_INT32 || f->kind == T_UINT32 || f->kind == T_SINT32 || f->kind == T_BOOL || f->kind == T_ENUM) {
            uint64_t val = read_varint(data, end);
            if (f->kind == T_SINT32) val = decode_zigzag(val);
            if (f->repeated) {
                if (wire_type == 2) {
                    uint64_t len = read_varint(data, end);
                    const uint8_t *limit = *data + len;
                    while (*data < limit) {
                        uint64_t pv = read_varint(data, limit);
                        if (f->kind == T_SINT32) pv = decode_zigzag(pv);
                        if (v->repeated.capacity <= v->repeated.count) {
                            v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                            v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                        }
                        Value *nv = calloc(1, sizeof(Value));
                        nv->is_set = true; nv->scalar = pv;
                        v->repeated.elems[v->repeated.count++] = nv;
                    }
                    *data = limit;
                } else {
                    if (v->repeated.capacity <= v->repeated.count) {
                        v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                        v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                    }
                    Value *nv = calloc(1, sizeof(Value));
                    nv->is_set = true; nv->scalar = val;
                    v->repeated.elems[v->repeated.count++] = nv;
                }
            } else {
                v->scalar = val; v->is_set = true;
            }
        } else if (f->kind == T_INT64 || f->kind == T_UINT64 || f->kind == T_SINT64) {
            uint64_t val = read_varint(data, end);
            if (f->kind == T_SINT64) val = decode_zigzag(val);
            if (f->repeated) {
                if (wire_type == 2) {
                    uint64_t len = read_varint(data, end);
                    const uint8_t *limit = *data + len;
                    while (*data < limit) {
                        uint64_t pv = read_varint(data, limit);
                        if (f->kind == T_SINT64) pv = decode_zigzag(pv);
                        if (v->repeated.capacity <= v->repeated.count) {
                            v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                            v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                        }
                        Value *nv = calloc(1, sizeof(Value));
                        nv->is_set = true; nv->scalar = pv;
                        v->repeated.elems[v->repeated.count++] = nv;
                    }
                    *data = limit;
                } else {
                    if (v->repeated.capacity <= v->repeated.count) {
                        v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                        v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                    }
                    Value *nv = calloc(1, sizeof(Value));
                    nv->is_set = true; nv->scalar = val;
                    v->repeated.elems[v->repeated.count++] = nv;
                }
            } else {
                v->scalar = val; v->is_set = true;
            }
        } else if (f->kind == T_FIXED32 || f->kind == T_SFIXED32) {
            uint32_t val = read_u32(data);
            if (f->repeated) {
                if (v->repeated.capacity <= v->repeated.count) {
                    v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                    v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                }
                Value *nv = calloc(1, sizeof(Value));
                nv->is_set = true; nv->scalar = val;
                v->repeated.elems[v->repeated.count++] = nv;
            } else {
                v->scalar = val; v->is_set = true;
            }
        } else if (f->kind == T_FIXED64 || f->kind == T_SFIXED64) {
            uint64_t val = read_u64(data);
            if (f->repeated) {
                if (v->repeated.capacity <= v->repeated.count) {
                    v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                    v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                }
                Value *nv = calloc(1, sizeof(Value));
                nv->is_set = true; nv->scalar = val;
                v->repeated.elems[v->repeated.count++] = nv;
            } else {
                v->scalar = val; v->is_set = true;
            }
        } else if (f->kind == T_STRING || f->kind == T_BYTES) {
            uint64_t len = read_varint(data, end);
            char *s = malloc(len + 1);
            memcpy(s, *data, len);
            s[len] = '\0';
            *data += len;
            if (f->repeated) {
                if (v->repeated.capacity <= v->repeated.count) {
                    v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                    v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                }
                Value *nv = calloc(1, sizeof(Value));
                nv->is_set = true; nv->bytes.s = s; nv->bytes.len = len;
                v->repeated.elems[v->repeated.count++] = nv;
            } else {
                if (v->bytes.s) free(v->bytes.s);
                v->bytes.s = s; v->bytes.len = len; v->is_set = true;
            }
        } else if (f->kind == T_MESSAGE) {
            uint64_t len = read_varint(data, end);
            const uint8_t *limit = *data + len;
            if (f->repeated) {
                if (v->repeated.capacity <= v->repeated.count) {
                    v->repeated.capacity = v->repeated.capacity ? v->repeated.capacity * 2 : 2;
                    v->repeated.elems = realloc(v->repeated.elems, sizeof(Value *) * v->repeated.capacity);
                }
                Value *nv = calloc(1, sizeof(Value));
                nv->is_set = true;
                nv->message = calloc(f->msg_type->num_fields, sizeof(Value));
                decode_message(f->msg_type, data, limit, nv->message);
                v->repeated.elems[v->repeated.count++] = nv;
            } else {
                if (v->message) {
                    // Merge
                    decode_message(f->msg_type, data, limit, v->message);
                } else {
                    v->message = calloc(f->msg_type->num_fields, sizeof(Value));
                    decode_message(f->msg_type, data, limit, v->message);
                }
                v->is_set = true;
            }
            *data = limit;
        } else if (f->is_map) {
            uint64_t len = read_varint(data, end);
            const uint8_t *limit = *data + len;
            // Map is an embedded message with field 1 (key) and field 2 (value)
            Value map_entry_val[2] = {0};
            // We need a temporary message schema for the map entry
            Message map_entry_schema;
            map_entry_schema.num_fields = 2;
            map_entry_schema.fields = malloc(sizeof(Field) * 2);
            map_entry_schema.fields[0].number = 1;
            map_entry_schema.fields[0].kind = f->map_key_kind;
            map_entry_schema.fields[0].repeated = false;
            map_entry_schema.fields[0].optional = false;
            map_entry_schema.fields[0].is_map = false;
            map_entry_schema.fields[1].number = 2;
            map_entry_schema.fields[1].kind = f->map_val_kind;
            map_entry_schema.fields[1].enum_type = f->map_val_enum;
            map_entry_schema.fields[1].msg_type = f->map_val_msg;
            map_entry_schema.fields[1].repeated = false;
            map_entry_schema.fields[1].optional = false;
            map_entry_schema.fields[1].is_map = false;

            // Use a temporary Value array for the map entry
            Value *temp_vals = calloc(2, sizeof(Value));
            // This is a hack; we need a real decoder for the map entry
            // Let's just reuse the logic:
            const uint8_t *entry_data = *data;
            while (entry_data < limit) {
                uint64_t key = read_varint(&entry_data, limit);
                int fn = key >> 3;
                int wt = key & 0x7;
                if (fn == 1) {
                    if (f->map_key_kind == T_STRING || f->map_key_kind == T_BYTES) {
                        uint64_t len_s = read_varint(&entry_data, limit);
                        temp_vals[0].bytes.s = malloc(len_s + 1);
                        memcpy(temp_vals[0].bytes.s, entry_data, len_s);
                        temp_vals[0].bytes.s[len_s] = '\0';
                        temp_vals[0].bytes.len = len_s;
                        temp_vals[0].is_set = true;
                        entry_data += len_s;
                    } else {
                        temp_vals[0].scalar = read_varint(&entry_data, limit);
                        temp_vals[0].is_set = true;
                    }
                } else if (fn == 2) {
                    Field *vf = &map_entry_schema.fields[1];
                    if (vf->kind == T_INT32 || vf->kind == T_UINT32 || vf->kind == T_SINT32 || vf->kind == T_BOOL || vf->kind == T_ENUM) {
                        temp_vals[1].scalar = read_varint(&entry_data, limit);
                        temp_vals[1].is_set = true;
                    } else if (vf->kind == T_INT64 || vf->kind == T_UINT64 || vf->kind == T_SINT64) {
                        temp_vals[1].scalar = read_varint(&entry_data, limit);
                        temp_vals[1].is_set = true;
                    } else if (vf->kind == T_FIXED32 || vf->kind == T_SFIXED32) {
                        temp_vals[1].scalar = read_u32(&entry_data);
                        temp_vals[1].is_set = true;
                    } else if (vf->kind == T_FIXED64 || vf->kind == T_SFIXED64) {
                        temp_vals[1].scalar = read_u64(&entry_data);
                        temp_vals[1].is_set = true;
                    } else if (vf->kind == T_STRING || vf->kind == T_BYTES) {
                        uint64_t len_s = read_varint(&entry_data, limit);
                        temp_vals[1].bytes.s = malloc(len_s + 1);
                        memcpy(temp_vals[1].bytes.s, entry_data, len_s);
                        temp_vals[1].bytes.s[len_s] = '\0';
                        temp_vals[1].bytes.len = len_s;
                        temp_vals[1].is_set = true;
                        entry_data += len_s;
                    } else if (vf->kind == T_MESSAGE) {
                        uint64_t len_s = read_varint(&entry_data, limit);
                        const uint8_t *msg_limit = entry_data + len_s;
                        temp_vals[1].message = calloc(vf->msg_type->num_fields, sizeof(Value));
                        decode_message(vf->msg_type, &entry_data, msg_limit, temp_vals[1].message);
                        temp_vals[1].is_set = true;
                        entry_data = msg_limit;
                    }
                } else {
                    // Skip unknown
                    if (wt == 0) read_varint(&entry_data, limit);
                    else if (wt == 1) entry_data += 8;
                    else if (wt == 2) { uint64_t l = read_varint(&entry_data, limit); entry_data += l; }
                    else if (wt == 5) entry_data += 4;
                }
            }
            // Add to map
            if (v->map.capacity <= v->map.count) {
                v->map.capacity = v->map.capacity ? v->map.capacity * 2 : 2;
                v->map.entries = realloc(v->map.entries, sizeof(MapEntry) * v->map.capacity);
            }
            // Check for duplicate key
            bool found = false;
            for (int i = 0; i < v->map.count; i++) {
                if (f->map_key_kind == T_STRING) {
                    if (strcmp(v->map.entries[i].key.bytes.s, temp_vals[0].bytes.s) == 0) {
                        // Replace value
                        // Free old value
                        v->map.entries[i].val = temp_vals[1];
                        found = true; break;
                    }
                } else {
                    if (v->map.entries[i].key.scalar == temp_vals[0].scalar) {
                        v->map.entries[i].val = temp_vals[1];
                        found = true; break;
                    }
                }
            }
            if (!found) {
                v->map.entries[v->map.count].key = temp_vals[0];
                v->map.entries[v->map.count].val = temp_vals[1];
                v->map.count++;
            }
            free(temp_vals);
            free(map_entry_schema.fields);
            *data = limit;
        }
    }
}

// --- JSON Output ---

void print_camel_case(const char *s) {
    for (int i = 0; s[i]; i++) {
        if (s[i] == '_') {
            if (s[i + 1] >= 'a' && s[i + 1] <= 'z') {
                putchar(s[i + 1] - 'a' + 'A');
                i++;
            }
        } else {
            putchar(s[i]);
        }
    }
}

void print_json_string(const char *s, size_t len) {
    printf("\"");
    for (size_t i = 0; i < len; i++) {
        if (s[i] == '"') printf("\\\"");
        else if (s[i] == '\\') printf("\\\\");
        else if (s[i] == '\b') printf("\\b");
        else if (s[i] == '\t') printf("\\t");
        else if (s[i] == '\n') printf("\\n");
        else if (s[i] == '\f') printf("\\f");
        else if (s[i] == '\r') printf("\\r");
        else if ((unsigned char)s[i] < 0x20) printf("\\u%02x", (unsigned char)s[i]);
        else printf("%c", s[i]);
    }
    printf("\"");
}

void print_base64(const uint8_t *data, size_t len) {
    static const char b64_table[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    printf("\"");
    for (size_t i = 0; i < len; i += 3) {
        uint32_t val = (data[i] << 16);
        if (i + 1 < len) val |= (data[i + 1] << 8);
        if (i + 2 < len) val |= data[i + 2];
        putchar(b64_table[(val >> 18) & 0x3F]);
        putchar(b64_table[(val >> 12) & 0x3F]);
        putchar(i + 1 < len ? b64_table[(val >> 6) & 0x3F] : '=');
        putchar(i + 2 < len ? b64_table[val & 0x3F] : '=');
    }
    printf("\"");
}

void print_val(Value *v, Field *f);

void print_msg(Value *v, Message *m) {
    printf("{");
    bool first = true;
    for (int i = 0; i < m->num_fields; i++) {
        Field *f = &m->fields[i];
        Value *fv = &v->message[i];
        // Presence rules
        bool print = false;
        if (f->repeated || f->is_map) {
            if (fv->is_set && (f->repeated ? fv->repeated.count > 0 : fv->map.count > 0)) print = true;
        } else if (f->kind == T_MESSAGE) {
            if (fv->is_set) print = true;
        } else {
            if (f->optional || f->oneof_id != -1) {
                if (fv->is_set) print = true;
            } else {
                // Default value check
                bool is_default = true;
                if (f->kind == T_STRING || f->kind == T_BYTES) {
                    if (fv->bytes.len != 0) is_default = false;
                } else if (f->kind == T_ENUM) {
                    if (fv->scalar != 0) is_default = false;
                } else {
                    if (fv->scalar != 0) is_default = false;
                }
                if (!is_default) print = true;
            }
        }
        if (print) {
            if (!first) putchar(',');
            print_camel_case(f->name);
            printf(":");
            print_val(fv, f);
            first = false;
        }
    }
    printf("}");
}

void print_val(Value *v, Field *f) {
    if (f->kind == T_INT32 || f->kind == T_UINT32 || f->kind == T_SINT32 || f->kind == T_BOOL || f->kind == T_FIXED32 || f->kind == T_SFIXED32) {
        if (f->kind == T_BOOL) printf("%s", v->scalar ? "true" : "false");
        else printf("%lld", (long long)v->scalar);
    } else if (f->kind == T_INT64 || f->kind == T_UINT64 || f->kind == T_SINT64 || f->kind == T_FIXED64 || f->kind == T_SFIXED64) {
        printf("\"%lld\"", (long long)v->scalar);
    } else if (f->kind == T_STRING) {
        print_json_string(v->bytes.s, v->bytes.len);
    } else if (f->kind == T_BYTES) {
        print_base64((uint8_t *)v->bytes.s, v->bytes.len);
    } else if (f->kind == T_ENUM) {
        Enum *e = f->enum_type;
        bool found = false;
        for (int i = 0; i < e->num_values; i++) {
            if (e->values[i] == v->scalar) {
                printf("\"%s\"", e->value_names[i]);
                found = true; break;
            }
        }
        if (!found) printf("%lld", (long long)v->scalar);
    } else if (f->kind == T_MESSAGE) {
        print_msg(v, f->msg_type);
    } else if (f->repeated) {
        printf("[");
        for (int i = 0; i < v->repeated.count; i++) {
            if (i > 0) putchar(',');
            print_val(v->repeated.elems[i], f);
        }
        printf("]");
    } else if (f->is_map) {
        printf("{");
        // Sort map entries
        int count = v->map.count;
        MapEntry *sorted = malloc(sizeof(MapEntry) * count);
        memcpy(sorted, v->map.entries, sizeof(MapEntry) * count);

        if (f->map_key_kind == T_STRING) {
            // Simple bubble sort for string keys
            for (int i = 0; i < count - 1; i++) {
                for (int j = 0; j < count - i - 1; j++) {
                    if (strcmp(sorted[j].key.bytes.s, sorted[j+1].key.bytes.s) > 0) {
                        MapEntry tmp = sorted[j]; sorted[j] = sorted[j+1]; sorted[j+1] = tmp;
                    }
                }
            }
        } else {
            // Sort numerically
            for (int i = 0; i < count - 1; i++) {
                for (int j = 0; j < count - i - 1; j++) {
                    if (sorted[j].key.scalar > sorted[j+1].key.scalar) {
                        MapEntry tmp = sorted[j]; sorted[j] = sorted[j+1]; sorted[j+1] = tmp;
                    }
                }
            }
        }
        for (int i = 0; i < count; i++) {
            if (i > 0) putchar(',');
            if (f->map_key_kind == T_STRING) print_json_string(sorted[i].key.bytes.s, sorted[i].key.bytes.len);
            else printf("\"%lld\"", (long long)sorted[i].key.scalar);
            printf(":");
            // Need the map value field for print_val
            Field map_val_f = {0};
            map_val_f.kind = f->map_val_kind;
            map_val_f.enum_type = f->map_val_enum;
            map_val_f.msg_type = f->map_val_msg;
            print_val(&sorted[i].val, &map_val_f);
        }
        printf("}");
        free(sorted);
    }
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    char path[1024];
    sprintf(path, "%s/schema.proto", argv[1]);
    FILE *fp = fopen(path, "r");
    if (!fp) return 0;
    fseek(fp, 0, SEEK_END);
    long len = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *buf = malloc(len + 1);
    fread(buf, 1, len, fp);
    buf[len] = 0;
    fclose(fp);

    Lexer lex = {buf, 0};
    Parser p = {&lex, NULL};
    parse_proto(&p);
    free(buf);

    char path_bin[1024];
    sprintf(path_bin, "%s/messages.bin", argv[1]);
    fp = fopen(path_bin, "rb");
    if (!fp) return 0;

    uint8_t bin_buf[100000];
    while (true) {
        uint8_t varint_buf[10];
        if (fread(varint_buf, 1, 1, fp) != 1) break;
        const uint8_t *p_var = varint_buf;
        const uint8_t *p_end = varint_buf + 1;
        // Since the length is a varint, we might need more bytes.
        // This is a simplification; real varints can be up to 10 bytes.
        // Let's just read one byte and then read the rest of the varint.
        uint64_t record_len = 0;
        int shift = 0;
        uint8_t b = varint_buf[0];
        record_len = b & 0x7f;
        while (b & 0x80) {
            fread(varint_buf, 1, 1, fp);
            b = varint_buf[0];
            shift += 7;
            record_len |= (uint64_t)(b & 0x7f) << shift;
        }

        uint8_t *data = malloc(record_len);
        fread(data, 1, record_len, fp);
        const uint8_t *p_data = data;
        const uint8_t *p_limit = data + record_len;

        Value *root_val = calloc(root_type->num_fields, sizeof(Value));
        decode_message(root_type, &p_data, p_limit, root_val);

        // Create a dummy Value to pass to print_msg
        Value root_v;
        root_v.message = root_val;
        print_msg(&root_v, root_type);
        putchar('\n');

        // Cleanup
        // (Simplification: only free root_val array)
        free(root_val);
        free(data);
    }
    fclose(fp);
    return 0;
}

