type Instruction = 
    | { type: 'CHAR', char: string }
    | { type: 'CLASS', predicate: (c: string) => boolean }
    | { type: 'ANY' }
    | { type: 'ANCHOR_START' }
    | { type: 'ANCHOR_END' }
    | { type: 'JUMP', target: number }
    | { type: 'SPLIT', t1: number, t2: number }
    | { type: 'SAVE', group: number, type: 'START' | 'END' };

class RegexParser {
    private pos = 0;
    private subject = "";

    constructor(private pattern: string) {}

    private peek() { return this.pattern[this.pos]; }
    private consume() { return this.pattern[this.pos++]; }

    parse() {
        const branches = [this.parseBranch()];
        while (this.peek() === '|') {
            this.consume();
            branches.push(this.parseBranch());
        }
        return { type: 'regex', branches };
    }

    private parseBranch() {
        const pieces = [];
        while (this.pos < this.pattern.length && this.peek() !== '|' && this.peek() !== ')') {
            pieces.push(this.parsePiece());
        }
        return { type: 'branch', pieces };
    }

    private parsePiece() {
        const atom = this.parseAtom();
        if (this.pos < this.pattern.length && this.isQuantifier(this.peek())) {
            const quant = this.parseQuantifier();
            return { type: 'piece', atom, quant };
        }
        return { type: 'piece', atom, quant: null };
    }

    private isQuantifier(c: string) {
        return c === '*' || c === '+' || c === '?' || c === '{';
    }

    private parseQuantifier() {
        let min = 0, max = Infinity, lazy = false;
        const c = this.consume();
        if (c === '*') { min = 0; max = Infinity; }
        else if (c === '+') { min = 1; max = Infinity; }
        else if (c === '?') { min = 0; max = 1; }
        else if (c === '{') {
            let buf = "";
            while (this.peek() !== '}') buf += this.consume();
            this.consume();
            const parts = buf.split(',');
            min = parseInt(parts[0], 10);
            if (parts.length === 1) max = min;
            else if (parts[1] === "") max = Infinity;
            else max = parseInt(parts[1], 10);
        }
        if (this.peek() === '?') {
            lazy = true;
            this.consume();
        }
        return { min, max, lazy };
    }

    private parseAtom() {
        const c = this.consume();
        if (c === '(') {
            if (this.peek() === '?' && this.pattern[this.pos + 1] === ':') {
                this.consume(); this.consume();
                const regex = this.parse();
                this.consume(); // ')'
                return { type: 'group', regex, capturing: false };
            } else {
                const regex = this.parse();
                this.consume(); // ')'
                return { type: 'group', regex, capturing: true };
            }
        } else if (c === '.') {
            return { type: 'any' };
        } else if (c === '^') {
            return { type: 'anchor_start' };
        } else if (c === '$') {
            return { type: 'anchor_end' };
        } else if (c === '[') {
            let negated = false;
            if (this.peek() === '^') {
                negated = true;
                this.consume();
            }
            const items = [];
            while (this.peek() !== ']') {
                let char = this.consume();
                if (char === '\\') {
                    char = this.consume();
                }
                if (this.peek() === '-' && this.pos + 1 < this.pattern.length && this.pattern[this.pos + 1] !== ']') {
                    this.consume();
                    let endChar = this.consume();
                    if (endChar === '\\') endChar = this.consume();
                    items.push({ type: 'range', start: char, end: endChar });
                } else {
                    items.push({ type: 'char', char });
                }
            }
            this.consume(); // ']'
            return { type: 'class', items, negated };
        } else if (c === '\\') {
            const esc = this.consume();
            return { type: 'escape', char: esc };
        } else {
            return { type: 'literal', char: c };
        }
    }
}

