function match(
    node: any,
    subject: string,
    pos: number,
    captures: Captures,
    memo: Set<string>,
    groupCount: { val: number }
): { success: boolean, pos: number, captures: Captures } | null {
    const stateKey = `${JSON.stringify(node)}-${pos}`;
    if (memo.has(stateKey)) return null;

    if (node.type === 'regex') {
        for (const branch of node.branches) {
            const res = match(branch, subject, pos, new Captures(captures), memo, groupCount);
            if (res) return res;
        }
    } else if (node.type === 'branch') {
        let currentPos = pos;
        let currentCaptures = new Captures(captures);
        let possible = true;
        for (const piece of node.pieces) {
            const res = matchPiece(piece, subject, currentPos, currentCaptures, memo, groupCount);
            if (res) {
                currentPos = res.pos;
                currentCaptures = res.captures;
            } else {
                possible = false;
                break;
            }
        }
        if (possible) return { success: true, pos: currentPos, captures: currentCaptures };
    }

    memo.add(stateKey);
    return null;
}

function matchPiece(piece: any, subject: string, pos: number, captures: Captures, memo: Set<string>, groupCount: { val: number }) {
    const { atom, quant } = piece;
    if (!quant) {
        return matchAtom(atom, subject, pos, captures, memo, groupCount);
    }

    const { min, max, lazy } = quant;
    const results: { pos: number, captures: Captures }[] = [];

    let currentPos = pos;
    let currentCaptures = new Captures(captures);

    for (let i = 0; i < min; i++) {
        const res = matchAtom(atom, subject, currentPos, currentCaptures, memo, groupCount);
        if (!res) return null;
        currentPos = res.pos;
        currentCaptures = res.captures;
    }

    results.push({ pos: currentPos, captures: currentCaptures });

    while (results.length - 1 < max) {
        const last = results[results.length - 1];
        const res = matchAtom(atom, subject, last.pos, last.captures, memo, groupCount);
        if (!res) break;
        if (res.pos === last.pos) break; // Avoid infinite loop
        results.push(res);
    }

    if (lazy) {
        for (const res of results) return res;
    } else {
        for (let i = results.length - 1; i >= 0; i--) return results[i];
    }
    return null;
}

function matchAtom(atom: any, subject: string, pos: number, captures: Captures, memo: Set<string>, groupCount: { val: number }) {
    if (atom.type === 'literal') {
        if (pos < subject.length && subject[pos] === atom.char) {
            return { success: true, pos: pos + 1, captures };
        }
    } else if (atom.type === 'any') {
        if (pos < subject.length) {
            return { success: true, pos: pos + 1, captures };
        }
    } else if (atom.type === 'anchor_start') {
        if (pos === 0) return { success: true, pos, captures };
    } else if (atom.type === 'anchor_end') {
        if (pos === subject.length) return { success: true, pos, captures };
    } else if (atom.type === 'escape') {
        const char = atom.char;
        const matched = checkEscape(char, subject[pos]);
        if (matched && pos < subject.length) {
            return { success: true, pos: pos + 1, captures };
        }
    } else if (atom.type === 'class') {
        const matched = checkClass(atom, subject[pos]);
        if (matched && pos < subject.length) {
            return { success: true, pos: pos + 1, captures };
        }
    } else if (atom.type === 'group') {
        const gId = atom.capturing ? ++groupCount.val : -1;
        const startPos = pos;
        const res = match(atom.regex, subject, pos, captures, memo, groupCount);
        if (res) {
            const newCaptures = new Captures(res.captures);
            if (atom.capturing) {
                newCaptures.set(gId, [startPos, res.pos]);
            }
            return { success: true, pos: res.pos, captures: newCaptures };
        }
    }
    return null;
}

function checkEscape(esc: string, c: string) {
    if (!c) return false;
    if (esc === 'd') return /\d/.test(c);
    if (esc === 'w') return /\w/.test(c);
    if (esc === 's') return /\s/.test(c);
    if (esc === 'D') return !/\d/.test(c);
    if (esc === 'W') return !/\w/.test(c);
    if (esc === 'S') return !/\s/.test(c);
    return esc === c;
}

function checkClass(node: any, c: string) {
    if (!c) return false;
    let matched = false;
    for (const item of node.items) {
        if (item.type === 'char') {
            if (item.char === c) matched = true;
        } else if (item.type === 'range') {
            if (c >= item.start && c <= item.end) matched = true;
        } else {
            // Handle class escapes
            const escChar = item.char;
            if (checkEscape(escChar, c)) matched = true;
        }
        if (matched) break;
    }
    return node.negated ? !matched : matched;
}

