import * as fs from 'fs';
import * as path from 'path';

type Captures = Map<number, [number, number]>;

interface Node {
    id: number;
}

interface RegexNode extends Node {
    type: 'regex';
    branches: BranchNode[];
}

interface BranchNode extends Node {
    type: 'branch';
    pieces: PieceNode[];
}

interface PieceNode extends Node {
    type: 'piece';
    atom: AtomNode;
    quantifier: Quantifier | null;
}

interface Quantifier {
    min: number;
    max: number;
    lazy: boolean;
}

interface AtomNode extends Node {
    type: 'atom';
    atomType: 'group' | 'any' | 'anchor_start' | 'anchor_end' | 'class' | 'escape' | 'literal';
    regex?: RegexNode;
    capturing?: boolean;
    groupNumber?: number;
    char?: string;
    classNode?: ClassNode;
}

interface ClassNode {
    negated: boolean;
    items: ClassItem[];
}

interface ClassItem {
    type: 'char' | 'range' | 'escape';
    char?: string;
    start?: string;
    end?: string;
}

class RegexParser {
    private pos = 0;
    private nodeCount = 0;

    constructor(private pattern: string) {}

    private nextId() { return this.nodeCount++; }
    private peek() { return this.pattern[this.pos]; }
    private consume() { return this.pattern[this.pos++]; }

    parse(): RegexNode {
        const branches = [this.parseBranch()];
        while (this.peek() === '|') {
            this.consume();
            branches.push(this.parseBranch());
        }
        return { id: this.nextId(), type: 'regex', branches };
    }

    private parseBranch(): BranchNode {
        const pieces = [];
        while (this.pos < this.pattern.length && this.peek() !== '|' && this.peek() !== ')') {
            pieces.push(this.parsePiece());
        }
        return { id: this.nextId(), type: 'branch', pieces };
    }

    private parsePiece(): PieceNode {
        const atom = this.parseAtom();
        let quantifier: Quantifier | null = null;
        if (this.pos < this.pattern.length && this.isQuantifier(this.peek())) {
            quantifier = this.parseQuantifier();
        }
        return { id: this.nextId(), type: 'piece', atom, quantifier };
    }

    private isQuantifier(c: string) {
        return c === '*' || c === '+' || c === '?' || c === '{';
    }

    private parseQuantifier(): Quantifier {
        let min = 0, max = Infinity, lazy = false;
        const c = this.consume();
        if (c === '*') { min = 0; max = Infinity; }
        else if (c === '+') { min = 1; max = Infinity; }
        else if (c === '?') { min = 0; max = 1; }
        else if (c === '{') {
            let buf = "";
            while (this.peek() !== '}') buf += this.consume();
            this.consume();
            const parts = buf.split(',');
            min = parseInt(parts[0], 10);
            if (parts.length === 1) max = min;
            else if (parts[1] === "") max = Infinity;
            else max = parseInt(parts[1], 10);
        }
        if (this.peek() === '?') {
            lazy = true;
            this.consume();
        }
        return { min, max, lazy };
    }

    private parseAtom(): AtomNode {
        const c = this.consume();
        if (c === '(') {
            if (this.peek() === '?' && this.pattern[this.pos + 1] === ':') {
                this.consume(); this.consume();
                const regex = this.parse();
                this.consume(); // ')'
                return { id: this.nextId(), type: 'atom', atomType: 'group', regex, capturing: false };
            } else {
                const regex = this.parse();
                this.consume(); // ')'
                return { id: this.nextId(), type: 'atom', atomType: 'group', regex, capturing: true };
            }
        } else if (c === '.') {
            return { id: this.nextId(), type: 'atom', atomType: 'any' };
        } else if (c === '^') {
            return { id: this.nextId(), type: 'atom', atomType: 'anchor_start' };
        } else if (c === '$') {
            return { id: this.nextId(), type: 'atom', atomType: 'anchor_end' };
        } else if (c === '[') {
            let negated = false;
            if (this.peek() === '^') {
                negated = true;
                this.consume();
            }
            const items: ClassItem[] = [];
            while (this.peek() !== ']') {
                let char = this.consume();
                if (char === '\\') char = this.consume();
                if (this.peek() === '-' && this.pos + 1 < this.pattern.length && this.pattern[this.pos + 1] !== ']') {
                    this.consume();
                    let endChar = this.consume();
                    if (endChar === '\\') endChar = this.consume();
                    items.push({ type: 'range', start: char, end: endChar });
                } else {
                    if (char === '\\' && this.pos < this.pattern.length) {
                        // We need to handle class escapes like \d, \w, \s
                        // But the logic above already handled the backslash for the current char.
                        // Let's re-evaluate.
                    }
                    // Re-check if it was a class escape
                    // The logic for class items is slightly different.
                }
            }
            // Corrected class item parsing:
            return { id: this.nextId(), type: 'atom', atomType: 'class', classNode: { negated, items: [] } }; 
        } else if (c === '\\') {
            const esc = this.consume();
            return { id: this.nextId(), type: 'atom', atomType: 'escape', char: esc };
        } else {
            return { id: this.nextId(), type: 'atom', atomType: 'literal', char: c };
        }
    }
}

// Redoing the parseAtom for class to be correct
function parseClassItems(parser: any): ClassItem[] {
    const items: ClassItem[] = [];
    while (parser.peek() !== ']') {
        let char = parser.consume();
        if (char === '\\') {
            const esc = parser.consume();
            if (['d', 'w', 's', 'D', 'W', 'S'].includes(esc)) {
                items.push({ type: 'escape', char: esc });
                continue;
            } else {
                char = esc;
            }
        }
        if (parser.peek() === '-' && parser.pos + 1 < parser.pattern.length && parser.pattern[parser.pos + 1] !== ']') {
            parser.consume();
            let endChar = parser.consume();
            if (endChar === '\\') endChar = parser.consume();
            items.push({ type: 'range', start: char, end: endChar });
        } else {
            items.push({ type: 'char', char });
        }
    }
    return items;
}

// Fixing the RegexParser to use the correct class item logic
class FixedRegexParser extends RegexParser {
    private parseAtom(): AtomNode {
        const c = this.consume();
        if (c === '(') {
            if (this.peek() === '?' && this.pattern[this.pos + 1] === ':') {
                this.consume(); this.consume();
                const regex = this.parse();
                this.consume();
                return { id: this.nextId(), type: 'atom', atomType: 'group', regex, capturing: false };
            } else {
                const regex = this.parse();
                this.consume();
                return { id: this.nextId(), type: 'atom', atomType: 'group', regex, capturing: true };
            }
        } else if (c === '.') {
            return { id: this.nextId(), type: 'atom', atomType: 'any' };
        } else if (c === '^') {
            return { id: this.nextId(), type: 'atom', atomType: 'anchor_start' };
        } else if (c === '$') {
            return { id: this.nextId(), type: 'atom', atomType: 'anchor_end' };
        } else if (c === '[') {
            let negated = false;
            if (this.peek() === '^') {
                negated = true;
                this.consume();
            }
            const items = parseClassItems(this);
            this.consume(); // ']'
            return { id: this.nextId(), type: 'atom', atomType: 'class', classNode: { negated, items } };
        } else if (c === '\\') {
            const esc = this.consume();
            return { id: this.nextId(), type: 'atom', atomType: 'escape', char: esc };
        } else {
            return { id: this.nextId(), type: 'atom', atomType: 'literal', char: c };
        }
    }
}

function checkEscape(esc: string, c: string) {
    if (!c) return false;
    if (esc === 'd') return /\d/.test(c);
    if (esc === 'w') return /\w/.test(c);
    if (esc === 's') return /[\s\t\n\r\f\v]/.test(c);
    if (esc === 'D') return !/\d/.test(c);
    if (esc === 'W') return !/\w/.test(c);
    if (esc === 'S') return !/[\s\t\n\r\f\v]/.test(c);
    return esc === c;
}

function checkClass(node: ClassNode, c: string) {
    if (!c) return false;
    let matched = false;
    for (const item of node.items) {
        if (item.type === 'char') {
            if (item.char === c) matched = true;
        } else if (item.type === 'range') {
            if (c >= item.start! && c <= item.end!) matched = true;
        } else if (item.type === 'escape') {
            if (checkEscape(item.char!, c)) matched = true;
        }
        if (matched) break;
    }
    return node.negated ? !matched : matched;
}

class Matcher {
    private memo = new Set<string>();
    private groupCount = 0;

    constructor(private subject: string) {}

    assignGroupNumbers(node: any) {
        if (node.type === 'regex') {
            node.branches.forEach((b: BranchNode) => this.assignGroupNumbers(b));
        } else if (node.type === 'branch') {
            node.pieces.forEach((p: PieceNode) => this.assignGroupNumbers(p.atom));
        } else if (node.type === 'atom' && node.atomType === 'group') {
            if (node.capturing) node.groupNumber = ++this.groupCount;
            this.assignGroupNumbers(node.regex);
        }
