    matchRegex(node: RegexNode, pos: number, captures: Captures): { pos: number, captures: Captures } | null {
        for (const branch of node.branches) {
            const res = this.matchBranch(branch, pos, new Captures(captures));
            if (res) return res;
        }
        return null;
    }

    matchBranch(node: BranchNode, pos: number, captures: Captures): { pos: number, captures: Captures } | null {
        let currentPos = pos;
        let currentCaptures = new Captures(captures);
        for (const piece of node.pieces) {
            const res = this.matchPiece(piece, currentPos, currentCaptures);
            if (!res) return null;
            currentPos = res.pos;
