function solve() {
    const dir = process.argv[2];
    if (!dir) return;
    const casesFile = path.join(dir, 'cases.txt');
    const content = fs.readFileSync(casesFile, 'utf-8');
    const lines = content.split('\n');

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (!line) continue;
        const parts = line.split('\t');
        if (parts.length < 2 && !line.includes('\t')) continue;
        const patternStr = parts[0];
        const subject = parts[1] || "";

        const parser = new FixedRegexParser(patternStr);
        const root = parser.parse();
        const matcher = new Matcher(subject);
        matcher.assignGroupNumbers(root);

        let bestMatch = null;
        for (let start = 0; start <= subject.length; start++) {
            const memo = new Set<string>();
            const res = matcher.matchRecursive(root, start, new Captures(), memo);
            if (res) {
                bestMatch = { start, end: res.pos, captures: res.captures };
                break;
            }
        }

        if (bestMatch) {
            let out = `${i + 1}: ${bestMatch.start}-${bestMatch.end}`;
            for (let g = 1; g <= matcher.groupCount; g++) {
                const cap = bestMatch.captures.get(g);
                out += cap ? ` ${cap[0]}-${cap[1]}` : ` -`;
            }
            process.stdout.write(out + '\n');
        } else {
            process.stdout.write(`${i + 1}: no match\n`);
        }
    }
}

