    static class RegexEngine {
        Node root;
        int groupCount = 0;

        RegexEngine(String pattern) {
            Parser parser = new Parser(pattern);
            this.root = parser.parseRegex();
            this.groupCount = parser.groupCount;
        }

        String search(String subject) {
            for (int i = 0; i <= subject.length(); i++) {
                Matcher matcher = new Matcher(subject, groupCount);
                if (match(root, i, matcher)) {
                    StringBuilder sb = new StringBuilder();
                    sb.append(i).append("-").append(matcher.currentPos);
                    for (int g = 1; g <= groupCount; g++) {
                        sb.append(" ");
                        if (matcher.groupStarts[g] == -1) {
                            sb.append("-");
                        } else {
                            sb.append(matcher.groupStarts[g]).append("-").append(matcher.groupEnds[g]);
                        }
                    }
                    return sb.toString();
                }
            }
            return "no match";
        }

        boolean match(Node node, int pos, Matcher matcher) {
            if (node == null) {
                matcher.currentPos = pos;
                return true;
            }
            if (matcher.memo[node.id][pos]) return false;
            if (node.match(pos, matcher, this)) return true;
            matcher.memo[node.id][pos] = true;
            return false;
        }
    }

