    static class Parser {
        String pattern;
        int pos = 0;
        int nodeIdCounter = 0;
        int groupCount = 0;

        Parser(String pattern) { this.pattern = pattern; }
        int nextId() { return nodeIdCounter++; }

        Node parseRegex() {
            Node node = parseBranch();
            while (pos < pattern.length() && pattern.charAt(pos) == '|') {
                pos++;
                Node nextBranch = parseBranch();
                node = new ChoiceNode(nextId(), node, nextBranch);
            }
            return node;
        }

        Node parseBranch() {
            List<Node> pieces = new ArrayList<>();
            while (pos < pattern.length() && pattern.charAt(pos) != ')' && pattern.charAt(pos) != '|') {
                pieces.add(parsePiece());
