        Node parsePiece() {
            Node atom = parseAtom();
            if (pos < pattern.length() && (pattern.charAt(pos) == '*' || pattern.charAt(pos) == '+' || pattern.charAt(pos) == '?' || pattern.charAt(pos) == '{')) {
                char qChar = pattern.charAt(pos++);
                int min = 0, max = -1;
                if (qChar == '*') { min = 0; max = -1; }
                else if (qChar == '+') { min = 1; max = -1; }
                else if (qChar == '?') { min = 0; max = 1; }
                else {
                    int end = pattern.indexOf('}', pos);
                    String range = pattern.substring(pos, end);
                    pos = end + 1;
                    if (range.contains(",")) {
                        String[] parts = range.split(",", -1);
                        min = Integer.parseInt(parts[0]);
                        max = parts[1].isEmpty() ? -1 : Integer.parseInt(parts[1]);
                    } else {
                        min = max = Integer.parseInt(range);
                    }
                }
                boolean lazy = (pos < pattern.length() && pattern.charAt(pos) == '?');
                if (lazy) pos++;
                return expandQuantifier(atom, min, max, lazy);
            }
            return atom;
        }

        Node expandQuantifier(Node atom, int min, int max, boolean lazy) {
            List<Node> sequence = new ArrayList<>();
            for (int i = 0; i < min; i++) sequence.add(atom);
            if (max == -1) {
                // X{min,} -> X repeated min times, then X*
                Node star = expandStar(atom, lazy);
                sequence.add(star);
            } else {
