                for (int i = 0; i < max - min; i++) {
                    Node optional = new ChoiceNode(nextId(), atom, null); // null as epsilon
                    if (lazy) optional = new LazyChoiceNode(nextId(), atom, null);
                    sequence.add(optional);
                }
