                        }
                    }
                }
                pos++; // skip ']'
                return cn;
            } else if (c == '\\') {
                char escaped = pattern.charAt(pos++);
                if ("dDwsS".indexOf(escaped) != -1) return new EscapeNode(nextId(), escaped, ' ');
                return new EscapeNode(nextId(), 'L', escaped);
            } else {
