import java.io.*;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        if (args.length < 2) return;
        String dataDir = args[0];
        String baseUrl = args[1];

        try {
            File clientFile = new File(dataDir, "client.json");
            String clientJson = Files.readString(clientFile.toPath());
            JsonParser parser = new JsonParser(clientJson);
            Map<String, Object> clientSettings = (Map<String, Object>) parser.parse();

            String clientId = (String) clientSettings.get("client_id");
            String clientSecret = (String) clientSettings.get("client_secret");
            String scope = (String) clientSettings.get("scope");
            int pageSize = ((Number) clientSettings.get("page_size")).intValue();

            HttpClient client = HttpClient.newBuilder()
                    .version(HttpClient.Version.HTTP_1_1)
                    .build();

            String token = getAccessToken(client, baseUrl, clientId, clientSecret, scope);

            long ordersCount = 0;
            int pagesCount = 0;
            int retriesCount = 0;
            int reauthCount = 0;

            Map<TotalKey, Long> totals = new HashMap<>();
            Map<String, Long> statusCounts = new HashMap<>();

            String cursor = null;
            boolean tokenWasJustRefreshed = false;

            while (true) {
                String url = baseUrl + "/orders?limit=" + pageSize;
                if (cursor != null) {
                    url += "&cursor=" + URLEncoder.encode(cursor, StandardCharsets.UTF_8);
                }

                HttpRequest request = HttpRequest.newBuilder()
                        .uri(URI.create(url))
                        .header("Authorization", "Bearer " + token)
                        .GET()
                        .build();

                HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

                if (response.statusCode() == 200) {
                    tokenWasJustRefreshed = false;
                    pagesCount++;

                    JsonParser orderParser = new JsonParser(response.body());
                    Map<String, Object> page = (Map<String, Object>) orderParser.parse();
                    List<Map<String, Object>> data = (List<Map<String, Object>>) page.get("data");

                    for (Map<String, Object> order : data) {
                        ordersCount++;
                        String status = (String) order.get("status");
                        statusCounts.put(status, statusCounts.getOrDefault(status, 0L) + 1);

                        if (!"cancelled".equals(status)) {
                            Map<String, Object> customer = (Map<String, Object>) order.get("customer");
                            String name = (String) customer.get("name");
                            String currency = (String) order.get("currency");
                            String amountStr = (String) order.get("amount");
                            long cents = new BigDecimal(amountStr).multiply(new BigDecimal("100")).longValueExact();

                            TotalKey key = new TotalKey(name, currency);
                            totals.put(key, totals.getOrDefault(key, 0L) + cents);
                        }
                    }

                    Object nextCursorObj = page.get("next_cursor");
                    cursor = (nextCursorObj == null) ? null : (String) nextCursorObj;
                    if (cursor == null) break;

                } else if (response.statusCode() == 401) {
                    if (tokenWasJustRefreshed) {
                        handleFatal(response);
                        return;
                    }
                    token = getAccessToken(client, baseUrl, clientId, clientSecret, scope);
                    reauthCount++;
                    tokenWasJustRefreshed = true;
                    // Retry same request
                } else if (response.statusCode() == 429 || response.statusCode() == 503) {
                    retriesCount++;
                    if (response.statusCode() == 429) {
                        String retryAfter = response.headers().firstValue("Retry-After").orElse("0");
                        Thread.sleep(Integer.parseInt(retryAfter) * 1000L);
                    } else {
                        Thread.sleep(1000);
                    }
                    // Retry same request
                } else {
                    handleFatal(response);
                    return;
                }
            }

            List<TotalKey> sortedKeys = new ArrayList<>(totals.keySet());
            Collections.sort(sortedKeys);
            for (TotalKey key : sortedKeys) {
                System.out.println("total " + key.currency + " " + formatCents(totals.get(key)) + " " + key.name);
            }

            List<String> sortedStatuses = new ArrayList<>(statusCounts.keySet());
            Collections.sort(sortedStatuses);
            for (String status : sortedStatuses) {
                System.out.println("status " + status + " " + statusCounts.get(status));
            }

            System.out.println("orders " + ordersCount + " pages " + pagesCount + " retries " + retriesCount + " reauth " + reauthCount);

        } catch (Exception e) {
            // Unexpected internal errors are not explicitly handled, but the prompt says only fatal API errors print ERROR.
        }
    }

    private static String getAccessToken(HttpClient client, String baseUrl, String clientId, String clientSecret, String scope) throws Exception {
        String authInput = URLEncoder.encode(clientId, StandardCharsets.UTF_8) + ":" + URLEncoder.encode(clientSecret, StandardCharsets.UTF_8);
        String b64Auth = Base64.getEncoder().encodeToString(authInput.getBytes(StandardCharsets.UTF_8));

        String body = "grant_type=client_credentials&scope=" + URLEncoder.encode(scope, StandardCharsets.UTF_8);

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/oauth/token"))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .header("Authorization", "Basic " + b64Auth)
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() != 200) {
            handleFatal(response);
            System.exit(0);
        }

        JsonParser parser = new JsonParser(response.body());
        Map<String, Object> json = (Map<String, Object>) parser.parse();
        return (String) json.get("access_token");
    }

    private static void handleFatal(HttpResponse<String> response) {
        System.out.println("ERROR " + response.statusCode() + " " + response.body());
    }

    private static String formatCents(long cents) {
        if (cents == 0) return "0.00";
        StringBuilder sb = new StringBuilder();
        if (cents < 0) {
            sb.append("-");
            cents = -cents;
        }
        long dollars = cents / 100;
        long remainingCents = cents % 100;
        sb.append(dollars).append(".");
        if (remainingCents < 10) sb.append("0");
        sb.append(remainingCents);
        return sb.toString();
    }

    static class TotalKey implements Comparable<TotalKey> {
        String name, currency;
        TotalKey(String name, String currency) { this.name = name; this.currency = currency; }
        @Override
        public int compareTo(TotalKey o) {
            byte[] b1 = this.name.getBytes(StandardCharsets.UTF_8);
            byte[] b2 = o.name.getBytes(StandardCharsets.UTF_8);
            int len = Math.min(b1.length, b2.length);
            for (int i = 0; i < len; i++) {
                int u1 = b1[i] & 0xFF, u2 = b2[i] & 0xFF;
                if (u1 != u2) return u1 - u2;
            }
            if (b1.length != b2.length) return b1.length - b2.length;
            return this.currency.compareTo(o.currency);
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof TotalKey)) return false;
            TotalKey other = (TotalKey) o;
            return name.equals(other.name) && currency.equals(other.currency);
        }
        @Override
        public int hashCode() { return Objects.hash(name, currency); }
    }

