                if cn.negated { matched = !matched }
                if matched { result = pos + 1 }
            }
        } else if let sn = node as? SequenceNode {
            var currentPos = pos
            var possible = true
            for child in sn.children {
                if let nextPos = match(node: child, pos: currentPos) {
                    currentPos = nextPos
                } else {
                    possible = false
                    break
                }
            }
            if possible { result = currentPos }
        } else if let cn = node as? ChoiceNode {
            for child in cn.children {
                if let nextPos = match(node: child, pos: pos) {
                    result = nextPos
                    break
                }
            }
        } else if let qn = node as? QuantifierNode {
            result = matchQuantifier(qn, pos)
        } else if let gn = node as? GroupNode {
            let oldCapture = captures[gn.groupIndex]
            if let nextPos = match(node: gn.child, pos: pos) {
                if gn.groupIndex != -1 {
                    captures[gn.groupIndex] = (pos, nextPos)
                }
                result = nextPos
            } else {
                if gn.groupIndex != -1 { captures[gn.groupIndex] = oldCapture }
