    func matchQuantifier(_ qn: QuantifierNode, _ pos: Int) -> Int? {
        var currentPos = pos
        for i in 0..<qn.min {
            if let nextPos = match(node: qn.atom, pos: currentPos) {
                currentPos = nextPos
            } else {
                return nil
            }
        }

        func tryNext(p: Int, count: Int) -> Int? {
            if count >= qn.max { return p }
            if let nextPos = match(node: qn.atom, pos: p) {
                if nextPos == p {
                    // Optional iteration matching empty string ends the loop
                    return p
                }
                let res = tryNext(p: nextPos, count: count + 1)
                if res != nil { return res }
