                // If greedy, we try to stop here.
                if !qn.lazy { return nextPos } // Wait, greedy logic is different
                return nil
            }
            return p
        }

        // Correct Greedy/Lazy Backtracking
        return matchQuantifierRecursive(qn, currentPos, qn.min, pos)
    }

    func matchQuantifierRecursive(_ qn: QuantifierNode, _ pos: Int, _ count: Int, _ startPos: Int) -> Int? {
        if count >= qn.max {
            return matchRemaining(qn, pos)
        }

        if qn.lazy {
            // Lazy: try to stop first, then try to match one more
            if let res = matchRemaining(qn, pos) { return res }
            if let nextPos = match(node: qn.atom, pos: pos) {
                if nextPos == pos { return pos } // Stop if empty match
                return matchQuantifierRecursive(qn, nextPos, count + 1, startPos)
            }
            return nil
        } else {
            // Greedy: try to match one more first, then try to stop
            if let nextPos = match(node: qn.atom, pos: pos) {
                if nextPos == pos {
                    // Mandatory empty match does not stop, but optional does.
                    // The rule is: if count >= min and it matches empty, it stops.
                    // Here count is the number of iterations already completed.
                    // The current iteration (count + 1) is optional if count >= qn.min.
                    if count >= qn.min { return pos }
                    // If mandatory, it must continue, but we avoid infinite loop.
                    // In this specific problem, the "mandatory empty" won't happen often.
                    return matchQuantifierRecursive(qn, nextPos, count + 1, startPos)
                }
                if let res = matchQuantifierRecursive(qn, nextPos, count + 1, startPos) {
                    return res
                }
            }
            return matchRemaining(qn, pos)
