import Foundation

// MARK: - Node Definitions
protocol Node {
    var id: Int { get }
}

class LiteralNode: Node {
    let id: Int
    let char: UInt8
    init(id: Int, char: UInt8) { self.id = id; self.char = char }
}

class DotNode: Node {
    let id: Int
    init(id: Int) { self.id = id }
}

class AnchorNode: Node {
    let id: Int
    let isStart: Bool
    init(id: Int, isStart: Bool) { self.id = id; self.isStart = isStart }
}

class ClassNode: Node {
    let id: Int
    let negated: Bool
    let items: Set<UInt8>
    let ranges: [(UInt8, UInt8)]
    let escapes: Set<UInt8>
    init(id: Int, negated: Bool, items: Set<UInt8>, ranges: [(UInt8, UInt8)], escapes: Set<UInt8>) {
        self.id = id; self.negated = negated; self.items = items; self.ranges = ranges; self.escapes = escapes
    }
}

class SequenceNode: Node {
    let id: Int
    let children: [Node]
    init(id: Int, children: [Node]) { self.id = id; self.children = children }
}

class ChoiceNode: Node {
    let id: Int
    let children: [Node]
    init(id: Int, children: [Node]) { self.id = id; self.children = children }
}

class QuantifierNode: Node {
    let id: Int
    let atom: Node
    let min: Int
    let max: Int
    let lazy: Bool
    init(id: Int, atom: Node, min: Int, max: Int, lazy: Bool) {
        self.id = id; self.atom = atom; self.min = min; self.max = max; self.lazy = lazy
    }
}

class GroupNode: Node {
    let id: Int
    let child: Node
    let groupIndex: Int
    init(id: Int, child: Node, groupIndex: Int) { self.id = id; self.child = child; self.groupIndex = groupIndex }
}

// MARK: - Parser
class Parser {
    let input: [UInt8]
    var pos = 0
    var nodeIdCounter = 0
    var groupCounter = 0

    init(input: [UInt8]) { self.input = input }
    func nextId() -> Int { nodeIdCounter += 1; return nodeIdCounter }

    func parseRegex() -> Node {
        var branches = [Node]()
        branches.append(parseBranch())
        while pos < input.count && input[pos] == 124 { // '|'
            pos += 1
            branches.append(parseBranch())
        }
        return branches.count == 1 ? branches[0] : ChoiceNode(id: nextId(), children: branches)
    }

    func parseBranch() -> Node {
        var pieces = [Node]()
        while pos < input.count && input[pos] != 124 && input[pos] != 41 { // '|', ')'
            pieces.append(parsePiece())
        }
        return pieces.count == 1 ? pieces[0] : SequenceNode(id: nextId(), children: pieces)
    }

    func parsePiece() -> Node {
        let atom = parseAtom()
        if pos < input.count {
            let c = input[pos]
            if c == 42 || c == 43 || c == 63 || c == 123 { // '*', '+', '?', '{'
                return parseQuantifier(atom: atom)
            }
        }
        return atom
    }

    func parseAtom() -> Node {
        let c = input[pos]
        pos += 1
        if c == 40 { // '('
            if pos < input.count && input[pos] == 63 { // '(?'
                pos += 1
                if pos < input.count && input[pos] == 58 { // '(?:'
                    pos += 1
                    let regex = parseRegex()
                    if pos < input.count && input[pos] == 41 { pos += 1 }
                    return GroupNode(id: nextId(), child: regex, groupIndex: -1)
                }
            }
            groupCounter += 1
            let regex = parseRegex()
            if pos < input.count && input[pos] == 41 { pos += 1 }
            return GroupNode(id: nextId(), child: regex, groupIndex: groupCounter)
        } else if c == 46 { // '.'
            return DotNode(id: nextId())
        } else if c == 94 { // '^'
            return AnchorNode(id: nextId(), isStart: true)
        } else if c == 36 { // '$'
            return AnchorNode(id: nextId(), isStart: false)
        } else if c == 91 { // '['
            var negated = false
            if pos < input.count && input[pos] == 94 {
                negated = true
                pos += 1
            }
            var items = Set<UInt8>()
            var ranges = [(UInt8, UInt8)]()
            var escapes = Set<UInt8>()
            while pos < input.count && input[pos] != 93 {
                var char = input[pos]
                pos += 1
                if char == 92 { // '\'
                    if pos < input.count {
                        let esc = input[pos]
                        pos += 1
                        if esc == 100 || esc == 119 || esc == 115 || esc == 68 || esc == 87 || esc == 83 {
                            escapes.insert(esc)
                        } else {
                            items.insert(esc)
                        }
                    }
                } else if pos < input.count && input[pos] == 45 { // '-'
                    pos += 1
                    if pos < input.count {
                        var endChar = input[pos]
                        pos += 1
                        if endChar == 92 && pos < input.count {
                            endChar = input[pos]
                            pos += 1
                        }
                        ranges.append((char, endChar))
                    }
                } else {
                    items.insert(char)
                }
            }
            if pos < input.count { pos += 1 }
            return ClassNode(id: nextId(), negated: negated, items: items, ranges: ranges, escapes: escapes)
        } else if c == 92 { // '\'
            if pos < input.count {
                let esc = input[pos]
                pos += 1
                if esc == 100 || esc == 119 || esc == 115 || esc == 68 || esc == 87 || esc == 83 {
                    var escapes = Set<UInt8>()
                    escapes.insert(esc)
                    return ClassNode(id: nextId(), negated: false, items: [], ranges: [], escapes: escapes)
                } else {
                    return LiteralNode(id: nextId(), char: esc)
                }
            }
        } else {
            return LiteralNode(id: nextId(), char: c)
        }
        return LiteralNode(id: nextId(), char: 0)
    }

    func parseQuantifier(atom: Node) -> Node {
        let c = input[pos]
        pos += 1
        var min = 0, max = Int.max, lazy = false
        if c == 42 { min = 0 }
        else if c == 43 { min = 1 }
        else if c == 63 { min = 0; max = 1 }
        else if c == 123 {
            var mStr = ""
            while pos < input.count && input[pos] != 44 && input[pos] != 125 {
                mStr.append(Character(UnicodeScalar(input[pos])))
                pos += 1
            }
            let m = Int(mStr) ?? 0
            if pos < input.count && input[pos] == 44 {
                pos += 1
                if pos < input.count && input[pos] != 125 {
                    var nStr = ""
                    while pos < input.count && input[pos] != 125 {
                        nStr.append(Character(UnicodeScalar(input[pos])))
                        pos += 1
                    }
                    let n = Int(nStr) ?? Int.max
                    min = m; max = n
                } else {
                    min = m; max = Int.max
                }
            } else {
                min = m; max = m
            }
            if pos < input.count && input[pos] == 125 { pos += 1 }
        }
        if pos < input.count && input[pos] == 63 {
            lazy = true
            pos += 1
        }
        return QuantifierNode(id: nextId(), atom: atom, min: min, max: max, lazy: lazy)
    }
}

// MARK: - Matcher
class BacktrackingMatcher {
    let subject: [UInt8]
    var captures = [Int: (Int, Int)]()
    var memo = Set<State>()

    struct State: Hashable {
        let nodeId: Int
        let pos: Int
        let continuationId: Int
    }

    init(subject: [UInt8]) { self.subject = subject }

    func matchEscape(_ char: UInt8, _ esc: UInt8) -> Bool {
        switch esc {
        case 100, 68: return (char >= 48 && char <= 57) != (esc == 68)
        case 119, 87: return ((char >= 65 && char <= 90) || (char >= 97 && char <= 122) || (char >= 48 && char <= 57) || char == 95) != (esc == 87)
        case 115, 83: return (char == 32 || char == 9 || char == 10 || char == 13 || char == 12 || char == 11) != (esc == 83)
        default: return false
        }
    }

    func match(node: Node, pos: Int, continuationId: Int, continuation: @escaping (Int) -> Bool) -> Bool {
        let state = State(nodeId: node.id, pos: pos, continuationId: continuationId)
        if memo.contains(state) { return false }

        var result = false
        if let ln = node as? LiteralNode {
            if pos < subject.count && subject[pos] == ln.char {
                result = continuation(pos + 1)
            }
        } else if let dn = node as? DotNode {
            if pos < subject.count {
                result = continuation(pos + 1)
            }
        } else if let an = node as? AnchorNode {
            if an.isStart {
                if pos == 0 { result = continuation(pos) }
            } else {
                if pos == subject.count { result = continuation(pos) }
            }
        } else if let cn = node as? ClassNode {
            if pos < subject.count {
                let char = subject[pos]
                var matched = false
                for esc in cn.escapes {
                    if matchEscape(char, esc) { matched = true; break }
                }
                if !matched {
                    for (s, e) in cn.ranges {
                        if char >= s && char <= e { matched = true; break }
                    }
                }
                if !matched {
                    if cn.items.contains(char) { matched = true }
                }
                if cn.negated { matched = !matched }
                if matched { result = continuation(pos + 1) }
            }
        } else if let sn = node as? SequenceNode {
            result = matchSequence(sn.children, 0, pos, continuationId, continuation)
        } else if let cn = node as? ChoiceNode {
            for child in cn.children {
                if match(node: child, pos: pos, continuationId: continuationId, continuation: continuation) {
                    result = true; break
                }
            }
        } else if let qn = node as? QuantifierNode {
            result = matchQuantifier(qn, pos, continuationId, continuation)
        } else if let gn = node as? GroupNode {
            let oldCapture = captures[gn.groupIndex]
            if gn.groupIndex != -1 { captures[gn.groupIndex] = (pos, pos) }

            let childMatch = match(node: gn.child, pos: pos, continuationId: continuationId) { (nextPos) in
                if gn.groupIndex != -1 {
                    self.captures[gn.groupIndex] = (pos, nextPos)
                }
                return continuation(nextPos)
            }

            if !childMatch {
                if gn.groupIndex != -1 { captures[gn.groupIndex] = oldCapture }
            }
            result = childMatch
        }

        if !result { memo.insert(state) }
        return result
    }

    func matchSequence(_ children: [Node], _ idx: Int, _ pos: Int, _ continuationId: Int, _ continuation: @escaping (Int) -> Bool) -> Bool {
        if idx == children.count {
            return continuation(pos)
        }
        return match(node: children[idx], pos: pos, continuationId: continuationId) { (nextPos) in
            self.matchSequence(children, idx + 1, nextPos, continuationId, continuation)
        }
    }

    func matchQuantifier(_ qn: QuantifierNode, _ pos: Int, _ continuationId: Int, _ continuation: @escaping (Int) -> Bool) -> Bool {
        var currentPos = pos
        var count = 0

        func tryMatchOne(p: Int) -> Int? {
            var nextP: Int? = nil
            _ = match(node: qn.atom, pos: p, continuationId: -1) { (np) in
                nextP = np
                return false
            }
            return nextP
        }

        while count < qn.min {
            if let nextP = tryMatchOne(p: currentPos) {
                currentPos = nextP
                count += 1
            } else {
                return false
            }
        }

        return matchOptional(qn, currentPos, count, continuationId, continuation)
    }

    func matchOptional(_ qn: QuantifierNode, _ pos: Int, _ count: Int, _ continuationId: Int, _ continuation: @escaping (Int) -> Bool) -> Bool {
        if count >= qn.max {
            return continuation(pos)
        }

        if qn.lazy {
            if continuation(pos) { return true }
            var nextP: Int? = nil
            if match(node: qn.atom, pos: pos, continuationId: -1) { (np) in
                nextP = np
                return false
            } {
                if let np = nextP, np != pos {
                    return matchOptional(qn, np, count + 1, continuationId, continuation)
                }
            }
            return false
        } else {
            var nextP: Int? = nil
            if match(node: qn.atom, pos: pos, continuationId: -1) { (np) in
                nextP = np
                return false
            } {
                if let np = nextP {
                    if np == pos {
                        // Optional empty match ends loop
                        return continuation(pos)
                    }
                    if matchOptional(qn, np, count + 1, continuationId, continuation) {
                        return true
                    }
                }
            }
            return continuation(pos)
        }
    }
}

// MARK: - Main
func main() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let dir = args[1]
    let filePath = (dir as NSString).appendingPathComponent("cases.txt")

    guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else { return }
    let lines = content.components(separatedBy: .newlines)

    for (i, line) in lines.enumerated() {
        if line.isEmpty && i == lines.count - 1 { continue }
        let parts = line.components(separatedBy: "\t")
        if parts.count < 2 { continue }
        let patternStr = parts[0]
        let subjectStr = parts[1]

        let parser = Parser(input: Array(patternStr.utf8))
        let root = parser.parseRegex()
        let subject = Array(subjectStr.utf8)

        var found = false
        for startPos in 0...subject.count {
            let matcher = BacktrackingMatcher(subject: subject)
            if matcher.match(node: root, pos: startPos, continuationId: 0) { (endPos) in
                let matchSpan = "\(startPos)-\(endPos)"
                var output = "\(i + 1): \(matchSpan)"
                for gIdx in 1...parser.groupCounter {
                    if let span = matcher.captures[gIdx] {
                        output += " \(span.0)-\(span.1)"
                    } else {
                        output += " -"
                    }
                }
                print(output)
                return true
            } {
                found = true
                break
            }
            if found { break }
        }
        if !found {
            print("\(i + 1): no match")
        }
    }
}

main()

