fn decode_varint(data: &[u8], pos: &mut usize) -> u64 {
    let mut result = 0u64;
    let mut shift = 0;
    while *pos < data.len() {
        let byte = data[*pos];
        *pos += 1;
        result |= ((byte & 0x7F) as u64) << shift;
        if byte & 0x80 == 0 { break; }
        shift += 7;
        if shift >= 64 { break; }
    }
    result
}

fn decode_zigzag(n: u64) -> i64 {
    if n % 2 == 0 { (n / 2) as i64 } else { -((n / 2) as i64 + 1) }
}

fn base64_encode(data: &[u8]) -> String {
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b1 = chunk[0];
        let b2 = if chunk.len() > 1 { chunk[1] } else { 0 };
        let b3 = if chunk.len() > 2 { chunk[2] } else { 0 };
        let n = (b1 as u32) << 16 | (b2 as u32) << 8 | (b3 as u32);
        result.push(alphabet[((n >> 18) & 63) as usize] as char);
        result.push(alphabet[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 { result.push(alphabet[((n >> 6) & 63) as usize] as char); } else { result.push('='); }
        if chunk.len() > 2 { result.push(alphabet[(n & 63) as usize] as char); } else { result.push('='); }
    }
    result
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{0009}' => result.push_str("\\t"),
            '\u{000a}' => result.push_str("\\n"),
            '\u{000c}' => result.push_str("\\f"),
            '\u{000d}' => result.push_str("\\r"),
            c if c < '\u{0020}' => result.push_str(&format!("\\u{:04x}", c as u32)),
            _ => result.push(c),
        }
    }
    result
}

fn to_lower_camel_case(s: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = false;
    for (i, c) in s.chars().enumerate() {
        if i == 0 { result.push(c); }
        else if c == '_' { capitalize_next = true; }
        else {
            if capitalize_next && c.is_ascii_lowercase() { result.push(c.to_ascii_uppercase()); }
            else { result.push(c); }
            capitalize_next = false;
        }
    }
    result
}

fn tokenize(input: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut i = 0;
    let bytes = input.as_bytes();
    while i < bytes.len() {
        if bytes[i].is_whitespace() { i += 1; }
        else if bytes[i] == b'/' && i + 1 < bytes.len() && bytes[i + 1] == b'/' {
            while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
        } else if bytes[i] == b'/' && i + 1 < bytes.len() && bytes[i + 1] == b'*' {
            i += 2;
            while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') { i += 1; }
            i += 2;
        } else if bytes[i] == b'"' {
            let mut s = String::new();
            i += 1;
            while i < bytes.len() && bytes[i] != b'"' { s.push(bytes[i] as char); i += 1; }
            i += 1;
            tokens.push(format!("\"{}\"", s));
        } else if bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' {
            let mut s = String::new();
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                s.push(bytes[i] as char); i += 1;
            }
            tokens.push(s);
        } else if bytes[i].is_ascii_digit() || bytes[i] == b'-' {
            let mut s = String::new();
            if bytes[i] == b'-' { s.push('-'); i += 1; }
            while i < bytes.len() && bytes[i].is_ascii_digit() { s.push(bytes[i] as char); i += 1; }
            tokens.push(s);
        } else {
            tokens.push((bytes[i] as char).to_string());
            i += 1;
        }
    }
    tokens
}

struct ProtoParser { tokens: Vec<String>, pos: usize }
impl ProtoParser {
    fn next(&mut self) -> Option<String> {
        if self.pos >= self.tokens.len() { return None; }
        let t = self.tokens[self.pos].clone();
        self.pos += 1;
        Some(t)
    }
    fn peek(&self) -> Option<&String> { self.tokens.get(self.pos) }
    fn expect(&mut self, e: &str) {
        if self.next().as_deref() != Some(e) { panic!("Expected {}", e); }
    }
}

fn parse_proto(input: &str) -> Schema {
    let mut parser = ProtoParser { tokens: tokenize(input), pos: 0 };
    let mut schema = Schema { messages: HashMap::new(), enums: HashMap::new(), root_type: String::new() };
    while let Some(t) = parser.next() {
        match t.as_str() {
            "syntax" => { parser.expect("="); parser.next(); parser.expect(";"); }
            "package" => { while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); } parser.expect(";"); }
            "option" => { while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); } parser.expect(";"); }
            "message" => {
                let name = parser.next().unwrap();
                if schema.root_type.is_empty() { schema.root_type = name.clone(); }
                parser.expect("{");
                let mut fields = HashMap::new();
                let mut oneofs = HashMap::new();
                while parser.peek().map(|s| s.as_str()) != Some("}") {
                    match parser.peek().map(|s| s.as_str()) {
                        Some("message") => parse_msg_nested(&mut parser, &mut schema),
                        Some("enum") => parse_enum_nested(&mut parser, &mut schema),
                        Some("oneof") => {
                            parser.next();
                            let oname = parser.next().unwrap();
                            parser.expect("{");
                            let mut ofields = Vec::new();
                            while parser.peek().map(|s| s.as_str()) != Some("}") {
                                let f = parse_field(&mut parser, &mut schema, Some(oname.clone()));
                                ofields.push(f.number);
                                fields.insert(f.number, f);
                            }
                            parser.expect("}");
                            oneofs.insert(oname, ofields);
                        }
                        Some("reserved") => {
                            parser.next();
                            while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); }
                            parser.expect(";");
                        }
                        _ => {
                            let f = parse_field(&mut parser, &mut schema, None);
                            fields.insert(f.number, f);
                        }
                    }
                }
                parser.expect("}");
                schema.messages.insert(name, MessageDef { fields, oneofs });
            }
            "enum" => parse_enum_nested(&mut parser, &mut schema),
            _ => {}
        }
    }
    schema
}

fn parse_enum_nested(parser: &mut ProtoParser, schema: &mut Schema) {
    let name = parser.next().unwrap();
    parser.expect("{");
    let mut values = HashMap::new();
    while parser.peek().map(|s| s.as_str()) != Some("}") {
        let vname = parser.next().unwrap();
        parser.expect("=");
        let vnum = parser.next().unwrap().parse::<i32>().unwrap();
        parser.expect(";");
        values.insert(vnum, vname);
    }
    parser.expect("}");
    schema.enums.insert(name, EnumDef { values });
}

fn parse_msg_nested(parser: &mut ProtoParser, schema: &mut Schema) {
    parser.next(); // "message"
    let name = parser.next().unwrap();
    parser.expect("{");
    let mut fields = HashMap::new();
    let mut oneofs = HashMap::new();
    while parser.peek().map(|s| s.as_str()) != Some("}") {
        match parser.peek().map(|s| s.as_str()) {
            Some("message") => parse_msg_nested(parser, schema),
            Some("enum") => parse_enum_nested(parser, schema),
            Some("oneof") => {
                parser.next();
                let oname = parser.next().unwrap();
                parser.expect("{");
                let mut ofields = Vec::new();
                while parser.peek().map(|s| s.as_str()) != Some("}") {
                    let f = parse_field(parser, schema, Some(oname.clone()));
                    ofields.push(f.number);
                    fields.insert(f.number, f);
                }
                parser.expect("}");
                oneofs.insert(oname, ofields);
            }
            Some("reserved") => {
                parser.next();
                while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); }
                parser.expect(";");
            }
            _ => {
                let f = parse_field(parser, schema, None);
                fields.insert(f.number, f);
            }
        }
    }
    parser.expect("}");
    schema.messages.insert(name, MessageDef { fields, oneofs });
}

fn parse_field(parser: &mut ProtoParser, schema: &mut Schema, oneof: Option<String>) -> Field {
    let mut repeated = false;
    let mut optional = false;
    if let Some(t) = parser.peek() {
        if t == "repeated" { repeated = true; parser.next(); }
        else if t == "optional" { optional = true; parser.next(); }
    }
    let (type_, name, number) = if let Some(t) = parser.peek() {
        if t == "map" {
            parser.next(); parser.expect("<");
            let kt = parser.next().unwrap(); parser.expect(",");
            let vt = parser.next().unwrap(); parser.expect(">");
            let fname = parser.next().unwrap(); parser.expect("=");
            let fnum = parser.next().unwrap().parse::<u32>().unwrap();
            parser.expect(";");
            (Type::Message(format!("map_{}_{}", kt, vt)), fname, fnum)
        } else {
            let tname = parser.next().unwrap();
            let fname = parser.next().unwrap();
            parser.expect("=");
            let fnum = parser.next().unwrap().parse::<u32>().unwrap();
            if parser.peek().map(|s| s.as_str()) == Some("[") {
                parser.next();
                while parser.peek().map(|s| s.as_str()) != Some("]") { parser.next(); }
                parser.expect("]");
            }
            parser.expect(";");
            let type_ = match tname.as_str() {
                "int32" => Type::Scalar(ScalarType::Int32), "int64" => Type::Scalar(ScalarType::Int64),
                "uint32" => Type::Scalar(ScalarType::UInt32), "uint64" => Type::Scalar(ScalarType::UInt64),
                "sint32" => Type::Scalar(ScalarType::SInt32), "sint64" => Type::Scalar(ScalarType::SInt64),
                "bool" => Type::Scalar(ScalarType::Bool), "string" => Type::Scalar(ScalarType::String),
                "bytes" => Type::Scalar(ScalarType::Bytes), "fixed32" => Type::Scalar(ScalarType::Fixed32),
                "fixed64" => Type::Scalar(ScalarType::Fixed64), "sfixed32" => Type::Scalar(ScalarType::SFixed32),
                "sfixed64" => Type::Scalar(ScalarType::SFixed64),
                _ => Type::Message(tname),
            };
            (type_, fname, fnum)
        }
    } else { panic!("Field parsing error") };
    Field { number, name, type_, is_repeated: repeated, is_optional: optional, oneof_name: oneof }
}

fn resolve_type(name: &str, schema: &Schema) -> Type {
    if schema.enums.contains_key(name) { Type::Enum(name.to_string()) } else { Type::Message(name.to_string()) }
}

fn decode_message(data: &[u8], pos: &mut usize, schema: &Schema, msg_name: &str) -> Value {
    let msg_def = schema.messages.get(msg_name).expect("Message not found");
    let mut fields = BTreeMap::new();
    while *pos < data.len() {
        let key = decode_varint(data, pos);
        let fnum = (key >> 3) as u32;
        let wtype = (key & 0x7) as u32;
        if let Some(fdef) = msg_def.fields.get(&fnum) {
            let val = match wtype {
                0 => {
                    let v = decode_varint(data, pos);
                    decode_scalar_varint(v, fdef, schema)
                }
                1 => {
                    let mut b = [0u8; 8];
                    for i in 0..8 { b[i] = data[*pos]; *pos += 1; }
                    decode_scalar_fixed64(u64::from_le_bytes(b), fdef)
                }
                2 => {
                    let len = decode_varint(data, pos) as usize;
                    let mut b = vec![0u8; len];
                    for i in 0..len { b[i] = data[*pos]; *pos += 1; }
                    decode_scalar_len_delimited(&b, fdef, schema)
                }
                5 => {
                    let mut b = [0u8; 4];
                    for i in 0..4 { b[i] = data[*pos]; *pos += 1; }
                    decode_scalar_fixed32(u32::from_le_bytes(b), fdef)
                }
                _ => {
                    if wtype == 3 {
                        while *pos < data.len() {
                            let k = decode_varint(data, pos);
                            if (k & 0x7) == 4 && (k >> 3) as u32 == fnum { break; }
                        }
                    } else { *pos += 1; }
                    Value::Scalar(ScalarValue::Bool(false))
                }
            };
            if let Some(oname) = &fdef.oneof_name {
                if let Some(others) = msg_def.oneofs.get(oname) {
                    for &ofnum in others { if ofnum != fnum { fields.remove(&ofnum); } }
                }
            }
            if fdef.is_repeated {
                let entry = fields.entry(fnum).or_insert(Value::Repeated(Vec::new()));
                if let Value::Repeated(ref mut v) = entry {
                    if let Value::Repeated(ref packed) = val { v.extend(packed.clone()); }
                    else { v.push(val); }
                }
            } else {
                let existing = fields.remove(&fnum);
                fields.insert(fnum, merge_values(existing, val, fdef, schema));
            }
        } else {
            match wtype {
                0 => { decode_varint(data, pos); }
                1 => { *pos += 8; }
                2 => { let len = decode_varint(data, pos) as usize; *pos += len; }
                5 => { *pos += 4; }
                3 => {
                    let fn_ = fnum;
                    while *pos < data.len() {
                        let k = decode_varint(data, pos);
                        if (k & 0x7) == 4 && (k >> 3) as u32 == fn_ { break; }
                    }
                }
                _ => { *pos += 1; }
            }
        }
    }
    Value::Message(fields)
}

fn decode_scalar_varint(v: u64, fdef: &Field, schema: &Schema) -> Value {
    match &fdef.type_ {
        Type::Scalar(ScalarType::Int32) => Value::Scalar(ScalarValue::Int32(v as i32)),
        Type::Scalar(ScalarType::Int64) => Value::Scalar(ScalarValue::Int64(v as i64)),
        Type::Scalar(ScalarType::UInt32) => Value::Scalar(ScalarValue::UInt32(v as u32)),
        Type::Scalar(ScalarType::UInt64) => Value::Scalar(ScalarValue::UInt64(v)),
        Type::Scalar(ScalarType::SInt32) => Value::Scalar(ScalarValue::SInt32(decode_zigzag(v) as i32)),
        Type::Scalar(ScalarType::SInt64) => Value::Scalar(ScalarValue::SInt64(decode_zigzag(v))),
        Type::Scalar(ScalarType::Bool) => Value::Scalar(ScalarValue::Bool(v != 0)),
        Type::Enum(name) => Value::Scalar(ScalarValue::Enum(v as i32)),
        _ => Value::Scalar(ScalarValue::Bool(false)),
    }
}

fn decode_scalar_fixed32(v: u32, fdef: &Field) -> Value {
    match &fdef.type_ {
        Type::Scalar(ScalarType::Fixed32) => Value::Scalar(ScalarValue::Fixed32(v)),
        Type::Scalar(ScalarType::SFixed32) => Value::Scalar(ScalarValue::SFixed32(v as i32)),
        _ => Value::Scalar(ScalarValue::Bool(false)),
    }
}

fn decode_scalar_fixed64(v: u64, fdef: &Field) -> Value {
    match &fdef.type_ {
        Type::Scalar(ScalarType::Fixed64) => Value::Scalar(ScalarValue::Fixed64(v)),
        Type::Scalar(ScalarType::SFixed64) => Value::Scalar(ScalarValue::SFixed64(v as i64)),
        _ => Value::Scalar(ScalarValue::Bool(false)),
    }
}

fn decode_scalar_len_delimited(data: &[u8], fdef: &Field, schema: &Schema) -> Value {
    match &fdef.type_ {
        Type::Scalar(ScalarType::String) => Value::Scalar(ScalarValue::String(String::from_utf8_lossy(data).into_owned())),
        Type::Scalar(ScalarType::Bytes) => Value::Scalar(ScalarValue::Bytes(data.to_vec())),
        Type::Message(name) => {
            if name.starts_with("map_") {
                let mut map = BTreeMap::new();
                let mut pos = 0;
                while pos < data.len() {
                    let key = decode_varint(data, &mut pos);
                    let fnum = (key >> 3) as u32;
                    let wtype = (key & 0x7) as u32;
                    let val = match wtype {
                        0 => { let v = decode_varint(data, &mut pos); Value::Scalar(ScalarValue::Int32(v as i32)) }
                        2 => {
                            let len = decode_varint(data, &mut pos) as usize;
                            let mut b = vec![0u8; len];
                            for i in 0..len { b[i] = data[pos]; pos += 1; }
                            Value::Scalar(ScalarValue::String(String::from_utf8_lossy(&b).into_owned()))
                        }
                        _ => { pos += 1; Value::Scalar(ScalarValue::Bool(false)) }
                    };
                    if fnum == 1 {
                        if let Value::Scalar(ScalarValue::Int32(v)) = val { map.insert(MapKey::Int32(v), Value::Scalar(ScalarValue::Bool(false))); }
                        else if let Value::Scalar(ScalarValue::String(v)) = val { map.insert(MapKey::String(v), Value::Scalar(ScalarValue::Bool(false))); }
                    } else if fnum == 2 {
                        // This is tricky because we don't know the key yet.
                        // We'll store it temporarily.
                    }
                }
                // Re-decode map entries properly
                let mut map = BTreeMap::new();
                let mut pos = 0;
                while pos < data.len() {
                    let key_wire = decode_varint(data, &mut pos);
                    let fnum = (key_wire >> 3) as u32;
                    let wtype = (key_wire & 0x7) as u32;
                    let mut entry_key = None;
                    let mut entry_val = None;
                    let start_pos = pos;
                    let mut end_pos = pos;
                    // This is simplified: assume map entries are small and well-formed
                    // In a real impl, we'd decode the embedded message properly.
                    // For this task, we'll use a simpler approach.
                    break;
                }
                Value::Scalar(ScalarValue::Bool(false))
            } else {
                let mut pos = 0;
                let res = resolve_type(name, schema);
                if let Type::Message(n) = res { decode_message(data, &mut pos, schema, &n) }
                else { Value::Scalar(ScalarValue::Bool(false)) }
            }
        }
        _ => Value::Scalar(ScalarValue::Bool(false)),
    }
}

fn merge_values(target: Option<Value>, source: Value, fdef: &Field, schema: &Schema) -> Value {
    match (target, source) {
        (Some(Value::Message(mut t)), Value::Message(s)) => {
            for (fnum, fval) in s {
                if let Some(fd) = fdef.fields.get(&fnum) {
                    let existing = t.remove(&fnum);
                    t.insert(fnum, merge_values(existing, fval, fd, schema));
                }
            }
            Value::Message(t)
        }
        (_, s) => s,
    }
}

fn print_value(val: &Value, fdef: &Field, schema: &Schema) {
    match val {
        Value::Scalar(sv) => {
            match sv {
                ScalarValue::Int32(v) => print!("{}", v),
                ScalarValue::Int64(v) => print!("\"{}\"", v),
                ScalarValue::UInt32(v) => print!("{}", v),
                ScalarValue::UInt64(v) => print!("\"{}\"", v),
                ScalarValue::SInt32(v) => print!("{}", v),
                ScalarValue::SInt64(v) => print!("\"{}\"", v),
                ScalarValue::Bool(v) => print!("{}", if *v { "true" } else { "false" }),
                ScalarValue::String(v) => print!("\"{}\"", escape_json_string(v)),
                ScalarValue::Bytes(v) => print!("\"{}\"", base64_encode(v)),
                ScalarValue::Fixed32(v) => print!("{}", v),
                ScalarValue::Fixed64(v) => print!("\"{}\"", v),
                ScalarValue::SFixed32(v) => print!("{}", v),
                ScalarValue::SFixed64(v) => print!("\"{}\"", v),
                ScalarValue::Enum(v) => {
                    if let Type::Enum(ename) = &fdef.type_ {
                        if let Some(edef) = schema.enums.get(ename) {
                            if let Some(name) = edef.values.get(v) {
                                print!("\"{}\"", name);
                            } else { print!("{}", v); }
                        }
                    } else { print!("{}", v); }
                }
            }
        }
        Value::Message(msg) => {
            print!("{{");
            let mut first = true;
            for (&num, val) in msg {
                if let Some(fd) = fdef.fields.get(&num) {
                    if should_print(val, fd, schema) {
                        if !first { print!(","); }
                        print!("\"{}\":", to_lower_camel_case(&fd.name));
                        print_value(val, fd, schema);
                        first = false;
                    }
                }
            }
            print!("}}");
        }
        Value::Repeated(vec) => {
            print!("[");
            for (i, val) in vec.iter().enumerate() {
                if i > 0 { print!(","); }
                // We need the field definition of the repeated element
                // Since it's the same as the parent field's type
                print_value(val, fdef, schema);
            }
            print!("]");
        }
        Value::Map(map) => {
            print!("{{");
            let mut first = true;
            for (key, val) in map {
                if !first { print!(","); }
                match key {
                    MapKey::String(s) => print!("\"{}\"", escape_json_string(s)),
                    MapKey::Int32(i) => print!("\"{}\"", i),
                }
                print!(":");
                // Map values are printed even if default
                // We need the map value type
                // For now, let's just print it.
                print_value(val, fdef, schema);
                first = false;
            }
            print!("}}");
        }
    }
}

fn should_print(val: &Value, fdef: &Field, schema: &Schema) -> bool {
    match val {
        Value::Scalar(sv) => {
            if fdef.is_optional || fdef.oneof_name.is_some() { return true; }
            match &fdef.type_ {
                Type::Scalar(ScalarType::Int32) => { if let Value::Scalar(ScalarValue::Int32(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::Int64) => { if let Value::Scalar(ScalarValue::Int64(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::UInt32) => { if let Value::Scalar(ScalarValue::UInt32(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::UInt64) => { if let Value::Scalar(ScalarValue::UInt64(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::SInt32) => { if let Value::Scalar(ScalarValue::SInt32(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::SInt64) => { if let Value::Scalar(ScalarValue::SInt64(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::Bool) => { if let Value::Scalar(ScalarValue::Bool(v)) = val { *v } else { false } }
                Type::Scalar(ScalarType::String) => { if let Value::Scalar(ScalarValue::String(v)) = val { !v.is_empty() } else { false } }
                Type::Scalar(ScalarType::Bytes) => { if let Value::Scalar(ScalarValue::Bytes(v)) = val { !v.is_empty() } else { false } }
                Type::Scalar(ScalarType::Fixed32) => { if let Value::Scalar(ScalarValue::Fixed32(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::SFixed32) => { if let Value::Scalar(ScalarValue::SFixed32(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::Fixed64) => { if let Value::Scalar(ScalarValue::Fixed64(v)) = val { *v != 0 } else { false } }
                Type::Scalar(ScalarType::SFixed64) => { if let Value::Scalar(ScalarValue::SFixed64(v)) = val { *v != 0 } else { false } }
                Type::Enum(ename) => {
                    if let Some(edef) = schema.enums.get(ename) {
                        let mut zero_val = 0;
                        for (v, _) in &edef.values { if *v == 0 { zero_val = 0; break; } } // Simplified
                        if let Value::Scalar(ScalarValue::Enum(v)) = val { *v != 0 } else { false }
                    } else { true }
                }
                _ => true,
            }
        }
        Value::Message(_) => true,
        Value::Repeated(v) => !v.is_empty(),
        Value::Map(m) => !m.is_empty(),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let proto_content = fs::read_to_string(format!("{}/schema.proto", dir)).unwrap();
    let schema = parse_proto(&proto_content);
    let mut bin_data = Vec::new();
    fs::File::open(format!("{}/messages.bin", dir)).unwrap().read_to_end(&mut bin_data).unwrap();
    let mut pos = 0;
    while pos < bin_data.len() {
        let len = decode_varint(&bin_data, &mut pos) as usize;
        let mut msg_pos = 0;
        let decoded = decode_message(&bin_data[pos..pos + len], &mut msg_pos, &schema, &schema.root_type);
        if let Value::Message(ref fields) = decoded {
            print!("{{");
            let mut first = true;
            for (&num, val) in fields {
                if let Some(fdef) = schema.messages.get(&schema.root_type).unwrap().fields.get(&num) {
                    if should_print(val, fdef, &schema) {
                        if !first { print!(","); }
                        print!("\"{}\":", to_lower_camel_case(&fdef.name));
                        print_value(val, fdef, &schema);
                        first = false;
                    }
                }
            }
            print!("}}");
        }
        println!();
        pos += len;
    }
}

use std::collections::{BTreeMap, HashMap, HashSet};
use std::env;
use std::fs;
use std::io::Read;

#[derive(Debug, Clone, PartialEq, Eq)]
enum ScalarType {
    Int32, Int64, UInt32, UInt64, SInt32, SInt64,
    Bool, String, Bytes, Fixed32, Fixed64, SFixed32, SFixed64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Type {
    Scalar(ScalarType),
    Message(String),
    Enum(String),
    Map { key_type: Box<Type>, value_type: Box<Type> },
}

#[derive(Debug, Clone)]
struct Field {
    number: u32,
    name: String,
    type_: Type,
    is_repeated: bool,
    is_optional: bool,
    oneof_name: Option<String>,
    msg_name: String,
}

#[derive(Debug, Clone)]
struct EnumDef {
    values: HashMap<i32, String>,
}

#[derive(Debug, Clone)]
struct MessageDef {
    fields: HashMap<u32, Field>,
    oneofs: HashMap<String, Vec<u32>>,
}

struct Schema {
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root_type: String,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum MapKey {
    Int32(i32),
    String(String),
}

#[derive(Debug, Clone, PartialEq)]
enum ScalarValue {
    I32(i32), I64(i64), U32(u32), U64(u64),
    SI32(i32), SI64(i64), B(bool), S(String),
    Bytes(Vec<u8>), F32(u32), F64(u64),
    SF32(i32), SF64(i64), Enum(i32),
}

#[derive(Debug, Clone)]
enum Value {
    Scalar(ScalarValue),
    Msg(MessageValue),
    List(Vec<Value>),
    Map(BTreeMap<MapKey, Value>),
}

#[derive(Debug, Clone)]
struct MessageValue {
    fields: BTreeMap<u32, Value>,
    present: HashSet<u32>,
}

fn decode_varint(data: &[u8], pos: &mut usize) -> u64 {
    let mut result = 0u64;
    let mut shift = 0;
    while *pos < data.len() {
        let byte = data[*pos];
        *pos += 1;
        result |= ((byte & 0x7F) as u64) << shift;
        if byte & 0x80 == 0 { break; }
        shift += 7;
        if shift >= 64 { break; }
    }
    result
}

fn decode_zigzag(n: u64) -> i64 {
    ((n >> 1) as i64) ^ (-((n & 1) as i64))
}

fn base64_encode(data: &[u8]) -> String {
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b1 = chunk[0];
        let b2 = if chunk.len() > 1 { chunk[1] } else { 0 };
        let b3 = if chunk.len() > 2 { chunk[2] } else { 0 };
        let n = (b1 as u32) << 16 | (b2 as u32) << 8 | (b3 as u32);
        result.push(alphabet[((n >> 18) & 63) as usize] as char);
        result.push(alphabet[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 { result.push(alphabet[((n >> 6) & 63) as usize] as char); } else { result.push('='); }
        if chunk.len() > 2 { result.push(alphabet[(n & 63) as usize] as char); } else { result.push('='); }
    }
    result
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{0009}' => result.push_str("\\t"),
            '\u{000a}' => result.push_str("\\n"),
            '\u{000c}' => result.push_str("\\f"),
            '\u{000d}' => result.push_str("\\r"),
            c if c < '\u{0020}' => result.push_str(&format!("\\u{:04x}", c as u32)),
            _ => result.push(c),
        }
    }
    result
}

fn to_lower_camel_case(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    if let Some(c) = chars.next() { result.push(c); }
    while let Some(c) = chars.next() {
        if c == '_' {
            if let Some(&next) = chars.peek() {
                if next.is_ascii_lowercase() {
                    result.push(next.to_ascii_uppercase());
                    chars.next();
                }
            }
        } else { result.push(c); }
    }
    result
}

fn tokenize(input: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut i = 0;
    let bytes = input.as_bytes();
    while i < bytes.len() {
        if bytes[i].is_ascii_whitespace() { i += 1; }
        else if bytes[i] == b'/' && i + 1 < bytes.len() && bytes[i + 1] == b'/' {
            while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
        } else if bytes[i] == b'/' && i + 1 < bytes.len() && bytes[i + 1] == b'*' {
            i += 2;
            while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') { i += 1; }
            i += 2;
        } else if bytes[i] == b'"' {
            let mut s = String::new();
            i += 1;
            while i < bytes.len() && bytes[i] != b'"' { s.push(bytes[i] as char); i += 1; }
            i += 1;
            tokens.push(format!("\"{}\"", s));
        } else if bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' {
            let mut s = String::new();
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                s.push(bytes[i] as char); i += 1;
            }
            tokens.push(s);
        } else if bytes[i].is_ascii_digit() || bytes[i] == b'-' {
            let mut s = String::new();
            if bytes[i] == b'-' { s.push('-'); i += 1; }
            while i < bytes.len() && bytes[i].is_ascii_digit() { s.push(bytes[i] as char); i += 1; }
            tokens.push(s);
        } else {
            tokens.push((bytes[i] as char).to_string());
            i += 1;
        }
    }
    tokens
}

struct ProtoParser { tokens: Vec<String>, pos: usize }
impl ProtoParser {
    fn next(&mut self) -> Option<String> {
        if self.pos >= self.tokens.len() { return None; }
        let t = self.tokens[self.pos].clone();
        self.pos += 1;
        Some(t)
    }
    fn peek(&self) -> Option<&String> { self.tokens.get(self.pos) }
    fn expect(&mut self, e: &str) {
        if self.next().as_deref() != Some(e) { panic!("Expected {}", e); }
    }
}

fn parse_proto(input: &str) -> Schema {
    let mut parser = ProtoParser { tokens: tokenize(input), pos: 0 };
    let mut schema = Schema { messages: HashMap::new(), enums: HashMap::new(), root_type: String::new() };
    while let Some(t) = parser.next() {
        match t.as_str() {
            "syntax" => { parser.expect("="); parser.next(); parser.expect(";"); }
            "package" => { while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); } parser.expect(";"); }
            "option" => { while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); } parser.expect(";"); }
            "message" => {
                let name = parser.next().unwrap();
                if schema.root_type.is_empty() { schema.root_type = name.clone(); }
                parse_msg_nested(&mut parser, &mut schema, name);
            }
            "enum" => parse_enum_nested(&mut parser, &mut schema),
            _ => {}
        }
    }
    schema
}

fn parse_enum_nested(parser: &mut ProtoParser, schema: &mut Schema) {
    let name = parser.next().unwrap();
    parser.expect("{");
    let mut values = HashMap::new();
    while parser.peek().map(|s| s.as_str()) != Some("}") {
        if parser.peek().map(|s| s.as_str()) == Some("option") {
            parser.next();
            while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); }
            parser.expect(";");
        } else {
            let vname = parser.next().unwrap();
            parser.expect("=");
            let vnum = parser.next().unwrap().parse::<i32>().unwrap();
            parser.expect(";");
            values.insert(vnum, vname);
        }
    }
    parser.expect("}");
    schema.enums.insert(name, EnumDef { values });
}

fn parse_msg_nested(parser: &mut ProtoParser, schema: &mut Schema, name: String) {
    parser.expect("{");
    let mut fields = HashMap::new();
    let mut oneofs = HashMap::new();
    while parser.peek().map(|s| s.as_str()) != Some("}") {
        match parser.peek().map(|s| s.as_str()) {
            Some("message") => {
                parser.next();
                let nested_name = parser.next().unwrap();
                parse_msg_nested(parser, schema, nested_name);
            }
            Some("enum") => {
                parser.next();
                let enum_name = parser.next().unwrap();
                parse_enum_nested(parser, schema);
            }
            Some("oneof") => {
                parser.next();
                let oname = parser.next().unwrap();
                parser.expect("{");
                let mut ofields = Vec::new();
                while parser.peek().map(|s| s.as_str()) != Some("}") {
                    let f = parse_field(parser, schema, Some(oname.clone()), name.clone());
                    ofields.push(f.number);
                    fields.insert(f.number, f);
                }
                parser.expect("}");
                oneofs.insert(oname, ofields);
            }
            Some("reserved") => {
                parser.next();
                while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); }
                parser.expect(";");
            }
            Some("option") => {
                parser.next();
                while parser.peek().map(|s| s.as_str()) != Some(";") { parser.next(); }
                parser.expect(";");
            }
            _ => {
                let f = parse_field(parser, schema, None, name.clone());
                fields.insert(f.number, f);
            }
        }
    }
    parser.expect("}");
    schema.messages.insert(name, MessageDef { fields, oneofs });
}

fn parse_field(parser: &mut ProtoParser, schema: &mut Schema, oneof: Option<String>, msg_name: String) -> Field {
    let mut repeated = false;
    let mut optional = false;
    if let Some(t) = parser.peek() {
        if t == "repeated" { repeated = true; parser.next(); }
        else if t == "optional" { optional = true; parser.next(); }
    }
    let (type_, name, number) = if let Some(t) = parser.peek() {
        if t == "map" {
            parser.next(); parser.expect("<");
            let kt_name = parser.next().unwrap(); parser.expect(",");
            let vt_name = parser.next().unwrap(); parser.expect(">");
            let fname = parser.next().unwrap(); parser.expect("=");
            let fnum = parser.next().unwrap().parse::<u32>().unwrap();
            if parser.peek().map(|s| s.as_str()) == Some("[") {
                parser.next();
                while parser.peek().map(|s| s.as_str()) != Some("]") { parser.next(); }
                parser.expect("]");
            }
            parser.expect(";");
            let kt = match kt_name.as_str() {
                "int32" => Type::Scalar(ScalarType::Int32),
                "string" => Type::Scalar(ScalarType::String),
                _ => panic!("Unsupported map key type"),
            };
            let vt = match vt_name.as_str() {
                "int32" => Type::Scalar(ScalarType::Int32),
                "int64" => Type::Scalar(ScalarType::Int64),
                "uint32" => Type::Scalar(ScalarType::UInt32),
                "uint64" => Type::Scalar(ScalarType::UInt64),
                "sint32" => Type::Scalar(ScalarType::SInt32),
                "sint64" => Type::Scalar(ScalarType::SInt64),
                "bool" => Type::Scalar(ScalarType::Bool),
                "string" => Type::Scalar(ScalarType::String),
                "bytes" => Type::Scalar(ScalarType::Bytes),
                "fixed32" => Type::Scalar(ScalarType::Fixed32),
                "fixed64" => Type::Scalar(ScalarType::Fixed64),
                "sfixed32" => Type::Scalar(ScalarType::SFixed32),
                "sfixed64" => Type::Scalar(ScalarType::SFixed64),
                _ => {
                    if schema.enums.contains_key(vt_name) { Type::Enum(vt_name.to_string()) } else { Type::Message(vt_name.to_string()) }
                }
            };
            (Type::Map { key_type: Box::new(kt), value_type: Box::new(vt) }, fname, fnum)
        } else {
            let tname = parser.next().unwrap();
            let fname = parser.next().unwrap();
            parser.expect("=");
            let fnum = parser.next().unwrap().parse::<u32>().unwrap();
            if parser.peek().map(|s| s.as_str()) == Some("[") {
                parser.next();
                while parser.peek().map(|s| s.as_str()) != Some("]") { parser.next(); }
                parser.expect("]");
            }
            parser.expect(";");
            let type_ = match tname.as_str() {
                "int32" => Type::Scalar(ScalarType::Int32), "int64" => Type::Scalar(ScalarType::Int64),
                "uint32" => Type::Scalar(ScalarType::UInt32), "uint64" => Type::Scalar(ScalarType::UInt64),
                "sint32" => Type::Scalar(ScalarType::SInt32), "sint64" => Type::Scalar(ScalarType::SInt64),
                "bool" => Type::Scalar(ScalarType::Bool), "string" => Type::Scalar(ScalarType::String),
                "bytes" => Type::Scalar(ScalarType::Bytes), "fixed32" => Type::Scalar(ScalarType::Fixed32),
                "fixed64" => Type::Scalar(ScalarType::Fixed64), "sfixed32" => Type::Scalar(ScalarType::SFixed32),
                "sfixed64" => Type::Scalar(ScalarType::SFixed64),
                _ => {
                    if schema.enums.contains_key(tname) { Type::Enum(tname.to_string()) } else { Type::Message(tname.to_string()) }
                }
            };
            (type_, fname, fnum)
        }
    } else { panic!("Field parsing error") };
    Field { number, name, type_, is_repeated: repeated, is_optional: optional, oneof_name: oneof, msg_name: msg_name }
}

fn decode_scalar_varint(v: u64, fdef: &Field, schema: &Schema) -> Value {
    match &fdef.type_ {
        Type::Scalar(ScalarType::Int32) => Value::Scalar(ScalarValue::I32(v as i32)),
        Type::Scalar(ScalarType::Int64) => Value::Scalar(ScalarValue::I64(v as i64)),
        Type::Scalar(ScalarType::UInt32) => Value::Scalar(ScalarValue::U32(v as u32)),
        Type::Scalar(ScalarType::UInt64) => Value::Scalar(ScalarValue::U64(v)),
        Type::Scalar(ScalarType::SInt32) => Value::Scalar(ScalarValue::SI32(decode_zigzag(v) as i32)),
        Type::Scalar(ScalarType::SInt64) => Value::Scalar(ScalarValue::SI64(decode_zigzag(v))),
        Type::Scalar(ScalarType::Bool) => Value::Scalar(ScalarValue::B(v != 0)),
        Type::Enum(name) => Value::Scalar(ScalarValue::Enum(v as i32)),
        _ => Value::Scalar(ScalarValue::B(false)),
    }
}

fn decode_scalar_fixed32(v: u32, fdef: &Field) -> Value {
    match &fdef.type_ {
        Type::Scalar(ScalarType::Fixed32) => Value::Scalar(ScalarValue::F32(v)),
        Type::Scalar(ScalarType::SFixed32) => Value::Scalar(ScalarValue::SF32(v as i32)),
        _ => Value::Scalar(ScalarValue::B(false)),
    }
}

fn decode_scalar_fixed64(v: u64, fdef: &Field) -> Value {
    match &fdef.type_ {
        Type::Scalar(ScalarType::Fixed64) => Value::Scalar(ScalarValue::F64(v)),
        Type::Scalar(ScalarType::SFixed64) => Value::Scalar(ScalarValue::SF64(v as i64)),
        _ => Value::Scalar(ScalarValue::B(false)),
    }
}

fn decode_message(data: &[u8], pos: &mut usize, schema: &Schema, msg_name: &str) -> MessageValue {
    let msg_def = schema.messages.get(msg_name).expect("Message not found");
    let mut mv = MessageValue { fields: BTreeMap::new(), present: HashSet::new() };
    while *pos < data.len() {
        let key = decode_varint(data, pos);
        let fnum = (key >> 3) as u32;
        let wtype = (key & 0x7) as u32;
        if let Some(fdef) = msg_def.fields.get(&fnum) {
            let val = match wtype {
                0 => {
                    let v = decode_varint(data, pos);
                    decode_scalar_varint(v, fdef, schema)
                }
                1 => {
                    let mut b = [0u8; 8];
                    for i in 0..8 { b[i] = data[*pos]; *pos += 1; }
                    decode_scalar_fixed64(u64::from_le_bytes(b), fdef)
                }
                2 => {
                    let len = decode_varint(data, pos) as usize;
                    let mut b = vec![0u8; len];
                    for i in 0..len { b[i] = data[*pos]; *pos += 1; }
                    if let Type::Scalar(ScalarType::String) = fdef.type_ {
                        Value::Scalar(ScalarValue::S(String::from_utf8_lossy(&b).into_owned()))
                    } else if let Type::Scalar(ScalarType::Bytes) = fdef.type_ {
                        Value::Scalar(ScalarValue::Bytes(b))
                    } else if let Type::Message(ref name) = fdef.type_ {
                        let mut mpos = 0;
                        Value::Msg(decode_message(&b, &mut mpos, schema, name))
                    } else if let Type::Map { .. } = fdef.type_ {
                        let mut mpos = 0;
                        Value::Msg(decode_message(&b, &mut mpos, schema, "map_entry")) // Temporary name
                    } else {
                        Value::Scalar(ScalarValue::B(false))
                    }
                }
                5 => {
                    let mut b = [0u8; 4];
                    for i in 0..4 { b[i] = data[*pos]; *pos += 1; }
                    decode_scalar_fixed32(u32::from_le_bytes(b), fdef)
                }
                _ => {
                    // Group or unknown
                    if wtype == 3 {
                        while *pos < data.len() {
                            let k = decode_varint(data, pos);
                            if (k & 0x7) == 4 && (k >> 3) as u32 == fnum { break; }
                        }
                    } else { *pos += 1; }
                    Value::Scalar(ScalarValue::B(false))
                }
            };
            merge_field(&mut mv, fnum, val, fdef, schema);
        } else {
            match wtype {
                0 => { decode_varint(data, pos); }
                1 => { *pos += 8; }
                2 => { let len = decode_varint(data, pos) as usize; *pos += len; }
                5 => { *pos += 4; }
                3 => {
                    let fn_ = fnum;
                    while *pos < data.len() {
                        let k = decode_varint(data, pos);
                        if (k & 0x7) == 4 && (k >> 3) as u32 == fn_ { break; }
                    }
                }
                _ => { *pos += 1; }
            }
        }
    }
    mv
}

fn merge_field(mv: &mut MessageValue, fnum: u32, val: Value, fdef: &Field, schema: &Schema) {
    if let Some(oname) = &fdef.oneof_name {
        if let Some(others) = schema.messages.get(&fdef.msg_name).unwrap().oneofs.get(oname) {
            for &ofnum in others {
                if ofnum != fnum {
                    mv.fields.remove(&ofnum);
                    mv.present.remove(&ofnum);
                }
            }
        }
    }
    if fdef.is_repeated {
        let entry = mv.fields.entry(fnum).or_insert(Value::List(Vec::new()));
        if let Value::List(ref mut list) = entry {
            match val {
                Value::List(ref source_list) => list.extend(source_list.clone()),
                _ => list.push(val),
            }
        }
    } else if let Type::Map { ref key_type, ref value_type } = fdef.type_ {
        let entry = mv.fields.entry(fnum).or_insert(Value::Map(BTreeMap::new()));
        if let Value::Map(ref mut map) = entry {
            if let Value::Msg(ref entry_msg) = val {
                let key = decode_map_key(entry_msg, key_type, schema);
                let value = decode_map_value(entry_msg, value_type, schema);
                map.insert(key, value);
            }
        }
        mv.present.insert(fnum);
    } else if let Type::Message(ref name) = fdef.type_ {
        if let Value::Msg(ref mut target_msg) = mv.fields.entry(fnum).or_insert_with(|| {
            Value::Msg(MessageValue { fields: BTreeMap::new(), present: HashSet::new() })
        }) {
            if let Value::Msg(source_msg) = val {
                let source_fields = source_msg.fields.clone();
                let msg_def = schema.messages.get(name).expect("Message not found");
                for (&sfnum, sv) in &source_fields {
                    if let Some(sfdef) = msg_def.fields.get(&sfnum) {
                        merge_field(target_msg, sfnum, sv.clone(), sfdef, schema);
                    }
                }
            }
        }
        mv.present.insert(fnum);
    } else {
        mv.fields.insert(fnum, val);
        mv.present.insert(fnum);
    }
}

fn decode_map_key(entry: &MessageValue, kt: &Type, schema: &Schema) -> MapKey {
    if let Some(Value::Scalar(sv)) = entry.fields.get(&1) {
        match sv {
            ScalarValue::I32(v) => MapKey::Int32(*v),
            ScalarValue::S(v) => MapKey::String(v.clone()),
            _ => match kt {
                Type::Scalar(ScalarType::Int32) => MapKey::Int32(0),
                _ => MapKey::String("".to_string()),
            },
        }
    } else {
        match kt {
            Type::Scalar(ScalarType::Int32) => MapKey::Int32(0),
            _ => MapKey::String("".to_string()),
        }
    }
}

fn decode_map_value(entry: &MessageValue, vt: &Type, schema: &Schema) -> Value {
    if let Some(val) = entry.fields.get(&2) {
        val.clone()
    } else {
        match vt {
            Type::Scalar(st) => match st {
                ScalarType::Int32 => Value::Scalar(ScalarValue::I32(0)),
                ScalarType::Int64 => Value::Scalar(ScalarValue::I64(0)),
                ScalarType::UInt32 => Value::Scalar(ScalarValue::U32(0)),
                ScalarType::UInt64 => Value::Scalar(ScalarValue::U64(0)),
                ScalarType::SInt32 => Value::Scalar(ScalarValue::SI32(0)),
                ScalarType::SInt64 => Value::Scalar(ScalarValue::SI64(0)),
                ScalarType::Bool => Value::Scalar(ScalarValue::B(false)),
                ScalarType::String => Value::Scalar(ScalarValue::S("".to_string())),
                ScalarType::Bytes => Value::Scalar(ScalarValue::Bytes(vec![])),
                ScalarType::Fixed32 => Value::Scalar(ScalarValue::F32(0)),
                ScalarType::Fixed64 => Value::Scalar(ScalarValue::F64(0)),
                ScalarType::SFixed32 => Value::Scalar(ScalarValue::SF32(0)),
                ScalarType::SFixed64 => Value::Scalar(ScalarValue::SF64(0)),
            },
            Type::Enum(name) => Value::Scalar(ScalarValue::Enum(0)),
            Type::Message(name) => {
                let mut pos = 0;
                Value::Msg(decode_message(&[], &mut pos, schema, name))
            }
            _ => Value::Scalar(ScalarValue::B(false)),
        }
    }
}

fn print_value(val: &Value, fdef: &Field, schema: &Schema) {
    match val {
        Value::Scalar(sv) => {
            match sv {
                ScalarValue::I32(v) => print!("{}", v),
                ScalarValue::I64(v) => print!("\"{}\"", v),
                ScalarValue::U32(v) => print!("{}", v),
                ScalarValue::U64(v) => print!("\"{}\"", v),
                ScalarValue::SI32(v) => print!("{}", v),
                ScalarValue::SI64(v) => print!("\"{}\"", v),
                ScalarValue::B(v) => print!("{}", if *v { "true" } else { "false" }),
                ScalarValue::S(v) => print!("\"{}\"", escape_json_string(v)),
                ScalarValue::Bytes(v) => print!("\"{}\"", base64_encode(v)),
                ScalarValue::F32(v) => print!("{}", v),
                ScalarValue::F64(v) => print!("\"{}\"", v),
                ScalarValue::SF32(v) => print!("{}", v),
                ScalarValue::SF64(v) => print!("\"{}\"", v),
                ScalarValue::Enum(v) => {
                    if let Type::Enum(ename) = &fdef.type_ {
                        if let Some(edef) = schema.enums.get(ename) {
                            if let Some(name) = edef.values.get(v) {
                                print!("\"{}\"", name);
                            } else { print!("{}", v); }
                        } else { print!("{}", v); }
                    } else { print!("{}", v); }
                }
            }
        }
        Value::Msg(mv) => {
            print!("{{");
            let mut first = true;
            let msg_def = schema.messages.get(&fdef.msg_name).expect("Message not found");
            for (&num, val) in &mv.fields {
                if let Some(fd) = msg_def.fields.get(&num) {
                    if should_print(val, fd, schema) {
                        if !first { print!(","); }
                        print!("\"{}\":", to_lower_camel_case(&fd.name));
                        print_value(val, fd, schema);
                        first = false;
                    }
                }
            }
            print!("}}");
        }
        Value::List(list) => {
            print!("[");
            for (i, val) in list.iter().enumerate() {
                if i > 0 { print!(","); }
                print_value(val, fdef, schema);
            }
            print!("]");
        }
        Value::Map(map) => {
            print!("{{");
            let mut first = true;
            for (key, val) in map {
                if !first { print!(","); }
                match key {
                    MapKey::Int32(i) => print!("\"{}\"", i),
                    MapKey::String(s) => print!("\"{}\"", escape_json_string(s)),
                }
                print!(":");
                // Map value type
                if let Type::Map { ref value_type, .. } = fdef.type_ {
                    let val_fdef = Field {
                        number: 0, name: "".to_string(), type_: *value_type.clone(),
                        is_repeated: false, is_optional: false, oneof_name: None,
                        msg_name: fdef.msg_name.clone(),
                    };
                    print_value(val, &val_fdef, schema);
                }
                first = false;
            }
            print!("}}");
        }
    }
}

fn should_print(val: &Value, fdef: &Field, schema: &Schema) -> bool {
    match val {
        Value::Scalar(sv) => {
            if fdef.is_optional || fdef.oneof_name.is_some() { return true; }
            match &fdef.type_ {
                Type::Scalar(st) => match st {
                    ScalarType::Int32 => if let ScalarValue::I32(v) = sv { *v != 0 } else { false },
                    ScalarType::Int64 => if let ScalarValue::I64(v) = sv { *v != 0 } else { false },
                    ScalarType::UInt32 => if let ScalarValue::U32(v) = sv { *v != 0 } else { false },
                    ScalarType::UInt64 => if let ScalarValue::U64(v) = sv { *v != 0 } else { false },
                    ScalarType::SInt32 => if let ScalarValue::SI32(v) = sv { *v != 0 } else { false },
                    ScalarType::SInt64 => if let ScalarValue::SI64(v) = sv { *v != 0 } else { false },
                    ScalarType::Bool => if let ScalarValue::B(v) = sv { *v } else { false },
                    ScalarType::String => if let ScalarValue::S(v) = sv { !v.is_empty() } else { false },
                    ScalarType::Bytes => if let ScalarValue::Bytes(v) = sv { !v.is_empty() } else { false },
                    ScalarType::Fixed32 => if let ScalarValue::F32(v) = sv { *v != 0 } else { false },
                    ScalarType::Fixed64 => if let ScalarValue::F64(v) = sv { *v != 0 } else { false },
                    ScalarType::SFixed32 => if let ScalarValue::SF32(v) = sv { *v != 0 } else { false },
                    ScalarType::SFixed64 => if let ScalarValue::SF64(v) = sv { *v != 0 } else { false },
                },
                Type::Enum(ename) => {
                    if let Some(edef) = schema.enums.get(ename) {
                        if let ScalarValue::Enum(v) = sv { *v != 0 } else { false }
                    } else { true }
                }
                _ => true,
            }
        }
        Value::Msg(_) => true,
        Value::List(v) => !v.is_empty(),
        Value::Map(m) => !m.is_empty(),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let proto_content = fs::read_to_string(format!("{}/schema.proto", dir)).unwrap();
    let schema = parse_proto(&proto_content);
    let mut bin_data = Vec::new();
    fs::File::open(format!("{}/messages.bin", dir)).unwrap().read_to_end(&mut bin_data).unwrap();
    let mut pos = 0;
    while pos < bin_data.len() {
        let len = decode_varint(&bin_data, &mut pos) as usize;
        let mut msg_pos = 0;
        let decoded = decode_message(&bin_data[pos..pos + len], &mut msg_pos, &schema, &schema.root_type);
        print!("{{");
        let mut first = true;
        let root_def = schema.messages.get(&schema.root_type).unwrap();
        for (&num, val) in &decoded.fields {
            if let Some(fdef) = root_def.fields.get(&num) {
                if should_print(val, fdef, &schema) {
                    if !first { print!(","); }
                    print!("\"{}\":", to_lower_camel_case(&fdef.name));
                    print_value(val, fdef, &schema);
                    first = false;
                }
            }
        }
        print!("}}");
        println!();
        pos += len;
    }
}

import json
import sys
import os
import http.client
from urllib.parse import urlparse

def escape_str(s):
    """Escapes strings according to the prompt's requirements."""
    return s.replace('\\', '\\\\').replace('\n', '\\n').replace('\r', '\\r').replace('\t', '\\t')

def run_tool(name, input_json):
    """Executes the requested tool and returns the result and a failure flag."""
    try:
        params = json.loads(input_json)
        if name == "measure":
            text = params.get("text", "")
            unit = params.get("unit", "")
            if unit == "code_points":
                return str(len(text)), False
            elif unit == "utf8_bytes":
                return str(len(text.encode('utf-8'))), False
            elif unit == "utf16_units":
                return str(len(text.encode('utf-16-le')) // 2), False
            else:
                return f"unsupported unit: {unit}", True
        elif name == "reverse":
            text = params.get("text", "")
            return text[::-1], False
        else:
            return f"unknown tool: {name}", True
    except Exception:
        return "invalid JSON input", True

def parse_sse_stream(response):
    """Parses a Server-Sent Events stream from an HTTP response."""
    buffer = ""
    current_event = None
    current_data = []
    while True:
        chunk = response.read(4096)
        if not chunk:
            break
        buffer += chunk.decode('utf-8', errors='replace')
        while "\n" in buffer:
            line, buffer = buffer.split("\n", 1)
            line = line.rstrip('\r')
            if not line:
                if current_event:
                    yield current_event, "\n".join(current_data)
                    current_event = None
                    current_data = []
                continue
            if line.startswith(":"):
                continue
            if line.startswith("event:"):
                val = line[6:]
                if val.startswith(" "): val = val[1:]
                current_event = val
            elif line.startswith("data:"):
                val = line[5:]
                if val.startswith(" "): val = val[1:]
                current_data.append(val)

def handle_request(conn, endpoint, request_params):
    """Sends a POST request and processes the streaming response."""
    headers = {
        "x-api-key": request_params['api_key'],
        "anthropic-version": "2023-06-01",
        "content-type": "application/json"
    }

    # Construct body based on prompt requirements
    body = {
        "model": request_params['model'],
        "max_tokens": request_params['max_tokens'],
        "stream": True,
        "thinking": {"type": "enabled", "budget_tokens": request_params['thinking_budget']},
        "system": request_params['system'],
        "tools": request_params['tools'],
        "messages": request_params['messages']
    }

    conn.request("POST", endpoint, body=json.dumps(body), headers=headers)
    response = conn.getresponse()

    if response.status != 200:
        error_data = json.loads(response.read().decode('utf-8'))
        return None, f"ERROR {response.status} {error_data['error']['type']}: {error_data['error']['message']}"

    # Process SSE stream
    blocks = {}
    total_input_tokens = 0
    total_cache_read_tokens = 0
    total_output_tokens = 0
    stop_reason = ""

    for event, data_str in parse_sse_stream(response):
        data = json.loads(data_str)
        if event == "message_start":
            usage = data.get("message", {}).get("usage", {})
            total_input_tokens += usage.get("input_tokens", 0)
            total_cache_read_tokens += usage.get("cache_read_input_tokens", 0)
        elif event == "content_block_start":
            idx = data['index']
            block = data['content_block']
            blocks[idx] = {"type": block['type'], "text": "", "signature": "", "id": None, "name": None, "input": ""}
            if block['type'] == "tool_use":
                blocks[idx]["id"] = block['id']
                blocks[idx]["name"] = block['name']
        elif event == "content_block_delta":
            idx = data['index']
            delta = data['delta']
            if delta['type'] == "thinking_delta":
                blocks[idx]["text"] += delta['thinking']
            elif delta['type'] == "signature_delta":
                blocks[idx]["signature"] += delta['signature']
            elif delta['type'] == "text_delta":
                blocks[idx]["text"] += delta['text']
            elif delta['type'] == "input_json_delta":
                blocks[idx]["input"] += delta['partial_json']
        elif event == "content_block_stop":
            pass
        elif event == "message_delta":
            stop_reason = data.get("delta", {}).get("stop_reason", "")
            total_output_tokens += data.get("usage", {}).get("output_tokens", 0)
        elif event == "message_stop":
            pass

    return {
        "blocks": blocks,
        "stop_reason": stop_reason,
        "input_tokens": total_input_tokens,
        "cache_read_tokens": total_cache_read_tokens,
        "output_tokens": total_output_tokens
    }, None

def main():
    if len(sys.argv) < 3:
        return
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(os.path.join(data_dir, 'request.json'), 'r') as f:
        req_data = json.load(f)

    parsed_url = urlparse(base_url)
    conn = http.client.HTTPConnection(parsed_url.hostname, parsed_url.port)
    endpoint = parsed_url.path.rstrip('/') + '/v1/messages'

    # Request 1
    req_params_1 = req_data.copy()
    req_params_1['messages'] = [{"role": "user", "content": req_data['prompt']}]

    res1, err1 = handle_request(conn, endpoint, req_params_1)
    if err1:
        print(err1)
        sys.exit(0)

    # Build transcript for Request 1
    transcript = ["request 1"]
    sorted_indices = sorted(res1['blocks'].keys())
    tool_uses = []

    for idx in sorted_indices:
        block = res1['blocks'][idx]
        if block['type'] == 'thinking':
            transcript.append(f"thinking {escape_str(block['text'])}")
            transcript.append(f"signature {escape_str(block['signature'])}")
        elif block['type'] == 'text':
            transcript.append(f"text {escape_str(block['text'])}")
        elif block['type'] == 'tool_use':
            transcript.append(f"tool_use {block['id']} {block['name']} {escape_str(block['input'])}")
            tool_uses.append(block)

    transcript.append(f"stop_reason {res1['stop_reason']}")

    # Run tools and record results
    tool_results = []
    for tu in tool_uses:
        result, is_error = run_tool(tu['name'], tu['input'])
        tool_results.append({"id": tu['id'], "result": result, "is_error": is_error})
        if is_error:
            transcript.append(f"error {tu['id']} {escape_str(result)}")
        else:
            transcript.append(f"result {tu['id']} {escape_str(result)}")

    # Request 2
    # Rebuild assistant message content blocks
    assistant_content = []
    for idx in sorted_indices:
        block = res1['blocks'][idx]
        if block['type'] == 'thinking':
            assistant_content.append({"type": "thinking", "thinking": block['text'], "signature": block['signature']})
        elif block['type'] == 'text':
            assistant_content.append({"type": "text", "text": block['text']})
        elif block['type'] == 'tool_use':
            assistant_content.append({"type": "tool_use", "id": block['id'], "name": block['name'], "input": json.loads(block['input'])})

    # Rebuild user message content blocks (tool results)
    user_content = []
    for tr in tool_results:
        block = {"type": "tool_result", "tool_use_id": tr['id'], "content": tr['result']}
        if tr['is_error']:
            block["is_error"] = True
        user_content.append(block)

    req_params_2 = req_data.copy()
    req_params_2['messages'] = [
        {"role": "user", "content": req_data['prompt']},
        {"role": "assistant", "content": assistant_content},
        {"role": "user", "content": user_content}
    ]

    res2, err2 = handle_request(conn, endpoint, req_params_2)
    if err2:
        for line in transcript:
            print(line)
        print(err2)
        sys.exit(0)

    # Build transcript for Request 2
    transcript.append("request 2")
    sorted_indices_2 = sorted(res2['blocks'].keys())
    for idx in sorted_indices_2:
        block = res2['blocks'][idx]
        if block['type'] == 'thinking':
            transcript.append(f"thinking {escape_str(block['text'])}")
            transcript.append(f"signature {escape_str(block['signature'])}")
        elif block['type'] == 'text':
            transcript.append(f"text {escape_str(block['text'])}")
        elif block['type'] == 'tool_use':
            transcript.append(f"tool_use {block['id']} {block['name']} {escape_str(block['input'])}")

    transcript.append(f"stop_reason {res2['stop_reason']}")

    # Final usage
    total_i = res1['input_tokens'] + res2['input_tokens']
    total_o = res1['output_tokens'] + res2['output_tokens']
    total_c = res1['cache_read_tokens'] + res2['cache_read_tokens']
    transcript.append(f"usage input={total_i} output={total_o} cache_read={total_c}")

    for line in transcript:
        print(line)

if __name__ == "__main__":
    main()

use std::collections::HashSet;
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};

#[derive(Clone, Debug)]
enum ClassItem {
    Char(char),
    Range(char, char),
    Shorthand(char),
}

#[derive(Clone, Debug)]
enum Regex {
    Literal(char),
    Any,
    StartAnchor,
    EndAnchor,
    Shorthand(char),
    Class(Vec<ClassItem>, bool),
    Seq(Vec<Regex>),
    Alt(Vec<Regex>),
    CapturingGroup(Box<Regex>),
    NonCapturingGroup(Box<Regex>),
    Quantified(Box<Regex>, Quantifier),
}

#[derive(Clone, Copy, Debug)]
enum QuantifierKind {
    ZeroOrMore,
    OneOrMore,
    ZeroOrOne,
    Exactly(usize),
    Min(usize),
    Range(usize, usize),
}

#[derive(Clone, Copy, Debug)]
struct Quantifier {
    kind: QuantifierKind,
    lazy: bool,
}

enum Op {
    Char(char),
    Any,
    StartAnchor,
    EndAnchor,
    Shorthand(char),
    Class(Vec<ClassItem>, bool),
    Jump(usize),
    Split(usize, usize, bool),
    SaveStart(usize),
    SaveEnd(usize),
    Match,
}

struct RegexParser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> RegexParser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn peek_next(&self) -> Option<char> {
        let mut chars = self.input[self.pos..].chars();
        chars.next();
        chars.next()
    }

    fn consume(&mut self, expected: char) {
        if self.peek() == Some(expected) {
            self.pos += expected.len_utf8();
        }
    }

    fn consume_char(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn parse_regex(&mut self) -> Regex {
        let mut branches = vec![self.parse_branch()];
        while self.peek() == Some('|') {
            self.consume('|');
            branches.push(self.parse_branch());
        }
        if branches.len() == 1 {
            branches.remove(0)
        } else {
            // Flatten Alt(A, B, C) to Alt(A, Alt(B, C))
            let mut root = Regex::Alt(vec![branches[0].clone()]);
            for i in 1..branches.len() {
                root = Regex::Alt(vec![
                    match &root {
                        Regex::Alt(b) => {
                            let mut b_clone = b.clone();
                            b_clone.push(branches[i].clone());
                            Regex::Alt(b_clone)
                        }
                        _ => {
                            let mut b = vec![root, branches[i].clone()];
                            Regex::Alt(b)
                        }
                    }
                ]);
                // This is not quite right, let's just keep the Alt list and handle it in compile.
            }
            // Actually, let's just keep the Alt as a vector and handle it in compile.
            Regex::Alt(branches)
        }
    }

    fn parse_branch(&mut self) -> Regex {
        let mut pieces = vec![];
        while !self.is_at_end() && self.peek() != Some('|') && self.peek() != Some(')') {
            pieces.push(self.parse_piece());
        }
        Regex::Seq(pieces)
    }

    fn parse_piece(&mut self) -> Regex {
        let atom = self.parse_atom();
        if let Some(quant) = self.parse_quantifier() {
            Regex::Quantified(Box::new(atom), quant)
        } else {
            atom
        }
    }

    fn parse_atom(&mut self) -> Regex {
        match self.peek() {
            Some('(') => {
                self.consume('(');
                if self.peek() == Some('?') && self.peek_next() == Some(':') {
                    self.consume('?');
                    self.consume(':');
                    let re = self.parse_regex();
                    self.consume(')');
                    Regex::NonCapturingGroup(Box::new(re))
                } else {
                    let re = self.parse_regex();
                    self.consume(')');
                    Regex::CapturingGroup(Box::new(re))
                }
            }
            Some('.') => {
                self.consume('.');
                Regex::Any
            }
            Some('^') => {
                self.consume('^');
                Regex::StartAnchor
            }
            Some('$') => {
                self.consume('$');
                Regex::EndAnchor
            }
            Some('[') => {
                self.consume('[');
                let mut negated = false;
                if self.peek() == Some('^') {
                    negated = true;
                    self.consume('^');
                }
                let mut items = vec![];
                while self.peek() != Some(']') {
                    items.push(self.parse_class_item());
                }
                self.consume(']');
                Regex::Class(items, negated)
            }
            Some('\\') => {
                self.consume('\\');
                let c = self.consume_char().unwrap();
                match c {
                    'd' => Regex::Shorthand('d'),
                    'w' => Regex::Shorthand('w'),
                    's' => Regex::Shorthand('s'),
                    'D' => Regex::Shorthand('D'),
                    'W' => Regex::Shorthand('W'),
                    'S' => Regex::Shorthand('S'),
                    _ => Regex::Literal(c),
                }
            }
            Some(c) if !['.', '^', '$', '[', '(', ')', '{', '}', '*', '+', '?', '|'].contains(&c) => {
                self.consume(c);
                Regex::Literal(c)
            }
            Some(c) => {
                self.consume(c);
                Regex::Literal(c)
            }
            None => Regex::Literal(' '), // Should not happen
        }
    }

    fn parse_quantifier(&mut self) -> Option<Quantifier> {
        let c = self.peek()?;
        let kind = match c {
            '*' => {
                self.consume('*');
                QuantifierKind::ZeroOrMore
            }
            '+' => {
                self.consume('+');
                QuantifierKind::OneOrMore
            }
            '?' => {
                self.consume('?');
                QuantifierKind::ZeroOrOne
            }
            '{' => {
                self.consume('{');
                let mut m = 0;
                while let Some(d) = self.peek() {
                    if d.is_ascii_digit() {
                        m = m * 10 + d.to_digit(10).unwrap() as usize;
                        self.consume(d);
                    } else {
                        break;
                    }
                }
                if self.peek() == Some(',') {
                    self.consume(',');
                    if let Some(d) = self.peek() {
                        if d.is_ascii_digit() {
                            let mut n = 0;
                            while let Some(d2) = self.peek() {
                                if d2.is_ascii_digit() {
                                    n = n * 10 + d2.to_digit(10).unwrap() as usize;
                                    self.consume(d2);
                                } else {
                                    break;
                                }
                            }
                            self.consume('}');
                            QuantifierKind::Range(m, n)
                        } else {
                            self.consume('}');
                            QuantifierKind::Min(m)
                        }
                    } else {
                        self.consume('}');
                        QuantifierKind::Exactly(m)
                    }
                } else {
                    self.consume('}');
                    QuantifierKind::Exactly(m)
                }
            }
            _ => return None,
        };
        let mut lazy = false;
        if self.peek() == Some('?') {
            self.consume('?');
            lazy = true;
        }
        Some(Quantifier { kind, lazy })
    }

    fn parse_class_item(&mut self) -> ClassItem {
        if self.peek() == Some('\\') {
            self.consume('\\');
            let c = self.consume_char().unwrap();
            match c {
                'd' => ClassItem::Shorthand('d'),
                'w' => ClassItem::Shorthand('w'),
                's' => ClassItem::Shorthand('s'),
                'D' => ClassItem::Shorthand('D'),
                'W' => ClassItem::Shorthand('W'),
                'S' => ClassItem::Shorthand('S'),
                _ => ClassItem::Char(c),
            }
        } else {
            let c = self.consume_char().unwrap();
            if self.peek() == Some('-') {
                self.consume('-');
                let next_c = if self.peek() == Some('\\') {
                    self.consume('\\');
                    self.consume_char().unwrap()
                } else {
                    self.consume_char().unwrap()
                };
                ClassItem::Range(c, next_c)
            } else {
                ClassItem::Char(c)
            }
        }
    }

    fn is_at_end(&self) -> bool {
        self.pos >= self.input.len()
    }
}

fn compile(re: &Regex, ops: &mut Vec<Op>, group_counter: &mut usize) {
    match re {
        Regex::Literal(c) => ops.push(Op::Char(*c)),
        Regex::Any => ops.push(Op::Any),
        Regex::StartAnchor => ops.push(Op::StartAnchor),
        Regex::EndAnchor => ops.push(Op::EndAnchor),
        Regex::Shorthand(c) => ops.push(Op::Shorthand(*c)),
        Regex::Class(items, neg) => ops.push(Op::Class(items.clone(), *neg)),
        Regex::Seq(regexes) => {
            for r in regexes {
                compile(r, ops, group_counter);
            }
        }
        Regex::Alt(regexes) => {
            let split_pos = ops.len();
            ops.push(Op::Split(0, 0, false));
            let mut branch_starts = vec![];
            for r in regexes {
                branch_starts.push(ops.len());
                compile(r, ops, group_counter);
                ops.push(Op::Jump(0));
            }
            let end_pos = ops.len();
            for i in 0..regexes.len() {
                // Find the jump at the end of branch i
                let mut j = branch_starts[i];
                let mut depth = 0;
                loop {
                    match &ops[j] {
                        Op::Split(_, _, _) => depth += 1,
                        Op::Jump(_) => {
                            if depth == 0 {
                                ops[j] = Op::Jump(end_pos);
                                break;
                            }
                            depth -= 1;
                        }
                        _ => {}
                    }
                    j += 1;
                }
                // This is wrong because we don't know the internal structure.
                // Let's use a simpler way to find the jump.
            }
            // Wait, I'll just use a more robust way.
        }
        _ => {}
    }
}

// Corrected compile function using a la-style approach
fn compile_rec(re: &Regex, ops: &mut Vec<Op>, group_counter: &mut usize) {
    match re {
        Regex::Literal(c) => ops.push(Op::Char(*c)),
        Regex::Any => ops.push(Op::Any),
        Regex::StartAnchor => ops.push(Op::StartAnchor),
        Regex::EndAnchor => ops.push(Op::EndAnchor),
        Regex::Shorthand(c) => ops.push(Op::Shorthand(*c)),
        Regex::Class(items, neg) => ops.push(Op::Class(items.clone(), *neg)),
        Regex::Seq(regexes) => {
            for r in regexes {
                compile_rec(r, ops, group_counter);
            }
        }
        Regex::Alt(regexes) => {
            let split_pos = ops.len();
            ops.push(Op::Split(0, 0, false));
            let mut branch_starts = vec![];
            for r in regexes {
                branch_starts.push(ops.len());
                compile_rec(r, ops, group_counter);
                ops.push(Op::Jump(0));
            }
            let end_pos = ops.len();
            for i in 0..regexes.len() {
                // Find the jump at the end of branch i
                let mut j = branch_starts[i];
                let mut depth = 0;
                loop {
                    match &ops[j] {
                        Op::Split(_, _, _) => depth += 1,
                        Op::Jump(_) => {
                            if depth == 0 {
                                ops[j] = Op::Jump(end_pos);
                                break;
                            }
                            depth -= 1;
                        }
                        _ => {}
                    }
                    j += 1;
                }
            }
            // Fix splits: Split(branch0, Split(branch1, ...))
            let mut current_split_pos = split_pos;
            for i in 0..regexes.len() - 1 {
                let next_split_pos = ops.len(); // This is not quite right.
                // Let's just use a simple approach:
                // Split(branch_starts[i], branch_starts[i+1], false)
                // But branch_starts[i+1] must be the next Split.
            }
        }
        _ => {}
    }
}

// Let's use a simpler approach: expand the regex AST into a simpler form first.
fn flatten_alt(re: &Regex) -> Regex {
    match re {
        Regex::Alt(branches) => {
            let mut flat_branches = vec![];
            for b in branches {
                let b = flatten_alt(b);
                match b {
                    Regex::Alt(inner) => flat_branches.extend(inner),
                    _ => flat_branches.push(b),
                }
            }
            Regex::Alt(flat_branches)
        }
        Regex::Seq(s) => Regex::Seq(s.iter().map(flatten_alt).collect()),
        Regex::CapturingGroup(r) => Regex::CapturingGroup(Box::new(flatten_alt(r))),
        Regex::NonCapturingGroup(r) => Regex::NonCapturingGroup(Box::new(flatten_alt(r))),
        Regex::Quantified(r, q) => Regex::Quantified(Box::new(flatten_alt(r)), *q),
        _ => re.clone(),
    }
}

fn compile_final(re: &Regex, ops: &mut Vec<Op>, group_counter: &mut usize) {
    match re {
        Regex::Literal(c) => ops.push(Op::Char(*c)),
        Regex::Any => ops.push(Op::Any),
        Regex::StartAnchor => ops.push(Op::StartAnchor),
        Regex::EndAnchor => ops.push(Op::EndAnchor),
        Regex::Shorthand(c) => ops.push(Op::Shorthand(*c)),
        Regex::Class(items, neg) => ops.push(Op::Class(items.clone(), *neg)),
        Regex::Seq(regexes) => {
            for r in regexes {
                compile_final(r, ops, group_counter);
            }
        }
        Regex::Alt(regexes) => {
            let split_pos = ops.len();
            ops.push(Op::Split(0, 0, false));
            let mut branch_starts = vec![];
            for r in regexes {
                branch_starts.push(ops.len());
                compile_final(r, ops, group_counter);
                ops.push(Op::Jump(0));
            }
            let end_pos = ops.len();
            for i in 0..regexes.len() {
                let mut j = branch_starts[i];
                let mut depth = 0;
                loop {
                    match &ops[j] {
                        Op::Split(_, _, _) => depth += 1,
                        Op::Jump(_) => {
                            if depth == 0 {
                                ops[j] = Op::Jump(end_pos);
                                break;
                            }
                            depth -= 1;
                        }
                        _ => {}
                    }
                    j += 1;
                }
            }
            // Fix splits to chain them: Split(branch0, next_split)
            let mut current_split_pos = split_pos;
            for i in 0..regexes.len() - 1 {
                let next_split_pos = ops.len();
                ops.push(Op::Split(0, 0, false));
                ops[current_split_pos] = Op::Split(branch_starts[i], next_split_pos, false);
                current_split_pos = next_split_pos;
            }
            // The last split jumps to the last branch and the end.
            // Wait, the last branch already jumps to the end.
            // So the last split should be Split(last_branch, end_pos, false).
            let last_branch_start = branch_starts[regexes.len() - 1];
            ops[current_split_pos] = Op::Split(last_branch_start, end_pos, false);
            // But we added too many splits. Let's just use a simpler Alt:
            // Split(t1, t2, false)
            // t1: branch 0
            // Jump(end)
            // t2: branch 1
            // Jump(end)
            // ...
            // This is what I had. Let's just fix the Split to:
            // Split(branch_starts[0], branch_starts[1], false)
            // But then branch_starts[1] must be the next Split.
            // Let's just use the simple Alt:
            // Split(t1, t2, false)
            // t1: branch 0, then Jump(end)
            // t2: branch 1, then Jump(end)
            // This only works if we have 2 branches. For N branches, we can nest them.
        }
        _ => {}
    }
}

// Let's use a truly recursive approach to avoid the Alt complexity.
fn compile_simple(re: &Regex, ops: &mut Vec<Op>, group_counter: &mut usize) {
    match re {
        Regex::Literal(c) => ops.push(Op::Char(*c)),
        Regex::Any => ops.push(Op::Any),
        Regex::StartAnchor => ops.push(Op::StartAnchor),
        Regex::EndAnchor => ops.push(Op::EndAnchor),
        Regex::Shorthand(c) => ops.push(Op::Shorthand(*c)),
        Regex::Class(items, neg) => ops.push(Op::Class(items.clone(), *neg)),
        Regex::Seq(regexes) => {
            for r in regexes {
                compile_simple(r, ops, group_counter);
            }
        }
        Regex::Alt(regexes) => {
            if regexes.len() == 0 {
                // Empty branch: matches empty string
            } else if regexes.len() == 1 {
                compile_simple(&regexes[0], ops, group_counter);
            } else {
                // Alt(r0, r1, ..., rn) = Alt(r0, Alt(r1, ..., rn))
                let r0 = &regexes[0];
                let mut rest = regexes[1..].to_vec();
                let r_rest = Regex::Alt(rest);

                let split_pos = ops.len();
                ops.push(Op::Split(0, 0, false));

                compile_simple(r0, ops, group_counter);
                let jump_pos = ops.len();
                ops.push(Op::Jump(0));

                compile_simple(&r_rest, ops, group_counter);
                let end_pos = ops.len();

                ops[split_pos] = Op::Split(split_pos + 1, jump_pos + 1, false);
                ops[jump_pos] = Op::Jump(end_pos);
            }
        }
        Regex::CapturingGroup(re) => {
            let id = *group_counter;
            *group_counter += 1;
            ops.push(Op::SaveStart(id));
            compile_simple(re, ops, group_counter);
            ops.push(Op::SaveEnd(id));
        }
        Regex::NonCapturingGroup(re) => {
            compile_simple(re, ops, group_counter);
        }
        Regex::Quantified(re, quant) => {
            match quant.kind {
                QuantifierKind::ZeroOrOne => {
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, quant.lazy));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, jump_pos + 1, quant.lazy);
                    ops[jump_pos] = Op::Jump(end_pos);
                }
                QuantifierKind::ZeroOrMore => {
                    let start_pos = ops.len();
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, quant.lazy));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, end_pos, quant.lazy);
                    ops[jump_pos] = Op::Jump(start_pos);
                }
                QuantifierKind::OneOrMore => {
                    compile_simple(re, ops, group_counter);
                    let mut q = *quant;
                    q.kind = QuantifierKind::ZeroOrMore;
                    let re_q = Regex::Quantified(Box::new(Regex::Literal(' ')), q); // This is just a hack
                    // Let's just manually do ZeroOrMore
                    let start_pos = ops.len();
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, q.lazy));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, end_pos, q.lazy);
                    ops[jump_pos] = Op::Jump(start_pos);
                }
                QuantifierKind::Exactly(m) => {
                    for _ in 0..m {
                        compile_simple(re, ops, group_counter);
                    }
                }
                QuantifierKind::Min(m) => {
                    for _ in 0..m {
                        compile_simple(re, ops, group_counter);
                    }
                    // Now ZeroOrMore(false)
                    let start_pos = ops.len();
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, false));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, end_pos, false);
                    ops[jump_pos] = Op::Jump(start_pos);
                }
                QuantifierKind::Range(m, n) => {
                    for _ in 0..m {
                        compile_simple(re, ops, group_counter);
                    }
                    for _ in 0..n - m {
                        let split_pos = ops.len();
                        ops.push(Op::Split(0, 0, quant.lazy));
                        compile_simple(re, ops, group_counter);
                        let jump_pos = ops.len();
                        ops.push(Op::Jump(0));
                        let end_pos = ops.len();
                        ops[split_pos] = Op::Split(split_pos + 1, jump_pos + 1, quant.lazy);
                        ops[jump_pos] = Op::Jump(end_pos);
                    }
                }
            }
        }
    }
}

fn is_digit(c: u8) -> bool { c >= b'0' && c <= b'9' }
fn is_word(c: u8) -> bool {
    (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || (c >= b'0' && c <= b'9') || c == b'_'
}
fn is_space(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == b'\x0c' || c == b'\x0b'
}

fn match_at(
    ip: usize,
    pos: usize,
    ops: &[Op],
    subject: &[u8],
    captures: &mut Vec<Option<(usize, usize)>>,
    memo: &mut HashSet<(usize, usize)>,
) -> Option<usize> {
    if ip >= ops.len() {
        return None;
    }
    if memo.contains(&(ip, pos)) {
        return None;
    }

    match &ops[ip] {
        Op::Char(c) => {
            if pos < subject.len() && subject[pos] == *c as u8 {
                if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::Any => {
            if pos < subject.len() {
                if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::StartAnchor => {
            // We only call match_at from the search loop, where pos is the start_pos.
            // But the start_pos is passed as pos. The anchor ^ matches only at position 0 of the subject.
            // Wait, the search loop tries start_pos = 0, 1, ..., len.
            // The anchor ^ should match if the current match attempt started at 0.
            // But the problem says: "^ matches only at position 0".
            // This means if we are at pos 0 of the subject, it matches.
            if pos == 0 {
                if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::EndAnchor => {
            if pos == subject.len() {
                if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::Shorthand(c) => {
            if pos < subject.len() {
                let matched = match *c {
                    'd' => is_digit(subject[pos]),
                    'w' => is_word(subject[pos]),
                    's' => is_space(subject[pos]),
                    'D' => !is_digit(subject[pos]),
                    'W' => !is_word(subject[pos]),
                    'S' => !is_space(subject[pos]),
                    _ => false,
                };
                if matched {
                    if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                        return Some(res);
                    }
                }
            }
        }
        Op::Class(items, neg) => {
            if pos < subject.len() {
                let mut matched = false;
                for item in items {
                    match item {
                        ClassItem::Char(c) => if subject[pos] == *c as u8 { matched = true; break; },
                        ClassItem::Shorthand(c) => {
                            let m = match *c {
                                'd' => is_digit(subject[pos]),
                                'w' => is_word(subject[pos]),
                                's' => is_space(subject[pos]),
                                'D' => !is_digit(subject[pos]),
                                'W' => !is_word(subject[pos]),
                                'S' => !is_space(subject[pos]),
                                _ => false,
                            };
                            if m { matched = true; break; }
                        }
                        ClassItem::Range(start, end) => {
                            if subject[pos] >= *start as u8 && subject[pos] <= *end as u8 {
                                matched = true;
                                break;
                            }
                        }
                    }
                }
                if matched ^ *neg {
                    if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                        return Some(res);
                    }
                }
            }
        }
        Op::Jump(target) => {
            if let Some(res) = match_at(*target, pos, ops, subject, captures, memo) {
                return Some(res);
            }
        }
        Op::Split(t1, t2, lazy) => {
            if !lazy {
                if let Some(res) = match_at(*t1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
                if let Some(res) = match_at(*t2, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            } else {
                if let Some(res) = match_at(*t2, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
                if let Some(res) = match_at(*t1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::SaveStart(id) => {
            let old = captures[*id];
            captures[*id] = Some((pos, pos));
            if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                return Some(res);
            }
            captures[*id] = old;
        }
        Op::SaveEnd(id) => {
            let old = captures[*id];
            if let Some((start, _)) = captures[*id] {
                captures[*id] = Some((start, pos));
            }
            if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                return Some(res);
            }
            captures[*id] = old;
        }
        Op::Match => {
            return Some(pos);
        }
    }
    memo.insert((ip, pos));
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = std::path::Path::new(dir).join("cases.txt");
    let file = File::open(path).expect("Could not open cases.txt");
    let reader = BufReader::new(file);

    for (line_idx, line_res) in reader.lines().enumerate() {
        let line = line_res.unwrap();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() < 2 { continue; }
        let pattern = parts[0];
        let subject = parts[1];

        let mut parser = RegexParser::new(pattern);
        let re = parser.parse_regex();
        let mut ops = vec![];
        let mut group_counter = 0;
        compile_simple(&re, &mut ops, &mut group_counter);
        ops.push(Op::Match);

        let subject_bytes = subject.as_bytes();
        let mut matched = false;
        for start_pos in 0..=subject_bytes.len() {
            let mut captures = vec![None; group_counter];
            let mut memo = HashSet::new();
            if let Some(end_pos) = match_at(0, start_pos, &ops, subject_bytes, &mut captures, &mut memo) {
                print!("{}: {}-{}", line_idx + 1, start_pos, end_pos);
                for cap in captures {
                    match cap {
                        Some((s, e)) => print!(" {}-{}", s, e),
                        None => print!(" -"),
                    }
                }
                println!();
                matched = true;
                break;
            }
        }
        if !matched {
            println!("{}: no match", line_idx + 1);
        }
    }
}

use std::collections::HashSet;
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};

#[derive(Clone, Debug)]
enum ClassItem {
    Char(char),
    Range(char, char),
    Shorthand(char),
}

#[derive(Clone, Debug)]
enum Regex {
    Literal(char),
    Any,
    StartAnchor,
    EndAnchor,
    Shorthand(char),
    Class(Vec<ClassItem>, bool),
    Seq(Vec<Regex>),
    Alt(Vec<Regex>),
    CapturingGroup(Box<Regex>),
    NonCapturingGroup(Box<Regex>),
    Quantified(Box<Regex>, Quantifier),
}

#[derive(Clone, Copy, Debug)]
enum QuantifierKind {
    ZeroOrMore,
    OneOrMore,
    ZeroOrOne,
    Exactly(usize),
    Min(usize),
    Range(usize, usize),
}

#[derive(Clone, Copy, Debug)]
struct Quantifier {
    kind: QuantifierKind,
    lazy: bool,
}

#[derive(Clone, Debug)]
enum Op {
    Char(char),
    Any,
    StartAnchor,
    EndAnchor,
    Shorthand(char),
    Class(Vec<ClassItem>, bool),
    Jump(usize),
    Split(usize, usize, bool),
    SaveStart(usize),
    SaveEnd(usize),
    Match,
}

struct RegexParser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> RegexParser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn peek_next(&self) -> Option<char> {
        let mut chars = self.input[self.pos..].chars();
        chars.next();
        chars.next()
    }

    fn consume(&mut self, expected: char) {
        if self.peek() == Some(expected) {
            self.pos += expected.len_utf8();
        }
    }

    fn consume_char(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn parse_regex(&mut self) -> Regex {
        let mut branches = vec![self.parse_branch()];
        while self.peek() == Some('|') {
            self.consume('|');
            branches.push(self.parse_branch());
        }
        if branches.len() == 1 {
            branches.remove(0)
        } else {
            Regex::Alt(branches)
        }
    }

    fn parse_branch(&mut self) -> Regex {
        let mut pieces = vec![];
        while !self.is_at_end() && self.peek() != Some('|') && self.peek() != Some(')') {
            pieces.push(self.parse_piece());
        }
        Regex::Seq(pieces)
    }

    fn parse_piece(&mut self) -> Regex {
        let atom = self.parse_atom();
        if let Some(quant) = self.parse_quantifier() {
            Regex::Quantified(Box::new(atom), quant)
        } else {
            atom
        }
    }

    fn parse_atom(&mut self) -> Regex {
        match self.peek() {
            Some('(') => {
                self.consume('(');
                if self.peek() == Some('?') && self.peek_next() == Some(':') {
                    self.consume('?');
                    self.consume(':');
                    let re = self.parse_regex();
                    self.consume(')');
                    Regex::NonCapturingGroup(Box::new(re))
                } else {
                    let re = self.parse_regex();
                    self.consume(')');
                    Regex::CapturingGroup(Box::new(re))
                }
            }
            Some('.') => {
                self.consume('.');
                Regex::Any
            }
            Some('^') => {
                self.consume('^');
                Regex::StartAnchor
            }
            Some('$') => {
                self.consume('$');
                Regex::EndAnchor
            }
            Some('[') => {
                self.consume('[');
                let mut negated = false;
                if self.peek() == Some('^') {
                    negated = true;
                    self.consume('^');
                }
                let mut items = vec![];
                while self.peek() != Some(']') {
                    items.push(self.parse_class_item());
                }
                self.consume(']');
                Regex::Class(items, negated)
            }
            Some('\\') => {
                self.consume('\\');
                let c = self.consume_char().unwrap();
                match c {
                    'd' | 'w' | 's' | 'D' | 'W' | 'S' => Regex::Shorthand(c),
                    _ => Regex::Literal(c),
                }
            }
            Some(c) if !['.', '^', '$', '[', '(', ')', '{', '}', '*', '+', '?', '|'].contains(&c) => {
                self.consume(c);
                Regex::Literal(c)
            }
            Some(c) => {
                self.consume(c);
                Regex::Literal(c)
            }
            None => Regex::Literal(' '),
        }
    }

    fn parse_quantifier(&mut self) -> Option<Quantifier> {
        let c = self.peek()?;
        let kind = match c {
            '*' => {
                self.consume('*');
                QuantifierKind::ZeroOrMore
            }
            '+' => {
                self.consume('+');
                QuantifierKind::OneOrMore
            }
            '?' => {
                self.consume('?');
                QuantifierKind::ZeroOrOne
            }
            '{' => {
                self.consume('{');
                let mut m = 0;
                while let Some(d) = self.peek() {
                    if d.is_ascii_digit() {
                        m = m * 10 + d.to_digit(10).unwrap() as usize;
                        self.consume(d);
                    } else {
                        break;
                    }
                }
                if self.peek() == Some(',') {
                    self.consume(',');
                    if let Some(d) = self.peek() {
                        if d.is_ascii_digit() {
                            let mut n = 0;
                            while let Some(d2) = self.peek() {
                                if d2.is_ascii_digit() {
                                    n = n * 10 + d2.to_digit(10).unwrap() as usize;
                                    self.consume(d2);
                                } else {
                                    break;
                                }
                            }
                            self.consume('}');
                            QuantifierKind::Range(m, n)
                        } else {
                            self.consume('}');
                            QuantifierKind::Min(m)
                        }
                    } else {
                        self.consume('}');
                        QuantifierKind::Exactly(m)
                    }
                } else {
                    self.consume('}');
                    QuantifierKind::Exactly(m)
                }
            }
            _ => return None,
        };
        let mut lazy = false;
        if self.peek() == Some('?') {
            self.consume('?');
            lazy = true;
        }
        Some(Quantifier { kind, lazy })
    }

    fn parse_class_item(&mut self) -> ClassItem {
        if self.peek() == Some('\\') {
            self.consume('\\');
            let c = self.consume_char().unwrap();
            match c {
                'd' | 'w' | 's' | 'D' | 'W' | 'S' => ClassItem::Shorthand(c),
                _ => ClassItem::Char(c),
            }
        } else {
            let c = self.consume_char().unwrap();
            if self.peek() == Some('-') {
                self.consume('-');
                let next_c = if self.peek() == Some('\\') {
                    self.consume('\\');
                    self.consume_char().unwrap()
                } else {
                    self.consume_char().unwrap()
                };
                ClassItem::Range(c, next_c)
            } else {
                ClassItem::Char(c)
            }
        }
    }

    fn is_at_end(&self) -> bool {
        self.pos >= self.input.len()
    }
}

fn compile_simple(re: &Regex, ops: &mut Vec<Op>, group_counter: &mut usize) {
    match re {
        Regex::Literal(c) => ops.push(Op::Char(*c)),
        Regex::Any => ops.push(Op::Any),
        Regex::StartAnchor => ops.push(Op::StartAnchor),
        Regex::EndAnchor => ops.push(Op::EndAnchor),
        Regex::Shorthand(c) => ops.push(Op::Shorthand(*c)),
        Regex::Class(items, neg) => ops.push(Op::Class(items.clone(), *neg)),
        Regex::Seq(regexes) => {
            for r in regexes {
                compile_simple(r, ops, group_counter);
            }
        }
        Regex::Alt(regexes) => {
            if regexes.is_empty() {
                return;
            }
            if regexes.len() == 1 {
                compile_simple(&regexes[0], ops, group_counter);
            } else {
                let r0 = &regexes[0];
                let r_rest = Regex::Alt(regexes[1..].to_vec());
                let split_pos = ops.len();
                ops.push(Op::Split(0, 0, false));
                compile_simple(r0, ops, group_counter);
                let jump_pos = ops.len();
                ops.push(Op::Jump(0));
                compile_simple(&r_rest, ops, group_counter);
                let end_pos = ops.len();
                ops[split_pos] = Op::Split(split_pos + 1, jump_pos + 1, false);
                ops[jump_pos] = Op::Jump(end_pos);
            }
        }
        Regex::CapturingGroup(re) => {
            let id = *group_counter;
            *group_counter += 1;
            ops.push(Op::SaveStart(id));
            compile_simple(re, ops, group_counter);
            ops.push(Op::SaveEnd(id));
        }
        Regex::NonCapturingGroup(re) => {
            compile_simple(re, ops, group_counter);
        }
        Regex::Quantified(re, quant) => {
            match quant.kind {
                QuantifierKind::ZeroOrOne => {
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, quant.lazy));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, end_pos, quant.lazy);
                    ops[jump_pos] = Op::Jump(end_pos);
                }
                QuantifierKind::ZeroOrMore => {
                    let start_pos = ops.len();
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, quant.lazy));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, end_pos, quant.lazy);
                    ops[jump_pos] = Op::Jump(start_pos);
                }
                QuantifierKind::OneOrMore => {
                    compile_simple(re, ops, group_counter);
                    let start_pos = ops.len();
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, quant.lazy));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, end_pos, quant.lazy);
                    ops[jump_pos] = Op::Jump(start_pos);
                }
                QuantifierKind::Exactly(m) => {
                    for _ in 0..m {
                        compile_simple(re, ops, group_counter);
                    }
                }
                QuantifierKind::Min(m) => {
                    for _ in 0..m {
                        compile_simple(re, ops, group_counter);
                    }
                    let start_pos = ops.len();
                    let split_pos = ops.len();
                    ops.push(Op::Split(0, 0, quant.lazy));
                    compile_simple(re, ops, group_counter);
                    let jump_pos = ops.len();
                    ops.push(Op::Jump(0));
                    let end_pos = ops.len();
                    ops[split_pos] = Op::Split(split_pos + 1, end_pos, quant.lazy);
                    ops[jump_pos] = Op::Jump(start_pos);
                }
                QuantifierKind::Range(m, n) => {
                    for _ in 0..m {
                        compile_simple(re, ops, group_counter);
                    }
                    for _ in 0..n - m {
                        let split_pos = ops.len();
                        ops.push(Op::Split(0, 0, quant.lazy));
                        compile_simple(re, ops, group_counter);
                        let jump_pos = ops.len();
                        ops.push(Op::Jump(0));
                        let end_pos = ops.len();
                        ops[split_pos] = Op::Split(split_pos + 1, end_pos, quant.lazy);
                        ops[jump_pos] = Op::Jump(end_pos);
                    }
                }
            }
        }
    }
}

fn is_digit(c: u8) -> bool { c >= b'0' && c <= b'9' }
fn is_word(c: u8) -> bool {
    (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || (c >= b'0' && c <= b'9') || c == b'_'
}
fn is_space(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == b'\x0c' || c == b'\x0b'
}

fn matches_shorthand(s: char, c: u8) -> bool {
    match s {
        'd' => is_digit(c),
        'w' => is_word(c),
        's' => is_space(c),
        'D' => !is_digit(c),
        'W' => !is_word(c),
        'S' => !is_space(c),
        _ => false,
    }
}

fn match_at(
    ip: usize,
    pos: usize,
    ops: &[Op],
    subject: &[u8],
    captures: &mut Vec<Option<(usize, usize)>>,
    memo: &mut HashSet<(usize, usize)>,
) -> Option<usize> {
    if ip >= ops.len() {
        return None;
    }
    if memo.contains(&(ip, pos)) {
        return None;
    }

    match &ops[ip] {
        Op::Char(c) => {
            if pos < subject.len() && subject[pos] == *c as u8 {
                if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::Any => {
            if pos < subject.len() {
                if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::StartAnchor => {
            if pos == 0 {
                if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::EndAnchor => {
            if pos == subject.len() {
                if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::Shorthand(c) => {
            if pos < subject.len() {
                if matches_shorthand(*c, subject[pos]) {
                    if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                        return Some(res);
                    }
                }
            }
        }
        Op::Class(items, neg) => {
            if pos < subject.len() {
                let mut matched = false;
                for item in items {
                    match item {
                        ClassItem::Char(c) => if subject[pos] == *c as u8 { matched = true; break; },
                        ClassItem::Shorthand(c) => if matches_shorthand(*c, subject[pos]) { matched = true; break; },
                        ClassItem::Range(start, end) => if subject[pos] >= *start as u8 && subject[pos] <= *end as u8 { matched = true; break; },
                    }
                }
                if matched ^ *neg {
                    if let Some(res) = match_at(ip + 1, pos + 1, ops, subject, captures, memo) {
                        return Some(res);
                    }
                }
            }
        }
        Op::Jump(target) => {
            if let Some(res) = match_at(*target, pos, ops, subject, captures, memo) {
                return Some(res);
            }
        }
        Op::Split(t1, t2, lazy) => {
            if !*lazy {
                if let Some(res) = match_at(*t1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
                if let Some(res) = match_at(*t2, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            } else {
                if let Some(res) = match_at(*t2, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
                if let Some(res) = match_at(*t1, pos, ops, subject, captures, memo) {
                    return Some(res);
                }
            }
        }
        Op::SaveStart(id) => {
            let old = captures[*id];
            captures[*id] = Some((pos, pos));
            if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                return Some(res);
            }
            captures[*id] = old;
        }
        Op::SaveEnd(id) => {
            let old = captures[*id];
            if let Some((start, _)) = captures[*id] {
                captures[*id] = Some((start, pos));
            }
            if let Some(res) = match_at(ip + 1, pos, ops, subject, captures, memo) {
                return Some(res);
            }
            captures[*id] = old;
        }
        Op::Match => {
            return Some(pos);
        }
    }
    memo.insert((ip, pos));
    None
}

fn run_match_at(ip: usize, pos: usize, ops: &[Op], subject: &[u8], captures: &mut Vec<Option<(usize, usize)>>, memo: &mut HashSet<(usize, usize)>) -> Option<usize> {
    match_at(ip, pos, ops, subject, captures, memo)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = std::path::Path::new(dir).join("cases.txt");
    let file = File::open(path).expect("Could not open cases.txt");
    let reader = BufReader::new(file);

    // To avoid stack overflow, we use a separate thread with a larger stack.
    let mut results = vec![];
    let mut cases = vec![];
    for line_res in reader.lines() {
        let line = line_res.unwrap();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() < 2 { continue; }
        cases.push((parts[0].to_string(), parts[1].to_string()));
    }

    let builder = std::thread::Builder::new().stack_size(64 * 1024 * 1024);
    let handle = builder.spawn(move || {
        let mut output = vec![];
        for (line_idx, (pattern, subject)) in cases.into_iter().enumerate() {
            let mut parser = RegexParser::new(&pattern);
            let re = parser.parse_regex();
            let mut ops = vec![];
            let mut group_counter = 0;
            compile_simple(&re, &mut ops, &mut group_counter);
            ops.push(Op::Match);

            let subject_bytes = subject.as_bytes();
            let mut matched = false;
            for start_pos in 0..=subject_bytes.len() {
                let mut captures = vec![None; group_counter];
                let mut memo = HashSet::new();
                if let Some(end_pos) = run_match_at(0, start_pos, &ops, subject_bytes, &mut captures, &mut memo) {
                    let mut res = format!("{}: {}-{}", line_idx + 1, start_pos, end_pos);
                    for cap in captures {
                        match cap {
                            Some((s, e)) => res.push_str(&format!(" {}-{}", s, e)),
                            None => res.push_str(" -"),
                        }
                    }
                    output.push(res);
                    matched = true;
                    break;
                }
            }
            if !matched {
                output.push(format!("{}: no match", line_idx + 1));
            }
        }
        output
    }).unwrap();

    let results = handle.join().unwrap();
    for res in results {
        println!("{}", res);
    }
}

