function crc32(buffer: Buffer): string {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let j = 0; j < 8; j++) {
            c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
        }
        table[i] = c;
    }
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < buffer.length; i++) {
        crc = (crc >>> 8) ^ table[(crc ^ buffer[i]) & 0xFF];
    }
    return ((crc ^ 0xFFFFFFFF) >>> 0).toString(16).padStart(8, '0');
}

function readVarint(buffer: Buffer, offset: number): { value: bigint; offset: number } {
    let value = 0n;
    let shift = 0;
    while (true) {
        const byte = buffer[offset++];
        value += BigInt(byte & 0x7F) << BigInt(shift);
        if ((byte & 0x80) === 0 || shift === 28) break;
        shift += 7;
    }
    if (shift === 28) {
        const byte = buffer[offset++];
        value += BigInt(byte) << BigInt(28);
    }
    return { value, offset };
}

function readInt(buffer: Buffer, offset: number, size: number, signed: boolean): bigint {
    let value = 0n;
    for (let i = 0; i < size; i++) {
        value = (value << 8n) | BigInt(buffer[offset + i]);
    }
    if (signed && (value & (1n << (BigInt(size) * 8n - 1n)))) {
        value = value - (1n << (BigInt(size) * 8n));
    }
    return value;
}

function parseSqlColumns(sql: string) {
    const match = sql.match(/CREATE\s+TABLE\s+("([^"]+)"|([^\s(]+))\s*\((.*)\)/is);
    if (!match) return { name: '', cols: [] };
    const tableName = match[2] || match[3];
    const defsRaw = match[4];
    const cols: { name: string, isAlias: boolean }[] = [];

    let depth = 0;
    let currentDef = '';
    for (let i = 0; i < defsRaw.length; i++) {
        const char = defsRaw[i];
        if (char === '(') depth++;
        if (char === ')') depth--;
        if (char === ',' && depth === 0) {
            cols.push(parseColDef(currentDef));
            currentDef = '';
        } else {
            currentDef += char;
        }
    }
    cols.push(parseColDef(currentDef));
    return { name: tableName, cols };
}

function parseColDef(def: string) {
    def = def.trim();
    let name = '';
    let remaining = '';
    if (def.startsWith('"')) {
        const endQuote = def.indexOf('"', 1);
        name = def.substring(1, endQuote);
        remaining = def.substring(endQuote + 1);
    } else {
        const firstSpace = def.search(/\s/);
        if (firstSpace === -1) {
            name = def;
            remaining = '';
        } else {
            name = def.substring(0, firstSpace);
            remaining = def.substring(firstSpace);
        }
    }

    const isInteger = /\bINTEGER\b/i.test(remaining.split(/\s+/)[0] || '');
    const hasPrimaryKey = /\bPRIMARY\s+KEY\b/i.test(remaining);
    return { name, isAlias: isInteger && hasPrimaryKey };
}

