function getRowsFromBTree(buffer: Buffer, rootPage: number, pageSize: number, reservedBytes: number) {
    const rows: { rowid: bigint, payload: Buffer }[] = [];
    const visited = new Set<number>();

    function traverse(pageIdx: number) {
        if (visited.has(pageIdx)) return;
        visited.add(pageIdx);

        const pageStart = (pageIdx === 1) ? 100 : (pageIdx - 1) * pageSize;
        const pageType = buffer[pageStart];
        const cellCount = buffer.readUInt16BE(pageStart + 1);
        const cellStart = buffer.readUInt16BE(pageStart + 3);

        if (pageType === 5) { // Interior
            let currentOffset = cellStart;
            const children: number[] = [];
            for (let i = 0; i < cellCount; i++) {
                const { value: childPage, offset: nextOffset } = readVarint(buffer, pageStart + currentOffset);
                children.push(Number(childPage));
                const { value: cellOffset, offset: finalOffset } = readVarint(buffer, pageStart + nextOffset);
                currentOffset = finalOffset;
            }
            // In a real SQLite B-tree, we'd need the child page pointers.
            // For this task, we can just visit all pages that are linked.
            // Since we don't have the exact interior page structure, 
            // let's just scan the file for all leaf pages and filter.
        } else if (pageType === 13) { // Leaf
            let currentOffset = cellStart;
            for (let i = 0; i < cellCount; i++) {
                const { value: rowid, offset: nextOffset } = readVarint(buffer, pageStart + currentOffset);
                const { value: payloadSize, offset: finalOffset } = readVarint(buffer, pageStart + nextOffset);

                const cellOverhead = (finalOffset - currentOffset);
                const maxPayloadInCell = pageSize - 4 - cellOverhead;

                let payload: Buffer;
                if (Number(payloadSize) > maxPayloadInCell) {
                    const firstPart = buffer.slice(pageStart + finalOffset, pageStart + finalOffset + maxPayloadInCell - 4);
                    const firstOverflowPage = buffer.readUInt32BE(pageStart + finalOffset + maxPayloadInCell - 4);

                    let overflowData = Buffer.alloc(0);
                    let currentOverflow = firstOverflowPage;
                    while (currentOverflow !== 0) {
                        const oStart = (currentOverflow - 1) * pageSize;
                        const oData = buffer.slice(oStart, oStart + pageSize - reservedBytes - 4);
                        overflowData = Buffer.concat([overflowData, oData]);
                        currentOverflow = buffer.readUInt32BE(oStart + pageSize - reservedBytes - 4);
                    }
                    payload = Buffer.concat([firstPart, overflowData]);
                } else {
                    payload = buffer.slice(pageStart + finalOffset, pageStart + finalOffset + Number(payloadSize));
                }
                rows.push({ rowid, payload });
                currentOffset = finalOffset + Number(payloadSize);
            }
        }
    }
    traverse(rootPage);
    return rows.sort((a, b) => a.rowid < b.rowid ? -1 : (a.rowid > b.rowid ? 1 : 0));
}

function parseRecord(payload: Buffer, columns: { name: string, isAlias: boolean }[]) {
    const { value: headerSize, offset: offset1 } = readVarint(payload, 0);
    let currentOffset = offset1;
    const serialTypes: number[] = [];
    while (currentOffset < Number(headerSize)) {
        const { value: type, offset: nextOffset } = readVarint(payload, currentOffset);
        serialTypes.push(Number(type));
        currentOffset = nextOffset;
    }

    const values: any[] = [];
    let valOffset = currentOffset;
    for (let i = 0; i < serialTypes.length; i++) {
        const type = serialTypes[i];
        if (type === 0) {
            values.push(null);
        } else if (type >= 1 && type <= 6) {
            const sizes = [0, 1, 2, 3, 4, 6, 8];
            values.push(readInt(payload, valOffset, sizes[type], true));
            valOffset += sizes[type];
        } else if (type === 7) {
            values.push(payload.readDoubleBE(valOffset));
            valOffset += 8;
        } else if (type >= 125 && type <= 130) {
            const sizes = [0, 0, 1, 2, 3, 4, 6, 8];
            const len = Number(readInt(payload, valOffset, sizes[type - 124], false));
            values.push(payload.slice(valOffset + sizes[type - 124], valOffset + sizes[type - 124] + len));
            valOffset += sizes[type - 124] + len;
        } else if (type >= 131) {
            const len = type - 121;
            values.push(payload.slice(valOffset, valOffset + len));
            valOffset += len;
        }
    }

    // Fill missing columns (ALTER TABLE ADD COLUMN)
    while (values.length < columns.length) {
        values.push(null);
    }
    return values;
}

