function crc32(buffer: Buffer): string {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let j = 0; j < 8; j++) {
            c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
        }
        table[i] = c;
    }
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < buffer.length; i++) {
        crc = (crc >>> 8) ^ table[(crc ^ buffer[i]) & 0xFF];
    }
    return ((crc ^ 0xFFFFFFFF) >>> 0).toString(16).padStart(8, '0');
}

function readVarint(buffer: Buffer, offset: number): { value: bigint; offset: number } {
    let value = 0n;
    let shift = 0;
    while (true) {
        const byte = buffer[offset++];
        value += BigInt(byte & 0x7F) << BigInt(shift);
        if ((byte & 0x80) === 0 || shift === 28) break;
        shift += 7;
    }
    if (shift === 28) {
        const byte = buffer[offset++];
        value += BigInt(byte) << BigInt(28);
    }
    return { value, offset };
}

function readInt(buffer: Buffer, offset: number, size: number, signed: boolean): bigint {
    let value = 0n;
    for (let i = 0; i < size; i++) {
        value |= BigInt(buffer[offset + i]) << BigInt(i * 8);
    }
    if (signed && (value & (1n << (BigInt(size) * 8n - 1n)))) {
        value -= (1n << (BigInt(size) * 8n));
    }
    return value;
}

function parseSqlColumns(sql: string) {
    const match = sql.match(/CREATE\s+TABLE\s+("([^"]+)"|([^\s(]+))\s*\((.*)\)/is);
    if (!match) return { name: '', cols: [] };
    const tableName = match[2] || match[3];
    const defsRaw = match[4];
    const cols: { name: string, isAlias: boolean }[] = [];

    let depth = 0;
    let currentDef = '';
    for (let i = 0; i < defsRaw.length; i++) {
        const char = defsRaw[i];
        if (char === '(') depth++;
        else if (char === ')') depth--;
        if (char === ',' && depth === 0) {
            cols.push(parseColDef(currentDef));
            currentDef = '';
        } else {
            currentDef += char;
        }
    }
    cols.push(parseColDef(currentDef));
    return { name: tableName, cols };
}

function parseColDef(def: string) {
    def = def.trim();
    let name = '';
    let remaining = '';
    if (def.startsWith('"')) {
        const endQuote = def.indexOf('"', 1);
        name = def.substring(1, endQuote);
        remaining = def.substring(endQuote + 1);
    } else {
        const firstSpace = def.search(/\s/);
        if (firstSpace === -1) {
            name = def;
            remaining = '';
        } else {
            name = def.substring(0, firstSpace);
            remaining = def.substring(firstSpace);
        }
    }

    const isInteger = /\bINTEGER\b/i.test(remaining.split(/\s+/)[0] || '');
    const hasPrimaryKey = /\bPRIMARY\s+KEY\b/i.test(remaining);
    return { name, isAlias: isInteger && hasPrimaryKey };
}

function formatBlobOrText(data: Buffer, storageClass: 'TEXT' | 'BLOB') {
    if (data.length > 100) {
        return `<${storageClass} len=${data.length} crc32=${crc32(data)}>`;
    }
    if (storageClass === 'TEXT') {
        let s = '';
        for (let i = 0; i < data.length; i++) {
            const b = data[i];
            if (b === 92) s += '\\\\';
            else if (b === 34) s += '\\"';
            else if (b === 10) s += '\\n';
            else if (b === 13) s += '\\r';
            else if (b === 9) s += '\\t';
            else if (b < 0x20 || b === 0x7F) s += '\\x' + b.toString(16).toUpperCase().padStart(2, '0');
            else {
                let j = i;
                while (j < data.length && (data[j] & 0x80) !== 0) j++;
                const chunk = data.slice(i, j + 1);
                s += chunk.toString('utf8');
                i = j;
            }
        }
        return `"${s}"`;
    } else {
        return `X'${data.toString('hex').toUpperCase()}'`;
    }
}

function walkBTree(buffer: Buffer, pageIdx: number, pageSize: number, reservedBytes: number, rows: { rowid: bigint, payload: Buffer }[]) {
    const pageStart = (pageIdx === 1) ? 100 : (pageIdx - 1) * pageSize;
    const type = buffer[pageStart];
    const cellCount = buffer.readUInt16LE(pageStart + 1);
    const cellStart = buffer.readUInt16LE(pageStart + 3);

    if (type === 5) { // Interior
        const children: number[] = [];
        let offset = pageStart + 8;
        const { value: firstChild, offset: nextOffset } = readVarint(buffer, offset);
        children.push(Number(firstChild));
        let ptrOffset = pageStart + cellStart;
        for (let i = 0; i < cellCount; i++) {
            const { value: child, offset: nextPtrOffset } = readVarint(buffer, ptrOffset);
            children.push(Number(child));
            ptrOffset = nextPtrOffset;
        }
        for (const child of children) {
            walkBTree(buffer, child, pageSize, reservedBytes, rows);
        }
    } else if (type === 13) { // Leaf
        let ptrOffset = pageStart + cellStart;
        for (let i = 0; i < cellCount; i++) {
            const { value: cellOffset, offset: nextPtrOffset } = readVarint(buffer, ptrOffset);
            ptrOffset = nextPtrOffset;

            let cellCur = pageStart + cellOffset;
            const { value: rowid, offset: nextOffset } = readVarint(buffer, cellCur);
            const { value: payloadSize, offset: payloadOffset } = readVarint(buffer, nextOffset);

            const cellOverhead = (nextOffset - cellCur) + (payloadOffset - nextOffset);
            const maxPayloadInCell = pageSize - 4 - cellOverhead;

            let payload: Buffer;
            if (Number(payloadSize) > maxPayloadInCell) {
                const firstPart = buffer.slice(pageStart + payloadOffset, pageStart + payloadOffset + maxPayloadInCell - 4);
                const firstOverflowPage = buffer.readUInt32LE(pageStart + payloadOffset + maxPayloadInCell - 4);
                let overflowData = Buffer.alloc(0);
                let currentOverflow = firstOverflowPage;
                while (currentOverflow !== 0) {
                    const oStart = (currentOverflow - 1) * pageSize;
                    const oData = buffer.slice(oStart, oStart + pageSize - reservedBytes - 4);
                    overflowData = Buffer.concat([overflowData, oData]);
                    currentOverflow = buffer.readUInt32LE(oStart + pageSize - reservedBytes - 4);
                }
                payload = Buffer.concat([firstPart, overflowData]);
            } else {
                payload = buffer.slice(pageStart + payloadOffset, pageStart + payloadOffset + Number(payloadSize));
            }
            rows.push({ rowid, payload });
        }
    }
}

function parseRecord(payload: Buffer) {
    const { value: headerSize, offset: offset1 } = readVarint(payload, 0);
    let currentOffset = offset1;
