#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn consume_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.consume_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => self.parse_string(),
            Some('t') | Some('f') => self.parse_bool(),
            Some('n') => self.parse_null(),
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> JsonValue {
        self.next(); // consume "
        let mut s = String::new();
        while let Some(c) = self.next() {
            if c == '"' { break; }
            if c == '\\' {
                match self.next() {
                    Some('n') => s.push('\n'),
                    Some('r') => s.push('\r'),
                    Some('t') => s.push('\t'),
                    Some('b') => s.push('\x08'),
                    Some('f') => s.push('\x0c'),
                    Some('\\') => s.push('\\'),
                    Some('"') => s.push('"'),
                    Some('/') => s.push('/'),
                    Some('u') => {
                        let mut hex = String::new();
                        for _ in 0..4 { hex.push(self.next().unwrap()); }
                        let code = u32::from_str_radix(&hex, 16).unwrap();
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.peek() == Some('\\') {
                                self.next(); // consume \
                                if self.next() == Some('u') {
                                    let mut hex2 = String::new();
                                    for _ in 0..4 { hex2.push(self.next().unwrap()); }
                                    let code2 = u32::from_str_radix(&hex2, 16).unwrap();
                                    let combined = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                    s.push(std::char::from_u32(combined).unwrap());
                                }
                            }
                        } else {
                            s.push(std::char::from_u32(code).unwrap());
                        }
                    }
                    _ => {}
                }
            } else {
                s.push(c);
            }
        }
        JsonValue::String(s)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.next(); // consume {
        let mut map = HashMap::new();
        loop {
            self.consume_whitespace();
            if self.peek() == Some('}') {
                self.next();
                break;
            }
            let key = match self.parse_string() {
                JsonValue::String(s) => s,
                _ => unreachable!(),
            };
            self.consume_whitespace();
            self.next(); // consume :
            let value = self.parse_value();
            map.insert(key, value);
            self.consume_whitespace();
            if self.peek() == Some(',') {
                self.next();
            } else if self.peek() == Some('}') {
                self.next();
                break;
            }
        }
        JsonValue::Object(map)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.next(); // consume [
        let mut arr = Vec::new();
        loop {
            self.consume_whitespace();
            if self.peek() == Some(']') {
                self.next();
                break;
            }
            arr.push(self.parse_value());
            self.consume_whitespace();
            if self.peek() == Some(',') {
                self.next();
            } else if self.peek() == Some(']') {
                self.next();
                break;
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_number(&mut self) -> JsonValue {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '-' || c == '.' || c == 'e' || c == 'E' || c == '+' {
                s.push(self.next().unwrap());
            } else {
                break;
            }
        }
        JsonValue::Number(s)
    }

    fn parse_bool(&mut self) -> JsonValue {
        if self.peek() == Some('t') {
            self.pos += 4;
            JsonValue::Bool(true)
        } else {
            self.pos += 5;
            JsonValue::Bool(false)
        }
    }

    fn parse_null(&mut self) -> JsonValue {
        self.pos += 4;
        JsonValue::Null
    }
}

fn parse_json(input: &str) -> JsonValue {
    let mut parser = Parser { input, pos: 0 };
    parser.parse_value()
}

fn base64_encode(input: &[u8]) -> String {
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in input.chunks(3) {
        let b1 = chunk[0] as usize;
        let b2 = if chunk.len() > 1 { chunk[1] as usize } else { 0 };
        let b3 = if chunk.len() > 2 { chunk[2] as usize } else { 0 };
        let combined = (b1 << 16) | (b2 << 8) | b3;
        result.push(alphabet[(combined >> 18) & 63] as char);
        result.push(alphabet[(combined >> 12) & 63] as char);
        if chunk.len() > 1 {
            result.push(alphabet[(combined >> 6) & 63] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(alphabet[combined & 63] as char);
        } else {
            result.push('=');
        }
    }
    result
}

fn url_encode(input: &str, space_as_plus: bool) -> String {
    let mut result = String::new();
    for b in input.as_bytes() {
        match *b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'*' => {
                result.push(*b as char);
            }
            b' ' if space_as_plus => result.push('+'),
            _ => result.push_str(&format!("%{:02X}", b)),
        }
    }
    result
}

fn parse_amount(s: &str) -> i64 {
    let s = s.trim_matches('"');
    let mut s = s.to_string();
    let negative = s.starts_with('-');
    if negative { s = s[1..].to_string(); }
    let parts: Vec<&str> = s.split('.').collect();
    let mut cents = 0i64;
    if parts.len() == 1 {
        cents = parts[0].parse::<i64>().unwrap_or(0) * 100;
    } else {
        let integer_part = parts[0].parse::<i64>().unwrap_or(0);
        let fraction_part = parts[1];
        let mut fraction_val = fraction_part.parse::<i64>().unwrap_or(0);
        if fraction_part.len() == 1 {
            fraction_val *= 10;
        }
        cents = integer_part * 100 + fraction_val;
    }
    if negative { -cents } else { cents }
}

fn format_amount(cents: i64) -> String {
    let abs_cents = cents.abs();
    let dollars = abs_cents / 100;
    let cents_rem = abs_cents % 100;
    let sign = if cents < 0 { "-" } else { "" };
    format!("{}{}.{:02}", sign, dollars, cents_rem)
}

fn send_request(host_port: &str, method: &str, path: &str, headers: Vec<(&str, &str)>, body: Option<&str>) -> (u16, HashMap<String, String>, String) {
    let (host, port) = match host_port.find(':') {
        Some(idx) => (&host_port[..idx], host_port[idx+1..].parse::<u16>().unwrap()),
        None => (host_port, 80),
    };

    let mut stream = TcpStream::connect(format!("{}:{}", host, port)).expect("Connection failed");
    let mut request = format!("{} {} HTTP/1.1\r\n", method, path);
    request.push_str(&format!("Host: {}\r\n", host_port));
    for (h, v) in headers {
        request.push_str(&format!("{}: {}\r\n", h, v));
    }
    request.push_str("Connection: close\r\n");
    if let Some(b) = body {
        request.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    request.push_str("\r\n");
    if let Some(b) = body {
        request.push_str(b);
    }
    stream.write_all(request.as_bytes()).unwrap();

    let mut reader = BufReader::new(stream);
    let mut status_line = String::new();
    reader.read_line(&mut status_line).unwrap();
    let status_code = status_line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse::<u16>().ok())
        .expect("Invalid status line");

    let mut response_headers = HashMap::new();
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        if line.trim() == "" { break; }
        if let Some(idx) = line.find(':') {
            let key = line[..idx].trim().to_lowercase();
            let val = line[idx+1..].trim().to_string();
            response_headers.insert(key, val);
        }
    }

    let body = if let Some(te) = response_headers.get("transfer-encoding") {
        if te.contains("chunked") {
            let mut body_bytes = Vec::new();
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                let size = usize::from_str_radix(line.trim(), 16).unwrap_or(0);
                if size == 0 {
                    reader.read_line(&mut String::new()).unwrap();
                    break;
                }
                let mut buffer = vec![0; size];
                reader.read_exact(&mut buffer).unwrap();
                body_bytes.extend(buffer);
                reader.read_line(&mut String::new()).unwrap();
            }
            String::from_utf8(body_bytes).unwrap()
        } else {
            let len = response_headers.get("content-length").and_then(|s| s.parse::<usize>().ok()).unwrap_or(0);
            let mut buffer = vec![0; len];
            reader.read_exact(&mut buffer).unwrap();
            String::from_utf8(buffer).unwrap()
        }
    } else {
        let len = response_headers.get("content-length").and_then(|s| s.parse::<usize>().ok()).unwrap_or(0);
        let mut buffer = vec![0; len];
        reader.read_exact(&mut buffer).unwrap();
        String::from_utf8(buffer).unwrap()
    };

    (status_code, response_headers, body)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 { return; }
    let data_dir = &args[1];
    let base_url = &args[2];

    let client_json_path = format!("{}/client.json", data_dir);
    let client_content = std::fs::read_to_string(client_json_path).expect("Could not read client.json");
    let client_data = parse_json(&client_content);
    let client_obj = match client_data {
        JsonValue::Object(obj) => obj,
        _ => panic!("client.json must be an object"),
    };

    let client_id = match client_obj.get("client_id") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("Missing client_id"),
    };
    let client_secret = match client_obj.get("client_secret") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("Missing client_secret"),
    };
    let scope = match client_obj.get("scope") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("Missing scope"),
    };
    let page_size = match client_obj.get("page_size") {
        Some(JsonValue::Number(s)) => s.parse::<usize>().unwrap(),
        _ => panic!("Missing page_size"),
    };

    let url_split = base_url.trim_start_matches("http://");
    let (host_port, base_path) = match url_split.find('/') {
        Some(idx) => (&url_split[..idx], &url_split[idx..]),
        None => (url_split, ""),
    };

    let get_token = || {
        let encoded_id = url_encode(&client_id, true);
        let encoded_secret = url_encode(&client_secret, true);
        let auth_str = format!("{}:{}", encoded_id, encoded_secret);
        let auth_b64 = base64_encode(auth_str.as_bytes());

        let path = format!("{}/oauth/token", base_path);
        let body = format!("grant_type=client_credentials&scope={}", url_encode(&scope, true));
        let headers = vec![("Content-Type", "application/x-www-form-urlencoded"), ("Authorization", &format!("Basic {}", auth_b64))];

        let (status, _, body_resp) = send_request(host_port, "POST", &path, headers, Some(&body));
        if status != 200 {
            println!("ERROR {} {}", status, body_resp);
            std::process::exit(0);
        }
        let token_data = parse_json(&body_resp);
        if let JsonValue::Object(obj) = token_data {
            if let Some(JsonValue::String(at)) = obj.get("access_token") {
                return at.clone();
            }
        }
        panic!("Invalid token response");
    };

    let mut access_token = get_token();
    let mut cursor: Option<String> = None;
    let mut n_orders = 0;
    let mut n_pages = 0;
    let mut n_retries = 0;
    let mut n_reauth = 0;

    let mut totals: BTreeMap<(String, String), i64> = BTreeMap::new();
    let mut status_counts: BTreeMap<String, i64> = BTreeMap::new();

    loop {
        let mut path = format!("{}/orders?limit={}", base_path, page_size);
        if let Some(ref c) = cursor {
            path.push_str(&format!("&cursor={}", url_encode(c, false)));
        }

        let mut request_headers = vec![("Authorization", &format!("Bearer {}", access_token))];
        let mut status = 0;
        let mut body_resp = String::new();
        let mut response_headers = HashMap::new();

        loop {
            let (s, h, b) = send_request(host_port, "GET", &path, request_headers.clone(), None);
            status = s;
            response_headers = h;
            body_resp = b;

            if status == 200 {
                break;
            } else if status == 429 {
                n_retries += 1;
                let retry_after = response_headers.get("retry-after").and_then(|s| s.parse::<u64>().ok()).unwrap_or(0);
                std::thread::sleep(Duration::from_secs(retry_after));
            } else if status == 503 {
                n_retries += 1;
                std::thread::sleep(Duration::from_millis(500));
            } else if status == 401 {
                let new_token = get_token();
                if new_token == access_token {
                    // This case is handled by the fatal logic, but avoid infinite loop
                    println!("ERROR {} {}", status, body_resp);
                    std::process::exit(0);
                }
                access_token = new_token;
                n_reauth += 1;
                request_headers = vec![("Authorization", &format!("Bearer {}", access_token))];
                // Repeat the a-priori request
            } else {
                println!("ERROR {} {}", status, body_resp);
                std::process::exit(0);
            }
        }

        n_pages += 1;
        let page_data = parse_json(&body_resp);
        if let JsonValue::Object(obj) = page_data {
            if let Some(JsonValue::Array(orders)) = obj.get("data") {
                for order_val in orders {
                    if let JsonValue::Object(order) = order_val {
                        let status = match order.get("status") {
                            Some(JsonValue::String(s)) => s.clone(),
                            _ => "unknown".to_string(),
                        };
                        *status_counts.entry(status.clone()).or_insert(0) += 1;
                        if status != "cancelled" {
                            let amount = match order.get("amount") {
                                Some(JsonValue::String(s)) => parse_amount(s),
                                _ => 0,
                            };
                            let currency = match order.get("currency") {
                                Some(JsonValue::String(s)) => s.clone(),
                                _ => "USD".to_string(),
                            };
                            let customer_name = match order.get("customer") {
                                Some(JsonValue::Object(cust)) => match cust.get("name") {
                                    Some(JsonValue::String(n)) => n.clone(),
                                    _ => "Unknown".to_string(),
                                },
                                _ => "Unknown".to_string(),
                            };
                            *totals.entry((customer_name, currency)).or_insert(0) += amount;
                        }
                        n_orders += 1;
                    }
                }
            }
            cursor = match obj.get("next_cursor") {
                Some(JsonValue::String(s)) => Some(s.clone()),
                _ => None,
            };
        }

        if cursor.is_none() { break; }
    }

    let mut sorted_totals: Vec<_> = totals.iter().collect();
    sorted_totals.sort_by(|a, b| {
        let (name_a, curr_a) = a.0;
        let (name_b, curr_b) = b.0;
        name_a.cmp(name_b).then(curr_a.cmp(curr_b))
    });

    for ((name, curr), amount) in sorted_totals {
        println!("total {} {} {}", curr, format_amount(*amount), name);
    }

    let mut sorted_statuses: Vec<_> = status_counts.iter().collect();
    sorted_statuses.sort_by_key(|a| a.0);
    for (status, count) in sorted_statuses {
        println!("status {} {}", status, count);
    }

    println!("orders {} pages {} retries {} reauth {}", n_orders, n_pages, n_retries, n_reauth);
}

use std::collections::{BTreeMap, HashMap};
use std::fs::File;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::time::Duration;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn consume_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.consume_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => self.parse_string(),
            Some('t') | Some('f') => self.parse_bool(),
            Some('n') => self.parse_null(),
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> JsonValue {
        self.next(); // consume "
        let mut s = String::new();
        while let Some(c) = self.next() {
            if c == '"' { break; }
            if c == '\\' {
                match self.next() {
                    Some('n') => s.push('\n'),
                    Some('r') => s.push('\r'),
                    Some('t') => s.push('\t'),
                    Some('b') => s.push('\x08'),
                    Some('f') => s.push('\x0c'),
                    Some('\\') => s.push('\\'),
                    Some('"') => s.push('"'),
                    Some('/') => s.push('/'),
                    Some('u') => {
                        let mut hex = String::new();
                        for _ in 0..4 {
                            if let Some(ch) = self.next() { hex.push(ch); }
                        }
                        let code = u32::from_str_radix(&hex, 16).unwrap_or(0);
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.peek() == Some('\\') {
                                self.next(); // consume \
                                if self.next() == Some('u') {
                                    let mut hex2 = String::new();
                                    for _ in 0..4 {
                                        if let Some(ch) = self.next() { hex2.push(ch); }
                                    }
                                    let code2 = u32::from_str_radix(&hex2, 16).unwrap_or(0);
                                    let combined = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                    if let Some(ch) = std::char::from_u32(combined) {
                                        s.push(ch);
                                    }
                                }
                            }
                        } else {
                            if let Some(ch) = std::char::from_u32(code) {
                                s.push(ch);
                            }
                        }
                    }
                    _ => {}
                }
            } else {
                s.push(c);
            }
        }
        JsonValue::String(s)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.next(); // consume {
        let mut map = HashMap::new();
        loop {
            self.consume_whitespace();
            if self.peek() == Some('}') {
                self.next();
                break;
            }
            let key = match self.parse_string() {
                JsonValue::String(s) => s,
                _ => unreachable!(),
            };
            self.consume_whitespace();
            self.next(); // consume :
            let value = self.parse_value();
            map.insert(key, value);
            self.consume_whitespace();
            if self.peek() == Some(',') {
                self.next();
            } else if self.peek() == Some('}') {
                self.next();
                break;
            }
        }
        JsonValue::Object(map)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.next(); // consume [
        let mut arr = Vec::new();
        loop {
            self.consume_whitespace();
            if self.peek() == Some(']') {
                self.next();
                break;
            }
            arr.push(self.parse_value());
            self.consume_whitespace();
            if self.peek() == Some(',') {
                self.next();
            } else if self.peek() == Some(']') {
                self.next();
                break;
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_number(&mut self) -> JsonValue {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '-' || c == '.' || c == 'e' || c == 'E' || c == '+' {
                s.push(self.next().unwrap());
            } else {
                break;
            }
        }
        JsonValue::Number(s)
    }

    fn parse_bool(&mut self) -> JsonValue {
        if self.peek() == Some('t') {
            self.pos += 4;
            JsonValue::Bool(true)
        } else {
            self.pos += 5;
            JsonValue::Bool(false)
        }
    }

    fn parse_null(&mut self) -> JsonValue {
        self.pos += 4;
        JsonValue::Null
    }
}

fn parse_json(input: &str) -> JsonValue {
    let mut parser = Parser { input, pos: 0 };
    parser.parse_value()
}

