fn send_request(host_port: &str, method: &str, path: &str, headers: &[(&str, String)], body: Option<&str>) -> (u16, HashMap<String, String>, String) {
    let (host, port) = match host_port.find(':') {
        Some(idx) => (&host_port[..idx], host_port[idx+1..].parse::<u16>().unwrap_or(80)),
        None => (host_port, 80),
    };

    let mut stream = TcpStream::connect(format!("{}:{}", host, port)).expect("Connection failed");
    let mut request = format!("{} {} HTTP/1.1\r\n", method, path);
    request.push_str(&format!("Host: {}\r\n", host_port));
    for (h, v) in headers {
        request.push_str(&format!("{}: {}\r\n", h, v));
    }
    request.push_str("Connection: close\r\n");
    if let Some(b) = body {
        request.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    request.push_str("\r\n");
    if let Some(b) = body {
        request.push_str(b);
    }
    stream.write_all(request.as_bytes()).unwrap();

    let mut reader = BufReader::new(stream);
    let mut status_line = String::new();
    reader.read_line(&mut status_line).unwrap();
    let status_code = status_line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse::<u16>().ok())
        .expect("Invalid status line");

    let mut response_headers = HashMap::new();
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        if line.trim() == "" { break; }
        if let Some(idx) = line.find(':') {
            let key = line[..idx].trim().to_lowercase();
            let val = line[idx+1..].trim().to_string();
            response_headers.insert(key, val);
        }
    }

    let mut body_bytes = Vec::new();
    if let Some(te) = response_headers.get("transfer-encoding") {
        if te.contains("chunked") {
            loop {
                let mut line = Vec::new();
                reader.read_until(b'\n', &mut line).unwrap();
                let line_str = String::from_utf8_lossy(&line).trim().to_string();
                if line_str.is_empty() { continue; }
                let size = usize::from_str_radix(&line_str, 16).unwrap_or(0);
                if size == 0 {
                    let mut end_line = Vec::new();
                    reader.read_until(b'\n', &mut end_line).unwrap();
                    break;
                }
                let mut buffer = vec![0; size];
                reader.read_exact(&mut buffer).unwrap();
                body_bytes.extend(buffer);
                let mut crlf = [0; 2];
                reader.read_exact(&mut crlf).unwrap();
            }
        } else {
            let len = response_headers.get("content-length").and_then(|s| s.parse::<usize>().ok()).unwrap_or(0);
            let mut buffer = vec![0; len];
            reader.read_exact(&mut buffer).unwrap();
            body_bytes.extend(buffer);
        }
    } else {
        let len = response_headers.get("content-length").and_then(|s| s.parse::<usize>().ok()).unwrap_or(0);
        let mut buffer = vec![0; len];
        reader.read_exact(&mut buffer).unwrap();
        body_bytes.extend(buffer);
    }

    (status_code, response_headers, String::from_utf8(body_bytes).unwrap())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 { return; }
    let data_dir = &args[1];
    let base_url = &args[2];

    let client_json_path = format!("{}/client.json", data_dir);
    let client_content = std::fs::read_to_string(client_json_path).expect("Could not read client.json");
    let client_data = parse_json(&client_content);
    let client_obj = match client_data {
        JsonValue::Object(obj) => obj,
        _ => panic!("client.json must be an object"),
    };

    let client_id = match client_obj.get("client_id") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("Missing client_id"),
    };
    let client_secret = match client_obj.get("client_secret") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("Missing client_secret"),
    };
    let scope = match client_obj.get("scope") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("Missing scope"),
    };
    let page_size = match client_obj.get("page_size") {
        Some(JsonValue::Number(s)) => s.parse::<usize>().unwrap(),
        _ => panic!("Missing page_size"),
    };

    let url_split = base_url.trim_start_matches("http://");
    let (host_port, base_path) = match url_split.find('/') {
        Some(idx) => (&url_split[..idx], &url_split[idx..]),
        None => (url_split, ""),
    };

    let mut access_token = String::new();
    let mut n_reauth = 0;
    let mut n_orders = 0;
    let mut n_pages = 0;
    let mut n_retries = 0;

    let mut totals: BTreeMap<(String, String), i64> = BTreeMap::new();
    let mut status_counts: BTreeMap<String, i64> = BTreeMap::new();

    let mut get_token = |token_out: &mut String, reauth_out: &mut usize| {
        let encoded_id = url_encode(&client_id, true);
        let encoded_secret = url_encode(&client_secret, true);
        let auth_str = format!("{}:{}", encoded_id, encoded_secret);
        let auth_b64 = base64_encode(auth_str.as_bytes());

        let path = format!("{}/oauth/token", base_path);
        let body = format!("grant_type=client_credentials&scope={}", url_encode(&scope, true));
        let headers = vec![
            ("Content-Type", "application/x-www-form-urlencoded".to_string()),
            ("Authorization", format!("Basic {}", auth_b64)),
        ];

        let (status, _, body_resp) = send_request(host_port, "POST", &path, &headers, Some(&body));
        if status != 200 {
            println!("ERROR {} {}", status, body_resp);
            std::process::exit(0);
        }
        let token_data = parse_json(&body_resp);
        if let JsonValue::Object(obj) = token_data {
            if let Some(JsonValue::String(at)) = obj.get("access_token") {
                *token_out = at;
                return;
            }
        }
        println!("ERROR 200 Invalid token response");
        std::process::exit(0);
    };

    get_token(&mut access_token, &mut n_reauth);
    let mut cursor: Option<String> = None;

    loop {
        let mut path = format!("{}/orders?limit={}", base_path, page_size);
        if let Some(ref c) = cursor {
            path.push_str(&format!("&cursor={}", url_encode(c, false)));
        }

        let mut status = 0;
        let mut body_resp = String::new();
        let mut response_headers = HashMap::new();

        loop {
            let headers = vec![("Authorization", format!("Bearer {}", access_token))];
            let (s, h, b) = send_request(host_port, "GET", &path, &headers, None);
            status = s;
            response_headers = h;
            body_resp = b;

            if status == 200 {
                break;
            } else if status == 429 {
                n_retries += 1;
                let retry_after = response_headers.get("retry-after").and_then(|s| s.parse::<u64>().ok()).unwrap_or(0);
                std::thread::sleep(Duration::from_secs(retry_after));
            } else if status == 503 {
                n_retries += 1;
                std::thread::sleep(Duration::from_millis(500));
            } else if status == 401 {
                get_token(&mut access_token, &mut n_reauth);
                n_reauth += 1;
            } else {
                println!("ERROR {} {}", status, body_resp);
                std::process::exit(0);
            }
        }

        n_pages += 1;
        let page_data = parse_json(&body_resp);
        if let JsonValue::Object(obj) = page_data {
            if let Some(JsonValue::Array(orders)) = obj.get("data") {
                for order_val in orders {
                    if let JsonValue::Object(order) = order_val {
                        let order_status = match order.get("status") {
                            Some(JsonValue::String(s)) => s.clone(),
                            _ => "unknown".to_string(),
                        };
                        *status_counts.entry(order_status.clone()).or_insert(0) += 1;
                        if order_status != "cancelled" {
                            let amount = match order.get("amount") {
                                Some(JsonValue::String(s)) => parse_amount(s),
                                _ => 0,
                            };
                            let currency = match order.get("currency") {
                                Some(JsonValue::String(s)) => s.clone(),
                                _ => "USD".to_string(),
                            };
                            let customer_name = match order.get("customer") {
                                Some(JsonValue::Object(cust)) => match cust.get("name") {
                                    Some(JsonValue::String(n)) => n.clone(),
                                    _ => "Unknown".to_string(),
                                },
                                _ => "Unknown".to_string(),
                            };
                            *totals.entry((customer_name, currency)).or_insert(0) += amount;
                        }
                        n_orders += 1;
                    }
                }
            }
            cursor = match obj.get("next_cursor") {
                Some(JsonValue::String(s)) => Some(s.clone()),
                _ => None,
            };
        }

        if cursor.is_none() { break; }
    }

    for ((name, curr), amount) in totals {
        println!("total {} {} {}", curr, format_amount(amount), name);
    }

    for (status, count) in status_counts {
        println!("status {} {}", status, count);
    }

    println!("orders {} pages {} retries {} reauth {}", n_orders, n_pages, n_retries, n_reauth);
}

import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

interface RequestData {
  api_key: string;
  model: string;
  max_tokens: number;
  thinking_budget: number;
  system: string;
  prompt: string;
  tools: any[];
}

interface ContentBlock {
  type: string;
  thinking?: string;
  signature?: string;
  text?: string;
  id?: string;
  name?: string;
  input_json?: string;
  parsed_input?: any;
}

function escapeString(str: string): string {
  return str.replace(/\\/g, '\\\\')
            .replace(/\n/g, '\\n')
            .replace(/\r/g, '\\r')
            .replace(/\t/g, '\\t');
}

async function run() {
  const [dataDir, baseUrl] = process.argv.slice(2);
  const requestData: RequestData = JSON.parse(fs.readFileSync(path.join(dataDir, 'request.json'), 'utf8'));

  let totalInputTokens = 0;
  let totalOutputTokens = 0;
  let totalCacheReadTokens = 0;
  const outputLines: string[] = [];

  function addOutput(line: string) {
    outputLines.push(line);
  }

  async function makeRequest(messages: any[]) {
    const body = JSON.stringify({
      model: requestData.model,
      max_tokens: requestData.max_tokens,
      stream: true,
      thinking: { type: 'enabled', budget_tokens: requestData.thinking_budget },
      system: requestData.system,
      tools: requestData.tools,
      messages: messages,
    });

    return new Promise<{ blocks: ContentBlock[], stopReason: string, usage: { input: number, output: number, cache: number } }>((resolve, reject) => {
      const req = http.request(`${baseUrl}/v1/messages`, {
        method: 'POST',
        headers: {
          'x-api-key': requestData.api_key,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      }, (res) => {
        if (res.statusCode !== 200) {
          let errorBody = '';
          res.on('data', (chunk) => { errorBody += chunk; });
          res.on('end', () => {
            try {
              const parsed = JSON.parse(errorBody);
              reject({ status: res.statusCode, type: parsed.error.type, message: parsed.error.message });
            } catch (e) {
              reject({ status: res.statusCode, type: 'unknown', message: errorBody });
            }
          });
          return;
        }

        let buffer = '';
        const blocks: ContentBlock[] = [];
        let stopReason = '';
        let requestUsage = { input: 0, output: 0, cache: 0 };

        res.on('data', (chunk) => {
          buffer += chunk.toString();
          const lines = buffer.split(/\r?\n/);
          buffer = lines.pop() || '';

          let eventName = '';
          let eventData = '';

          for (let i = 0; i < lines.length; i++) {
            const line = lines[i];
            if (line === '') {
              if (eventName) {
                try {
                  const data = JSON.parse(eventData);
                  if (eventName === 'message_start') {
                    requestUsage.input = data.message.usage.input_tokens;
                    requestUsage.cache = data.message.usage.cache_read_input_tokens;
                  } else if (eventName === 'content_block_start') {
                    const block = data.content_block;
                    blocks[data.index] = { ...block, input_json: '', parsed_input: undefined };
                  } else if (eventName === 'content_block_delta') {
                    const block = blocks[data.index];
                    const delta = data.delta;
                    if (delta.type === 'thinking_delta') block.thinking += delta.thinking;
                    else if (delta.type === 'signature_delta') block.signature += delta.signature;
                    else if (delta.type === 'text_delta') block.text += delta.text;
                    else if (delta.type === 'input_json_delta') block.input_json += delta.partial_json;
                  } else if (eventName === 'content_block_stop') {
                    // Block finished
                  } else if (eventName === 'message_delta') {
                    stopReason = data.delta.stop_reason;
                    requestUsage.output = data.usage.output_tokens;
                  }
                } catch (e) {}
                eventName = '';
                eventData = '';
              }
            } else if (line.startsWith(':')) {
              // comment
            } else if (line.startsWith('event:')) {
              let val = line.slice(6);
              if (val.startsWith(' ')) val = val.slice(1);
              eventName = val;
            } else if (line.startsWith('data:')) {
              let val = line.slice(5);
              if (val.startsWith(' ')) val = val.slice(1);
              eventData += (eventData === '' ? '' : '\n') + val;
            }
          }
        });

        res.on('end', () => {
          resolve({ blocks, stopReason, usage: requestUsage });
        });
      });

      req.on('error', (e) => reject(e));
      req.write(body);
      req.end();
    });
  }

  try {
    addOutput('request 1');
    const res1 = await makeRequest([{ role: 'user', content: requestData.prompt }]);

    totalInputTokens += res1.usage.input;
    totalCacheReadTokens += res1.usage.cache;
    totalOutputTokens += res1.usage.output;

    for (const block of res1.blocks) {
      if (block.type === 'thinking') {
        addOutput(`thinking ${escapeString(block.thinking || '')}`);
        addOutput(`signature ${escapeString(block.signature || '')}`);
      } else if (block.type === 'text') {
        addOutput(`text ${escapeString(block.text || '')}`);
      } else if (block.type === 'tool_use') {
        addOutput(`tool_use ${block.id} ${block.name} ${escapeString(block.input_json || '')}`);
        block.parsed_input = JSON.parse(block.input_json || '{}');
      }
    }
    addOutput(`stop_reason ${res1.stopReason}`);

    const toolResults: any[] = [];
    for (const block of res1.blocks) {
      if (block.type === 'tool_use') {
        const input = block.parsed_input;
        let result: string;
        let isError = false;

        if (block.name === 'measure') {
          const { text, unit } = input;
          if (unit === 'code_points') result = Array.from(text).length.toString();
          else if (unit === 'utf8_bytes') result = Buffer.byteLength(text, 'utf8').toString();
          else if (unit === 'utf16_units') result = text.length.toString();
          else {
            result = `unsupported unit: ${unit}`;
            isError = true;
          }
        } else if (block.name === 'reverse') {
          const { text } = input;
          result = Array.from(text).reverse().join('');
        } else {
          result = `unknown tool: ${block.name}`;
          isError = true;
        }

        if (isError) addOutput(`error ${block.id} ${escapeString(result)}`);
        else addOutput(`result ${block.id} ${escapeString(result)}`);

        toolResults.push({
          type: 'tool_result',
          tool_use_id: block.id,
          content: result,
          is_error: isError,
        });
      }
    }

    addOutput('request 2');
    const assistantContent = res1.blocks.map(b => {
      if (b.type === 'thinking') return { type: 'thinking', thinking: b.thinking, signature: b.signature };
      if (b.type === 'text') return { type: 'text', text: b.text };
      if (b.type === 'tool_use') return { type: 'tool_use', id: b.id, name: b.name, input: b.parsed_input };
      return null;
    }).filter(Boolean);

    const res2 = await makeRequest([
      { role: 'user', content: requestData.prompt },
      { role: 'assistant', content: assistantContent },
      { role: 'user', content: toolResults },
    ]);

    totalInputTokens += res2.usage.input;
    totalCacheReadTokens += res2.usage.cache;
    totalOutputTokens += res2.usage.output;

    for (const block of res2.blocks) {
      if (block.type === 'thinking') {
        addOutput(`thinking ${escapeString(block.thinking || '')}`);
        addOutput(`signature ${escapeString(block.signature || '')}`);
      } else if (block.type === 'text') {
        addOutput(`text ${escapeString(block.text || '')}`);
      } else if (block.type === 'tool_use') {
        addOutput(`tool_use ${block.id} ${block.name} ${escapeString(block.input_json || '')}`);
      }
    }
    addOutput(`stop_reason ${res2.stopReason}`);
    addOutput(`usage input=${totalInputTokens} output=${totalOutputTokens} cache_read=${totalCacheReadTokens}`);

  } catch (err: any) {
    if (err.status) {
      process.stdout.write(outputLines.join('\n') + (outputLines.length > 0 ? '\n' : ''));
      process.stdout.write(`ERROR ${err.status} ${err.type}: ${err.message}\n`);
    } else {
      process.stderr.write(err.stack);
    }
    process.exit(0);
  }

  process.stdout.write(outputLines.join('\n') + '\n');
  process.exit(0);
}

run();

