            .replace(/\r/g, '\\r')
            .replace(/\t/g, '\\t');
}

async function run() {
  const [dataDir, baseUrl] = process.argv.slice(2);
  if (!dataDir || !baseUrl) return;
  const requestData: RequestData = JSON.parse(fs.readFileSync(path.join(dataDir, 'request.json'), 'utf8'));

  let totalInputTokens = 0;
  let totalOutputTokens = 0;
  let totalCacheReadTokens = 0;
  const outputLines: string[] = [];

  function addOutput(line: string) {
    outputLines.push(line);
  }

  async function makeRequest(messages: any[]) {
    const body = JSON.stringify({
      model: requestData.model,
      max_tokens: requestData.max_tokens,
      stream: true,
      thinking: { type: 'enabled', budget_tokens: requestData.thinking_budget },
      system: requestData.system,
      tools: requestData.tools,
      messages: messages,
    });

    return new Promise<{ blocks: ContentBlock[], stopReason: string, usage: { input: number, output: number, cache: number } }>((resolve, reject) => {
      const req = http.request(`${baseUrl}/v1/messages`, {
        method: 'POST',
        headers: {
          'x-api-key': requestData.api_key,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      }, (res) => {
        if (res.statusCode !== 200) {
          let errorBody = '';
          res.on('data', (chunk) => { errorBody += chunk; });
          res.on('end', () => {
            try {
              const parsed = JSON.parse(errorBody);
              reject({ status: res.statusCode, type: parsed.error.type, message: parsed.error.message });
            } catch (e) {
              reject({ status: res.statusCode, type: 'unknown', message: errorBody });
            }
          });
          return;
        }

        let buffer = Buffer.alloc(0);
        const blocks: ContentBlock[] = [];
        let stopReason = '';
        let requestUsage = { input: 0, output: 0, cache: 0 };

        let eventName = '';
        let eventData = '';

        const processEvent = (name: string, dataStr: string) => {
          try {
            const data = JSON.parse(dataStr);
            if (name === 'message_start') {
              requestUsage.input = data.message.usage.input_tokens;
              requestUsage.cache = data.message.usage.cache_read_input_tokens;
            } else if (name === 'content_block_start') {
              const block = data.content_block;
              blocks[data.index] = { 
                ...block, 
                thinking: block.type === 'thinking' ? '' : undefined,
                signature: block.type === 'thinking' ? '' : undefined,
                text: block.type === 'text' ? '' : undefined,
                input_json: block.type === 'tool_use' ? '' : undefined
              };
            } else if (name === 'content_block_delta') {
              const block = blocks[data.index];
              const delta = data.delta;
              if (delta.type === 'thinking_delta') block.thinking += delta.thinking;
              else if (delta.type === 'signature_delta') block.signature += delta.signature;
              else if (delta.type === 'text_delta') block.text += delta.text;
              else if (delta.type === 'input_json_delta') block.input_json += delta.partial_json;
            } else if (name === 'message_delta') {
              stopReason = data.delta.stop_reason;
              requestUsage.output = data.usage.output_tokens;
            }
          } catch (e) {}
        };

        res.on('data', (chunk) => {
          buffer = Buffer.concat([buffer, chunk]);
          let offset = 0;
          while (true) {
            const lineEnd = buffer.indexOf('\n', offset);
            if (lineEnd === -1) break;

            const line = buffer.slice(offset, lineEnd).toString('utf8').replace('\r', '');
            if (line === '') {
              if (eventName) {
                processEvent(eventName, eventData);
                eventName = '';
                eventData = '';
              }
            } else if (line.startsWith('event:')) {
              let val = line.slice(6);
              if (val.startsWith(' ')) val = val.slice(1);
              eventName = val;
            } else if (line.startsWith('data:')) {
              let val = line.slice(5);
              if (val.startsWith(' ')) val = val.slice(1);
              eventData += (eventData === '' ? '' : '\n') + val;
            }
            offset = lineEnd + 1;
          }
          buffer = buffer.slice(offset);
        });

        res.on('end', () => {
          if (eventName) {
            processEvent(eventName, eventData);
          }
          resolve({ blocks, stopReason, usage: requestUsage });
        });
      });

      req.on('error', (e) => reject(e));
      req.write(body);
      req.end();
    });
  }

  try {
    addOutput('request 1');
    const res1 = await makeRequest([{ role: 'user', content: requestData.prompt }]);

    totalInputTokens += res1.usage.input;
    totalCacheReadTokens += res1.usage.cache;
    totalOutputTokens += res1.usage.output;

    for (const block of res1.blocks) {
      if (!block) continue;
      if (block.type === 'thinking') {
