#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <time.h>

typedef struct {
    char *name;
    char *currency;
    long long sum;
} OrderSum;

typedef struct {
    char *status;
    int count;
} StatusCount;

char *url_encode(const char *s) {
    char *res = malloc(strlen(s) * 3 + 1);
    int j = 0;
    for (int i = 0; s[i]; i++) {
        if ((s[i] >= 'a' && s[i] <= 'z') || (s[i] >= 'A' && s[i] <= 'Z') ||
            (s[i] >= '0' && s[i] <= '9') || s[i] == '-' || s[i] == '.' ||
            s[i] == '_' || s[i] == '*') {
            res[j++] = s[i];
