char *json_unescape(const char *s, int len) {
    char *res = malloc(len * 4 + 1);
    int j = 0;
    for (int i = 0; i < len; i++) {
        if (s[i] == '\\' && i + 1 < len) {
            i++;
            switch (s[i]) {
                case '"': res[j++] = '"'; break;
                case '\\': res[j++] = '\\'; break;
                case '/': res[j++] = '/'; break;
                case 'b': res[j++] = '\b'; break;
                case 'f': res[j++] = '\f'; break;
                case 'n': res[j++] = '\n'; break;
                case 'r': res[j++] = '\r'; break;
                case 't': res[j++] = '\t'; break;
                case 'u': {
                    i++;
                    unsigned int val = 0;
                    for (int k = 0; k < 4; k++) {
                        char c = s[i++];
                        if (c >= '0' && c <= '9') val = val * 16 + (c - '0');
                        else if (c >= 'a' && c <= 'f') val = val * 16 + (c - 'a' + 10);
                        else if (c >= 'A' && c <= 'F') val = val * 16 + (c - 'A' + 10);
                    }
                    if (val >= 0xD800 && val <= 0xDBFF && i < len && s[i] == '\\' && i + 1 < len && s[i + 1] == 'u') {
                        i += 2;
                        unsigned int val2 = 0;
                        for (int k = 0; k < 4; k++) {
                            char c = s[i++];
                            if (c >= '0' && c <= '9') val2 = val2 * 16 + (c - '0');
                            else if (c >= 'a' && c <= 'f') val2 = val2 * 16 + (c - 'a' + 10);
                            else if (c >= 'A' && c <= 'F') val2 = val2 * 16 + (c - 'A' + 10);
                        }
                        unsigned int cp = 0x10000 + (val - 0xD800) * 0x400 + (val2 - 0xDC00);
                        utf8_encode(cp, res, &j);
                    } else {
                        utf8_encode(val, res, &j);
                    }
                    break;
                }
                default: res[j++] = s[i]; break;
            }
        } else {
            res[j++] = s[i];
        }
    }
    res[j] = '\0';
