long long parse_amount(const char *s) {
    long long integer_part = 0, fractional_part = 0;
    int sign = 1, i = 0;
    if (s[i] == '-') { sign = -1; i++; }
    while (s[i] && s[i] != '"' && s[i] != ' ' && s[i] != '.') {
        integer_part = integer_part * 10 + (s[i] - '0');
        i++;
    }
    if (s[i] == '.') {
        i++;
        if (s[i] >= '0' && s[i] <= '9') {
            fractional_part = s[i] - '0';
            i++;
            if (s[i] >= '0' && s[i] <= '9') {
                fractional_part = fractional_part * 10 + (s[i] - '0');
                i++;
            } else {
                fractional_part *= 10;
            }
        }
    }
    return sign * (integer_part * 100 + fractional_part);
}

char *extract_json_string(const char *json, const char *key, int *len) {
    char search[128];
    sprintf(search, "\"%s\":", key);
    char *start = strstr(json, search);
    if (!start) return NULL;
    start += strlen(search);
    while (*start == ' ' || *start == '"') start++;
    char *end = strchr(start, '"');
    if (!end) return NULL;
    *len = end - start;
    char *res = malloc(*len + 1);
    memcpy(res, start, *len);
    res[*len] = '\0';
    return res;
}

