typedef struct {
    int status;
    char *body;
} HttpResponse;

HttpResponse send_request(const char *host, const char *path, const char *method, const char *headers, const char *body) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    getaddrinfo(host, NULL, &hints, &res);
    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    connect(sock, res->ai_addr, res->ai_addrlen);
    freeaddrinfo(res);

    char req[4096];
    int req_len = sprintf(req, "%s %s HTTP/1.1\r\nHost: %s\r\n%sConnection: close\r\n", method, path, host, headers ? headers : "");
    if (body) {
        char body_hdr[128];
        int bh_len = sprintf(body_hdr, "Content-Length: %lu\r\n", strlen(body));
        memcpy(req + req_len, body_hdr, bh_len);
        req_len += bh_len;
    }
    req_len += sprintf(req + req_len, "\r\n");
    send(sock, req, req_len, 0);
    if (body) send(sock, body, strlen(body), 0);

    char response[8192];
    int total_recv = 0;
    while (1) {
        int n = recv(sock, response + total_recv, sizeof(response) - total_recv - 1, 0);
        if (n <= 0) break;
        total_recv += n;
    }
    response[total_recv] = '\0';
    close(sock);

    HttpResponse hr;
    char status_str[16];
    sscanf(response, "HTTP/1.1 %s", status_str);
    hr.status = atoi(status_str);
    char *body_start = strstr(response, "\r\n\r\n");
    if (body_start) {
        body_start += 4;
        int body_len = total_recv - (body_start - response);
        char *body_buf = malloc(body_len + 1);
        memcpy(body_buf, body_start, body_len);
        body_buf[body_len] = '\0';

        if (strstr(response, "Transfer-Encoding: chunked")) {
            int b_idx = 0;
            while (1) {
                char *chunk_start = body_start + b_idx;
                char *chunk_end = strstr(chunk_start, "\r\n");
                int chunk_size = strtol(chunk_start, NULL, 16);
                if (chunk_size == 0) break;
                memcpy(body_buf + b_idx, chunk_end + 2, chunk_size);
                b_idx += chunk_size;
                body_start = chunk_end + 2 + chunk_size;
                body_start += 2; // skip \r\n
            }
            body_buf[b_idx] = '\0';
        }
        hr.body = body_buf;
    } else {
        hr.body = strdup("");
    }
    return hr;
}

