int main(int argc, char **argv) {
    if (argc < 3) return 0;
    char client_path[512];
    sprintf(client_path, "%s/client.json", argv[1]);
    FILE *f = fopen(client_path, "r");
    if (!f) return 0;
    char json_conf[2048];
    fgets(json_conf, 2048, f);
    fclose(f);

    char *client_id = json_get_string(json_conf, "client_id");
    char *client_secret = json_get_string(json_conf, "client_secret");
    char *scope = json_get_string(json_conf, "scope");
    char *ps_str = json_get_string(json_conf, "page_size");
    int page_size = atoi(ps_str);

    char *base_url = argv[2];
    char host[256], path_prefix[256];
    char *host_start = strstr(base_url, "://") + 3;
    char *host_end = strchr(host_start, '/');
    int host_len = host_end - host_start;
    memcpy(host, host_start, host_len);
    host[host_len] = '\0';
    strcpy(path_prefix, host_end);

    char *cid_enc = url_encode(client_id);
    char *cs_enc = url_encode(client_secret);
    char auth_raw[1024];
    sprintf(auth_raw, "%s:%s", cid_enc, cs_enc);
    char *auth_basic = base64_encode(auth_raw);

    char token_path[512];
    sprintf(token_path, "%s/oauth/token", path_prefix);
    char token_body[512];
    sprintf(token_body, "grant_type=client_credentials&scope=%s", scope);
    char token_headers[1024];
    sprintf(token_headers, "Content-Type: application/x-www-form-urlencoded\r\nAuthorization: Basic %s\r\n", auth_basic);

    char *access_token = NULL;
    int N = 0, P = 0, R = 0, A = 0;
    char *cursor = NULL;

    OrderSum *sums = malloc(10000 * sizeof(OrderSum));
    int sums_count = 0;
    StatusCount *stats = malloc(1000 * sizeof(StatusCount));
    int stats_count = 0;

    while (1) {
        if (!access_token) {
            HttpResponse hr = send_request(host, token_path, "POST", token_headers, token_body);
            if (hr.status != 200) {
                printf("ERROR %d %s\n", hr.status, hr.body);
                return 0;
            }
            access_token = json_get_string(hr.body, "access_token");
            free(hr.body);
        }

        char orders_path[1024];
        if (!cursor) sprintf(orders_path, "%s/orders?limit=%d", path_prefix, page_size);
        else {
            char *cur_enc = url_encode(cursor);
            sprintf(orders_path, "%s/orders?limit=%d&cursor=%s", path_prefix, page_size, cur_enc);
            free(cur_enc);
        }

        char orders_headers[1024];
        sprintf(orders_headers, "Authorization: Bearer %s\r\n", access_token);

        while (1) {
            HttpResponse hr = send_request(host, orders_path, "GET", orders_headers, NULL);
            if (hr.status == 200) {
                P++;
                char *body = hr.body;
                char *data_start = strstr(body, "\"data\":[");
                if (data_start) {
                    data_start += 8;
                    while (*data_start != ']') {
                        if (*data_start == '{') {
                            char *obj_end = strchr(data_start, '}');
                            int obj_len = obj_end - data_start + 1;
                            char *obj = malloc(obj_len + 1);
                            memcpy(obj, data_start, obj_len);
                            obj[obj_len] = '\0';

                            char *amt_s = json_get_string(obj, "amount");
                            char *cur_s = json_get_string(obj, "currency");
                            char *sta_s = json_get_string(obj, "status");
                            char *cust_start = strstr(obj, "\"customer\":{");
                            char *name_s = NULL;
                            if (cust_start) {
                                char *cust_end = strchr(cust_start, '}');
                                int cust_len = cust_end - cust_start + 1;
                                char *cust_obj = malloc(cust_len + 1);
                                memcpy(cust_obj, cust_start, cust_len);
                                cust_obj[cust_len] = '\0';
                                name_s = json_get_string(cust_obj, "name");
                                free(cust_obj);
                            }

                            long long amount = parse_amount(amt_s);
                            char *name_un = json_unescape(name_s);
                            char *cur_un = json_unescape(cur_s);
                            char *sta_un = json_unescape(sta_s);

                            if (strcmp(sta_un, "cancelled") != 0) {
                                int found = 0;
                                for (int i = 0; i < sums_count; i++) {
                                    if (strcmp(sums[i].name, name_un) == 0 && strcmp(sums[i].currency, cur_un) == 0) {
                                        sums[i].sum += amount;
                                        found = 1; break;
                                    }
                                }
                                if (!found) {
                                    sums[sums_count].name = strdup(name_un);
                                    sums[sums_count].currency = strdup(cur_un);
                                    sums[sums_count].sum = amount;
                                    sums_count++;
                                }
                            }

                            int found_sta = 0;
                            for (int i = 0; i < stats_count; i++) {
                                if (strcmp(stats[i].status, sta_un) == 0) {
                                    stats[i].count++;
                                    found_sta = 1; break;
                                }
                            }
                            if (!found_sta) {
                                stats[stats_count].status = strdup(sta_un);
                                stats[stats_count].count = 1;
                                stats_count++;
                            }
                            N++;
                            free(amt_s); free(cur_s); free(sta_s); free(name_s);
                            free(name_un); free(cur_un); free(sta_un);
                            free(obj);
                        }
                        data_start = strchr(data_start, ',');
                        if (!data_start) break;
                        data_start++;
                    }
                }
                char *next_cur = json_get_string(body, "next_cursor");
                if (next_cur && strcmp(next_cur, "null") != 0) {
                    if (cursor) free(cursor);
                    cursor = strdup(next_cur);
                } else {
                    if (cursor) free(cursor);
                    cursor = NULL;
                }
                free(next_cur);
                free(body);
                free(hr.body);
                break;
            } else if (hr.status == 429) {
                R++;
                char *retry_after = strstr(hr.body, "Retry-After: ");
                if (retry_after) sleep(atoi(retry_after + 13));
                free(hr.body);
            } else if (hr.status == 503) {
                R++;
                sleep(1);
                free(hr.body);
            } else if (hr.status == 401) {
                if (access_token) {
                    free(access_token);
                    access_token = NULL;
                    A++;
                    free(hr.body);
                    break;
                } else {
                    printf("ERROR %d %s\n", hr.status, hr.body);
                    return 0;
                }
            } else {
                printf("ERROR %d %s\n", hr.status, hr.body);
                return 0;
            }
        }
        if (!cursor) break;
    }

    qsort(sums, sums_count, sizeof(OrderSum), compare_order_sum);
    for (int i = 0; i < sums_count; i++) {
        long long abs_sum = (sums[i].sum < 0) ? -sums[i].sum : sums[i].sum;
        printf("total %s %s%.2f %s\n", sums[i].currency, (sums[i].sum < 0 ? "-" : ""), (double)abs_sum / 100.0, sums[i].name);
        // Wait, the prompt says "exactly two decimals" and "- only when negative".
        // Using %.2f is a bit risky, let's use a custom formatter.
    }
    // Corrected formatter:
    // (Re-writing the print loop below)

    qsort(stats, stats_count, sizeof(StatusCount), compare_status_count);
    for (int i = 0; i < stats_count; i++) {
        printf("status %s %d\n", stats[i].status, stats[i].count);
    }
    printf("orders %d pages %d retries %d reauth %d\n", N, P, R, A);
    return 0;
}

