        let ps = Int(header[16]) << 8 | Int(header[17])
        self.pageSize = ps == 0 ? 1024 : ps
        self.reservedBytes = Int(header[20])
    }

    func readBytes(at offset: Int, length: Int) throws -> [UInt8] {
        try handle.seek(toOffset: UInt64(offset))
        let data = try handle.read(upToCount: length) ?? Data()
        return [UInt8](data)
    }

    func readVarint(at offset: inout Int, data: [UInt8]) -> Int64 {
        var result: UInt64 = 0
        var shift: Int = 0
        for i in 0..<8 {
            if offset >= data.count { break }
            let b = data[offset]
            offset += 1
            result |= UInt64(b & 0x7F) << shift
            if b < 128 { return Int64(bitPattern: result) }
            shift += 7
        }
        if offset >= data.count { return Int64(bitPattern: result) }
        let b = data[offset]
        offset += 1
        result |= UInt64(b) << shift
        return Int64(bitPattern: result)
    }

    func readPage(_ pageID: Int) throws -> [UInt8] {
        let offset = (pageID - 1) * pageSize
        return try readBytes(at: offset, length: pageSize)
    }
}

// --- B-Tree and Record Parsing ---
class SQLiteParser {
    let file: SQLiteFile

    init(file: SQLiteFile) {
        self.file = file
    }

    func traverseBTree(pageID: Int, isRoot: Bool, callback: (Int64, [UInt8]) -> Void) throws {
        let page = try file.readPage(pageID)
        let headerStart = isRoot ? 100 : 0
        let pageType = page[headerStart]

        var offset = headerStart + 1
        // First free block offset (varint)
        _ = readVarint(at: &offset, data: page)
        let cellCount = Int(page[offset]) << 8 | Int(page[offset+1])
        offset += 2
        let cellStart = Int(page[offset]) << 8 | Int(page[offset+1])
        offset += 2
        // Free block count (2 bytes), Right-most pointer (4 bytes)

        if pageType == 0x0D { // Leaf Table B-Tree
            for i in 0..<cellCount {
                let cellPtr = Int(page[cellStart + i*2]) << 8 | Int(page[cellStart + i*2 + 1])
                var cOffset = cellPtr
                let payloadSize = readVarint(at: &cOffset, data: page)
                let rowid = readVarint(at: &cOffset, data: page)

                var payload = [UInt8]()
                let overhead = (cOffset - cellPtr)
                let maxPayload = file.pageSize - 4 - overhead

                if payloadSize > maxPayload {
                    var overflowPageID = 0
                    for j in 0..<4 {
                        overflowPageID |= Int(page[cOffset + j]) << (8 * (3 - j))
                    }
                    let available = file.pageSize - cOffset
                    payload = Array(page[cOffset + 4 ..< cOffset + 4 + available])

                    var currOverflow = overflowPageID
                    while currOverflow != 0 {
                        let oPage = try file.readPage(currOverflow)
                        payload.append(contentsOf: oPage[0 ..< file.pageSize - 4])
                        let last4 = oPage[file.pageSize - 4 ..< file.pageSize]
                        currOverflow = Int(last4[0]) << 24 | Int(last4[1]) << 16 | Int(last4[2]) << 8 | Int(last4[3])
                    }
                } else {
                    payload = Array(page[cOffset ..< cOffset + Int(payloadSize)])
                }
                callback(rowid, payload)
            }
        } else if pageType == 0x05 { // Interior Table B-Tree
            for i in 0..<cellCount {
                let cellPtr = Int(page[cellStart + i*2]) << 8 | Int(page[cellStart + i*2 + 1])
                var cOffset = cellPtr
                let payloadSize = readVarint(at: &cOffset, data: page)
                let _ = readVarint(at: &cOffset, data: page) // skip rowid

                let childPageID = Int(page[cOffset + Int(payloadSize) - 4]) << 24 | 
                                  Int(page[cOffset + Int(payloadSize) - 3]) << 16 | 
                                  Int(page[cOffset + Int(payloadSize) - 2]) << 8 | 
                                  Int(page[cOffset + Int(payloadSize) - 1])
                try traverseBTree(pageID: childPageID, isRoot: false, callback: callback)
            }
        }
    }

    func readVarint(at offset: inout Int, data: [UInt8]) -> Int64 {
        return file.readVarint(at: &offset, data: data)
    }

    func parseRecord(payload: [UInt8], columnCount: Int, isAlias: Int?) -> [Any?] {
        var offset = 0
        let headerSize = readVarint(at: &offset, data: payload)
        let numCols = readVarint(at: &offset, data: payload)

        var serialTypes = [Int]()
        while offset < headerSize {
            serialTypes.append(Int(readVarint(at: &offset, data: payload)))
        }

        var values = [Any?]()
        for i in 0..<Int(numCols) {
            if i >= serialTypes.count {
                values.append(nil)
                continue
            }
            let type = serialTypes[i]
            if type == 0 {
                values.append(nil)
            } else if type >= 1 && type <= 6 {
                let len = type - 1
                var res: Int64 = 0
                for j in 0..<len {
                    res = (res << 8) | Int64(payload[offset + j])
                }
                if (payload[offset] & 0x80) != 0 && len < 8 {
                    let mask = (1 << (len * 8)) - 1
                    res |= ~Int64(mask)
                }
                values.append(res)
                offset += len
            } else if type == 7 {
                var res: UInt64 = 0
                for j in 0..<8 {
                    res = (res << 8) | UInt64(payload[offset + j])
                }
                values.append(Double(bitPattern: res))
                offset += 8
            } else {
                let len = Int(type) - 128
                let data = Array(payload[offset ..< offset + len])
                values.append(data)
                offset += len
            }
        }

        // Handle ALIAS for rowid (INTEGER PRIMARY KEY)
        if let aliasIdx = isAlias {
            if aliasIdx < values.count {
                // The value in the record for the alias column is always NULL
            }
        }

        return values
    }
}

// --- Helper for SQL Parsing ---
func parseColumns(sql: String) -> (names: [String], aliasIdx: Int?) {
    let startIdx = sql.firstIndex(of: "(")!
    let endIdx = sql.lastIndex(of: ")")!
    let defsRaw = String(sql[sql.index(after: startIdx)...sql.index(before: endIdx)])

    var cols = [String]()
    var currentDef = ""
    var bracketDepth = 0
    var inQuotes = false

    for char in defsRaw {
        if char == "\"" { inQuotes = !inQuotes }
        if !inQuotes {
            if char == "(" { bracketDepth += 1 }
            else if char == ")" { bracketDepth -= 1 }
        }
        if char == "," && bracketDepth == 0 && !inQuotes {
