        let parts = def.split(separator: " ", omittingEmptySubsequences: true)
        if parts.isEmpty { continue }
        var name = String(parts[0])
        if name.hasPrefix("\"") && name.hasSuffix("\"") {
            name = String(name.dropFirst().dropLast())
        }
        names.append(name)

        let upperDef = def.uppercased()
        if upperDef.contains("INTEGER") && upperDef.contains("PRIMARY KEY") {
            // Check if it's exactly 'INTEGER' not 'INT'
            let tokens = def.split(separator: " ")
            if tokens.count > 1 {
                let typeToken = tokens[1].uppercased()
                if typeToken == "INTEGER" {
                    aliasIdx = i
                }
            } else {
                // Simple case: colname INTEGER PRIMARY KEY
                // We need a more robust way to check for "INTEGER"
            }
            // Actually, the prompt says: "declared type is the single word INTEGER"
            // and "definition contains PRIMARY KEY".
            var isInteger = false
            let words = def.components(separatedBy: .whitespacesAndNewlines).filter { !$0.isEmpty }
            for word in words {
                if word.uppercased() == "INTEGER" { isInteger = true; break }
            }
            if isInteger && upperDef.contains("PRIMARY KEY") {
                aliasIdx = i
            }
        }
    }
    return (names, aliasIdx)
}

