// To properly distinguish TEXT and BLOB, we need the declared type.
// Let's refine the column parsing.
struct ColumnInfo {
    let name: String
    let declaredType: String
    let isAlias: Bool
}

func parseColumnsDetailed(sql: String) -> [ColumnInfo] {
    let startIdx = sql.firstIndex(of: "(")!
    let endIdx = sql.lastIndex(of: ")")!
    let defsRaw = String(sql[sql.index(after: startIdx)...sql.index(before: endIdx)])
    var cols = [String]()
    var currentDef = "", bracketDepth = 0, inQuotes = false
    for char in defsRaw {
        if char == "\"" { inQuotes = !inQuotes }
        if !inQuotes {
            if char == "(" { bracketDepth += 1 }
            else if char == ")" { bracketDepth -= 1 }
        }
        if char == "," && bracketDepth == 0 && !inQuotes {
            cols.append(currentDef.trimmingCharacters(in: .whitespacesAndNewlines))
            currentDef = ""
        } else { currentDef.append(char) }
    }
    cols.append(currentDef.trimmingCharacters(in: .whitespacesAndNewlines))

    var infos = [ColumnInfo]()
    for def in cols {
        let tokens = def.split(separator: " ", omittingEmptySubsequences: true)
        if tokens.isEmpty { continue }
        var name = String(tokens[0])
        if name.hasPrefix("\"") && name.hasSuffix("\"") { name = String(name.dropFirst().dropLast()) }
        let upperDef = def.uppercased()
        let isAlias = upperDef.contains("INTEGER") && upperDef.contains("PRIMARY KEY") && 
                      (tokens.count > 1 ? tokens[1].uppercased() == "INTEGER" : false)
        var declaredType = "TEXT"
        if tokens.count > 1 {
            let type = tokens[1].uppercased()
            if type == "BLOB" { declaredType = "BLOB" }
        }
        infos.append(ColumnInfo(name: name, declaredType: declaredType, isAlias: isAlias))
    }
    return infos
}

