    }

    static func sendRequest(baseUrl: String, apiKey: String, body: [String: Any]) async -> ([BlockState], String, Usage, (status: Int, type: String, message: String)?) {
        let url = URL(string: "\(baseUrl)/v1/messages")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue(apiKey, forHTTPHeaderField: "x-api-key")
        request.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let jsonData = try! JSONSerialization.data(withJSONObject: body)
        request.httpBody = jsonData

        do {
            let (stream, response) = try await URLSession.shared.bytes(for: request)
            guard let httpResponse = response as? HTTPURLResponse else {
                return ([], "", Usage(), nil)
            }

            if httpResponse.statusCode != 200 {
                let bodyData = try await stream.collect()
                if let errorJson = try? JSONSerialization.jsonObject(with: bodyData) as? [String: Any],
                   let errorObj = errorJson["error"] as? [String: Any] {
                    return ([], "", Usage(), (status: httpResponse.statusCode, type: errorObj["type"] as? String ?? "", message: errorObj["message"] as? String ?? ""))
                }
                return ([], "", Usage(), (status: httpResponse.statusCode, type: "unknown", message: "unknown error"))
            }

            var blocks: [BlockState] = []
            var stopReason = ""
            var usage = Usage()
            var currentEventName = ""
            var currentEventData = ""

            for try await line in stream.lines {
                if line.isEmpty {
                    if !currentEventName.isEmpty {
                        if let data = currentEventData.data(using: .utf8),
                           let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
                            switch currentEventName {
                            case "message_start":
                                if let msg = json["message"] as? [String: Any],
                                   let u = msg["usage"] as? [String: Any] {
                                    usage.input += u["input_tokens"] as? Int ?? 0
                                    usage.cacheRead += u["cache_read_input_tokens"] as? Int ?? 0
                                }
                            case "content_block_start":
                                if let index = json["index"] as? Int,
                                   let block = json["content_block"] as? [String: Any] {
                                    let type = block["type"] as? String ?? ""
                                    let state = BlockState()
                                    state.type = type
                                    if type == "thinking" {
                                        state.thinking = block["thinking"] as? String ?? ""
                                        state.signature = block["signature"] as? String ?? ""
                                    } else if type == "text" {
                                        state.text = block["text"] as? String ?? ""
                                    } else if type == "tool_use" {
                                        state.id = block["id"] as? String ?? ""
                                        state.name = block["name"] as? String ?? ""
                                    }
                                    while blocks.count <= index { blocks.append(BlockState()) }
                                    blocks[index] = state
                                }
                            case "content_block_delta":
                                if let index = json["index"] as? Int,
                                   let delta = json["delta"] as? [String: Any],
                                   index < blocks.count {
                                    let state = blocks[index]
                                    if let type = delta["type"] as? String {
                                        switch type {
                                        case "thinking_delta": state.thinking += delta["thinking"] as? String ?? ""
                                        case "signature_delta": state.signature += delta["signature"] as? String ?? ""
                                        case "text_delta": state.text += delta["text"] as? String ?? ""
                                        case "input_json_delta": state.rawJson += delta["partial_json"] as? String ?? ""
                                        default: break
                                        }
                                    }
                                }
                            case "message_delta":
                                if let delta = json["delta"] as? [String: Any] {
                                    stopReason = delta["stop_reason"] as? String ?? ""
                                }
                                if let u = json["usage"] as? [String: Any] {
                                    usage.output += u["output_tokens"] as? Int ?? 0
                                }
                            default: break
                            }
                        }
                    }
                    currentEventName = ""
                    currentEventData = ""
                    continue
                }
                if line.hasPrefix(":") { continue }
                if line.hasPrefix("event") {
                    if let colonIdx = line.firstIndex(of: ":") {
                        var val = String(line[line.index(after: colonIdx)...])
                        if val.hasPrefix(" ") { val.removeFirst() }
                        currentEventName = val
                    }
                } else if line.hasPrefix("data") {
                    if let colonIdx = line.firstIndex(of: ":") {
                        var val = String(line[line.index(after: colonIdx)...])
                        if val.hasPrefix(" ") { val.removeFirst() }
                        if !currentEventData.isEmpty { currentEventData += "\n" }
                        currentEventData += val
                    }
                }
            }
            return (blocks, stopReason, usage, nil)
        } catch {
            return ([], "", Usage(), nil)
        }
    }
}

extension AsyncSequence where Element == UInt8 {
    func collect() async throws -> Data {
        var data = Data()
        for try await byte in self {
            data.append(byte)
        }
        return data
    }
