import Foundation

// --- Helper Functions ---

func escape(_ s: String) -> String {
    var result = ""
    for char in s {
        switch char {
        case "\\": result += "\\\\"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        default: result.append(char)
        }
    }
    return result
}

func executeTool(name: String, inputJSON: String) -> (result: String, isError: Bool) {
    guard let data = inputJSON.data(using: .utf8),
          let input = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
        return ("invalid json input", true)
    }
    switch name {
    case "measure":
        guard let text = input["text"] as? String,
              let unit = input["unit"] as? String else {
            return ("missing text or unit", true)
        }
        switch unit {
        case "code_points": return (String(text.unicodeScalars.count), false)
        case "utf8_bytes": return (String(text.utf8.count), false)
        case "utf16_units": return (String(text.utf16.count), false)
        default: return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        guard let text = input["text"] as? String else {
            return ("missing text", true)
        }
        let reversedScalars = text.unicodeScalars.reversed()
        return (String(String.UnicodeScalarView(reversedScalars)), false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

