use std::env;
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::path::Path;

struct DbFile {
    file: File,
    page_size: u32,
    reserved_bytes: u8,
}

impl DbFile {
    fn new(path: &Path) -> Self {
        let mut file = File::open(path).expect("Could not open db.sqlite");
        let mut header = [0u8; 100];
        file.read_exact(&mut header).expect("Could not read header");
        let page_size = u32::from_be_bytes([
            header[16], header[17], header[18], header[19],
        ]);
        let reserved_bytes = header[20];
        DbFile {
            file,
            page_size,
            reserved_bytes,
        }
    }

    fn read_page(&mut self, page_num: u32) -> Vec<u8> {
        let offset = if page_num == 1 {
            0
        } else {
            (page_num as u64 - 1) * self.page_size as u64
        };
        self.file.seek(SeekFrom::Start(offset)).expect("Seek failed");
        let mut buf = vec![0u8; self.page_size as usize];
        self.file.read_exact(&mut buf).expect("Read page failed");
        buf
    }

    fn read_varint(&mut self, buf: &[u8], pos: &mut usize) -> u64 {
        let mut res = 0u64;
        let mut shift = 0;
        loop {
            let b = buf[*pos];
            *pos += 1;
            if b < 0x80 {
                res |= (b as u64) << shift;
                break;
            }
            res |= (0x7F as u64) << shift;
            shift += 7;
        }
        res
    }
}

struct TableSchema {
    name: String,
    root_page: u32,
    columns: Vec<Column>,
}

struct Column {
    name: String,
    is_rowid_alias: bool,
}

fn parse_create_table(sql: &str) -> (String, Vec<Column>) {
    let sql = sql.trim();
    let start_paren = sql.find('(').expect("No '(' in CREATE TABLE");
    let end_paren = sql.rfind(')').expect("No ')' in CREATE TABLE");
    let table_name_part = &sql[..start_paren];
    let defs_part = &sql[start_paren + 1..end_paren];

    let table_name = table_name_part
        .split_whitespace()
        .last()
        .expect("No table name")
        .trim_end_matches('(')
        .trim_matches('"')
        .to_string();

    let mut columns = Vec::new();
    let mut current_def = String::new();
    let mut depth = 0;
    for c in defs_part.chars() {
        if c == '(' {
            depth += 1;
        } else if c == ')' {
            depth -= 1;
        }
        if c == ',' && depth == 0 {
            columns.push(parse_column_def(&current_def));
            current_def.clear();
        } else {
            current_def.push(c);
        }
    }
    columns.push(parse_column_def(&current_def));

    (table_name, columns)
}

fn parse_column_def(def: &str) -> Column {
    let def = def.trim();
    let parts: Vec<&str> = def.split_whitespace().collect();
    let mut col_name = parts[0].trim_matches('"').to_string();
    let mut is_rowid_alias = false;

    let def_upper = def.to_uppercase();
    if def_upper.contains("INTEGER") && def_upper.contains("PRIMARY KEY") {
        let mut is_integer_only = true;
        let mut tokens = def.split_whitespace();
        tokens.next(); // skip name
        while let Some(token) = tokens.next() {
            if token.to_uppercase() == "INTEGER" {
                continue;
            } else if token.to_uppercase() == "PRIMARY" {
                continue;
            } else if token.to_uppercase() == "KEY" {
                continue;
            } else {
                is_integer_only = false;
                break;
            }
        }
        if is_integer_only {
            is_rowid_alias = true;
        }
    }
    // Special case: "INTEGER PRIMARY KEY" must be the type.
    // The spec says: "declared type is the single word INTEGER".
    // Let's refine:
    let mut is_alias = false;
    let mut tokens = def.split_whitespace();
    let _name = tokens.next();
    if let Some(t) = tokens.next() {
        if t.to_uppercase() == "INTEGER" {
            let mut has_pk = false;
            while let Some(t2) = tokens.next() {
                if t2.to_uppercase() == "PRIMARY" {
                    has_pk = true;
                }
            }
            if has_pk {
                is_alias = true;
            }
        }
    }

    Column {
        name: col_name,
        is_rowid_alias: is_alias,
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    !crc
}

fn format_value(val: &Value) -> String {
    match val {
        Value::Null => "NULL".to_string(),
        Value::Integer(i) => i.to_string(),
        Value::Real(f) => {
            let s = format!("{:.10f}", f);
            let mut res = s.trim_end_matches('0').to_string();
            if res.ends_with('.') {
                res.push('0');
            }
            res
        }
        Value::Text(t) => {
            if t.len() > 100 {
                format!("<TEXT len={} crc32={:08x}>", t.len(), crc32(t))
            } else {
                let mut s = String::from("\"");
                for &b in t {
                    match b {
                        b'\\' => s.push_str("\\\\"),
                        b'\"' => s.push_str("\\\""),
                        b'\n' => s.push_str("\\n"),
                        b'\r' => s.push_str("\\r"),
                        b'\t' => s.push_str("\\t"),
                        b if b < 0x20 || b == 0x7F => {
                            s.push_str(&format!("\\x{:02X}", b));
                        }
                        b => s.push(b as char),
                    }
                }
                s.push('\"');
                s
            }
        }
        Value::Blob(b) => {
            if b.len() > 100 {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            } else {
                let mut s = String::from("X'");
                for &b in b {
                    s.push_str(&format!("{:02X}", b));
                }
                s.push('\'');
                s
            }
        }
    }
}

enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_payload(db: &mut DbFile, payload_start: usize, payload_size: usize, page_data: &[u8]) -> Vec<Value> {
    let mut pos = payload_start;
    let mut values = Vec::new();
    let mut serial_types = Vec::new();

    // Read serial types
    loop {
        let st = db.read_varint(page_data, &mut pos);
        serial_types.push(st);
        if st == 0 { break; }
    }

    let mut current_payload_pos = pos;
    let mut total_payload_read = pos - payload_start;
    let mut overflow_page = 0u32;

    // Handle overflow
    let mut full_payload = Vec::new();
    let page_limit = db.page_size as usize - db.reserved_bytes as usize - 8; // Rough limit
    // The actual overflow is handled by the B-tree logic, but the record payload 
    // might be split across overflow pages.

    // For this specific task, the overflow pages are handled by reading the 
    // overflow page pointer at the end of the page.
    // Let's implement the payload reading more carefully.

    // The payload is the data starting from 'pos'.
    // If the payload is larger than the available space on the page, it overflows.
    // The overflow page pointer is the last 4 bytes of the page.

    let mut payload_data = Vec::new();
    let mut bytes_to_read = payload_size - (pos - payload_start);

    // Read from the current page
    let available = page_data.len() - current_payload_pos;
    let read_now = available.min(bytes_to_read);
    if read_now > 0 {
        payload_data.extend_from_slice(&page_data[current_payload_pos..current_payload_pos + read_now]);
    }
    bytes_to_read -= read_now;

    // Read from overflow pages
    if bytes_to_read > 0 {
        let mut next_page = u32::from_le_bytes([
            page_data[page_data.len()-4], page_data[page_data.len()-3],
            page_data[page_data.len()-2], page_data[page_data.len()-1]
        ]);
        while next_page != 0 {
            let page = db.read_page(next_page);
            let next_page_ptr = u32::from_le_bytes([page[0], page[1], page[2], page[3]]);
            let page_data_len = db.page_size as usize - db.reserved_bytes as usize;
            let read_from_page = page_data_len.min(bytes_to_read);
            payload_data.extend_from_slice(&page[4..4 + read_from_page]);
            bytes_to_read -= read_from_page;
            next_page = next_page_ptr;
        }
    }

    let mut p_pos = 0;
    for &st in &serial_types[..serial_types.len()-1] {
        match st {
            0 => values.push(Value::Null),
            1 => {
                let b = payload_data[p_pos];
                values.push(Value::Integer(b as i8 as i64));
                p_pos += 1;
            }
            2 => {
                let b = [payload_data[p_pos], payload_data[p_pos+1]];
                values.push(Value::Integer(i16::from_le_bytes(b) as i64));
                p_pos += 2;
            }
            3 => {
                let b = [payload_data[p_pos], payload_data[p_pos+1], payload_data[p_pos+2]];
                let val = (b[0] as i64) | ((b[1] as i64) << 8) | ((b[2] as i8) as i64 << 16);
                values.push(Value::Integer(val));
                p_pos += 3;
            }
            4 => {
                let b = [payload_data[p_pos], payload_data[p_pos+1], payload_data[p_pos+2], payload_data[p_pos+3]];
                values.push(Value::Integer(i32::from_le_bytes(b) as i64));
                p_pos += 4;
            }
            6 => {
                let b = [
                    payload_data[p_pos], payload_data[p_pos+1], payload_data[p_pos+2], payload_data[p_pos+3],
                    payload_data[p_pos+4], payload_data[p_pos+5], payload_data[p_pos+6], payload_data[p_pos+7]
                ];
                values.push(Value::Integer(i64::from_le_bytes(b)));
                p_pos += 8;
            }
            7 => {
                let b = [
                    payload_data[p_pos], payload_data[p_pos+1], payload_data[p_pos+2], payload_data[p_pos+3],
                    payload_data[p_pos+4], payload_data[p_pos+5], payload_data[p_pos+6], payload_data[p_pos+7]
                ];
                values.push(Value::Real(f64::from_le_bytes(b)));
                p_pos += 8;
            }
            8 => {
                let mut temp_pos = p_pos;
                let mut len = 0;
                // We need a way to read varint from payload_data
                let mut varint_buf = Vec::new();
                loop {
                    let b = payload_data[temp_pos];
                    varint_buf.push(b);
                    temp_pos += 1;
                    if b < 0x80 { break; }
                }
                let mut res = 0u64;
                let mut shift = 0;
                for &b in &varint_buf {
                    res |= (b & 0x7F) as u64 << shift;
                    shift += 7;
                }
                len = res as usize;
                values.push(Value::Text(payload_data[temp_pos..temp_pos + len].to_vec()));
                p_pos = temp_pos + len;
            }
            9 => {
                let mut temp_pos = p_pos;
                let mut varint_buf = Vec::new();
                loop {
                    let b = payload_data[temp_pos];
                    varint_buf.push(b);
                    temp_pos += 1;
                    if b < 0x80 { break; }
                }
                let mut res = 0u64;
                let mut shift = 0;
                for &b in &varint_buf {
                    res |= (b & 0x7F) as u64 << shift;
                    shift += 7;
                }
                let len = res as usize;
                values.push(Value::Blob(payload_data[temp_pos..temp_pos + len].to_vec()));
                p_pos = temp_pos + len;
            }
            _ => {}
        }
    }
    values
}

fn walk_btree(db: &mut DbFile, page_num: u32, rows: &mut Vec<(i64, Vec<Value>)>) {
    let page = db.read_page(page_num);
    let page_type = if page_num == 1 { page[100] } else { page[0] };
    let num_cells = u16::from_le_bytes([page[if page_num == 1 { 101 } else { 1 }, page[if page_num == 1 { 102 } else { 2 }]]);
    // Wait, num_cells is 2 bytes.
    let num_cells = u16::from_le_bytes([
        page[if page_num == 1 { 101 } else { 1 }],
        page[if page_num == 1 { 102 } else { 2 }],
    ]);

    if page_type == 0x05 { // Interior
        let mut cell_ptr_pos = if page_num == 1 { 103 } else { 3 };
        for _ in 0..num_cells {
            let ptr = u16::from_le_bytes([page[cell_ptr_pos], page[cell_ptr_pos + 1]]);
            cell_ptr_pos += 2;
            let mut pos = ptr as usize;
            let payload_size = db.read_varint(&page, &mut pos);
            let rowid = db.read_varint(&page, &mut pos);
            // In interior pages, the first value of the payload is the child page
            let mut child_page_bytes = [0u8; 4];
            let mut c_pos = 0;
            // The child page is stored as a varint in the payload
            let mut res = 0u64;
            let mut shift = 0;
            loop {
                let b = page[pos + c_pos];
                c_pos += 1;
                res |= (b & 0x7F) as u64 << shift;
                shift += 7;
                if b < 0x80 { break; }
            }
            walk_btree(db, res as u32, rows);
        }
    } else if page_type == 0x0D { // Leaf
        let mut cell_ptr_pos = if page_num == 1 { 103 } else { 3 };
        for _ in 0..num_cells {
            let ptr = u16::from_le_bytes([page[cell_ptr_pos], page[cell_ptr_pos + 1]]);
            cell_ptr_pos += 2;
            let mut pos = ptr as usize;
            let payload_size = db.read_varint(&page, &mut pos);
            let rowid = db.read_varint(&page, &mut pos);
            let values = read_payload(db, pos, payload_size as usize, &page);
            rows.push((rowid as i64, values));
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let db_path = Path::new(dir).join("db.sqlite");
    let mut db = DbFile::new(&db_path);

    // Read sqlite_schema
    let mut schema_rows = Vec::new();
    walk_btree(&mut db, 1, &mut schema_rows);

    let mut tables = Vec::new();
    for (rowid, values) in schema_rows {
        if values.len() >= 5 {
            let type_val = match &values[0] {
                Value::Text(t) => String::from_utf8_lossy(t).to_string(),
                _ => "".to_string(),
            };
            if type_val == "table" {
                let name = match &values[1] {
                    Value::Text(t) => String::from_utf8_lossy(t).to_string(),
                    _ => "".to_string(),
                };
                if !name.starts_with("sqlite_") {
                    let root_page = match &values[3] {
                        Value::Integer(i) => *i as u32,
                        _ => 1,
                    };
                    let sql = match &values[4] {
                        Value::Text(t) => String::from_utf8_lossy(t).to_string(),
                        _ => "".to_string(),
                    };
                    let (t_name, cols) = parse_create_table(&sql);
                    tables.push(TableSchema {
                        name: t_name,
                        root_page,
                        columns: cols,
                    });
                }
            }
        }
    }
    tables.sort_by(|a, b| a.name.cmp(&b.name));

    for (i, table) in tables.iter().enumerate() {
        if i > 0 { println!(); }
        let mut rows = Vec::new();
        walk_btree(&mut db, table.root_page, &mut rows);
        rows.sort_by_key(|r| r.0);

        println!("TABLE {} rows={}", table.name, rows.len());
        let col_names: Vec<String> = table.columns.iter().map(|c| c.name.clone()).collect();
        println!("COLUMNS {}", col_names.join(", "));

        for (rowid, values) in rows {
            let mut row_vals = Vec::new();
            for (col_idx, col) in table.columns.iter().enumerate() {
                if col.is_rowid_alias {
                    row_vals.push(format!("{}", rowid));
                } else {
                    if col_idx < values.len() {
                        row_vals.push(format!("{}", format_value(&values[col_idx])));
                    } else {
                        row_vals.push("NULL".to_string());
                    }
                }
            }
            println!("{}: {}", rowid, row_vals.join(", "));
        }
    }
}

use std::env;
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::path::Path;

struct DbFile {
    file: File,
    page_size: u32,
    reserved_bytes: u8,
}

impl DbFile {
    fn new(path: &Path) -> Self {
        let mut file = File::open(path).expect("Could not open db.sqlite");
        let mut header = [0u8; 100];
        file.read_exact(&mut header).expect("Could not read header");
        let page_size = u32::from_be_bytes([
            header[16], header[17], header[18], header[19],
        ]);
        let reserved_bytes = header[20];
        DbFile {
            file,
            page_size,
            reserved_bytes,
        }
    }

    fn read_page(&mut self, page_num: u32) -> Vec<u8> {
        let offset = if page_num == 1 {
            0
        } else {
            (page_num as u64 - 1) * self.page_size as u64
        };
        self.file.seek(SeekFrom::Start(offset)).expect("Seek failed");
        let mut buf = vec![0u8; self.page_size as usize];
        self.file.read_exact(&mut buf).expect("Read page failed");
        buf
    }

    fn read_varint(buf: &[u8], pos: &mut usize) -> u64 {
        let mut res = 0u64;
        let mut shift = 0;
        loop {
            let b = buf[*pos];
            *pos += 1;
            if b < 0x80 {
                res |= (b as u64) << shift;
                break;
            }
            res |= (0x7F as u64) << shift;
            shift += 7;
        }
        res
    }
}

struct TableSchema {
    name: String,
    root_page: u32,
    columns: Vec<Column>,
}

struct Column {
    name: String,
    is_rowid_alias: bool,
}

fn parse_create_table(sql: &str) -> (String, Vec<Column>) {
    let sql = sql.trim();
    let start_paren = sql.find('(').expect("No '(' in CREATE TABLE");
    let end_paren = sql.rfind(')').expect("No ')' in CREATE TABLE");
    let table_name_part = &sql[..start_paren];
    let defs_part = &sql[start_paren + 1..end_paren];

    let table_name = table_name_part
        .split_whitespace()
        .last()
        .expect("No table name")
        .trim_matches('"')
        .to_string();

    let mut columns = Vec::new();
    let mut current_def = String::new();
    let mut depth = 0;
    for c in defs_part.chars() {
        if c == '(' {
            depth += 1;
        } else if c == ')' {
            depth -= 1;
        }
        if c == ',' && depth == 0 {
            columns.push(parse_column_def(&current_def));
            current_def.clear();
        } else {
            current_def.push(c);
        }
    }
    columns.push(parse_column_def(&current_def));

    (table_name, columns)
}

fn parse_column_def(def: &str) -> Column {
    let def = def.trim();
    let mut tokens = def.split_whitespace();
    let first_token = tokens.next().unwrap_or("");
    let col_name = first_token.trim_matches('"').to_string();

    let mut is_alias = false;
    if let Some(type_token) = tokens.next() {
        if type_token.to_uppercase() == "INTEGER" {
            let remaining = tokens.collect::<Vec<_>>().join(" ").to_uppercase();
            if remaining.contains("PRIMARY KEY") {
                is_alias = true;
            }
        }
    }
    Column {
        name: col_name,
        is_rowid_alias: is_alias,
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    !crc
}

fn format_real(f: f64) -> String {
    let s = format!("{:.8f}", f);
    let mut res = s;
    if let Some(dot_pos) = res.find('.') {
        let mut last_digit_pos = res.len() - 1;
        while last_digit_pos > dot_pos && res.as_bytes()[last_digit_pos] == b'0' {
            last_digit_pos -= 1;
        }
        res.truncate(last_digit_pos + 1);
    }
    res
}

fn format_value(val: &Value) -> String {
    match val {
        Value::Null => "NULL".to_string(),
        Value::Integer(i) => i.to_string(),
        Value::Real(f) => format_real(*f),
        Value::Text(t) => {
            if t.len() > 100 {
                format!("<TEXT len={} crc32={:08x}>", t.len(), crc32(t))
            } else {
                let mut s = String::from("\"");
                for &b in t {
                    match b {
                        b'\\' => s.push_str("\\\\"),
                        b'\"' => s.push_str("\\\""),
                        b'\n' => s.push_str("\\n"),
                        b'\r' => s.push_str("\\r"),
                        b'\t' => s.push_str("\\t"),
                        b if b < 0x20 || b == 0x7F => {
                            s.push_str(&format!("\\x{:02X}", b));
                        }
                        b => s.push(b as char),
                    }
                }
                s.push('\"');
                s
            }
        }
        Value::Blob(b) => {
            if b.len() > 100 {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            } else {
                let mut s = String::from("X'");
                for &b in b {
                    s.push_str(&format!("{:02X}", b));
                }
                s.push('\'');
                s
            }
        }
    }
}

enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_payload(db: &mut DbFile, payload_start: usize, payload_size: usize, page_data: &[u8]) -> Vec<Value> {
    let mut pos = payload_start;
    let mut serial_types = Vec::new();
    loop {
        let st = DbFile::read_varint(page_data, &mut pos);
        serial_types.push(st);
        if st == 0 { break; }
    }

    let mut payload_data = Vec::new();
    let mut remaining_size = payload_size;
    let end_of_page = db.page_size as usize - db.reserved_bytes as usize;
    let space_on_page = end_of_page - pos;

    if space_on_page > 4 && payload_size > (space_on_page - 4) {
        payload_data.extend_from_slice(&page_data[pos..end_of_page - 4]);
        let mut next_page = u32::from_le_bytes(page_data[end_of_page - 4..end_of_page].try_into().unwrap());
        remaining_size -= (end_of_page - 4 - pos);
        while remaining_size > 0 && next_page != 0 {
            let overflow_page = db.read_page(next_page);
            let next_page_ptr = u32::from_le_bytes(overflow_page[0..4].try_into().unwrap());
            let page_data_len = db.page_size as usize - db.reserved_bytes as usize;
            let read_len = remaining_size.min(page_data_len - 4);
            payload_data.extend_from_slice(&overflow_page[4..4 + read_len]);
            remaining_size -= read_len;
            next_page = next_page_ptr;
        }
    } else {
        payload_data.extend_from_slice(&page_data[pos..pos + payload_size]);
    }

    let mut p_pos = 0;
    let mut values = Vec::new();
    for &st in &serial_types[..serial_types.len() - 1] {
        match st {
            0 => values.push(Value::Null),
            1 => {
                values.push(Value::Integer(payload_data[p_pos] as i8 as i64));
                p_pos += 1;
            }
            2 => {
                let val = i16::from_le_bytes([payload_data[p_pos], payload_data[p_pos + 1]]);
                values.push(Value::Integer(val as i64));
                p_pos += 2;
            }
            3 => {
                let val = (payload_data[p_pos] as i64) | ((payload_data[p_pos + 1] as i64) << 8) | ((payload_data[p_pos + 2] as i8) as i64 << 16);
                values.push(Value::Integer(val));
                p_pos += 3;
            }
            4 => {
                let val = i32::from_le_bytes([payload_data[p_pos], payload_data[p_pos + 1], payload_data[p_pos + 2], payload_data[p_pos + 3]]);
                values.push(Value::Integer(val as i64));
                p_pos += 4;
            }
            6 => {
                let val = i64::from_le_bytes([
                    payload_data[p_pos], payload_data[p_pos + 1], payload_data[p_pos + 2], payload_data[p_pos + 3],
                    payload_data[p_pos + 4], payload_data[p_pos + 5], payload_data[p_pos + 6], payload_data[p_pos + 7],
                ]);
                values.push(Value::Integer(val));
                p_pos += 8;
            }
            7 => {
                let val = f64::from_le_bytes([
                    payload_data[p_pos], payload_data[p_pos + 1], payload_data[p_pos + 2], payload_data[p_pos + 3],
                    payload_data[p_pos + 4], payload_data[p_pos + 5], payload_data[p_pos + 6], payload_data[p_pos + 7],
                ]);
                values.push(Value::Real(val));
                p_pos += 8;
            }
            8 => {
                let mut vpos = p_pos;
                let mut len = 0u64;
                let mut shift = 0;
                loop {
                    let b = payload_data[vpos];
                    vpos += 1;
                    len |= (b & 0x7F) as u64 << shift;
                    shift += 7;
                    if b < 0x80 { break; }
                }
                values.push(Value::Text(payload_data[vpos..vpos + len as usize].to_vec()));
                p_pos = vpos + len as usize;
            }
            9 => {
                let mut vpos = p_pos;
                let mut len = 0u64;
                let mut shift = 0;
                loop {
                    let b = payload_data[vpos];
                    vpos += 1;
                    len |= (b & 0x7F) as u64 << shift;
                    shift += 7;
                    if b < 0x80 { break; }
                }
                values.push(Value::Blob(payload_data[vpos..vpos + len as usize].to_vec()));
                p_pos = vpos + len as usize;
            }
            _ => {}
        }
    }
    values
}

fn walk_btree(db: &mut DbFile, page_num: u32, rows: &mut Vec<(i64, Vec<Value>)>) {
    let page = db.read_page(page_num);
    let header_offset = if page_num == 1 { 100 } else { 0 };
    let page_type = page[header_offset];
    let num_cells = u16::from_le_bytes([page[header_offset + 3], page[header_offset + 4]]);

    if page_type == 0x05 {
        let mut cell_ptr_pos = header_offset + 8;
        for _ in 0..num_cells {
            let ptr = u16::from_le_bytes([page[cell_ptr_pos], page[cell_ptr_pos + 1]]);
            cell_ptr_pos += 2;
            let mut pos = ptr as usize;
            let payload_size = DbFile::read_varint(&page, &mut pos) as usize;
            let _rowid = DbFile::read_varint(&page, &mut pos);
            let mut child_pos = pos;
            let mut child_page = 0u64;
            let mut shift = 0;
            loop {
                let b = page[child_pos];
                child_pos += 1;
                child_page |= (b & 0x7F) as u64 << shift;
                shift += 7;
                if b < 0x80 { break; }
            }
            walk_btree(db, child_page as u32, rows);
        }
    } else if page_type == 0x0D {
        let mut cell_ptr_pos = header_offset + 8;
        for _ in 0..num_cells {
            let ptr = u16::from_le_bytes([page[cell_ptr_pos], page[cell_ptr_pos + 1]]);
            cell_ptr_pos += 2;
            let mut pos = ptr as usize;
            let payload_size = DbFile::read_varint(&page, &mut pos) as usize;
            let rowid = DbFile::read_varint(&page, &mut pos);
            let values = read_payload(db, pos, payload_size, &page);
            rows.push((rowid as i64, values));
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let db_path = Path::new(dir).join("db.sqlite");
    let mut db = DbFile::new(&db_path);

    let mut schema_rows = Vec::new();
    walk_btree(&mut db, 1, &mut schema_rows);

    let mut tables = Vec::new();
    for (_rowid, values) in schema_rows {
