            if (!*ptr) break;
            char word[64] = {0}; int wi = 0;
            while (*ptr && !isspace(*ptr) && *ptr != ',') word[wi++] = *ptr++;
            word[wi] = '\0';
            if (strcasecmp(word, "INTEGER") == 0) is_int = true;
            if (strcasecmp(word, "PRIMARY") == 0) {
                while (*ptr && isspace(*ptr)) ptr++;
                char word2[64] = {0}; int wi2 = 0;
                while (*ptr && !isspace(*ptr) && *ptr != ',') word2[wi2++] = *ptr++;
                word2[wi2] = '\0';
                if (strcasecmp(word2, "KEY") == 0) is_pk = true;
            }
        }
        t->is_rowid[t->col_count] = (is_int && is_pk);
        t->col_count++;
        free(def);
    }
}

void process_record(uint8_t *payload, int size, int64_t rowid, Table *t) {
    int n;
    uint64_t header_size = read_varint(payload, &n);
    uint8_t *type_ptr = payload;
    int type_count = 0;
    int type_off = 0;
    while (type_off < (int)header_size) {
        read_varint(type_ptr, &n);
        type_ptr += n;
        type_off += n;
        type_count++;
    }

    uint8_t *val_ptr = type_ptr;
    printf("%lld: ", (long long)rowid);
    for (int i = 0; i < t->col_count; i++) {
        if (i > 0) printf(", ");
        if (t->is_rowid[i]) {
            printf("%lld", (long long)rowid);
            continue;
        }
        if (i >= type_count) {
            printf("NULL");
            continue;
        }
        int tn;
        uint64_t type = read_varint(val_ptr, &tn);
        val_ptr += tn;
        if (type == 0) printf("NULL");
        else if (type >= 1 && type <= 6) {
            int sz = (type == 1) ? 1 : (type == 2) ? 2 : (type == 3) ? 3 : (type == 4) ? 4 : (type == 5) ? 6 : 8;
            int64_t val = 0;
            for (int j = 0; j < sz; j++) val |= (uint64_t)val_ptr[j] << (8 * j);
            if (sz == 1) val = (int8_t)val_ptr[0];
            else if (sz == 2) val = (int16_t)((val_ptr[0]) | (val_ptr[1] << 8));
            else if (sz == 3) {
                int32_t tmp = (val_ptr[0]) | (val_ptr[1] << 8) | (val_ptr[2] << 16);
                if (tmp & 0x800000) tmp |= 0xFF000000;
                val = tmp;
            } else if (sz == 4) val = (int32_t)((val_ptr[0]) | (val_ptr[1] << 8) | (val_ptr[2] << 16) | (val_ptr[3] << 24));
            else if (sz == 6) {
                int64_t tmp = (val_ptr[0]) | (val_ptr[1] << 8) | (val_ptr[2] << 16) | (val_ptr[3] << 24) | (val_ptr[4] << 32) | (val_ptr[5] << 40);
                if (tmp & 0x800000000000) tmp |= 0xFFFF000000000000ULL;
                val = tmp;
            } else val = (int64_t)((val_ptr[0]) | (val_ptr[1] << 8) | (val_ptr[2] << 16) | (val_ptr[3] << 24) | (val_ptr[4] << 32) | (val_ptr[5] << 40) | (val_ptr[6] << 48) | (val_ptr[7] << 56));
            printf("%lld", (long long)val);
            val_ptr += sz;
        } else if (type == 7) {
            double val;
            memcpy(&val, val_ptr, 8);
            print_real(val);
            val_ptr += 8;
        } else if (type >= 12 && type <= 16) {
            int len = type - 12;
            print_text(val_ptr, len);
            val_ptr += len;
        } else if (type >= 17) {
            int len = type - 17;
            print_blob(val_ptr, len);
            val_ptr += len;
        }
    }
    printf("\n");
}

