void traverse_btree(int page_num, Table *t, int *row_count) {
    uint8_t *page = read_page(page_num);
    uint8_t type = page[0];
    int cell_count = (page[3] << 8) | page[4];
    int content_start = (page[5] << 8) | page[6];

    if (type == 0x0D) { // Leaf
        int offset = content_start;
        for (int i = 0; i < cell_count; i++) {
            int n;
            uint64_t s = read_varint(page + offset, &n);
            int s_len = n;
            offset += n;
            int64_t rid = read_varint_signed(page + offset, &n);
            int r_len = n;
            offset += n;
            uint8_t *payload = page + offset;

            // Handle overflow
            uint8_t *full_payload = malloc(s);
            int read = 0;
            uint8_t *curr_page = page;
            int curr_off = offset;
            while (read < s) {
                int chunk = (s - read > page_size - 4) ? page_size - 4 : s - read;
                memcpy(full_payload + read, curr_page + curr_off, chunk);
                read += chunk;
                if (read < s) {
                    uint32_t next_page = 0;
                    memcpy(&next_page, curr_page + curr_off + chunk - 4, 4);
                    curr_page = read_page(next_page);
                    curr_off = 0;
                }
            }
            process_record(full_payload, s, rid, t);
            (*row_count)++;
            offset += s;
            free(full_payload);
        }
    } else { // Interior
        int offset = content_start;
        for (int i = 0; i < cell_count; i++) {
            int n;
            uint64_t s = read_varint(page + offset, &n);
            offset += n;
            uint8_t *payload = page + offset;
            uint32_t child_page = 0;
            memcpy(&child_page, payload, 4);
            traverse_btree(child_page, t, row_count);
            offset += s;
        }
    }
    free(page);
}

