import Foundation

// --- CSV Parser ---
func parseCSV(content: String) -> [[String]] {
    var rows = [[String]]()
    var currentRow = [String]()
    var currentField = ""
    var inQuotes = false
    let chars = Array(content)
    var i = 0
    while i < chars.count {
        let char = chars[i]
        if inQuotes {
            if char == "\"" {
                if i + 1 < chars.count && chars[i+1] == "\"" {
                    currentField.append("\"")
                    i += 1
                } else {
                    inQuotes = false
                }
            } else {
                currentField.append(char)
            }
        } else {
            if char == "\"" {
                inQuotes = true
            } else if char == "," {
                currentRow.append(currentField)
                currentField = ""
            } else if char == "\r" {
                if i + 1 < chars.count && chars[i+1] == "\n" {
                    i += 1
                }
                currentRow.append(currentField)
                rows.append(currentRow)
                currentRow = []
                currentField = ""
            } else if char == "\n" {
                currentRow.append(currentField)
                rows.append(currentRow)
                currentRow = []
                currentField = ""
            } else {
                currentField.append(char)
            }
        }
        i += 1
    }
    if i > 0 {
        let lastChar = chars[i-1]
        if lastChar != "\n" && lastChar != "\r" {
            currentRow.append(currentField)
            rows.append(currentRow)
        } else if lastChar == "," {
            currentRow.append(currentField)
            rows.append(currentRow)
        }
    }
    return rows
}

// --- JSON Escaping ---
func escapeJSONString(_ s: String) -> String {
    var result = ""
    for char in s {
        switch char {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\u{0008}": result += "\\b"
        case "\u{000C}": result += "\\f"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        default:
            if let ascii = char.asciiValue, ascii < 32 {
                result += String(format: "\\u%04x", ascii)
            } else {
                result.append(char)
            }
        }
    }
    return result
}

// --- Tool Result Helpers ---
func makeInventoryJSON(sku: String, name: String, price: Int, currency: String, stock: Int) -> String {
    return "{\"sku\":\"\(escapeJSONString(sku))\",\"name\":\"\(escapeJSONString(name))\",\"price_cents\":\(price),\"currency\":\"\(escapeJSONString(currency))\",\"stock\":\(stock)}"
}

func makeConversionJSON(amount: Int, currency: String) -> String {
    return "{\"amount_cents\":\(amount),\"currency\":\"\(escapeJSONString(currency))\"}"
}

func makeErrorJSON(message: String) -> String {
    return "{\"error\":\"\(escapeJSONString(message))\"}"
}

// --- Main Program ---
@main
struct Main {
    static func main() async {
        let args = CommandLine.arguments
        guard args.count >= 3 else { return }
        let dataDir = args[1]
        let baseUrl = args[2]

        // Load config files
        guard let taskData = try? Data(contentsOf: URL(fileURLWithPath: "\(dataDir)/task.json")),
              let taskJson = try? JSONSerialization.jsonObject(with: taskData) as? [String: Any],
              let apiKey = taskJson["api_key"] as? String,
              let model = taskJson["model"] as? String,
              let systemPrompt = taskJson["system"] as? String,
              let userPrompt = taskJson["user"] as? String,
              let tools = taskJson["tools"] as? [[String: Any]] else { return }

        guard let ratesData = try? Data(contentsOf: URL(fileURLWithPath: "\(dataDir)/rates.json")),
              let ratesJson = try? JSONSerialization.jsonObject(with: ratesData) as? [String: Any],
              let rates = ratesJson["rates"] as? [String: Int] else { return }

        var csvContent = try! String(contentsOfFile: "\(dataDir)/inventory.csv", encoding: .utf8)
        if csvContent.hasPrefix("\u{FEFF}") {
            csvContent.removeFirst()
        }
        let csvRows = parseCSV(content: csvContent)
        let inventory = csvRows.dropFirst().reduce(into: [String: [String]]()) { dict, row in
            if row.count >= 5 { dict[row[0]] = row }
        }

        var messages: [[String: Any]] = [
            ["role": "system", "content": systemPrompt],
            ["role": "user", "content": userPrompt]
        ]

        var totalPromptTokens = 0
        var totalCompletionTokens = 0
        var totalTokens = 0
        var requestCount = 0

        while true {
            let requestBody: [String: Any] = [
                "model": model,
                "messages": messages,
                "tools": tools,
                "tool_choice": "auto"
            ]

            guard let jsonData = try? JSONSerialization.data(withJSONObject: requestBody, options: []),
                  let url = URL(string: "\(baseUrl)/chat/completions") else { return }

            var request = URLRequest(url: url)
            request.httpMethod = "POST"
            request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.httpBody = jsonData

            do {
                let (data, response) = try await URLSession.shared.data(for: request)
                guard let httpResponse = response as? HTTPURLResponse else { return }
                requestCount += 1

                if httpResponse.statusCode != 200 {
                    if let errJson = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                       let errObj = errJson["error"] as? [String: Any],
                       let errMsg = errObj["message"] as? String {
                        print("ERROR \(httpResponse.statusCode) \(errMsg)")
                    } else {
                        print("ERROR \(httpResponse.statusCode) unknown error")
                    }
                    return
                }

                guard let responseJson = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                      let choices = responseJson["choices"] as? [[String: Any]],
                      let choice = choices.first,
                      let message = choice["message"] as? [String: Any],
                      let finishReason = choice["finish_reason"] as? String else { return }

                if let usage = responseJson["usage"] as? [String: Int] {
                    totalPromptTokens += usage["prompt_tokens"] ?? 0
                    totalCompletionTokens += usage["completion_tokens"] ?? 0
                    totalTokens += usage["total_tokens"] ?? 0
                }

                if finishReason == "tool_calls" {
                    if let content = message["content"] as? String {
                        print("SAY \(content)")
                    }

                    let toolCalls = message["tool_calls"] as? [[String: Any]] ?? []
                    for tc in toolCalls {
                        let id = tc["id"] as! String
                        let function = tc["function"] as! [String: Any]
                        let name = function["name"] as! String
                        print("CALL \(id) \(name)")
                    }

                    // Append assistant message as received
                    messages.append(message)

                    for tc in toolCalls {
                        let id = tc["id"] as! String
                        let function = tc["function"] as! [String: Any]
                        let name = function["name"] as! String
                        let argsString = function["arguments"] as! String

                        var resultString = ""
                        if let argsJson = try? JSONSerialization.jsonObject(with: argsString.data(using: .utf8)!) as? [String: Any] {
                            if name == "inventory_lookup" {
                                let sku = argsJson["sku"] as? String ?? ""
                                if let row = inventory[sku] {
                                    resultString = makeInventoryJSON(sku: row[0], name: row[1], price: Int(row[2]) ?? 0, currency: row[3], stock: Int(row[4]) ?? 0)
                                } else {
                                    resultString = makeErrorJSON(message: "unknown sku: \(sku)")
                                }
                            } else if name == "convert_currency" {
                                let amountCents = argsJson["amount_cents"] as? Int ?? 0
                                let from = argsJson["from"] as? String ?? ""
                                let to = argsJson["to"] as? String ?? ""
                                if let rateFrom = rates[from], let rateTo = rates[to] {
                                    let converted = (2 * amountCents * rateTo + rateFrom) / (2 * rateFrom)
                                    resultString = makeConversionJSON(amount: converted, currency: to)
                                } else {
                                    resultString = makeErrorJSON(message: "unknown currency")
                                }
                            } else {
                                resultString = makeErrorJSON(message: "unknown tool: \(name)")
                            }
                        } else {
                            resultString = makeErrorJSON(message: "invalid arguments")
                        }
                        print("RESULT \(id) \(resultString)")
                        messages.append(["role": "tool", "tool_call_id": id, "content": resultString])
                    }
                } else if finishReason == "stop" {
                    let content = message["content"] as? String ?? ""
                    print("FINAL \(content)")
                    print("USAGE prompt=\(totalPromptTokens) completion=\(totalCompletionTokens) total=\(totalTokens) requests=\(requestCount)")
                    return
                }
            } catch {
                return
            }
        }
    }
}

