import Foundation

// --- CSV Parser ---
func parseCSV(content: String) -> [[String]] {
    var rows = [[String]]()
    var currentRow = [String]()
    var currentField = ""
    var inQuotes = false
    let chars = Array(content)
    var i = 0
    while i < chars.count {
        let char = chars[i]
        if inQuotes {
            if char == "\"" {
                if i + 1 < chars.count && chars[i+1] == "\"" {
                    currentField.append("\"")
                    i += 1
                } else {
                    inQuotes = false
                }
            } else {
                currentField.append(char)
            }
        } else {
            if char == "\"" {
                inQuotes = true
            } else if char == "," {
                currentRow.append(currentField)
                currentField = ""
            } else if char == "\n" {
                currentRow.append(currentField)
                rows.append(currentRow)
                currentRow = []
                currentField = ""
            } else if char == "\r" {
                if i + 1 < chars.count && chars[i+1] == "\n" {
                    i += 1
                }
                currentRow.append(currentField)
                rows.append(currentRow)
                currentRow = []
                currentField = ""
            } else {
                currentField.append(char)
            }
        }
        i += 1
    }
    if i > 0 {
        if chars[i-1] != "\n" && chars[i-1] != "\r" {
            currentRow.append(currentField)
            rows.append(currentRow)
        } else if chars[i-1] == "," {
            currentRow.append(currentField)
            rows.append(currentRow)
        }
    }
    return rows
}

// --- JSON Escaping ---
func customEscape(_ s: String) -> String {
    var result = ""
    for char in s {
        switch char {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\u{0008}": result += "\\b"
        case "\u{000C}": result += "\\f"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        default:
            if let ascii = char.asciiValue, ascii < 32 {
                result += String(format: "\\u%04x", ascii)
            } else {
                result.append(char)
            }
        }
    }
    return result
}

