import * as fs from 'fs';
import * as path from 'path';

/**
 * DTMF Decoder for WAV files.
 * Processes files in a directory, decoding telephone keypad tones.
 */

function decodeDTMF() {
    const dir = process.argv[2];
    if (!dir) return;

    const files = fs.readdirSync(dir)
        .filter(f => f.endsWith('.wav'))
        .sort();

    for (let i = 0; i < files.length; i++) {
        const fileName = files[i];
        const filePath = path.join(dir, fileName);
        const buffer = fs.readFileSync(filePath);

        try {
            processWavFile(fileName, buffer);
        } catch (e) {
            // Error handling is handled within processWavFile for "unsupported"
        }

        if (i < files.length - 1) {
            process.stdout.write('\n');
        }
    }
}

function processWavFile(name: string, buffer: Buffer) {
    // RIFF Header
    if (buffer.length < 12 || buffer.slice(0, 4).toString() !== 'RIFF') {
        console.log(`${name}: unsupported`);
        return;
    }

    // Skip RIFF size (4 bytes) and "WAVE" (4 bytes)
    let offset = 12;
    let fmtChunk: { size: number, bodyOffset: number } | null = null;
    let dataChunk: { size: number, bodyOffset: number } | null = null;

    while (offset < buffer.length) {
        if (offset + 8 > buffer.length) break;
        const chunkId = buffer.slice(offset, offset + 4).toString();
        const chunkSize = buffer.readUInt32LE(offset + 4);
        const bodyOffset = offset + 8;

        if (chunkId === 'fmt ') {
            fmtChunk = { size: chunkSize, bodyOffset };
        } else if (chunkId === 'data') {
            dataChunk = { size: chunkSize, bodyOffset };
        }

        offset += 8 + chunkSize + (chunkSize % 2 === 1 ? 1 : 0);
    }

    if (!fmtChunk || !dataChunk) {
        console.log(`${name}: unsupported`);
        return;
    }

    // Parse fmt chunk
    const fmtBody = buffer.slice(fmtChunk.bodyOffset);
    const formatTag = fmtBody.readUInt16LE(0);
    const channels = fmtBody.readUInt16LE(2);
    const sampleRate = fmtBody.readUInt32LE(4);
    const bitsPerSample = fmtBody.readUInt16LE(14);

    let effectiveFormat = formatTag;
    if (formatTag === 0xFFFE) {
        if (fmtChunk.size < 26) {
            console.log(`${name}: unsupported`);
            return;
        }
        effectiveFormat = fmtBody.readUInt16LE(24);
    }

    if (effectiveFormat !== 1 || bitsPerSample !== 16) {
        console.log(`${name}: unsupported`);
        return;
    }

    if (![8000, 16000].includes(sampleRate)) {
        console.log(`${name}: unsupported`);
        return;
    }

    if (![1, 2].includes(channels)) {
        console.log(`${name}: unsupported`);
        return;
    }

    // Extract left channel samples
    const samplesPerFrame = channels;
    const bytesPerSample = 2;
    const numFrames = Math.floor(dataChunk.size / (samplesPerFrame * bytesPerSample));
    const leftChannel = new Int16Array(numFrames);

    for (let i = 0; i < numFrames; i++) {
        leftChannel[i] = buffer.readInt16LE(dataChunk.bodyOffset + i * samplesPerFrame * bytesPerSample);
    }

    // Detection
    const N = sampleRate / 50;
    const numBlocks = Math.floor(numFrames / N);
    const labels: string[] = [];

    const lowFreqs = [697, 770, 852, 941];
    const highFreqs = [1209, 1336, 1477, 1633];
    const keypad = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    for (let b = 0; b < numBlocks; b++) {
        let energy = 0;
        for (let n = 0; n < N; n++) {
            const x = leftChannel[b * N + n];
            energy += x * x;
        }

        if (energy < 1000000 * N) {
            labels.push('none');
            continue;
        }

        const rLow = new Array(4).fill(0);
        const rHigh = new Array(4).fill(0);

        const calcPower = (f: number) => {
            const c = 2 * Math.cos(2 * Math.PI * f / sampleRate);
            let s1 = 0, s2 = 0;
            for (let n = 0; n < N; n++) {
                const x = leftChannel[b * N + n];
                const s = x + c * s1 - s2;
                s2 = s1;
                s1 = s;
            }
            return s1 * s1 + s2 * s2 - c * s1 * s2;
        };

        for (let i = 0; i < 4; i++) {
            const pL = calcPower(lowFreqs[i]);
            rLow[i] = (2 * pL) / (N * energy);
        }
        for (let i = 0; i < 4; i++) {
            const pH = calcPower(highFreqs[i]);
            rHigh[i] = (2 * pH) / (N * energy);
        }

        let maxLIdx = 0, maxHIdx = 0;
        for (let i = 1; i < 4; i++) {
            if (rLow[i] > rLow[maxLIdx]) maxLIdx = i;
            if (rHigh[i] > rHigh[maxHIdx]) maxHIdx = i;
        }

        const rl = rLow[maxLIdx];
        const rh = rHigh[maxHIdx];

        if (rl >= 0.1 && rh >= 0.1 && (rl + rh) >= 0.6) {
            labels.push(keypad[maxLIdx][maxHIdx]);
        } else {
            labels.push('none');
        }
    }

    // Bridging
    const bridgedLabels = [...labels];
    for (let i = 1; i < labels.length - 1; i++) {
        if (labels[i] === 'none' && labels[i - 1] !== 'none' && labels[i - 1] === labels[i + 1]) {
            bridgedLabels[i] = labels[i - 1];
        }
    }

    // Events
    const events: { digit: string, start: number, end: number }[] = [];
    let currentDigit = '';
    let startIdx = 0;

    for (let i = 0; i <= bridgedLabels.length; i++) {
        const digit = i < bridgedLabels.length ? bridgedLabels[i] : 'none';
        if (digit === currentDigit) {
            continue;
        } else {
            if (currentDigit !== 'none' && (i - startIdx) >= 2) {
                events.push({
                    digit: currentDigit,
                    start: 20 * startIdx,
                    end: 20 * i
                });
            }
            currentDigit = digit;
            startIdx = i;
        }
    }

    // Output
    process.stdout.write(`${name}: ${sampleRate} Hz, ${channels} ch, ${numBlocks} blocks\n`);
    let digitsString = '';
    for (const event of events) {
        process.stdout.write(`${event.digit} ${event.start} ${event.end}\n`);
        digitsString += event.digit;
    }
    process.stdout.write(`digits: ${digitsString}\n`);
}

