                        System.out.println("CALL " + tc.get("id") + " " + func.get("name"));
                    }

                    conversation.add(message);

                    for (Map<String, Object> tc : toolCalls) {
                        Map<String, Object> func = (Map<String, Object>) tc.get("function");
                        String toolName = (String) func.get("name");
                        String argsJson = (String) func.get("arguments");
                        Map<String, Object> toolArgs = new JsonParser().parse(argsJson);

                        String result = executeTool(toolName, toolArgs, inventory, rates);
                        System.out.println("RESULT " + tc.get("id") + " " + result);

                        Map<String, Object> toolMsg = new HashMap<>();
                        toolMsg.put("role", "tool");
                        toolMsg.put("tool_call_id", tc.get("id"));
                        toolMsg.put("content", result);
                        conversation.add(toolMsg);
                    }
                } else if ("stop".equals(finishReason)) {
                    System.out.println("FINAL " + message.get("content"));
                    System.out.println("USAGE prompt=" + totalPromptTokens + " completion=" + totalCompletionTokens + " total=" + totalTokens + " requests=" + requestsCount);
                    break;
                }
            }
        } catch (Exception e) {
            // Silent fail as per requirements
        }
    }

    private static String executeTool(String name, Map<String, Object> args, List<String[]> inventory, Rates rates) {
        if ("inventory_lookup".equals(name)) {
            String sku = (String) args.get("sku");
            for (String[] row : inventory) {
                if (sku.equals(row[0])) {
                    return String.format("{\"sku\":\"%s\",\"name\":\"%s\",\"price_cents\":%s,\"currency\":\"%s\",\"stock\":%s}",
                            escapeJson(row[0]), escapeJson(row[1]), row[2], escapeJson(row[3]), row[4]);
                }
            }
            return "{\"error\":\"unknown sku: " + escapeJson(sku) + "\"}";
        } else if ("convert_currency".equals(name)) {
            long amountCents = ((Number) args.get("amount_cents")).longValue();
            String from = (String) args.get("from");
            String to = (String) args.get("to");
            long rateFrom = rates.rates.get(from);
            long rateTo = rates.rates.get(to);
            long converted = (2 * amountCents * rateTo + rateFrom) / (2 * rateFrom);
            return String.format("{\"amount_cents\":%d,\"currency\":\"%s\"}", converted, escapeJson(to));
        } else {
            return "{\"error\":\"unknown tool: " + escapeJson(name) + "\"}";
        }
    }

    private static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') sb.append("\\\"");
            else if (c == '\\') sb.append("\\\\");
            else if (c == '\b') sb.append("\\b");
            else if (c == '\f') sb.append("\\f");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else if (c < 32) sb.append(String.format("\\u%04x", (int) c));
            else sb.append(c);
        }
        return sb.toString();
    }

    private static String buildRequestBody(Task task, List<Map<String, Object>> conversation) {
        StringBuilder sb = new StringBuilder();
        sb.append("{");
        sb.append("\"model\":\"").append(escapeJson(task.model)).append("\",");
        sb.append("\"messages\":").append(toJson(conversation)).append(",");
        sb.append("\"tools\":").append(toJson(task.tools)).append(",");
        sb.append("\"tool_choice\":\"auto\"");
        sb.append("}");
        return sb.toString();
    }

    private static String toJson(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof String) return "\"" + escapeJson((String) obj) + "\"";
        if (obj instanceof Number) return obj.toString();
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof List) {
            List<?> list = (List<?>) obj;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                sb.append(toJson(list.get(i)));
                if (i < list.size() - 1) sb.append(",");
            }
            sb.append("]");
            return sb.toString();
        }
        if (obj instanceof Map) {
            Map<?, ?> map = (Map<?, ?>) obj;
            StringBuilder sb = new StringBuilder("{");
            int i = 0;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                sb.append("\"").append(escapeJson(entry.getKey().toString())).append("\":").append(toJson(entry.getValue()));
                if (++i < map.size()) sb.append(",");
            }
            sb.append("}");
            return sb.toString();
        }
        return "null";
    }

    private static Response sendRequest(String baseUrl, String apiKey, String body) throws IOException {
        URL url = new URL(baseUrl + "/chat/completions");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Authorization", "Bearer " + apiKey);
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setDoOutput(true);

        try (OutputStream os = conn.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }

        int status = conn.getResponseCode();
        InputStream is = (status < 400) ? conn.getInputStream() : conn.getErrorStream();
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buffer = new byte[4096];
        int read;
        while ((read = is.read(buffer)) != -1) baos.write(buffer, 0, read);
        String responseBody = baos.toString(StandardCharsets.UTF_8);
        return new Response(status, new JsonParser().parse(responseBody));
    }

