    private static List<String[]> loadInventory(String dir) throws IOException {
        byte[] bytes = java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(dir, "inventory.csv"));
        String content = new String(bytes, StandardCharsets.UTF_8);
        if (content.startsWith("\uFEFF")) content = content.substring(1);

        List<String[]> records = new ArrayList<>();
        int i = 0;
        while (i < content.length()) {
            List<String> fields = new ArrayList<>();
            while (i < content.length()) {
                if (content.charAt(i) == '"') {
                    i++;
                    StringBuilder sb = new StringBuilder();
                    while (i < content.length()) {
                        if (content.charAt(i) == '"') {
                            if (i + 1 < content.length() && content.charAt(i + 1) == '"') {
                                sb.append('"'); i += 2;
                            } else { i++; break; }
                        } else sb.append(content.charAt(i++));
                    }
                    fields.add(sb.toString());
                } else {
                    int start = i;
                    while (i < content.length() && content.charAt(i) != ',') {
                        if (content.charAt(i) == '\r' || content.charAt(i) == '\n') break;
                        i++;
                    }
                    fields.add(content.substring(start, i));
                }
                if (i < content.length() && content.charAt(i) == ',') i++;
                else break;
            }
            records.add(fields.toArray(new String[0]));
            if (i < content.length() && content.charAt(i) == '\r') {
                i++;
                if (i < content.length() && content.charAt(i) == '\n') i++;
            } else if (i < content.length() && content.charAt(i) == '\n') {
                i++;
            }
        }
        if (!records.isEmpty()) records.remove(0);
        return records;
    }

