    static class JsonParser {
        int pos;
        String input;
        Map<String, Object> parse(String s) { input = s; pos = 0; return parseObject(); }
        Object parseValue() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '"') return parseString();
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == 't' || c == 'f' || c == 'n') {
                if (input.startsWith("true", pos)) { pos += 4; return true; }
                if (input.startsWith("false", pos)) { pos += 5; return false; }
                if (input.startsWith("null", pos)) { pos += 4; return null; }
            }
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new RuntimeException("Unexpected char: " + c);
        }
        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // {
            while (pos < input.length()) {
                while (pos < input.length() && (Character.isWhitespace(input.charAt(pos)) || input.charAt(pos) == ',')) pos++;
                if (pos >= input.length() || input.charAt(pos) == '}') break;
                String key = parseString();
                while (pos < input.length() && (Character.isWhitespace(input.charAt(pos)) || input.charAt(pos) == ':')) pos++;
                map.put(key, parseValue());
                while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
                if (pos < input.length() && input.charAt(pos) == '}') { pos++; break; }
            }
            if (pos < input.length() && input.charAt(pos) == '}') pos++;
            return map;
        }
        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // [
            while (pos < input.length()) {
                while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
                if (pos >= input.length() || input.charAt(pos) == ']') break;
                list.add(parseValue());
                while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
                if (pos < input.length() && input.charAt(pos) == ',') pos++;
                if (pos < input.length() && input.charAt(pos) == ']') { pos++; break; }
            }
            if (pos < input.length() && input.charAt(pos) == ']') pos++;
            return list;
        }
        String parseString() {
            pos++; // "
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos++);
                if (c == '"') return sb.toString();
                if (c == '\\') {
                    char next = input.charAt(pos++);
                    if (next == '"') sb.append('"');
                    else if (next == '\\') sb.append('\\');
                    else if (next == '/') sb.append('/');
                    else if (next == 'b') sb.append('\b');
                    else if (next == 'f') sb.append('\f');
                    else if (next == 'n') sb.append('\n');
                    else if (next == 'r') sb.append('\r');
                    else if (next == 't') sb.append('\t');
                    else if (next == 'u') {
                        int code = Integer.parseInt(input.substring(pos, pos + 4), 16);
                        sb.append((char) code);
                        pos += 4;
                    }
                } else sb.append(c);
            }
            return sb.toString();
        }
        Number parseNumber() {
            int start = pos;
            while (pos < input.length() && (Character.isDigit(input.charAt(pos)) || input.charAt(pos) == '.' || input.charAt(pos) == '-' || input.charAt(pos) == 'e' || input.charAt(pos) == 'E' || input.charAt(pos) == '+')) pos++;
            String s = input.substring(start, pos);
            if (s.contains(".") || s.contains("e") || s.contains("E")) return Double.parseDouble(s);
            return Long.parseLong(s);
        }
    }
}

use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum JsonValue {
    Object(HashMap<String, JsonValue>),
    Array(Vec<JsonValue>),
    String(String),
    Number(f64),
    Boolean(bool),
    Null,
}

fn parse_json(input: &str) -> JsonValue {
    let mut chars = input.chars().peekable();
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
    parse_value(&mut chars)
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    match chars.peek() {
        Some('{') => parse_object(chars),
        Some('[') => parse_array(chars),
        Some('"') => parse_string(chars),
        Some('t') | Some('f') => parse_bool(chars),
        Some('n') => parse_null(chars),
        _ => parse_number(chars),
    }
}

fn parse_string(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    chars.next(); // "
    let mut s = String::new();
    while let Some(c) = chars.next() {
        if c == '"' { break; }
        if c == '\\' {
            match chars.next() {
                Some('n') => s.push('\n'),
                Some('r') => s.push('\r'),
                Some('t') => s.push('\t'),
                Some('b') => s.push('\x08'),
                Some('f') => s.push('\x0c'),
                Some('"') => s.push('"'),
                Some('\\') => s.push('\\'),
                Some('/') => s.push('/'),
                Some('u') => {
                    let mut hex = String::new();
                    for _ in 0..4 {
                        if let Some(h) = chars.next() { hex.push(h); }
                    }
                    let code = u16::from_str_radix(&hex, 16).unwrap_or(0);
                    if (0xD800..=0xDBFF).contains(&code) {
                        if let Some('\\') = chars.next() {
                            if let Some('u') = chars.next() {
                                let mut hex2 = String::new();
                                for _ in 0..4 {
                                    if let Some(h) = chars.next() { hex2.push(h); }
                                }
                                let code2 = u16::from_str_radix(&hex2, 16).unwrap_or(0);
                                let cp = 0x10000 + ((code as u32 - 0xD800) * 0x400) + (code2 as u32 - 0xDC00);
                                if let Some(c) = std::char::from_u32(cp) { s.push(c); }
                            }
                        }
                    } else {
                        if let Some(c) = std::char::from_u32(code as u32) { s.push(c); }
                    }
                }
                _ => {}
            }
        } else {
            s.push(c);
        }
    }
    JsonValue::String(s)
}

fn parse_object(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    chars.next(); // {
    let mut map = HashMap::new();
    loop {
        while let Some(&c) = chars.peek() {
            if c == '}' { break; }
            if c.is_whitespace() { chars.next(); } else { break; }
        }
        if let Some('}') = chars.peek() {
            chars.next();
            break;
        }
        let key = match parse_string(chars) {
            JsonValue::String(s) => s,
            _ => unreachable!(),
        };
        while let Some(&c) = chars.peek() {
            if c == ':' { break; }
            chars.next();
        }
        chars.next(); // :
        map.insert(key, parse_value(chars));
        while let Some(&c) = chars.peek() {
            if c == ',' {
                chars.next();
                break;
            } else if c == '}' {
                break;
            } else if c.is_whitespace() {
                chars.next();
            } else {
                break;
            }
        }
    }
    JsonValue::Object(map)
}

fn parse_array(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    chars.next(); // [
    let mut arr = Vec::new();
    loop {
        while let Some(&c) = chars.peek() {
            if c == ']' { break; }
            if c.is_whitespace() { chars.next(); } else { break; }
        }
        if let Some(']') = chars.peek() {
            chars.next();
            break;
        }
        arr.push(parse_value(chars));
        while let Some(&c) = chars.peek() {
            if c == ',' {
                chars.next();
                break;
            } else if c == ']' {
                break;
            } else if c.is_whitespace() {
                chars.next();
            } else {
                break;
            }
        }
    }
    JsonValue::Array(arr)
}

fn parse_bool(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    let mut s = String::new();
    while let Some(&c) = chars.peek() {
        if c == 't' || c == 'f' || c == 'r' || c == 'u' || c == 'e' || c == 'l' {
            s.push(chars.next().unwrap());
        } else {
            break;
        }
    }
    if s == "true" { JsonValue::Boolean(true) } else { JsonValue::Boolean(false) }
}

fn parse_null(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    for _ in 0..4 { chars.next(); }
    JsonValue::Null
}

fn parse_number(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    let mut s = String::new();
    while let Some(&c) = chars.peek() {
        if c == '-' || c == '.' || c.is_ascii_digit() || c == 'e' || c == 'E' || c == '+' {
            s.push(chars.next().unwrap());
        } else {
            break;
        }
    }
    JsonValue::Number(s.parse::<f64>().unwrap_or(0.0))
}

fn serialize_json(val: &JsonValue) -> String {
    match val {
        JsonValue::String(s) => {
            let mut res = String::from("\"");
            for c in s.chars() {
                match c {
                    '\n' => res.push_str("\\n"),
                    '\r' => res.push_str("\\r"),
                    '\t' => res.push_str("\\t"),
                    '\\' => res.push_str("\\\\"),
                    '"' => res.push_str("\\\""),
                    _ => res.push(c),
                }
            }
            res.push('"');
            res
        }
        JsonValue::Number(n) => {
            if let Some(i) = n.to_string().strip_suffix(".0") {
                i.to_string()
            } else {
                n.to_string()
            }
        }
        JsonValue::Boolean(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
        JsonValue::Array(arr) => {
            let mut res = String::from("[");
            for (i, val) in arr.iter().enumerate() {
                if i > 0 { res.push(','); }
                res.push_str(&serialize_json(val));
            }
            res.push(']');
            res
        }
        JsonValue::Object(obj) => {
            let mut res = String::from("{");
            let mut first = true;
            for (k, v) in obj {
                if !first { res.push(','); }
                res.push_str(&format!("\"{}\":", k));
                res.push_str(&serialize_json(v));
                first = false;
            }
            res.push('}');
            res
        }
    }
}

fn escape_string(s: &str) -> String {
    let mut res = String::new();
    for c in s.chars() {
        match c {
            '\n' => res.push_str("\\n"),
            '\r' => res.push_str("\\r"),
            '\t' => res.push_str("\\t"),
            '\\' => res.push_str("\\\\"),
            _ => res.push(c),
        }
    }
    res
}

