    file.read_to_string(&mut content).unwrap();
    let req_json = parse_json(&content);

    let api_key = match &req_json {
        JsonValue::Object(o) => match o.get("api_key") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => "".to_string(),
        },
        _ => "".to_string(),
    };
    let model = match &req_json {
        JsonValue::Object(o) => match o.get("model") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => "".to_string(),
        },
        _ => "".to_string(),
    };
    let max_tokens = match &req_json {
        JsonValue::Object(o) => match o.get("max_tokens") {
            Some(JsonValue::Number(n)) => *n as i64,
            _ => 0,
        },
        _ => 0,
    };
    let thinking_budget = match &req_json {
        JsonValue::Object(o) => match o.get("thinking_budget") {
            Some(JsonValue::Number(n)) => *n as i64,
            _ => 0,
        },
        _ => 0,
    };
    let system = match &req_json {
        JsonValue::Object(o) => match o.get("system") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => "".to_string(),
        },
        _ => "".to_string(),
    };
    let prompt = match &req_json {
        JsonValue::Object(o) => match o.get("prompt") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => "".to_string(),
        },
        _ => "".to_string(),
    };
    let tools = match &req_json {
        JsonValue::Object(o) => o.get("tools").cloned().unwrap_or(JsonValue::Array(vec![])),
        _ => JsonValue::Array(vec![]),
    };

    let host_split: Vec<&str> = base_url.splitn(2, '/').collect();
    let host_full = host_split[0].replace("http://", "");
    let host_parts: Vec<&str> = host_full.splitn(2, '/').collect();
    let host = host_parts[0];
    let path_start = if host_parts.len() > 1 { host_parts[1] } else { "" };
    let path = if path_start.is_empty() {
        format!("/v1/messages")
    } else {
        format!("/{}/v1/messages", path_start)
    };

    let mut total_input_tokens = 0;
    let mut total_output_tokens = 0;
    let mut total_cache_read_tokens = 0;

    let mut current_messages = vec![
        JsonValue::Object({
            let mut m = HashMap::new();
            m.insert("role".to_string(), JsonValue::String("user".to_string()));
            m.insert("content".to_string(), JsonValue::String(prompt.clone()));
            m
        }),
    ];

    for round in 1..=2 {
        if round == 2 {
            println!("request 2");
        } else {
            println!("request 1");
        }

        let body = {
            let mut b = HashMap::new();
            b.insert("model".to_string(), JsonValue::String(model.clone()));
            b.insert("max_tokens".to_string(), JsonValue::Number(max_tokens as f64));
            b.insert("stream".to_string(), JsonValue::Boolean(true));
            let mut thinking = HashMap::new();
            thinking.insert("type".to_string(), JsonValue::String("enabled".to_string()));
            thinking.insert("budget_tokens".to_string(), JsonValue::Number(thinking_budget as f64));
            b.insert("thinking".to_string(), JsonValue::Object(thinking));
            b.insert("system".to_string(), JsonValue::String(system.clone()));
