        };

        let body_str = serialize_json(&body);
        let mut stream = TcpStream::connect(host).unwrap();
        stream.write_all(format!("POST {} HTTP/1.1\r\nHost: {}\r\nx-api-key: {}\ranthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nContent-Length: {}\r\n\r\n{}", path, host, api_key, body_str.len(), body_str).as_bytes()).unwrap();

        let mut reader = BufReader::new(stream);
        let mut line = String::new();
        loop {
            line.clear();
            reader.read_line(&mut line).unwrap();
            if line.trim() == "" { break; }
        }

        let mut chunk_reader = reader;
        let mut blocks: Vec<ContentBlock> = Vec::new();
        let mut stop_reason = String::new();

        loop {
            let mut size_line = String::new();
            chunk_reader.read_line(&mut size_line).unwrap();
            let size_str = size_line.trim();
            if size_str.is_empty() { break; }
            let size = usize::from_str_radix(size_str, 16).unwrap_or(0);
            if size == 0 {
                let mut end_line = String::new();
                chunk_reader.read_line(&mut end_line).unwrap();
                break;
            }
            let mut buffer = vec![0u8; size];
            chunk_reader.read_exact(&mut buffer).unwrap();
            let mut end_line = String::new();
            chunk_reader.read_line(&mut end_line).unwrap();

            let chunk_text = String::from_utf8_lossy(&buffer);
            let mut sse_lines = chunk_text.split("\n");
            let mut current_event = String::new();
            let mut current_data = String::new();

            for line in sse_lines {
                let line = line.trim_end_matches("\r");
                if line.is_empty() {
                    if !current_event.is_empty() {
                        let data = current_data.trim_start_matches("data:").trim_start();
                        let json_data = parse_json(data);
                        match current_event.as_str() {
                            "message_start" => {
                                if let JsonValue::Object(o) = json_data {
                                    if let Some(JsonValue::Object(m)) = o.get("message") {
                                        if let Some(JsonValue::Object(u)) = m.get("usage") {
                                            if let Some(JsonValue::Number(n)) = u.get("input_tokens") { total_input_tokens += *n as i64; }
                                            if let Some(JsonValue::Number(n)) = u.get("cache_read_input_tokens") { total_cache_read_tokens += *n as i64; }
                                        }
                                    }
                                }
                            }
                            "content_block_start" => {
                                if let JsonValue::Object(o) = json_data {
                                    let index = match o.get("index") { Some(JsonValue::Number(n)) => *n as usize, _ => 0 };
                                    let block_val = o.get("content_block").cloned().unwrap();
                                    let mut block = ContentBlock {
                                        block_type: "".to_string(), thinking: "".to_string(), signature: "".to_string(),
                                        text: "".to_string(), id: "".to_string(), name: "".to_string(),
                                        input_raw: "".to_string(), input_parsed: JsonValue::Null,
                                    };
                                    if let JsonValue::Object(bo) = block_val {
                                        if let Some(JsonValue::String(t)) = bo.get("type") {
                                            block.block_type = t.clone();
                                            if t == "thinking" {
                                                block.thinking = match bo.get("thinking") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                                block.signature = match bo.get("signature") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                            } else if t == "text" {
                                                block.text = match bo.get("text") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                            } else if t == "tool_use" {
                                                block.id = match bo.get("id") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                                block.name = match bo.get("name") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                            }
                                        }
                                    }
                                    while blocks.len() <= index { blocks.push(block.clone()); }
                                    blocks[index] = block;
                                }
                            }
                            "content_block_delta" => {
                                if let JsonValue::Object(o) = json_data {
                                    let index = match o.get("index") { Some(JsonValue::Number(n)) => *n as usize, _ => 0 };
                                    if let Some(JsonValue::Object(d)) = o.get("delta") {
                                        if let Some(JsonValue::Object(dt)) = d.get("type") { } // wait, type is a string
                                    }
                                    if let Some(JsonValue::Object(d)) = o.get("delta") {
                                        let dt = match d.get("type") { Some(JsonValue::String(s)) => s.as_str(), _ => "" };
                                        match dt {
                                            "thinking_delta" => {
                                                if let Some(JsonValue::String(s)) = d.get("thinking") { blocks[index].thinking.push_str(s); }
                                            }
                                            "signature_delta" => {
                                                if let Some(JsonValue::String(s)) = d.get("signature") { blocks[index].signature.push_str(s); }
                                            }
                                            "text_delta" => {
                                                if let Some(JsonValue::String(s)) = d.get("text") { blocks[index].text.push_str(s); }
                                            }
                                            "input_json_delta" => {
                                                if let Some(JsonValue::String(s)) = d.get("partial_json") { blocks[index].input_raw.push_str(s); }
                                            }
                                            _ => {}
                                        }
                                    }
                                }
                            }
                            "content_block_stop" => {}
                            "message_delta" => {
                                if let JsonValue::Object(o) = json_data {
                                    if let Some(JsonValue::Object(d)) = o.get("delta") {
                                        if let Some(JsonValue::String(s)) = d.get("stop_reason") { stop_reason = s.clone(); }
                                    }
                                    if let Some(JsonValue::Object(u)) = o.get("usage") {
                                        if let Some(JsonValue::Number(n)) = u.get("output_tokens") { total_output_tokens += *n as i64; }
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                    current_event = String::new();
                    current_data = String::new();
                } else if line.starts_with("event:") {
                    current_event = line["event:".len()..].trim().to_string();
                } else if line.starts_with("data:") {
                    current_data.push_str(line["data:".len()..].trim_start());
                }
            }
        }

        for block in &blocks {
            if block.block_type == "thinking" {
                println!("thinking {}", escape_string(&block.thinking));
                println!("signature {}", escape_string(&block.signature));
            } else if block.block_type == "text" {
                println!("text {}", escape_string(&block.text));
            } else if block.block_type == "tool_use" {
                println!("tool_use {} {} {}", block.id, block.name, escape_string(&block.input_raw));
            }
        }
        println!("stop_reason {}", stop_reason);

        if round == 1 {
            let mut tool_results = Vec::new();
            for block in &blocks {
                if block.block_type == "tool_use" {
                    let input_parsed = parse_json(&block.input_raw);
                    let result = if block.name == "measure" {
                        if let JsonValue::Object(o) = input_parsed {
                            let text = match o.get("text") { Some(JsonValue::String(s)) => s, _ => "" }.clone();
                            let unit = match o.get("unit") { Some(JsonValue::String(s)) => s, _ => "" }.clone();
                            match unit.as_str() {
                                "code_points" => text.chars().count().to_string(),
                                "utf8_bytes" => text.len().to_string(),
                                "utf16_units" => text.encode_utf16().count().to_string(),
                                _ => format!("unsupported unit: {}", unit),
                            }
                        } else { "error".to_string() }
                    } else if block.name == "reverse" {
                        if let JsonValue::Object(o) = input_parsed {
                            let text = match o.get("text") { Some(JsonValue::String(s)) => s, _ => "" }.clone();
                            text.chars().rev().collect::<String>()
                        } else { "error".to_string() }
                    } else {
                        format!("unknown tool: {}", block.name)
                    };

                    let is_error = result.contains("unsupported unit") || result.contains("unknown tool");
                    if is_error {
                        println!("error {} {}", block.id, escape_string(&result));
                    } else {
                        println!("result {} {}", block.id, escape_string(&result));
                    }

                    tool_results.push(JsonValue::Object({
                        let mut m = HashMap::new();
                        m.insert("type".to_string(), JsonValue::String("tool_result".to_string()));
                        m.insert("tool_use_id".to_string(), JsonValue::String(block.id.clone()));
                        m.insert("content".to_string(), JsonValue::String(result));
                        if is_error { m.insert("is_error".to_string(), JsonValue::Boolean(true)); }
                        m
                    }));
                }
            }

            let mut assistant_content = Vec::new();
            for block in &blocks {
                if block.block_type == "thinking" {
                    assistant_content.push(JsonValue::Object({
                        let mut m = HashMap::new();
                        m.insert("type".to_string(), JsonValue::String("thinking".to_string()));
                        m.insert("thinking".to_string(), JsonValue::String(block.thinking.clone()));
                        m.insert("signature".to_string(), JsonValue::String(block.signature.clone()));
                        m
                    }));
                } else if block.block_type == "text" {
                    assistant_content.push(JsonValue::Object({
                        let mut m = HashMap::new();
                        m.insert("type".to_string(), JsonValue::String("text".to_string()));
                        m.insert("text".to_string(), JsonValue::String(block.text.clone()));
                        m
                    }));
                } else if block.block_type == "tool_use" {
                    assistant_content.push(JsonValue::Object({
                        let mut m = HashMap::new();
                        m.insert("type".to_string(), JsonValue::String("tool_use".to_string()));
                        m.insert("id".to_string(), JsonValue::String(block.id.clone()));
                        m.insert("name".to_string(), JsonValue::String(block.name.clone()));
                        m.insert("input".to_string(), parse_json(&block.input_raw));
                        m
                    }));
                }
            }

            current_messages.push(JsonValue::Object({
                let mut m = HashMap::new();
                m.insert("role".to_string(), JsonValue::String("assistant".to_string()));
                m.insert("content".to_string(), JsonValue::Array(assistant_content));
                m
            }));
            current_messages.push(JsonValue::Object({
                let mut m = HashMap::new();
                m.insert("role".to_string(), JsonValue::String("user".to_string()));
                m.insert("content".to_string(), JsonValue::Array(tool_results));
                m
            }));
        }
    }
    println!("usage input={} output={} cache_read={}", total_input_tokens, total_output_tokens, total_cache_read_tokens);
}

use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum JsonValue {
    Object(HashMap<String, JsonValue>),
    Array(Vec<JsonValue>),
    String(String),
    Number(f64),
    Boolean(bool),
    Null,
}

fn parse_json(input: &str) -> JsonValue {
    let mut chars = input.chars().peekable();
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
    parse_value(&mut chars)
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    match chars.peek() {
        Some('{') => parse_object(chars),
        Some('[') => parse_array(chars),
        Some('"') => parse_string(chars),
        Some('t') | Some('f') => parse_bool(chars),
        Some('n') => parse_null(chars),
        _ => parse_number(chars),
    }
}

fn parse_string(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    chars.next(); // "
    let mut s = String::new();
    while let Some(c) = chars.next() {
        if c == '"' { break; }
        if c == '\\' {
            match chars.next() {
                Some('n') => s.push('\n'),
                Some('r') => s.push('\r'),
                Some('t') => s.push('\t'),
                Some('b') => s.push('\x08'),
                Some('f') => s.push('\x0c'),
                Some('"') => s.push('"'),
                Some('\\') => s.push('\\'),
                Some('/') => s.push('/'),
                Some('u') => {
                    let mut hex = String::new();
                    for _ in 0..4 {
                        if let Some(h) = chars.next() { hex.push(h); }
                    }
                    let code = u16::from_str_radix(&hex, 16).unwrap_or(0);
                    if (0xD800..=0xDBFF).contains(&code) {
                        if let Some('\\') = chars.next() {
                            if let Some('u') = chars.next() {
                                let mut hex2 = String::new();
                                for _ in 0..4 {
                                    if let Some(h) = chars.next() { hex2.push(h); }
                                }
                                let code2 = u16::from_str_radix(&hex2, 16).unwrap_or(0);
                                let cp = 0x10000 + ((code as u32 - 0xD800) * 0x400) + (code2 as u32 - 0xDC00);
                                if let Some(c) = std::char::from_u32(cp) { s.push(c); }
                            }
                        }
                    } else {
                        if let Some(c) = std::char::from_u32(code as u32) { s.push(c); }
                    }
                }
                _ => {}
            }
        } else {
            s.push(c);
        }
    }
    JsonValue::String(s)
}

fn parse_object(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    chars.next(); // {
    let mut map = HashMap::new();
    loop {
        while let Some(&c) = chars.peek() {
            if c == '}' { break; }
            if c.is_whitespace() { chars.next(); } else { break; }
        }
        if let Some('}') = chars.peek() {
            chars.next();
            break;
        }
        let key = match parse_string(chars) {
            JsonValue::String(s) => s,
            _ => unreachable!(),
        };
        while let Some(&c) = chars.peek() {
            if c == ':' { break; }
            chars.next();
        }
        chars.next(); // :
        map.insert(key, parse_value(chars));
        while let Some(&c) = chars.peek() {
            if c == ',' {
                chars.next();
                break;
            } else if c == '}' {
                break;
            } else if c.is_whitespace() {
                chars.next();
            } else {
                break;
            }
        }
    }
    JsonValue::Object(map)
}

fn parse_array(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    chars.next(); // [
    let mut arr = Vec::new();
    loop {
        while let Some(&c) = chars.peek() {
            if c == ']' { break; }
            if c.is_whitespace() { chars.next(); } else { break; }
        }
        if let Some(']') = chars.peek() {
            chars.next();
            break;
        }
        arr.push(parse_value(chars));
        while let Some(&c) = chars.peek() {
            if c == ',' {
                chars.next();
                break;
            } else if c == ']' {
                break;
            } else if c.is_whitespace() {
                chars.next();
            } else {
                break;
            }
        }
    }
    JsonValue::Array(arr)
}

fn parse_bool(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    let mut s = String::new();
    while let Some(&c) = chars.peek() {
        if c == 't' || c == 'f' || c == 'r' || c == 'u' || c == 'e' || c == 'l' {
            s.push(chars.next().unwrap());
        } else {
            break;
        }
    }
    if s == "true" { JsonValue::Boolean(true) } else { JsonValue::Boolean(false) }
}

fn parse_null(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    for _ in 0..4 { chars.next(); }
    JsonValue::Null
}

fn parse_number(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    let mut s = String::new();
    while let Some(&c) = chars.peek() {
        if c == '-' || c == '.' || c.is_ascii_digit() || c == 'e' || c == 'E' || c == '+' {
            s.push(chars.next().unwrap());
        } else {
            break;
        }
    }
    JsonValue::Number(s.parse::<f64>().unwrap_or(0.0))
}

fn serialize_json(val: &JsonValue) -> String {
    match val {
        JsonValue::String(s) => {
            let mut res = String::from("\"");
            for c in s.chars() {
                match c {
                    '\n' => res.push_str("\\n"),
                    '\r' => res.push_str("\\r"),
                    '\t' => res.push_str("\\t"),
                    '\\' => res.push_str("\\\\"),
                    '"' => res.push_str("\\\""),
                    _ => res.push(c),
                }
            }
            res.push('"');
            res
        }
        JsonValue::Number(n) => {
            let s = n.to_string();
            if let Some(i) = s.strip_suffix(".0") {
                i.to_string()
            } else {
                s
            }
        }
        JsonValue::Boolean(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
        JsonValue::Array(arr) => {
            let mut res = String::from("[");
            for (i, val) in arr.iter().enumerate() {
                if i > 0 { res.push(','); }
                res.push_str(&serialize_json(val));
            }
            res.push(']');
            res
        }
        JsonValue::Object(obj) => {
            let mut res = String::from("{");
            let mut first = true;
            for (k, v) in obj {
                if !first { res.push(','); }
                res.push_str(&format!("\"{}\":", k));
                res.push_str(&serialize_json(v));
                first = false;
            }
            res.push('}');
            res
        }
    }
}

fn escape_string(s: &str) -> String {
    let mut res = String::new();
    for c in s.chars() {
        match c {
            '\n' => res.push_str("\\n"),
            '\r' => res.push_str("\\r"),
            '\t' => res.push_str("\\t"),
            '\\' => res.push_str("\\\\"),
            _ => res.push(c),
        }
    }
    res
}

#[derive(Clone)]
struct ContentBlock {
    block_type: String,
    thinking: String,
    signature: String,
    text: String,
    id: String,
    name: String,
    input_raw: String,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 { return; }
    let data_dir = &args[1];
    let base_url = &args[2];

    let mut file = File::open(format!("{}/request.json", data_dir)).unwrap();
    let mut content = String::new();
    file.read_to_string(&mut content).unwrap();
    let req_json = parse_json(&content);

    let api_key = if let JsonValue::Object(o) = &req_json {
        match o.get("api_key") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() }
    } else { "".to_string() };
    let model = if let JsonValue::Object(o) = &req_json {
        match o.get("model") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() }
    } else { "".to_string() };
    let max_tokens = if let JsonValue::Object(o) = &req_json {
        match o.get("max_tokens") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 }
    } else { 0 };
    let thinking_budget = if let JsonValue::Object(o) = &req_json {
        match o.get("thinking_budget") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 }
    } else { 0 };
    let system = if let JsonValue::Object(o) = &req_json {
        match o.get("system") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() }
    } else { "".to_string() };
    let prompt = if let JsonValue::Object(o) = &req_json {
        match o.get("prompt") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() }
    } else { "".to_string() };
    let tools = if let JsonValue::Object(o) = &req_json {
        o.get("tools").cloned().unwrap_or(JsonValue::Array(vec![]))
    } else { JsonValue::Array(vec![]) };

    let host_start = base_url.find("://").map(|i| i + 3).unwrap_or(0);
    let host_end = base_url[host_start..].find('/').map(|i| i + host_start).unwrap_or(base_url.len());
    let host = &base_url[host_start..host_end];
    let path = &base_url[host_end..];
    let full_path = format!("{}/v1/messages", path);

    let mut total_input_tokens = 0;
    let mut total_output_tokens = 0;
    let mut total_cache_read_tokens = 0;
    let mut printed_lines = Vec::new();

    let mut current_messages = vec![
        JsonValue::Object({
            let mut m = HashMap::new();
            m.insert("role".to_string(), JsonValue::String("user".to_string()));
            m.insert("content".to_string(), JsonValue::String(prompt.clone()));
            m
        }),
    ];

    for round in 1..=2 {
        let round_str = if round == 1 { "request 1" } else { "request 2" };
        printed_lines.push(round_str.to_string());

        let body = {
            let mut b = HashMap::new();
            b.insert("model".to_string(), JsonValue::String(model.clone()));
            b.insert("max_tokens".to_string(), JsonValue::Number(max_tokens as f64));
            b.insert("stream".to_string(), JsonValue::Boolean(true));
            let mut thinking = HashMap::new();
            thinking.insert("type".to_string(), JsonValue::String("enabled".to_string()));
            thinking.insert("budget_tokens".to_string(), JsonValue::Number(thinking_budget as f64));
            b.insert("thinking".to_string(), JsonValue::Object(thinking));
            b.insert("system".to_string(), JsonValue::String(system.clone()));
            b.insert("tools".to_string(), tools.clone());
            b.insert("messages".to_string(), JsonValue::Array(current_messages.clone()));
            JsonValue::Object(b)
        };

        let body_str = serialize_json(&body);
        let mut stream = TcpStream::connect(host).unwrap();
        let request = format!(
            "POST {} HTTP/1.1\r\nHost: {}\r\nx-api-key: {}\ranthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            full_path, host, api_key, body_str.len(), body_str
        );
        stream.write_all(request.as_bytes()).unwrap();

        let mut reader = BufReader::new(stream);
        let mut status_line = String::new();
        reader.read_line(&mut status_line).unwrap();
        let status = status_line.split_whitespace().nth(1).unwrap_or("").to_string();

        if status != "200" {
            let mut headers = String::new();
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                if line == "\r\n" || line == "\n" { break; }
                headers.push_str(&line);
            }
            let content_length = headers.lines()
                .find(|l| l.to_lowercase().starts_with("content-length:"))
                .and_then(|l| l["content-length:".len()..].trim().parse::<usize>().ok())
                .unwrap_or(0);
            let mut body_bytes = vec![0u8; content_length];
            reader.read_exact(&mut body_bytes).unwrap();
            let error_json = parse_json(std::str::from_utf8(&body_bytes).unwrap());
            if let JsonValue::Object(o) = error_json {
                if let Some(JsonValue::Object(e)) = o.get("error") {
                    let e_type = match e.get("type") { Some(JsonValue::String(s)) => s, _ => "" };
                    let e_msg = match e.get("message") { Some(JsonValue::String(s)) => s, _ => "" };
                    for line in &printed_lines { println!("{}", line); }
                    println!("ERROR {} {}: {}", status, e_type, e_msg);
                    return;
                }
            }
        }

        loop {
            let mut line = String::new();
            reader.read_line(&mut line).unwrap();
            if line == "\r\n" || line == "\n" { break; }
        }

        let mut sse_buffer = String::new();
        let mut blocks: Vec<ContentBlock> = Vec::new();
        let mut stop_reason = String::new();
        let mut current_event = String::new();
        let mut current_data = Vec::new();

        loop {
            let mut size_line = String::new();
            reader.read_line(&mut size_line).unwrap();
            let size_str = size_line.trim();
            if size_str.is_empty() { break; }
            let size = usize::from_str_radix(size_str, 16).unwrap_or(0);
            if size == 0 {
                let mut end_line = String::new();
                reader.read_line(&mut end_line).unwrap();
            } else {
                let mut buffer = vec![0u8; size];
                reader.read_exact(&mut buffer).unwrap();
                let mut end_line = String::new();
                reader.read_line(&mut end_line).unwrap();
                sse_buffer.push_str(&String::from_utf8_lossy(&buffer));
            }

            while let Some(line_end) = sse_buffer.find('\n') {
                let line = sse_buffer[..line_end].trim_end_matches("\r");
                sse_buffer = sse_buffer[line_end + 1..].to_string();
                if line.is_empty() {
                    if !current_event.is_empty() {
                        let data = current_data.join("\n");
                        let json_data = parse_json(&data);
                        match current_event.as_str() {
                            "message_start" => {
                                if let JsonValue::Object(o) = json_data {
                                    if let Some(JsonValue::Object(m)) = o.get("message") {
                                        if let Some(JsonValue::Object(u)) = m.get("usage") {
                                            if let Some(JsonValue::Number(n)) = u.get("input_tokens") { total_input_tokens += *n as i64; }
                                            if let Some(JsonValue::Number(n)) = u.get("cache_read_input_tokens") { total_cache_read_tokens += *n as i64; }
                                        }
                                    }
                                }
                            }
                            "content_block_start" => {
                                if let JsonValue::Object(o) = json_data {
                                    let index = match o.get("index") { Some(JsonValue::Number(n)) => *n as usize, _ => 0 };
                                    let block_val = o.get("content_block").cloned().unwrap();
                                    let mut block = ContentBlock {
                                        block_type: "".to_string(), thinking: "".to_string(), signature: "".to_string(),
                                        text: "".to_string(), id: "".to_string(), name: "".to_string(), input_raw: "".to_string(),
                                    };
                                    if let JsonValue::Object(bo) = block_val {
                                        if let Some(JsonValue::String(t)) = bo.get("type") {
                                            block.block_type = t.clone();
                                            if t == "thinking" {
                                                block.thinking = match bo.get("thinking") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                                block.signature = match bo.get("signature") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                            } else if t == "text" {
                                                block.text = match bo.get("text") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                            } else if t == "tool_use" {
                                                block.id = match bo.get("id") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                                block.name = match bo.get("name") { Some(JsonValue::String(s)) => s.clone(), _ => "".to_string() };
                                            }
                                        }
                                    }
                                    while blocks.len() <= index { blocks.push(ContentBlock {
                                        block_type: "".to_string(), thinking: "".to_string(), signature: "".to_string(),
                                        text: "".to_string(), id: "".to_string(), name: "".to_string(), input_raw: "".to_string(),
                                    }); }
                                    blocks[index] = block;
                                }
                            }
                            "content_block_delta" => {
                                if let JsonValue::Object(o) = json_data {
                                    let index = match o.get("index") { Some(JsonValue::Number(n)) => *n as usize, _ => 0 };
                                    if let Some(JsonValue::Object(d)) = o.get("delta") {
                                        let dt = match d.get("type") { Some(JsonValue::String(s)) => s.as_str(), _ => "" };
                                        match dt {
                                            "thinking_delta" => { if let Some(JsonValue::String(s)) = d.get("thinking") { blocks[index].thinking.push_str(s); } }
                                            "signature_delta" => { if let Some(JsonValue::String(s)) = d.get("signature") { blocks[index].signature.push_str(s); } }
                                            "text_delta" => { if let Some(JsonValue::String(s)) = d.get("text") { blocks[index].text.push_str(s); } }
                                            "input_json_delta" => { if let Some(JsonValue::String(s)) = d.get("partial_json") { blocks[index].input_raw.push_str(s); } }
                                            _ => {}
                                        }
                                    }
                                }
                            }
                            "message_delta" => {
                                if let JsonValue::Object(o) = json_data {
                                    if let Some(JsonValue::Object(d)) = o.get("delta") {
                                        if let Some(JsonValue::String(s)) = d.get("stop_reason") { stop_reason = s.clone(); }
                                    }
                                    if let Some(JsonValue::Object(u)) = o.get("usage") {
                                        if let Some(JsonValue::Number(n)) = u.get("output_tokens") { total_output_tokens += *n as i64; }
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                    current_event.clear();
                    current_data.clear();
                } else if line.starts_with("event:") {
                    let mut val = &line[6..];
                    if val.starts_with(' ') { val = &val[1..]; }
                    current_event = val.to_string();
                } else if line.starts_with("data:") {
                    let mut val = &line[5..];
                    if val.starts_with(' ') { val = &val[1..]; }
                    current_data.push(val.to_string());
                }
            }
        }

        for block in &blocks {
            if block.block_type == "thinking" {
                printed_lines.push(format!("thinking {}", escape_string(&block.thinking)));
                printed_lines.push(format!("signature {}", escape_string(&block.signature)));
            } else if block.block_type == "text" {
                printed_lines.push(format!("text {}", escape_string(&block.text)));
            } else if block.block_type == "tool_use" {
                printed_lines.push(format!("tool_use {} {} {}", block.id, block.name, escape_string(&block.input_raw)));
            }
        }
        printed_lines.push(format!("stop_reason {}", stop_reason));

        if round == 1 {
            let mut tool_results = Vec::new();
            for block in &blocks {
                if block.block_type == "tool_use" {
                    let input_parsed = parse_json(&block.input_raw);
                    let result = if block.name == "measure" {
                        if let JsonValue::Object(o) = input_parsed {
                            let text = match o.get("text") { Some(JsonValue::String(s)) => s, _ => "" }.clone();
                            let unit = match o.get("unit") { Some(JsonValue::String(s)) => s, _ => "" }.clone();
                            if unit == "code_points" { text.chars().count().to_string() }
                            else if unit == "utf8_bytes" { text.len().to_string() }
                            else if unit == "utf16_units" { text.encode_utf16().count().to_string() }
                            else { format!("unsupported unit: {}", unit) }
                        } else { "error".to_string() }
                    } else if block.name == "reverse" {
                        if let JsonValue::Object(o) = input_parsed {
                            let text = match o.get("text") { Some(JsonValue::String(s)) => s, _ => "" }.clone();
                            text.chars().rev().collect::<String>()
                        } else { "error".to_string() }
                    } else {
                        format!("unknown tool: {}", block.name)
                    };

                    let is_error = result.contains("unsupported unit") || result.contains("unknown tool");
                    if is_error {
                        printed_lines.push(format!("error {} {}", block.id, escape_string(&result)));
                    } else {
                        printed_lines.push(format!("result {} {}", block.id, escape_string(&result)));
                    }

                    let mut res_obj = HashMap::new();
                    res_obj.insert("type".to_string(), JsonValue::String("tool_result".to_string()));
                    res_obj.insert("tool_use_id".to_string(), JsonValue::String(block.id.clone()));
                    res_obj.insert("content".to_string(), JsonValue::String(result));
                    if is_error { res_obj.insert("is_error".to_string(), JsonValue::Boolean(true)); }
                    tool_results.push(JsonValue::Object(res_obj));
                }
            }

            let mut assistant_content = Vec::new();
            for block in &blocks {
                if block.block_type == "thinking" {
                    let mut m = HashMap::new();
                    m.insert("type".to_string(), JsonValue::String("thinking".to_string()));
                    m.insert("thinking".to_string(), JsonValue::String(block.thinking.clone()));
                    m.insert("signature".to_string(), JsonValue::String(block.signature.clone()));
                    assistant_content.push(JsonValue::Object(m));
                } else if block.block_type == "text" {
                    let mut m = HashMap::new();
                    m.insert("type".to_string(), JsonValue::String("text".to_string()));
                    m.insert("text".to_string(), JsonValue::String(block.text.clone()));
                    assistant_content.push(JsonValue::Object(m));
                } else if block.block_type == "tool_use" {
                    let mut m = HashMap::new();
                    m.insert("type".to_string(), JsonValue::String("tool_use".to_string()));
                    m.insert("id".to_string(), JsonValue::String(block.id.clone()));
                    m.insert("name".to_string(), JsonValue::String(block.name.clone()));
                    m.insert("input".to_string(), parse_json(&block.input_raw));
                    assistant_content.push(JsonValue::Object(m));
                }
            }

            let mut assistant_msg = HashMap::new();
            assistant_msg.insert("role".to_string(), JsonValue::String("assistant".to_string()));
            assistant_msg.insert("content".to_string(), JsonValue::Array(assistant_content));
            current_messages.push(JsonValue::Object(assistant_msg));

            let mut user_msg = HashMap::new();
            user_msg.insert("role".to_string(), JsonValue::String("user".to_string()));
            user_msg.insert("content".to_string(), JsonValue::Array(tool_results));
            current_messages.push(JsonValue::Object(user_msg));
        }
    }
    for line in &printed_lines { println!("{}", line); }
    println!("usage input={} output={} cache_read={}", total_input_tokens, total_output_tokens, total_cache_read_tokens);
}

import Foundation

/// Helper to read a 16-bit unsigned little-endian integer from Data
func readUInt16(data: Data, offset: Int) -> UInt16 {
    return UInt16(data[offset]) | (UInt16(data[offset + 1]) << 8)
}

/// Helper to read a 32-bit unsigned little-endian integer from Data
func readUInt32(data: Data, offset: Int) -> UInt32 {
    return UInt32(data[offset]) | (UInt32(data[offset + 1]) << 8) | (UInt32(data[offset + 2]) << 16) | (UInt32(data[offset + 3]) << 24)
}

/// Helper to read a 16-bit signed little-endian integer from Data
func readInt16(data: Data, offset: Int) -> Int16 {
    let val = UInt16(data[offset]) | (UInt16(data[offset + 1]) << 8)
    return Int16(bitPattern: val)
}

func main() {
    let args = CommandLine.arguments
    guard args.count > 1 else { return }
    let dirPath = args[1]

    let fileManager = FileManager.default
    guard let files = try? fileManager.contentsOfDirectory(atPath: dirPath).filter({ $0.hasSuffix(".wav") }).sorted() else {
        return
    }

    let lowFreqs = [697.0, 770.0, 852.0, 941.0]
    let highFreqs = [1209.0, 1336.0, 1477.0, 1633.0]
    let digitMap = [
        ["1", "2", "3", "A"],
        ["4", "5", "6", "B"],
        ["7", "8", "9", "C"],
        ["*", "0", "#", "D"]
    ]

    for (index, fileName) in files.enumerated() {
        if index > 0 {
            print("")
        }

        let filePath = (dirPath as NSString).appendingPathComponent(fileName)
        guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)) else {
            continue
        }

        // RIFF parsing
        if data.count < 12 {
            print("\(fileName): unsupported")
            continue
        }

        // Check RIFF header (4 bytes "RIFF", 4 bytes size, 4 bytes "WAVE")
        if data[0] != 82 || data[1] != 73 || data[2] != 70 || data[3] != 70 ||
           data[8] != 87 || data[9] != 65 || data[10] != 86 || data[11] != 69 {
            print("\(fileName): unsupported")
            continue
        }

        var offset = 12
        var fmtFound = false
        var dataFound = false
        var sampleRate: UInt32 = 0
        var channels: UInt16 = 0
        var bitsPerSample: UInt16 = 0
        var effectiveFormat: UInt16 = 0
        var dataOffset = 0
        var dataSize: UInt32 = 0

        // Parse chunks
        while offset + 8 <= data.count {
            let chunkId = String(data[offset..<offset+4].map { Character(UnicodeScalar($0)) })
            let chunkSize = Int(readUInt32(data: data, offset: offset + 4))

            if chunkId == "fmt " {
                fmtFound = true
                let tag = readUInt16(data: data, offset: offset + 8)
                channels = readUInt16(data: data, offset: offset + 10)
                sampleRate = readUInt32(data: data, offset: offset + 12)
                bitsPerSample = readUInt16(data: data, offset: offset + 22)

                effectiveFormat = tag
                // If WAVE_FORMAT_EXTENSIBLE, the effective format is at offset 24 of the fmt body
                if tag == 0xFFFE {
                    if offset + 8 + 24 + 1 <= data.count {
                        effectiveFormat = readUInt16(data: data, offset: offset + 8 + 24)
                    }
                }
            } else if chunkId == "data" {
                dataFound = true
                dataOffset = offset + 8
                dataSize = UInt32(chunkSize)
            }

            // Chunk size is n; if n is odd, there's one pad byte
            offset += 8 + chunkSize + (chunkSize % 2 != 0 ? 1 : 0)
        }

        // Validation: Effective format must be 1 (PCM) and bits per sample must be 16
        if !fmtFound || !dataFound || effectiveFormat != 1 || bitsPerSample != 16 {
            print("\(fileName): unsupported")
            continue
        }

        // Extract samples: signed 16-bit, interleaved, use only the first (left) channel
        let numFrames = Int(dataSize) / (2 * Int(channels))
        var leftSamples = [Int16]()
        leftSamples.reserveCapacity(numFrames)

        for i in 0..<numFrames {
            let samplePos = dataOffset + i * 2 * Int(channels)
            if samplePos + 1 < data.count {
                leftSamples.append(readInt16(data: data, offset: samplePos))
            }
        }

        let rate = Double(sampleRate)
        let N = Int(rate / 50.0) // 20ms block size
        let numBlocks = leftSamples.count / N

        var blockLabels = [String?]()

        for b in 0..<numBlocks {
            let start = b * N
            var energy: Double = 0
            for n in 0..<N {
                let x = Double(leftSamples[start + n])
                energy += x * x
            }

            // Condition 1: Energy threshold
            if energy < 1000000.0 * Double(N) {
                blockLabels.append(nil)
                continue
            }

            var maxRLow = -1.0
            var bestLowIdx = -1
            var maxRHigh = -1.0
            var bestHighIdx = -1

            // Goertzel for low group
            for (lowIdx, f) in lowFreqs.enumerated() {
                let c = 2.0 * cos(2.0 * .pi * f / rate)
                var s1 = 0.0
                var s2 = 0.0
                for n in 0..<N {
                    let s = Double(leftSamples[start + n]) + c * s1 - s2
                    s2 = s1
                    s1 = s
                }
                let P = s1 * s1 + s2 * s2 - c * s1 * s2
                let r = 2.0 * P / (Double(N) * energy)
                if r > maxRLow {
                    maxRLow = r
                    bestLowIdx = lowIdx
                }
            }

            // Goertzel for high group
            for (highIdx, f) in highFreqs.enumerated() {
                let c = 2.0 * cos(2.0 * .pi * f / rate)
                var s1 = 0.0
                var s2 = 0.0
                for n in 0..<N {
                    let s = Double(leftSamples[start + n]) + c * s1 - s2
                    s2 = s1
                    s1 = s
                }
                let P = s1 * s1 + s2 * s2 - c * s1 * s2
                let r = 2.0 * P / (Double(N) * energy)
                if r > maxRHigh {
                    maxRHigh = r
                    bestHighIdx = highIdx
                }
            }

            // Condition 3: Relative power thresholds
            if maxRLow >= 0.1 && maxRHigh >= 0.1 && (maxRLow + maxRHigh) >= 0.6 {
                blockLabels.append(digitMap[bestLowIdx][bestHighIdx])
            } else {
                blockLabels.append(nil)
            }
        }

        // Step 4: Bridging
        var bridgedLabels = blockLabels
        for i in 1..<blockLabels.count - 1 {
            if blockLabels[i] == nil {
                if let prev = blockLabels[i-1], let next = blockLabels[i+1], prev == next {
                    bridgedLabels[i] = prev
                }
            }
        }

        // Step 5: Events (Runs of >= 2 blocks)
        var events = [(digit: String, start: Int, end: Int)]()
        var i = 0
        while i < bridgedLabels.count {
            if let digit = bridgedLabels[i] {
                var j = i
                while j < bridgedLabels.count && bridgedLabels[j] == digit {
                    j += 1
                }
                if j - i >= 2 {
                    events.append((digit: digit, start: i * 20, end: j * 20))
                }
                i = j
            } else {
                i += 1
            }
        }

        // Output results
        print("\(fileName): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks")
        var allDigits = ""
        for event in events {
            print("\(event.digit) \(event.start) \(event.end)")
            allDigits += event.digit
        }
        print("digits: \(allDigits)")
    }
}

