import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File queriesFile = new File(dir, "queries.txt");
        if (!queriesFile.exists()) return;

        try (BufferedReader br = new BufferedReader(new FileReader(queriesFile))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                String[] parts = line.split(" ");
                if (parts.length < 3) continue;
                String type = parts[0];
                String filename = parts[1];
                TzifFile tzif = new TzifFile(new File(dir, filename));

                if ("UTC".equals(type)) {
                    long t = Long.parseLong(parts[2]);
                    TzType typeAtT = tzif.getTypeAt(t);
                    ZonedDateTime utc = ZonedDateTime.ofInstant(Instant.ofEpochSecond(t), ZoneOffset.UTC);
                    long offsetSecs = typeAtT.offset;
                    ZonedDateTime local = utc.minusSeconds(offsetSecs);
                    System.out.println(line + " -> " + formatLocal(local, offsetSecs) + " " + typeAtT.abbr);
                } else if ("LOCAL".equals(type)) {
                    String localStr = parts[2];
                    LocalDateTime ldt = LocalDateTime.parse(localStr);
                    List<Long> matches = new ArrayList<>();

                    // Try std and dst offsets from the footer/rules
                    long stdOff = tzif.footerRule.stdType.offset;
                    long dstOff = tzif.footerRule.dstType.offset;

                    long t1 = ldt.toEpochSecond(ZoneOffset.UTC) + stdOff;
                    long t2 = ldt.toEpochSecond(ZoneOffset.UTC) + dstOff;

                    if (isLocalTime(t1, ldt, tzif)) matches.add(t1);
                    if (t2 != t1 && isLocalTime(t2, ldt, tzif)) matches.add(t2);
                    Collections.sort(matches);

                    if (matches.size() == 1) {
                        long t = matches.get(0);
                        TzType typeAtT = tzif.getTypeAt(t);
                        System.out.println(line + " -> " + t + " " + formatOffset(typeAtT.offset) + " " + typeAtT.abbr);
                    } else if (matches.size() > 1) {
                        long t1_match = matches.get(0);
                        long t2_match = matches.get(1);
                        TzType type1 = tzif.getTypeAt(t1_match);
                        TzType type2 = tzif.getTypeAt(t2_match);
                        System.out.println(line + " -> " + t1_match + " " + formatOffset(type1.offset) + " " + type1.abbr + 
                                           " | " + t2_match + " " + formatOffset(type2.offset) + " " + type2.abbr);
                    } else {
                        // Gap: find offset before the transition that skipped this time
                        long tGap = ldt.toEpochSecond(ZoneOffset.UTC) + stdOff; // Default to std
                        // We need to find the transition that caused the gap.
                        // A gap happens when we switch from std to dst and the local time jumps forward.
                        // The offset before was stdOff (usually).
                        TzType typeBefore = tzif.getTypeAt(tGap - 1);
                        long tActual = ldt.toEpochSecond(ZoneOffset.UTC) + typeBefore.offset;
                        TzType typeActual = tzif.getTypeAt(tActual);
                        ZonedDateTime utcActual = ZonedDateTime.ofInstant(Instant.ofEpochSecond(tActual), ZoneOffset.UTC);
                        ZonedDateTime localActual = utcActual.minusSeconds(typeActual.offset);
                        System.out.println(line + " -> GAP " + tActual + " " + formatLocal(localActual, typeActual.offset) + " " + typeActual.abbr);
                    }
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static boolean isLocalTime(long t, LocalDateTime ldt, TzifFile tzif) {
        TzType type = tzif.getTypeAt(t);
        ZonedDateTime utc = ZonedDateTime.ofInstant(Instant.ofEpochSecond(t), ZoneOffset.UTC);
        ZonedDateTime local = utc.minusSeconds(type.offset);
        return local.toLocalDateTime().equals(ldt);
    }

    private static String formatLocal(ZonedDateTime local, long offsetSecs) {
        return local.format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")) + formatOffset(offsetSecs);
    }

    private static String formatOffset(long offsetSecs) {
        if (offsetSecs == 0) return "+00:00";
        boolean neg = offsetSecs < 0;
        long abs = Math.abs(offsetSecs);
        long h = abs / 3600;
        long m = (abs % 3600) / 60;
        long s = abs % 60;
        String res = (neg ? "-" : "+") + String.format("%02d:%02d", h, m);
        if (s != 0) res += ":" + String.format("%02d", s);
        return res;
    }

    static class TzifFile {
        long[] transitions;
        byte[] typeIndices;
        TzType[] types;
        TzRule footerRule;

        TzifFile(File file) throws IOException {
            byte[] data = Files.readAllBytes(file.toPath());
            ByteBuffer bb = ByteBuffer.wrap(data);

            // Skip first block
            bb.position(0);
            if (bb.getInt() != 0x545A6966) throw new IOException("Invalid TZif");
            bb.get(); // version
            bb.position(4);
            int isutcnt = bb.getInt();
            int isstdcnt = bb.getInt();
            int leapcnt = bb.getInt();
            int timecnt = bb.getInt();
            int typecnt = bb.getInt();
            int charcnt = bb.getInt();

            // Data block 1 size
            int block1Size = timecnt * 4 + timecnt * 1 + typecnt * 6 + charcnt + leapcnt * 8 + isstdcnt + isutcnt;
            bb.position(44 + block1Size);

            // Header 2
            if (bb.getInt() != 0x545A6966) throw new IOException("Invalid TZif Header 2");
            bb.get(); // version
            bb.position(bb.position() + 15);
            int isutcnt2 = bb.getInt();
            int isstdcnt2 = bb.getInt();
            int leapcnt2 = bb.getInt();
            int timecnt2 = bb.getInt();
            int typecnt2 = bb.getInt();
            int charcnt2 = bb.getInt();

            transitions = new long[timecnt2];
            for (int i = 0; i < timecnt2; i++) transitions[i] = bb.getLong();
            typeIndices = new byte[timecnt2];
            bb.get(typeIndices);

            types = new TzType[typecnt2];
            for (int i = 0; i < typecnt2; i++) {
                int offset = bb.getInt();
                int isdst = bb.get() & 0xFF;
                int abbrIdx = bb.get() & 0xFF;
                types[i] = new TzType(offset, isdst != 0, abbrIdx);
            }

            byte[] chars = new byte[charcnt2];
            bb.get(chars);
            for (TzType t : types) {
                int start = t.abbrIdx;
                int end = start;
                while (end < chars.length && chars[end] != 0) end++;
                t.abbr = new String(chars, start, end - start);
            }

            // Footer
            int pos = bb.position();
            while (pos < data.length && data[pos] != '\n') pos++;
            pos++; // skip \n
            StringBuilder sb = new StringBuilder();
            while (pos < data.length && data[pos] != '\n') {
                sb.append((char) data[pos++]);
            }
            footerRule = parsePosixTz(sb.toString());
        }

        TzType getTypeAt(long t) {
            int idx = Arrays.binarySearch(transitions, t);
            if (idx < 0) idx = -idx - 2;
            if (idx < 0) return types[0];
            if (idx >= transitions.length - 1) {
                return getFooterTypeAt(t);
            }
            return types[typeIndices[idx] & 0xFF];
        }

        TzType getFooterTypeAt(long t) {
            // Use the footer rule to determine if t is in DST
            long tLocal = t - footerRule.stdType.offset;
            ZonedDateTime zdt = ZonedDateTime.ofInstant(Instant.ofEpochSecond(tLocal), ZoneOffset.UTC);
            int year = zdt.getYear();

            long start = footerRule.getStartUnix(year);
            long end = footerRule.getEndUnix(year);

            boolean isDst;
            if (start < end) {
                isDst = (t >= start && t < end);
            } else {
                isDst = (t >= start || t < end);
            }

            // If the transition shifted the year, check neighbors
            if (!isDst) {
                for (int y : new int[]{year - 1, year + 1}) {
                    long s = footerRule.getStartUnix(y);
                    long e = footerRule.getEndUnix(y);
                    if (s < e) {
                        if (t >= s && t < e) return footerRule.dstType;
                    } else {
                        if (t >= s || t < e) return footerRule.dstType;
                    }
                }
            }

            return isDst ? footerRule.dstType : footerRule.stdType;
        }

        private TzRule getFooterTypeAtYear(long t, int year) {
            long start = footerRule.getStartUnix(year);
            long end = footerRule.getEndUnix(year);
            if (start < end) {
                return (t >= start && t < end) ? footerRule.dstType : footerRule.stdType;
            } else {
                return (t >= start || t < end) ? footerRule.dstType : footerRule.stdType;
            }
        }
    }

    static class TzType {
        int offset;
        boolean isDst;
        int abbrIdx;
        String abbr;
        TzType(int offset, boolean isDst, int abbrIdx) {
            this.offset = offset; this.isDst = isDst; this.abbrIdx = abbrIdx;
        }
    }

    static class TzRule {
        TzType stdType, dstType;
        Rule startRule, endRule;

        long getStartUnix(int year) {
            LocalDateTime ldt = startRule.getDate(year).atTime(LocalTime.MIDNIGHT).plusSeconds(startRule.timeOffset);
            return ldt.toEpochSecond(ZoneOffset.UTC) + stdType.offset;
        }

        long getEndUnix(int year) {
            LocalDateTime ldt = endRule.getDate(year).atTime(LocalTime.MIDNIGHT).plusSeconds(endRule.timeOffset);
            return ldt.toEpochSecond(ZoneOffset.UTC) + dstType.offset;
        }
    }

    static class Rule {
        int month, week, day;
        long timeOffset;
        LocalDate getDate(int year) {
            LocalDate first = LocalDate.of(year, month, 1);
            int firstDayOfWeek = first.getDayOfWeek().getValue() % 7;
            int daysUntilFirstD = (day - firstDayOfWeek + 7) % 7;
            LocalDate firstD = first.plusDays(daysUntilFirstD);
            if (week < 5) return firstD.plusWeeks(week - 1);
            LocalDate last = LocalDate.of(year, month, 1).withDayOfMonth(LocalDate.of(year, month, 1).lengthOfMonth());
            int lastDayOfWeek = last.getDayOfWeek().getValue() % 7;
            return last.minusDays((lastDayOfWeek - day + 7) % 7);
        }
    }

    private static TzRule parsePosixTz(String tz) {
        TzRule rule = new TzRule();
        String[] parts = tz.split(",");
        String stdDst = parts[0];

        // Parse std and dst
        int splitIdx = -1;
        if (stdDst.contains(">")) {
            int open = stdDst.indexOf('<');
            int close = stdDst.indexOf('>');
            if (open != -1 && close != -1) {
                // Check if there's another name after the offset
                String afterOffset = stdDst.substring(close + 1);
                // This is complex. Let's use a simpler heuristic for name/offset.
            }
        }

        // Better heuristic: a name is 3+ letters or <...>
        String stdName, stdOffStr, dstName, dstOffStr;
        if (stdDst.startsWith("<")) {
            int close = stdDst.indexOf('>');
            stdName = stdDst.substring(1, close);
            stdOffStr = stdDst.substring(close + 1);
        } else {
            int i = 0;
            while (i < stdDst.length() && Character.isLetter(stdDst.charAt(i))) i++;
            stdName = stdDst.substring(0, i);
            stdOffStr = stdDst.substring(i);
        }

        // Now find the DST part in stdOffStr
        int dstStart = -1;
        for (int i = 0; i < stdOffStr.length(); i++) {
            if (i >= 3 && Character.isLetter(stdOffStr.charAt(i))) {
                // Potential start of DST name
                int j = i;
                while (j < stdOffStr.length() && Character.isLetter(stdOffStr.charAt(j))) j++;
                if (j - i >= 3) {
                    dstStart = i;
                    break;
                }
            } else if (i < stdOffStr.length() && stdOffStr.charAt(i) == '<') {
                dstStart = i;
                break;
            }
        }

        if (dstStart == -1) {
            rule.stdType = new TzType(parseOffset(stdOffStr), false, 0);
            rule.dstType = new TzType(rule.stdType.offset - 3600, true, 0);
        } else {
            String sOff = stdOffStr.substring(0, dstStart);
            String dPart = stdOffStr.substring(dstStart);
            String dName, dOffStr;
            if (dPart.startsWith("<")) {
                int close = dPart.indexOf('>');
                dName = dPart.substring(1, close);
                dOffStr = dPart.substring(close + 1);
            } else {
                int i = 0;
                while (i < dPart.length() && Character.isLetter(dPart.charAt(i))) i++;
                dName = dPart.substring(0, i);
                dOffStr = dPart.substring(i);
            }
            rule.stdType = new TzType(parseOffset(sOff), false, 0);
            rule.dstType = new TzType(dOffStr.isEmpty() ? rule.stdType.offset - 3600 : parseOffset(dOffStr), true, 0);
        }

        if (parts.length > 1) {
            rule.startRule = parseRule(parts[1]);
            rule.endRule = parseRule(parts[2]);
        }
        return rule;
    }

    private static int parseOffset(String s) {
        if (s.isEmpty()) return 0;
        boolean neg = s.startsWith("-");
        if (s.startsWith("+") || s.startsWith("-")) s = s.substring(1);

        int h = 0, m = 0, sec = 0;
        String[] parts = s.split(":");
        h = Integer.parseInt(parts[0]);
        if (parts.length > 1) m = Integer.parseInt(parts[1]);
        if (parts.length > 2) sec = Integer.parseInt(parts[2]);

        long total = h * 3600L + m * 60L + sec;
        return (int) (neg ? -total : total);
    }

    private static Rule parseRule(String s) {
        Rule r = new Rule();
        String[] parts = s.split("/");
        String[] dateParts = parts[0].substring(1).split("\\.");
        r.month = Integer.parseInt(dateParts[0]);
        r.week = Integer.parseInt(dateParts[1]);
        r.day = Integer.parseInt(dateParts[2]);
        if (parts.length > 1) {
            r.timeOffset = parseOffset(parts[1]) * 1; // offset from midnight
            // The prompt says /time is [+-]hh:mm:ss, default 02:00:00
            // But my parseOffset handles it. Let's fix the default.
        } else {
            r.timeOffset = 2 * 3600;
        }

        // Special case: if the rule was just "2", it means 2 hours.
        // My parseOffset handles "2" as 2 hours.
        return r;
    }
}

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File queriesFile = new File(dir, "queries.txt");
        if (!queriesFile.exists()) return;

        try (BufferedReader br = new BufferedReader(new FileReader(queriesFile))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                String[] parts = line.split(" ");
                if (parts.length < 3) continue;
                String type = parts[0];
                String filename = parts[1];
                TzifFile tzif = new TzifFile(new File(dir, filename));

                if ("UTC".equals(type)) {
                    long t = Long.parseLong(parts[2]);
                    TzType typeAtT = tzif.getTypeAt(t);
                    ZonedDateTime utc = ZonedDateTime.ofInstant(Instant.ofEpochSecond(t), ZoneOffset.UTC);
                    ZonedDateTime local = utc.minusSeconds(typeAtT.offset);
                    System.out.println(line + " -> " + formatLocal(local, typeAtT.offset) + " " + typeAtT.abbr);
                } else if ("LOCAL".equals(type)) {
                    String localStr = parts[2];
                    LocalDateTime ldt = LocalDateTime.parse(localStr);
                    List<Long> matches = new ArrayList<>();

                    // To find all possible t for a given local time, we check all offsets present in the file.
                    Set<Integer> allOffsets = new HashSet<>();
                    for (TzType type : tzif.types) allOffsets.add(type.offset);
                    allOffsets.add(tzif.footerRule.stdType.offset);
                    allOffsets.add(tzif.footerRule.dstType.offset);

                    for (int off : allOffsets) {
                        long t = ldt.toEpochSecond(ZoneOffset.UTC) + off;
                        if (isLocalTime(t, ldt, tzif)) {
                            matches.add(t);
                        }
                    }
                    Collections.sort(matches);

                    if (matches.size() == 1) {
                        long t = matches.get(0);
                        TzType typeAtT = tzif.getTypeAt(t);
                        System.out.println(line + " -> " + t + " " + formatOffset(typeAtT.offset) + " " + typeAtT.abbr);
                    } else if (matches.size() > 1) {
                        long t1 = matches.get(0);
                        long t2 = matches.get(1);
                        TzType type1 = tzif.getTypeAt(t1);
                        TzType type2 = tzif.getTypeAt(t2);
                        System.out.println(line + " -> " + t1 + " " + formatOffset(type1.offset) + " " + type1.abbr + 
                                           " | " + t2 + " " + formatOffset(type2.offset) + " " + type2.abbr);
                    } else {
                        // Gap: find offset before the transition that skipped this time.
                        // We find the t that would have been the wall-clock time if the offset didn't change.
                        long tApprox = ldt.toEpochSecond(ZoneOffset.UTC);
                        // Search for the closest transition to find the offset before the jump.
                        TzType typeBefore = tzif.getTypeAt(tApprox - 86400); // Look back one day
                        long tActual = ldt.toEpochSecond(ZoneOffset.UTC) + typeBefore.offset;
                        TzType typeActual = tzif.getTypeAt(tActual);
                        ZonedDateTime utcActual = ZonedDateTime.ofInstant(Instant.ofEpochSecond(tActual), ZoneOffset.UTC);
                        ZonedDateTime localActual = utcActual.minusSeconds(typeActual.offset);
                        System.out.println(line + " -> GAP " + tActual + " " + formatLocal(localActual, typeActual.offset) + " " + typeActual.abbr);
                    }
                }
            }
        } catch (Exception e) {
            // Silently fail or handle error
        }
    }

    private static boolean isLocalTime(long t, LocalDateTime ldt, TzifFile tzif) {
        TzType type = tzif.getTypeAt(t);
        ZonedDateTime utc = ZonedDateTime.ofInstant(Instant.ofEpochSecond(t), ZoneOffset.UTC);
        ZonedDateTime local = utc.minusSeconds(type.offset);
        return local.toLocalDateTime().equals(ldt);
    }

    private static String formatLocal(ZonedDateTime local, long offsetSecs) {
        return local.format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")) + formatOffset(offsetSecs);
    }

    private static String formatOffset(long offsetSecs) {
        if (offsetSecs == 0) return "+00:00";
        boolean neg = offsetSecs < 0;
        long abs = Math.abs(offsetSecs);
        long h = abs / 3600;
        long m = (abs % 3600) / 60;
        long s = abs % 60;
        String res = (neg ? "-" : "+") + String.format("%02d:%02d", h, m);
        if (s != 0) res += ":" + String.format("%02d", s);
        return res;
    }

    static class TzifFile {
        long[] transitions;
        byte[] typeIndices;
        TzType[] types;
        TzRule footerRule;

        TzifFile(File file) throws IOException {
            byte[] data = Files.readAllBytes(file.toPath());
            ByteBuffer bb = ByteBuffer.wrap(data);

            bb.position(0);
            if (bb.getInt() != 0x545A6966) throw new IOException("Invalid TZif");
            bb.get(); // version
            bb.position(20);
            int timecnt1 = bb.getInt();
            int typecnt1 = bb.getInt();
            int charcnt1 = bb.getInt();

            // Skip first block
            int block1S = timecnt1 * 4 + timecnt1 * 1 + typecnt1 * 6 + charcnt1;
            // The header is 44 bytes. We need to account for isutcnt, isstdcnt, leapcnt.
            bb.position(0);
            bb.position(20);
            int isut1 = bb.getInt();
            int isstd1 = bb.getInt();
            int leap1 = bb.getInt();
            int tcnt1 = bb.getInt();
            int tycnt1 = bb.getInt();
            int ccnt1 = bb.getInt();
            int block1S_total = tcnt1 * 4 + tcnt1 + tycnt1 * 6 + ccnt1 + leap1 * 8 + isstd1 + isut1;
            bb.position(44 + block1S_total);

            if (bb.getInt() != 0x545A6966) throw new IOException("Invalid TZif Header 2");
            bb.get(); // version
            bb.position(bb.position() + 15);
            int isut2 = bb.getInt();
            int isstd2 = bb.getInt();
            int leap2 = bb.getInt();
            int timecnt2 = bb.getInt();
            int typecnt2 = bb.getInt();
            int charcnt2 = bb.getInt();

            transitions = new long[timecnt2];
            for (int i = 0; i < timecnt2; i++) transitions[i] = bb.getLong();
            typeIndices = new byte[timecnt2];
            bb.get(typeIndices);

            types = new TzType[typecnt2];
            for (int i = 0; i < typecnt2; i++) {
                int offset = bb.getInt();
                int isdst = bb.get() & 0xFF;
                int abbrIdx = bb.get() & 0xFF;
                types[i] = new TzType(offset, isdst != 0, abbrIdx);
            }

            byte[] chars = new byte[charcnt2];
            bb.get(chars);
            for (TzType t : types) {
                int start = t.abbrIdx;
                int end = start;
                while (end < chars.length && chars[end] != 0) end++;
                t.abbr = new String(chars, start, end - start);
            }

            int pos = bb.position();
            while (pos < data.length && data[pos] != '\n') pos++;
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < data.length && data[pos] != '\n') {
                sb.append((char) data[pos++]);
            }
            footerRule = parsePosixTz(sb.toString());
        }

        TzType getTypeAt(long t) {
            int idx = Arrays.binarySearch(transitions, t);
            if (idx < 0) idx = -idx - 2;
            if (idx < 0) return types[0];
            if (idx >= transitions.length - 1) {
                return getFooterTypeAt(t);
            }
            return types[typeIndices[idx] & 0xFF];
        }

        TzType getFooterTypeAt(long t) {
            int year = ZonedDateTime.ofInstant(Instant.ofEpochSecond(t), ZoneOffset.UTC).getYear();
            // Check current, previous, and next year to be safe.
            for (int y : new int[]{year, year - 1, year + 1}) {
                long s = footerRule.getStartUnix(y);
                long e = footerRule.getEndUnix(y);
                if (s < e) {
                    if (t >= s && t < e) return footerRule.dstType;
                } else {
                    if (t >= s || t < e) return footerRule.dstType;
                }
            }
            // If not in DST, use stdType.
            return footerRule.stdType;
        }
    }

    static class TzType {
        int offset;
        boolean isDst;
        int abbrIdx;
        String abbr;
        TzType(int offset, boolean isDst, int abbrIdx) {
            this.offset = offset; this.isDst = isDst; this.abbrIdx = abbrIdx;
        }
    }

    static class TzRule {
        TzType stdType, dstType;
        Rule startRule, endRule;

        long getStartUnix(int year) {
            LocalDateTime ldt = startRule.getDate(year).atTime(LocalTime.MIDNIGHT).plusSeconds(startRule.timeOffset);
            return ldt.toEpochSecond(ZoneOffset.UTC) + stdType.offset;
        }

        long getEndUnix(int year) {
            LocalDateTime ldt = endRule.getDate(year).atTime(LocalTime.MIDNIGHT).plusSeconds(endRule.timeOffset);
            return ldt.toEpochSecond(ZoneOffset.UTC) + dstType.offset;
        }
    }

    static class Rule {
        int month, week, day;
        long timeOffset;
        LocalDate getDate(int year) {
            LocalDate first = LocalDate.of(year, month, 1);
            int firstDayOfWeek = first.getDayOfWeek().getValue() % 7;
            int daysUntilFirstD = (day - firstDayOfWeek + 7) % 7;
            LocalDate firstD = first.plusDays(daysUntilFirstD);
            if (week < 5) return firstD.plusWeeks(week - 1);
            LocalDate last = first.withDayOfMonth(first.lengthOfMonth());
            int lastDayOfWeek = last.getDayOfWeek().getValue() % 7;
            return last.minusDays((lastDayOfWeek - day + 7) % 7);
        }
    }

    private static TzRule parsePosixTz(String tz) {
        TzRule rule = new TzRule();
        String[] parts = tz.split(",");
        String stdDst = parts[0];

        int dstStart = -1;
        for (int i = 0; i < stdDst.length(); i++) {
            if (i >= 3 && (Character.isLetter(stdDst.charAt(i)) || stdDst.charAt(i) == '<')) {
                if (stdDst.charAt(i) == '<') {
                    dstStart = i; break;
                } else {
                    int j = i;
                    while (j < stdDst.length() && Character.isLetter(stdDst.charAt(j))) j++;
                    if (j - i >= 3) { dstStart = i; break; }
                }
            }
        }

        if (dstStart == -1) {
            String stdOffStr = stdDst.substring(0, stdDst.length());
            // Remove name
            int nameEnd = 0;
            if (stdOffStr.startsWith("<")) {
                nameEnd = stdOffStr.indexOf('>') + 1;
            } else {
                while (nameEnd < stdOffStr.length() && Character.isLetter(stdOffStr.charAt(nameEnd))) nameEnd++;
            }
            rule.stdType = new TzType(parseOffset(stdOffStr.substring(nameEnd)), false, 0);
            rule.dstType = new TzType(rule.stdType.offset - 3600, true, 0);
        } else {
            String sPart = stdDst.substring(0, dstStart);
            String dPart = stdDst.substring(dstStart);
            int sNameEnd = 0;
            if (sPart.startsWith("<")) sNameEnd = sPart.indexOf('>') + 1;
            else while (sNameEnd < sPart.length() && Character.isLetter(sPart.charAt(sNameEnd))) sNameEnd++;
            rule.stdType = new TzType(parseOffset(sPart.substring(sNameEnd)), false, 0);

            int dNameEnd = 0;
            if (dPart.startsWith("<")) dNameEnd = dPart.indexOf('>') + 1;
            else while (dNameEnd < dPart.length() && Character.isLetter(dPart.charAt(dNameEnd))) dNameEnd++;
            String dOffStr = dPart.substring(dNameEnd);
            rule.dstType = new TzType(dOffStr.isEmpty() ? rule.stdType.offset - 3600 : parseOffset(dOffStr), true, 0);
        }

        if (parts.length > 1) {
            rule.startRule = parseRule(parts[1]);
            rule.endRule = parseRule(parts[2]);
        }
        return rule;
    }

    private static int parseOffset(String s) {
        if (s.isEmpty()) return 0;
        boolean neg = s.startsWith("-");
        if (s.startsWith("+") || s.startsWith("-")) s = s.substring(1);
        String[] parts = s.split(":");
        int h = Integer.parseInt(parts[0]);
        int m = parts.length > 1 ? Integer.parseInt(parts[1]) : 0;
        int sec = parts.length > 2 ? Integer.parseInt(parts[2]) : 0;
        long total = h * 3600L + m * 60L + sec;
        return (int) (neg ? -total : total);
    }

    private static Rule parseRule(String s) {
        Rule r = new Rule();
        String[] parts = s.split("/");
        String[] dateParts = parts[0].substring(1).split("\\.");
        r.month = Integer.parseInt(dateParts[0]);
        r.week = Integer.parseInt(dateParts[1]);
        r.day = Integer.parseInt(dateParts[2]);
        if (parts.length > 1) {
            r.timeOffset = parseOffset(parts[1]);
            // a simple offset like "/2" means 2 hours, but parseOffset handles that.
            // However, if it's just a number, it's hours.
            if (!parts[1].contains(":") && !parts[1].startsWith("+") && !parts[1].startsWith("-")) {
                r.timeOffset = Integer.parseInt(parts[1]) * 3600;
            }
        } else {
            r.timeOffset = 2 * 3600;
        }
        return r;
    }
}

use std::collections::HashMap;
use std::fs::File;
use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

fn parse_json(s: &str) -> JsonValue {
    let mut chars = s.chars().peekable();
    parse_value(&mut chars)
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
    match chars.next() {
        Some('{') => {
            let mut map = HashMap::new();
            loop {
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else {
                        break;
                    }
                }
                if let Some('}') = chars.peek() {
                    chars.next();
                    break;
                }
                let key = match parse_value(chars) {
                    JsonValue::String(s) => s,
                    _ => panic!("Expected string key"),
                };
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else {
                        break;
                    }
                }
                if let Some(':') = chars.peek() {
                    chars.next();
                }
                map.insert(key, parse_value(chars));
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else if c == ',' {
                        chars.next();
                        break;
                    } else {
                        break;
                    }
                }
                if let Some('}') = chars.peek() {
                    chars.next();
                    break;
                }
            }
            JsonValue::Object(map)
        }
        Some('[') => {
            let mut arr = Vec::new();
            loop {
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else {
                        break;
                    }
                }
                if let Some(']') = chars.peek() {
                    chars.next();
                    break;
                }
                arr.push(parse_value(chars));
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else if c == ',' {
                        chars.next();
                        break;
                    } else {
                        break;
                    }
                }
                if let Some(']') = chars.peek() {
                    chars.next();
                    break;
                }
            }
            JsonValue::Array(arr)
        }
        Some('"') => {
            let mut s = String::new();
            loop {
                match chars.next() {
                    Some('"') => break,
                    Some('\\') => match chars.next() {
                        Some('n') => s.push('\n'),
                        Some('r') => s.push('\r'),
                        Some('t') => s.push('\t'),
                        Some('b') => s.push('\x08'),
                        Some('f') => s.push('\x0c'),
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('u') => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                if let Some(c) = chars.next() {
                                    hex.push(c);
                                }
                            }
                            let code = u32::from_str_radix(&hex, 16).unwrap();
                            if (0xD800..=0xDBFF).contains(&code) {
                                if let Some('\\') = chars.next() {
                                    if let Some('u') = chars.next() {
                                        let mut hex2 = String::new();
                                        for _ in 0..4 {
                                            if let Some(c) = chars.next() {
                                                hex2.push(c);
                                            }
                                        }
                                        let code2 = u32::from_str_radix(&hex2, 16).unwrap();
                                        let cp = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                        s.push(std::char::from_u32(cp).unwrap());
                                    }
                                }
                            } else {
                                s.push(std::char::from_u32(code).unwrap());
                            }
                        }
                        _ => panic!("Invalid escape"),
                    },
                    Some(c) => s.push(c),
                    None => panic!("Unterminated string"),
                }
            }
            JsonValue::String(s)
        }
        Some('t') => {
            chars.next(); chars.next(); chars.next(); chars.next(); chars.next();
            JsonValue::Bool(true)
        }
        Some('f') => {
            chars.next(); chars.next(); chars.next(); chars.next(); chars.next();
            JsonValue::Bool(false)
        }
        Some('n') => {
            chars.next(); chars.next(); chars.next(); chars.next();
            JsonValue::Null
        }
        Some(c) if c.is_digit(10) || c == '-' => {
            let mut s = String::new();
            s.push(c);
            while let Some(&c) = chars.peek() {
                if c.is_digit(10) || c == '.' || c == '-' || c == 'e' || c == 'E' || c == '+' {
                    s.push(chars.next().unwrap());
                } else {
                    break;
                }
            }
            JsonValue::Number(s.parse().unwrap())
        }
        _ => panic!("Invalid JSON value"),
    }
}

fn serialize_json_value(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Number(n) => {
            if let Some(i) = n.to_string().strip_suffix(".0") {
                i.to_string()
            } else {
                n.to_string()
            }
        }
        JsonValue::String(s) => {
            let mut res = String::from("\"");
            for c in s.chars() {
                match c {
                    '"' => res.push_str("\\\""),
                    '\\' => res.push_str("\\\\"),
                    '\x08' => res.push_str("\\b"),
                    '\x0c' => res.push_str("\\f"),
                    '\n' => res.push_str("\\n"),
                    '\r' => res.push_str("\\r"),
                    '\t' => res.push_str("\\t"),
                    c if c < '\x20' => {
                        res.push_str(&format!("\\u{:04x}", c as u32));
                    }
                    _ => res.push(c),
                }
            }
            res.push('"');
            res
        }
        JsonValue::Array(arr) => {
            let mut res = String::from("[");
            for (i, v) in arr.iter().enumerate() {
                if i > 0 { res.push(','); }
                res.push_str(&serialize_json_value(v));
            }
            res.push(']');
            res
        }
        JsonValue::Object(map) => {
            let mut res = String::from("{");
            let mut first = true;
            for (k, v) in map {
                if !first { res.push(','); }
                res.push_str(&serialize_json_value(&JsonValue::String(k.clone())));
                res.push(':');
                res.push_str(&serialize_json_value(v));
                first = false;
            }
            res.push('}');
            res
        }
    }
}

fn serialize_json_compact(kvs: &[(&str, JsonValue)]) -> String {
    let mut res = String::from("{");
    for (i, (k, v)) in kvs.iter().enumerate() {
        if i > 0 { res.push(','); }
        res.push_str(&serialize_json_value(&JsonValue::String(k.to_string())));
        res.push(':');
        res.push_str(&serialize_json_value(v));
    }
    res.push('}');
    res
}

fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut chars = line.chars().peekable();
    loop {
        if let Some('"') = chars.peek() {
            chars.next();
            let mut field = String::new();
            loop {
                match chars.next() {
                    Some('"') => {
                        if let Some('"') = chars.peek() {
                            field.push('"');
                            chars.next();
                        } else {
                            break;
                        }
                    }
                    Some(c) => field.push(c),
                    None => break,
                }
            }
            fields.push(field);
        } else {
            let mut field = String::new();
            while let Some(&c) = chars.peek() {
                if c == ',' {
                    chars.next();
                    break;
                } else {
                    field.push(chars.next().unwrap());
                }
            }
            fields.push(field);
        }
        if chars.peek().is_none() {
            break;
        }
    }
    fields
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 { return; }
    let data_dir = &args[1];
    let base_url = &args[2];

    let mut task_file = File::open(format!("{}/task.json", data_dir)).unwrap();
    let mut task_content = String::new();
    task_file.read_to_string(&mut task_content).unwrap();
    let task = parse_json(&task_content);
    let task_obj = match &task {
        JsonValue::Object(o) => o,
        _ => panic!("task.json must be an object"),
    };

    let api_key = match task_obj.get("api_key") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("api_key missing"),
    };
    let model = match task_obj.get("model") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("model missing"),
    };
    let system_prompt = match task_obj.get("system") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("system missing"),
    };
    let user_prompt = match task_obj.get("user") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("user missing"),
    };
    let tools_def = task_obj.get("tools").cloned().unwrap();

    let mut inventory_file = File::open(format!("{}/inventory.csv", data_dir)).unwrap();
    let mut inventory_content = Vec::new();
    inventory_file.read_to_end(&mut inventory_content).unwrap();
    let mut inventory_str = String::from_utf8_lossy(&inventory_content).to_string();
    if inventory_str.starts_with("\u{feff}") {
        inventory_str = inventory_str[1..].to_string();
    }
    let lines: Vec<&str> = inventory_str.split("\r\n").collect();
    let header = parse_csv_line(lines[0]);
    let mut inventory_map = HashMap::new();
    for line in lines.iter().skip(1) {
        if line.is_empty() { continue; }
        let fields = parse_csv_line(line);
        let sku = fields[0].clone();
        let mut row = HashMap::new();
        for (i, h) in header.iter().enumerate() {
            let val = match *h {
                "price_cents" | "stock" => JsonValue::Number(fields[i].parse().unwrap()),
                _ => JsonValue::String(fields[i].clone()),
            };
            row.insert(h.to_string(), val);
        }
        inventory_map.insert(sku, row);
    }

    let mut rates_file = File::open(format!("{}/rates.json", data_dir)).unwrap();
    let mut rates_content = String::new();
    rates_file.read_to_string(&mut rates_content).unwrap();
    let rates_json = parse_json(&rates_content);
    let rates_obj = match &rates_json {
        JsonValue::Object(o) => o,
        _ => panic!("rates.json must be an object"),
    };
    let rates_map = match rates_obj.get("rates") {
        Some(JsonValue::Object(o)) => o,
        _ => panic!("rates missing"),
    };

    let mut messages = vec![
        JsonValue::Object({
            let mut m = HashMap::new();
            m.insert("role".to_string(), JsonValue::String("system".to_string()));
            m.insert("content".to_string(), JsonValue::String(system_prompt));
            m
        }),
        JsonValue::Object({
            let mut m = HashMap::new();
            m.insert("role".to_string(), JsonValue::String("user".to_string()));
            m.insert("content".to_string(), JsonValue::String(user_prompt));
            m
        }),
    ];

    let mut prompt_tokens_sum = 0;
    let mut completion_tokens_sum = 0;
    let mut total_tokens_sum = 0;
    let mut requests_count = 0;

    let (host, path_prefix) = if let Some(idx) = base_url.find("://") {
        let rest = &base_url[idx + 3..];
        if let Some(slash_idx) = rest.find('/') {
            (&rest[..slash_idx], &rest[slash_idx..])
        } else {
            (rest, "")
        }
    } else {
        panic!("Invalid URL");
    };

    loop {
        requests_count += 1;
        let mut body_map = HashMap::new();
        body_map.insert("model".to_string(), JsonValue::String(model.clone()));
        body_map.insert("messages".to_string(), JsonValue::Array(messages.clone()));
        body_map.insert("tools".to_string(), tools_def.clone());
        body_map.insert("tool_choice".to_string(), JsonValue::String("auto".to_string()));
        let body = serialize_json_value(&JsonValue::Object(body_map));

        let mut stream = TcpStream::connect(host).unwrap();
        let request = format!(
            "POST {}/chat/completions HTTP/1.1\r\nHost: {}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            path_prefix, host, api_key, body.len(), body
        );
        stream.write_all(request.as_bytes()).unwrap();

        let mut response = String::new();
        stream.read_to_string(&mut response).unwrap();
        let mut parts = response.splitn(2, "\r\n\r\n");
        let header_part = parts.next().unwrap();
        let body_part = parts.next().unwrap_or("");

        let status_line = header_part.lines().next().unwrap();
        let status_code = status_line.split_whitespace().nth(1).unwrap().parse::<u16>().unwrap();

        if status_code != 200 {
            let resp_json = parse_json(body_part);
            let err_msg = match &resp_json {
                JsonValue::Object(o) => match o.get("error") {
                    Some(JsonValue::Object(eo)) => match eo.get("message") {
                        Some(JsonValue::String(sm)) => sm.clone(),
                        _ => "Unknown error".to_string(),
                    },
                    _ => "Unknown error".to_string(),
                },
                _ => "Unknown error".to_string(),
            };
            println!("ERROR {} {}", status_code, err_msg);
            std::process::exit(0);
        }

        let resp_json = parse_json(body_part);
        let resp_obj = match &resp_json {
            JsonValue::Object(o) => o,
            _ => panic!("Response must be an object"),
        };

        let usage = match resp_obj.get("usage") {
            Some(JsonValue::Object(u)) => u,
            _ => panic!("Usage missing"),
        };
        prompt_tokens_sum += match usage.get("prompt_tokens") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 };
        completion_tokens_sum += match usage.get("completion_tokens") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 };
        total_tokens_sum += match usage.get("total_tokens") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 };

        let choices = match resp_obj.get("choices") {
            Some(JsonValue::Array(a)) => a,
            _ => panic!("Choices missing"),
        };
        let choice = &choices[0];
        let choice_obj = match choice {
            JsonValue::Object(o) => o,
            _ => panic!("Choice must be an object"),
        };

        let finish_reason = match choice_obj.get("finish_reason") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => panic!("finish_reason missing"),
        };
        let message = match choice_obj.get("message") {
            Some(JsonValue::Object(m)) => m,
            _ => panic!("message missing"),
        };

        if finish_reason == "stop" {
            let content = match message.get("content") {
                Some(JsonValue::String(s)) => s.clone(),
                _ => "".to_string(),
            };
            println!("FINAL {}", content);
            println!("USAGE prompt={} completion={} total={} requests={}", prompt_tokens_sum, completion_tokens_sum, total_tokens_sum, requests_count);
            break;
        } else if finish_reason == "tool_calls" {
            let content = match message.get("content") {
                Some(JsonValue::String(s)) => Some(s.clone()),
                _ => None,
            };
            if let Some(s) = content {
                println!("SAY {}", s);
            }

            let tool_calls = match message.get("tool_calls") {
                Some(JsonValue::Array(a)) => a,
                _ => panic!("tool_calls missing"),
            };

            messages.push(JsonValue::Object(message.clone()));

            for call in tool_calls {
                let call_obj = match call {
                    JsonValue::Object(o) => o,
                    _ => panic!("Tool call must be an object"),
                };
                let call_id = match call_obj.get("id") {
                    Some(JsonValue::String(s)) => s.clone(),
                    _ => panic!("call id missing"),
                };
                let func_obj = match call_obj.get("function") {
                    Some(JsonValue::Object(f)) => f,
                    _ => panic!("function missing"),
                };
                let func_name = match func_obj.get("name") {
                    Some(JsonValue::String(s)) => s.clone(),
                    _ => panic!("function name missing"),
                };
                let args_str = match func_obj.get("arguments") {
                    Some(JsonValue::String(s)) => s,
                    _ => panic!("arguments missing"),
                };
                println!("CALL {} {}", call_id, func_name);

                let args_json = parse_json(args_str);
                let args_obj = match args_json {
                    JsonValue::Object(o) => o,
                    _ => panic!("arguments must be an object"),
                };

                let result = if func_name == "inventory_lookup" {
                    let sku = match args_obj.get("sku") {
                        Some(JsonValue::String(s)) => s,
                        _ => panic!("sku missing"),
                    };
                    if let Some(row) = inventory_map.get(sku) {
                        let kvs = [
                            ("sku", row.get("sku").unwrap().clone()),
                            ("name", row.get("name").unwrap().clone()),
                            ("price_cents", row.get("price_cents").unwrap().clone()),
                            ("currency", row.get("currency").unwrap().clone()),
                            ("stock", row.get("stock").unwrap().clone()),
                        ];
                        serialize_json_compact(&kvs)
                    } else {
                        serialize_json_compact(&[("error", JsonValue::String(format!("unknown sku: {}", sku)))])
                    }
                } else if func_name == "convert_currency" {
                    let amount_cents = match args_obj.get("amount_cents") {
                        Some(JsonValue::Number(n)) => *n as i64,
                        _ => panic!("amount_cents missing"),
                    };
                    let from = match args_obj.get("from") {
                        Some(JsonValue::String(s)) => s,
                        _ => panic!("from missing"),
                    };
                    let to = match args_obj.get("to") {
                        Some(JsonValue::String(s)) => s,
                        _ => panic!("to missing"),
                    };
                    let rate_from = match rates_map.get(from) {
                        Some(JsonValue::Number(n)) => *n as i64,
                        _ => panic!("rate missing"),
                    };
                    let rate_to = match rates_map.get(to) {
                        Some(JsonValue::Number(n)) => *n as i64,
                        _ => panic!("rate missing"),
                    };
                    let converted = (2 * amount_cents * rate_to + rate_from) / (2 * rate_from);
                    serialize_json_compact(&[
                        ("amount_cents", JsonValue::Number(converted as f64)),
                        ("currency", JsonValue::String(to.to_string())),
                    ])
                } else {
                    serialize_json_compact(&[("error", JsonValue::String(format!("unknown tool: {}", func_name)))])
                };
                println!("RESULT {} {}", call_id, result);
                messages.push(JsonValue::Object({
                    let mut m = HashMap::new();
                    m.insert("role".to_string(), JsonValue::String("tool".to_string()));
                    m.insert("tool_call_id".to_string(), JsonValue::String(call_id));
                    m.insert("content".to_string(), JsonValue::String(result));
                    m
                }));
            }
        } else {
            panic!("Unexpected finish_reason: {}", finish_reason);
        }
    }
}

use std::collections::HashMap;
use std::fs::File;
use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

fn parse_json(s: &str) -> JsonValue {
    let mut chars = s.chars().peekable();
    parse_value(&mut chars)
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> JsonValue {
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
    match chars.next() {
        Some('{') => {
            let mut map = HashMap::new();
            loop {
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else {
                        break;
                    }
                }
                if let Some('}') = chars.peek() {
                    chars.next();
                    break;
                }
                let key = match parse_value(chars) {
                    JsonValue::String(s) => s,
                    _ => panic!("Expected string key"),
                };
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else if c == ':' {
                        chars.next();
                        break;
                    } else {
                        break;
                    }
                }
                map.insert(key, parse_value(chars));
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else if c == ',' {
                        chars.next();
                        break;
                    } else {
                        break;
                    }
                }
                if let Some('}') = chars.peek() {
                    chars.next();
                    break;
                }
            }
            JsonValue::Object(map)
        }
        Some('[') => {
            let mut arr = Vec::new();
            loop {
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else {
                        break;
                    }
                }
                if let Some(']') = chars.peek() {
                    chars.next();
                    break;
                }
                arr.push(parse_value(chars));
                while let Some(&c) = chars.peek() {
                    if c.is_whitespace() {
                        chars.next();
                    } else if c == ',' {
                        chars.next();
                        break;
                    } else {
                        break;
                    }
                }
                if let Some(']') = chars.peek() {
                    chars.next();
                    break;
                }
            }
            JsonValue::Array(arr)
        }
        Some('"') => {
            let mut s = String::new();
            loop {
                match chars.next() {
                    Some('"') => break,
                    Some('\\') => match chars.next() {
                        Some('n') => s.push('\n'),
                        Some('r') => s.push('\r'),
                        Some('t') => s.push('\t'),
                        Some('b') => s.push('\x08'),
                        Some('f') => s.push('\x0c'),
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('u') => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                if let Some(c) = chars.next() { hex.push(c); }
                            }
                            let code = u32::from_str_radix(&hex, 16).unwrap();
                            if (0xD800..=0xDBFF).contains(&code) {
                                if let Some('\\') = chars.next() {
                                    if let Some('u') = chars.next() {
                                        let mut hex2 = String::new();
                                        for _ in 0..4 {
                                            if let Some(c) = chars.next() { hex2.push(c); }
                                        }
                                        let code2 = u32::from_str_radix(&hex2, 16).unwrap();
                                        let cp = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00);
                                        s.push(std::char::from_u32(cp).unwrap());
                                    }
                                }
                            } else {
                                s.push(std::char::from_u32(code).unwrap());
                            }
                        }
                        _ => panic!("Invalid escape"),
                    },
                    Some(c) => s.push(c),
                    None => panic!("Unterminated string"),
                }
            }
            JsonValue::String(s)
        }
        Some('t') => {
            for _ in 0..4 { chars.next(); }
            JsonValue::Bool(true)
        }
        Some('f') => {
            for _ in 0..4 { chars.next(); }
            JsonValue::Bool(false)
        }
        Some('n') => {
            for _ in 0..3 { chars.next(); }
            JsonValue::Null
        }
        Some(c) if c.is_digit(10) || c == '-' => {
            let mut s = String::new();
            s.push(c);
            while let Some(&c) = chars.peek() {
                if c.is_digit(10) || c == '.' || c == '-' || c == 'e' || c == 'E' || c == '+' {
                    s.push(chars.next().unwrap());
                } else {
                    break;
                }
            }
            JsonValue::Number(s.parse().unwrap())
        }
        _ => panic!("Invalid JSON value"),
    }
}

fn serialize_json_value(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Number(n) => {
            if let Some(i) = n.to_string().strip_suffix(".0") {
                i.to_string()
            } else {
                n.to_string()
            }
        }
        JsonValue::String(s) => {
            let mut res = String::from("\"");
            for c in s.chars() {
                match c {
                    '"' => res.push_str("\\\""),
                    '\\' => res.push_str("\\\\"),
                    '\x08' => res.push_str("\\b"),
                    '\x0c' => res.push_str("\\f"),
                    '\n' => res.push_str("\\n"),
                    '\r' => res.push_str("\\r"),
                    '\t' => res.push_str("\\t"),
                    c if c < '\x20' => {
                        res.push_str(&format!("\\u{:04x}", c as u32));
                    }
                    _ => res.push(c),
                }
            }
            res.push('"');
            res
        }
        JsonValue::Array(arr) => {
            let mut res = String::from("[");
            for (i, v) in arr.iter().enumerate() {
                if i > 0 { res.push(','); }
                res.push_str(&serialize_json_value(v));
            }
            res.push(']');
            res
        }
        JsonValue::Object(map) => {
            let mut res = String::from("{");
            let mut first = true;
            let mut keys: Vec<_> = map.keys().collect();
            keys.sort();
            for k in keys {
                if !first { res.push(','); }
                res.push_str(&serialize_json_value(&JsonValue::String(k.clone())));
                res.push(':');
                res.push_str(&serialize_json_value(map.get(k).unwrap()));
                first = false;
            }
            res.push('}');
            res
        }
    }
}

fn serialize_json_compact(kvs: &[(&str, JsonValue)]) -> String {
    let mut res = String::from("{");
    for (i, (k, v)) in kvs.iter().enumerate() {
        if i > 0 { res.push(','); }
        res.push_str(&serialize_json_value(&JsonValue::String(k.to_string())));
        res.push(':');
        res.push_str(&serialize_json_value(v));
    }
    res.push('}');
    res
}

fn parse_csv(content: &str) -> Vec<Vec<String>> {
    let mut records = Vec::new();
    let mut chars = content.chars().peekable();
    loop {
        let mut record = Vec::new();
        loop {
            let mut field = String::new();
            if let Some('"') = chars.peek() {
                chars.next();
                loop {
                    match chars.next() {
                        Some('"') => {
                            if let Some('"') = chars.peek() {
                                field.push('"');
                                chars.next();
                            } else {
                                break;
                            }
                        }
                        Some(c) => field.push(c),
                        None => break,
                    }
                }
            } else {
                while let Some(&c) = chars.peek() {
                    if c == ',' {
                        break;
                    } else {
                        field.push(chars.next().unwrap());
                    }
                }
            }
            record.push(field);
            if let Some(',') = chars.peek() {
                chars.next();
            } else {
                break;
            }
        }
        records.push(record);
        if let Some('\r') = chars.peek() {
            chars.next();
            if let Some('\n') = chars.peek() {
                chars.next();
            }
        } else if let Some('\n') = chars.peek() {
            chars.next();
        } else {
            break;
        }
    }
    records
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 { return; }
    let data_dir = &args[1];
    let base_url = &args[2];

    let mut task_file = File::open(format!("{}/task.json", data_dir)).unwrap();
    let mut task_content = String::new();
    task_file.read_to_string(&mut task_content).unwrap();
    let task = parse_json(&task_content);
    let task_obj = match &task {
        JsonValue::Object(o) => o,
        _ => panic!("task.json must be an object"),
    };

    let api_key = match task_obj.get("api_key") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("api_key missing"),
    };
    let model = match task_obj.get("model") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("model missing"),
    };
    let system_prompt = match task_obj.get("system") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("system missing"),
    };
    let user_prompt = match task_obj.get("user") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => panic!("user missing"),
    };
    let tools_def = task_obj.get("tools").cloned().unwrap();

    let mut inventory_file = File::open(format!("{}/inventory.csv", data_dir)).unwrap();
    let mut inventory_content = Vec::new();
    inventory_file.read_to_end(&mut inventory_content).unwrap();
    let mut inventory_str = String::from_utf8_lossy(&inventory_content).to_string();
    if inventory_str.starts_with("\u{feff}") {
        inventory_str = inventory_str[1..].to_string();
    }
    let records = parse_csv(&inventory_str);
    let header = &records[0];
    let mut inventory_map = HashMap::new();
    for record in records.iter().skip(1) {
        if record.is_empty() { continue; }
        let sku = record[0].clone();
        let mut row = HashMap::new();
        for (i, h) in header.iter().enumerate() {
            let val = match *h {
                "price_cents" | "stock" => JsonValue::Number(record[i].parse().unwrap()),
                _ => JsonValue::String(record[i].clone()),
            };
            row.insert(h.to_string(), val);
        }
        inventory_map.insert(sku, row);
    }

    let mut rates_file = File::open(format!("{}/rates.json", data_dir)).unwrap();
    let mut rates_content = String::new();
    rates_file.read_to_string(&mut rates_content).unwrap();
    let rates_json = parse_json(&rates_content);
    let rates_obj = match &rates_json {
        JsonValue::Object(o) => o,
        _ => panic!("rates.json must be an object"),
    };
    let rates_map = match rates_obj.get("rates") {
        Some(JsonValue::Object(o)) => o,
        _ => panic!("rates missing"),
    };

    let mut messages = vec![
        JsonValue::Object({
            let mut m = HashMap::new();
            m.insert("role".to_string(), JsonValue::String("system".to_string()));
            m.insert("content".to_string(), JsonValue::String(system_prompt));
            m
        }),
        JsonValue::Object({
            let mut m = HashMap::new();
            m.insert("role".to_string(), JsonValue::String("user".to_string()));
            m.insert("content".to_string(), JsonValue::String(user_prompt));
            m
        }),
    ];

    let mut prompt_tokens_sum = 0;
    let mut completion_tokens_sum = 0;
    let mut total_tokens_sum = 0;
    let mut requests_count = 0;

    let (host, path_prefix) = if let Some(idx) = base_url.find("://") {
        let rest = &base_url[idx + 3..];
        if let Some(slash_idx) = rest.find('/') {
            (&rest[..slash_idx], &rest[slash_idx..])
        } else {
            (rest, "")
        }
    } else {
        panic!("Invalid URL");
    };

    loop {
        requests_count += 1;
        let mut body_map = HashMap::new();
        body_map.insert("model".to_string(), JsonValue::String(model.clone()));
        body_map.insert("messages".to_string(), JsonValue::Array(messages.clone()));
        body_map.insert("tools".to_string(), tools_def.clone());
        body_map.insert("tool_choice".to_string(), JsonValue::String("auto".to_string()));
        let body = serialize_json_value(&JsonValue::Object(body_map));

        let mut stream = TcpStream::connect(host).unwrap();
        let request = format!(
            "POST {}/chat/completions HTTP/1.1\r\nHost: {}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            path_prefix, host, api_key, body.len(), body
        );
        stream.write_all(request.as_bytes()).unwrap();

        let mut response = String::new();
        stream.read_to_string(&mut response).unwrap();
        let mut parts = response.splitn(2, "\r\n\r\n");
        let header_part = parts.next().unwrap();
        let body_part = parts.next().unwrap_or("");

        let status_line = header_part.lines().next().unwrap();
        let status_code = status_line.split_whitespace().nth(1).unwrap().parse::<u16>().unwrap();

        if status_code != 200 {
            let resp_json = parse_json(body_part);
            let err_msg = match &resp_json {
                JsonValue::Object(o) => match o.get("error") {
                    Some(JsonValue::Object(eo)) => match eo.get("message") {
                        Some(JsonValue::String(sm)) => sm.clone(),
                        _ => "Unknown error".to_string(),
                    },
                    _ => "Unknown error".to_string(),
                },
                _ => "Unknown error".to_string(),
            };
            println!("ERROR {} {}", status_code, err_msg);
            std::process::exit(0);
        }

        let resp_json = parse_json(body_part);
        let resp_obj = match &resp_json {
            JsonValue::Object(o) => o,
            _ => panic!("Response must be an object"),
        };

        let usage = match resp_obj.get("usage") {
            Some(JsonValue::Object(u)) => u,
            _ => panic!("Usage missing"),
        };
        prompt_tokens_sum += match usage.get("prompt_tokens") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 };
        completion_tokens_sum += match usage.get("completion_tokens") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 };
        total_tokens_sum += match usage.get("total_tokens") { Some(JsonValue::Number(n)) => *n as i64, _ => 0 };

        let choices = match resp_obj.get("choices") {
            Some(JsonValue::Array(a)) => a,
            _ => panic!("Choices missing"),
        };
        let choice = &choices[0];
        let choice_obj = match choice {
            JsonValue::Object(o) => o,
            _ => panic!("Choice must be an object"),
        };

        let finish_reason = match choice_obj.get("finish_reason") {
            Some(JsonValue::String(s)) => s.clone(),
            _ => panic!("finish_reason missing"),
        };
        let message = match choice_obj.get("message") {
            Some(JsonValue::Object(m)) => m,
            _ => panic!("message missing"),
        };

        if finish_reason == "stop" {
            let content = match message.get("content") {
                Some(JsonValue::String(s)) => s.clone(),
                _ => "".to_string(),
            };
            println!("FINAL {}", content);
            println!("USAGE prompt={} completion={} total={} requests={}", prompt_tokens_sum, completion_tokens_sum, total_tokens_sum, requests_count);
            break;
        } else if finish_reason == "tool_calls" {
            let content = match message.get("content") {
                Some(JsonValue::String(s)) => Some(s.clone()),
                _ => None,
            };
            if let Some(s) = content {
                println!("SAY {}", s);
            }

            let tool_calls = match message.get("tool_calls") {
                Some(JsonValue::Array(a)) => a,
                _ => panic!("tool_calls missing"),
            };

            messages.push(JsonValue::Object(message.clone()));

            for call in tool_calls {
                let call_obj = match call {
                    JsonValue::Object(o) => o,
                    _ => panic!("Tool call must be an object"),
                };
                let call_id = match call_obj.get("id") {
                    Some(JsonValue::String(s)) => s.clone(),
                    _ => panic!("call id missing"),
                };
                let func_obj = match call_obj.get("function") {
                    Some(JsonValue::Object(f)) => f,
                    _ => panic!("function missing"),
                };
                let func_name = match func_obj.get("name") {
                    Some(JsonValue::String(s)) => s.clone(),
                    _ => panic!("function name missing"),
                };
                let args_str = match func_obj.get("arguments") {
                    Some(JsonValue::String(s)) => s,
                    _ => panic!("arguments missing"),
                };
                println!("CALL {} {}", call_id, func_name);

                let args_json = parse_json(args_str);
                let args_obj = match args_json {
                    JsonValue::Object(o) => o,
                    _ => panic!("arguments must be an object"),
                };

                let result = if func_name == "inventory_lookup" {
                    let sku = match args_obj.get("sku") {
                        Some(JsonValue::String(s)) => s,
                        _ => panic!("sku missing"),
                    };
                    if let Some(row) = inventory_map.get(sku) {
                        let kvs = [
                            ("sku", row.get("sku").unwrap().clone()),
                            ("name", row.get("name").unwrap().clone()),
                            ("price_cents", row.get("price_cents").unwrap().clone()),
                            ("currency", row.get("currency").unwrap().clone()),
                            ("stock", row.get("stock").unwrap().clone()),
                        ];
                        serialize_json_compact(&kvs)
                    } else {
                        serialize_json_compact(&[("error", JsonValue::String(format!("unknown sku: {}", sku)))])
                    }
                } else if func_name == "convert_currency" {
                    let amount_cents = match args_obj.get("amount_cents") {
                        Some(JsonValue::Number(n)) => *n as i64,
                        _ => panic!("amount_cents missing"),
                    };
                    let from = match args_obj.get("from") {
                        Some(JsonValue::String(s)) => s,
                        _ => panic!("from missing"),
                    };
                    let to = match args_obj.get("to") {
                        Some(JsonValue::String(s)) => s,
                        _ => panic!("to missing"),
                    };
                    let rate_from = match rates_map.get(from) {
                        Some(JsonValue::Number(n)) => *n as i64,
                        _ => panic!("rate missing"),
                    };
                    let rate_to = match rates_map.get(to) {
                        Some(JsonValue::Number(n)) => *n as i64,
                        _ => panic!("rate missing"),
                    };
                    let converted = (2 * amount_cents * rate_to + rate_from) / (2 * rate_from);
                    serialize_json_compact(&[
                        ("amount_cents", JsonValue::Number(converted as f64)),
                        ("currency", JsonValue::String(to.to_string())),
                    ])
                } else {
                    serialize_json_compact(&[("error", JsonValue::String(format!("unknown tool: {}", func_name)))])
                };
                println!("RESULT {} {}", call_id, result);
                messages.push(JsonValue::Object({
                    let mut m = HashMap::new();
                    m.insert("role".to_string(), JsonValue::String("tool".to_string()));
                    m.insert("tool_call_id".to_string(), JsonValue::String(call_id));
                    m.insert("content".to_string(), JsonValue::String(result));
                    m
                }));
            }
        } else {
            panic!("Unexpected finish_reason: {}", finish_reason);
        }
    }
}

