    p += strlen(search);
    while (*p == ' ' || *p == '\"') p++;
    if (*p == '\"') {
        char *start = p;
        p++;
        while (*p && (*p != '\"' || (*p == '\"' && *(p + 1) == '\"'))) {
            if (*p == '\"' && *(p + 1) == '\"') p++;
            p++;
        }
        int len = p - start;
        char *res = malloc(len + 1);
        memcpy(res, start, len); // This is slightly wrong, it includes the opening quote
        // Corrected:
        return NULL; // Use a more robust parser
    }
    return NULL;
