// A more robust but simple JSON parser for the specific needs of this task
char *parse_json_string(const char *json, const char *key) {
    char search[128];
    snprintf(search, sizeof(search), "\"%s\"", key);
    char *p = strstr(json, search);
    if (!p) return NULL;
    p += strlen(search);
    while (*p && (*p == ' ' || *p == ':')) p++;
    if (*p != '\"') return NULL;
    p++;
    char *res = malloc(1024);
    int i = 0;
    while (*p && *p != '\"') {
        if (*p == '\\') {
            p++;
            if (*p == 'n') res[i++] = '\n';
            else if (*p == 'r') res[i++] = '\r';
            else if (*p == 't') res[i++] = '\t';
            else if (*p == 'b') res[i++] = '\b';
            else if (*p == 'f') res[i++] = '\f';
            else if (*p == '\"') res[i++] = '\"';
            else if (*p == '\\') res[i++] = '\\';
            else if (*p == 'u') {
                char hex[5];
                memcpy(hex, p + 1, 4);
                hex[4] = '\0';
                int val = (int)strtol(hex, NULL, 16);
                // Simplified UTF-8 encoding for BMP
                if (val < 128) res[i++] = (char)val;
                else if (val < 2048) {
                    res[i++] = (char)(0xC0 | (val >> 6));
                    res[i++] = (char)(0x80 | (val & 0x3F));
                } else {
                    res[i++] = (char)(0xE0 | (val >> 12));
                    res[i++] = (char)(0x80 | ((val >> 6) & 0x3F));
                    res[i++] = (char)(0x80 | (val & 0x3F));
                }
                p += 4;
            } else res[i++] = *p;
        } else res[i++] = *p;
        p++;
    }
    res[i] = '\0';
    return res;
}

long long parse_json_int(const char *json, const char *key) {
    char search[128];
    snprintf(search, sizeof(search), "\"%s\":", key);
    char *p = strstr(json, search);
    if (!p) return 0;
    p += strlen(search);
    while (*p && (*p == ' ' || *p == ':')) p++;
    return atoll(p);
}

char *json_escape(const char *s) {
    char *res = malloc(strlen(s) * 4 + 1);
    int i = 0, j = 0;
    while (s[i]) {
        unsigned char c = s[i];
        if (c == '\"') { res[j++] = '\\'; res[j++] = '\"'; }
        else if (c == '\\') { res[j++] = '\\'; res[j++] = '\\'; }
        else if (c == '\b') { res[j++] = '\\'; res[j++] = 'b'; }
        else if (c == '\f') { res[j++] = '\\'; res[j++] = 'f'; }
        else if (c == '\n') { res[j++] = '\\'; res[j++] = 'n'; }
        else if (c == '\r') { res[j++] = '\\'; res[j++] = 'r'; }
        else if (c == '\t') { res[j++] = '\\'; res[j++] = 't'; }
        else if (c < 32) {
            res[j++] = '\\'; res[j++] = 'u';
            char hex[3];
            snprintf(hex, 3, "%02x", c);
            res[j++] = hex[0]; res[j++] = hex[1];
        } else res[j++] = c;
        i++;
    }
    res[j] = '\0';
    return res;
}

char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(len + 1);
    fread(buf, 1, len, f);
    buf[len] = '\0';
    fclose(f);
    return buf;
}

char *csv_field(char **cursor) {
    if (!*cursor) return NULL;
    char *start = *cursor;
    if (**cursor == '\"') {
        (*cursor)++;
        while (**cursor) {
            if (**cursor == '\"' && *(*cursor + 1) == '\"') {
                (*cursor) += 2;
            } else if (**cursor == '\"') {
                (*cursor)++;
                break;
            } else (*cursor)++;
        }
        char *res = malloc(strlen(start) + 1);
        int i = 0, j = 0;
        char *p = start + 1;
        while (*p && *p != '\"') {
            if (*p == '\"' && *(p + 1) == '\"') {
                res[j++] = '\"';
                p += 2;
            } else {
                res[j++] = *p++;
            }
        }
        res[j] = '\0';
        if (**cursor == ',') (*cursor)++;
        else if (**cursor == '\n' || **cursor == '\r') {
            if (**cursor == '\r' && *(*cursor + 1) == '\n') (*cursor) += 2;
            else (*cursor)++;
        }
        return res;
    } else {
        while (**cursor && **cursor != ',' && **cursor != '\n' && **cursor != '\r') (*cursor)++;
        int len = *cursor - start;
        char *res = malloc(len + 1);
        memcpy(res, start, len);
        res[len] = '\0';
        if (**cursor == ',') (*cursor)++;
        else if (**cursor == '\n' || **cursor == '\r') {
            if (**cursor == '\r' && *(*cursor + 1) == '\n') (*cursor) += 2;
            else (*cursor)++;
        }
        return res;
    }
}

typedef struct {
    char *host;
    int port;
    char *path;
} URL;

URL parse_url(const char *url) {
    URL res = {NULL, 80, NULL};
    const char *p = url;
    if (strncmp(p, "http://", 7) == 0) p += 7;
    const char *end = strchr(p, '/');
    int host_len = end ? (int)(end - p) : (int)strlen(p);
    res.host = malloc(host_len + 1);
    memcpy(res.host, p, host_len);
    res.host[host_len] = '\0';
    if (end) {
        res.path = strdup(end);
    } else {
        res.path = strdup("");
    }
    char *port_p = strchr(res.host, ':');
    if (port_p) {
        res.port = atoi(port_p + 1);
        *port_p = '\0';
    }
    return res;
}

char *http_request(URL url, const char *api_key, const char *body, int *status) {
    struct addrinfo hints = {0}, *res;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    getaddrinfo(url.host, (char *)atoll(NULL), &hints, &res); // This is wrong, need port
    // Fixing port:
    char port_str[10];
    snprintf(port_str, 10, "%d", url.port);
    getaddrinfo(url.host, port_str, &hints, &res);

    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    connect(sock, res->ai_addr, res->ai_addrlen);

    char path[512];
    snprintf(path, sizeof(path), "%s/chat/completions", url.path);
    char req[8192];
    snprintf(req, sizeof(req), "POST %s HTTP/1.1\r\nHost: %s\r\nAuthorization: Bearer %s\r\nContent-Type: application/json\r\nContent-Length: %ld\r\nConnection: close\r\n\r\n%s",
             path, url.host, api_key, strlen(body), body);
    send(sock, req, strlen(req), 0);

    char buf[16384], response[16384];
    int bytes_read = 0, total_read = 0;
    while ((bytes_read = recv(sock, buf, sizeof(buf) - 1, 0)) > 0) {
        memcpy(response + total_read, buf, bytes_read);
        total_read += bytes_read;
    }
    response[total_read] = '\0';
    close(sock);
    free(res);

    sscanf(response, "HTTP/1.1 %d", status);
    char *body_start = strstr(response, "\r\n\r\n");
    return body_start ? strdup(body_start + 4) : NULL;
}

