char *json_escape(const char *s) {
    if (!s) return strdup("null");
    int len = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] == '\"' || s[i] == '\\') len += 2;
        else if (s[i] == '\b') len += 2;
        else if (s[i] == '\f') len += 2;
        else if (s[i] == '\n') len += 2;
        else if (s[i] == '\r') len += 2;
        else if (s[i] == '\t') len += 2;
        else if ((unsigned char)s[i] < 32) len += 6;
        else len++;
    }
    char *res = malloc(len + 1);
    int j = 0;
    for (int i = 0; s[i]; i++) {
        unsigned char c = s[i];
        if (c == '\"') { res[j++] = '\\'; res[j++] = '\"'; }
        else if (c == '\\') { res[j++] = '\\'; res[j++] = '\\'; }
        else if (c == '\b') { res[j++] = '\\'; res[j++] = 'b'; }
        else if (c == '\f') { res[j++] = '\\'; res[j++] = 'f'; }
        else if (c == '\n') { res[j++] = '\\'; res[j++] = 'n'; }
        else if (c == '\r') { res[j++] = '\\'; res[j++] = 'r'; }
        else if (c == '\t') { res[j++] = '\\'; res[j++] = 't'; }
        else if (c < 32) {
            res[j++] = '\\'; res[j++] = 'u';
            sprintf(&res[j], "%02x", c);
            j += 4;
        } else res[j++] = c;
    }
    res[j] = '\0';
    return res;
}

char *json_parse_string(const char *json, const char *key) {
    char search[128];
    snprintf(search, sizeof(search), "\"%s\"", key);
    char *p = strstr(json, search);
    if (!p) return NULL;
    p += strlen(search);
    while (*p && (*p == ' ' || *p == ':' || *p == '\"')) p++;
    if (!*p) return NULL;
    char *start = p;
    p++;
    while (*p) {
        if (*p == '\\' && *(p + 1)) p += 2;
        else if (*p == '\"') break;
        else p++;
    }
    int len = p - start;
    char *res = malloc(len + 1);
    int j = 0;
    char *s = start;
    while (s < p) {
        if (*s == '\\' && *(s + 1)) {
            char next = *(s + 1);
            if (next == '\"') res[j++] = '\"';
            else if (next == '\\') res[j++] = '\\';
            else if (next == '/') res[j++] = '/';
            else if (next == 'b') res[j++] = '\b';
            else if (next == 'f') res[j++] = '\f';
            else if (next == 'n') res[j++] = '\n';
            else if (next == 'r') res[j++] = '\r';
