char *http_request(const char *url_str, const char *api_key, const char *body, int *status) {
    char host[256], path[1024], port_str[10] = "80";
    const char *p = url_str;
    if (strncmp(p, "http://", 7) == 0) p += 7;
    const char *slash = strchr(p, '/');
    int host_len = slash ? (int)(slash - p) : (int)strlen(p);
    memcpy(host, p, host_len);
    host[host_len] = '\0';
    char *colon = strchr(host, ':');
    if (colon) {
        *colon = '\0';
        strcpy(port_str, colon + 1);
    }
    strcpy(path, slash ? slash : "");
    strcat(path, "/chat/completions");

    struct addrinfo hints = {0}, *res;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    getaddrinfo(host, port_str, &hints, &res);
    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    connect(sock, res->ai_addr, res->ai_addrlen);
    free(res);

    char req[16384];
    snprintf(req, sizeof(req), "POST %s HTTP/1.1\r\nHost: %s\r\nAuthorization: Bearer %s\r\nContent-Type: application/json\r\nContent-Length: %ld\r\nConnection: close\r\n\r\n%s",
             path, host, api_key, strlen(body), body);
    send(sock, req, strlen(req), 0);

    char buf[4096], response[65536];
    int bytes_read, total_read = 0;
    while ((bytes_read = recv(sock, buf, sizeof(buf) - 1, 0)) > 0) {
        memcpy(response + total_read, buf, bytes_read);
        total_read += bytes_read;
    }
    response[total_read] = '\0';
    close(sock);

    sscanf(response, "HTTP/1.1 %d", status);
    char *body_start = strstr(response, "\r\n\r\n");
    return body_start ? strdup(body_start + 4) : strdup("");
}

