import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File[] files = dir.listFiles();
        if (files == null) return;

        Arrays.sort(files, (a, b) -> a.getName().compareTo(b.getName()));

        for (File f : files) {
            if (f.getName().endsWith(".wav")) {
                processWav(f);
                System.out.println();
            }
        }
    }

    private static void processWav(File file) {
        try {
            byte[] bytes = Files.readAllBytes(file.toPath());
            int pos = 0;
            if (bytes.length < 12) {
                System.out.println(file.getName() + ": unsupported");
                return;
            }

            String riff = new String(bytes, pos, 4); pos += 4;
            if (!riff.equals("RIFF")) {
                System.out.println(file.getName() + ": unsupported");
                return;
            }
            int riffSize = readIntLE(bytes, pos); pos += 4;
            String wave = new String(bytes, pos, 4); pos += 4;
            if (!wave.equals("WAVE")) {
                System.out.println(file.getName() + ": unsupported");
                return;
            }

            int channels = 0, rate = 0, bitsPerSample = 0;
            int effectiveFormat = 0;
            int dataStart = -1, dataSize = 0;

            while (pos < bytes.length) {
                if (pos + 8 > bytes.length) break;
                String chunkId = new String(bytes, pos, 4); pos += 4;
                int n = readIntLE(bytes, pos); pos += 4;

                if (chunkId.equals("fmt ")) {
                    if (pos + n > bytes.length) {
                        System.out.println(file.getName() + ": unsupported");
                        return;
                    }
                    int tag = readShortLE(bytes, pos) & 0xFFFF;
                    channels = readShortLE(bytes, pos + 2) & 0xFFFF;
                    rate = readIntLE(bytes, pos + 4);
                    bitsPerSample = readShortLE(bytes, pos + 14) & 0xFFFF;
                    effectiveFormat = tag;
                    if (tag == 0xFFFE) {
                        if (n < 26) {
                            System.out.println(file.getName() + ": unsupported");
                            return;
                        }
                        effectiveFormat = readShortLE(bytes, pos + 24) & 0xFFFF;
                    }
                } else if (chunkId.equals("data")) {
                    dataStart = pos;
                    dataSize = n;
                }
                pos += n;
                if (n % 2 != 0) pos++;
            }

            if (effectiveFormat != 1 || bitsPerSample != 16 || (rate != 8000 && rate != 16000) || (channels < 1 || channels > 2)) {
                System.out.println(file.getName() + ": unsupported");
                return;
            }

            int numFrames = dataSize / (2 * channels);
            int[] samples = new int[numFrames];
            for (int i = 0; i < numFrames; i++) {
                samples[i] = readShortLE(bytes, dataStart + i * 2 * channels);
            }

            int N = rate / 50;
            int numBlocks = numFrames / N;
            char[] labels = new char[numBlocks];

            double[] lowFreqs = {697, 770, 852, 941};
            double[] highFreqs = {1209, 1336, 1477, 1633};
            char[][] keypad = {
                {'1', '2', '3', 'A'},
                {'4', '5', '6', 'B'},
                {'7', '8', '9', 'C'},
                {'*', '0', '#', 'D'}
            };

            for (int i = 0; i < numBlocks; i++) {
                int start = i * N;
                long E = 0;
                for (int n = 0; n < N; n++) {
                    E += (long) samples[start + n] * samples[start + n];
                }

                if (E < 1000000L * N) {
                    labels[i] = ' ';
                } else {
                    double maxLowR = -1, maxHighR = -1;
                    int lowIdx = -1, highIdx = -1;

                    for (int fIdx = 0; fIdx < 4; fIdx++) {
                        double rL = calculateR(lowFreqs[fIdx], rate, N, samples, start, E);
                        if (rL > maxLowR) {
                            maxLowR = rL;
                            lowIdx = fIdx;
                        }
                        double rH = calculateR(highFreqs[fIdx], rate, N, samples, start, E);
                        if (rH > maxHighR) {
                            maxHighR = rH;
                            highIdx = fIdx;
                        }
                    }

                    if (maxLowR >= 0.1 && maxHighR >= 0.1 && (maxLowR + maxHighR) >= 0.6) {
                        labels[i] = keypad[lowIdx][highIdx];
                    } else {
                        labels[i] = ' ';
                    }
                }
            }

            char[] bridged = labels.clone();
            for (int i = 1; i < numBlocks - 1; i++) {
                if (labels[i] == ' ' && labels[i - 1] != ' ' && labels[i - 1] == labels[i + 1]) {
                    bridged[i] = labels[i - 1];
                }
            }

            System.out.println(file.getName() + ": " + rate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
            StringBuilder digits = new StringBuilder();
            for (int i = 0; i < numBlocks; ) {
                if (bridged[i] == ' ') {
                    i++;
                    continue;
                }
                char digit = bridged[i];
                int start = i;
                while (i < numBlocks && bridged[i] == digit) i++;
                int end = i;
                if (end - start >= 2) {
                    System.out.println(digit + " " + (start * 20) + " " + (end * 20));
                    for (int k = 0; k < end - start; k++) digits.append(digit);
                }
            }
            System.out.println("digits: " + digits.toString());

        } catch (Exception e) {
            // Silently ignore or handle as unsupported
        }
    }

    private static double calculateR(double f, int rate, int N, int[] samples, int start, long E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * f / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[start + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }

    private static short readShortLE(byte[] b, int pos) {
        return (short) ((b[pos] & 0xFF) | ((b[pos + 1] & 0xFF) << 8));
    }

    private static int readIntLE(byte[] b, int pos) {
        return (b[pos] & 0xFF) | ((b[pos + 1] & 0xFF) << 8) | ((b[pos + 2] & 0xFF) << 16) | ((b[pos + 3] & 0xFF) << 24);
    }
}

