import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.Base64;

public class Main {
    public static void main(String[] args) {
        for (int i = 0; i < args.length; i++) {
            try {
                System.out.println("session " + (i + 1));
                new WebSocketSession(args[i]).run();
            } catch (Exception e) {
                // Errors are handled inside WebSocketSession, but this is a safety net
            }
        }
    }

    static class WebSocketSession {
        private final String url;
        private boolean isExpectingSha1 = false;
        private boolean hasSentClose = false;
        private final Random random = new Random();

        public WebSocketSession(String url) {
            this.url = url;
        }

        public void run() {
            try {
                String host = "";
                int port = -1;
                String path = "";

                // Parse ws://127.0.0.1:port/path
                int wsIdx = url.indexOf("://");
                String afterWs = url.substring(wsIdx + 3);
                int slashIdx = afterWs.indexOf('/');
                String hostPort = afterWs.substring(0, slashIdx);
                path = afterWs.substring(slashIdx);

                int colonIdx = hostPort.indexOf(':');
                host = hostPort.substring(0, colonIdx);
                port = Integer.parseInt(hostPort.substring(colonIdx + 1));

                try (Socket socket = new Socket(host, port)) {
                    InputStream in = socket.getInputStream();
                    OutputStream out = socket.getOutputStream();

                    // Handshake
                    byte[] keyBytes = new byte[16];
                    random.nextBytes(keyBytes);
                    String key = Base64.getEncoder().encodeToString(keyBytes);

                    PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out, StandardCharsets.US_ASCII)));
                    writer.print("GET " + path + " HTTP/1.1\r\n");
                    writer.print("Host: " + host + ":" + port + "\r\n");
                    writer.print("Upgrade: websocket\r\n");
                    writer.print("Connection: Upgrade\r\n");
                    writer.print("Sec-WebSocket-Version: 13\r\n");
                    writer.print("Sec-WebSocket-Key: " + key + "\r\n");
                    writer.print("\r\n");
                    writer.flush();

                    // Read response headers
                    ByteArrayOutputStream responseBuffer = new ByteArrayOutputStream();
                    while (true) {
                        int b = in.read();
                        if (b == -1) break;
                        responseBuffer.write(b);
                        if (responseBuffer.toString().endsWith("\r\n\r\n")) break;
                    }
                    String response = responseBuffer.toString();
                    String[] lines = response.split("\r\n");
                    String statusLine = lines[0];
                    String[] statusParts = statusLine.split(" ", 3);
                    int statusCode = Integer.parseInt(statusParts[1]);

                    if (statusCode != 101) {
                        System.out.println("handshake failed: " + statusLine.substring(statusLine.indexOf(" ") + 1));
                        return;
                    }

                    String acceptKey = "";
                    for (String line : lines) {
                        if (line.toLowerCase().startsWith("sec-websocket-accept:")) {
                            acceptKey = line.substring(line.indexOf(":") + 1).trim();
                        }
                    }

                    MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
                    sha1.update((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII));
                    String expectedAccept = Base64.getEncoder().encodeToString(sha1.digest());

                    if (!expectedAccept.equals(acceptKey)) {
                        System.out.println("handshake failed: bad Sec-WebSocket-Accept");
                        return;
                    }

                    // Frame loop
                    ByteArrayOutputStream messageAccumulator = new ByteArrayOutputStream();
                    int currentOpcode = -1;

                    while (true) {
                        int b1 = in.read();
                        if (b1 == -1) break;
                        boolean fin = (b1 & 0x80) != 0;
                        int opcode = b1 & 0x0F;

                        int b2 = in.read();
                        if (b2 == -1) break;
                        long payloadLen = b2 & 0x7F;
                        if (payloadLen == 126) {
                            payloadLen = (in.read() << 8) | (in.read() & 0xFF);
                        } else if (payloadLen == 127) {
                            payloadLen = 0;
                            for (int i = 0; i < 8; i++) {
                                payloadLen = (payloadLen << 8) | (in.read() & 0xFF);
                            }
                        }

                        byte[] payload = new byte[(int) payloadLen];
                        int readTotal = 0;
                        while (readTotal < payloadLen) {
                            int r = in.read(payload, readTotal, (int) payloadLen - readTotal);
                            if (r == -1) break;
                            readTotal += r;
                        }

                        if (opcode == 9) { // Ping
                            sendFrame(out, 10, payload);
                        } else if (opcode == 10) { // Pong
                            // Ignore
                        } else if (opcode == 8) { // Close
                            if (!hasSentClose) {
                                byte[] closeResp = new byte[2];
                                if (payload.length >= 2) {
                                    closeResp[0] = payload[0];
                                    closeResp[1] = payload[1];
                                } else {
                                    closeResp[0] = 0; closeResp[1] = 0;
                                }
                                sendFrame(out, 8, closeResp);
                            }
                            int code = (payload.length >= 2) ? ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF) : 0;
                            String reason = (payload.length > 2) ? new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8) : "";
                            if (reason.isEmpty()) {
                                System.out.println("closed " + code);
                            } else {
                                System.out.println("closed " + code + " " + reason);
                            }
                            break;
                        } else { // Data message (0, 1, 2)
                            if (currentOpcode == -1) currentOpcode = opcode;
                            messageAccumulator.write(payload);
                            if (fin) {
                                byte[] fullMessage = messageAccumulator.toByteArray();
                                if (isExpectingSha1) {
                                    MessageDigest md = MessageDigest.getInstance("SHA-1");
                                    md.update(fullMessage);
                                    byte[] digest = md.digest();
                                    StringBuilder hex = new StringBuilder();
                                    for (byte b : digest) hex.append(String.format("%02x", b));
                                    String hexS = hex.toString();
                                    sendFrame(out, 1, hexS.getBytes(StandardCharsets.UTF_8));
                                    System.out.println("SHA1 " + fullMessage.length + " -> " + hexS);
                                    isExpectingSha1 = false;
                                } else if (currentOpcode == 1) {
                                    String text = new String(fullMessage, StandardCharsets.UTF_8);
                                    handleCommand(out, text);
                                }
                                messageAccumulator.reset();
                                currentOpcode = -1;
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // Connection error
            }
        }

        private void handleCommand(OutputStream out, String text) throws IOException {
            if (text.startsWith("ADD ")) {
                String[] parts = text.substring(4).split(" ");
                long a = Long.parseLong(parts[0]);
                long b = Long.parseLong(parts[1]);
                String sum = String.valueOf(a + b);
                sendFrame(out, 1, sum.getBytes(StandardCharsets.UTF_8));
                System.out.println(text + " -> " + sum);
            } else if (text.startsWith("REV ")) {
                String content = text.substring(4);
                String reversed = new StringBuilder(content).reverse().toString();
                sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8));
                System.out.println(text + " -> " + reversed);
            } else if (text.equals("SHA1")) {
                isExpectingSha1 = true;
            } else if (text.equals("BYE")) {
                hasSentClose = true;
                sendFrame(out, 8, new byte[]{0x03, (byte) 0xE8});
            }
        }

        private void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
            out.write(0x80 | opcode);
            if (payload.length <= 125) {
                out.write(0x80 | payload.length);
            } else if (payload.length <= 65535) {
                out.write(0x80 | 126);
                out.write((payload.length >> 8) & 0xFF);
                out.write(payload.length & 0xFF);
            } else {
                out.write(0x80 | 127);
                for (int i = 7; i >= 0; i--) {
                    out.write((int) ((payload.length >> (8 * i)) & 0xFF));
                }
            }
            byte[] mask = new byte[4];
            do {
                random.nextBytes(mask);
            } while (mask[0] == 0 && mask[1] == 0 && mask[2] == 0 && mask[3] == 0);
            out.write(mask);
            for (int i = 0; i < payload.length; i++) {
                out.write(payload[i] ^ mask[i % 4]);
            }
            out.flush();
        }
    }
}

import Foundation

struct TZType {
    let offset: Int64
    let isdst: Bool
    let abbr: String
}

struct POSIXRule {
    let stdOffset: Int64
    let dstOffset: Int64
    let stdAbbr: String
    let dstAbbr: String?
    let startRule: (month: Int, week: Int, dayOfWeek: Int, timeOffset: Int64)?
    let endRule: (month: Int, week: Int, dayOfWeek: Int, timeOffset: Int64)?
}

class TZifFile {
    let transitions: [Int64]
    let typeIndices: [Int]
    let types: [TZType]
    let rule: POSIXRule

    init(data: Data, footer: String) {
        var offset = 44
        let isutcnt = Int(data[offset+0...offset+3].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        let isstdcnt = Int(data[offset+4...offset+7].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        let leapcnt = Int(data[offset+8...offset+11].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        let timecnt = Int(data[offset+12...offset+15].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        let typecnt = Int(data[offset+16...offset+19].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        let charcnt = Int(data[offset+20...offset+23].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })

        // Skip block 1
        let block1Size = 44 + timecnt * 4 + timecnt * 1 + typecnt * 6 + charcnt + leapcnt * 8 + isstdcnt + isutcnt
        offset += block1Size

        // Read block 2 header
        let h2Offset = offset
        let tcnt2 = Int(data[h2Offset+12...h2Offset+15].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        let tycnt2 = Int(data[h2Offset+16...h2Offset+19].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        let ccnt2 = Int(data[h2Offset+20...h2Offset+23].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })

        offset += 44
        var trans = [Int64]()
        for _ in 0..<tcnt2 {
            trans.append(Int64(data[offset...offset+7].withUnsafeBytes { $0.load(as: Int64.self).bigEndian }))
            offset += 8
        }

        var indices = [Int]()
        for _ in 0..<tcnt2 {
            indices.append(Int(data[offset]))
            offset += 1
        }

        var typeRecords = [TZType]()
        for _ in 0..<tycnt2 {
            let off = Int64(data[offset...offset+3].withUnsafeBytes { $0.load(as: Int32.self).bigEndian })
            let isdst = data[offset+4] != 0
            let abbrIdx = Int(data[offset+5])
            typeRecords.append(TZType(offset: off, isdst: isdst, abbr: "")) // Abbr filled later
            offset += 6
        }

        var abbrs = [String]()
        var currentAbbr = ""
        for _ in 0..<ccnt2 {
            let char = data[offset]
            offset += 1
            if char == 0 {
                abbrs.append(currentAbbr)
                currentAbbr = ""
            } else {
                currentAbbr.append(Character(UnicodeScalar(char)))
            }
        }
        if !currentAbbr.isEmpty { abbrs.append(currentAbbr) }

        let finalTypes = typeRecords.enumerated().map { (i, type) -> TZType in
            let idx = typeIndices.indices.contains(i) ? typeIndices[i] : i // This is a simplification
            // The prompt says type indices are provided. The actual type for a transition is typeIndices[i].
            return type
        }

        // Correct the types with abbreviations
        var correctedTypes = [TZType]()
        for tr in typeRecords {
            // We need to map the abbr index to the actual string
            // The prompt says "one byte index into the abbreviation characters"
            // This usually means the index of the NUL-terminated string.
            // But the TZif format actually stores abbreviations as a sequence of NUL-terminated strings.
            // The index is the index of the string in that sequence.
            // Let's just use the index.
        }

        // Re-mapping types to include abbreviations
        var typesWithAbbr = [TZType]()
        for tr in typeRecords {
            // Find the abbreviation at index tr.abbrIdx
            // Since we parsed all NUL-terminated strings into `abbrs` array:
            let abbr = (tr.abbr < abbrs.count) ? abbrs[tr.abbr] : "Unknown"
            typesWithAbbr.append(TZType(offset: tr.offset, isdst: tr.isdst, abbr: abbr))
        }

        self.transitions = trans
        self.typeIndices = indices
        self.types = typesWithAbbr
        self.rule = POSIXRule.parse(footer)
    }

    func getType(for t: Int64) -> TZType {
        if transitions.isEmpty || t < transitions[0] {
            return types[0]
        }
        if t > transitions.last! {
            return getTypeFromRule(t)
        }
        var low = 0, high = transitions.count - 1
        while low <= high {
            let mid = (low + high) / 2
            if transitions[mid] <= t {
                low = mid + 1
            } else {
                high = mid - 1
            }
        }
        let idx = typeIndices[high]
        return types[idx]
    }

    private func getTypeFromRule(_ t: Int64) -> TZType {
        let stdOff = rule.stdOffset
        let dstOff = rule.dstOffset

        // Estimate year
        let calendar = Calendar.current
        let date = Date(timeIntervalSince1970: TimeInterval(t - stdOff))
        let year = calendar.component(.year, from: date)

        let startT = getTransitionUnixTime(year: year, rule: rule.startRule, offset: stdOff)
        let endT = getTransitionUnixTime(year: year, rule: rule.endRule, offset: dstOff)

        let isDst: Bool
        if let s = startT, let e = endT {
            if s < e {
                isDst = (t >= s && t < e)
            } else {
                isDst = (t >= s || t < e)
            }
        } else {
            isDst = false
        }

        return isDst ? TZType(offset: dstOff, isdst: true, abbr: rule.dstAbbr ?? rule.stdAbbr) : TZType(offset: stdOff, isdst: false, abbr: rule.stdAbbr)
    }

    private func getTransitionUnixTime(year: Int, rule: (month: Int, week: Int, dayOfWeek: Int, timeOffset: Int64)?, offset: Int64) -> Int64? {
        guard let r = rule else { return nil }
        let calendar = Calendar.current
        var components = DateComponents()
        components.year = year
        components.month = r.month
        components.day = 1

        guard let firstOfMonth = calendar.date(from: components) else { return nil }

        var day = firstOfMonth
        while calendar.component(.weekday, from: day) != (r.dayOfWeek + 1) {
            day = calendar.date(byAdding: .day, value: 1, to: day)!
        }

        if r.week == 5 {
            while true {
                let nextDay = calendar.date(byAdding: .day, value: 7, to: day)!
                let nextMonth = calendar.component(.month, from: nextDay)
                if nextMonth != r.month { break }
                day = nextDay
            }
        } else {
            day = calendar.date(byAdding: .day, value: (r.week - 1) * 7, to: day)!
        }

        let midnight = calendar.startOfDay(for: day)
        let unixMidnight = Int64(midnight.timeIntervalSince1970)
        return unixMidnight + r.timeOffset - offset
    }
}

extension POSIXRule {
    static func parse(_ s: String) -> POSIXRule {
        let parts = s.split(separator: ",", omittingEmptySubsequences: false)
        let stdPart = String(parts[0])

        var cursor = stdPart.startIndex
        func readName() -> String {
            if cursor < stdPart.endIndex && stdPart[cursor] == "<" {
                cursor = stdPart.index(after: cursor)
                let start = cursor
                while cursor < stdPart.endIndex && stdPart[cursor] != ">" { cursor = stdPart.index(after: cursor) }
                let name = String(stdPart[start..<cursor])
                if cursor < stdPart.endIndex { cursor = stdPart.index(after: cursor) }
                return name
            } else {
                let start = cursor
                while cursor < stdPart.endIndex && stdPart[cursor].isLetter { cursor = stdPart.index(after: cursor) }
                return String(stdPart[start..<cursor])
            }
        }

        func readOffset() -> Int64? {
            if cursor >= stdPart.endIndex { return nil }
            let start = cursor
            if cursor < stdPart.endIndex && (stdPart[cursor] == "+" || stdPart[cursor] == "-") { cursor = stdPart.index(after: cursor) }
            while cursor < stdPart.endIndex && (stdPart[cursor].isNumber || stdPart[cursor] == ":") { cursor = stdPart.index(after: cursor) }
            let offStr = String(stdPart[start..<cursor])
            if offStr.isEmpty { return nil }
            return parseOffset(offStr)
        }

        let stdName = readName()
        let stdOff = readOffset() ?? 0
        let dstName = readName()
        let dstOff = readOffset() ?? (stdOff - 3600)

        func parseRule(_ rStr: String) -> (Int, Int, Int, Int64)? {
            let parts = rStr.split(separator: "/")
            let datePart = String(parts[0])
            let timeOff = parts.count > 1 ? parseOffset(String(parts[1])) : 0
            let dateComponents = datePart.split(separator: ".")
            if dateComponents.count < 3 { return nil }
            let m = Int(dateComponents[0].dropFirst()) ?? 0
            let w = Int(dateComponents[1]) ?? 0
            let d = Int(dateComponents[2]) ?? 0
            return (m, w, d, timeOff)
        }

        let startR = parts.count > 1 ? parseRule(String(parts[1])) : nil
        let endR = parts.count > 2 ? parseRule(String(parts[2])) : nil

        return POSIXRule(stdOffset: stdOff, dstOffset: dstOff, stdAbbr: stdName, dstAbbr: dstName.isEmpty ? nil : dstName, startRule: startR, endRule: endR)
    }

    static func parseOffset(_ s: String) -> Int64 {
        var sign: Int64 = 1
        var cursor = s.startIndex
        if cursor < s.endIndex && s[cursor] == "+" { sign = 1; cursor = s.index(after: cursor) }
        else if cursor < s.endIndex && s[cursor] == "-" { sign = -1; cursor = s.index(after: cursor) }

        let parts = s[cursor...].split(separator: ":")
        var totalSeconds: Int64 = 0
        if parts.count > 0 { totalSeconds += Int64(parts[0]) ?? 0 }
        if parts.count > 1 { totalSeconds += (Int64(parts[1]) ?? 0) * 60 }
        if parts.count > 2 { totalSeconds += (Int64(parts[2]) ?? 0) * 60 * 60 } // This is wrong, offsets are hh:mm:ss
        // Correction:
        var h: Int64 = 0, m: Int64 = 0, s_sec: Int64 = 0
        if parts.count > 0 { h = Int64(parts[0]) ?? 0 }
        if parts.count > 1 { m = Int64(parts[1]) ?? 0 }
        if parts.count > 2 { s_sec = Int64(parts[2]) ?? 0 }

        // The prompt says "EST5" means offset is 5 hours.
        // If there's only one number, it's hours.
        let total = (h * 3600) + (m * 60) + s_sec
        return sign * total
    }
}

func formatOffset(_ off: Int64) -> String {
    let absOff = abs(off)
    let h = absOff / 3600
    let m = (absOff % 3600) / 60
    let s = absOff % 60
    let sign = off >= 0 ? "+" : "-"
    if s == 0 {
        return String(format: "%@%02d:%02d", sign, h, m)
    } else {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    }
}

func formatLocal(_ t: Int64, _ offset: Int64) -> String {
    let date = Date(timeIntervalSince1970: TimeInterval(t - offset))
    let calendar = Calendar.current
    let y = calendar.component(.year, from: date)
    let m = calendar.component(.month, from: date)
    let d = calendar.component(.day, from: date)
    let h = calendar.component(.hour, from: date)
    let min = calendar.component(.minute, from: date)
    let s = calendar.component(.second, from: date)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d%@", y, m, d, h, min, s, formatOffset(offset))
}

func parseWallClock(_ w: String) -> Date {
    let formatter = DateFormatter()
    formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss"
    formatter.timeZone = TimeZone(secondsFromGMT: 0)
    return formatter.date(from: w)!
}

func main() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let dir = args[1]

    let queriesFile = URL(fileURLWithPath: dir).appendingPathComponent("queries.txt")
    guard let queries = try? String(contentsOf: queriesFile) else { return }

    var tzifCache = [String: TZifFile]()

    for line in queries.components(separatedBy: .newlines) {
        if line.trimmingCharacters(in: .whitespaces).isEmpty { continue }
        let parts = line.split(separator: " ")
        if parts.count < 3 { continue }

        let type = String(parts[0])
        let fileName = String(parts[1])

        if tzifCache[fileName] == nil {
            let fileURL = URL(fileURLWithPath: dir).appendingPathComponent(fileName)
            if let data = try? Data(contentsOf: fileURL) {
                let content = String(data: data, encoding: .utf8) ?? ""
                let footer = content.components(separatedBy: .newlines).filter { !$0.isEmpty }.last ?? ""
                tzifCache[fileName] = TZifFile(data: data, footer: footer)
            }
        }

        guard let tzif = tzifCache[fileName] else { continue }

        if type == "UTC" {
            let t = Int64(parts[2]) ?? 0
            let tzType = tzif.getType(for: t)
            print("\(line) -> \(formatLocal(t, tzType.offset)) \(tzType.abbr)")
        } else if type == "LOCAL" {
            let wStr = String(parts[2])
            let wDate = parseWallClock(wStr)
            let wUnix = Int64(wDate.timeIntervalSince1970)

            var possibleT = [Int64]()
            // Test potential offsets
            let offsetsToTry = [tzif.rule.stdOffset, tzif.rule.dstOffset]
            // Also try any transition offsets that might be relevant
            for tType in tzif.types {
                // This is a bit brute-force, but for the given range, it's okay.
                // In a real scenario, we'd only check offsets for the specific year.
            }

            // To be more precise, we only need to check offsets that could potentially
            // result in the given wall-clock time.
            var candidates = Set<Int64>()
            candidates.insert(tzif.rule.stdOffset)
            candidates.insert(tzif.rule.dstOffset)
            for ty in tzif.types { candidates.insert(ty.offset) }

            for off in candidates {
                let t = wUnix - off
                let resType = tzif.getType(for: t)
                if resType.offset == off {
                    possibleT.append(t)
                }
            }

            possibleT.sort()
            let uniqueT = Array(Set(possibleT)).sorted()

            if uniqueT.count == 1 {
                let t = uniqueT[0]
                let ty = tzif.getType(for: t)
                print("\(line) -> \(t) \(formatOffset(ty.offset)) \(ty.abbr)")
            } else if uniqueT.count > 1 {
                let t1 = uniqueT[0]
                let ty1 = tzif.getType(for: t1)
                let t2 = uniqueT[1]
                let ty2 = tzif.getType(for: t2)
                print("\(line) -> \(t1) \(formatOffset(ty1.offset)) \(ty1.abbr) | \(t2) \(formatOffset(ty2.offset)) \(ty2.abbr)")
            } else {
                // GAP: Find transition that caused it
                // Find the transition T_i such that Local(T_i - 1) < W < Local(T_i)
                var gapT: Int64 = 0
                var foundGap = false

                // Check transitions
                for i in 0..<tzif.transitions.count {
                    let t_i = tzif.transitions[i]
                    let off_prev = tzif.getType(for: t_i - 1).offset
                    let off_curr = tzif.getType(for: t_i).offset

                    let local_prev = t_i - 1 - off_prev
                    let local_curr = t_i - off_curr

                    if local_prev < wUnix && wUnix < local_curr {
                        gapT = wUnix - off_prev
                        foundGap = true
                        break
                    }
                }

                if !foundGap {
                    // Gap might be caused by the POSIX rule transition
                    // This is rarer but possible.
                    gapT = wUnix - tzif.rule.stdOffset // Fallback
                }

                let ty = tzif.getType(for: gapT)
                print("\(line) -> GAP \(gapT) \(formatLocal(gapT, ty.offset)) \(ty.abbr)")
            }
        }
    }
}

