import Foundation

struct TZType {
    let offset: Int64
    let isdst: Bool
    let abbr: String
}

struct POSIXRule {
    let stdOffset: Int64
    let dstOffset: Int64
    let stdAbbr: String
    let dstAbbr: String?
    let startRule: (month: Int, week: Int, dayOfWeek: Int, timeOffset: Int64)?
    let endRule: (month: Int, week: Int, dayOfWeek: Int, timeOffset: Int64)?
}

class TZifFile {
    let transitions: [Int64]
    let typeIndices: [Int]
    let types: [TZType]
    let rule: POSIXRule

    init(data: Data, footer: String) {
        var offset = 0

        func readUInt32() -> UInt32 {
            let val = data[offset..<offset+4].withUnsafeBytes { $0.load(as: UInt32.self).bigEndian }
            offset += 4
            return val
        }

        func readInt32() -> Int32 {
            let val = data[offset..<offset+4].withUnsafeBytes { $0.load(as: Int32.self).bigEndian }
            offset += 4
            return val
        }

        func readInt64() -> Int64 {
            let val = data[offset..<offset+8].withUnsafeBytes { $0.load(as: Int64.self).bigEndian }
            offset += 8
            return val
        }

        // Skip Block 1
        _ = readUInt32() // magic
        _ = readUInt32() // version
        offset += 12 // unused
        let isutcnt = Int(readUInt32())
        let isstdcnt = Int(readUInt32())
        let leapcnt = Int(readUInt32())
        let timecnt = Int(readUInt32())
        let typecnt = Int(readUInt32())
        let charcnt = Int(readUInt32())

        let block1Size = (timecnt * 4) + (timecnt * 1) + (typecnt * 6) + charcnt + (leapcnt * 8) + isstdcnt + isutcnt
        offset += block1Size

        // Read Block 2 Header
        _ = readUInt32() // magic
        _ = readUInt32() // version
        offset += 12 // unused
        let tcnt2 = Int(readUInt32())
        let tycnt2 = Int(readUInt32())
        let ccnt2 = Int(readUInt32())

        var trans = [Int64]()
        for _ in 0..<tcnt2 {
            trans.append(readInt64())
        }

        var indices = [Int]()
        for _ in 0..<tcnt2 {
            indices.append(Int(data[offset]))
            offset += 1
        }

        var typeRecords = [(offset: Int64, isdst: Bool, abbrIdx: Int)]()
        for _ in 0..<tycnt2 {
            let off = Int64(readInt32())
            let isdst = data[offset] != 0
            let abbrIdx = Int(data[offset+1])
            typeRecords.append((off, isdst, abbrIdx))
            offset += 2
        }

        var abbrs = [String]()
        var currentAbbr = ""
        for _ in 0..<ccnt2 {
            let char = data[offset]
            offset += 1
            if char == 0 {
                abbrs.append(currentAbbr)
                currentAbbr = ""
            } else {
                currentAbbr.append(Character(UnicodeScalar(char)))
            }
        }
        if !currentAbbr.isEmpty { abbrs.append(currentAbbr) }

        var finalTypes = [TZType]()
        for tr in typeRecords {
            let abbr = tr.abbrIdx < abbrs.count ? abbrs[tr.abbrIdx] : "Unknown"
            finalTypes.append(TZType(offset: tr.offset, isdst: tr.isdst, abbr: abbr))
        }

        self.transitions = trans
        self.typeIndices = indices
        self.types = finalTypes
        self.rule = POSIXRule.parse(footer)
    }

    func getType(for t: Int64) -> TZType {
        if transitions.isEmpty || t < transitions[0] {
            return types[0]
        }
        if t > transitions.last! {
            return getTypeFromRule(t)
        }
        var low = 0, high = transitions.count - 1
        while low <= high {
            let mid = (low + high) / 2
            if transitions[mid] <= t {
                low = mid + 1
            } else {
                high = mid - 1
            }
        }
        let idx = typeIndices[high]
        return types[idx]
    }

    private func getTypeFromRule(_ t: Int64) -> TZType {
        let stdOff = rule.stdOffset
        let dstOff = rule.dstOffset

        // Rough estimate of year using standard offset
        let date = Date(timeIntervalSince1970: TimeInterval(t - stdOff))
        let calendar = Calendar.current
        let year = calendar.component(.year, from: date)

        let startT = getTransitionUnixTime(year: year, rule: rule.startRule, offset: stdOff)
        let endT = getTransitionUnixTime(year: year, rule: rule.endRule, offset: dstOff)

        let isDst: Bool
        if let s = startT, let e = endT {
            if s < e {
                isDst = (t >= s && t < e)
            } else {
                isDst = (t >= s || t < e)
            }
        } else {
            isDst = false
        }

        return isDst ? TZType(offset: dstOff, isdst: true, abbr: rule.dstAbbr ?? rule.stdAbbr) : TZType(offset: stdOff, isdst: false, abbr: rule.stdAbbr)
    }

    private func getTransitionUnixTime(year: Int, rule: (month: Int, week: Int, dayOfWeek: Int, timeOffset: Int64)?, offset: Int64) -> Int64? {
        guard let r = rule else { return nil }
        let calendar = Calendar.current
        var components = DateComponents()
        components.year = year
        components.month = r.month
        components.day = 1

        guard let firstOfMonth = calendar.date(from: components) else { return nil }

        var day = firstOfMonth
        while calendar.component(.weekday, from: day) != (r.dayOfWeek + 1) {
            day = calendar.date(byAdding: .day, value: 1, to: day)!
        }

        if r.week == 5 {
            while true {
                let nextDay = calendar.date(byAdding: .day, value: 7, to: day)!
                if calendar.component(.month, from: nextDay) != r.month { break }
                day = nextDay
            }
        } else {
            day = calendar.date(byAdding: .day, value: (r.week - 1) * 7, to: day)!
        }

        let midnight = calendar.startOfDay(for: day)
        let unixMidnight = Int64(midnight.timeIntervalSince1970)
        return unixMidnight + r.timeOffset - offset
    }
}

extension POSIXRule {
    static func parse(_ s: String) -> POSIXRule {
        let parts = s.split(separator: ",", omittingEmptySubsequences: false)
        let stdPart = String(parts[0])

        var cursor = stdPart.startIndex
        func readName() -> String {
            if cursor < stdPart.endIndex && stdPart[cursor] == "<" {
                cursor = stdPart.index(after: cursor)
                let start = cursor
                while cursor < stdPart.endIndex && stdPart[cursor] != ">" { cursor = stdPart.index(after: cursor) }
                let name = String(stdPart[start..<cursor])
                if cursor < stdPart.endIndex { cursor = stdPart.index(after: cursor) }
                return name
            } else {
                let start = cursor
                while cursor < stdPart.endIndex && stdPart[cursor].isLetter { cursor = stdPart.index(after: cursor) }
                return String(stdPart[start..<cursor])
            }
        }

        func readOffset() -> Int64? {
            if cursor >= stdPart.endIndex { return nil }
            let start = cursor
            if cursor < stdPart.endIndex && (stdPart[cursor] == "+" || stdPart[cursor] == "-") { cursor = stdPart.index(after: cursor) }
            while cursor < stdPart.endIndex && (stdPart[cursor].isNumber || stdPart[cursor] == ":") { cursor = stdPart.index(after: cursor) }
            let offStr = String(stdPart[start..<cursor])
            if offStr.isEmpty { return nil }
            return parseOffset(offStr)
        }

        let stdName = readName()
        let stdOff = readOffset() ?? 0
        let dstName = readName()
        let dstOff = readOffset() ?? (stdOff - 3600)

        func parseRule(_ rStr: String) -> (Int, Int, Int, Int64)? {
            let parts = rStr.split(separator: "/")
            let datePart = String(parts[0])
            let timeOff = parts.count > 1 ? parseOffset(String(parts[1])) : 7200 // default 02:00:00
            let dateComponents = datePart.split(separator: ".")
            if dateComponents.count < 3 { return nil }
            let m = Int(dateComponents[0].dropFirst()) ?? 0
            let w = Int(dateComponents[1]) ?? 0
            let d = Int(dateComponents[2]) ?? 0
            return (m, w, d, timeOff)
        }

        let startR = parts.count > 1 ? parseRule(String(parts[1])) : nil
        let endR = parts.count > 2 ? parseRule(String(parts[2])) : nil

        return POSIXRule(stdOffset: stdOff, dstOffset: dstOff, stdAbbr: stdName, dstAbbr: dstName.isEmpty ? nil : dstName, startRule: startR, endRule: endR)
    }

    static func parseOffset(_ s: String) -> Int64 {
        var sign: Int64 = 1
        var cursor = s.startIndex
        if cursor < s.endIndex && s[cursor] == "+" { sign = 1; cursor = s.index(after: cursor) }
        else if cursor < s.endIndex && s[cursor] == "-" { sign = -1; cursor = s.index(after: cursor) }

        let parts = s[cursor...].split(separator: ":")
        var h: Int64 = 0, m: Int64 = 0, s_sec: Int64 = 0
        if parts.count > 0 { h = Int64(parts[0]) ?? 0 }
        if parts.count > 1 { m = Int64(parts[1]) ?? 0 }
        if parts.count > 2 { s_sec = Int64(parts[2]) ?? 0 }

        // If only one number is given, it's hours
        let total = (h * 3600) + (m * 60) + s_sec
        return sign * total
    }
}

func formatOffset(_ off: Int64) -> String {
    let absOff = abs(off)
    let h = absOff / 3600
    let m = (absOff % 3600) / 60
    let s = absOff % 60
    let sign = off >= 0 ? "+" : "-"
    if s == 0 {
        return String(format: "%@%02d:%02d", sign, h, m)
    } else {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    }
}

func formatLocal(_ t: Int64, _ offset: Int64) -> String {
    let date = Date(timeIntervalSince1970: TimeInterval(t - offset))
    let calendar = Calendar.current
    let y = calendar.component(.year, from: date)
    let m = calendar.component(.month, from: date)
    let d = calendar.component(.day, from: date)
    let h = calendar.component(.hour, from: date)
    let min = calendar.component(.minute, from: date)
    let s = calendar.component(.second, from: date)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d%@", y, m, d, h, min, s, formatOffset(offset))
}

func parseWallClock(_ w: String) -> Int64 {
    let formatter = DateFormatter()
    formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss"
    formatter.timeZone = TimeZone(secondsFromGMT: 0)
    return Int64(formatter.date(from: w)!.timeIntervalSince1970)
}

func main() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let dir = args[1]

    let queriesFile = URL(fileURLWithPath: dir).appendingPathComponent("queries.txt")
    guard let queries = try? String(contentsOf: queriesFile) else { return }

    var tzifCache = [String: TZifFile]()

    for line in queries.components(separatedBy: .newlines) {
        if line.trimmingCharacters(in: .whitespaces).isEmpty { continue }
        let parts = line.split(separator: " ")
        if parts.count < 3 { continue }

        let type = String(parts[0])
        let fileName = String(parts[1])

        if tzifCache[fileName] == nil {
            let fileURL = URL(fileURLWithPath: dir).appendingPathComponent(fileName)
            if let data = try? Data(contentsOf: fileURL) {
                let content = String(data: data, encoding: .utf8) ?? ""
                let footer = content.components(separatedBy: .newlines).filter { !$0.isEmpty }.last ?? ""
                tzifCache[fileName] = TZifFile(data: data, footer: footer)
            }
        }

        guard let tzif = tzifCache[fileName] else { continue }

        if type == "UTC" {
            let t = Int64(parts[2]) ?? 0
            let tzType = tzif.getType(for: t)
            print("\(line) -> \(formatLocal(t, tzType.offset)) \(tzType.abbr)")
        } else if type == "LOCAL" {
            let wStr = String(parts[2])
            let wUnix = parseWallClock(wStr)

            var candidates = Set<Int64>()
            candidates.insert(tzif.rule.stdOffset)
            candidates.insert(tzif.rule.dstOffset)
            for ty in tzif.types { candidates.insert(ty.offset) }

            var possibleT = [Int64]()
            for off in candidates {
                let t = wUnix + off
                let resType = tzif.getType(for: t)
                if resType.offset == off {
                    possibleT.append(t)
                }
            }

            let uniqueT = Array(Set(possibleT)).sorted()

            if uniqueT.count == 1 {
                let t = uniqueT[0]
                let ty = tzif.getType(for: t)
                print("\(line) -> \(t) \(formatOffset(ty.offset)) \(ty.abbr)")
            } else if uniqueT.count > 1 {
                let t1 = uniqueT[0]
                let ty1 = tzif.getType(for: t1)
                let t2 = uniqueT[1]
                let ty2 = tzif.getType(for: t2)
                print("\(line) -> \(t1) \(formatOffset(ty1.offset)) \(ty1.abbr) | \(t2) \(formatOffset(ty2.offset)) \(ty2.abbr)")
            } else {
                var gapT: Int64 = 0
                var foundGap = false

                for i in 0..<tzif.transitions.count {
                    let t_i = tzif.transitions[i]
                    let off_prev = tzif.getType(for: t_i - 1).offset
                    let off_curr = tzif.getType(for: t_i).offset

                    let local_prev = t_i - 1 - off_prev
                    let local_curr = t_i - off_curr

                    if local_prev < wUnix && wUnix < local_curr {
                        gapT = wUnix + off_prev
                        foundGap = true
                        break
                    }
                }

                if !foundGap {
                    gapT = wUnix + tzif.rule.stdOffset
                }

                let ty = tzif.getType(for: gapT)
                print("\(line) -> GAP \(gapT) \(formatLocal(gapT, ty.offset)) \(ty.abbr)")
            }
        }
    }
}

main()

