                else { buf[len++] = 0xF0 | (cp >> 18); buf[len++] = 0x80 | ((cp >> 12) & 0x3F); buf[len++] = 0x80 | ((cp >> 6) & 0x3F); buf[len++] = 0x80 | (cp & 0x3F); }
            }
        } else {
            buf[len++] = *json_cursor;
        }
        json_cursor++;
    }
    json_cursor++;
    buf[len] = 0;
    return buf;
}

json_value* json_parse_value() {
    while (*json_cursor && isspace(*json_cursor)) json_cursor++;
    json_value *v = calloc(1, sizeof(json_value));
    if (*json_cursor == '"') {
        v->type = JSON_STRING;
        v->s = parse_json_string();
    } else if (*json_cursor == '{') {
        v->type = JSON_OBJECT;
        json_cursor++;
        while (*json_cursor != '}') {
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == '}') break;
            char *key = parse_json_string();
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            json_cursor++; // skip :
            json_value *val = json_parse_value();
            v->object.keys = realloc(v->object.keys, sizeof(char*) * (v->object.count + 1));
            v->object.vals = realloc(v->object.vals, sizeof(json_value*) * (v->object.count + 1));
            v->object.keys[v->object.count] = key;
            v->object.vals[v->object.count] = val;
            v->object.count++;
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == ',') json_cursor++;
        }
        json_cursor++;
    } else if (*json_cursor == '[') {
        v->type = JSON_ARRAY;
        json_cursor++;
        while (*json_cursor != ']') {
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == ']') break;
            json_value *val = json_parse_value();
            v->array.elems = realloc(v->array.elems, sizeof(json_value*) * (v->array.count + 1));
            v->array.elems[v->array.count++] = val;
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == ',') json_cursor++;
        }
        json_cursor++;
    } else if (isdigit(*json_cursor) || *json_cursor == '-') {
        v->type = JSON_NUMBER;
        v->n = strtod(json_cursor, (char**)&json_cursor);
    } else if (strncmp(json_cursor, "true", 4) == 0) {
        v->type = JSON_BOOLEAN; v->b = 1; json_cursor += 4;
    } else if (strncmp(json_cursor, "false", 5) == 0) {
        v->type = JSON_BOOLEAN; v->b = 0; json_cursor += 5;
    } else if (strncmp(json_cursor, "null", 4) == 0) {
        v->type = JSON_NULL; json_cursor += 4;
    }
    return v;
}

void json_free(json_value *v) {
    if (!v) return;
    if (v->type == JSON_STRING) free(v->s);
    else if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->object.count; i++) {
            free(v->object.keys[i]);
            json_free(v->object.vals[i]);
        }
        free(v->object.keys); free(v->object.vals);
    } else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->array.count; i++) json_free(v->array.elems[i]);
        free(v->array.elems);
    }
    free(v);
}

json_value* json_get_obj(json_value *v, const char *key) {
    if (!v || v->type != JSON_OBJECT) return NULL;
    for (int i = 0; i < v->object.count; i++) {
        if (strcmp(v->object.keys[i], key) == 0) return v->object.vals[i];
    }
    return NULL;
}

char* json_get_str(json_value *v, const char *key) {
    json_value *val = json_get_obj(v, key);
    return (val && val->type == JSON_STRING) ? val->s : NULL;
}

void json_serialize_string(char *buf, const char *s) {
    if (!s) { strcpy(buf, "null"); return; }
    int len = 0;
    buf[len++] = '"';
    for (int i = 0; s[i]; i++) {
        if (s[i] == '"') { buf[len++] = '\\'; buf[len++] = '"'; }
        else if (s[i] == '\\') { buf[len++] = '\\'; buf[len++] = '\\'; }
        else if (s[i] == '\n') { buf[len++] = '\\'; buf[len++] = 'n'; }
        else if (s[i] == '\r') { buf[len++] = '\\'; buf[len++] = 'r'; }
        else if (s[i] == '\t') { buf[len++] = '\\'; buf[len++] = 't'; }
        else buf[len++] = s[i];
    }
    buf[len++] = '"';
    buf[len] = 0;
}

char* json_serialize(json_value *v) {
    char *buf = malloc(16384);
    int len = 0;
    if (v->type == JSON_STRING) {
        len += sprintf(buf, "\"%s\"", v->s); // Simple serialize, but we should escape
        // To be safe, use a proper escape function
    } else if (v->type == JSON_NUMBER) {
        len += sprintf(buf, "%g", v->n);
    } else if (v->type == JSON_BOOLEAN) {
        len += sprintf(buf, "%s", v->b ? "true" : "false");
    } else if (v->type == JSON_NULL) {
        len += sprintf(buf, "null");
    } else if (v->type == JSON_ARRAY) {
        len += sprintf(buf, "[");
        for (int i = 0; i < v->array.count; i++) {
            char *s = json_serialize(v->array.elems[i]);
            len += sprintf(buf + len, "%s%s", s, i < v->array.count - 1 ? "," : "");
            free(s);
        }
        len += sprintf(buf + len, "]");
    } else if (v->type == JSON_OBJECT) {
        len += sprintf(buf, "{");
        for (int i = 0; i < v->object.count; i++) {
            char kbuf[256];
            json_serialize_string(kbuf, v->object.keys[i]);
            char *s = json_serialize(v->object.vals[i]);
            len += sprintf(buf + len, "%s:%s%s", kbuf, s, i < v->object.count - 1 ? "," : "");
            free(s);
        }
        len += sprintf(buf + len, "}");
    }
    return buf;
}

// Proper JSON serialize for strings
char* json_escape(const char *s) {
    if (!s) return strdup("null");
    char *res = malloc(strlen(s) * 4 + 1);
    int len = 0;
    res[len++] = '"';
    for (int i = 0; s[i]; i++) {
        if (s[i] == '"') { res[len++] = '\\'; res[len++] = '"'; }
        else if (s[i] == '\\') { res[len++] = '\\'; res[len++] = '\\'; }
        else if (s[i] == '\n') { res[len++] = '\\'; res[len++] = 'n'; }
        else if (s[i] == '\r') { res[len++] = '\\'; res[len++] = 'r'; }
        else if (s[i] == '\t') { res[len++] = '\\'; res[len++] = 't'; }
        else res[len++] = s[i];
    }
    res[len++] = '"';
    res[len] = 0;
    return res;
}

uint32_t utf8_to_cp(const unsigned char *s, int *len) {
    if (*s < 0x80) { *len = 1; return *s; }
    if ((*s & 0xE0) == 0xC0) { *len = 2; return ((*s & 0x1F) << 6) | (s[1] & 0x3F); }
    if ((*s & 0xF0) == 0xE0) { *len = 3; return ((*s & 0x0F) << 12) | ((s[1] & 0x3F) << 6) | (s[2] & 0x3F); }
    if ((*s & 0xF8) == 0xF0) { *len = 4; return ((*s & 0x07) << 18) | ((s[1] & 0x3F) << 12) | ((s[2] & 0x3F) << 6) | (s[3] & 0x3F); }
    return 0;
}

int cp_to_utf8(uint32_t cp, unsigned char *s) {
    if (cp < 0x80) { s[0] = cp; return 1; }
    if (cp < 0x800) { s[0] = 0xC0 | (cp >> 6); s[1] = 0x80 | (cp & 0x3F); return 2; }
    if (cp < 0x10000) { s[0] = 0xE0 | (cp >> 12); s[1] = 0x80 | ((cp >> 6) & 0x3F); s[2] = 0x80 | (cp & 0x3F); return 3; }
    s[0] = 0xF0 | (cp >> 18); s[1] = 0x80 | ((cp >> 12) & 0x3F); s[2] = 0x80 | ((cp >> 6) & 0x3F); s[3] = 0x80 | (cp & 0x3F); return 4;
}

