char* run_tool(const char *name, const char *input_json) {
    json_cursor = input_json;
    json_value *v = json_parse_value();
    if (strcmp(name, "measure") == 0) {
        char *text = json_get_str(v, "text");
        char *unit = json_get_str(v, "unit");
        char res[128];
        if (!unit) {
            char *err = malloc(128);
            sprintf(err, "unsupported unit: %s", unit ? unit : "null");
            json_free(v); return err;
        }
        if (strcmp(unit, "utf8_bytes") == 0) {
            sprintf(res, "%zu", strlen(text));
        } else if (strcmp(unit, "code_points") == 0) {
            int cp_count = 0;
            const unsigned char *p = (const unsigned char*)text;
            while (*p) { int len; utf8_to_cp(p, &len); p += len; cp_count++; }
            sprintf(res, "%d", cp_count);
        } else if (strcmp(unit, "utf16_units") == 0) {
            int u16_count = 0;
            const unsigned char *p = (const unsigned char*)text;
            while (*p) { int len; uint32_t cp = utf8_to_cp(p, &len); p += len; u16_count += (cp > 0xFFFF ? 2 : 1); }
            sprintf(res, "%d", u16_count);
        } else {
            char *err = malloc(128);
            sprintf(err, "unsupported unit: %s", unit);
            json_free(v); return err;
        }
        char *res_s = strdup(res);
        json_free(v); return res_s;
    } else if (strcmp(name, "reverse") == 0) {
        char *text = json_get_str(v, "text");
        const unsigned char *p = (const unsigned char*)text;
        uint32_t *cps = malloc(strlen(text) * 4 * sizeof(uint32_t));
        int cp_count = 0;
        while (*p) { int len; cps[cp_count++] = utf8_to_cp(p, &len); p += len; }
        char *res = malloc(strlen(text) * 4 + 1);
        int len = 0;
        for (int i = cp_count - 1; i >= 0; i--) {
            unsigned char tmp[4];
            len += cp_to_utf8(cps[i], tmp);
            memcpy(res + len - (i == cp_count - 1 ? 0 : 0), tmp, 0); // This is wrong, just use a loop
        }
        // Correct the reverse loop
        len = 0;
        for (int i = cp_count - 1; i >= 0; i--) {
            unsigned char tmp[4];
            int l = cp_to_utf8(cps[i], tmp);
            memcpy(res + len, tmp, l);
            len += l;
        }
        res[len] = 0;
        free(cps); json_free(v); return res;
    } else {
        char *err = malloc(128);
        sprintf(err, "unknown tool: %s", name);
        json_free(v); return err;
    }
}

char* read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = 0;
    fclose(f);
    return buf;
}

