typedef enum { JSON_STRING, JSON_NUMBER, JSON_OBJECT, JSON_ARRAY, JSON_BOOLEAN, JSON_NULL } json_type;
typedef struct json_value {
    json_type type;
    union {
        char *s;
        double n;
        struct { struct json_value **elems; int count; } array;
        struct { char **keys; struct json_value **vals; int count; } object;
        int b;
    };
} json_value;

const char *json_cursor;
char *parse_json_string() {
    json_cursor++; // skip "
    int cap = 128, len = 0;
    char *buf = malloc(cap);
    while (*json_cursor != '"') {
        if (*json_cursor == '\\') {
            json_cursor++;
            if (*json_cursor == 'n') buf[len++] = '\n';
            else if (*json_cursor == 'r') buf[len++] = '\r';
            else if (*json_cursor == 't') buf[len++] = '\t';
            else if (*json_cursor == '"') buf[len++] = '"';
            else if (*json_cursor == '\\') buf[len++] = '\\';
            else if (*json_cursor == 'u') {
                char hex[5] = {0};
                memcpy(hex, json_cursor + 1, 4);
                uint32_t cp = (uint32_t)strtol(hex, NULL, 16);
                json_cursor += 4;
                if (cp >= 0xD800 && cp <= 0xDBFF) {
                    char hex2[5] = {0};
                    memcpy(hex2, json_cursor + 1, 4);
                    uint32_t low = (uint32_t)strtol(hex2, NULL, 16);
                    cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                    json_cursor += 4;
                }
                if (cp < 0x80) buf[len++] = cp;
                else if (cp < 0x800) { buf[len++] = 0xC0 | (cp >> 6); buf[len++] = 0x80 | (cp & 0x3F); }
                else if (cp < 0x10000) { buf[len++] = 0xE0 | (cp >> 12); buf[len++] = 0x80 | ((cp >> 6) & 0x3F); buf[len++] = 0x80 | (cp & 0x3F); }
                else { buf[len++] = 0xF0 | (cp >> 18); buf[len++] = 0x80 | ((cp >> 12) & 0x3F); buf[len++] = 0x80 | ((cp >> 6) & 0x3F); buf[len++] = 0x80 | (cp & 0x3F); }
            }
        } else buf[len++] = *json_cursor;
        if (len >= cap - 4) { cap *= 2; buf = realloc(buf, cap); }
        json_cursor++;
    }
    json_cursor++;
    buf[len] = 0;
    return buf;
}

json_value *json_parse_value() {
    while (*json_cursor && isspace(*json_cursor)) json_cursor++;
    if (!*json_cursor) return NULL;
    json_value *v = calloc(1, sizeof(json_value));
    if (*json_cursor == '"') {
        v->type = JSON_STRING; v->s = parse_json_string();
    } else if (*json_cursor == '{') {
        v->type = JSON_OBJECT; json_cursor++;
        while (*json_cursor != '}') {
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == '}') break;
            char *key = parse_json_string();
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            json_cursor++; // :
            json_value *val = json_parse_value();
            v->object.keys = realloc(v->object.keys, sizeof(char *) * (v->object.count + 1));
            v->object.vals = realloc(v->object.vals, sizeof(json_value *) * (v->object.count + 1));
            v->object.keys[v->object.count] = key;
            v->object.vals[v->object.count++] = val;
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == ',') json_cursor++;
        }
        json_cursor++;
    } else if (*json_cursor == '[') {
        v->type = JSON_ARRAY; json_cursor++;
        while (*json_cursor != ']') {
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == ']') break;
            json_value *val = json_parse_value();
            v->array.elems = realloc(v->array.elems, sizeof(json_value *) * (v->array.count + 1));
            v->array.elems[v->array.count++] = val;
            while (*json_cursor && isspace(*json_cursor)) json_cursor++;
            if (*json_cursor == ',') json_cursor++;
        }
        json_cursor++;
    } else if (isdigit(*json_cursor) || *json_cursor == '-') {
        v->type = JSON_NUMBER; v->n = strtod(json_cursor, (char **)&json_cursor);
    } else if (strncmp(json_cursor, "true", 4) == 0) { v->type = JSON_BOOLEAN; v->b = 1; json_cursor += 4; }
    else if (strncmp(json_cursor, "false", 5) == 0) { v->type = JSON_BOOLEAN; v->b = 0; json_cursor += 5; }
    else if (strncmp(json_cursor, "null", 4) == 0) { v->type = JSON_NULL; json_cursor += 4; }
    return v;
}

void json_free(json_value *v) {
    if (!v) return;
    if (v->type == JSON_STRING) free(v->s);
    else if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->object.count; i++) { free(v->object.keys[i]); json_free(v->object.vals[i]); }
        free(v->object.keys); free(v->object.vals);
    } else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->array.count; i++) json_free(v->array.elems[i]);
        free(v->array.elems);
    }
    free(v);
}

json_value *json_get_obj(json_value *v, const char *key) {
    if (!v || v->type != JSON_OBJECT) return NULL;
    for (int i = 0; i < v->object.count; i++) if (strcmp(v->object.keys[i], key) == 0) return v->object.vals[i];
    return NULL;
}

char *json_get_str(json_value *v, const char *key) {
    json_value *val = json_get_obj(v, key);
    return (val && val->type == JSON_STRING) ? val->s : NULL;
}

char *json_escape(const char *s) {
    if (!s) return strdup("null");
    int cap = strlen(s) * 4 + 5, len = 0;
    char *res = malloc(cap);
    res[len++] = '"';
    for (int i = 0; s[i]; i++) {
        if (s[i] == '"') { res[len++] = '\\'; res[len++] = '"'; }
        else if (s[i] == '\\') { res[len++] = '\\'; res[len++] = '\\'; }
        else if (s[i] == '\n') { res[len++] = '\\'; res[len++] = 'n'; }
        else if (s[i] == '\r') { res[len++] = '\\'; res[len++] = 'r'; }
        else if (s[i] == '\t') { res[len++] = '\\'; res[len++] = 't'; }
        else res[len++] = s[i];
        if (len >= cap - 5) { cap *= 2; res = realloc(res, cap); }
    }
    res[len++] = '"'; res[len] = 0;
    return res;
}

char *json_serialize(json_value *v) {
    if (!v) return strdup("null");
    int cap = 1024, len = 0;
    char *buf = malloc(cap);
    if (v->type == JSON_STRING) {
        char *esc = json_escape(v->s);
        len = sprintf(buf, "%s", esc);
        free(esc);
    } else if (v->type == JSON_NUMBER) len = sprintf(buf, "%g", v->n);
    else if (v->type == JSON_BOOLEAN) len = sprintf(buf, "%s", v->b ? "true" : "false");
    else if (v->type == JSON_NULL) len = sprintf(buf, "null");
    else if (v->type == JSON_ARRAY) {
        len = sprintf(buf, "[");
        for (int i = 0; i < v->array.count; i++) {
            char *s = json_serialize(v->array.elems[i]);
            int slen = strlen(s);
            if (len + slen + 2 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            memcpy(buf + len, s, slen); len += slen;
            if (i < v->array.count - 1) buf[len++] = ',';
            free(s);
        }
        buf[len++] = ']'; buf[len] = 0;
    } else if (v->type == JSON_OBJECT) {
        len = sprintf(buf, "{");
        for (int i = 0; i < v->object.count; i++) {
            char *ke = json_escape(v->object.keys[i]);
            char *vs = json_serialize(v->object.vals[i]);
            int klen = strlen(ke), vlen = strlen(vs);
            if (len + klen + vlen + 3 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            memcpy(buf + len, ke, klen); len += klen;
            buf[len++] = ':';
            memcpy(buf + len, vs, vlen); len += vlen;
            if (i < v->object.count - 1) buf[len++] = ',';
            free(ke); free(vs);
        }
        buf[len++] = '}'; buf[len] = 0;
    }
    return buf;
}

uint32_t utf8_to_cp(const unsigned char *s, int *len) {
    if ((*s & 0x80) == 0) { *len = 1; return *s; }
    if ((*s & 0xE0) == 0xC0) { *len = 2; return ((*s & 0x1F) << 6) | (s[1] & 0x3F); }
    if ((*s & 0xF0) == 0xE0) { *len = 3; return ((*s & 0x0F) << 12) | ((s[1] & 0x3F) << 6) | (s[2] & 0x3F); }
    if ((*s & 0xF8) == 0xF0) { *len = 4; return ((*s & 0x07) << 18) | ((s[1] & 0x3F) << 12) | ((s[2] & 0x3F) << 6) | (s[3] & 0x3F); }
    return 0;
}

int cp_to_utf8(uint32_t cp, unsigned char *s) {
    if (cp < 0x80) { s[0] = cp; return 1; }
    if (cp < 0x800) { s[0] = 0xC0 | (cp >> 6); s[1] = 0x80 | (cp & 0x3F); return 2; }
    if (cp < 0x10000) { s[0] = 0xE0 | (cp >> 12); s[1] = 0x80 | ((cp >> 6) & 0x3F); s[2] = 0x80 | (cp & 0x3F); return 3; }
    s[0] = 0xF0 | (cp >> 18); s[1] = 0x80 | ((cp >> 12) & 0x3F); s[2] = 0x80 | ((cp >> 6) & 0x3F); s[3] = 0x80 | (cp & 0x3F); return 4;
}

