        if (strcmp(unit, "utf8_bytes") == 0) sprintf(res, "%zu", strlen(text));
        else if (strcmp(unit, "code_points") == 0) {
            int cp_count = 0; const unsigned char *p = (const unsigned char *)text;
            while (*p) { int l; utf8_to_cp(p, &l); p += l; cp_count++; }
            sprintf(res, "%d", cp_count);
        } else if (strcmp(unit, "utf16_units") == 0) {
            int u16_count = 0; const unsigned char *p = (const unsigned char *)text;
            while (*p) { int l; uint32_t cp = utf8_to_cp(p, &l); p += l; u16_count += (cp > 0xFFFF ? 2 : 1); }
            sprintf(res, "%d", u16_count);
        } else {
            char *e = malloc(128); sprintf(e, "unsupported unit: %s", unit); json_free(v); return e;
        }
        char *res_s = strdup(res); json_free(v); return res_s;
    } else if (strcmp(name, "reverse") == 0) {
        char *text = json_get_str(v, "text");
        const unsigned char *p = (const unsigned char *)text;
        uint32_t *cps = malloc(strlen(text) * 4 * sizeof(uint32_t));
        int cp_count = 0;
        while (*p) { int l; cps[cp_count++] = utf8_to_cp(p, &l); p += l; }
        char *res = malloc(strlen(text) * 4 + 1);
        int len = 0;
        for (int i = cp_count - 1; i >= 0; i--) {
            unsigned char tmp[4]; int l = cp_to_utf8(cps[i], tmp);
            memcpy(res + len, tmp, l); len += l;
        }
        res[len] = 0; free(cps); json_free(v); return res;
    } else {
        char *e = malloc(128); sprintf(e, "unknown tool: %s", name); json_free(v); return e;
    }
}

char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END); long size = ftell(f); fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f); buf[size] = 0;
    fclose(f); return buf;
}

