typedef struct {
    int32_t offset;
    int8_t isdst;
    int8_t abbr_idx;
} TZType;

typedef struct {
    int64_t *trans_times;
    int8_t *trans_types;
    TZType *types;
    char *abbrevs;
    int timecnt, typecnt, charcnt;
    char *footer;
    int32_t std_offset, dst_offset;
    char *std_abbr, *dst_abbr;
    int start_m, start_w, start_d, start_h, start_min, start_s;
    int end_m, end_w, end_d, end_h, end_min, end_s;
    bool has_dst;
    bool has_start_end;
} TZZone;

static uint32_t read_u32_be(unsigned char *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static int32_t read_i32_be(unsigned char *p) {
    return (int32_t)read_u32_be(p);
}

static int64_t read_i64_be(unsigned char *p) {
    return ((int64_t)read_u32_be(p) << 32) | read_u32_be(p + 4);
}

static int parse_offset(const char *s, int *len) {
    int sign = 1;
    if (*s == '+') { sign = 1; s++; }
    else if (*s == '-') { sign = -1; s--; s++; } // This is just to handle the logic, we'll use a pointer
    return 0; // Placeholder
}

static int parse_offset_str(const char *s, int *len) {
    int sign = 1;
    if (*s == '+') { sign = 1; s++; }
    else if (*s == '-') { sign = -1; s++; }
    int h = 0, m = 0, sec = 0;
    int i = 0;
    while (s[i] >= '0' && s[i] <= '9') {
        h = h * 10 + (s[i] - '0');
        i++;
    }
    if (s[i] == ':') {
        i++;
        int j = 0;
        while (s[i + j] >= '0' && s[i + j] <= '9') {
            m = m * 10 + (s[i + j] - '0');
            j++;
        }
        i += j;
        if (s[i] == ':') {
            i++;
            int k = 0;
            while (s[i + k] >= '0' && s[i + k] <= '9') {
                sec = sec * 10 + (s[i + k] - '0');
                k++;
            }
            i += k;
        }
    }
    *len = i;
    return sign * (h * 3600 + m * 60 + sec);
}

static void parse_footer(TZZone *zone) {
    char *s = zone->footer;
    while (*s == ' ' || *s == '\n' || *s == '\r') s++;
    if (!*s) return;

    char std_name[64], dst_name[64];
    int snlen = 0, dnlen = 0;

    if (*s == '<') {
        s++;
        while (*s && *s != '>') std_name[snlen++] = *s++;
        if (*s == '>') s++;
        std_name[snlen] = '\0';
    } else {
        while (*s && ( (*s >= 'A' && *s <= 'Z') || (*s >= 'a' && *s <= 'z') )) std_name[snlen++] = *s++;
        std_name[snlen] = '\0';
    }

    int len;
    zone->std_offset = parse_offset_str(s, &len);
    s += len;

    if (*s && *s != ',' && *s != '\n' && *s != '\r') {
        zone->has_dst = true;
        if (*s == '<') {
            s++;
            while (*s && *s != '>') dst_name[dnlen++] = *s++;
            if (*s == '>') s++;
            dst_name[dnlen] = '\0';
        } else {
            while (*s && ( (*s >= 'A' && *s <= 'Z') || (*s >= 'a' && *s <= 'z') )) dst_name[dnlen++] = *s++;
            dst_name[dnlen] = '\0';
        }
        if (*s && (*s == '+' || *s == '-' || (*s >= '0' && *s <= '9'))) {
            zone->dst_offset = parse_offset_str(s, &len);
            s += len;
        } else {
            zone->dst_offset = zone->std_offset - 3600;
        }
    } else {
        zone->has_dst = false;
    }

    zone->std_abbr = strdup(std_name);
    zone->dst_abbr = strdup(dst_name);

    if (*s == ',') {
        s++;
        zone->has_start_end = true;
        // Start rule: Mm.w.d[/time]
        s++; // 'M'
        zone->start_m = 0; while (*s >= '0' && *s <= '9') zone->start_m = zone->start_m * 10 + (*s++ - '0');
        s++; // '.'
        zone->start_w = 0; while (*s >= '0' && *s <= '9') zone->start_w = zone->start_w * 10 + (*s++ - '0');
        s++; // '.'
        zone->start_d = 0; while (*s >= '0' && *s <= '9') zone->start_d = zone->start_d * 10 + (*s++ - '0');
        if (*s == '/') {
            s++;
            int len_t;
            int t_sec = parse_offset_str(s, &len_t);
            zone->start_h = t_sec / 3600;
            zone->start_min = (t_sec % 3600) / 60;
            if (zone->start_min < 0) zone->start_min = 60 + zone->start_min;
            zone->start_s = t_sec % 60;
            if (zone->start_s < 0) zone->start_s = 60 + zone->start_s;
            s += len_t;
        } else {
            zone->start_h = 2; zone->start_min = 0; zone->start_s = 0;
        }
        s++; // ','
        // End rule: Mm.w.d[/time]
        s++; // 'M'
        zone->end_m = 0; while (*s >= '0' && *s <= '9') zone->end_m = zone->end_m * 10 + (*s++ - '0');
        s++; // '.'
        zone->end_w = 0; while (*s >= '0' && *s <= '9') zone->end_w = zone->end_w * 10 + (*s++ - '0');
        s++; // '.'
        zone->end_d = 0; while (*s >= '0' && *s <= '9') zone->end_d = zone->end_d * 10 + (*s++ - '0');
        if (*s == '/') {
            s++;
            int len_t;
            int t_sec = parse_offset_str(s, &len_t);
            zone->end_h = t_sec / 3600;
            zone->end_min = (t_sec % 3600) / 60;
            if (zone->end_min < 0) zone->end_min = 60 + zone->end_min;
            zone->end_s = t_sec % 60;
            if (zone->end_s < 0) zone->end_s = 60 + zone->end_s;
            s += len_t;
        } else {
            zone->end_h = 2; zone->end_min = 0; zone->end_s = 0;
        }
    }
}

static bool is_leap(int y) {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

static int days_in_month(int m, int y) {
    static const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (m == 2 && is_leap(y)) return 29;
    return days[m - 1];
}

static int64_t date_to_unix(int y, int m, int d, int h, int min, int s) {
    int64_t days = 0;
    for (int year = 1800; year < y; year++) days += is_leap(year) ? 366 : 365;
    for (int month = 1; month < m; month++) days += days_in_month(month, y);
    days += d - 1;
    // 1800-01-01 is not a Unix epoch. Unix epoch is 1970-01-01.
    // Days from 1800-01-01 to 1970-01-01:
    // 1970-1800 = 170 years.
    // Leap years between 1800 and 1970: 1804, ..., 1968.
    // (1968 - 1804) / 4 + 1 = 41 + 1 = 42.
    // But 1800, 1900 were not leap years.
    // Wait, simpler: use a known reference.
    // 1970-01-01 is 0.
    int64_t epoch_days = 0;
    if (y >= 1970) {
        for (int year = 1970; year < y; year++) epoch_days += is_leap(year) ? 366 : 365;
        for (int month = 1; month < m; month++) epoch_days += days_in_month(month, y);
        epoch_days += d - 1;
    } else {
        for (int year = y; year < 1970; year++) epoch_days -= is_leap(year) ? 366 : 365;
        for (int month = 1; month < m; month++) epoch_days -= days_in_month(month, y); // This is wrong.
        // Correct way for pre-1970:
        epoch_days = 0;
        for (int year = 1970; year > y; year--) epoch_days -= is_leap(year - 1) ? 366 : 365;
        // Now we are at Jan 1 of year y. We need to subtract the days from Jan 1 to (m, d).
        int64_t days_in_y = 0;
        for (int month = 1; month < m; month++) days_in_y += days_in_month(month, y);
        days_in_y += d - 1;
        epoch_days -= days_in_y;
    }
    // Correcting the pre-1970 logic:
    // Just use a loop from 1970 to y.
    int64_t total_days = 0;
    if (y >= 1970) {
        for (int year = 1970; year < y; year++) total_days += is_leap(year) ? 366 : 365;
        for (int month = 1; month < m; month++) total_days += days_in_month(month, y);
        total_days += d - 1;
    } else {
        for (int year = 1969; year >= y; year--) total_days -= is_leap(year) ? 366 : 365;
        // Now we are at Jan 1 of year y.
        int64_t days_in_y = 0;
        for (int month = 1; month < m; month++) days_in_y += days_in_month(month, y);
        days_in_y += d - 1;
        total_days += days_in_y;
    }
    return total_days * 86400LL + h * 3600LL + min * 60LL + s;
}

static void unix_to_date(int64_t t, int *y, int *m, int *d, int *h, int *min, int *s) {
    int64_t days = t / 86400LL;
    int64_t rem = t % 86400LL;
    if (rem < 0) { days--; rem += 86400LL; }
    *h = rem / 3600;
    *min = (rem % 3600) / 60;
    *s = rem % 60;
    if (days >= 0) {
        int year = 1970;
        while (days >= (is_leap(year) ? 366 : 365)) {
            days -= (is_leap(year) ? 366 : 365);
            year++;
        }
        *y = year;
        int month = 1;
        while (days >= days_in_month(month, year)) {
            days -= days_in_month(month, year);
            month++;
        }
        *m = month;
        *d = (int)days + 1;
    } else {
        int year = 1969;
        while (days < 0) {
            int dy = is_leap(year) ? 366 : 365;
            if (days <= -dy) days += dy;
            else {
                // days is between -dy+1 and -1
                // we need to find the date in year 'year'
                // days = - (days_in_year - days_from_start_of_year)
                int64_t pos = dy + days;
                int month = 1;
                while (pos >= days_in_month(month, year)) {
                    pos -= days_in_month(month, year);
                    month++;
                }
                *y = year;
                *m = month;
                *d = (int)pos + 1;
                days = 0;
            }
            year--;
        }
        *y = 1970; *m = 1; *d = 1; // fallback
    }
}

static int get_weekday(int y, int m, int d) {
    // 1970-01-01 was a Thursday (4)
    int64_t t = date_to_unix(y, m, d, 0, 0, 0);
    int wd = (int)((t / 86400LL + 4) % 7);
    if (wd < 0) wd += 7;
    return wd;
}

static int64_t find_nth_day(int y, int m, int w, int d_target) {
    int d = 1;
    int found = 0;
    while (d <= days_in_month(m, y)) {
        if (get_weekday(y, m, d) == d_target) {
            found++;
            if (found == w && w != 5) return date_to_unix(y, m, d, 0, 0, 0);
        }
        d++;
    }
    if (w == 5) {
        // Find the last d_target day
        for (int i = days_in_month(m, y); i >= 1; i--) {
            if (get_weekday(y, m, i) == d_target) return date_to_unix(y, m, i, 0, 0, 0);
        }
    }
    return -1;
}

static int32_t get_offset(TZZone *zone, int64_t t) {
    if (zone->timecnt > 0) {
        if (t < zone->trans_times[0]) return zone->types[0].offset;
        if (t < zone->trans_times[zone->timecnt - 1]) {
            for (int i = 0; i < zone->timecnt - 1; i++) {
                if (t >= zone->trans_times[i] && t < zone->trans_times[i+1])
                    return zone->types[zone->trans_types[i]].offset;
            }
        }
    }
    // Footer rule
    int y, m, d, h, min, s;
    unix_to_date(t - zone->std_offset, &y, &m, &d, &h, &min, &s);
    int64_t start_utc = find_nth_day(y, zone->start_m, zone->start_w, zone->start_d) 
                        + zone->start_h * 3600LL + zone->start_min * 60LL + zone->start_s - zone->std_offset;
    int64_t end_utc = find_nth_day(y, zone->end_m, zone->end_w, zone->end_d) 
                      + zone->end_h * 3600LL + zone->end_min * 60LL + zone->end_s - zone->dst_offset;

    bool is_dst = false;
    if (start_utc < end_utc) { // Northern
        if (t >= start_utc && t < end_utc) is_dst = true;
    } else { // Southern
        if (t >= start_utc || t < end_utc) is_dst = true;
    }
    return is_dst ? zone->dst_offset : zone->std_offset;
}

static const char* get_abbr(TZZone *zone, int64_t t) {
    if (zone->timecnt > 0) {
        int type_idx = 0;
        if (t < zone->trans_times[0]) type_idx = 0;
        else {
            for (int i = 0; i < zone->timecnt; i++) {
                if (t >= zone->trans_times[i]) type_idx = zone->trans_types[i];
            }
        }
        int char_idx = zone->types[type_idx].abbr_idx;
        const char *res = zone->abbrevs + char_idx;
        return res;
    }
    int32_t off = get_offset(zone, t);
    return (off == zone->dst_offset) ? zone->dst_abbr : zone->std_abbr;
}

void format_local(int64_t t, TZZone *zone, char *buf) {
    int32_t off = get_offset(zone, t);
    int y, m, d, h, min, s;
    unix_to_date(t - off, &y, &m, &d, &h, &min, &s);
    int sign = (off >= 0) ? 1 : -1;
    int abs_off = (off < 0) ? -off : off;
    int off_h = abs_off / 3600;
    int off_m = (abs_off % 3600) / 60;
    int off_s = abs_off % 60;
    if (off_s == 0) sprintf(buf, "%04d-%02d-%02dT%02d:%02d:%02d%s%02d:%02d", y, m, d, h, min, s, (sign == 1 ? "+" : "-"), off_h, off_m);
    else sprintf(buf, "%04d-%02d-%02dT%02d:%02d:%02d%s%02d:%02d:%02d", y, m, d, h, min, s, (sign == 1 ? "+" : "-"), off_h, off_m, off_s);
}

