        }
        fread(zone.trans_types, 1, timecnt2, ftz);
        for (int i = 0; i < typecnt2; i++) {
            unsigned char b[6];
            fread(b, 1, 6, ftz);
            zone.types[i].offset = read_i32_be(b);
            zone.types[i].isdst = b[4];
            zone.types[i].abbr_idx = b[5];
        }
        fread(zone.abbrevs, 1, charcnt2, ftz);
        zone.abbrevs[charcnt2] = '\0';
        fseek(ftz, 0, SEEK_END);
        long fsize = ftell(ftz);
        char *footer = malloc(fsize + 1);
        fseek(ftz, 0, SEEK_SET);
        int c;
        int idx = 0;
        while ((c = fgetc(ftz)) != EOF) footer[idx++] = (char)c;
        footer[idx] = '\0';
        zone.footer = footer;
        parse_footer(&zone);

        if (strcmp(qtype, "UTC") == 0) {
