            printf("%s -> %s %s\n", line, local_buf, get_abbr(&zone, t));
        } else {
            int y, m, d, h, min, s;
            sscanf(time_str, "%d-%d-%dT%d:%d:%d", &y, &m, &d, &h, &min, &s);
            int64_t L = date_to_unix(y, m, d, h, min, s);
            int64_t t_std = L - zone.std_offset;
            int64_t t_dst = L - zone.dst_offset;
            bool std_ok = (get_offset(&zone, t_std) == zone.std_offset);
            bool dst_ok = (get_offset(&zone, t_dst) == zone.dst_offset);

            if (std_ok && dst_ok && t_std != t_dst) {
                if (t_std > t_dst) { int64_t tmp = t_std; t_std = t_dst; t_dst = tmp; }
                char b1[64], b2[64];
                format_local(t_std, &zone, b1);
                format_local(t_dst, &zone, b2);
                int sign1 = (zone.std_offset >= 0) ? 1 : -1;
                int abs1 = (zone.std_offset < 0) ? -zone.std_offset : zone.std_offset;
                int sign2 = (zone.dst_offset >= 0) ? 1 : -1;
                int abs2 = (zone.dst_offset < 0) ? -zone.dst_offset : zone.dst_offset;
                printf("%s -> %lld %s%02d:%02d %s | %lld %s%02d:%02d %s\n", 
                    line, t_std, (sign1 == 1 ? "+" : "-"), abs1/3600, (abs1%3600)/60, get_abbr(&zone, t_std),
                    t_dst, (sign2 == 1 ? "+" : "-"), abs2/3600, (abs2%3600)/60, get_abbr(&zone, t_dst));
            } else if (std_ok || dst_ok) {
                int64_t t = std_ok ? t_std : t_dst;
                int32_t off = get_offset(&zone, t);
                int sign = (off >= 0) ? 1 : -1;
                int abs_off = (off < 0) ? -off : off;
                printf("%s -> %lld %s%02d:%02d %s\n", line, t, (sign == 1 ? "+" : "-"), abs_off/3600, (abs_off%3600)/60, get_abbr(&zone, t));
            } else {
                int64_t t = L - zone.std_offset;
                char local_buf[64];
                format_local(t, &zone, local_buf);
                printf("%s -> GAP %lld %s %s\n", line, t, local_buf, get_abbr(&zone, t));
            }
        }
        free(zone.trans_times); free(zone.trans_types); free(zone.types); free(zone.abbrevs); free(zone.footer);
        fclose(ftz);
    }
    fclose(fq);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int32_t offset;
    int8_t isdst;
    int8_t abbr_idx;
} TZType;

typedef struct {
    int64_t *trans_times;
    int8_t *trans_types;
    TZType *types;
    char *abbrevs;
    int timecnt, typecnt, charcnt;
    int32_t std_offset, dst_offset;
    char *std_abbr, *dst_abbr;
    int start_m, start_w, start_d, start_h, start_min, start_s;
    int end_m, end_w, end_d, end_h, end_min, end_s;
    bool has_dst;
    bool has_start_end;
} TZZone;

static uint32_t read_u32_be(unsigned char *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static int32_t read_i32_be(unsigned char *p) {
    return (int32_t)read_u32_be(p);
}

static int64_t read_i64_be(unsigned char *p) {
    return ((int64_t)read_u32_be(p) << 32) | read_u32_be(p + 4);
}

static int parse_offset_str(const char *s, int *len) {
    int sign = 1;
    if (*s == '+') { sign = 1; s++; }
    else if (*s == '-') { sign = -1; s++; }
    int h = 0, m = 0, sec = 0;
    int i = 0;
    while (s[i] >= '0' && s[i] <= '9') {
        h = h * 10 + (s[i] - '0');
        i++;
    }
    if (s[i] == ':') {
        i++;
        int j = 0;
        while (s[i + j] >= '0' && s[i + j] <= '9') {
            m = m * 10 + (s[i + j] - '0');
            j++;
        }
        i += j;
        if (s[i] == ':') {
            i++;
            int k = 0;
            while (s[i + k] >= '0' && s[i + k] <= '9') {
                sec = sec * 10 + (s[i + k] - '0');
                k++;
            }
            i += k;
        }
    }
    *len = i;
    return sign * (h * 3600 + m * 60 + sec);
}

static void parse_footer(TZZone *zone, const char *footer) {
    const char *s = footer;
    while (*s == ' ' || *s == '\n' || *s == '\r') s++;
    if (!*s) return;

    char std_name[64], dst_name[64];
    int snlen = 0, dnlen = 0;

    if (*s == '<') {
        s++;
        while (*s && *s != '>') std_name[snlen++] = *s++;
        if (*s == '>') s++;
        std_name[snlen] = '\0';
    } else {
        while (*s && ((*s >= 'A' && *s <= 'Z') || (*s >= 'a' && *s <= 'z'))) std_name[snlen++] = *s++;
        std_name[snlen] = '\0';
    }

    int len;
    zone->std_offset = parse_offset_str(s, &len);
    s += len;

    if (*s && *s != ',' && *s != '\n' && *s != '\r') {
        zone->has_dst = true;
        if (*s == '<') {
            s++;
            while (*s && *s != '>') dst_name[dnlen++] = *s++;
            if (*s == '>') s++;
            dst_name[dnlen] = '\0';
        } else {
            while (*s && ((*s >= 'A' && *s <= 'Z') || (*s >= 'a' && *s <= 'z'))) dst_name[dnlen++] = *s++;
            dst_name[dnlen] = '\0';
        }
        if (*s && (*s == '+' || *s == '-' || (*s >= '0' && *s <= '9'))) {
            zone->dst_offset = parse_offset_str(s, &len);
            s += len;
        } else {
            zone->dst_offset = zone->std_offset - 3600;
        }
    } else {
        zone->has_dst = false;
    }

    zone->std_abbr = strdup(std_name);
    zone->dst_abbr = strdup(dst_name);

    if (*s == ',') {
        s++;
        zone->has_start_end = true;
        s++; // 'M'
        zone->start_m = 0; while (*s >= '0' && *s <= '9') zone->start_m = zone->start_m * 10 + (*s++ - '0');
        s++; // '.'
        zone->start_w = 0; while (*s >= '0' && *s <= '9') zone->start_w = zone->start_w * 10 + (*s++ - '0');
        s++; // '.'
        zone->start_d = 0; while (*s >= '0' && *s <= '9') zone->start_d = zone->start_d * 10 + (*s++ - '0');
        if (*s == '/') {
            s++;
            int len_t;
            int t_sec = parse_offset_str(s, &len_t);
            zone->start_h = t_sec / 3600;
            zone->start_min = (t_sec % 3600) / 60;
            if (zone->start_min < 0) zone->start_min += 60;
            zone->start_s = t_sec % 60;
            if (zone->start_s < 0) zone->start_s += 60;
            s += len_t;
        } else {
            zone->start_h = 2; zone->start_min = 0; zone->start_s = 0;
        }
        s++; // ','
        s++; // 'M'
        zone->end_m = 0; while (*s >= '0' && *s <= '9') zone->end_m = zone->end_m * 10 + (*s++ - '0');
        s++; // '.'
        zone->end_w = 0; while (*s >= '0' && *s <= '9') zone->end_w = zone->end_w * 10 + (*s++ - '0');
        s++; // '.'
        zone->end_d = 0; while (*s >= '0' && *s <= '9') zone->end_d = zone->end_d * 10 + (*s++ - '0');
        if (*s == '/') {
            s++;
            int len_t;
            int t_sec = parse_offset_str(s, &len_t);
            zone->end_h = t_sec / 3600;
            zone->end_min = (t_sec % 3600) / 60;
            if (zone->end_min < 0) zone->end_min += 60;
            zone->end_s = t_sec % 60;
            if (zone->end_s < 0) zone->end_s += 60;
            s += len_t;
        } else {
            zone->end_h = 2; zone->end_min = 0; zone->end_s = 0;
        }
    }
}

static bool is_leap(int y) {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

static int days_in_month(int m, int y) {
    static const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (m == 2 && is_leap(y)) return 29;
    return days[m - 1];
}

static int64_t date_to_unix(int y, int m, int d, int h, int min, int s) {
    int64_t total_days = 0;
    if (y >= 1970) {
        for (int year = 1970; year < y; year++) total_days += is_leap(year) ? 366 : 365;
        for (int month = 1; month < m; month++) total_days += days_in_month(month, y);
        total_days += d - 1;
    } else {
        for (int year = 1969; year >= y; year--) total_days -= is_leap(year) ? 366 : 365;
        int64_t days_in_y = 0;
        for (int month = 1; month < m; month++) days_in_y += days_in_month(month, y);
        days_in_y += d - 1;
        total_days += days_in_y;
    }
    return total_days * 86400LL + h * 3600LL + min * 60LL + s;
}

static void unix_to_date(int64_t t, int *y, int *m, int *d, int *h, int *min, int *s) {
    int64_t days = t / 86400LL;
    int64_t rem = t % 86400LL;
    if (rem < 0) { days--; rem += 86400LL; }
    *h = (int)(rem / 3600);
    *min = (int)((rem % 3600) / 60);
    *s = (int)(rem % 60);
    if (days >= 0) {
        int year = 1970;
        while (days >= (is_leap(year) ? 366 : 365)) {
            days -= (is_leap(year) ? 366 : 365);
            year++;
        }
        *y = year;
        int month = 1;
        while (days >= days_in_month(month, year)) {
            days -= days_in_month(month, year);
            month++;
        }
        *m = month;
        *d = (int)days + 1;
    } else {
        int year = 1969;
        while (days < 0) {
            int dy = is_leap(year) ? 366 : 365;
            if (days <= -dy) {
                days += dy;
                year--;
            } else {
                int64_t pos = dy + days;
                int month = 1;
                while (pos >= days_in_month(month, year)) {
                    pos -= days_in_month(month, year);
                    month++;
                }
                *y = year;
                *m = month;
                *d = (int)pos + 1;
                days = 0;
            }
        }
        *y = 1970; *m = 1; *d = 1; // Fallback
    }
}

static int get_weekday(int y, int m, int d) {
    int64_t t = date_to_unix(y, m, d, 0, 0, 0);
    int wd = (int)((t / 86400LL + 4) % 7);
    if (wd < 0) wd += 7;
    return wd;
}

static int64_t find_nth_day(int y, int m, int w, int d_target) {
    int d = 1;
    int found = 0;
    int max_d = days_in_month(m, y);
    while (d <= max_d) {
        if (get_weekday(y, m, d) == d_target) {
            found++;
            if (found == w && w != 5) return date_to_unix(y, m, d, 0, 0, 0);
        }
        d++;
    }
    if (w == 5) {
        for (int i = max_d; i >= 1; i--) {
            if (get_weekday(y, m, i) == d_target) return date_to_unix(y, m, i, 0, 0, 0);
        }
    }
    return -1;
}

static int32_t get_offset(TZZone *zone, int64_t t) {
    if (zone->timecnt > 0) {
        if (t < zone->trans_times[0]) return zone->types[0].offset;
        if (t >= zone->trans_times[zone->timecnt - 1]) {
            // Use footer rule after the last transition
        } else {
            for (int i = 0; i < zone->timecnt - 1; i++) {
                if (t >= zone->trans_times[i] && t < zone->trans_times[i+1])
                    return zone->types[zone->trans_types[i]].offset;
            }
        }
    }
    if (!zone->has_dst || !zone->has_start_end) return zone->std_offset;
    int y, m, d, h, min, s;
    unix_to_date(t - zone->std_offset, &y, &m, &d, &h, &min, &s);
    int64_t start_utc = find_nth_day(y, zone->start_m, zone->start_w, zone->start_d) 
                        + zone->start_h * 3600LL + zone->start_min * 60LL + zone->start_s - zone->std_offset;
    int64_t end_utc = find_nth_day(y, zone->end_m, zone->end_w, zone->end_d) 
                      + zone->end_h * 3600LL + zone->end_min * 60LL + zone->end_s - zone->dst_offset;
    if (start_utc < end_utc) {
        if (t >= start_utc && t < end_utc) return zone->dst_offset;
    } else {
        if (t >= start_utc || t < end_utc) return zone->dst_offset;
    }
    return zone->std_offset;
}

static const char* get_abbr(TZZone *zone, int64_t t) {
    if (zone->timecnt > 0) {
        int type_idx = 0;
        if (t >= zone->trans_times[0]) {
            for (int i = 0; i < zone->timecnt; i++) {
                if (t >= zone->trans_times[i]) type_idx = zone->trans_types[i];
            }
        }
        int char_idx = zone->types[type_idx].abbr_idx;
        return zone->abbrevs + char_idx;
    }
    int32_t off = get_offset(zone, t);
    return (off == zone->dst_offset) ? zone->dst_abbr : zone->std_abbr;
}

void format_local(int64_t t, TZZone *zone, char *buf) {
    int32_t off = get_offset(zone, t);
    int y, m, d, h, min, s;
    unix_to_date(t - off, &y, &m, &d, &h, &min, &s);
    int sign = (off >= 0) ? -1 : 1; // UTC offset is -off
    int32_t utc_off = -off;
    int abs_off = (utc_off < 0) ? -utc_off : utc_off;
    int off_h = abs_off / 3600;
    int off_m = (abs_off % 3600) / 60;
    int off_s = abs_off % 60;
    if (off_s == 0) sprintf(buf, "%04d-%02d-%02dT%02d:%02d:%02d%s%02d:%02d", y, m, d, h, min, s, (utc_off >= 0 ? "+" : "-"), off_h, off_m);
    else sprintf(buf, "%04d-%02d-%02dT%02d:%02d:%02d%s%02d:%02d:%02d", y, m, d, h, min, s, (utc_off >= 0 ? "+" : "-"), off_h, off_m, off_s);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    char qpath[1024];
    sprintf(qpath, "%s/queries.txt", argv[1]);
    FILE *fq = fopen(qpath, "r");
    if (!fq) return 0;
    char line[256];
    while (fgets(line, sizeof(line), fq)) {
        if (line[0] == '\n' || line[0] == '\r') continue;
        char qtype[16], filename[128], time_str[64];
        if (sscanf(line, "%s %s %s", qtype, filename, time_str) < 3) continue;

        char fpath[1024];
        sprintf(fpath, "%s/%s", argv[1], filename);
        FILE *ftz = fopen(fpath, "rb");
        if (!ftz) continue;
        unsigned char h1[44];
        fread(h1, 1, 44, ftz);
        int timecnt1 = read_i32_be(h1 + 24);
        int typecnt1 = read_i32_be(h1 + 32);
        int charcnt1 = read_i32_be(h1 + 36);
        int leapcnt1 = read_i32_be(h1 + 28);
        fseek(ftz, 44 + timecnt1 * 4 + timecnt1 * 1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8, SEEK_CUR);
        unsigned char h2[44];
        fread(h2, 1, 44, ftz);
        int timecnt2 = read_i32_be(h2 + 24);
        int typecnt2 = read_i32_be(h2 + 32);
        int charcnt2 = read_i32_be(h2 + 36);
        int leapcnt2 = read_i32_be(h2 + 28);

        TZZone zone;
        zone.timecnt = timecnt2;
        zone.trans_times = malloc(timecnt2 * 8);
        zone.trans_types = malloc(timecnt2 * 1);
        zone.types = malloc(typecnt2 * sizeof(TZType));
        zone.abbrevs = malloc(charcnt2 + 1);

        for (int i = 0; i < timecnt2; i++) {
            unsigned char b[8];
            fread(b, 1, 8, ftz);
            zone.trans_times[i] = read_i64_be(b);
        }
        fread(zone.trans_types, 1, timecnt2, ftz);
        for (int i = 0; i < typecnt2; i++) {
            unsigned char b[6];
            fread(b, 1, 6, ftz);
            zone.types[i].offset = read_i32_be(b);
            zone.types[i].isdst = b[4];
            zone.types[i].abbr_idx = b[5];
        }
        fread(zone.abbrevs, 1, charcnt2, ftz);
        zone.abbrevs[charcnt2] = '\0';
        fseek(ftz, 44 + timecnt2 * 8 + timecnt2 * 1 + typecnt2 * 6 + charcnt2 + leapcnt2 * 12, SEEK_SET);

        unsigned char footer_buf[1024];
        int fidx = 0;
        int c;
        while ((c = fgetc(ftz)) != EOF && fidx < 1023) footer_buf[fidx++] = (char)c;
        footer_buf[fidx] = '\0';
        parse_footer(&zone, (char*)footer_buf);

        if (strcmp(qtype, "UTC") == 0) {
            int64_t t = atoll(time_str);
            char local_buf[64];
            format_local(t, &zone, local_buf);
            printf("%s -> %s %s\n", line, local_buf, get_abbr(&zone, t));
        } else {
            int y, m, d, h, min, s;
            sscanf(time_str, "%d-%d-%dT%d:%d:%d", &y, &m, &d, &h, &min, &s);
            int64_t L = date_to_unix(y, m, d, h, min, s);
            int64_t candidates[10];
            int count = 0;

            int32_t possible_offsets[100];
            int off_count = 0;
            for(int i=0; i<zone.typecnt; i++) possible_offsets[off_count++] = zone.types[i].offset;
            possible_offsets[off_count++] = zone.std_offset;
            if(zone.has_dst) possible_offsets[off_count++] = zone.dst_offset;

            for(int i=0; i<off_count; i++) {
                int64_t t = L + possible_offsets[i];
                if (get_offset(&zone, t) == possible_offsets[i]) {
                    bool dup = false;
                    for(int j=0; j<count; j++) if(candidates[j] == t) dup = true;
                    if(!dup) candidates[count++] = t;
                }
            }

            if (count == 1) {
                int64_t t = candidates[0];
                int32_t off = get_offset(&zone, t);
                int32_t utc_off = -off;
                int abs_off = (utc_off < 0) ? -utc_off : utc_off;
                printf("%s -> %lld %s%02d:%02d %s\n", line, t, (utc_off >= 0 ? "+" : "-"), abs_off/3600, (abs_off%3600)/60, get_abbr(&zone, t));
            } else if (count >= 2) {
                for(int i=0; i<count-1; i++) for(int j=i+1; j<count; j++) if(candidates[i] > candidates[j]) { int64_t tmp = candidates[i]; candidates[i] = candidates[j]; candidates[j] = tmp; }
                int64_t t1 = candidates[0], t2 = candidates[1];
                int32_t off1 = get_offset(&zone, t1), off2 = get_offset(&zone, t2);
                int32_t utc1 = -off1, utc2 = -off2;
                int abs1 = (utc1 < 0) ? -utc1 : utc1, abs2 = (utc2 < 0) ? -utc2 : utc2;
                printf("%s -> %lld %s%02d:%02d %s | %lld %s%02d:%02d %s\n", line, t1, (utc1 >= 0 ? "+" : "-"), abs1/3600, (abs1%3600)/60, get_abbr(&zone, t1), t2, (utc2 >= 0 ? "+" : "-"), abs2/3600, (abs2%3600)/60, get_abbr(&zone, t2));
            } else {
                int32_t off_before = zone.std_offset;
                for(int i=0; i<zone.timecnt; i++) {
                    int64_t t_trans = zone.trans_times[i];
                    if (L + get_offset(&zone, t_trans - 1) == L) { // This is a simplification
                    }
                }
                // Correct GAP: find the transition that skipped L
                int64_t t_gap = L + zone.std_offset; 
                // In most cases, the gap is caused by a transition. Find the most recent transition before L+off.
                for(int i=0; i < zone.timecnt; i++) {
                    int64_t t_trans = zone.trans_times[i];
                    int32_t off_prev = (i == 0) ? zone.types[0].offset : zone.types[zone.trans_types[i-1]].offset;
                    if (t_trans - off_prev <= L + off_prev && t_trans - get_offset(&zone, t_trans) > L + off_prev) {
                        off_before = off_prev;
                        break;
                    }
                }
                t_gap = L + off_before;
                char local_buf[64];
                format_local(t_gap, &zone, local_buf);
                printf("%s -> GAP %lld %s %s\n", line, t_gap, local_buf, get_abbr(&zone, t_gap));
            }
        }
        free(zone.trans_times); free(zone.trans_types); free(zone.types); free(zone.abbrevs); free(zone.std_abbr); free(zone.dst_abbr);
        fclose(ftz);
    }
    fclose(fq);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

type TypeRecord = {
    offset: number;
    isDst: number;
    abbrIdx: number;
};

type Transition = {
    time: number;
    typeIdx: number;
};

type FooterRule = {
    stdOffset: number;
    dstOffset: number;
    stdName: string;
    dstName: string;
    startRule: { m: number, w: number, d: number, time: number } | null;
    endRule: { m: number, w: number, d: number, time: number } | null;
};

class TZZone {
    transitions: Transition[] = [];
    types: TypeRecord[] = [];
    abbreviations: string[] = [];
    footer: FooterRule = { stdOffset: 0, dstOffset: 0, stdName: '', dstName: '', startRule: null, endRule: null };

    constructor(buffer: Buffer) {
        const view = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength);

        // Header 1
        const v1 = view.getUint8(4);
        const isutcnt = view.getInt32(20, false);
        const isstdcnt = view.getInt32(24, false);
        const leapcnt = view.getInt32(28, false);
        const timecnt = view.getInt32(32, false);
        const typecnt = view.getInt32(36, false);
        const charcnt = view.getInt32(40, false);

        // Skip block 1
        let offset = 44 + timecnt * 4 + timecnt * 1 + typecnt * 6 + charcnt + leapcnt * 8 + isstdcnt + isutcnt;

        // Header 2
        const v2 = view.getUint8(offset + 4);
        const timecnt2 = view.getInt32(offset + 32, false);
        const typecnt2 = view.getInt32(offset + 36, false);
        const charcnt2 = view.getInt32(offset + 40, false);

        offset += 44;
        for (let i = 0; i < timecnt2; i++) {
            this.transitions.push({
                time: Number(view.getBigInt64(offset, false)),
                typeIdx: 0
            });
            offset += 8;
        }
        for (let i = 0; i < timecnt2; i++) {
            this.transitions[i].typeIdx = view.getUint8(offset++);
        }
        for (let i = 0; i < typecnt2; i++) {
            this.types.push({
                offset: view.getInt32(offset, false),
                isDst: view.getUint8(offset + 4),
                abbrIdx: view.getUint8(offset + 5),
            });
            offset += 6;
        }
        const chars = buffer.slice(offset, offset + charcnt2);
        let currentAbbr = "";
        for (let i = 0; i < chars.length; i++) {
            if (chars[i] === 0) {
                this.abbreviations.push(currentAbbr);
                currentAbbr = "";
            } else {
                currentAbbr += String.fromCharCode(chars[i]);
            }
        }
        if (currentAbbr) this.abbreviations.push(currentAbbr);

        // Footer
        let footerStart = buffer.indexOf(10, offset); // find newline
        if (footerStart === -1) return;
        let footerEnd = buffer.indexOf(10, footerStart + 1);
        if (footerEnd === -1) footerEnd = buffer.length;
        const tzString = buffer.slice(footerStart + 1, footerEnd).toString();
        this.parseFooter(tzString);
    }

    parseFooter(s: string) {
        let i = 0;
        const parseName = () => {
            if (s[i] === '<') {
                let end = s.indexOf('>', i);
                let name = s.slice(i + 1, end);
                i = end + 1;
                return name;
            } else {
                let start = i;
                while (i < s.length && /[a-zA-Z]/.test(s[i])) i++;
                return s.slice(start, i);
            }
        };
        const parseOffset = () => {
            let sign = 1;
            if (s[i] === '+') { sign = 1; i++; }
            else if (s[i] === '-') { sign = -1; i++; }
            let numStr = "";
            while (i < s.length && (/[0-9]/.test(s[i]) || s[i] === ':')) {
                numStr += s[i++];
            }
            let parts = numStr.split(':');
            let total = 0;
            if (parts.length === 1) {
                total = parseInt(parts[0]) * 3600;
            } else {
                total = parseInt(parts[0]) * 3600;
                if (parts[1]) total += parseInt(parts[1]) * 60;
                if (parts[2]) total += parseInt(parts[2]);
            }
            return total * sign;
        };

        this.footer.stdName = parseName();
        this.footer.stdOffset = parseOffset();
        if (i < s.length && s[i] !== ',') {
            this.footer.dstName = parseName();
            if (i < s.length && (s[i] === '+' || s[i] === '-' || /[0-9]/.test(s[i]))) {
                this.footer.dstOffset = parseOffset();
            } else {
                this.footer.dstOffset = this.footer.stdOffset - 3600;
            }
        } else {
            this.footer.dstName = this.footer.stdName;
            this.footer.dstOffset = this.footer.stdOffset;
        }

        if (s[i] === ',') {
            i++;
            const parseRule = () => {
                if (i >= s.length) return null;
                if (s[i] !== 'M') return null;
                i++;
                let m = parseInt(s.slice(i));
                i += s.slice(i).indexOf('.').slice(0,0).length || 0; // dummy
                let match = s.slice(i).match(/^(\d)\.(\d)\.(\d)/);
                if (!match) return null;
                let [_, wStr, dStr, timeStr] = s.slice(i).match(/^(\d)\.(\d)\.(\d)(?:\/([+-]?\d+:?\d*:?\d*)?)?/);
                // Wait, the regex above is a bit messy. Let's be precise.
                // The format is M m . w . d [/time]
                // We already consumed 'M'.
            };
            // Better rule parser
            const parseRuleS = (str: string) => {
                let m = parseInt(str.slice(1, str.indexOf('.')));
                let rem = str.slice(str.indexOf('.') + 1);
                let w = parseInt(rem.slice(0, rem.indexOf('.')));
                let rem2 = rem.slice(rem.indexOf('.') + 1);
                let d = parseInt(rem2.slice(0, rem2.indexOf('/')));
                let timeStr = rem2.includes('/') ? rem2.slice(rem2.indexOf('/') + 1) : "02:00:00";

                let sign = 1;
                if (timeStr.startsWith('+')) { sign = 1; timeStr = timeStr.slice(1); }
                else if (timeStr.startsWith('-')) { sign = -1; timeStr = timeStr.slice(1); }
                let parts = timeStr.split(':');
                let total = 0;
                if (parts.length === 1) total = parseInt(parts[0]) * 3600;
                else {
                    total = parseInt(parts[0]) * 3600;
                    if (parts[1]) total += parseInt(parts[1]) * 60;
                    if (parts[2]) total += parseInt(parts[2]);
                }
                return { m, w, d, time: total * sign };
            };

            let rules = s.slice(i).split(',');
            if (rules.length >= 1) this.footer.startRule = parseRuleS(rules[0]);
            if (rules.length >= 2) this.footer.endRule = parseRuleS(rules[1]);
        }
    }

    getOffset(t: number): { offset: number, abbr: string } {
        let typeIdx = 0;
        if (this.transitions.length > 0) {
            if (t < this.transitions[0].time) {
                typeIdx = 0;
            } else {
                let low = 0, high = this.transitions.length - 1;
                while (low <= high) {
                    let mid = Math.floor((low + high) / 2);
                    if (this.transitions[mid].time <= t) {
                        typeIdx = this.transitions[mid].typeIdx;
                        low = mid + 1;
                    } else {
                        high = mid - 1;
                    }
                }
            }
        }

        if (this.transitions.length > 0 && t >= this.transitions[this.transitions.length - 1].time) {
            // Footer rule
            const year = new Date(t * 1000).getUTCFullYear();
            const tStart = this.getTransitionTime(year, true);
            const tEnd = this.getTransitionTime(year, false);
            let isDst = false;
            if (tStart < tEnd) {
                if (t >= tStart && t < tEnd) isDst = true;
            } else if (tStart > tEnd) {
                if (t >= tStart || t < tEnd) isDst = true;
            }

            const offsetTzif = isDst ? -this.footer.dstOffset : -this.footer.stdOffset;
            const abbr = isDst ? this.footer.dstName : this.footer.stdName;
            return { offset: offsetTzif, abbr };
        }

        const type = this.types[typeIdx];
        return { offset: type.offset, abbr: this.abbreviations[type.abbrIdx] };
    }

    getTransitionTime(year: number, isStart: boolean) {
        const rule = isStart ? this.footer.startRule : this.footer.endRule;
        if (!rule) return 0;

        let date = new Date(Date.UTC(year, rule.m - 1, 1));
        while (date.getUTCDay() !== rule.d) date.setUTCDate(date.getUTCDate() + 1);

        if (rule.w < 5) {
            date.setUTCDate(date.getUTCDate() + (rule.w - 1) * 7);
        } else {
            let nextMonth = new Date(Date.UTC(year, rule.m, 1));
            date = new Date(nextMonth);
            date.setUTCDate(date.getUTCDate() - 1);
            while (date.getUTCDay() !== rule.d) date.setUTCDate(date.getUTCDate() - 1);
        }

        const localT = date.getTime() / 1000 + rule.time;
        const posixOffset = isStart ? this.footer.stdOffset : this.footer.dstOffset;
        return localT - posixOffset;
    }

    utcToLocal(t: number) {
        const { offset, abbr } = this.getOffset(t);
        const localT = t + offset;
        const date = new Date(localT * 1000);

        const y = date.getUTCFullYear();
        const m = String(date.getUTCMonth() + 1).padStart(2, '0');
        const d = String(date.getUTCDate()).padStart(2, '0');
        const hh = String(date.getUTCHours()).padStart(2, '0');
        const mm = String(date.getUTCMinutes()).padStart(2, '0');
        const ss = String(date.getUTCSeconds()).padStart(2, '0');

        let offStr = (offset >= 0 ? '+' : '-') + 
                     String(Math.floor(Math.abs(offset) / 3600)).padStart(2, '0') + ':' + 
                     String(Math.floor((Math.abs(offset) % 3600) / 60)).padStart(2, '0');
        if (Math.abs(offset) % 60 !== 0) {
            offStr += ':' + String(Math.abs(offset) % 60).padStart(2, '0');
        }

        return { local: `${y}-${m}-${d}T${hh}:${mm}:${ss}${offStr}`, abbr };
    }
}

function solve() {
    const dir = process.argv[2];
    if (!dir) return;
    const queriesPath = path.join(dir, 'queries.txt');
    const queries = fs.readFileSync(queriesPath, 'utf8').split('\n').filter(l => l.trim());

    const zones = new Map<string, TZZone>();

    for (const query of queries) {
        const parts = query.split(' ');
        const type = parts[0];
        const fileName = parts[1];
        if (!zones.has(fileName)) {
            const buffer = fs.readFileSync(path.join(dir, fileName));
            zones.set(fileName, new TZZone(buffer));
        }
        const zone = zones.get(fileName)!;

        if (type === 'UTC') {
            const t = parseInt(parts[2]);
            const { local, abbr } = zone.utcToLocal(t);
            process.stdout.write(`${query} -> ${local} ${abbr}\n`);
        } else {
            const wallClock = parts[3];
            const [yStr, rest] = wallClock.split('T');
            const [mStr, dStr, timeStr] = rest.split(':').slice(0, 3).concat(rest.split(':').slice(3, 4)[0] || "").join(':').split(':'); // This is wrong
            // Correct split
            const dateParts = wallClock.split('T');
            const dayParts = dateParts[0].split('-');
            const timeParts = dateParts[1].split(':');

            const baseUnix = Date.UTC(
                parseInt(dayParts[0]),
                parseInt(dayParts[1]) - 1,
                parseInt(dayParts[2]),
                parseInt(timeParts[0]),
                parseInt(timeParts[1]),
                parseInt(timeParts[2])
            ) / 1000;

            const offsets = new Set<number>();
            zone.types.forEach(t => offsets.add(t.offset));
            offsets.add(-zone.footer.stdOffset);
            offsets.add(-zone.footer.dstOffset);

            const matches: { t: number, offset: number, abbr: string }[] = [];
            for (const off of offsets) {
                const t = baseUnix - off;
                const { offset, abbr } = zone.getOffset(t);
                if (offset === off) {
                    const { local } = zone.utcToLocal(t);
                    if (local.split('+').slice(0,1)[0] === (dateParts[0] + 'T' + timeParts.join(':')) || 
                        local.split('-').slice(0,1)[0] === (dateParts[0] + 'T' + timeParts.join(':')) || // This is a bit fragile
                        true) {
                        // Re-verify using the la-val
                        const res = zone.utcToLocal(t);
                        if (res.local.startsWith(wallClock)) {
                            matches.push({ t, offset, abbr });
                        }
                    }
                }
            }

            // De-duplicate matches
            const uniqueMatches = matches.filter((v, i, a) => a.findIndex(t => t.t === v.t) === i).sort((a, b) => a.t - b.t);

            if (uniqueMatches.length === 1) {
                const m = uniqueMatches[0];
                let offStr = (m.offset >= 0 ? '+' : '-') + 
                             String(Math.floor(Math.abs(m.offset) / 3600)).padStart(2, '0') + ':' + 
                             String(Math.floor((Math.abs(m.offset) % 3600) / 60)).padStart(2, '0');
                if (Math.abs(m.offset) % 60 !== 0) offStr += ':' + String(Math.abs(m.offset) % 60).padStart(2, '0');
                process.stdout.write(`${query} -> ${m.t} ${offStr} ${m.abbr}\n`);
            } else if (uniqueMatches.length > 1) {
                const res = uniqueMatches.map(m => {
                    let offStr = (m.offset >= 0 ? '+' : '-') + 
                                 String(Math.floor(Math.abs(m.offset) / 3600)).padStart(2, '0') + ':' + 
                                 String(Math.floor((Math.abs(m.offset) % 3600) / 60)).padStart(2, '0');
                    if (Math.abs(m.offset) % 60 !== 0) offStr += ':' + String(Math.abs(m.offset) % 60).padStart(2, '0');
                    return `${m.t} ${offStr} ${m.abbr}`;
                }).join(' | ');
                process.stdout.write(`${query} -> ${res}\n`);
            } else {
                // Gap: find offset before
                // Binary search for the gap
                let low = baseUnix - 1000000, high = baseUnix + 1000000;
                for (let i = 0; i < 100; i++) {
                    let mid = (low + high) / 2;
                    if (zone.utcToLocal(mid).local.startsWith(wallClock)) {
                        low = mid; break;
                    }
                    if (zone.utcToLocal(mid).local < wallClock) low = mid;
                    else high = mid;
                }
                const { offset: offBefore } = zone.getOffset(low);
                const tGap = baseUnix - offBefore;
                const { local, abbr } = zone.utcToLocal(tGap);
                process.stdout.write(`${query} -> GAP ${tGap} ${local} ${abbr}\n`);
            }
        }
    }
}

