import * as fs from 'fs';
import * as path from 'path';

type TypeRecord = {
    utcOffset: number;
    isDst: number;
    abbrIdx: number;
};

type Transition = {
    time: number;
    typeIdx: number;
};

type FooterRule = {
    stdPosixOffset: number;
    dstPosixOffset: number;
    stdName: string;
    dstName: string;
    startRule: { m: number, w: number, d: number, time: number } | null;
    endRule: { m: number, w: number, d: number, time: number } | null;
};

class TZZone {
    transitions: Transition[] = [];
    types: TypeRecord[] = [];
    abbreviations: string[] = [];
    footer: FooterRule = { stdPosixOffset: 0, dstPosixOffset: 0, stdName: '', dstName: '', startRule: null, endRule: null };

    constructor(buffer: Buffer) {
        const view = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength);

        const isutcnt = view.getInt32(20, false);
        const isstdcnt = view.getInt32(24, false);
        const leapcnt = view.getInt32(28, false);
        const timecnt = view.getInt32(32, false);
        const typecnt = view.getInt32(36, false);
        const charcnt = view.getInt32(40, false);

        let offset = 44 + timecnt * 4 + timecnt * 1 + typecnt * 6 + charcnt + leapcnt * 8 + isstdcnt + isutcnt;

        const timecnt2 = view.getInt32(offset + 32, false);
        const typecnt2 = view.getInt32(offset + 36, false);
        const charcnt2 = view.getInt32(offset + 40, false);

        offset += 44;
        for (let i = 0; i < timecnt2; i++) {
            this.transitions.push({
                time: Number(view.getBigInt64(offset, false)),
                typeIdx: 0
            });
            offset += 8;
        }
        for (let i = 0; i < timecnt2; i++) {
            this.transitions[i].typeIdx = view.getUint8(offset++);
        }
        for (let i = 0; i < typecnt2; i++) {
            this.types.push({
                utcOffset: -view.getInt32(offset, false),
                isDst: view.getUint8(offset + 4),
                abbrIdx: view.getUint8(offset + 5),
            });
            offset += 6;
        }
        const chars = buffer.slice(offset, offset + charcnt2);
        let currentAbbr = "";
        for (let i = 0; i < chars.length; i++) {
            if (chars[i] === 0) {
                this.abbreviations.push(currentAbbr);
                currentAbbr = "";
            } else {
                currentAbbr += String.fromCharCode(chars[i]);
            }
        }
        if (currentAbbr) this.abbreviations.push(currentAbbr);

        let footerStart = buffer.indexOf(10, offset);
        if (footerStart === -1) return;
        let footerEnd = buffer.indexOf(10, footerStart + 1);
        if (footerEnd === -1) footerEnd = buffer.length;
        const tzString = buffer.slice(footerStart + 1, footerEnd).toString();
        this.parseFooter(tzString);
    }

    parseFooter(s: string) {
        let i = 0;
        const parseName = () => {
            if (i >= s.length) return "";
            if (s[i] === '<') {
                let end = s.indexOf('>', i);
                let name = s.slice(i + 1, end);
                i = end + 1;
                return name;
            } else {
                let start = i;
                while (i < s.length && /[a-zA-Z]/.test(s[i])) i++;
                return s.slice(start, i);
            }
        };
        const parseOffset = () => {
            if (i >= s.length) return 0;
            let sign = 1;
            if (s[i] === '+') { sign = 1; i++; }
            else if (s[i] === '-') { sign = -1; i++; }
            let numStr = "";
            while (i < s.length && (/[0-9]/.test(s[i]) || s[i] === ':')) {
                numStr += s[i++];
            }
            let parts = numStr.split(':');
            let total = 0;
            if (parts.length >= 1) total += parseInt(parts[0]) * 3600;
            if (parts.length >= 2) total += parseInt(parts[1]) * 60;
            if (parts.length >= 3) total += parseInt(parts[2]);
            return total * sign;
        };

        this.footer.stdName = parseName();
        this.footer.stdPosixOffset = parseOffset();
        if (i < s.length && s[i] !== ',') {
            this.footer.dstName = parseName();
            if (i < s.length && (s[i] === '+' || s[i] === '-' || /[0-9]/.test(s[i]))) {
                this.footer.dstPosixOffset = parseOffset();
            } else {
                this.footer.dstPosixOffset = this.footer.stdPosixOffset - 3600;
            }
        } else {
            this.footer.dstName = this.footer.stdName;
            this.footer.dstPosixOffset = this.footer.stdPosixOffset;
        }

        if (i < s.length && s[i] === ',') {
            i++;
            const parseRuleS = (str: string) => {
                if (!str || str[0] !== 'M') return null;
                let dot1 = str.indexOf('.');
                let m = parseInt(str.slice(1, dot1));
                let rem = str.slice(dot1 + 1);
                let dot2 = rem.indexOf('.');
                let w = parseInt(rem.slice(0, dot2));
                let rem2 = rem.slice(dot2 + 1);
                let slash = rem2.indexOf('/');
                let d = parseInt(slash === -1 ? rem2 : rem2.slice(0, slash));
                let timeStr = slash === -1 ? "02:00:00" : rem2.slice(slash + 1);

                let sign = 1;
                if (timeStr.startsWith('+')) { sign = 1; timeStr = timeStr.slice(1); }
                else if (timeStr.startsWith('-')) { sign = -1; timeStr = timeStr.slice(1); }
                let parts = timeStr.split(':');
                let total = 0;
                if (parts.length >= 1) total += parseInt(parts[0]) * 3600;
                if (parts.length >= 2) total += parseInt(parts[1]) * 60;
                if (parts.length >= 3) total += parseInt(parts[2]);
                return { m, w, d, time: total * sign };
            };

            let rules = s.slice(i).split(',');
            if (rules.length >= 1) this.footer.startRule = parseRuleS(rules[0]);
            if (rules.length >= 2) this.footer.endRule = parseRuleS(rules[1]);
        }
    }

    getOffset(t: number): { offset: number, abbr: string } {
        if (this.transitions.length > 0 && t >= this.transitions[this.transitions.length - 1].time) {
            const year = new Date(t * 1000).getUTCFullYear();
            const tStart = this.getTransitionTime(year, true);
            const tEnd = this.getTransitionTime(year, false);
            let isDst = false;
            if (tStart < tEnd) {
                if (t >= tStart && t < tEnd) isDst = true;
            } else if (tStart > tEnd) {
                if (t >= tStart || t < tEnd) isDst = true;
            }
            return isDst ? { offset: -this.footer.dstPosixOffset, abbr: this.footer.dstName } 
                         : { offset: -this.footer.stdPosixOffset, abbr: this.footer.stdName };
        }

        let typeIdx = 0;
        if (this.transitions.length > 0) {
            if (t < this.transitions[0].time) {
                typeIdx = 0;
            } else {
                let low = 0, high = this.transitions.length - 1;
                while (low <= high) {
                    let mid = Math.floor((low + high) / 2);
                    if (this.transitions[mid].time <= t) {
                        typeIdx = this.transitions[mid].typeIdx;
                        low = mid + 1;
                    } else {
                        high = mid - 1;
                    }
                }
            }
        }
        const type = this.types[typeIdx];
        return { offset: type.utcOffset, abbr: this.abbreviations[type.abbrIdx] };
    }

    getTransitionTime(year: number, isStart: boolean) {
        const rule = isStart ? this.footer.startRule : this.footer.endRule;
        if (!rule) return 0;

        let date = new Date(Date.UTC(year, rule.m - 1, 1));
        while (date.getUTCDay() !== rule.d) date.setUTCDate(date.getUTCDate() + 1);
        if (rule.w < 5) {
            date.setUTCDate(date.getUTCDate() + (rule.w - 1) * 7);
        } else {
            let nextMonth = new Date(Date.UTC(year, rule.m, 1));
            date = new Date(nextMonth);
            date.setUTCDate(date.getUTCDate() - 1);
            while (date.getUTCDay() !== rule.d) date.setUTCDate(date.getUTCDate() - 1);
        }
        const localT = date.getTime() / 1000 + rule.time;
        const posixOffset = isStart ? this.footer.stdPosixOffset : this.footer.dstPosixOffset;
        return localT + posixOffset;
    }

    utcToLocal(t: number) {
        const { offset, abbr } = this.getOffset(t);
        const localT = t + offset;
        const date = new Date(localT * 1000);
        const y = date.getUTCFullYear();
        const m = String(date.getUTCMonth() + 1).padStart(2, '0');
        const d = String(date.getUTCDate()).padStart(2, '0');
        const hh = String(date.getUTCHours()).padStart(2, '0');
        const mm = String(date.getUTCMinutes()).padStart(2, '0');
        const ss = String(date.getUTCSeconds()).padStart(2, '0');

        let offStr = (offset >= 0 ? '+' : '-') + 
                     String(Math.floor(Math.abs(offset) / 3600)).padStart(2, '0') + ':' + 
                     String(Math.floor((Math.abs(offset) % 3600) / 60)).padStart(2, '0');
        if (Math.abs(offset) % 60 !== 0) {
            offStr += ':' + String(Math.abs(offset) % 60).padStart(2, '0');
        }
        return { local: `${y}-${m}-${d}T${hh}:${mm}:${ss}${offStr}`, abbr };
    }
}

