}

struct TzFile {
    transitions: Vec<i64>,
    type_indices: Vec<u8>,
    types: Vec<TzType>,
    abbreviations: Vec<String>,
    footer: FooterRule,
}

impl TzFile {
    fn load(path: &Path) -> Self {
        let bytes = fs::read(path).expect("Failed to read TZif file");
        let mut pos = 0;

        let mut read_u32 = |p: &mut usize| {
            let val = (bytes[*p] as u64) << 24 | (bytes[*p + 1] as u64) << 16 | (bytes[*p + 2] as u64) << 8 | (bytes[*p + 3] as u64);
            *p += 4;
            val as i32
        };
        let mut read_i64 = |p: &mut usize| {
            let val = (bytes[*p] as u64) << 56 | (bytes[*p + 1] as u64) << 48 | (bytes[*p + 2] as u64) << 40 | (bytes[*p + 3] as u64) << 32 | (bytes[*p + 4] as u64) << 24 | (bytes[*p + 5] as u64) << 16 | (bytes[*p + 6] as u64) << 8 | (bytes[*p + 7] as u64);
            *p += 8;
            val as i64
        };

        pos += 44; // Skip header 1
        let isutcnt1 = read_u32(&mut pos);
        let isstdcnt1 = read_u32(&mut pos);
        let leapcnt1 = read_u32(&mut pos);
        let timecnt1 = read_u32(&mut pos);
        let typecnt1 = read_u32(&mut pos);
        let charcnt1 = read_u32(&mut pos);

        pos += (timecnt1 as usize) * 4;
        pos += (timecnt1 as usize);
        pos += (typecnt1 as usize) * 6;
        pos += (charcnt1 as usize);
        pos += (leapcnt1 as usize) * 8;
        pos += (isstdcnt1 as usize);
        pos += (isutcnt1 as usize);

        pos += 44; // Header 2
        let _isutcnt2 = read_u32(&mut pos);
        let _isstdcnt2 = read_u32(&mut pos);
        let _leapcnt2 = read_u32(&mut pos);
        let timecnt2 = read_u32(&mut pos);
        let typecnt2 = read_u32(&mut pos);
        let charcnt2 = read_u32(&mut pos);

        let mut transitions = Vec::with_capacity(timecnt2 as usize);
        for _ in 0..timecnt2 { transitions.push(read_i64(&mut pos)); }

        let mut type_indices = Vec::with_capacity(timecnt2 as usize);
        for _ in 0..timecnt2 { type_indices.push(bytes[pos]); pos += 1; }

        let mut types = Vec::with_capacity(typecnt2 as usize);
        for _ in 0..typecnt2 {
            let offset = read_u32(&mut pos);
            let is_dst = bytes[pos]; pos += 1;
            let abbr_idx = bytes[pos]; pos += 1;
            types.push(TzType { utc_offset: offset, is_dst, abbr_idx });
        }

        let mut abbreviations = Vec::new();
        let mut current_abbr = String::new();
        for _ in 0..charcnt2 {
            let b = bytes[pos]; pos += 1;
            if b == 0 {
                abbreviations.push(current_abbr.clone());
                current_abbr.clear();
            } else {
                current_abbr.push(b as char);
            }
        }
        if !current_abbr.is_empty() { abbreviations.push(current_abbr); }

        pos += (0 as usize) * 12; // leapcnt2 is ignored
        pos += 0; // isstdcnt2 ignored
        pos += 0; // isutcnt2 ignored

        while pos < bytes.len() && bytes[pos] != b'\n' { pos += 1; }
        pos += 1;
        let mut footer_str = String::new();
        while pos < bytes.len() && bytes[pos] != b'\n' {
            footer_str.push(bytes[pos] as char);
            pos += 1;
        }

        TzFile { transitions, type_indices, types, abbreviations, footer: parse_footer(&footer_str) }
    }

    fn get_type_at(&self, t: i64) -> (TzType, String) {
        if self.transitions.is_empty() || t < self.transitions[0] {
            let ty = self.types[0];
            let abbr = self.abbreviations.get(ty.abbr_idx as usize).cloned().unwrap_or_else(|| "GMT".to_string());
            return (ty, abbr);
        }
        if t > self.transitions[self.transitions.len() - 1] {
            return self.get_footer_type(t);
        }
        let idx = match self.transitions.binary_search(&t) {
            Ok(i) => i,
            Err(i) => i - 1,
        };
        let ty = self.types[self.type_indices[idx] as usize];
        let abbr = self.abbreviations.get(ty.abbr_idx as usize).cloned().unwrap_or_else(|| "GMT".to_string());
        (ty, abbr)
    }

    fn get_footer_type(&self, t: i64) -> (TzType, String) {
        let year = get_year_from_unix(t);
        let t_start = self.calc_transition_utc(year, true);
        let t_end = self.calc_transition_utc(year, false);
        let is_dst = if t_start < t_end {
            t >= t_start && t < t_end
        } else if t_start > t_end {
            t >= t_start || t < t_end
        } else {
            false
        };

        if is_dst {
            let offset = self.footer.dst_offset.unwrap_or(self.footer.std_offset - 3600);
            (TzType { utc_offset: offset, is_dst: 1, abbr_idx: 1 }, self.footer.dst_abbr.clone())
        } else {
            (TzType { utc_offset: self.footer.std_offset, is_dst: 0, abbr_idx: 0 }, self.footer.std_abbr.clone())
        }
    }

    fn calc_transition_utc(&self, year: i32, is_start: bool) -> i64 {
        let rule = if is_start { &self.footer.start_rule } else { &self.footer.end_rule };
        if rule.is_none() { return i64::MAX; }
        let rule = rule.unwrap();
        let offset = if is_start { self.footer.std_offset } else { self.footer.dst_offset.unwrap_or(self.footer.std_offset - 3600) };
        let (m, d) = get_date_from_rule(year, rule);
        let local_t = date_to_unix(year, m, d, rule.time_offset);
        local_t - offset as i64
    }
}

fn parse_offset(s: &str) -> i32 {
    if s.is_empty() { return 0; }
    let (sign, rest) = if s.starts_with('+') { ('+', &s[1..]) } else if s.starts_with('-') { ('-', &s[1..]) } else { ('+', s) };
    let parts: Vec<&str> = rest.split(':').collect();
    let mut total = 0;
    if parts.len() >= 1 { total += parts[0].parse::<i32>().unwrap_or(0) * 3600; }
    if parts.len() >= 2 { total += parts[1].parse::<i32>().unwrap_or(0) * 60; }
    if parts.len() >= 3 { total += parts[2].parse::<i32>().unwrap_or(0); }
    if sign == '-' { -total } else { total }
}

fn parse_footer(s: &str) -> FooterRule {
    let parts: Vec<&str> = s.split(',').collect();
    let std_part = parts[0];
    let (std_name, std_off_str) = split_name_offset(std_part);
    let std_offset = parse_offset(std_off_str);

    let mut dst_offset = None;
    let mut dst_name = String::new();
    let mut start_rule = None;
    let mut end_rule = None;

    if parts.len() > 1 {
        let dst_part = parts[1];
        let (name, off_str) = split_name_offset(dst_part);
        dst_name = name.to_string();
        if !off_str.is_empty() {
            dst_offset = Some(parse_offset(off_str));
        }
        if parts.len() > 2 { start_rule = Some(parse_rule(parts[2])); }
        if parts.len() > 3 { end_rule = Some(parse_rule(parts[3])); }
    }

    FooterRule { std_offset, std_abbr: std_name.to_string(), dst_offset, dst_abbr: dst_name, start_rule, end_rule }
}

fn split_name_offset(s: &str) -> (&str, &str) {
    if s.starts_with('<') {
        if let Some(end) = s.find('>') {
            return (&s[0..end + 1], &s[end + 1..]);
        }
    }
    let mut i = 0;
    while i < s.len() && s.as_bytes()[i].is_ascii_alphabetic() { i += 1; }
    if i < s.len() {
        let rest = &s[i..];
        if rest.starts_with('+') || rest.starts_with('-') || (rest.len() > 0 && rest.as_bytes()[0].is_ascii_digit()) {
            return (&s[0..i], rest);
        }
    }
    (s, "")
}

fn parse_rule(s: &str) -> Rule {
    let (rule_part, time_part) = if let Some(idx) = s.find('/') {
        (&s[0..idx], &s[idx + 1..])
    } else {
        (s, "02:00:00")
    };
    let parts: Vec<&str> = rule_part.split('.').collect();
    let m = parts[0].parse::<u8>().unwrap();
    let w = parts[1].parse::<u8>().unwrap();
    let d = parts[2].parse::<u8>().unwrap();
    let time_offset = parse_offset(time_part);
    Rule { month: m, week: w, day: d, time_offset }
}

fn is_leap(y: i32) -> bool { (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0) }
fn days_in_month(m: u8, y: i32) -> u8 {
    match m {
        1|3|5|7|8|10|12 => 31,
        4|6|9|11 => 30,
        2 => if is_leap(y) { 29 } else { 28 },
        _ => 0,
    }
}

fn date_to_unix(y: i32, m: u8, d: u8, time_offset: i32) -> i64 {
    let mut days = 0i64;
    if y >= 1970 {
        for year in 1970..y { days += if is_leap(year) { 366 } else { 365 }; }
    } else {
        for year in (y..1970).rev() { days -= if is_leap(year) { 366 } else { 365 }; }
    }
    for month in 1..m { days += days_in_month(month, y) as i64; }
    days += (d - 1) as i64;
    days * 86400 + time_offset as i64
}

fn get_year_from_unix(t: i64) -> i32 {
    let mut y = 1970;
    let mut days = t / 86400;
    let mut rem = t % 86400;
    if rem < 0 { days -= 1; rem += 86400; }

    if days >= 0 {
        while days >= (if is_leap(y) { 366 } else { 365 }) {
            days -= if is_leap(y) { 366 } else { 365 };
            y += 1;
        }
    } else {
        while days < 0 {
            y -= 1;
            days += if is_leap(y) { 366 } else { 365 };
        }
    }
    // The rem part might push the date into the next year
    let mut d_y = date_to_unix(y, 1, 1, 0);
    let mut d_y_next = date_to_unix(y + 1, 1, 1, 0);
    if t >= d_y_next { y += 1; }
    else if t < d_y { y -= 1; }
    y
}

fn get_date_from_rule(y: i32, rule: &Rule) -> (u8, u8) {
    let mut count = 0;
    let mut last_day = 0;
    for d in 1..=days_in_month(rule.month, y) {
        if get_weekday(y, rule.month, d) == rule.day {
            count += 1;
            if count == rule.week && rule.week < 5 { return (rule.month, d); }
            last_day = d;
        }
    }
    (rule.month, last_day)
}

fn get_weekday(y: i32, m: u8, d: u8) -> u8 {
    let t = date_to_unix(y, m, d, 0);
    (((t / 86400 + 4) % 7 + 7) % 7) as u8
}

fn format_offset(offset: i32) -> String {
    let sign = if offset < 0 { "-" } else { "+" };
    let abs_off = offset.abs();
    let h = abs_off / 3600;
    let m = (abs_off % 3600) / 60;
    let s = abs_off % 60;
    if s == 0 { format!("{}{:02}:{:02}", sign, h, m) } else { format!("{}{:02}:{:02}:{:02}", sign, h, m, s) }
}

fn unix_to_local_time(t: i64) -> (i32, i32, u8, u8, u8, u8) {
    let mut days = t / 86400;
    let mut sec = t % 86400;
    if sec < 0 { sec += 86400; days -= 1; }
    let mut y = 1970;
    if days >= 0 {
        while days >= (if is_leap(y) { 366 } else { 365 }) {
            days -= if is_leap(y) { 366 } else { 365 };
            y += 1;
        }
    } else {
        while days < 0 {
            y -= 1;
            days += if is_leap(y) { 366 } else { 365 };
        }
    }
    let mut m = 1;
    while m <= 12 && days >= days_in_month(m, y) as i64 {
        days -= days_in_month(m, y) as i64;
        m += 1;
    }
    let d = (days + 1) as u8;
    let h = (sec / 3600) as u8;
    let min = ((sec % 3600) / 60) as u8;
    let s = (sec % 60) as u8;
    (y, m as i32, d, h, min, s)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let queries_path = Path::new(dir).join("queries.txt");
    let reader = BufReader::new(fs::File::open(queries_path).expect("Failed to open queries.txt"));

    for line in reader.lines() {
        let line = line.unwrap();
        if line.trim().is_empty() { continue; }
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 3 { continue; }

        let tz_path = Path::new(dir).join(parts[1]);
        let tz = TzFile::load(&tz_path);

        if parts[0] == "UTC" {
            let t = parts[2].parse::<i64>().unwrap();
            let (tz_type, abbr) = tz.get_type_at(t);
            let local_t = t - tz_type.utc_offset as i64;
            let (y, m, d, h, min, s) = unix_to_local_time(local_t);
            println!("{} -> {:04}-{:02}-{:02}T{:02}:{:02}:{:02}{} {}", line, y, m, d, h, min, s, format_offset(tz_type.utc_offset), abbr);
        } else if parts[0] == "LOCAL" {
            let local_time_str = parts[2];
            let (y_s, m_s, d_s, h_s, min_s, s_s) = {
                let parts: Vec<&str> = local_time_str.split('T').collect();
                let date_parts: Vec<&str> = parts[0].split('-').collect();
                let time_parts: Vec<&str> = parts[1].split(':').collect();
                (date_parts[0].parse::<i32>().unwrap(), date_parts[1].parse::<i32>().unwrap(), date_parts[2].parse::<i32>().unwrap(),
                 time_parts[0].parse::<i32>().unwrap(), time_parts[1].parse::<i32>().unwrap(), time_parts[2].parse::<i32>().unwrap())
            };
            let w = date_to_unix(y_s, m_s as u8, d_s as u8, h_s * 3600 + min_s * 60 + s_s);

            let mut possible_offsets = Vec::new();
            for ty in &tz.types { possible_offsets.push(ty.utc_offset); }
            possible_offsets.push(tz.footer.std_offset);
            if let Some(off) = tz.footer.dst_offset { possible_offsets.push(off); }

            let mut possible_ts = Vec::new();
            for &off in &possible_offsets {
                let t = w + off as i64;
                let (tz_type, abbr) = tz.get_type_at(t);
                if t - tz_type.utc_offset as i64 == w {
                    possible_ts.push((t, tz_type.utc_offset, abbr));
                }
            }
            possible_ts.sort_by_key(|k| k.0);
            possible_ts.dedup_by(|a, b| a.0 == b.0);

            if possible_ts.len() == 1 {
                let (t, off, abbr) = possible_ts[0];
                println!("{} -> {} {} {}", line, t, format_offset(off), abbr);
            } else if possible_ts.len() > 1 {
                let mut res = String::new();
                for (i, (t, off, abbr)) in possible_ts.iter().enumerate() {
                    res.push_str(&format!("{} {} {}", t, format_offset(*off), abbr));
                    if i < possible_ts.len() - 1 { res.push_str(" | "); }
                }
                println!("{} -> {}", line, res);
            } else {
                let mut best_off = 0;
                let mut found = false;
                for &off in &possible_offsets {
                    let t = w + off as i64;
                    let (ty_before, _) = tz.get_type_at(t - 1);
                    let (ty_after, _) = tz.get_type_at(t);
                    if ty_before.utc_offset == off && ty_after.utc_offset != off {
                        best_off = off;
                        found = true;
                        break;
                    }
                }
                if !found {
                    // Fallback to first offset if no transition found
                    best_off = possible_offsets[0];
                }
                let t = w + best_off as i64;
                let (tz_type, abbr) = tz.get_type_at(t);
                let local_t_final = t - tz_type.utc_offset as i64;
                let (y, m, d, h, min, s) = unix_to_local_time(local_t_final);
                println!("{} -> GAP {} {:04}-{:02}-{:02}T{:02}:{:02}:{:02}{} {}", line, t, y, m, d, h, min, s, format_offset(tz_type.utc_offset), abbr);
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <dirent.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

typedef struct {
    uint32_t rate;
    uint16_t channels;
    uint16_t bps;
    uint16_t effective_format;
} WavInfo;

const double LOW_FREQS[] = {697, 770, 852, 941};
const double HIGH_FREQS[] = {1209, 1336, 1477, 1633};
const char DTMF_MAP[4][4] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

void process_file(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return;

    char riff_id[4];
    uint32_t riff_size;
    char wave_id[4];

    if (fread(riff_id, 1, 4, fp) != 4 || memcmp(riff_id, "RIFF", 4) != 0) {
        fclose(fp);
        return;
    }
    if (fread(&riff_size, 4, 1, fp) != 1) {
        fclose(fp);
        return;
    }
    if (fread(wave_id, 1, 4, fp) != 4 || memcmp(wave_id, "WAVE", 4) != 0) {
        fclose(fp);
        return;
    }

    WavInfo info = {0};
    int fmt_found = 0, data_found = 0;
    int16_t *samples = NULL;
    uint32_t num_samples = 0;

    char chunk_id[4];
    uint32_t chunk_size;
    while (fread(chunk_id, 1, 4, fp) == 4) {
        if (fread(&chunk_size, 4, 1, fp) != 1) break;

        if (memcmp(chunk_id, "fmt ", 4) == 0) {
            uint8_t *fmt_body = malloc(chunk_size);
            if (fmt_body) {
                fread(fmt_body, 1, chunk_size, fp);
                uint16_t tag = *(uint16_t *)fmt_body;
                info.channels = *(uint16_t *)(fmt_body + 2);
                info.rate = *(uint32_t *)(fmt_body + 4);
                info.bps = *(uint16_t *)(fmt_body + 14);
                if (tag == 0xFFFE && chunk_size >= 26) {
                    info.effective_format = *(uint16_t *)(fmt_body + 24);
                } else {
                    info.effective_format = tag;
                }
                fmt_found = 1;
                free(fmt_body);
            }
        } else if (memcmp(chunk_id, "data", 4) == 0) {
            samples = malloc(chunk_size);
            if (samples) {
                fread(samples, 1, chunk_size, fp);
                num_samples = chunk_size / (2 * info.channels);
                data_found = 1;
            }
        } else {
            fseek(fp, chunk_size, SEEK_CUR);
        }
        if (chunk_size % 2 != 0) fgetc(fp);
    }
    fclose(fp);

    char name[256];
    const char *last_slash = strrchr(filename, '/');
    strcpy(name, last_slash ? last_slash + 1 : filename);

    if (!fmt_found || !data_found || info.effective_format != 1 || info.bps != 16 || 
        (info.rate != 8000 && info.rate != 16000) || (info.channels < 1 || info.channels > 2)) {
        printf("%s: unsupported\n\n", name);
        if (samples) free(samples);
        return;
    }

    int N = info.rate / 50;
    int num_blocks = num_samples / N;
    char *labels = malloc(num_blocks);
    int16_t *left_channel = malloc(num_samples * 2);
    for (uint32_t i = 0; i < num_samples; i++) {
        left_channel[i] = samples[i * info.channels];
    }

    for (int i = 0; i < num_blocks; i++) {
        double E = 0;
        for (int n = 0; n < N; n++) {
            double x = left_channel[i * N + n];
            E += x * x;
        }

        if (E < 1000000.0 * N) {
            labels[i] = 0;
        } else {
            double r_low[4], r_high[4];
            for (int f_idx = 0; f_idx < 4; f_idx++) {
                double freq = LOW_FREQS[f_idx];
                double c = 2.0 * cos(2.0 * M_PI * freq / info.rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = left_channel[i * N + n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_low[f_idx] = 2.0 * P / (N * E);
            }
            for (int f_idx = 0; f_idx < 4; f_idx++) {
                double freq = HIGH_FREQS[f_idx];
                double c = 2.0 * cos(2.0 * M_PI * freq / info.rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = left_channel[i * N + n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_high[f_idx] = 2.0 * P / (N * E);
            }

            int fl_idx = 0, fh_idx = 0;
            for (int j = 1; j < 4; j++) {
                if (r_low[j] > r_low[fl_idx]) fl_idx = j;
                if (r_high[j] > r_high[fh_idx]) fh_idx = j;
            }

            if (r_low[fl_idx] >= 0.1 && r_high[fh_idx] >= 0.1 && (r_low[fl_idx] + r_high[fh_idx] >= 0.6)) {
                labels[i] = DTMF_MAP[fl_idx][fh_idx];
            } else {
                labels[i] = 0;
            }
        }
    }

    char *bridged = malloc(num_blocks);
    for (int i = 0; i < num_blocks; i++) {
        if (labels[i] == 0 && i > 0 && i < num_blocks - 1 && labels[i - 1] == labels[i + 1] && labels[i - 1] != 0) {
            bridged[i] = labels[i - 1];
        } else {
            bridged[i] = labels[i];
        }
    }

    printf("%s: %u Hz, %u ch, %d blocks\n", name, info.rate, info.channels, num_blocks);
    char digits_str[1024] = {0};
    int digits_len = 0;
    for (int i = 0; i < num_blocks; ) {
        if (bridged[i] == 0) {
            i++;
            continue;
        }
        int start = i;
        while (i < num_blocks && bridged[i] == bridged[start]) i++;
        int len = i - start;
        if (len >= 2) {
            printf("%c %d %d\n", bridged[start], start * 20, i * 20);
            for (int k = 0; k < len; k++) {
                if (digits_len < 1023) digits_str[digits_len++] = bridged[start];
            }
        }
    }
    printf("digits: %s\n\n", digits_str);

    free(samples);
    free(left_channel);
    free(labels);
    free(bridged);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    const char *dir_path = argv[1];
    DIR *dp = opendir(dir_path);
    if (!dp) return 0;

    char **files = NULL;
    int file_count = 0;
    struct dirent *entry;
    while ((entry = readdir(dp))) {
        if (strlen(entry->d_name) > 4 && strcmp(entry->d_name + strlen(entry->d_name) - 4, ".wav") == 0) {
            files = realloc(files, sizeof(char *) * (file_count + 1));
            files[file_count++] = strdup(entry->d_name);
        }
    }
    closedir(dp);

    qsort(files, file_count, sizeof(char *), compare_strings);

    for (int i = 0; i < file_count; i++) {
        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, files[i]);
        process_file(full_path);
        free(files[i]);
    }
    free(files);
    return 0;
}

