        return;
    }

    int N = info.rate / 50;
    int num_blocks = num_frames / N;
    char *labels = malloc(num_blocks);
    int16_t *left_channel = malloc(num_frames * sizeof(int16_t));
    for (uint32_t i = 0; i < num_frames; i++) {
        left_channel[i] = samples[i * info.channels];
    }

    for (int i = 0; i < num_blocks; i++) {
        double E = 0;
        for (int n = 0; n < N; n++) {
            double x = left_channel[i * N + n];
            E += x * x;
        }

        if (E < 1000000.0 * N) {
            labels[i] = 0;
        } else {
            double r_low[4], r_high[4];
            for (int f_idx = 0; f_idx < 4; f_idx++) {
                double freq = LOW_FREQS[f_idx];
                double c = 2.0 * cos(2.0 * M_PI * freq / info.rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = left_channel[i * N + n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_low[f_idx] = 2.0 * P / (N * E);
            }
            for (int f_idx = 0; f_idx < 4; f_idx++) {
                double freq = HIGH_FREQS[f_idx];
                double c = 2.0 * cos(2.0 * M_PI * freq / info.rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = left_channel[i * N + n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_high[f_idx] = 2.0 * P / (N * E);
            }

            int fl_idx = 0, fh_idx = 0;
            for (int j = 1; j < 4; j++) {
                if (r_low[j] > r_low[fl_idx]) fl_idx = j;
                if (r_high[j] > r_high[fh_idx]) fh_idx = j;
            }

            if (r_low[fl_idx] >= 0.1 && r_high[fh_idx] >= 0.1 && (r_low[fl_idx] + r_high[fh_idx] >= 0.6)) {
                labels[i] = DTMF_MAP[fl_idx][fh_idx];
            } else {
                labels[i] = 0;
            }
        }
    }

    char *bridged = malloc(num_blocks);
    for (int i = 0; i < num_blocks; i++) {
        if (labels[i] == 0 && i > 0 && i < num_blocks - 1 && labels[i - 1] == labels[i + 1] && labels[i - 1] != 0) {
            bridged[i] = labels[i - 1];
        } else {
            bridged[i] = labels[i];
        }
    }

    printf("%s: %u Hz, %u ch, %d blocks\n", name, info.rate, info.channels, num_blocks);
    char *digits_str = malloc(num_blocks + 1);
    int digits_len = 0;
    for (int i = 0; i < num_blocks; ) {
        if (bridged[i] == 0) {
            i++;
            continue;
        }
        int start = i;
        while (i < num_blocks && bridged[i] == bridged[start]) i++;
        int len = i - start;
        if (len >= 2) {
            printf("%c %d %d\n", bridged[start], start * 20, i * 20);
            digits_str[digits_len++] = bridged[start];
        }
    }
    digits_str[digits_len] = '\0';
    printf("digits: %s\n", digits_str);

    free(samples);
    free(left_channel);
    free(labels);
    free(bridged);
    free(digits_str);
}

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    const char *dir_path = argv[1];
    DIR *dp = opendir(dir_path);
    if (!dp) return 0;

    char **files = NULL;
    int file_count = 0;
    struct dirent *entry;
    while ((entry = readdir(dp))) {
        size_t len = strlen(entry->d_name);
        if (len > 4 && strcmp(entry->d_name + len - 4, ".wav") == 0) {
            files = realloc(files, sizeof(char *) * (file_count + 1));
            files[file_count++] = strdup(entry->d_name);
        }
    }
    closedir(dp);

    qsort(files, file_count, sizeof(char *), compare_strings);

    for (int i = 0; i < file_count; i++) {
        if (i > 0) printf("\n");
        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, files[i]);
        process_file(full_path);
        free(files[i]);
    }
    free(files);
    return 0;
}

import Foundation
import CommonCrypto
import Darwin

// Helper to read exact number of bytes from socket
func readExactly(fd: Int32, count: Int) -> [UInt8]? {
    var buffer = [UInt8](repeating: 0, count: count)
    var bytesRead = 0
    while bytesRead < count {
        let result = recv(fd, &buffer[bytesRead], count - bytesRead, 0)
        if result <= 0 { return nil }
        bytesRead += result
    }
    return buffer
}

// Helper to send bytes to socket
func sendExactly(fd: Int32, data: [UInt8]) {
    var bytesSent = 0
    while bytesSent < data.count {
        let result = send(fd, data[bytesSent...], data.count - bytesSent, 0)
        if result <= 0 { return }
        bytesSent += result
    }
}

// SHA1 helper
func sha1(data: [UInt8]) -> [UInt8] {
    var digest = [UInt8](repeating: 0, count: Int(CC_SHA1_DIGEST_LENGTH))
    CC_SHA1(data, UInt32(data.count), &digest)
    return digest
}

// Base64 helpers
func base64Encode(_ data: [UInt8]) -> String {
    return Data(data).base64EncodedString()
}

// WebSocket Frame logic
func sendFrame(fd: Int32, opcode: UInt8, payload: [UInt8]) {
    var header = [UInt8]()
    // FIN = 1, RSV = 0
    header.append(0x80 | (opcode & 0x0F))

    // Mask = 1
    let len = payload.count
    if len <= 125 {
        header.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        header.append(0x80 | 126)
        let len16 = UInt16(len).bigEndian
        withUnsafeBytes(of: len16) { header.append(contentsOf: $0) }
    } else {
        header.append(0x80 | 127)
        let len64 = UInt64(len).bigEndian
        withUnsafeBytes(of: len64) { header.append(contentsOf: $0) }
    }

    // Masking key
    var mask = [UInt8](repeating: 0, count: 4)
    arc4random_buf(&mask, 4)
    // Ensure mask is not all zeros
    while mask == [0,0,0,0] {
        arc4random_buf(&mask, 4)
    }
    header.append(contentsOf: mask)

    // Masked payload
    var maskedPayload = [UInt8]()
    for i in 0..<payload.count {
        maskedPayload.append(payload[i] ^ mask[i % 4])
    }

    sendExactly(fd: fd, data: header + maskedPayload)
}

func parseUrl(_ urlString: String) -> (host: String, port: Int, path: String)? {
    guard urlString.hasPrefix("ws://") else { return nil }
    let afterWs = String(urlString.dropFirst(5))
    let parts = afterWs.split(separator: "/", maxSplits: 1, omittingEmptySubsequences: false)
    guard parts.count == 2 else { return nil }

    let hostPort = String(parts[0])
    let path = String(parts[1])

    let hostPortParts = hostPort.split(separator: ":")
    let host = String(hostPortParts[0])
    let port = hostPortParts.count > 1 ? Int(hostPortParts[1]) ?? 80 : 80

    return (host, port, path)
}

func main() {
    let args = Array(CommandLine.arguments.dropFirst())
    for (index, urlString) in args.enumerated() {
        print("session \(index + 1)")

        guard let (host, port, path) = parseUrl(urlString) else { continue }

        var addr = sockaddr_in()
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_port = UInt16(port).bigEndian
        inet_pton(AF_INET, host, &addr.sin_addr)

        let fd = socket(AF_INET, SOCK_STREAM, 0)
        if fd < 0 { continue }

        let connectRes = withUnsafePointer(to: &addr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }

        if connectRes < 0 {
            close(fd)
            continue
        }

        // Handshake
        var randomBytes = [UInt8](repeating: 0, count: 16)
        arc4random_buf(&randomBytes, 16)
        let secWebSocketKey = base64Encode(randomBytes)

        var request = "GET \(path) HTTP/1.1\r\n"
        request += "Host: \(host):\(port)\r\n"
        request += "Upgrade: websocket\r\n"
        request += "Connection: Upgrade\r\n"
        request += "Sec-WebSocket-Version: 13\r\n"
        request += "Sec-WebSocket-Key: \(secWebSocketKey)\r\n"
        request += "\r\n"

        sendExactly(fd: fd, data: Array(request.utf8))

        var responseData = [UInt8]()
        while true {
            if let byte = readExactly(fd: fd, count: 1) {
                responseData.append(byte[0])
                if responseData.suffix(4) == [13, 10, 13, 10] { break }
            } else {
                break
            }
        }

        let responseString = String(decoding: responseData, as: UTF8.self)
        let responseLines = responseString.components(separatedBy: "\r\n")
        let statusLine = responseLines[0]
        let statusParts = statusLine.split(separator: " ", maxSplits: 2, omittingEmptySubsequences: false)

        if statusParts.count < 2 {
            close(fd)
            continue
        }

        let statusCode = String(statusParts[1])
        if statusCode != "101" {
            let reason = statusParts.count > 2 ? String(statusParts[2]) : ""
            print("handshake failed: \(statusCode) \(reason)".trimmingCharacters(in: .whitespaces))
            close(fd)
            continue
        }

        var acceptKey: String?
        for line in responseLines[1...] {
            let parts = line.split(separator: ":", maxSplits: 1, omittingEmptySubsequences: false)
            if parts.count == 2 && parts[0].trimmingCharacters(in: .whitespaces).caseInsensitiveCompare("Sec-WebSocket-Accept") == .orderedSame {
                acceptKey = parts[1].trimmingCharacters(in: .whitespaces)
            }
        }

        let magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
        let combined = secWebSocketKey + magic
        let hashed = sha1(data: Array(combined.utf8))
        let expectedAccept = base64Encode(hashed)

        if acceptKey != expectedAccept {
            print("handshake failed: bad Sec-WebSocket-Accept")
            close(fd)
            continue
        }

        var messageBuffer = [UInt8]()
        var currentOpcode: UInt8 = 0
        var awaitingSha1Payload = false
        var sessionClosed = false
        var sentCloseFrame = false

        while !sessionClosed {
            guard let header = readExactly(fd: fd, count: 2) else { break }
            let fin = (header[0] & 0x80) != 0
            let opcode = header[0] & 0x0F
            let masked = (header[1] & 0x80) != 0
            var payloadLen = Int(header[1] & 0x7F)

            if payloadLen == 126 {
                guard let lenBytes = readExactly(fd: fd, count: 2) else { break }
                payloadLen = Int(UInt16(lenBytes[0]) << 8 | UInt16(lenBytes[1]))
            } else if payloadLen == 127 {
                guard let lenBytes = readExactly(fd: fd, count: 8) else { break }
                var len64: UInt64 = 0
                for b in lenBytes { len64 = (len64 << 8) | UInt64(b) }
                payloadLen = Int(len64)
            }

            var maskKey = [UInt8]()
            if masked {
                guard let mk = readExactly(fd: fd, count: 4) else { break }
                maskKey = mk
            }

            var payload = [UInt8]()
            while payload.count < payloadLen {
                guard let chunk = readExactly(fd: fd, count: min(payloadLen - payload.count, 8192)) else { break }
                payload.append(contentsOf: chunk)
            }

            if masked {
                for i in 0..<payload.count {
                    payload[i] ^= maskKey[i % 4]
                }
            }

            if opcode == 9 { // Ping
                sendFrame(fd: fd, opcode: 10, payload: payload)
            } else if opcode == 10 { // Pong
                // Ignore
            } else if opcode == 8 { // Close
                var code = 1000
                if payload.count >= 2 {
                    code = Int(UInt16(payload[0]) << 8 | UInt16(payload[1]))
                }
                let reason = payload.count > 2 ? String(decoding: payload[2...], as: UTF8.self) : ""

                if !sentCloseFrame {
                    var closePayload = [UInt8]()
                    if payload.count >= 2 {
                        closePayload.append(payload[0])
                        closePayload.append(payload[1])
                    } else {
                        closePayload.append(0x03)
                        closePayload.append(0xE8)
                    }
                    sendFrame(fd: fd, opcode: 8, payload: closePayload)
                    sentCloseFrame = true
                }

                if reason.isEmpty {
                    print("closed \(code)")
                } else {
                    print("closed \(code) \(reason)")
                }
                sessionClosed = true
            } else {
                if opcode != 0 { currentOpcode = opcode }
                messageBuffer.append(contentsOf: payload)

                if fin {
                    let finalOpcode = currentOpcode
                    let finalPayload = messageBuffer
                    messageBuffer = []

                    if finalOpcode == 1 { // Text
                        let text = String(decoding: finalPayload, as: UTF8.self)
                        if text == "BYE" {
                            sendFrame(fd: fd, opcode: 8, payload: [0x03, 0xE8])
                            sentCloseFrame = true
                        } else if text == "SHA1" {
                            awaitingSha1Payload = true
                        } else if text.hasPrefix("ADD ") {
                            let parts = text.split(separator: " ", maxSplits: 2, omittingEmptySubsequences: false)
                            if parts.count == 3 {
                                let a = Int64(parts[1]) ?? 0
                                let b = Int64(parts[2]) ?? 0
                                let sum = a + b
                                let reply = String(sum)
                                print("\(text) -> \(reply)")
                                sendFrame(fd: fd, opcode: 1, payload: Array(reply.utf8))
                            }
                        } else if text.hasPrefix("REV ") {
                            let parts = text.split(separator: " ", maxSplits: 1, omittingEmptySubsequences: false)
                            if parts.count == 2 {
                                let content = String(parts[1])
                                let reversed = String(content.reversed())
                                print("\(text) -> \(reversed)")
                                sendFrame(fd: fd, opcode: 1, payload: Array(reversed.utf8))
                            }
                        }
                    } else if finalOpcode == 2 { // Binary
                        if awaitingSha1Payload {
                            let hashed = sha1(data: finalPayload)
                            let hexHashed = hashed.map { String(format: "%02x", $0) }.joined()
                            print("SHA1 \(finalPayload.count) -> \(hexHashed)")
                            sendFrame(fd: fd, opcode: 1, payload: Array(hexHashed.utf8))
                            awaitingSha1Payload = false
                        }
                    }
                    currentOpcode = 0
                }
            }
        }
        close(fd)
    }
}

