        .filter_map(|e| e.ok())
        .filter(|e| {
            e.file_name()
                .to_str()
                .map(|s| s.ends_with(".wav"))
                .unwrap_or(false)
        })
        .collect();

    files.sort_by(|a, b| a.file_name().cmp(&b.file_name()));

    for (i, entry) in files.into_iter().enumerate() {
        let path = entry.path();
        let filename = path.file_name().unwrap().to_str().unwrap().to_string();
        let mut file_data = Vec::new();
        if let Ok(mut f) = fs::File::open(&path) {
            let _ = f.read_to_end(&mut file_data);
        }

        if let Some(output) = process_wav(&file_data) {
            println!("{}: {}", filename, output);
        } else {
            println!("{}: unsupported", filename);
        }

        if i < files.len() - 1 {
