        }
    }
}

fn process_wav(data: &[u8]) -> Option<String> {
    if data.len() < 12 { return None; }
    if &data[0..4] != b"RIFF" { return None; }
    if &data[8..12] != b"WAVE" { return None; }

    let mut pos = 12;
    let mut fmt_chunk: Option<(usize, usize)> = None;
    let mut data_chunk: Option<(usize, usize)> = None;

    while pos + 8 <= data.len() {
        let id = &data[pos..pos + 4];
        let size = u32::from_le_bytes([data[pos + 4], data[pos + 5], data[pos + 6], data[pos + 7]]) as usize;
        pos += 8;

        if id == b"fmt " {
            fmt_chunk = Some((pos, size));
        } else if id == b"data" {
            data_chunk = Some((pos, size));
        }

        pos += size;
        if size % 2 != 0 && pos < data.len() {
            pos += 1;
        }
    }

    let (fmt_pos, fmt_size) = fmt_chunk?;
    let (data_pos, data_size) = data_chunk?;

    // fmt must come before data
    if fmt_pos >= data_pos { return None; }

    if fmt_size < 16 { return None; }
    let mut tag = u16::from_le_bytes([data[fmt_pos], data[fmt_pos + 1]]);
    let channels = u16::from_le_bytes([data[fmt_pos + 2], data[fmt_pos + 3]]);
    let rate = u32::from_le_bytes([data[fmt_pos + 4], data[fmt_pos + 5], data[fmt_pos + 6], data[fmt_pos + 7]]);
    let bits_per_sample = u16::from_le_bytes([data[fmt_pos + 14], data[fmt_pos + 15]]);

    if tag == 0xFFFE {
        if fmt_size < 26 { return None; }
        tag = u16::from_le_bytes([data[fmt_pos + 24], data[fmt_pos + 25]]);
    }

    if tag != 1 || bits_per_sample != 16 { return None; }
    if channels < 1 || channels > 2 { return None; }
    if rate != 8000 && rate != 16000 { return None; }

    let samples_per_frame = channels as usize;
    let bytes_per_sample = 2;
    let total_frames = data_size / (samples_per_frame * bytes_per_sample);
    let n_block = (rate / 50) as usize;
    let num_blocks = total_frames / n_block;

    let mut left_samples = Vec::with_capacity(total_frames);
    for f in 0..total_frames {
        let start = data_pos + f * samples_per_frame * bytes_per_sample;
        if start + 2 > data.len() { break; }
        let sample = i16::from_le_bytes([data[start], data[start + 1]]);
        left_samples.push(sample as f64);
    }

    let low_freqs = [697.0, 770.0, 852.0, 941.0];
    let high_freqs = [1209.0, 1336.0, 1477.0, 1633.0];
    let dtmf_map = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut block_labels = Vec::new();
    for b in 0..num_blocks {
        let block = &left_samples[b * n_block .. (b + 1) * n_block];
        let mut energy = 0.0;
        for &x in block {
            energy += x * x;
        }

        if energy < 1000000.0 * (n_block as f64) {
            block_labels.push(None);
            continue;
        }

        let mut max_rl = -1.0;
        let mut fl_idx = 0;
        for (i, &f) in low_freqs.iter().enumerate() {
            let c = 2.0 * (2.0 * std::f64::consts::PI * f / rate as f64).cos();
            let mut s1 = 0.0;
            let mut s2 = 0.0;
            for &x in block {
                let s = x + c * s1 - s2;
                s2 = s1;
                s1 = s;
            }
            let p = s1 * s1 + s2 * s2 - c * s1 * s2;
            let r = 2.0 * p / (n_block as f64 * energy);
            if r > max_rl {
                max_rl = r;
                fl_idx = i;
            }
        }

        let mut max_rh = -1.0;
        let mut fh_idx = 0;
        for (i, &f) in high_freqs.iter().enumerate() {
            let c = 2.0 * (2.0 * std::f64::consts::PI * f / rate as f64).cos();
            let mut s1 = 0.0;
            let mut s2 = 0.0;
            for &x in block {
                let s = x + c * s1 - s2;
                s2 = s1;
                s1 = s;
            }
            let p = s1 * s1 + s2 * s2 - c * s1 * s2;
            let r = 2.0 * p / (n_block as f64 * energy);
            if r > max_rh {
                max_rh = r;
                fh_idx = i;
            }
        }

        let rl = max_rl;
        let rh = max_rh;
        if rl >= 0.1 && rh >= 0.1 && (rl + rh) >= 0.6 {
            block_labels.push(Some(dtmf_map[fl_idx][fh_idx]));
        } else {
            block_labels.push(None);
        }
    }

    let mut bridged_labels = block_labels.clone();
    for i in 1..block_labels.len().saturating_sub(1) {
        if block_labels[i].is_none() {
            if let (Some(prev), Some(next)) = (block_labels[i-1], block_labels[i+1]) {
                if prev == next {
                    bridged_labels[i] = prev;
                }
            }
        }
    }

    let mut events = Vec::new();
    let mut i = 0;
    while i < bridged_labels.len() {
        if let Some(digit) = bridged_labels[i] {
            let mut j = i + 1;
            while j < bridged_labels.len() && bridged_labels[j] == Some(digit) {
                j += 1;
            }
            if (j - i) >= 2 {
                events.push((digit, i * 20, j * 20));
            }
            i = j;
        } else {
            i += 1;
        }
    }

    let mut output = format!("{} Hz, {} ch, {} blocks", rate, channels, num_blocks);
    let mut digits_seq = String::new();
    for (digit, start, end) in events {
        output.push_str(&format!("\n{} {} {}", digit, start, end));
        digits_seq.push(digit);
    }
    output.push_str(&format!("\ndigits: {}", digits_seq));
    Some(output)
}

