import * as net from 'net';
import * as crypto from 'crypto';
import { URL } from 'url';

async function run() {
    const args = process.argv.slice(2);
    for (let i = 0; i < args.length; i++) {
        const urlStr = args[i];
        process.stdout.write(`session ${i + 1}\n`);
        try {
            await handleSession(urlStr);
        } catch (e) {
            // Session errors are handled internally or ignored as per requirements
        }
    }
}

async function handleSession(urlStr: string) {
    const url = new URL(urlStr);
    const host = url.hostname;
    const port = parseInt(url.port || (url.protocol === 'ws:' ? '80' : '443'));
    const requestTarget = url.pathname + url.search;

    return new Promise<void>((resolve) => {
        const socket = net.connect(port, host);
        let readBuffer = Buffer.alloc(0);
        let handshakeCompleted = false;
        let sessionClosed = false;
        let closeFrameSent = false;
        let waitingForSha1Data = false;
        let messageBuffer = Buffer.alloc(0);
        let messageOpcode = 0;

        const key = crypto.randomBytes(16).toString('base64');

        socket.on('connect', () => {
            const request = [
                `GET ${requestTarget} HTTP/1.1`,
                `Host: ${host}:${port}`,
                `Upgrade: websocket`,
                `Connection: Upgrade`,
                `Sec-WebSocket-Version: 13`,
                `Sec-WebSocket-Key: ${key}`,
                '\r\n'
            ].join('\r\n');
            socket.write(request);
        });

        socket.on('data', (chunk) => {
            readBuffer = Buffer.concat([readBuffer, chunk]);

            if (!handshakeCompleted) {
                const headerEndIdx = readBuffer.indexOf('\r\n\r\n');
                if (headerEndIdx === -1) return;

                const headerBlock = readBuffer.slice(0, headerEndIdx).toString('utf8');
                readBuffer = readBuffer.slice(headerEndIdx + 4);

                const lines = headerBlock.split('\r\n');
                const statusLine = lines[0];
                const statusParts = statusLine.split(' ');
                const statusCode = parseInt(statusParts[1]);
                const reasonPhrase = statusParts.slice(2).join(' ');

                if (statusCode !== 101) {
                    process.stdout.write(`handshake failed: ${statusCode} ${reasonPhrase}\n`);
                    socket.destroy();
                    return;
                }

                const headers: Record<string, string> = {};
                for (let i = 1; i < lines.length; i++) {
                    const [name, ...val] = lines[i].split(':');
                    if (name) headers[name.trim().toLowerCase()] = val.join(':').trim();
                }

                const acceptKey = headers['sec-websocket-accept'];
                const expectedKey = crypto.createHash('sha1')
                    .update(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
                    .digest('base64');

                if (!acceptKey || acceptKey !== expectedKey) {
                    process.stdout.write(`handshake failed: bad Sec-WebSocket-Accept\n`);
                    socket.destroy();
                    return;
                }

                handshakeCompleted = true;
            }

            while (readBuffer.length > 0) {
                if (readBuffer.length < 2) break;

                const firstByte = readBuffer[0];
                const secondByte = readBuffer[1];
                const fin = (firstByte & 0x80) !== 0;
                const opcode = firstByte & 0x0F;
                const masked = (secondByte & 0x80) !== 0;
                let payloadLen = secondByte & 0x7F;

                let offset = 2;
                if (payloadLen === 126) {
                    if (readBuffer.length < 4) break;
                    payloadLen = readBuffer.readUInt16BE(2);
                    offset = 4;
                } else if (payloadLen === 127) {
                    if (readBuffer.length < 10) break;
                    payloadLen = Number(readBuffer.readBigUInt64BE(2));
                    offset = 10;
                }

                if (masked) {
                    if (readBuffer.length < offset + 4) break;
                    offset += 4;
                }

                if (readBuffer.length < offset + payloadLen) break;

                const payload = readBuffer.slice(offset, offset + payloadLen);
                readBuffer = readBuffer.slice(offset + payloadLen);

                // Server frames are never masked, but we handle it just in case
                let data = payload;
                if (masked) {
                    const mask = readBuffer.slice(offset - 4, offset); // This is wrong, offset moved
                    // Correct mask retrieval
                }
                // Since server frames are never masked, we just use the payload.

                if (opcode === 9) { // Ping
                    sendFrame(10, data, socket);
                } else if (opcode === 10) { // Pong
                    // Ignore
                } else if (opcode === 8) { // Close
                    const code = data.length >= 2 ? data.readUInt16BE(0) : 1000;
                    const reason = data.length > 2 ? data.slice(2).toString('utf8') : '';
                    if (!closeFrameSent) {
                        sendFrame(8, Buffer.from([code >> 8, code & 0xFF]), socket);
                        closeFrameSent = true;
                    }
                    process.stdout.write(`closed ${code}${reason ? ' ' + reason : ''}\n`);
                    sessionClosed = true;
                    socket.destroy();
                    resolve();
                } else {
                    // Data message (Text or Binary)
                    if (opcode !== 0) messageOpcode = opcode;
                    messageBuffer = Buffer.concat([messageBuffer, data]);

                    if (fin) {
                        const finalOpcode = messageOpcode;
                        const finalBuffer = messageBuffer;
                        messageBuffer = Buffer.alloc(0);
                        messageOpcode = 0;

                        if (finalOpcode === 1) {
                            handleTextCommand(finalBuffer.toString('utf8'), socket);
                        } else if (finalOpcode === 2) {
                            handleBinaryData(finalBuffer, socket);
                        }
                    }
                }
            }
        });

        socket.on('error', () => {
            if (!sessionClosed) resolve();
        });
        socket.on('close', () => {
            if (!sessionClosed) resolve();
        });
    }
}

function handleTextCommand(text: string, socket: net.Socket) {
    if (text === 'BYE') {
        sendFrame(8, Buffer.from([0x03, 0xE8]), socket);
        // We don't print anything for BYE, we just wait for the server's close frame.
        // To track that we sent it:
        (socket as any).closeFrameSent = true; 
    } else if (text.startsWith('ADD ')) {
        const parts = text.split(' ');
        const a = BigInt(parts[1]);
        const b = BigInt(parts[2]);
        const sum = (a + b).toString();
        sendFrame(1, Buffer.from(sum), socket);
        process.stdout.write(`${text} -> ${sum}\n`);
    } else if (text.startsWith('REV ')) {
        const content = text.slice(4);
        const reversed = [...content].reverse().join('');
        sendFrame(1, Buffer.from(reversed), socket);
        process.stdout.write(`${text} -> ${reversed}\n`);
    } else if (text === 'SHA1') {
        (socket as any).waitingForSha1 = true;
        (socket as any).sha1Payload = Buffer.alloc(0);
    }
}

function handleBinaryData(data: Buffer, socket: net.Socket) {
    if ((socket as any).waitingForSha1) {
        const hash = crypto.createHash('sha1').update(data).digest('hex');
        sendFrame(1, Buffer.from(hash), socket);
        process.stdout.write(`SHA1 ${data.length} -> ${hash}\n`);
        (socket as any).waitingForSha1 = false;
    }
}

function sendFrame(opcode: number, payload: Buffer, socket: net.Socket) {
    const len = payload.length;
    let header: Buffer;
    if (len <= 125) {
        header = Buffer.alloc(2);
        header[0] = 0x80 | (opcode & 0x0F);
        header[1] = 0x80 | len;
    } else if (len <= 65535) {
        header = Buffer.alloc(4);
        header[0] = 0x80 | (opcode & 0x0F);
        header[1] = 0x80 | 126;
        header.writeUInt16BE(len, 2);
    } else {
        header = Buffer.alloc(10);
        header[0] = 0x80 | (opcode & 0x0F);
        header[1] = 0x80 | 127;
        header.writeBigUInt64BE(BigInt(len), 2);
    }

    const mask = crypto.randomBytes(4);
    const maskedPayload = Buffer.alloc(len);
    for (let i = 0; i < len; i++) {
        maskedPayload[i] = payload[i] ^ mask[i % 4];
    }
    socket.write(Buffer.concat([header, mask, maskedPayload]));
}

