/* --- SHA-1 Implementation --- */
typedef struct {
    uint32_t state[5];
    uint64_t count;
    uint8_t buffer[64];
} SHA1_CTX;

#define SHA1_ROL(value, bits) (((value) << (bits)) | ((value) >> (32 - (bits))))

void sha1_transform(SHA1_CTX *ctx, const uint8_t *data) {
    uint32_t a = ctx->state[0], b = ctx->state[1], c = ctx->state[2], d = ctx->state[3], e = ctx->state[4];
    uint32_t w[80];
    for (int i = 0; i < 16; i++) {
        w[i] = (uint32_t)data[i * 4] << 24 | (uint32_t)data[i * 4 + 1] << 16 | (uint32_t)data[i * 4 + 2] << 8 | (uint32_t)data[i * 4 + 3];
    }
    for (int i = 16; i < 80; i++) w[i] = SHA1_ROL(w[i - 3] ^ w[i - 16] ^ w[i - 7] ^ w[i - 15], 1);
    for (int i = 0; i < 80; i++) {
        uint32_t f, k;
        if (i < 20) { f = (b & c) | (~b & d); k = 0x5A827999; }
        else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1; }
        else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
        else { f = b ^ c ^ d; k = 0xCA62C1D6; }
        uint32_t temp = SHA1_ROL(a, 5) + f + e + k + w[i];
        e = d; d = c; c = SHA1_ROL(b, 30); b = a; a = temp;
    }
    ctx->state[0] += a; ctx->state[1] += b; ctx->state[2] += c; ctx->state[3] += d; ctx->state[4] += e;
}

void sha1_init(SHA1_CTX *ctx) {
    ctx->state[0] = 0x67452301; ctx->state[1] = 0xEFCDAB89; ctx->state[2] = 0x98BADCFE; ctx->state[3] = 0x10325476; ctx->state[4] = 0xC3D2E1F0;
    ctx->count = 0;
}

void sha1_update(SHA1_CTX *ctx, const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        ctx->buffer[ctx->count % 64] = data[i];
        ctx->count++;
        if (ctx->count % 64 == 0) sha1_transform(ctx, ctx->buffer);
    }
}

void sha1_final(uint8_t digest[20], SHA1_CTX *ctx) {
    uint64_t total_len = ctx->count;
    uint8_t b[64];
    int i = ctx->count % 64;
    b[i] = 0x80;
    if (i >= 56) {
        memset(b, 0, 64);
        b[0] = 0x80;
        sha1_transform(ctx, b);
        i = 0;
    }
    memset(b + i, 0, 56 - i);
    uint64_t bits = total_len * 8;
    for (int j = 0; j < 8; j++) b[56 + j] = (bits >> (56 - 8 * j)) & 0xFF;
    sha1_transform(ctx, b);
    for (int j = 0; j < 5; j++) {
        digest[j * 4] = (ctx->state[j] >> 24) & 0xFF;
        digest[j * 4 + 1] = (ctx->state[j] >> 16) & 0xFF;
        digest[j * 4 + 2] = (ctx->state[j] >> 8) & 0xFF;
        digest[j * 4 + 3] = ctx->state[j] & 0xFF;
    }
}

/* --- Base64 Implementation --- */
static const char b64_table[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
void base64_encode(const uint8_t *src, size_t len, char *dst) {
    size_t i = 0, j = 0;
    while (i < len) {
        uint32_t val = ((uint32_t)src[i++] << 16);
        if (i < len + 1 && (i-1) < len) { /* logic fix */ }
        // Using a simpler triple-based approach
    }
}

void base64_encode_fixed(const uint8_t *src, size_t len, char *dst) {
    int i = 0, j = 0;
    for (; i < len; i += 3) {
        uint32_t val = ((uint32_t)src[i] << 16);
        if (i + 1 < len) val |= ((uint32_t)src[i + 1] << 8);
        if (i + 2 < len) val |= (uint32_t)src[i + 2];
        dst[j++] = b64_table[(val >> 18) & 0x3F];
        dst[j++] = b64_table[(val >> 12) & 0x3F];
        dst[j++] = (i + 1 < len) ? b64_table[(val >> 6) & 0x3F] : '=';
        dst[j++] = (i + 2 < len) ? b64_table[val & 0x3F] : '=';
    }
    dst[j] = '\0';
}

/* --- WebSocket Helpers --- */
void read_n(int fd, void *buf, size_t n) {
    size_t total = 0;
    while (total < n) {
        ssize_t r = recv(fd, (char*)buf + total, n - total, 0);
        if (r <= 0) exit(0);
        total += r;
    }
}

void send_frame(int fd, uint8_t opcode, const uint8_t *payload, size_t len) {
    uint8_t header[14];
    int h_len = 0;
    header[h_len++] = 0x80 | (opcode & 0x0F);
    if (len <= 125) {
        header[h_len++] = 0x80 | (uint8_t)len;
    } else if (len <= 65535) {
        header[h_len++] = 0x80 | 126;
        header[h_len++] = (len >> 8) & 0xFF;
        header[h_len++] = len & 0xFF;
    } else {
        header[h_len++] = 0x80 | 127;
        for (int i = 7; i >= 0; i--) header[h_len++] = (len >> (8 * i)) & 0xFF;
    }
    uint8_t mask[4];
    arc4random_buf(mask, 4);
    while (memcmp(mask, "\0\0\0\0", 4) == 0) arc4random_buf(mask, 4);
    for (int i = 0; i < 4; i++) header[h_len++] = mask[i];
    send(fd, header, h_len, 0);
    uint8_t *masked_payload = malloc(len);
    for (size_t i = 0; i < len; i++) masked_payload[i] = payload[i] ^ mask[i % 4];
    send(fd, masked_payload, len, 0);
    free(masked_payload);
}

void reverse_utf8(const char *s, char *dst) {
    size_t len = strlen(s);
    if (len == 0) { dst[0] = '\0'; return; }
    const char *ptr = s;
    const char *starts[200000];
    int count = 0;
    while (*ptr) {
        starts[count++] = ptr;
        unsigned char c = (unsigned char)*ptr;
        if (c < 0x80) ptr += 1;
        else if ((c & 0xE0) == 0xC0) ptr += 2;
        else if ((c & 0xF0) == 0xE0) ptr += 3;
        else if ((c & 0xF8) == 0xF0) ptr += 4;
        else ptr++;
    }
    char *out = dst;
    for (int i = count - 1; i >= 0; i--) {
        const char *c = starts[i];
        unsigned char b = (unsigned char)*c;
        int clen = (b < 0x80) ? 1 : ((b & 0xE0) == 0xC0) ? 2 : ((b & 0xF0) == 0xE0) ? 3 : 4;
        memcpy(out, c, clen);
        out += clen;
    }
    *out = '\0';
}

void handle_session(int session_id, const char *url) {
    printf("session %d\n", session_id);
    char host[256], path[256];
    int port;
    sscanf(url, "ws://%[^:]:%d%s", host, &port, path);
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = { .sin_family = AF_INET, .sin_port = htons(port) };
    inet_pton(AF_INET, host, &addr.sin_addr);
    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) { close(fd); return; }

    uint8_t key_bin[16];
    arc4random_buf(key_bin, 16);
    char key_b64[32];
    base64_encode_fixed(key_bin, 16, key_b64);

    char req[1024];
    int req_len = sprintf(req, "GET %s HTTP/1.1\r\nHost: %s:%d\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: %s\r\n\r\n", path, host, port, key_b64);
    send(fd, req, req_len, 0);

    char resp[4096];
    int resp_ptr = 0;
    while (1) {
        char c;
        if (recv(fd, &c, 1, 0) <= 0) break;
        resp[resp_ptr++] = c;
        if (resp_ptr >= 4 && resp[resp_ptr - 4] == '\r' && resp[resp_ptr - 3] == '\n' && resp[resp_ptr - 2] == '\r' && resp[resp_ptr - 1] == '\n') break;
    }
    resp[resp_ptr] = '\0';

    int status_code;
    char reason[256];
    if (sscanf(resp, "HTTP/1.1 %d %s", &status_code, reason) != 2) {
        // Handle cases where reason phrase might be empty
        sscanf(resp, "HTTP/1.1 %d", &status_code);
        reason[0] = '\0';
    }
    if (status_code != 101) {
        printf("handshake failed: %d %s\n", status_code, reason);
        close(fd); return;
    }

    char magic[] = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
    char combined[128];
    sprintf(combined, "%s%s", key_b64, magic);
    SHA1_CTX ctx;
    sha1_init(&ctx);
    sha1_update(&ctx, (uint8_t*)combined, strlen(combined));
    uint8_t sha1_res[20];
    sha1_final(sha1_res, &ctx);
    char accept_b64[32];
    base64_encode_fixed(sha1_res, 20, accept_b64);

    char *accept_ptr = strstr(resp, "Sec-WebSocket-Accept: ");
    if (!accept_ptr || strncmp(accept_ptr + 22, accept_b64, strlen(accept_b64)) != 0) {
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        close(fd); return;
    }

    bool awaiting_sha1 = false;
    bool sent_close = false;
    uint8_t *msg_buf = NULL;
    size_t msg_len = 0;

    while (1) {
        uint8_t h[2];
        read_n(fd, h, 2);
        uint8_t fin = h[0] & 0x80;
        uint8_t opcode = h[0] & 0x0F;
        uint64_t len = h[1] & 0x7F;
        if (len == 126) { uint8_t l[2]; read_n(fd, l, 2); len = (l[0] << 8) | l[1]; }
        else if (len == 127) { uint8_t l[8]; read_n(fd, l, 8); len = 0; for(int i=0; i<8; i++) len = (len << 8) | l[i]; }

        uint8_t *payload = malloc(len);
        read_n(fd, payload, len);

        if (opcode == 9) { // Ping
            send_frame(fd, 10, payload, len);
        } else if (opcode == 8) { // Close
            uint16_t code = (len >= 2) ? (payload[0] << 8) | payload[1] : 0;
            if (!sent_close) {
                uint8_t close_payload[2] = { (code >> 8) & 0xFF, code & 0xFF };
                send_frame(fd, 8, close_payload, 2);
                sent_close = true;
            }
            printf("closed %d", code);
            if (len > 2) printf(" %s", payload + 2);
            printf("\n");
            free(payload);
            free(msg_buf);
            close(fd);
            return;
        } else if (opcode == 0 || opcode == 1 || opcode == 2) {
            if (opcode != 0) {
                free(msg_buf);
                msg_buf = malloc(len);
                memcpy(msg_buf, payload, len);
                msg_len = len;
            } else {
                msg_buf = realloc(msg_buf, msg_len + len);
                memcpy(msg_buf + msg_len, payload, len);
                msg_len += len;
            }
            if (fin) {
                if (awaiting_sha1) {
                    SHA1_CTX sctx; sha1_init(&sctx);
                    sha1_update(&sctx, msg_buf, msg_len);
                    uint8_t sres[20]; sha1_final(sres, &sctx);
                    char hex[41];
                    for (int i = 0; i < 20; i++) sprintf(hex + i * 2, "%02x", sres[i]);
                    printf("SHA1 %zu -> %s\n", msg_len, hex);
                    awaiting_sha1 = false;
                } else {
                    char *text = malloc(msg_len + 1);
                    memcpy(text, msg_buf, msg_len); text[msg_len] = '\0';
                    if (strncmp(text, "ADD", 3) == 0) {
                        long long a, b;
                        if (sscanf(text + 4, "%lld %lld", &a, &b) == 2) {
                            char reply[64]; sprintf(reply, "%lld", a + b);
                            send_frame(fd, 1, (uint8_t*)reply, strlen(reply));
                            printf("%s -> %s\n", text, reply);
                        }
                    } else if (strncmp(text, "REV", 3) == 0) {
                        char *rev_text = text + 4;
                        char *reversed = malloc(msg_len + 1);
                        reverse_utf8(rev_text, reversed);
                        send_frame(fd, 1, (uint8_t*)reversed, strlen(reversed));
                        printf("%s -> %s\n", text, reversed);
                        free(reversed);
                    } else if (strncmp(text, "SHA1", 4) == 0) {
                        awaiting_sha1 = true;
                    } else if (strncmp(text, "BYE", 3) == 0) {
                        uint8_t close_payload[2] = { 0x03, 0xE8 };
                        send_frame(fd, 8, close_payload, 2);
                        sent_close = true;
                    }
                    free(text);
                }
                free(msg_buf); msg_buf = NULL; msg_len = 0;
            }
        }
        free(payload);
    }
}

int main(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) handle_session(i, argv[i]);
    return 0;
}
